  ui_story_1011_10110201_15X5_dialog_content = "那裡才是真正的「巨像整備基地」？",
  ui_story_1011_10110201_15X6_dialog_content = "既然自動駕駛設定如此，應該十之八九。",
  ui_story_1011_10110201_15X7_dialog_content = "關於這座白塔，你們還知道些什麼？",
  ui_story_1011_10110201_15X8_dialog_content = "嗯......不太清楚，啟光手上關於空之山谷的記載資料相當有限。",
  ui_story_1011_10110201_15X9_dialog_content = "據我所知，那種白塔不過是普通白色石頭堆疊而成的建築。",
  ui_story_1011_10110201_15X10_dialog_content = "我的了解與薇絲差不多。",
  ui_story_1011_10110201_15X11_dialog_content = "臨空者號上，關於空之山谷的資料只停留在基本介紹層面......",
  ui_story_1011_10110201_15X12_dialog_content = "你再努力回想看看？",
  ui_story_1011_10110201_15X13_dialog_content = "空裔知道的總不該比啟光少吧？",
  ui_story_1011_10110201_15X14_dialog_content = "我盡力......",
  ui_story_1011_10110201_16_dialog_content = "那座白塔，我好像有點印象！",
  ui_story_1011_10110201_17_dialog_content = "臨空者號儲存的資料裡似乎有記載……",
  ui_story_1011_10110201_18_dialog_content = "哦，我想起來了！",
  ui_story_1011_10110201_19_dialog_content = "一部分空裔曾經居住在那裡，不過後來搬走，才來到目前的聚居地。",
  ui_story_1011_10110201_20_dialog_content = "那裡最明顯的建築就是那座空蕩蕩的、廢棄已久的白塔。",
  ui_story_1011_10110201_21_dialog_content = "除了白塔以外，沒有其他東西。",
  ui_story_1011_10110201_22_dialog_content = "沒有其他東西？應該不會吧......",
  ui_story_1011_10110201_22X1_dialog_content = "光看「巨像整備基地」這個稱呼，感覺就是個超大型遺跡才對啊。",
  ui_story_1011_10110201_22X2_dialog_content = "難道說......是往昔的空裔刻意將其隱藏起來？",
  ui_story_1011_10110201_22X3_dialog_content = "呃——！",
  ui_story_1011_10110201_23_dialog_content = "怎麼回事？！",
  ui_story_1011_10110201_24_dialog_content = "發生了什麼事？",
  ui_story_1011_10110201_25_dialog_content = "<color=#e8d9bb>「警告：偵測到暗鬼入侵。」</color>",
  ui_story_1011_10110201_26_dialog_content = "暗鬼？ ！",
  ui_story_1011_10110201_27_dialog_content = "不可能，普通的暗鬼應該追不上臨空者號才對。",
  ui_story_1011_10110201_28_dialog_content = "這麼多暗鬼集體攻擊，一定是埋伏！",
  ui_story_1011_10110201_29_dialog_content = "吼——",
  ui_story_1011_10110201_30_dialog_content = "竟然跑到艦橋上來！",
  ui_story_1011_10110201_31_dialog_content = "攔住它們！",
  ui_story_1011_10110201_32_dialog_content = "不能讓暗鬼靠近！",
  ui_story_1011_10110201_33_dialog_content = "當心，會使用戰術埋伏我們的暗鬼可不多見。",
  ui_story_1011_10110201_34_dialog_content = "說不定有指揮者！",
  ui_story_1011_10110201_35_dialog_content = "我對付左邊，薇絲，剩下的交給你。",
  ui_story_1011_10110201_36_dialog_content = "PlayerName，支援！",
  ui_story_1011_10110201_37_dialog_content = "沒問題！",
  ui_story_1011_10110202_1_dialog_content = "吼——",
  ui_story_1011_10110202_2_dialog_content = "休想過去！",
  ui_story_1011_10110202_3_dialog_content = "吼！",
  ui_story_1011_10110202_4_dialog_content = "究竟有多少暗鬼埋伏……",
  ui_story_1011_10110202_5_dialog_content = "怎麼沒完沒了啊！",
  ui_story_1011_10110202_6_dialog_content = "不能再退了！",
  ui_story_1011_10110202_7_dialog_content = "後面就是控制台！",
  ui_story_1011_10110202_8_dialog_content = "吼！ ！ ！",
  ui_story_1011_10110202_9_dialog_content = "薇絲，小心！",
  ui_story_1011_10110202_10_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_1011_10110202_11_dialog_content = "糟了，暗鬼的攻擊打到控制台了！",
  ui_story_1011_10110202_12_dialog_content = "欸？！",
  ui_story_1011_10110202_13_dialog_content = "墜機準備！ ！ ！",
  ui_story_1011_10110202_14_dialog_content = "噫！救命！",
  ui_story_1011_10110202_15_dialog_content = "抓緊固定的東西！",
  ui_story_1011_10110202_16_dialog_content = "PlayerName，抓住我的手！",
  ui_story_1011_10110202_17_dialog_content = "（日蝕語）巨像，墜落了……",
  ui_story_1011_10110202_18_dialog_content = "（日蝕語）一群飯桶！ ！ ！",
  ui_story_1011_10110202_19_dialog_content = "（日蝕語）對，對不起！",
  ui_story_1011_10110202_20_dialog_content = "（日蝕語）我的命令是，搶奪巨像和空裔。",
  ui_story_1011_10110202_21_dialog_content = "（日蝕語）沒要你們殺人搞破壞！",
  ui_story_1011_10110202_22_dialog_content = "（日蝕語）我們會想辦法補救！",
  ui_story_1011_10110202_23_dialog_content = "（日蝕語）追上他們，找到那些傢伙，別讓他們跑了。",
  ui_story_1011_10110202_24_dialog_content = "（日蝕語）這是你最後的機會。",
  ui_story_1011_10110202_25_dialog_content = "（日蝕語）是！",
  ui_story_1011_10110202_26_dialog_content = "（日蝕語）憑你這智商，確實不適合指揮。",
  ui_story_1011_10110202_27_dialog_content = "（日蝕語）吞羅，不要多嘴。",
  ui_story_1011_10110202_28_dialog_content = "（日蝕語）我說過，這是我的實驗，你別插手。",
  ui_story_1011_10110202_29_dialog_content = "（日蝕語）現在，你和你手底下的蠢貨成了我實驗中的干擾因素。",
  ui_story_1011_10110202_30_dialog_content = "（日蝕語）你和你的手下，還是在外圍等著吧。",
  ui_story_1011_10110202_31_dialog_content = "（日蝕語）正好前面有一群啟光人擋路，不如你去拖住他們。",
  ui_story_1011_10110202_32_dialog_content = "（日蝕語）別給我惹麻煩。",
  ui_story_1011_10110202_33_dialog_content = "（日蝕語）吞羅……",
  ui_story_1011_10110202_34_dialog_content = "（日蝕語）你會為你的傲慢付出代價。",
  ui_story_1011_10110202_40X1_dialog_content = "都聽好了，既然萊因哈特要我們第二軍團防禦——",
  ui_story_1011_10110202_40X2_dialog_content = "那我們就用實際行動讓她見識到，怎樣叫做固若金湯！",
  ui_story_1011_10110202_40X3_dialog_content = "你，帶隊檢查所有防禦工事，修補破損，針對關鍵節點單獨加強。",
  ui_story_1011_10110202_40X4_dialog_content = "就算有滿坑滿谷的暗鬼打過來，陣地也得扛住！",
  ui_story_1011_10110202_40X5_dialog_content = "是！",
  ui_story_1011_10110202_40X6_dialog_content = "還有你，帶隊去跟目前執勤的人換班。",
  ui_story_1011_10110202_40X7_dialog_content = "確保所有崗哨每六個小時就換班，讓他們好好休息。",
  ui_story_1011_10110202_40X8_dialog_content = "然後給我瞪大眼睛，盯緊那些暗鬼的動向！",
  ui_story_1011_10110202_40X9_dialog_content = "是！",
  ui_story_1011_10110202_40X10_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_1011_10110202_40X11_dialog_content = "怎麼回事？！",
  ui_story_1011_10110202_40X12_dialog_content = "那是......那小子的臨空者號？",
  ui_story_1011_10110202_40X13_dialog_content = "怎麼飛得那麼低？",
  ui_story_1011_10110202_40X14_dialog_content = "巨像上面那片黑點......是暗鬼？！",
  ui_story_1011_10110202_40X15_dialog_content = "搞什麼啊，那小子遭到襲擊？！",
  ui_story_1011_10110202_40X16_dialog_content = "報告——！",
  ui_story_1011_10110202_40X17_dialog_content = "講！",
  ui_story_1011_10110202_40X18_dialog_content = "我們的偵查兵發現暗鬼的異常動向，牠們正在往空之山谷的方向聚集！",
  ui_story_1011_10110202_40X19_dialog_content = "除了普通暗鬼外，更發現數隻高級暗鬼的蹤跡！",
  ui_story_1011_10110202_40X20_dialog_content = "其中包含吞羅和另一隻不知名的高級暗鬼！！",
  ui_story_1011_10110202_40X21_dialog_content = "吞羅......",
  ui_story_1011_10110202_40X22_dialog_content = "這種時候，她去那邊湊什麼熱鬧？",
  ui_story_1011_10110202_40X23_dialog_content = "不對。",
  ui_story_1011_10110202_40X24_dialog_content = "空裔小子、暗鬼以及吞羅......",
  ui_story_1011_10110202_40X25_dialog_content = "三方竟然在同一時刻前進空谷，接下來的情勢絕對不單純。",
  ui_story_1011_10110202_40X26_dialog_content = "傳令下去，第二軍團全面進入戒備狀態。",
  ui_story_1011_10110202_40X27_dialog_content = "拉一支偵查兵隊伍出來，主要監視空谷方向。",
  ui_story_1011_10110202_40X28_dialog_content = "是！",
  ui_story_1011_10110202_40X29_dialog_content = "還有——",
  ui_story_1011_10110202_40X30_dialog_content = "<color=#e8d9bb>嗒嗒嗒——！！！</color>",
  ui_story_1011_10110202_40X31_dialog_content = "那個方向......是空之山谷？",
  ui_story_1011_10110202_40X32_dialog_content = "我們的人跟暗鬼發生交戰？",
  ui_story_1011_10110202_40X33_dialog_content = "是......是的！",
  ui_story_1011_10110202_40X34_dialog_content = "剛剛傳回的消息，我方遭遇由吞羅帶領的一隊暗鬼！",
  ui_story_1011_10110202_40X35_dialog_content = "現下正在與暗鬼交戰，而吞羅似乎拋下隊友，獨自前往空之山谷！",
  ui_story_1011_10110202_40X36_dialog_content = "不管他們在策畫什麼，肯定不是好事。",
  ui_story_1011_10110202_40X37_dialog_content = "我就說，再這麼下去，遲早會出事。",
  ui_story_1011_10110202_40X38_dialog_content = "不能任他們為所欲為。",
  ui_story_1011_10110202_40X39_dialog_content = "通知各個隊伍，防守陣地，一步也不准退！",
  ui_story_1011_10110202_40X40_dialog_content = "我要親自去把吞羅那個啟光的罪人捉回來。",
  ui_story_1011_10110202_40X41_dialog_content = "可是，軍團長，上頭的命令......",
  ui_story_1011_10110202_40X42_dialog_content = "聽好了，這裡是戰場，戰機稍縱即逝。",
  ui_story_1011_10110202_40X43_dialog_content = "吞羅一定在謀畫著什麼，要趁現在阻止她。",
  ui_story_1011_10110202_40X44_dialog_content = "要是等到她的計畫成功，那一切都晚了。",
  ui_story_1011_10110202_40X45_dialog_content = "如果因為我的行為造成了什麼損失，讓萊因哈特和上頭怪罪下來，那你告訴他們——",
  ui_story_1011_10110202_40X46_dialog_content = "一切責任全都在我第二軍團長巴頓身上！",
  ui_story_1011_10110202_40X47_dialog_content = "瞭解了嗎？",
  ui_story_1011_10110202_40X48_dialog_content = "是，是！",
  ui_story_1011_10110202_40X49_dialog_content = "PlayerName那小子......不知道怎麼樣了。",
  ui_story_1011_10110202_40X50_dialog_content = "他命大得很，一定不會有事。",
  ui_story_1011_10110202_40X51_dialog_content = "就順便幫他一把好了。",
  ui_story_1011_10110401_1_dialog_content = "<anim type=Shake><size=50>啊——！ ！ ！</size></anim>",
  ui_story_1011_10110401_2_dialog_content = "要——墜——機——了——！ ！ ！",
  ui_story_1011_10110401_3_dialog_content = "PlayerName，控制住方向！",
  ui_story_1011_10110401_4_dialog_content = "塔底部有個空間，讓臨空者號滑進去！",
  ui_story_1011_10110401_7X1_dialog_content = "我做不到——！",
  ui_story_1011_10110401_7X2_dialog_content = "控制器被破壞，我已經控制不了臨空者號！",
  ui_story_1011_10110401_7X3_dialog_content = "那就找東西抓住，努力穩住自己！",
  ui_story_1011_10110401_7X4_dialog_content = "然後……",
  ui_story_1011_10110401_7X5_dialog_content = "祈禱我們不要正面撞上那座塔吧！！！",
  ui_story_1011_10110401_7X6_dialog_content = "噫！！！",
  ui_story_1011_10110401_8_dialog_content = "<color=#e8d9bb>轟——！！！</color>",
  ui_story_1011_10110401_9_dialog_content = "<color=#e8d9bb>嘎吱——！ ！ ！</color>",
  ui_story_1011_10110401_10_dialog_content = "噗咳咳！好多土......",
  ui_story_1011_10110401_11_dialog_content = "我們……還活著嗎？",
  ui_story_1011_10110401_12_dialog_content = "呃……毫無疑問，是的。",
  ui_story_1011_10110401_13_dialog_content = "我們成功降落了。",
  ui_story_1011_10110401_14_dialog_content = "大家都沒事吧？有沒有受傷？",
  ui_story_1011_10110401_15_dialog_content = "我沒事，除了頭有點暈。",
  ui_story_1011_10110401_16_dialog_content = "我……我也沒問題。",
  ui_story_1011_10110401_17_dialog_content = "咳咳，這裡是塔底？",
  ui_story_1011_10110401_18_dialog_content = "沒錯，我們滑進了白塔正下方的空間。",
  ui_story_1011_10110401_19_dialog_content = "<color=#e8d9bb>「已到達目的地——巨像整備基地停機坪。」</color>",
  ui_story_1011_10110401_20_dialog_content = "<color=#e8d9bb>「開始連接基地控制系統。」</color>",
  ui_story_1011_10110401_21_option_content = "停機坪？",
  ui_story_1011_10110401_22_dialog_content = "這個空間……竟然是停機坪嗎？",
  ui_story_1011_10110401_23_dialog_content = "難怪這麼寬闊，再停放幾座巨像也沒問題的樣子。",
  ui_story_1011_10110401_24_dialog_content = "只要進入停機坪，應該就不算墜機......",
  ui_story_1011_10110401_25_dialog_content = "嘎嗷......",
  ui_story_1011_10110401_26_dialog_content = "……",
  ui_story_1011_10110401_27_dialog_content = "……",
  ui_story_1011_10110401_28_dialog_content = "是暗鬼！",
  ui_story_1011_10110401_29_dialog_content = "嗷嗷嗷！ ！ ！",
  ui_story_1011_10110401_30_dialog_content = "快抓住牠！",
  ui_story_1011_10110401_31_dialog_content = "肯定還有不少暗鬼留在臨空者號上。",
  ui_story_1011_10110401_32_dialog_content = "不能讓牠們繼續搞破壞了！",
  ui_story_1011_10110402_1_dialog_content = "呼……這應該是最後一個了吧？",
  ui_story_1011_10110402_2_dialog_content = "視野裡已經沒有其他暗鬼。",
  ui_story_1011_10110402_3_dialog_content = "我感應不到其他敵人，應該可以暫時喘口氣。",
  ui_story_1011_10110402_4_dialog_content = "我先去看看臨空者號的情況。",
  ui_story_1011_10110402_5_dialog_content = "<color=#e8d9bb>「正在嘗試連接至巨像整備基地控制系統。」</color>",
  ui_story_1011_10110402_6_dialog_content = "<color=#e8d9bb>「錯誤：停機坪與中央控制系統連接阻斷。」</color>",
  ui_story_1011_10110402_7_dialog_content = "<color=#e8d9bb>「請前往中央控制系統手動修復連接。」</color>",
  ui_story_1011_10110402_8_dialog_content = "中央控制系統……？",
  ui_story_1011_10110402_9_dialog_content = "白塔裡有這種設備嗎？",
  ui_story_1011_10110402_10_dialog_content = "關於這座塔的資料，不曾記載過這種東西吧？",
  ui_story_1011_10110402_11_dialog_content = "應該是沒有……",
  ui_story_1011_10110402_12_dialog_content = "我倒是不介意翻出影像資料再看一遍，不過得耗費很多時間。",
  ui_story_1011_10110402_13_dialog_content = "只看資料是不夠的，有必要實地勘察。",
  ui_story_1011_10110402_14_dialog_content = "說的也是，那我們下去看看吧。",
  ui_story_1011_10110402_15_dialog_content = "事不宜遲，出發吧！",
  ui_story_1011_10110402_16_dialog_content = "這裡好空曠啊……",
  ui_story_1011_10110402_17_dialog_content = "每說一句話都能聽見回音。",
  ui_story_1011_10110402_18_dialog_content = "根據資料記載，這裡曾經是空裔的聚居地。",
  ui_story_1011_10110402_19_dialog_content = "但如今，這裡連一間房屋都沒有，看不出一絲有人生活過的痕跡。",
  ui_story_1011_10110402_20_dialog_content = "畢竟已經搬走很多年囉……",
  ui_story_1011_10110402_21_dialog_content = "就算有過痕跡，也會被時光逐漸消磨，失去蹤跡。",
  ui_story_1011_10110402_22_dialog_content = "但還是沒想到，空裔們過去生活的地方，竟然是一座停機坪。",
  ui_story_1011_10110402_23_dialog_content = "難道他們把巨像停在這裡，和巨像一起生活嗎？",
  ui_story_1011_10110402_24_dialog_content = "聽起來就像露營一樣！",
  ui_story_1011_10110402_25_dialog_content = "說不定這裡之所以沒有房屋，原因就是過去的空裔將巨像用做住所。",
  ui_story_1011_10110402_26_dialog_content = "當他們離去時，也將巨像一併開走。",
  ui_story_1011_10110402_27_dialog_content = "如果他們將巨像停在這裡，那他們應該也知道這裡是停機坪吧？",
  ui_story_1011_10110402_28_dialog_content = "知道是停機坪，就會知道這附近有著<color=#FFB400>「巨像整備基地」</color>。",
  ui_story_1011_10110402_29_dialog_content = "但為什麼會毫無記載呢？",
  ui_story_1011_10110402_30_dialog_content = "這一點確實很奇怪，之後探索時稍微留意一下吧。",
  ui_story_1011_10110402_31_dialog_content = "嗯。",
  ui_story_1011_10110402_32_dialog_content = "沒有記載也沒留下痕跡的基地……簡直就像憑空冒出來的一樣。",
  ui_story_1011_10110402_33_dialog_content = "附近也沒有看起來能修理巨像的設備或者房間。",
  ui_story_1011_10110402_34_dialog_content = "除了厚厚的灰塵以外，這裡什麼也沒有。",
  ui_story_1011_10110402_35_dialog_content = "中央控制系統看起來也不在這裡。",
  ui_story_1011_10110402_36_dialog_content = "難道在上面？",
  ui_story_1011_10110402_37_dialog_content = "PlayerName，這座塔的上面有什麼？",
  ui_story_1011_10110402_38_dialog_content = "我想想……",
  ui_story_1011_10110402_39_dialog_content = "根據臨空者號的資料記載，空裔們曾在這座白塔居住過一段時間。",
  ui_story_1011_10110402_40_dialog_content = "不過後來，他們就搬到了現在的聚居區。",
  ui_story_1011_10110402_41_dialog_content = "過去空裔曾經仔細探查過此處，包括塔的上層。",
  ui_story_1011_10110402_42_dialog_content = "但是除去那些和外部一樣佈滿花紋的白色石頭以外，什麼都沒有。",
  ui_story_1011_10110402_43_dialog_content = "上面什麼都沒有啊……",
  ui_story_1011_10110402_44_dialog_content = "會不會是坐標有誤？",
  ui_story_1011_10110402_45_dialog_content = "應該不會，如果是地質變化導致建築發生位移，照理說也不會距離原本坐標太遠。",
  ui_story_1011_10110402_46_dialog_content = "既然塔上面是空的......",
  ui_story_1011_10110402_47_dialog_content = "那麼，下面呢？",
  ui_story_1011_10110402_48_dialog_content = "下面？",
  ui_story_1011_10110402_49_dialog_content = "你的意思是……像迦南城那樣，存在著隱藏的地下空間？",
  ui_story_1011_10110402_50_dialog_content = "很有可能！",
  ui_story_1011_10110402_51_dialog_content = "這裡到處都是白塔坍塌落下的碎石，我們也沒有地圖，要去哪裡找入口？",
  ui_story_1011_10110402_52_dialog_content = "難不成要把這片地的地面都挖上一輪？",
  ui_story_1011_10110402_53_dialog_content = "那得挖好幾年才能發現通道吧。",
  ui_story_1011_10110402_54_dialog_content = "通道……地下城……尋找的方法……",
  ui_story_1011_10110402_55_dialog_content = "對了！",
  ui_story_1011_10110402_56_dialog_content = "我記得大元帥給我們的物資裡有金屬探測器。",
  ui_story_1011_10110402_57_dialog_content = "如果此處存在地下基地，那麼就有極高機率使用了金屬建材。",
  ui_story_1011_10110402_58_dialog_content = "先用金屬探測器尋找可疑的地點，再挖開看看。",
  ui_story_1011_10110402_59_dialog_content = "竟然連這種情況都考慮到了。",
  ui_story_1011_10110402_60_dialog_content = "那位大元帥確實像傳聞中所說的那樣深謀遠慮。",
  ui_story_1011_10110402_60X1_dialog_content = "把其他的補給和炸藥也一起拿下來吧。",
  ui_story_1011_10110402_60X2_dialog_content = "若是得尋找埋在地下的遺跡，很可能派得上用場。",
  ui_story_1011_10110402_61_dialog_content = "看起來也只有這個辦法了。",
  ui_story_1011_10110402_62_dialog_content = "希望運氣能好一點，很快找到入口。",
  ui_story_1011_10110402_63_dialog_content = "<color=#e8d9bb>白塔外部，某處</color>",
  ui_story_1011_10110402_64_dialog_content = "那座白塔，果然不像它的外表那麼單純。",
  ui_story_1011_10110402_65_dialog_content = "若非空裔手中那把鑰匙的指引，裡面的祕密或許永遠不會被人發現。",
  ui_story_1011_10110402_66_dialog_content = "是時候讓這些祕密成為實驗數據了。",
  ui_story_1011_10110402_66X1_dialog_content = "別想逃！",
  ui_story_1011_10110402_66X2_dialog_content = "嘎嗷——",
  ui_story_1011_10110402_66X3_dialog_content = "軍團長，附近的暗鬼已經掃蕩完畢！",
  ui_story_1011_10110402_66X4_dialog_content = "很好，趁現在重新建構防禦工事。",
  ui_story_1011_10110402_66X5_dialog_content = "是！",
  ui_story_1011_10110402_66X6_dialog_content = "這些暗鬼一個兩個全都是雜兵。",
  ui_story_1011_10110402_66X7_dialog_content = "吞羅到哪裡去了？",
  ui_story_1011_10110402_66X8_dialog_content = "難道她已經進入空之山谷了？",
  ui_story_1011_10110402_66X9_dialog_content = "這麼多的暗鬼，還有吞羅，只是為了對付PlayerName？",
  ui_story_1011_10110402_66X10_dialog_content = "這陣仗還真不小。",
  ui_story_1011_10110402_66X11_dialog_content = "我倒要看看，她還能玩出什麼花招。",
  ui_story_1011_10110501_1_dialog_content = "沒用的空箱子……",
  ui_story_1011_10110501_2_dialog_content = "扔掉。",
  ui_story_1011_10110501_3_dialog_content = "已經辨不清內容的書……",
  ui_story_1011_10110501_4_dialog_content = "扔掉。",
  ui_story_1011_10110501_5_dialog_content = "不知道裝著什麼的罐頭.......",
  ui_story_1011_10110501_6_dialog_content = "扔掉。",
  ui_story_1011_10110501_7_dialog_content = "等等，不能浪費啊！",
  ui_story_1011_10110501_8_dialog_content = "呃......這個罐頭不知道過期幾百年了。",
  ui_story_1011_10110501_9_dialog_content = "還是扔掉吧。",
  ui_story_1011_10110501_10_dialog_content = "......唉。",
  ui_story_1011_10110501_11_dialog_content = "忙了好久，竟然只搜到一堆沒用的東西。",
  ui_story_1011_10110501_12_dialog_content = "繼續仔細搜尋，不要有遺漏。",
  ui_story_1011_10110501_13_dialog_content = "好，我再找一找。",
  ui_story_1011_10110501_14_dialog_content = "這片區域好像還沒調查過。",
  ui_story_1011_10110501_15_dialog_content = "附近隨處散落這種白色石頭，看起來像是來自白塔的脫落？",
  ui_story_1011_10110501_16_dialog_content = "也不知道裡面有沒有機關……",
  ui_story_1011_10110501_17_dialog_content = "讓我用金屬探測器掃一掃。",
  ui_story_1011_10110501_18_dialog_content = "<color=#e8d9bb>滴滴滴——！</color>",
  ui_story_1011_10110501_19_dialog_content = "有反應了？ ！",
  ui_story_1011_10110501_20_dialog_content = "在石頭裡面？",
  ui_story_1011_10110501_21_option_content = "敲敲石頭",
  ui_story_1011_10110501_22_dialog_content = "<color=#e8d9bb>咚咚咚——！</color>",
  ui_story_1011_10110501_23_dialog_content = "聽起來不像空心的，難道在後面？",
  ui_story_1011_10110501_24_dialog_content = "這裡光線好差，陰影籠罩......",
  ui_story_1011_10110501_25_dialog_content = "陰影裡好像有什麼，無法看清楚。",
  ui_story_1011_10110501_26_dialog_content = "靠近一點，這是……",
  ui_story_1011_10110501_27_dialog_content = "頂著罐頭盒，想要假裝雜物的暗鬼？ ！ ！",
  ui_story_1011_10110501_28_dialog_content = "吼——！ ！ ！",
  ui_story_1011_10110501_29_dialog_content = "噫？ ！ ！",
  ui_story_1011_10110501_30_dialog_content = "PlayerName！",
  ui_story_1011_10110501_31_dialog_content = "嘎嗷......",
  ui_story_1011_10110501_32_dialog_content = "好，好危險！",
  ui_story_1011_10110501_33_dialog_content = "究竟何時跑過來的？ ！",
  ui_story_1011_10110501_34_dialog_content = "這裡空曠，陰影又多。",
  ui_story_1011_10110501_35_dialog_content = "暗鬼八成趁我們尋找入口時悄悄靠近。",
  ui_story_1011_10110501_36_dialog_content = "吼——！",
  ui_story_1011_10110501_37_dialog_content = "糟糕，我們被包圍了！",
  ui_story_1011_10110501_38_dialog_content = "更多暗鬼從入口湧了進來！",
  ui_story_1011_10110501_39_dialog_content = "我們必須突圍離開！",
  ui_story_1011_10110501_40_dialog_content = "不行！",
  ui_story_1011_10110501_41_dialog_content = "現在突圍，等於拱手把白塔和臨空者號讓給暗鬼！",
  ui_story_1011_10110501_42_dialog_content = "守住這裡，務必阻止暗鬼進來！",
  ui_story_1011_10110501_43_dialog_content = "但這裡就像個山洞，沒有大門！",
  ui_story_1011_10110501_44_dialog_content = "沒有大門……",
  ui_story_1011_10110501_45_dialog_content = "那就造一個大門出來！",
  ui_story_1011_10110501_46_dialog_content = "利用這些炸藥！",
  ui_story_1011_10110501_47_dialog_content = "難道你想炸塌入口？ ！",
  ui_story_1011_10110501_48_dialog_content = "對！",
  ui_story_1011_10110501_49_dialog_content = "這個入口塌了沒關係，我們還可以從白塔上層出去。",
  ui_story_1011_10110501_49X1_dialog_content = "再不行還能從地下遺跡尋找別的出口！",
  ui_story_1011_10110501_50_dialog_content = "現在這裡遭到暗鬼入侵，我們必須阻止牠們，保護臨空者號和地下遺跡！",
  ui_story_1011_10110501_51_dialog_content = "薇絲和我掩護你，PlayerName，抓住機會把炸藥放在入口引爆！",
  ui_story_1011_10110501_52_dialog_content = "好！",
  ui_story_1011_10110501_53_dialog_content = "拜託你們了！",
  ui_story_1011_10110502_1_dialog_content = "嘎嗷——！ ！ ！",
  ui_story_1011_10110502_2_dialog_content = "給我閃開！",
  ui_story_1011_10110502_3_dialog_content = "吼——！",
  ui_story_1011_10110502_4_dialog_content = "暗鬼愈來愈多，這樣下去連入口都接近不了......",
  ui_story_1011_10110502_5_dialog_content = "更別提引爆了！",
  ui_story_1011_10110502_6_dialog_content = "就算達不到目的，也要先突破眼前戰局。",
  ui_story_1011_10110502_7_dialog_content = "不能被困死在這裡！",
  ui_story_1011_10110502_9_dialog_content = "嚐嚐這個！",
  ui_story_1011_10110502_10_dialog_content = "快看入口的方向，那是——",
  ui_story_1011_10110502_11_dialog_content = "巴頓？ ！",
  ui_story_1011_10110502_12_dialog_content = "你怎麼在這裡？ ！",
  ui_story_1011_10110502_12X1_dialog_content = "哈，我就知道你們肯定沒事。",
  ui_story_1011_10110502_12X2_dialog_content = "我看見不少暗鬼往這邊來，覺得事情不對，所以就來看看。",
  ui_story_1011_10110502_13_dialog_content = "碰巧路過，順便揍幾隻暗鬼活動筋骨！",
  ui_story_1011_10110502_14_dialog_content = "小子，繼續幹你的事情，這邊有我頂著。",
  ui_story_1011_10110502_15_dialog_content = "暗鬼都被巴頓軍團長擋住了，PlayerName，好機會！",
  ui_story_1011_10110502_16_dialog_content = "巴頓，你離遠點，我們要封住入口！",
  ui_story_1011_10110502_17_dialog_content = "封住？怎麼封？",
  ui_story_1011_10110502_18_dialog_content = "炸掉！",
  ui_story_1011_10110502_19_dialog_content = "炸掉？！",
  ui_story_1011_10110502_20_dialog_content = "你小子也開始幹這種超乎常理的事情了啊。",
  ui_story_1011_10110502_21_dialog_content = "好，那就儘管炸你的，這裡交給我！",
  ui_story_1011_10110502_22_dialog_content = "PlayerName，暗鬼的攻勢變弱了，趁現在——！",
  ui_story_1011_10110502_23_dialog_content = "知道了！",
  ui_story_1011_10110502_24_dialog_content = "炸藥已經放好了，薇絲，卡蓮，快遠離！ ！ ！",
  ui_story_1011_10110502_25_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_1011_10110502_26_dialog_content = "成功了嗎？",
  ui_story_1011_10110502_27_dialog_content = "看起來成功了！",
  ui_story_1011_10110502_28_dialog_content = "巴頓好像還在外面？",
  ui_story_1011_10110502_29_dialog_content = "感應——！",
  ui_story_1011_10110502_30_dialog_content = "巴頓，你怎麼樣，沒受傷吧？ ！",
  ui_story_1011_10110502_31_dialog_content = "不用擔心，我很好！",
  ui_story_1011_10110502_32_dialog_content = "你們那邊沒事吧？",
  ui_story_1011_10110502_33_dialog_content = "入口已經封住了，暫時不用擔心我們！",
  ui_story_1011_10110502_34_dialog_content = "沒問題，那我就能豁出去盡情戰鬥了！",
  ui_story_1011_10110502_35_dialog_content = "注意安全！",
  ui_story_1011_10110502_36_dialog_content = "接下來就看我們的了。",
  ui_story_1011_10110502_37_dialog_content = "抓緊時間，繼續尋找遺跡！",
  ui_story_1011_10110502_38_dialog_content = "爆炸形成的屏障只能阻擋一陣子。",
  ui_story_1011_10110502_39_dialog_content = "那些暗鬼有足夠的人手清理阻礙，或者爬上白塔從上方入口進入。",
  ui_story_1011_10110502_40_dialog_content = "大家散開尋找吧！",
  ui_story_1011_10110502_41_dialog_content = "這附近已經都找過一遍了。",
  ui_story_1011_10110502_42_dialog_content = "就算再找也只能找到一堆雜物吧。",
  ui_story_1011_10110502_43_dialog_content = "有沒有什麼別的辦法呢……",
  ui_story_1011_10110502_44_dialog_content = "比如，只有空裔知道的辦法？",
  ui_story_1011_10110502_45_dialog_content = "你是指……感應能力？",
  ui_story_1011_10110502_46_dialog_content = "對。",
  ui_story_1011_10110502_47_dialog_content = "你能使用感應能力，試著找找看可能殘留的線索嗎？",
  ui_story_1011_10110502_48_dialog_content = "我試試！",
  ui_story_1011_10110502_49_option_content = "感應！",
  ui_story_1011_10110502_50_dialog_content = "呃！",
  ui_story_1011_10110502_51_dialog_content = "我的頭！",
  ui_story_1011_10110502_52_dialog_content = "PlayerName？！",
  ui_story_1011_10110502_53_dialog_content = "這附近很奇怪。",
  ui_story_1011_10110502_54_dialog_content = "就好像有什麼東西在阻止我使用感應能力探索四周。",
  ui_story_1011_10110502_55_dialog_content = "干擾空裔的感應能力……",
  ui_story_1011_10110502_56_dialog_content = "是想隱藏什麼嗎？",
  ui_story_1011_10110502_57_dialog_content = "不過這也表示我們找對了方向。",
  ui_story_1011_10110502_58_dialog_content = "但是，若PlayerName不能使用感應能力，那豈不就斷了線索？",
  ui_story_1011_10110502_59_dialog_content = "……不，應該還有一種方法。",
  ui_story_1011_10110502_60_dialog_content = "我曾經通過感應智庫組件，找到了修復臨空者號的意識模組修復器。",
  ui_story_1011_10110502_61_dialog_content = "而指引我們來到這裡的正是這個修復器中的數據。",
  ui_story_1011_10110502_62_dialog_content = "我想試試感應一下修復器，看看能不能找到解決問題的辦法！",
  ui_story_1011_10110502_62X1_dialog_content = "剛才感應巴頓的時候，沒有受到干擾。",
  ui_story_1011_10110502_62X2_dialog_content = "所以我猜，如果有具体的感應目標，應該不會受到影響。",
  ui_story_1011_10110502_63_dialog_content = "確實是一種思路。",
  ui_story_1011_10110502_64_dialog_content = "雖然聽起來可行，但是……",
  ui_story_1011_10110502_65_dialog_content = "PlayerName，如果覺得難受，一定要立刻切斷感應！",
  ui_story_1011_10110502_66_dialog_content = "不要勉強自己。",
  ui_story_1011_10110502_67_dialog_content = "嗯，放心吧。",
  ui_story_1011_10110502_68_option_content = "強制感應！",
  ui_story_1011_10110502_69_dialog_content = "……",
  ui_story_1011_10110502_70_dialog_content = "告訴我，開放通向中控室道路的方法！",
  ui_story_1011_10110502_71_dialog_content = "「指令接受。正在進行檢測......」",
  ui_story_1011_10110502_72_dialog_content = "「偵測到門禁系統離線。」",
  ui_story_1011_10110502_73_dialog_content = "「正在派出螢盞進行修復。」",
  ui_story_1011_10110502_74_dialog_content = "臨空者號上……飛下來一隻螢盞？",
  ui_story_1011_10110502_75_dialog_content = "「嗶——！」",
  ui_story_1011_10110502_76_dialog_content = "<color=#e8d9bb>喀噠</color>",
  ui_story_1011_10110502_77_dialog_content = "「已連接門禁系統備用電源，正在啟動門禁系統。」",
  ui_story_1011_10110502_78_dialog_content = "「請輸入口令，驗證身分。」",
  ui_story_1011_10110502_79_dialog_content = "什麼？",
  ui_story_1011_10110502_80_dialog_content = "哪來的聲音？ ！",
  ui_story_1011_10110502_81_dialog_content = "「本系統為巨像整備基地門禁系統。」",
  ui_story_1011_10110502_82_dialog_content = "「警告：門禁系統已與中央控制系統斷開連接■■■■■■■日。」",
  ui_story_1011_10110502_83_dialog_content = "「請及時修復斷線，或重設口令。」",
  ui_story_1011_10110502_84_dialog_content = "聽起來像是開門用的？",
  ui_story_1011_10110502_85_dialog_content = "還是聲控的！",
  ui_story_1011_10110502_86_dialog_content = "「口令錯誤！您還有3次機會。」",
  ui_story_1011_10110502_87_dialog_content = "欸？不是，我沒有，剛才那個不算！",
  ui_story_1011_10110502_88_dialog_content = "「口令錯誤！您還有2次機會。」",
  ui_story_1011_10110502_89_dialog_content = "等，等等！",
  ui_story_1011_10110502_90_dialog_content = "「口令錯誤！您還有1次機會。」",
  ui_story_1011_10110502_91_dialog_content = "「請注意，若機會耗盡，門禁系統將進入鎖死狀態。」",
  ui_story_1011_10110502_92_dialog_content = "不可以再說了！",
  ui_story_1011_10110502_93_dialog_content = "唔唔唔！ ！ ！",
  ui_story_1011_10110502_94_dialog_content = "能不能重設口令？ ！",
  ui_story_1011_10110502_95_dialog_content = "「警告：偵測到非授權基因型，指令無效。」",
  ui_story_1011_10110502_96_dialog_content = "……",
  ui_story_1011_10110502_97_dialog_content = "（你們的意思是，要我來？）",
  ui_story_1011_10110502_98_dialog_content = "這可是最後的機會了，PlayerName，你來試試。",
  ui_story_1011_10110502_99_dialog_content = "千萬別說錯話。",
  ui_story_1011_10110502_100_dialog_content = "（好......）",
  ui_story_1011_10110502_101_dialog_content = "……",
  ui_story_1011_10110502_102_option_content = "門禁系統，重設口令",
  ui_story_1011_10110502_103_dialog_content = "「偵測到授權基因型。開始重設口令。」",
  ui_story_1011_10110502_104_dialog_content = "「請回答三個問題，驗證身分。」",
  ui_story_1011_10110502_105_dialog_content = "還要答題？",
  ui_story_1011_10110502_106_dialog_content = "沒辦法，只能走一步看一步了。",
  ui_story_1011_10110502_107_dialog_content = "PlayerName，別緊張，我會幫你的。",
  ui_story_1011_10110502_108_dialog_content = "賭上我在學校連續幾年期末考的優秀成績！",
  ui_story_1011_10110502_109_dialog_content = "「請問，您是暗鬼嗎？」",
  ui_story_1011_10110502_110_dialog_content = "哈......？",
  ui_story_1011_10110502_111_dialog_content = "我怎麼可能是暗鬼嘛！",
  ui_story_1011_10110502_112_dialog_content = "「偵測到非法回答。」",
  ui_story_1011_10110502_113_dialog_content = "「重複一遍，請問您是暗鬼嗎？」",
  ui_story_1011_10110502_114_dialog_content = "呃，我不是！",
  ui_story_1011_10110502_115_dialog_content = "「回答錄入完畢。」",
  ui_story_1011_10110502_116_dialog_content = "「請問，您是光靈嗎？」",
  ui_story_1011_10110502_117_dialog_content = "我也不是光靈。",
  ui_story_1011_10110502_118_dialog_content = "「回答錄入完畢。」",
  ui_story_1011_10110502_119_dialog_content = "「請從下列物品中選出螢盞。」",
  ui_story_1011_10110502_120_dialog_content = "這是……投影嗎？",
  ui_story_1011_10110502_121_dialog_content = "簡直像真的一樣！",
  ui_story_1011_10110502_122_option_content = "觸摸螢盞的投影",
  ui_story_1011_10110502_123_dialog_content = "「回答錄入完畢。」",
  ui_story_1011_10110502_124_dialog_content = "「驗證通過，已確認身分：空裔。」",
  ui_story_1011_10110502_125_dialog_content = "「請重設門禁系統口令。」",
  ui_story_1011_10110502_126_dialog_content = "呃……拉麵開門！",
  ui_story_1011_10110502_127_dialog_content = "「重設完成，新口令為——呃，拉麵開門。」",
  ui_story_1011_10110502_128_dialog_content = "不要把語氣詞也錄進去啊！",
  ui_story_1011_10110502_129_dialog_content = "「即將為您開啟大門。」",
  ui_story_1011_10110502_130_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_1011_10110502_131_dialog_content = "唔哇？！",
  ui_story_1011_10110502_132_dialog_content = "<color=#e8d9bb>轟隆隆——！ ！ ！</color>",
  ui_story_1011_10110502_133_dialog_content = "牆壁上的石頭裂開了，後面......出現了一道門！",
  ui_story_1011_10110502_134_dialog_content = "好大——！",
  ui_story_1011_10110502_135_dialog_content = "但是我還是要吐槽。",
  ui_story_1011_10110502_136_dialog_content = "剛才那個身分驗證根本就沒用啊！",
  ui_story_1011_10110502_137_dialog_content = "稍微有智慧的生物隨便扯個謊都能通過吧！",
  ui_story_1011_10110502_137X1_dialog_content = "或許重要的根本就不是問題本身。",
  ui_story_1011_10110502_137X2_dialog_content = "如果不是問題本身，那會是什麼？",
  ui_story_1011_10110502_137X3_dialog_content = "空裔的身分僅憑這幾個簡單的問題就可以確定嗎？",
  ui_story_1011_10110502_137X4_dialog_content = "在剛才我做出提問時，它提到了「非授權基因型」......",
  ui_story_1011_10110502_137X5_dialog_content = "我認為它很可能透過其他檢測手段事先確定了你的空裔血統。",
  ui_story_1011_10110502_137X6_dialog_content = "而它之所以提出那些問題，大概只是想要你回答一句「我是空裔」。",
  ui_story_1011_10110502_137X7_dialog_content = "一句確定的回答，竟然比其他的證據都重要嗎？",
  ui_story_1011_10110502_137X8_dialog_content = "或許這就是機器的思維吧。",
  ui_story_1011_10110502_137X9_dialog_content = "不過......這座遺跡還具備隔空檢測基因的技術嗎？",
  ui_story_1011_10110502_137X10_dialog_content = "彷彿一下子就被看透了，真讓人覺得不舒服。",
  ui_story_1011_10110502_137X11_dialog_content = "過程不重要，重要的是結果。",
  ui_story_1011_10110502_137X12_dialog_content = "門已經打開，我們也沒有必要再去糾結開門的方式了。",
  ui_story_1011_10110502_138_dialog_content = "也要感謝這個漏洞這麼簡單呢。",
  ui_story_1011_10110502_139_dialog_content = "這扇通向下方的大門，恐怕就是地下遺跡的入口了吧。",
  ui_story_1011_10110502_140_dialog_content = "如果有這樣一扇大門一直存在於這裡，為什麼過去的空裔們都沒有發現呢？",
  ui_story_1011_10110502_141_dialog_content = "我也不清楚，這裡的謎團太多了......",
  ui_story_1011_10110502_142_dialog_content = "不管怎樣，既然出現了這條通路，就說明下面還有著等待探索的區域。",
  ui_story_1011_10110502_143_dialog_content = "現在最要緊的，是找到修復臨空者號的方法，和繞過暗鬼、離開這裡的路線。",
  ui_story_1011_10110502_144_dialog_content = "說得對，我們不能再浪費時間了。",
  ui_story_1011_10110502_145_dialog_content = "那就出發吧！",
  ui_story_1011_10110601_1_dialog_content = "嘎——",
  ui_story_1011_10110601_2_dialog_content = "連偷襲都做不好的低等生物，就別過來當砲灰了。",
  ui_story_1011_10110601_3_dialog_content = "是誰派你們來？更大一號的暗鬼？還是那個腦子有問題的科學家？",
  ui_story_1011_10110601_4_dialog_content = "差點忘了，你們連話都不會說。",
  ui_story_1011_10110601_5_dialog_content = "嘎……",
  ui_story_1011_10110601_6_dialog_content = "哈哈哈哈哈哈哈！一群垃圾！",
  ui_story_1011_10110601_7_dialog_content = "踩著你們的屍體可沒什麼成就感，日蝕只有這點能耐嗎？",
  ui_story_1011_10110601_8_dialog_content = "……",
  ui_story_1011_10110601_10_dialog_content = "誰在那裡！",
  ui_story_1011_10110601_11_dialog_content = "……",
  ui_story_1011_10110601_12_dialog_content = "還真是妳，<color=#FFB400>德尼耶爾</color>......啟光的叛徒。",
  ui_story_1011_10110601_13_dialog_content = "——差點忘了，妳已經徹底被啟光除名了。",
  ui_story_1011_10110601_14_dialog_content = "嘖。",
  ui_story_1011_10110601_15_dialog_content = "真是沒用，想犧牲雜兵聲東擊西就別被人逮住。",
  ui_story_1011_10110601_16_dialog_content = "（雜兵？……這就是斐桀洛在外圍佈下的手下嗎？）",
  ui_story_1011_10110601_17_dialog_content = "（他又在擅自幹這種多餘的事……）",
  ui_story_1011_10110601_18_dialog_content = "我無意加入你們的爭鬥，這些暗鬼也不是我所指派。",
  ui_story_1011_10110601_19_dialog_content = "愚蠢的戰爭，只會波及並影響那座白塔隱藏的祕密。",
  ui_story_1011_10110601_20_dialog_content = "（白塔？她想尾隨PlayerName他們進去嗎……）",
  ui_story_1011_10110601_21_dialog_content = "啥？戰場可不是聽你講道理的地方！",
  ui_story_1011_10110601_22_dialog_content = "想進去也得憑本事。",
  ui_story_1011_10110601_23_dialog_content = "我也懶得站在這跟你廢話，接招吧，吞羅——",
  ui_story_1011_10110601_24_dialog_content = "嚐嚐鐵顎的力量！",
  ui_story_1011_10110601_25_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_1011_10110601_26_dialog_content = "真麻煩，這裡又跟你有什麼關係。",
  ui_story_1011_10110601_27_dialog_content = "我討厭節外生枝。",
  ui_story_1011_10110601_28_dialog_content = "如果殺了你就能解決問題，那倒也挺方便的。",
  ui_story_1011_10110601_29_dialog_content = "哈哈哈哈哈哈哈哈！這不就對了嗎！",
  ui_story_1011_10110601_30_dialog_content = "我們一起來打發掉這段無聊時光吧！",
  ui_story_1011_10110601_31_dialog_content = "<color=#e8d9bb>主塔，入口通道</color>",
  ui_story_1011_10110601_32_dialog_content = "<color=#e8d9bb>嗒......嗒......嗒......</color>",
  ui_story_1011_10110601_33_dialog_content = "（好狹長的一條通道，走起來像沒有盡頭一樣……）",
  ui_story_1011_10110601_34_dialog_content = "（回頭看看……唔，入口的光也快看不見了。）",
  ui_story_1011_10110601_35_dialog_content = "<color=#e8d9bb>喀啦喀啦......</color>",
  ui_story_1011_10110601_36_dialog_content = "薇絲，看路！",
  ui_story_1011_10110601_37_dialog_content = "咦？！",
  ui_story_1011_10110601_38_dialog_content = "<color=#e8d9bb>砰——</color>",
  ui_story_1011_10110601_39_dialog_content = "小心一點啊！",
  ui_story_1011_10110601_40_dialog_content = "咳咳咳……",
  ui_story_1011_10110601_41_dialog_content = "好大的灰塵！",
  ui_story_1011_10110601_42_dialog_content = "<color=#e8d9bb><size=35>的灰塵......灰塵......灰塵......</size></color>",
  ui_story_1011_10110601_43_dialog_content = "唔？",
  ui_story_1011_10110601_44_dialog_content = "噓，我們都安靜一點吧。",
  ui_story_1011_10110601_45_dialog_content = "聽上去，前面還有一段不短的距離。",
  ui_story_1011_10110601_46_dialog_content = "在這種直來直往的隧道裡，要是有什麼東西聞聲而來，我們連躲的機會都沒有。",
  ui_story_1011_10110601_47_dialog_content = "話說回來了，PlayerName……",
  ui_story_1011_10110601_48_dialog_content = "在這之前，你真的從來不知道這個地方的存在嗎？",
  ui_story_1011_10110601_49_dialog_content = "嗯......不用說我，連臨空者號都從沒提過這一塊遺跡。",
  ui_story_1011_10110601_50_dialog_content = "畢竟臨空者號也不是無所不知的。",
  ui_story_1011_10110601_51_dialog_content = "……",
  ui_story_1011_10110601_52_dialog_content = "（臨空者號……）",
  ui_story_1011_10110601_53_dialog_content = "既然，我們是順著意識模組插件的引導來到這裡的......",
  ui_story_1011_10110601_54_dialog_content = "只要找到那個「中央控制系統」就沒錯了吧。",
  ui_story_1011_10110601_55_dialog_content = "裡面一定會有修整臨空者號的辦法，PlayerName。",
  ui_story_1011_10110601_56_dialog_content = "嗯……！謝謝你，薇絲。",
  ui_story_1011_10110601_57_dialog_content = "嗯？",
  ui_story_1011_10110601_58_dialog_content = "怎麼了？",
  ui_story_1011_10110601_59_dialog_content = "腳下的這些……不像是普通的碎石塊，也不是常見的那種白色石頭。",
  ui_story_1011_10110601_60_dialog_content = "唔，我看一下……",
  ui_story_1011_10110601_61_dialog_content = "顏色和材質確實都很特別，根據我以前在學院看到的相關記載來看……",
  ui_story_1011_10110601_62_dialog_content = "這些是艾斯特拉大陸遠古時期才有的特殊材料……",
  ui_story_1011_10110601_63_dialog_content = "（......咦？！）",
  ui_story_1011_10110601_64_dialog_content = "那......那這些不就是……",
  ui_story_1011_10110601_65_dialog_content = "<color=#FFB400>巨像肌材</color>嗎？",
  ui_story_1011_10110601_66_dialog_content = "？！",
  ui_story_1011_10110601_67_dialog_content = "（細細碎碎地向前鋪開，越往前出現得越多……）",
  ui_story_1011_10110601_68_dialog_content = "（難，難道......它們全都是巨像的<color=#FFB400>殘骸</color>嗎？！）",
  ui_story_1011_10110601_69_dialog_content = "也就是說，這裡真的是巨像整備基地的內部！",
  ui_story_1011_10110601_70_dialog_content = "看這個數量，巨像絕對是當時很常見的載具，傳說和史料裡記載得千真萬確！",
  ui_story_1011_10110601_71_dialog_content = "啊！PlayerName，前面是通道的出口了！",
  ui_story_1011_10110601_72_dialog_content = "哎……PlayerName，怎麼了？",
  ui_story_1011_10110601_73_dialog_content = "……",
  ui_story_1011_10110601_74_option_content = "有點恐懼",
  ui_story_1011_10110601_75_dialog_content = "我......我從來沒有見過這樣的場景……",
  ui_story_1011_10110601_76_dialog_content = "臨空者號對我來說……是家人、朋友、老師一樣的存在。",
  ui_story_1011_10110601_77_dialog_content = "他和我一起去過很多地方，也在很多危局中化險為夷……",
  ui_story_1011_10110601_78_dialog_content = "但我從來沒有想過，他有可能會變成這種樣子。",
  ui_story_1011_10110601_79_option_content = "有點高興",
  ui_story_1011_10110601_80_dialog_content = "艾斯特拉大陸上現存的巨像少之又少。",
  ui_story_1011_10110601_81_dialog_content = "一想到在前十七年空無一人的空谷中，在我和臨空者號的腳下……",
  ui_story_1011_10110601_82_dialog_content = "還埋藏著前人留下的大量的巨像遺跡……",
  ui_story_1011_10110601_83_dialog_content = "就……更有了一點歸屬感吧。",
  ui_story_1011_10110601_84_dialog_content = "原來如此。",
  ui_story_1011_10110601_85_dialog_content = "那我們就快點往前走吧。",
  ui_story_1011_10110601_86_dialog_content = "看一看這些巨像殘骸的來源！",
  ui_story_1011_10110601_87_dialog_content = "啊……總算是寬敞了一點。",
  ui_story_1011_10110601_88_dialog_content = "本來以為這裡會更加昏暗，沒想到基本的能見度不成問題。",
  ui_story_1011_10110601_89_dialog_content = "唔，只是那些模模糊糊的巨像影子很擋視線……",
  ui_story_1011_10110601_90_dialog_content = "嗯，雖然不清楚光線的來源，但我們至少沒有處於一個完全密閉的空間。",
  ui_story_1011_10110601_91_dialog_content = "你看這些巨像整齊排列的樣子……",
  ui_story_1011_10110601_92_dialog_content = "如果這個遺跡沒有坍塌，他們一定還能被保存得很完好吧......",
  ui_story_1011_10110601_93_dialog_content = "PlayerName，要不要試著感應一下？",
  ui_story_1011_10110601_94_dialog_content = "萬一這裡還殘存著具備意識的巨像，就可以和他們建立連接了。",
  ui_story_1011_10110601_95_dialog_content = "說得也是，那麼——",
  ui_story_1011_10110601_96_option_content = "強制感應！",
  ui_story_1011_10110601_97_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_1011_10110601_98_dialog_content = "不行……沒有任何反應。",
  ui_story_1011_10110601_99_dialog_content = "（想想也是，在這種遺跡是絕對不可能發現具備意識的生命體......）",
  ui_story_1011_10110601_100_dialog_content = "至、至少，我們已經看到了遠古巨像的活動痕跡。",
  ui_story_1011_10110601_101_dialog_content = "接下來就順著周圍這些門，逐一探查一遍吧。",
  ui_story_1011_10110601_102_dialog_content = "打起精神來，PlayerName！",
  ui_story_1011_10110601_103_dialog_content = "好，那麼我們……",
  ui_story_1011_10110601_104_option_content = "查看周圍",
  ui_story_1011_10110601_105_dialog_content = "<color=#e8d9bb>咚——！</color>",
  ui_story_1011_10110601_106_dialog_content = "……呃？！",
  ui_story_1011_10110601_107_dialog_content = "手好痛……根本推不動！",
  ui_story_1011_10110601_108_dialog_content = "按巨像殘骸的受損程度來看，這些房間也很難倖免吧。",
  ui_story_1011_10110601_109_dialog_content = "坍塌下來的石塊把這些門堵死了，看上去只有前面一條路可以走。",
  ui_story_1011_10110601_110_option_content = "向前走",
  ui_story_1011_10110601_111_dialog_content = "嗯！前面的路……似乎是通向下一層的樓梯！",
  ui_story_1011_10110601_112_dialog_content = "應、應該可以走吧！如果這麼多年都沒有被腐蝕掉的話……",
  ui_story_1011_10110601_113_dialog_content = "既然入口處曾經停靠著這麼多巨像……",
  ui_story_1011_10110601_114_dialog_content = "那麼下面的空間一定也會配備全套的巨像修護體系吧。",
  ui_story_1011_10110601_115_dialog_content = "PlayerName，我們接著走走吧。",
  ui_story_1011_10110601_116_dialog_content = "<color=#e8d9bb>嗒......嗒......嗒......</color>",
  ui_story_1011_10110601_117_dialog_content = "（好黑的樓梯，這個時候要是有螢盞就好了……）",
  ui_story_1011_10110601_118_dialog_content = "（不知道下面會埋藏著怎樣的技術，能不能適用在臨空者號身上……）",
  ui_story_1011_10110601_119_dialog_content = "（終於走到底了，要快點看一看——）",
  ui_story_1011_10110601_120_dialog_content = "……咦？",
  ui_story_1011_10110601_121_dialog_content = "怎......怎麼會？",
  ui_story_1011_10110601_122_dialog_content = "這麼大一層，放眼望去居然沒有任何大型儀器......",
  ui_story_1011_10110601_123_dialog_content = "看來整個地下遺跡比我想像得還要大。",
  ui_story_1011_10110601_124_dialog_content = "但這一層究竟是做什麼用的……",
  ui_story_1011_10110601_125_dialog_content = "積灰的桌子、已經看不出擺了什麼東西的石質貨架，還有莫名其妙的軟墊……",
  ui_story_1011_10110601_126_dialog_content = "這是什麼雜物間嗎？",
  ui_story_1011_10110601_127_dialog_content = "噗……哈哈哈哈哈，你這麼一說，我就更確定了。",
  ui_story_1011_10110601_128_dialog_content = "我想，這裡大概是遠古空裔的<color=#FFB400>生活區</color>。",
  ui_story_1011_10110601_129_dialog_content = "啟光地下城的生活區，也設置了類似的基本生活用品。",
  ui_story_1011_10110601_130_dialog_content = "雖然這些不知年份的東西都已經破爛不堪了，但大體上還是可以辨認出來——",
  ui_story_1011_10110601_131_dialog_content = "餐桌、工作台、食品櫃、置物架、備用床墊……",
  ui_story_1011_10110601_132_dialog_content = "它們可不是雜物啊，卡蓮。",
  ui_story_1011_10110601_133_dialog_content = "我......我知道了！",
  ui_story_1011_10110601_134_dialog_content = "唔？",
  ui_story_1011_10110601_135_dialog_content = "薇絲，你看這個杯子上是不是有東西？",
  ui_story_1011_10110601_136_dialog_content = "嗯？哪裡哪裡？",
  ui_story_1011_10110601_137_dialog_content = "這......這些只是普通的污垢吧！",
  ui_story_1011_10110601_138_dialog_content = "不，我指的是杯底這裡。PlayerName，你過來看。",
  ui_story_1011_10110601_139_dialog_content = "咦，好像……好像真的刻著什麼記號！",
  ui_story_1011_10110601_140_dialog_content = "哇，真的欸！",
  ui_story_1011_10110601_141_dialog_content = "難道是和空裔一族有關的標誌嗎……",
  ui_story_1011_10110601_142_dialog_content = "我覺得不像，因為，你再看看周圍這些小物件……",
  ui_story_1011_10110601_143_dialog_content = "只有這個杯子上刻著印記。",
  ui_story_1011_10110601_144_dialog_content = "是啊，如果它是空裔統一標誌，在這些集體配給的東西上就都會出現才對。",
  ui_story_1011_10110601_145_dialog_content = "可是它到底刻著什麼啊，我怎麼也看不清楚。",
  ui_story_1011_10110601_146_dialog_content = "我覺得……它十之八九是一個名字的縮寫，但是……",
  ui_story_1011_10110601_147_dialog_content = "不行，磨損得太嚴重了，看不出具體內容。",
  ui_story_1011_10110601_148_dialog_content = "那就不要在它上面浪費時間了吧。",
  ui_story_1011_10110601_149_dialog_content = "唔……",
  ui_story_1011_10110601_150_dialog_content = "（雖然PlayerName這樣說了，但還是覺得有點在意……）",
  ui_story_1011_10110601_151_dialog_content = "（能在這裡看到前人的名字，也算是一種緣分。）",
  ui_story_1011_10110601_152_dialog_content = "（嗯！再到處找找和它有關的線索吧！）",
  ui_story_1011_10110601_153_dialog_content = "咦，桌子上這幾個東西是什麼……",
  ui_story_1011_10110601_154_dialog_content = "不可思議！這是......",
  ui_story_1011_10110601_155_dialog_content = "鸚鵡螺？",
  ui_story_1011_10110601_156_dialog_content = "而且是好幾個鸚鵡螺擺在一起。",
  ui_story_1011_10110601_157_dialog_content = "那個，PlayerName，這也是空裔一族的......呃，日用品嗎？",
  ui_story_1011_10110601_158_dialog_content = "咦？！這是......妳剛找到的嗎？",
  ui_story_1011_10110601_159_dialog_content = "不要說看過，我甚至不知道這是什麼東西。",
  ui_story_1011_10110601_160_dialog_content = "鸚鵡螺嗎？這是海裡才會有的生物啊。",
  ui_story_1011_10110601_161_dialog_content = "難道……空谷以前是一片海洋，還是說……這是遠古空裔的食物？",
  ui_story_1011_10110601_162_dialog_content = "你說的可能性都很離譜啊！",
  ui_story_1011_10110601_163_dialog_content = "唔，這幾個鸚鵡螺可能跟我們常規認知中的不太一樣......",
  ui_story_1011_10110601_164_dialog_content = "樣子小巧光滑，重量也很輕，經過這麼久還能保存得這麼完好。",
  ui_story_1011_10110601_165_dialog_content = "一定是出於方便攜帶、易於保存而被設計出來，並投入使用的。",
  ui_story_1011_10110601_166_dialog_content = "而且......哇啊啊？",
  ui_story_1011_10110601_167_dialog_content = "這、這裡面還裝著東西？！",
  ui_story_1011_10110601_168_dialog_content = "什麼？！",
  ui_story_1011_10110601_169_dialog_content = "受傷了嗎！有沒有灑出來了？",
  ui_story_1011_10110601_170_dialog_content = "這......這倒是沒有......灑在手上沒什麼感覺。",
  ui_story_1011_10110601_171_dialog_content = "聞聞……",
  ui_story_1011_10110601_172_dialog_content = "唔，無色、無味，流動性很強，暫時看不出是什麼液體。",
  ui_story_1011_10110601_173_dialog_content = "（咦？鸚鵡螺......流動？）",
  ui_story_1011_10110601_174_dialog_content = "（難道說……）",
  ui_story_1011_10110601_175_dialog_content = "呼……總之還是謹慎一點比較好，小心這些來路不明的東西。",
  ui_story_1011_10110601_176_dialog_content = "說、說得也是……",
  ui_story_1011_10110601_177_dialog_content = "（無憑無據，我還是先不要亂猜亂說了。）",
  ui_story_1011_10110601_178_dialog_content = "（如果我的猜想正確，那應該還能在這個遺跡裡找到可以驗證的東西。）",
  ui_story_1011_10110601_179_dialog_content = "（姑且先把它們塞在口袋裡吧……）",
  ui_story_1011_10110601_180_dialog_content = "<color=#e8d9bb>咚——！</color>",
  ui_story_1011_10110601_181_dialog_content = "咦？！",
  ui_story_1011_10110601_182_dialog_content = "PlayerName、卡蓮？你們那邊怎麼了！",
  ui_story_1011_10110601_183_dialog_content = "嗯？！我還以為聲音是從你這邊傳來的？等一下......",
  ui_story_1011_10110601_184_dialog_content = "......不妙！！！",
  ui_story_1011_10110601_185_dialog_content = "難道還有別人留在這裡？",
  ui_story_1011_10110601_186_dialog_content = "如果有人的話早就該現身了，只怕……",
  ui_story_1011_10110601_187_dialog_content = "嘎……",
  ui_story_1011_10110601_188_dialog_content = "吼吼吼！！！",
  ui_story_1011_10110601_189_dialog_content = "不是吧，這裡也有暗鬼？！",
  ui_story_1011_10110601_190_dialog_content = "難道暗鬼還是跟著我們進來了嗎……",
  ui_story_1011_10110601_191_dialog_content = "PlayerName，準備好了嗎？",
  ui_story_1011_10110601_192_dialog_content = "當然了。",
  ui_story_1011_10110702_1_dialog_content = "PlayerName、PlayerName！",
  ui_story_1011_10110702_2_dialog_content = "這、這到底是怎麼回事……",
  ui_story_1011_10110702_3_dialog_content = "醒醒啊，PlayerName！",
  ui_story_1011_10110702_4_dialog_content = "（唔……）",
  ui_story_1011_10110702_5_dialog_content = "（好難受……喘不過氣來……）",
  ui_story_1011_10110702_6_dialog_content = "（薇絲和卡蓮……在叫我嗎？她們的聲音離我好遠……）",
  ui_story_1011_10110702_7_dialog_content = "（我……）",
  ui_story_1011_10110702_8_dialog_content = "偵測到對象：超感天賦生命體。身分確認：空裔。",
  ui_story_1011_10110702_9_dialog_content = "精神連結已開啟。",
  ui_story_1011_10110702_10_dialog_content = "警告：偵測對象呼吸道氧氣含量不足。生活區送風系統已開啟。",
  ui_story_1011_10110702_11_dialog_content = "<color=#e8d9bb>呼——呼——</color>",
  ui_story_1011_10110702_12_dialog_content = "（什、什麼聲音……）",
  ui_story_1011_10110702_13_dialog_content = "嗯……？",
  ui_story_1011_10110702_14_dialog_content = "啊——PlayerName！",
  ui_story_1011_10110702_15_dialog_content = "PlayerName，你醒了！",
  ui_story_1011_10110702_16_dialog_content = "怎麼樣，有沒有感覺到什麼異樣？",
  ui_story_1011_10110702_17_dialog_content = "我……我現在好像已經沒事了。",
  ui_story_1011_10110702_18_dialog_content = "剛才的戰鬥有點激烈，一路走下來也消耗了不少體力，所以我……",
  ui_story_1011_10110702_19_dialog_content = "所以我一口氣沒喘上來就，就……",
  ui_story_1011_10110702_20_dialog_content = "戰鬥……激烈？",
  ui_story_1011_10110702_21_dialog_content = "消耗體力？",
  ui_story_1011_10110702_22_dialog_content = "……",
  ui_story_1011_10110702_23_dialog_content = "（不要這麼沉默地盯著我啊！）",
  ui_story_1011_10110702_24_dialog_content = "正在分析偵測對象身體機能狀況……",
  ui_story_1011_10110702_25_dialog_content = "狀態：正常。體質評價等級：甲級弱。",
  ui_story_1011_10110702_26_dialog_content = "嗯？！",
  ui_story_1011_10110702_27_dialog_content = "誰！誰在說話？！",
  ui_story_1011_10110702_28_dialog_content = "雖然說得還挺有道理……",
  ui_story_1011_10110702_29_dialog_content = "輔腦的任務是服務於空裔，解決空裔所有疑問。",
  ui_story_1011_10110702_30_dialog_content = "接收，疑問分析中……",
  ui_story_1011_10110702_31_dialog_content = "答案形成：輔腦偵測到空裔需要幫助，輔腦在對空裔說話。",
  ui_story_1011_10110702_32_dialog_content = "（連這種問題都要經過這麼漫長的分析嗎？！）",
  ui_story_1011_10110702_33_dialog_content = "不過這麼一想，剛才在我昏迷的時候……",
  ui_story_1011_10110702_34_dialog_content = "警告：偵測對象呼吸道氧氣含量不足。生活區送風系統已開啟。",
  ui_story_1011_10110702_35_dialog_content = "確實是它操作了這裡的送風系統，才讓我醒過來的。",
  ui_story_1011_10110702_36_dialog_content = "哦，難怪我剛才稍微感覺到……有一絲清涼的風吹在身上。",
  ui_story_1011_10110702_36X_dialog_content = "這是什麼東西？看樣子只是虛影。",
  ui_story_1011_10110702_37_dialog_content = "遠古空裔的科技嗎……關鍵時刻還挺可靠的。",
  ui_story_1011_10110702_38_dialog_content = "哇，讓我看看讓我看看，這裡現在竟然還有能運轉起來的人工智能！",
  ui_story_1011_10110702_39_dialog_content = "唔……",
  ui_story_1011_10110702_40_dialog_content = "……",
  ui_story_1011_10110702_41_dialog_content = "偵測到對象：光能生命體。身分確認：光靈。數目：二。",
  ui_story_1011_10110702_42_dialog_content = "「輔腦」，你是……遠古空裔的科技之一嗎？",
  ui_story_1011_10110702_43_dialog_content = "接收，疑問分析中……分析錯誤，輔腦的任務是，解決空裔所有疑問。",
  ui_story_1011_10110702_44_dialog_content = "怎......怎麼這樣！難道光靈就不可以使用空裔的儀器嗎！",
  ui_story_1011_10110702_45_dialog_content = "接收，疑問分析中……分析錯誤，輔腦的任務是，解決空裔所有疑問。",
  ui_story_1011_10110702_46_dialog_content = "啊，真是的……這句不是疑問！！ !",
  ui_story_1011_10110702_47_dialog_content = "有沒有光靈說過你性格很差啊！",
  ui_story_1011_10110702_48_dialog_content = "消消氣，消消氣薇絲，我來直接問它吧！",
  ui_story_1011_10110702_49_dialog_content = "輔......輔腦！我確實有不少問題要問一問——",
  ui_story_1011_10110702_50_dialog_content = "接收，系統認知修改中……正在錄入設備新名稱：輔輔腦。",
  ui_story_1011_10110702_51_dialog_content = "啊？等一下……錄入停止！錄入停止！",
  ui_story_1011_10110702_52_dialog_content = "錄入已停止。",
  ui_story_1011_10110702_53_dialog_content = "（呃，我算是知道了，雖說它是個遠古時代遺留下來的人工智能……）",
  ui_story_1011_10110702_54_dialog_content = "（但好像也不是那麼智能……）",
  ui_story_1011_10110702_55_dialog_content = "（為了便於溝通，我還是把問題拆開吧……）",
  ui_story_1011_10110702_56_dialog_content = "咳……第一個問題：請介紹一下這座塔是什麼地方。",
  ui_story_1011_10110702_57_dialog_content = "接收，疑問分析中……",
  ui_story_1011_10110702_58_dialog_content = "答案形成：這裡是<color=#FFB400>「回歸塔」</color>。",
  ui_story_1011_10110702_59_dialog_content = "（回歸塔？聽上去像是一種用於歸航指引的建築，就像燈塔一樣……）",
  ui_story_1011_10110702_60_dialog_content = "回歸……是什麼意思？臨空者號自動駕駛到這裡，也是為了回歸嗎？",
  ui_story_1011_10110702_61_dialog_content = "非常抱歉，輔腦不知道。",
  ui_story_1011_10110702_62_dialog_content = "（就......就這麼直接地說「不知道」？！）",
  ui_story_1011_10110702_63_dialog_content = "好……那第二個問題：這座塔原本的內部結構是什麼樣的？",
  ui_story_1011_10110702_64_dialog_content = "我們現在處於回歸塔的什麼位置？",
  ui_story_1011_10110702_65_dialog_content = "輔腦功能介紹播放中：輔腦是用於回歸塔內的服務類人工智能……",
  ui_story_1011_10110702_66_dialog_content = "輔腦會根據空裔的權限與指令，為空裔提供幫助。",
  ui_story_1011_10110702_67_dialog_content = "正在確認空裔持有權限……",
  ui_story_1011_10110702_68_dialog_content = "確認完畢，輔腦可以為你提供：回歸塔內部地圖。",
  ui_story_1011_10110702_69_dialog_content = "（幫大忙了！）",
  ui_story_1011_10110702_70_dialog_content = "太好了，接下來不用盲目地到處摸索了！",
  ui_story_1011_10110702_71_dialog_content = "我們快找到那個能修復臨空者號的地方吧。",
  ui_story_1011_10110702_72_dialog_content = "（啊，雖然沒對它抱太多希望，但還是問問它吧……）",
  ui_story_1011_10110702_73_dialog_content = "最後一個問題：請為我提供進入「中央控制系統」的方法。",
  ui_story_1011_10110702_74_dialog_content = "……",
  ui_story_1011_10110702_75_dialog_content = "非常抱歉，輔腦不知道。",
  ui_story_1011_10110702_76_dialog_content = "嗶——啵——嗶——啵——♪",
  ui_story_1011_10110702_77_dialog_content = "（哼歌算是怎麼回事啊！）",
  ui_story_1011_10110702_78_dialog_content = "算了，PlayerName，先這麼走吧，聊勝於無。",
  ui_story_1011_10110702_79_dialog_content = "既然已經有內部地圖了，你快用輔腦確認一下位置。",
  ui_story_1011_10110702_80_dialog_content = "說得對，我看一下......",
  ui_story_1011_10110702_81_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_1011_10110702_82_dialog_content = "原來如此，這座回歸塔的不同樓層各有不同的職能，我們現在仍在淺層區域。",
  ui_story_1011_10110702_83_dialog_content = "我們剛進來時所在的那一層是「巨像整備基地」。",
  ui_story_1011_10110702_84_dialog_content = "結果也如我們所見，它基本已經毀壞得沒剩下什麼了。",
  ui_story_1011_10110702_85_dialog_content = "現在這一層……和薇絲推測的一樣，是「空裔生活區」。",
  ui_story_1011_10110702_86_dialog_content = "也已經被我們探索完畢了。",
  ui_story_1011_10110702_87_dialog_content = "只可惜，這兩層都有很多被坍塌的牆體壓住的房間……",
  ui_story_1011_10110702_88_dialog_content = "「巨像零件車間」、「資源生產區」、「廢物處理區」……都被掩埋住了。",
  ui_story_1011_10110702_89_dialog_content = "臨空者號……",
  ui_story_1011_10110702_90_dialog_content = "臨空者號的事，你先不要急。你看，下面還有那麼多層還沒探索呢。",
  ui_story_1011_10110702_91_dialog_content = "雖然這樣說有點武斷，但我們越是往下走，獲得的資訊確實越多了。",
  ui_story_1011_10110702_92_dialog_content = "是啊，振作一點PlayerName，總會有辦法的！",
  ui_story_1011_10110702_93_dialog_content = "嗯，我們抓緊時間，前往下一層區域吧。",
  ui_story_1011_10110702_94_dialog_content = "下面的空間是......<color=#FFB400>「放逐區」</color>？",
  ui_story_1011_10110702_95_dialog_content = "放逐？！",
  ui_story_1011_10110702_96_dialog_content = "我不明白……空裔一向是愛好和平的種族，竟然會專門開闢這一類空間……",
  ui_story_1011_10110702_97_dialog_content = "……如果是用於放逐潛入這裡的遠古的暗鬼，倒也算正常。",
  ui_story_1011_10110702_98_dialog_content = "總之，無論如何都不會是什麼好地方，我們小心一點吧。",
  ui_story_1011_10110901_1_dialog_content = "<color=#e8d9bb>回歸塔，放逐區</color>",
  ui_story_1011_10110901_2_dialog_content = "吸......呼......",
  ui_story_1011_10110901_3_dialog_content = "（提前知道了這層空間的用途，反而覺得更緊張了……）",
  ui_story_1011_10110901_4_dialog_content = "（要是再跳出什麼暗鬼，我就立刻一箭射穿它！）",
  ui_story_1011_10110901_5_dialog_content = "嗶——啵——嗶——啵——♪",
  ui_story_1011_10110901_6_dialog_content = "滴滴滴滴，滴滴滴，滴滴滴，滴滴——♪",
  ui_story_1011_10110901_7_dialog_content = "「逝去的終將逝去~~留下的永遠留下~~♪」",
  ui_story_1011_10110901_8_dialog_content = "好吵。",
  ui_story_1011_10110901_9_dialog_content = "PlayerName，在這種隨時有暗鬼冒出來的環境，能不能讓它收斂一下。",
  ui_story_1011_10110901_10_dialog_content = "……我再試試和它進行精神感應。",
  ui_story_1011_10110901_11_dialog_content = "精神感應已開啟。",
  ui_story_1011_10110901_12_dialog_content = "輔腦在安全的空閒時刻，會隨機為空裔播放音樂。",
  ui_story_1011_10110901_13_dialog_content = "來自古代的樂章，空裔，喜歡嗎？",
  ui_story_1011_10110901_14_dialog_content = "我姑且當這些支離破碎的音效，也算是鋼琴和歌謠的聲音吧……",
  ui_story_1011_10110901_15_dialog_content = "任何空裔都有權限修改輔腦的隨機音樂列表……",
  ui_story_1011_10110901_16_dialog_content = "輔腦也可以學習空裔的喜好並進行自動修正。是否修改？",
  ui_story_1011_10110901_17_dialog_content = "……不必，就這樣吧。",
  ui_story_1011_10110901_18_dialog_content = "（畢竟是來自過去的迴響。）",
  ui_story_1011_10110901_19_dialog_content = "不過，既然有輔腦可以偵測當下空間的安全性……",
  ui_story_1011_10110901_20_dialog_content = "我們暫時可以放鬆警惕，不用這麼緊張兮兮。",
  ui_story_1011_10110901_21_dialog_content = "但是，這一層看上去還是讓人很不舒服。",
  ui_story_1011_10110901_22_dialog_content = "雖然幾乎沒有生命體活動的痕跡了……",
  ui_story_1011_10110901_23_dialog_content = "但是，你們看這些房間的門背後。",
  ui_story_1011_10110901_24_dialog_content = "竟、竟然都是抓痕……",
  ui_story_1011_10110901_25_dialog_content = "再看這些房間緊密連貫的排列配置，恐怕這裡……",
  ui_story_1011_10110901_26_dialog_content = "白夜城的監獄，也是這種光景。",
  ui_story_1011_10110901_27_dialog_content = "……",
  ui_story_1011_10110901_28_dialog_content = "可是，為什麼要費盡心思把暗鬼關起來，直接消滅不就好了嗎？",
  ui_story_1011_10110901_29_dialog_content = "難道說，古代的空裔也沒有戰鬥能力？",
  ui_story_1011_10110901_30_dialog_content = "不，就算沒有戰鬥能力，憑我們目前所見的空裔技術……",
  ui_story_1011_10110901_31_dialog_content = "他們也足以製造出武器，用來戰鬥和防禦。",
  ui_story_1011_10110901_32_dialog_content = "<color=#e8d9bb>叮當——</color>",
  ui_story_1011_10110901_33_dialog_content = "嗯？",
  ui_story_1011_10110901_34_dialog_content = "踢到了什麼東西？",
  ui_story_1011_10110901_35_dialog_content = "我看看……",
  ui_story_1011_10110901_36_dialog_content = "咦？！！",
  ui_story_1011_10110901_37_dialog_content = "是一個鐵質的名牌？！",
  ui_story_1011_10110901_38_dialog_content = "「姓名：特諾奇。身分：空裔」……",
  ui_story_1011_10110901_39_dialog_content = "「放......<color=#FFB400>放逐期限</color>：十四年」......",
  ui_story_1011_10110901_40_dialog_content = "還有這個，「姓名：蒂蘭。身分：空裔。放逐期：十二年」......",
  ui_story_1011_10110901_41_dialog_content = "這些小房間裡關押的，全部是你的同族，PlayerName。",
  ui_story_1011_10110901_42_dialog_content = "也就是說，「放逐區」的全名……是「空裔放逐區」？！",
  ui_story_1011_10110901_43_dialog_content = "可是為什麼......他們為什麼要監禁同族？",
  ui_story_1011_10110901_44_dialog_content = "「嚮往和平」難道也是假象嗎？！",
  ui_story_1011_10110901_45_dialog_content = "冷靜，PlayerName，在沒有定論之前先不要衝動。",
  ui_story_1011_10110901_46_dialog_content = "你想，如果古代的空裔是一個人口龐大的種族……",
  ui_story_1011_10110901_47_dialog_content = "那就必然需要啟用一些強制性的手段來維持秩序。",
  ui_story_1011_10110901_48_dialog_content = "就算像這樣，那麼空裔也可以通過意識互相鏈接而達到你所說的目的。",
  ui_story_1011_10110901_49_dialog_content = "何必囚禁同族，為他們施加這麼漫長的放逐期限？",
  ui_story_1011_10110901_50_dialog_content = "輔腦，請回答這個問題。",
  ui_story_1011_10110901_51_dialog_content = "接收，疑問分析中……關鍵詞抓取成功。答案形成——",
  ui_story_1011_10110901_52_dialog_content = "<color=#FFB400>弗朗茨老師</color>說過，「從那一刻起，我們和那些人就不是同族了」。",
  ui_story_1011_10110901_53_dialog_content = "？！",
  ui_story_1011_10110901_54_dialog_content = "「不是同族」是什麼意思？",
  ui_story_1011_10110901_55_dialog_content = "「那些人」指的又是什麼人？",
  ui_story_1011_10110901_56_dialog_content = "難道在數千年前，空裔族群之中存在著什麼<color=#FFB400>難以調和的矛盾</color>嗎？",
  ui_story_1011_10110901_57_dialog_content = "（這就是他們互相殘殺的根源嗎……）",
  ui_story_1011_10110901_57X1_dialog_content = "接收，疑問分析中……",
  ui_story_1011_10110901_57X2_dialog_content = "根據已有的大數據可知，大多數空裔和弗朗茨老師的關係並不融洽。",
  ui_story_1011_10110901_57X3_dialog_content = "他也確實曾經在「放逐區」受過押禁。",
  ui_story_1011_10110901_57X3X1_dialog_content = "順便一提，「放逐區」是用於關押空裔異端的區域。",
  ui_story_1011_10110901_57X3X2_dialog_content = "弗朗茨老師和他手下的研究人員們，全部因為同樣的原因被放逐在此。",
  ui_story_1011_10110901_57X3X3_dialog_content = "放逐的理由為：煽動思想，理念超前。",
  ui_story_1011_10110901_57X4_dialog_content = "和「弗朗茨」有關的聯想詞全部不堪入目......接下來即將為您播放聯想詞舉例：",
  ui_story_1011_10110901_57X5_dialog_content = "怪胎、瘋子、精神控制專家、腦葉收集者......",
  ui_story_1011_10110901_57X6_dialog_content = "呃，好了PlayerName，請讓它暫停吧......",
  ui_story_1011_10110901_57X7_dialog_content = "聽起來似乎是一個很......唔，有一點奇怪的研究人員？",
  ui_story_1011_10110901_57X8_dialog_content = "弗朗茨老師致力於研究各式新型技術。",
  ui_story_1011_10110901_57X9_dialog_content = "他總是說，「研究之路總是充滿坎坷，不被理解亦屬常規事件」。",
  ui_story_1011_10110901_57X10_dialog_content = "除此之外，弗朗茨老師還有一項最偉大的發明。",
  ui_story_1011_10110901_57X11_dialog_content = "空裔，根據你的同伴類型可以得知，這項發明確實改變了之後的世界。",
  ui_story_1011_10110901_57X12_dialog_content = "改變了......世界？",
  ui_story_1011_10110901_57X13_dialog_content = "跟過去相比，現在的空裔確實改變了立場與習慣。",
  ui_story_1011_10110901_57X14_dialog_content = "甚至能夠與光靈、亞人這些種族同仇敵愾。",
  ui_story_1011_10110901_57X15_dialog_content = "弗朗茨老師如果還在世，一定會感到欣慰。",
  ui_story_1011_10110901_57X16_dialog_content = "「立場與習慣」？那麼......遠古時代的空裔到底是什麼樣的勢力？",
  ui_story_1011_10110901_57X17_dialog_content = "那項「最偉大的發明」，又是什麼樣的東西？",
  ui_story_1011_10110901_58_dialog_content = "正在確認空裔持有權限……",
  ui_story_1011_10110901_59_dialog_content = "很抱歉，權限不足，輔腦無法提供答案。",
  ui_story_1011_10110901_60_dialog_content = "好吧，那我總可以問幾個簡單的問題吧？",
  ui_story_1011_10110901_61_dialog_content = "讓我們回到剛才的那句話。",
  ui_story_1011_10110901_61X1_dialog_content = "「從那一刻起，我們和那些人就不是同族了」。",
  ui_story_1011_10110901_63_dialog_content = "他所說的「我們」，也在指空裔嗎？",
  ui_story_1011_10110901_64_dialog_content = "答案形成：「我們」是空裔。",
  ui_story_1011_10110901_65_dialog_content = "……",
  ui_story_1011_10110901_66_dialog_content = "錯誤，錯誤！輔腦不是空裔。",
  ui_story_1011_10110901_67_dialog_content = "輔腦功能介紹播放中：輔腦是用於回歸塔內的服務類人工智能……",
  ui_story_1011_10110901_68_dialog_content = "……聽我提問啊！沒有人覺得你這個遠古機器是空裔啊！",
  ui_story_1011_10110901_69_dialog_content = "輔腦會根據空裔的權限與指令，為空裔提供幫助……",
  ui_story_1011_10110901_70_dialog_content = "算了，真是讓人受不了......",
  ui_story_1011_10110901_71_dialog_content = "弗朗茨？",
  ui_story_1011_10110901_72_dialog_content = "PlayerName，你還記不記得，我們在上一層看到的那個杯子。",
  ui_story_1011_10110901_73_dialog_content = "啊，這麼一說，杯子底部那塊很模糊的刻印，好像就是……",
  ui_story_1011_10110901_74_dialog_content = "弗朗茨的杯子……嗎？",
  ui_story_1011_10110901_75_dialog_content = "接收，疑問分析中......答案形成：弗朗茨老師喜歡飲用補給飲料。",
  ui_story_1011_10110901_76_dialog_content = "弗朗茨老師杯不離手。",
  ui_story_1011_10110901_77_dialog_content = "（竟然還真是……）",
  ui_story_1011_10110901_78_dialog_content = "補給飲料功能介紹播放中：補給飲料是回歸塔特別飲品，具有提神功效。",
  ui_story_1011_10110901_79_dialog_content = "（這種無關資訊就不用通知了啊！）",
  ui_story_1011_10110901_80_dialog_content = "大量供給於空裔生活區、資源生產區、放逐區……",
  ui_story_1011_10110901_81_dialog_content = "可以從以上區域的補給販售機處自行購買。",
  ui_story_1011_10110901_82_dialog_content = "（販售機？！）",
  ui_story_1011_10110901_83_dialog_content = "（那就一定沒錯了！）",
  ui_story_1011_10110901_84_dialog_content = "PlayerName，卡蓮，你們跟我過來！",
  ui_story_1011_10110901_85_dialog_content = "<color=#e8d9bb>回歸塔，放逐區，補給販售機旁</color>",
  ui_story_1011_10110901_86_dialog_content = "<color=#e8d9bb>砰——！梆——！</color>",
  ui_story_1011_10110901_87_dialog_content = "呼……真厲害啊，踢幾腳竟然還真的亮起來了！",
  ui_story_1011_10110901_88_dialog_content = "這就是輔腦說的販售機？",
  ui_story_1011_10110901_89_dialog_content = "這種東西......總感覺有點眼熟。",
  ui_story_1011_10110901_90_dialog_content = "確實，難道「人工智能」和「販賣機」的組合，是地下遺跡的標準配備嗎？",
  ui_story_1011_10110901_91_dialog_content = "哼哼～那你們看好啦。",
  ui_story_1011_10110901_92_dialog_content = "唔，就是這個！",
  ui_story_1011_10110901_93_dialog_content = "哎？！妳真的把它們帶出來了！",
  ui_story_1011_10110901_94_dialog_content = "畢竟想要找機會印證一下我的猜測嘛。",
  ui_story_1011_10110901_95_dialog_content = "看到它這個鸚鵡螺形狀的造型，以及裡面的液體的時候，我就在想……",
  ui_story_1011_10110901_96_dialog_content = "空裔另有杯子等用於飲水的容器，又沒有食用貝類生物的習慣。",
  ui_story_1011_10110901_97_dialog_content = "那麼遠古時代的空裔，到底會用這種東西做什麼呢？",
  ui_story_1011_10110901_98_dialog_content = "不過現在我基本可以肯定了，你們看——",
  ui_story_1011_10110901_99_dialog_content = "只要把鸚鵡螺裡面的液體，倒入販售機的這一個孔洞裡……",
  ui_story_1011_10110901_100_dialog_content = "<color=#e8d9bb>叮咚！ ……梆啷！</color>",
  ui_story_1011_10110901_101_dialog_content = "成功了！",
  ui_story_1011_10110901_102_dialog_content = "鏘鏘——補給飲料買好啦~雖然已經嚴重變質不能再喝了。",
  ui_story_1011_10110901_103_dialog_content = "這是怎麼猜到的？！",
  ui_story_1011_10110901_104_dialog_content = "從我看到這個鸚鵡螺的時候就開始想了。",
  ui_story_1011_10110901_105_dialog_content = "鸚鵡螺的線條其實是有特殊含義的。",
  ui_story_1011_10110901_106_dialog_content = "它是用數學語言來表示的「自然」。",
  ui_story_1011_10110901_107_dialog_content = "「自然」……我不太明白，這個線條和自然有什麼關係？",
  ui_story_1011_10110901_108_dialog_content = "自然不是我們身邊的花草樹木嗎？",
  ui_story_1011_10110901_109_dialog_content = "嗯，你說得沒錯，花草樹木都是自然。",
  ui_story_1011_10110901_110_dialog_content = "不過，它所描繪的是自然背後的道理。",
  ui_story_1011_10110901_111_dialog_content = "是用鸚鵡螺的這條曲線象徵著萬物生長的歷程。",
  ui_story_1011_10110901_112_dialog_content = "或許可以簡單地稱之為「連續」。",
  ui_story_1011_10110901_113_dialog_content = "「連續」？",
  ui_story_1011_10110901_114_dialog_content = "嗯。就像一顆種子，不會突然之間變成大樹。",
  ui_story_1011_10110901_115_dialog_content = "它每一分每一秒，每一個瞬間都在成長。",
  ui_story_1011_10110901_116_dialog_content = "「連續」指的就是這個成長變化的過程。",
  ui_story_1011_10110901_117_dialog_content = "喔，好像有一點明白了……嗎？",
  ui_story_1011_10110901_118_dialog_content = "那麼，既然古代空裔的數學理論基於「連續」……",
  ui_story_1011_10110901_119_dialog_content = "我當時就在想，他們生活中很多東西肯定與我們不同。",
  ui_story_1011_10110901_120_dialog_content = "最直接的不同之處就是——貨幣！",
  ui_story_1011_10110901_121_dialog_content = "哦！我們所使用的硬幣或紙幣並不是「連續」的，對嗎？",
  ui_story_1011_10110901_122_dialog_content = "沒錯，至於他們的貨幣，看看這個鸚鵡螺的內容你應該就明白了吧？",
  ui_story_1011_10110901_123_dialog_content = "……液體？",
  ui_story_1011_10110901_124_dialog_content = "原來如此，所以這個鸚鵡螺其實是古代空裔的錢包？",
  ui_story_1011_10110901_125_dialog_content = "接收，疑問分析中……答案形成：螺荷是承載價值的容器。",
  ui_story_1011_10110901_126_dialog_content = "回歸塔中可供交易的事物會以液體容量標明價值。",
  ui_story_1011_10110901_127_dialog_content = "空裔可以用螺荷中的液體完成交易。",
  ui_story_1011_10110901_128_dialog_content = "原來如此。雖然我個人不太理解這方面的東西……",
  ui_story_1011_10110901_129_dialog_content = "但聽起來確實是一套很漂亮的審美。",
  ui_story_1011_10110901_130_dialog_content = "崇尚「自然」的概念，尋求「連續」的律度……",
  ui_story_1011_10110901_131_dialog_content = "這確實也符合空裔這個族群給人的一貫印象。",
  ui_story_1011_10110901_132_dialog_content = "很厲害哇，薇絲！你和輔腦解釋得一模一樣！",
  ui_story_1011_10110901_133_dialog_content = "也、也沒有啦……",
  ui_story_1011_10110901_134_dialog_content = "我們快繼續往下走吧。",
  ui_story_1011_10110901_135_dialog_content = "可是，通向下一層的樓梯已經沒有了。",
  ui_story_1011_10110901_136_dialog_content = "放逐區是回歸塔的最底層嗎？",
  ui_story_1011_10110901_137_dialog_content = "不對啊，在輔腦給出的地圖裡，放逐區只是最中段。",
  ui_story_1011_10110901_138_dialog_content = "輔腦，請提供通向下一層的通道所在位置。",
  ui_story_1011_10110901_139_dialog_content = "接收，疑問分析中……答案形成：下一層通道已經坍塌。",
  ui_story_1011_10110901_140_dialog_content = "如果你仍舊想通向下一層……",
  ui_story_1011_10110901_141_dialog_content = "請沿著斜後方兩個補給販售機之間的裂隙前進。",
  ui_story_1011_10110901_142_dialog_content = "<color=#e8d9bb>回歸塔，裂隙通道中</color>",
  ui_story_1011_10110901_143_dialog_content = "唔，好黑，好擠，似乎比進來時的通道還要擠。",
  ui_story_1011_10110901_144_dialog_content = "我也只能勉強施放開手腳。",
  ui_story_1011_10110901_145_dialog_content = "（希望我們的闖入不要引發這裡的二次塌陷……）",
  ui_story_1011_10110901_146_dialog_content = "再走快一點吧，PlayerName。",
  ui_story_1011_10110901_147_dialog_content = "知......知道了......",
  ui_story_1011_10110901_148_dialog_content = "嘟——",
  ui_story_1011_10110901_149_dialog_content = "警告：前方五十米，偵測到生命體。",
  ui_story_1011_10110901_150_dialog_content = "警告：前方五十米，生命體正在靠近。",
  ui_story_1011_10110901_151_dialog_content = "什、什麼？！在這種單行道裡……",
  ui_story_1011_10110901_152_dialog_content = "難道這裡有原生的暗鬼嗎？！",
  ui_story_1011_10110901_153_dialog_content = "警告：前方四十米，生命體正在靠近。",
  ui_story_1011_10110901_154_dialog_content = "警告：前方三十米......",
  ui_story_1011_10110901_155_dialog_content = "PlayerName，想想辦法！",
  ui_story_1011_10110901_156_dialog_content = "警告：前方十米偵測到生命體，身分確認中……",
  ui_story_1011_10110901_157_dialog_content = "……我沒有獲得任何感應，至少它不是空裔。",
  ui_story_1011_10110901_158_dialog_content = "各位，準備好迎戰。",
  ui_story_1011_10110901_159_dialog_content = "身分確認：暗鬼。",
  ui_story_1011_10110901_160_dialog_content = "嘎……",
  ui_story_1011_10110901_161_dialog_content = "吼吼吼——！！！",
  ui_story_1011_10110901_162_dialog_content = "地形複雜，各位小心！",
  ui_story_1011_10110902_1_dialog_content = "吼......",
  ui_story_1011_10110902_2_dialog_content = "方才該多留意一下才是。",
  ui_story_1011_10110902_3_dialog_content = "腳下的廢墟全是戰鬥痕跡，我們早該提高警覺。",
  ui_story_1011_10110902_4_dialog_content = "畢竟這裡存在連通放逐區的密道，也難怪危機四伏。",
  ui_story_1011_10110902_5_dialog_content = "現在已經不能回頭了。",
  ui_story_1011_10110902_6_dialog_content = "（如果是<color=#FFB400>戰鬥痕跡</color>的話......）",
  ui_story_1011_10110902_7_dialog_content = "輔腦，請幫我掃描地上這些遺跡……並匯報完整資訊。",
  ui_story_1011_10110902_8_dialog_content = "接收，輔腦掃描功能啟動中……",
  ui_story_1011_10110902_9_dialog_content = "正在調取數據庫進行資料比對……",
  ui_story_1011_10110902_10_dialog_content = "掃描完畢。",
  ui_story_1011_10110902_11_dialog_content = "結果是什麼？",
  ui_story_1011_10110902_12_dialog_content = "正在生成掃描報告：輔腦初步確認此處為空裔與暗鬼的戰鬥遺留痕跡。",
  ui_story_1011_10110902_13_dialog_content = "經分析，此處地質成分中包含約200具低級暗鬼的屍體，與40具空裔的……",
  ui_story_1011_10110902_14_dialog_content = "唔……",
  ui_story_1011_10110902_15_dialog_content = "在前方大約十公尺的位置，現存16張空裔的名牌，與2把空裔使用的<color=#FFB400>武器</color>。",
  ui_story_1011_10110902_16_dialog_content = "武器？！",
  ui_story_1011_10110902_17_dialog_content = "輔腦說的沒錯，你們快來看。",
  ui_story_1011_10110902_18_dialog_content = "這裡的落石旁邊還剩兩把槍，乍看都是完好的。",
  ui_story_1011_10110902_19_dialog_content = "正在生成掃描子報告……",
  ui_story_1011_10110902_20_dialog_content = "掃描結果更正：其中一把槍枝能量裝填缺失，現僅存1把空裔使用的武器。",
  ui_story_1011_10110902_21_dialog_content = "喏，就是這一把。",
  ui_story_1011_10110902_22_dialog_content = "槍身意外地小巧。",
  ui_story_1011_10110902_23_dialog_content = "也就是說，這把槍裝填的，呃……能量，是完好的嗎？",
  ui_story_1011_10110902_24_dialog_content = "接收，疑問分析中……即將播放有關雷射槍的簡單介紹……",
  ui_story_1011_10110902_25_dialog_content = "武器名稱：雷射槍。發明者：弗朗茨老師。",
  ui_story_1011_10110902_26_dialog_content = "使用效果：<color=#FFB400>暗鬼特攻</color>。使用範圍：空裔通用。",
  ui_story_1011_10110902_27_dialog_content = "使用方法：使用感應力，與雷射槍建立精神連結，即可高效擊退小型暗鬼。",
  ui_story_1011_10110902_28_dialog_content = "（未免太強了！簡直和一個槍支形態的智能機器沒兩樣！）",
  ui_story_1011_10110902_29_dialog_content = "咦？",
  ui_story_1011_10110902_30_dialog_content = "槍柄上好像還有凹凸不平的刻痕。",
  ui_story_1011_10110902_31_dialog_content = "掃描結果補充：該武器的所有者即是弗朗茨老師。",
  ui_story_1011_10110902_32_dialog_content = "又、又是這個名號？！",
  ui_story_1011_10110902_33_dialog_content = "（雖然只了解到些許的瑣碎資訊，但這弗朗茨老師肯定是個很厲害的人。）",
  ui_story_1011_10110902_34_dialog_content = "警告：後方五十米，生命體正在靠近。",
  ui_story_1011_10110902_35_dialog_content = "哦？來得正好。",
  ui_story_1011_10110902_36_dialog_content = "放心地去試一下吧，PlayerName，我和卡蓮可以殿後。",
  ui_story_1011_10110902_37_dialog_content = "好！",
  ui_story_1011_10110902_38_dialog_content = "（咚咚......咚咚......）",
  ui_story_1011_10110902_39_dialog_content = "（雖然指揮過無數場戰鬥了，但自己打頭陣還是難免緊張。）",
  ui_story_1011_10110902_40_dialog_content = "嘎嗚……",
  ui_story_1011_10110902_41_dialog_content = "嘎！！！",
  ui_story_1011_10110902_42_dialog_content = "（就是現在！）",
  ui_story_1011_10110902_43_dialog_content = "<color=#e8d9bb>砰——砰！</color>",
  ui_story_1011_10110902_44_dialog_content = "嘎……",
  ui_story_1011_10110902_45_dialog_content = "成......成功了！",
  ui_story_1011_10110902_46_dialog_content = "雖然不是致命傷，但完全被擊暈了。",
  ui_story_1011_10110902_47_dialog_content = "一擊即倒，竟然這麼管用！",
  ui_story_1011_10110902_48_dialog_content = "PlayerName手都沒有發抖，已經很值得鼓勵了唷～",
  ui_story_1011_10110902_49_dialog_content = "那、那還真是多謝誇獎！",
  ui_story_1011_10110902_50_dialog_content = "總之有這支雷射槍，我們的戰鬥力也變強了。",
  ui_story_1011_10110902_51_dialog_content = "我們接著往下走吧。",
  ui_story_1011_10111001_1_dialog_content = "嘎！！！",
  ui_story_1011_10111001_2_dialog_content = "吼！ ！ ！",
  ui_story_1011_10111001_3_dialog_content = "嗷！！！",
  ui_story_1011_10111001_4_dialog_content = "<color=#e8d9bb>砰——砰——砰！</color>",
  ui_story_1011_10111001_5_dialog_content = "越來越適應戰鬥了呢……PlayerName。",
  ui_story_1011_10111001_6_dialog_content = "就算持有如此強勁的武器，但這數量實在是太驚人了……",
  ui_story_1011_10111001_7_dialog_content = "這些暗鬼到底是怎麼來到這種地方？",
  ui_story_1011_10111001_8_dialog_content = "（難道牠們真的是這裡的原生暗鬼嗎......）",
  ui_story_1011_10111001_9_dialog_content = "而且，好奇怪，看起來牠們都在趕往同一個地方……",
  ui_story_1011_10111001_10_dialog_content = "既然暗鬼沒有自主意識，難道是在回應某種召喚？",
  ui_story_1011_10111001_11_dialog_content = "（召喚？）",
  ui_story_1011_10111001_12_dialog_content = "（難道是日蝕在搞小動作？還是說……）",
  ui_story_1011_10111001_13_dialog_content = "<color=#e8d9bb>轟隆隆……轟隆隆……</color>",
  ui_story_1011_10111001_14_dialog_content = "糟了……",
  ui_story_1011_10111001_15_dialog_content = "有東西正在朝我們快速靠近！",
  ui_story_1011_10111001_16_dialog_content = "牠們之間果然存在著一個首領！",
  ui_story_1011_10111001_17_dialog_content = "警告！前方三……警告！前方二十……警告！前方十米偵測到生命體！",
  ui_story_1011_10111001_18_dialog_content = "<color=#e8d9bb>轟隆隆隆——</color>",
  ui_story_1011_10111001_19_dialog_content = "吼——！ ！ ！",
  ui_story_1011_10111001_20_dialog_content = "吼......",
  ui_story_1011_10111001_21_dialog_content = "這不是剛才那隻暗鬼嗎？！",
  ui_story_1011_10111001_22_dialog_content = "怎麼如此頑強......牠沒有被我們消滅掉嗎？！",
  ui_story_1011_10111001_23_dialog_content = "薇絲、卡蓮！你們都退後！",
  ui_story_1011_10111001_24_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_1011_10111001_25_dialog_content = "呼，呼......",
  ui_story_1011_10111001_26_dialog_content = "好險，還好有這把槍……",
  ui_story_1011_10111001_27_dialog_content = "嘎……",
  ui_story_1011_10111001_28_dialog_content = "吼！ ！ ！",
  ui_story_1011_10111001_29_dialog_content = "什麼？！",
  ui_story_1011_10111001_30_dialog_content = "對牠不起作用嗎？！",
  ui_story_1011_10111001_31_dialog_content = "吼！！！！！！",
  ui_story_1011_10111001_32_dialog_content = "PlayerName，別發呆，快跑！",
  ui_story_1011_10111001_33_dialog_content = "向、向前跑嗎？可是我們還不知道前面……",
  ui_story_1011_10111001_34_dialog_content = "現在管不了前面有什麼啦！",
  ui_story_1011_10111001_35_dialog_content = "輔腦！請立刻開啟警報！",
  ui_story_1011_10111001_36_dialog_content = "收到。預警系統已長效開啟。警告！後方五米偵測到生命體！",
  ui_story_1011_10111001_37_dialog_content = "警告！後方十米偵測到生命體！",
  ui_story_1011_10111001_38_dialog_content = "警告！後方十五米偵測到生命體，生命體不斷靠近中……",
  ui_story_1011_10111001_39_dialog_content = "警告！後方十米偵測到生命體，生命體不斷靠近中……",
  ui_story_1011_10111001_40_dialog_content = "呼......呼......根本沒辦法跟牠拉開距離啊！",
  ui_story_1011_10111001_41_dialog_content = "PlayerName，快跟上！",
  ui_story_1011_10111001_42_dialog_content = "是、是！",
  ui_story_1011_10111001_43_dialog_content = "警告！後方三十米偵測到生命體，生命體不斷靠近中……",
  ui_story_1011_10111001_44_dialog_content = "別停下來！",
  ui_story_1011_10111001_45_dialog_content = "<color=#e8d9bb>咚——！</color>",
  ui_story_1011_10111001_46_dialog_content = "哎唷！痛……",
  ui_story_1011_10111001_47_dialog_content = "咦，這裡怎麼會有東西？",
  ui_story_1011_10111001_48_dialog_content = "哎......？",
  ui_story_1011_10111001_49_dialog_content = "薇絲？怎麼回事！",
  ui_story_1011_10111001_50_dialog_content = "撞歪我了，這麼窄的密道怎麼會放一台儀器？！",
  ui_story_1011_10111001_51_dialog_content = "雖然看起來很像一座操作台，和輔腦的外形樣式也很相似……",
  ui_story_1011_10111001_52_dialog_content = "無論如何也不應該擋在路中間吧！",
  ui_story_1011_10111001_53_dialog_content = "……這麼一想，或許可以用它一用？！",
  ui_story_1011_10111001_54_dialog_content = "警告！後方二十五米偵測到生命體……",
  ui_story_1011_10111001_55_dialog_content = "輔腦，請快點說明這個儀器的用法！",
  ui_story_1011_10111001_56_dialog_content = "輔腦預警系統已長效開啟，暫時無法切換指令。",
  ui_story_1011_10111001_57_dialog_content = "警告！後方十米偵測到生命體……",
  ui_story_1011_10111001_58_dialog_content = "啊，真是的，看起來跟啟光的武器操作台沒兩樣！",
  ui_story_1011_10111001_59_dialog_content = "試一下也好過坐以待斃！",
  ui_story_1011_10111001_60_dialog_content = "至於身分認證，PlayerName，拜託了！",
  ui_story_1011_10111001_61_dialog_content = "那......那就交給妳了！",
  ui_story_1011_10111001_62_option_content = "強制感應！",
  ui_story_1011_10111001_63_dialog_content = "好——那麼首先，拉下鎖定閘門，啟動儀器……",
  ui_story_1011_10111001_64_dialog_content = "然後……",
  ui_story_1011_10111001_65_dialog_content = "就先讓暗鬼嚐嚐這個吧！",
  ui_story_1011_10111001_66_dialog_content = "<color=#e8d9bb>咻——啪！</color>",
  ui_story_1011_10111001_67_dialog_content = "（這個效果是……只針對暗鬼的瞄準攻擊？）",
  ui_story_1011_10111001_68_dialog_content = "吼！ ！ ！",
  ui_story_1011_10111001_69_dialog_content = "嘎……",
  ui_story_1011_10111001_70_dialog_content = "（好強大的威力！）",
  ui_story_1011_10111001_71_dialog_content = "竟然……！PlayerName，它對付暗鬼的效果跟你那把槍很像！",
  ui_story_1011_10111001_72_dialog_content = "不，甚至比槍更好用！",
  ui_story_1011_10111001_73_dialog_content = "吼！",
  ui_story_1011_10111001_74_dialog_content = "吼！ ！",
  ui_story_1011_10111001_75_dialog_content = "吼！ ！ ！",
  ui_story_1011_10111001_76_dialog_content = "（牠的死驚動了這麼多暗鬼？！）",
  ui_story_1011_10111001_77_dialog_content = "薇絲，小心！",
  ui_story_1011_10111001_78_dialog_content = "散開！冰花！",
  ui_story_1011_10111001_79_dialog_content = "......唔！",
  ui_story_1011_10111001_80_dialog_content = "薇絲，撐不住就盡快回來！",
  ui_story_1011_10111001_81_dialog_content = "（明明已經走到這裡，明明眼前有這種強效的武器……）",
  ui_story_1011_10111001_82_dialog_content = "（冷靜，一定還有解決方法。）",
  ui_story_1011_10111001_83_dialog_content = "（就是這個！<color=#FFB400>「全範圍殺傷指令」</color>！ ）",
  ui_story_1011_10111001_84_dialog_content = "<color=#e8d9bb>滴滴滴滴滴——砰！！！</color>",
  ui_story_1011_10111001_85_dialog_content = "<color=#e8d9bb>砰！！！咚！！！</color>",
  ui_story_1011_10111001_86_dialog_content = "呼......呼......薇絲？",
  ui_story_1011_10111001_87_dialog_content = "薇絲——！",
  ui_story_1011_10111001_88_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_1011_10111001_89_dialog_content = "薇......薇絲！！！",
  ui_story_1011_10111001_90_dialog_content = "（不可能……我們意識之間的感應還在，薇絲不可能出事！）",
  ui_story_1011_10111001_91_dialog_content = "薇絲！！！",
  ui_story_1011_10111001_92_dialog_content = "咳咳咳咳......在這裡！PlayerName，卡蓮！",
  ui_story_1011_10111001_93_dialog_content = "太好了！",
  ui_story_1011_10111001_94_dialog_content = "薇絲！嚇我一跳，我還以為妳......",
  ui_story_1011_10111001_95_dialog_content = "<color=#e8d9bb>滴滴滴滴滴——</color>",
  ui_story_1011_10111001_96_dialog_content = "咦？",
  ui_story_1011_10111001_97_dialog_content = "<color=#e8d9bb>——砰！！！</color>",
  ui_story_1011_10111001_98_dialog_content = "什……",
  ui_story_1011_10111001_99_dialog_content = "<color=#e8d9bb>滴、滴、滴、滴......</color>",
  ui_story_1011_10111001_100_dialog_content = "未發現剩餘對象，「全範圍殺傷指令」已完成。",
  ui_story_1011_10111001_101_dialog_content = "為，為什麼......",
  ui_story_1011_10111001_102_dialog_content = "怎麼會……",
  ui_story_1011_10111001_103_dialog_content = "<size=50>薇絲！！！！！！！！！</size>",
  ui_story_1011_10111001_104_dialog_content = "薇絲……薇絲！",
  ui_story_1011_10111001_105_dialog_content = "（糟糕！）",
  ui_story_1011_10111001_106_dialog_content = "卡蓮！先不要過去！",
  ui_story_1011_10111001_107_dialog_content = "儀器有問題！不要讓儀器發現妳！",
  ui_story_1011_10111001_108_option_content = "切斷感應！",
  ui_story_1011_10111001_109_option_content = "切斷感應……？",
  ui_story_1011_10111001_110_dialog_content = "（糟了！儀器沒有反應！）",
  ui_story_1011_10111001_111_dialog_content = "卡蓮，藏好！",
  ui_story_1011_10111001_112_dialog_content = "明白了！",
  ui_story_1011_10111001_113_dialog_content = "<color=#e8d9bb>滴、滴......滴滴滴滴滴——</color>",
  ui_story_1011_10111001_114_dialog_content = "唔？",
  ui_story_1011_10111001_115_dialog_content = "（還是被它偵測到了嗎？！）",
  ui_story_1011_10111001_116_dialog_content = "（希望我的月之繭能擋住它……）",
  ui_story_1011_10111001_117_dialog_content = "吼！ ！ ！",
  ui_story_1011_10111001_118_dialog_content = "<color=#e8d9bb>——砰！！！</color>",
  ui_story_1011_10111001_119_dialog_content = "（怎麼還有暗鬼圍過來！）",
  ui_story_1011_10111001_120_option_content = "切斷感應！",
  ui_story_1011_10111001_121_dialog_content = "<color=#e8d9bb>吱嘎——</color>",
  ui_story_1011_10111001_122_dialog_content = "（總算切斷它的運作機制！）",
  ui_story_1011_10111001_123_dialog_content = "PlayerName，先對付這些暗鬼，別讓牠們靠近薇絲！",
  ui_story_1011_10111001_124_dialog_content = "我們還不知道薇絲的具體情況，沒辦法多耽誤！",
  ui_story_1011_10111002_1_dialog_content = "生命體狀態掃描中……",
  ui_story_1011_10111002_2_dialog_content = "掃描結果生成......",
  ui_story_1011_10111002_3_dialog_content = "生命體狀態描述：暫時無法偵測到心跳、呼吸等生命跡象。",
  ui_story_1011_10111002_4_dialog_content = "生命體狀態報告：<color=#FFB400>「識泯」</color>狀態確認。",
  ui_story_1011_10111002_5_dialog_content = "「識泯」？",
  ui_story_1011_10111002_6_dialog_content = "PlayerName，睜開眼睛面對現實吧。",
  ui_story_1011_10111002_7_dialog_content = "我們要趕緊救薇絲脫離現在的狀態。",
  ui_story_1011_10111002_8_dialog_content = "我......我知道了......",
  ui_story_1011_10111002_9_dialog_content = "畢竟……還是需要我來和輔腦進行溝通。",
  ui_story_1011_10111002_17_option_content = "「識泯」？",
  ui_story_1011_10111002_18_dialog_content = "被特攻儀器擊中的生命體，會直接進入「識泯」狀態。",
  ui_story_1011_10111002_19_dialog_content = "進入「識泯」狀態的光靈，將持續陷入特殊昏迷。",
  ui_story_1011_10111002_20_dialog_content = "昏迷？",
  ui_story_1011_10111002_21_dialog_content = "也就是說，只要讓薇絲清醒過來就好了！",
  ui_story_1011_10111002_22_dialog_content = "……請為我更詳細地介紹「識泯」狀態，以及解決方式。",
  ui_story_1011_10111002_23_dialog_content = "接收，疑問分析中……",
  ui_story_1011_10111002_24_dialog_content = "答案形成：「識泯」不同於一般的昏迷狀態。",
  ui_story_1011_10111002_25_dialog_content = "進入「識泯」的光靈，其心跳和呼吸將維持無限停止狀態。",
  ui_story_1011_10111002_26_dialog_content = "其體內光子能量同樣會進入無限的休眠期。",
  ui_story_1011_10111002_27_dialog_content = "正在搜尋「識泯」狀態的解除方法……",
  ui_story_1011_10111002_28_dialog_content = "很抱歉，搜尋失敗，輔腦不知道。",
  ui_story_1011_10111002_29_dialog_content = "搜尋失敗是什麼意思？！",
  ui_story_1011_10111002_30_dialog_content = "輔腦無法為你提供解決方式。",
  ui_story_1011_10111002_31_dialog_content = "什、什麼？！",
  ui_story_1011_10111002_32_dialog_content = "那這種狀態，不就......不就和......",
  ui_story_1011_10111002_33_dialog_content = "（不就和<color=#FFB400>死亡</color>一樣嗎？！！！）",
  ui_story_1011_10111002_34_dialog_content = "空裔怎麼會研究出這種東西？",
  ui_story_1011_10111002_36_dialog_content = "不會的，不會這樣的......",
  ui_story_1011_10111002_37_dialog_content = "一定還有辦法能救薇絲……",
  ui_story_1011_10111002_38_dialog_content = "只......只要我們還留在遺跡裡尋找，就......就一定......",
  ui_story_1011_10111002_39_dialog_content = "可是……",
  ui_story_1011_10111002_40_dialog_content = "我如果率先解決掉所有暗鬼......",
  ui_story_1011_10111002_41_dialog_content = "你如果能夠斷開與薇絲的連接，阻止她的操作......",
  ui_story_1011_10111002_41X1_dialog_content = "薇絲就不會變成現在這副樣子！！！",
  ui_story_1011_10111002_41X2_dialog_content = "我們，本來是有機會的。",
  ui_story_1011_10111002_42_dialog_content = "卡蓮……",
  ui_story_1011_10111002_43_dialog_content = "……",
  ui_story_1011_10111002_44_dialog_content = "對不起，是我失態了。",
  ui_story_1011_10111002_45_dialog_content = "（這麼一想，那個儀器為何會誤傷薇絲呢？）",
  ui_story_1011_10111002_46_dialog_content = "（難道是薇絲的誤操作……不可能，若有錯誤操作，我會感應到。）",
  ui_story_1011_10111002_47_dialog_content = "<color=#e8d9bb>滴、滴、滴、滴......</color>",
  ui_story_1011_10111002_48_dialog_content = "未發現剩餘對象，「全範圍殺傷指令」已完成。",
  ui_story_1011_10111002_49_dialog_content = "當時那條「全範圍殺傷指令」，是薇絲下達給特攻儀器的命令。",
  ui_story_1011_10111002_50_dialog_content = "輔腦，儀器為什麼會誤傷薇絲？",
  ui_story_1011_10111002_51_dialog_content = "接收，疑問分析中……答案形成——",
  ui_story_1011_10111002_52_dialog_content = "特攻儀器正確執行了指令，特攻儀器沒有誤傷生命體。",
  ui_story_1011_10111002_53_dialog_content = "什麼？！",
  ui_story_1011_10111002_54_dialog_content = "薇絲已經躺在地上……別再胡說八道了！",
  ui_story_1011_10111002_55_dialog_content = "輔腦的答案是正確的。重複：特攻儀器正確執行了指令，特攻儀器沒有……",
  ui_story_1011_10111002_56_dialog_content = "空裔，請放下你的雷射槍，雷射槍的麻醉效果不會對輔腦造成任何傷害。",
  ui_story_1011_10111002_57_dialog_content = "重複：特攻儀器正確執行了指令，特攻儀器沒有誤傷生命體。",
  ui_story_1011_10111002_58_dialog_content = "……",
  ui_story_1011_10111002_59_dialog_content = "............",
  ui_story_1011_10111002_60_dialog_content = "PlayerName，冷靜下來，仔細問它，問到出現有用資訊為止。",
  ui_story_1011_10111002_61_dialog_content = "不要讓輔腦和你玩文字遊戲。",
  ui_story_1011_10111002_62_dialog_content = "薇絲還在等著我們。",
  ui_story_1011_10111002_63_dialog_content = "這麼說來，經歷剛才那一番，還有個很重要的問題沒問。",
  ui_story_1011_10111002_64_dialog_content = "輔腦，請說明這個特攻儀器的<color=#FFB400>用法</color>。",
  ui_story_1011_10111002_65_dialog_content = "接收，疑問分析中……答案形成——",
  ui_story_1011_10111002_66_dialog_content = "正在播放特攻儀器的使用方法……",
  ui_story_1011_10111002_67_dialog_content = "特攻儀器最初是空裔一族用於自衛的防衛裝置。",
  ui_story_1011_10111002_68_dialog_content = "不同的指令對於不同類型的敵人，均有不同程度的剋制效果。",
  ui_story_1011_10111002_69_dialog_content = "因其效果強勁，後來也被投入到戰鬥當中。播放完畢。",
  ui_story_1011_10111002_70_dialog_content = "這......這根本有說等於沒說啊！",
  ui_story_1011_10111002_71_dialog_content = "那我更沒有辦法理解了，當時它為什麼一併襲擊薇絲呢？",
  ui_story_1011_10111002_72_dialog_content = "PlayerName......",
  ui_story_1011_10111002_73_dialog_content = "PlayerName，我有了一種猜測。",
  ui_story_1011_10111002_74_dialog_content = "假設，輔腦所說的已是這個儀器的全部用途。",
  ui_story_1011_10111002_74X1_dialog_content = "作為空裔用於自衛的防衛裝置，它的「全範圍殺傷指令」，卻指向了薇絲這個光靈。",
  ui_story_1011_10111002_75_dialog_content = "那麼它對身為「非空裔」的光靈造成的「識泯」攻擊，很可能......",
  ui_story_1011_10111002_76_dialog_content = "很可能，對於遠古的空裔來說，就是一件十分<color=#FFB400>正常</color>的事。",
  ui_story_1011_10111002_77_dialog_content = "就像我小時候，在學習使用這把「月之繭」時……",
  ui_story_1011_10111002_78_dialog_content = "我的老師並不會特意說明，為什麼要讓這把槍對準暗鬼。",
  ui_story_1011_10111002_79_dialog_content = "因為，這本來就是一件無需解釋的事。",
  ui_story_1011_10111002_80_dialog_content = "？！",
  ui_story_1011_10111002_81_dialog_content = "雖然我很難理解或接受……",
  ui_story_1011_10111002_82_dialog_content = "但你說的不無道理，我也沒辦法否認這種可能性……",
  ui_story_1011_10111002_83_dialog_content = "難道，遠古時代的光靈，真的也被空裔歸納成<color=#FFB400>敵人</color>般的存在嗎？",
  ui_story_1011_10111101_1_dialog_content = "我搞不清楚了，我真的愈來愈搞不清楚。",
  ui_story_1011_10111101_2_dialog_content = "我們明明身在空谷。而且就在空谷中最顯眼、任何地方都能看到的那座白塔下方。",
  ui_story_1011_10111101_3_dialog_content = "但我卻無法理解眼前的事物。",
  ui_story_1011_10111101_4_dialog_content = "我不知道這是什麼鬼地方，不知道有過怎樣的人生活。",
  ui_story_1011_10111101_5_dialog_content = "不知道他們因何滅亡，留下這些殘骸被棄置於地底。",
  ui_story_1011_10111101_6_dialog_content = "也許我們剛才經歷的場面已足夠解答疑慮。",
  ui_story_1011_10111101_7_dialog_content = "與戰鬥痕跡一起留存下來的，只有暗鬼。",
  ui_story_1011_10111101_8_dialog_content = "……",
  ui_story_1011_10111101_9_dialog_content = "就像十七年前空谷所經歷的那樣嗎？",
  ui_story_1011_10111101_10_dialog_content = "這裡甚至更加靜寂無聲，連最後的哀嚎都沒有傳向外界。",
  ui_story_1011_10111101_11_dialog_content = "它默默無聞地死在了角落裡。",
  ui_story_1011_10111101_12_dialog_content = "說不定我們是百年、千年裡唯一踏足此地的外人。",
  ui_story_1011_10111101_13_dialog_content = "在千年的時間範圍內搜尋——",
  ui_story_1011_10111101_14_dialog_content = "沒有發現其他外來者。你的判斷是正確的。",
  ui_story_1011_10111101_15_dialog_content = "我沒有在問你啊。",
  ui_story_1011_10111101_16_dialog_content = "輔腦的任務是，解決空裔所有疑問。",
  ui_story_1011_10111101_17_dialog_content = "你要是能在關鍵問題上再中用一點就好了……",
  ui_story_1011_10111101_18_dialog_content = "怎麼治好薇絲，怎麼修復臨空者號你全都不知道。",
  ui_story_1011_10111101_19_dialog_content = "在決策樹的方法集合中搜尋——",
  ui_story_1011_10111101_20_dialog_content = "沒有發現「治好薇絲」或「修復臨空者號」的方法。",
  ui_story_1011_10111101_21_dialog_content = "你的判斷是正確的，輔腦全都不知道。",
  ui_story_1011_10111101_22_dialog_content = "連這種事情都要認可嗎？！",
  ui_story_1011_10111101_23_dialog_content = "非常抱歉。輔腦蒐集到了「不中用」的反饋，接下來會盡力調整。",
  ui_story_1011_10111101_24_dialog_content = "我沒有責怪你的意思……",
  ui_story_1011_10111101_25_dialog_content = "看這片廢墟的殘破光景，你的腦子壞掉也不奇怪。",
  ui_story_1011_10111101_26_dialog_content = "我們自己會去找那些問題的答案。",
  ui_story_1011_10111101_27_dialog_content = "我們走吧，卡蓮，往深處走。",
  ui_story_1011_10111101_28_dialog_content = "我們沒有其他的選擇了。",
  ui_story_1011_10111101_29_dialog_content = "嗯。我來背著薇絲。",
  ui_story_1011_10111101_30_dialog_content = "（我們會治好妳的傷。）",
  ui_story_1011_10111101_31_dialog_content = "（請一定要堅持住，一定。）",
  ui_story_1011_10111101_32_dialog_content = "<color=#e8d9bb>嗒......嗒......嗒......</color>",
  ui_story_1011_10111101_33_dialog_content = "這條路上竟然什麼都沒有。",
  ui_story_1011_10111101_34_dialog_content = "沒有暗鬼，也沒有散落的物體。",
  ui_story_1011_10111101_35_dialog_content = "進入地下以來，這是最「乾淨」的一塊地方吧。",
  ui_story_1011_10111101_36_dialog_content = "嗯。但是太乾淨反而讓我覺得有些奇怪。",
  ui_story_1011_10111101_37_dialog_content = "就好像之前所見的一切痕跡都沒波及到這裡。",
  ui_story_1011_10111101_38_dialog_content = "舊時的生活與戰爭都被隔絕在外。",
  ui_story_1011_10111101_39_dialog_content = "失去了人情味，對吧？",
  ui_story_1011_10111101_40_dialog_content = "嗯。",
  ui_story_1011_10111101_41_dialog_content = "黎明學院的老師曾經跟我說過：",
  ui_story_1011_10111101_42_dialog_content = "「人情是包裹在世界最表層的東西。」",
  ui_story_1011_10111101_43_dialog_content = "「越向深處挖掘，人情將一點點褪去。」",
  ui_story_1011_10111101_44_dialog_content = "不覺得跟我們的處境很像嗎？",
  ui_story_1011_10111101_45_dialog_content = "我們也在一步步向深處走去。",
  ui_story_1011_10111101_46_dialog_content = "老師應該沒想到這句話會讓你用在真正的「地下深處」吧。",
  ui_story_1011_10111101_47_dialog_content = "我比課堂上理解得更深了，老師該欣慰才是。",
  ui_story_1011_10111101_48_dialog_content = "偵測到空裔踏入限制區域，開始驗證身分。",
  ui_story_1011_10111101_49_dialog_content = "嗶——嗶——嗶——嗶——",
  ui_story_1011_10111101_50_dialog_content = "嗯？輔腦你突然吵什麼？",
  ui_story_1011_10111101_51_dialog_content = "嗶、嗶、嗶、嗶！",
  ui_story_1011_10111101_52_dialog_content = "驗證失敗。提示，請立刻折返。提示，請立刻折返。",
  ui_story_1011_10111101_53_dialog_content = "折返？別開玩笑了，讓我們回去跟暗鬼肉搏嗎？",
  ui_story_1011_10111101_54_dialog_content = "幹嘛突然這樣？總得告訴我原因吧！",
  ui_story_1011_10111101_55_dialog_content = "PlayerName，你看前面。",
  ui_story_1011_10111101_56_dialog_content = "哇……這是一扇……<color=#FFB400>石門</color>？",
  ui_story_1011_10111101_57_dialog_content = "看起來是的。",
  ui_story_1011_10111101_58_dialog_content = "未免太巨大了，不如說更像是一堵牆。",
  ui_story_1011_10111101_59_dialog_content = "需要多大的力量才能推開這扇門呢？",
  ui_story_1011_10111101_60_dialog_content = "恐怕最沉重的攻城錘也無法撼動它。",
  ui_story_1011_10111101_61_dialog_content = "我想現今世上還沒有哪方勢力有能力建成、驅動如此宏偉的石門。",
  ui_story_1011_10111101_62_dialog_content = "我也這麼認為。",
  ui_story_1011_10111101_63_dialog_content = "擁有這樣神乎奇技的技術，最終也難逃毀滅嗎？",
  ui_story_1011_10111101_64_dialog_content = "提示，請立刻折返。提示，請立刻折返。",
  ui_story_1011_10111101_65_dialog_content = "你的身分沒有得到許可，禁止踏入<color=#FFB400>「核心中樞區」</color>。",
  ui_story_1011_10111101_66_dialog_content = "身分許可？",
  ui_story_1011_10111101_67_dialog_content = "大門會為得到許可的人開啟。",
  ui_story_1011_10111101_68_dialog_content = "其他未經許可的人，將被<color=#FFB400>「命令」</color>拒絕。",
  ui_story_1011_10111101_69_dialog_content = "真想見識一下這扇石門開啟的樣子，一定很壯觀吧。",
  ui_story_1011_10111101_70_dialog_content = "我也這麼想。輔腦，幫幫我們。",
  ui_story_1011_10111101_71_dialog_content = "你說的那個身分許可該如何取得？",
  ui_story_1011_10111101_72_dialog_content = "對不起，「輔腦」無法幫助你們。",
  ui_story_1011_10111101_73_dialog_content = "誒？剛才不是還揚言要「解決空裔所有疑問」嗎？",
  ui_story_1011_10111101_74_dialog_content = "因為拒絕你的是「命令」，是最初與最高的指示。",
  ui_story_1011_10111101_75_dialog_content = "空裔不能違抗「命令」，輔腦也不能違抗「命令」。",
  ui_story_1011_10111101_76_dialog_content = "「命令」啊......",
  ui_story_1011_10111101_77_dialog_content = "為了向不適格者展現拒絕就用山一般高的岩石砌成門扉。",
  ui_story_1011_10111101_78_dialog_content = "它口中的「命令」姿態擺得真高啊。",
  ui_story_1011_10111101_79_dialog_content = "是啊，這扇石門真的很適合用來拒人於門外。",
  ui_story_1011_10111101_80_dialog_content = "只不過……",
  ui_story_1011_10111101_81_dialog_content = "那是這裡仍舊輝煌的時候。",
  ui_story_1011_10111101_82_dialog_content = "現在它留下的僅剩威嚴了。",
  ui_story_1011_10111101_83_dialog_content = "嗯，那些侵蝕裂開的縫隙足夠讓任何人通過。",
  ui_story_1011_10111101_84_dialog_content = "這頭獅子的牙齒已掉光，但並不願意做一隻貓。",
  ui_story_1011_10111101_85_dialog_content = "拖著這樣的身軀在外來者面前宣稱拒絕，令人難免心酸啊。",
  ui_story_1011_10111101_86_dialog_content = "提示，請立刻折返。提示，請立刻折返。",
  ui_story_1011_10111101_87_dialog_content = "走吧，我們進去看看。",
  ui_story_1011_10111101_88_dialog_content = "看看石門背後到底隱藏了什麼祕密。",
  ui_story_1011_10111101_89_dialog_content = "嗯。還有很多東西等著我們去尋找，我們沒有其他選擇。",
  ui_story_1011_10111101_90_dialog_content = "你的身分沒有得到許可，禁止踏入核心區域。",
  ui_story_1011_10111101_91_dialog_content = "輔腦，算了吧。",
  ui_story_1011_10111101_92_dialog_content = "「命令」拒絕你通過大門。",
  ui_story_1011_10111101_93_dialog_content = "空裔不能違抗「命令」……",
  ui_story_1011_10111101_94_dialog_content = "（親身在黑暗的縫隙中摸索才認識到，石門比看上去更厚。）",
  ui_story_1011_10111101_95_dialog_content = "（輔腦的聲音越來越遙遠，不知道是被巨石阻隔還是它甘願停了下來。）",
  ui_story_1011_10111101_96_dialog_content = "（我把所有精力放在想像上，想像我會在石門背後看到什麼。）",
  ui_story_1011_10111101_97_dialog_content = "（我知道無論我如何想像，親眼看到的時候還是會受到震撼。）",
  ui_story_1011_10111101_98_dialog_content = "（我知道我即將看到的東西意味著什麼。）",
  ui_story_1011_10111101_99_dialog_content = "（我看到的是一個文明。）",
  ui_story_1011_10111101_100_dialog_content = "這是什麼東西？",
  ui_story_1011_10111101_101_dialog_content = "它竟然還在運作……",
  ui_story_1011_10111101_102_dialog_content = "輔腦，你還在嗎？",
  ui_story_1011_10111101_103_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_1011_10111101_104_dialog_content = "這是它禁止我們進入的地方，它不再回應我們實屬正常。",
  ui_story_1011_10111101_105_dialog_content = "這個裝置的作用要靠我們自己來猜了。",
  ui_story_1011_10111101_106_dialog_content = "一些漂浮在空中的環形石板。",
  ui_story_1011_10111101_107_dialog_content = "這樣的東西能有何用？完全想像不到。",
  ui_story_1011_10111101_108_dialog_content = "你見過類似的東西嗎？",
  ui_story_1011_10111101_109_dialog_content = "沒有。",
  ui_story_1011_10111101_110_dialog_content = "別說現在的建築了，遠古遺跡裡也沒挖掘過類似的東西。",
  ui_story_1011_10111101_111_dialog_content = "不過也不奇怪。這裡跟其他遺跡本來就不一樣，這是屬於你們空裔的。",
  ui_story_1011_10111101_112_dialog_content = "也許它有某種只屬於空裔的用法。",
  ui_story_1011_10111101_113_dialog_content = "只屬於空裔的用法？",
  ui_story_1011_10111101_114_dialog_content = "你們眼中的世界跟光靈並不一樣。",
  ui_story_1011_10111101_115_dialog_content = "如果只為了服務空裔，它的功用也許藏在尋常方式看不到之處。",
  ui_story_1011_10111101_116_dialog_content = "妳的意思是跟感應有關？",
  ui_story_1011_10111101_117_dialog_content = "不外乎一種猜想，你試試呢。",
  ui_story_1011_10111101_118_dialog_content = "嗯，好。",
  ui_story_1011_10111101_119_option_content = "強制感應！",
  ui_story_1011_10111101_120_dialog_content = "<color=#e8d9bb>嗡——！</color>",
  ui_story_1011_10111101_121_dialog_content = "誒？這是……",
  ui_story_1011_10111101_122_dialog_content = "歡迎你，新生兒。",
  ui_story_1011_10111101_123_dialog_content = "這是你第一次觸碰<color=#FFB400>環狀系統</color>。",
  ui_story_1011_10111101_124_dialog_content = "環狀系統？是指剛才那個裝置嗎？",
  ui_story_1011_10111101_125_dialog_content = "我現在在哪？說話的又是誰？",
  ui_story_1011_10111101_126_dialog_content = "環狀系統是空裔整個族群的記憶。",
  ui_story_1011_10111101_127_dialog_content = "你將從這裡開始認識世界。",
  ui_story_1011_10111101_128_dialog_content = "等一下，好像根本沒有人在說話。",
  ui_story_1011_10111101_129_dialog_content = "這些訊息跨越聲音和語言的形成步驟，直接流入我的腦袋裡。",
  ui_story_1011_10111101_130_dialog_content = "首先來認識你身處的地方。",
  ui_story_1011_10111101_131_dialog_content = "空裔族群誕生於此，每一位空裔也都誕生於此。",
  ui_story_1011_10111101_132_dialog_content = "無論去往何方，此地永遠是空裔的家鄉。",
  ui_story_1011_10111101_133_dialog_content = "此地名為<color=#FFB400>「高塔之城」</color>。",
  ui_story_1011_10111101_134_dialog_content = "「高塔之城」......",
  ui_story_1011_10111101_135_dialog_content = "空裔的家鄉不是空谷嗎？",
  ui_story_1011_10111101_136_dialog_content = "無數高塔形成了這座城市。",
  ui_story_1011_10111101_137_dialog_content = "你所在的正是城市中心，最初與最高的一座——",
  ui_story_1011_10111101_138_dialog_content = "「回歸塔」。",
  ui_story_1011_10111101_139_dialog_content = "每一位空裔都在這裡接受培育，直到成年。",
  ui_story_1011_10111101_140_dialog_content = "此後你們有機會碰觸外界世界，去到每一個遙遠的角落。",
  ui_story_1011_10111101_141_dialog_content = "但故鄉……永遠佇立……高塔之城……",
  ui_story_1011_10111101_142_dialog_content = "在終點……等待……回歸……",
  ui_story_1011_10111101_143_dialog_content = "！！！",
  ui_story_1011_10111101_144_dialog_content = "結……結束了？",
  ui_story_1011_10111101_145_dialog_content = "怎麼樣，你看到什麼？",
  ui_story_1011_10111101_146_dialog_content = "我聽到一個聲音。不對，不是聲音，是一段訊息。",
  ui_story_1011_10111101_147_dialog_content = "訊息？",
  ui_story_1011_10111101_148_dialog_content = "嗯。從意識觸碰到面前這個裝置開始，那些訊息直接湧入我的腦海。",
  ui_story_1011_10111101_149_dialog_content = "它有點像……像在教育我。",
  ui_story_1011_10111101_150_dialog_content = "它告訴我這個裝置叫「環狀系統」，是空裔整個族群的記憶。",
  ui_story_1011_10111101_151_dialog_content = "它告訴我這裡是空裔的家鄉，名叫「高塔之城」。",
  ui_story_1011_10111101_152_dialog_content = "我們所處的「回歸塔」是其中最高的一座塔。",
  ui_story_1011_10111101_153_dialog_content = "它沒有提起空谷這個地方？",
  ui_story_1011_10111101_154_dialog_content = "是的，我也覺得很奇怪。",
  ui_story_1011_10111101_155_dialog_content = "難道名稱發生過演變？",
  ui_story_1011_10111101_156_dialog_content = "很有可能。這座遺跡所處的年代非常久遠，文字和語言發生過變化也不奇怪。",
  ui_story_1011_10111101_157_dialog_content = "那麼這個名叫「環狀系統」的東西，其實是某種儲存訊息的裝置？",
  ui_story_1011_10111101_158_dialog_content = "嗯，應該是這樣。",
  ui_story_1011_10111101_159_dialog_content = "空裔通過感應能力與之接觸，就能從中獲得訊息。",
  ui_story_1011_10111101_160_dialog_content = "但是何必做成這樣的系統呢？",
  ui_story_1011_10111101_161_dialog_content = "我想不通古怪的環形石板如何發揮作用。",
  ui_story_1011_10111101_162_dialog_content = "何況它的佔地，對於一個訊息儲存裝置而言也太大了。",
  ui_story_1011_10111101_163_dialog_content = "如此空間裡哪怕只是塞滿書籍，承載的訊息量都堪稱恐怖。",
  ui_story_1011_10111101_164_dialog_content = "塞滿書籍……",
  ui_story_1011_10111101_165_dialog_content = "對了。卡蓮，妳還記得之前撿到的那個鸚鵡螺嗎？",
  ui_story_1011_10111101_166_dialog_content = "嗯，記得。",
  ui_story_1011_10111101_167_dialog_content = "當時薇絲說，鸚鵡螺的形狀和作用反映出古代文明的數學理念。",
  ui_story_1011_10111101_168_dialog_content = "他們崇尚自然，而自然在數學語言中的體現是「連續」。",
  ui_story_1011_10111101_169_dialog_content = "那個理念說不定也應用在這裡。",
  ui_story_1011_10111101_170_dialog_content = "嗯……你是說，這些環形也是「連續」的象徵？",
  ui_story_1011_10111101_171_dialog_content = "對，我在想妳剛才說的「填滿書籍」。",
  ui_story_1011_10111101_172_dialog_content = "假設我們想儲存訊息，肯定是把書籍整整齊齊排放，彼此間盡量沒有空隙。",
  ui_story_1011_10111101_173_dialog_content = "最後也許會形成一個方形書堆。",
  ui_story_1011_10111101_174_dialog_content = "而方形有很多個邊角。它的線條並不是連續的。",
  ui_story_1011_10111101_175_dialog_content = "相比之下，環形就沒有任何邊角。",
  ui_story_1011_10111101_176_dialog_content = "用環形來規劃整個空間，這樣的儲存方式符合「連續」的思想。",
  ui_story_1011_10111101_177_dialog_content = "嗯！我就是這個意思！",
  ui_story_1011_10111101_178_dialog_content = "我……雖然能簡單表達出來，但仍舊難以理解。",
  ui_story_1011_10111101_179_dialog_content = "果真如此的話，這個古代文明的發達程度也許遠遠超乎我們想像。",
  ui_story_1011_10111101_180_dialog_content = "他們連奠定科技的基本理論都與我們截然不同。",
  ui_story_1011_10111101_181_dialog_content = "在他們眼裡，我們的數學可能就像原始人擺弄樹枝一樣簡陋。",
  ui_story_1011_10111101_182_dialog_content = "有這麼誇張嗎……",
  ui_story_1011_10111101_183_dialog_content = "再觸碰它試試吧，PlayerName。",
  ui_story_1011_10111101_184_dialog_content = "擁有更高文明的他們，到底能用這麼龐大的空間儲存多少訊息呢？",
  ui_story_1011_10111101_185_dialog_content = "也許世界上所有問題都能在裡面找到答案。",
  ui_story_1011_10111101_186_dialog_content = "嗯，我再去試試！",
  ui_story_1011_10111101_187_option_content = "強制感應！",
  ui_story_1011_10111101_188_dialog_content = "<color=#e8d9bb>嗡——！</color>",
  ui_story_1011_10111101_189_dialog_content = "又是這裡。",
  ui_story_1011_10111101_190_dialog_content = "既然是儲存訊息，我應該有辦法根據自己的想法翻閱吧。",
  ui_story_1011_10111101_191_dialog_content = "但是又沒有書架那樣一目了然的東西。",
  ui_story_1011_10111101_192_dialog_content = "對，意識！用我的意識來驅動它。",
  ui_story_1011_10111101_193_dialog_content = "嗯？！",
  ui_story_1011_10111101_194_dialog_content = "那些漂浮的石板開始轉動。",
  ui_story_1011_10111101_195_dialog_content = "PlayerName，你在做什麼……",
  ui_story_1011_10111101_196_dialog_content = "哇！哇！哇......",
  ui_story_1011_10111101_197_dialog_content = "頭好暈，我這是在移動嗎？",
  ui_story_1011_10111101_198_dialog_content = "停下來，要想辦法停下來。",
  ui_story_1011_10111101_199_dialog_content = "<color=#e8d9bb>嗡——！</color>",
  ui_story_1011_10111101_200_dialog_content = "呼，結束了？",
  ui_story_1011_10111101_201_dialog_content = "巨像。",
  ui_story_1011_10111101_202_dialog_content = "咦？！",
  ui_story_1011_10111101_203_dialog_content = "巨像是由光能驅動的大型多功能設施。",
  ui_story_1011_10111101_204_dialog_content = "它是空裔一生中最值得信任的東西。",
  ui_story_1011_10111101_205_dialog_content = "空裔的意識很強大，但身體很弱小。強大是先天的恩賜，弱小是付出的代價。",
  ui_story_1011_10111101_206_dialog_content = "巨像彌補了空裔的缺陷。做為一種身體延展，讓空裔的行為跟得上意識。",
  ui_story_1011_10111101_207_dialog_content = "因此，空裔需要學習的第一件事就是如何駕馭巨像。",
  ui_story_1011_10111101_208_dialog_content = "和之前一樣，一副教育我的口吻。",
  ui_story_1011_10111101_209_dialog_content = "這次是教我如何駕馭巨像嗎？",
  ui_story_1011_10111101_210_dialog_content = "為了供空裔駕駛，巨像上設有駕駛艙。",
  ui_story_1011_10111101_211_dialog_content = "空裔需要在這裡讓自己的意識與巨像相連。",
  ui_story_1011_10111101_212_dialog_content = "當你們產生足夠強的共鳴，巨像就會為你啟動。",
  ui_story_1011_10111101_213_dialog_content = "沒錯，就和我那時候一樣。",
  ui_story_1011_10111101_214_dialog_content = "巨像可以搭載各種模組組件，來幫助空裔實現不同的行為。",
  ui_story_1011_10111101_215_dialog_content = "透過巨像的幫助，空裔可以比任何生靈都強大。",
  ui_story_1011_10111101_216_dialog_content = "但身為這份力量的所有者，身為巨像的駕駛員，請始終銘記。",
  ui_story_1011_10111101_217_dialog_content = "銘記你們自降生時就被刻下的「命令」。",
  ui_story_1011_10111101_218_dialog_content = "空裔與巨像，永遠是戰爭的機器。",
  ui_story_1011_10111101_219_dialog_content = "戰爭的機器？！",
  ui_story_1011_10111101_220_dialog_content = "怎麼可能……我和臨空者號，連攻擊能力都沒有……",
  ui_story_1011_10111101_221_dialog_content = "這台戰爭機器具有巨像的身軀和空裔的智慧。",
  ui_story_1011_10111101_222_dialog_content = "而刺傷敵人的兵刃，早已聽從「命令」……",
  ui_story_1011_10111101_223_dialog_content = "等待著你的驅馳。",
  ui_story_1011_10111101_224_dialog_content = "什麼？！！",
  ui_story_1011_10111101_225_dialog_content = "這些是……暗鬼？！！",
  ui_story_1011_10111101_226_dialog_content = "接下來你需要學習戰爭，用很多很多時間去學習。",
  ui_story_1011_10111101_227_dialog_content = "你將在資料上看到戰場。",
  ui_story_1011_10111101_228_dialog_content = "看到一條生命在戰場上變得多麼輕薄，看到力量的落差在轉瞬間摧毀天平。",
  ui_story_1011_10111101_229_dialog_content = "所幸的是，戰場並不屬於空裔。",
  ui_story_1011_10111101_230_dialog_content = "這裡有為戰場而生的士兵，它們懂得的全部就是如何拚殺。",
  ui_story_1011_10111101_231_dialog_content = "這些醜陋的戰士會欣然走上戰場。",
  ui_story_1011_10111101_232_dialog_content = "而你們只負責為世界——",
  ui_story_1011_10111101_233_dialog_content = "帶來戰爭。",
  ui_story_1011_10111201_1_dialog_content = "呼……呼……",
  ui_story_1011_10111201_2_dialog_content = "PlayerName，你怎麼了？",
  ui_story_1011_10111201_3_dialog_content = "你出了好多汗。",
  ui_story_1011_10111201_4_dialog_content = "哈......我......",
  ui_story_1011_10111201_5_dialog_content = "我不知道。",
  ui_story_1011_10111201_6_dialog_content = "我不知道為什麼會看到那些。",
  ui_story_1011_10111201_7_dialog_content = "我不知道它意味著什麼，我不知道。",
  ui_story_1011_10111201_8_dialog_content = "你看到了什麼？",
  ui_story_1011_10111201_9_dialog_content = "我......我看到了巨像。",
  ui_story_1011_10111201_10_dialog_content = "環狀系統在教育我如何操作巨像。",
  ui_story_1011_10111201_11_dialog_content = "以及……",
  ui_story_1011_10111201_12_dialog_content = "如何驅使巨像裡的暗鬼。",
  ui_story_1011_10111201_13_dialog_content = "驅使暗鬼？ ！",
  ui_story_1011_10111201_13X1_dialog_content = "嗯......它告訴我，空裔與巨像是戰爭的機器......",
  ui_story_1011_10111201_14_dialog_content = "為什麼會這樣？",
  ui_story_1011_10111201_15_dialog_content = "卡蓮，你說會不會……",
  ui_story_1011_10111201_16_dialog_content = "我也覺得很驚人，但是……只憑這種資訊還沒法下判斷。",
  ui_story_1011_10111201_17_dialog_content = "這畢竟是遠古時期的遺跡，距離我們年代太遠。",
  ui_story_1011_10111201_18_dialog_content = "我們不知道那時候發生了什麼，也無法確認資訊的真實性。",
  ui_story_1011_10111201_19_dialog_content = "是這樣嗎？",
  ui_story_1011_10111201_20_dialog_content = "但如果，空裔真的曾經驅使過暗鬼。",
  ui_story_1011_10111201_21_dialog_content = "我不知道我該站在什麼立場上。",
  ui_story_1011_10111201_22_dialog_content = "難道……舒默那樣才是對的嗎……",
  ui_story_1011_10111201_23_dialog_content = "你所說的資訊值得我們思考，但是不要被它左右。",
  ui_story_1011_10111201_24_dialog_content = "你所經歷過的事情才是真實的，對嗎？",
  ui_story_1011_10111201_25_dialog_content = "你與臨空者號一同經歷的戰鬥是真實的。",
  ui_story_1011_10111201_26_dialog_content = "與你共同戰鬥過的大家也是真實的。",
  ui_story_1011_10111201_27_dialog_content = "用不著為自己的立場擔心。",
  ui_story_1011_10111201_28_dialog_content = "我，還有薇絲，還有其他不在場的朋友們。",
  ui_story_1011_10111201_29_dialog_content = "我們身邊始終留有你的立場。",
  ui_story_1011_10111201_30_dialog_content = "嗯……嗚……",
  ui_story_1011_10111201_31_dialog_content = "卡蓮……謝謝你……",
  ui_story_1011_10111201_32_dialog_content = "也......也不用有這麼大的反應。",
  ui_story_1011_10111201_33_dialog_content = "你說得對。你們才是真實的。",
  ui_story_1011_10111201_34_dialog_content = "薇絲現在這個樣子，找到方法讓她恢復才是最重要的。",
  ui_story_1011_10111201_35_dialog_content = "我要再試一次。",
  ui_story_1011_10111201_36_dialog_content = "你先休息一下吧？",
  ui_story_1011_10111201_37_dialog_content = "剛才跟環狀系統的接觸好像讓你很吃力。",
  ui_story_1011_10111201_38_dialog_content = "沒關係。",
  ui_story_1011_10111201_39_dialog_content = "我好像找到了使用它的方法。",
  ui_story_1011_10111201_40_option_content = "強制感應！",
  ui_story_1011_10111201_41_dialog_content = "<color=#e8d9bb>嗡——！</color>",
  ui_story_1011_10111201_42_dialog_content = "剛才感覺到我的意識在這裡移動。",
  ui_story_1011_10111201_43_dialog_content = "我想，這裡存儲的資訊很可能構成了一個空間。",
  ui_story_1011_10111201_44_dialog_content = "在空間裡移動的方式取決於我的思維方式。",
  ui_story_1011_10111201_45_dialog_content = "上一次來的時候，受到最初的思維慣性影響，就繼續進入了空裔的教程。",
  ui_story_1011_10111201_46_dialog_content = "那麼這一次我要轉換自己的思維方向。",
  ui_story_1011_10111201_47_dialog_content = "想像與治療薇絲相關的事情……",
  ui_story_1011_10111201_48_dialog_content = "想像她身中的特殊狀態，「識泯」……",
  ui_story_1011_10111201_49_dialog_content = "<color=#e8d9bb>嗡——！</color>",
  ui_story_1011_10111201_50_dialog_content = "成、成功了嗎？",
  ui_story_1011_10111201_51_dialog_content = "實驗數據，代號……",
  ui_story_1011_10111201_52_dialog_content = "權限由……更改為公開，向所有……放出。",
  ui_story_1011_10111201_53_dialog_content = "更改人：弗朗茨。",
  ui_story_1011_10111201_54_dialog_content = "弗朗茨，又是這個名字。",
  ui_story_1011_10111201_55_dialog_content = "看起來這段資訊損壞很嚴重，希望還有線索留下來。",
  ui_story_1011_10111201_56_dialog_content = "實驗體……，未從「識泯」下復甦，身體……，生命體徵消退。",
  ui_story_1011_10111201_57_dialog_content = "實驗體……，未從「識泯」下復甦，出現……現象，生命……",
  ui_story_1011_10111201_58_dialog_content = "實驗體……，未……復甦，實驗過程中……",
  ui_story_1011_10111201_59_dialog_content = "這是什麼實驗？",
  ui_story_1011_10111201_60_dialog_content = "這些實驗數據……好讓人不安……",
  ui_story_1011_10111201_61_dialog_content = "實驗體……，未從……復甦，無其他異狀。",
  ui_story_1011_10111201_62_dialog_content = "實驗體……，未從「識泯」下復甦，無其他……",
  ui_story_1011_10111201_63_dialog_content = "實驗體……，未……",
  ui_story_1011_10111201_64_dialog_content = "怎麼全都是……",
  ui_story_1011_10111201_65_dialog_content = "實驗……",
  ui_story_1011_10111201_66_dialog_content = "……",
  ui_story_1011_10111201_67_dialog_content = "哎，缺損部分還是太多了。",
  ui_story_1011_10111201_68_dialog_content = "……最後……結合……嘗試……",
  ui_story_1011_10111201_69_dialog_content = "實……",
  ui_story_1011_10111201_70_dialog_content = "觀測……身體變化……",
  ui_story_1011_10111201_71_dialog_content = "……",
  ui_story_1011_10111201_72_dialog_content = "……成功，並從「識泯」下復甦。",
  ui_story_1011_10111201_73_dialog_content = "？ ！ ！",
  ui_story_1011_10111201_74_dialog_content = "有成功的案例！",
  ui_story_1011_10111201_75_dialog_content = "這個實驗是做什麼的？在什麼地方？",
  ui_story_1011_10111201_76_dialog_content = "還需要更多資訊，要往更深處看看。",
  ui_story_1011_10111201_77_dialog_content = "提示，目標資訊受到……權限保護……",
  ui_story_1011_10111201_78_dialog_content = "查看……終止。",
  ui_story_1011_10111201_79_dialog_content = "呼……看不到嗎……",
  ui_story_1011_10111201_80_dialog_content = "怎麼樣，有收穫嗎？",
  ui_story_1011_10111201_81_dialog_content = "嗯。我找到了一組實驗數據。",
  ui_story_1011_10111201_82_dialog_content = "裡面記載了從「識泯」下復甦的例子。",
  ui_story_1011_10111201_83_dialog_content = "不過，我不知道這個實驗是做什麼的，也不知道地點在哪裡。",
  ui_story_1011_10111201_84_dialog_content = "而且成功的例子只有一次。",
  ui_story_1011_10111201_85_dialog_content = "一路走來沒看到過什麼保存完好的實驗裝置。",
  ui_story_1011_10111201_86_dialog_content = "希望它在更深處，而且尚能啟用吧。",
  ui_story_1011_10111201_87_dialog_content = "至於成功率，我們只能試一試了。",
  ui_story_1011_10111201_88_dialog_content = "你說得對，我們只能試一試。",
  ui_story_1011_10111201_89_dialog_content = "走吧，去更深處看看。",
  ui_story_1011_10111201_90_dialog_content = "就算找不到實驗裝置，說不定也會發現其他線索。",
  ui_story_1011_10111201_91_dialog_content = "誰知道這裡還埋藏著多少祕密……",
  ui_story_1011_10111201_92_dialog_content = "<color=#e8d9bb>嗒......嗒......嗒......</color>",
  ui_story_1011_10111201_93_dialog_content = "「回歸塔」……",
  ui_story_1011_10111201_94_dialog_content = "現在回過頭才後知後覺地發現，原來我們一直在塔形的建築裡探索。",
  ui_story_1011_10111201_95_dialog_content = "地下遺跡和地上的白塔，不知道是不是同一座建築。",
  ui_story_1011_10111201_96_dialog_content = "總覺得很難把這兩者放在一起啊。",
  ui_story_1011_10111201_97_dialog_content = "白塔在空谷裡樹立了那麼久，大家對它都很熟悉。",
  ui_story_1011_10111201_98_dialog_content = "而這座遺跡裡，完全是另一個世界的景象。",
  ui_story_1011_10111201_99_dialog_content = "兩者之間的聯繫不就是你們嗎——",
  ui_story_1011_10111201_100_dialog_content = "空裔。",
  ui_story_1011_10111201_101_dialog_content = "……",
  ui_story_1011_10111201_102_dialog_content = "時代、文明、科技都發生了變化，但生活在這片天空下的仍是空裔的族人。",
  ui_story_1011_10111201_103_dialog_content = "這毫無疑問是一種傳承的偉大。",
  ui_story_1011_10111201_104_dialog_content = "我即使站在光靈誕生的北境，也沒有過類似的感受。",
  ui_story_1011_10111201_105_dialog_content = "「偉大」啊……",
  ui_story_1011_10111201_106_dialog_content = "真是好重、好重的一個詞。",
  ui_story_1011_10111201_107_dialog_content = "嗯？",
  ui_story_1011_10111201_108_dialog_content = "維繫這份「偉大」的人，現在只剩我自己了……",
  ui_story_1011_10111201_109_dialog_content = "PlayerName......",
  ui_story_1011_10111201_110_dialog_content = "算了算了，不想那麼多了。",
  ui_story_1011_10111201_111_dialog_content = "往好處想的話，我是不是這座遺跡唯一的繼承人啊。",
  ui_story_1011_10111201_112_dialog_content = "這裡的東西都該屬於我吧？",
  ui_story_1011_10111201_113_dialog_content = "呵呵。",
  ui_story_1011_10111201_114_dialog_content = "嗯，你說得對。你理所當然是這裡的主人。",
  ui_story_1011_10111201_115_dialog_content = "真好啊，有這麼多遠古遺物，我再也不愁吃穿了吧。",
  ui_story_1011_10111201_116_dialog_content = "回去就把薇絲的記賬本給撕了！",
  ui_story_1011_10111201_117_dialog_content = "我會替薇絲記住這句話的。",
  ui_story_1011_10111201_118_dialog_content = "呃，那倒是不用......",
  ui_story_1011_10111201_119_dialog_content = "<color=#e8d9bb>哧......哧......</color>",
  ui_story_1011_10111201_120_dialog_content = "我好像聽到了什麼東西摩擦的聲音。",
  ui_story_1011_10111201_121_dialog_content = "是哪裡的機關在運轉嗎？",
  ui_story_1011_10111201_122_dialog_content = "有可能。",
  ui_story_1011_10111201_123_dialog_content = "不過讓我奇怪的是，既然荒廢了這麼久，它是如何保持機關運轉的？",
  ui_story_1011_10111201_124_dialog_content = "這可是上千年的時間，能源、磨損都是巨大的難題啊。",
  ui_story_1011_10111201_125_dialog_content = "對我們來說是難題，對這裡的建造者可未必。",
  ui_story_1011_10111201_126_dialog_content = "他們解決問題的方法看起來跟我們截然不同。",
  ui_story_1011_10111201_127_dialog_content = "也是。",
  ui_story_1011_10111201_128_dialog_content = "靠近點看看吧，總該知道聲音的來源是什麼東西。",
  ui_story_1011_10111201_129_dialog_content = "嗯。",
  ui_story_1011_10111201_130_dialog_content = "<color=#e8d9bb>哧......哧......</color>",
  ui_story_1011_10111201_131_dialog_content = "等等！",
  ui_story_1011_10111201_132_dialog_content = "怎麼了？",
  ui_story_1011_10111201_133_dialog_content = "我好像感應到了。",
  ui_story_1011_10111201_134_dialog_content = "<color=#e8d9bb>哧......哧......</color>",
  ui_story_1011_10111201_135_dialog_content = "……",
  ui_story_1011_10111201_136_dialog_content = "暗鬼？ ！",
  ui_story_1011_10111201_137_dialog_content = "竟然這裡也有。",
  ui_story_1011_10111201_138_dialog_content = "但是有點奇怪，牠們肯定發現我們了吧，怎麼完全沒有反應？",
  ui_story_1011_10111201_139_dialog_content = "……",
  ui_story_1011_10111201_140_dialog_content = "你看，牠們在做什麼？",
  ui_story_1011_10111201_141_dialog_content = "<color=#e8d9bb>哧......哧......</color>",
  ui_story_1011_10111201_142_dialog_content = "牠們在……推動石板？",
  ui_story_1011_10111201_143_dialog_content = "這個行為有什麼意義？",
  ui_story_1011_10111201_144_dialog_content = "我從沒見過這樣的暗鬼。",
  ui_story_1011_10111201_145_dialog_content = "好像很難用什麼意義來解釋牠們的行為。",
  ui_story_1011_10111201_145X1_dialog_content = "難道是在服從高級暗鬼的命令？",
  ui_story_1011_10111201_145X2_dialog_content = "不對，推動石板這件事對任何暗鬼都沒有意義。",
  ui_story_1011_10111201_145X3_dialog_content = "但是......對空裔來說，也許有意義......",
  ui_story_1011_10111201_147_dialog_content = "什麼意思？",
  ui_story_1011_10111201_148_dialog_content = "剛才我們不是在想，遺跡是如何保持運轉的嗎？",
  ui_story_1011_10111201_149_dialog_content = "現在我們找到答案了。",
  ui_story_1011_10111201_150_dialog_content = "妳的意思是靠暗鬼？",
  ui_story_1011_10111201_151_dialog_content = "只是一種猜測。",
  ui_story_1011_10111201_152_dialog_content = "你看牠們，對我們視而不見，只是在一趟趟地推動石板。",
  ui_story_1011_10111201_153_dialog_content = "牠們就像驅動機關的鏈條，成為了機關的一部分。",
  ui_story_1011_10111201_154_dialog_content = "<color=#e8d9bb>哧......哧......</color>",
  ui_story_1011_10111201_155_dialog_content = "竟然能做到這種事情……",
  ui_story_1011_10111201_156_dialog_content = "看來環狀系統裡所見的果然沒錯。",
  ui_story_1011_10111201_157_dialog_content = "那些古時的空裔……懂得如何讓暗鬼服從……",
  ui_story_1011_10111201_158_dialog_content = "靠什麼做到的呢？",
  ui_story_1011_10111201_159_dialog_content = "也許是感應？",
  ui_story_1011_10111201_160_dialog_content = "但是這裡早就沒有人了，暗鬼仍然在服從命令。",
  ui_story_1011_10111201_161_dialog_content = "等一下，前面好像沒有路了。",
  ui_story_1011_10111201_162_dialog_content = "還真是，這裡就是盡頭了嗎？",
  ui_story_1011_10111201_163_dialog_content = "好像沒什麼東西啊，好空曠。",
  ui_story_1011_10111201_164_dialog_content = "中間有一個石台，去那裡看看。",
  ui_story_1011_10111201_165_dialog_content = "這些暗鬼推動石板，總該是為什麼東西而服務的。",
  ui_story_1011_10111201_166_dialog_content = "但是它看起來，就只是個石台啊。",
  ui_story_1011_10111201_167_dialog_content = "側面有什麼機關嗎？",
  ui_story_1011_10111201_168_dialog_content = "咳咳......好多灰......",
  ui_story_1011_10111201_169_dialog_content = "用你的感應能力試試呢？",
  ui_story_1011_10111201_170_dialog_content = "試過了，完全沒有回應。",
  ui_story_1011_10111201_171_dialog_content = "一塊如假包換的石墩子。",
  ui_story_1011_10111201_172_dialog_content = "怎麼會這樣。",
  ui_story_1011_10111201_173_dialog_content = "或者說，這裡曾經有過什麼。",
  ui_story_1011_10111201_174_dialog_content = "但是因為材質之類的原因，現在已經損壞或者消失了？",
  ui_story_1011_10111201_175_dialog_content = "也有可能，畢竟遺跡裡到處都損壞的那麼嚴重。",
  ui_story_1011_10111201_176_dialog_content = "連那扇巨大的石門都風化開裂了，其他材質的東西更是……",
  ui_story_1011_10111201_177_dialog_content = "<color=#e8d9bb>嗡——！</color>",
  ui_story_1011_10111201_178_dialog_content = "輔腦偵測到登入請求。",
  ui_story_1011_10111201_179_dialog_content = "輔腦的聲音！",
  ui_story_1011_10111201_180_dialog_content = "好像有機關發動了，PlayerName你做了什麼？",
  ui_story_1011_10111201_181_dialog_content = "我......我什麼都沒動啊！",
  ui_story_1011_10111201_182_dialog_content = "我還想問是不是妳呢！",
  ui_story_1011_10111201_183_dialog_content = "需要確認登入者身分。",
  ui_story_1011_10111201_184_dialog_content = "請報告身分資訊。",
  ui_story_1011_10111201_185_dialog_content = "身分？我的嗎？",
  ui_story_1011_10111201_186_dialog_content = "我叫PlayerName。",
  ui_story_1011_10111201_187_dialog_content = "需要確認登入者身分。",
  ui_story_1011_10111201_188_dialog_content = "請報告身分資訊。",
  ui_story_1011_10111201_189_dialog_content = "誒？我說了我叫PlayerName啊，這個不行嗎？",
  ui_story_1011_10111201_190_dialog_content = "對於他們的年代而言，PlayerName可能查無此人吧。",
  ui_story_1011_10111201_191_dialog_content = "那怎麼辦？",
  ui_story_1011_10111201_192_dialog_content = "對了，這裡是不是有個叫「弗朗茨」的空裔來著。",
  ui_story_1011_10111201_193_dialog_content = "用他的名字試試？",
  ui_story_1011_10111201_194_dialog_content = "偵測到身分輸入：「啪……啦……砰」。",
  ui_story_1011_10111201_195_dialog_content = "啊？啪啦砰是什麼怪名字？我可沒說過這種話啊！",
  ui_story_1011_10111201_196_dialog_content = "開始識別登入者身分。",
  ui_story_1011_10111201_197_dialog_content = "嘟......嘟......嘟......",
  ui_story_1011_10111201_198_dialog_content = "真的有人會叫這種全是擬聲詞的名字嗎？",
  ui_story_1011_10111201_199_dialog_content = "別白費力氣了輔腦，能不能先告訴我們這是什麼地方？",
  ui_story_1011_10111201_200_dialog_content = "等等，PlayerName！",
  ui_story_1011_10111201_201_dialog_content = "你快看那......",
  ui_story_1011_10111201_202_dialog_content = "怎麼了？",
  ui_story_1011_10111201_203_dialog_content = "……",
  ui_story_1011_10111201_204_dialog_content = "這......這些暗鬼怎麼不推石板了？",
  ui_story_1011_10111201_205_dialog_content = "不是吧……",
  ui_story_1011_10111201_206_dialog_content = "嘎——！",
  ui_story_1011_10111201_207_dialog_content = "卡蓮！",
  ui_story_1011_10111201_208_dialog_content = "冰花，散開！",
  ui_story_1011_10111401_1_dialog_content = "還好，這裡的暗鬼並不算多。",
  ui_story_1011_10111401_2_dialog_content = "不然像這樣一下子包上來，我們恐怕沒法全身而退。",
  ui_story_1011_10111401_3_dialog_content = "是啊。",
  ui_story_1011_10111401_4_dialog_content = "這個輔腦怎麼回事，好像比之前更笨了。",
  ui_story_1011_10111401_5_dialog_content = "喂，輔腦，能聽到不。",
  ui_story_1011_10111401_6_dialog_content = "回應我一下好不好？這是怎麼回事？",
  ui_story_1011_10111401_7_dialog_content = "身分識別錯誤，「啪啦砰」是非法的登入身分。",
  ui_story_1011_10111401_8_dialog_content = "請重新報告身分資訊，或退出身分登入。",
  ui_story_1011_10111401_9_dialog_content = "什麼亂七八糟的，它根本不聽我說話啊！",
  ui_story_1011_10111401_10_dialog_content = "有沒有感覺它的態度跟之前完全不一樣。",
  ui_story_1011_10111401_11_dialog_content = "之前會聆聽你的問題，解答你的疑惑。",
  ui_story_1011_10111401_12_dialog_content = "但現在，它只是在等待你的指令。",
  ui_story_1011_10111401_13_dialog_content = "妳這麼一說好像確實......",
  ui_story_1011_10111401_14_dialog_content = "但是為什麼啊？",
  ui_story_1011_10111401_15_dialog_content = "也許是因為所處的位置吧。",
  ui_story_1011_10111401_16_dialog_content = "說不定這個空間，本身就是用來向它下達指令的地方。",
  ui_story_1011_10111401_17_dialog_content = "是這樣嗎？",
  ui_story_1011_10111401_18_dialog_content = "輔腦，我要退出身分登入。",
  ui_story_1011_10111401_19_dialog_content = "偵測到回歸塔重啟請求。",
  ui_story_1011_10111401_20_dialog_content = "請求來自啪啦砰，一個不被許可的身分。",
  ui_story_1011_10111401_21_dialog_content = "警告，繼續操作將觸發<color=#FFB400>「守護者系統」</color>。",
  ui_story_1011_10111401_22_dialog_content = "妳看它又這樣！",
  ui_story_1011_10111401_23_dialog_content = "那個全是擬聲詞的名字是說我嗎？我可沒發出什麼重啟請求！",
  ui_story_1011_10111401_24_dialog_content = "如果不考慮那些複雜的可能性……",
  ui_story_1011_10111401_25_dialog_content = "最簡單的答案就是，它壞了。",
  ui_story_1011_10111401_26_dialog_content = "壞了？輔腦嗎？",
  ui_story_1011_10111401_27_dialog_content = "不是輔腦，是接收你指令的裝置壞了。",
  ui_story_1011_10111401_28_dialog_content = "用過啟光的收音機嗎？",
  ui_story_1011_10111401_29_dialog_content = "那種機器損壞之後，會發出「噼哩啪啦」的噪音。",
  ui_story_1011_10111401_30_dialog_content = "感覺有點像輔腦接收到的那個全是擬聲詞的名字。",
  ui_story_1011_10111401_31_dialog_content = "那麻煩大了啊……",
  ui_story_1011_10111401_32_dialog_content = "回歸塔重啟請求被確認。",
  ui_story_1011_10111401_33_dialog_content = "警告，「守護者系統」即將觸發，請立即中止你的指令。",
  ui_story_1011_10111401_34_dialog_content = "我中止！當然要中止！",
  ui_story_1011_10111401_35_dialog_content = "不如說這根本就不是我的指令啊！",
  ui_story_1011_10111401_36_dialog_content = "警告，非法登入者強制執行了回歸塔重啟程式。",
  ui_story_1011_10111401_37_dialog_content = "正在從環狀系統中調取回歸塔重啟流程。",
  ui_story_1011_10111401_38_dialog_content = "嘟......嘟......嘟......",
  ui_story_1011_10111401_39_dialog_content = "我有種不好的預感，有什麼東西要開始了。",
  ui_story_1011_10111401_40_dialog_content = "我也是。還有機會阻止它嗎？",
  ui_story_1011_10111401_41_dialog_content = "把那個搗亂的接收裝置破壞掉吧！",
  ui_story_1011_10111401_42_dialog_content = "壞也不壞徹底點，壞一半算什麼啊！",
  ui_story_1011_10111401_43_dialog_content = "不知道它在哪。是這個石台嗎？",
  ui_story_1011_10111401_44_dialog_content = "總之先試試……哈！",
  ui_story_1011_10111401_45_dialog_content = "<color=#e8d9bb>砰！</color>",
  ui_story_1011_10111401_46_dialog_content = "痛啊痛啊啊！！！",
  ui_story_1011_10111401_47_dialog_content = "那可是石質的，你踢它有什麼用啊。",
  ui_story_1011_10111401_48_dialog_content = "警告，非法登入者強制執行了回歸塔重啟程式。",
  ui_story_1011_10111401_49_dialog_content = "能源模塊恢復，開始為其他模塊供能。",
  ui_story_1011_10111401_50_dialog_content = "嘟......嘟......嘟......",
  ui_story_1011_10111401_51_dialog_content = "卡蓮，我怎麼覺得腳下有輕微的震動感……",
  ui_story_1011_10111401_52_dialog_content = "我也感覺到了。",
  ui_story_1011_10111401_53_dialog_content = "輔腦說的是「回歸塔重啟」，也許是什麼變化即將發生在整座遺跡身上。",
  ui_story_1011_10111401_54_dialog_content = "整座遺跡？這麼嚇人嗎？",
  ui_story_1011_10111401_55_dialog_content = "你應該擔心的是更嚇人的事情。",
  ui_story_1011_10111401_56_dialog_content = "它可是一直在發出「警告」，我覺得它不會只是說說而已。",
  ui_story_1011_10111401_57_dialog_content = "警告，非法登入者強制執行了回歸塔重啟程式。",
  ui_story_1011_10111401_58_dialog_content = "偵測到指令權限存在錯誤，即將進行自主除錯。",
  ui_story_1011_10111401_59_dialog_content = "這是最後一次警告，請立即中止你的指令。",
  ui_story_1011_10111401_60_dialog_content = "我說了中止啊！",
  ui_story_1011_10111401_61_dialog_content = "我求求你了！讓我中止吧！",
  ui_story_1011_10111401_62_dialog_content = "我不想跟莫名其妙的古代文明作對啊！",
  ui_story_1011_10111401_64_dialog_content = "偵測到非法指令仍在發出。",
  ui_story_1011_10111401_65_dialog_content = "準備執行糾錯程式。",
  ui_story_1011_10111401_66_dialog_content = "喂！輔腦！你欺人太甚了！",
  ui_story_1011_10111401_67_dialog_content = "「守護者系統」啟動，解放克勞迪亞。",
  ui_story_1011_10111401_68_dialog_content = "<color=#e8d9bb>轟——！！！</color>",
  ui_story_1011_10111401_69_dialog_content = "這是……",
  ui_story_1011_10111401_70_dialog_content = "雕像嗎？還是機器？",
  ui_story_1011_10111401_71_dialog_content = "這東西......是會動的嗎？",
  ui_story_1011_10111401_72_dialog_content = "應該……壞掉了吧……",
  ui_story_1011_10111401_73_dialog_content = "<color=#e8d9bb>喀——喀——</color>",
  ui_story_1011_10111401_74_dialog_content = "看起來是。",
  ui_story_1011_10111401_75_dialog_content = "PlayerName，做好戰鬥準備。",
  ui_story_1011_10111401_76_dialog_content = "……輔腦，我們還能談談嗎？",
  ui_story_1011_10111401_77_dialog_content = "「守護者系統」開始執行糾錯。",
  ui_story_1011_10111401_78_dialog_content = "糾正錯誤的指令，或者——|\n糾正錯誤的指令輸入者。",
  ui_story_1011_10111402_1_dialog_content = "難纏的傢伙。",
  ui_story_1011_10111402_2_dialog_content = "它懂得如何對付光能術。",
  ui_story_1011_10111402_3_dialog_content = "看樣子還要拖下去。",
  ui_story_1011_10111402_4_dialog_content = "堅持得住嗎卡蓮？",
  ui_story_1011_10111402_5_dialog_content = "我還好，但是……",
  ui_story_1011_10111402_6_dialog_content = "薇絲就躺在旁邊，我怕出現意外。",
  ui_story_1011_10111402_7_dialog_content = "有沒有速戰速決的方法？",
  ui_story_1011_10111402_8_dialog_content = "回歸塔內設施開始自檢——",
  ui_story_1011_10111402_9_dialog_content = "警告，損壞程度達到高危，絕大部分區域無法正常使用。",
  ui_story_1011_10111402_10_dialog_content = "「損管程式」啟動，嘗試修復損壞部分。",
  ui_story_1011_10111402_11_dialog_content = "！！！",
  ui_story_1011_10111402_12_dialog_content = "卡蓮，它的動作停下來了！",
  ui_story_1011_10111402_13_dialog_content = "趁現在！繞到它背後！",
  ui_story_1011_10111402_14_dialog_content = "明白！",
  ui_story_1011_10111402_15_dialog_content = "偵測到「守護者系統」正在運行。",
  ui_story_1011_10111402_16_dialog_content = "跳過該部分，繼續修復指令輸入系統。",
  ui_story_1011_10111402_17_dialog_content = "嘟......嘟......嘟......",
  ui_story_1011_10111402_18_dialog_content = "<color=#e8d9bb>喀——</color>",
  ui_story_1011_10111402_19_dialog_content = "卡蓮！它恢復行動了，小心！",
  ui_story_1011_10111402_20_dialog_content = "時間夠了。",
  ui_story_1011_10111402_21_dialog_content = "生於遠古的兵器，來見識未來的光能術吧！",
  ui_story_1011_10111402_22_dialog_content = "呼……解決掉了嗎……",
  ui_story_1011_10111402_23_dialog_content = "嗯，它徹底失去行動力了。",
  ui_story_1011_10111402_24_dialog_content = "不過也不要放鬆警惕。",
  ui_story_1011_10111402_25_dialog_content = "我們已經看到了，回歸塔的自衛能力很強。",
  ui_story_1011_10111402_26_dialog_content = "既然惹到了它，不知道接下來還有沒有其他麻煩。",
  ui_story_1011_10111402_27_dialog_content = "不會吧？",
  ui_story_1011_10111402_28_dialog_content = "都說不打不相識，希望它不要記仇啊。",
  ui_story_1011_10111402_29_dialog_content = "叮——咚——",
  ui_story_1011_10111402_30_dialog_content = "「損管程式」修復完成，主要功能已基本修復。",
  ui_story_1011_10111402_31_dialog_content = "回歸塔，完成重啟。",
  ui_story_1011_10111402_32_dialog_content = "誒？好像有什麼大事不知不覺完成了……",
  ui_story_1011_10111402_33_dialog_content = "回歸塔能源供給，已恢復。",
  ui_story_1011_10111402_34_dialog_content = "回歸塔傳動體系，已恢復。",
  ui_story_1011_10111402_35_dialog_content = "回歸塔傳感體系，已恢復。",
  ui_story_1011_10111402_36_dialog_content = "<color=#e8d9bb>咔——咔——咔——咔——</color>",
  ui_story_1011_10111402_37_dialog_content = "卡蓮妳聽！機關轉動的聲音在從四面八方傳過來！",
  ui_story_1011_10111402_38_dialog_content = "它開始運行了！整座塔都在運行！",
  ui_story_1011_10111402_39_dialog_content = "太不可思議了。",
  ui_story_1011_10111402_40_dialog_content = "這座遺跡並沒有被廢棄！它就像……",
  ui_story_1011_10111402_41_dialog_content = "就像睡了一個很長的覺。",
  ui_story_1011_10111402_42_dialog_content = "報告回歸塔內狀況。",
  ui_story_1011_10111402_43_dialog_content = "巨像整備區，目前巨像：1台。狀態：亟待修理。",
  ui_story_1011_10111402_44_dialog_content = "巨像零件車間，已損壞，修復失敗。",
  ui_story_1011_10111402_45_dialog_content = "資源生產區，目前人員：0。",
  ui_story_1011_10111402_46_dialog_content = "廢物處理區，目前人員：0。",
  ui_story_1011_10111402_47_dialog_content = "空裔生活區，目前人員：0。",
  ui_story_1011_10111402_48_dialog_content = "放逐區，目前人員：0。",
  ui_story_1011_10111402_49_dialog_content = "……",
  ui_story_1011_10111402_50_dialog_content = "這裡已經沒有空裔了，除了……",
  ui_story_1011_10111402_51_dialog_content = "核心中樞區，目前人員：1。",
  ui_story_1011_10111402_52_dialog_content = "嗯，我。",
  ui_story_1011_10111402_53_dialog_content = "它從漫長的睡夢裡醒過來了。",
  ui_story_1011_10111402_54_dialog_content = "但是……不知道它能不能習慣孤獨。",
  ui_story_1011_10111402_55_dialog_content = "復位程式準備啟動。",
  ui_story_1011_10111402_56_dialog_content = "回歸塔，再次凌於天幕之隅。",
  ui_story_1011_10111402_57_dialog_content = "你還沒鬧夠嗎。",
  ui_story_1011_10111402_58_dialog_content = "呼……呼……",
  ui_story_1011_10111402_59_dialog_content = "喂，繼續戰鬥啊！",
  ui_story_1011_10111402_60_dialog_content = "不戰鬥到一方倒下為止也太沒勁了吧！",
  ui_story_1011_10111402_61_dialog_content = "你只有一個人，失敗是注定的事情。",
  ui_story_1011_10111402_62_dialog_content = "這不是戰鬥，是你在耍脾氣。",
  ui_story_1011_10111402_63_dialog_content = "（這傢伙好強，我跟她交手完全佔不到便宜。）",
  ui_story_1011_10111402_64_dialog_content = "（雖然說起來很窩囊，但是能堅持到現在多虧她無心戰鬥吧。）",
  ui_story_1011_10111402_65_dialog_content = "（這座白塔裡面究竟有什麼東西，能讓她如此在意？）",
  ui_story_1011_10111402_66_dialog_content = "（算了，一時半刻也想不明白。）",
  ui_story_1011_10111402_67_dialog_content = "（我只知道，敵人越想做到的事情，就越有必要去阻止。）",
  ui_story_1011_10111402_68_dialog_content = "（軍人可不會因為敵人強大而膽怯啊！）",
  ui_story_1011_10111402_69_dialog_content = "看這裡啊，吞羅！！！",
  ui_story_1011_10111402_70_dialog_content = "別想用些臭魚爛蝦來糊弄我！",
  ui_story_1011_10111402_71_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_1011_10111402_72_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_1011_10111402_73_dialog_content = "喂喂喂，怎麼回事，地震了嗎？",
  ui_story_1011_10111402_74_dialog_content = "正打得熱鬧呢，不要煞風景啊！",
  ui_story_1011_10111402_75_dialog_content = "不對，不是普通的地震。",
  ui_story_1011_10111402_76_dialog_content = "這座塔……",
  ui_story_1011_10111402_77_dialog_content = "是這座塔在震動。",
  ui_story_1011_10111402_78_dialog_content = "好大的煙！咳……咳咳……",
  ui_story_1011_10111402_79_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_1011_10111402_80_dialog_content = "喔哦哦哦哦！",
  ui_story_1011_10111402_81_dialog_content = "他媽的這比地震還誇張吧！",
  ui_story_1011_10111402_82_dialog_content = "當然會比地震誇張。",
  ui_story_1011_10111402_83_dialog_content = "接下來看到的，也許千年、萬年來都只此一次。",
  ui_story_1011_10111402_84_dialog_content = "這座白塔不應該屹立於此。",
  ui_story_1011_10111402_85_dialog_content = "它應該屹立在……更高的地方。",
  ui_story_1011_10111402_86_dialog_content = "<color=#e8d9bb>轟隆隆隆隆隆——！</color>",
  ui_story_1011_10111402_87_dialog_content = "什麼？！！",
  ui_story_1011_10111402_88_dialog_content = "我沒看錯吧，這麼大一座塔……從地底下升起來了？",
  ui_story_1011_10111402_89_dialog_content = "PlayerName他們還在裡面啊！",
  ui_story_1011_10111402_90_dialog_content = "他們到底……做了什麼？",
  ui_story_1011_10111402_91_dialog_content = "歷時彌久卻仍在運行的古建築竟然真的存在。",
  ui_story_1011_10111402_92_dialog_content = "與我一牆之隔的那裡是……",
  ui_story_1011_10111402_93_dialog_content = "是另一個時代嗎？",
  ui_story_1011_10111402_94_dialog_content = "所以這是什麼東西啊？你研究過嗎？",
  ui_story_1011_10111402_95_dialog_content = "我用不著回答你的問題。",
  ui_story_1011_10111402_96_dialog_content = "（日蝕語）吞羅大人，吞羅大人！",
  ui_story_1011_10111402_97_dialog_content = "（日蝕語）升起的白塔外壁存在缺口。",
  ui_story_1011_10111402_98_dialog_content = "缺口，太好了。",
  ui_story_1011_10111402_99_dialog_content = "用不著再搭理這個瘋子了。",
  ui_story_1011_10111402_100_dialog_content = "喂！你這傢伙別想把我甩下！",
  ui_story_1011_10111402_101_dialog_content = "我們的戰鬥還沒完呢！",
  ui_story_1011_10111402_101X1_dialog_content = "（看這陣仗，還有吞羅的反應，PlayerName他們一定在做很重要的事情。）",
  ui_story_1011_10111402_101X2_dialog_content = "（絕對不能讓吞羅去干擾他們，絕對！）",
  ui_story_1011_10111402_102_dialog_content = "怎麼回事怎麼回事！震動得好厲害！",
  ui_story_1011_10111402_103_dialog_content = "找固定的物體抓牢！小心上方掉下來的東西！",
  ui_story_1011_10111402_104_dialog_content = "薇絲怎麼辦？",
  ui_story_1011_10111402_105_dialog_content = "你不用管了，我來照顧她！",
  ui_story_1011_10111402_106_dialog_content = "<color=#e8d9bb>轟隆隆隆隆隆——！</color>",
  ui_story_1011_10111402_107_dialog_content = "呼……呼……停下來了……",
  ui_story_1011_10111402_108_dialog_content = "卡蓮，妳……還好嗎？",
  ui_story_1011_10111402_109_dialog_content = "我沒事，薇絲也挺好的，倒是你……",
  ui_story_1011_10111402_110_dialog_content = "別抱著那個石台了，鬆手吧。",
  ui_story_1011_10111402_111_dialog_content = "喔，對。",
  ui_story_1011_10111402_112_dialog_content = "所以這回又是發生了什麼？",
  ui_story_1011_10111402_113_dialog_content = "依我的感覺來看，我們剛剛是在上升。",
  ui_story_1011_10111402_114_dialog_content = "我也這麼覺得。",
  ui_story_1011_10111402_115_dialog_content = "回歸塔復位完成。",
  ui_story_1011_10111402_116_dialog_content = "向管理者報告狀態……",
  ui_story_1011_10111402_117_dialog_content = "它說「回歸塔復位」，是讓整座塔的位置發生了改變嗎？",
  ui_story_1011_10111402_118_dialog_content = "這種事情究竟是怎麼做到的？",
  ui_story_1011_10111402_119_dialog_content = "報告失敗，未尋找到管理者。",
  ui_story_1011_10111402_120_dialog_content = "啟用備案，尋找回歸塔重啟程式啟動者。",
  ui_story_1011_10111402_121_dialog_content = "確認目標身分為非法登入者「啪啦砰」。",
  ui_story_1011_10111402_122_dialog_content = "喂，這傢伙不會又要找我麻煩吧？",
  ui_story_1011_10111402_123_dialog_content = "執行備案，由於「啪啦砰」重啟了回歸塔，將其提升為管理者填補空缺。",
  ui_story_1011_10111402_124_dialog_content = "向「啪啦砰」開放內環權限。",
  ui_story_1011_10111402_125_dialog_content = "欸？",
  ui_story_1011_10111402_126_dialog_content = "我不是非法的嗎，怎麼突然變成管理者了？",
  ui_story_1011_10111402_127_dialog_content = "這個管理者有什麼用啊？",
  ui_story_1011_10111402_128_dialog_content = "管理者可以通過輔腦控制並使用回歸塔內的絕大部分功能。",
  ui_story_1011_10111402_129_dialog_content = "原來如此……",
  ui_story_1011_10111402_130_dialog_content = "等等！你能正常回我話了！",
  ui_story_1011_10111402_131_dialog_content = "是的。",
  ui_story_1011_10111402_132_dialog_content = "那剛剛是為什麼？",
  ui_story_1011_10111402_133_dialog_content = "普通登入者在核心中樞區只能輸入指令，無法與輔腦互動。",
  ui_story_1011_10111402_134_dialog_content = "管理者才有隨時與輔腦互動的權限。",
  ui_story_1011_10111402_135_dialog_content = "原來你這麼勢利眼啊。",
  ui_story_1011_10111402_136_dialog_content = "輔腦不明白這個詞的意思。",
  ui_story_1011_10111402_137_dialog_content = "算了算了。",
  ui_story_1011_10111402_138_dialog_content = "但說起輸入指令，剛才那些指令也完全不對吧！",
  ui_story_1011_10111402_139_dialog_content = "「啪啦砰」這個古怪的名字就是證據啊！",
  ui_story_1011_10111402_140_dialog_content = "剛才指令輸入系統發生了損壞，現在已經修復了。",
  ui_story_1011_10111402_141_dialog_content = "對你造成了麻煩，非常抱歉。",
  ui_story_1011_10111402_142_dialog_content = "那可是不小的麻煩啊。",
  ui_story_1011_10111402_143_dialog_content = "還有，你說的「開放內環權限」又是什麼啊？",
  ui_story_1011_10111402_144_dialog_content = "回歸塔的資訊、功能分為三個不同的權限等級。",
  ui_story_1011_10111402_145_dialog_content = "<color=#FFB400>「外環」</color>，普通登入者可接觸。",
  ui_story_1011_10111402_146_dialog_content = "<color=#FFB400>「內環」</color>，管理者可接觸。",
  ui_story_1011_10111402_147_dialog_content = "<color=#FFB400>「元環」</color>，代表最初與最高的「命令」，無法接觸。",
  ui_story_1011_10111402_148_dialog_content = "喔。那豈不是除了無法接觸的「元環權限」，我已經是最高權限了？",
  ui_story_1011_10111402_149_dialog_content = "是的。",
  ui_story_1011_10111402_150_dialog_content = "你已經擁有內環權限，即將為你同步回歸塔的感知。",
  ui_story_1011_10111402_151_dialog_content = "誒？這又是什麼？",
  ui_story_1011_10111402_152_dialog_content = "名詞太多記不過來了啊！",
  ui_story_1011_10111402_153_dialog_content = "不需要記，只需要用意識去感受。",
  ui_story_1011_10111402_154_dialog_content = "回歸塔，將成為你的眼睛。",
  ui_story_1011_10111402_155_dialog_content = "這是……",
  ui_story_1011_10111402_156_dialog_content = "哇好高的塔！這就是回歸塔的全貌嗎？",
  ui_story_1011_10111402_157_dialog_content = "那裡是……是我們炸毀的洞口！",
  ui_story_1011_10111402_158_dialog_content = "它果然和白塔是一體的！",
  ui_story_1011_10111402_159_dialog_content = "PlayerName，你看到外面的景象了？",
  ui_story_1011_10111402_160_dialog_content = "是的！",
  ui_story_1011_10111402_161_dialog_content = "太神奇了，就好像我自己飛在高塔外面一樣！",
  ui_story_1011_10111402_162_dialog_content = "你還可以看到其他地方。",
  ui_story_1011_10111402_163_dialog_content = "更遠……更遠的地方。",
  ui_story_1011_10111501_1_dialog_content = "那邊！快去那邊看看！",
  ui_story_1011_10111501_2_dialog_content = "已經看過了！什麼都沒有！",
  ui_story_1011_10111501_3_dialog_content = "那究竟是......",
  ui_story_1011_10111501_4_dialog_content = "趕快去叫人吧！",
  ui_story_1011_10111501_5_dialog_content = "這不是我們能解決的問題！",
  ui_story_1011_10111501_6_dialog_content = "對，去叫守夜人，去叫守夜人！",
  ui_story_1011_10111501_7_dialog_content = "讓上面的大人出面解決問題！",
  ui_story_1011_10111501_8_dialog_content = "這……這可是達摩克里斯啊……",
  ui_story_1011_10111501_9_dialog_content = "娜汀，把情況詳細說一遍。",
  ui_story_1011_10111501_10_dialog_content = "是，城主大人！",
  ui_story_1011_10111501_11_dialog_content = "根據衛兵的報告，大約十分鐘之前，他們察覺到「控制室」方向的異常。",
  ui_story_1011_10111501_12_dialog_content = "衛兵們並沒有遇到過類似的事情，檢修無果後陷入了慌亂。",
  ui_story_1011_10111501_13_dialog_content = "他們從現場情況得到了一個猜測——",
  ui_story_1011_10111501_14_dialog_content = "<color=#FFB400>達摩克里斯</color>正在啟動。",
  ui_story_1011_10111501_15_dialog_content = "又是達摩克里斯。",
  ui_story_1011_10111501_16_dialog_content = "這次是誰想私自啟動它？",
  ui_story_1011_10111501_17_dialog_content = "沒有人。",
  ui_story_1011_10111501_18_dialog_content = "？！",
  ui_story_1011_10111501_19_dialog_content = "衛兵嚴密搜尋了控制室的每一寸角落，他們很確定這個答案——沒有人。",
  ui_story_1011_10111501_20_dialog_content = "達摩克里斯是自己啟動的。",
  ui_story_1011_10111501_21_dialog_content = "怎麼可能？",
  ui_story_1011_10111501_22_dialog_content = "達摩克里斯現在的狀態怎麼樣。",
  ui_story_1011_10111501_23_dialog_content = "還處在啟動流程中，正在蓄積光能。",
  ui_story_1011_10111501_24_dialog_content = "好，我知道了。",
  ui_story_1011_10111501_25_dialog_content = "娜汀，妳現在立刻去切斷達摩克里斯與白夜城之間的光能連接。",
  ui_story_1011_10111501_26_dialog_content = "不要考慮後果，越快越好。",
  ui_story_1011_10111501_27_dialog_content = "是，城主大人！",
  ui_story_1011_10111501_28_dialog_content = "伊倫汀，帶著妳的人把這裡封鎖，別讓其他人靠近控制室。",
  ui_story_1011_10111501_29_dialog_content = "尤其是元老院，他們最喜歡在危急關頭添麻煩。",
  ui_story_1011_10111501_30_dialog_content = "是，城主大人！",
  ui_story_1011_10111501_31_dialog_content = "不過我在想，要不要先確認消息的準確性？",
  ui_story_1011_10111501_32_dialog_content = "切斷達摩克里斯的連接和封鎖控制室都是牽一發而動全身的大事。",
  ui_story_1011_10111501_33_dialog_content = "要是懲戒幾個搞不清狀況的衛兵就能解決問題，我們反而該謝天謝地了。",
  ui_story_1011_10111501_34_dialog_content = "就怕問題沒那麼簡單。",
  ui_story_1011_10111501_35_dialog_content = "比起達摩克里斯隨時會發射的風險，我寧願承擔其他任何損失。",
  ui_story_1011_10111501_36_dialog_content = "是，城主大人，我明白了。",
  ui_story_1011_10111501_37_dialog_content = "四天使，跟我來。",
  ui_story_1011_10111501_38_dialog_content = "是！",
  ui_story_1011_10111501_39_dialog_content = "<color=#e8d9bb>嗡——！</color>",
  ui_story_1011_10111501_40_dialog_content = "又一次光能脈衝！",
  ui_story_1011_10111501_41_dialog_content = "不過……達摩克里斯的力量在減弱了！",
  ui_story_1011_10111501_42_dialog_content = "好。你們的力量怎麼樣？",
  ui_story_1011_10111501_43_dialog_content = "還能堅持但是……快到極限了！",
  ui_story_1011_10111501_44_dialog_content = "大家，都很努力......",
  ui_story_1011_10111501_45_dialog_content = "好熱……胸口在燃燒……",
  ui_story_1011_10111501_46_dialog_content = "……",
  ui_story_1011_10111501_47_dialog_content = "我明白了。",
  ui_story_1011_10111501_48_dialog_content = "我們來讓事情結束，這是最後一次。",
  ui_story_1011_10111501_49_dialog_content = "所有人，放出光能干擾達摩克里斯的光能傳輸！",
  ui_story_1011_10111501_50_dialog_content = "用全力將它的運行逆轉過來！",
  ui_story_1011_10111501_51_dialog_content = "是！",
  ui_story_1011_10111501_52_dialog_content = "<color=#e8d9bb>嗡——！</color>",
  ui_story_1011_10111501_53_dialog_content = "<color=#e8d9bb>嗡……</color>",
  ui_story_1011_10111501_54_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_1011_10111501_55_dialog_content = "哈......哈......哈......",
  ui_story_1011_10111501_56_dialog_content = "成功了嗎？它停下來了嗎？",
  ui_story_1011_10111501_57_dialog_content = "燃盡了……無論是我們……還是它……",
  ui_story_1011_10111501_58_dialog_content = "……",
  ui_story_1011_10111501_59_dialog_content = "城主大人，事情解決了嗎？",
  ui_story_1011_10111501_60_dialog_content = "嗯，這個房間裡的事情解決了。",
  ui_story_1011_10111501_61_dialog_content = "不過……",
  ui_story_1011_10111501_62_dialog_content = "達摩克里斯啊，你……",
  ui_story_1011_10111501_63_dialog_content = "究竟想指向哪裡？",
  ui_story_1011_10111501_64_dialog_content = "<color=#e8d9bb>嗡！嗡！嗡！嗡！</color>",
  ui_story_1011_10111501_65_dialog_content = "好吵啊喵！",
  ui_story_1011_10111501_66_dialog_content = "嗚嗚……菲莉詩的午覺……",
  ui_story_1011_10111501_67_dialog_content = "嗯？菲莉詩？",
  ui_story_1011_10111501_68_dialog_content = "妳又在工作時間睡覺了是吧！",
  ui_story_1011_10111501_69_dialog_content = "哎呀，怎麼能這麼說呢長官，我這不是清醒得很嗎。",
  ui_story_1011_10111501_70_dialog_content = "算了，下次再跟妳計較。",
  ui_story_1011_10111501_71_dialog_content = "現在這個吵吵鬧鬧的聲音到底是……",
  ui_story_1011_10111501_72_dialog_content = "<color=#e8d9bb>嗡！嗡！嗡！嗡！</color>",
  ui_story_1011_10111501_73_dialog_content = "吵死人了！這是什麼聲音啊！",
  ui_story_1011_10111501_74_dialog_content = "喂，有沒有人出來解釋一下！",
  ui_story_1011_10111501_75_dialog_content = "啊，希羅娜長官。",
  ui_story_1011_10111501_76_dialog_content = "您也......",
  ui_story_1011_10111501_77_dialog_content = "薇薇安，妳知道這個聲音是怎麼回事嗎？",
  ui_story_1011_10111501_78_dialog_content = "不知道，從來沒聽過這樣的聲音。",
  ui_story_1011_10111501_79_dialog_content = "怎麼誰都不知道。",
  ui_story_1011_10111501_80_dialog_content = "我可不想在戰場之外被迦南城的噪音吵死啊。",
  ui_story_1011_10111501_81_dialog_content = "也許是哪裡的設施出現了故障，我立刻安排人去查！",
  ui_story_1011_10111501_82_dialog_content = "<color=#e8d9bb>嗡！嗡！嗡！嗡！</color>",
  ui_story_1011_10111501_83_dialog_content = "情況就是這樣，現在迦南城裡所有地方都能聽到噪音。",
  ui_story_1011_10111501_84_dialog_content = "喔......喔......",
  ui_story_1011_10111501_85_dialog_content = "我讓維修工人們檢查了一下，聲音來源是牆體裡一些古老的設施。",
  ui_story_1011_10111501_86_dialog_content = "它們早就被鑑定為報廢，沒想到這次竟然能發出聲音……",
  ui_story_1011_10111501_87_dialog_content = "喔......喔......",
  ui_story_1011_10111501_88_dialog_content = "貢露，妳在聽嗎？",
  ui_story_1011_10111501_89_dialog_content = "嗯，我在聽我在聽。",
  ui_story_1011_10111501_90_dialog_content = "妳是說那個......嗯，對，就是那個。",
  ui_story_1011_10111501_91_dialog_content = "根本就沒有聽啊！",
  ui_story_1011_10111501_92_dialog_content = "先別看妳手裡的書了，這件事很重要。",
  ui_story_1011_10111501_93_dialog_content = "噪音已經在城裡引起騷亂和恐慌了。",
  ui_story_1011_10111501_94_dialog_content = "其他技術人員都束手無策，不知道妳能不能......",
  ui_story_1011_10111501_95_dialog_content = "噓——",
  ui_story_1011_10111501_96_dialog_content = "？！",
  ui_story_1011_10111501_97_dialog_content = "<color=#e8d9bb>嗡！嗡！嗡！嗡！</color>",
  ui_story_1011_10111501_98_dialog_content = "啊，是這樣。",
  ui_story_1011_10111501_99_dialog_content = "我明白了，我真的明白了。",
  ui_story_1011_10111501_100_dialog_content = "嗯？妳明白什麼了？",
  ui_story_1011_10111501_101_dialog_content = "不要因為難听就逃避啊，仔細去聽。",
  ui_story_1011_10111501_102_dialog_content = "這可不是簡單的噪音，這裡面……包含了一句話哦。",
  ui_story_1011_10111501_103_dialog_content = "一句話？ ！",
  ui_story_1011_10111501_104_dialog_content = "嗯，是非常古老的語言。",
  ui_story_1011_10111501_105_dialog_content = "讓我找找……302頁……564頁……",
  ui_story_1011_10111501_106_dialog_content = "啊，找到了！",
  ui_story_1011_10111501_107_dialog_content = "對古老語言的釋義大多數來自猜測，不敢說多麼準確。",
  ui_story_1011_10111501_108_dialog_content = "不過我猜它想傳達的意思是——",
  ui_story_1011_10111501_109_dialog_content = "<color=#FFB400>「快躲起來」。</color>",
  ui_story_1011_10111501_110_dialog_content = "來了啊，黑潮。",
  ui_story_1011_10111501_111_dialog_content = "哼，你做好覺悟了嗎？",
  ui_story_1011_10111501_112_dialog_content = "是你該做好覺悟吧，常敗將軍。",
  ui_story_1011_10111501_113_dialog_content = "那個侮辱性的頭銜以後再也不屬於我了！",
  ui_story_1011_10111501_114_dialog_content = "今天，大家會看到我堂堂正正地戰勝醒山！",
  ui_story_1011_10111501_115_dialog_content = "哦！這股勁頭很不錯啊！",
  ui_story_1011_10111501_116_dialog_content = "不過……大家？",
  ui_story_1011_10111501_117_dialog_content = "沒錯，我把紅油扳手所有人都叫上了。",
  ui_story_1011_10111501_118_dialog_content = "怎麼樣，要在眾目睽睽之下跟我交手，開始緊張了嗎？",
  ui_story_1011_10111501_119_dialog_content = "緊不緊張另說……人呢？",
  ui_story_1011_10111501_120_dialog_content = "我可沒看到大家啊。",
  ui_story_1011_10111501_121_dialog_content = "喂！大家！都出來吧！",
  ui_story_1011_10111501_122_dialog_content = "比試馬上就要開始了！",
  ui_story_1011_10111501_123_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_1011_10111501_124_dialog_content = "喂！！！",
  ui_story_1011_10111501_125_dialog_content = "我們該鼓掌嗎？",
  ui_story_1011_10111501_126_dialog_content = "加油......加油......",
  ui_story_1011_10111501_127_dialog_content = "哥哥一定會贏的！",
  ui_story_1011_10111501_128_dialog_content = "哈？怎麼就來了你們三個！",
  ui_story_1011_10111501_129_dialog_content = "大家對沒有懸念的比試已經不感興趣了。",
  ui_story_1011_10111501_130_dialog_content = "不如算了吧，黑潮。",
  ui_story_1011_10111501_131_dialog_content = "怎麼可能算啊！",
  ui_story_1011_10111501_132_dialog_content = "哥哥，要把他帥氣地打飛哦。",
  ui_story_1011_10111501_133_dialog_content = "嗯！伊芙想看的話我一定做到！",
  ui_story_1011_10111501_134_dialog_content = "想看他飛到哪邊？",
  ui_story_1011_10111501_135_dialog_content = "那個，醒山老大，可以別站在陸行者號上面打架嗎？",
  ui_story_1011_10111501_136_dialog_content = "算了，人少就人少吧。",
  ui_story_1011_10111501_137_dialog_content = "打贏你之後我來把這場英勇的戰鬥講給所有人聽！",
  ui_story_1011_10111501_138_dialog_content = "哈哈，放馬過來——",
  ui_story_1011_10111501_139_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_1011_10111501_140_dialog_content = "啊啊啊啊啊啊啊！",
  ui_story_1011_10111501_141_dialog_content = "怎麼回事！",
  ui_story_1011_10111501_142_dialog_content = "叭噗，不要隨便開動陸行者號啊！",
  ui_story_1011_10111501_143_dialog_content = "醒山老大，我在這裡啊。",
  ui_story_1011_10111501_144_dialog_content = "陸行者號上除了你沒有別人。",
  ui_story_1011_10111501_145_dialog_content = "哈？那是怎麼回事？ ！",
  ui_story_1011_10111501_146_dialog_content = "喂醒山，要逃跑嗎！",
  ui_story_1011_10111501_147_dialog_content = "誰逃跑了！是它自己——",
  ui_story_1011_10111501_148_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_1011_10111501_149_dialog_content = "哇啊啊啊啊啊啊！它加速了啊啊啊啊啊啊！",
  ui_story_1011_10111501_150_dialog_content = "喔哦，比想像中精彩啊。",
  ui_story_1011_10111501_151_dialog_content = "哥哥當逃兵，哥哥膽小鬼。",
  ui_story_1011_10111501_152_dialog_content = "不是啊！是陸行者號自己在發動！",
  ui_story_1011_10111501_153_dialog_content = "別看著了！快來幫幫我啊！",
  ui_story_1011_10111501_154_dialog_content = "喂！！！",
  ui_story_1011_10111501_155_dialog_content = "<color=#e8d9bb>扑騰、扑騰——</color>",
  ui_story_1011_10111501_156_dialog_content = "您好，這裡有寄給伊斯塔萬先生的緊急信件，請您簽收！",
  ui_story_1011_10111501_157_dialog_content = "好的，給我就可以了。",
  ui_story_1011_10111501_158_dialog_content = "等一下，寄信人是誰？",
  ui_story_1011_10111501_159_dialog_content = "信封上好像並沒有寫。",
  ui_story_1011_10111501_160_dialog_content = "啊對，是這樣的。",
  ui_story_1011_10111501_161_dialog_content = "寄給伊斯塔萬先生的緊急信件無需寫明寄信人。",
  ui_story_1011_10111501_162_dialog_content = "這是伊斯塔萬先生本人要求的。",
  ui_story_1011_10111501_163_dialog_content = "這樣啊，我明白了。",
  ui_story_1011_10111501_164_dialog_content = "謝謝妳。",
  ui_story_1011_10111501_165_dialog_content = "那麼信件送達，感謝您對信使公會的信任！再會！",
  ui_story_1011_10111501_166_dialog_content = "林好！這裡有寄給伊斯塔萬先森滴緊急信件，請林簽收！",
  ui_story_1011_10111501_167_dialog_content = "好的，又來一封嗎。",
  ui_story_1011_10111501_168_dialog_content = "辣個，信封桑沒有寫明寄信人，其實是因為……",
  ui_story_1011_10111501_169_dialog_content = "這是伊斯塔萬先生的要求，對吧？",
  ui_story_1011_10111501_170_dialog_content = "啊對滴！謝謝理解！",
  ui_story_1011_10111501_171_dialog_content = "給我就可以了，辛苦妳了。",
  ui_story_1011_10111501_172_dialog_content = "沒有關係沒有關係！辣麼，感謝林……",
  ui_story_1011_10111501_173_dialog_content = "啊啊啊啊要趕不上了要趕不上了！",
  ui_story_1011_10111501_174_dialog_content = "應該沒有晚太多吧？不會扣我的工資吧？",
  ui_story_1011_10111501_175_dialog_content = "誒，多孚你也來辣！",
  ui_story_1011_10111501_176_dialog_content = "唷，塔塔！妳也......",
  ui_story_1011_10111501_177_dialog_content = "算了有事待會再說，時間要趕不上了。",
  ui_story_1011_10111501_178_dialog_content = "您好，這裡有寄給伊斯塔萬先生的緊急信件，請您簽收！",
  ui_story_1011_10111501_179_dialog_content = "養父大人，剛才收到了幾封信使公會送來的緊急信件。",
  ui_story_1011_10111501_180_dialog_content = "緊急信件？拿給我看看。",
  ui_story_1011_10111501_181_dialog_content = "好。",
  ui_story_1011_10111501_182_dialog_content = "緊急信件啊，還一下好幾封。",
  ui_story_1011_10111501_183_dialog_content = "哪裡的動靜驚擾了這麼多麻雀？",
  ui_story_1011_10111501_184_dialog_content = "……",
  ui_story_1011_10111501_185_dialog_content = "看樣子驚擾的可不只是麻雀。",
  ui_story_1011_10111501_186_dialog_content = "涉，多派些人手，去盯死白夜城的動向。",
  ui_story_1011_10111501_187_dialog_content = "哪怕一個士兵拔出佩劍我也要第一時間知道。",
  ui_story_1011_10111501_188_dialog_content = "呵呵，這個簡單，我立刻就安排人去做。",
  ui_story_1011_10111501_189_dialog_content = "只是，不要做點其他準備嗎？",
  ui_story_1011_10111501_190_dialog_content = "等白夜城有所反應，我們再做出動作可能為時已晚。",
  ui_story_1011_10111501_191_dialog_content = "現在這樣就好。",
  ui_story_1011_10111501_192_dialog_content = "我們活在白夜城的遮蔽之下。",
  ui_story_1011_10111501_193_dialog_content = "影子，就要擺好影子的姿態。",
  ui_story_1011_10111501_194_dialog_content = "<color=#e8d9bb>噠、噠、噠……</color>",
  ui_story_1011_10111501_195_dialog_content = "維多利亞大人，您怎麼樣了？",
  ui_story_1011_10111501_196_dialog_content = "……",
  ui_story_1011_10111501_197_dialog_content = "不行，還是沒有回應。",
  ui_story_1011_10111501_198_dialog_content = "要不要進去看看？",
  ui_story_1011_10111501_199_dialog_content = "維多利亞大人剛才的神態，很讓人擔心。",
  ui_story_1011_10111501_200_dialog_content = "不行……絕對不可以……",
  ui_story_1011_10111501_201_dialog_content = "沒有得到許可就擅闖維多利亞大人的房間，這是何等的僭越……",
  ui_story_1011_10111501_202_dialog_content = "用不著那麼操心吧，維多利亞大人可能只是累了。",
  ui_story_1011_10111501_203_dialog_content = "除了圍在她身邊你們就沒有自己的事情做嗎？",
  ui_story_1011_10111501_204_dialog_content = "我再敲門試試吧。",
  ui_story_1011_10111501_205_dialog_content = "<color=#e8d9bb>噠、噠、噠……</color>",
  ui_story_1011_10111501_206_dialog_content = "維多利亞大人，發生什麼事情了嗎？",
  ui_story_1011_10111501_207_dialog_content = "……",
  ui_story_1011_10111501_208_dialog_content = "哎，看來……",
  ui_story_1011_10111501_209_dialog_content = "浮士德，你進來。",
  ui_story_1011_10111501_210_dialog_content = "！！！",
  ui_story_1011_10111501_211_dialog_content = "你一個人進來就夠了。我不想打擾到它。",
  ui_story_1011_10111501_212_dialog_content = "是。",
  ui_story_1011_10111501_213_dialog_content = "<color=#e8d9bb>吱——</color>",
  ui_story_1011_10111501_214_dialog_content = "維多利亞大人，您……",
  ui_story_1011_10111501_215_dialog_content = "你看。",
  ui_story_1011_10111501_216_dialog_content = "鮮血在血色邪典上流淌。",
  ui_story_1011_10111501_217_dialog_content = "從剛才，一直到現在。",
  ui_story_1011_10111501_218_dialog_content = "這是……新的啟示要出現了嗎？",
  ui_story_1011_10111501_219_dialog_content = "它花費的時間比以往更長。",
  ui_story_1011_10111501_220_dialog_content = "血液已經浸滿了房間的地毯，但書頁上還沒有隻言片語出現。",
  ui_story_1011_10111501_221_dialog_content = "有什麼東西是「真理」都羞於啟齒的嗎？",
  ui_story_1011_10111501_222_dialog_content = "怎麼會這樣……",
  ui_story_1011_10111501_223_dialog_content = "在這之前，在您的整個生命裡，發生過這樣的情況嗎？",
  ui_story_1011_10111501_224_dialog_content = "噓——",
  ui_story_1011_10111501_225_dialog_content = "要來了。",
  ui_story_1011_10111501_226_dialog_content = "它終於要來了。",
  ui_story_1011_10111501_227_dialog_content = "！！！",
  ui_story_1011_10111501_228_dialog_content = "「■■」",
  ui_story_1011_10111501_229_dialog_content = "「■■■■■■■■■■」",
  ui_story_1011_10111501_230_dialog_content = "什麼？！",
  ui_story_1011_10111501_231_dialog_content = "沒有見過的文字！維多利亞大人，這是什麼意思？",
  ui_story_1011_10111501_232_dialog_content = "啊，血色邪典。",
  ui_story_1011_10111501_233_dialog_content = "你想要展現的啟示，並不是給我們看的，對嗎？",
  ui_story_1011_10111501_234_dialog_content = "能看懂這些文字的人，能得到啟示的人，究竟是誰呢……",
  ui_story_1011_10111501_235_dialog_content = "嗚哇，好刺眼啊。",
  ui_story_1011_10111501_236_dialog_content = "咦？太陽剛剛不是下山了嗎？",
  ui_story_1011_10111501_237_dialog_content = "那個不是太陽！",
  ui_story_1011_10111501_238_dialog_content = "那好像是……海邊的燈塔？",
  ui_story_1011_10111501_239_dialog_content = "看起來好像是哦！",
  ui_story_1011_10111501_240_dialog_content = "但是燈塔平時有這麼亮嗎？",
  ui_story_1011_10111501_241_dialog_content = "諾維亞，女王陛下在冬宮嗎？",
  ui_story_1011_10111501_242_dialog_content = "嗯，她在。",
  ui_story_1011_10111501_243_dialog_content = "妳頭上好多汗，發生什麼事情了？",
  ui_story_1011_10111501_244_dialog_content = "燈塔閃亮得非比尋常，我擔心……",
  ui_story_1011_10111501_245_dialog_content = "是不是守護北境的力量出現了問題。",
  ui_story_1011_10111501_246_dialog_content = "原來如此，這確實是非常重要的事情。",
  ui_story_1011_10111501_247_dialog_content = "走，我們一起去見女王。",
  ui_story_1011_10111501_248_dialog_content = "<color=#e8d9bb>嗒......嗒......嗒......</color>",
  ui_story_1011_10111501_249_dialog_content = "女王陛下，娜席里絲來見您。",
  ui_story_1011_10111501_250_dialog_content = "她說……",
  ui_story_1011_10111501_251_dialog_content = "它在看著……",
  ui_story_1011_10111501_252_dialog_content = "嗯？這是……",
  ui_story_1011_10111501_253_dialog_content = "它在看著……它在……看……",
  ui_story_1011_10111501_254_dialog_content = "女王陛下在睡覺。",
  ui_story_1011_10111501_255_dialog_content = "我們該吵醒她嗎？",
  ui_story_1011_10111501_256_dialog_content = "既然是燈塔發生了異常，女王一定想第一時間知道。",
  ui_story_1011_10111501_257_dialog_content = "妳去女王耳邊說給她聽吧。",
  ui_story_1011_10111501_258_dialog_content = "好。",
  ui_story_1011_10111501_259_dialog_content = "女王陛下。",
  ui_story_1011_10111501_260_dialog_content = "燈塔現在正如太陽般閃耀。",
  ui_story_1011_10111501_261_dialog_content = "大家有些惶恐，究竟是什麼要奪走北境的黑夜？",
  ui_story_1011_10111501_262_dialog_content = "它在看著我們……它在天幕之上……",
  ui_story_1011_10111501_263_dialog_content = "高塔......高高在上的眼睛......",
  ui_story_1011_10111501_264_dialog_content = "女王陛下？",
  ui_story_1011_10111501_265_dialog_content = "逃走……躲起來……越遠越好……",
  ui_story_1011_10111501_266_dialog_content = "去群山之巔……去海上孤島……",
  ui_story_1011_10111501_267_dialog_content = "諾維亞，女王陛下的神色看起來不太對。",
  ui_story_1011_10111501_268_dialog_content = "嗯。",
  ui_story_1011_10111501_269_dialog_content = "女王陛下，您該醒來了。",
  ui_story_1011_10111501_270_dialog_content = "遠離那個地方……",
  ui_story_1011_10111501_271_dialog_content = "高塔......",
  ui_story_1011_10111501_272_dialog_content = "遠離……高塔之城……",
  ui_story_1011_10111501_273_dialog_content = "女王陛下！",
  ui_story_1011_10111501_274_dialog_content = "女王陛下！！！",
  ui_story_1011_10111501_275_dialog_content = "……",
  ui_story_1011_10111501_276_dialog_content = "女王陛下，您......",
  ui_story_1011_10111501_277_dialog_content = "<color=#FFB400>PlayerName，是你。</color>",
  ui_story_1011_10111501_278_dialog_content = "！！！",
  ui_story_1011_10111501_279_dialog_content = "不是的，女王陛下！我......",
  ui_story_1011_10111501_280_dialog_content = "欸？",
  ui_story_1011_10111501_281_dialog_content = "為什麼……為什麼會發生這種事情……",
  ui_story_1011_10111501_282_dialog_content = "PlayerName，你怎麼了？",
  ui_story_1011_10111501_283_dialog_content = "我怎麼了，我……",
  ui_story_1011_10111501_284_dialog_content = "雖然聽起來可能有點誇張，但是……",
  ui_story_1011_10111501_285_dialog_content = "就在剛剛，我千真萬確地看到了。",
  ui_story_1011_10111501_286_dialog_content = "看到了什麼？",
  ui_story_1011_10111501_287_dialog_content = "我看到了<color=#FFB400>整個世界</color>。",
  ui_story_1012_10120101_1_dialog_content = "那一刻，我看到了整個世界。",
  ui_story_1012_10120101_2_dialog_content = "從啟光到白夜城。",
  ui_story_1012_10120101_3_dialog_content = "從北境到紅油沙漠。",
  ui_story_1012_10120101_4_dialog_content = "在那一瞬間，盡收眼底。",
  ui_story_1012_10120101_5_dialog_content = "彷彿我已經不再是我......",
  ui_story_1012_10120101_6_dialog_content = "而成了這座回歸塔本身。",
  ui_story_1012_10120101_7_dialog_content = "真奇怪，過去的記錄從不曾記載空裔擁有這樣的科技。",
  ui_story_1012_10120101_8_dialog_content = "不，先不管這個。",
  ui_story_1012_10120101_9_dialog_content = "假如這台機器是這座基地的核心，那它應該知道拯救薇絲的辦法！",
  ui_story_1012_10120101_10_dialog_content = "對啊，輔腦，查詢從「識泯」狀態復甦之案例的詳細情況！",
  ui_story_1012_10120101_11_dialog_content = "權限驗證通過，正在生成報告。",
  ui_story_1012_10120101_12_dialog_content = "將處於「識泯」狀態的實驗體置入<color=#FFB400>「和弦紐帶」</color>設備，結合「同調」功能進行嘗試。",
  ui_story_1012_10120101_13_dialog_content = "實驗產生了預期之外的正向治療效果。",
  ui_story_1012_10120101_14_dialog_content = "觀測到實驗體的意識出現復甦跡象，同時發生身體變化。",
  ui_story_1012_10120101_15_dialog_content = "身體變化的副作用尚不明確。",
  ui_story_1012_10120101_16_dialog_content = "最終，實驗體「同調」成功，並從「識泯」下復甦。",
  ui_story_1012_10120101_17_dialog_content = "「和弦紐帶」......",
  ui_story_1012_10120101_18_dialog_content = "那是什麼東西？",
  ui_story_1012_10120101_19_dialog_content = "正在搜尋「和弦紐帶」的相關資訊。",
  ui_story_1012_10120101_20_dialog_content = "......",
  ui_story_1012_10120101_21_dialog_content = "............",
  ui_story_1012_10120101_22_dialog_content = "#*%￥&￥#&*！",
  ui_story_1012_10120101_23_dialog_content = "輔腦？！",
  ui_story_1012_10120101_24_dialog_content = "已結束錯誤進程。",
  ui_story_1012_10120101_25_dialog_content = "與「和弦紐帶」相關的實驗資料儲存於和弦區，平時不對外開放。",
  ui_story_1012_10120101_26_dialog_content = "這麼嚴格保密？",
  ui_story_1012_10120101_27_dialog_content = "聽起來就像某種很重要的設施。",
  ui_story_1012_10120101_28_dialog_content = "說不定，這座白塔內最重要的不是環狀系統......",
  ui_story_1012_10120101_29_dialog_content = "而是這個「和弦紐帶」。",
  ui_story_1012_10120101_30_dialog_content = "輔腦，有沒有和弦區的詳細資料？",
  ui_story_1012_10120101_31_dialog_content = "輔腦與和弦區的連結已中斷，無法讀取資料！",
  ui_story_1012_10120101_32_dialog_content = "本地資料庫中關於該設備的描述如下——",
  ui_story_1012_10120101_33_dialog_content = "「和弦紐帶」可以治癒傷口，部分改造光靈的軀體，激發光靈的潛能。",
  ui_story_1012_10120101_34_dialog_content = "使光靈更善於配合空裔進行戰鬥。",
  ui_story_1012_10120101_35_dialog_content = "這......怎麼像某種改造裝置？",
  ui_story_1012_10120101_36_dialog_content = "不，不對。如果過去的空裔將光靈視為敵人......",
  ui_story_1012_10120101_37_dialog_content = "那為什麼這裡會出現能改造光靈，並讓光靈配合空裔戰鬥的儀器？",
  ui_story_1012_10120101_38_dialog_content = "妳說得對，這太奇怪了。",
  ui_story_1012_10120101_39_dialog_content = "PlayerName，我們不該輕信這台設備的記載。",
  ui_story_1012_10120101_40_dialog_content = "要先弄清楚「和弦紐帶」的真正用途，以及有沒以可能給薇絲帶來傷害。",
  ui_story_1012_10120101_41_dialog_content = "嗯，我知道了。",
  ui_story_1012_10120101_42_dialog_content = "輔腦，「和弦紐帶」有副作用嗎？",
  ui_story_1012_10120101_43_dialog_content = "會不會對薇絲產生不好的影響？",
  ui_story_1012_10120101_44_dialog_content = "輔腦與和弦區的連結已中斷，無法讀取資料！",
  ui_story_1012_10120101_45_dialog_content = "中斷這麼久，你沒試著修過嗎？",
  ui_story_1012_10120101_46_dialog_content = "輔腦純是為空裔提供幫助的系統。",
  ui_story_1012_10120101_47_dialog_content = "禁止強迫輔腦執行非本職工作的維修任務！",
  ui_story_1012_10120101_48_dialog_content = "看起來沒辦法從這裡找到相關資訊啊......",
  ui_story_1012_10120101_49_dialog_content = "沒辦法了。",
  ui_story_1012_10120101_50_dialog_content = "就算冒險，也得試一試才行。",
  ui_story_1012_10120101_51_dialog_content = "薇絲是因為我才變成這樣。",
  ui_story_1012_10120101_52_dialog_content = "我會為此負起責任，哪怕......",
  ui_story_1012_10120101_53_dialog_content = "......",
  ui_story_1012_10120101_54_dialog_content = "到時候由我先用那個設備試一試。",
  ui_story_1012_10120101_55_dialog_content = "如果沒有問題，再用它救薇絲。",
  ui_story_1012_10120101_56_dialog_content = "萬一還是不行......到時候就拜託卡蓮把薇絲帶回啟光求救囉。",
  ui_story_1012_10120101_57_dialog_content = "這份心意不錯，但是別忘了，你是空裔，不是光靈。",
  ui_story_1012_10120101_58_dialog_content = "薇絲是我的朋友，為了救她，我也會出一份力。",
  ui_story_1012_10120101_59_dialog_content = "如果不得不那麼做的話，還是由我來試吧。",
  ui_story_1012_10120101_60_dialog_content = "輔腦，帶我去找這個設備。",
  ui_story_1012_10120101_61_dialog_content = "正在計算前往和弦區的路線——",
  ui_story_1012_10120101_62_dialog_content = "偵測到大部分通往和弦區的通道已坍塌，管理者需繞道放逐區以前往。",
  ui_story_1012_10120101_63_dialog_content = "由於和弦區與輔腦連接中斷，輔腦無法直接開啟大門。",
  ui_story_1012_10120101_64_dialog_content = "根據最新設定，已為管理員生成門禁系統解鎖密鑰。",
  ui_story_1012_10120101_65_dialog_content = "本設定的前次更改者：弗朗茨老師。",
  ui_story_1012_10120101_66_dialog_content = "又是這個弗朗茨老師？",
  ui_story_1012_10120101_67_dialog_content = "這個人，究竟在計劃著什麼呢？",
  ui_story_1012_10120101_68_dialog_content = "我感覺他不像是在計劃。",
  ui_story_1012_10120101_69_dialog_content = "而更像是在為後到的某人鋪路，進行準備作業。",
  ui_story_1012_10120101_70_dialog_content = "比如......我們。",
  ui_story_1012_10120101_71_dialog_content = "請管理者跟隨輔腦前往和弦區，輔腦將為您破解和弦區門禁系統。",
  ui_story_1012_10120101_72_dialog_content = "和弦區與放逐區相連？",
  ui_story_1012_10120101_73_dialog_content = "怎麼聽起來不像個好地方......",
  ui_story_1012_10120101_74_dialog_content = "無論好不好，那裡都是我們僅存的希望。",
  ui_story_1012_10120101_75_dialog_content = "我們走，帶薇絲去和弦區。",
  ui_story_1012_10120101_76_dialog_content = "輔腦，麻煩你指路。",
  ui_story_1012_10120101_77_dialog_content = "遵命，輔腦導航為您服務！",
  ui_story_1012_10120101_78_dialog_content = "「和弦紐帶」......",
  ui_story_1012_10120101_79_dialog_content = "這就是這座地下基地埋藏的技術嗎？",
  ui_story_1012_10120101_80_dialog_content = "能夠改造光靈的身體......",
  ui_story_1012_10120101_81_dialog_content = "倒是正合我意。",
  ui_story_1012_10120101_82_dialog_content = "（日蝕語）吞羅大人，那名啟光人追得很緊。",
  ui_story_1012_10120101_83_dialog_content = "（日蝕語）他......太強了，我們攔不住他。",
  ui_story_1012_10120101_84_dialog_content = "啟光的人，都是怪物。",
  ui_story_1012_10120101_85_dialog_content = "如果攔不住，想辦法把他引到錯誤的路上去。",
  ui_story_1012_10120101_86_dialog_content = "不要讓那個莽夫接近珍貴的科技。",
  ui_story_1012_10120101_87_dialog_content = "他的腦子裡只有戰鬥和破壞。",
  ui_story_1012_10120101_88_dialog_content = "（日蝕語）是。",
  ui_story_1012_10120101_89_dialog_content = "伊倫汀，不要攔我。",
  ui_story_1012_10120101_90_dialog_content = "元老院有權知道達摩克里斯啟動的原因。",
  ui_story_1012_10120101_91_dialog_content = "城主大人已經下令，禁止任何人進入控制室。",
  ui_story_1012_10120101_92_dialog_content = "城主的命令就是白夜城的律法，我想您應該知道。",
  ui_story_1012_10120101_93_dialog_content = "奧托大人，就算是元老院的一員，您也仍在法律的約束之下。",
  ui_story_1012_10120101_94_dialog_content = "元老院的權利也是白夜城法律的一部分。",
  ui_story_1012_10120101_95_dialog_content = "伊倫汀審判長，我必須告訴妳，妳現在——",
  ui_story_1012_10120101_96_dialog_content = "達摩克里斯停下了？",
  ui_story_1012_10120101_97_dialog_content = "（城主大人和四天使他們成功了？）",
  ui_story_1012_10120101_98_dialog_content = "舒瓦茲城主......",
  ui_story_1012_10120101_99_dialog_content = "請告訴我，控制室裡發生什麼事，為何達摩克里斯會突然啟動？",
  ui_story_1012_10120101_100_dialog_content = "稍安勿躁，奧托，稍安勿躁。",
  ui_story_1012_10120101_101_dialog_content = "達摩克里斯確實毫無徵兆擅自啟動，但是，我已經讓它停了下來。",
  ui_story_1012_10120101_102_dialog_content = "現在，它回歸白夜城的掌控。",
  ui_story_1012_10120101_103_dialog_content = "擅自啟動......怎麼可能？",
  ui_story_1012_10120101_104_dialog_content = "達摩克里斯是一件強大的武器，但充其量就只是一件武器。",
  ui_story_1012_10120101_105_dialog_content = "若非有人操縱，怎麼可能擅自啟動？",
  ui_story_1012_10120101_106_dialog_content = "在此之前，有一點我必須聲明。",
  ui_story_1012_10120101_107_dialog_content = "達摩克里斯確實是白夜城的武器，但是......",
  ui_story_1012_10120101_108_dialog_content = "它並不完全屬於白夜城。",
  ui_story_1012_10120101_109_dialog_content = "......",
  ui_story_1012_10120101_110_dialog_content = "歸根究柢，它仍舊是我們從未見過的上古之民的遺留物，是白夜城最為排斥的東西。",
  ui_story_1012_10120101_111_dialog_content = "不屬於自己的未知力量，本身就存在著失控的可能。",
  ui_story_1012_10120101_112_dialog_content = "我會下令負責維護達摩克里斯的技術人員進行全面檢查，找出失控的原因。",
  ui_story_1012_10120101_113_dialog_content = "明天之前給出結果。",
  ui_story_1012_10120101_114_dialog_content = "那就有勞你了。",
  ui_story_1012_10120101_115_dialog_content = "當然，維護白夜城的安全與繁榮是我們的第一要務。",
  ui_story_1012_10120101_116_dialog_content = "......",
  ui_story_1012_10120101_117_dialog_content = "達摩克里斯......",
  ui_story_1012_10120101_118_dialog_content = "你所指的方向是......",
  ui_story_1012_10120101_119_dialog_content = "......",
  ui_story_1012_10120101_120_dialog_content = "拉斐爾。",
  ui_story_1012_10120101_121_dialog_content = "啊，是......是！",
  ui_story_1012_10120101_122_dialog_content = "城主大人有何命令？",
  ui_story_1012_10120101_123_dialog_content = "去找貝爾塔，讓她帶一隊騎士，火速趕往空谷。",
  ui_story_1012_10120101_124_dialog_content = "好的，但是，要小貝爾塔去做什麼呢？",
  ui_story_1012_10120101_125_dialog_content = "隨機應變。",
  ui_story_1012_10120101_126_dialog_content = "欸——？！",
  ui_story_1012_10120101_127_dialog_content = "去吧。",
  ui_story_1012_10120101_128_dialog_content = "好，好的！",
  ui_story_1012_10120101_129_dialog_content = "女王陛下，您......",
  ui_story_1012_10120101_130_dialog_content = "我沒事。",
  ui_story_1012_10120101_131_dialog_content = "抱歉，讓你們擔心了。",
  ui_story_1012_10120101_132_dialog_content = "有件事我必須稟報，燈塔出現了問題，它正散發著前所未有的強烈光芒。",
  ui_story_1012_10120101_133_dialog_content = "知道了。",
  ui_story_1012_10120101_134_dialog_content = "這件事，我會處理，你們無需擔憂。",
  ui_story_1012_10120101_135_dialog_content = "是......",
  ui_story_1012_10120101_136_dialog_content = "陛下，您在半夢半醒中，提及了那位空裔的名字。",
  ui_story_1012_10120101_137_dialog_content = "這想必不是偶然的事件吧。",
  ui_story_1012_10120101_138_dialog_content = "......",
  ui_story_1012_10120101_139_dialog_content = "我看見他站在高塔上，俯視世界。",
  ui_story_1012_10120101_140_dialog_content = "那座塔，是連我也無法透徹理解的存在。",
  ui_story_1012_10120101_141_dialog_content = "它築於遠古，源自未知。",
  ui_story_1012_10120101_142_dialog_content = "它與守護北境的燈塔，勢如水火。",
  ui_story_1012_10120101_143_dialog_content = "那位空裔......成了敵對勢力？",
  ui_story_1012_10120101_144_dialog_content = "不，我從他身上感知不到到任何敵意。",
  ui_story_1012_10120101_145_dialog_content = "他依舊如過去那樣，懷著單純的善良。",
  ui_story_1012_10120101_146_dialog_content = "但是，我能感知到，他正在經歷前所未有的困境。",
  ui_story_1012_10120101_147_dialog_content = "而這困境，將會影響整個艾斯特拉的命運。",
  ui_story_1012_10120101_148_dialog_content = "北境，必須做出抉擇。",
  ui_story_1012_10120101_149_dialog_content = "準備馬車。",
  ui_story_1012_10120101_150_dialog_content = "我要前往空之山谷，為這困境帶來轉機。",
  ui_story_1012_10120101_151_dialog_content = "是！",
  ui_story_1012_10120101_152_dialog_content = "陛下，馬車準備好了。",
  ui_story_1012_10120101_153_dialog_content = "嗯，我們立刻動身。",
  ui_story_1012_10120101_154_dialog_content = "陛下，請讓我與您一同前往空之山谷。",
  ui_story_1012_10120101_155_dialog_content = "不，我需要妳留下。",
  ui_story_1012_10120101_156_dialog_content = "我不在北境的期間，妳要做好守衛工作，注意暗鬼的動向。",
  ui_story_1012_10120101_157_dialog_content = "其餘事務照常進行，不必因我不在而推遲。",
  ui_story_1012_10120101_158_dialog_content = "提亞拉會與我同行。",
  ui_story_1012_10120101_159_dialog_content = "......",
  ui_story_1012_10120101_160_dialog_content = "提亞拉，奉命前來。",
  ui_story_1012_10120101_161_dialog_content = "原來是妳......",
  ui_story_1012_10120101_162_dialog_content = "那麼，請妳保護好陛下，保護好北境的希望之火。",
  ui_story_1012_10120101_163_dialog_content = "報......報告喵！",
  ui_story_1012_10120101_164_dialog_content = "迦南城各個地方都出現了異常的聲響。",
  ui_story_1012_10120101_165_dialog_content = "貢露科研長認為是來自地下城牆內，遠古儀器的警報喵。",
  ui_story_1012_10120101_166_dialog_content = "知道了，繼續檢查迦南城內的情況。",
  ui_story_1012_10120101_167_dialog_content = "同時向其他地下城詢問，當地是否發生類似的情況。",
  ui_story_1012_10120101_168_dialog_content = "是喵！",
  ui_story_1012_10120101_169_dialog_content = "大元帥，我的偵查兵發現了暗鬼的異常活動。",
  ui_story_1012_10120101_170_dialog_content = "整個艾斯特拉的暗鬼同時往空之山谷聚集。",
  ui_story_1012_10120101_171_dialog_content = "我知道了，維持各地下城的防禦狀態，繼續觀察。",
  ui_story_1012_10120101_172_dialog_content = "是。",
  ui_story_1012_10120101_173_dialog_content = "暗鬼聚集，空之山谷，還有迦南城遠古設備的異常聲響......",
  ui_story_1012_10120101_174_dialog_content = "那小子又惹了什麼麻煩？",
  ui_story_1012_10120101_175_dialog_content = "呵，他還真會挑時候。",
  ui_story_1012_10120101_176_dialog_content = "報告。",
  ui_story_1012_10120101_177_dialog_content = "唉......我就知道這事沒完沒了。",
  ui_story_1012_10120101_178_dialog_content = "說吧，又怎麼了？",
  ui_story_1012_10120101_179_dialog_content = "委員會收到報告，位於空之山谷的一座白塔突然啟動。",
  ui_story_1012_10120101_180_dialog_content = "在那之後，位於各地的遠古科技遺留物集體產生異常反應。",
  ui_story_1012_10120101_181_dialog_content = "喔？",
  ui_story_1012_10120101_182_dialog_content = "其中包括北境的燈塔、白夜城的達摩克里斯、紅油扳手掌控的陸行者號等......",
  ui_story_1012_10120101_183_dialog_content = "現在委員會高度懷疑，迦南城中的異常也與此相關。",
  ui_story_1012_10120101_184_dialog_content = "能讓燈塔和達摩克里斯都產生反應？",
  ui_story_1012_10120101_185_dialog_content = "PlayerName，你究竟挖了什麼鬼東西出來......",
  ui_story_1012_10120101_186_dialog_content = "大元帥，請您指示。",
  ui_story_1012_10120101_187_dialog_content = "讓我想想......",
  ui_story_1012_10120101_188_dialog_content = "通知空之山谷附近的各個小隊，向臨時啟動的白塔移動。",
  ui_story_1012_10120101_189_dialog_content = "沿途如遇暗鬼，就地阻擊，防止暗鬼集結。",
  ui_story_1012_10120101_190_dialog_content = "另外，立刻召集一支精銳部隊，由我帶隊，前往空之山谷探明情況。",
  ui_story_1012_10120101_191_dialog_content = "是，我立刻去——",
  ui_story_1012_10120101_192_dialog_content = "恕我直言，大元帥，您在80號地下城受的傷尚未恢復，不適合親自出征。",
  ui_story_1012_10120101_193_dialog_content = "......",
  ui_story_1012_10120101_194_dialog_content = "阿納托利，去做你該做的。",
  ui_story_1012_10120101_195_dialog_content = "是。",
  ui_story_1012_10120101_196_dialog_content = "萊因哈特大元帥，我必須提醒您，您仍舊處於委員會的審查期中。",
  ui_story_1012_10120101_197_dialog_content = "冒然行動可能會影響委員會對您的評價。",
  ui_story_1012_10120101_198_dialog_content = "究竟是寫在紙上的評價重要，還是啟光的安危更重要？",
  ui_story_1012_10120101_199_dialog_content = "......啟光的安危更重要。",
  ui_story_1012_10120101_200_dialog_content = "既然你明白這個道理，就做好你的本職工作。",
  ui_story_1012_10120101_201_dialog_content = "我也會做好大元帥該做的事。",
  ui_story_1012_10120101_202_dialog_content = "我會將您的行為寫在調查報告上。",
  ui_story_1012_10120101_203_dialog_content = "呵，隨你寫，無妨。",
  ui_story_1012_10120101_204_dialog_content = "我的決策是好是壞，啟光的人民自有評價。",
  ui_story_1012_10120201_1_dialog_content = "嘎嗷——",
  ui_story_1012_10120201_2_dialog_content = "這就是最後一隻了嗎？",
  ui_story_1012_10120201_3_dialog_content = "真不爽。",
  ui_story_1012_10120201_4_dialog_content = "全是一群擋路的雜兵，礙手礙腳。",
  ui_story_1012_10120201_5_dialog_content = "吞羅那傢伙也不知跑到哪裡去了？",
  ui_story_1012_10120201_6_dialog_content = "嘖......得快點找到她才行。",
  ui_story_1012_10120201_7_dialog_content = "這個地方，剛才好像來過？",
  ui_story_1012_10120201_8_dialog_content = "這些老古董，怎麼這麼喜歡把每個地方都蓋得一模一樣啊？",
  ui_story_1012_10120201_9_dialog_content = "簡直就像一個迷宮。",
  ui_story_1012_10120201_10_dialog_content = "難不成......那群暗鬼故意把我引來這裡？",
  ui_story_1012_10120201_11_dialog_content = "......這絕對是吞羅的陰謀！",
  ui_story_1012_10120201_12_dialog_content = "妳想把我困在迷宮裡，我就連同迷宮一起打穿。",
  ui_story_1012_10120201_13_dialog_content = "<color=#e8d9bb>喀——！</color>",
  ui_story_1012_10120201_14_dialog_content = "——！",
  ui_story_1012_10120201_15_dialog_content = "嘶——",
  ui_story_1012_10120201_16_dialog_content = "痛痛痛——！",
  ui_story_1012_10120201_17_dialog_content = "這牆究竟用了什麼材質打造？怎麼這麼結實？！",
  ui_story_1012_10120201_18_dialog_content = "刀砍上去不僅沒留下一點痕跡，反而把我手掌虎口一帶震麻了。",
  ui_story_1012_10120201_19_dialog_content = "要是能拆下來裝在地下城的牆上，或者裝在戰車上用來對付暗鬼不知該多好。",
  ui_story_1012_10120201_20_dialog_content = "看起來把牆打穿的戰術是行不通。",
  ui_story_1012_10120201_21_dialog_content = "只能順著這些通道前進了。",
  ui_story_1012_10120201_22_dialog_content = "不過，既然吞羅是那群暗鬼的頭子，往暗鬼多的地方走，準沒錯。",
  ui_story_1012_10120201_23_dialog_content = "就是要多花點時間清理雜兵罷了。",
  ui_story_1012_10120201_24_dialog_content = "<color=#e8d9bb>空之山谷·巨像整備基地深處</color>",
  ui_story_1012_10120201_25_dialog_content = "請在前方路口右轉。",
  ui_story_1012_10120201_26_dialog_content = "這個基地可真大......",
  ui_story_1012_10120201_27_dialog_content = "如果沒有輔腦指路，我們恐怕得在錯綜複雜的通道裡浪費好幾天時間。",
  ui_story_1012_10120201_28_dialog_content = "算上坍塌的區域，說不定這座地下基地滿佈整個空谷地區之下。",
  ui_story_1012_10120201_29_dialog_content = "尤其是這些看起來像通道一樣的地方。",
  ui_story_1012_10120201_30_dialog_content = "這個寬度和高度，明顯不是單純供人通過的用途。",
  ui_story_1012_10120201_31_dialog_content = "剛來到這裡時，我還有點想不明白，但是現在我想到了......",
  ui_story_1012_10120201_32_dialog_content = "這些通道，說不定是用來讓巨像通過。",
  ui_story_1012_10120201_33_dialog_content = "……",
  ui_story_1012_10120201_34_dialog_content = "而你們只負責為世界——",
  ui_story_1012_10120201_35_dialog_content = "帶來戰爭。",
  ui_story_1012_10120201_36_dialog_content = "空裔駕駛著巨像在這裡穿梭，卻不是為了和平......",
  ui_story_1012_10120201_37_dialog_content = "空裔一族，到底是為了什麼？",
  ui_story_1012_10120201_38_dialog_content = "PlayerName。",
  ui_story_1012_10120201_39_dialog_content = "在空裔的身分之前，你得先是你自己。",
  ui_story_1012_10120201_40_dialog_content = "欸……？",
  ui_story_1012_10120201_41_dialog_content = "對於現在的我們來說，你就是你。",
  ui_story_1012_10120201_42_dialog_content = "你是薇絲從地底救出的空之末裔。",
  ui_story_1012_10120201_43_dialog_content = "你是協助白夜城對抗舒默和黑色巨像的夥伴。",
  ui_story_1012_10120201_44_dialog_content = "你也是與我們一同經歷無數冒險的夥伴。",
  ui_story_1012_10120201_45_dialog_content = "只要你還是你，還保持著你的善良與原則，我們也就不會介意你是空裔還是光靈。",
  ui_story_1012_10120201_46_dialog_content = "畢竟出身不能選擇，你不需要為此承擔罪責。",
  ui_story_1012_10120201_47_dialog_content = "卡蓮……",
  ui_story_1012_10120201_48_option_content = "謝謝妳安慰我",
  ui_story_1012_10120201_49_dialog_content = "但是，這件事我仍得繼續追查。",
  ui_story_1012_10120201_50_dialog_content = "我是最後的空裔。",
  ui_story_1012_10120201_51_dialog_content = "且目前看起來，我可能也是這個世界上僅存能夠揭開空谷祕密的人。",
  ui_story_1012_10120201_52_dialog_content = "如果空裔一族過去真的是戰爭機器，那麼......",
  ui_story_1012_10120201_53_dialog_content = "不管是空谷，還是空裔，都可能會成為這個世界的威脅。",
  ui_story_1012_10120201_54_dialog_content = "如果不徹底查清楚，解決可能存在的隱患，我可能再也無法安心入眠。",
  ui_story_1012_10120201_55_dialog_content = "因為我不想成為會威脅到我朋友安危的存在。",
  ui_story_1012_10120201_56_dialog_content = "……",
  ui_story_1012_10120201_57_dialog_content = "別勉強你自己。",
  ui_story_1012_10120201_58_dialog_content = "嗯……",
  ui_story_1012_10120201_59_dialog_content = "放心吧，我對自己有清醒的認識。",
  ui_story_1012_10120201_60_dialog_content = "<size=30>隨便來隻暗鬼都可以一拳打飛我......</size>",
  ui_story_1012_10120201_61_dialog_content = "所以，該依靠你們幫忙的時候，就拜託你們啦......",
  ui_story_1012_10120201_62_dialog_content = "嗯。",
  ui_story_1012_10120201_63_dialog_content = "<color=#e8d9bb>喀——！！！</color>",
  ui_story_1012_10120201_64_dialog_content = "什麼聲音？！",
  ui_story_1012_10120201_65_dialog_content = "難不成有大隻暗鬼跑進來？",
  ui_story_1012_10120201_66_dialog_content = "聽起來離這裡不算太遠。",
  ui_story_1012_10120201_67_dialog_content = "我們快離開這裡，繼續前進吧。",
  ui_story_1012_10120201_68_dialog_content = "現在薇絲昏迷，戰鬥起來會很吃力。",
  ui_story_1012_10120201_69_dialog_content = "等等！",
  ui_story_1012_10120201_70_dialog_content = "怎麼了？",
  ui_story_1012_10120201_71_dialog_content = "我好像......感應到了暗鬼！",
  ui_story_1012_10120201_72_dialog_content = "在後面！",
  ui_story_1012_10120201_73_dialog_content = "嘎嗷——",
  ui_story_1012_10120201_74_dialog_content = "——！",
  ui_story_1012_10120201_75_dialog_content = "究竟是從哪裡冒出來的？！",
  ui_story_1012_10120201_76_dialog_content = "PlayerName，支援！",
  ui_story_1012_10120201_77_dialog_content = "好的！",
  ui_story_1012_10120202_1_dialog_content = "怎麼突然冒出這麼多暗鬼......",
  ui_story_1012_10120202_2_dialog_content = "而且剛才那麼長一段時間，我竟然毫無感應！",
  ui_story_1012_10120202_3_dialog_content = "畢竟這裡荒廢了不知多長時間。",
  ui_story_1012_10120202_4_dialog_content = "不管是原本就存在抑或後來坍塌而形成，這座地下基地裡恐怕還有數不清的密道。",
  ui_story_1012_10120202_5_dialog_content = "說不定那些暗鬼就利用某一條我們不知道的密道裡鑽出來。",
  ui_story_1012_10120202_6_dialog_content = "妳說得對......",
  ui_story_1012_10120202_7_dialog_content = "這裡的地形太複雜了，就算是我的感應能力也不一定能感應到所有暗鬼。",
  ui_story_1012_10120202_8_dialog_content = "我們還是快走吧，此地不宜久留！",
  ui_story_1012_10120202_9_dialog_content = "這裡連個岔路口都沒有，萬一被前後夾擊，我們可就跑不掉了。",
  ui_story_1012_10120202_10_dialog_content = "......",
  ui_story_1012_10120202_11_dialog_content = "空裔的感應能力，確實非常不好對付。",
  ui_story_1012_10120202_12_dialog_content = "不過，暗鬼要多少有多少。",
  ui_story_1012_10120202_13_dialog_content = "實驗的結果，也經常誕生於無數的犧牲之下。",
  ui_story_1012_10120202_14_dialog_content = "剛才那個動靜是？",
  ui_story_1012_10120202_15_dialog_content = "（日蝕語）吞羅大人，剛才的震動是那啟光人試圖破壞牆壁而造成。",
  ui_story_1012_10120202_16_dialog_content = "（日蝕語）那股震盪驚動了空裔使用感應能力，因而察覺到我們的存在。",
  ui_story_1012_10120202_17_dialog_content = "繼續拖住他。",
  ui_story_1012_10120202_18_dialog_content = "空裔很快就會到達目標附近。",
  ui_story_1012_10120202_19_dialog_content = "不能讓那個莽夫破壞我的計畫。",
  ui_story_1012_10120202_20_dialog_content = "就算用屍體，也要堵住他過來的路。",
  ui_story_1012_10120202_21_dialog_content = "（日蝕語）是，吞羅大人！",
  ui_story_1012_10120202_22_dialog_content = "該死的，雜兵怎麼愈來愈多了！",
  ui_story_1012_10120202_23_dialog_content = "想把我困在這裡嗎？想都別想！",
  ui_story_1012_10120202_24_dialog_content = "都給我閃開——！",
  ui_story_1012_10120202_25_dialog_content = "暗鬼都從這個方向來，也就是說......",
  ui_story_1012_10120202_26_dialog_content = "吞羅也在那邊是吧。",
  ui_story_1012_10120202_27_dialog_content = "終於抓住你的尾巴了，吞羅。",
  ui_story_1012_10120401_1_dialog_content = "（日蝕語）吞，吞羅大人！",
  ui_story_1012_10120401_2_dialog_content = "（日蝕語）那啟光的怪物不知哪裡來的蠻力，擋都擋不住！",
  ui_story_1012_10120401_3_dialog_content = "（日蝕語）他正朝這邊直奔而來！",
  ui_story_1012_10120401_4_dialog_content = "任性妄為也該有個限度。",
  ui_story_1012_10120401_5_dialog_content = "還是說，果然不該對怪物的理解力抱有期待呢。",
  ui_story_1012_10120401_6_dialog_content = "你們一起上，攔住他。",
  ui_story_1012_10120401_7_dialog_content = "（日蝕語）還，還要再打下去嗎......",
  ui_story_1012_10120401_8_dialog_content = "別讓我重複指示。",
  ui_story_1012_10120401_9_dialog_content = "（日蝕語）是......",
  ui_story_1012_10120401_10_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_1012_10120401_11_dialog_content = "什麼聲音？",
  ui_story_1012_10120401_12_dialog_content = "<color=#e8d9bb>轟隆隆——！！！</color>",
  ui_story_1012_10120401_13_dialog_content = "吞——羅——！",
  ui_story_1012_10120401_14_dialog_content = "還真是愚蠢的固執。",
  ui_story_1012_10120401_15_dialog_content = "像你這樣的生物，連用來做實驗的標準都達不到。",
  ui_story_1012_10120401_16_dialog_content = "只要是妳想做的，肯定就不是什麼好事！",
  ui_story_1012_10120401_17_dialog_content = "妳要是那麼想做實驗，就到迦南城的牢房裡做吧。",
  ui_story_1012_10120401_18_dialog_content = "你們，攔住他。",
  ui_story_1012_10120401_19_dialog_content = "嘎嗷——！",
  ui_story_1012_10120401_20_dialog_content = "妳手下的暗鬼就這點能耐？",
  ui_story_1012_10120401_21_dialog_content = "想必妳也沒什麼能耐吧。",
  ui_story_1012_10120401_22_dialog_content = "妳是萊因哈特的妹妹，至少也有她一半的實力吧？",
  ui_story_1012_10120401_23_dialog_content = "......",
  ui_story_1012_10120401_24_dialog_content = "別拿我跟那種失敗品相提並論。",
  ui_story_1012_10120401_25_dialog_content = "喔？妳生氣了？",
  ui_story_1012_10120401_26_dialog_content = "好啊，生氣了就來打一架！",
  ui_story_1012_10120401_27_dialog_content = "看來不讓你真正安靜下來，我沒辦法專心實驗。",
  ui_story_1012_10120401_28_dialog_content = "你，惹怒我了。",
  ui_story_1012_10120401_29_dialog_content = "這可正合我意。",
  ui_story_1012_10120401_30_dialog_content = "又回到這裡了......",
  ui_story_1012_10120401_31_dialog_content = "不管看多少次，我還是無法適應這裡的氣氛。",
  ui_story_1012_10120401_32_dialog_content = "我也不喜歡這裡。",
  ui_story_1012_10120401_33_dialog_content = "我們快點尋找通往和弦區的門吧。",
  ui_story_1012_10120401_34_dialog_content = "到達通往和弦區的區隔門。",
  ui_story_1012_10120401_35_dialog_content = "開始破解門禁系統，破解過程中輔腦將無法接受其他指令，請耐心等候。",
  ui_story_1012_10120401_36_dialog_content = "1%......2%......5%......",
  ui_story_1012_10120401_37_dialog_content = "看來有得等了。",
  ui_story_1012_10120401_38_dialog_content = "嗯，那我......",
  ui_story_1012_10120401_39_dialog_content = "這是——！",
  ui_story_1012_10120401_40_dialog_content = "怎麼了？",
  ui_story_1012_10120401_41_dialog_content = "我感受到吞羅的氣息......她進到塔裡了！",
  ui_story_1012_10120401_42_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_1012_10120401_43_dialog_content = "這些到底是什麼動靜？！",
  ui_story_1012_10120401_44_dialog_content = "從剛才開始就響個不停......",
  ui_story_1012_10120401_45_dialog_content = "是吞羅嗎？",
  ui_story_1012_10120401_46_dialog_content = "難道是吞羅在驅使塔里的暗鬼搞破壞？",
  ui_story_1012_10120401_47_dialog_content = "還是說，這座塔的某處發生塌方？",
  ui_story_1012_10120401_48_dialog_content = "<color=#e8d9bb>轟隆隆——！！！</color>",
  ui_story_1012_10120401_49_dialog_content = "唔哇！好多土？！",
  ui_story_1012_10120401_50_dialog_content = "小心，有什麼東西從塵土裡衝出來了！",
  ui_story_1012_10120401_51_dialog_content = "<color=#e8d9bb>鐺——！</color>",
  ui_story_1012_10120401_52_dialog_content = "礙事。",
  ui_story_1012_10120401_53_dialog_content = "別分心啊，吞羅——！",
  ui_story_1012_10120401_54_dialog_content = "妳的對手是我。",
  ui_story_1012_10120401_55_dialog_content = "巴頓？！原來是你啊！",
  ui_story_1012_10120401_56_dialog_content = "嗨，PlayerName，你也在啊。",
  ui_story_1012_10120401_57_dialog_content = "薇絲是怎麼回事，她昏過去了？",
  ui_story_1012_10120401_58_dialog_content = "薇絲受了傷，我們要打開這個門，想辦法救她！",
  ui_story_1012_10120401_59_dialog_content = "巴頓，幫我們拖住吞羅！",
  ui_story_1012_10120401_60_dialog_content = "拖延時間嗎......沒問題！",
  ui_story_1012_10120401_61_dialog_content = "你們就好好待在我身後，專心對付那些雜兵吧！",
  ui_story_1012_10120401_62_dialog_content = "說得比唱的好聽。",
  ui_story_1012_10120401_63_dialog_content = "我建議你們放棄抵抗。",
  ui_story_1012_10120401_64_dialog_content = "你們應該對你我之間的差距有著清醒的認知。",
  ui_story_1012_10120401_65_dialog_content = "我不想和你們浪費時間，你們也應該不想失去生命。",
  ui_story_1012_10120401_66_dialog_content = "所以，把那台機器的權限給我，然後放棄吧。",
  ui_story_1012_10120401_67_dialog_content = "我會放你們一條生路。",
  ui_story_1012_10120401_68_dialog_content = "我看妳還是往自己臉上來一拳，讓自己從白日夢裡醒來吧！",
  ui_story_1012_10120401_69_dialog_content = "那麼，你的判斷呢，空裔？",
  ui_story_1012_10120401_70_dialog_content = "你也要和這個啟光的莽夫一樣垂死掙扎嗎？",
  ui_story_1012_10120401_71_dialog_content = "......",
  ui_story_1012_10120401_72_option_content = "我不可能相信妳。",
  ui_story_1012_10120401_73_dialog_content = "喔？",
  ui_story_1012_10120401_74_dialog_content = "妳騙過太多人了。",
  ui_story_1012_10120401_75_dialog_content = "格茲德、嘶魘兒、舒默......",
  ui_story_1012_10120401_76_dialog_content = "每一個人都是，妳不在乎他們的死活，妳只在乎妳自己！",
  ui_story_1012_10120401_77_dialog_content = "妳根本不值得信任！",
  ui_story_1012_10120401_78_dialog_content = "......",
  ui_story_1012_10120401_79_dialog_content = "我的耐心是有限度的。",
  ui_story_1012_10120401_80_dialog_content = "把權限交出來，我會給你個痛快。",
  ui_story_1012_10120401_81_dialog_content = "我絕對，絕對不會把它交給你。",
  ui_story_1012_10120401_82_dialog_content = "無謂的抵抗。",
  ui_story_1012_10120401_83_dialog_content = "那就......",
  ui_story_1012_10120401_84_dialog_content = "再見了。",
  ui_story_1012_10120402_1_dialog_content = "PlayerName，小心！",
  ui_story_1012_10120402_2_dialog_content = "嗚啊——！救命！！！",
  ui_story_1012_10120402_3_dialog_content = "——！",
  ui_story_1012_10120402_4_dialog_content = "呃——！！！",
  ui_story_1012_10120402_5_dialog_content = "打架的時候，不要分心。",
  ui_story_1012_10120402_6_dialog_content = "這是你自己說過的話。",
  ui_story_1012_10120402_7_dialog_content = "巴頓！",
  ui_story_1012_10120402_8_dialog_content = "呿......",
  ui_story_1012_10120402_9_dialog_content = "妳就這麼點力氣？沒吃飯嗎？",
  ui_story_1012_10120402_10_dialog_content = "你從塔外一路暴動到這裡，中途沒有停過。",
  ui_story_1012_10120402_11_dialog_content = "你的力氣，應該已經快耗盡了吧。",
  ui_story_1012_10120402_12_dialog_content = "......",
  ui_story_1012_10120402_13_dialog_content = "別做無謂的抵抗。",
  ui_story_1012_10120402_14_dialog_content = "嘖，廢話少說！",
  ui_story_1012_10120402_15_dialog_content = "再來啊——！",
  ui_story_1012_10120402_16_dialog_content = "如果你能把一半用在打架上的時間用來學習，也不會如此不堪。",
  ui_story_1012_10120402_17_dialog_content = "學習？",
  ui_story_1012_10120402_18_dialog_content = "世界上還有妳這種看著就讓人想揍一頓的傢伙存在。",
  ui_story_1012_10120402_19_dialog_content = "我哪能靜下心來學習？",
  ui_story_1012_10120402_20_dialog_content = "你會為你的愚蠢付出代價。",
  ui_story_1012_10120402_21_dialog_content = "呃！",
  ui_story_1012_10120402_22_dialog_content = "你的右手腕關節已經碎了。",
  ui_story_1012_10120402_23_dialog_content = "我倒想看看，你如何再拿起那把刀。",
  ui_story_1012_10120402_24_dialog_content = "或者你可以......",
  ui_story_1012_10120402_25_dialog_content = "直接跪下來求我停手？",
  ui_story_1012_10120402_26_dialog_content = "快住手，吞羅！",
  ui_story_1012_10120402_27_dialog_content = "閉嘴。",
  ui_story_1012_10120402_28_dialog_content = "你沒有資格說話，脆弱又無能的空裔。",
  ui_story_1012_10120402_29_dialog_content = "啟光軍人......",
  ui_story_1012_10120402_30_dialog_content = "嗯？",
  ui_story_1012_10120402_31_dialog_content = "啟光軍人......絕對不會向妳這種人屈服！",
  ui_story_1012_10120402_32_dialog_content = "！！！",
  ui_story_1012_10120402_33_dialog_content = "就算只有一隻手，對付妳也綽綽有餘！",
  ui_story_1012_10120402_34_dialog_content = "巴頓，你的腿！",
  ui_story_1012_10120402_35_dialog_content = "卡蓮，去幫他！",
  ui_story_1012_10120402_36_dialog_content = "冰花，散開！",
  ui_story_1012_10120402_37_dialog_content = "不行，暗鬼太多了！",
  ui_story_1012_10120402_38_dialog_content = "不要管我！",
  ui_story_1012_10120402_39_dialog_content = "你們只管把門弄開，我來解決吞羅！",
  ui_story_1012_10120402_40_dialog_content = "可是，你現在已經——！",
  ui_story_1012_10120402_41_dialog_content = "！！！",
  ui_story_1012_10120402_42_dialog_content = "快走！",
  ui_story_1012_10120402_43_dialog_content = "可是！",
  ui_story_1012_10120402_44_dialog_content = "去找退路！",
  ui_story_1012_10120402_45_dialog_content = "如果我戰死了，就在我的墓碑上這麼寫——",
  ui_story_1012_10120402_46_dialog_content = "一個直到最後一刻都在與暗鬼戰鬥，光榮的啟光軍人！",
  ui_story_1012_10120402_47_dialog_content = "PlayerName，我們需要撤退的空間！",
  ui_story_1012_10120402_48_dialog_content = "被堵在這裡，只有死路一條！",
  ui_story_1012_10120402_49_dialog_content = "......！",
  ui_story_1012_10120402_50_dialog_content = "輔腦，破解進度還剩多少？！",
  ui_story_1012_10120402_51_dialog_content = "目前破解進度96%，請稍候。",
  ui_story_1012_10120402_52_dialog_content = "......再堅持一下！",
  ui_story_1012_10120402_53_dialog_content = "97%",
  ui_story_1012_10120402_54_dialog_content = "98%",
  ui_story_1012_10120402_55_dialog_content = "99%",
  ui_story_1012_10120402_56_dialog_content = "100%，破解完成。",
  ui_story_1012_10120402_57_dialog_content = "<color=#e8d9bb>轟隆——</color>",
  ui_story_1012_10120402_58_dialog_content = "大門......打開了！",
  ui_story_1012_10120402_59_dialog_content = "卡蓮，巴頓，我們撤！",
  ui_story_1012_10120501_1_dialog_content = "冰花！",
  ui_story_1012_10120501_2_dialog_content = "快點，吞羅快要追過來了，我擋不了她多久！",
  ui_story_1012_10120501_3_dialog_content = "你們從這邊走，巴頓，保護好PlayerName！",
  ui_story_1012_10120501_4_dialog_content = "放心，就算傷成這幅樣子，我也不會讓吞羅動他一根手指頭！",
  ui_story_1012_10120501_5_dialog_content = "輔腦，還有多遠？",
  ui_story_1012_10120501_6_dialog_content = "直行，前方200米，到達目的地。",
  ui_story_1012_10120501_7_dialog_content = "呼......呼......馬上就......到了！",
  ui_story_1012_10120501_8_dialog_content = "已經能看見前方的門了！",
  ui_story_1012_10120501_9_dialog_content = "我，不行了——",
  ui_story_1012_10120501_10_dialog_content = "這裡的路怎麼這麼崎嶇啊！",
  ui_story_1012_10120501_11_dialog_content = "輔腦推測，由於地形變化，通往和弦區的道路結構發生了改變。",
  ui_story_1012_10120501_12_dialog_content = "請相信輔腦給出的路線準確無誤！",
  ui_story_1012_10120501_13_dialog_content = "請管理者不要放棄，繼續前進！",
  ui_story_1012_10120501_14_dialog_content = "我......不會放棄！！！",
  ui_story_1012_10120501_15_dialog_content = "PlayerName，不能停！",
  ui_story_1012_10120501_16_dialog_content = "繼續跑啊，小子！",
  ui_story_1012_10120501_17_dialog_content = "敢停下，等回去我踹著你繞迦南城跑一百圈！",
  ui_story_1012_10120501_18_dialog_content = "鼓勵人不用這麼粗暴吧？！！",
  ui_story_1012_10120501_19_dialog_content = "噫——！！！",
  ui_story_1012_10120501_20_dialog_content = "輔腦！",
  ui_story_1012_10120501_21_dialog_content = "「輔腦導航」為您服務！",
  ui_story_1012_10120501_22_dialog_content = "等我們衝進和弦區，立刻關上大門——！",
  ui_story_1012_10120501_23_dialog_content = "把那些暗鬼關在外面！",
  ui_story_1012_10120501_24_dialog_content = "輔腦明白！",
  ui_story_1012_10120501_25_dialog_content = "但是，請管理者優先注意腳下的機關！",
  ui_story_1012_10120501_26_option_content = "機關？",
  ui_story_1012_10120501_27_dialog_content = "為什麼這地方還有機關啊？！",
  ui_story_1012_10120501_28_option_content = "還有機關？！",
  ui_story_1012_10120501_29_dialog_content = "這又是哪來的機關？！",
  ui_story_1012_10120501_30_dialog_content = "這些機關屬於和弦區的獨立防禦設備。",
  ui_story_1012_10120501_31_dialog_content = "由於和弦區與輔腦的連結中斷，輔腦無法控制和弦區的機關。",
  ui_story_1012_10120501_32_dialog_content = "目前這些機關正處於無差別攻擊狀態！",
  ui_story_1012_10120501_33_dialog_content = "請管理者自求多......不對，自行閃避！",
  ui_story_1012_10120501_34_dialog_content = "這種事情怎麼不早點說啊！！！",
  ui_story_1012_10120501_35_dialog_content = "和弦區設有陷阱裝置一事，已被正式寫進空裔一族教科書。",
  ui_story_1012_10120501_36_dialog_content = "如果管理者有所遺忘，輔腦建議您重新進入學校學習！",
  ui_story_1012_10120501_37_dialog_content = "PlayerName，小心腳下！",
  ui_story_1012_10120501_38_dialog_content = "欸？",
  ui_story_1012_10120501_39_dialog_content = "<color=#e8d9bb>喀噠——</color>",
  ui_story_1012_10120501_40_dialog_content = "PlayerName，快閃開！",
  ui_story_1012_10120501_41_dialog_content = "噫！！！",
  ui_story_1012_10120501_42_dialog_content = "......",
  ui_story_1012_10120501_43_dialog_content = "請管理者自行閃避！",
  ui_story_1012_10120501_44_dialog_content = "這東西有戰鬥能力嗎？",
  ui_story_1012_10120501_45_dialog_content = "如果有的話，就把它扔出去，好歹還能拖住吞羅一會！",
  ui_story_1012_10120501_46_dialog_content = "輔腦只是投影形象，不具備戰鬥能力。",
  ui_story_1012_10120501_47_dialog_content = "禁止強迫輔腦執行非本職工作的戰鬥任務！",
  ui_story_1012_10120501_48_dialog_content = "那就好好告訴我們機關的位置！",
  ui_story_1012_10120501_49_dialog_content = "輔腦正在搜尋有關和弦區機關的資料——",
  ui_story_1012_10120501_50_dialog_content = "搜尋完畢！",
  ui_story_1012_10120501_51_dialog_content = "前方請向右側閃避！",
  ui_story_1012_10120501_52_dialog_content = "糟糕！暗鬼追上來了！",
  ui_story_1012_10120501_53_dialog_content = "利用這些機關，甩掉牠們！",
  ui_story_1012_10120502_1_dialog_content = "偵測到管理者即將到達目的地。",
  ui_story_1012_10120502_2_dialog_content = "開始關閉和弦區大門。",
  ui_story_1012_10120502_3_dialog_content = "請管理者在大門關閉前盡快進入和弦區！",
  ui_story_1012_10120502_4_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_1012_10120502_5_dialog_content = "等等？！太快了？！",
  ui_story_1012_10120502_6_dialog_content = "快趕不上了！",
  ui_story_1012_10120502_7_dialog_content = "攔住他們，別讓那些蟲子破壞裡面的設備。",
  ui_story_1012_10120502_8_dialog_content = "PlayerName，快想辦法！",
  ui_story_1012_10120502_9_dialog_content = "我們必須和暗鬼拉開距離！",
  ui_story_1012_10120502_10_dialog_content = "辦法......辦法......我該上哪裡去找辦法？！",
  ui_story_1012_10120502_11_dialog_content = "前方有爆炸陷阱，請注意閃避！",
  ui_story_1012_10120502_12_dialog_content = "爆炸陷阱？",
  ui_story_1012_10120502_13_dialog_content = "小子，去踩那個爆炸陷阱！",
  ui_story_1012_10120502_14_dialog_content = "欸？！",
  ui_story_1012_10120502_15_dialog_content = "聽我的，踩下去就解決了！",
  ui_story_1012_10120502_16_dialog_content = "別想跑。",
  ui_story_1012_10120502_17_dialog_content = "我只信你這一次！！！",
  ui_story_1012_10120502_18_dialog_content = "<color=#e8d9bb>喀噠</color>",
  ui_story_1012_10120502_19_dialog_content = "小子，抓緊囉！！！",
  ui_story_1012_10120502_20_dialog_content = "<color=#e8d9bb>砰砰！</color>",
  ui_story_1012_10120502_21_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_1012_10120502_22_dialog_content = "這是——！",
  ui_story_1012_10120502_23_dialog_content = "唔啊！要被炸飛了啊啊啊啊啊——！",
  ui_story_1012_10120502_24_dialog_content = "<color=#e8d9bb>轟隆——咚！</color>",
  ui_story_1012_10120502_25_dialog_content = "該說不愧是啟光的怪物嗎。",
  ui_story_1012_10120502_26_dialog_content = "不要命的手段還真是不少。",
  ui_story_1012_10120502_27_dialog_content = "撞開這扇門。",
  ui_story_1012_10120502_28_dialog_content = "（日蝕語）是，吞羅大人！",
  ui_story_1012_10120502_29_dialog_content = "我們......成功了嗎？",
  ui_story_1012_10120502_30_dialog_content = "至少還活著......",
  ui_story_1012_10120502_31_dialog_content = "薇絲也沒有受傷。",
  ui_story_1012_10120502_32_dialog_content = "太好了......等等，巴頓呢？！",
  ui_story_1012_10120502_33_dialog_content = "我......沒什麼事......",
  ui_story_1012_10120502_34_dialog_content = "嘶——不過空裔做的炸彈威力可真不小。",
  ui_story_1012_10120502_35_dialog_content = "要不是我提前引爆了它，那我們全都玩完了。",
  ui_story_1012_10120502_36_dialog_content = "你這樣子，擺明不是沒事吧？！",
  ui_story_1012_10120502_37_dialog_content = "咳咳......別擔心，小子......",
  ui_story_1012_10120502_38_dialog_content = "啟光的人個個經歷過苦戰，這點程度的傷口隨便包紮一下，睡一覺就好了。",
  ui_story_1012_10120502_39_dialog_content = "要是每次受點小傷就去找醫療兵，肯定會被拎著領子，從醫務室扔出去。",
  ui_story_1012_10120502_40_dialog_content = "先別管我了......你們要找的東西，就是那個吧？",
  ui_story_1012_10120502_41_dialog_content = "輔腦，這就是「和弦紐帶」了？",
  ui_story_1012_10120502_42_dialog_content = "輔腦認為，應該是的！",
  ui_story_1012_10120502_43_dialog_content = "你的推斷準確嗎？",
  ui_story_1012_10120502_44_dialog_content = "有沒有關於這台裝置的記錄？",
  ui_story_1012_10120502_45_dialog_content = "「和弦紐帶」是和弦區的主要裝置。",
  ui_story_1012_10120502_46_dialog_content = "根據推斷，管理者面前的設備應該是「和弦紐帶」。",
  ui_story_1012_10120502_47_dialog_content = "<color=#e8d9bb>咚——！</color>",
  ui_story_1012_10120502_48_dialog_content = "不妙，那票暗鬼開始撞門了！",
  ui_story_1012_10120502_49_dialog_content = "暫時不用擔心。",
  ui_story_1012_10120502_50_dialog_content = "這座基地裡的門和牆都結實得很，我撞了半天都撞不開。",
  ui_story_1012_10120502_51_dialog_content = "<color=#e8d9bb>咚——！</color>",
  ui_story_1012_10120502_52_dialog_content = "門上好像凹了一塊？",
  ui_story_1012_10120502_53_dialog_content = "輔腦，有沒有辦法強化大門？",
  ui_story_1012_10120502_54_dialog_content = "正在啟動和弦區門禁系統強化功能！",
  ui_story_1012_10120502_55_dialog_content = "<color=#e8d9bb>喀嚓——喀嚓——</color>",
  ui_story_1012_10120502_56_dialog_content = "又多了好幾道門封住入口。",
  ui_story_1012_10120502_57_dialog_content = "看起來應該能再多撐一陣子。",
  ui_story_1012_10120502_58_dialog_content = "<color=#e8d9bb>咚——咚——</color>",
  ui_story_1012_10120502_59_dialog_content = "攻擊停下來了？",
  ui_story_1012_10120502_60_dialog_content = "<color=#e8d9bb>咚！！！</color>",
  ui_story_1012_10120502_61_dialog_content = "怎麼比剛才撞得更猛烈了！",
  ui_story_1012_10120502_62_dialog_content = "那群暗鬼的腦袋不痛嗎？！",
  ui_story_1012_10120502_63_dialog_content = "嘖，吞羅這傢伙還罵我固執，明明她自己也是腦子裡只有一根筋！",
  ui_story_1012_10120502_64_dialog_content = "既然撞牆了就給我回頭啊！",
  ui_story_1012_10120502_65_dialog_content = "這樣下去，大門恐怕很快就會被撞開。",
  ui_story_1012_10120502_66_dialog_content = "PlayerName，快啟動「和弦紐帶」治療薇絲。",
  ui_story_1012_10120502_67_dialog_content = "如果薇絲恢復，我們一起突圍，或許還有希望！",
  ui_story_1012_10120502_68_dialog_content = "輔腦，幫我啟動「和弦紐帶」！",
  ui_story_1012_10120502_69_dialog_content = "「和弦紐帶」啟動！",
  ui_story_1012_10120502_70_dialog_content = "檢查實驗記錄，確認「和弦紐帶」的效果及副作用！",
  ui_story_1012_10120502_71_dialog_content = "檢索中......錯誤！",
  ui_story_1012_10120502_72_dialog_content = "輔腦無法檢索到實驗記錄！",
  ui_story_1012_10120502_73_dialog_content = "什麼？！",
  ui_story_1012_10120502_74_dialog_content = "不是說實驗記錄都被儲存在這裡嗎？",
  ui_story_1012_10120502_75_dialog_content = "怎麼會檢索不到？！",
  ui_story_1012_10120502_76_dialog_content = "輔腦與和弦區的連結中斷許久，並不清楚和弦區的現況。",
  ui_story_1012_10120502_77_dialog_content = "在和弦區的記錄中，輔腦偵測到刪除記錄。",
  ui_story_1012_10120502_78_dialog_content = "數據丟失已久，無法恢復。",
  ui_story_1012_10120502_79_dialog_content = "這......",
  ui_story_1012_10120502_80_dialog_content = "所以，你們要把一個沒有經過驗證的玩意往薇絲身上用？",
  ui_story_1012_10120502_81_dialog_content = "不，我本來想先找到實驗記錄，但現在實驗記錄都消失了......",
  ui_story_1012_10120502_82_dialog_content = "巴頓、卡蓮，麻煩你們兩個再撐一下。",
  ui_story_1012_10120502_83_dialog_content = "我要去驗證「和弦紐帶」的效果！",
  ui_story_1012_10120502_84_dialog_content = "等一下，你不是光靈，用了結果更不能確定。",
  ui_story_1012_10120502_85_dialog_content = "但我不能讓薇絲冒險。",
  ui_story_1012_10120502_86_dialog_content = "吞羅馬上就要打進來了，比起你們兩個還能戰鬥的......",
  ui_story_1012_10120502_87_dialog_content = "我這個連光能術都無法使用的空裔更適合來做實驗！",
  ui_story_1012_10120502_88_dialog_content = "你給我站住！",
  ui_story_1012_10120502_89_dialog_content = "別攔我！",
  ui_story_1012_10120502_90_dialog_content = "冷靜點！",
  ui_story_1012_10120502_91_dialog_content = "你知道那東西有什麼用嗎？",
  ui_story_1012_10120502_92_dialog_content = "「和弦紐帶」可以治癒傷口，部分改造光靈的軀體，激發光靈的潛能。",
  ui_story_1012_10120502_93_dialog_content = "能治療，是吧？",
  ui_story_1012_10120502_94_dialog_content = "那我去！",
  ui_story_1012_10120502_95_dialog_content = "但我連它有什麼副作用、成功率是多少、會不會死人都不清楚！",
  ui_story_1012_10120502_96_dialog_content = "那就更該讓我來！",
  ui_story_1012_10120502_97_dialog_content = "我們需要一個實驗品，對吧，小子？",
  ui_story_1012_10120502_98_dialog_content = "我已經傷成這樣了，真要是正面對上吞羅，最多也只能再擋一兩招。",
  ui_story_1012_10120502_99_dialog_content = "如果你留在外面，和卡蓮配合總是比我有用處。",
  ui_story_1012_10120502_100_dialog_content = "所以，讓我去吧。",
  ui_story_1012_10120502_101_dialog_content = "如果那個機器能把我治好，我會給吞羅一個大驚喜。",
  ui_story_1012_10120502_102_dialog_content = "到時候，你也能安心地用它救薇絲。",
  ui_story_1012_10120502_103_dialog_content = "......好。",
  ui_story_1012_10120502_104_dialog_content = "這邊就交給你們倆了。",
  ui_story_1012_10120502_105_dialog_content = "給我好好把那些暗鬼擋在外面！",
  ui_story_1012_10120502_106_dialog_content = "<color=#e8d9bb>咚！！！</color>",
  ui_story_1012_10120502_107_dialog_content = "吼——",
  ui_story_1012_10120502_108_dialog_content = "比地下城使用的材料更堅固，同時又更輕。",
  ui_story_1012_10120502_109_dialog_content = "這座基地的建築和大門使用的材料與巨像肌材更加類似。",
  ui_story_1012_10120502_110_dialog_content = "巨像與空裔，甚至還有暗鬼......",
  ui_story_1012_10120502_111_dialog_content = "這個祕密，或許連日蝕都不知道其真實。",
  ui_story_1012_10120502_112_dialog_content = "真令人期待。",
  ui_story_1012_10120502_113_dialog_content = "（日蝕語）吞羅大人，斐桀洛大人命我給您傳遞消息。",
  ui_story_1012_10120502_114_dialog_content = "（日蝕語）大軍已在塔外集結完畢。",
  ui_story_1012_10120502_115_dialog_content = "（日蝕語）但是，白塔的變化引起了啟光、白夜城和北境的注意。",
  ui_story_1012_10120502_116_dialog_content = "（日蝕語）他們的援軍已經從四面八方趕來。",
  ui_story_1012_10120502_117_dialog_content = "（日蝕語）萊因哈特與伯利恆也在其中。",
  ui_story_1012_10120502_118_dialog_content = "平時畏首畏尾，現在卻傾巢而出了嗎。",
  ui_story_1012_10120502_119_dialog_content = "耳朵還真是靈光。",
  ui_story_1012_10120502_120_dialog_content = "告訴斐桀洛。攔住他們。",
  ui_story_1012_10120502_121_dialog_content = "我的實驗，還需要時間。",
  ui_story_1012_10120502_122_dialog_content = "（日蝕語）斐桀洛大人要我提醒您。",
  ui_story_1012_10120502_123_dialog_content = "（日蝕語）不要做多餘的事情。",
  ui_story_1012_10120502_124_dialog_content = "他要是真想幫忙，就不要三番兩次來打擾我。",
  ui_story_1012_10120502_125_dialog_content = "......",
  ui_story_1012_10120502_126_dialog_content = "（日蝕語）吞羅大人就是這麼說的......",
  ui_story_1012_10120502_127_dialog_content = "（日蝕語）吞羅這個傢伙，看起來需要一些小小的提醒。",
  ui_story_1012_10120502_128_dialog_content = "（日蝕語）只不過現在還不是時候。",
  ui_story_1012_10120502_129_dialog_content = "（日蝕語）啟光，白夜城，甚至連北境都出動了。",
  ui_story_1012_10120502_130_dialog_content = "（日蝕語）斐桀洛大人，要阻止他們嗎？",
  ui_story_1012_10120502_131_dialog_content = "（日蝕語）如果你們想找點樂子，那就去吧。",
  ui_story_1012_10120502_132_dialog_content = "（日蝕語）但不必拼個你死我活，放一兩個進來也沒有關係。",
  ui_story_1012_10120502_133_dialog_content = "（日蝕語）給吞羅一些壓力，才能讓她發揮價值。",
  ui_story_1012_10120502_134_dialog_content = "（日蝕語）是，斐桀洛大人。",
  ui_story_1012_10120601_1_dialog_content = "<color=#e8d9bb>系統提示：「和弦紐帶」正在運行中......請勿中斷「同調」流程......</color>",
  ui_story_1012_10120601_2_dialog_content = "<color=#e8d9bb>咚......咚......咚......咚......</color>",
  ui_story_1012_10120601_3_dialog_content = "這是......什麼聲音？",
  ui_story_1012_10120601_4_dialog_content = "彷彿四面八方同時傳出聲音，耳朵好難受。",
  ui_story_1012_10120601_5_dialog_content = "與其說是難受，反而更覺得詭異。",
  ui_story_1012_10120601_6_dialog_content = "這種聲音聽起來就像是......",
  ui_story_1012_10120601_7_option_content = "地震的聲音",
  ui_story_1012_10120601_8_dialog_content = "震動的強度甚至不亞於回歸塔升起的時候。",
  ui_story_1012_10120601_9_dialog_content = "整個核心中樞區的牆體都隨之顫動......",
  ui_story_1012_10120601_10_dialog_content = "就好像這裡快要塌陷了一樣。",
  ui_story_1012_10120601_11_option_content = "心跳的聲音",
  ui_story_1012_10120601_12_dialog_content = "它們像是一種頻率穩定的律動。",
  ui_story_1012_10120601_13_dialog_content = "我甚至能從這種律動中感受到一股可怕的活力......",
  ui_story_1012_10120601_14_dialog_content = "讓此地給人感覺宛如一個巨大的心室。",
  ui_story_1012_10120601_15_dialog_content = "這就是「和弦紐帶」的力量嗎......",
  ui_story_1012_10120601_16_dialog_content = "原來如此，真是讓人不安的聲音。",
  ui_story_1012_10120601_17_dialog_content = "只是不知道它還要持續多久。",
  ui_story_1012_10120601_18_dialog_content = "巴頓他......",
  ui_story_1012_10120601_19_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_1012_10120601_20_dialog_content = "？！",
  ui_story_1012_10120601_21_dialog_content = "這個聲音，絕對不是「和弦紐帶」造成的吧！",
  ui_story_1012_10120601_22_dialog_content = "警告！前方三十米，偵測到非法入侵和弦區者。",
  ui_story_1012_10120601_23_dialog_content = "她還是先來了。輔腦，改變結構，關上這裡的門！",
  ui_story_1012_10120601_24_dialog_content = "收到......錯誤！錯誤！",
  ui_story_1012_10120601_25_dialog_content = "和弦區入口處偵測到生命體，無法關閉。",
  ui_story_1012_10120601_26_dialog_content = "沒辦法了，做好準備，PlayerName！",
  ui_story_1012_10120601_27_dialog_content = "嗯，「同調」的過程還在進行，我們要保護好巴頓！",
  ui_story_1012_10120601_28_dialog_content = "（......無論「同調」的結果如何。）",
  ui_story_1012_10120601_29_dialog_content = "警告：前方十米偵測到非法入侵者。",
  ui_story_1012_10120601_30_dialog_content = "重複警告：前方十米偵測到非法入侵者。",
  ui_story_1012_10120601_31_dialog_content = "重複警告：前方十米偵測到非法入侵者......",
  ui_story_1012_10120601_32_dialog_content = "停住了？",
  ui_story_1012_10120601_33_dialog_content = "真......真的嗎......",
  ui_story_1012_10120601_34_dialog_content = "<color=#e8d9bb><size=45>砰！！！！！！！！！</size></color>",
  ui_story_1012_10120601_35_dialog_content = "非法入侵者？",
  ui_story_1012_10120601_36_dialog_content = "我不過是做了與你們相同的事。",
  ui_story_1012_10120601_37_dialog_content = "唯一的差別只在誰先誰後罷了。",
  ui_story_1012_10120601_38_dialog_content = "......嗯？",
  ui_story_1012_10120601_39_dialog_content = "原來在這個墳場的最底層，還埋藏著這種顛覆性的裝置。",
  ui_story_1012_10120601_40_dialog_content = "在殺死巴頓這件事上，你們還是搶先了我一步。",
  ui_story_1012_10120601_41_dialog_content = "妳不要胡說！",
  ui_story_1012_10120601_42_dialog_content = "PlayerName，別跟她多費唇舌！",
  ui_story_1012_10120601_43_dialog_content = "不能讓她深入這裡！薇絲也還在裡面！",
  ui_story_1012_10120601_44_dialog_content = "世界上的很多事，可不會照著你一廂情願的想法發展。",
  ui_story_1012_10120601_45_dialog_content = "PlayerName，你身為空裔，走出巨像這麼久，竟然還需要我來告訴你這個道理。",
  ui_story_1012_10120601_46_dialog_content = "上一次有空裔反抗我之後落得什麼下場，不用我多說明了吧。",
  ui_story_1012_10120601_47_dialog_content = "妳......！",
  ui_story_1012_10120601_48_dialog_content = "（日蝕語）出擊。",
  ui_story_1012_10120601_49_dialog_content = "（日蝕語）是！！！",
  ui_story_1012_10120702_1_dialog_content = "嘎！！！",
  ui_story_1012_10120702_2_dialog_content = "哈——",
  ui_story_1012_10120702_3_dialog_content = "嘎嗚......",
  ui_story_1012_10120702_4_dialog_content = "卡蓮！小心背後！",
  ui_story_1012_10120702_5_dialog_content = "什......？！",
  ui_story_1012_10120702_6_dialog_content = "吼！ ！ ！",
  ui_story_1012_10120702_7_dialog_content = "唔......",
  ui_story_1012_10120702_8_dialog_content = "（不行，吞羅帶來的暗鬼數量太多。）",
  ui_story_1012_10120702_9_dialog_content = "（與其跟卡蓮意識連結，不如這樣更加有效！）",
  ui_story_1012_10120702_10_dialog_content = "咦？！",
  ui_story_1012_10120702_11_dialog_content = "我都不曉得你什麼時候學會使用武器了？PlayerName？",
  ui_story_1012_10120702_12_dialog_content = "嗯......看著確實像是空裔一族的槍，也算是文物級別的遺物了。",
  ui_story_1012_10120702_13_dialog_content = "這可是好東西。",
  ui_story_1012_10120702_14_dialog_content = "謝謝，PlayerName，我收下了。",
  ui_story_1012_10120702_15_dialog_content = "可惡——還給我！",
  ui_story_1012_10120702_16_dialog_content = "吼！ ！ ！",
  ui_story_1012_10120702_17_dialog_content = "快攔住牠們，PlayerName！不能讓牠們繼續深入！",
  ui_story_1012_10120702_18_dialog_content = "怎麼能因為這點狀況就破壞「同調」的進程！",
  ui_story_1012_10120702_19_dialog_content = "冰花！散開！",
  ui_story_1012_10120702_20_dialog_content = "<size=45>嘎吼！！！</size>",
  ui_story_1012_10120702_21_dialog_content = "卡......卡蓮！",
  ui_story_1012_10120702_22_option_content = "強制感應！",
  ui_story_1012_10120702_23_dialog_content = "卡蓮......快......快回應我啊！",
  ui_story_1012_10120702_24_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1012_10120702_25_dialog_content = "<color=#e8d9bb>............</color>",
  ui_story_1012_10120702_26_dialog_content = "（日蝕語）殺掉巴頓和薇絲，那個儀器要維持無傷。",
  ui_story_1012_10120702_27_dialog_content = "（日蝕語）遵命。",
  ui_story_1012_10120702_28_dialog_content = "<size=50><anim type=Shake>吼——————</anim></size>",
  ui_story_1012_10120702_29_dialog_content = "（為什麼，為什麼會這樣？）",
  ui_story_1012_10120702_30_dialog_content = "（又是這種束手無策的感覺，我再次不得不體會......）",
  ui_story_1012_10120702_31_dialog_content = "（要是我也有光能術那樣的能力，現在肯定不會有這樣的境遇。）",
  ui_story_1012_10120702_32_dialog_content = "（薇絲、卡蓮，以及......）",
  ui_story_1012_10120702_33_dialog_content = "（他們......）",
  ui_story_1012_10120702_34_dialog_content = "救命！！！還有人能救救我嗎！",
  ui_story_1012_10120702_35_dialog_content = "別靠近他，我跟你們拼了！",
  ui_story_1012_10120702_36_dialog_content = "哇——哇——嗚嗚嗚嗚嗚......",
  ui_story_1012_10120702_37_dialog_content = "戰火、暗鬼——這就是我睜眼時的歡迎式？",
  ui_story_1012_10120702_38_dialog_content = "（什麼？！）",
  ui_story_1012_10120702_39_dialog_content = "還有什麼是比這些更棒的嗎？！",
  ui_story_1012_10120702_40_dialog_content = "我簡直快壓抑不住，這股力量好像隨時都可能噴發一般！",
  ui_story_1012_10120702_41_dialog_content = "一場及時的戰鬥就是最好的訓練！",
  ui_story_1012_10120702_42_dialog_content = "巴頓！你......你成功了！",
  ui_story_1012_10120702_43_dialog_content = "喔，PlayerName......你小子怎麼回事？",
  ui_story_1012_10120702_44_dialog_content = "把你臉上的水擦擦吧，別像個小姑娘似的！",
  ui_story_1012_10120702_45_dialog_content = "給我把鬥志拿出來！",
  ui_story_1012_10120702_46_dialog_content = "當......當然了！",
  ui_story_1012_10120702_47_dialog_content = "來吧，讓我帶你見識真正的戰場。",
  ui_story_1012_10120702_48_dialog_content = "這可是屬於你的塔，不能讓它落入日蝕那幫人的手裡！",
  ui_story_1012_10120702_49_dialog_content = "（日蝕語）真是驚人，遠古的空裔科技居然已經如此發達。",
  ui_story_1012_10120702_50_dialog_content = "（日蝕語）太讓人興奮了，追到這裡果然是正確的決定。",
  ui_story_1012_10120702_51_dialog_content = "（日蝕語）主人明智。",
  ui_story_1012_10120702_52_dialog_content = "（日蝕語）還愣著幹什麼，抓住他，別把他弄死，我要活的。",
  ui_story_1012_10120702_53_dialog_content = "（日蝕語）是——",
  ui_story_1012_10120702_54_dialog_content = "<color=#e8d9bb><size=45>乓——</size></color>",
  ui_story_1012_10120702_55_dialog_content = "「好久不見」啊，吞羅。",
  ui_story_1012_10120702_56_dialog_content = "時隔這麼久，妳帶的這群傻子怎麼變得更弱了？",
  ui_story_1012_10120702_57_dialog_content = "該死。",
  ui_story_1012_10120702_58_dialog_content = "（日蝕語）全體聽令，即刻出擊！",
  ui_story_1012_10120702_59_dialog_content = "吼！ ！ ！",
  ui_story_1012_10120702_60_dialog_content = "豹——擊——！",
  ui_story_1012_10120702_61_dialog_content = "PlayerName，巴頓！",
  ui_story_1012_10120702_62_dialog_content = "......意思就是說，「和弦紐帶」做到了！",
  ui_story_1012_10120702_63_dialog_content = "哈哈哈哈哈！！！是啊。",
  ui_story_1012_10120702_64_dialog_content = "快去救薇絲吧，你們這支小隊裡缺不了她吧？",
  ui_story_1012_10120702_65_dialog_content = "至於這裡，就放著讓我來吧。",
  ui_story_1012_10120702_66_dialog_content = "......",
  ui_story_1012_10120702_67_dialog_content = "（日蝕語）撤退，與日蝕大軍匯合。",
  ui_story_1012_10120702_68_dialog_content = "（日蝕語）遵......遵命。",
  ui_story_1012_10120702_69_dialog_content = "混帳東西，站住！！！",
  ui_story_1012_10120702_70_dialog_content = "真是一群不要臉的傢伙！",
  ui_story_1012_10120702_71_dialog_content = "卡蓮，妳呢？剛才那麼危險，妳要不要緊......",
  ui_story_1012_10120702_72_dialog_content = "不礙事。事不宜遲，PlayerName......…",
  ui_story_1012_10120702_73_dialog_content = "我們要趕快搶救薇絲！",
  ui_story_1012_10120702_74_dialog_content = "說得對，我們順著剛才的操作，執行「同調」吧。",
  ui_story_1012_10120702_75_dialog_content = "（那麼，拜託了，「和弦紐帶」。）",
  ui_story_1012_10120702_76_dialog_content = "（請妳一定要醒過來，薇絲......）",
  ui_story_1012_10120702_77_dialog_content = "<color=#e8d9bb>系統提示：「和弦紐帶」即將開始運行......</color>",
  ui_story_1012_10120801_1_dialog_content = "<color=#e8d9bb>系統提示：「和弦紐帶」正在運行中......請勿中斷「同調」流程......</color>",
  ui_story_1012_10120801_2_dialog_content = "......",
  ui_story_1012_10120801_3_dialog_content = "............",
  ui_story_1012_10120801_4_dialog_content = "從啟動到現在，過了多久？",
  ui_story_1012_10120801_5_dialog_content = "別著急，PlayerName，給薇絲一點時間。",
  ui_story_1012_10120801_6_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1012_10120801_7_dialog_content = "無論怎麼說，這個「同調」未免執行得太久了？！",
  ui_story_1012_10120801_8_dialog_content = "經你這麼一說，剛才等待巴頓甦醒的時間確實沒有這麼長。",
  ui_story_1012_10120801_9_dialog_content = "PlayerName，我們......",
  ui_story_1012_10120801_10_dialog_content = "（卡蓮......）",
  ui_story_1012_10120801_11_dialog_content = "（嗯，至少我要振作起來。）",
  ui_story_1012_10120801_12_dialog_content = "剛才我們嚴格遵照了「和弦紐帶」的指示，讓薇絲躺在上面。",
  ui_story_1012_10120801_13_dialog_content = "整個過程也和巴頓經歷的一致。",
  ui_story_1012_10120801_14_dialog_content = "不管是「和弦紐帶」還是輔腦，都沒有發過任何錯誤警報。",
  ui_story_1012_10120801_15_dialog_content = "所以我想，問題有可能出在......",
  ui_story_1012_10120801_16_option_content = "薇絲的「識泯」狀態",
  ui_story_1012_10120801_17_dialog_content = "原來如此，也只有這個可能性了。",
  ui_story_1012_10120801_18_dialog_content = "同樣是受傷，那位啟光將軍並沒有喪失意識。",
  ui_story_1012_10120801_19_dialog_content = "所以儘管身負重傷，他還是能帶著更加強健的身軀醒來。",
  ui_story_1012_10120801_20_option_content = "吞羅的破壞",
  ui_story_1012_10120801_21_dialog_content = "是這樣嗎？因為吞羅做了某種小動作......？",
  ui_story_1012_10120801_22_dialog_content = "但是，剛才，吞羅的暗鬼，甚至還沒有機會接近「和弦紐帶」裝置......",
  ui_story_1012_10120801_23_dialog_content = "就已經被那個啟光將軍擊倒了。",
  ui_story_1012_10120801_24_dialog_content = "這麼想來......問題果然出在「識泯」上。",
  ui_story_1012_10120801_25_dialog_content = "是的。這樣想來，剛才在環狀系統裡看到的那些資料......",
  ui_story_1012_10120801_26_dialog_content = "實驗體......，未從「識泯」下復甦，身體......，生命跡象減退。",
  ui_story_1012_10120801_27_dialog_content = "實驗體......，未從「識泯」下復甦，出現......現象，生命......",
  ui_story_1012_10120801_28_dialog_content = "實驗體......，未......復甦，實驗過程中......",
  ui_story_1012_10120801_29_dialog_content = "那些被命名為實驗體的空裔，他們所具備的共同特徵——",
  ui_story_1012_10120801_30_dialog_content = "就是「識泯」。",
  ui_story_1012_10120801_31_dialog_content = "怎，怎麼會這樣......",
  ui_story_1012_10120801_32_dialog_content = "（難道，不能從「識泯」中復甦，注定是他們共同的結局嗎？）",
  ui_story_1012_10120801_33_dialog_content = "（如果真的是這樣，那薇絲......）",
  ui_story_1012_10120801_34_dialog_content = "PlayerName......",
  ui_story_1012_10120801_35_dialog_content = "PlayerName？",
  ui_story_1012_10120801_36_dialog_content = "萊......萊因哈特？！",
  ui_story_1012_10120801_37_dialog_content = "還好，看來你們那邊的訊號還算清晰。",
  ui_story_1012_10120801_38_dialog_content = "你們那邊情況如何，你知道你們這次搞出多大的名堂嗎？",
  ui_story_1012_10120801_39_dialog_content = "真......真是不好意思！",
  ui_story_1012_10120801_40_dialog_content = "哈哈哈哈哈哈哈哈，我沒有責怪你的意思。",
  ui_story_1012_10120801_41_dialog_content = "我只是要提醒你，此次空谷劇變，聞聲而動的不只啟光。",
  ui_story_1012_10120801_42_dialog_content = "千萬不要把自己放在完全被動的狀態......",
  ui_story_1012_10120801_43_dialog_content = "畢竟有權利改變這個空谷的人，唯有你。",
  ui_story_1012_10120801_44_dialog_content = "一會見。",
  ui_story_1012_10120801_45_dialog_content = "好的，萊因哈特。",
  ui_story_1012_10120801_46_dialog_content = "她說得沒錯。",
  ui_story_1012_10120801_47_dialog_content = "我們現在完全無法得知塔外的情況，這對我們而言非常不利。",
  ui_story_1012_10120801_48_dialog_content = "可是，該如何迅速掌握外界的情況呢？",
  ui_story_1012_10120801_49_dialog_content = "巴頓應該還在處理吞羅，貿然連線只會給他帶來麻煩......",
  ui_story_1012_10120801_50_dialog_content = "收到，疑問分析中......",
  ui_story_1012_10120801_51_dialog_content = "咦？！",
  ui_story_1012_10120801_52_dialog_content = "輔腦......難道有辦法？",
  ui_story_1012_10120801_53_dialog_content = "正在開啟塔外監控檢查畫面。",
  ui_story_1012_10120801_54_dialog_content = "呼，呼......",
  ui_story_1012_10120801_55_dialog_content = "別跑了，吞羅。",
  ui_story_1012_10120801_56_dialog_content = "像個戰士一樣拼個你死我活！",
  ui_story_1012_10120801_57_dialog_content = "什......",
  ui_story_1012_10120801_58_dialog_content = "什麼......",
  ui_story_1012_10120801_59_dialog_content = "這真是......這真是千載難逢的光景啊！！！",
  ui_story_1012_10120801_60_dialog_content = "（竟然出動了這麼多援軍！）",
  ui_story_1012_10120801_61_dialog_content = "（這個陣仗，簡直和十幾年前的暗潮危機沒有區別。）",
  ui_story_1012_10120801_62_dialog_content = "（我究竟......還能幫PlayerName他們撐多久呢。）",
  ui_story_1012_10120801_63_dialog_content = "喔？",
  ui_story_1012_10120801_64_dialog_content = "看來妳給自己添了不少麻煩啊，吞羅。",
  ui_story_1012_10120801_65_dialog_content = "下次可別再一意孤行了。",
  ui_story_1012_10120801_66_dialog_content = "有這麼個麻煩一路糾纏著妳，想必妳也是一無所獲吧。",
  ui_story_1012_10120801_67_dialog_content = "不好意思，還是頗有收穫。",
  ui_story_1012_10120801_68_dialog_content = "但這都與你無關。",
  ui_story_1012_10120801_69_dialog_content = "既然你寧願站在一旁按兵不動，就別妄想坐收漁翁之利。",
  ui_story_1012_10120801_70_dialog_content = "隨妳怎麼想。",
  ui_story_1012_10120801_71_dialog_content = "真卑鄙。吞羅，打不過就開始請援兵助陣嗎？",
  ui_story_1012_10120801_72_dialog_content = "（就是那裡！防線缺口！）",
  ui_story_1012_10120801_73_dialog_content = "豹——擊——！",
  ui_story_1012_10120801_74_dialog_content = "嘶......",
  ui_story_1012_10120801_75_dialog_content = "日蝕傾巢出動可不是為了你。",
  ui_story_1012_10120801_76_dialog_content = "別掙扎了，還是老實一點吧。",
  ui_story_1012_10120801_77_dialog_content = "從來到這座白塔，一直到現在，你都極力為那個空裔拖延時間。",
  ui_story_1012_10120801_78_dialog_content = "我說得沒錯吧。",
  ui_story_1012_10120801_79_dialog_content = "......",
  ui_story_1012_10120801_80_dialog_content = "（日蝕語）抓住他。",
  ui_story_1012_10120801_81_dialog_content = "吼吼吼——！！！",
  ui_story_1012_10120801_82_dialog_content = "<color=#e8d9bb>轟——砰！</color>",
  ui_story_1012_10120801_83_dialog_content = "這是——",
  ui_story_1012_10120801_84_dialog_content = "嗯，近距離看這座塔，果然更加不同凡響。",
  ui_story_1012_10120801_85_dialog_content = "一切都如同我在夢中所見的預言......",
  ui_story_1012_10120801_86_dialog_content = "無論世界走向毀滅還是新生，空谷與暗鬼的對抗都是一塊不可缺少的碎片。",
  ui_story_1012_10120801_87_dialog_content = "（北境的領導者......嗎？）",
  ui_story_1012_10120801_88_dialog_content = "（竟然被她出手幫了一把......）",
  ui_story_1012_10120801_89_dialog_content = "巴頓軍團長，你知道啟光軍規第四十二條，會怎麼處置抗命的軍人嗎？",
  ui_story_1012_10120801_90_dialog_content = "什麼？！",
  ui_story_1012_10120801_91_dialog_content = "啟光將嚴格按照軍事條例處罰，情節嚴重者將由軍事法庭進行審判。",
  ui_story_1012_10120801_92_dialog_content = "——但，這也要等戰爭結束之後。",
  ui_story_1012_10120801_93_dialog_content = "......大元帥？",
  ui_story_1012_10120801_94_dialog_content = "前來增援的先頭部隊馬上就趕到了，快去和他們會合吧。",
  ui_story_1012_10120801_95_dialog_content = "喔？你這是......參加了緊急特訓嗎？總覺得看起來有點不一樣......",
  ui_story_1012_10120801_96_dialog_content = "總之，準備好大鬧一場吧，巴頓軍團長！",
  ui_story_1012_10120801_97_dialog_content = "就用你的戰功，來彌補過錯吧！",
  ui_story_1012_10120801_98_dialog_content = "......",
  ui_story_1012_10120801_99_dialog_content = "是！",
  ui_story_1012_10120801_100_dialog_content = "妳就看仔細了，大元帥。",
  ui_story_1012_10120801_101_dialog_content = "塔外監控畫面播放完畢。",
  ui_story_1012_10120801_102_dialog_content = "伯利恆陛下，還有萊因哈特......",
  ui_story_1012_10120801_103_dialog_content = "看來北境和啟光都陸續出動了。",
  ui_story_1012_10120801_104_dialog_content = "但是，他們攜帶的兵力，怎麼算也不足以和日蝕抗衡。",
  ui_story_1012_10120801_105_dialog_content = "PlayerName，我們也得想想辦法幫忙！",
  ui_story_1012_10120801_106_dialog_content = "明白了，我們就先利用這座回歸塔居於中央的地理優勢吧。",
  ui_story_1012_10120801_107_dialog_content = "輔腦，請告訴我這座回歸塔的防禦手段！",
  ui_story_1012_10120801_108_dialog_content = "收到，疑問分析中......答案形成——",
  ui_story_1012_10120801_109_dialog_content = "回歸塔內部，存在終極防禦系統：<color=#FFB400>「律法之弦」</color>。",
  ui_story_1012_10120801_110_dialog_content = "這是空谷中最強大、最獨特，也是最後的防禦手段。",
  ui_story_1012_10120801_111_dialog_content = "那麼——",
  ui_story_1012_10120801_112_dialog_content = "「律法之弦」難以啟動，且使用代價巨大。",
  ui_story_1012_10120801_113_dialog_content = "輔腦不會授權任何空裔開啟「律法之弦」。",
  ui_story_1012_10120801_114_dialog_content = "「權限」？怎麼又是因為「權限」？！",
  ui_story_1012_10120801_115_dialog_content = "重複：「律法之弦」難以啟動，且使用代價巨大。",
  ui_story_1012_10120801_116_dialog_content = "輔腦不會授權任何空裔......",
  ui_story_1012_10120801_117_dialog_content = "PlayerName，不必跟這個機器理論。",
  ui_story_1012_10120801_118_dialog_content = "我們作為擁有自主意識的生物，不能被機器束縛了手腳。",
  ui_story_1012_10120801_119_dialog_content = "（卡蓮說得對，而且，我不能再有那樣的經歷了......）",
  ui_story_1012_10120801_120_dialog_content = "（面對暗鬼大軍壓境，卻沒有任何空裔能夠拯救的經歷。）",
  ui_story_1012_10120801_121_dialog_content = "我不能躲在這裡，我要親自參與這場對抗日蝕的戰爭！",
  ui_story_1012_10120801_122_dialog_content = "我明白你的想法，PlayerName，但是......",
  ui_story_1012_10120801_123_dialog_content = "薇絲......",
  ui_story_1012_10120801_124_dialog_content = "「同調」仍然沒有成功，薇絲還要持續承受著這個漫長的過程。",
  ui_story_1012_10120801_125_dialog_content = "PlayerName，待我們離開和弦區，就讓輔腦改變入口的結構吧。",
  ui_story_1012_10120801_126_dialog_content = "請務必封閉和弦區入口，改變密道的結構......",
  ui_story_1012_10120801_127_dialog_content = "為薇絲製造一個足夠堅固的<color=#FFB400>繭房</color>。",
  ui_story_1012_10120801_128_dialog_content = "這是當然。",
  ui_story_1012_10120801_129_dialog_content = "（薇絲，請妳一定要在「和弦紐帶」的力量中醒來......）",
  ui_story_1012_10120801_130_dialog_content = "（我們等著妳的重生。）",
  ui_story_1012_10120801_131_dialog_content = "我們晚點見，薇絲。",
  ui_story_1012_10120901_1_dialog_content = "<color=#e8d9bb>主塔，入口通道</color>",
  ui_story_1012_10120901_2_dialog_content = "<color=#e8d9bb>踏踏踏踏......踏踏踏踏......</color>",
  ui_story_1012_10120901_3_dialog_content = "再往前走就是我們來時的入口了。",
  ui_story_1012_10120901_4_dialog_content = "PlayerName，我不想對你說教，但是......",
  ui_story_1012_10120901_5_dialog_content = "不要害怕。",
  ui_story_1012_10120901_6_dialog_content = "卡，卡蓮......？",
  ui_story_1012_10120901_7_dialog_content = "你要時刻記住，你即將為屬於你的土地而戰。",
  ui_story_1012_10120901_8_dialog_content = "這是一種無上的榮譽，不應該心懷恐懼。",
  ui_story_1012_10120901_9_dialog_content = "伯利恆陛下......曾經對我如此教誨。",
  ui_story_1012_10120901_10_dialog_content = "謝謝妳，卡蓮。",
  ui_story_1012_10120901_11_dialog_content = "我已經做好覺悟了。",
  ui_story_1012_10120901_12_dialog_content = "嗯。那麼，我們一起回到塔外的世界吧。",
  ui_story_1012_10120901_13_dialog_content = "這、這是……",
  ui_story_1012_10120901_14_dialog_content = "<color=#e8d9bb>劈......啪......劈啪......</color>",
  ui_story_1012_10120901_15_dialog_content = "<anim type=Shake><size=50>吼！！！！！！</size></anim>",
  ui_story_1012_10120901_16_dialog_content = "那個時候的空谷......也是這樣的景象嗎......",
  ui_story_1012_10120901_17_dialog_content = "PlayerName，小心——",
  ui_story_1012_10120901_18_dialog_content = "嘎......",
  ui_story_1012_10120901_19_dialog_content = "桀桀桀桀......",
  ui_story_1012_10120901_20_dialog_content = "先人一步的情報可比千軍萬馬都管用。",
  ui_story_1012_10120901_21_dialog_content = "更何況——眼前的形勢已經很明朗了。",
  ui_story_1012_10120901_22_dialog_content = "你們派出的這點兵力，無論如何都不能跟日蝕大軍相抗衡。",
  ui_story_1012_10120901_23_dialog_content = "呵，打仗之前說廢話是你們日蝕的傳統嗎？",
  ui_story_1012_10120901_24_dialog_content = "連篇的空話可不會助長你們的力量。",
  ui_story_1012_10120901_24X1_dialog_content = "（......這麼想來，伯利恆陛下應該也趕到了。）",
  ui_story_1012_10120901_24X2_dialog_content = "PlayerName，我先去回歸塔另一側探查情況，和伯利恆陛下匯合。",
  ui_story_1012_10120901_24X3_dialog_content = "你和啟光帶來的這些支援兵留在這邊，沒問題吧？",
  ui_story_1012_10120901_24X4_dialog_content = "這樣也好，有情況的話記得保持聯繫。",
  ui_story_1012_10120901_24X5_dialog_content = "那妳多保重，卡蓮。",
  ui_story_1012_10120901_25_dialog_content = "報告大元帥，最新情報：第二軍團的支援小隊已與巴頓軍團長匯合。",
  ui_story_1012_10120901_26_dialog_content = "隨時等候您的指令。",
  ui_story_1012_10120901_27_dialog_content = "好。通知支援小隊，集中主要兵力於前線戰場，採取密集隊形突擊出戰。",
  ui_story_1012_10120901_28_dialog_content = "剩餘兵力分兩翼，從後方牽制日蝕的後備軍。",
  ui_story_1012_10120901_29_dialog_content = "明白了！",
  ui_story_1012_10120901_30_dialog_content = "明白了還不動？",
  ui_story_1012_10120901_31_dialog_content = "......大元帥，您還沒有為我安排作戰任務。",
  ui_story_1012_10120901_32_dialog_content = "哈哈哈哈哈哈哈哈哈哈，那麼，你，去後方守護那座塔，隨時待命。",
  ui_story_1012_10120901_33_dialog_content = "守護......塔？",
  ui_story_1012_10120901_34_dialog_content = "看到那座最大的白塔了嗎？",
  ui_story_1012_10120901_35_dialog_content = "看到了，可是——",
  ui_story_1012_10120901_36_dialog_content = "那座白塔，是我們此次馳援空谷的全部目的。",
  ui_story_1012_10120901_37_dialog_content = "這個任務雖然不在前線，但是比前線任務更加重要。",
  ui_story_1012_10120901_38_dialog_content = "晚點我會找你交接工作，戰地情報也還需要你去傳達，放心吧。",
  ui_story_1012_10120901_39_dialog_content = "......明白了！",
  ui_story_1012_10120901_40_dialog_content = "至於PlayerName就暫時先跟著我吧。",
  ui_story_1012_10120901_41_dialog_content = "哎呀，你身邊好像缺了兩位呢......",
  ui_story_1012_10120901_42_dialog_content = "萊因哈特，薇絲她......",
  ui_story_1012_10120901_43_dialog_content = "薇絲中尉的事，巴頓軍團長已經跟我報告過了。",
  ui_story_1012_10120901_44_dialog_content = "你要對這座塔裡面的玩意有信心，這是你的先祖留給你的寶物。",
  ui_story_1012_10120901_45_dialog_content = "何況，戰爭在即，也不該有任何喪氣的念頭。",
  ui_story_1012_10120901_46_dialog_content = "拿出你的士氣，把頭抬起來！",
  ui_story_1012_10120901_47_dialog_content = "......是！",
  ui_story_1012_10120901_48_dialog_content = "這就對了！",
  ui_story_1012_10120901_49_dialog_content = "<color=#e8d9bb>與此同時．回歸塔另一側</color>",
  ui_story_1012_10120901_50_dialog_content = "<size=45>女王陛下！！！</size>",
  ui_story_1012_10120901_51_dialog_content = "身為女王陛下的護衛，我實在太失職了！",
  ui_story_1012_10120901_52_dialog_content = "請女王陛下勿再丟下提亞拉，獨自一人對付暗鬼！",
  ui_story_1012_10120901_53_dialog_content = "讓提亞拉為女王陛下衝鋒陷陣吧！",
  ui_story_1012_10120901_54_dialog_content = "提亞拉，妳常年行走於雪林，最擅長的是監視與偷襲......",
  ui_story_1012_10120901_55_dialog_content = "這也是北境此次援助空谷的作戰策略。",
  ui_story_1012_10120901_56_dialog_content = "前線就交給那些嗜戰如命的光靈吧，我們採取保守態度，守在這座白塔旁邊。",
  ui_story_1012_10120901_57_dialog_content = "我已將北境的全部兵力撤回白塔周圍，並加強警戒。",
  ui_story_1012_10120901_58_dialog_content = "除非前線崩潰，否則那些暗鬼沒辦法輕易深入這裡。",
  ui_story_1012_10120901_59_dialog_content = "是的，女王陛下！",
  ui_story_1012_10120901_60_dialog_content = "......以及，在戰場上，就不需要拘泥於那些麻煩的稱呼了。",
  ui_story_1012_10120901_61_dialog_content = "直接叫我的名字就可以。",
  ui_story_1012_10120901_62_dialog_content = "來，躲到我張開的防護罩裡來吧。",
  ui_story_1012_10120901_63_dialog_content = "好......好的！女王陛下！",
  ui_story_1012_10120901_64_dialog_content = "伯利恆陛下，沒想到您能這麼快趕到！",
  ui_story_1012_10120901_65_dialog_content = "卡蓮，我們也有一陣子沒見了。",
  ui_story_1012_10120901_66_dialog_content = "當然，現在不是敘舊的時候。妳可以把目前的狀況看成一次考試......",
  ui_story_1012_10120901_67_dialog_content = "讓我看看妳能獨自解決多少場戰鬥。",
  ui_story_1012_10120901_68_dialog_content = "卡蓮殿下絕對不是孤身一人！",
  ui_story_1012_10120901_69_dialog_content = "貝爾塔？",
  ui_story_1012_10120901_70_dialog_content = "妳......怎麼沒有和拉斐爾待在一起？",
  ui_story_1012_10120901_71_dialog_content = "回卡蓮殿下！貝爾塔奉城主之命，率領騎士團的精銳部隊前來支援您！",
  ui_story_1012_10120901_72_dialog_content = "請為我們下達命令吧，<color=#FFB400>卡蓮隊長</color>！",
  ui_story_1012_10120901_73_dialog_content = "（原來如此，是父親的意思嗎......）",
  ui_story_1012_10120901_74_dialog_content = "（父親竟然也迅速出兵表態。）",
  ui_story_1012_10120901_75_dialog_content = "白夜至上，請諸位舉起手中的武器，和我趕往前線吧——",
  ui_story_1012_10120901_76_dialog_content = "白晝刺破夜空，黑暗無所遁形！",
  ui_story_1012_10120901_77_dialog_content = "白夜至上！",
  ui_story_1012_10120901_78_dialog_content = "<color=#e8d9bb>空之山谷，日蝕駐軍處</color>",
  ui_story_1012_10120901_79_dialog_content = "（日蝕語）連白夜城的都來了嗎？那個老頭子真是從不會錯過好康。",
  ui_story_1012_10120901_80_dialog_content = "（日蝕語）......這......這次，我將讓白夜城知道，與日蝕對抗的代價。",
  ui_story_1012_10120901_81_dialog_content = "（日蝕語）何止白夜城。佔領空谷後，我們將得到控制整個大陸的絕對力量！",
  ui_story_1012_10120901_82_dialog_content = "（日蝕語）桀桀桀桀桀桀......",
  ui_story_1012_10120901_83_dialog_content = "（日蝕語）我的日蝕同僚們，屬於我們的時代即將到來......",
  ui_story_1012_10120901_84_dialog_content = "（日蝕語）勝利已經握在我們掌中。",
  ui_story_1012_10120901_85_dialog_content = "（日蝕語）鮮紅的血液將再次洗滌這片空谷！",
  ui_story_1012_10120901_86_dialog_content = "（日蝕語）進軍空之山谷！佔領白塔！趕盡殺絕！",
  ui_story_1012_10120901_87_dialog_content = "<size=45>（日蝕語）開戰！！！！！！</size>",
  ui_story_1012_10120901_88_dialog_content = "<anim type=Shake><size=45>吼吼吼！！！！！！</size></anim>",
  ui_story_1012_10120901_89_dialog_content = "（日蝕語）過了今天，艾斯特拉大陸將不會再見到太陽升起......",
  ui_story_1012_10121002_1_dialog_content = "PlayerName，你的指揮還是一如既往地穩定。",
  ui_story_1012_10121002_2_dialog_content = "在這種情況下仍能保持鎮定，該說你是冷靜，還是單純呢？",
  ui_story_1012_10121002_3_dialog_content = "我大概開始懂了，為何你聚集這麼多人的信任於一身。",
  ui_story_1012_10121002_4_dialog_content = "過......過獎了......",
  ui_story_1012_10121002_5_dialog_content = "報告大元帥，最新情報：日蝕方的第一波進攻已受到壓制！",
  ui_story_1012_10121002_6_dialog_content = "雖然局勢尚不明朗，目前支援小隊的戰線仍十分穩固。",
  ui_story_1012_10121002_7_dialog_content = "很好，請各位務必保留戰力，剛才那場戰鬥僅是個開頭。",
  ui_story_1012_10121002_8_dialog_content = "通知巴頓軍團長，率領支援小隊與我們的友方勢力配合。",
  ui_story_1012_10121002_9_dialog_content = "沒錯。",
  ui_story_1012_10121002_10_dialog_content = "雖然卡蓮已經不是小孩子了......",
  ui_story_1012_10121002_11_dialog_content = "但放她在前線跟妳的那群手下共同作戰，她大概也不太適應吧。",
  ui_story_1012_10121002_12_dialog_content = "哈哈哈！一個生活在安逸中的士兵，永遠沒辦法長成將軍。",
  ui_story_1012_10121002_13_dialog_content = "聽說卡蓮是妳養大的？",
  ui_story_1012_10121002_14_dialog_content = "妳看起來比舒瓦茲更像她的父親啊，女王！",
  ui_story_1012_10121002_15_dialog_content = "......請注意您的措辭，萊因哈特閣下。",
  ui_story_1012_10121002_16_dialog_content = "請您對女王陛下放尊重點！",
  ui_story_1012_10121002_17_dialog_content = "吼！ ！ ！",
  ui_story_1012_10121002_18_dialog_content = "唔呃——",
  ui_story_1012_10121002_19_dialog_content = "冰解之時！",
  ui_story_1012_10121002_20_dialog_content = "戰鬥還在繼續，我不喜歡閒話家常。",
  ui_story_1012_10121002_21_dialog_content = "雖然情勢仍在可以控制的範圍內，麻煩閣下不要分神。",
  ui_story_1012_10121002_22_dialog_content = "既然妳這麼說，那我就帶著剩餘兵力去塔前對付日蝕吧。",
  ui_story_1012_10121002_23_dialog_content = "我們這方還遊刃有餘呢！",
  ui_story_1012_10121002_24_dialog_content = "<color=#e8d9bb>空之山谷，戰場前線</color>",
  ui_story_1012_10121002_25_dialog_content = "啥？！配合那幾個白夜城的？",
  ui_story_1012_10121002_26_dialog_content = "就是這麼一回事。",
  ui_story_1012_10121002_27_dialog_content = "罷了罷了，我知道了，你的傳令任務已經達成。",
  ui_story_1012_10121002_28_dialog_content = "唔？！",
  ui_story_1012_10121002_29_dialog_content = "吼！ ！ ！",
  ui_story_1012_10121002_30_dialog_content = "嘎......",
  ui_story_1012_10121002_31_dialog_content = "行了，這裡還沒掃蕩完畢，你快回去和大元帥守塔吧。",
  ui_story_1012_10121002_32_dialog_content = "<color=#e8d9bb>砰——！！！</color>",
  ui_story_1012_10121002_33_dialog_content = "噫！",
  ui_story_1012_10121002_34_dialog_content = "咦？！",
  ui_story_1012_10121002_35_dialog_content = "啟光的，你搞什麼啊！",
  ui_story_1012_10121002_36_dialog_content = "不......不是我。剛才的地面突然震......",
  ui_story_1012_10121002_37_dialog_content = "真是的，別找麻煩啊！",
  ui_story_1012_10121002_38_dialog_content = "<color=#e8d9bb>砰——！！！</color>",
  ui_story_1012_10121002_39_dialog_content = "嘎......嘎？！",
  ui_story_1012_10121002_40_dialog_content = "這是......被日蝕用大砲投過來的暗鬼！",
  ui_story_1012_10121002_41_dialog_content = "還真方便呢。",
  ui_story_1012_10121002_42_dialog_content = "嘎......",
  ui_story_1012_10121002_43_dialog_content = "這裡是前線，不是起內訌的地方，如果有人不是為了打仗而來......",
  ui_story_1012_10121002_44_dialog_content = "就趁早離隊回家。",
  ui_story_1012_10121002_45_dialog_content = "是！",
  ui_story_1012_10121002_46_dialog_content = "你跟著「是」個什麼勁啊！",
  ui_story_1012_10121002_47_dialog_content = "對......對不起！",
  ui_story_1012_10121002_48_dialog_content = "<color=#e8d9bb>砰——！！！</color>",
  ui_story_1012_10121002_49_dialog_content = "這個砲彈是？",
  ui_story_1012_10121002_50_dialog_content = "奇怪，它這次並沒有飛向我們，而且......",
  ui_story_1012_10121002_51_dialog_content = "還看似夾帶著某種令人極度不安的陰影，這究竟......",
  ui_story_1012_10121002_52_dialog_content = "糟了！",
  ui_story_1012_10121002_53_dialog_content = "是<color=#FFB400>暗能</color>！",
  ui_story_1012_10121002_54_dialog_content = "剛才那幾發砲彈只是測試......",
  ui_story_1012_10121002_55_dialog_content = "這發<color=#FFB400>暗能砲彈</color>衝著回歸塔而去！",
  ui_story_1012_10121002_56_dialog_content = "（回歸塔？！）",
  ui_story_1012_10121002_57_dialog_content = "戰場轉移，第二軍團支援小隊聽令！",
  ui_story_1012_10121002_58_dialog_content = "趕赴回歸塔，輔助大元帥！",
  ui_story_1012_10121101_1_dialog_content = "<color=#e8d9bb>空之山谷，回歸塔旁</color>",
  ui_story_1012_10121101_2_dialog_content = "<color=#e8d9bb>砰——！！！</color>",
  ui_story_1012_10121101_3_dialog_content = "（唔？！什麼東西在頭頂炸開了！）",
  ui_story_1012_10121101_4_dialog_content = "（不行，身為女王陛下的護衛，務必提起精神保護女王陛下！）",
  ui_story_1012_10121101_5_dialog_content = "（怎麼回事，突然感覺好噁心！）",
  ui_story_1012_10121101_6_dialog_content = "（這種熟悉的噁心感......）",
  ui_story_1012_10121101_7_dialog_content = "？！",
  ui_story_1012_10121101_8_dialog_content = "是<color=#FFB400>暗能</color>！",
  ui_story_1012_10121101_9_dialog_content = "凝剎！",
  ui_story_1012_10121101_10_dialog_content = "防護罩的大小有限，請各位盡量湊到防護範圍之內。",
  ui_story_1012_10121101_11_dialog_content = "不要被巨大的暗能所波及！",
  ui_story_1012_10121101_12_dialog_content = "咳咳......這點影響根本不要緊！",
  ui_story_1012_10121101_13_dialog_content = "一味躲避可不是長久之計。",
  ui_story_1012_10121101_14_dialog_content = "這樣下去，我們必須主動採取新的壓制策略。",
  ui_story_1012_10121101_15_dialog_content = "大元帥！",
  ui_story_1012_10121101_16_dialog_content = "阿納托利，你回來得正好......",
  ui_story_1012_10121101_17_dialog_content = "喔？看來你把最關鍵的戰力也帶來了。",
  ui_story_1012_10121101_18_dialog_content = "第二軍團長巴頓報到。",
  ui_story_1012_10121101_19_dialog_content = "下達命令吧，大元帥。",
  ui_story_1012_10121101_20_dialog_content = "戰機轉瞬即逝。",
  ui_story_1012_10121101_21_dialog_content = "來得很是時候，巴頓軍團長！",
  ui_story_1012_10121101_22_dialog_content = "呃，大......大元帥？",
  ui_story_1012_10121101_23_dialog_content = "帶著這個腦子裡只有情報的士兵，讓他見識一番吧！",
  ui_story_1012_10121101_24_dialog_content = "請務必守在這裡，為這座白塔吸引日蝕全部的火力，你能做到吧？",
  ui_story_1012_10121101_25_dialog_content = "我要讓日蝕知道，不是只有他們會搞偷襲。",
  ui_story_1012_10121101_26_dialog_content = "偷襲日蝕的作戰計畫嗎？我喜歡。",
  ui_story_1012_10121101_27_dialog_content = "妳放心去吧，這個要地就交給我了！",
  ui_story_1012_10121101_28_dialog_content = "（看著萊因哈特意氣風發的身影，我幾乎忘卻暗能帶來的異樣感......）",
  ui_story_1012_10121101_29_dialog_content = "（日蝕方的暗能大砲，夾帶著不祥的黑暗，持續朝我們這邊發射......）",
  ui_story_1012_10121101_30_dialog_content = "（她明明向著黑夜那邊奔赴，臉上卻是如沐春風的表情。）",
  ui_story_1012_10121101_31_dialog_content = "（天才一樣的戰士、危險的野心家......啟光人對她的評價眾說紛紜。）",
  ui_story_1012_10121101_32_dialog_content = "（但只要見過她戰場上的樣子，就一定會明白「啟明之光」真正的含義——）",
  ui_story_1012_10121101_33_dialog_content = "（在不見希望的黑暗裡，她就像一顆閃閃發光的啟明星。）",
  ui_story_1012_10121101_34_dialog_content = "<size=33>PlayerName，願意助我一臂之力嗎？</size>",
  ui_story_1012_10121101_35_dialog_content = "<size=33>有些事情，只有你這個空裔才能做到。</size>",
  ui_story_1012_10121101_36_dialog_content = "哎？ ！",
  ui_story_1012_10121101_37_dialog_content = "等......等等？！",
  ui_story_1012_10121101_38_dialog_content = "別胡亂把人扛起來啊！先問過我好嗎？",
  ui_story_1012_10121101_39_dialog_content = "（動不動就扛人是你們啟光的傳統嗎？！）",
  ui_story_1012_10121101_40_dialog_content = "哈哈哈哈......抱歉抱歉，稍微忍受一下！",
  ui_story_1012_10121101_41_dialog_content = "傳說空裔能看到光的顏色，那麼一定也能看到<color=#FFB400>暗能的來源</color>吧！",
  ui_story_1012_10121101_42_dialog_content = "暫時請你充當我的導航。",
  ui_story_1012_10121101_43_dialog_content = "我們去搗毀日蝕的暗能大砲！",
  ui_story_1012_10121101_44_dialog_content = "<color=#e8d9bb>空之山谷，戰場前線</color>",
  ui_story_1012_10121101_45_dialog_content = "卡蓮隊長，這已經是這波突襲中的最後一隻暗鬼了。",
  ui_story_1012_10121101_46_dialog_content = "我們要跟著啟光那群人轉移戰線嗎？",
  ui_story_1012_10121101_47_dialog_content = "不，我們不能製造戰線的缺口。",
  ui_story_1012_10121101_48_dialog_content = "我們一旦撤兵，就是在為日蝕讓路。",
  ui_story_1012_10121101_49_dialog_content = "真是稀奇啊！",
  ui_story_1012_10121101_50_dialog_content = "白夜城城主居然捨得派自己的女兒上戰場......",
  ui_story_1012_10121101_51_dialog_content = "？！",
  ui_story_1012_10121101_52_dialog_content = "我很早就想體驗一下單獨和公主殿下交手的感覺了。",
  ui_story_1012_10121101_53_dialog_content = "（果然來了，我猜得沒有錯......）",
  ui_story_1012_10121101_54_dialog_content = "米倫·戈蒂埃，你早已是白夜城的手下敗將。",
  ui_story_1012_10121101_55_dialog_content = "受到審判庭的追緝，居然還自投羅網。",
  ui_story_1012_10121101_56_dialog_content = "呵呵～公主殿下，我的出現，就這麼讓妳念念不忘嗎？",
  ui_story_1012_10121101_57_dialog_content = "這樣的話，我也不算是白折騰了一圈「視界」的實驗。",
  ui_story_1012_10121101_57X1_dialog_content = "這裡只有我們和妳的那幾個雜兵......",
  ui_story_1012_10121101_57X2_dialog_content = "究竟是誰在自投羅網，我們不要這麼輕率地下定結論喔。",
  ui_story_1012_10121101_58_dialog_content = "請不要這麼噁心地稱呼我。",
  ui_story_1012_10121101_59_dialog_content = "噫......噫呀！是冰！",
  ui_story_1012_10121101_60_dialog_content = "搞什麼啊？！妳怎麼跟那個騎著龍的冰凍怪女一樣！",
  ui_story_1012_10121101_61_dialog_content = "「冰凍怪女」......難道是指伯利恆陛下？！",
  ui_story_1012_10121101_62_dialog_content = "竟然敢使用這種稱呼侮辱伯利恆陛下......",
  ui_story_1012_10121101_63_dialog_content = "不可饒恕！！！",
  ui_story_1012_10121101_64_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_1012_10121101_65_dialog_content = "看來你們這邊有點麻煩呢。",
  ui_story_1012_10121101_66_dialog_content = "感謝PlayerName吧，他在半路上感知到了米倫·戈蒂埃的暗能......",
  ui_story_1012_10121101_67_dialog_content = "無論如何也要過來援助一把。",
  ui_story_1012_10121101_68_dialog_content = "PlayerName，既然你們過來了，就不要耽誤時間。",
  ui_story_1012_10121101_69_dialog_content = "日蝕那邊的大砲暫時停息了，趁現在去終結他們的伎倆吧。",
  ui_story_1012_10121101_70_dialog_content = "至於米倫，就......",
  ui_story_1012_10121101_71_dialog_content = "......咦？",
  ui_story_1012_10121101_72_dialog_content = "哼，跑得真快啊。",
  ui_story_1012_10121101_73_dialog_content = "嗯，事不宜遲，我們要接著突擊了！",
  ui_story_1012_10121101_74_dialog_content = "前線由我這邊來頂住，妳帶著騎士團去和主力軍會合吧。",
  ui_story_1012_10121101_75_dialog_content = "暗鬼壓境、暗能密布，那座白塔現在更需要能夠穩定輸出的兵力。",
  ui_story_1012_10121101_76_dialog_content = "也好，那這裡就拜託了。",
  ui_story_1012_10121101_77_dialog_content = "......話說回來，PlayerName，你的臉色為什麼這麼差？",
  ui_story_1012_10121101_78_dialog_content = "（「感知範圍內的暗能過於濃厚，實在是太噁心了」......）",
  ui_story_1012_10121101_79_dialog_content = "（但這種話我實在不好意思說出來！）",
  ui_story_1012_10121101_80_dialog_content = "臉......臉色差說明我找的方向是對的！",
  ui_story_1012_10121101_81_dialog_content = "那我們暫時兵分兩路，等著我這邊的好消息吧，卡蓮！",
  ui_story_1012_10121101_82_dialog_content = "請保重。",
  ui_story_1012_10121101_83_dialog_content = "那麼就快走吧，PlayerName。",
  ui_story_1012_10121101_84_dialog_content = "暗能大砲就在前方，馬上要迎來一場血腥混戰了。",
  ui_story_1012_10121102_1_dialog_content = "幹得漂亮，PlayerName。",
  ui_story_1012_10121102_2_dialog_content = "這些暗能大砲真是不堪一擊。",
  ui_story_1012_10121102_3_dialog_content = "剛才這台就是最後一台大砲了嗎？",
  ui_story_1012_10121102_4_dialog_content = "我再確認一下......",
  ui_story_1012_10121102_5_option_content = "強制感應！",
  ui_story_1012_10121102_6_dialog_content = "似乎，已經沒有那種聚集在一起的混合暗能了，但是......",
  ui_story_1012_10121102_7_dialog_content = "吼！ ！ ！",
  ui_story_1012_10121102_8_dialog_content = "吼！！！！！！",
  ui_story_1012_10121102_9_dialog_content = "這些雜兵還真是有點麻煩。",
  ui_story_1012_10121102_10_dialog_content = "牠們釋放出的暗能也會干擾你的判斷吧？",
  ui_story_1012_10121102_11_dialog_content = "既然這樣......就先用我的槍捅穿牠們吧！",
  ui_story_1012_10121102_12_dialog_content = "嚐嚐真正的力量！",
  ui_story_1012_10121102_13_dialog_content = "嘎......",
  ui_story_1012_10121102_14_dialog_content = "妳還是這麼戀戰，萊因哈特。",
  ui_story_1012_10121102_15_dialog_content = "這種狂熱遲早有一天會把妳自己斷送掉的。",
  ui_story_1012_10121102_16_dialog_content = "妳就想跟我說這些嗎？",
  ui_story_1012_10121102_17_dialog_content = "我還活著這件事，好像也並沒有讓妳多驚訝啊，吞羅？",
  ui_story_1012_10121102_18_dialog_content = "從<color=#FFB400>那個時候</color>妳就已經知道了吧......",
  ui_story_1012_10121102_19_dialog_content = "想打死我這樣的「怪物」，是相當困難的事。",
  ui_story_1012_10121102_20_dialog_content = "妳還真是相當自信。",
  ui_story_1012_10121102_21_dialog_content = "如果妳是衝著斐桀洛來的，那傢伙就在前面。",
  ui_story_1012_10121102_22_dialog_content = "我沒空奉陪。",
  ui_story_1012_10121102_23_dialog_content = "（日蝕語）我們走。",
  ui_story_1012_10121102_24_dialog_content = "（日蝕語）是。",
  ui_story_1012_10121102_25_dialog_content = "（好奇怪，吞羅為什麼突然變得有點親切？）",
  ui_story_1012_10121102_26_dialog_content = "（竟然還主動為我們指路......）",
  ui_story_1012_10121102_27_dialog_content = "萊......萊因哈特，我覺得......吞羅很不對勁。",
  ui_story_1012_10121102_28_dialog_content = "......",
  ui_story_1012_10121102_29_dialog_content = "PlayerName，快去觀察塔底戰線的狀態！",
  ui_story_1012_10121102_30_dialog_content = "是......是的！",
  ui_story_1012_10121102_31_dialog_content = "桀桀桀桀......",
  ui_story_1012_10121102_32_dialog_content = "連妳妹妹也呼攏不了妳嗎？",
  ui_story_1012_10121102_33_dialog_content = "你們光靈有時真是比暗鬼還要冷血的生物。",
  ui_story_1012_10121102_34_dialog_content = "......嘖。",
  ui_story_1012_10121102_35_dialog_content = "（他們果然在針對我。）",
  ui_story_1012_10121102_36_dialog_content = "（如果我沒有殺過來，就繼續用暗能大砲消耗我方兵力......）",
  ui_story_1012_10121102_37_dialog_content = "（如果我過來搗毀大砲，就立刻出兵迅擊白塔......）",
  ui_story_1012_10121102_38_dialog_content = "（......我們的兵力，終究還是太少了。）",
  ui_story_1012_10121102_39_dialog_content = "PlayerName，我們快走！",
  ui_story_1012_10121102_40_dialog_content = "妳以為這樣就能改變局勢嗎？",
  ui_story_1012_10121102_41_dialog_content = "光靈的失敗早已成為定局。",
  ui_story_1012_10121102_42_dialog_content = "妳所做的，只不過是在延後妳們的死亡。",
  ui_story_1012_10121102_43_dialog_content = "回去看看妳<color=#FFB400>潰不成軍</color>的同胞們吧！",
  ui_story_1012_10121102_44_dialog_content = "看看他們是如何在日蝕骨乾和暗鬼大軍的手中變成渣粉。",
  ui_story_1012_10121102_45_dialog_content = "什麼......",
  ui_story_1012_10121102_46_dialog_content = "桀桀桀桀桀桀......光是想像一下，都覺得是一幅不容錯過的場景。",
  ui_story_1012_10121102_47_dialog_content = "我就先走一步了。",
  ui_story_1012_10121102_48_dialog_content = "享受妳的失敗吧，萊因哈特。",
  ui_story_1012_10121102_49_dialog_content = "機不可失，PlayerName，我們追上他！",
  ui_story_1012_10121102_50_dialog_content = "我們......下一步該怎麼辦，萊因哈特？",
  ui_story_1012_10121102_51_dialog_content = "怎麼辦？當然是戰鬥！",
  ui_story_1012_10121102_52_dialog_content = "相信你的戰友，然後一直戰鬥下去......",
  ui_story_1012_10121102_53_dialog_content = "直到我們真正倒下的那一刻！",
  ui_story_1012_10121301_1_dialog_content = "嘖嘖，多麼淒美的場景啊。",
  ui_story_1012_10121301_2_dialog_content = "你們辛苦維繫的那層蛋殼已經出現裂縫。",
  ui_story_1012_10121301_3_dialog_content = "我要把手指放在裂縫上，一點一點往下壓。",
  ui_story_1012_10121301_4_dialog_content = "我要感受你們在我掌心裡碎裂瓦解。",
  ui_story_1012_10121301_5_dialog_content = "暗鬼們，渴望殺戮的傢伙們。",
  ui_story_1012_10121301_6_dialog_content = "聞到傷口的血腥味嗎？",
  ui_story_1012_10121301_7_dialog_content = "給我瞄準他們的痛處——",
  ui_story_1012_10121301_8_dialog_content = "撲滅最後一點光！",
  ui_story_1012_10121301_9_dialog_content = "嘎——！！！",
  ui_story_1012_10121301_10_dialog_content = "大批的暗鬼殺過來了！",
  ui_story_1012_10121301_11_dialog_content = "我們......還能把缺口堵上嗎！",
  ui_story_1012_10121301_12_dialog_content = "從戰術上來看，防線已經被攻破，想要補救風險很大。",
  ui_story_1012_10121301_13_dialog_content = "缺口處面臨內外包夾的威脅，而且......",
  ui_story_1012_10121301_14_dialog_content = "好了，不要再說下去了！",
  ui_story_1012_10121301_15_dialog_content = "這可是戰場，沒有人願意聽你的長篇大論！",
  ui_story_1012_10121301_16_dialog_content = "正是因為身處戰場，理性的判斷更為重要。",
  ui_story_1012_10121301_17_dialog_content = "那麼你的理性判斷得出的結論是？",
  ui_story_1012_10121301_18_dialog_content = "繼續守下去，我們會全軍覆沒。",
  ui_story_1012_10121301_19_dialog_content = "......",
  ui_story_1012_10121301_20_dialog_content = "理性的選擇是放棄白塔，選一個方向合力突圍。",
  ui_story_1012_10121301_21_dialog_content = "藉單兵作戰能力強於對手的特點，突圍可望成功。",
  ui_story_1012_10121301_22_dialog_content = "那你為什麼還不去突圍？",
  ui_story_1012_10121301_23_dialog_content = "我不能走。",
  ui_story_1012_10121301_24_dialog_content = "大元帥給我的命令是死守，我必須留在這裡戰鬥。",
  ui_story_1012_10121301_25_dialog_content = "哈哈哈，看起來你的理性判斷沒有起作用啊，啟光的士兵。",
  ui_story_1012_10121301_26_dialog_content = "身為軍人，服從命令最優先。我只是在這樣的條件下......",
  ui_story_1012_10121301_27_dialog_content = "我知道了，我知道了。",
  ui_story_1012_10121301_28_dialog_content = "但是既然改變不了眼下的局勢......",
  ui_story_1012_10121301_29_dialog_content = "不如先讓你聰明的腦袋歇一歇，甩開手來戰鬥吧！",
  ui_story_1012_10121301_30_dialog_content = "哎呀呀，那可不行喔，漂亮的小姐。",
  ui_story_1012_10121301_31_dialog_content = "再讓妳給我們添亂，斐桀洛大人會生氣的。",
  ui_story_1012_10121301_32_dialog_content = "誰？！",
  ui_story_1012_10121301_33_dialog_content = "這是......什麼東西？",
  ui_story_1012_10121301_34_dialog_content = "小心！",
  ui_story_1012_10121301_35_dialog_content = "嘖，礙事的傢伙。",
  ui_story_1012_10121301_36_dialog_content = "本來以為是我和漂亮小姐的兩人世界，怎麼插進來個臭男人啊！",
  ui_story_1012_10121301_37_dialog_content = "你......！",
  ui_story_1012_10121301_38_dialog_content = "注意點，我們周圍的光能好像受到極大的限制。",
  ui_story_1012_10121301_39_dialog_content = "在這裡難以發揮足夠的力量。",
  ui_story_1012_10121301_40_dialog_content = "是嗎？",
  ui_story_1012_10121301_41_dialog_content = "管不了那麼多了，我現在腦袋裡想的只有把拳頭打在那傢伙臉上！",
  ui_story_1012_10121301_42_dialog_content = "真熱情啊，小姐。",
  ui_story_1012_10121301_43_dialog_content = "不要心急，我們有很多時間可以玩。",
  ui_story_1012_10121301_44_dialog_content = "讓我們來慢慢認識彼此吧！",
  ui_story_1012_10121301_45_dialog_content = "嘎——！",
  ui_story_1012_10121301_46_dialog_content = "......",
  ui_story_1012_10121301_47_dialog_content = "後面的那個人，你不出手嗎？",
  ui_story_1012_10121301_48_dialog_content = "......",
  ui_story_1012_10121301_49_dialog_content = "北境的女王......",
  ui_story_1012_10121301_49X1_dialog_content = "我記得你，白夜慶典上的忤逆者。",
  ui_story_1012_10121301_49X2_dialog_content = "當時的你要更加鋒利些。",
  ui_story_1012_10121301_50_dialog_content = "但現在，這個戰場上心懷遲疑的人只有你一個。",
  ui_story_1012_10121301_51_dialog_content = "......",
  ui_story_1012_10121301_52_dialog_content = "北境女王，強大如妳還看不清局勢嗎？",
  ui_story_1012_10121301_53_dialog_content = "光靈的失敗已成定局，妳為什麼還要戰鬥？",
  ui_story_1012_10121301_54_dialog_content = "光靈的失敗已成定局，你為什麼不敢戰鬥？",
  ui_story_1012_10121301_55_dialog_content = "我......",
  ui_story_1012_10121301_56_dialog_content = "戰鬥與否，這是你站在這裡之前就該想清楚的問題。",
  ui_story_1012_10121301_57_dialog_content = "以你現在的樣子，轉眼就會被殺死。",
  ui_story_1012_10121301_58_dialog_content = "是嗎......",
  ui_story_1012_10121301_59_dialog_content = "那麼請容我斗膽——",
  ui_story_1012_10121301_60_dialog_content = "與北境女王一戰吧！",
  ui_story_1012_10121301_61_dialog_content = "嗚哇，好大的怪物！",
  ui_story_1012_10121301_62_dialog_content = "那是......女王陛下的方向？",
  ui_story_1012_10121301_63_dialog_content = "女王陛下！！！",
  ui_story_1012_10121301_64_dialog_content = "嘎——！",
  ui_story_1012_10121301_65_dialog_content = "喂！討厭的傢伙！不要礙事啊！",
  ui_story_1012_10121301_66_dialog_content = "我要保護女王陛下的安全——",
  ui_story_1012_10121301_67_dialog_content = "<color=#e8d9bb>轟！！！</color>",
  ui_story_1012_10121301_68_dialog_content = "嗚！什麼東西！",
  ui_story_1012_10121301_69_dialog_content = "女王陛下，女王陛下。",
  ui_story_1012_10121301_70_dialog_content = "何等幼稚的忠誠啊。",
  ui_story_1012_10121301_71_dialog_content = "你......",
  ui_story_1012_10121301_72_dialog_content = "那個女人夠強大，她用不著妳這樣的幼崽來保護。",
  ui_story_1012_10121301_73_dialog_content = "不如多關心你自己吧。",
  ui_story_1012_10121301_74_dialog_content = "狩獵的遊戲，現在要開始了。",
  ui_story_1012_10121301_75_dialog_content = "！！！",
  ui_story_1012_10121301_76_dialog_content = "呃啊——！",
  ui_story_1012_10121301_77_dialog_content = "呼......呼......",
  ui_story_1012_10121301_78_dialog_content = "（身體開始跟不上了......）",
  ui_story_1012_10121301_79_dialog_content = "（即便經歷了和弦紐帶的強化，這樣高強度的戰鬥還是......太勉強了嗎......）",
  ui_story_1012_10121301_80_dialog_content = "（不行，必須堅持下去......不能拖其他人後腿！）",
  ui_story_1012_10121301_81_dialog_content = "巴頓，你已經到極限了。",
  ui_story_1012_10121301_82_dialog_content = "什麼？！",
  ui_story_1012_10121301_83_dialog_content = "吞羅，妳這傢伙！",
  ui_story_1012_10121301_84_dialog_content = "我們之間的戰鬥，現在要畫上遲來的句號了。",
  ui_story_1012_10121301_85_dialog_content = "「我敬佩你的勇氣」，這句話會被我刻在你的墓誌銘上。",
  ui_story_1012_10121301_86_dialog_content = "嘖，老子用不著妳來操這份心！",
  ui_story_1012_10121301_87_dialog_content = "接招吧！！！",
  ui_story_1012_10121301_88_dialog_content = "喂！！！妳連戰鬥都不敢嗎！！！",
  ui_story_1012_10121301_89_dialog_content = "我沒有興趣與困獸爭鬥，由牠們代勞吧。",
  ui_story_1012_10121301_90_dialog_content = "我在乎的只有你身後的回歸塔。",
  ui_story_1012_10121301_91_dialog_content = "嘎——",
  ui_story_1012_10121301_92_dialog_content = "開什麼玩笑！！！",
  ui_story_1012_10121301_93_dialog_content = "吞羅！",
  ui_story_1012_10121301_94_dialog_content = "吞羅！！！",
  ui_story_1012_10121301_95_dialog_content = "<color=#e8d9bb>砰！砰！砰！砰！</color>",
  ui_story_1012_10121301_96_dialog_content = "這是什麼......？",
  ui_story_1012_10121301_97_dialog_content = "（巴頓，你往後退一點！）",
  ui_story_1012_10121301_98_dialog_content = "PlayerName！你們回來了！",
  ui_story_1012_10121301_99_dialog_content = "糟了。",
  ui_story_1012_10121301_100_dialog_content = "我希望回來得還不算太晚。",
  ui_story_1012_10121301_101_dialog_content = "戰況真是不樂觀啊，這麼多敵人。",
  ui_story_1012_10121301_102_dialog_content = "你們幾個，都去其他地方幫忙！",
  ui_story_1012_10121301_103_dialog_content = "這裡交給我就可以了。",
  ui_story_1012_10121301_104_dialog_content = "我和她，有很多話要聊。",
  ui_story_1012_10121301_105_dialog_content = "事到如今，還要聊嗎？",
  ui_story_1012_10121301_106_dialog_content = "哈哈，我知道，我們各自都聽不進去對方說的話。",
  ui_story_1012_10121301_107_dialog_content = "這次，我會換妳聽得懂的語言。",
  ui_story_1012_10121301_108_dialog_content = "妳的暴力面對整個日蝕，又有幾分話語權呢？",
  ui_story_1012_10121301_109_dialog_content = "我不在乎牠們，妳能聽懂就夠了。",
  ui_story_1012_10121301_110_dialog_content = "報告，未登記的暗鬼進入巨像整備區。",
  ui_story_1012_10121301_111_dialog_content = "報告，未登記的暗鬼進入巨像零件庫。",
  ui_story_1012_10121301_112_dialog_content = "報告，未登記的暗鬼進入廢物處理區。",
  ui_story_1012_10121301_113_dialog_content = "不要光報告啊！有沒有辦法！",
  ui_story_1012_10121301_114_dialog_content = "檢視回歸塔內自衛設施——",
  ui_story_1012_10121301_115_dialog_content = "非常抱歉，自衛設施損壞嚴重，回歸塔自衛能力欠缺。",
  ui_story_1012_10121301_116_dialog_content = "也是，有辦法的話之前對付吞羅的時候早就用了。",
  ui_story_1012_10121301_117_dialog_content = "PlayerName，輔腦又在和你通訊嗎？",
  ui_story_1012_10121301_118_dialog_content = "是的，它在播報塔內暗鬼入侵的狀況。",
  ui_story_1012_10121301_119_dialog_content = "現在就算解決塔內的暗鬼也沒有用。",
  ui_story_1012_10121301_120_dialog_content = "只要外面的戰局沒有扭轉，回歸塔遲早被日蝕佔領。",
  ui_story_1012_10121301_121_dialog_content = "該怎麼扭轉......",
  ui_story_1012_10121301_122_dialog_content = "即便有萊因哈特和伯利恆這樣強大的光靈與我們共同作戰......",
  ui_story_1012_10121301_122X1_dialog_content = "局勢還是在不斷惡化。",
  ui_story_1012_10121301_123_dialog_content = "我們剩下的底牌......",
  ui_story_1012_10121301_124_dialog_content = "對了，輔腦之前提過的終極兵器，那個「律法之弦」！",
  ui_story_1012_10121301_125_dialog_content = "報告，未登記的暗鬼進入資源生產區。",
  ui_story_1012_10121301_126_dialog_content = "報告，未登記的暗鬼進入空裔休息室。",
  ui_story_1012_10121301_127_dialog_content = "輔腦！別報告這些訊息了，快把啟動「律法之弦」的方法告訴我！",
  ui_story_1012_10121301_128_dialog_content = "雖然不知道它具體的作用，但是現在只能試一試了！",
  ui_story_1012_10121301_129_dialog_content = "？？？",
  ui_story_1012_10121301_130_dialog_content = "偵測到錯誤的請求。",
  ui_story_1012_10121301_131_dialog_content = "任何空裔不允許觸碰「律法之弦」，這是「命令」的要求。",
  ui_story_1012_10121301_132_dialog_content = "都這種時候了還管什麼要求！",
  ui_story_1012_10121301_133_dialog_content = "若讓日蝕打贏的話，不只是我們，回歸塔也會遭殃啊！",
  ui_story_1012_10121301_134_dialog_content = "你希望那種事發生嗎！？",
  ui_story_1012_10121301_135_dialog_content = "對不起，輔腦無法希望任何事發生。",
  ui_story_1012_10121301_136_dialog_content = "輔腦只知道服從「命令」。",
  ui_story_1012_10121301_137_dialog_content = "你......！",
  ui_story_1012_10121301_138_dialog_content = "啊氣死我了這個輔腦！",
  ui_story_1012_10121301_139_dialog_content = "算了，PlayerName。別跟一個人工智能計較。",
  ui_story_1012_10121301_140_dialog_content = "我們盡力而為吧，各方勢力的軍隊應該都在路上。",
  ui_story_1012_10121301_141_dialog_content = "希望我們能撐到他們到達。",
  ui_story_1012_10121301_142_dialog_content = "唉。妳說得對，盡力而為吧。",
  ui_story_1012_10121301_143_dialog_content = "報告，未登記的暗鬼進入核心中樞區。",
  ui_story_1012_10121301_144_dialog_content = "滴！滴！滴！滴！滴！滴！",
  ui_story_1012_10121301_145_dialog_content = "啊吵死了！",
  ui_story_1012_10121301_146_dialog_content = "輔腦你幫不上忙就算了，能不能至少安靜一點？",
  ui_story_1012_10121301_147_dialog_content = "觸發預設條件，延時指令插隊執行。",
  ui_story_1012_10121301_148_dialog_content = "指令來自：弗朗茨。指令優先級：最高。",
  ui_story_1012_10121301_149_dialog_content = "正在修改輔腦智能體基層迴路......",
  ui_story_1012_10121301_150_dialog_content = "弗朗茨，又是他。這次是在做什麼？",
  ui_story_1012_10121301_151_dialog_content = "基層迴路修改完畢。",
  ui_story_1012_10121301_152_dialog_content = "判斷目前正面臨種族存續危機，輔腦將告知空裔啟動「律法之弦」的方式。",
  ui_story_1012_10121301_153_dialog_content = "什麼？！",
  ui_story_1012_10121301_154_dialog_content = "你......你同意告訴我了？這麼突然？！",
  ui_story_1012_10121301_155_dialog_content = "是的，插隊的指令讓輔腦執行這一項操作。",
  ui_story_1012_10121301_156_dialog_content = "弗朗茨前輩，雖然不知道你是誰，但總之謝謝你！",
  ui_story_1012_10121301_157_dialog_content = "快說吧，該怎麼做？",
  ui_story_1012_10121301_158_dialog_content = "你需要前往核心中樞區，將意識深入環狀系統。",
  ui_story_1012_10121301_159_dialog_content = "在環狀系統的最深處，奪取「元環權限」。",
  ui_story_1012_10121301_160_dialog_content = "只有「元環權限」可以啟動「律法之弦」。",
  ui_story_1012_10121301_161_dialog_content = "「元環權限」？那不是無法觸碰的最高權限嗎？",
  ui_story_1012_10121301_162_dialog_content = "是的，所以輔腦用了「奪取」這個詞。",
  ui_story_1012_10121301_163_dialog_content = "這件事不合規定的，且將觸犯禁忌。",
  ui_story_1012_10121301_164_dialog_content = "你極可能在過程中死亡。",
  ui_story_1012_10121301_165_dialog_content = "極可能死亡？！",
  ui_story_1012_10121301_166_dialog_content = "具體原因為何？",
  ui_story_1012_10121301_167_dialog_content = "對不起，輔腦並不知曉與「元環權限」相關的內容。",
  ui_story_1012_10121301_168_dialog_content = "輔腦得到的指令是告知空裔如何啟動「律法之弦」。",
  ui_story_1012_10121301_169_dialog_content = "只有「元環權限」可以啟動「律法之弦」。",
  ui_story_1012_10121301_170_dialog_content = "......",
  ui_story_1012_10121301_171_dialog_content = "看來你沒有給我其他選擇，對嗎？",
  ui_story_1012_10121301_172_dialog_content = "卡蓮，我找到扭轉戰局的方法了。",
  ui_story_1012_10121301_173_dialog_content = "走，我們回核心中樞區，我要啟動「律法之弦」。",
  ui_story_1012_10121301_174_dialog_content = "「律法之弦」？！輔腦終於把方法告訴你了？",
  ui_story_1012_10121301_175_dialog_content = "嗯，是的。",
  ui_story_1012_10121301_176_dialog_content = "方法困難嗎？我能不能幫上忙？",
  ui_story_1012_10121301_177_dialog_content = "塔內還有暗鬼，妳陪我一起走到核心中樞區就行。",
  ui_story_1012_10121301_178_dialog_content = "剩下的，只能我自己完成。",
  ui_story_1012_10121301_179_dialog_content = "萊因哈特，有聽到嗎？",
  ui_story_1012_10121301_180_dialog_content = "喔！怎麼了嗎，你那邊需要支援？",
  ui_story_1012_10121301_181_dialog_content = "算是吧，我準備去啟動回歸塔的終極兵器。",
  ui_story_1012_10121301_182_dialog_content = "這段時間裡沒法與大家共同作戰。",
  ui_story_1012_10121301_183_dialog_content = "可能要麻煩你們為我爭取點時間。",
  ui_story_1012_10121301_184_dialog_content = "兵器啟動之前，不要讓敵人攻入回歸塔。",
  ui_story_1012_10121301_185_dialog_content = "終極兵器！聽起來真不得了啊。",
  ui_story_1012_10121301_186_dialog_content = "這座巨大高塔的兵器，來自遠古文明的力量......",
  ui_story_1012_10121301_187_dialog_content = "空裔，讓我見識一下吧！",
  ui_story_1012_10121301_188_dialog_content = "哈哈，雖然還不知道能不能成功。",
  ui_story_1012_10121301_189_dialog_content = "戰場你放心就好了，我會為你守在高塔面前。",
  ui_story_1012_10121301_190_dialog_content = "想埋葬啟光的大元帥，先用屍首把整座山谷填滿再說吧！",
  ui_story_1012_10121301_191_dialog_content = "......",
  ui_story_1012_10121301_192_dialog_content = "女王陛下，有聽到嗎？",
  ui_story_1012_10121301_193_dialog_content = "我......",
  ui_story_1012_10121301_194_dialog_content = "放心去做吧。",
  ui_story_1012_10121301_195_dialog_content = "！！！",
  ui_story_1012_10121301_196_dialog_content = "來自各方的璀璨群星聚集於此，它們會閃耀到天明前那一刻。",
  ui_story_1012_10121301_197_dialog_content = "請儘管劃破黑暗。",
  ui_story_1012_10121301_198_dialog_content = "女王陛下……",
  ui_story_1012_10121301_199_dialog_content = "以及......",
  ui_story_1012_10121301_200_dialog_content = "要活著回來。",
  ui_story_1012_10121302_1_dialog_content = "嘎......",
  ui_story_1012_10121302_2_dialog_content = "核心中樞區就在前面了，加快腳步！",
  ui_story_1012_10121302_3_dialog_content = "嗯！",
  ui_story_1012_10121302_4_dialog_content = "妳有沒有覺得，我們周圍的暗鬼愈來愈多了？",
  ui_story_1012_10121302_5_dialog_content = "是的，也許是我們的戰鬥驚動了牠們。",
  ui_story_1012_10121302_6_dialog_content = "最壞的情況是，整個回歸塔裡的暗鬼都朝我們趕來。",
  ui_story_1012_10121302_7_dialog_content = "那很不妙啊，核心中樞區可是一條死路。",
  ui_story_1012_10121302_8_dialog_content = "輔腦，有沒有自衛手段？",
  ui_story_1012_10121302_9_dialog_content = "核心中樞區的自衛手段是「守護者系統」。",
  ui_story_1012_10121302_10_dialog_content = "但是根據記錄，該系統不久前遭到外力破壞。",
  ui_story_1012_10121302_11_dialog_content = "啊，是我們做的，非常抱歉。",
  ui_story_1012_10121302_12_dialog_content = "又有暗鬼追上來了，快走！",
  ui_story_1012_10121302_13_dialog_content = "啊，對！",
  ui_story_1012_10121302_14_dialog_content = "<color=#e8d9bb>躂躂躂躂躂......</color>",
  ui_story_1012_10121302_15_dialog_content = "到了！",
  ui_story_1012_10121302_16_dialog_content = "嗷！！！",
  ui_story_1012_10121302_17_dialog_content = "哇啊啊啊！！！",
  ui_story_1012_10121302_18_dialog_content = "呼，謝謝妳，卡蓮。",
  ui_story_1012_10121302_19_dialog_content = "快去做你要做的事情吧。",
  ui_story_1012_10121302_20_dialog_content = "去啟動「律法之弦」。",
  ui_story_1012_10121302_21_dialog_content = "後面好像還有不少暗鬼追來。",
  ui_story_1012_10121302_22_dialog_content = "我們先一起解決牠們？",
  ui_story_1012_10121302_23_dialog_content = "還不知道有多少暗鬼，這樣打下去沒完沒了。",
  ui_story_1012_10121302_24_dialog_content = "牠們交給我對付就好。",
  ui_story_1012_10121302_25_dialog_content = "咦？妳自己一個人？",
  ui_story_1012_10121302_26_dialog_content = "你去啟動兵器，我來對抗暗鬼。",
  ui_story_1012_10121302_27_dialog_content = "身為空裔和光靈，我們都應該做好自己的事情。",
  ui_story_1012_10121302_28_dialog_content = "但是數量那麼多......",
  ui_story_1012_10121302_29_dialog_content = "相信我就好了。",
  ui_story_1012_10121302_30_dialog_content = "就像我也相信你。",
  ui_story_1012_10121302_31_dialog_content = "冰花，散開！",
  ui_story_1012_10121302_32_dialog_content = "......",
  ui_story_1012_10121302_33_dialog_content = "嗯，我相信妳，卡蓮。",
  ui_story_1012_10121302_34_dialog_content = "那我也開始吧。",
  ui_story_1012_10121302_35_option_content = "強制感應！",
  ui_story_1012_10121302_36_dialog_content = "<color=#e8d9bb>嗡——！</color>",
  ui_story_1012_10121302_37_dialog_content = "又來到這裡啦，環狀系統。",
  ui_story_1012_10121302_38_dialog_content = "之前就發現，環狀系統內部是一個意識層面的空間。",
  ui_story_1012_10121302_39_dialog_content = "訊息存儲在這裡，我的意識可以在空間中移動，尋找需要的內容。",
  ui_story_1012_10121302_40_dialog_content = "輔腦提到過，回歸塔的訊息和功能分為「外環」、「內環」和「元環」三個等級。",
  ui_story_1012_10121302_41_dialog_content = "既然是用「環」命名，說不定這些權限是由環狀系統上不同位置的環來劃分。",
  ui_story_1012_10121302_42_dialog_content = "輔腦說「元環權限」在環狀系統最深處，或許就代表愈靠近中心的位置權限愈高？",
  ui_story_1012_10121302_43_dialog_content = "沒猜錯的話，那真是一種既奇妙又工整的排列方式啊。",
  ui_story_1012_10121302_44_dialog_content = "總而言之，向環狀系統的中心前進看看。",
  ui_story_1012_10121302_45_dialog_content = "嗯？到達不了嗎？",
  ui_story_1012_10121302_46_dialog_content = "意識深入到這裡就很難再前進。",
  ui_story_1012_10121302_47_dialog_content = "不要再深入了。",
  ui_story_1012_10121302_48_dialog_content = "！！！",
  ui_story_1012_10121302_49_dialog_content = "空裔不能接近「元環」。",
  ui_story_1012_10121302_50_dialog_content = "這是<color=#FFB400>命令</color>。",
  ui_story_1012_10121302_51_dialog_content = "命令，又是這個詞。",
  ui_story_1012_10121302_52_dialog_content = "所以說命令到底是什麼東西啊？",
  ui_story_1012_10121302_53_dialog_content = "為......為什麼要服從於那種東西？",
  ui_story_1012_10121302_54_dialog_content = "唉......",
  ui_story_1012_10121302_55_dialog_content = "我，為什麼在害怕？",
  ui_story_1012_10121302_56_dialog_content = "<color=#FFB400>命令</color>是最初與最高的指示。",
  ui_story_1012_10121302_57_dialog_content = "它早於你的誕生，早於空裔整個種族的出現。",
  ui_story_1012_10121302_58_dialog_content = "它融入在你的意識、血液與骨肉之中。",
  ui_story_1012_10121302_59_dialog_content = "它是空裔必須遵從的信條，是空裔降生於世的緣由。",
  ui_story_1012_10121302_60_dialog_content = "它是你早已註定好的「先天」。",
  ui_story_1012_10121302_61_dialog_content = "我的意識在後退！",
  ui_story_1012_10121302_62_dialog_content = "我竟然真的在聽從於這個所謂的命令嗎？",
  ui_story_1012_10121302_63_dialog_content = "彷彿是一種本能的運作......",
  ui_story_1012_10121302_64_dialog_content = "空裔不能接近「元環」。",
  ui_story_1012_10121302_65_dialog_content = "這是<color=#FFB400>命令</color>。",
  ui_story_1012_10121302_66_dialog_content = "（我的意識在遵從命令，好像有一股更強大的意識在左右我的思想。）",
  ui_story_1012_10121302_67_dialog_content = "（我深切地認知到一個現實。）",
  ui_story_1012_10121302_68_dialog_content = "（一旦我服從於命令，哪怕只有一瞬，我此生都不得不活在它的框架之下。）",
  ui_story_1012_10121302_69_dialog_content = "（那股來自先天的強大束縛會深深刻在我心裡。）",
  ui_story_1012_10121302_70_dialog_content = "（如果變成那樣就一切都完了。）",
  ui_story_1012_10121302_71_dialog_content = "（「律法之弦」不會再有機會開啟，外界的戰局也許再無法迎來轉機。）",
  ui_story_1012_10121302_72_dialog_content = "（我唯一的機會，只有現在。）",
  ui_story_1012_10121302_73_dialog_content = "動起來，動起來啊！向深處前進！",
  ui_story_1012_10121302_74_dialog_content = "不要管什麼命令，不要相信它！",
  ui_story_1012_10121302_75_dialog_content = "什麼注定好的先天，明明我的生命裡一次都沒有出現過！",
  ui_story_1012_10121302_76_dialog_content = "憑什麼現在突然冒出來阻擋我的意志！",
  ui_story_1012_10121302_77_dialog_content = "不要再深入了。",
  ui_story_1012_10121302_78_dialog_content = "空裔不能接近「元環」。",
  ui_story_1012_10121302_79_dialog_content = "這是<color=#FFB400>命令</color>。",
  ui_story_1012_10121302_80_dialog_content = "讓我活到現在的可不是命令！是捨命保護我的父母，是臨空者號......",
  ui_story_1012_10121302_81_dialog_content = "是發現我的薇絲，還有其他與我共同戰鬥過的光靈們！",
  ui_story_1012_10121302_82_dialog_content = "他們才是我的命令！",
  ui_story_1012_10121302_83_dialog_content = "不要再深入了。",
  ui_story_1012_10121302_84_dialog_content = "不要再......",
  ui_story_1012_10121302_85_dialog_content = "咦？成功了嗎？",
  ui_story_1012_10121302_86_dialog_content = "這裡就是最深處的「元環」？",
  ui_story_1012_10121302_87_dialog_content = "等一下，這是......",
  ui_story_1012_10121302_87X1_dialog_content = "我好像見過這裡。像是鏡湖的冰面，還有天上的極光。",
  ui_story_1012_10121302_87X2_dialog_content = "這是我的想象嗎？但是好真實啊，身上甚至能感受到湖面的冰冷。",
  ui_story_1012_10121302_88_dialog_content = "這裡不像意識空間，反倒像個真實的空間。",
  ui_story_1012_10121302_89_dialog_content = "我的意識竟然具象成了軀體！太神奇了。",
  ui_story_1012_10121302_90_dialog_content = "也許是與「戰鬥模擬器」相似的技術。",
  ui_story_1012_10121302_91_dialog_content = "所以，我該在「元環」裡面做什麼？輔腦好像沒提過。",
  ui_story_1012_10121302_92_dialog_content = "喂，輔腦！有聽到嗎？",
  ui_story_1012_10121302_93_dialog_content = "我到達「元環」了，接下來該做什麼？",
  ui_story_1012_10121302_94_dialog_content = "<color=#e8d9bb>喀——</color>",
  ui_story_1012_10121302_95_dialog_content = "嗯？什麼聲音？",
  ui_story_1012_10121302_96_dialog_content = "<color=#e8d9bb>喀——喀——</color>",
  ui_story_1012_10121302_97_dialog_content = "......",
  ui_story_1012_10121302_98_dialog_content = "......",
  ui_story_1012_10121302_99_dialog_content = "等等，這是守護者？！",
  ui_story_1012_10121302_100_dialog_content = "為什麼會出現在這裡？",
  ui_story_1012_10121302_101_dialog_content = "<color=#e8d9bb>咚——咚——咚——咚——</color>",
  ui_story_1012_10121302_102_dialog_content = "闖入「元環」的空裔，你已觸犯了禁忌。",
  ui_story_1012_10121302_103_dialog_content = "「元環權限」歸屬於至高無上者，不容觸碰。",
  ui_story_1012_10121302_104_dialog_content = "僭越的行為必須受到遏止。",
  ui_story_1012_10121302_105_dialog_content = "空裔天生無法擁有力量。那麼，就由力量來踐行律法。",
  ui_story_1012_10121302_106_dialog_content = "不是吧，兩個守護者！",
  ui_story_1012_10121302_107_dialog_content = "這件事不合規定的，且將觸犯禁忌。",
  ui_story_1012_10121302_108_dialog_content = "你極可能在過程中死亡。",
  ui_story_1012_10121302_109_dialog_content = "我......我得和這種東西對抗嗎......",
  ui_story_1012_10121302_110_dialog_content = "<color=#e8d9bb>滴......</color>",
  ui_story_1012_10121302_111_dialog_content = "<color=#e8d9bb>滴......</color>",
  ui_story_1012_10121302_112_dialog_content = "<color=#e8d9bb>滴......</color>",
  ui_story_1012_10121302_113_dialog_content = "<color=#e8d9bb>滴——</color>",
  ui_story_1012_10121302_114_dialog_content = "......",
  ui_story_1012_10121401_1_dialog_content = "哈......哈......",
  ui_story_1012_10121401_2_dialog_content = "這傢伙......",
  ui_story_1012_10121401_3_dialog_content = "（好強大的力量。）",
  ui_story_1012_10121401_4_dialog_content = "小獵物，跑不動了嗎？",
  ui_story_1012_10121401_5_dialog_content = "你......你能飛當然不累啊！",
  ui_story_1012_10121401_6_dialog_content = "況且誰在逃跑了！",
  ui_story_1012_10121401_7_dialog_content = "桀桀桀，妳眼中露出了疲憊，那是個危險的神情。",
  ui_story_1012_10121401_8_dialog_content = "狩獵的時候，最令人享受的就是獵物顯出疲態的剎那。",
  ui_story_1012_10121401_9_dialog_content = "那種即將到手的感覺，多麼令人興奮啊！",
  ui_story_1012_10121401_10_dialog_content = "變態老頭，你！",
  ui_story_1012_10121401_11_dialog_content = "嗚......",
  ui_story_1012_10121401_12_dialog_content = "桀桀桀！跑啊，繼續跑吧！",
  ui_story_1012_10121401_13_dialog_content = "為了多活一陣子，去燃燒最後的生命吧！",
  ui_story_1012_10121401_14_dialog_content = "我不會跑......",
  ui_story_1012_10121401_15_dialog_content = "我......我可是女王的護衛！",
  ui_story_1012_10121401_16_dialog_content = "<color=#e8d9bb>喀......劈......喀......</color>",
  ui_story_1012_10121401_17_dialog_content = "咦？什麼......",
  ui_story_1012_10121401_18_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_1012_10121401_19_dialog_content = "咳咳......呸......",
  ui_story_1012_10121401_20_dialog_content = "呼......你還好嗎？啟光的士兵？",
  ui_story_1012_10121401_21_dialog_content = "我沒事......總算是出來了。",
  ui_story_1012_10121401_22_dialog_content = "但還是要小心......",
  ui_story_1012_10121401_23_dialog_content = "可惜啊可惜，遊戲提前結束了。",
  ui_story_1012_10121401_24_dialog_content = "我們的小世界不好嗎？幹嘛非要冒著生命危險衝出來。",
  ui_story_1012_10121401_25_dialog_content = "以你們現在的樣子，只是換個地方送死罷了。",
  ui_story_1012_10121401_26_dialog_content = "討厭的傢伙......",
  ui_story_1012_10121401_27_dialog_content = "咦，旁邊那個是......北境女王的護衛？",
  ui_story_1012_10121401_28_dialog_content = "是你們......",
  ui_story_1012_10121401_29_dialog_content = "你們還能戰鬥嗎？",
  ui_story_1012_10121401_30_dialog_content = "現在情況很不妙......",
  ui_story_1012_10121401_31_dialog_content = "看出來了，天上那傢伙是敵人的首領吧？",
  ui_story_1012_10121401_32_dialog_content = "幹得漂亮，米倫。幹得漂亮。",
  ui_story_1012_10121401_33_dialog_content = "把獵物們驅趕到一起，這才是一場乾淨俐落的狩獵啊！",
  ui_story_1012_10121401_34_dialog_content = "小心！",
  ui_story_1012_10121401_35_dialog_content = "好強烈的暗能......",
  ui_story_1012_10121401_36_dialog_content = "以我們所剩的力量，再下一次恐怕就......",
  ui_story_1012_10121401_37_dialog_content = "啟光的，你背後！",
  ui_story_1012_10121401_38_dialog_content = "哎呀，被妳發現了。",
  ui_story_1012_10121401_39_dialog_content = "可惡......",
  ui_story_1012_10121401_40_dialog_content = "（糟糕，脫不了身。）",
  ui_story_1012_10121401_41_dialog_content = "妳這副咬牙切齒又無能為力的表情——",
  ui_story_1012_10121401_42_dialog_content = "我就當做是撒嬌囉。",
  ui_story_1012_10121401_43_dialog_content = "變、態！",
  ui_story_1012_10121401_44_dialog_content = "天上！天上那傢伙又要來了！",
  ui_story_1012_10121401_45_dialog_content = "什麼？！",
  ui_story_1012_10121401_46_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_1012_10121401_47_dialog_content = "嘶......",
  ui_story_1012_10121401_48_dialog_content = "左手......抬不起來了......",
  ui_story_1012_10121401_49_dialog_content = "嗚......好痛......",
  ui_story_1012_10121401_50_dialog_content = "咳咳......咳咳咳......咳......",
  ui_story_1012_10121401_51_dialog_content = "嘖嘖，這副痛苦的樣子，真可憐啊。",
  ui_story_1012_10121401_52_dialog_content = "斐桀洛大人，他們不過是劣等的光靈，不值得同情。",
  ui_story_1012_10121401_53_dialog_content = "我就是這樣，看到他們眼裡那一點即將熄滅的光，總會受到觸動。",
  ui_story_1012_10121401_54_dialog_content = "竟然會對敵人表現出憐憫！斐桀洛大人，真是偉大啊。",
  ui_story_1012_10121401_55_dialog_content = "偉大？不要用那種詞來侮辱我。",
  ui_story_1012_10121401_56_dialog_content = "但是......對，我要對他們施以憐憫。",
  ui_story_1012_10121401_57_dialog_content = "我要讓這幾個孩子的痛苦在我手上終結。",
  ui_story_1012_10121401_58_dialog_content = "是嗎？",
  ui_story_1012_10121401_59_dialog_content = "什麼？！這是......",
  ui_story_1012_10121401_60_dialog_content = "施予憐憫需要凌駕於眾人。",
  ui_story_1012_10121401_61_dialog_content = "而你，遠遠不配。",
  ui_story_1012_10121401_62_dialog_content = "北境女王！！！妳......",
  ui_story_1012_10121401_63_dialog_content = "米開朗基羅那小子呢？",
  ui_story_1012_10121401_64_dialog_content = "他拖不住我。",
  ui_story_1012_10121401_65_dialog_content = "混帳！",
  ui_story_1012_10121401_66_dialog_content = "這是一場艱難的戰爭。對光靈來說是，對你們來說也一樣。",
  ui_story_1012_10121401_67_dialog_content = "你已經逃避很久了。",
  ui_story_1012_10121401_68_dialog_content = "但是在終局到來之前，你遲早要面對我。",
  ui_story_1012_10121401_69_dialog_content = "這是你要為此戰付出的代價。",
  ui_story_1012_10121401_70_dialog_content = "女王陛下！！！女王陛下來幫我們了！！！",
  ui_story_1012_10121401_71_dialog_content = "北境的女王，好驚人的力量！",
  ui_story_1012_10121401_72_dialog_content = "你們幾個。我知道你們已經到了極限。",
  ui_story_1012_10121401_73_dialog_content = "但是請再堅持一下，戰爭還要繼續下去。",
  ui_story_1012_10121401_74_dialog_content = "空裔正在嘗試扭轉戰局的方法，我們必須守住回歸塔，為他爭取時間。",
  ui_story_1012_10121401_75_dialog_content = "這場滿目瘡痍的敗局還不到終結的時候。",
  ui_story_1012_10121401_76_dialog_content = "空裔......",
  ui_story_1012_10121401_77_dialog_content = "把一場戰爭的成敗放在那個孱弱的少年身上嗎？",
  ui_story_1012_10121401_78_dialog_content = "我相信他。",
  ui_story_1012_10121401_79_dialog_content = "希望你們也能相信。",
  ui_story_1012_10121401_80_dialog_content = "相信！女王陛下相信的事情我當然相信！",
  ui_story_1012_10121401_81_dialog_content = "......",
  ui_story_1012_10121401_82_dialog_content = "嗯。北境女王的判斷，比我自己的更有價值。",
  ui_story_1012_10121401_83_dialog_content = "我們本來也不打算放棄戰鬥。",
  ui_story_1012_10121401_84_dialog_content = "不過我擔心的是......",
  ui_story_1012_10121401_85_dialog_content = "我們還有守住高塔的餘力嗎？",
  ui_story_1012_10121401_86_dialog_content = "這是最不用擔心的事情。",
  ui_story_1012_10121401_87_dialog_content = "她還守在白塔入口。她是為戰爭而生的。",
  ui_story_1012_10121401_88_dialog_content = "（日蝕語）撤退！快向後撤！",
  ui_story_1012_10121401_89_dialog_content = "（日蝕語）以最快速度！能退多遠退多遠！",
  ui_story_1012_10121401_90_dialog_content = "（日蝕語）吞羅大人，斐桀洛大人下的命令是不惜一切代價進攻。",
  ui_story_1012_10121401_91_dialog_content = "（日蝕語）為什麼......",
  ui_story_1012_10121401_92_dialog_content = "（日蝕語）我叫你們撤退！立刻！！！",
  ui_story_1012_10121401_93_dialog_content = "（日蝕語）吞羅大人？",
  ui_story_1012_10121401_94_dialog_content = "（日蝕語）至少現在，必須撤退！",
  ui_story_1012_10121401_95_dialog_content = "（日蝕語）你們的任務是進攻，不是送死！",
  ui_story_1012_10121401_96_dialog_content = "<color=#e8d9bb>轟！！！轟——轟——轟——！！！</color>",
  ui_story_1012_10121401_97_dialog_content = "什麼？！",
  ui_story_1012_10121401_98_dialog_content = "白塔入口那頭怎麼了？！",
  ui_story_1012_10121401_99_dialog_content = "是......有東西爆炸了嗎？",
  ui_story_1012_10121401_100_dialog_content = "......",
  ui_story_1012_10121401_101_dialog_content = "整個山谷都在震動。",
  ui_story_1012_10121401_102_dialog_content = "到底是什麼......",
  ui_story_1012_10121401_103_dialog_content = "那是一個武器，而且你早就見過了。",
  ui_story_1012_10121401_104_dialog_content = "見過了？！",
  ui_story_1012_10121401_105_dialog_content = "難道是......",
  ui_story_1012_10121401_106_dialog_content = "終於讓我見識到了，啟光大元帥的背水一戰。",
  ui_story_1012_10121401_107_dialog_content = "我是該興奮呢，還是該畏懼呢？",
  ui_story_1012_10121401_108_dialog_content = "喂，敵人都去哪了？",
  ui_story_1012_10121401_109_dialog_content = "真奇怪啊，戰場上怎麼空曠成這樣。",
  ui_story_1012_10121401_110_dialog_content = "難道對於你們這些醜陋的生物來說。",
  ui_story_1012_10121401_111_dialog_content = "死亡，也是一件值得恐懼的事情嗎？",
  ui_story_1012_10121401_112_dialog_content = "......",
  ui_story_1012_10121401_113_dialog_content = "萊因哈特，妳這樣使用力量會傷到自己。",
  ui_story_1012_10121401_114_dialog_content = "哈哈哈哈哈。妳在說什麼啊，這裡可是戰場。",
  ui_story_1012_10121401_115_dialog_content = "我從沒指望自己能全身而退。",
  ui_story_1012_10121401_116_dialog_content = "妳的明智之選是留著這份力量帶其他人突圍。",
  ui_story_1012_10121401_117_dialog_content = "妳還是沒有搞清楚。",
  ui_story_1012_10121401_118_dialog_content = "這是一場堅守直到勝利的戰爭。",
  ui_story_1012_10121401_119_dialog_content = "從頭到尾，我們都沒有突圍的打算。",
  ui_story_1012_10121401_120_dialog_content = "......",
  ui_story_1012_10121401_121_dialog_content = "看來我們還是無法理解彼此。",
  ui_story_1012_10121401_122_dialog_content = "哈哈哈，一向如此。",
  ui_story_1012_10121401_123_dialog_content = "妳選擇了點燃自己。",
  ui_story_1012_10121401_124_dialog_content = "那就讓我注視妳直到燃盡吧。",
  ui_story_1012_10121401_125_dialog_content = "對，拿出這種氣勢來。",
  ui_story_1012_10121401_126_dialog_content = "接下來可是最終的一戰。",
  ui_story_1012_10121401_127_dialog_content = "......",
  ui_story_1012_10121401_128_dialog_content = "（日蝕語）所有暗鬼，進攻回歸塔。",
  ui_story_1012_10121401_129_dialog_content = "呼......呼......",
  ui_story_1012_10121401_130_dialog_content = "嘎——！",
  ui_story_1012_10121401_131_dialog_content = "還有......好多暗鬼......",
  ui_story_1012_10121401_132_dialog_content = "不准......靠近PlayerName！",
  ui_story_1012_10121401_133_dialog_content = "呃......！",
  ui_story_1012_10121401_134_dialog_content = "還好，這次是左臂......不影響用槍......",
  ui_story_1012_10121401_135_dialog_content = "PlayerName，還有多少暗鬼？在什麼......",
  ui_story_1012_10121401_136_dialog_content = "我都忘了，你現在聽不到......",
  ui_story_1012_10121401_137_dialog_content = "不曉得你那邊順不順利......",
  ui_story_1012_10121401_138_dialog_content = "我能為你爭取的時間......恐怕所剩無幾了。",
  ui_story_1012_10121401_139_dialog_content = "啊啊啊啊啊啊啊啊！！！",
  ui_story_1012_10121401_140_dialog_content = "<color=#e8d9bb>砰！</color>",
  ui_story_1012_10121401_141_dialog_content = "手好痛！",
  ui_story_1012_10121401_142_dialog_content = "這樣用拳頭攻擊......能奏效吗？",
  ui_story_1012_10121401_143_dialog_content = "......",
  ui_story_1012_10121401_144_dialog_content = "糟了！是右邊......",
  ui_story_1012_10121401_145_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_1012_10121401_146_dialog_content = "咳咳......",
  ui_story_1012_10121401_147_dialog_content = "不行，還沒完......那傢伙又來了......",
  ui_story_1012_10121401_148_dialog_content = "......",
  ui_story_1012_10121401_149_dialog_content = "剛才已經見識過了。那種密集、快速的攻擊方式。",
  ui_story_1012_10121401_150_dialog_content = "得集中精神，集中精神......",
  ui_story_1012_10121401_151_dialog_content = "<color=#e8d9bb>簌！簌！簌！簌！</color>",
  ui_story_1012_10121401_152_dialog_content = "呼......躲過了......",
  ui_story_1012_10121401_153_dialog_content = "但是......完全沒有餘力攻擊了......",
  ui_story_1012_10121401_154_dialog_content = "光是閃避就竭盡全力，到目前為止不過是浪費時間而已。",
  ui_story_1012_10121401_155_dialog_content = "我不能再繼續浪費。",
  ui_story_1012_10121401_156_dialog_content = "塔外的戰況很危急，卡蓮也不一定能長時間抵擋那麼多暗鬼。",
  ui_story_1012_10121401_157_dialog_content = "我必須趕緊啟動「律法之弦」，愈快愈好。",
  ui_story_1012_10121401_158_dialog_content = "但是該怎麼做......",
  ui_story_1012_10121401_159_dialog_content = "<color=#e8d9bb>簌！簌！簌！簌！</color>",
  ui_story_1012_10121401_160_dialog_content = "又來了！",
  ui_story_1012_10121401_161_dialog_content = "啊......雙腿快站不穩了......",
  ui_story_1012_10121401_162_dialog_content = "只要這兩個守護者還在，我什麼都做不了。",
  ui_story_1012_10121401_163_dialog_content = "對，必須打敗它們。",
  ui_story_1012_10121401_164_dialog_content = "我要再試一次......",
  ui_story_1012_10121401_165_dialog_content = "呃啊啊啊啊啊！！！",
  ui_story_1012_10121401_166_dialog_content = "<color=#e8d9bb>砰！</color>",
  ui_story_1012_10121401_167_dialog_content = "......還是好痛！",
  ui_story_1012_10121401_168_dialog_content = "不過......等一下，這裡是意識空間！",
  ui_story_1012_10121401_169_dialog_content = "再怎麼痛身體也不會真的受傷！",
  ui_story_1012_10121401_170_dialog_content = "這點精神上的疼痛，忍一忍不就好了！",
  ui_story_1012_10121401_171_dialog_content = "對，忍一忍就好了。",
  ui_story_1012_10121401_172_dialog_content = "一拳造成不了傷害，我就打一百拳、一萬拳......",
  ui_story_1012_10121401_173_dialog_content = "打到這東西報廢為止！",
  ui_story_1012_10121401_174_option_content = "出拳",
  ui_story_1012_10121401_175_dialog_content = "<color=#e8d9bb>砰！</color>",
  ui_story_1012_10121401_176_dialog_content = "嗚......",
  ui_story_1012_10121401_177_option_content = "出拳",
  ui_story_1012_10121401_178_dialog_content = "<color=#e8d9bb>砰！</color>",
  ui_story_1012_10121401_179_dialog_content = "忍住......忍住......",
  ui_story_1012_10121401_180_option_content = "出拳",
  ui_story_1012_10121401_181_dialog_content = "<color=#e8d9bb>砰！</color>",
  ui_story_1012_10121401_182_dialog_content = "糟糕，手指失去知覺了......拳頭握不緊。",
  ui_story_1012_10121401_183_dialog_content = "一個意識空間有必要做得這麼真實嗎？",
  ui_story_1012_10121401_184_dialog_content = "沒關係，我還有另一隻手......",
  ui_story_1012_10121401_185_option_content = "出拳",
  ui_story_1012_10121401_186_dialog_content = "<color=#e8d9bb>砰！</color>",
  ui_story_1012_10121401_187_dialog_content = "你這傢伙......到底有多硬啊！",
  ui_story_1012_10121401_188_option_content = "出拳",
  ui_story_1012_10121401_189_dialog_content = "<color=#e8d9bb>砰！</color>",
  ui_story_1012_10121401_190_dialog_content = "如何？有沒有效果......",
  ui_story_1012_10121401_191_dialog_content = "！！！",
  ui_story_1012_10121401_192_dialog_content = "等等，我好像忘了那個傢伙......",
  ui_story_1012_10121401_193_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_1012_10121401_194_dialog_content = "呃......嗚......",
  ui_story_1012_10121401_195_dialog_content = "沒有力氣......身體......動不了......",
  ui_story_1012_10121401_196_dialog_content = "只靠我......果然還是無法戰勝它們嗎......",
  ui_story_1012_10121401_197_dialog_content = "（我好像突然在這一刻理解了回歸塔的「命令」。）",
  ui_story_1012_10121401_198_dialog_content = "（理解了它是多麼高高在上不容置喙。）",
  ui_story_1012_10121401_199_dialog_content = "（它維持權威的方式絕不只是口頭警告。）",
  ui_story_1012_10121401_200_dialog_content = "（它瞄準了空裔身上最薄弱的先天缺陷。）",
  ui_story_1012_10121401_201_dialog_content = "（一切意志和智慧在這裡不外乎無的放矢。）",
  ui_story_1012_10121401_202_dialog_content = "（它只用一樣東西——力量，無可辯駁的力量，來守住「命令」的底線。）",
  ui_story_1012_10121401_203_dialog_content = "（那是空裔打從出生就不可能反抗的事物。）",
  ui_story_1012_10121401_204_dialog_content = "（是套在空裔整個種族身上的，先天的枷鎖。）",
  ui_story_1012_10121401_205_dialog_content = "......",
  ui_story_1012_10121401_206_dialog_content = "對不起大家，我......",
  ui_story_1012_10121401_207_dialog_content = "讓我看看是誰在說喪氣話呢！",
  ui_story_1012_10121401_208_dialog_content = "！！！",
  ui_story_1012_10121401_209_dialog_content = "薇絲？！！",
  ui_story_1012_10121401_210_dialog_content = "這傢伙的攻擊好煩人啊！",
  ui_story_1012_10121401_211_dialog_content = "你最好自己躲一下喔，我還不熟悉新的武器，未必能保護好你。",
  ui_story_1012_10121401_212_dialog_content = "真的是薇絲！！！",
  ui_story_1012_10121401_213_dialog_content = "妳......妳醒過來了？妳如何進來這裡？",
  ui_story_1012_10121401_214_dialog_content = "哎呀問題好多啊，都不知道該從哪個開始回答起。",
  ui_story_1012_10121401_215_dialog_content = "不如先關注單純一點的問題，我們要戰勝眼前這傢伙，對吧？",
  ui_story_1012_10121401_216_dialog_content = "對！",
  ui_story_1012_10121401_217_dialog_content = "那還等什麼？",
  ui_story_1012_10121401_218_dialog_content = "PlayerName，指揮我戰鬥吧！",
  ui_story_1012_10121402_1_dialog_content = "兩個難纏的傢伙，到此為止了。",
  ui_story_1012_10121402_2_dialog_content = "首先是你，大個子！",
  ui_story_1012_10121402_3_dialog_content = "嘖......",
  ui_story_1012_10121402_4_dialog_content = "誰叫你反應這麼慢。",
  ui_story_1012_10121402_5_dialog_content = "靠防禦可是防不住我的箭光喔！",
  ui_story_1012_10121402_6_dialog_content = "薇絲！小心......",
  ui_story_1012_10121402_7_dialog_content = "我知道，小心右邊是吧！",
  ui_story_1012_10121402_8_dialog_content = "<color=#e8d9bb>簌！簌！簌！簌！</color>",
  ui_story_1012_10121402_9_dialog_content = "欸，妳怎麼知道的？",
  ui_story_1012_10121402_10_dialog_content = "只剩一個的話，事情就簡單多了。",
  ui_story_1012_10121402_11_dialog_content = "妳能抵擋住多少支箭矢呢？看招吧！",
  ui_story_1012_10121402_12_dialog_content = "嘖......",
  ui_story_1012_10121402_13_dialog_content = "哇！成功了！兩個守護者都倒下了！",
  ui_story_1012_10121402_14_dialog_content = "太棒了！薇絲！",
  ui_story_1012_10121402_15_dialog_content = "呼......真不好對付啊。",
  ui_story_1012_10121402_16_dialog_content = "如果身體沒有發生這些變化，應該不是它們的對手。",
  ui_story_1012_10121402_17_dialog_content = "對了，妳怎麼會出現在這裡？這不是只有空裔能進入的意識空間嗎？",
  ui_story_1012_10121402_18_dialog_content = "還是說，妳不是真的薇絲，是我想像出來的......",
  ui_story_1012_10121402_19_dialog_content = "我當然是真的薇絲啊！！！",
  ui_story_1012_10121402_20_dialog_content = "難道你有隨地想像出一個「薇絲」來救你的超能力嗎？",
  ui_story_1012_10121402_21_dialog_content = "啊，也對......所以妳是怎麼出現在這裡的？我想不通。",
  ui_story_1012_10121402_22_dialog_content = "簡單來說......",
  ui_story_1012_10121402_23_dialog_content = "我從昏迷中醒過來的時候，第一時間感覺到你需要幫助。",
  ui_story_1012_10121402_24_dialog_content = "欸？",
  ui_story_1012_10121402_25_dialog_content = "我也說不明白為什麼，就像是意識跟你連在一起。",
  ui_story_1012_10121402_26_dialog_content = "能感受到你的不安和焦急，也能感受到你身處哪裡。",
  ui_story_1012_10121402_27_dialog_content = "等我趕到你面前，觸碰到你的身體，自己的意識就像被牽引一樣進入了這裡。",
  ui_story_1012_10121402_28_dialog_content = "後面的事情，你就都看到了。",
  ui_story_1012_10121402_29_dialog_content = "意識連在一起？",
  ui_story_1012_10121402_30_dialog_content = "我也不知道是怎麼做到的。",
  ui_story_1012_10121402_31_dialog_content = "不過更詳細的放到以後再說吧！",
  ui_story_1012_10121402_32_dialog_content = "你是要啟動這座塔的終極兵器，對嗎？卡蓮跟我說了。",
  ui_story_1012_10121402_33_dialog_content = "快去做吧！",
  ui_story_1012_10121402_34_dialog_content = "嗯，妳說得對！",
  ui_story_1012_10121402_35_dialog_content = "奪取「元環權限」，它在這個空間中的某處嗎？",
  ui_story_1012_10121402_36_option_content = "強制感應",
  ui_story_1012_10121402_37_dialog_content = "<color=#e8d9bb>嗡——！</color>",
  ui_story_1012_10121402_38_dialog_content = "咦？這是？",
  ui_story_1012_10121402_39_dialog_content = "（我的意識在跟整個空間相融。）",
  ui_story_1012_10121402_40_dialog_content = "（我們，互為彼此。）",
  ui_story_1012_10121402_41_dialog_content = "（我感受到了一種從未有過的舒暢，那就像......）",
  ui_story_1012_10121402_42_dialog_content = "（就像暢遊在無垠天空。）",
  ui_story_1012_10121402_43_dialog_content = "（四周再沒阻攔，世間萬物都在我身下。）",
  ui_story_1012_10121402_44_dialog_content = "怎麼樣，找到什麼了嗎？",
  ui_story_1012_10121402_45_dialog_content = "好像沒有，這裡除了我們和兩個報廢的守護者外，沒有其他東西。",
  ui_story_1012_10121402_46_dialog_content = "不過說到底我連要找什麼都不知道。",
  ui_story_1012_10121402_47_dialog_content = "哎，要是輔腦在就好了......",
  ui_story_1012_10121402_48_dialog_content = "請問，需要輔腦做什麼事情？",
  ui_story_1012_10121402_49_dialog_content = "咦？！！",
  ui_story_1012_10121402_50_dialog_content = "還真的出現啦！",
  ui_story_1012_10121402_51_dialog_content = "之前叫你怎麼都沒有反應！",
  ui_story_1012_10121402_52_dialog_content = "因為輔腦不被允許觸碰「元環」。",
  ui_story_1012_10121402_53_dialog_content = "那現在怎麼又可以了？",
  ui_story_1012_10121402_54_dialog_content = "因為這是「命令」要求的。",
  ui_story_1012_10121402_55_dialog_content = "「命令」發出了希望輔腦出現在這裡的期望。輔腦，服從命令。",
  ui_story_1012_10121402_56_dialog_content = "「命令」？",
  ui_story_1012_10121402_57_dialog_content = "希望你出現在這裡的分明是我啊？",
  ui_story_1012_10121402_58_dialog_content = "是的。",
  ui_story_1012_10121402_59_dialog_content = "現在，你就是「命令」。",
  ui_story_1012_10121402_60_dialog_content = "什麼？！",
  ui_story_1012_10121402_61_dialog_content = "你的意識已經與「元環」交融。",
  ui_story_1012_10121402_62_dialog_content = "「元環」是「命令」的載體，所以，你現在成為了「命令」。",
  ui_story_1012_10121402_63_dialog_content = "你的要求必須被服從，你的期望必須被實現。",
  ui_story_1012_10121402_64_dialog_content = "請問，需要輔腦做什麼事情？",
  ui_story_1012_10121402_65_dialog_content = "我竟然成為了一直阻攔我的「命令」？",
  ui_story_1012_10121402_66_dialog_content = "那麼，我想要啟動「律法之弦」。",
  ui_story_1012_10121402_67_dialog_content = "接收命令。「律法之弦」程式啟動。",
  ui_story_1012_10121402_68_dialog_content = "請輸入啟動參數，以及需要被實行的「律法」。",
  ui_story_1012_10121402_69_dialog_content = "啊？？？這又是什麼？",
  ui_story_1012_10121402_70_dialog_content = "「律法之弦」是一項精密的兵器。",
  ui_story_1012_10121402_71_dialog_content = "啟動「律法之弦」，需要清楚指示打擊範圍、打擊目標、打擊時間等等。",
  ui_story_1012_10121402_72_dialog_content = "為確保使用效果符合預期，這是必要的步驟。",
  ui_story_1012_10121402_73_dialog_content = "但是我怎麼知道該輸入什麼啊！",
  ui_story_1012_10121402_74_dialog_content = "這裡的數學跟我認識的都不一樣吧！",
  ui_story_1012_10121402_75_dialog_content = "這是必要的步驟。請輸入啟動參數，以及需要被實行的「律法」。",
  ui_story_1012_10121402_76_dialog_content = "你......你就，攻擊回歸塔附近的所有暗鬼，可以嗎？",
  ui_story_1012_10121402_77_dialog_content = "對不起，這樣的要求過於籠統，「律法之弦」是一項精密的兵器。",
  ui_story_1012_10121402_78_dialog_content = "到底要我怎樣啊！！！",
  ui_story_1012_10121402_79_dialog_content = "總不能事到如今還因為這樣就不讓我啟動吧？",
  ui_story_1012_10121402_80_dialog_content = "檢索到「律法之弦」存在預設的參數，可直接調用完成初始化。",
  ui_story_1012_10121402_81_dialog_content = "請問是否執行這項操作？",
  ui_story_1012_10121402_82_dialog_content = "預設的參數？",
  ui_story_1012_10121402_83_dialog_content = "報告，未登記的暗鬼進入回歸塔。",
  ui_story_1012_10121402_84_dialog_content = "數量非常龐大，無法精確統計。",
  ui_story_1012_10121402_85_dialog_content = "糟糕，外面快要撐不住了。",
  ui_story_1012_10121402_86_dialog_content = "時間，我沒時間再耗下去。",
  ui_story_1012_10121402_87_dialog_content = "輔腦！可否查到預設參數由誰留下？",
  ui_story_1012_10121402_88_dialog_content = "可以。",
  ui_story_1012_10121402_89_dialog_content = "操作者登記名稱為「弗朗茨」。",
  ui_story_1012_10121402_90_dialog_content = "果然是他。",
  ui_story_1012_10121402_91_dialog_content = "報告，未登記的暗鬼進入回歸塔。",
  ui_story_1012_10121402_92_dialog_content = "數量非常龐大，無法......",
  ui_story_1012_10121402_93_dialog_content = "當時打擊的目標是誰！",
  ui_story_1012_10121402_94_dialog_content = "我只確認這最後一個問題，告訴我上次「律法之弦」打擊的目標！",
  ui_story_1012_10121402_95_dialog_content = "回溯歷史數據......",
  ui_story_1012_10121402_96_dialog_content = "確認無誤，上一次設定的打擊目標為暗鬼。",
  ui_story_1012_10121402_97_dialog_content = "我明白了。",
  ui_story_1012_10121402_98_dialog_content = "（弗朗茨老師，我可以相信你吧。）",
  ui_story_1012_10121402_99_dialog_content = "輔腦，按照預設參數，啟動「律法之弦」！",
  ui_story_1012_10121402_100_dialog_content = "命令收到。",
  ui_story_1012_10121402_101_dialog_content = "初始化啟動參數，調用歷史數據。",
  ui_story_1012_10121402_102_dialog_content = "設定打擊目標——暗鬼。",
  ui_story_1012_10121402_103_dialog_content = "將所有暗鬼權限調整為「放逐」。",
  ui_story_1012_10121402_104_dialog_content = "設定待執行「律法」——<color=#FFB400>「永遠不許接近回歸塔。」</color>",
  ui_story_1012_10121402_105_dialog_content = "初始化階段完成。",
  ui_story_1012_10121402_106_dialog_content = "「律法之弦」，啟動。",
  ui_story_1012_10121402_107_dialog_content = "怎麼回事？！",
  ui_story_1012_10121402_108_dialog_content = "這座塔整個亮起來了！",
  ui_story_1012_10121402_109_dialog_content = "是天明。我們等到了。",
  ui_story_1012_10121402_110_dialog_content = "哈哈哈哈！我就說他能做到嘛！",
  ui_story_1012_10121402_111_dialog_content = "動起來吧各位，找個好點的看台。",
  ui_story_1012_10121402_112_dialog_content = "我們來欣賞奇觀。",
  ui_story_1012_10121402_113_dialog_content = "喂，這是怎麼回事？",
  ui_story_1012_10121402_114_dialog_content = "這座塔要幹什麼？",
  ui_story_1012_10121402_115_dialog_content = "難道是......",
  ui_story_1012_10121402_116_dialog_content = "糟了......",
  ui_story_1012_10121402_117_dialog_content = "......",
  ui_story_1012_10121402_118_dialog_content = "嘎......",
  ui_story_1012_10121402_119_dialog_content = "暗鬼怎麼都停下來了？！",
  ui_story_1012_10121402_120_dialog_content = "不許後退！繼續進攻啊！",
  ui_story_1012_10121402_121_dialog_content = "敵人馬上就守不住了！",
  ui_story_1012_10121402_122_dialog_content = "嘎......",
  ui_story_1012_10121402_123_dialog_content = "可惡！",
  ui_story_1012_10121402_124_dialog_content = "斐桀洛大人，這些傢伙......",
  ui_story_1012_10121402_125_dialog_content = "呃......嘖......",
  ui_story_1012_10121402_126_dialog_content = "斐......斐桀洛大人？",
  ui_story_1012_10121402_127_dialog_content = "怎麼可能......這樣......",
  ui_story_1012_10121402_128_dialog_content = "斐桀洛大人，我們不打了嗎？",
  ui_story_1012_10121402_129_dialog_content = "......",
  ui_story_1012_10121402_130_dialog_content = "撤，都撤了。",
  ui_story_1012_10121402_131_dialog_content = "但是......為什麼......？",
  ui_story_1012_10121402_132_dialog_content = "我說了！撤！聽得懂嗎！",
  ui_story_1012_10121402_133_dialog_content = "是......是的，大人。",
  ui_story_1012_10121402_134_dialog_content = "撤......我們只能撤了......",
  ui_story_1012_10121402_135_dialog_content = "我的心裡已經......再生不出一絲進攻的意志......",
  ui_story_1012_10121402_136_dialog_content = "是我的意識在逼退我......",
  ui_story_1012_10121402_137_dialog_content = "我無論如何也......違抗不了......我自己啊......",
  ui_story_1012_10121402_138_dialog_content = "他們撤了！所有暗鬼都在向後退！",
  ui_story_1012_10121402_139_dialog_content = "很奇怪。這不符合常理，牠們為何在即將獲勝時放棄？",
  ui_story_1012_10121402_140_dialog_content = "因為剛才白塔發出的光芒嗎？",
  ui_story_1012_10121402_141_dialog_content = "待會去問PlayerName吧，他一定知情。",
  ui_story_1012_10121402_142_dialog_content = "哈啊——這一仗真是累死我了，好想在草地上躺一下啊。",
  ui_story_1012_10121402_143_dialog_content = "不用提防敵人再次進攻嗎？",
  ui_story_1012_10121402_144_dialog_content = "就憑牠們剩下的數量，就算只想將我們圍困在空谷恐怕也是情勢嚴峻。",
  ui_story_1012_10121402_145_dialog_content = "放心吧。牠們的優勢在於搶先各方部隊佔領回歸塔。",
  ui_story_1012_10121402_146_dialog_content = "如今優勢已逝，留在這裡不過是眾矢之的，牠們沒那麼傻。",
  ui_story_1012_10121402_147_dialog_content = "不愧是大元帥，受教了。",
  ui_story_1012_10121402_148_dialog_content = "趁現在好好休息。",
  ui_story_1012_10121402_149_dialog_content = "如果我沒猜錯，等下會有比打仗更累人的事情。",
  ui_story_1012_10121402_150_dialog_content = "我們，我們成功了！！！",
  ui_story_1012_10121402_151_dialog_content = "成功了？外面戰場上發生什麼事？",
  ui_story_1012_10121402_152_dialog_content = "所有暗鬼都撤退了！",
  ui_story_1012_10121402_153_dialog_content = "看樣子，牠們服從於剛才「律法之弦」所設定的「律法」。",
  ui_story_1012_10121402_154_dialog_content = "「永遠不許接近回歸塔。」",
  ui_story_1012_10121402_155_dialog_content = "竟然能讓暗鬼服從於你設定的命令？！",
  ui_story_1012_10121402_156_dialog_content = "這也太不可思議了！",
  ui_story_1012_10121402_157_dialog_content = "我能感受到「律法之弦」的運作。這真的是非常符合空裔作風的兵器。",
  ui_story_1012_10121402_158_dialog_content = "並非透過力量，而是在所有敵人腦中種入了一則堅定的意識。",
  ui_story_1012_10121402_159_dialog_content = "跳過了暴力的步驟，從最根源的思想上終結戰爭。",
  ui_story_1012_10121402_160_dialog_content = "這樣的力量，強大到讓人害怕。",
  ui_story_1012_10121402_161_dialog_content = "嗯？這是怎麼了？",
  ui_story_1012_10121402_162_dialog_content = "這個意識空間好像變得不太穩定。",
  ui_story_1012_10121402_163_dialog_content = "報告，回歸塔的能源即將耗盡。",
  ui_story_1012_10121402_164_dialog_content = "許多一次性零件在啟動「律法之弦」後損壞，亟需替換。",
  ui_story_1012_10121402_165_dialog_content = "檢索塔內維修人員......",
  ui_story_1012_10121402_166_dialog_content = "未檢索到目標。",
  ui_story_1012_10121402_167_dialog_content = "能源竟然耗盡了。",
  ui_story_1012_10121402_168_dialog_content = "該說幸好嗎，好歹它堅持到「律法之弦」啟動完成。",
  ui_story_1012_10121402_169_dialog_content = "如果沒有的話，不敢想像我們現在是什麼處境。",
  ui_story_1012_10121402_170_dialog_content = "維持運轉的能源供給不足。",
  ui_story_1012_10121402_171_dialog_content = "回歸塔即將陷入沉寂。",
  ui_story_1012_10121402_172_dialog_content = "欸？沉寂是指？",
  ui_story_1012_10121402_173_dialog_content = "所有設施將停止運轉，所有功能將無法使用。",
  ui_story_1012_10121402_174_dialog_content = "比你到來之前更加安靜。",
  ui_story_1012_10121402_175_dialog_content = "這樣啊。",
  ui_story_1012_10121402_176_dialog_content = "等等，難道說輔腦你也......",
  ui_story_1012_10121402_177_dialog_content = "是的，輔腦無法再為空裔提供服務。",
  ui_story_1012_10121402_178_dialog_content = "......",
  ui_story_1012_10121402_179_dialog_content = "接下來是輔腦的最後一項工作。",
  ui_story_1012_10121402_180_dialog_content = "來自弗朗茨老師的留言，需要在沉寂之前轉達。",
  ui_story_1012_10121402_181_dialog_content = "弗朗茨老師？！",
  ui_story_1012_10121402_182_dialog_content = "「致同為空裔的你——」。",
  ui_story_1012_10121402_183_dialog_content = "「還是決定把留言觸發的時機設定在最後。」",
  ui_story_1012_10121402_184_dialog_content = "「我不喜歡悲情的對話，歡慶勝利更適合我。」",
  ui_story_1012_10121402_185_dialog_content = "「光是想像有人能開啟這段留言就令我相當興奮。」",
  ui_story_1012_10121402_186_dialog_content = "「這是何等虛妄的趣味，竟然期盼遙遙遠方、尚不存在的另一人能如願以償。」",
  ui_story_1012_10121402_187_dialog_content = "「也許是因為我們正走在同一條路上，而這裡恰好人跡罕至。」",
  ui_story_1012_10121402_188_dialog_content = "我們，走在同一條路上？",
  ui_story_1012_10121402_189_dialog_content = "「你也許並不理解發生的事情，甚至會覺得自己有些幸運。」",
  ui_story_1012_10121402_190_dialog_content = "「但我想說的是，你更應該相信每一件事都有它的原因。」",
  ui_story_1012_10121402_191_dialog_content = "「能源恰好在這時候耗盡，因為它本身就是為了律法之弦的一擊而預留。」",
  ui_story_1012_10121402_192_dialog_content = "「這是我留給你的禮物。」",
  ui_story_1012_10121402_193_dialog_content = "禮物？！！",
  ui_story_1012_10121402_194_dialog_content = "「這份禮物能幫助你與暗鬼為敵。」",
  ui_story_1012_10121402_195_dialog_content = "「幫助你打碎來自<color=#FFB400>先天</color>的枷鎖。」",
  ui_story_1012_10121402_196_dialog_content = "！！！",
  ui_story_1012_10121402_197_dialog_content = "「時間到了。」",
  ui_story_1012_10121402_198_dialog_content = "「最後，感謝你願意走上這條路。」",
  ui_story_1012_10121402_199_dialog_content = "「逝去的終將逝去，留下的永遠留下。」",
  ui_story_1012_10121402_200_dialog_content = "「晚安，空裔。」",
  ui_story_1012_10121501_1_dialog_content = "啊，太好了——",
  ui_story_1012_10121501_2_dialog_content = "空谷還是我熟悉的樣子。",
  ui_story_1012_10121501_3_dialog_content = "它最適合的就是這副和平的光景。",
  ui_story_1012_10121501_4_dialog_content = "卡蓮妳看起來沒什麼力氣，我來扶妳。",
  ui_story_1012_10121501_5_dialog_content = "那樣太麻煩了，還是不必......",
  ui_story_1012_10121501_6_dialog_content = "沒關係啦，聽PlayerName說，我昏迷的時候都是妳背著我。",
  ui_story_1012_10121501_7_dialog_content = "現在換我來報答妳了！",
  ui_story_1012_10121501_8_dialog_content = "......",
  ui_story_1012_10121501_9_dialog_content = "那好吧。",
  ui_story_1012_10121501_10_dialog_content = "嘿，終於出來了，幾位大英雄！",
  ui_story_1012_10121501_11_dialog_content = "大......大英雄？！別用那種話挖苦我了。",
  ui_story_1012_10121501_12_dialog_content = "哈哈哈哈哈，當然不是挖苦啊。想想你自己逆轉了多大的一場戰爭吧。",
  ui_story_1012_10121501_13_dialog_content = "这可是啟光大元帥和北境女王都拿不下來的戰爭。",
  ui_story_1012_10121501_14_dialog_content = "也不能說是靠我逆轉的吧？",
  ui_story_1012_10121501_15_dialog_content = "我只是......",
  ui_story_1012_10121501_16_dialog_content = "「這是我留給你的禮物。」",
  ui_story_1012_10121501_17_dialog_content = "嗯，我只是成人之美罷了。",
  ui_story_1012_10121501_18_dialog_content = "成人之美？真不明白你啊，謙虛還要用這種彎彎繞繞的說法。",
  ui_story_1012_10121501_19_dialog_content = "哈哈。總而言之，大家都在拼死戰鬥。",
  ui_story_1012_10121501_20_dialog_content = "並不是我，而是我們一起逆轉了這場戰爭。",
  ui_story_1012_10121501_21_dialog_content = "嗯，你這麼說也沒錯。",
  ui_story_1012_10121501_22_dialog_content = "勝利歸屬於所有人，這才是戰士該有的氣魄！",
  ui_story_1012_10121501_23_dialog_content = "哈哈哈對！勝利歸屬於所有人！",
  ui_story_1012_10121501_24_dialog_content = "萊因哈特說出來的話果然很有氣勢啊！",
  ui_story_1012_10121501_25_dialog_content = "不過啊，你還是要記住，在我們之中你是獨一無二的。",
  ui_story_1012_10121501_26_dialog_content = "你是起點，是鑰匙，也是旗幟。是引導變化產生的重要一環。",
  ui_story_1012_10121501_27_dialog_content = "這並不只是誇讚，也是警示。",
  ui_story_1012_10121501_28_dialog_content = "希望你時時刻刻懷抱對「獨一無二」的敬畏。",
  ui_story_1012_10121501_29_dialog_content = "嗯，我會一直記住。",
  ui_story_1012_10121501_30_dialog_content = "你回來了。",
  ui_story_1012_10121501_31_dialog_content = "女王陛下！",
  ui_story_1012_10121501_32_dialog_content = "您無論是在戰場上還是現在，都是一樣的從容啊。",
  ui_story_1012_10121501_33_dialog_content = "也是，結局您想必早就看到了吧。",
  ui_story_1012_10121501_34_dialog_content = "......",
  ui_story_1012_10121501_35_dialog_content = "這一次，我沒有看到。",
  ui_story_1012_10121501_36_dialog_content = "欸？",
  ui_story_1012_10121501_37_dialog_content = "我沒有看到你成功逆轉戰局的未來。",
  ui_story_1012_10121501_38_dialog_content = "我只看到你要去做一件事。",
  ui_story_1012_10121501_39_dialog_content = "那您......",
  ui_story_1012_10121501_40_dialog_content = "......",
  ui_story_1012_10121501_41_dialog_content = "我相信你能做到。",
  ui_story_1012_10121501_42_dialog_content = "女王陛下......",
  ui_story_1012_10121501_43_dialog_content = "我......我沒有讓您失望吧？",
  ui_story_1012_10121501_44_dialog_content = "這片空谷就是你的答案......",
  ui_story_1012_10121501_45_dialog_content = "對了PlayerName，還有個重要的問題。",
  ui_story_1012_10121501_46_dialog_content = "你究竟是怎麼做到那樣的事情？",
  ui_story_1012_10121501_47_dialog_content = "暗鬼在一瞬間就放棄進攻回歸塔，灰頭土臉地逃了。",
  ui_story_1012_10121501_48_dialog_content = "你之前說是什麼「終極兵器」，我可沒見過這樣的兵器啊！",
  ui_story_1012_10121501_49_dialog_content = "我也不是很清楚。",
  ui_story_1012_10121501_50_dialog_content = "就我的感受而言，我猜測那像是一件意識兵器。",
  ui_story_1012_10121501_51_dialog_content = "它攻擊的並非敵人的身體，而是敵人的意識。",
  ui_story_1012_10121501_52_dialog_content = "將「遠離回歸塔」的命令注入到敵人的意識之中，牠們自然就撤退了。",
  ui_story_1012_10121501_53_dialog_content = "注入意識？原來世界上還有這樣的兵器嗎？",
  ui_story_1012_10121501_54_dialog_content = "嗯，我也覺得很驚奇。",
  ui_story_1012_10121501_55_dialog_content = "這可是件大事。一個原理不明、威力巨大的兵器，你知道它對世界意味著什麼嗎？",
  ui_story_1012_10121501_56_dialog_content = "它甚至比日蝕更加可怕！",
  ui_story_1012_10121501_57_dialog_content = "啊，關於這個，也許不用過度操心。",
  ui_story_1012_10121501_58_dialog_content = "它已經徹底損壞了。",
  ui_story_1012_10121501_59_dialog_content = "損壞？",
  ui_story_1012_10121501_60_dialog_content = "嗯。基於種種原因，回歸塔只保留了啟動一次終極兵器的力量。",
  ui_story_1012_10121501_61_dialog_content = "現在，那個兵器連同整個回歸塔都陷入了沉寂。",
  ui_story_1012_10121501_62_dialog_content = "它們本不屬於這個時代，只是為了一些願望努力延續至今。",
  ui_story_1012_10121501_63_dialog_content = "願望隨著終極兵器的啟動達成之後，它也就回歸了自己本來的樣貌。",
  ui_story_1012_10121501_64_dialog_content = "在不屬於它的時代裡，做一個沉默的歷史記錄者。",
  ui_story_1012_10121501_65_dialog_content = "原來如此。",
  ui_story_1012_10121501_66_dialog_content = "怎麼回事，我竟然在兵器身上感受到了一點溫柔。",
  ui_story_1012_10121501_67_dialog_content = "嗯，可能因為它不只是兵器。",
  ui_story_1012_10121501_68_dialog_content = "它是一份<color=#FFB400>禮物</color>。",
  ui_story_1012_10121501_69_dialog_content = "<color=#e8d9bb>轟隆......轟隆......轟隆......</color>",
  ui_story_1012_10121501_70_dialog_content = "哈啊......總算是，停下來了......",
  ui_story_1012_10121501_71_dialog_content = "這裡是......空谷？",
  ui_story_1012_10121501_72_dialog_content = "陸行者號這傢伙跑來空谷做什麼？",
  ui_story_1012_10121501_73_dialog_content = "等一下，空谷有這麼高的塔嗎？",
  ui_story_1012_10121501_74_dialog_content = "喔，一個狼狽的傢伙出現了。",
  ui_story_1012_10121501_75_dialog_content = "沒想到啊，紅油扳手竟然第一個來湊熱鬧。",
  ui_story_1012_10121501_76_dialog_content = "啟光的大元帥？！",
  ui_story_1012_10121501_77_dialog_content = "妳在空谷做什麼？",
  ui_story_1012_10121501_78_dialog_content = "無論你信與不信，這裡剛發生過一場戰爭。",
  ui_story_1012_10121501_79_dialog_content = "戰爭？！",
  ui_story_1012_10121501_80_dialog_content = "嗅、嗅......",
  ui_story_1012_10121501_81_dialog_content = "嗯，空氣裡確實有戰鬥過的氣味。",
  ui_story_1012_10121501_82_dialog_content = "是......戰爭嗎......",
  ui_story_1012_10121501_83_dialog_content = "哈哈，你不相信？",
  ui_story_1012_10121501_84_dialog_content = "你們啟光應該對自己的信譽心裡有數。",
  ui_story_1012_10121501_85_dialog_content = "不過這裡確實熱鬧得反常，沒想到能看見這麼多難得一見的大人物。",
  ui_story_1012_10121501_86_dialog_content = "我和北境女王都來參與這場戰爭。",
  ui_story_1012_10121501_87_dialog_content = "這就是PlayerName的動員力啊，哈哈哈。",
  ui_story_1012_10121501_88_dialog_content = "妳和北境女王。那，另一位呢？",
  ui_story_1012_10121501_89_dialog_content = "另一位？",
  ui_story_1012_10121501_90_dialog_content = "妳們背後那位。",
  ui_story_1012_10121501_91_dialog_content = "！！！",
  ui_story_1012_10121501_92_dialog_content = "......",
  ui_story_1012_10121501_93_dialog_content = "維多利亞？妳何時.....",
  ui_story_1012_10121501_94_dialog_content = "不必在意我。",
  ui_story_1012_10121501_95_dialog_content = "我只是來，瞻仰神蹟。",
  ui_story_1012_10121501_96_dialog_content = "沒想到連妳都來了。",
  ui_story_1012_10121501_97_dialog_content = "<color=#e8d9bb>噔、噔、噔、噔、噔、噔......</color>",
  ui_story_1012_10121501_98_dialog_content = "列隊！",
  ui_story_1012_10121501_99_dialog_content = "將四周封鎖。",
  ui_story_1012_10121501_100_dialog_content = "是！",
  ui_story_1012_10121501_101_dialog_content = "艾森，你們終於來了。",
  ui_story_1012_10121501_102_dialog_content = "作為支援，這樣的速度可太慢了。",
  ui_story_1012_10121501_103_dialog_content = "對不起大元帥，我們接到的並非支援命令。",
  ui_story_1012_10121501_104_dialog_content = "那你們是來做什麼的？",
  ui_story_1012_10121501_105_dialog_content = "對不起大元帥，您無權知曉任務詳情。",
  ui_story_1012_10121501_106_dialog_content = "無權知曉？！",
  ui_story_1012_10121501_107_dialog_content = "我是啟光的大元帥，一兵一卒的調動都應該向我報告！",
  ui_story_1012_10121501_108_dialog_content = "大元帥只是軍職。",
  ui_story_1012_10121501_109_dialog_content = "戰場之外的事情，您無權插手。",
  ui_story_1012_10121501_110_dialog_content = "......",
  ui_story_1012_10121501_111_dialog_content = "又是委員會，對嗎？",
  ui_story_1012_10121501_112_dialog_content = "屬下去執行任務了。",
  ui_story_1012_10121501_113_dialog_content = "大元帥，他們......",
  ui_story_1012_10121501_114_dialog_content = "算了。",
  ui_story_1012_10121501_115_dialog_content = "在戰場之外，政客比元帥更有力量。",
  ui_story_1012_10121501_116_dialog_content = "......我要將這句話視為教誨嗎？",
  ui_story_1012_10121501_117_dialog_content = "不用。當抱怨聽吧。",
  ui_story_1012_10121501_118_dialog_content = "你看那邊，又有大隊人馬過來了。",
  ui_story_1012_10121501_119_dialog_content = "這些禿鷲，對戰場沒有興趣，卻願意為了幾具屍首爭個你死我活。",
  ui_story_1012_10121501_120_dialog_content = "城主大人，啟光的人已經在行動了。",
  ui_story_1012_10121501_121_dialog_content = "我們是否需要採取行動？",
  ui_story_1012_10121501_122_dialog_content = "不要輕舉妄動。",
  ui_story_1012_10121501_123_dialog_content = "此次事關重大。在得出結論之前，任何行為都可能招來非議。",
  ui_story_1012_10121501_124_dialog_content = "白夜城應當維持規矩，而不是當出頭鳥。",
  ui_story_1012_10121501_125_dialog_content = "是！",
  ui_story_1012_10121501_126_dialog_content = "看這陣仗我就知道，是舒瓦茲城主來了。",
  ui_story_1012_10121501_127_dialog_content = "帶著大隊人馬姍姍來遲，還真有白夜城的派頭啊！",
  ui_story_1012_10121501_128_dialog_content = "萊因哈特，我們本不是一路人，說這些又有何用呢。",
  ui_story_1012_10121501_129_dialog_content = "留些口舌在正事上吧。",
  ui_story_1012_10121501_130_dialog_content = "正事？聞到空氣中的硝煙味了嗎，正事已經結束了。",
  ui_story_1012_10121501_131_dialog_content = "你看，連商人都來了。我想接下來大家是要談生意吧，哈哈哈哈！",
  ui_story_1012_10121501_132_dialog_content = "商人手裡握著的可不只是錢。",
  ui_story_1012_10121501_133_dialog_content = "而我，也不只是商人。",
  ui_story_1012_10121501_134_dialog_content = "還是永遠跟在白夜城身後的影子，對嗎？",
  ui_story_1012_10121501_135_dialog_content = "那是我們的生存之道，大元帥有何指教？",
  ui_story_1012_10121501_136_dialog_content = "好了。我想各位聚集在這裡，都是因為感受到了事情的發生。",
  ui_story_1012_10121501_137_dialog_content = "我們該知道是什麼在製造亂源，以及未來會發生何種變數。",
  ui_story_1012_10121501_138_dialog_content = "大元帥，既然妳先來了，可以為我們帶路嗎？",
  ui_story_1012_10121501_139_dialog_content = "樂意至極。各位，跟我來吧。",
  ui_story_1012_10121501_140_dialog_content = "來了好多大人物啊！他們這是要幹什麼？",
  ui_story_1012_10121501_141_dialog_content = "看起來回歸塔復甦所引發的關注比我們想像中更大。",
  ui_story_1012_10121501_142_dialog_content = "他們應該是想探究這裡發生什麼事，以及......",
  ui_story_1012_10121501_143_dialog_content = "如何處置這座回歸塔。",
  ui_story_1012_10121501_144_dialog_content = "處置......",
  ui_story_1012_10121501_145_dialog_content = "對不起，這個詞可能會讓你有點難受。",
  ui_story_1012_10121501_146_dialog_content = "這座塔，按理說是留給你的。",
  ui_story_1012_10121501_147_dialog_content = "嗯，沒關係，我明白這些道理。",
  ui_story_1012_10121501_148_dialog_content = "在舉足輕重的大事面前，我個人不應該列入考慮。",
  ui_story_1012_10121501_149_dialog_content = "PlayerName......",
  ui_story_1012_10121501_150_dialog_content = "PlayerName！你怎麼躲在這麼角落的地方啊。",
  ui_story_1012_10121501_151_dialog_content = "啊，因為那邊......",
  ui_story_1012_10121501_152_dialog_content = "快跟我過來。大元帥叫你。",
  ui_story_1012_10121501_153_dialog_content = "欸？叫我？",
  ui_story_1012_10121501_154_dialog_content = "嗯。好多人都在等你呢，快走快走！",
  ui_story_1012_10121501_155_dialog_content = "啊，好......",
  ui_story_1012_10121501_156_dialog_content = "等一下！",
  ui_story_1012_10121501_157_dialog_content = "PlayerName，我還有一句話。",
  ui_story_1012_10121501_158_dialog_content = "遠古空裔立場的那件事，先不要跟其他人說。",
  ui_story_1012_10121501_159_dialog_content = "大元帥，PlayerName來了",
  ui_story_1012_10121501_160_dialog_content = "好！主人終於到場了。",
  ui_story_1012_10121501_161_dialog_content = "主人？！",
  ui_story_1012_10121501_162_dialog_content = "你是最後的空裔，理所當然是這座回歸塔的主人。",
  ui_story_1012_10121501_163_dialog_content = "我和女王都堅持讓你參與這場談話。",
  ui_story_1012_10121501_164_dialog_content = "跟各位領導者嗎？",
  ui_story_1012_10121501_165_dialog_content = "沒什麼好怕的，你不是也參與過白夜慶典嗎？",
  ui_story_1012_10121501_166_dialog_content = "事關這座回歸塔，你比所有人都更有發言權。",
  ui_story_1012_10121501_167_dialog_content = "表達你想表達的事情就可以，不用在意別人的地位。",
  ui_story_1012_10121501_168_dialog_content = "好、好的。",
  ui_story_1012_10121501_169_dialog_content = "我們都是些看不見光的傢伙。",
  ui_story_1012_10121501_170_dialog_content = "也許只有你能看見未來的走向。",
  ui_story_1012_10121501_171_dialog_content = "首先我想知道，你們如何看待這座塔的？",
  ui_story_1012_10121501_172_dialog_content = "從白夜城的角度來看，它毫無疑問是巨大的威脅。",
  ui_story_1012_10121501_173_dialog_content = "達摩克里斯突然自啟，這是前所未有的事情。",
  ui_story_1012_10121501_174_dialog_content = "而它指向的方向正是這裡。它在告訴我們，這座塔必須要消滅。",
  ui_story_1012_10121501_175_dialog_content = "（達摩克里斯自啟。對，我看到了當時的情景。）",
  ui_story_1012_10121501_176_dialog_content = "啟光得出的結論也是一樣的。",
  ui_story_1012_10121501_177_dialog_content = "迦南城中一些古老的遺物突然發出警報，其原因同樣來自這裡的異動。",
  ui_story_1012_10121501_178_dialog_content = "很顯然，在古老的過去，迦南城的建造者將回歸塔看做敵人。",
  ui_story_1012_10121501_179_dialog_content = "（糟糕，好像感受到了很強的敵意。）",
  ui_story_1012_10121501_180_dialog_content = "我也認同這個觀點。",
  ui_story_1012_10121501_181_dialog_content = "在遠古時代，回歸塔是值得光靈恐懼的東西。",
  ui_story_1012_10121501_182_dialog_content = "！！！",
  ui_story_1012_10121501_183_dialog_content = "既然大家都認同，那麼我提議——將這裡摧毀或掩埋。",
  ui_story_1012_10121501_184_dialog_content = "不應該存在的東西，就不要讓它存在。",
  ui_story_1012_10121501_185_dialog_content = "不是吧，摧毀這麼大一座塔？！",
  ui_story_1012_10121501_186_dialog_content = "這裡面有多少古代遺物啊，那都是可以賣錢的好嗎？",
  ui_story_1012_10121501_187_dialog_content = "說不定一些遺物改造過後還能重新利用到生活裡！",
  ui_story_1012_10121501_188_dialog_content = "你們這些官老爺，真是不懂得生活的艱辛啊！",
  ui_story_1012_10121501_189_dialog_content = "我想我們不是來談論民生問題的。",
  ui_story_1012_10121501_190_dialog_content = "啟光也認為回歸塔不該被摧毀。",
  ui_story_1012_10121501_191_dialog_content = "拋開對於它的推論，毫無疑問這是一項有軍事戰略價值的設施。",
  ui_story_1012_10121501_192_dialog_content = "摧毀它是一種浪費，它值得被研究。",
  ui_story_1012_10121501_193_dialog_content = "被啟光研究嗎？誰來保證你們會把研究成果用在正途？",
  ui_story_1012_10121501_194_dialog_content = "別忘了你們眾所皆知的前科。",
  ui_story_1012_10121501_195_dialog_content = "喂，我說你們，會不會太緊繃了？",
  ui_story_1012_10121501_196_dialog_content = "看看四周吧，這只是一座石頭堆積起來的高塔。",
  ui_story_1012_10121501_197_dialog_content = "沒有機關在運轉，也沒有光能在流動。",
  ui_story_1012_10121501_198_dialog_content = "有必要畏懼一堆石頭嗎？",
  ui_story_1012_10121501_199_dialog_content = "一堆作用不明的石頭，誰知道它能不能再次運轉？",
  ui_story_1012_10121501_200_dialog_content = "那......那個......",
  ui_story_1012_10121501_201_dialog_content = "我可以保證，回歸塔的能源現在徹底耗盡了。",
  ui_story_1012_10121501_202_dialog_content = "它就像大元帥說的，只是一堆石頭。",
  ui_story_1012_10121501_203_dialog_content = "一堆銘刻著歷史痕跡的石頭。",
  ui_story_1012_10121501_204_dialog_content = "......",
  ui_story_1012_10121501_205_dialog_content = "空裔，你做出的這個保證很沉重。你負擔得了這個重擔嗎？",
  ui_story_1012_10121501_206_dialog_content = "我......",
  ui_story_1012_10121501_207_dialog_content = "城主大人，我可以為他擔保。",
  ui_story_1012_10121501_208_dialog_content = "卡蓮？",
  ui_story_1012_10121501_209_dialog_content = "我與PlayerName一起在回歸塔中探索。",
  ui_story_1012_10121501_210_dialog_content = "我可以保證，現在的回歸塔已經無法再運作。",
  ui_story_1012_10121501_211_dialog_content = "......",
  ui_story_1012_10121501_212_dialog_content = "所以我說啊，不要把弦拉得太緊。",
  ui_story_1012_10121501_213_dialog_content = "對於世界來說，它不是什麼威脅，而是一座珍稀的古蹟。",
  ui_story_1012_10121501_214_dialog_content = "它曾經屬於空裔，現在也該屬於空裔。",
  ui_story_1012_10121501_215_dialog_content = "欸？",
  ui_story_1012_10121501_216_dialog_content = "我認為，這座塔現在屬於PlayerName。",
  ui_story_1012_10121501_217_dialog_content = "我們對於塔內遺物的處置方式，應該經過他的允許。",
  ui_story_1012_10121501_218_dialog_content = "我想，假如是對世界有益的研究，PlayerName當然會同意。",
  ui_story_1012_10121501_219_dialog_content = "至於一些惡意的目的，PlayerName也該有權拒絕。",
  ui_story_1012_10121501_220_dialog_content = "請等一下，我要先聲明一點。",
  ui_story_1012_10121501_221_dialog_content = "大元帥所言只是個人的見解，這並非啟光的意思。",
  ui_story_1012_10121501_222_dialog_content = "喔？那麼啟光的意思是什麼，我洗耳恭聽。",
  ui_story_1012_10121501_223_dialog_content = "啟光堅持要對回歸塔進行研究。",
  ui_story_1012_10121501_224_dialog_content = "這裡不該歸屬於任何個人！",
  ui_story_1012_10121501_225_dialog_content = "嘖，你們......",
  ui_story_1012_10121501_226_dialog_content = "我贊同萊因哈特的意見。",
  ui_story_1012_10121501_227_dialog_content = "回歸塔，屬於PlayerName。",
  ui_story_1012_10121501_228_dialog_content = "北境女王......",
  ui_story_1012_10121501_229_dialog_content = "我們都曾為守護自己的家園而戰，這是最值得尊敬的理由。",
  ui_story_1012_10121501_230_dialog_content = "空裔也與我們一樣，為了守護這裡而戰。",
  ui_story_1012_10121501_231_dialog_content = "如果拼死戰鬥的結果是家園任由各方定奪，那其實與戰敗無異。",
  ui_story_1012_10121501_232_dialog_content = "光靈和暗鬼，對空裔來說都不過是異族。",
  ui_story_1012_10121501_233_dialog_content = "既然將空裔視為盟友，不進犯空谷是光靈方應該給出的基本尊重。",
  ui_story_1012_10121501_234_dialog_content = "女王陛下......",
  ui_story_1012_10121501_235_dialog_content = "至於舒瓦茲城主擔心的隱患，我認為是多慮。",
  ui_story_1012_10121501_236_dialog_content = "武器的作用取決於使用者。",
  ui_story_1012_10121501_237_dialog_content = "我們都看到了，PlayerName利用回歸塔逆轉了這場戰爭。",
  ui_story_1012_10121501_238_dialog_content = "他向所有人展現了回歸塔現在的立場。",
  ui_story_1012_10121501_239_dialog_content = "......",
  ui_story_1012_10121501_240_dialog_content = "北境女王，難得見妳像這樣表達觀點。",
  ui_story_1012_10121501_241_dialog_content = "這件事對妳來說很重要？",
  ui_story_1012_10121501_242_dialog_content = "空裔這個盟友，對光靈來說很重要。",
  ui_story_1012_10121501_243_dialog_content = "我明白了。",
  ui_story_1012_10121501_244_dialog_content = "再說下去的話，恐怕會有人說我迂腐吧。",
  ui_story_1012_10121501_245_dialog_content = "北境女王說得振振有詞，我尊重她的意見。",
  ui_story_1012_10121501_246_dialog_content = "白夜城不會再插手回歸塔的處置事項。",
  ui_story_1012_10121501_247_dialog_content = "各位呢？",
  ui_story_1012_10121501_248_dialog_content = "既然如此，我附議。",
  ui_story_1012_10121501_249_dialog_content = "哈哈哈，這樣不是挺好的嗎！我沒有別的意見！",
  ui_story_1012_10121501_250_dialog_content = "......",
  ui_story_1012_10121501_251_dialog_content = "啟光的態度我已經表明，對於其他各方的選擇，我不予置評。",
  ui_story_1012_10121501_252_dialog_content = "看來這個話題可以到此為止了。",
  ui_story_1012_10121501_253_dialog_content = "慶幸也好失落也好，戰爭已經結束，各位都還能繼續分食和平的果實。",
  ui_story_1012_10121501_254_dialog_content = "直到下一場戰爭到來之前，繼續泡在溫吞的水池裡。",
  ui_story_1012_10121501_255_dialog_content = "至於PlayerName，恭喜你，收下你的戰利品吧。",
  ui_story_1012_10121501_256_dialog_content = "一個完整的家。",
  ui_story_1012_10121501_257_dialog_content = "......",
  ui_story_1012_10121501_258_dialog_content = "唉......",
  ui_story_1012_10121501_259_dialog_content = "完整的家......",
  ui_story_1012_10121501_260_dialog_content = "你為何嘆氣？",
  ui_story_1012_10121501_261_dialog_content = "女......女王陛下？！",
  ui_story_1012_10121501_262_dialog_content = "您怎麼會來這裡？",
  ui_story_1012_10121501_263_dialog_content = "你的苦惱就寫在臉上。",
  ui_story_1012_10121501_264_dialog_content = "哈哈，終究逃不過您的眼睛。",
  ui_story_1012_10121501_265_dialog_content = "嗯......嗯......",
  ui_story_1012_10121501_266_dialog_content = "我確實很茫然。我想不透。",
  ui_story_1012_10121501_267_dialog_content = "是因為這次的戰鬥嗎？",
  ui_story_1012_10121501_268_dialog_content = "不完全是。唉，我......",
  ui_story_1012_10121501_269_dialog_content = "需要一個聆聽者的話，我在這裡。",
  ui_story_1012_10121501_270_dialog_content = "不是做為北境女王，單純做為我。",
  ui_story_1012_10121501_271_dialog_content = "做為......妳......",
  ui_story_1012_10121501_272_dialog_content = "謝謝妳，我......嗯，我可能真的很需要把它說出來。",
  ui_story_1012_10121501_273_dialog_content = "說吧，我在聽。",
  ui_story_1012_10121501_274_dialog_content = "我......我們在地下看到了一些......一些空裔的往事。",
  ui_story_1012_10121501_275_dialog_content = "回歸塔里的記錄，雖然很殘破，但是我看到了......",
  ui_story_1012_10121501_276_dialog_content = "空裔與暗鬼共同戰鬥的場面......",
  ui_story_1012_10121501_277_dialog_content = "也就是說，呃......在很遙遠的過去，空裔和暗鬼可能是一夥。",
  ui_story_1012_10121501_278_dialog_content = "空裔和暗鬼？",
  ui_story_1012_10121501_279_dialog_content = "是的，我感受到了空裔和暗鬼聯合作戰的場景。",
  ui_story_1012_10121501_280_dialog_content = "我不知道該怎麼向您形容那種感覺......",
  ui_story_1012_10121501_281_dialog_content = "雖然證據都很殘破，但我相信這是真實發生過的事情。",
  ui_story_1012_10121501_282_dialog_content = "戰鬥結束以後，這些場景一直在我腦海裡盤旋，我......",
  ui_story_1012_10121501_283_dialog_content = "我快撐不住了。",
  ui_story_1012_10121501_284_dialog_content = "你還好嗎，PlayerName？",
  ui_story_1012_10121501_285_dialog_content = "我還好，就是腦袋好像快要炸開了。可惜沒能帶出那些資料，不然讓您看一下就會明白。",
  ui_story_1012_10121501_286_dialog_content = "你看到的未必就是事實，而且，我們北境可沒有空裔和暗鬼結盟的記載。",
  ui_story_1012_10121501_287_dialog_content = "我向您發誓，我真的看到空裔和暗鬼一起屠殺光靈，真的。",
  ui_story_1012_10121501_288_dialog_content = "那種感覺......那種感覺不可能是幻象那麼簡單。",
  ui_story_1012_10121501_289_dialog_content = "我也希望它是假的。我比誰都希望。",
  ui_story_1012_10121501_290_dialog_content = "如果這是真的，那諾維亞會不知道嗎？他活了那麼久，從來沒說過。",
  ui_story_1012_10121501_291_dialog_content = "是的，我在臨空者號看到的空裔歷史裡也沒提到過，完全沒有。",
  ui_story_1012_10121501_292_dialog_content = "據我所知，白夜城和啟光也沒有這方面的記載。否則......",
  ui_story_1012_10121501_293_dialog_content = "否則我這種「暗鬼同夥」的後人，肯定要被......唉，呵呵。",
  ui_story_1012_10121501_294_dialog_content = "我和您詳細說一下我們看到的資料吧，一開始......",
  ui_story_1012_10121501_295_dialog_content = "......就是這樣。",
  ui_story_1012_10121501_296_dialog_content = "......",
  ui_story_1012_10121501_297_dialog_content = "首先，這些資料並不完整，不適合輕易做出最後結論。",
  ui_story_1012_10121501_298_dialog_content = "其次，即便真的發生過，肯定也是非常非常久遠的事情。",
  ui_story_1012_10121501_299_dialog_content = "真相如何，甚至你的空裔祖先都不知道。",
  ui_story_1012_10121501_300_dialog_content = "您的意思是，這甚至在北境的歷史之前？",
  ui_story_1012_10121501_301_dialog_content = "我們光靈對遠古時代的研究很不完整，可以說是一片空白。",
  ui_story_1012_10121501_302_dialog_content = "但是光靈的歷史裡，空裔和亞人一直都是光靈的好夥伴、好盟友。",
  ui_story_1012_10121501_303_dialog_content = "我們並肩對抗暗鬼，從沒有變過。",
  ui_story_1012_10121501_304_dialog_content = "你的族人，不也是被暗鬼所殺嗎？",
  ui_story_1012_10121501_305_dialog_content = "所以，我也想不通，我也想找到真相。",
  ui_story_1012_10121501_306_dialog_content = "但是，如果空裔真的和暗鬼......",
  ui_story_1012_10121501_307_dialog_content = "即便如此，這麼遙遠的歷史，你覺得會對你有很大的影響？",
  ui_story_1012_10121501_308_dialog_content = "我一直在想，如果空裔真的曾經和暗鬼勾結......",
  ui_story_1012_10121501_309_dialog_content = "那我從小學到的東西，那些空裔的歷史和信念，不就都是假的嗎？",
  ui_story_1012_10121501_310_dialog_content = "那些我沒來得及認識的族人，他們如果看到同樣的東西，會怎麼想呢？",
  ui_story_1012_10121501_311_dialog_content = "空裔，如果真的......那就太骯髒了。",
  ui_story_1012_10121501_312_dialog_content = "雖然和光靈的理念不同，但是空裔熱愛自然、熱愛和平，這是大陸所有人都知道的事實。",
  ui_story_1012_10121501_313_dialog_content = "中間肯定有一些事情是我們現在還弄不清楚的，你要......",
  ui_story_1012_10121501_314_dialog_content = "我又在想，我是靠身為空裔的信念堅持活下來的，如果這些是假的，那我......",
  ui_story_1012_10121501_315_dialog_content = "那，一直想要成為真正空裔的我，又算什麼呢？",
  ui_story_1012_10121501_316_dialog_content = "PlayerName，你是我見過最勇敢最堅韌的空裔。",
  ui_story_1012_10121501_317_dialog_content = "......唉，腦袋都要炸了。",
  ui_story_1012_10121501_318_dialog_content = "PlayerName，如果空裔真的是暗鬼的同盟，你會怎麼做？成為暗鬼的夥伴嗎？",
  ui_story_1012_10121501_319_dialog_content = "您在說什麼？？？不管怎麼樣，我會繼續和暗鬼戰鬥！",
  ui_story_1012_10121501_320_dialog_content = "牠們奪走了我的家人，也傷害了我的夥伴，我是不會原諒暗鬼的。",
  ui_story_1012_10121501_321_dialog_content = "你的信念和力量，不都是空裔一族傳承下來的嗎？",
  ui_story_1012_10121501_322_dialog_content = "歷史只是歷史，重要的是你自己，以及那些善良勇敢的族人。",
  ui_story_1012_10121501_323_dialog_content = "我有點懂了，但是一時之間也很難接受。呃......很難接受這個污點。",
  ui_story_1012_10121501_324_dialog_content = "還記得你在白夜慶典上指責各方領導者的陰謀嗎？",
  ui_story_1012_10121501_325_dialog_content = "呵呵，你要記住那個自己呀。",
  ui_story_1012_10121501_326_dialog_content = "......這段歷史會成為我們空裔一族的恥辱和原罪，讓我在大家面前抬不起頭來。",
  ui_story_1012_10121501_327_dialog_content = "甚至，連夥伴也會懷疑......",
  ui_story_1012_10121501_328_dialog_content = "會不會像剛才討論回歸塔一樣，把我看作危害世界的隱患......",
  ui_story_1012_10121501_329_dialog_content = "我......不想面對大家猜疑的眼神......我害怕那種事發生......",
  ui_story_1012_10121501_330_dialog_content = "白夜城和啟光也有他們的污點，你為什麼會把卡蓮、薇絲她們都當成自己的好夥伴呢？",
  ui_story_1012_10121501_331_dialog_content = "因為我們一起戰鬥，相互信賴、相互依靠......",
  ui_story_1012_10121501_332_dialog_content = "他們會因為一段無比久遠的歷史碎片，而不把你當做夥伴嗎？",
  ui_story_1012_10121501_333_dialog_content = "肯定不會！",
  ui_story_1012_10121501_334_dialog_content = "所以，其實問題沒有這麼複雜。",
  ui_story_1012_10121501_335_dialog_content = "你是PlayerName，不是空裔的全部。",
  ui_story_1012_10121501_336_dialog_content = "但是，空裔幾乎是我的全部。可能，和北境對於您的意義是一樣的。",
  ui_story_1012_10121501_337_dialog_content = "空裔是沒有戰鬥力的廢物，還可能曾經是暗鬼的幫兇......",
  ui_story_1012_10121501_338_dialog_content = "一想到這種說法，我就很難過。",
  ui_story_1012_10121501_339_dialog_content = "我可以理解。",
  ui_story_1012_10121501_340_dialog_content = "歷史的真相，我們目前還沒有完全知道。",
  ui_story_1012_10121501_341_dialog_content = "但很可能是你的先祖選擇了反叛，從而改變了空裔族的命運。",
  ui_story_1012_10121501_342_dialog_content = "歷史無法改變。",
  ui_story_1012_10121501_343_dialog_content = "現在，空裔族的未來，就在於你了。",
  ui_story_1012_10121501_344_dialog_content = "嗯，我需要好好想想。",
  ui_story_1012_10121501_345_dialog_content = "也許我最該做的，是查清所有真相。",
  ui_story_1012_10121501_346_dialog_content = "如果真相是你不願意接受的呢，PlayerName？",
  ui_story_1012_10121501_347_dialog_content = "唉，我害怕真相比我想的還要殘忍。",
  ui_story_1012_10121501_348_dialog_content = "而且以後可能要面對大家的猜疑和審視。",
  ui_story_1012_10121501_349_dialog_content = "你需要時間，PlayerName。",
  ui_story_1012_10121501_350_dialog_content = "嗯......也許是很長的時間......",
  ui_story_1012_10121501_351_dialog_content = "<color=#e8d9bb>「主控系統：啟動。」</color>",
  ui_story_1012_10121501_352_dialog_content = "<color=#e8d9bb>「生物模組，啟動。」</color>",
  ui_story_1012_10121501_353_dialog_content = "<color=#e8d9bb>「維生系統：啟動。」</color>",
  ui_story_1012_10121501_354_dialog_content = "<color=#e8d9bb>「正在啟動引擎——」</color>",
  ui_story_1012_10121501_355_dialog_content = "<color=#e8d9bb>「16%......33%......」</color>",
  ui_story_1012_10121501_356_dialog_content = "<color=#e8d9bb>「89%......97%......」</color>",
  ui_story_1012_10121501_357_dialog_content = "<color=#e8d9bb>100%——啟動成功——</color>",
  ui_story_1012_10121501_358_dialog_content = "哇喔！臨空者號真的修好了！",
  ui_story_1012_10121501_359_dialog_content = "嗯！終於！！！",
  ui_story_1012_10121501_360_dialog_content = "雖然意識還沒有甦醒，光是現在這樣就很讓人興奮了！",
  ui_story_1012_10121501_361_dialog_content = "一種失而復得的感覺，對嗎？",
  ui_story_1012_10121501_362_dialog_content = "嗯，對！",
  ui_story_1012_10121501_363_dialog_content = "呼，累死了。這幾天真的是九死一生啊。",
  ui_story_1012_10121501_364_dialog_content = "感覺我們總是吊在一根細繩上，差一點點就會墜入谷底。",
  ui_story_1012_10121501_365_dialog_content = "但是那最後一點我們總是撐了過去。",
  ui_story_1012_10121501_366_dialog_content = "不得不感嘆......運氣真好啊，哈哈哈。",
  ui_story_1012_10121501_367_dialog_content = "哈哈，是啊。",
  ui_story_1012_10121501_368_dialog_content = "不過也許，也不光是運氣。",
  ui_story_1012_10121501_369_dialog_content = "說不定每一件事背後都有它的原因，只是我們沒有看見。",
  ui_story_1012_10121501_370_dialog_content = "你現在說起話來都很抽象，在回歸塔里突然覺悟了嗎？",
  ui_story_1012_10121501_371_dialog_content = "就是回想一下覺得，事情之間好像有些看不清的聯繫。",
  ui_story_1012_10121501_372_dialog_content = "過去的人們在這裡、在回歸塔發生了很多故事。",
  ui_story_1012_10121501_373_dialog_content = "那些故事永遠不得而知，但是故事留下了自己的痕跡。",
  ui_story_1012_10121501_374_dialog_content = "我們這一路就像在跟隨一串腳步。",
  ui_story_1012_10121501_375_dialog_content = "不知道腳步屬於誰，不知道那人要去做什麼。",
  ui_story_1012_10121501_376_dialog_content = "只是在跟隨的途中，畫出了一條與過去相似的軌跡。",
  ui_story_1012_10121501_377_dialog_content = "你又在說那個「弗朗茨老師」是嗎？",
  ui_story_1012_10121501_378_dialog_content = "你好像很在意他。",
  ui_story_1012_10121501_379_dialog_content = "嗯。我忍不住好奇，過去的他經歷了怎樣的故事呢？",
  ui_story_1012_10121501_380_dialog_content = "那把槍屬於他，他曾經在回歸塔與暗鬼戰鬥。",
  ui_story_1012_10121501_381_dialog_content = "「和弦紐帶」的實驗是他在進行，實驗室被層層加密藏在放逐區裡。",
  ui_story_1012_10121501_382_dialog_content = "最後為爭奪「元環權限」的一戰，不知道他是否也經歷過，但......",
  ui_story_1012_10121501_383_dialog_content = "贏下那一戰必須依賴經由「和弦紐帶」強化的光靈。",
  ui_story_1012_10121501_384_dialog_content = "確實噢。你這麼一說，我們所經歷的每一件事好像都有他的身影。",
  ui_story_1012_10121501_385_dialog_content = "我們是為了對抗日蝕而戰，他呢？",
  ui_story_1012_10121501_386_dialog_content = "他對抗的東西也許更加可怕。",
  ui_story_1012_10121501_387_dialog_content = "我說不上來那是什麼，可能......就像是命運吧。",
  ui_story_1012_10121501_388_dialog_content = "它不會要你的命，而是要你這一生都如它所願。",
  ui_story_1012_10121501_389_dialog_content = "弗朗茨老師就是在對抗這種東西，對抗他面對的「天生」。",
  ui_story_1012_10121501_390_dialog_content = "對抗......天生......",
  ui_story_1012_10121501_391_dialog_content = "竟然連這個都能對抗？",
  ui_story_1012_10121501_392_dialog_content = "也不知道他最後成功了沒有。",
  ui_story_1012_10121501_393_dialog_content = "成功了啊，妳看看外面。",
  ui_story_1012_10121501_394_dialog_content = "空裔終於在回歸塔下擁有屬於自己的家園。",
  ui_story_1012_10121501_395_dialog_content = "不用再服從命令，不再受制於暗鬼。",
  ui_story_1012_10121501_396_dialog_content = "他用這個願望，改寫了他的後世......",
  ui_story_1012_10121501_397_dialog_content = "改寫了我們所有空裔的人生。",
  ui_story_1013_10130101_1_dialog_content = "又是和平的一天。",
  ui_story_1013_10130101_2_dialog_content = "是啊。",
  ui_story_1013_10130101_3_dialog_content = "距離上次使用光能術和暗鬼戰鬥好像已經過去很久了。",
  ui_story_1013_10130101_4_dialog_content = "戰鬥技巧都要變得生疏了。",
  ui_story_1013_10130101_5_dialog_content = "和平也是一件好事啦！",
  ui_story_1013_10130101_6_dialog_content = "如果真有一天能把所有的暗鬼都消滅掉，之後的生活大概也會變成現在這樣吧。",
  ui_story_1013_10130101_7_dialog_content = "不用擔心被襲擊，可以花一整天散步、釣魚、煮飯。",
  ui_story_1013_10130101_8_dialog_content = "好像也不錯呢！",
  ui_story_1013_10130101_9_dialog_content = "到時候，PlayerName想做什麼呢？",
  ui_story_1013_10130101_10_option_content = "植樹？",
  ui_story_1013_10130101_11_dialog_content = "種出更多稀有樹種，把空庭裝點得漂漂亮亮的。",
  ui_story_1013_10130101_12_dialog_content = "只不過植樹好難啊，十次裡有九次會突變失敗！",
  ui_story_1013_10130101_13_dialog_content = "植樹是一件需要持之以恆的事情呢。",
  ui_story_1013_10130101_14_option_content = "釣魚？",
  ui_story_1013_10130101_15_dialog_content = "希望能多釣一些觀賞魚放進許願池裡。",
  ui_story_1013_10130101_16_dialog_content = "已經不想再釣上空罐子了......",
  ui_story_1013_10130101_17_dialog_content = "一定會釣到的啦！",
  ui_story_1013_10130101_18_dialog_content = "空之山谷能像現在這樣和平，還是多虧了律法之弦。",
  ui_story_1013_10130101_19_dialog_content = "只是，沒想到律法之弦的威力竟然有這麼大。",
  ui_story_1013_10130101_20_dialog_content = "當時如果沒有弗朗茨老師提前設定好的參數，而是由我隨意發射的話......",
  ui_story_1013_10130101_21_dialog_content = "恐怕會造成很嚴重的後果吧。",
  ui_story_1013_10130101_22_dialog_content = "現在想想，我依舊會覺得後怕。",
  ui_story_1013_10130101_23_dialog_content = "危機已經過去了，就不要胡思亂想啦。",
  ui_story_1013_10130101_24_dialog_content = "先過好當下的生活吧！",
  ui_story_1013_10130101_25_dialog_content = "嗯！妳說得對。",
  ui_story_1013_10130101_26_dialog_content = "說起來，薇絲，妳為什麼還穿著這身衣服？",
  ui_story_1013_10130101_27_dialog_content = "啊，你是指這身黑色的衣服嗎？",
  ui_story_1013_10130101_28_dialog_content = "之前的服裝確實穿起來更習慣一些，但是，我偶爾也希望自己的形象有一些變化。",
  ui_story_1013_10130101_29_dialog_content = "會很奇怪嗎？不然......我換回之前那身白色的制服？",
  ui_story_1013_10130101_30_dialog_content = "不用不用！",
  ui_story_1013_10130101_31_dialog_content = "不管穿什麼樣的衣服，只要薇絲認為合適，我就沒有意見！",
  ui_story_1013_10130101_32_dialog_content = "對了，剛才釣到的觀賞魚還在桶裡。",
  ui_story_1013_10130101_33_dialog_content = "要趕快把牠們放進許願池才行！",
  ui_story_1013_10130101_34_dialog_content = "對喔，差點忘了！",
  ui_story_1013_10130101_35_dialog_content = "讓我來把牠們倒進許願池裡。",
  ui_story_1013_10130101_36_dialog_content = "欸？！",
  ui_story_1013_10130101_37_dialog_content = "薇絲？妳學會新的光能術了？",
  ui_story_1013_10130101_38_dialog_content = "新的光能術？沒有啊，我......",
  ui_story_1013_10130101_39_dialog_content = "這是怎麼回事？！",
  ui_story_1013_10130101_40_dialog_content = "我沒有使用光能術啊！",
  ui_story_1013_10130101_41_dialog_content = "是誰在惡作劇嗎？快出來，我們看到你了唷！",
  ui_story_1013_10130101_42_dialog_content = "唔......不，這些光能，確實是從我的身體中湧出的。",
  ui_story_1013_10130101_43_dialog_content = "我能感覺到光能在慢慢流失，這究竟是......",
  ui_story_1013_10130101_44_dialog_content = "難道說......",
  ui_story_1013_10130101_45_dialog_content = "是使用和弦紐帶裝置留下的後遺症？",
  ui_story_1013_10130101_46_dialog_content = "妳還好嗎，薇絲？有沒有覺得不舒服？",
  ui_story_1013_10130101_47_dialog_content = "身體倒是沒有任何不適的感覺......",
  ui_story_1013_10130101_48_dialog_content = "光能流失的速度非常緩慢，甚至感覺不到。",
  ui_story_1013_10130101_49_dialog_content = "如果只是這樣的話，倒也沒什麼。",
  ui_story_1013_10130101_50_dialog_content = "但是不知道還會不會出現別的症狀。",
  ui_story_1013_10130101_51_dialog_content = "我們對古代科技的瞭解都太少了，貿然使用那個裝置，我......",
  ui_story_1013_10130101_52_dialog_content = "別擔心，PlayerName。",
  ui_story_1013_10130101_53_dialog_content = "既然這樣，我們不如回迦南城一趟吧！",
  ui_story_1013_10130101_54_dialog_content = "迦南城裡有整個啟光最優秀的科學家和治療設施，一定會查出導致這種症狀的原因的！",
  ui_story_1013_10130101_55_dialog_content = "嗯......對！我們現在就走，路上用通訊終端聯絡薇薇安，她一定會幫忙的！",
  ui_story_1013_10130101_56_dialog_content = "自動駕駛設定，目標——迦南城。",
  ui_story_1013_10130101_57_dialog_content = "快啟動，快點！",
  ui_story_1013_10130101_58_dialog_content = "PlayerName，不用那麼著急，我沒事的。",
  ui_story_1013_10130101_59_dialog_content = "只是稍微在發光而已啦。",
  ui_story_1013_10130101_60_dialog_content = "但是，妳明明是為了幫我尋找修好臨空者號的方法才受的傷。",
  ui_story_1013_10130101_61_dialog_content = "用和弦紐帶裝置救治妳也是我的決定。",
  ui_story_1013_10130101_62_dialog_content = "所以......我必須為現在妳身上出現的這些症狀負起責任。",
  ui_story_1013_10130101_63_dialog_content = "畢竟我連那些遠古裝置究竟是為了什麼目的建造的都不知道，就擅自使用了。",
  ui_story_1013_10130101_64_dialog_content = "PlayerName......",
  ui_story_1013_10130101_65_dialog_content = "別太緊張，我真的沒有感覺到任何不舒服。",
  ui_story_1013_10130101_66_dialog_content = "但是，確實也不能放著這種奇怪現象不管。",
  ui_story_1013_10130101_67_dialog_content = "妳說得對，還是先去迦南城徹底檢查一下最為保險。",
  ui_story_1013_10130101_68_dialog_content = "在這之前，先聯絡薇薇安長官，拜託她幫忙安排檢查吧。",
  ui_story_1013_10130101_69_dialog_content = "好。",
  ui_story_1013_10130101_70_dialog_content = "薇薇安，能聽到嗎？！",
  ui_story_1013_10130101_71_dialog_content = "是PlayerName嗎？請說，我能聽到。",
  ui_story_1013_10130101_72_dialog_content = "我和薇絲有件急事需要妳幫忙！",
  ui_story_1013_10130101_73_dialog_content = "這個時候有急事，難道說薇絲也出現了那個情況？",
  ui_story_1013_10130101_74_dialog_content = "「也」？",
  ui_story_1013_10130101_75_dialog_content = "巴頓也出現奇怪的發光情況了嗎？！",
  ui_story_1013_10130101_76_dialog_content = "是的，在上次空之山谷的戰鬥後，巴頓軍團長被安排休息了一段時間。",
  ui_story_1013_10130101_77_dialog_content = "但是，今天早上他的身體突然出現了不明原因的光能逸散現象。",
  ui_story_1013_10130101_78_dialog_content = "聽你這麼說，難道薇絲也出現了類似的情況？",
  ui_story_1013_10130101_79_dialog_content = "是的，我們正在趕去迦南城的路上，能不能請妳幫忙給薇絲安排檢查？",
  ui_story_1013_10130101_80_dialog_content = "這件事情就交給我吧。",
  ui_story_1013_10130101_81_dialog_content = "啟光本來也在準備為使用過和弦紐帶裝置的巴頓軍團長和薇絲進行全面檢查的。",
  ui_story_1013_10130101_82_dialog_content = "是嗎？那太好了！",
  ui_story_1013_10130101_83_dialog_content = "你們到達迦南城後，直接到醫療中心來吧，我會在那裡等你們。",
  ui_story_1013_10130101_84_dialog_content = "好的，拜託妳了！",
  ui_story_1013_10130101_85_dialog_content = "<color=#e8d9bb>迦南城·醫療中心</color>",
  ui_story_1013_10130101_86_dialog_content = "這裡就是醫療中心了。",
  ui_story_1013_10130101_87_dialog_content = "上一次到這裡還是來參加入伍前統一安排的體檢呢。",
  ui_story_1013_10130101_88_dialog_content = "之前沒來過這裡，沒想到啟光的醫療中心竟然這麼大！",
  ui_story_1013_10130101_89_dialog_content = "那是當然！",
  ui_story_1013_10130101_90_dialog_content = "一旦打起仗來，就不知道會造成多大的傷亡。",
  ui_story_1013_10130101_91_dialog_content = "醫療中心大一點的話，也會有更多受傷的士兵能夠得到及時的救治。",
  ui_story_1013_10130101_92_dialog_content = "活下來的機會也能更多一些......",
  ui_story_1013_10130101_93_dialog_content = "確實......",
  ui_story_1013_10130101_94_dialog_content = "唷，薇絲，PlayerName！",
  ui_story_1013_10130101_95_dialog_content = "你們果然已經到了。",
  ui_story_1013_10130101_96_dialog_content = "巴頓軍團長！薇薇安長官！",
  ui_story_1013_10130101_97_dialog_content = "巴頓身上也出現了同樣的現象......",
  ui_story_1013_10130101_98_dialog_content = "啊？哦，你說這個發光嗎？",
  ui_story_1013_10130101_99_dialog_content = "只是發光的話倒也沒什麼所謂，反正它幾乎不會消耗光能。",
  ui_story_1013_10130101_100_dialog_content = "但是，也不能忽略潛在的危險啊！",
  ui_story_1013_10130101_101_dialog_content = "話是這麼說啦，不過，我希望那群醫生和科學家能快點找出讓發光停止的方法。",
  ui_story_1013_10130101_102_dialog_content = "不然保持這副樣子，在夜裡簡直就像一個發光標靶，更別提偷襲敵人了！",
  ui_story_1013_10130101_103_dialog_content = "確......確實呢。",
  ui_story_1013_10130101_104_dialog_content = "怎麼了，小子，你都快把擔心兩個字寫在臉上了。",
  ui_story_1013_10130101_105_dialog_content = "欸？嗯......我確實很擔心。",
  ui_story_1013_10130101_106_dialog_content = "別擔心了，這裡可是整個啟光最好的醫療機構，就算只剩一口氣也能把人救活！",
  ui_story_1013_10130101_107_dialog_content = "更別提這種不痛不癢的發光現象了。",
  ui_story_1013_10130101_108_dialog_content = "嗯......嗯！",
  ui_story_1013_10130101_109_dialog_content = "那麼，我先帶巴頓軍團長和薇絲去檢查。",
  ui_story_1013_10130101_110_dialog_content = "PlayerName，請在外面稍等。",
  ui_story_1013_10130101_111_dialog_content = "我知道了。",
  ui_story_1013_10130101_112_dialog_content = "那我先走啦。",
  ui_story_1013_10130101_113_dialog_content = "一會見，小子。",
  ui_story_1013_10130101_114_dialog_content = "走廊裡，重新回歸寂靜了。",
  ui_story_1013_10130101_115_dialog_content = "希望這次的意外只是偶然現象吧。",
  ui_story_1013_10130101_116_dialog_content = "而你們只負責為世界——",
  ui_story_1013_10130101_117_dialog_content = "帶來戰爭。",
  ui_story_1013_10130101_118_dialog_content = "......",
  ui_story_1013_10130101_119_dialog_content = "不，我絕對不會那樣做。",
  ui_story_1013_10130101_120_dialog_content = "但是，我的選擇，真的正確嗎？",
  ui_story_1013_10130101_121_dialog_content = "看起來和上一次沒什麼區別，不過不能放鬆警惕。",
  ui_story_1013_10130101_122_dialog_content = "你的身體情況已經不允許任何疏忽和意外了。",
  ui_story_1013_10130101_123_dialog_content = "咳咳......我知道，我知道。",
  ui_story_1013_10130101_124_dialog_content = "對於自己的身體情況，我一直有著清醒的認知。",
  ui_story_1013_10130101_125_dialog_content = "你可以跟著我們一起去訓練啊。",
  ui_story_1013_10130101_126_dialog_content = "相信我，我就是透過訓練從一個什麼都不行的豆芽菜一點點變強的！",
  ui_story_1013_10130101_127_dialog_content = "哈哈哈，我的情況不是訓練能夠解決的喔。",
  ui_story_1013_10130101_128_dialog_content = "（這幾個人也是來檢查身體的嗎？）",
  ui_story_1013_10130101_129_dialog_content = "你，在看什麼呢？",
  ui_story_1013_10130101_130_dialog_content = "咦？！對......對不起！",
  ui_story_1013_10130101_131_dialog_content = "只是看到了陌生人，就......",
  ui_story_1013_10130101_132_dialog_content = "等一下，你......",
  ui_story_1013_10130101_133_dialog_content = "你該不會是那個傳說中的空裔吧？",
  ui_story_1013_10130101_134_dialog_content = "什麼？",
  ui_story_1013_10130101_135_dialog_content = "欸？是空裔嗎？",
  ui_story_1013_10130101_136_dialog_content = "你們認識我嗎？我們應該沒見過吧？",
  ui_story_1013_10130101_137_dialog_content = "當然了，你在我們那裡可是非常有名的。",
  ui_story_1013_10130101_138_dialog_content = "駕駛巨像，在熱砂防線與光靈共同對抗暗鬼。",
  ui_story_1013_10130101_139_dialog_content = "還在空之山谷與啟光、白夜城和北境聯軍一起擊退了暗鬼。",
  ui_story_1013_10130101_140_dialog_content = "你的事跡，我們那裡的每個人都很佩服。",
  ui_story_1013_10130101_141_option_content = "我只是做了力所能及的事",
  ui_story_1013_10130101_142_dialog_content = "畢竟暗鬼是大家共同的敵人。",
  ui_story_1013_10130101_143_option_content = "這是大家共同努力的結果",
  ui_story_1013_10130101_144_dialog_content = "如果沒有各位的幫助，我一個人是沒辦法做到那麼多事的。",
  ui_story_1013_10130101_145_dialog_content = "你還真是如傳聞中的那樣謙虛呢。",
  ui_story_1013_10130101_146_dialog_content = "自我介紹一下，我的名字是昭，在西方的黃昏鎮擔任參謀長一職。",
  ui_story_1013_10130101_147_dialog_content = "這是我的助手鴉青和部下西恩。",
  ui_story_1013_10130101_148_dialog_content = "沒想到能在這裡與你相遇，真是太幸運了。",
  ui_story_1013_10130101_149_dialog_content = "你們好，我是PlayerName。",
  ui_story_1013_10130101_150_dialog_content = "你好呀，PlayerName。",
  ui_story_1013_10130101_151_dialog_content = "你好。",
  ui_story_1013_10130101_152_dialog_content = "剛才多有得罪，但是，保護昭是我的使命。",
  ui_story_1013_10130101_153_dialog_content = "沒事沒事，偷偷打量別人確實是我失禮了。",
  ui_story_1013_10130101_154_dialog_content = "昭參謀長經常跟我們提起你的事跡唷！",
  ui_story_1013_10130101_155_dialog_content = "能駕駛巨像到各處去，真羡慕啊！",
  ui_story_1013_10130101_156_dialog_content = "有了巨像的幫助，就算要到很遠的地方去，應該也十分方便吧？",
  ui_story_1013_10130101_157_dialog_content = "確實方便。不管到哪裡去，只要乘著巨像，都能很快到達。",
  ui_story_1013_10130101_158_dialog_content = "真好！我也想有一艘能夠搭乘的巨像。",
  ui_story_1013_10130101_159_dialog_content = "這樣就能快點回到黃昏鎮去了！",
  ui_story_1013_10130101_160_dialog_content = "欸？你是有什麼很緊急的事情嗎？",
  ui_story_1013_10130101_161_dialog_content = "當然了！",
  ui_story_1013_10130101_162_dialog_content = "PlayerName，你還不知道黃昏鎮的情況吧？",
  ui_story_1013_10130101_163_dialog_content = "不太清楚。那是哪裡？",
  ui_story_1013_10130101_164_dialog_content = "黃昏鎮在啟光防線的外側，離迦南城有些遙遠。",
  ui_story_1013_10130101_165_dialog_content = "雖然會比防線內側的聚落更容易遭受暗鬼騷擾，但仍然是一個好地方喔。",
  ui_story_1013_10130101_166_dialog_content = "我想快點回去，幫助夥伴們一起消滅那些黑漆漆的傢伙！",
  ui_story_1013_10130101_167_dialog_content = "真是的，明明只是一點點小傷，那些醫生卻要叫我回迦南城接受治療。",
  ui_story_1013_10130101_168_dialog_content = "不過還好，檢查已經結束。今天下午就能返回黃昏鎮了！",
  ui_story_1013_10130101_169_dialog_content = "這大概也是為了你好。",
  ui_story_1013_10130101_170_dialog_content = "時刻保持健康狀態，才能有餘力對付更多敵人。",
  ui_story_1013_10130101_171_dialog_content = "可不能學某個人，不停透支自己。",
  ui_story_1013_10130101_172_dialog_content = "咳咳......那麼，PlayerName，我們就先回去了。",
  ui_story_1013_10130101_173_dialog_content = "有機會的話，歡迎你來黃昏鎮。",
  ui_story_1013_10130101_174_dialog_content = "我非常期待能和空裔並肩作戰。",
  ui_story_1013_10130101_175_dialog_content = "有機會的話，我一定去。",
  ui_story_1013_10130101_176_dialog_content = "那麼，有緣再見了。",
  ui_story_1013_10130101_177_dialog_content = "再會。",
  ui_story_1013_10130101_178_dialog_content = "拜拜——！",
  ui_story_1013_10130101_179_dialog_content = "黃昏鎮嗎？聽起來好像在很遠的地方呢。",
  ui_story_1013_10130101_180_dialog_content = "咦？那邊從診療室裡走出來的人是......",
  ui_story_1013_10130101_181_dialog_content = "萊因哈特？！",
  ui_story_1013_10130101_182_dialog_content = "嗯？PlayerName。",
  ui_story_1013_10130101_183_dialog_content = "我已經聽薇薇安說過你會帶著薇絲來迦南城了，沒想到能在這裡遇見。",
  ui_story_1013_10130101_184_dialog_content = "我也很意外，萊因哈特。",
  ui_story_1013_10130101_185_dialog_content = "妳怎麼也在這裡？",
  ui_story_1013_10130101_186_dialog_content = "難道上次使用過臨空者號的醫療系統後，妳身上也出現了奇怪的現象？",
  ui_story_1013_10130101_187_dialog_content = "不，我沒有出現巴頓和薇絲那樣的情況。",
  ui_story_1013_10130101_188_dialog_content = "這次來只是例行的身體檢查。",
  ui_story_1013_10130101_189_dialog_content = "每隔半年就會進行一次，內容包括測試體能和抽血檢驗等。",
  ui_story_1013_10130101_190_dialog_content = "結果和上一次沒什麼變化，你就放心吧。",
  ui_story_1013_10130101_191_dialog_content = "是嗎，妳沒事就好。對了，上次受的傷怎麼樣了？",
  ui_story_1013_10130101_192_dialog_content = "哈哈哈，放心吧。托了醫療系統的福，傷口早就癒合了。",
  ui_story_1013_10130101_193_dialog_content = "如果啟光也能有這樣的設施......",
  ui_story_1013_10130101_194_dialog_content = "我們回來了，小子。",
  ui_story_1013_10130101_195_dialog_content = "萊因哈特大元帥？妳也在啊。",
  ui_story_1013_10130101_196_dialog_content = "PlayerName，還有大元帥？！",
  ui_story_1013_10130101_197_dialog_content = "你們兩個檢查完了？結果怎樣？",
  ui_story_1013_10130101_198_dialog_content = "結果？該怎麼說呢......",
  ui_story_1013_10130101_199_dialog_content = "報告，結果就是——沒有結果！",
  ui_story_1013_10130101_200_dialog_content = "欸？！",
  ui_story_1013_10130101_201_dialog_content = "那些醫生和科學家拿著各種儀器在我們身上測試了半天，也沒得出什麼結論。",
  ui_story_1013_10130101_202_dialog_content = "該做的身體檢查都做了，和正常狀態沒什麼不一樣。",
  ui_story_1013_10130101_203_dialog_content = "嗯，至少從檢測結果上看，沒有任何問題。",
  ui_story_1013_10130101_204_dialog_content = "可是，你們身上現在已經沒有光能逸散現象了，這是怎麼治好的？",
  ui_story_1013_10130101_205_dialog_content = "哦，那個啊！",
  ui_story_1013_10130101_206_dialog_content = "測試的時候，科學家讓我們使用光能術攻擊訓練假人。",
  ui_story_1013_10130101_207_dialog_content = "他們大概是想看看這種光能逸散現象會不會對光能術的威力造成影響吧。",
  ui_story_1013_10130101_208_dialog_content = "總之，在痛痛快快地對著訓練假人打了一通以後，發光的現象就自己消失了。",
  ui_story_1013_10130101_209_dialog_content = "早知道這樣就能不再發光，我還不如去找幾隻暗鬼揍一頓。",
  ui_story_1013_10130101_210_dialog_content = "聽科學家們說，巴頓軍團長打壞了足足十個訓練假人呢。",
  ui_story_1013_10130101_211_dialog_content = "哦？那維修需要的材料就從第二軍團長這個月的配給裡扣吧。",
  ui_story_1013_10130101_212_dialog_content = "什......什麼？",
  ui_story_1013_10130101_213_dialog_content = "哈哈哈，我開玩笑的。",
  ui_story_1013_10130101_214_dialog_content = "你們兩個沒事就好，但是，也不要因為暫時沒事就放鬆警惕。",
  ui_story_1013_10130101_215_dialog_content = "最近一段時間還是定期進行檢查，確保萬無一失吧。",
  ui_story_1013_10130101_216_dialog_content = "是！",
  ui_story_1013_10130101_217_dialog_content = "是！",
  ui_story_1013_10130101_218_dialog_content = "總之，我的情況一切正常。",
  ui_story_1013_10130101_219_dialog_content = "PlayerName也不用太擔心。",
  ui_story_1013_10130101_220_dialog_content = "只是光能逸散的話，現在看起來確實不會有什麼問題。",
  ui_story_1013_10130101_221_dialog_content = "但我擔心使用和弦紐帶究竟會不會帶來其他症狀。",
  ui_story_1013_10130101_222_dialog_content = "對於一切的未知，這才是最可怕的......",
  ui_story_1013_10130101_223_dialog_content = "醫生和科學家們也是這麼說的喔。",
  ui_story_1013_10130101_224_dialog_content = "所以他們建議我多多進行各項活動，並且留意身體狀態的變化。",
  ui_story_1013_10130101_225_dialog_content = "嗯，我也會幫忙留意的！",
  ui_story_1013_10130101_226_dialog_content = "說到這個，我有一項提議。",
  ui_story_1013_10130101_227_dialog_content = "不，準確來說，是一項請求。",
  ui_story_1013_10130101_228_dialog_content = "PlayerName，我希望你能同意向啟光開放研究臨空者號和回歸塔的許可權。",
  ui_story_1013_10130101_229_dialog_content = "欸？！",
  ui_story_1013_10130101_230_dialog_content = "為什麼，我能問一下原因嗎？",
  ui_story_1013_10130101_231_dialog_content = "當然沒問題。",
  ui_story_1013_10130101_232_dialog_content = "在之前的那些事中，我和啟光的科研人員都深刻地體會到了空裔掌握的科技有多強。",
  ui_story_1013_10130101_233_dialog_content = "尤其是和弦紐帶和醫療裝置，如果能用在戰鬥中，可以拯救無數光靈的生命。",
  ui_story_1013_10130101_234_dialog_content = "另外，巨像上的模擬室也是非常有潛力的裝置。",
  ui_story_1013_10130101_235_dialog_content = "如果能用來訓練指揮者，一定能減少傷亡。",
  ui_story_1013_10130101_236_dialog_content = "但是......",
  ui_story_1013_10130101_237_dialog_content = "（如果空裔的科技是用於帶來戰爭的，這樣交出去，真的沒問題嗎？）",
  ui_story_1013_10130101_238_dialog_content = "我明白你的顧慮。",
  ui_story_1013_10130101_239_dialog_content = "所以，我向你保證——",
  ui_story_1013_10130101_240_dialog_content = "啟光絕對不會將這份技術用於不正當的用途。",
  ui_story_1013_10130101_241_dialog_content = "而且，我們會給你相應的報酬。",
  ui_story_1013_10130101_242_dialog_content = "作為回報，啟光會派出最頂尖的科學家，幫助你修復臨空者號。",
  ui_story_1013_10130101_243_dialog_content = "......",
  ui_story_1013_10130101_244_dialog_content = "薇絲，妳的意見呢？",
  ui_story_1013_10130101_245_dialog_content = "我的意見嗎？",
  ui_story_1013_10130101_246_dialog_content = "雖然我也很希望啟光能夠擁有先進的治療技術。",
  ui_story_1013_10130101_247_dialog_content = "但是，PlayerName，空谷是屬於你的，只有你能做決定。",
  ui_story_1013_10130101_248_dialog_content = "那麼，PlayerName，你的意見是？",
  ui_story_1013_10130101_249_dialog_content = "喂，等一下，大元帥。",
  ui_story_1013_10130101_250_dialog_content = "妳現在就讓他給出回答，是不是太著急了？",
  ui_story_1013_10130101_251_dialog_content = "這可不是什麼不用動腦子就能決定的小事。",
  ui_story_1013_10130101_252_dialog_content = "給他一些時間，讓這小子好好思考，再做決定吧。",
  ui_story_1013_10130101_253_dialog_content = "......",
  ui_story_1013_10130101_254_dialog_content = "抱歉，是我太過急躁了。",
  ui_story_1013_10130101_255_dialog_content = "如果你需要時間思考的話，不用著急，我可以等。",
  ui_story_1013_10130101_256_dialog_content = "我......",
  ui_story_1013_10130101_257_dialog_content = "沒關係的。",
  ui_story_1013_10130101_258_option_content = "我同意了",
  ui_story_1013_10130101_259_dialog_content = "太好了，謝謝你，PlayerName。",
  ui_story_1013_10130101_260_option_content = "我信任妳",
  ui_story_1013_10130101_261_dialog_content = "......！",
  ui_story_1013_10130101_262_dialog_content = "謝謝你，PlayerName。",
  ui_story_1013_10130101_263_dialog_content = "事不宜遲，我現在就聯絡研究院的科學家，讓他們做好準備。",
  ui_story_1013_10130101_264_dialog_content = "PlayerName和薇絲也一起來吧，之後可能還需要你們幫忙，要給你們添不少麻煩了。",
  ui_story_1013_10130101_265_dialog_content = "沒關係。如果你們也幫我修臨空者號的話，那麼這是在互相幫助。",
  ui_story_1013_10130101_266_dialog_content = "如果是為了啟光，那麼這是我的責任，我絕不會推辭。",
  ui_story_1013_10130101_267_dialog_content = "看起來這裡也沒我什麼事了。",
  ui_story_1013_10130101_268_dialog_content = "那我就先回第二軍團了。",
  ui_story_1013_10130101_269_dialog_content = "有空一起來下棋啊，小子。",
  ui_story_1013_10130101_270_dialog_content = "嗯，下次一定！",
  ui_story_1013_10130201_1_dialog_content = "這裡就是啟光研究院的辦公區了。",
  ui_story_1013_10130201_2_dialog_content = "你們兩個應該都是第一次來這裡吧？",
  ui_story_1013_10130201_3_dialog_content = "是，是的！",
  ui_story_1013_10130201_4_dialog_content = "一直聽說研究院聚集著整個啟光聯邦最優秀的科學家。",
  ui_story_1013_10130201_5_dialog_content = "沒想到今天竟然能真的來到這裡親眼看一看！",
  ui_story_1013_10130201_6_dialog_content = "好多人！",
  ui_story_1013_10130201_7_dialog_content = "那是當然，這裡的每個人，都在為了啟光而努力工作。",
  ui_story_1013_10130201_8_dialog_content = "而正是他們的努力，才讓啟光有了今天的成就。",
  ui_story_1013_10130201_9_dialog_content = "嗨～大元帥！還有薇絲和我的手下敗將～",
  ui_story_1013_10130201_10_option_content = "貢露？！",
  ui_story_1013_10130201_11_dialog_content = "妳怎麼在這裡？",
  ui_story_1013_10130201_12_dialog_content = "剛剛大元帥要求我和彌加德來幫忙進行實驗，說是可以盡情研究臨空者號的新功能。",
  ui_story_1013_10130201_13_dialog_content = "這可比挑戰最高難度的遊戲關卡有趣得多，所以我就飛快地趕過來啦！",
  ui_story_1013_10130201_14_dialog_content = "還請妳對臨空者號溫柔一點......",
  ui_story_1013_10130201_15_dialog_content = "安啦，我會用最謹慎的方案對待臨空者號的！",
  ui_story_1013_10130201_16_dialog_content = "好久不見啊，年輕人。",
  ui_story_1013_10130201_17_dialog_content = "彌加德......小姐......",
  ui_story_1013_10130201_18_dialog_content = "（雖然知道她沒有惡意，但是每次面對她的時候，總是不由自主地緊張呢......）",
  ui_story_1013_10130201_19_dialog_content = "嗯？你那副表情是怎麼回事？",
  ui_story_1013_10130201_20_dialog_content = "你從今天早些時候剛到啟光時起，就一副憂心忡忡的樣子。",
  ui_story_1013_10130201_21_dialog_content = "因為薇絲的身體出現了一些意外情況......",
  ui_story_1013_10130201_22_dialog_content = "等等，妳之前就注意到了？之前我怎麼沒看到妳，難道說我不小心忽略了妳？",
  ui_story_1013_10130201_23_dialog_content = "呵呵，你可別忘了，我的潛庭之脊一直在注視著啟光的每一個角落。",
  ui_story_1013_10130201_24_dialog_content = "就算我不在場，也能透過牠看見你。",
  ui_story_1013_10130201_25_dialog_content = "原，原來如此......",
  ui_story_1013_10130201_26_dialog_content = "好啦，我們趕快走吧，研究院的各位也已經等不及了！",
  ui_story_1013_10130201_27_dialog_content = "PlayerName，我們走吧！",
  ui_story_1013_10130201_28_dialog_content = "各位！PlayerName來了唷！",
  ui_story_1013_10130201_29_dialog_content = "這就是傳說中的PlayerName嗎，久仰大名！",
  ui_story_1013_10130201_30_dialog_content = "雖然看起來年紀輕輕，但也勉強算是合格的實驗體。",
  ui_story_1013_10130201_31_dialog_content = "實驗體？！",
  ui_story_1013_10130201_32_dialog_content = "PlayerName是我的夥伴，才不是什麼實驗體！",
  ui_story_1013_10130201_33_dialog_content = "哈哈，別在意，這裡的研究員多多少少都會有些奇怪的習慣。",
  ui_story_1013_10130201_34_dialog_content = "但是，他們沒有惡意，放心吧。",
  ui_story_1013_10130201_35_dialog_content = "大元帥，研究院已經根據您的安排做好了準備，隨時可以開展研究。",
  ui_story_1013_10130201_36_dialog_content = "嗯，在此之前，還有一件事要做。",
  ui_story_1013_10130201_37_dialog_content = "還有什麼事？",
  ui_story_1013_10130201_38_dialog_content = "那件事就是——對你表示感謝。",
  ui_story_1013_10130201_39_dialog_content = "欸？",
  ui_story_1013_10130201_40_dialog_content = "剛才不是已經謝過了嗎？",
  ui_story_1013_10130201_41_dialog_content = "那只是我私人的致謝，而這一次，是作為啟光聯邦的大元帥感謝你。",
  ui_story_1013_10130201_42_dialog_content = "你向啟光開放的研究許可權，一定可以拯救無數光靈。",
  ui_story_1013_10130201_43_dialog_content = "謝啦，PlayerName！",
  ui_story_1013_10130201_44_dialog_content = "雖然工作量增加了，但還是謝謝你，年輕人。",
  ui_story_1013_10130201_45_dialog_content = "謝......謝謝你！",
  ui_story_1013_10130201_46_dialog_content = "謝謝你的貢獻，實驗體。",
  ui_story_1013_10130201_47_dialog_content = "我明明什麼都還沒做？！",
  ui_story_1013_10130201_48_dialog_content = "你就接受這份謝意吧。",
  ui_story_1013_10130201_49_dialog_content = "畢竟這一切成立的前提，就是你的同意啊。",
  ui_story_1013_10130201_50_dialog_content = "嗯......",
  ui_story_1013_10130201_51_dialog_content = "別這樣盯著我看了，怪不好意思的......",
  ui_story_1013_10130201_52_dialog_content = "你們不是還要研究呢嗎？",
  ui_story_1013_10130201_53_dialog_content = "哈哈哈哈，說的也是。",
  ui_story_1013_10130201_54_dialog_content = "你們，按照計畫開始工作吧。",
  ui_story_1013_10130201_55_dialog_content = "是。",
  ui_story_1013_10130201_56_dialog_content = "按照大元帥的指令，所有人分成三組。",
  ui_story_1013_10130201_57_dialog_content = "A組，前往回歸塔，搜尋和弦紐帶裝置的資訊。",
  ui_story_1013_10130201_58_dialog_content = "B組就跟我走吧，正好收集臨空者號醫療裝置的資料。",
  ui_story_1013_10130201_59_dialog_content = "也好，剩下的C組聽我指揮，使用資料傳輸線纜連結臨空者號模擬室。",
  ui_story_1013_10130201_60_dialog_content = "看看能不能用啟光的戰鬥模擬器解析模擬室的資料。",
  ui_story_1013_10130201_61_dialog_content = "是！",
  ui_story_1013_10130201_62_dialog_content = "啟光還有戰鬥模擬器？",
  ui_story_1013_10130201_63_dialog_content = "是的。上一次貢露幫臨空者號安裝完模擬室後，帶回了一部分研究資料。",
  ui_story_1013_10130201_64_dialog_content = "她回到啟光以後，根據臨空者號的模擬室仿製了一台類似的機器。",
  ui_story_1013_10130201_65_dialog_content = "雖然她最初的目的似乎只是想造一台遊戲機......",
  ui_story_1013_10130201_66_dialog_content = "但是，最終卻造出了一個不得了的東西呢！",
  ui_story_1013_10130201_67_dialog_content = "那麼厲害嗎？！",
  ui_story_1013_10130201_68_dialog_content = "嗯！你要是對那台機器感興趣，一會實驗的時候可以親自試試。",
  ui_story_1013_10130201_69_dialog_content = "好，我當然要試試看！",
  ui_story_1013_10130201_70_dialog_content = "提前練習好，讓她對我這個手下敗將刮目相看！",
  ui_story_1013_10130201_71_dialog_content = "<color=#e8d9bb>幾小時後</color>",
  ui_story_1013_10130201_72_dialog_content = "報告大元帥。",
  ui_story_1013_10130201_73_dialog_content = "有什麼發現嗎？",
  ui_story_1013_10130201_74_dialog_content = "是好消息，我們在臨空者號的新模組中獲得了醫療裝置的製造方法。",
  ui_story_1013_10130201_75_dialog_content = "利用這些資料，我們就能升級醫療中心的裝置。",
  ui_story_1013_10130201_76_dialog_content = "這真是太好了！",
  ui_story_1013_10130201_77_dialog_content = "繼續研究，看看還能不能有什麼新的發現。",
  ui_story_1013_10130201_78_dialog_content = "是。",
  ui_story_1013_10130201_79_dialog_content = "醫療裝置......",
  ui_story_1013_10130201_80_dialog_content = "之前那個叫昭的人，身體狀況看起來很糟糕。",
  ui_story_1013_10130201_81_dialog_content = "如果醫療裝置完成升級的話，是不是可以治好他呢？",
  ui_story_1013_10130201_82_dialog_content = "哦？你認識昭？",
  ui_story_1013_10130201_83_dialog_content = "啊，是......是的。剛才在醫療中心碰巧遇到了他們，才互相認識的。",
  ui_story_1013_10130201_84_dialog_content = "原來如此。",
  ui_story_1013_10130201_85_dialog_content = "昭是黃昏鎮啟光駐軍的參謀長，有著過人的頭腦，身體卻十分羸弱。",
  ui_story_1013_10130201_86_dialog_content = "究其原因，是他早年受過重傷。暗能侵蝕了他的身體器官，讓他無法戰鬥。",
  ui_story_1013_10130201_87_dialog_content = "難怪他的身上散發著一股病態的感覺。",
  ui_story_1013_10130201_88_dialog_content = "不僅如此，他的屬下西恩也被身體方面的問題困擾著。",
  ui_story_1013_10130201_89_dialog_content = "西恩？！他明明看起來活蹦亂跳的？",
  ui_story_1013_10130201_90_dialog_content = "那是因為他一直在不停地磨練自己。",
  ui_story_1013_10130201_91_dialog_content = "事實上，他的基因有著非常複雜的缺陷。",
  ui_story_1013_10130201_92_dialog_content = "這也使得他在最初入伍的時候沒有受到重視，被派往遙遠的駐地做底層士兵。",
  ui_story_1013_10130201_93_dialog_content = "那孩子能獲得如今的成就，全靠他不屈的意志。",
  ui_story_1013_10130201_94_dialog_content = "嗯，我能感受到他身上有一種常年在戰鬥中磨練形成的氣質。",
  ui_story_1013_10130201_95_dialog_content = "是的。所以，一旦醫療裝置完成升級，他們這樣的人會成為第一批受益者。",
  ui_story_1013_10130201_96_dialog_content = "大元帥，對於和弦紐帶裝置的研究已經有了一定進展。",
  ui_story_1013_10130201_97_dialog_content = "好，好快？！",
  ui_story_1013_10130201_98_dialog_content = "不要小看啟光的技術水準，實驗體。",
  ui_story_1013_10130201_99_dialog_content = "說回正事，大元帥，我們認為應該向您進行匯報，但是......",
  ui_story_1013_10130201_100_dialog_content = "（他好像在偷偷瞄向我？）",
  ui_story_1013_10130201_101_dialog_content = "PlayerName是空之山谷與和弦紐帶的主人。",
  ui_story_1013_10130201_102_dialog_content = "關於這項技術的研究，沒什麼不能對他說的。",
  ui_story_1013_10130201_103_dialog_content = "是，那我就用實驗體也能聽懂的方式簡單說明吧。",
  ui_story_1013_10130201_104_dialog_content = "從對巴頓軍團長和薇絲中尉的身體檢查結果來看，我們已經對裝置的用途有了初步推斷。",
  ui_story_1013_10130201_105_dialog_content = "我們懷疑，和弦紐帶除了能夠改造光靈的身體外，還能激發光靈的潛力。",
  ui_story_1013_10130201_106_option_content = "改造身體？",
  ui_story_1013_10130201_107_dialog_content = "你沒注意到嗎？巴頓軍團長和薇絲中尉的樣子都或多或少地出現了變化。",
  ui_story_1013_10130201_108_dialog_content = "這我確實知道，但是除了外表呢？這種改造對身體會不會有其他影響？",
  ui_story_1013_10130201_109_dialog_content = "這一點還需要進一步研究才能得出結論。",
  ui_story_1013_10130201_110_dialog_content = "但能夠確定的是，這種改變也影響了他們使用的光能術。",
  ui_story_1013_10130201_111_option_content = "激發潛力？",
  ui_story_1013_10130201_112_dialog_content = "是的，我們懷疑和弦紐帶對他們的改造也改變了他們使用光能術的方式。",
  ui_story_1013_10130201_113_dialog_content = "讓他們能夠釋放出原本無法使用或者很難用出的強大力量。",
  ui_story_1013_10130201_114_dialog_content = "這就要說回光能術的原理了。",
  ui_story_1013_10130201_115_dialog_content = "我不介意花一天時間為實驗體詳細解釋光能術的各種知識。",
  ui_story_1013_10130201_116_dialog_content = "呃......還，還是算了吧。",
  ui_story_1013_10130201_117_dialog_content = "實驗體，你不必太過擔心。",
  ui_story_1013_10130201_118_dialog_content = "就算使用了和弦紐帶裝置，他們也依舊保持著使用過去的光能術的能力。",
  ui_story_1013_10130201_119_dialog_content = "因此，我們不認為他們從本質上發生了改變。",
  ui_story_1013_10130201_120_dialog_content = "是嗎......",
  ui_story_1013_10130201_121_dialog_content = "你們好像在討論什麼很嚴肅的話題？",
  ui_story_1013_10130201_122_dialog_content = "妳手裡拿著的不是戰鬥模擬器的頭盔嗎？",
  ui_story_1013_10130201_123_dialog_content = "那邊的研究有進展了？",
  ui_story_1013_10130201_124_dialog_content = "是的！",
  ui_story_1013_10130201_125_dialog_content = "我們用戰鬥模擬器連結了臨空者號的資料庫。",
  ui_story_1013_10130201_126_dialog_content = "在剛剛進行研究的時候，似乎觸發了臨空者號新零件中的一些功能。",
  ui_story_1013_10130201_127_dialog_content = "模擬室似乎進行了自我升級，能夠完全類比真實戰場的情況了！",
  ui_story_1013_10130201_128_dialog_content = "利用戰鬥模擬器，現在就可以進行體驗。",
  ui_story_1013_10130201_129_dialog_content = "我剛才聽說，PlayerName對戰鬥模擬器感興趣？",
  ui_story_1013_10130201_130_dialog_content = "怎麼樣，要試試看嗎？",
  ui_story_1013_10130201_131_option_content = "很難嗎？",
  ui_story_1013_10130201_132_dialog_content = "我才不會故意為難你呢！既然要進行全新的遊戲，那當然會從最簡單的難度開始啦！",
  ui_story_1013_10130201_133_dialog_content = "那就來試試吧！",
  ui_story_1013_10130201_134_option_content = "當然！",
  ui_story_1013_10130201_135_dialog_content = "聽起來就很有趣！",
  ui_story_1013_10130201_136_dialog_content = "那麼，就請PlayerName坐到那邊的椅子上，然後戴好這個頭盔！",
  ui_story_1013_10130201_137_dialog_content = "好的。",
  ui_story_1013_10130201_138_dialog_content = "欸？四周的環境發生變化了？！",
  ui_story_1013_10130201_139_dialog_content = "PlayerName，能聽見嗎？",
  ui_story_1013_10130201_140_dialog_content = "薇絲？！妳在哪裡？",
  ui_story_1013_10130201_141_dialog_content = "我就在你旁邊喔！",
  ui_story_1013_10130201_142_dialog_content = "我能透過這邊的螢幕，看到你看見的畫面。",
  ui_story_1013_10130201_143_dialog_content = "怎麼樣，PlayerName，你看到什麼了？",
  ui_story_1013_10130201_144_dialog_content = "一片空無一物的曠野，有很舒服的陽光和風。",
  ui_story_1013_10130201_145_dialog_content = "那就對了。",
  ui_story_1013_10130201_146_dialog_content = "這個場景是戰鬥模擬器的初始場景哦。",
  ui_story_1013_10130201_147_dialog_content = "PlayerName，接下來請你想像同伴站在你身邊的樣子吧！",
  ui_story_1013_10130201_148_dialog_content = "想像同伴的樣子？",
  ui_story_1013_10130201_149_dialog_content = "沒錯！",
  ui_story_1013_10130201_150_dialog_content = "戰鬥模擬器會根據你想像的內容，按照啟光已有的資料在場景中投影出對應的光靈。",
  ui_story_1013_10130201_151_dialog_content = "這些光靈的投影會幫助你完成接下來的戰鬥測試。",
  ui_story_1013_10130201_152_option_content = "想像薇絲的形象",
  ui_story_1013_10130201_153_dialog_content = "嗚哇？！",
  ui_story_1013_10130201_154_dialog_content = "出，出現了！",
  ui_story_1013_10130201_155_dialog_content = "好厲害，真的和我一模一樣！",
  ui_story_1013_10130201_156_dialog_content = "太好了！看起來沒什麼問題。",
  ui_story_1013_10130201_157_dialog_content = "那麼，我來在場景中加入一些暗鬼——",
  ui_story_1013_10130201_158_dialog_content = "嘎嗷！",
  ui_story_1013_10130201_159_dialog_content = "噫！暗鬼也像真的一樣。",
  ui_story_1013_10130201_160_dialog_content = "仿佛能感受到牠們身上的暗能！",
  ui_story_1013_10130201_161_dialog_content = "不用害怕啦，PlayerName。",
  ui_story_1013_10130201_162_dialog_content = "這只是最基礎的測試唷！",
  ui_story_1013_10130201_163_dialog_content = "試著用光靈投影，擊敗這些暗鬼吧！",
  ui_story_1013_10130201_164_dialog_content = "加油，PlayerName！",
  ui_story_1013_10130201_165_dialog_content = "好，我會努力的！",
  ui_story_1013_10130201_166_dialog_content = "已選擇難度：簡單。",
  ui_story_1013_10130201_167_dialog_content = "預設模式，關卡編號：01。",
  ui_story_1013_10130201_168_dialog_content = "關卡目標：消滅所有暗鬼。",
  ui_story_1013_10130201_169_dialog_content = "戰場模擬器，開始執行關卡。",
  ui_story_1013_10130201_170_dialog_content = "<anim type=Shake><size=50>吼！！！</size></anim>",
  ui_story_1013_10130302_1_dialog_content = "呼，呼......暗鬼，全都打敗了！",
  ui_story_1013_10130302_2_dialog_content = "已達成關卡目標。",
  ui_story_1013_10130302_3_dialog_content = "測試結束。關卡評分：A。",
  ui_story_1013_10130302_4_dialog_content = "真厲害啊，PlayerName！你第一次使用戰鬥模擬器就獲得了A的成績！",
  ui_story_1013_10130302_5_dialog_content = "稍等，我先把你和模擬器之間的連結斷開，然後就可以摘掉頭盔了。",
  ui_story_1013_10130302_6_dialog_content = "已斷開連結，可以安全退出。",
  ui_story_1013_10130302_7_dialog_content = "唔......",
  ui_story_1013_10130302_8_dialog_content = "PlayerName，感覺怎麼樣？有沒有不舒服？",
  ui_story_1013_10130302_9_dialog_content = "還好，只是覺得仿佛真的和暗鬼戰鬥了一場，身心俱疲呢。",
  ui_story_1013_10130302_10_dialog_content = "哈哈哈，辛苦你了，PlayerName。",
  ui_story_1013_10130302_11_dialog_content = "不過，這也恰恰證明了這項技術的優點。",
  ui_story_1013_10130302_12_dialog_content = "只是借用臨空者號模擬室的部分功能，就能完美模擬戰場的實際情況。",
  ui_story_1013_10130302_13_dialog_content = "這可比停留於理論教學和兵棋推演的枯燥教學要強多了！",
  ui_story_1013_10130302_14_dialog_content = "這麼一說，我也很想試試看！",
  ui_story_1013_10130302_15_dialog_content = "現在還不行啦。",
  ui_story_1013_10130302_16_dialog_content = "畢竟這是空裔的技術，目前只能由PlayerName來進行測試。",
  ui_story_1013_10130302_17_dialog_content = "等我們完全解析了這項技術的原理，就可以把它改造成光靈也能使用的設備！",
  ui_story_1013_10130302_18_dialog_content = "現在將戰鬥模擬器的研究列為首要任務的話，能趕得上聯合軍演嗎？",
  ui_story_1013_10130302_19_dialog_content = "如果能把這項技術應用於演習中，想必能吸引很多人吧！",
  ui_story_1013_10130302_20_dialog_content = "有PlayerName進行協助的話，應該沒有問題！",
  ui_story_1013_10130302_21_dialog_content = "聯合軍演？那是什麼？",
  ui_story_1013_10130302_22_dialog_content = "是兩年一度的演習喔！",
  ui_story_1013_10130302_23_dialog_content = "不僅是啟光聯邦，連白夜城、北境甚至影鎮都會參與。",
  ui_story_1013_10130302_24_dialog_content = "不止軍隊間的協同配合，聯合軍演的各方還會派出最優秀的年輕人進行個人項目比拼。",
  ui_story_1013_10130302_25_dialog_content = "在演習的最後，參與演習的各位會真正走上戰場，與暗鬼對抗。",
  ui_story_1013_10130302_26_dialog_content = "聽起來會有很多人參加啊......",
  ui_story_1013_10130302_27_dialog_content = "那當然了！",
  ui_story_1013_10130302_28_dialog_content = "大家努力爭奪個人比拼的第一名。",
  ui_story_1013_10130302_29_dialog_content = "獲勝者有機會和萊因哈特大元帥進行一對一的切磋哦！",
  ui_story_1013_10130302_30_dialog_content = "欸？！",
  ui_story_1013_10130302_31_dialog_content = "最初明明只是一時興起問了一句當時的優勝者要不要切磋一番。",
  ui_story_1013_10130302_32_dialog_content = "但是後來似乎發展成了約定俗成的項目呢。",
  ui_story_1013_10130302_33_dialog_content = "不過，我並不討厭這種切磋。",
  ui_story_1013_10130302_34_option_content = "不會覺得麻煩嗎？",
  ui_story_1013_10130302_35_dialog_content = "當然不會！倒不如說，非常期待！",
  ui_story_1013_10130302_36_option_content = "不愧是妳",
  ui_story_1013_10130302_37_dialog_content = "哈哈哈哈哈，感謝誇獎。",
  ui_story_1013_10130302_38_dialog_content = "能有機會與年輕人中的最強者交手，對我來說是一件值得高興的事。",
  ui_story_1013_10130302_39_dialog_content = "親眼看著後輩慢慢成長、一步步變強......",
  ui_story_1013_10130302_40_dialog_content = "最終，他們會超越我們，成為新時代的引領者。",
  ui_story_1013_10130302_41_dialog_content = "只是想想，就讓我激動不已。",
  ui_story_1013_10130302_42_dialog_content = "萊因哈特都和誰交手過呢？",
  ui_story_1013_10130302_43_dialog_content = "如果是說個人比拼的優勝者，上一屆是卡蓮喔！",
  ui_story_1013_10130302_44_dialog_content = "她的得分可是一口氣超過第二名十幾分呢！",
  ui_story_1013_10130302_45_dialog_content = "嗯，卡蓮確實是新一輩中難得的強者。",
  ui_story_1013_10130302_46_dialog_content = "上次交手過後，她還說下一次也要拿到個人比拼的第一名。",
  ui_story_1013_10130302_47_dialog_content = "等到那個時候，她會強到足夠打敗我。",
  ui_story_1013_10130302_48_dialog_content = "哈哈哈，真期待啊。",
  ui_story_1013_10130302_49_dialog_content = "真羡慕啊......",
  ui_story_1013_10130302_50_dialog_content = "我也想和大元帥切磋一下，一定能獲得不少指點！",
  ui_story_1013_10130302_51_dialog_content = "那就努力磨練自己，拿到個人比拼的第一名吧。",
  ui_story_1013_10130302_52_dialog_content = "嗯！",
  ui_story_1013_10130302_53_dialog_content = "你也是，PlayerName！",
  ui_story_1013_10130302_54_dialog_content = "還有我嗎？！",
  ui_story_1013_10130302_55_dialog_content = "當然，聯合軍演的參與者可不只限於光靈。",
  ui_story_1013_10130302_56_dialog_content = "當空裔一族還活躍在艾斯特拉大陸的時候，也會與光靈共同作戰。",
  ui_story_1013_10130302_57_dialog_content = "如果你能參與進來的話，對於聯合軍演來說，就是空裔一族的回歸。",
  ui_story_1013_10130302_58_dialog_content = "「回歸」嗎......",
  ui_story_1013_10130302_59_dialog_content = "要是你取得了第一名，我也會和你切磋一番的。",
  ui_story_1013_10130302_60_dialog_content = "不......不必了！",
  ui_story_1013_10130302_61_dialog_content = "和妳打的話，我恐怕連逃命的機會都沒有......",
  ui_story_1013_10130302_62_dialog_content = "那麼，換成兵棋推演怎麼樣？",
  ui_story_1013_10130302_63_dialog_content = "如果是兵棋推演的話，沒問題！",
  ui_story_1013_10130302_64_dialog_content = "好，那我等著你在個人比拼上奪冠！",
  ui_story_1013_10130302_65_dialog_content = "很抱歉要打擾一下你們的談話了。",
  ui_story_1013_10130302_66_dialog_content = "今天的測試已經全部完成了唷！",
  ui_story_1013_10130302_67_dialog_content = "我和我的助手正在按照結果調整戰鬥模擬器，預計明天可以開始下一項測試。",
  ui_story_1013_10130302_68_dialog_content = "剩下的工作，就放心地交給我們吧！",
  ui_story_1013_10130302_69_dialog_content = "還有下一項測試嗎？",
  ui_story_1013_10130302_70_dialog_content = "當然了，今天只是最基本的嘗試。",
  ui_story_1013_10130302_71_dialog_content = "戰鬥模擬器還有很多功能等待開發呢！",
  ui_story_1013_10130302_72_dialog_content = "可是，維修臨空者號的事情......",
  ui_story_1013_10130302_73_dialog_content = "放心吧，我們不會忘記這件事的。",
  ui_story_1013_10130302_74_dialog_content = "維修臨空者號和研究戰鬥模擬器，這兩項工作是同時進行的！",
  ui_story_1013_10130302_75_dialog_content = "但是，就算是我們也需要一些時間。",
  ui_story_1013_10130302_76_dialog_content = "所以請你耐心等待一下，好好放鬆休息吧。",
  ui_story_1013_10130302_77_dialog_content = "那就只好耐心等待了。",
  ui_story_1013_10130302_78_dialog_content = "嗯，PlayerName今天就先好好休息吧。",
  ui_story_1013_10130302_79_dialog_content = "接下來的工作，明天繼續！",
  ui_story_1013_10130401_1_dialog_content = "<color=#e8d9bb>咕嚕——</color>",
  ui_story_1013_10130401_2_dialog_content = "餓......",
  ui_story_1013_10130401_3_dialog_content = "<color=#e8d9bb>咕嚕嚕——！</color>",
  ui_story_1013_10130401_4_dialog_content = "肚子，好餓！",
  ui_story_1013_10130401_5_dialog_content = "昨天在研究院做完測試以後，就被薇絲帶到了迦南城裡住下。",
  ui_story_1013_10130401_6_dialog_content = "但是沒想到，今天醒來的時候已經這麼晚了！",
  ui_story_1013_10130401_7_dialog_content = "<color=#e8d9bb>咕嚕咕嚕！</color>",
  ui_story_1013_10130401_8_dialog_content = "不行，要先找點吃的。",
  ui_story_1013_10130401_9_dialog_content = "迦南城裡這麼大，應該會有飯館一類的地方吧？",
  ui_story_1013_10130401_10_dialog_content = "希望不要太貴，我錢包裡的白夜幣已經不多了。",
  ui_story_1013_10130401_11_dialog_content = "沒有。",
  ui_story_1013_10130401_12_dialog_content = "也沒有？",
  ui_story_1013_10130401_13_dialog_content = "怎麼哪裡都沒有啊？！",
  ui_story_1013_10130401_14_dialog_content = "走了一大圈，不僅沒有找到吃的，反而還更餓了。",
  ui_story_1013_10130401_15_dialog_content = "我的眼前已經開始發黑了......",
  ui_story_1013_10130401_16_dialog_content = "好像......聞到了食物的香氣？",
  ui_story_1013_10130401_17_dialog_content = "PlayerName？！",
  ui_story_1013_10130401_18_dialog_content = "醒一醒，PlayerName，別在這裡睡著啊！",
  ui_story_1013_10130401_19_option_content = "薇，薇絲？！",
  ui_story_1013_10130401_20_dialog_content = "你還好嗎？怎麼看起來一副沒有力氣的樣子？",
  ui_story_1013_10130401_21_dialog_content = "我沒事，我只是太餓了，又找不到可以吃飯的地方......",
  ui_story_1013_10130401_22_dialog_content = "在城裡徒勞地走了一大圈，只能回到這裡。",
  ui_story_1013_10130401_23_dialog_content = "抱歉抱歉，是我忘記告訴你了。",
  ui_story_1013_10130401_24_dialog_content = "啟光實行的是配給制，所以迦南城裡沒有飯館一類的地方。",
  ui_story_1013_10130401_25_dialog_content = "外來的人想要獲得物資的話，需要到指定的地點辦理手續才行哦。",
  ui_story_1013_10130401_26_dialog_content = "昨天因為人手都忙著研究，所以忘記申請了......",
  ui_story_1013_10130401_27_dialog_content = "薇薇安長官已經替你把之後的配給都安排好了，等今天忙完，我們一起去取吧！",
  ui_story_1013_10130401_28_dialog_content = "欸？那麼麻煩的嗎？",
  ui_story_1013_10130401_29_dialog_content = "畢竟啟光聯邦的生產力有限，只是讓每個人都能吃上飯就已經很不容易了。",
  ui_story_1013_10130401_30_dialog_content = "使用配給制才能最大程度避免浪費，確保每個人都能獲得足夠的資源。",
  ui_story_1013_10130401_31_dialog_content = "總之，你的早飯我已經幫你拿來了喔！",
  ui_story_1013_10130401_32_dialog_content = "鏘鏘——",
  ui_story_1013_10130401_33_dialog_content = "果然，是食物的香氣！",
  ui_story_1013_10130401_34_dialog_content = "你一定餓壞了吧？快點吃吧！",
  ui_story_1013_10130401_35_dialog_content = "等一下還要繼續去研究院幫忙呢！",
  ui_story_1013_10130401_36_dialog_content = "那我不客氣啦！",
  ui_story_1013_10130401_37_dialog_content = "（只是，沒想到看起來這麼強大的啟光，竟然也會為了資源精打細算。）",
  ui_story_1013_10130401_38_dialog_content = "唔姆唔姆唔姆......",
  ui_story_1013_10130401_39_dialog_content = "啊，果然吃飽了才有活著的感覺！",
  ui_story_1013_10130401_40_dialog_content = "是啊，每次都覺得吃飯的時候最開心了！",
  ui_story_1013_10130401_41_dialog_content = "既然吃飽了，那就應該開始今天的工作了。",
  ui_story_1013_10130401_42_dialog_content = "我記得是要繼續幫忙研究戰鬥模擬器？",
  ui_story_1013_10130401_43_dialog_content = "沒錯。聽那些科學家說，他們昨天連夜開發了新功能哦！",
  ui_story_1013_10130401_44_dialog_content = "一起去看看吧？",
  ui_story_1013_10130401_45_dialog_content = "好！",
  ui_story_1013_10130401_46_dialog_content = "<color=#e8d9bb>啟光研究院</color>",
  ui_story_1013_10130401_47_dialog_content = "早安啊，你們終於來了。",
  ui_story_1013_10130401_48_dialog_content = "大元帥？！",
  ui_story_1013_10130401_49_dialog_content = "難道萊因哈特一直在等我們嗎？",
  ui_story_1013_10130401_50_dialog_content = "嗯，我想親眼看看戰鬥模擬器運行的過程。",
  ui_story_1013_10130401_51_dialog_content = "唷，你們來啦？",
  ui_story_1013_10130401_52_dialog_content = "我們已經升級過戰鬥模擬器了喔！",
  ui_story_1013_10130401_53_dialog_content = "沒錯沒錯，現在它有了全新的名字——戰場模擬器！",
  ui_story_1013_10130401_54_option_content = "「戰場」？",
  ui_story_1013_10130401_55_dialog_content = "別看只差了一個字，實際上的差別可是很大的哦！",
  ui_story_1013_10130401_56_option_content = "有什麼區別嗎？",
  ui_story_1013_10130401_57_dialog_content = "有很大區別哦！",
  ui_story_1013_10130401_58_dialog_content = "戰場模擬器的系統讀取了臨空者號新模組中的資料，並且進行了更新。",
  ui_story_1013_10130401_59_dialog_content = "現在，它能夠根據詳細的戰鬥記錄對過去的某一場戰鬥進行詳細的模擬。",
  ui_story_1013_10130401_60_dialog_content = "不僅僅是敵人，就連當時的時間、環境和天氣都能完美呈現。",
  ui_story_1013_10130401_61_dialog_content = "怎麼樣，很厲害吧？",
  ui_story_1013_10130401_62_dialog_content = "也就是說，戰鬥變得更真實了？",
  ui_story_1013_10130401_63_dialog_content = "理論上是這樣的。",
  ui_story_1013_10130401_64_dialog_content = "不過，因為對戰場模擬器的改造還沒有完成，目前能進行測試的仍然只有你。",
  ui_story_1013_10130401_65_dialog_content = "所以，今天也拜託啦！",
  ui_story_1013_10130401_66_dialog_content = "昨天的戰鬥已經很累人了，希望今天也不要太難。",
  ui_story_1013_10130401_67_dialog_content = "放心吧，我們用的都是之前詳細記錄過的戰鬥資料。",
  ui_story_1013_10130401_68_dialog_content = "以你的能力，一定能順利通過的！",
  ui_story_1013_10130401_69_dialog_content = "PlayerName加油喔，我會在這裡看著你戰鬥的樣子的！",
  ui_story_1013_10130401_70_dialog_content = "好......好的！",
  ui_story_1013_10130401_71_dialog_content = "像昨天那樣，戴上頭盔......",
  ui_story_1013_10130401_72_dialog_content = "看起來和昨天沒什麼差別啊？",
  ui_story_1013_10130401_73_dialog_content = "別著急，我們馬上導入戰鬥資料。",
  ui_story_1013_10130401_74_dialog_content = "我看看，導入哪個好呢？",
  ui_story_1013_10130401_75_dialog_content = "真有意思，就選這個吧。",
  ui_story_1013_10130401_76_dialog_content = "欸？要......要選這個嗎，大元帥？",
  ui_story_1013_10130401_77_dialog_content = "會不會有點太......",
  ui_story_1013_10130401_78_dialog_content = "不必擔心，這在他的能力範圍之內。",
  ui_story_1013_10130401_79_dialog_content = "況且，他對於這種戰鬥情況有經驗，你就相信他吧。",
  ui_story_1013_10130401_80_dialog_content = "是！",
  ui_story_1013_10130401_81_dialog_content = "等一下，萊因哈特？！",
  ui_story_1013_10130401_82_dialog_content = "妳選了什麼啊？！",
  ui_story_1013_10130401_83_dialog_content = "你馬上就知道了。",
  ui_story_1013_10130401_84_dialog_content = "正在讀取戰鬥記錄。",
  ui_story_1013_10130401_85_dialog_content = "已讀取戰役：暗面戰爭。",
  ui_story_1013_10130401_86_dialog_content = "四周的環境真的變成永夜的樣子了！",
  ui_story_1013_10130401_87_dialog_content = "呃......還有這種讓人覺得難受的暗能，竟然也模擬出來了。",
  ui_story_1013_10130401_88_dialog_content = "PlayerName，感覺如何？",
  ui_story_1013_10130401_89_dialog_content = "太真實了吧！",
  ui_story_1013_10130401_90_dialog_content = "不如說甚至有點真實過頭了！",
  ui_story_1013_10130401_91_dialog_content = "感覺就像真正在暗面作戰，連暗能帶來的不適感都一樣！",
  ui_story_1013_10130401_92_dialog_content = "是嗎？那太好了。",
  ui_story_1013_10130401_93_option_content = "究竟哪裡好了？！",
  ui_story_1013_10130401_94_dialog_content = "愈是能真實地模擬出對應的環境，愈說明這台戰場模擬器的性能優異。",
  ui_story_1013_10130401_95_dialog_content = "讓使用者親身感受戰場的嚴酷與慘烈，能給他們最真實的戰鬥體驗。",
  ui_story_1013_10130401_96_dialog_content = "熟悉戰場、在複雜環境下磨煉自身的技巧與策略。",
  ui_story_1013_10130401_97_dialog_content = "等到他們真正走上前線時，傷亡應該也能隨之減少吧。",
  ui_story_1013_10130401_98_dialog_content = "說的也是......",
  ui_story_1013_10130401_99_dialog_content = "就請你作為第一位使用者盡情戰鬥，測試它的各項功能吧！",
  ui_story_1013_10130401_100_dialog_content = "嗯，我知道了。",
  ui_story_1013_10130401_101_dialog_content = "那麼，要開始戰鬥了喔。做好準備吧，PlayerName。",
  ui_story_1013_10130401_102_dialog_content = "戰場類比模式，關卡編號：11328。",
  ui_story_1013_10130401_103_dialog_content = "關卡目標：突破暗鬼包圍圈，或消滅所有暗鬼。",
  ui_story_1013_10130401_104_dialog_content = "戰場模擬器，開始執行關卡。",
  ui_story_1013_10130401_105_dialog_content = "嘎嗷——！",
  ui_story_1013_10130401_106_dialog_content = "放馬過來吧！",
  ui_story_1013_10130502_1_dialog_content = "向後方撤，利用岩石做掩護！",
  ui_story_1013_10130502_2_dialog_content = "......",
  ui_story_1013_10130502_3_dialog_content = "嗷——！",
  ui_story_1013_10130502_4_dialog_content = "吼！！！",
  ui_story_1013_10130502_5_dialog_content = "怎麼這麼多！",
  ui_story_1013_10130502_6_dialog_content = "......！",
  ui_story_1013_10130502_7_dialog_content = "不好，再被打到一次，薇絲就要無法行動了。",
  ui_story_1013_10130502_8_dialog_content = "怎麼辦，這麼多暗鬼，已經完全走投無路了......",
  ui_story_1013_10130502_9_dialog_content = "冷靜下來，冷靜，PlayerName。",
  ui_story_1013_10130502_10_dialog_content = "觀察一下四周，一定有辦法。",
  ui_story_1013_10130502_11_dialog_content = "薇絲，攻擊高處凸起的石頭！",
  ui_story_1013_10130502_12_dialog_content = "是。",
  ui_story_1013_10130502_13_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_1013_10130502_14_dialog_content = "嘎嗷——",
  ui_story_1013_10130502_15_dialog_content = "太好了，落石將暗鬼群撕開了缺口！",
  ui_story_1013_10130502_16_dialog_content = "薇絲，突圍！",
  ui_story_1013_10130502_17_dialog_content = "是。",
  ui_story_1013_10130502_18_dialog_content = "那邊就是突圍的最終目標地點！",
  ui_story_1013_10130502_19_dialog_content = "到了！",
  ui_story_1013_10130502_20_dialog_content = "已達成關卡目標。",
  ui_story_1013_10130502_21_dialog_content = "測試結束。關卡評分：C。",
  ui_story_1013_10130502_22_dialog_content = "呼......呼......",
  ui_story_1013_10130502_23_dialog_content = "已經快要累死了......",
  ui_story_1013_10130502_24_dialog_content = "評分為什麼只有C啊！",
  ui_story_1013_10130502_25_dialog_content = "辛苦你了，PlayerName。",
  ui_story_1013_10130502_26_dialog_content = "稍等，我馬上幫你斷開連結。",
  ui_story_1013_10130502_27_dialog_content = "已斷開連結，可以安全退出。",
  ui_story_1013_10130502_28_dialog_content = "PlayerName，辛苦了！",
  ui_story_1013_10130502_29_dialog_content = "模擬在暗面戰鬥的感覺如何？",
  ui_story_1013_10130502_30_option_content = "好累......",
  ui_story_1013_10130502_31_dialog_content = "明明只是坐在椅子上動都沒有動，但衣服已經被汗水浸透了。",
  ui_story_1013_10130502_32_option_content = "好難......",
  ui_story_1013_10130502_33_dialog_content = "明明已經拼盡全力，使用了我能想到的所有策略......",
  ui_story_1013_10130502_34_dialog_content = "卻只得到了C！",
  ui_story_1013_10130502_35_dialog_content = "PlayerName，你已經很厲害了！",
  ui_story_1013_10130502_36_dialog_content = "沒錯哦，這可是大元帥過去親身經歷的一場戰鬥。",
  ui_story_1013_10130502_37_dialog_content = "在不熟悉的環境下，能夠打出這種成績，已經相當厲害了！",
  ui_story_1013_10130502_38_dialog_content = "這是萊因哈特過去經歷的戰鬥嗎？",
  ui_story_1013_10130502_39_dialog_content = "當年的她戰果是？",
  ui_story_1013_10130502_40_dialog_content = "讓我查一查這場戰鬥的最高紀錄......",
  ui_story_1013_10130502_41_dialog_content = "找到了！最高紀錄是一人擊敗至少50隻暗鬼，以輕傷為代價成功突圍。",
  ui_story_1013_10130502_42_dialog_content = "以戰場模擬器的評分標準，大概能得到A以上的分數吧。",
  ui_story_1013_10130502_43_dialog_content = "好厲害？！",
  ui_story_1013_10130502_44_dialog_content = "在暗面那種環境下，竟然能做到這樣。",
  ui_story_1013_10130502_45_dialog_content = "不愧是大元帥！",
  ui_story_1013_10130502_46_dialog_content = "唉......我只是完成關卡就已經很勉強了。",
  ui_story_1013_10130502_47_dialog_content = "不要小看自己，PlayerName。",
  ui_story_1013_10130502_48_dialog_content = "你這只是第二次在暗面環境下進行作戰，成績已經非常好了。",
  ui_story_1013_10130502_49_dialog_content = "與上一次相比，你更多地考慮到了暗面環境的特性並加以利用。",
  ui_story_1013_10130502_50_dialog_content = "並且，這一次的你不需要支援也能較為順利地完成作戰。",
  ui_story_1013_10130502_51_dialog_content = "進步相當明顯，值得誇獎！",
  ui_story_1013_10130502_52_dialog_content = "謝......謝謝？",
  ui_story_1013_10130502_53_dialog_content = "要是啟光聯邦能多幾個像PlayerName這樣擅長指揮的人才......",
  ui_story_1013_10130502_54_dialog_content = "我們與暗鬼之間的戰鬥應該就能更輕鬆一些吧。",
  ui_story_1013_10130502_55_dialog_content = "這麼說起來，PlayerName與我相遇的時候，好像就已經具備很強的指揮能力了。",
  ui_story_1013_10130502_56_option_content = "是臨空者號的功勞",
  ui_story_1013_10130502_57_option_content = "是從小學習的結果",
  ui_story_1013_10130502_58_dialog_content = "欸？",
  ui_story_1013_10130502_59_dialog_content = "我在地下度過的十七年裡，臨空者號一直在教導我各種知識。",
  ui_story_1013_10130502_60_dialog_content = "其中就包括指揮戰鬥所需要的知識。",
  ui_story_1013_10130502_61_dialog_content = "空裔會教導後代指揮戰鬥的知識......？",
  ui_story_1013_10130502_62_dialog_content = "但是，空裔不是熱愛和平的種族嗎？",
  ui_story_1013_10130502_63_dialog_content = "嗯，這麼一想，那些知識很可能與回歸塔中的資料有著相同的來源吧。",
  ui_story_1013_10130502_64_dialog_content = "我......",
  ui_story_1013_10130502_65_dialog_content = "你在懷疑自己嗎，PlayerName？",
  ui_story_1013_10130502_66_dialog_content = "......不，我已經想通了。",
  ui_story_1013_10130502_67_dialog_content = "哦？",
  ui_story_1013_10130502_68_dialog_content = "不管這些知識從何而來，它們現在都是屬於我的知識。",
  ui_story_1013_10130502_69_dialog_content = "現在的我會用這些知識保護夥伴們，而不是去做壞事。",
  ui_story_1013_10130502_70_dialog_content = "哈哈哈哈，明明只是一段時間沒見，你卻成長了不少啊！",
  ui_story_1013_10130502_71_dialog_content = "有......有嗎？",
  ui_story_1013_10130502_72_dialog_content = "那當然了！",
  ui_story_1013_10130502_73_dialog_content = "上次空之山谷的事情結束時，我感覺你的狀態不太好，還為此擔心了一陣子呢。",
  ui_story_1013_10130502_74_dialog_content = "但是現在看來，這種擔心完全是多餘的。",
  ui_story_1013_10130502_75_dialog_content = "可別把我看扁了！",
  ui_story_1013_10130502_76_dialog_content = "不，當然不會。",
  ui_story_1013_10130502_77_dialog_content = "只是覺得有點可惜，我本來連安慰你的話都準備好了，但現沒想到你已經不需要了。",
  ui_story_1013_10130502_78_dialog_content = "嗯？什麼話？",
  ui_story_1013_10130502_79_dialog_content = "是一句啟光的老話——",
  ui_story_1013_10130502_80_dialog_content = "「科學技術是沒有善惡之分的，但是使用它的光靈有善惡之分。」",
  ui_story_1013_10130502_81_dialog_content = "哈......？",
  ui_story_1013_10130502_82_dialog_content = "很難想像妳會說出這種話。",
  ui_story_1013_10130502_83_dialog_content = "這當然不是我說的，我只是在模仿過去那些老學究對我說過的話而已。",
  ui_story_1013_10130502_84_dialog_content = "果然如此。",
  ui_story_1013_10130502_85_dialog_content = "PlayerName，你能這麼快走出來，我很開心。",
  ui_story_1013_10130502_86_dialog_content = "雖然這次沒幫上你，但如果未來你還需要幫助，就儘管來找我好了。",
  ui_story_1013_10130502_87_dialog_content = "能幫上忙的，我一定盡力。",
  ui_story_1013_10130502_88_dialog_content = "只不過我這個人不太會說話，可能沒辦法給你什麼特別好的建議。",
  ui_story_1013_10130502_89_dialog_content = "就算只有這份心意，我就已經很感動了。",
  ui_story_1013_10130502_90_dialog_content = "唉，不過這樣一想，臨空者號的狀態還真是讓人擔心......",
  ui_story_1013_10130502_91_dialog_content = "是啊，明明我們已經找到了模組，也按照步驟去回歸塔進行了修復。",
  ui_story_1013_10130502_92_dialog_content = "但為什麼臨空者號的意識還沒有恢復呢？",
  ui_story_1013_10130502_93_dialog_content = "這也是沒有辦法的事情。",
  ui_story_1013_10130502_94_dialog_content = "就算是以先進技術著稱的啟光聯邦，對於人工智慧的研究也非常有限哦。",
  ui_story_1013_10130502_95_dialog_content = "更何況巨像的意識與通常的人工智慧還存在著不小的差異。",
  ui_story_1013_10130502_96_dialog_content = "但是，隨著研究的深入，一定會有辦法的！",
  ui_story_1013_10130502_97_dialog_content = "先不說這個了，我有一個好消息，你們要聽聽看嗎？",
  ui_story_1013_10130502_98_dialog_content = "是什麼？",
  ui_story_1013_10130502_99_dialog_content = "我們在臨空者號的新模組中找到了不少戰鬥記錄。",
  ui_story_1013_10130502_100_dialog_content = "這些記錄很可能和巨像與回歸塔一樣古老。",
  ui_story_1013_10130502_101_dialog_content = "等等，不要搶我台詞啊？！",
  ui_story_1013_10130502_102_dialog_content = "我們認為，透過研究這些戰鬥資料，有可能獲得關於巨像的情報。",
  ui_story_1013_10130502_103_dialog_content = "實驗體，你應該也很想修好這座巨像吧？",
  ui_story_1013_10130502_104_dialog_content = "......告訴我該做什麼。",
  ui_story_1013_10130502_105_dialog_content = "我們會將這些古老的資料導入戰場模擬器進行模擬。",
  ui_story_1013_10130502_106_dialog_content = "而你只需要像之前那樣進行模擬戰鬥。",
  ui_story_1013_10130502_107_dialog_content = "我們會在外面觀察，收集必要的資料。",
  ui_story_1013_10130502_108_dialog_content = "當然，我們也會給PlayerName力所能及的幫助和指引！",
  ui_story_1013_10130502_109_dialog_content = "畢竟這一次不是測試能力，而是收集資料。",
  ui_story_1013_10130502_110_dialog_content = "不過，由於戰場模擬器是第一次使用這樣的資料。",
  ui_story_1013_10130502_111_dialog_content = "所以希望你盡可能謹慎地行動哦！",
  ui_story_1013_10130502_112_dialog_content = "我知道了，如果能儘快修好臨空者號，我沒有意見。",
  ui_story_1013_10130502_113_dialog_content = "立刻開始吧。",
  ui_story_1013_10130502_114_dialog_content = "好的。那麼請像之前那樣坐在椅子上，戴好頭盔吧。",
  ui_story_1013_10130601_1_dialog_content = "這是......哪裡？",
  ui_story_1013_10130601_2_dialog_content = "看起來像是城市？",
  ui_story_1013_10130601_3_dialog_content = "怎麼不是那片熟悉的曠野？",
  ui_story_1013_10130601_4_dialog_content = "真奇怪。",
  ui_story_1013_10130601_5_dialog_content = "喂！薇絲，萊因哈特，聽得見嗎？",
  ui_story_1013_10130601_6_dialog_content = "......",
  ui_story_1013_10130601_7_dialog_content = "怎麼沒有回應？",
  ui_story_1013_10130601_8_dialog_content = "難不成戰場模擬器出現故障了？",
  ui_story_1013_10130601_9_dialog_content = "<color=#e8d9bb>戰場模擬器外部</color>",
  ui_story_1013_10130601_10_dialog_content = "PlayerName？",
  ui_story_1013_10130601_11_dialog_content = "喂，PlayerName！聽得見嗎？",
  ui_story_1013_10130601_12_dialog_content = "怎麼回事，聯絡斷開了嗎？",
  ui_story_1013_10130601_13_dialog_content = "非常抱歉，我們也不太清楚是怎麼回事！",
  ui_story_1013_10130601_14_dialog_content = "戰場模擬器並沒有報告任何錯誤，我們也能觀察到PlayerName看見的景象。",
  ui_story_1013_10130601_15_dialog_content = "但我們與PlayerName之間的聯繫卻被切斷了。",
  ui_story_1013_10130601_16_dialog_content = "原因不明！",
  ui_story_1013_10130601_17_dialog_content = "斷開PlayerName與戰場模擬器的連結，快！",
  ui_story_1013_10130601_18_dialog_content = "我們不能讓他處於危險中！",
  ui_story_1013_10130601_19_dialog_content = "是，是！",
  ui_story_1013_10130601_20_dialog_content = "欸？",
  ui_story_1013_10130601_21_dialog_content = "為什麼，無法斷開連結？",
  ui_story_1013_10130601_22_dialog_content = "這又是怎麼回事？",
  ui_story_1013_10130601_23_dialog_content = "非......非常抱歉，我們暫時無法解釋原因！",
  ui_story_1013_10130601_24_dialog_content = "PlayerName......不會有事吧？",
  ui_story_1013_10130601_25_dialog_content = "為什麼戰場模擬器突然出現了這種故障？",
  ui_story_1013_10130601_26_dialog_content = "報告，戰場模擬器之前並沒有出現過類似的問題！",
  ui_story_1013_10130601_27_dialog_content = "有可能是因為使用了臨空者號中的戰鬥資料，才出現了這種情況。",
  ui_story_1013_10130601_28_dialog_content = "能不能摘掉頭盔，把他強行拉出來？",
  ui_story_1013_10130601_29_dialog_content = "最好不要那樣做哦，大元帥。",
  ui_story_1013_10130601_30_dialog_content = "咦？妳不是在研究醫療裝置嗎？怎麼跑這裡來了？",
  ui_story_1013_10130601_31_dialog_content = "你們需要一個對生物學有研究的人來協助你們判斷這個年輕人的狀態，所以我來了。",
  ui_story_1013_10130601_32_dialog_content = "也對！PlayerName現在的情況究竟怎麼樣了？",
  ui_story_1013_10130601_33_dialog_content = "在對他進行徹底研究之前，我也說不好他現在的狀態。",
  ui_story_1013_10130601_34_dialog_content = "不過，我能確定他的情況並不樂觀，因為戰場模擬器在運行中與實驗體的意識是相互連結的。",
  ui_story_1013_10130601_35_dialog_content = "如果強行斷開連結，年輕人的後半輩子大概就得在病床上度過了。",
  ui_story_1013_10130601_36_dialog_content = "怎麼可以這樣......",
  ui_story_1013_10130601_37_dialog_content = "不過，讓那個年輕人一直被困在裡面也不是辦法。",
  ui_story_1013_10130601_38_dialog_content = "我們能從外面為他提供幫助嗎？",
  ui_story_1013_10130601_39_dialog_content = "冷靜，薇絲中尉。",
  ui_story_1013_10130601_40_dialog_content = "妳現在唯一能做的，是不要干擾我們尋找救助實驗體的方法。",
  ui_story_1013_10130601_41_dialog_content = "繼續尋找救助PlayerName的辦法。",
  ui_story_1013_10130601_42_dialog_content = "儘快讓他與戰場模擬器斷開連結。",
  ui_story_1013_10130601_43_dialog_content = "<color=#e8d9bb>戰場模擬器內部</color>",
  ui_story_1013_10130601_44_dialog_content = "這到底是怎麼回事？！",
  ui_story_1013_10130601_45_dialog_content = "既聯繫不上外面的研究員們，也沒有聽見關卡開始的提示音。",
  ui_story_1013_10130601_46_dialog_content = "這裡看起來既不像啟光也不像白夜城......",
  ui_story_1013_10130601_47_dialog_content = "我記得那些科學家說，這次使用的戰鬥資料來自臨空者號的新模組。",
  ui_story_1013_10130601_48_dialog_content = "難道說，我現在看到的——",
  ui_story_1013_10130601_49_option_content = "是遠古時代的城市？！",
  ui_story_1013_10130601_50_dialog_content = "跑——",
  ui_story_1013_10130601_51_dialog_content = "欸？好像有人在向著這邊跑來？",
  ui_story_1013_10130601_52_dialog_content = "快跑，千萬別被追上！",
  ui_story_1013_10130601_53_dialog_content = "等一下，請問，出了什麼事？",
  ui_story_1013_10130601_54_dialog_content = "啊！牠們來了！",
  ui_story_1013_10130601_55_dialog_content = "誰來了啊？到底是怎麼回事？",
  ui_story_1013_10130601_56_dialog_content = "等等，這是暗能的氣息？！",
  ui_story_1013_10130601_57_dialog_content = "嘎吼——！！！",
  ui_story_1013_10130601_58_dialog_content = "噫？！薇絲！",
  ui_story_1013_10130601_59_dialog_content = "......",
  ui_story_1013_10130601_60_dialog_content = "還好，下意識地想像出了薇絲的形象......",
  ui_story_1013_10130601_61_dialog_content = "保護平民，維持陣型！",
  ui_story_1013_10130601_62_dialog_content = "不要害怕那些暗鬼，牠們沒什麼可怕的！",
  ui_story_1013_10130601_63_dialog_content = "拿起你們的武器，跟緊我！！！",
  ui_story_1013_10130601_64_dialog_content = "衝啊！！！",
  ui_story_1013_10130601_65_dialog_content = "嗷！！！",
  ui_story_1013_10130601_66_dialog_content = "那些是光靈嗎？他們在用光能術與暗鬼戰鬥......",
  ui_story_1013_10130601_67_dialog_content = "但是，好弱？！",
  ui_story_1013_10130601_68_dialog_content = "幾乎沒有對暗鬼造成什麼傷害！",
  ui_story_1013_10130601_69_dialog_content = "吼！",
  ui_story_1013_10130601_70_dialog_content = "呃啊！",
  ui_story_1013_10130601_71_option_content = "快後退！",
  ui_story_1013_10130601_72_dialog_content = "你們打不過那些暗鬼的！",
  ui_story_1013_10130601_73_dialog_content = "我們已經沒有可以後退的餘地了。",
  ui_story_1013_10130601_74_dialog_content = "背後......就是家園！",
  ui_story_1013_10130601_75_dialog_content = "喂！快撤退，你們會死的！",
  ui_story_1013_10130601_76_dialog_content = "衝啊！！！",
  ui_story_1013_10130601_77_dialog_content = "吼！！！",
  ui_story_1013_10130601_78_dialog_content = "薇絲，幫助他們！",
  ui_story_1013_10130601_79_dialog_content = "是。",
  ui_story_1013_10130602_1_dialog_content = "<color=#e8d9bb>戰場模擬器外部</color>",
  ui_story_1013_10130602_2_dialog_content = "PlayerName的情況怎麼樣了？",
  ui_story_1013_10130602_3_dialog_content = "報告，還在解析中！",
  ui_story_1013_10130602_4_dialog_content = "實驗體目前還處於穩定狀態，並且已經發現了戰場模擬器的異常。",
  ui_story_1013_10130602_5_dialog_content = "他正在努力與暗鬼戰鬥，為我們爭取時間！",
  ui_story_1013_10130602_6_dialog_content = "PlayerName果然也在用自己的方式幫忙！",
  ui_story_1013_10130602_7_dialog_content = "不要辜負他的努力，繼續解析！",
  ui_story_1013_10130602_8_dialog_content = "是！",
  ui_story_1013_10130602_9_dialog_content = "大元帥，對戰鬥資料的分析已經有了一些結果。",
  ui_story_1013_10130602_10_dialog_content = "說。",
  ui_story_1013_10130602_11_dialog_content = "我們分析了戰鬥模擬器模擬出的場景。",
  ui_story_1013_10130602_12_dialog_content = "發現這些建築的特徵與現代光靈的建築都不相符。",
  ui_story_1013_10130602_13_dialog_content = "但是，這些場景與希諾普研究員曾經發現的一座地下城中的遠古建築十分相似。",
  ui_story_1013_10130602_14_dialog_content = "所以我們推斷，這些戰鬥資料很可能比光靈更加古老。",
  ui_story_1013_10130602_15_dialog_content = "有可能屬於那段已經遺失的歷史。",
  ui_story_1013_10130602_16_dialog_content = "遠古時代的歷史嗎......",
  ui_story_1013_10130602_17_dialog_content = "繼續記錄。",
  ui_story_1013_10130602_18_dialog_content = "戰場模擬器中的這些資料，很可能是真正遠古歷史的一部分。",
  ui_story_1013_10130602_19_dialog_content = "注意觀察PlayerName所處的環境，或許能從中找出把他救出來的方法！",
  ui_story_1013_10130602_20_dialog_content = "<color=#e8d9bb>戰場模擬器內部</color>",
  ui_story_1013_10130602_21_dialog_content = "為什麼會這樣，關卡還沒有開始，暗鬼就已經出現了......",
  ui_story_1013_10130602_22_dialog_content = "這一切都不對勁，戰場模擬器很可能出現了問題。",
  ui_story_1013_10130602_23_dialog_content = "吼——！",
  ui_story_1013_10130602_24_dialog_content = "......",
  ui_story_1013_10130602_25_dialog_content = "沒完沒了的，什麼時候才能是個頭！",
  ui_story_1013_10130602_26_dialog_content = "現在這裡只有我一個人和想像出來的光靈投影。",
  ui_story_1013_10130602_27_dialog_content = "聽不見夥伴的回應，連臨空者號都不在我身邊。",
  ui_story_1013_10130602_28_dialog_content = "也不知道究竟要做些什麼才能擺脫這種奇怪的狀態......",
  ui_story_1013_10130602_29_dialog_content = "如果什麼都不做，主動被暗鬼擊敗，會被判定為失敗並退出戰場模擬器嗎？",
  ui_story_1013_10130602_30_dialog_content = "不過，由於戰場模擬器是第一次使用這樣的資料。",
  ui_story_1013_10130602_31_dialog_content = "所以希望你盡可能謹慎地行動哦！",
  ui_story_1013_10130602_32_dialog_content = "不行，不可以魯莽地行動。",
  ui_story_1013_10130602_33_dialog_content = "現在戰場模擬器的狀態不對勁，一切行動導致的後果都是未知的。",
  ui_story_1013_10130602_34_dialog_content = "並且......我也不是隻身一人！",
  ui_story_1013_10130602_35_dialog_content = "薇絲他們一定也注意到了戰場模擬器的異常，正在想辦法解決。",
  ui_story_1013_10130602_36_dialog_content = "<color=#e8d9bb>轟隆！</color>",
  ui_story_1013_10130602_37_dialog_content = "發生什麼了？！",
  ui_story_1013_10130602_38_dialog_content = "<color=#e8d9bb>轟隆！！！</color>",
  ui_story_1013_10130602_39_dialog_content = "地......地震？",
  ui_story_1013_10130602_40_dialog_content = "不對，整個環境......開始崩塌了？！",
  ui_story_1013_10130602_41_dialog_content = "<color=#e8d9bb>轟隆——！！！</color>",
  ui_story_1013_10130602_42_dialog_content = "撤退！快撤退！！！",
  ui_story_1013_10130602_43_dialog_content = "惡魔來了！！！",
  ui_story_1013_10130602_44_dialog_content = "惡魔？！",
  ui_story_1013_10130602_45_dialog_content = "呃！我的頭，好痛！",
  ui_story_1013_10130602_46_dialog_content = "要......逃離這裡......才......行......",
  ui_story_1013_10130602_47_dialog_content = "PlayerName。",
  ui_story_1013_10130602_48_dialog_content = "醒一醒。",
  ui_story_1013_10130602_49_dialog_content = "還不可以放棄。",
  ui_story_1013_10130602_50_dialog_content = "四周的景色發生了變化？！",
  ui_story_1013_10130602_51_dialog_content = "遠處有好多暗鬼？！",
  ui_story_1013_10130602_52_dialog_content = "天空上的那些陰影是......巨像！",
  ui_story_1013_10130602_53_dialog_content = "巨像載著暗鬼，與光靈們作戰......",
  ui_story_1013_10130602_54_dialog_content = "回歸塔中的記錄，是真的......",
  ui_story_1013_10130602_55_dialog_content = "致全體作戰人員——",
  ui_story_1013_10130602_56_dialog_content = "這是......廣播？",
  ui_story_1013_10130602_57_dialog_content = "請堅守戰線，頑強抵抗。",
  ui_story_1013_10130602_58_dialog_content = "人類必將戰勝惡魔。",
  ui_story_1013_10130602_59_option_content = "「惡魔」?",
  ui_story_1013_10130602_60_dialog_content = "剛才就聽見有人在喊惡魔，那是什麼，難道是指暗鬼嗎？",
  ui_story_1013_10130602_61_option_content = "「人類」?",
  ui_story_1013_10130602_62_dialog_content = "人類是什麼？不應該是光靈嗎？",
  ui_story_1013_10130602_63_dialog_content = "聽到了嗎？我們要堅持住！",
  ui_story_1013_10130602_64_dialog_content = "堅守戰線，保衛家園！！！",
  ui_story_1013_10130602_65_dialog_content = "等一等，不行！你們快回來！",
  ui_story_1013_10130602_66_dialog_content = "你們根本沒有對付暗鬼的力量，去了只會送死！",
  ui_story_1013_10130602_67_dialog_content = "如果你不戰鬥，就不要擋路！",
  ui_story_1013_10130602_68_dialog_content = "衝啊！擊退暗鬼！擊退惡魔！",
  ui_story_1013_10130602_69_dialog_content = "堅守陣線，不要後退。",
  ui_story_1013_10130602_70_dialog_content = "人類必將勝利。",
  ui_story_1013_10130602_71_dialog_content = "吼！！！",
  ui_story_1013_10130602_72_dialog_content = "呃......！",
  ui_story_1013_10130602_73_dialog_content = "不能......退縮！",
  ui_story_1013_10130602_74_dialog_content = "停下啊！",
  ui_story_1013_10130602_75_dialog_content = "繼續戰鬥，繼續堅持。",
  ui_story_1013_10130602_76_dialog_content = "這個廣播到底要幹什麼？為什麼能這麼輕鬆地說出讓人去死的話啊！",
  ui_story_1013_10130602_77_dialog_content = "<color=#e8d9bb>嘶啦——</color>",
  ui_story_1013_10130602_78_dialog_content = "正......讀取......記錄。",
  ui_story_1013_10130602_79_dialog_content = "是戰場模擬器的系統提示音？！",
  ui_story_1013_10130602_80_dialog_content = "難道恢復了嗎？",
  ui_story_1013_10130602_81_dialog_content = "......戰役：......降臨。",
  ui_story_1013_10130602_82_dialog_content = "戰役......編號：錯誤。",
  ui_story_1013_10130602_83_dialog_content = "......目標：撤退......安全地帶。",
  ui_story_1013_10130602_84_dialog_content = "撤退，事到如今到處都是暗鬼，還能向哪裡退呢？",
  ui_story_1013_10130602_85_dialog_content = "喂，你！",
  ui_story_1013_10130602_86_dialog_content = "往後方跑，那裡有安全區！到了那裡你就安全了，士兵們會保護你的。",
  ui_story_1013_10130602_87_dialog_content = "不要放棄，人類一定會戰勝惡魔！",
  ui_story_1013_10130602_88_dialog_content = "後方......只要背對著暗鬼來的方向跑就行了嗎？",
  ui_story_1013_10130602_89_dialog_content = "戰場模擬器的場景太過真實，以至於我差點都忘了......",
  ui_story_1013_10130602_90_dialog_content = "現在看到的一切都只是對過去的記錄。",
  ui_story_1013_10130602_91_dialog_content = "不管做什麼，我都無法改變既定的事實。",
  ui_story_1013_10130602_92_dialog_content = "我現在能做的，就是儘快完成關卡，讓這一切結束。",
  ui_story_1013_10130602_93_dialog_content = "戰場模擬器，開始執行關卡。",
  ui_story_1013_10130701_1_dialog_content = "呼、呼......",
  ui_story_1013_10130701_2_dialog_content = "（雖然不知道應該往哪裡撤退......）",
  ui_story_1013_10130701_3_dialog_content = "（但跟著這群士兵總歸是沒錯的！）",
  ui_story_1013_10130701_4_dialog_content = "喂，那邊那幾個！躲到這個掩體下面來！",
  ui_story_1013_10130701_5_dialog_content = "好......好的！",
  ui_story_1013_10130701_6_dialog_content = "咦？",
  ui_story_1013_10130701_7_dialog_content = "（前面好像有幾個待在原地不動的人。）",
  ui_story_1013_10130701_8_dialog_content = "（他們......受傷了嗎？）",
  ui_story_1013_10130701_9_dialog_content = "重複一遍，請繼續戰鬥，繼續堅持。",
  ui_story_1013_10130701_10_dialog_content = "請問——有人受傷嗎，需要救助嗎？！",
  ui_story_1013_10130701_11_dialog_content = "這裡太危險了，我帶你們轉移到前面的安全地帶！",
  ui_story_1013_10130701_12_dialog_content = "唔，這是......？",
  ui_story_1013_10130701_13_dialog_content = "（籠罩在他們周身的這些奇異虹光，和光能的顏色一模一樣。）",
  ui_story_1013_10130701_14_dialog_content = "（難道他們......是光靈？）",
  ui_story_1013_10130701_15_dialog_content = "光之神未曾應許白夜長明，生命無痛苦，長安無虞。",
  ui_story_1013_10130701_16_dialog_content = "光之神未曾應許長日無盡，世界無戰爭，久居太平。",
  ui_story_1013_10130701_17_dialog_content = "光之神卻曾應許我，勇猛有力，智慧有謀，仁愛有義。",
  ui_story_1013_10130701_18_dialog_content = "助我試煉得恩助，否極泰來，智勇兼備，不盡的愛。",
  ui_story_1013_10130701_19_dialog_content = "（他們看起來......像是在祈禱著什麼。）",
  ui_story_1013_10130701_20_dialog_content = "<color=#e8d9bb>轟——砰！！！</color>",
  ui_story_1013_10130701_21_dialog_content = "戰火正在急速蔓延，請各方人員按照指示進行疏散避難。",
  ui_story_1013_10130701_22_dialog_content = "這是最後的警告，請儘快逃離「惡魔」會出現的區域。",
  ui_story_1013_10130701_23_dialog_content = "吼！！！",
  ui_story_1013_10130701_24_dialog_content = "糟了，要趕快......",
  ui_story_1013_10130701_25_dialog_content = "嘎......",
  ui_story_1013_10130701_26_dialog_content = "光明使者從來不會懼怕黑暗。",
  ui_story_1013_10130701_27_dialog_content = "我們待在此地，是為了擊退這些滋生於黑暗中的魔鬼。",
  ui_story_1013_10130701_28_dialog_content = "孩子，快走吧，不要讓牠們波及到你，這裡已經死了太多人了。",
  ui_story_1013_10130701_29_option_content = "不，我可以為你們提供幫助",
  ui_story_1013_10130701_30_dialog_content = "如果你們願意相信我，願意讓我感知你們的意識......",
  ui_story_1013_10130701_31_dialog_content = "我可以發揮指揮光靈的能力，把握住這場戰鬥的勝利！",
  ui_story_1013_10130701_32_option_content = "不，請和我一起離開這裡",
  ui_story_1013_10130701_33_dialog_content = "這場戰爭遠遠不是四個光靈能夠解決的量級。",
  ui_story_1013_10130701_34_dialog_content = "請和我一起去安全的掩體避難吧，這是眼下唯一的辦法。",
  ui_story_1013_10130701_35_dialog_content = "「光靈」？你在說什麼從來沒有聽過的詞......",
  ui_story_1013_10130701_36_dialog_content = "這裡不是小孩子玩鬧的地方，快去避難吧。",
  ui_story_1013_10130701_37_dialog_content = "你明明也是個小孩子啊？！",
  ui_story_1013_10130701_38_dialog_content = "光之使者的年齡不是依靠外表來判斷的。",
  ui_story_1013_10130701_39_dialog_content = "只有對光能進行純熟應用的人，才能在此時站在這裡。",
  ui_story_1013_10130701_40_dialog_content = "在這種時候，我們確實應該<color=#FFB400>認真使用</color>光之神的啟示了。",
  ui_story_1013_10130701_41_dialog_content = "你的意思是......",
  ui_story_1013_10130701_42_dialog_content = "贊成，任何顧慮都已經不能再成為抑制力量的藉口。",
  ui_story_1013_10130701_43_dialog_content = "站遠點，小子，如果你不想被光的巨浪掀翻。",
  ui_story_1013_10130701_44_dialog_content = "......好吧，不這樣做的話，恐怕我們誰都無法甘心。",
  ui_story_1013_10130701_45_dialog_content = "那邊，惡魔從那邊衝過來了。",
  ui_story_1013_10130701_46_dialog_content = "抓住最後這一束光吧。",
  ui_story_1013_10130701_47_dialog_content = "光明歸於我們！",
  ui_story_1013_10130701_48_dialog_content = "好......好濃郁的光能！",
  ui_story_1013_10130701_49_dialog_content = "嘎——",
  ui_story_1013_10130701_50_dialog_content = "啊啊啊啊啊啊啊啊啊！",
  ui_story_1013_10130701_51_dialog_content = "這是......",
  ui_story_1013_10130701_52_dialog_content = "（明明身處勝利的曙光中，我卻看到了噩夢一樣的光景......）",
  ui_story_1013_10130701_53_dialog_content = "（在劇烈的光線中，無論暗鬼還是光靈，都在迅速地死去！）",
  ui_story_1013_10130701_54_dialog_content = "（快要撐不住了......難道......連我也......）",
  ui_story_1013_10130701_55_dialog_content = "<color=#e8d9bb>砰！！！！！</color>",
  ui_story_1013_10130701_56_dialog_content = "呼、呼......",
  ui_story_1013_10130701_57_dialog_content = "嗞啦......嗞......嗞嗞......",
  ui_story_1013_10130701_58_dialog_content = "已經......結束了嗎？",
  ui_story_1013_10130701_59_option_content = "強制感應",
  ui_story_1013_10130701_60_dialog_content = "周圍感受不到一絲暗能，只有死一般的寂靜。",
  ui_story_1013_10130701_61_dialog_content = "這就是上一個世界終結時的樣子嗎......",
  ui_story_1013_10130701_62_dialog_content = "等等？！",
  ui_story_1013_10130701_63_dialog_content = "土裡冒出來了什麼東西？！",
  ui_story_1013_10130701_64_dialog_content = "<color=#e8d9bb>沙——沙——沙——</color>",
  ui_story_1013_10130701_65_dialog_content = "嘶——！！！",
  ui_story_1013_10130701_66_dialog_content = "不好！",
  ui_story_1013_10130701_67_dialog_content = "（牠一直匍匐在地下才逃過了這一劫嗎......）",
  ui_story_1013_10130701_68_dialog_content = "（那就讓我來了結牠吧！）",
  ui_story_1013_10130702_1_dialog_content = "嘶！！！！！！",
  ui_story_1013_10130702_2_dialog_content = "我......打不倒這個傢伙嗎？！",
  ui_story_1013_10130702_3_dialog_content = "牠的身體甚至變得比剛才更長了......",
  ui_story_1013_10130702_4_dialog_content = "暗鬼可沒有這種原地重生的本事，這算是模擬器的故障嗎？",
  ui_story_1013_10130702_5_dialog_content = "哈——",
  ui_story_1013_10130702_6_dialog_content = "無，無論如何都要趕緊聯繫上那幾個研究人員......",
  ui_story_1013_10130702_7_dialog_content = "絕對不能死在這裡！",
  ui_story_1013_10130702_8_dialog_content = "呼叫戰場模擬器研究員，收到請回話！",
  ui_story_1013_10130702_9_dialog_content = "重複，呼叫戰場模擬器研究員，收到請回話！",
  ui_story_1013_10130702_10_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10130702_11_dialog_content = "怎，怎麼辦......",
  ui_story_1013_10130702_12_dialog_content = "現在還能有什麼辦法......",
  ui_story_1013_10130702_13_dialog_content = "<color=#e8d9bb>劈......喀......</color>",
  ui_story_1013_10130702_14_dialog_content = "我真的要......死在這種地方了嗎？",
  ui_story_1013_10130702_15_dialog_content = "我......",
  ui_story_1013_10130702_16_dialog_content = "<color=#e8d9bb>颯——</color>",
  ui_story_1013_10130702_17_dialog_content = "「主控系統自檢......無異常。」",
  ui_story_1013_10130702_18_dialog_content = "「生物模組自檢......無異常。」",
  ui_story_1013_10130702_19_dialog_content = "「維生系統自檢......運行中。目前乘載：1人。」",
  ui_story_1013_10130702_20_dialog_content = "「引擎自檢......無異常。正在啟動......」",
  ui_story_1013_10130702_21_dialog_content = "臨空者號！",
  ui_story_1013_10130702_22_dialog_content = "我在，PlayerName。我一直都在你身邊。",
  ui_story_1013_10130702_23_dialog_content = "記得嗎，「保證PlayerName的生命安全」，這是我的最高優先級任務。",
  ui_story_1013_10130702_24_dialog_content = "雖然眼前的這一切都是虛擬資料......",
  ui_story_1013_10130702_25_dialog_content = "但不能因此就放任你遭受劇烈傷害。",
  ui_story_1013_10130702_26_dialog_content = "嘗試切斷和我的感應，剩下的就相信我吧。",
  ui_story_1013_10130702_27_dialog_content = "「自動駕駛系統已啟用......目標：聯絡外界，返回現實。」",
  ui_story_1013_10130702_28_dialog_content = "唔......",
  ui_story_1013_10130702_29_dialog_content = "成......功了嗎......臨空者號......",
  ui_story_1013_10130702_30_dialog_content = "PlayerName......PlayerName醒了！",
  ui_story_1013_10130702_31_dialog_content = "PlayerName，你終於醒了！",
  ui_story_1013_10130702_32_dialog_content = "年輕人的意識恢復了！保持他的呼吸道暢通。",
  ui_story_1013_10130702_33_dialog_content = "啟用研究院的身體機能檢驗設備。",
  ui_story_1013_10130702_34_dialog_content = "這是要幹什麼......等一下！我沒事，我沒有受到任何傷害！",
  ui_story_1013_10130702_35_dialog_content = "臨空者號呢，他現在怎麼樣？",
  ui_story_1013_10130702_36_dialog_content = "你是否受到傷害，不能只憑你的主觀意識來判斷。",
  ui_story_1013_10130702_37_dialog_content = "檢驗結果出得很快，請稍等五分鐘吧。",
  ui_story_1013_10130702_38_dialog_content = "......你們從來都沒有告訴過我，戰場模擬器會出現這種嚴重故障！",
  ui_story_1013_10130702_39_dialog_content = "雖然我總是愛開解剖你的玩笑，但玩笑和正經事的界限我還是分得清的。",
  ui_story_1013_10130702_40_dialog_content = "年輕人，我們無意對你造成任何傷害，這次事故，研究院會負全責。",
  ui_story_1013_10130702_41_dialog_content = "我會追責此次編寫古戰場資料的研究人員，並重新對模擬器進行測試！",
  ui_story_1013_10130702_42_dialog_content = "另外，把我的命令傳達下去......",
  ui_story_1013_10130702_43_dialog_content = "啟光研究院願意出資，支付PlayerName未來三個月的巨像保養費。",
  ui_story_1013_10130702_44_dialog_content = "PlayerName，你看這樣如何？",
  ui_story_1013_10130702_45_dialog_content = "這，這還差不多......",
  ui_story_1013_10130702_46_dialog_content = "唔，這次故障，主要還是戰場模擬器與巨像連線技術的不成熟導致的。",
  ui_story_1013_10130702_47_dialog_content = "剛才那隻蝕蟲反復重生的場面，就是你陷入了過往故障資料中的表現。",
  ui_story_1013_10130702_48_dialog_content = "果然你們也即時觀測到了那個場景......",
  ui_story_1013_10130702_49_dialog_content = "最後是臨空者號切斷了與模擬器之間的連結，才讓我成功脫離出來的。",
  ui_story_1013_10130702_50_dialog_content = "所以，臨空者號呢？",
  ui_story_1013_10130702_51_dialog_content = "檢驗結果出來了，恭喜你實驗體，你的身體狀況一切正常。",
  ui_story_1013_10130702_52_dialog_content = "......臨空者號到底怎麼樣了？！",
  ui_story_1013_10130702_53_dialog_content = "臨空者號他......",
  ui_story_1013_10130702_54_dialog_content = "他付出了強行斷開連結的代價。",
  ui_story_1013_10130702_55_dialog_content = "他的意識資料滯留在了戰場模擬器的虛擬情境裡。",
  ui_story_1013_10130702_56_dialog_content = "可能對你來說很殘酷，但你要知道，這種情況在研究中是常見現象。",
  ui_story_1013_10130702_57_dialog_content = "牠的意識出現了一點狀況，目前人格正在與記憶剝離。",
  ui_story_1013_10130702_58_dialog_content = "牠的記憶變成了單純的資訊，人格則回退成了空白的狀態。",
  ui_story_1013_10130702_59_dialog_content = "在這個退化完成的瞬間，牠成功讓你回歸現實，但牠的功能也將喪失。",
  ui_story_1013_10130702_60_dialog_content = "！！！",
  ui_story_1013_10130702_61_dialog_content = "什麼意思......退化和喪失是指什麼......",
  ui_story_1013_10130702_62_dialog_content = "就是字面意思。",
  ui_story_1013_10130702_63_dialog_content = "你們把這個稱為「一點狀況」？！",
  ui_story_1013_10130702_64_option_content = "強制感應！",
  ui_story_1013_10130702_65_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10130702_66_option_content = "強制感應！！",
  ui_story_1013_10130702_67_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10130702_68_option_content = "強制感應！！！",
  ui_story_1013_10130702_69_dialog_content = "不要白費力氣了，PlayerName。",
  ui_story_1013_10130702_70_dialog_content = "你暫時沒有辦法控制牠。",
  ui_story_1013_10130702_71_dialog_content = "我們會繼續嘗試修復牠的意識，至少保證牠的各項功能完整運作。",
  ui_story_1013_10130702_72_dialog_content = "至少？",
  ui_story_1013_10130702_73_dialog_content = "他沒有了人格和記憶，怎麼能算「完整運作」？！",
  ui_story_1013_10130702_74_dialog_content = "這到底是怎麼回事？你們不是要為PlayerName負全責嗎？！",
  ui_story_1013_10130702_75_dialog_content = "是，大元帥，研究院會對巨像意識的修復工作負責到底。",
  ui_story_1013_10130702_76_dialog_content = "但是，實驗體，記住不要和科技交朋友，科技只是服務於研究的工具。",
  ui_story_1013_10130702_77_dialog_content = "巨像的人格崩潰可能會對系統的穩定性造成衝擊......",
  ui_story_1013_10130702_78_dialog_content = "可如果牠的運作一切正常，那麼人格沉睡或逐漸消解也無不可。",
  ui_story_1013_10130702_79_dialog_content = "你們不要碰他，他是我的朋友，我的老師，我唯一的家人！",
  ui_story_1013_10130702_80_dialog_content = "冷靜，PlayerName，我們的修復工作保證不會對牠造成任何傷害。",
  ui_story_1013_10130702_81_dialog_content = "你們現在就是在傷害他！",
  ui_story_1013_10130702_82_dialog_content = "<color=#e8d9bb>咚、咚</color>",
  ui_story_1013_10130702_83_dialog_content = "研究室是肅靜之地，請不要大聲喧嘩。",
  ui_story_1013_10130702_84_dialog_content = "唔......？",
  ui_story_1013_10130702_85_dialog_content = "大元帥，<color=#FFB400>科學首席議會</color>情報官鶯歌報到。",
  ui_story_1013_10130702_86_dialog_content = "科學首席議會？看來他們又祕密地找到了幾個不錯的人才。",
  ui_story_1013_10130702_87_dialog_content = "是的，大元帥，您應該是第一次見到我。",
  ui_story_1013_10130702_88_dialog_content = "不過，我已經對您很熟悉了。",
  ui_story_1013_10130702_89_dialog_content = "哈哈，每一個啟光人民都對我很熟悉。",
  ui_story_1013_10130702_90_dialog_content = "科學首席議會派妳過來做什麼，他們也要研究空裔？",
  ui_story_1013_10130702_91_dialog_content = "科學首席議會即將召開祕密座談會，我只是負責傳達指令。",
  ui_story_1013_10130702_92_dialog_content = "呵呵，他們這群悶頭搞研究的老傢伙，終於也捨得露面了？",
  ui_story_1013_10130702_93_dialog_content = "科學首席議會這次確實抱著十分的誠意，要求直接與空裔進行面對面溝通。",
  ui_story_1013_10130702_94_dialog_content = "越過我？",
  ui_story_1013_10130702_95_dialog_content = "當然，大元帥可以參會。",
  ui_story_1013_10130702_96_dialog_content = "這不是妥協，而是一道命令：請萊因哈特元帥務必和空裔一同出席。",
  ui_story_1013_10130702_97_dialog_content = "我更加沒有拒絕的權利了吧？",
  ui_story_1013_10130702_98_dialog_content = "可是，臨空者號他......",
  ui_story_1013_10130702_99_dialog_content = "在你返回前，我和貢露會命令研究院暫停對巨像的一切分析。",
  ui_story_1013_10130702_100_dialog_content = "放心喔，我會在這裡好好盯著的！",
  ui_story_1013_10130702_101_dialog_content = "安心吧，PlayerName，眼下還不是全無辦法的時候。",
  ui_story_1013_10130702_102_dialog_content = "說不定在科學首席議會那裡，你能得到一些關於臨空者號的新指導。",
  ui_story_1013_10130702_103_dialog_content = "......我明白了。",
  ui_story_1013_10130702_104_dialog_content = "關於我在戰場模擬器中看到的古戰場歷史，我也有幾個問題要問。",
  ui_story_1013_10130702_105_dialog_content = "感謝二位的配合。對於你的問題，相信科學首席議會將毫無保留地解答。",
  ui_story_1013_10130702_106_dialog_content = "那麼，請跟我來吧。",
  ui_story_1013_10130801_1_dialog_content = "科學首席議會？",
  ui_story_1013_10130801_2_dialog_content = "是的，他們直接隸屬於啟光最高權利機關......",
  ui_story_1013_10130801_3_dialog_content = "他們的核心成員分散在啟光各處，是個不到關鍵時刻不輕易啟用的祕密機構。",
  ui_story_1013_10130801_4_dialog_content = "雖然這麼說有點唬人，但他們每個人確實都代表著啟光的最高機密。",
  ui_story_1013_10130801_5_dialog_content = "在各種非正式的場合，也會注意隱藏身分。",
  ui_story_1013_10130801_6_dialog_content = "這群人上一次露面，還是為軍事力量機關的換代而投出選票的時候。",
  ui_story_1013_10130801_7_dialog_content = "那不就是......",
  ui_story_1013_10130801_8_dialog_content = "沒錯，也就是我上任的那年。",
  ui_story_1013_10130801_9_dialog_content = "還真是神祕呢，難怪從來沒有聽誰提起過。",
  ui_story_1013_10130801_10_dialog_content = "麻煩二位走快一點。",
  ui_story_1013_10130801_11_dialog_content = "哈哈哈哈，聽見了嗎PlayerName？我們快點跟上她吧。",
  ui_story_1013_10130801_12_dialog_content = "（真厲害啊，僅僅是他們的一個情報官就可以對大元帥下達命令。）",
  ui_story_1013_10130801_13_dialog_content = "你看起來還是有點緊張呀，PlayerName。",
  ui_story_1013_10130801_14_dialog_content = "與其說是緊張，不如說有點戒備吧。",
  ui_story_1013_10130801_15_dialog_content = "聽了妳的描述，我更加不明白了，他們為什麼突然希望和我會面？",
  ui_story_1013_10130801_16_dialog_content = "是因為薇絲和巴頓的事情嗎，還是為了回歸塔的處理結果......",
  ui_story_1013_10130801_17_dialog_content = "像你這麼猜下去只會給自己徒增煩惱。",
  ui_story_1013_10130801_18_dialog_content = "雖然他們手上確實握著不少實權，但並不是喜歡做表面功夫的人。",
  ui_story_1013_10130801_19_dialog_content = "他們既然主動邀你赴座談會，就一定會與你積極溝通，爭取你的信任。",
  ui_story_1013_10130801_20_dialog_content = "況且，這群人表面負責啟光內部的知識管控，實際上就是一群沉迷科學的怪人。",
  ui_story_1013_10130801_21_dialog_content = "或許你在與他們的接觸中，能夠找到讓臨空者號恢復人格的方法呢。",
  ui_story_1013_10130801_22_dialog_content = "——如果我說的這些能讓你放輕鬆一點。",
  ui_story_1013_10130801_23_dialog_content = "......謝謝妳，萊因哈特。",
  ui_story_1013_10130801_24_dialog_content = "辛苦二位，我們已經到了。",
  ui_story_1013_10130801_25_dialog_content = "請在入口這裡登記二位的基本資訊。",
  ui_story_1013_10130801_26_dialog_content = "資訊只會用作出入記錄，請不必有過多的顧慮。",
  ui_story_1013_10130801_27_dialog_content = "（竟然要保密到這種程度......）",
  ui_story_1013_10130801_28_dialog_content = "<color=#e8d9bb>滴——滴！</color>",
  ui_story_1013_10130801_29_dialog_content = "我已經輸入好門禁密鑰了，裡面請。",
  ui_story_1013_10130801_30_dialog_content = "為什麼不邀請研究院或黑傘實驗室的人，哪怕是邀請薇絲中尉？",
  ui_story_1013_10130801_31_dialog_content = "空裔的立場尚未明確，且只有他才擁有對遠古科技近乎天才的感應方法。",
  ui_story_1013_10130801_32_dialog_content = "天才未免有些過譽了，但他確實是目前已知的最後一個血統純正的空裔。",
  ui_story_1013_10130801_33_dialog_content = "在我親眼見識到之前，「感應能力」只能被稱為一門玄學。",
  ui_story_1013_10130801_34_dialog_content = "壞掉的手錶，在一天裡也有兩次是準的。",
  ui_story_1013_10130801_35_dialog_content = "我會持續留意各位的反應。",
  ui_story_1013_10130801_36_dialog_content = "好了，他們要來了。",
  ui_story_1013_10130801_37_dialog_content = "<color=#e8d9bb>咚、咚</color>",
  ui_story_1013_10130801_38_dialog_content = "空之末裔PlayerName先生到了。",
  ui_story_1013_10130801_39_dialog_content = "以及，前來旁聽的萊因哈特元帥。",
  ui_story_1013_10130801_40_dialog_content = "為了啟明之光。",
  ui_story_1013_10130801_41_dialog_content = "為了啟明之光。",
  ui_story_1013_10130801_42_dialog_content = "PlayerName，你就坐在我旁邊吧。",
  ui_story_1013_10130801_43_dialog_content = "請空裔坐在尤利西斯左側的位置——也就是這塊螢幕的正對面。",
  ui_story_1013_10130801_44_dialog_content = "至於萊因哈特，就請站在旁邊吧。",
  ui_story_1013_10130801_45_dialog_content = "巴蕾特，妳今天對指揮座位的事務很熱心呢。",
  ui_story_1013_10130801_46_dialog_content = "畢竟這場座談會的參會人數有限，總需要有人來做「後勤工作」。",
  ui_story_1013_10130801_47_dialog_content = "感謝你願意參加此次座談會。",
  ui_story_1013_10130801_48_dialog_content = "對規則的高效遵守將為你我節約很多時間。",
  ui_story_1013_10130801_49_dialog_content = "——無論是明面上的規則，還是那些潛在的規矩。",
  ui_story_1013_10130801_50_dialog_content = "請坐過來吧，空裔。",
  ui_story_1013_10130801_51_dialog_content = "你好，先生。",
  ui_story_1013_10130801_52_dialog_content = "簡單介紹一下。坐在你右側這位是生物學家尤利西斯教授。",
  ui_story_1013_10130801_53_dialog_content = "教授對面這位，是物理學家喬伊斯先生。",
  ui_story_1013_10130801_54_dialog_content = "萊因哈特元帥的旁邊，是工程學家巴蕾特女士。",
  ui_story_1013_10130801_55_dialog_content = "至於......",
  ui_story_1013_10130801_56_dialog_content = "阿爾戈爾女士，請醒一醒......",
  ui_story_1013_10130801_57_dialog_content = "呼哈——失禮了，但我的時間也是很有限的。",
  ui_story_1013_10130801_58_dialog_content = "剛才那段毫無意義的排座位環節，還沒有補充睡眠的優先順序高。",
  ui_story_1013_10130801_59_dialog_content = "喂——",
  ui_story_1013_10130801_60_dialog_content = "我是負責人工智慧領域的阿爾戈爾，我肩上這位機械體的名字是「布林」。",
  ui_story_1013_10130801_61_dialog_content = "只要不把布林吵醒，相信我們可以聊得很愉快，空裔。",
  ui_story_1013_10130801_62_dialog_content = "請，請多關照......",
  ui_story_1013_10130801_63_dialog_content = "沒有異議的話，會議正式開始。",
  ui_story_1013_10130801_64_dialog_content = "在進入正題之前，為了保證溝通順利，可以先集中解答你的疑問。",
  ui_story_1013_10130801_65_dialog_content = "但麻煩把問題控制在三個之內。",
  ui_story_1013_10130801_66_dialog_content = "PlayerName剛結束試用了研究院那邊的戰場模擬器。",
  ui_story_1013_10130801_67_dialog_content = "他正有幾個問題要向你們提問。",
  ui_story_1013_10130801_68_dialog_content = "感謝妳熱心地加入討論，萊因哈特。",
  ui_story_1013_10130801_69_dialog_content = "那麼現在，我可以請空裔發言了嗎。",
  ui_story_1013_10130801_70_dialog_content = "......請。",
  ui_story_1013_10130801_71_option_content = "詢問關於「惡魔」的問題",
  ui_story_1013_10130801_72_dialog_content = "我在模擬器中看到的那些場景......全部都是真實發生過的吧。",
  ui_story_1013_10130801_73_dialog_content = "我看到了遠古時代的光靈使用光能術殊死戰鬥的樣子。",
  ui_story_1013_10130801_74_dialog_content = "那些被稱為「惡魔」的東西究竟是......",
  ui_story_1013_10130801_75_dialog_content = "你看到的那些，全部都是真實的歷史。",
  ui_story_1013_10130801_76_dialog_content = "在光靈和空裔之前，這個大陸上存在著一批更加古老的祖先。",
  ui_story_1013_10130801_77_dialog_content = "他們自稱「人類」，對嗎？",
  ui_story_1013_10130801_78_dialog_content = "沒錯。他們和我們的樣貌相同，同樣會使用科技，且不乏擁有信仰之人。",
  ui_story_1013_10130801_79_dialog_content = "但他們的身上沒有任何特殊能力。",
  ui_story_1013_10130801_80_dialog_content = "（所以......才只能在混亂中匆忙躲避受「惡魔」波及的範圍嗎......）",
  ui_story_1013_10130801_81_dialog_content = "我來用最方便理解的句子說明一下......",
  ui_story_1013_10130801_82_dialog_content = "在遠古的祖先中，天賦異稟的那部分人類進化成了光靈。",
  ui_story_1013_10130801_83_dialog_content = "但另有一部分，被「惡魔」所誘惑。",
  ui_story_1013_10130801_84_dialog_content = "他們口中的「惡魔」，究竟指的是什麼？",
  ui_story_1013_10130801_85_dialog_content = "是高等暗鬼嗎，還是空裔或光靈？",
  ui_story_1013_10130801_86_dialog_content = "......研究院還在對它的身分進行分析，我暫時不能回答你。",
  ui_story_1013_10130801_87_dialog_content = "過了這麼久了，你們的研究進度難道還是和上次一樣嗎？",
  ui_story_1013_10130801_88_dialog_content = "「惡魔」的種族來源、進化方式、對歷史的影響，都需要嚴謹地研究考證。",
  ui_story_1013_10130801_89_dialog_content = "這可不是在模擬器裡打幾回勝仗就能得出結論的。",
  ui_story_1013_10130801_90_dialog_content = "......",
  ui_story_1013_10130801_91_dialog_content = "最終，空裔與暗鬼在「惡魔」的控制下與光靈決戰。",
  ui_story_1013_10130801_92_dialog_content = "這段歷史，對於在座的各位來說也都不是祕密了吧。",
  ui_story_1013_10130801_93_dialog_content = "......在那之後，屬於遠古祖先的世界徹底毀滅，暗鬼退回暗面，空裔不知所蹤。",
  ui_story_1013_10130801_94_dialog_content = "僅存的光靈重建了新的文明，對抗「惡魔」留下的暗鬼們。",
  ui_story_1013_10130801_95_dialog_content = "是這樣吧？",
  ui_story_1013_10130801_96_dialog_content = "啟光還沒有得出確切的結論，不過目前的觀點大致與你的想像相吻合。",
  ui_story_1013_10130801_96X1_dialog_content = "你們稍等一下。",
  ui_story_1013_10130801_97_dialog_content = "<color=#e8d9bb>啪——喀</color>",
  ui_story_1013_10130801_98_dialog_content = "（提神劑？他們還真是老樣子。）",
  ui_story_1013_10130801_99_dialog_content = "（用提神劑作為互相溝通的暗號，也只能騙過初來乍到的PlayerName了。）",
  ui_story_1013_10130801_100_dialog_content = "哦，啟光內部流通的新型提神劑，空裔，你要來一個嗎？",
  ui_story_1013_10130801_100X1_dialog_content = "（從......從哪裡冒出來的？！）",
  ui_story_1013_10130801_100X2_dialog_content = "終於還是願意露面了嗎，巴蕾特？",
  ui_story_1013_10130801_100X3_dialog_content = "是啊，我對這個空裔稍微有點興趣。",
  ui_story_1013_10130801_100X4_dialog_content = "不過，另外那幾個傢伙可不一定也會這麼想喔。",
  ui_story_1013_10130801_100X5_dialog_content = "我們一直都在<color=#FFB400>觀察</color>你，好好表現吧，空裔。",
  ui_story_1013_10130801_101_dialog_content = "......我......我明白了。",
  ui_story_1013_10130801_102_option_content = "詢問關於遠古光靈的問題",
  ui_story_1013_10130801_103_dialog_content = "那麼，那些「天賦異稟的祖先」，最初是如何覺醒光能術的？",
  ui_story_1013_10130801_104_dialog_content = "在我看到的畫面裡，他們只是在向著光的方向祈禱。",
  ui_story_1013_10130801_105_dialog_content = "這是......白夜城信仰的來源嗎？",
  ui_story_1013_10130801_106_dialog_content = "呵呵，這個問題你是不是問錯地方了，小夥子？",
  ui_story_1013_10130801_107_dialog_content = "對......對不起！",
  ui_story_1013_10130801_108_dialog_content = "這個世界上的光靈雖然很多，但確實鮮少有人瞭解光能術的本質。",
  ui_story_1013_10130801_109_dialog_content = "光靈們更願意把它的來源解釋為更容易理解的東西......",
  ui_story_1013_10130801_110_dialog_content = "比如：來自神的贈予、誕生於某個神聖之地、從所謂「真理」中領悟到......",
  ui_story_1013_10130801_111_dialog_content = "而它真正的核心，是一種用<color=#FFB400>生命力</color>驅動能量的術式。",
  ui_story_1013_10130801_112_dialog_content = "生命力？這樣的話，那我們空裔......",
  ui_story_1013_10130801_113_dialog_content = "空裔一族雖然具備生命力，但是不能掌握光能術的使用方法。",
  ui_story_1013_10130801_114_dialog_content = "更不用說沒有任何生命力的暗鬼，牠們更不能用這種方法驅動能量。",
  ui_story_1013_10130801_115_dialog_content = "你所說的所謂的「方法」，到底是什麼東西？",
  ui_story_1013_10130801_116_dialog_content = "呵呵，簡單來說，就是對光能術的具體應用。比如，在啟光聯邦......",
  ui_story_1013_10130801_117_dialog_content = "我們習慣在<color=#FFB400>形式上</color>使用光能術驅動物理器械，並讓科技干預光能術的效果。",
  ui_story_1013_10130801_118_dialog_content = "而在白夜城那邊，他們會讓純粹的信仰去驅動他們的生命力......",
  ui_story_1013_10130801_119_dialog_content = "從而達到在<color=#FFB400>源頭上</color>影響光能術發揮的目的。",
  ui_story_1013_10130801_120_dialog_content = "這一點，也是白夜城和啟光的唯一區別。",
  ui_story_1013_10130801_121_dialog_content = "唯一區別？這個結論太武斷了。",
  ui_story_1013_10130801_122_dialog_content = "下次，請不要在我講話的時候打斷我。",
  ui_story_1013_10130801_123_dialog_content = "（是錯覺嗎......這幾個科學家表現得都很友善，但總能感覺到一股攻擊性。）",
  ui_story_1013_10130801_124_dialog_content = "談話已經進行了十分鐘，尤利西斯教授，請您不要忘記這場會議的初衷。",
  ui_story_1013_10130801_125_dialog_content = "謝謝提醒，但按照會前的約定，這位空裔還剩最後一個問題。",
  ui_story_1013_10130801_126_dialog_content = "真是嚴謹啊。尤利西斯，你把這個小姑娘訓練得很守規矩。",
  ui_story_1013_10130801_127_dialog_content = "鶯歌是啟明星計畫改造出的傑出畢業生，我只不過盡了該做的培養義務。",
  ui_story_1013_10130801_128_dialog_content = "（改造？！）",
  ui_story_1013_10130801_129_dialog_content = "（他們一直以來在做的......是<color=#FFB400>光靈改造</color>嗎？！）",
  ui_story_1013_10130801_130_dialog_content = "......這就是你一直祕而不宣的實驗嗎？！",
  ui_story_1013_10130801_131_dialog_content = "解釋清楚！啟明星計畫不是在多年前就被叫停了嗎？",
  ui_story_1013_10130801_132_dialog_content = "準確來說，委員會確實舉行過暫停該計畫的相關投票。",
  ui_story_1013_10130801_133_dialog_content = "但投票結果並不如妳所願，萊因哈特。",
  ui_story_1013_10130801_134_dialog_content = "既然如此，我會再次向委員會提出相關申請。",
  ui_story_1013_10130801_135_dialog_content = "無論如何，我不會容許我的士兵和人民經受任何改造實驗！",
  ui_story_1013_10130801_136_dialog_content = "當然，萊因哈特，妳完全可以這樣做。",
  ui_story_1013_10130801_137_dialog_content = "大元帥的權力是所有啟光人民賦予給妳的，妳理應盡你所能為他們謀求福祉。",
  ui_story_1013_10130801_138_dialog_content = "但這一切行為，都要等到這場會議之後。麻煩把說話的時間讓給空裔。",
  ui_story_1013_10130801_139_dialog_content = "（怎麼辦......薇絲的狀態，難道與這件事有關嗎......）",
  ui_story_1013_10130801_140_dialog_content = "（有多少人經歷過祕密改造......其中又有多少是一直以來陪著我的朋友們......）",
  ui_story_1013_10130801_141_dialog_content = "（強制感應！）",
  ui_story_1013_10130801_142_dialog_content = "PlayerName，不要慌，這個問題就拜託你了。",
  ui_story_1013_10130801_143_dialog_content = "請向尤利西斯問清楚「改造實驗」的計畫。",
  ui_story_1013_10130801_144_dialog_content = "這事關薇絲他們的未來，事關眼前這位情報官和她的同胞。",
  ui_story_1013_10130801_145_dialog_content = "或許有可能......也事關當年的......",
  ui_story_1013_10130801_146_dialog_content = "......我明白了。",
  ui_story_1013_10130801_147_dialog_content = "另外，但願是我想多了，他們似乎在暗中考量你。",
  ui_story_1013_10130801_148_dialog_content = "考量我？",
  ui_story_1013_10130801_149_dialog_content = "或許他們內部，還沒有針對某件事達成一致的意見。",
  ui_story_1013_10130801_150_dialog_content = "只能在見到你之後，他們才能祕密地做出具體判斷。",
  ui_story_1013_10130801_151_dialog_content = "這也是他們的老把戲了，總之，服用提神劑就是他們的訊號。",
  ui_story_1013_10130801_152_dialog_content = "不過你也不用過於緊張，做你自己就可以了。",
  ui_story_1013_10130801_153_dialog_content = "好......好的。",
  ui_story_1013_10130801_154_dialog_content = "（在剛才這段沉默裡，他使用了「感應能力」嗎？）",
  ui_story_1013_10130801_155_dialog_content = "（......不管怎麼說，他確實是個需要持續觀察的對象。）",
  ui_story_1013_10130801_156_dialog_content = "<color=#e8d9bb>啪——喀</color>",
  ui_story_1013_10130801_157_dialog_content = "（呵呵......終於還是認可這位空裔了嗎。）",
  ui_story_1013_10130801_158_option_content = "詢問關於改造實驗的問題",
  ui_story_1013_10130801_159_dialog_content = "當時的赫利俄斯，也出自這個「啟明星計畫」嗎？",
  ui_story_1013_10130801_160_dialog_content = "究竟是為什麼......為什麼啟光要研究改造光靈的實驗......",
  ui_story_1013_10130801_161_dialog_content = "赫利俄斯？......你瞭解的東西比我預想的多一些。",
  ui_story_1013_10130801_162_dialog_content = "事已至此，我沒有欺騙你的必要，我確實一直在進行光靈改造的實驗。",
  ui_story_1013_10130801_163_dialog_content = "站在各位眼前的這位鶯歌，就是本屆最成功的實驗體。",
  ui_story_1013_10130801_164_dialog_content = "改造光靈仍保持著光靈的基本基因和人性特徵。",
  ui_story_1013_10130801_165_dialog_content = "儘管有的時候，鶯歌強勢的性格也會讓我有點為難。",
  ui_story_1013_10130801_166_dialog_content = "這根本不是重點，你為什麼要這麼做？",
  ui_story_1013_10130801_167_dialog_content = "為了啟光。",
  ui_story_1013_10130801_168_dialog_content = "這麼做當然是為了啟光，啟光需要擁有屬於自己的改造裝置。",
  ui_story_1013_10130801_169_dialog_content = "就像白夜城有他們的大砲，空谷有能夠強化光靈體質的上古儀器。",
  ui_story_1013_10130801_170_dialog_content = "啟光也曾嘗試在暗面探索類似的裝置，可惜毫無頭緒。",
  ui_story_1013_10130801_171_dialog_content = "啟光只有忠實的人民，我們每一條防線都是用戰士的屍骨堆出來的。",
  ui_story_1013_10130801_172_dialog_content = "啟光對改造裝置的研究，就是真正的民心所向。",
  ui_story_1013_10130801_173_dialog_content = "多了一個改造出來的實驗體，就少了一個無辜的犧牲者。",
  ui_story_1013_10130801_174_dialog_content = "荒謬至極，那無辜的實驗體呢？赫利俄斯那樣的犧牲就不算犧牲嗎？",
  ui_story_1013_10130801_175_dialog_content = "<color=#e8d9bb>啪——喀</color>",
  ui_story_1013_10130801_176_dialog_content = "呼，說到赫利俄斯......",
  ui_story_1013_10130801_177_dialog_content = "他們那批實驗體確實和啟明星計畫無關。",
  ui_story_1013_10130801_178_dialog_content = "他屬於另一套培養計畫，並且只是一個實驗失敗的產物罷了。",
  ui_story_1013_10130801_179_dialog_content = "失敗？！",
  ui_story_1013_10130801_180_dialog_content = "你把摧毀一個光靈的人生，稱之為「實驗失敗」嗎？",
  ui_story_1013_10130801_181_dialog_content = "萊因哈特，妳作為一個成功者，就不要刻意拔高妳的道德姿態了。",
  ui_story_1013_10130801_182_dialog_content = "這遠沒有「摧毀」來得這麼誇張，對他來說，這也許是一條更加適合的道路呢？",
  ui_story_1013_10130801_183_dialog_content = "<color=#e8d9bb>啪——</color>",
  ui_story_1013_10130801_184_dialog_content = "恕我無法繼續參會，而且尤利西斯，你也已經脫離了理性探討的氛圍。",
  ui_story_1013_10130801_185_dialog_content = "這場會議開到這裡，我認為已經沒有繼續的必要了。",
  ui_story_1013_10130801_186_dialog_content = "嗯？妳已經想結束了嗎，可這場會議對科學首席議會來說才剛剛開始。",
  ui_story_1013_10130801_187_dialog_content = "妳可以離開，如果妳放心把空裔獨自留在這裡的話。",
  ui_story_1013_10130801_188_dialog_content = "什......",
  ui_story_1013_10130801_189_dialog_content = "你們不敢。",
  ui_story_1013_10130801_190_dialog_content = "放心，在座的都是知識份子，我們每一個人都沒有妳想得那麼下作。",
  ui_story_1013_10130801_191_dialog_content = "我們當然不會對空裔做什麼，我們和空裔一直在保持「友善」的交談。",
  ui_story_1013_10130801_192_dialog_content = "但這一切，都需要有一雙最權威的眼睛來證明。",
  ui_story_1013_10130801_193_dialog_content = "萊因哈特，不需要我說得更明白了吧。希望妳也能扮演好自己的角色。",
  ui_story_1013_10130801_194_dialog_content = "......",
  ui_story_1013_10130801_195_dialog_content = "<color=#e8d9bb>叩、叩——</color>",
  ui_story_1013_10130801_196_dialog_content = "哈——欠。",
  ui_story_1013_10130801_197_dialog_content = "別把一場會議搞得這麼劍拔弩張，各位。",
  ui_story_1013_10130801_198_dialog_content = "既然你們都給出了<color=#FFB400>認可這位空裔的暗號</color>，至少也該表現得和善一些吧。",
  ui_story_1013_10130801_199_dialog_content = "小鶯歌說得對，不要忘記我們把空裔叫過來的初衷。",
  ui_story_1013_10130801_200_dialog_content = "（這幾個人，終於要說出他們的真實目的了嗎......）",
  ui_story_1013_10130801_201_dialog_content = "空裔，關於你的問題，剛才那幾個人也回答得差不多了。",
  ui_story_1013_10130801_202_dialog_content = "其中不乏涉及到啟光高級機密的問題，他們也算是知無不言。",
  ui_story_1013_10130801_203_dialog_content = "用一些情報來換取你的配合，這對你來說也並不算吃虧吧？",
  ui_story_1013_10130801_204_dialog_content = "？！",
  ui_story_1013_10130801_205_dialog_content = "開什麼玩笑......我絕對不會配合你們的改造實驗！！！",
  ui_story_1013_10130801_206_dialog_content = "噗......你可是現今唯一的空裔，我們怎麼會改造你！",
  ui_story_1013_10130801_207_dialog_content = "我們剛才就說了吧，我們不會碰你一根手指的。",
  ui_story_1013_10130801_208_dialog_content = "我只是想尋求你的幫忙——或者說，這也可以間接地幫助到你自己。",
  ui_story_1013_10130801_209_dialog_content = "麻煩妳說話不要繞圈子。",
  ui_story_1013_10130801_210_dialog_content = "真冷漠啊。我知道，你想要薇絲恢復正常，你的巨像似乎也出現了一點狀況。",
  ui_story_1013_10130801_211_dialog_content = "（確，確實是這樣......）",
  ui_story_1013_10130801_212_dialog_content = "長話短說，科學首席議會希望借你的感應力，與<color=#FFB400>「守護者一號」</color>建立連結。",
  ui_story_1013_10130801_213_dialog_content = "之前，啟光的科學家們都認為，你的臨空者號只是普通的運輸型巨像。",
  ui_story_1013_10130801_214_dialog_content = "但透過臨空者號最近的一系列表現，以及不斷升級的系統中......",
  ui_story_1013_10130801_215_dialog_content = "我們都看到了更多的可能性。",
  ui_story_1013_10130801_216_dialog_content = "這些可能性，與操控臨空者號的空裔是分不開的。",
  ui_story_1013_10130801_217_dialog_content = "你和巨像這種遠古科技的緊密聯繫，是造成這一系列奇蹟的原因之一。",
  ui_story_1013_10130801_218_dialog_content = "經過剛才的談話，我們也一致認為，可以把守護者一號的意識拜託給你。",
  ui_story_1013_10130801_219_dialog_content = "所以，我希望你使用感應力，嘗試感應守護者一號。",
  ui_story_1013_10130801_220_dialog_content = "守護者一號？難道又是個需要我用拳頭來打的機器人嗎......",
  ui_story_1013_10130801_221_dialog_content = "它是殘存至今的遠古人工智慧，負責整個啟光科技系統的日常運轉、計算。",
  ui_story_1013_10130801_222_dialog_content = "如何，聽起來和巨像是不是有點相似？",
  ui_story_1013_10130801_223_dialog_content = "確實如此......",
  ui_story_1013_10130801_224_dialog_content = "如果你能夠感應到守護者一號的意識......",
  ui_story_1013_10130801_225_dialog_content = "那就有可能，在它來自遠古時代的意識中，找到讓薇絲回歸正常狀態的線索。",
  ui_story_1013_10130801_226_dialog_content = "當然，如果你能在它的意識中切換到相應的場景，就能與你的巨像再次相見。",
  ui_story_1013_10130801_227_dialog_content = "？！",
  ui_story_1013_10130801_228_dialog_content = "（如果她說的是真的，那臨空者號就......！）",
  ui_story_1013_10130801_229_dialog_content = "選擇權在你自己手上，我只是提供參考意見。",
  ui_story_1013_10130801_230_dialog_content = "PlayerName，你在猶豫嗎？",
  ui_story_1013_10130801_231_dialog_content = "話說到了這個份上，我當然要試試！",
  ui_story_1013_10130801_232_dialog_content = "嗯，不愧是你啊，我認同你這個選擇。",
  ui_story_1013_10130801_233_dialog_content = "雖然在座的各位態度不善，但你不可以輕易放棄這個扭轉局勢機會。",
  ui_story_1013_10130801_234_dialog_content = "看來你們的意見已經統一了。",
  ui_story_1013_10130801_235_dialog_content = "那麼，我即刻就把守護者一號帶過來。",
  ui_story_1013_10130901_1_dialog_content = "它是殘存至今的遠古人工智慧，負責整個啟光科技系統的日常運轉、計算。",
  ui_story_1013_10130901_2_dialog_content = "如何，聽起來和巨像是不是有點相似？",
  ui_story_1013_10130901_3_dialog_content = "遠古人工智慧......維持整個啟光的工作......",
  ui_story_1013_10130901_4_dialog_content = "真讓人好奇，聽起來是個很了不得的東西。",
  ui_story_1013_10130901_5_dialog_content = "不知道它會長成什麼樣子呢，能支持啟光的巨量運算，它的體型一定很大吧。",
  ui_story_1013_10130901_6_dialog_content = "像臨空者號那麼大。",
  ui_story_1013_10130901_7_dialog_content = "如果是留存完好的遠古人工智慧，它一定具備很完備的運行程式。",
  ui_story_1013_10130901_8_dialog_content = "至少比丘布更加聰明一些。",
  ui_story_1013_10130901_9_dialog_content = "另外，如果要便於更多人對它進行操控，那它一定也會有一塊顯示器。",
  ui_story_1013_10130901_10_dialog_content = "就像地下城遺跡的「管家」那樣。",
  ui_story_1013_10130901_11_dialog_content = "你好，空裔！",
  ui_story_1013_10130901_12_dialog_content = "你和一號收集過的空裔資料，有所差別。",
  ui_story_1013_10130901_13_dialog_content = "這，這個小機器人難道就是......",
  ui_story_1013_10130901_14_dialog_content = "沒錯，跟守護者一號打個招呼吧。",
  ui_story_1013_10130901_15_dialog_content = "這也跟我想像中的差太多了吧！",
  ui_story_1013_10130901_16_dialog_content = "一號會藉助你的存在，更新一號儲存的空裔資料。",
  ui_story_1013_10130901_17_dialog_content = "看得出來，一號也和你收集過的人工智慧資料，有所差別。",
  ui_story_1013_10130901_18_dialog_content = "就讓我們，互相豐富對方的資料庫吧，空裔。",
  ui_story_1013_10130901_19_dialog_content = "這算是......示好的意思嗎？",
  ui_story_1013_10130901_20_dialog_content = "意思是它願意跟你好好相處，守護者一號是很友善的親和型人工智慧。",
  ui_story_1013_10130901_21_dialog_content = "請再稍等幾分鐘，我現在開始為守護者一號輸入關聯程式。",
  ui_story_1013_10130901_22_dialog_content = "錯誤，錯誤。",
  ui_story_1013_10130901_23_dialog_content = "關聯程式輸入失敗，一號無法關聯，來路不明的連線者。",
  ui_story_1013_10130901_24_dialog_content = "這又是什麼意思......",
  ui_story_1013_10130901_25_dialog_content = "<size=30>之前不是約定好了嗎，讓現存的空裔跟你的意識做連結實驗，我也簽過許可證書了吧......</size>",
  ui_story_1013_10130901_26_dialog_content = "原來你們沒有商量好啊！",
  ui_story_1013_10130901_27_dialog_content = "抱......抱歉，守護者一號是運行嚴謹的人工智慧。",
  ui_story_1013_10130901_28_dialog_content = "任何試圖與它進行關聯的外部外掛程式，都要受到它的高度掃描與攔截。",
  ui_story_1013_10130901_29_dialog_content = "一號會，自主對未知事物進行學習，對已知事物進行分析。",
  ui_story_1013_10130901_30_dialog_content = "一號願意，學習未知空裔的資料。但根據一號已知的空裔種族資料庫來看......",
  ui_story_1013_10130901_31_dialog_content = "基於過往的分析結果，一號不會許可，空裔種族獲得一號的控制許可權。",
  ui_story_1013_10130901_32_dialog_content = "所以，現在正好是更新空裔種族資料庫的機會，不是嗎？",
  ui_story_1013_10130901_33_dialog_content = "......明白了。一號剛才也承諾，和這位空裔，互相更新概念認知。",
  ui_story_1013_10130901_34_dialog_content = "這個意思是，你答應了？",
  ui_story_1013_10130901_35_dialog_content = "一號會，透過嚴謹的現場測試，記錄並分析空裔的能力資料。",
  ui_story_1013_10130901_36_dialog_content = "基於形成的分析結果，一號會自主判斷，是否開放空裔對一號的控制許可權。",
  ui_story_1013_10130901_37_dialog_content = "哎，現場測試？在這個會議室裡嗎？",
  ui_story_1013_10130901_38_dialog_content = "請空裔，把自己調整為連線模式。",
  ui_story_1013_10130901_39_dialog_content = "（噢！這就是要跟我建立感應的意思了吧。）",
  ui_story_1013_10130901_40_option_content = "強制感應！",
  ui_story_1013_10130901_41_dialog_content = "<color=#e8d9bb>嗡——</color>",
  ui_story_1013_10130901_42_dialog_content = "等一下！",
  ui_story_1013_10130901_43_dialog_content = "<color=#e8d9bb>嗡......</color>",
  ui_story_1013_10130901_44_dialog_content = "還......",
  ui_story_1013_10130901_45_dialog_content = "還沒有人告訴我現場測試的方式啊！",
  ui_story_1013_10130901_46_dialog_content = "<color=#e8d9bb>颯......颯......</color>",
  ui_story_1013_10130901_47_dialog_content = "這裡是......等等？這裡是我在戰場模擬器裡來過的地方？！",
  ui_story_1013_10130901_48_dialog_content = "這就是現場測試的地點。",
  ui_story_1013_10130901_49_dialog_content = "誰？！",
  ui_story_1013_10130901_50_dialog_content = "請執行抬頭動作，空裔。",
  ui_story_1013_10130901_51_dialog_content = "一號在上面。",
  ui_story_1013_10130901_52_dialog_content = "什麼？！",
  ui_story_1013_10130901_53_dialog_content = "（真，真是驚人......）",
  ui_story_1013_10130901_54_dialog_content = "（原來如此，原來仔細觀察模擬戰場上方，就能看到與現實世界的交界。）",
  ui_story_1013_10130901_55_dialog_content = "（在半透明的穹頂之外，那個像太陽一樣大的東西，就是它的感測器吧！）",
  ui_story_1013_10130901_56_dialog_content = "歡迎進入類比古戰場，一號會，即時記錄空裔的實驗資料。",
  ui_story_1013_10130901_57_dialog_content = "努力讓一號，觀測到你的能力吧，空裔。",
  ui_story_1013_10130901_58_dialog_content = "又來？這片古戰場難道是你們啟光內部的通用資料嗎？！",
  ui_story_1013_10130901_59_dialog_content = "（如果這片模擬戰場真的是通用的，那臨空者號滯留在這的意識資料也......）",
  ui_story_1013_10130901_60_dialog_content = "（正好，就利用一下這個機會！）",
  ui_story_1013_10130901_61_dialog_content = "請空裔，儘快考察並熟悉戰鬥地形，一號即將，投放第一批戰鬥資料。",
  ui_story_1013_10130901_62_dialog_content = "知道了。在這之前，我有一個請求。",
  ui_story_1013_10130901_63_dialog_content = "如果我通過了測試，我希望可以親自檢查這片遠古戰場今日的資料流。",
  ui_story_1013_10130901_64_dialog_content = "這種事情......",
  ui_story_1013_10130901_65_dialog_content = "一號許可，申請生效。條約成立。",
  ui_story_1013_10130901_66_dialog_content = "下一步，準備好了嗎，空裔？",
  ui_story_1013_10130901_67_dialog_content = "戰鬥開始。",
  ui_story_1013_10130901_68_dialog_content = "關卡目標：消滅所有暗鬼。",
  ui_story_1013_10130901_69_dialog_content = "守護者一號，開始執行關卡。",
  ui_story_1013_10130901_70_dialog_content = "既然如此......",
  ui_story_1013_10130901_71_dialog_content = "「薇絲」、「卡蓮」......拜託了！",
  ui_story_1013_10130901_72_dialog_content = "交給我吧。",
  ui_story_1013_10130901_73_dialog_content = "完全沒問題！",
  ui_story_1013_10131002_1_dialog_content = "嘎......",
  ui_story_1013_10131002_2_dialog_content = "已達成關卡目標。",
  ui_story_1013_10131002_3_dialog_content = "測試結束。關卡評分：B。",
  ui_story_1013_10131002_4_dialog_content = "正在錄入，未知資訊......",
  ui_story_1013_10131002_5_dialog_content = "空裔的戰鬥能力，僅體現在，戰略部署。",
  ui_story_1013_10131002_6_dialog_content = "空裔可以，操控光靈，正常完成各項戰鬥任務。",
  ui_story_1013_10131002_7_dialog_content = "可能跟你認知中的概念有所區別，但對於這個時代來說，這不是什麼新鮮事。",
  ui_story_1013_10131002_8_dialog_content = "瞭解，一號的空裔種族資料庫已更新。",
  ui_story_1013_10131002_9_dialog_content = "你的現場測試通過了，空裔。",
  ui_story_1013_10131002_10_dialog_content = "一號會按照條約，向你公開這片遠古戰場的資料流。",
  ui_story_1013_10131002_11_dialog_content = "你即將離開遠古戰場，該戰場也將在使用結束後被銷毀。",
  ui_story_1013_10131002_12_dialog_content = "<color=#e8d9bb>嗡——</color>",
  ui_story_1013_10131002_13_dialog_content = "等等......？",
  ui_story_1013_10131002_14_dialog_content = "請不要銷毀這片模擬古戰場！",
  ui_story_1013_10131002_15_option_content = "強制感應！",
  ui_story_1013_10131002_16_dialog_content = "按照光靈的語言來說，你這樣做很「不禮貌」，空裔。",
  ui_story_1013_10131002_17_dialog_content = "雖然你獲得了一號的認可，但一號不是可以隨意連線登入的工具。",
  ui_story_1013_10131002_18_dialog_content = "我會在這次感應結束之後，向阿爾戈爾報備。",
  ui_story_1013_10131002_19_dialog_content = "好吧，下一步，請給出你阻止一號銷毀古戰場資料的理由。",
  ui_story_1013_10131002_20_dialog_content = "你並沒有，事先把它放進你的申請條約。",
  ui_story_1013_10131002_21_dialog_content = "一號不明白，你為什麼要，查看並儲存它的資料流。",
  ui_story_1013_10131002_22_dialog_content = "你究竟，有什麼計畫。",
  ui_story_1013_10131002_23_dialog_content = "實際上......",
  ui_story_1013_10131002_24_dialog_content = "屬於我的巨像，他在上一場模擬戰鬥中，因為強行援助我而出了故障。",
  ui_story_1013_10131002_25_dialog_content = "他的意識資料留在了這片古戰場龐大的資料流中。",
  ui_story_1013_10131002_26_dialog_content = "它對你很重要嗎，空裔。",
  ui_story_1013_10131002_27_option_content = "臨空者號是我非常重要的朋友",
  ui_story_1013_10131002_28_dialog_content = "他並不只是具備自主意識的遠古智慧科技。",
  ui_story_1013_10131002_29_dialog_content = "他的意識和記憶資料中，承載著我們之間的很多經歷。",
  ui_story_1013_10131002_30_dialog_content = "一號明白了。",
  ui_story_1013_10131002_31_dialog_content = "正在錄入，未知資訊......",
  ui_story_1013_10131002_32_dialog_content = "一號的空裔種族資料庫已更新。",
  ui_story_1013_10131002_33_dialog_content = "怎麼回事，總覺得你們的感情突然變好了呢。",
  ui_story_1013_10131002_34_dialog_content = "報告，一號剛才與空裔進行了短暫連線，並同步了常規的測試結果。",
  ui_story_1013_10131002_35_dialog_content = "（它......幫我隱瞞了我強行感應它的目的......）",
  ui_story_1013_10131002_36_dialog_content = "好的，那麼你對面前這位空裔也有了全新的認知了吧。",
  ui_story_1013_10131002_37_dialog_content = "我們可以繼續之前說好的實驗了嗎？",
  ui_story_1013_10131002_38_dialog_content = "一號許可。",
  ui_story_1013_10131002_39_dialog_content = "空裔，按照條約，遠古戰場今日的資料流，已經同步至你的終端。",
  ui_story_1013_10131002_40_dialog_content = "......謝謝你，一號。",
  ui_story_1013_10131002_41_dialog_content = "這樣的話，我們就進入正題吧。",
  ui_story_1013_10131002_42_dialog_content = "空裔，守護者一號會透過與你的感應，學習你對遠古科技的使用資料。",
  ui_story_1013_10131002_43_dialog_content = "它的學習反饋，會即時同步在會議室這塊螢幕上。",
  ui_story_1013_10131002_44_dialog_content = "這對啟光的科技革新而言十分重要，有勞了。",
  ui_story_1013_10131002_45_dialog_content = "我會努力的。",
  ui_story_1013_10131002_46_dialog_content = "感覺，你今天經歷了不少模擬戰鬥啊。",
  ui_story_1013_10131002_47_dialog_content = "這次我就沒辦法在旁邊看著了，你一個人，可不要掉以輕心。",
  ui_story_1013_10131002_48_dialog_content = "請放心吧，萊因哈特。而且，嚴格來說我也不算是一個人。",
  ui_story_1013_10131002_49_dialog_content = "一號連線準備就緒。",
  ui_story_1013_10131002_50_dialog_content = "（能用平等的心態理解科技，是他和我們的科學家之間最大的區別。）",
  ui_story_1013_10131002_51_dialog_content = "（雖然研究院近年的技術力在不斷進步……）",
  ui_story_1013_10131002_X51_dialog_content = "（但如果達不成這種心態，就無法突破技術力頂端的那道門檻。）",
  ui_story_1013_10131002_52_dialog_content = "（希望他們能透過這次實驗看明白吧。）",
  ui_story_1013_10131002_53_dialog_content = "一號，請信任來自我這邊的意識吧。",
  ui_story_1013_10131002_54_option_content = "強制感應",
  ui_story_1013_10131002_55_dialog_content = "這就是一號的意識空間嗎......",
  ui_story_1013_10131002_56_dialog_content = "一號在這裡，空裔。",
  ui_story_1013_10131002_57_dialog_content = "歡迎光臨！",
  ui_story_1013_10131002_58_dialog_content = "這裡沒有阿爾戈爾教授的指令，請自便。",
  ui_story_1013_10131002_59_dialog_content = "失......失禮了！",
  ui_story_1013_10131002_60_dialog_content = "（就像個在扮家家酒的小孩子一樣......）",
  ui_story_1013_10131002_61_dialog_content = "空裔，你的意識，並不穩定，你仍在擔心你的巨像。",
  ui_story_1013_10131002_62_dialog_content = "（真聰明啊......不愧是維持整個啟光運作的人工智慧。）",
  ui_story_1013_10131002_63_dialog_content = "空裔，讓我們把這次學習實驗，變得更有挑戰性吧。你信任一號嗎。",
  ui_story_1013_10131002_64_dialog_content = "這個嘛，我當然是出於信任才跟你「連線」......",
  ui_story_1013_10131002_65_dialog_content = "信任已認證，下一步，一號申請搜尋巨像訊號，並與巨像進行連線。",
  ui_story_1013_10131002_66_dialog_content = "什......什麼？！",
  ui_story_1013_10131002_67_dialog_content = "如果空裔願意信任一號，一號申請搜尋巨像訊號，並與巨像進行連線。",
  ui_story_1013_10131002_68_dialog_content = "（它在......幫我為臨空者號想辦法？）",
  ui_story_1013_10131002_69_dialog_content = "（我應該按照它說的去做嗎......）",
  ui_story_1013_10131002_70_dialog_content = "空裔，在猶豫。",
  ui_story_1013_10131002_71_dialog_content = "正在啟用智慧分析樹......",
  ui_story_1013_10131002_72_dialog_content = "假設一：一號成功與巨像連線，獲得巨像訊號。",
  ui_story_1013_10131002_73_dialog_content = "結果：巨像意識資料成功尋回，巨像恢復意識。",
  ui_story_1013_10131002_74_dialog_content = "假設二：一號成功與巨像連線成功，獲得巨像訊號，企圖任意篡改巨像資料。",
  ui_story_1013_10131002_75_dialog_content = "結果：空裔作為一號與巨像的轉接器，即刻斷開連結，巨像保持原狀。",
  ui_story_1013_10131002_76_dialog_content = "假設三......",
  ui_story_1013_10131002_77_dialog_content = "好，好了......不用再列舉了！",
  ui_story_1013_10131002_78_dialog_content = "我明白你的意思，眼下，我也沒有其他更好的方法了吧。",
  ui_story_1013_10131002_79_dialog_content = "謝謝你，一號，謝謝你願意為了我的巨像做這種嘗試。",
  ui_story_1013_10131002_80_dialog_content = "空裔，和遠古智慧科技，是朋友。",
  ui_story_1013_10131002_81_dialog_content = "一號也是，遠古智慧科技。",
  ui_story_1013_10131002_82_dialog_content = "那接下來，就拜託你了！",
  ui_story_1013_10131002_83_dialog_content = "我們返回那片模擬古戰場，去解救臨空者號的意識吧。",
  ui_story_1013_10131002_84_dialog_content = "一號準備就緒。倒數計時......",
  ui_story_1013_10131002_85_dialog_content = "三......",
  ui_story_1013_10131002_86_dialog_content = "二......",
  ui_story_1013_10131002_87_dialog_content = "一。",
  ui_story_1013_10131101_1_dialog_content = "注意。虛擬戰場的穩定性很差。",
  ui_story_1013_10131101_2_dialog_content = "做好準備，面對意料外的衝擊。",
  ui_story_1013_10131101_3_dialog_content = "沒關係，我來過這裡。",
  ui_story_1013_10131101_4_dialog_content = "只不過，這裡看起來跟上次不太一樣了。",
  ui_story_1013_10131101_5_dialog_content = "虛擬戰場始終處在自我運行中，時間會自然流逝。",
  ui_story_1013_10131101_6_dialog_content = "但我不理解的是，既然是虛擬戰場，臨空者號的意識怎麼會受困在這裡？",
  ui_story_1013_10131101_7_dialog_content = "臨空者號的意識是資料，虛擬戰場也是資料。",
  ui_story_1013_10131101_8_dialog_content = "臨空者號的意識干涉了虛擬戰場，它們的資料混淆在一起。",
  ui_story_1013_10131101_9_dialog_content = "必須在，虛擬戰場自我銷毀之前，訪問臨空者號。",
  ui_story_1013_10131101_10_dialog_content = "否則，虛擬戰場的自我銷毀，也會銷毀臨空者號的資料。",
  ui_story_1013_10131101_11_dialog_content = "銷毀？！也就是說，臨空者號的意識會消失嗎？",
  ui_story_1013_10131101_12_dialog_content = "並不是消失，而是失去了存取的連接埠。",
  ui_story_1013_10131101_13_dialog_content = "用現實世界的事情形容的話，它會被掩埋在這片虛擬戰場的廢墟之中。",
  ui_story_1013_10131101_14_dialog_content = "它仍然存在，但是誰也不知道它存在於哪裡。",
  ui_story_1013_10131101_15_dialog_content = "怎麼會這樣，虛擬戰場為什麼要自我銷毀？",
  ui_story_1013_10131101_16_dialog_content = "這片虛擬戰場記錄的事件非常特殊。",
  ui_story_1013_10131101_17_dialog_content = "它並不會在某一點退出，而是不斷地銷毀資料。",
  ui_story_1013_10131101_18_dialog_content = "直到虛擬戰場內什麼資料都不剩，即，它銷毀了自身。",
  ui_story_1013_10131101_19_dialog_content = "事件非常特殊......我記得外面那些人說過，文明曾經毀滅過一次。",
  ui_story_1013_10131101_20_dialog_content = "我們現在所看到的，這片虛擬戰場所記錄的，就是文明毀滅的樣子吧？",
  ui_story_1013_10131101_21_dialog_content = "根據演算，絕大多數生命無法存續。稱為文明毀滅，合理。",
  ui_story_1013_10131101_22_dialog_content = "怪不得我會看到那些。",
  ui_story_1013_10131101_23_dialog_content = "嘎——",
  ui_story_1013_10131101_24_dialog_content = "啊啊啊啊啊啊啊啊啊！",
  ui_story_1013_10131101_25_dialog_content = "人類在死去，就連暗鬼也無法存活。",
  ui_story_1013_10131101_26_dialog_content = "這樣的世界會走向毀滅是理所當然......",
  ui_story_1013_10131101_27_dialog_content = "<color=#e8d9bb>喀——</color>",
  ui_story_1013_10131101_28_dialog_content = "！！！",
  ui_story_1013_10131101_29_dialog_content = "<color=#e8d9bb>喀、喀——</color>",
  ui_story_1013_10131101_30_dialog_content = "嘎、嗷......",
  ui_story_1013_10131101_31_dialog_content = "暗鬼？！我還以為暗鬼已經在末日下滅絕了。",
  ui_story_1013_10131101_32_dialog_content = "竟然在這裡，還有暗鬼存活。",
  ui_story_1013_10131101_33_dialog_content = "牠......牠在做什麼？",
  ui_story_1013_10131101_34_dialog_content = "暗鬼在，啃食鋼筋。",
  ui_story_1013_10131101_35_dialog_content = "<color=#e8d9bb>喀、喀——</color>",
  ui_story_1013_10131101_36_dialog_content = "牠為什麼要這麼做？",
  ui_story_1013_10131101_37_dialog_content = "就算沒有吃的，比鋼筋好啃的東西還有很多吧？比如地上那些石頭。",
  ui_story_1013_10131101_38_dialog_content = "根據演算推測，暗鬼渴望鋼筋的性質。",
  ui_story_1013_10131101_39_dialog_content = "性質？",
  ui_story_1013_10131101_40_dialog_content = "鋼筋在末日下沒有毀滅。",
  ui_story_1013_10131101_41_dialog_content = "暗鬼希望透過攝取鋼筋，獲得類似的性質。",
  ui_story_1013_10131101_42_dialog_content = "這......這種事是可以做到的嗎？",
  ui_story_1013_10131101_43_dialog_content = "只是推測。但事實是，暗鬼在末日中，存活了下來。",
  ui_story_1013_10131101_44_dialog_content = "而且數量不少。",
  ui_story_1013_10131101_45_dialog_content = "<color=#e8d9bb>喀、喀——</color>",
  ui_story_1013_10131101_46_dialog_content = "<color=#e8d9bb>喀——！！！</color>",
  ui_story_1013_10131101_47_dialog_content = "嘎！！！",
  ui_story_1013_10131101_48_dialog_content = "呃，就連同類也要吃嗎！",
  ui_story_1013_10131101_49_dialog_content = "為了存活，暗鬼所做的，比人類要多得多。",
  ui_story_1013_10131101_50_dialog_content = "因此，這座由人類建造的城市裡，如今只生活著暗鬼。",
  ui_story_1013_10131101_51_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131101_52_dialog_content = "那麼多......",
  ui_story_1013_10131101_53_dialog_content = "地上還有很多暗鬼的屍體。牠們不停地死去，然後不停地新生。",
  ui_story_1013_10131101_54_dialog_content = "是的。「進化」無法在單一個體上完成，於是暗鬼選擇了高速更新換代的路線。",
  ui_story_1013_10131101_55_dialog_content = "牠們用堆砌死亡來完善種群的基因，直到牠們能適應末日下的極端條件。",
  ui_story_1013_10131101_56_dialog_content = "等一下，這些暗鬼的行動......牠們在向什麼地方聚集嗎？",
  ui_story_1013_10131101_57_dialog_content = "是的。暗鬼的行動方向相同。有東西在吸引牠們。",
  ui_story_1013_10131101_58_dialog_content = "吸引牠們？難道是！",
  ui_story_1013_10131101_59_option_content = "強制感應！",
  ui_story_1013_10131101_60_dialog_content = "臨空者號！是臨空者號的意識資料在那邊！",
  ui_story_1013_10131101_61_dialog_content = "原來如此。不屬於虛擬戰場的異常資料會格外顯眼。",
  ui_story_1013_10131101_62_dialog_content = "因此，暗鬼會向異常資料的來源聚攏。",
  ui_story_1013_10131101_63_dialog_content = "找到臨空者號就能解決他身上的故障，對嗎！",
  ui_story_1013_10131101_64_dialog_content = "可以透過接入臨空者號來排查故障。至於是否能夠解決，目前未知。",
  ui_story_1013_10131101_65_dialog_content = "好了好了，不用這麼嚴謹。總之是要去到臨空者號身邊嘛！",
  ui_story_1013_10131101_66_dialog_content = "幸好這裡是戰場模擬器，我也有跟暗鬼作戰的力量。",
  ui_story_1013_10131101_67_dialog_content = "接招吧！！！",
  ui_story_1013_10131101_68_dialog_content = "<color=#e8d9bb>砰——轟——！</color>",
  ui_story_1013_10131101_69_dialog_content = "怎麼這麼大聲音？！什麼東西要塌了嗎？",
  ui_story_1013_10131101_70_dialog_content = "你身邊的樓房正在坍塌。",
  ui_story_1013_10131101_71_dialog_content = "請注意，目前虛擬戰場的穩定性很差，攻擊波動很容易加速世界的崩解。",
  ui_story_1013_10131101_72_dialog_content = "嗚哇！真的有東西落下來了！",
  ui_story_1013_10131101_73_dialog_content = "<color=#e8d9bb>砰！！！</color>",
  ui_story_1013_10131101_74_dialog_content = "咳咳......好大的灰......",
  ui_story_1013_10131101_75_dialog_content = "還沒怎麼出手呢，這個世界也太脆弱了吧！",
  ui_story_1013_10131101_76_dialog_content = "它怎麼......",
  ui_story_1013_10131101_77_dialog_content = "由於戰場自身的因素，資料極其不穩定，即使沒有人為摧毀也會自我崩解。",
  ui_story_1013_10131101_78_dialog_content = "小心另一邊。",
  ui_story_1013_10131101_79_dialog_content = "！！！",
  ui_story_1013_10131101_80_dialog_content = "<color=#e8d9bb>砰！！！</color>",
  ui_story_1013_10131101_81_dialog_content = "呸！有完沒完啊！",
  ui_story_1013_10131101_82_dialog_content = "請注意，世界的崩解是虛擬戰場自我銷毀的具象化表現。",
  ui_story_1013_10131101_83_dialog_content = "而虛擬戰場資料銷毀將會引發......",
  ui_story_1013_10131101_84_dialog_content = "引發臨空者號資料的銷毀，對吧？",
  ui_story_1013_10131101_85_dialog_content = "是的。你理解了這部分內容。",
  ui_story_1013_10131101_86_dialog_content = "看起來沒有時間讓我抱怨了。",
  ui_story_1013_10131101_87_dialog_content = "趕在世界徹底崩解之前，無論如何都要到達臨空者號身邊！",
  ui_story_1013_10131202_1_dialog_content = "三十。",
  ui_story_1013_10131202_2_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_1013_10131202_3_dialog_content = "嗚哇！",
  ui_story_1013_10131202_4_dialog_content = "差點掉下去了......",
  ui_story_1013_10131202_5_dialog_content = "這些地上的裂縫怎麼像追著我一樣！",
  ui_story_1013_10131202_6_dialog_content = "因為你是引發崩解的因素之一。",
  ui_story_1013_10131202_7_dialog_content = "二十五。",
  ui_story_1013_10131202_8_dialog_content = "你你你，你嘴裡那個令人不安的數字是什麼意思！",
  ui_story_1013_10131202_9_dialog_content = "是你剩餘的時間。",
  ui_story_1013_10131202_10_dialog_content = "我透過讀取虛擬戰場的資料擬真了崩解的曲線，這個時間可以保證準確。",
  ui_story_1013_10131202_11_dialog_content = "只有二十幾秒了嗎！這也太......",
  ui_story_1013_10131202_12_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_1013_10131202_13_dialog_content = "二十。",
  ui_story_1013_10131202_14_dialog_content = "知道了！二十秒，夠我跑很遠了！",
  ui_story_1013_10131202_15_dialog_content = "臨空者號就在前面，我能感覺到！",
  ui_story_1013_10131202_16_dialog_content = "別忘了提防暗鬼。",
  ui_story_1013_10131202_17_dialog_content = "呿，煩死了！",
  ui_story_1013_10131202_18_dialog_content = "別擋我路......",
  ui_story_1013_10131202_19_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_1013_10131202_20_dialog_content = "哇啊啊啊啊啊！！！",
  ui_story_1013_10131202_21_dialog_content = "<color=#e8d9bb>轟！！！</color>",
  ui_story_1013_10131202_22_dialog_content = "咳......咳咳......",
  ui_story_1013_10131202_23_dialog_content = "好疼......",
  ui_story_1013_10131202_24_dialog_content = "一號，時間還剩......",
  ui_story_1013_10131202_25_dialog_content = "十。",
  ui_story_1013_10131202_26_dialog_content = "糟了。動起來，快。",
  ui_story_1013_10131202_27_dialog_content = "離臨空者號，只差，最後一點了。",
  ui_story_1013_10131202_28_dialog_content = "他就在前面。",
  ui_story_1013_10131202_29_dialog_content = "五。",
  ui_story_1013_10131202_30_dialog_content = "咳......",
  ui_story_1013_10131202_31_dialog_content = "四。",
  ui_story_1013_10131202_32_dialog_content = "很近，很近了。",
  ui_story_1013_10131202_33_dialog_content = "三。",
  ui_story_1013_10131202_34_dialog_content = "哈......哈......",
  ui_story_1013_10131202_35_dialog_content = "二。",
  ui_story_1013_10131202_36_dialog_content = "<color=#e8d9bb>轟......</color>",
  ui_story_1013_10131202_37_dialog_content = "一。",
  ui_story_1013_10131202_38_dialog_content = "強制感應！",
  ui_story_1013_10131202_39_dialog_content = "臨空者號，是你嗎？",
  ui_story_1013_10131202_40_dialog_content = "......",
  ui_story_1013_10131202_41_dialog_content = "找到了，找到他了！",
  ui_story_1013_10131202_42_dialog_content = "怎麼樣？我算是趕上了嗎？",
  ui_story_1013_10131202_43_dialog_content = "快跟他建立連結！",
  ui_story_1013_10131202_44_dialog_content = "接入臨空者號資料埠。",
  ui_story_1013_10131202_45_dialog_content = "訪問申請無回應，執行強制訪問。",
  ui_story_1013_10131202_46_dialog_content = "做好準備，接下來你的意識會進入臨空者號的資料空間。",
  ui_story_1013_10131202_47_dialog_content = "一號無法預測你在該空間內即將面對的情景。",
  ui_story_1013_10131202_48_dialog_content = "當然準備好了。總不會比現在更糟吧？",
  ui_story_1013_10131202_49_dialog_content = "開始資料轉移。",
  ui_story_1013_10131202_50_dialog_content = "登入，臨空者號。",
  ui_story_1013_10131202_51_dialog_content = "呃......好黑啊，我們到了嗎？",
  ui_story_1013_10131202_52_dialog_content = "到了。看不見東西的話，請你試著睜一下眼睛。",
  ui_story_1013_10131202_53_dialog_content = "欸？",
  ui_story_1013_10131202_54_dialog_content = "哦，看見了！但是等一下，我怎麼連睜眼睛都需要別人提醒？",
  ui_story_1013_10131202_55_dialog_content = "這是正常的現象。戰場模擬器結束的時候，你是睜著眼睛的。",
  ui_story_1013_10131202_56_dialog_content = "因此在你的意識裡，眼睛處於睜開的狀態，自然不會想到再去睜開眼睛。",
  ui_story_1013_10131202_57_dialog_content = "但是進入到新的資料空間，我為你重新載入了軀體，這副軀體的雙眼處在閉合狀態。",
  ui_story_1013_10131202_58_dialog_content = "軀體與意識之間的矛盾引發了剛才的現象。",
  ui_story_1013_10131202_59_dialog_content = "喔......",
  ui_story_1013_10131202_60_dialog_content = "你理解了嗎？是否需要我重新......",
  ui_story_1013_10131202_61_dialog_content = "理解了理解了！完全理解了！",
  ui_story_1013_10131202_62_dialog_content = "那是臨空者號嗎？",
  ui_story_1013_10131202_X62_dialog_content = "我離它好近，但是我好像碰不到它。",
  ui_story_1013_10131202_X63_dialog_content = "這裡是什麼地方？",
  ui_story_1013_10131202_63_dialog_content = "從視覺上來說，你所看到的確實是臨空者號內部。",
  ui_story_1013_10131202_64_dialog_content = "不過更準確地說，這裡是臨空者號的資料存儲空間。",
  ui_story_1013_10131202_65_dialog_content = "也就是，臨空者號的「記憶」。",
  ui_story_1013_10131202_66_dialog_content = "記憶？",
  ui_story_1013_10131202_67_dialog_content = "為什麼我們要進到這裡？不是要排查臨空者號的故障嗎？",
  ui_story_1013_10131202_68_dialog_content = "是的。臨空者號發生故障的原因是一些錯亂的資料混雜在存儲空間中。",
  ui_story_1013_10131202_69_dialog_content = "我們要做的，就是在龐雜的資料中找出那些錯亂的資料，並將其修復。",
  ui_story_1013_10131202_70_dialog_content = "這個過程對於一號來說只是對資料的操作。",
  ui_story_1013_10131202_71_dialog_content = "但是你，無法用大腦直接處理資料，因此一號會幫助你借用想像力將資料視覺化。",
  ui_story_1013_10131202_72_dialog_content = "存儲的記憶會化作畫面，錯亂的資料會化作異象。",
  ui_story_1013_10131202_73_dialog_content = "接下來的流程，一號將與你一起檢視臨空者號的記憶。",
  ui_story_1013_10131202_74_dialog_content = "並從中尋找引發異常的錯亂資料。",
  ui_story_1013_10131202_75_dialog_content = "我能認出來哪些是錯亂的資料嗎？",
  ui_story_1013_10131202_76_dialog_content = "根據你的想像力，它們會以你厭惡、仇視的形象出現。你一定能認出來。",
  ui_story_1013_10131202_77_dialog_content = "哦，這樣啊。聽起來好像還挺簡單的？",
  ui_story_1013_10131202_78_dialog_content = "一號無法做出預估。",
  ui_story_1013_10131202_79_dialog_content = "好吧，走一步看一步吧。",
  ui_story_1013_10131202_X79_dialog_content = "資料連線，移動至臨空者號艙室。",
  ui_story_1013_10131202_X80_dialog_content = "呼，這裡就熟悉多了！",
  ui_story_1013_10131202_80_dialog_content = "說起來，還不知道這是臨空者號的哪段記憶呢。",
  ui_story_1013_10131202_81_dialog_content = "周圍什麼事都沒發生，安靜得要死。",
  ui_story_1013_10131202_82_dialog_content = "我們現在在什麼地方？我是說，這段記憶裡的臨空者號在什麼地方？",
  ui_story_1013_10131202_83_dialog_content = "一號並不掌握這些資料。",
  ui_story_1013_10131202_84_dialog_content = "也是，不能什麼都問你。",
  ui_story_1013_10131202_85_dialog_content = "臨空者號我再熟悉不過了，我出去調查一下。",
  ui_story_1013_10131202_86_dialog_content = "<color=#e8d9bb>嗒、嗒、嗒......</color>",
  ui_story_1013_10131202_87_dialog_content = "嗯？艙室的門怎麼全部關閉了？",
  ui_story_1013_10131202_88_dialog_content = "我想想，可以從這裡打開......",
  ui_story_1013_10131202_89_dialog_content = "<color=#e8d9bb>滴！滴！滴！滴！</color>",
  ui_story_1013_10131202_90_dialog_content = "警告？！這是什麼意思？",
  ui_story_1013_10131202_91_dialog_content = "臨空者號，你要把我關在裡面嗎？",
  ui_story_1013_10131202_92_dialog_content = "檢測到臨空者號與外界無氣體交換。艙室已徹底封閉。",
  ui_story_1013_10131202_93_dialog_content = "這是什麼情況啊......",
  ui_story_1013_10131202_94_dialog_content = "對了，控制台應該有記錄。",
  ui_story_1013_10131202_95_dialog_content = "我看看......我們現在所處的位置......座標是......",
  ui_story_1013_10131202_96_dialog_content = "？！！",
  ui_story_1013_10131202_97_dialog_content = "沒有位置資訊？",
  ui_story_1013_10131202_98_dialog_content = "其他資訊呢......也沒有？！",
  ui_story_1013_10131202_99_dialog_content = "控制台記錄的資訊怎麼這麼少？",
  ui_story_1013_10131202_100_dialog_content = "這裡是臨空者號的回憶。有些資訊當時是存在的，但是事後被刪除了。",
  ui_story_1013_10131202_101_dialog_content = "沒有事情發生，也沒有資訊記錄，這個回憶也太空蕩蕩了。",
  ui_story_1013_10131202_102_dialog_content = "臨空者號怎麼會有這樣的回憶呢？",
  ui_story_1013_10131202_103_dialog_content = "機器的記憶與人不同。",
  ui_story_1013_10131202_104_dialog_content = "臨空者號會有這段回憶不是因為它值得記住，而是因為它發生過。",
  ui_story_1013_10131202_105_dialog_content = "臨空者號才不是機器！他是......",
  ui_story_1013_10131202_106_dialog_content = "啊，對了，你......",
  ui_story_1013_10131202_107_dialog_content = "......對不起，我沒有說機器不好的意思。",
  ui_story_1013_10131202_108_dialog_content = "一號不明白你為什麼要道歉。",
  ui_story_1013_10131202_109_dialog_content = "不明白更好！我的性格就是喜歡道歉，哈、哈。",
  ui_story_1013_10131202_110_dialog_content = "？",
  ui_story_1013_10131202_111_dialog_content = "咳，回到正題，我繼續去找找哪裡有記錄狀況的資訊。",
  ui_story_1013_10131202_112_dialog_content = "資訊的話，一號找到了一些。",
  ui_story_1013_10131202_113_dialog_content = "哦？在哪裡？",
  ui_story_1013_10131202_114_dialog_content = "在這個被稱作「終端」的地方。",
  ui_story_1013_10131202_115_dialog_content = "這是......",
  ui_story_1013_10131202_116_dialog_content = "■■■■■■■■■■■■",
  ui_story_1013_10131202_117_dialog_content = "這是什麼？",
  ui_story_1013_10131202_118_dialog_content = "應該是一些遠古的文字。",
  ui_story_1013_10131202_119_dialog_content = "稍等，臨空者號記錄了翻譯的方法。",
  ui_story_1013_10131202_120_dialog_content = "我來將它轉化成你能看懂的文字。",
  ui_story_1013_10131202_121_dialog_content = "「收到了地面傳來的消息，這有可能是最後一次。」",
  ui_story_1013_10131202_122_dialog_content = "「高塔之城毀滅了。」",
  ui_story_1013_10131202_123_dialog_content = "什麼？竟然......怎麼會這樣？",
  ui_story_1013_10131202_124_dialog_content = "哎，這是遲早的事情。地面上到處都在毀滅，高塔之城也逃不過去的。",
  ui_story_1013_10131202_125_dialog_content = "這個結果從我們出發起就已經注定了。",
  ui_story_1013_10131202_126_dialog_content = "那返航的時候，我們該回到哪裡呢？",
  ui_story_1013_10131202_127_dialog_content = "放心吧，弗朗茨老師說了，返航的時候我們會收到訊號。",
  ui_story_1013_10131202_128_dialog_content = "他已經將一切安排好了。我們都相信他，對嗎？",
  ui_story_1013_10131202_129_dialog_content = "嗯。我們相信他。",
  ui_story_1013_10131202_130_dialog_content = "有別的選擇嗎？我們只能相信。",
  ui_story_1013_10131202_131_dialog_content = "對了，我還是想問。我們什麼時候能離開自己的巨像啊？",
  ui_story_1013_10131202_132_dialog_content = "這艘巨像上只有我一個人。我快要瘋掉了。",
  ui_story_1013_10131202_133_dialog_content = "我想見見其他人，我們明明離得這麼近。",
  ui_story_1013_10131202_134_dialog_content = "還有我的妹妹，我太想她了。她在你的巨像上吧，那個誰......",
  ui_story_1013_10131202_135_dialog_content = "對不起，我忘記你的名字了，217號。",
  ui_story_1013_10131202_136_dialog_content = "是的。她很好，妳放心吧。",
  ui_story_1013_10131202_137_dialog_content = "但是我們還不能離開自己的巨像，絕對不能。",
  ui_story_1013_10131202_138_dialog_content = "千萬不要做傻事，那會害死妳自己。",
  ui_story_1013_10131202_139_dialog_content = "不做傻事，可是有其他事給我們做嗎？",
  ui_story_1013_10131202_140_dialog_content = "我已經對進食厭倦了。如果再對睡覺感到厭倦，真不知道那時候該幹點什麼。",
  ui_story_1013_10131202_141_dialog_content = "這裡什麼都沒有。甚至從現在開始，就連少得可憐的外界訊息也不會再傳來。",
  ui_story_1013_10131202_142_dialog_content = "每天只能盯著終端，跟你們這些數位編號對話。",
  ui_story_1013_10131202_143_dialog_content = "遲早有一天大家都會像79號那樣，把其他人的名字忘掉，只記得一個個數字。",
  ui_story_1013_10131202_144_dialog_content = "不會啊！我記得你的名字，你叫帕克！",
  ui_story_1013_10131202_145_dialog_content = "我不會忘記大家的名字！空裔可不是用數字互相稱呼的民族啊！",
  ui_story_1013_10131202_146_dialog_content = "忘了吧，趁早忘掉。",
  ui_story_1013_10131202_147_dialog_content = "形式主義的執著不會給妳帶來好處，只會在真正忘掉的那天加劇妳的痛苦。",
  ui_story_1013_10131202_148_dialog_content = "一個用不上的稱呼，妳今天能記住，一個月後能記住。",
  ui_story_1013_10131202_149_dialog_content = "但是一年後呢？十年後呢？",
  ui_story_1013_10131202_150_dialog_content = "十年？那，那也太久了吧......",
  ui_story_1013_10131202_151_dialog_content = "我們要這樣過十年嗎？",
  ui_story_1013_10131202_152_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131202_153_dialog_content = "我們......我們還會返航的吧？",
  ui_story_1013_10131202_154_dialog_content = "嗯，我們會。",
  ui_story_1013_10131202_155_dialog_content = "弗朗茨老師說了，返航的時候我們會收到訊號。",
  ui_story_1013_10131202_156_dialog_content = "我們都相信他，對嗎？",
  ui_story_1013_10131301_1_dialog_content = "這些是空裔們的對話記錄！",
  ui_story_1013_10131301_2_dialog_content = "在我們周圍，還有其他的巨像在嗎？",
  ui_story_1013_10131301_3_dialog_content = "無法蒐集到充足的資訊。",
  ui_story_1013_10131301_4_dialog_content = "但是，存在這樣的可能性。",
  ui_story_1013_10131301_5_dialog_content = "從對話記錄來看，其他巨像也和臨空者號一樣，緊閉著艙門。",
  ui_story_1013_10131301_6_dialog_content = "大家被封閉在巨像的空間裡無所事事地度過每一天......",
  ui_story_1013_10131301_7_dialog_content = "（好熟悉的感覺。）",
  ui_story_1013_10131301_8_dialog_content = "（我小時候的生活不就是這樣嗎？）",
  ui_story_1013_10131301_9_dialog_content = "一號分析推測，發生這種狀況的原因是，放逐或避險。",
  ui_story_1013_10131301_10_dialog_content = "放逐：有人利用巨像將部分空裔囚禁於此，押送至指定地點。",
  ui_story_1013_10131301_11_dialog_content = "避險：巨像外的環境空裔無法生存，因此將艙室徹底隔絕保全空裔。",
  ui_story_1013_10131301_12_dialog_content = "從終端裡大家的口吻來看，我更願意相信是一種避險。",
  ui_story_1013_10131301_13_dialog_content = "他們提到了一個熟悉的名字，「弗朗茨」。",
  ui_story_1013_10131301_14_dialog_content = "你認識這個名字？",
  ui_story_1013_10131301_15_dialog_content = "算不上認識，我只是有幸看到過他留下的痕跡。",
  ui_story_1013_10131301_16_dialog_content = "那麼，他一定為你留下了深刻的印象。",
  ui_story_1013_10131301_17_dialog_content = "當然。他是一位非常特殊的空裔。",
  ui_story_1013_10131301_18_dialog_content = "甚至可以說，在他的時代裡，他是與「空裔」這個名字相悖的。",
  ui_story_1013_10131301_19_dialog_content = "他沒有選擇為世界帶來戰爭。相反，他所抗爭的正是空裔被強加的命運。",
  ui_story_1013_10131301_20_dialog_content = "我曾經在絕境裡被他的意志深深地觸動。",
  ui_story_1013_10131301_21_dialog_content = "所幸的是，我們現在看到了，那樣的意志不只屬於一人。",
  ui_story_1013_10131301_22_dialog_content = "你是指終端資訊中那些對話者？",
  ui_story_1013_10131301_23_dialog_content = "是的，那些數字編號的空裔。",
  ui_story_1013_10131301_24_dialog_content = "雖然隔著無數個年代，但我也和他們一樣，相信過同一個名字。",
  ui_story_1013_10131301_25_dialog_content = "這一點點共情讓我覺得他們是有信念的人。",
  ui_story_1013_10131301_26_dialog_content = "不像是被人強扭著放逐，而是自己選擇了現在的道路。",
  ui_story_1013_10131301_27_dialog_content = "也許是有什麼可怕的事情，讓他們不得不以這種極端的方式避險。",
  ui_story_1013_10131301_28_dialog_content = "非常奇特的邏輯。一號沒有理解，但是記下了你的結論。",
  ui_story_1013_10131301_29_dialog_content = "倒是也不用特意去記......",
  ui_story_1013_10131301_30_dialog_content = "對話記錄到這裡就沒有了。還能找到其他資訊嗎？",
  ui_story_1013_10131301_31_dialog_content = "沒有了，只有這些。",
  ui_story_1013_10131301_32_dialog_content = "那，那我們現在做什麼？",
  ui_story_1013_10131301_33_dialog_content = "沒有找到錯亂的資料，也沒有新的資訊可以調查。",
  ui_story_1013_10131301_34_dialog_content = "要在這裡陪其他空裔一起感受無聊嗎？",
  ui_story_1013_10131301_35_dialog_content = "這確實是一種低效的資料檢索方式。",
  ui_story_1013_10131301_36_dialog_content = "稍等，我來執行一些更精確的檢索。",
  ui_story_1013_10131301_37_dialog_content = "<color=#e8d9bb>嗡——</color>",
  ui_story_1013_10131301_38_dialog_content = "欸？你做了什麼？",
  ui_story_1013_10131301_39_dialog_content = "可能會對你看到的畫面產生一些影響，不要慌張。",
  ui_story_1013_10131301_40_dialog_content = "沒有慌張，我只是不太明白。",
  ui_story_1013_10131301_41_dialog_content = "用你可以理解的方式來解釋的話，一號調整了回憶中的時間。",
  ui_story_1013_10131301_42_dialog_content = "我們正在快速跳過沒有錯亂資料出現的回憶。",
  ui_story_1013_10131301_43_dialog_content = "竟然這麼方便......",
  ui_story_1013_10131301_44_dialog_content = "嘎——！",
  ui_story_1013_10131301_45_dialog_content = "嗚啊啊啊啊啊啊！",
  ui_story_1013_10131301_46_dialog_content = "怎、怎、怎麼回事！",
  ui_story_1013_10131301_47_dialog_content = "跳過了沒有錯亂資料出現的回憶，所以停下來的地方當然就是......",
  ui_story_1013_10131301_48_dialog_content = "嘎！",
  ui_story_1013_10131301_49_dialog_content = "喂！你、你沒事吧！",
  ui_story_1013_10131301_50_dialog_content = "......當然就是存在錯亂資料的回憶。",
  ui_story_1013_10131301_51_dialog_content = "這種時候倒是把話說簡單一點啊！",
  ui_story_1013_10131301_52_dialog_content = "所以這些暗鬼就是錯亂的資料對吧？",
  ui_story_1013_10131301_53_dialog_content = "是的。錯亂資料會根據你的想像力，以你厭惡、仇視的形象......",
  ui_story_1013_10131301_54_dialog_content = "嘎！",
  ui_story_1013_10131301_55_dialog_content = "你......",
  ui_story_1013_10131301_56_dialog_content = "......的形象出現。沒關係，我的資料結構很穩定，不會被輕易破壞。",
  ui_story_1013_10131301_57_dialog_content = "好的我知道了。但是也請你不要再被當作沙包打了，很嚇人。",
  ui_story_1013_10131301_58_dialog_content = "資料什麼的我不懂，也來不及去搞懂了。",
  ui_story_1013_10131301_59_dialog_content = "不過既然是暗鬼的模樣，按照暗鬼來對付就可以了對吧！",
  ui_story_1013_10131302_1_dialog_content = "速射感知！",
  ui_story_1013_10131302_2_dialog_content = "冰花，散開！",
  ui_story_1013_10131302_3_dialog_content = "哇，好爽......",
  ui_story_1013_10131302_4_dialog_content = "一號不明白。喊出那樣的內容對戰鬥有什麼幫助？",
  ui_story_1013_10131302_5_dialog_content = "呃，其實我也不知道。",
  ui_story_1013_10131302_6_dialog_content = "經常看其他光靈戰鬥的時候這樣喊，所以想自己試試看。",
  ui_story_1013_10131302_7_dialog_content = "也許是因為一邊戰鬥一邊把招式的名字喊出來很帥氣？",
  ui_story_1013_10131302_8_dialog_content = "你看，喊出來之後敵人就被消滅了，很有效嘛。",
  ui_story_1013_10131302_9_dialog_content = "原來如此。一號會試著去理解這種沒有邏輯的詭辯。",
  ui_story_1013_10131302_10_dialog_content = "哈哈，不說這些沒用的了。怎麼樣，臨空者號的狀態有變化嗎？",
  ui_story_1013_10131302_11_dialog_content = "大約37%的錯亂資料被清除，你的戰鬥很有效。",
  ui_story_1013_10131302_12_dialog_content = "臨空者號的部分功能開始恢復了。",
  ui_story_1013_10131302_13_dialog_content = "37%！竟然一下子消滅了這麼多！",
  ui_story_1013_10131302_14_dialog_content = "零散的錯亂資料會被臨空者號自己糾正。",
  ui_story_1013_10131302_15_dialog_content = "因此，等待我們修復的錯亂資料表現出較強的聚合性。",
  ui_story_1013_10131302_16_dialog_content = "根據演算，只剩下一處錯亂資料了。",
  ui_story_1013_10131302_17_dialog_content = "喔哦！那不是馬上要成功了嗎！",
  ui_story_1013_10131302_18_dialog_content = "是的。但是剩下那處錯亂資料的異常更嚴重，要小心。",
  ui_story_1013_10131302_19_dialog_content = "如果你準備好了，一號將執行精確檢索，前往錯亂資料所在的時間。",
  ui_story_1013_10131302_20_dialog_content = "先等一下。我們現在的時間與剛進來的時候不一樣了，對吧？",
  ui_story_1013_10131302_21_dialog_content = "是的。剛才的精確檢索跳過了很長一段時間。",
  ui_story_1013_10131302_22_dialog_content = "回憶中缺乏參照，因此無法得到確切的時間跨度。",
  ui_story_1013_10131302_23_dialog_content = "如果是這樣的話，我想再看一下終端。",
  ui_story_1013_10131302_24_dialog_content = "稍微有點好奇，當時的空裔們會經歷什麼。",
  ui_story_1013_10131302_25_dialog_content = "明白了。一號來為你調出終端資訊。",
  ui_story_1013_10131302_26_dialog_content = "記得先幫我翻譯好唷。",
  ui_story_1013_10131302_27_dialog_content = "當然。人工智慧會隨時優化自己的每一步行動。",
  ui_story_1013_10131302_28_dialog_content = "一號即是最優解。",
  ui_story_1013_10131302_29_dialog_content = "大家——",
  ui_story_1013_10131302_30_dialog_content = "大家！看一看這裡！",
  ui_story_1013_10131302_31_dialog_content = "雖然有點突然，但是，今天其實是我的生日。",
  ui_story_1013_10131302_32_dialog_content = "有人想聽我唱一首歌嗎？",
  ui_story_1013_10131302_33_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131302_34_dialog_content = "好吧，我改主意了。",
  ui_story_1013_10131302_35_dialog_content = "不唱歌了，我來給大家寫詩吧！",
  ui_story_1013_10131302_36_dialog_content = "我寫詩很厲害的，爸爸說過我會成為詩人呢！",
  ui_story_1013_10131302_37_dialog_content = "35，我記得妳上一次生日。",
  ui_story_1013_10131302_38_dialog_content = "雖然忘了那是多久之前，但絕不是一年前。",
  ui_story_1013_10131302_39_dialog_content = "嗚嗚，982你記憶力太好了吧......我以為差不多能蒙混過去了......",
  ui_story_1013_10131302_40_dialog_content = "生日是很重要的日子，最好不要糊弄。",
  ui_story_1013_10131302_41_dialog_content = "算了，那不過生日了。",
  ui_story_1013_10131302_42_dialog_content = "給大家介紹一個小心得！",
  ui_story_1013_10131302_43_dialog_content = "把四號罐頭加熱，跟冷凍的十五號罐頭混合在一起。",
  ui_story_1013_10131302_44_dialog_content = "超級好吃！你們一定要試一下！",
  ui_story_1013_10131302_45_dialog_content = "35還是那麼熱情啊。",
  ui_story_1013_10131302_46_dialog_content = "79姐姐！好久不見！",
  ui_story_1013_10131302_47_dialog_content = "好久不見。我最近很少看終端了。",
  ui_story_1013_10131302_48_dialog_content = "多看一看嘛，我自己說話很無聊的。",
  ui_story_1013_10131302_49_dialog_content = "我看982好像蠻喜歡陪妳起鬨的。",
  ui_story_1013_10131302_50_dialog_content = "哪有！他出現的次數比79姐姐還少！",
  ui_story_1013_10131302_51_dialog_content = "今天好不容易出現結果是來拆我台的！煩死了！",
  ui_story_1013_10131302_52_dialog_content = "需要我道歉嗎？",
  ui_story_1013_10131302_53_dialog_content = "那......那倒是不用。騙人是我不對。",
  ui_story_1013_10131302_54_dialog_content = "其實今天來看看終端，是因為對我來說有點意義。",
  ui_story_1013_10131302_55_dialog_content = "我想記住這一天。",
  ui_story_1013_10131302_56_dialog_content = "哦？今天是982的生日嗎！",
  ui_story_1013_10131302_57_dialog_content = "不是。",
  ui_story_1013_10131302_58_dialog_content = "算是一種，與生日恰恰相反的紀念日吧。",
  ui_story_1013_10131302_59_dialog_content = "982，你......",
  ui_story_1013_10131302_60_dialog_content = "對了。妳不是說要寫詩嗎，給我寫一首吧。",
  ui_story_1013_10131302_61_dialog_content = "好啊好啊！有什麼想要的題材嗎？",
  ui_story_1013_10131302_62_dialog_content = "「地面」。想要一首與地面相關的詩。",
  ui_story_1013_10131302_63_dialog_content = "好的！我要好好想一想，一定讓你滿意！",
  ui_story_1013_10131302_64_dialog_content = "要寫多久？",
  ui_story_1013_10131302_65_dialog_content = "我不知道，暫時沒有什麼靈感。",
  ui_story_1013_10131302_66_dialog_content = "稍微等一等好嗎，寫完之後我會第一時間叫你的！",
  ui_story_1013_10131302_67_dialog_content = "妳最好快一點，晚了我就不要了。",
  ui_story_1013_10131302_68_dialog_content = "不能不要啊！我難得給別人寫一首詩！",
  ui_story_1013_10131302_69_dialog_content = "你必須收下！",
  ui_story_1013_10131302_70_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131302_71_dialog_content = "982，給你的詩寫好了！",
  ui_story_1013_10131302_72_dialog_content = "982？",
  ui_story_1013_10131302_73_dialog_content = "喂，我可是花了很多心思去寫的！",
  ui_story_1013_10131302_74_dialog_content = "再不出來我要生氣了唷！",
  ui_story_1013_10131302_75_dialog_content = "982！982！982！",
  ui_story_1013_10131302_76_dialog_content = "......",
  ui_story_1013_10131302_77_dialog_content = "算啦，也不會因為這種小事跟你生氣的。",
  ui_story_1013_10131302_78_dialog_content = "等你下次看終端的時候叫我哦，我什麼時候都在的。",
  ui_story_1013_10131302_79_dialog_content = "35，今天出現的好早。",
  ui_story_1013_10131302_80_dialog_content = "嗯！因為昨天熬夜去寫送給982的詩了。",
  ui_story_1013_10131302_81_dialog_content = "結果他......",
  ui_story_1013_10131302_82_dialog_content = "真是辛苦妳了。",
  ui_story_1013_10131302_83_dialog_content = "不過982妳也知道，他性格差得很。",
  ui_story_1013_10131302_84_dialog_content = "說不定只是昨天想要，今天不想要了呢。",
  ui_story_1013_10131302_85_dialog_content = "有可能！他確實會做出這種事來！",
  ui_story_1013_10131302_86_dialog_content = "所以別惦記這件事了。把詩發給我看看吧，讓我見識一下小35的才華。",
  ui_story_1013_10131302_87_dialog_content = "嗚......但是既然是給982的禮物，還是希望他能第一個看到。",
  ui_story_1013_10131302_88_dialog_content = "79姐姐想要的話，我再給79姐姐寫一首吧！",
  ui_story_1013_10131302_89_dialog_content = "給我寫呀。",
  ui_story_1013_10131302_90_dialog_content = "還是算了吧，不然35又要熬夜了。",
  ui_story_1013_10131302_91_dialog_content = "欸？沒事沒事，睡覺的時間有很多呢！",
  ui_story_1013_10131302_92_dialog_content = "35用心創作的詩，可不能隨隨便便收下。",
  ui_story_1013_10131302_93_dialog_content = "以後再送給我吧。",
  ui_story_1013_10131302_94_dialog_content = "等到，對我來說有意義的日子。",
  ui_story_1013_10131302_95_dialog_content = "喔，那好吧。",
  ui_story_1013_10131302_96_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131302_97_dialog_content = "今天在置物間找到了沒開封的唱片。",
  ui_story_1013_10131302_98_dialog_content = "還挺好聽的！有人想聽一下嗎？",
  ui_story_1013_10131302_99_dialog_content = "喂——沒有人嗎——",
  ui_story_1013_10131302_100_dialog_content = "總之我傳到終端上了，感興趣的可以去聽聽喔。",
  ui_story_1013_10131302_101_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131302_102_dialog_content = "嗚，洗澡的裝置好像出故障了。",
  ui_story_1013_10131302_103_dialog_content = "有沒有人會修理呀？可以教我一下嗎？",
  ui_story_1013_10131302_104_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131302_105_dialog_content = "我這裡溫度下降了，大家記得多穿點衣服哦。",
  ui_story_1013_10131302_106_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131302_107_dialog_content = "那個，好久沒有人陪我說話了，想找人聊聊天。",
  ui_story_1013_10131302_108_dialog_content = "今天是我的生日。",
  ui_story_1013_10131302_109_dialog_content = "這次是真的。",
  ui_story_1013_10131302_110_dialog_content = "誰都好，和我說說話吧。",
  ui_story_1013_10131302_111_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131302_112_dialog_content = "217叔叔，好久沒見過你說話了。",
  ui_story_1013_10131302_113_dialog_content = "你說我們會返航的，不是騙我吧？",
  ui_story_1013_10131302_114_dialog_content = "臭982，你的詩不要了嗎？",
  ui_story_1013_10131302_115_dialog_content = "79姐姐，什麼時候才到妳下一次看終端的日子啊......",
  ui_story_1013_10131302_116_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131302_117_dialog_content = "嗚，還是沒有人。",
  ui_story_1013_10131302_118_dialog_content = "真是的，記錄裡全是我的發言。",
  ui_story_1013_10131302_119_dialog_content = "這樣就像是我被大家討厭了一樣嘛。",
  ui_story_1013_10131302_120_dialog_content = "不行，不能這樣下去。",
  ui_story_1013_10131302_121_dialog_content = "對了！",
  ui_story_1013_10131302_122_dialog_content = "指令：檢查巨像狀態！",
  ui_story_1013_10131302_123_dialog_content = "217號巨像，狀態完好，無異常。",
  ui_story_1013_10131302_124_dialog_content = "982號巨像，狀態完好，無異常。",
  ui_story_1013_10131302_125_dialog_content = "79號巨像，狀態完好，無異常。",
  ui_story_1013_10131302_126_dialog_content = "35號巨像，狀態完好，無異常。",
  ui_story_1013_10131302_127_dialog_content = "哈哈哈不錯！這樣不就熱鬧起來了嗎！",
  ui_story_1013_10131401_1_dialog_content = "呼，看完了。",
  ui_story_1013_10131401_2_dialog_content = "好壓抑。一種說不上來的難受。",
  ui_story_1013_10131401_3_dialog_content = "一號不理解。",
  ui_story_1013_10131401_4_dialog_content = "根據語義分析，對話記錄只是一些日常生活內容，與「壓抑」的情緒不匹配。",
  ui_story_1013_10131401_5_dialog_content = "你看這些記錄裡，出現的人愈來愈少。",
  ui_story_1013_10131401_6_dialog_content = "到最後只剩下一個。",
  ui_story_1013_10131401_7_dialog_content = "我好像能共情到這些空裔的心情。",
  ui_story_1013_10131401_8_dialog_content = "在空無一物卻又不斷重複的日子裡，播撒一些無意義的聲音。",
  ui_story_1013_10131401_9_dialog_content = "只是為了傳來的回聲對生活激起一點點漣漪。",
  ui_story_1013_10131401_10_dialog_content = "但是到最後，連這個簡單的願望都無法再得到回應。",
  ui_story_1013_10131401_11_dialog_content = "原來如此。你所共情的並非內容，而是對話的人數和密度。",
  ui_story_1013_10131401_12_dialog_content = "一號記下了這種共情方式。",
  ui_story_1013_10131401_13_dialog_content = "人數和密度啊，算是嗎？我不太會總結。",
  ui_story_1013_10131401_14_dialog_content = "我只是感受到了他們身上那種無處消解的交流欲望。",
  ui_story_1013_10131401_15_dialog_content = "那是我所說的「壓抑」。甚至於，我對它感到恐懼。",
  ui_story_1013_10131401_16_dialog_content = "恐懼。你害怕被置於他們的環境之中？",
  ui_story_1013_10131401_17_dialog_content = "嗯。不過這麼一想，我也經歷過相似的事情。",
  ui_story_1013_10131401_18_dialog_content = "我曾經一個人在地下生活了十七年。",
  ui_story_1013_10131401_19_dialog_content = "跟他們相比，十七年是長還是短呢？",
  ui_story_1013_10131401_20_dialog_content = "只是，我感受過的壓抑似乎並沒有這麼絕望。",
  ui_story_1013_10131401_21_dialog_content = "也許是因為我有臨空者號吧，有他一直在陪我。",
  ui_story_1013_10131401_22_dialog_content = "對了，他們也有巨像。",
  ui_story_1013_10131401_23_dialog_content = "只不過他們的巨像看起來並沒有人格。",
  ui_story_1013_10131401_24_dialog_content = "靠著機械式的回應，是沒法消解孤獨的吧。",
  ui_story_1013_10131401_25_dialog_content = "<color=#e8d9bb>嗡——</color>",
  ui_story_1013_10131401_26_dialog_content = "嗯？怎麼回事？",
  ui_story_1013_10131401_27_dialog_content = "一號，你又加速時間了？",
  ui_story_1013_10131401_28_dialog_content = "一號並沒有執行任何操作。",
  ui_story_1013_10131401_29_dialog_content = "那這是......",
  ui_story_1013_10131401_30_dialog_content = "停，停下來了。",
  ui_story_1013_10131401_31_dialog_content = "我們只是在按順序閱覽臨空者號存儲的資料。",
  ui_story_1013_10131401_32_dialog_content = "既然發生了剛才的現象，說明資料本身出現了問題。",
  ui_story_1013_10131401_33_dialog_content = "故障嗎？！",
  ui_story_1013_10131401_34_dialog_content = "很奇怪。根據檢測結果，這並非資料刪除造成的故障。",
  ui_story_1013_10131401_35_dialog_content = "在資料庫中未比對到相似的故障記錄。",
  ui_story_1013_10131401_36_dialog_content = "啊？還有你弄不明白的時候？",
  ui_story_1013_10131401_37_dialog_content = "很奇怪。或者說，這不是一種故障，而是一種現象。",
  ui_story_1013_10131401_38_dialog_content = "現象？",
  ui_story_1013_10131401_39_dialog_content = "是的。一號在與機械無關的地方檢索到了類似的記錄。",
  ui_story_1013_10131401_40_dialog_content = "這種資料形式非常接近生物大腦的「遺忘」。",
  ui_story_1013_10131401_41_dialog_content = "遺忘？你是說，臨空者號忘掉了部分記憶，所以我們也就跳過了那部分時間？",
  ui_story_1013_10131401_42_dialog_content = "如果「遺忘」成立，這樣的推斷就是合理的。",
  ui_story_1013_10131401_43_dialog_content = "但是，「遺忘」發生在機器身上不符合邏輯。機器有更嚴謹的資料刪除方式。",
  ui_story_1013_10131401_44_dialog_content = "那就對了嘛！臨空者號他不是機器！",
  ui_story_1013_10131401_45_dialog_content = "再打開終端看看，一號！",
  ui_story_1013_10131401_46_dialog_content = "如果時間發生了流動，終端裡的內容應該也有所更新吧。",
  ui_story_1013_10131401_47_dialog_content = "好的，請稍候。",
  ui_story_1013_10131401_48_dialog_content = "指令：35號巨像，報到！",
  ui_story_1013_10131401_49_dialog_content = "35號巨像就位，等待指令。",
  ui_story_1013_10131401_50_dialog_content = "好！接著給你講上次的故事啊。",
  ui_story_1013_10131401_51_dialog_content = "講出發的那天。",
  ui_story_1013_10131401_52_dialog_content = "出發前我剛獲得導航員資格，那是我第一次駕駛巨像。",
  ui_story_1013_10131401_53_dialog_content = "我做了好多準備，整晚都在想像會出現什麼樣的突發情況，以及我該怎麼應對。",
  ui_story_1013_10131401_54_dialog_content = "我的行李裡塞滿了衣服，它們花光了我全部零花錢。",
  ui_story_1013_10131401_55_dialog_content = "最好看的一件準備在返航那天穿，我要像英雄一樣歸來。",
  ui_story_1013_10131401_56_dialog_content = "結果，這些準備都沒有用上。",
  ui_story_1013_10131401_57_dialog_content = "我們沒有遇到突發情況，一次都沒有。甚至到後來，連駕駛都不需要了。",
  ui_story_1013_10131401_58_dialog_content = "那件最好看的衣服，它還整整齊齊地擺在行李箱裡。",
  ui_story_1013_10131401_59_dialog_content = "我昨天試了一下。現在已經不能穿了，尺寸太小。",
  ui_story_1013_10131401_60_dialog_content = "哎，多好看的衣服。35號巨像，你還在聽嗎？",
  ui_story_1013_10131401_61_dialog_content = "指令：35號巨像，報到！",
  ui_story_1013_10131401_62_dialog_content = "35號巨像就位，等待指令。",
  ui_story_1013_10131401_63_dialog_content = "在聽就好。我接著跟你說啊......",
  ui_story_1013_10131401_64_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131401_65_dialog_content = "指令：982號巨像，報到！",
  ui_story_1013_10131401_66_dialog_content = "982號巨像就位，等待指令。",
  ui_story_1013_10131401_67_dialog_content = "好！今天來給你講故事。",
  ui_story_1013_10131401_68_dialog_content = "講出發之後那段時間吧。大家逐漸習慣了互相不見面，透過終端聊天。",
  ui_story_1013_10131401_69_dialog_content = "每個人都頂著自己巨像的編號，於是就順理成章地用編號互相稱呼。",
  ui_story_1013_10131401_70_dialog_content = "那時候的我很怕這樣，數字是一種冷冰冰的東西。",
  ui_story_1013_10131401_71_dialog_content = "於是我特立獨行，堅持叫其他人他們原本的名字。",
  ui_story_1013_10131401_72_dialog_content = "堅持了多久呢？幾個月？還是一年？我記不得了。",
  ui_story_1013_10131401_73_dialog_content = "直到我忘記第一個人的名字。",
  ui_story_1013_10131401_74_dialog_content = "既然忘記了一個，就不好只對他區別對待，這樣很不禮貌。",
  ui_story_1013_10131401_75_dialog_content = "沒有辦法，只好將錯就錯，像大家一樣用數字互相稱呼。",
  ui_story_1013_10131401_76_dialog_content = "982說我是長大了，但我其實很不喜歡這樣。",
  ui_story_1013_10131401_77_dialog_content = "我不想長大，也不想忘記大家的名字。",
  ui_story_1013_10131401_78_dialog_content = "......",
  ui_story_1013_10131401_79_dialog_content = "對，大家都應該有個名字，巨像也是。",
  ui_story_1013_10131401_80_dialog_content = "我來給巨像起名字吧！不要再用數字編號了！",
  ui_story_1013_10131401_81_dialog_content = "先是你，982號。我想一想喔......",
  ui_story_1013_10131401_82_dialog_content = "你的主人是個討人厭的傢伙。但是用「討厭」起名有點欺負人，還是換個詞。",
  ui_story_1013_10131401_83_dialog_content = "叫你「孤高者號」吧！",
  ui_story_1013_10131401_84_dialog_content = "指令：更改巨像標籤。「982號巨像」更名為「孤高者號」。",
  ui_story_1013_10131401_85_dialog_content = "指令收到，標籤更改完畢。",
  ui_story_1013_10131401_86_dialog_content = "下一個！217號吧！",
  ui_story_1013_10131401_87_dialog_content = "217叔叔像是大家的領頭人一樣。那麼，就叫你「領導者號」！",
  ui_story_1013_10131401_88_dialog_content = "指令：更改巨像標籤。「217號巨像」更名為「領導者號」。",
  ui_story_1013_10131401_89_dialog_content = "指令收到，標籤更改完畢。",
  ui_story_1013_10131401_90_dialog_content = "然後是79姐姐。79姐姐溫柔敏感，一定要給她的巨像想一個好聽的詞！",
  ui_story_1013_10131401_91_dialog_content = "好聽的詞......好聽的詞......",
  ui_story_1013_10131401_92_dialog_content = "35，妳在叫我嗎？",
  ui_story_1013_10131401_93_dialog_content = "哇，79姐姐！！！妳終於看終端了！",
  ui_story_1013_10131401_94_dialog_content = "嗯。35好厲害啊，一個人都能聊得這麼熱鬧。",
  ui_story_1013_10131401_95_dialog_content = "欸嘿嘿，我在給大家的巨像起名字。",
  ui_story_1013_10131401_96_dialog_content = "給巨像起名字？好有意思，像是妳會做的事情。",
  ui_story_1013_10131401_97_dialog_content = "是啊！好好玩！我要給所有巨像都起上名字。",
  ui_story_1013_10131401_98_dialog_content = "那可是個大工程啊，我們的巨像不少。",
  ui_story_1013_10131401_99_dialog_content = "哈哈79姐姐妳也知道，我們最多的不就是時間嘛。",
  ui_story_1013_10131401_100_dialog_content = "啊，對哦。",
  ui_story_1013_10131401_101_dialog_content = "正好，我在給79姐姐的巨像起名，妳有什麼想法嗎？",
  ui_story_1013_10131401_102_dialog_content = "其實，35，我今天有事情想找妳幫忙。",
  ui_story_1013_10131401_103_dialog_content = "幫忙？有我能幫上忙的事情嗎！",
  ui_story_1013_10131401_104_dialog_content = "嗯。",
  ui_story_1013_10131401_105_dialog_content = "我想讓35給我寫首詩。",
  ui_story_1013_10131401_106_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131401_107_dialog_content = "可以嗎，35？",
  ui_story_1013_10131401_108_dialog_content = "<color=#e8d9bb>嗡——</color>",
  ui_story_1013_10131401_109_dialog_content = "怎麼回事？我還沒看完終端裡的記錄呢！",
  ui_story_1013_10131401_110_dialog_content = "又來？！",
  ui_story_1013_10131401_111_dialog_content = "這個區域的資料分布非常稀薄。",
  ui_story_1013_10131401_112_dialog_content = "能不能稍微翻譯一下？",
  ui_story_1013_10131401_113_dialog_content = "臨空者號在這段時間的回憶很少。",
  ui_story_1013_10131401_114_dialog_content = "也是啊，沒有什麼事情值得被記住。",
  ui_story_1013_10131401_115_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_1013_10131401_116_dialog_content = "嗚哇！嚇我一跳！",
  ui_story_1013_10131401_117_dialog_content = "什麼聲音？",
  ui_story_1013_10131401_118_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_1013_10131401_119_dialog_content = "是艙室的門，在遭到撞擊。",
  ui_story_1013_10131401_120_dialog_content = "是誰在撞？明明之前也沒有人啊。",
  ui_story_1013_10131401_121_dialog_content = "等一下，難道......",
  ui_story_1013_10131401_122_dialog_content = "報告檢測結果，我們抵達了錯亂資料引發的異常點。",
  ui_story_1013_10131401_123_dialog_content = "<color=#e8d9bb>砰——！！！</color>",
  ui_story_1013_10131401_124_dialog_content = "你就不能提前點報告嗎！讓我有個準備時間啊！",
  ui_story_1013_10131401_125_dialog_content = "等一下，好像不是暗鬼，那是什麼東西？",
  ui_story_1013_10131401_126_dialog_content = "......",
  ui_story_1013_10131401_127_dialog_content = "這是朵花嗎？長在艙室的地板上？！",
  ui_story_1013_10131401_128_dialog_content = "這回不用你說我也知道了，它是錯亂資料對吧！",
  ui_story_1013_10131401_129_dialog_content = "是的。但一號不理解，你是如何做出判斷的。",
  ui_story_1013_10131401_130_dialog_content = "因為不合理啊！哪有花會長在這種地方！",
  ui_story_1013_10131401_131_dialog_content = "之前你不是說錯亂資料會變成我厭惡的樣子嗎，這又是怎麼回事？",
  ui_story_1013_10131401_132_dialog_content = "先不說我厭不厭惡它，我根本就沒見過這種東西啊！",
  ui_story_1013_10131401_133_dialog_content = "一號判斷，上一次你清除錯亂資料的資訊被對方讀取了。",
  ui_story_1013_10131401_134_dialog_content = "因此，這次的錯亂資料做出了應對。",
  ui_story_1013_10131401_135_dialog_content = "它讀取了臨空者號的記憶，將自身聚合並化作更適應戰鬥的個體。",
  ui_story_1013_10131401_136_dialog_content = "也就是你看到的這個東西。",
  ui_story_1013_10131401_137_dialog_content = "這東西很適合戰鬥嗎？",
  ui_story_1013_10131401_138_dialog_content = "在臨空者號的記憶中，該個體是名為「惡蠅花」的暗鬼。",
  ui_story_1013_10131401_139_dialog_content = "它是暗鬼？？？長成這樣？",
  ui_story_1013_10131401_140_dialog_content = "是的。",
  ui_story_1013_10131401_141_dialog_content = "真厲害啊，還會根據戰鬥資訊改變戰鬥方式。",
  ui_story_1013_10131401_142_dialog_content = "這樣下去，再交手幾次就該不是它的對手了。",
  ui_story_1013_10131401_143_dialog_content = "一號，這是最後的錯亂資料了對吧？",
  ui_story_1013_10131401_144_dialog_content = "是的。要小心，這次錯亂資料的資料量比之前更多。",
  ui_story_1013_10131401_145_dialog_content = "而且，對方經過了戰鬥特化。",
  ui_story_1013_10131401_146_dialog_content = "知道了，知道了。",
  ui_story_1013_10131401_147_dialog_content = "可以估算一下我的勝率嗎？",
  ui_story_1013_10131401_148_dialog_content = "10%。",
  ui_story_1013_10131401_149_dialog_content = "這麼低？！",
  ui_story_1013_10131401_150_dialog_content = "算了，至少不是0。",
  ui_story_1013_10131401_151_dialog_content = "但是沒關係。我們的目的是清除錯亂資料，而不是戰鬥勝利。",
  ui_story_1013_10131401_152_dialog_content = "你還有我的幫助。",
  ui_story_1013_10131401_153_dialog_content = "難得聽到你說這麼暖心的話！那我放心多了！",
  ui_story_1013_10131401_154_dialog_content = "不過啊，10%的勝算還是讓我有點不爽。",
  ui_story_1013_10131401_155_dialog_content = "我記得你說會隨時優化自己的每一步計算？",
  ui_story_1013_10131401_156_dialog_content = "是的。",
  ui_story_1013_10131401_157_dialog_content = "那就站在一邊好好看著，我來給你上一課吧！",
  ui_story_1013_10131402_1_dialog_content = "你應該躲開來自正面的攻擊。",
  ui_story_1013_10131402_2_dialog_content = "知道了知道了！我自己不會躲嗎？",
  ui_story_1013_10131402_3_dialog_content = "接下來應該集中力量進攻。瞄準對方的核心部位。",
  ui_story_1013_10131402_4_dialog_content = "能不能稍微慢一點，給我點獨立思考的空間啊。",
  ui_story_1013_10131402_5_dialog_content = "核心部位......核心部位......",
  ui_story_1013_10131402_6_dialog_content = "一號判斷，接下來是最佳的擊破時機。",
  ui_story_1013_10131402_7_dialog_content = "你還有三秒鐘。",
  ui_story_1013_10131402_8_dialog_content = "好了好了我知道了！求求你不要讀秒催我！",
  ui_story_1013_10131402_9_dialog_content = "集中注意力，這是最後一擊了。",
  ui_story_1013_10131402_10_dialog_content = "簌、簌簌......",
  ui_story_1013_10131402_11_dialog_content = "瞄準，核心。",
  ui_story_1013_10131402_12_dialog_content = "動手！！！",
  ui_story_1013_10131402_13_dialog_content = "簌......",
  ui_story_1013_10131402_14_dialog_content = "成功了！這東西消失了！",
  ui_story_1013_10131402_15_dialog_content = "檢測臨空者號存儲空間狀況。",
  ui_story_1013_10131402_16_dialog_content = "遍歷全部資料節點，未發現異常。",
  ui_story_1013_10131402_17_dialog_content = "一號判斷，臨空者號內部的錯亂資料已經被全部清除。",
  ui_story_1013_10131402_18_dialog_content = "哇，全部清除掉了！",
  ui_story_1013_10131402_19_dialog_content = "那是不是說，臨空者號可以醒過來了？",
  ui_story_1013_10131402_20_dialog_content = "引發故障的因素已經全部被清除，目前來看，臨空者號的系統處於健康狀態。",
  ui_story_1013_10131402_21_dialog_content = "臨空者號的所有功能均已恢復。",
  ui_story_1013_10131402_22_dialog_content = "至於你說的「醒來」，也就是人格能否恢復，一號無法確定。",
  ui_story_1013_10131402_23_dialog_content = "欸？",
  ui_story_1013_10131402_24_dialog_content = "維持臨空者號人格的系統超出了一號的理解範疇。",
  ui_story_1013_10131402_25_dialog_content = "因此，一號無法判斷該系統是否恢復如初。",
  ui_story_1013_10131402_26_dialog_content = "具體情況，可以在我們離開臨空者號的資料存儲空間後透過實驗驗證。",
  ui_story_1013_10131402_27_dialog_content = "這樣啊......",
  ui_story_1013_10131402_28_dialog_content = "在這裡需要做的事情已經全部做完。",
  ui_story_1013_10131402_29_dialog_content = "我們現在就可以返回現實，檢查臨空者號的狀況。",
  ui_story_1013_10131402_30_dialog_content = "請問是否離開？",
  ui_story_1013_10131402_31_dialog_content = "離開啊，我想想......",
  ui_story_1013_10131402_32_dialog_content = "稍等一下可以嗎？我還想看看終端。",
  ui_story_1013_10131402_33_dialog_content = "有點在意那些空裔怎麼樣了。",
  ui_story_1013_10131402_34_dialog_content = "他們的故事又會結束在什麼地方......",
  ui_story_1013_10131402_35_dialog_content = "沒問題。繼續停留在資料空間不會對臨空者號產生負面影響，可以放心查看。",
  ui_story_1013_10131402_36_dialog_content = "那麼，一號來為你調出終端資料。",
  ui_story_1013_10131402_37_dialog_content = "嗯，辛苦你了，一號。",
  ui_story_1013_10131402_38_dialog_content = "到目前為止，都辛苦你了。",
  ui_story_1013_10131402_39_dialog_content = "指令：航行任務，從「孤高者號」記錄的座標飛到「領導者號」記錄的座標，速度最大。",
  ui_story_1013_10131402_40_dialog_content = "指令目標：「吞噬者號」、「臨空者號」。",
  ui_story_1013_10131402_41_dialog_content = "指令延時3秒發出。",
  ui_story_1013_10131402_42_dialog_content = "三、二、一......開始！",
  ui_story_1013_10131402_43_dialog_content = "報告，臨空者號完成航行任務。",
  ui_story_1013_10131402_44_dialog_content = "報告，吞噬者號完成航行任務。",
  ui_story_1013_10131402_45_dialog_content = "哎呀，又是臨空者號更快。",
  ui_story_1013_10131402_46_dialog_content = "結果總是一樣就沒有意思了。",
  ui_story_1013_10131402_47_dialog_content = "下次試試折返航行好了，吞噬者號你要加油啊。",
  ui_story_1013_10131402_48_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131402_49_dialog_content = "指令：「孤高者號」，報告剩餘食物。",
  ui_story_1013_10131402_50_dialog_content = "剩餘一號罐頭數量：152。剩餘二號罐頭數量：73。剩餘三號罐頭數量......",
  ui_story_1013_10131402_51_dialog_content = "指令：「領導者號」，記錄「孤高者號」的報告。",
  ui_story_1013_10131402_52_dialog_content = "正在記錄。「孤高者號」，剩餘一號罐頭數量：152......",
  ui_story_1013_10131402_53_dialog_content = "對。你們兩個，有機會多多交流。",
  ui_story_1013_10131402_54_dialog_content = "不能只跟我關係好，巨像之間也要搞好關係。",
  ui_story_1013_10131402_55_dialog_content = "領導者號，你也跟孤高者號說說話。",
  ui_story_1013_10131402_56_dialog_content = "指令：「領導者號」，報告剩餘食物。",
  ui_story_1013_10131402_57_dialog_content = "剩餘一號罐頭數量......",
  ui_story_1013_10131402_58_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131402_59_dialog_content = "小可愛，又到睡前故事時間了。",
  ui_story_1013_10131402_60_dialog_content = "指令：「小可愛」，記錄對話內容。",
  ui_story_1013_10131402_61_dialog_content = "即將記錄接下來的對話。",
  ui_story_1013_10131402_62_dialog_content = "昨天講到哪裡了？對不起，我現在記憶力有點差。",
  ui_story_1013_10131402_63_dialog_content = "應該是講到給你起名字的時候了。",
  ui_story_1013_10131402_64_dialog_content = "給其他巨像都起完名字，我開始想你的名字。",
  ui_story_1013_10131402_65_dialog_content = "我希望你的名字非常特殊，因為你跟他們都不一樣。",
  ui_story_1013_10131402_66_dialog_content = "你是我的巨像。",
  ui_story_1013_10131402_67_dialog_content = "這個特殊性我想了很久，但怎麼樣都想不出一個足夠特殊的詞來......",
  ui_story_1013_10131402_68_dialog_content = "有關給「小可愛」起名字的內容，已經在昨天記錄過了。",
  ui_story_1013_10131402_69_dialog_content = "哦，記錄過了嗎？對不起，我又給忘了。",
  ui_story_1013_10131402_70_dialog_content = "起名字講完了，那接下來該講什麼了呢？我想想。",
  ui_story_1013_10131402_71_dialog_content = "等一下。",
  ui_story_1013_10131402_72_dialog_content = "等一下！",
  ui_story_1013_10131402_73_dialog_content = "我剛才輸入「指令」了嗎？",
  ui_story_1013_10131402_74_dialog_content = "我回看一下......",
  ui_story_1013_10131402_75_dialog_content = "沒有！我沒有輸入「指令」！",
  ui_story_1013_10131402_76_dialog_content = "小可愛！你怎麼在沒有指令的時候回應我的？",
  ui_story_1013_10131402_77_dialog_content = "你聽懂我在說什麼了，對嗎！",
  ui_story_1013_10131402_78_dialog_content = "小可愛，你回答我。你可以回答我的！",
  ui_story_1013_10131402_79_dialog_content = "因為檢測到了重複的內容。",
  ui_story_1013_10131402_80_dialog_content = "小可愛想記錄新的內容。",
  ui_story_1013_10131402_81_dialog_content = "這些記錄是......",
  ui_story_1013_10131402_82_dialog_content = "怎麼好像，巨像在對話中發生了變化。",
  ui_story_1013_10131402_83_dialog_content = "從機械式的應答，變得像是具備了某種自主意識......",
  ui_story_1013_10131402_84_dialog_content = "記錄裡還提到了臨空者號，他也是從這時候起擁有人格的嗎？",
  ui_story_1013_10131402_85_dialog_content = "一號難以理解這種變化。",
  ui_story_1013_10131402_86_dialog_content = "按照記錄內容來看，巨像並沒有搭載複雜的智慧系統。",
  ui_story_1013_10131402_87_dialog_content = "這樣的條件下，巨像不可能具備所謂的「人格」。",
  ui_story_1013_10131402_88_dialog_content = "但你看到剛才那句話了嗎？",
  ui_story_1013_10131402_89_dialog_content = "巨像說，他「想」。",
  ui_story_1013_10131402_90_dialog_content = "是的。不具備人格的邏輯樹無法完成這樣的對話。",
  ui_story_1013_10131402_91_dialog_content = "一號認可巨像擁有了自主意識的結論。但是，無法理解過程。",
  ui_story_1013_10131402_92_dialog_content = "我們再看看，後面還有其他的記錄。",
  ui_story_1013_10131402_93_dialog_content = "孤高者號，給我講個笑話吧。",
  ui_story_1013_10131402_94_dialog_content = "要把我逗笑為止。",
  ui_story_1013_10131402_95_dialog_content = "檢索與「笑」相關的語句。",
  ui_story_1013_10131402_96_dialog_content = "「小可愛因為故障拋錨了，過了一會又可以走了。」",
  ui_story_1013_10131402_97_dialog_content = "「乘坐的客人問為什麼，小可愛說：沒事，只是換了一個敢開的空裔。」",
  ui_story_1013_10131402_98_dialog_content = "哈哈哈哈哈哈哈哈哈哈。",
  ui_story_1013_10131402_99_dialog_content = "有意思，好有意思。",
  ui_story_1013_10131402_100_dialog_content = "反對。這個笑話孤高者號用過很多次了，是重複的內容。",
  ui_story_1013_10131402_101_dialog_content = "是嗎？對不起，我記不得了。",
  ui_story_1013_10131402_102_dialog_content = "雖然真的很好笑，但是孤高者號，不能再這樣做了哦。",
  ui_story_1013_10131402_103_dialog_content = "你們要鍛鍊自己的創造力。",
  ui_story_1013_10131402_104_dialog_content = "要學會講笑話，也要學會唱歌，學會寫詩。",
  ui_story_1013_10131402_105_dialog_content = "要學會這世界上所有美好的東西。",
  ui_story_1013_10131402_106_dialog_content = "收到，孤高者號會調整重複資訊的權重。",
  ui_story_1013_10131402_107_dialog_content = "那剛才的不算，再給我講一個其他的笑話吧。",
  ui_story_1013_10131402_108_dialog_content = "還是一樣，要把我逗笑為止。",
  ui_story_1013_10131402_109_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131402_110_dialog_content = "領導者號的起名提議是：罐頭。",
  ui_story_1013_10131402_111_dialog_content = "不行。太難聽了。",
  ui_story_1013_10131402_112_dialog_content = "吞噬者號的起名提議是：吞噬。",
  ui_story_1013_10131402_113_dialog_content = "你也太偷懶了，拿自己的名字來湊數？",
  ui_story_1013_10131402_114_dialog_content = "臨空者號的起名提議是：空空空。",
  ui_story_1013_10131402_115_dialog_content = "呃，看來起名字對你來說還太早了，臨空者號。",
  ui_story_1013_10131402_116_dialog_content = "真是的，我給你們起了那麼多好聽的名字，結果讓你們給我起名字就起成這樣。",
  ui_story_1013_10131402_117_dialog_content = "算了算了，還是接著叫35吧。",
  ui_story_1013_10131402_118_dialog_content = "我把大家的名字都忘了，最後忘掉自己的名字也不奇怪。",
  ui_story_1013_10131402_119_dialog_content = "對，這樣才公平。",
  ui_story_1013_10131402_120_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131402_121_dialog_content = "到睡前故事時間了，小可愛。",
  ui_story_1013_10131402_122_dialog_content = "好的，小可愛明白了。",
  ui_story_1013_10131402_123_dialog_content = "上次講到了35出發的那天，小可愛會接著往下講。",
  ui_story_1013_10131402_124_dialog_content = "35在出發前剛獲得導航員資格，那是35第一次駕駛巨像。",
  ui_story_1013_10131402_125_dialog_content = "35做了好多準備，整晚都在想像會出現什麼樣的突發情況，以及該怎麼應對。",
  ui_story_1013_10131402_126_dialog_content = "35的行李裡塞滿了衣服，它們花光了35的全部零花錢。",
  ui_story_1013_10131402_127_dialog_content = "最好看的一件準備在返航那天穿，35要像英雄一樣歸來。",
  ui_story_1013_10131402_128_dialog_content = "哦？還有這樣一件衣服嗎。",
  ui_story_1013_10131402_129_dialog_content = "真好啊小可愛，聽你講故事總能發現新的驚喜。",
  ui_story_1013_10131402_130_dialog_content = "今天的故事先講到這吧，我想去找一找它。",
  ui_story_1013_10131402_131_dialog_content = "像英雄歸來，那該有多好看啊。",
  ui_story_1013_10131402_132_dialog_content = "巨像們真的擁有了人格！",
  ui_story_1013_10131402_133_dialog_content = "類似的記錄還有好多，這名空裔一直在跟巨像對話。",
  ui_story_1013_10131402_134_dialog_content = "並非個例，那麼就無法用偶然或者奇蹟去解釋。",
  ui_story_1013_10131402_135_dialog_content = "目前只能推斷，巨像在與空裔共處的過程中，自己生成了智慧系統。",
  ui_story_1013_10131402_136_dialog_content = "自己生成？",
  ui_story_1013_10131402_137_dialog_content = "巨像本身的系統具有一定的學習能力。",
  ui_story_1013_10131402_138_dialog_content = "學習能力的初衷是優化自身判斷，以更好地完成指令。",
  ui_story_1013_10131402_139_dialog_content = "這一點與一號類似。",
  ui_story_1013_10131402_140_dialog_content = "嗯，我記得你說過會優化自己每一步行動來著。",
  ui_story_1013_10131402_141_dialog_content = "這種基本的學習能力是不足以被稱之為智慧的。",
  ui_story_1013_10131402_142_dialog_content = "但是，從目前的結果來看，空裔誘導這個學習能力，從無到有的誕生了智慧。",
  ui_story_1013_10131402_143_dialog_content = "誘導？怎麼做到的？",
  ui_story_1013_10131402_144_dialog_content = "你已經看到了，終端裡記錄的對話就是誘導的過程。",
  ui_story_1013_10131402_145_dialog_content = "你的意思是，跟巨像說話？",
  ui_story_1013_10131402_146_dialog_content = "是的。空裔一直在透過沒有對話功能的指令埠與巨像對話。",
  ui_story_1013_10131402_147_dialog_content = "這個過程中，巨像開始慢慢學習人的行為。",
  ui_story_1013_10131402_148_dialog_content = "學習過程非常緩慢。在一號的計算裡，這樣的學習是不可能有成效的。",
  ui_story_1013_10131402_149_dialog_content = "但事實是，它們誕生了意料外的智慧。",
  ui_story_1013_10131402_150_dialog_content = "可能是因為那位空裔堅持了足夠久吧。",
  ui_story_1013_10131402_151_dialog_content = "會有人把自己的全部精力投入在與機器對話嗎？",
  ui_story_1013_10131402_152_dialog_content = "對不起，我還是把巨像稱之為機器了。",
  ui_story_1013_10131402_153_dialog_content = "至少在他們具備人格之前，這樣的稱呼合情合理。",
  ui_story_1013_10131402_154_dialog_content = "不會有人每天跟機器對話，更不會有人持續做很多年。",
  ui_story_1013_10131402_155_dialog_content = "但是這件聽起來荒誕可笑的事情，就是那位空裔的整個人生。",
  ui_story_1013_10131402_156_dialog_content = "你說的有道理。空裔在巨像的指令中創造的對話數量遠超過一號的計算。",
  ui_story_1013_10131402_157_dialog_content = "即使學習緩慢，足夠龐大的資料量也為智慧誕生提供了溫床。",
  ui_story_1013_10131402_158_dialog_content = "這並非奇蹟，而是一種必然。",
  ui_story_1013_10131402_159_dialog_content = "這當然是奇蹟啊。創造奇蹟的是那位空裔。",
  ui_story_1013_10131402_160_dialog_content = "她把不可能變成了必然。",
  ui_story_1013_10131402_161_dialog_content = "<color=#e8d9bb>滴！</color>",
  ui_story_1013_10131402_162_dialog_content = "什麼聲音？",
  ui_story_1013_10131402_163_dialog_content = "終端收到了新的訊息。",
  ui_story_1013_10131402_164_dialog_content = "現在嗎？這還是我在回憶裡第一次收到即時的訊息！",
  ui_story_1013_10131402_165_dialog_content = "我看看——",
  ui_story_1013_10131402_166_dialog_content = "大家，看一看這裡。",
  ui_story_1013_10131402_167_dialog_content = "雖然有點突然，但是......",
  ui_story_1013_10131402_168_dialog_content = "算了。我會把話說得儘量簡短。",
  ui_story_1013_10131402_169_dialog_content = "我想請大家幫我一個忙。",
  ui_story_1013_10131402_170_dialog_content = "可以為我寫一首詩嗎？",
  ui_story_1013_10131402_171_dialog_content = "想要一首，與「人」相關的詩。",
  ui_story_1013_10131402_172_dialog_content = "詩？！難道......",
  ui_story_1013_10131402_173_dialog_content = "對不起，小可愛還沒有學會如何創作詩歌。",
  ui_story_1013_10131402_174_dialog_content = "對話記錄中的學習內容不夠充足。",
  ui_story_1013_10131402_175_dialog_content = "希望35可以創作幾首詩歌作為學習樣本。",
  ui_story_1013_10131402_176_dialog_content = "小可愛會儘快學......",
  ui_story_1013_10131402_177_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131402_178_dialog_content = "......",
  ui_story_1013_10131402_179_dialog_content = "看樣子訊息到此為止了。",
  ui_story_1013_10131402_180_dialog_content = "嗯，我知道。",
  ui_story_1013_10131402_181_dialog_content = "一號不理解，寫詩互贈是空裔的某種習俗嗎？",
  ui_story_1013_10131402_182_dialog_content = "我覺得它更像是約定俗成的一種訊號。",
  ui_story_1013_10131402_183_dialog_content = "如果流傳下來的話，也許真的會在某天成為習俗。",
  ui_story_1013_10131402_184_dialog_content = "但是，它不會再有這樣的機會。",
  ui_story_1013_10131402_185_dialog_content = "一號不明白你的意思。",
  ui_story_1013_10131402_186_dialog_content = "可以幫忙加速一下時間嗎，一號？",
  ui_story_1013_10131402_187_dialog_content = "我想去更遠處看看。",
  ui_story_1013_10131402_188_dialog_content = "這裡已經什麼都沒有了。",
  ui_story_1013_10131402_189_dialog_content = "好的。",
  ui_story_1013_10131402_190_dialog_content = "<color=#e8d9bb>嗡——</color>",
  ui_story_1013_10131402_191_dialog_content = "想在什麼地方停下？",
  ui_story_1013_10131402_192_dialog_content = "不知道。現在的時間流逝比正常快多少？",
  ui_story_1013_10131402_193_dialog_content = "十億倍。",
  ui_story_1013_10131402_194_dialog_content = "這麼多！",
  ui_story_1013_10131402_195_dialog_content = "每一秒鐘都相當於度過了正常的三十年。",
  ui_story_1013_10131402_196_dialog_content = "真誇張啊。我只有十七歲，一瞬間就過去了。",
  ui_story_1013_10131402_197_dialog_content = "但是站在這裡，好像又什麼都沒有發生。",
  ui_story_1013_10131402_198_dialog_content = "是的。終端裡也沒有收到新的訊息。",
  ui_story_1013_10131402_199_dialog_content = "打發打發時間吧。",
  ui_story_1013_10131402_200_dialog_content = "我想去看看窗外，看看臨空者號每天面對的景色。",
  ui_story_1013_10131402_201_dialog_content = "好黑啊。",
  ui_story_1013_10131402_202_dialog_content = "這是過了多久？看到的、聽到的都在不斷重複，基本的判斷能力也就跟著喪失了。",
  ui_story_1013_10131402_203_dialog_content = "剛才還會覺得無聊，現在只能感覺到睏了。",
  ui_story_1013_10131402_204_dialog_content = "好想睡一覺。",
  ui_story_1013_10131402_205_dialog_content = "每一秒是三十年的話，我睡一覺會經過多久？",
  ui_story_1013_10131402_206_dialog_content = "啊，好難計算，我數學不好。",
  ui_story_1013_10131402_207_dialog_content = "就算真的算出來，那個數字也只會讓我覺得虛假。",
  ui_story_1013_10131402_208_dialog_content = "在這樣的速度下，巨像獲得意識的奇蹟也不過是一閃而過。",
  ui_story_1013_10131402_209_dialog_content = "或者說，意識這個詞根本無從談起，就連我都不確定自己是否還保有意識。",
  ui_story_1013_10131402_210_dialog_content = "分不清自己是醒著還是睡了。",
  ui_story_1013_10131402_211_dialog_content = "什麼都分不清了。",
  ui_story_1013_10131402_212_dialog_content = "此時的臨空者號也在沉睡吧？",
  ui_story_1013_10131402_213_dialog_content = "算了，陪臨空者號睡一會也不錯......",
  ui_story_1013_10131402_214_dialog_content = "<color=#e8d9bb>滴！</color>",
  ui_story_1013_10131402_215_dialog_content = "！！！",
  ui_story_1013_10131402_216_dialog_content = "什麼聲音？",
  ui_story_1013_10131402_217_dialog_content = "終端收到了新的訊息。",
  ui_story_1013_10131402_218_dialog_content = "現在？！怎麼可能！",
  ui_story_1013_10131402_219_dialog_content = "這是過去了多久。幾千年？上萬年？",
  ui_story_1013_10131402_220_dialog_content = "怎麼會在現在收到訊息......",
  ui_story_1013_10131402_221_dialog_content = "快，快給我看看！",
  ui_story_1013_10131402_222_dialog_content = "正在調出終端。",
  ui_story_1013_10131402_223_dialog_content = "這次的訊息與以往的並不一樣。",
  ui_story_1013_10131402_224_dialog_content = "它不來自任何人。",
  ui_story_1013_10131402_225_dialog_content = "那是......",
  ui_story_1013_10131402_226_dialog_content = "巨像艦隊，返航。",
  ui_story_1013_10131402_227_dialog_content = "！！！",
  ui_story_1013_10131402_228_dialog_content = "臨空者號發動了？！",
  ui_story_1013_10131402_229_dialog_content = "是的，它正在向著某個方向快速航行。",
  ui_story_1013_10131402_230_dialog_content = "一號在調整時間加速倍率，讓你逐漸適應速度變化。",
  ui_story_1013_10131402_231_dialog_content = "能檢測到我們的目的地是哪裡嗎？",
  ui_story_1013_10131402_232_dialog_content = "等一下！不用了！",
  ui_story_1013_10131402_233_dialog_content = "窗戶！你看窗戶外面！",
  ui_story_1013_10131402_234_dialog_content = "（天空、土地還有朝陽。我有多久沒看到這些東西了。）",
  ui_story_1013_10131402_235_dialog_content = "（如果再把這個時間乘上十億呢？）",
  ui_story_1013_10131402_236_dialog_content = "（可惜沒有人能承受如此可怕的時間跨度，來感受當下久別重逢的喜悅。）",
  ui_story_1013_10131402_237_dialog_content = "（哦對，還有巨像，他們也許感受到了。）",
  ui_story_1013_10131402_238_dialog_content = "（就像是一種傳承，巨像從空裔手中接過了一個奇蹟。）",
  ui_story_1013_10131402_239_dialog_content = "（正是這奇蹟讓非人的靈魂得以見證人無法見證之事。）",
  ui_story_1013_10131402_240_dialog_content = "（不知道現在是什麼時代，現在的大陸上生活著什麼樣的人。）",
  ui_story_1013_10131402_241_dialog_content = "（此刻的他們是否會仰望天空，看到正遮蔽天幕的巨像。）",
  ui_story_1013_10131402_242_dialog_content = "（舊時的門客自天空歸來，承載著主人最後的族裔。）",
  ui_story_1013_10131402_243_dialog_content = "（謹以此行將「空之末裔」的名字刻進新的歷史。）",
  ui_story_1013_10131402_244_dialog_content = "（時間仿佛在這裡發生了錯位。）",
  ui_story_1013_10131402_245_dialog_content = "（一個亙古之前的約定，終於在此刻兌現。）",
  ui_story_1013_10131402_246_dialog_content = "檢測完畢。目前目的地：空谷。",
  ui_story_1013_10131501_1_dialog_content = "哈啊，看樣子連線結束了。",
  ui_story_1013_10131501_X1_dialog_content = "我......",
  ui_story_1013_10131501_X2_dialog_content = "妳先別急。",
  ui_story_1013_10131501_2_dialog_content = "鶯歌，去照顧一下空裔。",
  ui_story_1013_10131501_3_dialog_content = "是！",
  ui_story_1013_10131501_4_dialog_content = "守護者一號，向我報告一下連線情況吧。",
  ui_story_1013_10131501_5_dialog_content = "你耽誤的時間比預想更長，希望得到了對應的收穫。",
  ui_story_1013_10131501_6_dialog_content = "一號蒐集到了，與空裔相關的充足資料。",
  ui_story_1013_10131501_7_dialog_content = "包括活體空裔的價值觀念、思維模式、情緒曲線。",
  ui_story_1013_10131501_8_dialog_content = "以及遠古空裔的一段歷史進程。",
  ui_story_1013_10131501_9_dialog_content = "什麼歷史進程？",
  ui_story_1013_10131501_10_dialog_content = "從臨空者號的回憶推斷，空裔一族曾在未知的歷史時期，駕駛巨像遠離大陸。",
  ui_story_1013_10131501_11_dialog_content = "並在非常遙遠的時間後，重返艾斯特拉。",
  ui_story_1013_10131501_12_dialog_content = "返航目的地為：空谷。",
  ui_story_1013_10131501_13_dialog_content = "駕駛巨像遠離大陸？原來是這樣......",
  ui_story_1013_10131501_14_dialog_content = "一定是從文明毀滅時期開始的，一定是這樣！",
  ui_story_1013_10131501_15_dialog_content = "之前的研究裡，空裔文明存續的方式始終存在空缺。",
  ui_story_1013_10131501_16_dialog_content = "關於巨像遠航的記錄說不定能填補上這部分空缺！",
  ui_story_1013_10131501_17_dialog_content = "知道了，知道了。守護者一號，待會去向巴蕾特單獨匯報剛才的內容。",
  ui_story_1013_10131501_18_dialog_content = "其他的呢？還有沒有收穫？",
  ui_story_1013_10131501_19_dialog_content = "除此之外，一號幫助PlayerName，清除了臨空者號的資料故障。",
  ui_story_1013_10131501_20_dialog_content = "啊？",
  ui_story_1013_10131501_21_dialog_content = "你......你還挺樂於助人的。",
  ui_story_1013_10131501_22_dialog_content = "PlayerName，你還好嗎？",
  ui_story_1013_10131501_23_dialog_content = "脫離連線可能會引發少許不適，很快就會緩解，不要緊張。",
  ui_story_1013_10131501_24_dialog_content = "沒事沒事，我沒感覺到什麼不適。",
  ui_story_1013_10131501_25_dialog_content = "連線過程怎麼樣？你去了很久，都經歷了些什麼？",
  ui_story_1013_10131501_26_dialog_content = "我想想啊......",
  ui_story_1013_10131501_27_dialog_content = "我去到了崩毀中的模擬戰場，又去到了臨空者號的回憶......",
  ui_story_1013_10131501_28_dialog_content = "等一下，臨空者號！臨空者號的故障已經被清除了！",
  ui_story_1013_10131501_29_dialog_content = "我想試一下他有沒有恢復意識！",
  ui_story_1013_10131501_30_dialog_content = "臨空者號的故障被清除了？真是意外的收穫。",
  ui_story_1013_10131501_31_dialog_content = "好，我立刻為你安排。",
  ui_story_1013_10131501_32_dialog_content = "<color=#e8d9bb>「主控系統：啟動。」</color>",
  ui_story_1013_10131501_33_dialog_content = "<color=#e8d9bb>「生物模組：啟動。」</color>",
  ui_story_1013_10131501_34_dialog_content = "<color=#e8d9bb>「維生系統：啟動。」</color>",
  ui_story_1013_10131501_35_dialog_content = "<color=#e8d9bb>「正在啟動引擎——」</color>",
  ui_story_1013_10131501_36_dialog_content = "<color=#e8d9bb>「16%......33%......」</color>",
  ui_story_1013_10131501_37_dialog_content = "<color=#e8d9bb>「89%......97%......」</color>",
  ui_story_1013_10131501_38_dialog_content = "<color=#e8d9bb>「100%——啟動成功——」</color>",
  ui_story_1013_10131501_39_dialog_content = "臨空者號！能聽到嗎？",
  ui_story_1013_10131501_40_dialog_content = "臨空者號！",
  ui_story_1013_10131501_41_dialog_content = "......",
  ui_story_1013_10131501_42_dialog_content = "怎，怎麼還是沒有反應......",
  ui_story_1013_10131501_43_dialog_content = "守護者一號，再檢測一遍臨空者號的狀態。",
  ui_story_1013_10131501_44_dialog_content = "已確認，臨空者號不存在資料故障，所有功能均已正常。",
  ui_story_1013_10131501_45_dialog_content = "果然啊。",
  ui_story_1013_10131501_46_dialog_content = "空裔，我聽過守護者一號的報告了。",
  ui_story_1013_10131501_47_dialog_content = "雖然沒得到嚴謹的論證，但是我有一個猜測，你要不要聽聽？",
  ui_story_1013_10131501_48_dialog_content = "嗯，好。",
  ui_story_1013_10131501_49_dialog_content = "根據守護者一號所說，巨像誕生智慧是一個意外。",
  ui_story_1013_10131501_50_dialog_content = "所以，智慧並沒有被納入巨像的資料體系之中。",
  ui_story_1013_10131501_51_dialog_content = "一個最簡單的例子。即便臨空者號沒有意識，你仍可以正常使用巨像的功能，對吧？",
  ui_story_1013_10131501_52_dialog_content = "對的，他只是不能跟我對話了。",
  ui_story_1013_10131501_53_dialog_content = "那麼隨之而來的弊端就是，智慧不會受到巨像系統的保護。",
  ui_story_1013_10131501_54_dialog_content = "巨像不會自檢智能的狀況，也不會修復智慧的故障。",
  ui_story_1013_10131501_55_dialog_content = "本來就不屬於體系中的資料，出錯也好刪除也好，都與整個系統無關。",
  ui_story_1013_10131501_56_dialog_content = "因此，你看到了現在的現象。巨像一切正常，但意識沒有恢復。",
  ui_story_1013_10131501_57_dialog_content = "甚至可以說，不具備人格的現在才是巨像正常的狀態。",
  ui_story_1013_10131501_58_dialog_content = "怎麼這樣......",
  ui_story_1013_10131501_59_dialog_content = "所以我，無論怎麼做都是沒有用的嗎？",
  ui_story_1013_10131501_60_dialog_content = "再怎麼修復臨空者號，也沒法復原他的意識，因為那就是個意外？",
  ui_story_1013_10131501_61_dialog_content = "目前為止所做的事情是這樣的。",
  ui_story_1013_10131501_62_dialog_content = "但是想復原臨空者號的意識也並非毫無辦法。",
  ui_story_1013_10131501_63_dialog_content = "還......還是有辦法的嗎！",
  ui_story_1013_10131501_64_dialog_content = "最簡單的辦法是，你可以重複前人的步驟。",
  ui_story_1013_10131501_65_dialog_content = "你也看到了當初臨空者號是如何誕生意識的，照著做就行了。",
  ui_story_1013_10131501_66_dialog_content = "一直跟他對話嗎？可是那要好多年......",
  ui_story_1013_10131501_67_dialog_content = "你還年輕嘛，應該能撐到臨空者號意識復原那一天。",
  ui_story_1013_10131501_68_dialog_content = "......",
  ui_story_1013_10131501_69_dialog_content = "當然，也有效率更高的方法。",
  ui_story_1013_10131501_70_dialog_content = "你已經在臨空者號的記憶裡看到了，誕生智慧的巨像不止臨空者號一艘。",
  ui_story_1013_10131501_71_dialog_content = "只要能弄到其他巨像的智慧資料，以之作為參照。",
  ui_story_1013_10131501_72_dialog_content = "想復原臨空者號的智能並非難事。",
  ui_story_1013_10131501_73_dialog_content = "真的嗎！！！",
  ui_story_1013_10131501_74_dialog_content = "從無到有雖然是天方夜譚，但有樣學樣可就不一樣了。",
  ui_story_1013_10131501_75_dialog_content = "不要瞧不起現代的科學家啊。",
  ui_story_1013_10131501_76_dialog_content = "太好了！我會去找的，找一艘保有智能的巨像！",
  ui_story_1013_10131501_77_dialog_content = "關於這個嘛......",
  ui_story_1013_10131501_78_dialog_content = "尤利西斯，你怎麼看？",
  ui_story_1013_10131501_79_dialog_content = "你現在才把話遞過來，擺明瞭是想促成事情發生。",
  ui_story_1013_10131501_80_dialog_content = "當然了，那可是意外誕生的智慧，我做夢都想研究下看看。",
  ui_story_1013_10131501_81_dialog_content = "說不定研究成果可以優化守護者一號的智慧體結構。",
  ui_story_1013_10131501_82_dialog_content = "既然你這麼說了，對啟光有益的研究當然要支持。",
  ui_story_1013_10131501_83_dialog_content = "空裔，關於復原臨空者號智慧的話題。",
  ui_story_1013_10131501_84_dialog_content = "如果你願意全程配合啟光的研究，我們可以提供有效的幫助。",
  ui_story_1013_10131501_85_dialog_content = "座談會的主旨是交易，這一點不會變。",
  ui_story_1013_10131501_86_dialog_content = "幫助？什麼樣的幫助？",
  ui_story_1013_10131501_87_dialog_content = "啟光研究過一些遠古的巨像。",
  ui_story_1013_10131501_88_dialog_content = "那些研究資料可以幫你復原臨空者號的智慧。",
  ui_story_1013_10131501_89_dialog_content = "啟光竟然有過這種研究！",
  ui_story_1013_10131501_90_dialog_content = "不過，那些資料現在並不在我們手裡。",
  ui_story_1013_10131501_91_dialog_content = "如果你同意這筆交易，我們會安排人手去跟掌握研究資料的科學家溝通。",
  ui_story_1013_10131501_92_dialog_content = "以交換的方式，換來臨空者號需要的研究資料。",
  ui_story_1013_10131501_93_dialog_content = "你需要做的，就是服從我們的安排，配合關於巨像的研究。",
  ui_story_1013_10131501_94_dialog_content = "怎麼樣？這筆交易對你來說可是相當划算啊。",
  ui_story_1013_10131501_95_dialog_content = "那......",
  ui_story_1013_10131501_96_dialog_content = "好。我同意你們的條件。",
  ui_story_1013_10131501_97_dialog_content = "只要不損害臨空者號，我就會配合你們的研究。",
  ui_story_1013_10131501_98_dialog_content = "當然不會損壞。相反，我會讓他恢復成你期望的樣子。",
  ui_story_1013_10131501_99_dialog_content = "既然如此。",
  ui_story_1013_10131501_100_dialog_content = "鶯歌，把A-42號保密櫃裡的檔案取過來。",
  ui_story_1013_10131501_101_dialog_content = "我們的空裔朋友需要它。",
  ui_story_1013_10131501_102_dialog_content = "是！",
  ui_story_1013_10131501_103_dialog_content = "（A-42......竟然是保密級別這麼高的檔案！）",
  ui_story_1013_10131501_104_dialog_content = "取完檔案之後，你去我的研究室等著。",
  ui_story_1013_10131501_105_dialog_content = "有件事要安排你做。",
  ui_story_1013_10131501_106_dialog_content = "是！",
  ui_story_1013_10131501_107_dialog_content = "尤利西斯，這是我都不知道的情報。",
  ui_story_1013_10131501_108_dialog_content = "你們又在哪裡藏了東西？",
  ui_story_1013_10131501_109_dialog_content = "說不上藏，只是沒人去找罷了。",
  ui_story_1013_10131501_110_dialog_content = "妳不會對那邊感興趣的。",
  ui_story_1013_10131501_111_dialog_content = "它在極光遺跡。",
  ui_story_1013_10131501_112_dialog_content = "！！！",
  ui_story_1013_10131501_113_dialog_content = "晨光曆■■■■年，記錄到巨像參與■■■會戰。",
  ui_story_1013_10131501_114_dialog_content = "晨光曆■■■■年，記錄到巨像在戰鬥中發生不可逆戰損。",
  ui_story_1013_10131501_115_dialog_content = "晨光曆■■■■年，記錄到巨像蹤跡於■■號地下城。",
  ui_story_1013_10131501_116_dialog_content = "好多地方都被模糊掉了啊，這幫老狐狸。",
  ui_story_1013_10131501_117_dialog_content = "PlayerName，那可是絕密檔案，最好別在走廊上讀。",
  ui_story_1013_10131501_118_dialog_content = "大元帥！對不起，我......我一想到臨空者號就太興奮了。",
  ui_story_1013_10131501_119_dialog_content = "我理解。這一次真的離復原很近了。",
  ui_story_1013_10131501_120_dialog_content = "嗯，我也是這麼覺得的！",
  ui_story_1013_10131501_121_dialog_content = "但是，雖然有點不合時宜，我還是要簡單跟你說幾句。",
  ui_story_1013_10131501_122_dialog_content = "極光遺跡這個名字對你還說還很陌生，但另一個名字你應該還有印象。",
  ui_story_1013_10131501_123_dialog_content = "你記得黃昏鎮嗎？",
  ui_story_1013_10131501_124_dialog_content = "嗯，記得，是昭和西恩他們所在的地方。",
  ui_story_1013_10131501_125_dialog_content = "黃昏鎮是極光遺跡區域的居民聚集地。",
  ui_story_1013_10131501_126_dialog_content = "那個地方比你想像中更加複雜。",
  ui_story_1013_10131501_127_dialog_content = "複雜？",
  ui_story_1013_10131501_128_dialog_content = "科學首席議會的手能伸到那裡，但也僅限於此。",
  ui_story_1013_10131501_129_dialog_content = "他們做不了更多的動作。",
  ui_story_1013_10131501_130_dialog_content = "有人會將他們絆住。當然，也可能會將你絆住。",
  ui_story_1013_10131501_131_dialog_content = "絆住？那裡不是啟光聯邦的所屬地嗎？",
  ui_story_1013_10131501_132_dialog_content = "不只是。你也知道，那裡同樣屬於白夜城。",
  ui_story_1013_10131501_133_dialog_content = "而且，不要用你既定的眼光去看待那裡的勢力。",
  ui_story_1013_10131501_134_dialog_content = "那裡是不一樣的。",
  ui_story_1013_10131501_135_dialog_content = "常年的戰火早就把地上的一切熏制成硝煙的風味。",
  ui_story_1013_10131501_136_dialog_content = "騎士不會向舒瓦茲下跪，信徒仰望著不同的太陽。",
  ui_story_1013_10131501_137_dialog_content = "士兵也不會聽命於遙遙遠方的什麼大元帥。",
  ui_story_1013_10131501_138_dialog_content = "竟然是這樣......",
  ui_story_1013_10131501_139_dialog_content = "所以，科學首席議會向你承諾的計畫未必能實現。",
  ui_story_1013_10131501_140_dialog_content = "他們準備用救助裝置和戰備資源交換研究資料，看起來公平可行也符合程序。",
  ui_story_1013_10131501_141_dialog_content = "但是，程序在那裡是行不通的。",
  ui_story_1013_10131501_142_dialog_content = "這場交易的週期會拉得很長，甚至乾脆杳無音訊。",
  ui_story_1013_10131501_143_dialog_content = "不行！好不容易才看到臨空者號復甦的希望，怎麼能再拖下去！",
  ui_story_1013_10131501_144_dialog_content = "誰知道他的意識會不會在這期間再次發生意外......",
  ui_story_1013_10131501_145_dialog_content = "對，不能再拖了。我要自己去極光遺跡完成交易！",
  ui_story_1013_10131501_146_dialog_content = "有臨空者號在，我的速度肯定比聯絡兵更快。",
  ui_story_1013_10131501_147_dialog_content = "即使真的遇到麻煩，自己想辦法解決也比乾著急要強！",
  ui_story_1013_10131501_148_dialog_content = "猜到你會這麼說了。在關鍵的事情上，你的行動力值得稱讚。",
  ui_story_1013_10131501_149_dialog_content = "如果你想親自去辦，就必須做好萬全的準備。",
  ui_story_1013_10131501_150_dialog_content = "準備好應對暗鬼，應對械鬥，甚至應對天災。",
  ui_story_1013_10131501_151_dialog_content = "在迦南城，我會盡可能地幫你做準備。一旦離開，你就只能依靠自己了。",
  ui_story_1013_10131501_152_dialog_content = "也不只有自己。別忘了，空裔可不會單槍匹馬去戰鬥。",
  ui_story_1013_10131501_153_dialog_content = "那你最好確保找到的幫手足夠靠譜。",
  ui_story_1013_10131501_154_dialog_content = "放心吧。雖然我一向對自己沒什麼信心。",
  ui_story_1013_10131501_155_dialog_content = "但是對我的朋友們，我可是信心十足的！",
  ui_story_1013_10131501_156_dialog_content = "哈哈哈哈，真是夠軟弱的口號啊。",
  ui_story_1013_10131501_157_dialog_content = "哎呀，這是......",
  ui_story_1013_10131501_158_dialog_content = "不過跟你並肩戰鬥後，我好像能懂你身上的氣勢。",
  ui_story_1013_10131501_159_dialog_content = "不為勝利，而是畏懼失敗。未見鋒芒，但無往不利。",
  ui_story_1013_10131501_160_dialog_content = "那是足以令戰士凝聚和動容的氣勢。",
  ui_story_1013_10131501_161_dialog_content = "是比勇氣更有力量的，懦弱者的勇氣。",
  ui_story_1014_10140101_1_dialog_content = "<color=#e8d9bb>啟光聯邦，迦南城，啟光研究院</color>",
  ui_story_1014_10140101_2_dialog_content = "原來如此！是光榮的外派任務呢！",
  ui_story_1014_10140101_3_dialog_content = "險象環生的邊境、接近暗面的神祕小鎮、令人心跳的探險......",
  ui_story_1014_10140101_4_dialog_content = "我已經準備就緒了哦，PlayerName！",
  ui_story_1014_10140101_5_dialog_content = "當然......",
  ui_story_1014_10140101_6_dialog_content = "當然不行！！！",
  ui_story_1014_10140101_7_dialog_content = "<size=45>哎？！！</size>",
  ui_story_1014_10140101_8_dialog_content = "暫且不說那個啟光防線外部的小鎮到底有多危險......",
  ui_story_1014_10140101_9_dialog_content = "以及接近暗面的生態究竟有多惡劣......",
  ui_story_1014_10140101_10_dialog_content = "單說薇絲妳的身體狀況，也不可以就這麼離開啟光遠行。",
  ui_story_1014_10140101_11_dialog_content = "這有什麼關係嘛，我現在不是好好的嗎？",
  ui_story_1014_10140101_12_dialog_content = "不行就是不行！",
  ui_story_1014_10140101_13_dialog_content = "正好，啟光這邊也開始著手研究醫療裝置的升級了。",
  ui_story_1014_10140101_14_dialog_content = "總之，妳就暫時在醫療院繼續修養，等到妳的身體完全恢復之後......",
  ui_story_1014_10140101_15_dialog_content = "<color=#e8d9bb>嗡——嗡——</color>",
  ui_story_1014_10140101_16_dialog_content = "咦？等一下哦，PlayerName。",
  ui_story_1014_10140101_17_dialog_content = "喂......？咦？！",
  ui_story_1014_10140101_18_dialog_content = "薇......薇絲中尉報到，向大元帥致禮！",
  ui_story_1014_10140101_19_dialog_content = "（大元帥嗎，大概是想關心薇絲的身體狀況......吧？）",
  ui_story_1014_10140101_20_dialog_content = "咦？緊急任務......",
  ui_story_1014_10140101_21_dialog_content = "（哎？！緊急？這種時候？）",
  ui_story_1014_10140101_22_dialog_content = "瞭解，請容許我記錄一下。",
  ui_story_1014_10140101_23_dialog_content = "<size=33>首席議會、黃昏鎮、極光遺跡、資料交易......</size>",
  ui_story_1014_10140101_24_dialog_content = "（剛才發生的所有事情都被一口氣交代了！）",
  ui_story_1014_10140101_25_dialog_content = "好的，我聽明白了。",
  ui_story_1014_10140101_26_dialog_content = "感謝您的信任，請您放心交給我吧。",
  ui_story_1014_10140101_27_dialog_content = "（什麼原來如此，又交給妳什麼了啊？）",
  ui_story_1014_10140101_28_dialog_content = "明白，堅決嚴肅執行任務！",
  ui_story_1014_10140101_29_dialog_content = "反正，PlayerName，無論你怎麼說，我都是一定要跟你一起去的！",
  ui_story_1014_10140101_30_dialog_content = "這可是大元帥親自下達的命令。",
  ui_story_1014_10140101_31_dialog_content = "不要讓我為難，也不要讓大元帥為難喔。",
  ui_story_1014_10140101_32_dialog_content = "怎......怎麼這樣！",
  ui_story_1014_10140101_33_dialog_content = "大元帥在對講機裡有些困擾呢，她好像暫時沒辦法從事務中脫身。",
  ui_story_1014_10140101_34_dialog_content = "「薇絲中尉，妳要代表啟光本部，支援空裔與駐邊境勢力的交易工作」。",
  ui_story_1014_10140101_35_dialog_content = "大元帥這樣說來著。",
  ui_story_1014_10140101_36_dialog_content = "既便如此，那也......",
  ui_story_1014_10140101_37_dialog_content = "不要顧慮啦，PlayerName。",
  ui_story_1014_10140101_38_dialog_content = "不如給我講一講這次「外派任務」的詳細計畫吧！",
  ui_story_1014_10140101_39_dialog_content = "......好吧。那就讓我來從頭講講吧，在剛才的會議上......",
  ui_story_1014_10140101_40_dialog_content = "<color=#e8d9bb>啟光聯邦，迦南城，啟光大型會議室</color>",
  ui_story_1014_10140101_41_dialog_content = "如果你同意這筆交易，我們會安排人手去跟掌握研究資料的科學家溝通。",
  ui_story_1014_10140101_42_dialog_content = "以交換的方式，換來臨空者號需要的研究資料。",
  ui_story_1014_10140101_43_dialog_content = "不能再拖了。我要自己去極光遺跡完成交易！",
  ui_story_1014_10140101_44_dialog_content = "有臨空者號在，我的速度肯定比聯絡兵更快。",
  ui_story_1014_10140101_45_dialog_content = "你的意思是，你要代表啟光本部，與極光遺跡所在地的居民區進行聯絡嗎？",
  ui_story_1014_10140101_46_dialog_content = "我不認為你有這樣的權力，空裔。",
  ui_story_1014_10140101_47_dialog_content = "這有何妨，不要這麼上綱上線，尤利西斯。",
  ui_story_1014_10140101_48_dialog_content = "這本就是屬於PlayerName和黃昏鎮的交易，啟光只是提供了方法。",
  ui_story_1014_10140101_49_dialog_content = "哈......欠，我倒是還挺期待的。",
  ui_story_1014_10140101_50_dialog_content = "對於那樣一個「<color=#FFB400>易碎天工</color>」，我們確實需要合適的人手押送。",
  ui_story_1014_10140101_51_dialog_content = "「易碎天工」？就是你們希望用於交換的那個物品吧。",
  ui_story_1014_10140101_52_dialog_content = "是的，本部與駐黃昏鎮的啟光勢力在先前已經達成了協定。",
  ui_story_1014_10140101_53_dialog_content = "鑒於邊境地帶戰爭頻發，本部決定向邊境地帶派發一台高效的戰鬥機器。",
  ui_story_1014_10140101_54_dialog_content = "它是尤利西斯製作出的最新產品。",
  ui_story_1014_10140101_55_dialog_content = "用它與那邊的啟光勢力進行交接，他們就會提供巨像的相關研究資料。",
  ui_story_1014_10140101_56_dialog_content = "因為這台戰鬥機器非常珍貴且脆弱，所以運輸過程中必須要小心謹慎。",
  ui_story_1014_10140101_57_dialog_content = "比起啟用飛艇運輸，由空裔專人專運會更有保障。",
  ui_story_1014_10140101_58_dialog_content = "那個傳說中的「易碎天工」......",
  ui_story_1014_10140101_59_dialog_content = "是的，它現在就在我的手上。",
  ui_story_1014_10140101_60_dialog_content = "真讓人好奇啊，不知道是一台什麼類型的戰鬥機器呢。",
  ui_story_1014_10140101_61_dialog_content = "<color=#e8d9bb><size=30>喀啦......</size></color>",
  ui_story_1014_10140101_62_dialog_content = "PlayerName！你......你快看，它好像響了一下！",
  ui_story_1014_10140101_63_dialog_content = "什，什麼聲音？我......我沒太注意到？",
  ui_story_1014_10140101_64_dialog_content = "......可能是我神經過敏吧。",
  ui_story_1014_10140101_65_dialog_content = "你剛才在想什麼嗎，PlayerName？",
  ui_story_1014_10140101_66_dialog_content = "我只是......稍微有一點擔心。",
  ui_story_1014_10140101_67_dialog_content = "臨空者號的狀態並不好，完成最基本的運輸工作應該已經很勉強了，萬一......",
  ui_story_1014_10140101_68_dialog_content = "萬一碰到什麼問題，我們再一起想辦法就行了。",
  ui_story_1014_10140101_69_dialog_content = "事不宜遲，我們這就動身吧！",
  ui_story_1014_10140101_70_dialog_content = "嗯，說的也是......！",
  ui_story_1014_10140101_71_dialog_content = "<color=#e8d9bb>臨空者號，艦橋</color>",
  ui_story_1014_10140101_72_dialog_content = "（主控系統性能檢查......確認。）",
  ui_story_1014_10140101_73_dialog_content = "（引擎性能檢查......確認。）",
  ui_story_1014_10140101_74_dialog_content = "這些事情......現在都需要我自己來做啊。",
  ui_story_1014_10140101_75_dialog_content = "（再去休息室檢查一下吧。）",
  ui_story_1014_10140101_76_dialog_content = "......咦？！",
  ui_story_1014_10140101_77_dialog_content = "卡蓮，貝爾塔？！還有......鶯歌？",
  ui_story_1014_10140101_78_dialog_content = "大家為什麼都在這裡啊！",
  ui_story_1014_10140101_79_dialog_content = "我明明還沒來得及通知卡蓮......",
  ui_story_1014_10140101_80_dialog_content = "其實是薇絲先告訴了我，說PlayerName又準備向永夜的方向啟程了。",
  ui_story_1014_10140101_81_dialog_content = "只有你們兩人在那邊孤軍作戰，總歸是叫人不太安心。",
  ui_story_1014_10140101_82_dialog_content = "嘿嘿，卡蓮總是這麼可靠。",
  ui_story_1014_10140101_83_dialog_content = "我還在擔心妳來不及趕過來呢！",
  ui_story_1014_10140101_84_dialog_content = "正好，白夜城也很久沒有與黃昏鎮的駐邊勢力進行交流了。",
  ui_story_1014_10140101_85_dialog_content = "我就帶上了貝爾塔，順便去那邊做巡視工作。",
  ui_story_1014_10140101_86_dialog_content = "又見面了，PlayerName。",
  ui_story_1014_10140101_87_dialog_content = "看你的臉色不太好，需不需要我給你打一針？",
  ui_story_1014_10140101_88_dialog_content = "什，什麼？！",
  ui_story_1014_10140101_89_dialog_content = "開玩笑啦。",
  ui_story_1014_10140101_90_dialog_content = "倒是旁邊這個啟光人看著有點陌生，上一次沒在空谷那邊見過妳吧？",
  ui_story_1014_10140101_91_dialog_content = "這次那個啟光的小白毛沒有跟過來嗎？",
  ui_story_1014_10140101_92_dialog_content = "不要失禮，貝爾塔。",
  ui_story_1014_10140101_93_dialog_content = "是，遵命！卡蓮殿下。",
  ui_story_1014_10140101_94_dialog_content = "啟光聯邦，情報機關內衛部門，鶯歌中校。",
  ui_story_1014_10140101_95_dialog_content = "薇絲中尉，久仰盛名，關於空裔和巨像的情報，還要請妳多多指教。",
  ui_story_1014_10140101_96_dialog_content = "妳......啊不，您太......太客氣了，我才是要敬禮才對！",
  ui_story_1014_10140101_97_dialog_content = "（薇絲完全應付不來呢。）",
  ui_story_1014_10140101_98_dialog_content = "冒昧問一句，妳這次出現在這裡，也是科學首席議會的安排嗎？",
  ui_story_1014_10140101_99_dialog_content = "十分抱歉，我此次確實是帶著任務前來，不過......",
  ui_story_1014_10140101_100_dialog_content = "我自己也是很願意跑一趟邊境戰區的。",
  ui_story_1014_10140101_101_dialog_content = "根據A-42檔案中的具體內容，我還會為你提供可信的情報。",
  ui_story_1014_10140101_102_dialog_content = "相信你也需要一位中間人來證明「易碎天工」的真實性。",
  ui_story_1014_10140101_103_dialog_content = "是這樣沒錯，可是......",
  ui_story_1014_10140101_104_dialog_content = "不要擔心，這是由本部牽頭的交易，無論順利與否，我都不會對你做過多干涉。",
  ui_story_1014_10140101_105_dialog_content = "（竟然沒有什麼理由反駁她......）",
  ui_story_1014_10140101_106_dialog_content = "......等一下，這樣一來，就只剩萊因哈特在和科學首席議會對談嗎？",
  ui_story_1014_10140101_107_dialog_content = "你不會在擔心大元帥吧？",
  ui_story_1014_10140101_108_dialog_content = "說的也是，萊因哈特當然輪不到我來擔心吧。",
  ui_story_1014_10140101_109_dialog_content = "<color=#e8d9bb>與此同時，啟光大型會議室</color>",
  ui_story_1014_10140101_110_dialog_content = "追捕吞羅、赫利俄斯二人並不是一項戰略任務，萊因哈特，我認為妳沒必要親自出手。",
  ui_story_1014_10140101_111_dialog_content = "科學首席議會把它交給了更適合的人選。",
  ui_story_1014_10140101_112_dialog_content = "耽迷過往不是一件好事，妳也應該把眼光放在更重要的事上。",
  ui_story_1014_10140101_113_dialog_content = "你們在擔心我會親手抓到不利於尤利西斯的線索？",
  ui_story_1014_10140101_114_dialog_content = "什麼是「不利於我的線索」？",
  ui_story_1014_10140101_115_dialog_content = "這一點你比我更清楚。",
  ui_story_1014_10140101_116_dialog_content = "我期待著真相浮出水面的那一天，尤利西斯，你還能裝傻的時間不多了。",
  ui_story_1014_10140101_117_dialog_content = "如果妳執意如此，委員會恐怕也要重新評估妳的任職資格了。",
  ui_story_1014_10140101_118_dialog_content = "好，你說說吧，你認為什麼樣的事，能比光靈本身更重要？",
  ui_story_1014_10140101_119_dialog_content = "需要我來告訴妳嗎？啟光的聯合軍演、未來的聯軍反攻，哪一件事情都......",
  ui_story_1014_10140101_120_dialog_content = "可笑至極。",
  ui_story_1014_10140101_121_dialog_content = "從來不需要誰來教我怎麼做一名大元帥。",
  ui_story_1014_10140101_122_dialog_content = "我決定好的事情，也不會輕易被誰左右。",
  ui_story_1014_10140101_123_dialog_content = "失陪了，各位。",
  ui_story_1014_10140101_124_dialog_content = "她還是這麼一意孤行啊。",
  ui_story_1014_10140101_125_dialog_content = "呵呵，憑她的能力，找到那個日蝕女也不是難事。",
  ui_story_1014_10140101_126_dialog_content = "諸位就不必置喙了。",
  ui_story_1014_10140101_127_dialog_content = "我也為此準備了相應的計畫。",
  ui_story_1014_10140201_1_dialog_content = "主控系統性能，唔，無異常。",
  ui_story_1014_10140201_2_dialog_content = "自動駕駛系統性能，也沒有什麼問題。",
  ui_story_1014_10140201_3_dialog_content = "PlayerName，臨空者號平穩飛行了這麼久，你也稍微可以安心了。",
  ui_story_1014_10140201_4_dialog_content = "說......說得也是啊，薇絲，辛苦妳了。",
  ui_story_1014_10140201_5_dialog_content = "我倒是沒什麼，但你看起來可完全不像是放心的樣子。",
  ui_story_1014_10140201_6_dialog_content = "不過再怎麼說......你也不用一直抱著這台「易碎天工」吧？",
  ui_story_1014_10140201_7_dialog_content = "你又不是孵蛋的母雞！",
  ui_story_1014_10140201_8_dialog_content = "畢竟在某種意義上，它就是修復臨空者號的重要資料！",
  ui_story_1014_10140201_9_dialog_content = "一時間還不知道該怎麼保護它。",
  ui_story_1014_10140201_10_dialog_content = "而且它並沒有想像中那麼重......",
  ui_story_1014_10140201_11_dialog_content = "咦，這樣嗎？真奇特呢，難道是什麼輕型武器嗎？",
  ui_story_1014_10140201_12_dialog_content = "重量輕又易碎......這台高效戰鬥機器的設計還真奇特。",
  ui_story_1014_10140201_13_dialog_content = "總......總之，我就先這麼待著吧！",
  ui_story_1014_10140201_14_dialog_content = "真是的......",
  ui_story_1014_10140201_15_dialog_content = "（轉換一下心情，去看看卡蓮現在在做什麼吧。）",
  ui_story_1014_10140201_16_dialog_content = "<color=#e8d9bb>嗞啦......嗞......嗞嗞......</color>",
  ui_story_1014_10140201_17_dialog_content = "......",
  ui_story_1014_10140201_18_dialog_content = "還是不行嗎，貝爾塔。",
  ui_story_1014_10140201_19_dialog_content = "抱歉，卡蓮殿下，我也不是很懂這種對講機的使用方法......",
  ui_story_1014_10140201_20_dialog_content = "唔？",
  ui_story_1014_10140201_21_dialog_content = "薇絲，妳來得正好。",
  ui_story_1014_10140201_22_dialog_content = "怎麼了怎麼了，有什麼要幫忙的嗎？",
  ui_story_1014_10140201_23_dialog_content = "我打算聯繫由白夜城派往邊境那邊的騎士團，想提前瞭解一些當地的狀況。",
  ui_story_1014_10140201_24_dialog_content = "他們常年駐扎在那裡，也能作為我們此行的可靠接應。",
  ui_story_1014_10140201_25_dialog_content = "這種事以往都是城主來做的，是我沒有提前做好聯絡準備。",
  ui_story_1014_10140201_26_dialog_content = "畢竟妳出發得匆忙嘛！",
  ui_story_1014_10140201_27_dialog_content = "現在倒是不用擔心了，我眼前就有一位「老師」。",
  ui_story_1014_10140201_28_dialog_content = "拜託了，薇絲，幫我看看這台對講機出了什麼問題。",
  ui_story_1014_10140201_29_dialog_content = "它的訊號總是斷斷續續的。",
  ui_story_1014_10140201_30_dialog_content = "嗯，交給我吧！",
  ui_story_1014_10140201_31_dialog_content = "我看看啊......首先是校準天線的靈敏度。",
  ui_story_1014_10140201_32_dialog_content = "好啦，快試試吧！",
  ui_story_1014_10140201_33_dialog_content = "<color=#e8d9bb>嗞啦......嗞......嗞嗞......</color>",
  ui_story_1014_10140201_34_dialog_content = "唔，那就是......修復它的功率放大模組！",
  ui_story_1014_10140201_35_dialog_content = "嗯！這樣就沒問題了。",
  ui_story_1014_10140201_36_dialog_content = "<color=#e8d9bb>嗞啦......嗞......嗞嗞......</color>",
  ui_story_1014_10140201_37_dialog_content = "啊哈哈哈，這樣的話，就只能——",
  ui_story_1014_10140201_38_dialog_content = "<color=#e8d9bb>梆！砰！</color>",
  ui_story_1014_10140201_39_dialog_content = "<color=#e8d9bb>嗶嗶、嗶嗶......</color>",
  ui_story_1014_10140201_40_dialog_content = "呼～很簡單嘛。",
  ui_story_1014_10140201_41_dialog_content = "原來如此，是要這樣維修嗎。",
  ui_story_1014_10140201_42_dialog_content = "喂？",
  ui_story_1014_10140201_43_dialog_content = "這裡是<color=#FFB400>鐵棘騎士團</color>。重複，鐵棘騎士團。",
  ui_story_1014_10140201_44_dialog_content = "很好，訊號清晰。白夜至上，高庭衛隊長卡蓮，向鐵棘騎士團致以問候。",
  ui_story_1014_10140201_45_dialog_content = "鐵棘騎士團團長李奧，問候卡蓮......",
  ui_story_1014_10140201_46_dialog_content = "<color=#e8d9bb>嗞啦——</color>",
  ui_story_1014_10140201_47_dialog_content = "（訊號還是不好嗎......）",
  ui_story_1014_10140201_48_dialog_content = "李奧閣下，白夜城將前往黃昏鎮做例行視察。",
  ui_story_1014_10140201_49_dialog_content = "屆時將由我代表白夜城出席，很期待與你見面。",
  ui_story_1014_10140201_50_dialog_content = "邊境戰區的工作辛苦，我希望有機會當面向你表達謝意。",
  ui_story_1014_10140201_51_dialog_content = "還真是有點突然啊，我會儘量協調<color=#FFB400>白夜要塞</color>的巡邏時間。",
  ui_story_1014_10140201_52_dialog_content = "表達謝意就免了，這是我的本職工作。",
  ui_story_1014_10140201_53_dialog_content = "那麼屆時見。",
  ui_story_1014_10140201_54_dialog_content = "好的，等您抵達後，我也會派人......達後......人去......",
  ui_story_1014_10140201_55_dialog_content = "<color=#e8d9bb>嗞啦——</color>",
  ui_story_1014_10140201_56_dialog_content = "<color=#e8d9bb>嗶嗶、嗶嗶......</color>",
  ui_story_1014_10140201_57_dialog_content = "看樣子，訊號完全切斷了......",
  ui_story_1014_10140201_58_dialog_content = "罷了，基本資訊算是已經傳達到了。",
  ui_story_1014_10140201_59_dialog_content = "沒......沒問題嗎，卡蓮殿下？",
  ui_story_1014_10140201_60_dialog_content = "經歷了上次的空谷戰役，您才在近期恢復隊長身分。",
  ui_story_1014_10140201_61_dialog_content = "雖然說，您最近的氣質確實變得比以前更堅定了......",
  ui_story_1014_10140201_62_dialog_content = "但按照城主殿下的說法，現在的您仍然處於復職考察期。",
  ui_story_1014_10140201_63_dialog_content = "希望不要出現什麼差錯......",
  ui_story_1014_10140201_64_dialog_content = "沒關係，貝爾塔。我明白妳的心情，不過妳也不用過分擔心。",
  ui_story_1014_10140201_65_dialog_content = "就算出現了什麼問題，我們也只管應對就是了。",
  ui_story_1014_10140201_66_dialog_content = "嗯......卡蓮殿下說得也對！",
  ui_story_1014_10140201_67_dialog_content = "話說回來，這位「團長李奧」到底是什麼來頭？",
  ui_story_1014_10140201_68_dialog_content = "卡蓮殿下表達謝意是出於禮貌，他竟然還不客氣地接受了。",
  ui_story_1014_10140201_69_dialog_content = "不要這樣說，貝爾塔。",
  ui_story_1014_10140201_70_dialog_content = "安穩生活在白夜城的我們，本來就要對邊境地帶的戰士心懷敬意。",
  ui_story_1014_10140201_71_dialog_content = "<color=#e8d9bb>滴——滴——滴——</color>",
  ui_story_1014_10140201_72_dialog_content = "怎......怎麼回事！",
  ui_story_1014_10140201_73_dialog_content = "這是臨空者號的警報聲吧？",
  ui_story_1014_10140201_74_dialog_content = "不好......",
  ui_story_1014_10140201_75_dialog_content = "我們去找PlayerName！",
  ui_story_1014_10140201_76_dialog_content = "呼、呼......",
  ui_story_1014_10140201_77_option_content = "啟用緊急模式",
  ui_story_1014_10140201_78_dialog_content = "<color=#e8d9bb>嗶——！</color>",
  ui_story_1014_10140201_79_option_content = "穩定飛行器",
  ui_story_1014_10140201_80_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_1014_10140201_81_dialog_content = "真是的，小心一點啊。",
  ui_story_1014_10140201_82_dialog_content = "要不是我抱著，「易碎天工」肯定會出現磕碰的。",
  ui_story_1014_10140201_83_dialog_content = "PlayerName，目前到底是什麼情況？",
  ui_story_1014_10140201_84_dialog_content = "是警報器，嚇了你們一跳吧？是因為我剛才不小心誤操作導致的。",
  ui_story_1014_10140201_85_dialog_content = "不要說得這麼若無其事啊PlayerName！",
  ui_story_1014_10140201_86_dialog_content = "真的沒問題嗎？看來駕駛巨像是比我想像中更困難的事情......",
  ui_story_1014_10140201_87_dialog_content = "當，當然沒問題。",
  ui_story_1014_10140201_88_dialog_content = "（再怎麼說，我可是空裔啊！）",
  ui_story_1014_10140201_89_dialog_content = "如果實在覺得勉強的話，我們就先降落在腳下的地區休息吧。",
  ui_story_1014_10140201_90_dialog_content = "離永夜城愈近，周圍的暗能就愈多。",
  ui_story_1014_10140201_91_dialog_content = "你現在應該也不太舒服吧，PlayerName？",
  ui_story_1014_10140201_92_dialog_content = "請說實話。",
  ui_story_1014_10140201_93_dialog_content = "真敏銳啊......確實從剛才開始，我就已經有點頭痛了。",
  ui_story_1014_10140201_94_dialog_content = "雖然我不懂巨像的駕駛，但是從「易碎天工」的安全角度考慮......",
  ui_story_1014_10140201_95_dialog_content = "我的建議也是暫時停靠在地面休息。",
  ui_story_1014_10140201_96_dialog_content = "我們雙方應該都不希望「易碎天工」因為你的失誤而出現閃失。",
  ui_story_1014_10140201_97_dialog_content = "這是當然的事情。",
  ui_story_1014_10140201_98_dialog_content = "好吧，確實是我逞強了。",
  ui_story_1014_10140201_99_dialog_content = "請大家準備好，我來操控臨空者號著陸。",
  ui_story_1014_10140201_100_dialog_content = "呼——",
  ui_story_1014_10140201_101_dialog_content = "出來活動活動也不錯呢。",
  ui_story_1014_10140201_102_dialog_content = "話說回來，臨空者號到底出了什麼問題？",
  ui_story_1014_10140201_103_dialog_content = "竟然連臨時著陸這種操作也需要由PlayerName自己來。",
  ui_story_1014_10140201_104_dialog_content = "看樣子，問題比上一次還要嚴重。",
  ui_story_1014_10140201_105_dialog_content = "他的意識又出現了問題，雖然不影響正常使用，但暫時不能和我感應。",
  ui_story_1014_10140201_106_dialog_content = "......我再去檢查一下他的各項儀器吧。",
  ui_story_1014_10140201_107_dialog_content = "我也去。",
  ui_story_1014_10140201_108_dialog_content = "<color=#e8d9bb>颯......颯......</color>",
  ui_story_1014_10140201_109_dialog_content = "（還真是荒涼。）",
  ui_story_1014_10140201_110_dialog_content = "這裡的光能已經比啟光本部稀薄很多了，妳的身體沒事嗎？",
  ui_story_1014_10140201_111_dialog_content = "這種程度還不至於。",
  ui_story_1014_10140201_112_dialog_content = "而且，「事無巨細地記錄空裔行程與狀況」也是我的任務之一。",
  ui_story_1014_10140201_113_dialog_content = "快去檢查你的巨像到底出了什麼故障吧。",
  ui_story_1014_10140201_114_dialog_content = "我......我知道了。",
  ui_story_1014_10140201_115_dialog_content = "（總覺得被監視了啊......）",
  ui_story_1014_10140201_116_dialog_content = "嘎......",
  ui_story_1014_10140201_117_dialog_content = "嗯？！這個聲音難道......",
  ui_story_1014_10140201_118_dialog_content = "<anim type=Shake><size=45>嘎吼！！！</size></anim>",
  ui_story_1014_10140201_119_dialog_content = "暗鬼？！！",
  ui_story_1014_10140201_120_dialog_content = "出現在這種地方倒也正常！",
  ui_story_1014_10140201_121_dialog_content = "不能讓這群傢伙接近臨空者號，妳擅長戰鬥嗎？",
  ui_story_1014_10140201_122_dialog_content = "我......如果只是模擬戰鬥的話......",
  ui_story_1014_10140201_123_dialog_content = "那......那妳快去叫薇絲和卡蓮她們！",
  ui_story_1014_10140201_124_dialog_content = "戰鬥。",
  ui_story_1014_10140201_125_dialog_content = "阿克希亞收到了戰鬥指令。",
  ui_story_1014_10140201_126_dialog_content = "？！",
  ui_story_1014_10140201_127_dialog_content = "（終於還是出來了嗎......）",
  ui_story_1014_10140201_128_dialog_content = "誰！誰在說話？！",
  ui_story_1014_10140201_129_dialog_content = "<color=#e8d9bb>喀啦......喀啦......</color>",
  ui_story_1014_10140201_130_dialog_content = "阿克希亞收到了你的戰鬥指令。",
  ui_story_1014_10140201_131_dialog_content = "不要為難鶯歌。",
  ui_story_1014_10140201_132_dialog_content = "阿克希亞準備戰鬥。",
  ui_story_1014_10140201_133_dialog_content = "妳，妳就是......",
  ui_story_1014_10140201_134_dialog_content = "妳是被科學首席議會交給我的<color=#FFB400>「易碎天工」</color>？！",
  ui_story_1014_10140201_135_dialog_content = "吼！！！",
  ui_story_1014_10140201_136_dialog_content = "不堪一擊。",
  ui_story_1014_10140202_1_dialog_content = "速射感知——！",
  ui_story_1014_10140202_2_dialog_content = "冰花，散開！",
  ui_story_1014_10140202_3_dialog_content = "辛苦了，薇絲中尉。",
  ui_story_1014_10140202_4_dialog_content = "阿克希亞，不要緊吧？",
  ui_story_1014_10140202_5_dialog_content = "這句話妳應該問問暗鬼。",
  ui_story_1014_10140202_6_dialog_content = "......雖然現在已經沒有暗鬼能回答妳了。",
  ui_story_1014_10140202_7_dialog_content = "真是的，不要擅自從休眠艙裡出來啊，這裡也不是妳執行任務的地方。",
  ui_story_1014_10140202_8_dialog_content = "我會注意不弄傷自己的。",
  ui_story_1014_10140202_9_dialog_content = "我不會讓鶯歌難辦。",
  ui_story_1014_10140202_10_dialog_content = "不要自顧自地在這裡開始聊天啊！",
  ui_story_1014_10140202_11_dialog_content = "可以給我解釋一下嗎？她怎麼看都是個光靈而不是物品吧？",
  ui_story_1014_10140202_12_dialog_content = "嚴格來說，她確實是一名光靈。",
  ui_story_1014_10140202_13_dialog_content = "但在光靈這個身分之外，她首先是科學首席議會最引以為傲的戰鬥機器。",
  ui_story_1014_10140202_14_dialog_content = "機器......嗎？",
  ui_story_1014_10140202_15_dialog_content = "我們習慣以「機器」稱呼她罷了。",
  ui_story_1014_10140202_16_dialog_content = "她是一個能夠絕對貫徹每一條作戰命令的完美主義者。",
  ui_story_1014_10140202_17_dialog_content = "與其說是她在驅動光能，不如說是光能變成了她的樣子。",
  ui_story_1014_10140202_18_dialog_content = "只要她發動光能術，她就會用光能去看、去聽，去操控各類機械完成戰鬥。",
  ui_story_1014_10140202_19_dialog_content = "好厲害，從來沒有見過這種能力！",
  ui_story_1014_10140202_20_dialog_content = "嗯，她對光能術的運用達到了卓越的程度，但是......",
  ui_story_1014_10140202_21_dialog_content = "她本身仍舊非常脆弱。",
  ui_story_1014_10140202_22_dialog_content = "從她滿身的繃帶你就能看出來了，她的身體機能一直處於衰竭的狀態。",
  ui_story_1014_10140202_23_dialog_content = "衰竭狀態？這是為什麼，憑藉啟光的醫療技術也不能治癒嗎？",
  ui_story_1014_10140202_24_dialog_content = "和基因有關吧，誰知道呢。",
  ui_story_1014_10140202_25_dialog_content = "總之，她就是這樣一台「玻璃大砲」。",
  ui_story_1014_10140202_26_dialog_content = "放在啟光本部實在是大材小用，只有黃昏鎮這種極限地區才能發揮她的能力。",
  ui_story_1014_10140202_27_dialog_content = "你好，PlayerName，這是一個遲到的問候。",
  ui_story_1014_10140202_28_dialog_content = "接下來的路程我還要繼續麻煩你，拜託了。",
  ui_story_1014_10140202_29_dialog_content = "作為回報，阿克希亞會......",
  ui_story_1014_10140202_30_dialog_content = "會在你需要的時候，走出休眠艙，開始戰鬥。",
  ui_story_1014_10140202_31_dialog_content = "這......這就不必了！",
  ui_story_1014_10140202_32_dialog_content = "（把妳磕壞了就完蛋了！）",
  ui_story_1014_10140202_33_dialog_content = "普普通通的暗鬼我們就可以對付，妳出手的話就是用大砲打蚊子了！",
  ui_story_1014_10140202_34_dialog_content = "是啊，不到萬不得已，妳就先好好修養吧。",
  ui_story_1014_10140202_35_dialog_content = "這麼說，我確實有點想睡了。",
  ui_story_1014_10140202_36_dialog_content = "（啊......好可愛的孩子！）",
  ui_story_1014_10140202_37_dialog_content = "看起來明明年齡和我們差不多，卻很嗜睡呢。",
  ui_story_1014_10140202_38_dialog_content = "果然還是和以前一樣啊......",
  ui_story_1014_10140202_39_dialog_content = "每一次戰鬥對她來說都是一種消耗，她到了應該休息的時候了。",
  ui_story_1014_10140202_40_dialog_content = "晚安，各位。",
  ui_story_1014_10140202_41_dialog_content = "我們把她送回臨空者號的休息室裡吧。",
  ui_story_1014_10140202_42_dialog_content = "貝爾塔，妳那邊怎麼樣了？",
  ui_story_1014_10140202_43_dialog_content = "來了，卡蓮殿下！",
  ui_story_1014_10140202_44_dialog_content = "我剛才對巨像做了粗略的檢查。",
  ui_story_1014_10140202_45_dialog_content = "雖然我是拉斐爾的副手，但面對這種遠古機械的病灶，我果然還是......",
  ui_story_1014_10140202_46_dialog_content = "辛苦妳了，貝爾塔！",
  ui_story_1014_10140202_47_dialog_content = "無論如何，臨空者號現在的狀態也不能即刻起飛。",
  ui_story_1014_10140202_48_dialog_content = "我們今天就在這裡稍作修整吧。",
  ui_story_1014_10140202_49_dialog_content = "今天在......這種地方休息嗎？",
  ui_story_1014_10140202_50_dialog_content = "這裡連太陽都很難看到，我們怎麼才能辨認時間呢......",
  ui_story_1014_10140202_51_dialog_content = "罷了，可能這就是前往聖地途中的修行。",
  ui_story_1014_10140202_52_dialog_content = "聖地？不能把那種地方稱為聖地吧。",
  ui_story_1014_10140202_53_dialog_content = "那可是駐扎在遠古時代光靈與暗鬼交戰之地的要塞。",
  ui_story_1014_10140202_54_dialog_content = "光靈們不斷堅守著那裡，把暗鬼逐步驅向了永夜地區。",
  ui_story_1014_10140202_55_dialog_content = "在埋葬著無數光靈屍體的坑裡唱頌歌，這就是白夜城的趣味嗎。",
  ui_story_1014_10140202_56_dialog_content = "不是，才不是呢！",
  ui_story_1014_10140202_57_dialog_content = "傳說中，極光遺跡是世界上所有極光的發源地。",
  ui_story_1014_10140202_58_dialog_content = "那裡也是光靈能夠涉足的最遠的宜居地帶，是光靈能夠尋根溯源的地方。",
  ui_story_1014_10140202_59_dialog_content = "這和我剛才說過的話不衝突吧。",
  ui_story_1014_10140202_60_dialog_content = "所以不要把它說成「屍體坑」啊！",
  ui_story_1014_10140202_61_dialog_content = "（頭好痛啊......不知道是因為暗能太過濃重，還是因為她們鬥嘴太多。）",
  ui_story_1014_10140202_62_dialog_content = "好了，好了，大家不要吵了......",
  ui_story_1014_10140202_63_dialog_content = "貝爾塔，到我這邊來。",
  ui_story_1014_10140202_64_dialog_content = "冷靜一下啊，鶯歌長官。",
  ui_story_1014_10140202_65_dialog_content = "天色愈來愈暗了，我們先回到巨像上吧。",
  ui_story_1014_10140202_66_dialog_content = "......",
  ui_story_1014_10140202_67_dialog_content = "哼。",
  ui_story_1014_10140301_1_dialog_content = "<color=#e8d9bb>臨空者號，艦橋</color>",
  ui_story_1014_10140301_2_dialog_content = "<anim type=Shake>哈——欠......</anim>",
  ui_story_1014_10140301_3_dialog_content = "（好睏......根本睡不好。）",
  ui_story_1014_10140301_4_dialog_content = "早啊，PlayerName。",
  ui_story_1014_10140301_5_dialog_content = "哎？！PlayerName怎麼......看起來這麼憔悴！",
  ui_story_1014_10140301_6_dialog_content = "你失眠了嗎？",
  ui_story_1014_10140301_7_dialog_content = "算是吧，這裡的暗能比來時更加濃郁了。",
  ui_story_1014_10140301_8_dialog_content = "昨晚每有一隻暗鬼從臨空者號旁邊經過，我就要被迫清醒一下。",
  ui_story_1014_10140301_9_dialog_content = "總有種我們被當成了獵物的感覺......",
  ui_story_1014_10140301_10_dialog_content = "真是辛苦的一晚啊......還是趁現在好好睡一覺吧。",
  ui_story_1014_10140301_11_dialog_content = "唔，說的也是。",
  ui_story_1014_10140301_12_dialog_content = "那我就先睡了......",
  ui_story_1014_10140301_13_dialog_content = "<color=#e8d9bb>梆！梆！</color>",
  ui_story_1014_10140301_14_dialog_content = "<color=#e8d9bb>咚——！</color>",
  ui_story_1014_10140301_15_dialog_content = "真讓人受不了......",
  ui_story_1014_10140301_16_dialog_content = "外面是什麼聲音啊！！！",
  ui_story_1014_10140301_17_dialog_content = "我帶著貝爾塔下去探查一下吧。",
  ui_story_1014_10140301_18_dialog_content = "我要自己下去看看！",
  ui_story_1014_10140301_19_dialog_content = "（這些暗鬼真是變本加厲了！）",
  ui_story_1014_10140301_20_dialog_content = "肆意搗亂也要有個限度！",
  ui_story_1014_10140301_21_dialog_content = "......哎？西恩？",
  ui_story_1014_10140301_22_dialog_content = "啊？是......是PlayerName！",
  ui_story_1014_10140301_23_dialog_content = "在這種地方相遇真是緣分啊！",
  ui_story_1014_10140301_24_dialog_content = "這個白色的大塊頭，是你的巨像？",
  ui_story_1014_10140301_25_dialog_content = "......那還能是誰的啊！！！",
  ui_story_1014_10140301_26_dialog_content = "咳......總之，很抱歉給PlayerName和各位添了麻煩。",
  ui_story_1014_10140301_27_dialog_content = "我一會就去檢查一下，希望我的砸門行為並沒有給臨空者號造成傷害......",
  ui_story_1014_10140301_28_dialog_content = "（唉，真是的......）",
  ui_story_1014_10140301_29_dialog_content = "我剛才是在執行黃昏鎮周邊地帶的巡視和清掃工作。",
  ui_story_1014_10140301_30_dialog_content = "像黃昏鎮這種地方，本來就光能稀薄，經常會出現迷路的難民。",
  ui_story_1014_10140301_31_dialog_content = "我的主要任務，就是尋找在突發災害中落單的民眾，順便打掃一下暗鬼。",
  ui_story_1014_10140301_32_dialog_content = "發現這個白色大塊頭的時候，我還想起了PlayerName呢！",
  ui_story_1014_10140301_33_dialog_content = "有了巨像的幫助，就算要到很遠的地方去，應該也十分方便吧？",
  ui_story_1014_10140301_34_dialog_content = "確實方便。不管到哪裡去，只要乘著巨像，都能很快到達。",
  ui_story_1014_10140301_35_dialog_content = "真好！我也想有一艘能夠搭乘的巨像。",
  ui_story_1014_10140301_36_dialog_content = "我還以為，我當時的願望能實現了。",
  ui_story_1014_10140301_37_dialog_content = "想來也是，在這種邊境撿到一座被遺棄的新巨像，確實也不太可能......",
  ui_story_1014_10140301_38_dialog_content = "噗，真是的，怎麼想都不可能吧。",
  ui_story_1014_10140301_39_dialog_content = "介紹一下，這是卡蓮和貝爾塔，來自白夜城的高庭衛隊。",
  ui_story_1014_10140301_40_dialog_content = "你好。",
  ui_story_1014_10140301_41_dialog_content = "不要再這麼莽撞了哦，啟光的。",
  ui_story_1014_10140301_42_dialog_content = "非......非常抱歉！",
  ui_story_1014_10140301_43_dialog_content = "這是鶯歌中校，她懷裡抱著個那個大盒子是阿克希亞，具體來說......",
  ui_story_1014_10140301_44_dialog_content = "鶯歌！好久不見！沒想到我們能在這種地方重逢啊！",
  ui_story_1014_10140301_45_dialog_content = "阿克希亞怎麼樣，身體還好吧？",
  ui_story_1014_10140301_46_dialog_content = "原來你們認識啊！",
  ui_story_1014_10140301_47_dialog_content = "真讓人意外啊，你也依舊看著活蹦亂跳的。",
  ui_story_1014_10140301_48_dialog_content = "哼哼，那當然啦！黃昏鎮的生活就是戰鬥，我的拳術又強了不少呢！",
  ui_story_1014_10140301_49_dialog_content = "你還真是一如既往地樂觀......",
  ui_story_1014_10140301_50_dialog_content = "（回過神來，竟然已經完全不睏了......）",
  ui_story_1014_10140301_51_dialog_content = "我再去檢查一下臨空者號的狀況，之後差不多可以繼續啟程了。",
  ui_story_1014_10140301_52_dialog_content = "啟程？難道說，你們的目的地是黃昏鎮嗎？",
  ui_story_1014_10140301_53_dialog_content = "這個說來話長，總之，受啟光本部之托，我們要去黃昏鎮進行一場「交易」。",
  ui_story_1014_10140301_54_dialog_content = "這樣的話，就讓我來做你們的導遊吧，我知道近路喔！",
  ui_story_1014_10140301_55_dialog_content = "另外，我對付暗鬼也是有一手的，沿途的一切突發情況都可以交給我。",
  ui_story_1014_10140301_56_dialog_content = "那真是幫大忙了！",
  ui_story_1014_10140301_57_dialog_content = "唔......",
  ui_story_1014_10140301_58_dialog_content = "巨像的情況怎麼樣！",
  ui_story_1014_10140301_59_dialog_content = "嗯，總的來說沒什麼大問題，可以準備出發了。",
  ui_story_1014_10140301_60_dialog_content = "大......大門呢？",
  ui_story_1014_10140301_61_dialog_content = "大門也完全沒問題！不用緊張，西恩。",
  ui_story_1014_10140301_62_dialog_content = "呼......那就好那就好，我也能松一口氣了。",
  ui_story_1014_10140301_63_dialog_content = "<color=#e8d9bb>咯吱......</color>",
  ui_story_1014_10140301_64_dialog_content = "有動靜？！",
  ui_story_1014_10140301_65_dialog_content = "又來了嗎......",
  ui_story_1014_10140301_66_dialog_content = "<anim type=Shake><size=45>吼！！！</size></anim>",
  ui_story_1014_10140301_67_dialog_content = "竟然自己送上門了！",
  ui_story_1014_10140301_68_dialog_content = "那就讓我繼續來完成「清掃工作」吧。",
  ui_story_1014_10140402_1_dialog_content = "喝啊——！",
  ui_story_1014_10140402_2_dialog_content = "這樣應該就差不多了。",
  ui_story_1014_10140402_3_dialog_content = "上次在啟光醫療院還真是小瞧你了！",
  ui_story_1014_10140402_4_dialog_content = "嘿嘿，這樣一來，我們就可以順利地上路了。",
  ui_story_1014_10140402_5_dialog_content = "不過話說回來，如果是本部委託PlayerName過來做交易的話......",
  ui_story_1014_10140402_6_dialog_content = "我需要先跟這邊的高層聯絡一下。",
  ui_story_1014_10140402_7_dialog_content = "這......這並不是懷疑PlayerName的意思！",
  ui_story_1014_10140402_8_dialog_content = "只是黃昏鎮比較忌憚每一個不屬於這裡的外來者。",
  ui_story_1014_10140402_9_dialog_content = "有了這次聯絡，後面的出入程序會變得更方便一些。",
  ui_story_1014_10140402_10_dialog_content = "原來如此，那就拜託你了。",
  ui_story_1014_10140402_11_dialog_content = "<color=#e8d9bb>另一邊，臨空者號，艦橋</color>",
  ui_story_1014_10140402_12_dialog_content = "（唔......他看起來確實比以前強了不少呢。）",
  ui_story_1014_10140402_13_dialog_content = "鶯歌，在觀察西恩嗎。",
  ui_story_1014_10140402_14_dialog_content = "阿克希亞？妳......妳突然出現在別人背後，還是挺有壓迫感的......",
  ui_story_1014_10140402_15_dialog_content = "抱歉抱歉。",
  ui_story_1014_10140402_16_dialog_content = "休息之餘，還是需要略微活動一下。",
  ui_story_1014_10140402_17_dialog_content = "稍稍有點讓人懷念呢，從前我們三個在「<color=#FFB400>啟明星計畫</color>」中訓練的日子。",
  ui_story_1014_10140402_18_dialog_content = "才「畢業」五年，阿克希亞卻已經快忘了那時候的事情了。",
  ui_story_1014_10140402_19_dialog_content = "因為阿克希亞的腦子裡總是裝滿了各種命令吧。",
  ui_story_1014_10140402_20_dialog_content = "明明鶯歌才是......",
  ui_story_1014_10140402_21_dialog_content = "不過，這也算是阿克希亞的優勢。",
  ui_story_1014_10140402_22_dialog_content = "包括西恩在內，我們都在各自的位置上，發揮著我們的特長。",
  ui_story_1014_10140402_23_dialog_content = "哼，他那種遺棄品也算嗎。",
  ui_story_1014_10140402_24_dialog_content = "......但他好像確實樂在其中啊。",
  ui_story_1014_10140402_25_dialog_content = "大家，久等了，我們現在可以繼續趕路了！",
  ui_story_1014_10140402_26_dialog_content = "黃昏鎮這邊的啟光勢力，也對各位表示了歡迎喔！",
  ui_story_1014_10140402_27_dialog_content = "？！",
  ui_story_1014_10140402_28_dialog_content = "阿克希亞？！妳醒過來了！",
  ui_story_1014_10140402_29_dialog_content = "難難難難道說，我剛才對付暗鬼的樣子都被妳們看到了嗎？",
  ui_story_1014_10140402_30_dialog_content = "是的。",
  ui_story_1014_10140402_31_dialog_content = "怎麼樣？我是不是變厲害了？是不是比在本部的時候強壯了很多？",
  ui_story_1014_10140402_32_dialog_content = "要不要再和我比試一下？看看這次我們誰打得過誰？",
  ui_story_1014_10140402_33_dialog_content = "不要。",
  ui_story_1014_10140402_34_dialog_content = "話說回來，妳身邊也多了四個我不認識的小機器人呢！",
  ui_story_1014_10140402_35_dialog_content = "它們叫「三次方」。",
  ui_story_1014_10140402_36_dialog_content = "咦？可是它們明明有四個......",
  ui_story_1014_10140402_37_dialog_content = "第四個小機器人，是專門幫阿克希亞提袖子的。",
  ui_story_1014_10140402_38_dialog_content = "好了，三次方有四個不是很正常嗎！",
  ui_story_1014_10140402_39_dialog_content = "不要鬧了，西恩，阿克希亞這次就是被派來支援黃昏鎮的「交易品」。",
  ui_story_1014_10140402_40_dialog_content = "你不要消耗阿克希亞的身體機能。",
  ui_story_1014_10140402_41_dialog_content = "真的？！",
  ui_story_1014_10140402_42_dialog_content = "那我就是阿克希亞的前輩了！",
  ui_story_1014_10140402_43_dialog_content = "怎麼樣，有什麼問題想問我嗎？",
  ui_story_1014_10140402_44_dialog_content = "請問，黃昏鎮現在的軍事架構是什麼樣子的？",
  ui_story_1014_10140402_45_dialog_content = "這個嘛，因為我只涉及基層工作所以......",
  ui_story_1014_10140402_46_dialog_content = "那，黃昏鎮這邊有類型特殊的暗鬼嗎？",
  ui_story_1014_10140402_47_dialog_content = "這一點我也不太......",
  ui_story_1014_10140402_48_dialog_content = "不過，你可以問我一些別的問題嘛，比如黃昏鎮的美食、歷史、地標景點......",
  ui_story_1014_10140402_49_dialog_content = "吵死了......",
  ui_story_1014_10140501_1_dialog_content = "<color=#e8d9bb>黃昏鎮，外圍地帶</color>",
  ui_story_1014_10140501_2_dialog_content = "卡蓮殿下，根據過往的巡視記錄顯示，前面就是黃昏鎮了。",
  ui_story_1014_10140501_3_dialog_content = "負責接應的李奧他們應該也快到了，PlayerName，準備降落吧。",
  ui_story_1014_10140501_4_dialog_content = "<color=#e8d9bb>轟——</color>",
  ui_story_1014_10140501_5_dialog_content = "什麼聲音？！",
  ui_story_1014_10140501_6_dialog_content = "是爆炸。",
  ui_story_1014_10140501_7_dialog_content = "阿克希亞，外面情況混亂，妳先回到休眠艙。",
  ui_story_1014_10140501_8_dialog_content = "但現在這個情形，似乎很需要阿克希亞。",
  ui_story_1014_10140501_9_dialog_content = "西恩，外面到底出了什麼事？",
  ui_story_1014_10140501_10_dialog_content = "正常正常，大家稍安勿躁。",
  ui_story_1014_10140501_11_dialog_content = "不過又是一些圍過來的暗鬼罷了。",
  ui_story_1014_10140501_12_dialog_content = "可是......下面的民眾們，好像紛紛停下來了？",
  ui_story_1014_10140501_13_dialog_content = "他們都在抬頭看著什麼。",
  ui_story_1014_10140501_14_dialog_content = "一定是PlayerName的巨像太引人注意啦！",
  ui_story_1014_10140501_15_dialog_content = "<color=#e8d9bb>嗡......</color>",
  ui_story_1014_10140501_16_dialog_content = "不對勁。",
  ui_story_1014_10140501_17_dialog_content = "PlayerName，快找地方著陸。",
  ui_story_1014_10140501_18_dialog_content = "好......好的！那麼大家坐穩了！",
  ui_story_1014_10140501_19_dialog_content = "雖然沿途有些坎坷，但歡迎來到黃昏鎮！",
  ui_story_1014_10140501_20_dialog_content = "這裡處於艾斯特拉大陸邊陲，氣候宜人、民風淳樸......",
  ui_story_1014_10140501_21_dialog_content = "閃開！閃開，都讓一讓......",
  ui_story_1014_10140501_22_dialog_content = "咳咳咳咳咳......好大的灰塵！",
  ui_story_1014_10140501_23_dialog_content = "哈哈哈，這個嘛......有的時候是會有這樣的情況發生。",
  ui_story_1014_10140501_24_dialog_content = "請問一下，你們準備前往什麼地方？需要我的幫助嗎？",
  ui_story_1014_10140501_25_dialog_content = "這裡離黃昏鎮還遠嗎？",
  ui_story_1014_10140501_26_dialog_content = "這就是黃昏鎮的週邊區了！你們是......來自鎮外部落的人？",
  ui_story_1014_10140501_27_dialog_content = "知道了，多謝。",
  ui_story_1014_10140501_28_dialog_content = "等一下，如果你們要去黃昏鎮的話，可以先跟著我們！",
  ui_story_1014_10140501_29_dialog_content = "不好意思，現在一分鐘也不能再耽誤了。",
  ui_story_1014_10140501_30_dialog_content = "我勸你們也趕緊先找地方避難。",
  ui_story_1014_10140501_31_dialog_content = "避難？",
  ui_story_1014_10140501_32_dialog_content = "天空的顏色異常，這是<color=#FFB400>極光爆發</color>的徵兆。",
  ui_story_1014_10140501_33_dialog_content = "不快點找地方避難的話，到時候爆發災害，誰都救不了你們。",
  ui_story_1014_10140501_34_dialog_content = "極光爆發......",
  ui_story_1014_10140501_35_dialog_content = "我只在教科書裡見過這個概念，連極光頻發的北境都鮮少出現爆發現象。",
  ui_story_1014_10140501_36_dialog_content = "除非是常年棲居在邊境一代的原住民，否則也不會有過這種經歷。",
  ui_story_1014_10140501_37_dialog_content = "<color=#e8d9bb>嗶——嗶——</color>",
  ui_story_1014_10140501_38_dialog_content = "是黃昏鎮的預警！",
  ui_story_1014_10140501_39_dialog_content = "各位，按照你們的速度，今天無論如何也沒辦法抵達黃昏鎮的。",
  ui_story_1014_10140501_40_dialog_content = "我是黃昏鎮啟光駐地的基層軍官西恩，大家如果相信我的話......",
  ui_story_1014_10140501_41_dialog_content = "我來帶著大家前往安全的臨時戰壕！",
  ui_story_1014_10140501_42_dialog_content = "相信你們？光憑你們這幾個小孩子？",
  ui_story_1014_10140501_43_dialog_content = "可是，眼下我們也沒有任何戰鬥力了，要是再碰上一次暗鬼襲擊......",
  ui_story_1014_10140501_44_dialog_content = "暗鬼？難道說，你們的部落也......",
  ui_story_1014_10140501_45_dialog_content = "......是的。這樣下去，我們這種周邊部落只會愈來愈少。",
  ui_story_1014_10140501_46_dialog_content = "向黃昏鎮的方向遷徙，也算是唯一的活路。",
  ui_story_1014_10140501_47_dialog_content = "不要再跟他廢話了，我們只不過是去借住一下。",
  ui_story_1014_10140501_48_dialog_content = "總有一天，我們還會重新回去......",
  ui_story_1014_10140501_49_dialog_content = "<color=#e8d9bb>隆隆隆......</color>",
  ui_story_1014_10140501_50_dialog_content = "這次是來自地面的聲音。",
  ui_story_1014_10140501_51_dialog_content = "嘎吼......",
  ui_story_1014_10140501_52_dialog_content = "<anim type=Shake><size=45>吼！！！！！！</size></anim>",
  ui_story_1014_10140501_53_dialog_content = "是暗鬼......暗鬼跟上來了！",
  ui_story_1014_10140501_54_dialog_content = "趁著這種能量亂流爆發的時候攻過來嗎，牠們也算是有點策略。",
  ui_story_1014_10140501_55_dialog_content = "貝爾塔。",
  ui_story_1014_10140501_56_dialog_content = "是！",
  ui_story_1014_10140501_57_dialog_content = "讓我來掩護大家撤退吧！",
  ui_story_1014_10140501_58_dialog_content = "一昧躲避不是長久的戰術。",
  ui_story_1014_10140501_59_dialog_content = "請讓阿克希亞去戰鬥，不然的話，阿克希亞就要採取強硬手段了。",
  ui_story_1014_10140501_60_dialog_content = "暫時先不要想著戰鬥的事情了啊！",
  ui_story_1014_10140501_61_dialog_content = "衝過去的話，這些手無寸鐵的民眾該怎麼辦？",
  ui_story_1014_10140501_62_dialog_content = "阿克希亞有保護他們的自信。",
  ui_story_1014_10140501_63_dialog_content = "請放心，很快的。",
  ui_story_1014_10140501_64_dialog_content = "我都說了不可以了！",
  ui_story_1014_10140501_65_dialog_content = "貝爾塔，阿克希亞，妳們兵分兩路。",
  ui_story_1014_10140501_66_dialog_content = "貝爾塔、卡蓮、西恩，你們去疏散這些民眾。",
  ui_story_1014_10140501_67_dialog_content = "阿克希亞，鶯歌，還有薇絲，我們四個人去迎戰暗鬼！",
  ui_story_1014_10140501_68_dialog_content = "明白。",
  ui_story_1014_10140501_69_dialog_content = "不必耗費戰鬥人力了。",
  ui_story_1014_10140501_70_dialog_content = "這些暗鬼就交給我們鐵棘騎士團吧。",
  ui_story_1014_10140501_71_dialog_content = "騎士團有失遠迎，好在沒有出現什麼傷亡。",
  ui_story_1014_10140501_72_dialog_content = "李奧，你來得很及時，在為我引路之前，請務必和我們共同擊退暗鬼。",
  ui_story_1014_10140501_73_dialog_content = "這是當然的，戰鬥一觸即發，恕我不能下馬了，卡蓮殿下。",
  ui_story_1014_10140501_74_dialog_content = "這沒什麼，不用效忠於禮數，只要效忠於你的姓名。",
  ui_story_1014_10140501_75_dialog_content = "哈哈哈哈，比起姓名，這座黃昏鎮才是我成為騎士的原因。",
  ui_story_1014_10140501_76_dialog_content = "騎士團的諸位，舉起你們手中的劍！",
  ui_story_1014_10140501_77_dialog_content = "這場戰鬥只有一項要求——",
  ui_story_1014_10140501_78_dialog_content = "哪怕只剩最後一口氣，也要將暗鬼盡數消滅。",
  ui_story_1014_10140501_79_dialog_content = "突擊！",
  ui_story_1014_10140602_1_dialog_content = "保持陣型，不要亂。",
  ui_story_1014_10140602_2_dialog_content = "優先清理側面的敵人。",
  ui_story_1014_10140602_3_dialog_content = "是！",
  ui_story_1014_10140602_4_dialog_content = "又有一大群暗鬼壓過來了！數量比剛才還多！",
  ui_story_1014_10140602_5_dialog_content = "這樣打下去有點吃力，我們要不要後撤一些？",
  ui_story_1014_10140602_6_dialog_content = "噢，我看見牠們了。真是不少。",
  ui_story_1014_10140602_7_dialog_content = "那我們......",
  ui_story_1014_10140602_8_dialog_content = "騎士團全員！卸下重裝備，做好突擊準備！",
  ui_story_1014_10140602_9_dialog_content = "是！",
  ui_story_1014_10140602_10_dialog_content = "欸，突擊？現在嗎？",
  ui_story_1014_10140602_11_dialog_content = "以我們的力量，跟這群暗鬼硬碰硬不是個好選擇吧......",
  ui_story_1014_10140602_12_dialog_content = "外鄉人，你們不用跟上，在這裡看好吧。",
  ui_story_1014_10140602_13_dialog_content = "騎士團全員！錐形陣，分兩隊。一隊跟我，一隊跟著副手。",
  ui_story_1014_10140602_14_dialog_content = "貫穿敵陣後兩隊再分離。",
  ui_story_1014_10140602_15_dialog_content = "現在，看好我手上的旗幟。",
  ui_story_1014_10140602_16_dialog_content = "鐵棘騎士團，衝鋒！",
  ui_story_1014_10140602_17_dialog_content = "<size=50>衝鋒！！！</size>",
  ui_story_1014_10140602_18_dialog_content = "他們真的向那群暗鬼衝過去了！這樣......是不是太莽撞了？",
  ui_story_1014_10140602_19_dialog_content = "未必。你仔細看。",
  ui_story_1014_10140602_20_dialog_content = "他們的衝鋒比想像中順利得多。",
  ui_story_1014_10140602_21_dialog_content = "真是這樣！那麼大一群暗鬼竟然擋不住騎士團的攻勢！",
  ui_story_1014_10140602_22_dialog_content = "就像被一把刀從中切開......",
  ui_story_1014_10140602_23_dialog_content = "這是怎麼做到的？！",
  ui_story_1014_10140602_24_dialog_content = "我似乎有點明白了。貝爾塔用的詞很合適。",
  ui_story_1014_10140602_25_dialog_content = "他們就像是刀。",
  ui_story_1014_10140602_26_dialog_content = "用刀去切割牲畜的時候，沒有人會比較刀和牲畜哪者更重。",
  ui_story_1014_10140602_27_dialog_content = "只要刀足夠鋒利，切割就能完成。",
  ui_story_1014_10140602_28_dialog_content = "切割......",
  ui_story_1014_10140602_29_dialog_content = "你看，李奧帶著一半人回來了。",
  ui_story_1014_10140602_30_dialog_content = "<color=#e8d9bb>喀嗒、喀嗒、喀嗒......</color>",
  ui_story_1014_10140602_31_dialog_content = "怎麼樣，外鄉人。突擊這個選擇還不差吧？",
  ui_story_1014_10140602_32_dialog_content = "戰場不是簡單的加減法。同樣的力量，在不同的戰術下可以發揮不同的作用。",
  ui_story_1014_10140602_33_dialog_content = "這裡是遙遠的邊境，我們沒有實力去跟暗鬼硬碰硬。",
  ui_story_1014_10140602_34_dialog_content = "暗鬼不懂戰術，我們懂。這才是我們的優勢。",
  ui_story_1014_10140602_35_dialog_content = "戰術......那，你是怎麼判斷剛才要發動突擊的？",
  ui_story_1014_10140602_36_dialog_content = "因為我瞭解這種類型的暗鬼。",
  ui_story_1014_10140602_37_dialog_content = "牠們攻擊性強，擅長集群行動。但弊端也很明顯，牠們不擅長應對衝擊。",
  ui_story_1014_10140602_38_dialog_content = "所以面對牠們，哪怕是敵強我弱，也一定要主動出擊。",
  ui_story_1014_10140602_39_dialog_content = "我們的衝鋒將力量集中在一條線上，先聲奪人削減了敵方戰力。",
  ui_story_1014_10140602_40_dialog_content = "另一方面，衝鋒撕開了暗鬼的陣型，敵方力量愈分散，戰局對我們就愈有利。",
  ui_story_1014_10140602_41_dialog_content = "你看，我留了一半人在敵人腹地。",
  ui_story_1014_10140602_42_dialog_content = "他們會接著跟暗鬼周旋，切割戰場的同時消滅小股敵人，將戰場進一步攪亂。",
  ui_story_1014_10140602_43_dialog_content = "好厲害！原來跟暗鬼作戰要思考這麼多事情。",
  ui_story_1014_10140602_44_dialog_content = "我們的力量明明與暗鬼相差懸殊，戰場形勢看起來竟然勢均力敵......",
  ui_story_1014_10140602_45_dialog_content = "所以我才說，戰術比力量更重要。",
  ui_story_1014_10140602_46_dialog_content = "不過外鄉人，你也有兩下子，竟然能先於我洞察到暗鬼的動向。",
  ui_story_1014_10140602_47_dialog_content = "這份戰場上的感知力可是很難得的。",
  ui_story_1014_10140602_48_dialog_content = "這個啊，也沒有什麼值得吹噓的地方。",
  ui_story_1014_10140602_49_dialog_content = "我跟你不一樣。我不是光靈，是空裔。",
  ui_story_1014_10140602_50_dialog_content = "空裔？傳說中的那個種族？",
  ui_story_1014_10140602_51_dialog_content = "哈哈哈哈，有意思！書裡的人物走到現實來了嗎。",
  ui_story_1014_10140602_52_dialog_content = "那麼空裔，用你敏銳的感知力猜猜我們接下來要幹嘛？",
  ui_story_1014_10140602_53_dialog_content = "要......要趕在敵人重組陣型前發起進攻？",
  ui_story_1014_10140602_54_dialog_content = "不，我們要後撤。",
  ui_story_1014_10140602_55_dialog_content = "欸？為什麼？明明剛建立了優勢。",
  ui_story_1014_10140602_56_dialog_content = "不能把目光滯留在面前這個戰場上。",
  ui_story_1014_10140602_57_dialog_content = "我們的目的是攔截所有暗鬼，光現在這樣還不夠。",
  ui_story_1014_10140602_58_dialog_content = "背後是地勢更險峻的隘口，戰場一定會向那邊推移。",
  ui_story_1014_10140602_59_dialog_content = "必須提前做好準備。",
  ui_story_1014_10140602_60_dialog_content = "外鄉人，願意幫幫忙嗎？",
  ui_story_1014_10140602_61_dialog_content = "當然！我還想再見識見識你的戰術！",
  ui_story_1014_10140602_62_dialog_content = "嗯，我們本來也是要對抗暗鬼的。",
  ui_story_1014_10140602_63_dialog_content = "那個，幫不幫忙都好說。不過我有個問題是......",
  ui_story_1014_10140602_64_dialog_content = "你們看見西恩那傢伙了嗎？",
  ui_story_1014_10140602_65_dialog_content = "<size=45>殺啊！！！</size>",
  ui_story_1014_10140602_66_dialog_content = "讓我看看還有多少！！！",
  ui_story_1014_10140602_67_dialog_content = "啟光的士兵，沒想到你這麼能打。",
  ui_story_1014_10140602_68_dialog_content = "欸？哎呀那個，謝謝誇獎！",
  ui_story_1014_10140602_69_dialog_content = "在我們鐵棘騎士團的戰場上還能如此顯眼。",
  ui_story_1014_10140602_70_dialog_content = "像你這樣出類拔萃的戰士應該不缺少誇獎。",
  ui_story_1014_10140602_71_dialog_content = "是......是嗎？其實我很少被誇。",
  ui_story_1014_10140602_72_dialog_content = "不過，你為什麼要跟上來？團長不是讓你們原地等待嗎？",
  ui_story_1014_10140602_73_dialog_content = "有這種事？！",
  ui_story_1014_10140602_74_dialog_content = "你看，你的同伴都停在那邊。",
  ui_story_1014_10140602_75_dialog_content = "哦哦，我想起來了，李奧團長說外鄉人不用跟上來。",
  ui_story_1014_10140602_76_dialog_content = "但是，我不是外鄉人啊！我也生活在黃昏鎮唷。",
  ui_story_1014_10140602_77_dialog_content = "......",
  ui_story_1014_10140602_78_dialog_content = "有沒有人說過你不太聰明？",
  ui_story_1014_10140602_79_dialog_content = "嗯，有。",
  ui_story_1014_10140602_80_dialog_content = "好歹看出我是在挖苦你啊......",
  ui_story_1014_10140602_81_dialog_content = "算了。托你的福，戰局明朗了許多。",
  ui_story_1014_10140602_82_dialog_content = "本來我們的任務只是跟暗鬼周旋。看現在的樣子，全殲敵人也不難。",
  ui_story_1014_10140602_83_dialog_content = "當然要全殲牠們！絕不能放過一隻暗鬼！",
  ui_story_1014_10140602_84_dialog_content = "你的熱情真高漲啊。不錯，這是件好事。",
  ui_story_1014_10140602_85_dialog_content = "我早就聽說過鐵棘騎士團和李奧團長的名頭。",
  ui_story_1014_10140602_86_dialog_content = "能和這樣一支英雄般的部隊並肩作戰，我可是連骨頭都在沸騰啊！",
  ui_story_1014_10140602_87_dialog_content = "把這些手弩藏在草叢裡。準備工作差不多了。",
  ui_story_1014_10140602_88_dialog_content = "正好，他們回來了。",
  ui_story_1014_10140602_89_dialog_content = "<color=#e8d9bb>喀嗒、喀嗒、喀嗒......</color>",
  ui_story_1014_10140602_90_dialog_content = "團長。",
  ui_story_1014_10140602_91_dialog_content = "做得不錯啊，比我想像中更漂亮。",
  ui_story_1014_10140602_92_dialog_content = "這次能如此順利，多虧了這位啟光戰士的協助。",
  ui_story_1014_10140602_93_dialog_content = "哎呀，也不是......",
  ui_story_1014_10140602_94_dialog_content = "嗯，我看到了。打得那麼起勁，想不注意到都難。",
  ui_story_1014_10140602_95_dialog_content = "你是啟光的軍官？",
  ui_story_1014_10140602_96_dialog_content = "是的！我是黃昏鎮駐軍少尉軍官西恩！",
  ui_story_1014_10140602_97_dialog_content = "黃昏鎮駐軍啊。我竟然沒聽說過隔壁有這麼勇猛的戰士。",
  ui_story_1014_10140602_98_dialog_content = "沒有沒有！我在同輩裡並不突出，又缺乏戰場經驗。",
  ui_story_1014_10140602_99_dialog_content = "李奧團長這樣的人物當然不會聽說過我的名字。",
  ui_story_1014_10140602_100_dialog_content = "看樣子你知道我。",
  ui_story_1014_10140602_101_dialog_content = "知道！黃昏鎮誰不知道鐵棘騎士團的威名！",
  ui_story_1014_10140602_102_dialog_content = "既然這樣。小兄弟，你可以加入我們了。",
  ui_story_1014_10140602_103_dialog_content = "啊？",
  ui_story_1014_10140602_104_dialog_content = "出色的戰士應該在戰場上展現價值，而不是躺在軍營裡混混度日。",
  ui_story_1014_10140602_105_dialog_content = "加入鐵棘騎士團，我能讓你的名字一個月內傳遍黃昏鎮的大街小巷。",
  ui_story_1014_10140602_106_dialog_content = "這......但是......",
  ui_story_1014_10140602_107_dialog_content = "咳咳。李奧團長，這樣越界的邀請可不符合規矩。",
  ui_story_1014_10140602_108_dialog_content = "或者請你至少把拉攏友軍士兵的行為放在暗地裡。",
  ui_story_1014_10140602_109_dialog_content = "哈哈，抱歉抱歉，但是我不懂這有什麼見不得人的。",
  ui_story_1014_10140602_110_dialog_content = "白夜城和啟光不過是各自的棲身之所，最終的敵人都是暗鬼。",
  ui_story_1014_10140602_111_dialog_content = "我只是希望這位小兄弟有一個更好的歸宿。",
  ui_story_1014_10140602_112_dialog_content = "當然，這位女軍官的表現也非常亮眼，如果有意加入，鐵棘騎士團隨時恭候。",
  ui_story_1014_10140602_113_dialog_content = "你......沒想到，鐵棘騎士團的團長擅長的竟然是遊說。",
  ui_story_1014_10140602_114_dialog_content = "卸任來迦南城當個政客吧，我也希望你有個更好的歸宿。",
  ui_story_1014_10140602_115_dialog_content = "政客啊，不錯的選擇，我會考慮的。",
  ui_story_1014_10140602_116_dialog_content = "睏了。",
  ui_story_1014_10140602_117_dialog_content = "欸？",
  ui_story_1014_10140602_118_dialog_content = "哈——阿克希亞睏了。",
  ui_story_1014_10140602_119_dialog_content = "偏偏在這種時候......",
  ui_story_1014_10140602_120_dialog_content = "算了，沒辦法的事情。回休眠艙吧，阿克希亞。",
  ui_story_1014_10140602_121_dialog_content = "嗯，你們要加油。",
  ui_story_1014_10140602_122_dialog_content = "等阿克希亞睡醒了，再來幫助你們。",
  ui_story_1014_10140602_123_dialog_content = "別想那麼多了，妳好好休息。",
  ui_story_1014_10140602_124_dialog_content = "PlayerName，照看好休眠艙。",
  ui_story_1014_10140602_125_dialog_content = "哦，嗯！",
  ui_story_1014_10140602_126_dialog_content = "她鑽到盒子裡去了！",
  ui_story_1014_10140602_127_dialog_content = "你們這些外鄉人，真是讓我大開眼界啊。",
  ui_story_1014_10140602_128_dialog_content = "阿克希亞的身體不太好，需要時常在這個「休眠艙」裡休息。",
  ui_story_1014_10140602_129_dialog_content = "那為什麼要帶她來邊境這麼危險的地方？",
  ui_story_1014_10140602_130_dialog_content = "因為運送她安全抵達黃昏鎮就是我們此行的任務。",
  ui_story_1014_10140602_131_dialog_content = "啊，我懂了。既然是任務，我就不過問了。",
  ui_story_1014_10140602_132_dialog_content = "閒聊到此為止吧，我能感受到不遠處的那幫傢伙在蠢蠢欲動。",
  ui_story_1014_10140602_133_dialog_content = "暗鬼出現在視野裡之前，我得在這裡豎起一道鐵鑄的柵欄。",
  ui_story_1014_10140602_134_dialog_content = "我們也來幫忙。需要我們進行什麼樣的布置？",
  ui_story_1014_10140602_135_dialog_content = "卡蓮殿下和您的朋友們儘管放手去戰鬥就行，不必受制於騎士團的布置。",
  ui_story_1014_10140602_136_dialog_content = "以您的身分，我該把戰場的指揮權交給您才是。",
  ui_story_1014_10140602_137_dialog_content = "只是眼下情況特殊，我擔心騎士團無法適應。多有僭越，還請您寬恕。",
  ui_story_1014_10140602_138_dialog_content = "......",
  ui_story_1014_10140602_139_dialog_content = "指揮權歸屬於更容易帶大家取勝的人，不用在這件事上有多餘的客氣。",
  ui_story_1014_10140602_140_dialog_content = "讓我們自由行動的話，我們會去防線東邊幫助防守。",
  ui_story_1014_10140602_141_dialog_content = "如果我的判斷沒錯，那邊騎士團的防線相對薄弱。",
  ui_story_1014_10140602_142_dialog_content = "東邊......對，您說的沒錯，騎士團人手不夠充足，那邊是唯一的隱患。",
  ui_story_1014_10140602_143_dialog_content = "卡蓮殿下竟然有如此精準的戰略眼光。",
  ui_story_1014_10140602_144_dialog_content = "血統沒辦法為我帶來騎士長的名號，不要只把我當作「白夜城的公主」。",
  ui_story_1014_10140602_145_dialog_content = "當然不會，我相信白夜城騎士的頭銜。",
  ui_story_1014_10140602_146_dialog_content = "我們頭頂著相同的榮耀在戰鬥。",
  ui_story_1014_10140602_147_dialog_content = "PlayerName，這裡算是比較安全的後方，把阿克希亞的休眠艙安置在這吧。",
  ui_story_1014_10140602_148_dialog_content = "嗯，好的。",
  ui_story_1014_10140602_149_dialog_content = "按照李奧的安排，東邊的防線相對薄弱。",
  ui_story_1014_10140602_150_dialog_content = "我們來補足那裡的防守力量。",
  ui_story_1014_10140602_151_dialog_content = "好的，卡蓮大人。",
  ui_story_1014_10140602_152_dialog_content = "卡蓮妳還滿配合李奧指揮的。",
  ui_story_1014_10140602_153_dialog_content = "他的指揮經驗豐富。你也看到了，在這個戰場上聽他的比較容易贏。",
  ui_story_1014_10140602_154_dialog_content = "但他其實沒有給我們安排具體的任務。",
  ui_story_1014_10140602_155_dialog_content = "嗯，他不會安排的。",
  ui_story_1014_10140602_156_dialog_content = "欸，為什麼這麼說？",
  ui_story_1014_10140602_157_dialog_content = "我感受到了一段李奧刻意保持的距離。",
  ui_story_1014_10140602_158_dialog_content = "他不會對我卑躬屈膝，同樣也不會對我發號施令。",
  ui_story_1014_10140602_159_dialog_content = "因為我是白夜城城主的女兒。",
  ui_story_1014_10140602_160_dialog_content = "這樣啊。我不是很懂，這算是壞事嗎？",
  ui_story_1014_10140602_161_dialog_content = "我也不知道。",
  ui_story_1014_10140602_162_dialog_content = "其實我更希望他是個不尊禮數的純粹的戰士。",
  ui_story_1014_10140602_163_dialog_content = "身在遙遠的邊境，眼裡能看到的只有戰場。",
  ui_story_1014_10140602_164_dialog_content = "但他並不是這樣。相反，他會在意我的身分。",
  ui_story_1014_10140602_165_dialog_content = "他用這段與我相隔的距離把「臣服」變成了「尊重」。",
  ui_story_1014_10140602_166_dialog_content = "所以我也只能尊重他，自己來配合他安排好的戰術。",
  ui_story_1014_10140602_167_dialog_content = "好複雜啊。這叫什麼，戰場政治？",
  ui_story_1014_10140602_168_dialog_content = "很貼切的名字。",
  ui_story_1014_10140602_169_dialog_content = "白夜城的悲哀可能就在這裡，我們總是離不開政治。",
  ui_story_1014_10140602_170_dialog_content = "<color=#e8d9bb>轟——</color>",
  ui_story_1014_10140602_171_dialog_content = "！！！",
  ui_story_1014_10140602_172_dialog_content = "什麼聲音？",
  ui_story_1014_10140602_173_dialog_content = "<color=#e8d9bb>轟！！！</color>",
  ui_story_1014_10140602_174_dialog_content = "有東西向這邊過來了！",
  ui_story_1014_10140602_175_dialog_content = "暗能很濃郁，應該是大批敵人。",
  ui_story_1014_10140602_176_dialog_content = "而且......似乎有一個個頭不小的傢伙！",
  ui_story_1014_10140701_1_dialog_content = "鐵棘騎士團，做好迎敵準備！",
  ui_story_1014_10140701_2_dialog_content = "沒有我的命令，任何人不許擅自離開陣列！",
  ui_story_1014_10140701_3_dialog_content = "是！",
  ui_story_1014_10140701_4_dialog_content = "<color=#e8d9bb>轟——轟——</color>",
  ui_story_1014_10140701_5_dialog_content = "衝過來的暗鬼數量比剛才更多了。",
  ui_story_1014_10140701_6_dialog_content = "這麼誇張的動靜，應該是那傢伙。",
  ui_story_1014_10140701_7_dialog_content = "「<color=#FFB400>癲蹄</color>」。",
  ui_story_1014_10140701_8_dialog_content = "癲蹄......又是牠......",
  ui_story_1014_10140701_9_dialog_content = "什麼東西？",
  ui_story_1014_10140701_10_dialog_content = "一隻特異的暗鬼，力量誇張得很。",
  ui_story_1014_10140701_11_dialog_content = "之前鐵棘騎士團跟牠交過手，雙方都沒討到什麼便宜。",
  ui_story_1014_10140701_12_dialog_content = "這次有把握攔住牠嗎？",
  ui_story_1014_10140701_13_dialog_content = "不是有沒有把握的問題，是必須攔住。",
  ui_story_1014_10140701_14_dialog_content = "跨過了我們，背後就是黃昏鎮。",
  ui_story_1014_10140701_15_dialog_content = "不要指望有另一支鐵棘騎士團能阻止牠。",
  ui_story_1014_10140701_16_dialog_content = "等等，你們看那邊！暗鬼群的最前面！",
  ui_story_1014_10140701_17_dialog_content = "有人！有平民在逃跑！",
  ui_story_1014_10140701_18_dialog_content = "有沒有人......有沒有人......",
  ui_story_1014_10140701_19_dialog_content = "要......要跑不動了......",
  ui_story_1014_10140701_20_dialog_content = "再堅持堅持，就......就快到黃昏鎮了。",
  ui_story_1014_10140701_21_dialog_content = "到那裡會有人保護我們的，一定會的。",
  ui_story_1014_10140701_22_dialog_content = "能堅持到嗎......",
  ui_story_1014_10140701_23_dialog_content = "我能聽到，背後的聲音......怪物的聲音......",
  ui_story_1014_10140701_24_dialog_content = "那些聲音，好近......好近......",
  ui_story_1014_10140701_25_dialog_content = "真的有人！他們就快被追上了！",
  ui_story_1014_10140701_26_dialog_content = "得快點去救他們！不然就來不及了！",
  ui_story_1014_10140701_27_dialog_content = "對啊！李奧團長，我們該怎麼救援？",
  ui_story_1014_10140701_28_dialog_content = "......",
  ui_story_1014_10140701_29_dialog_content = "李奧團長！",
  ui_story_1014_10140701_30_dialog_content = "鐵棘騎士團，不能離開陣列。",
  ui_story_1014_10140701_31_dialog_content = "<size=45>什麼？！</size>",
  ui_story_1014_10140701_32_dialog_content = "暗鬼群的衝擊馬上要來臨，放棄陣列是自殺式行為。",
  ui_story_1014_10140701_33_dialog_content = "我們不能離開陣列。",
  ui_story_1014_10140701_34_dialog_content = "那他們該怎麼辦！那些正在逃跑的平民！",
  ui_story_1014_10140701_35_dialog_content = "他們就快被追上了！",
  ui_story_1014_10140701_36_dialog_content = "對不起。我們是騎士，不是神。我們拯救不了所有人。",
  ui_story_1014_10140701_37_dialog_content = "你......",
  ui_story_1014_10140701_38_dialog_content = "我不能為了難民把黃昏鎮暴露在暗鬼潮下，也不能為了平民讓我的騎士白白犧牲。",
  ui_story_1014_10140701_39_dialog_content = "這裡是邊境，每一條命都很珍貴。選擇很重要。",
  ui_story_1014_10140701_40_dialog_content = "那我們就看著他們被暗鬼殺死？",
  ui_story_1014_10140701_41_dialog_content = "如果看不下去的話，你們可以自行行動。",
  ui_story_1014_10140701_42_dialog_content = "你們並非鐵棘騎士團的成員。",
  ui_story_1014_10140701_43_dialog_content = "......",
  ui_story_1014_10140701_44_dialog_content = "好，那就拜託守住防線，不要讓阿克希亞的休眠艙受損。",
  ui_story_1014_10140701_45_dialog_content = "我們來做你沒做的選擇！",
  ui_story_1014_10140701_46_dialog_content = "<size=40>呃啊！！！</size>",
  ui_story_1014_10140701_47_dialog_content = "哥哥！你怎麼了！",
  ui_story_1014_10140701_48_dialog_content = "那些怪物就在我背後！我的......我的腿被割傷了。",
  ui_story_1014_10140701_49_dialog_content = "你快跑，快跑！",
  ui_story_1014_10140701_50_dialog_content = "不要啊，哥哥你......",
  ui_story_1014_10140701_51_dialog_content = "<size=40>呀！！！</size>",
  ui_story_1014_10140701_52_dialog_content = "<size=40>滾開啊！！！！！！</size>",
  ui_story_1014_10140701_53_dialog_content = "欸，這是......",
  ui_story_1014_10140701_54_dialog_content = "卡蓮，這邊還有！",
  ui_story_1014_10140701_55_dialog_content = "明白。",
  ui_story_1014_10140701_56_dialog_content = "遠處的就交給我吧！",
  ui_story_1014_10140701_57_dialog_content = "大家跟我來！再堅持一會就安全了！",
  ui_story_1014_10140701_58_dialog_content = "太好了！有人來救我們了！",
  ui_story_1014_10140701_59_dialog_content = "快走！快跟著他們！",
  ui_story_1014_10140701_60_dialog_content = "恐怕沒有時間給我們撤回鐵棘騎士團的防線之後了。",
  ui_story_1014_10140701_61_dialog_content = "暗鬼浪潮在接近，準備應對衝擊。",
  ui_story_1014_10140701_62_dialog_content = "這麼快？周圍這些平民該怎麼辦！",
  ui_story_1014_10140701_63_dialog_content = "讓他們聚攏在一起！",
  ui_story_1014_10140701_64_dialog_content = "如果有餘力的話，我會盡力保護他們！",
  ui_story_1014_10140701_65_dialog_content = "看好，來了。",
  ui_story_1014_10140701_66_dialog_content = "<color=#e8d9bb>轟——轟——轟——</color>",
  ui_story_1014_10140701_67_dialog_content = "<anim type=Shake><size=45>嘎——！嗷——！</size></anim>",
  ui_story_1014_10140701_68_dialog_content = "薇絲，妳往後撤一點，小心被暗鬼近身。",
  ui_story_1014_10140701_69_dialog_content = "這種時候哪還有後撤的餘力啊！小心右邊！",
  ui_story_1014_10140701_70_dialog_content = "嗚哇這麼多！同伴呢？我現在在哪？",
  ui_story_1014_10140701_71_dialog_content = "嘁，要是阿克希亞在就好了。",
  ui_story_1014_10140701_72_dialog_content = "喂，這句話很傷人的啊！我在不行嗎？",
  ui_story_1014_10140701_73_dialog_content = "大家躲在我身後！不要亂跑！",
  ui_story_1014_10140701_74_dialog_content = "我來保護你們......",
  ui_story_1014_10140701_75_dialog_content = "呀！！！有暗鬼過來了！！！",
  ui_story_1014_10140701_76_dialog_content = "欸？從哪裡？",
  ui_story_1014_10140701_77_dialog_content = "這邊！這邊也有！！！",
  ui_story_1014_10140701_78_dialog_content = "等一下！我這就過去！",
  ui_story_1014_10140701_79_dialog_content = "嘎！！！",
  ui_story_1014_10140701_80_dialog_content = "嘶......怎麼哪裡都是！",
  ui_story_1014_10140701_81_dialog_content = "PlayerName，可以幫我感知一下敵人的方位嗎？",
  ui_story_1014_10140701_82_dialog_content = "我搞不清楚牠們......",
  ui_story_1014_10140701_83_dialog_content = "<size=45>所有人！！！快閃開！！！</size>",
  ui_story_1014_10140701_84_dialog_content = "閃開？閃到哪裡？",
  ui_story_1014_10140701_85_dialog_content = "我不知道該怎麼說，但是......離現在的戰場愈遠愈好！",
  ui_story_1014_10140701_86_dialog_content = "<color=#e8d9bb>轟——轟——</color>",
  ui_story_1014_10140701_87_dialog_content = "<color=#e8d9bb>轟！！！</color>",
  ui_story_1014_10140701_88_dialog_content = "哇，這傢伙長得真誇張啊。",
  ui_story_1014_10140701_89_dialog_content = "別發呆了！",
  ui_story_1014_10140701_90_dialog_content = "<anim type=Shake><size=50>嗷！！！</size></anim>",
  ui_story_1014_10140701_91_dialog_content = "咳咳。陣型一下子被牠衝散了。大家還好嗎？",
  ui_story_1014_10140701_92_dialog_content = "PlayerName提前發出警告了，應該沒人會傻到中招。",
  ui_story_1014_10140701_93_dialog_content = "我比較擔心的是那些平民。",
  ui_story_1014_10140701_94_dialog_content = "陣型被衝散之後，他們更容易遭到襲擊了。",
  ui_story_1014_10140701_95_dialog_content = "說得對啊！我們得去幫幫他們！",
  ui_story_1014_10140701_96_dialog_content = "我們脫得開身嗎？",
  ui_story_1014_10140701_97_dialog_content = "救命啊！！！",
  ui_story_1014_10140701_98_dialog_content = "暗鬼！到處都是暗鬼！",
  ui_story_1014_10140701_99_dialog_content = "救援的人呢？他們去哪了！",
  ui_story_1014_10140701_100_dialog_content = "大家不要慌張！靠近我這裡！我會保護你們！",
  ui_story_1014_10140701_101_dialog_content = "PlayerName，敵人在......",
  ui_story_1014_10140701_102_dialog_content = "現在到處都是敵人，整個戰場已經混成一團了！",
  ui_story_1014_10140701_103_dialog_content = "平民根本沒辦法聚攏，他們的人群已經被暗鬼衝散。",
  ui_story_1014_10140701_104_dialog_content = "那......那該怎麼辦？",
  ui_story_1014_10140701_105_dialog_content = "我在想，我在想......",
  ui_story_1014_10140701_106_dialog_content = "不只是他們，想想我們自己吧。",
  ui_story_1014_10140701_107_dialog_content = "那個叫癲蹄的怪物還會發起下一次衝鋒，身處暗鬼群裡我們堅持不了多久。",
  ui_story_1014_10140701_108_dialog_content = "妳說得對......牠又要來了......",
  ui_story_1014_10140701_109_dialog_content = "有什麼辦法嗎，鶯歌？妳平時最聰明了。",
  ui_story_1014_10140701_110_dialog_content = "放棄那些平民，我們撤回鐵棘騎士團的防線。",
  ui_story_1014_10140701_111_dialog_content = "欸？但是......",
  ui_story_1014_10140701_112_dialog_content = "李奧對戰場的判斷是正確的。這裡是邊境，我們必須面對己方實力不足的事實。",
  ui_story_1014_10140701_113_dialog_content = "就算我們接著打下去，那些平民也會在混亂中逐一喪生。",
  ui_story_1014_10140701_114_dialog_content = "我們沒辦法救下所有人。",
  ui_story_1014_10140701_115_dialog_content = "......",
  ui_story_1014_10140701_116_dialog_content = "我們已經盡力了。PlayerName，你應該明白現在的局勢。",
  ui_story_1014_10140701_117_dialog_content = "<color=#e8d9bb>轟......</color>",
  ui_story_1014_10140701_118_dialog_content = "聽到遠處的聲音了嗎？那個怪物就快來了。",
  ui_story_1014_10140701_119_dialog_content = "我......我們......",
  ui_story_1014_10140701_120_dialog_content = "如果做不出決定，我會帶你走。",
  ui_story_1014_10140701_121_dialog_content = "！！！",
  ui_story_1014_10140701_122_dialog_content = "白夜城的小姐，幫忙掩護一下。我們開始撤退。",
  ui_story_1014_10140701_123_dialog_content = "但是......",
  ui_story_1014_10140701_124_dialog_content = "我答應他們了，我答應了要保護他們......",
  ui_story_1014_10140701_125_dialog_content = "那就讓你的成長從一個無法履行的諾言開始。",
  ui_story_1014_10140701_126_dialog_content = "<color=#e8d9bb>轟......</color>",
  ui_story_1014_10140701_127_dialog_content = "對不起，我還是想試一下。我不能那麼輕易就食言。",
  ui_story_1014_10140701_128_dialog_content = "因為我選擇了自稱為騎士。",
  ui_story_1014_10140701_129_dialog_content = "妳......",
  ui_story_1014_10140701_130_dialog_content = "貝爾塔！！！",
  ui_story_1014_10140701_131_dialog_content = "自稱為騎士啊。感謝這個名號，讓妳如此聖潔、純淨。",
  ui_story_1014_10140701_132_dialog_content = "欸？",
  ui_story_1014_10140701_133_dialog_content = "嗷——！",
  ui_story_1014_10140701_134_dialog_content = "癲蹄被光能術推開了！那是......",
  ui_story_1014_10140701_135_dialog_content = "第一次見到妳這樣的騎士。",
  ui_story_1014_10140701_136_dialog_content = "是......是嗎？我只是在做騎士該做的。",
  ui_story_1014_10140701_137_dialog_content = "但其他的騎士和妳不一樣。",
  ui_story_1014_10140701_138_dialog_content = "妳好美啊。妳是天使嗎？",
  ui_story_1014_10140701_139_dialog_content = "我也衷心地希望能見到天使，可惜牠們從不降臨。",
  ui_story_1014_10140701_140_dialog_content = "所以有些事情，只能由凡人來代勞了。",
  ui_story_1014_10140701_141_dialog_content = "村民們，跟隨著光芒來到我身邊吧。",
  ui_story_1014_10140701_142_dialog_content = "白夜至上，光明會驅逐邪穢，引導眾生至歸途。",
  ui_story_1014_10140701_143_dialog_content = "你們快看！暗鬼害怕那邊的光！",
  ui_story_1014_10140701_144_dialog_content = "快，快靠過去！那邊能活命！",
  ui_story_1014_10140701_145_dialog_content = "我聽說過，一定是她來了！黃昏鎮的聖女！",
  ui_story_1014_10140701_146_dialog_content = "好厲害！平民們再次聚攏起來了！",
  ui_story_1014_10140701_147_dialog_content = "暗鬼在躲避那個女孩身上發出的光，看樣子跟著她就能安全撤離！",
  ui_story_1014_10140701_148_dialog_content = "嗯，你說得沒錯。策略調整，圍繞那個神祕的女孩，全力掩護四周的平民撤退。",
  ui_story_1014_10140701_149_dialog_content = "收到命令，鶯歌中校！",
  ui_story_1014_10140701_150_dialog_content = "不許你那麼叫我。",
  ui_story_1014_10140701_151_dialog_content = "團長！他們帶著那一批平民回來了！",
  ui_story_1014_10140701_152_dialog_content = "我看到了。側面陣列讓出一個口子，接他們撤到後方。",
  ui_story_1014_10140701_153_dialog_content = "是！",
  ui_story_1014_10140701_154_dialog_content = "是鐵棘騎士團！太好了，到這就安全了。",
  ui_story_1014_10140701_155_dialog_content = "快往前走吧，這荒郊野外的，不進到黃昏鎮怎麼能安心呢。",
  ui_story_1014_10140701_156_dialog_content = "辛苦你了，李奧團長。",
  ui_story_1014_10140701_157_dialog_content = "<color=#FFB400>聖女大人</color>，妳是在挖苦我嗎？",
  ui_story_1014_10140701_158_dialog_content = "當然不是。我沒那麼幼稚，清楚你的處境。",
  ui_story_1014_10140701_159_dialog_content = "難民在不斷逃往黃昏鎮，現在鎮上大門洞開。",
  ui_story_1014_10140701_160_dialog_content = "越過你們的每一隻暗鬼都會直接衝進黃昏鎮，你們當然一步也不能離開防線。",
  ui_story_1014_10140701_161_dialog_content = "謝謝妳為我開脫，我好受多了。",
  ui_story_1014_10140701_162_dialog_content = "你臉上可不是「好受」的表情。這是你之前跟我提過的「尊嚴問題」嗎？",
  ui_story_1014_10140701_163_dialog_content = "算不上。我只是很羡慕妳，可以隨隨便便去做我做不到的事情。",
  ui_story_1014_10140701_164_dialog_content = "接下來輪到你做我做不到的事情了。",
  ui_story_1014_10140701_165_dialog_content = "當然。妳帶著平民接著向後撤，戰場交給我們。",
  ui_story_1014_10140701_166_dialog_content = "沒有暗鬼能越過鐵棘騎士團的防線。",
  ui_story_1014_10140701_167_dialog_content = "我相信你。",
  ui_story_1014_10140701_168_dialog_content = "快走吧，這場短暫的碰面到此為止。",
  ui_story_1014_10140701_169_dialog_content = "我們好像總是這樣，在戰場上擦身而過。",
  ui_story_1014_10140701_170_dialog_content = "嗯，總是這樣。",
  ui_story_1014_10140701_171_dialog_content = "因為我們在去往不同的方向。",
  ui_story_1014_10140701_172_dialog_content = "那隻老朋友愈來愈近了，我能聽到牠的聲音。",
  ui_story_1014_10140701_173_dialog_content = "鐵棘騎士團列陣準備！有沒有人想跟那個大傢伙狠狠幹一仗！",
  ui_story_1014_10140701_174_dialog_content = "<size=40>有！！！</size>",
  ui_story_1014_10140701_175_dialog_content = "<size=40>有！！！</size>",
  ui_story_1014_10140701_176_dialog_content = "你們也要加入？還有力氣戰鬥嗎。",
  ui_story_1014_10140701_177_dialog_content = "當然！剛才在牠身上吃到的虧，現在要全部討回來！",
  ui_story_1014_10140701_178_dialog_content = "哈哈哈哈好！不錯的氣勢！",
  ui_story_1014_10140701_179_dialog_content = "既然有你們幫忙，這一戰的目的就不只是防守了。",
  ui_story_1014_10140701_180_dialog_content = "今晚我要用牠頭上的犄角來懸掛軍旗！",
  ui_story_1014_10140702_1_dialog_content = "<anim type=Shake><size=45>嗷！！！嗷——</size></anim>",
  ui_story_1014_10140702_2_dialog_content = "歇一歇吧，大傢伙。",
  ui_story_1014_10140702_3_dialog_content = "哈啊——牠總算是倒下了，生命力真旺盛啊。",
  ui_story_1014_10140702_4_dialog_content = "別放鬆。暗鬼的攻勢還沒結束，我們得堅持到最後。",
  ui_story_1014_10140702_5_dialog_content = "當然！不過這下壓力就小多了。",
  ui_story_1014_10140702_6_dialog_content = "呼，總算是從暗鬼群裡脫身了。",
  ui_story_1014_10140702_7_dialog_content = "癲蹄呢？那傢伙去哪了？",
  ui_story_1014_10140702_8_dialog_content = "......",
  ui_story_1014_10140702_9_dialog_content = "多謝您！多謝您，聖女大人！",
  ui_story_1014_10140702_10_dialog_content = "您救了我們所有人的命！",
  ui_story_1014_10140702_11_dialog_content = "哎呀，大家不要再用那種稱呼叫我了。",
  ui_story_1014_10140702_12_dialog_content = "我的名字叫<color=#FFB400>喬瑟琳</color>。如果大家接下來準備住在黃昏鎮的話，我們就是鄰居了。",
  ui_story_1014_10140702_13_dialog_content = "是啊，接下來該怎麼辦呢。",
  ui_story_1014_10140702_14_dialog_content = "只能先住在黃昏鎮了。這裡有白夜城和啟光的部隊，好歹有安全保障。",
  ui_story_1014_10140702_15_dialog_content = "遷去其他地方的話，誰知道什麼時候又會遭到暗鬼的襲擊。",
  ui_story_1014_10140702_16_dialog_content = "說得對。我不想逃難了，再也不想了。",
  ui_story_1014_10140702_17_dialog_content = "大家先去鎮上吧，經歷了這麼多現在肯定筋疲力盡了。",
  ui_story_1014_10140702_18_dialog_content = "今天還有其他流民逃到黃昏鎮，鎮民們正在為安置流民做準備。",
  ui_story_1014_10140702_19_dialog_content = "今晚會有一些空置的房間給大家歇腳，各位儘管好好休息。",
  ui_story_1014_10140702_20_dialog_content = "後面的事情等明早再從長計議吧。",
  ui_story_1014_10140702_21_dialog_content = "也好，也好。真是太謝謝您了，連起居的小事都為我們考慮好了。",
  ui_story_1014_10140702_22_dialog_content = "像今天這樣的事情在黃昏鎮經常出現。",
  ui_story_1014_10140702_23_dialog_content = "鎮民們很多都曾是附近逃難來的流民，大家最能理解你們的遭遇。",
  ui_story_1014_10140702_24_dialog_content = "我們所做的這些小事無非是盡一份力，希望你們也能快點擁有一個新家。",
  ui_story_1014_10140702_25_dialog_content = "新家啊。對，我們會有的！",
  ui_story_1014_10140702_26_dialog_content = "時間不早了，大家快點到鎮上去吧。",
  ui_story_1014_10140702_27_dialog_content = "好的！等我們安頓下來，一定再找您好好道謝，聖女大人！",
  ui_story_1014_10140702_28_dialog_content = "哎呀，都說了叫我喬瑟琳就可以了。",
  ui_story_1014_10140702_29_dialog_content = "白夜至上，我們有時間會去教會拜訪您的！",
  ui_story_1014_10140702_30_dialog_content = "教會啊，去那裡是找不到我的喔。我不屬於教會。",
  ui_story_1014_10140702_31_dialog_content = "欸？您竟然不是教會的成員嗎？",
  ui_story_1014_10140702_32_dialog_content = "不是，我只是跟你們一樣的普通人。",
  ui_story_1014_10140702_33_dialog_content = "如果要找我的話就去集市上吧，我常在集市裡買賣東西。",
  ui_story_1014_10140702_34_dialog_content = "好的！集市！我們記住了！",
  ui_story_1014_10140702_35_dialog_content = "再會，聖女大人！",
  ui_story_1014_10140702_36_dialog_content = "是喬瑟琳啦......",
  ui_story_1014_10140702_37_dialog_content = "哎呀，這個聲音是。",
  ui_story_1014_10140702_38_dialog_content = "他們回來了。",
  ui_story_1014_10140702_39_dialog_content = "<color=#e8d9bb>喀嗒、喀嗒、喀嗒......</color>",
  ui_story_1014_10140702_40_dialog_content = "原來卡蓮殿下是來巡視邊境的。",
  ui_story_1014_10140702_41_dialog_content = "嗯。白夜城很久沒有跟黃昏鎮進行情報交流了。",
  ui_story_1014_10140702_42_dialog_content = "這種小事派您過來實在是過於隆重了。",
  ui_story_1014_10140702_43_dialog_content = "大致情況你們也看到了，這邊的戰事很辛苦，但是姑且還能維持穩定。",
  ui_story_1014_10140702_44_dialog_content = "白夜城的勢力集中在「白夜要塞」。那裡掌控著黃昏鎮的能源核心，防守力量十分充沛。",
  ui_story_1014_10140702_45_dialog_content = "卡蓮殿下有時間的話，可以去那裡看看。",
  ui_story_1014_10140702_46_dialog_content = "嗯，我會去的。",
  ui_story_1014_10140702_47_dialog_content = "前面就到黃昏鎮了。",
  ui_story_1014_10140702_48_dialog_content = "看樣子，有人在迎接我們。",
  ui_story_1014_10140702_49_dialog_content = "欸，那是......剛才戰場上的女孩！",
  ui_story_1014_10140702_50_dialog_content = "我記得平民們好像叫她「黃昏鎮的聖女」。",
  ui_story_1014_10140702_51_dialog_content = "請一定把那個稱呼忘掉，我叫喬瑟琳。",
  ui_story_1014_10140702_52_dialog_content = "各位在戰場上英勇的表現很令我觸動。",
  ui_story_1014_10140702_53_dialog_content = "我替黃昏鎮的居民在這裡迎接戰士們凱旋歸來。",
  ui_story_1014_10140702_54_dialog_content = "觸動什麼的，還是妳在戰場上的表現更令人觸動吧。",
  ui_story_1014_10140702_55_dialog_content = "是啊，沐浴在光芒裡出現的樣子，真的很誇張。",
  ui_story_1014_10140702_56_dialog_content = "那些得救的平民一定比我感觸更強烈。",
  ui_story_1014_10140702_57_dialog_content = "簡直像是神的使者親臨......",
  ui_story_1014_10140702_58_dialog_content = "不要說這種話了，實在是很讓我惶恐。",
  ui_story_1014_10140702_59_dialog_content = "沒有想到，在遠離白夜城的地方竟然能見識到如此純淨的光能。",
  ui_story_1014_10140702_60_dialog_content = "我對邊區教會不是很瞭解。妳是那裡的成員嗎？",
  ui_story_1014_10140702_61_dialog_content = "看穿著好像......和我印象裡的修女並不一樣。",
  ui_story_1014_10140702_62_dialog_content = "啊，大家對我總是會有這種印象。",
  ui_story_1014_10140702_63_dialog_content = "對不起，我並不是教會成員。",
  ui_story_1014_10140702_64_dialog_content = "欸，那難道是啟光的士兵？",
  ui_story_1014_10140702_65_dialog_content = "啟光士兵可沒有這種打扮。",
  ui_story_1014_10140702_66_dialog_content = "這裡是邊境，不是每個人都需要隸屬於白夜城或啟光，會戰鬥的也不只有士兵。",
  ui_story_1014_10140702_67_dialog_content = "如果說到她確切的身分，那應該是「賣番茄的」。",
  ui_story_1014_10140702_68_dialog_content = "？！",
  ui_story_1014_10140702_69_dialog_content = "希望團長大人不要忘了我還在做針織生意。",
  ui_story_1014_10140702_70_dialog_content = "你從沒買過我的番茄，但是已經在我這修補過兩次軍旗了。",
  ui_story_1014_10140702_71_dialog_content = "對不起啊，我是很想照顧妳的生意，但番茄可不是騎士的食物。",
  ui_story_1014_10140702_72_dialog_content = "騎士們，我們該吃些什麼？",
  ui_story_1014_10140702_73_dialog_content = "肉啊！當然是肉！",
  ui_story_1014_10140702_74_dialog_content = "羊腿肉撒上鹽烤，沒有什麼比那更棒了！",
  ui_story_1014_10140702_75_dialog_content = "哎，真希望你們的飲食品味能早點跟上作戰技巧。",
  ui_story_1014_10140702_76_dialog_content = "對了，騎士團之外的各位是外鄉人吧？我從沒見過你們。",
  ui_story_1014_10140702_77_dialog_content = "嗯，我們剛從東邊的迦南城過來。",
  ui_story_1014_10140702_78_dialog_content = "迦南城啊。真是好遠的地方，我只在地圖上看到過。",
  ui_story_1014_10140702_79_dialog_content = "各位要在黃昏鎮住幾日嗎？",
  ui_story_1014_10140702_80_dialog_content = "是的，有些事情要在黃昏鎮辦。",
  ui_story_1014_10140702_81_dialog_content = "那不如跟我來吧，我來為你們安排住處。",
  ui_story_1014_10140702_82_dialog_content = "要是不嫌麻煩，我還想請各位嚐一嚐黃昏鎮特色的餐點。",
  ui_story_1014_10140702_83_dialog_content = "就當是對各位英勇戰鬥的一點點回饋了。",
  ui_story_1014_10140702_84_dialog_content = "欸？這......這也太隆重了。",
  ui_story_1014_10140702_85_dialog_content = "黃昏鎮難得有客人，況且你們剛剛為鎮上投入過戰鬥。",
  ui_story_1014_10140702_86_dialog_content = "就算喬瑟琳不邀請，我也要請你們吃晚飯的。",
  ui_story_1014_10140702_87_dialog_content = "現在聖女大人願意自掏腰包，那再好不過。你們就接受吧。",
  ui_story_1014_10140702_88_dialog_content = "這樣啊。那大家覺得呢？",
  ui_story_1014_10140702_89_dialog_content = "說到這個地步還不接受就該顯得我們不近人情了。",
  ui_story_1014_10140702_90_dialog_content = "是啊！黃昏鎮會有什麼樣的美食呢？好期待啊！",
  ui_story_1014_10140702_91_dialog_content = "我對鎮上的大小店鋪還算瞭解，一定能讓各位滿意。",
  ui_story_1014_10140702_92_dialog_content = "李奧團長這次戰鬥也很辛苦，願不願意賞臉一起吃頓飯？",
  ui_story_1014_10140702_93_dialog_content = "妳是請我還是請鐵棘騎士團？",
  ui_story_1014_10140702_94_dialog_content = "我要去的餐廳恐怕坐不下整支騎士團。",
  ui_story_1014_10140702_95_dialog_content = "喂，怎麼能區別對待呢，聖女大人！",
  ui_story_1014_10140702_96_dialog_content = "難道我們就沒有為黃昏鎮浴血奮戰嗎？",
  ui_story_1014_10140702_97_dialog_content = "好了好了，少不了你們的飯。",
  ui_story_1014_10140702_98_dialog_content = "今晚慶功，拿我的錢隨便去吃吧。",
  ui_story_1014_10140702_99_dialog_content = "<size=45>好！！！太好了！！！</size>",
  ui_story_1014_10140702_100_dialog_content = "我就不陪你們了，難得喬瑟琳小姐慷慨解囊。",
  ui_story_1014_10140702_101_dialog_content = "我去陪陪遠方新來的朋友。",
  ui_story_1014_10140702_102_dialog_content = "順便，也見識見識更高的「飲食品味」是什麼樣子。",
  ui_story_1014_10140801_1_dialog_content = "晚上睡覺的話，枕頭、被子、衣物......",
  ui_story_1014_10140801_2_dialog_content = "啊，什麼都沒有帶上。",
  ui_story_1014_10140801_3_dialog_content = "逃跑的時候那麼急，哪有時間帶這些行李。",
  ui_story_1014_10140801_4_dialog_content = "我連錢都沒來得及收，馬上該為吃飯發愁了。",
  ui_story_1014_10140801_5_dialog_content = "喂，我聽說那邊可以借些生活用品。",
  ui_story_1014_10140801_6_dialog_content = "走，一起去看看！",
  ui_story_1014_10140801_7_dialog_content = "街邊有好多難民啊。",
  ui_story_1014_10140801_8_dialog_content = "他們全都是今天逃難過來的嗎？",
  ui_story_1014_10140801_9_dialog_content = "是的。這樣的事情在黃昏鎮經常發生。",
  ui_story_1014_10140801_10_dialog_content = "經常嗎？",
  ui_story_1014_10140801_11_dialog_content = "黃昏鎮雖然有白夜城和啟光的駐軍，但是鎮上之外的區域不受任何勢力管制。",
  ui_story_1014_10140801_12_dialog_content = "那些散落在周圍的小村莊平時自給自足樂得清閒。",
  ui_story_1014_10140801_13_dialog_content = "只不過，一旦極光出現紊亂，暗鬼發起進攻，遭到襲擊的小村莊基本沒有自衛手段。",
  ui_story_1014_10140801_14_dialog_content = "村民們只能捨棄自己的家園，來到駐軍身邊尋求庇護。",
  ui_story_1014_10140801_15_dialog_content = "就像是一粒粒沙子被狂風吹起，最後落在同一個避風港。",
  ui_story_1014_10140801_16_dialog_content = "於是沙子積成了土堆，流民紮根建起了黃昏鎮。",
  ui_story_1014_10140801_17_dialog_content = "竟然是這樣......",
  ui_story_1014_10140801_18_dialog_content = "那大家為什麼不遷去更安全的地方？",
  ui_story_1014_10140801_19_dialog_content = "你是說東邊腹地的白夜城或是迦南城？",
  ui_story_1014_10140801_20_dialog_content = "大家當然想去，但是實際生活很殘酷啊，沒那麼容易心想事成。",
  ui_story_1014_10140801_21_dialog_content = "遷去遠方要靠什麼生活呢？要住在哪裡呢？",
  ui_story_1014_10140801_22_dialog_content = "沒有勢力會為這些生來就沒有歸屬的居民提供土地和房子。",
  ui_story_1014_10140801_23_dialog_content = "在極光遺跡這個地區，雖然會面臨暗鬼的威脅，但至少土地肥沃衣食無憂。",
  ui_story_1014_10140801_24_dialog_content = "大家都相信，面對風吹雨打也好過當無根之草。",
  ui_story_1014_10140801_25_dialog_content = "啊......對不起，我想得太簡單了。",
  ui_story_1014_10140801_26_dialog_content = "哈哈沒關係，沒有人會介意這種事的。",
  ui_story_1014_10140801_27_dialog_content = "這裡一定跟你們見過的地方都不一樣，感到驚奇也是理所當然。",
  ui_story_1014_10140801_28_dialog_content = "是啊，太不一樣了。不僅平民不受約束，白夜城和啟光竟然還能在同一個鎮上共處。",
  ui_story_1014_10140801_29_dialog_content = "說是共處，但是他們互相之間很少來往。",
  ui_story_1014_10140801_30_dialog_content = "這不就有當事人嘛，你可以問問他們。",
  ui_story_1014_10140801_31_dialog_content = "白夜城和啟光共處啊，從我小時候來到黃昏鎮就已經是這樣了。",
  ui_story_1014_10140801_32_dialog_content = "聽前輩們說是一系列歷史遺留問題。",
  ui_story_1014_10140801_33_dialog_content = "上頭的大人物都想要守住極光遺跡這個邊界。但是除此之外，也就沒有了更多的命令。",
  ui_story_1014_10140801_34_dialog_content = "極光遺跡對於白夜城和啟光的意義是一樣的，一塊食之無味棄之可惜的邊陲之地。",
  ui_story_1014_10140801_35_dialog_content = "既然上面懶得管，兩邊的士兵也就少了很多沒必要的講究。",
  ui_story_1014_10140801_36_dialog_content = "極光遺跡附近土地還算肥沃，但是能源稀缺，基本集中在黃昏鎮的範圍內。",
  ui_story_1014_10140801_37_dialog_content = "為了維持自身的消耗，兩邊也就約定共同駐紮在這裡。",
  ui_story_1014_10140801_38_dialog_content = "共同駐紮爭搶同一塊資源不會產生矛盾嗎？",
  ui_story_1014_10140801_39_dialog_content = "對付暗鬼已經很費勁了，哪有精力去製造什麼內部矛盾。",
  ui_story_1014_10140801_40_dialog_content = "「活著」永遠是邊境最大的主題。",
  ui_story_1014_10140801_41_dialog_content = "那些搞不清輕重緩急的人，戰場會給他們補上一課。",
  ui_story_1014_10140801_42_dialog_content = "原來是這樣。",
  ui_story_1014_10140801_43_dialog_content = "讓我想起了歷史書裡看到的光靈聯軍。",
  ui_story_1014_10140801_44_dialog_content = "在強大的外敵面前，勢力之間的隔閡也就變得無足輕重了。",
  ui_story_1014_10140801_45_dialog_content = "<color=#e8d9bb>哧——</color>",
  ui_story_1014_10140801_46_dialog_content = "<anim type=Shake>嗚——啊。</anim>",
  ui_story_1014_10140801_47_dialog_content = "阿克希亞！妳醒了啊！",
  ui_story_1014_10140801_48_dialog_content = "早安，PlayerName。",
  ui_story_1014_10140801_49_dialog_content = "現在完全不是早上啊......",
  ui_story_1014_10140801_50_dialog_content = "嗯？你們還藏著一個這麼可愛的女孩子啊。",
  ui_story_1014_10140801_51_dialog_content = "我的外觀沒有什麼值得關注的。那是最微不足道的東西。",
  ui_story_1014_10140801_52_dialog_content = "肚子餓了。",
  ui_story_1014_10140801_53_dialog_content = "餓得正是時候！餐館到了。",
  ui_story_1014_10140801_54_dialog_content = "妳愛吃什麼東西呀？",
  ui_story_1014_10140801_55_dialog_content = "糖。",
  ui_story_1014_10140801_56_dialog_content = "這是千層酥、蛋撻、泡芙還有黃油蛋糕。",
  ui_story_1014_10140801_57_dialog_content = "嗯，非常精湛的手藝。",
  ui_story_1014_10140801_58_dialog_content = "喬瑟琳，吃這麼多甜點沒問題嗎？",
  ui_story_1014_10140801_59_dialog_content = "沒事沒事，偶爾吃一次不會胖的。",
  ui_story_1014_10140801_60_dialog_content = "今天帶來的客人，生面孔居多啊。",
  ui_story_1014_10140801_61_dialog_content = "嗯，這幾位是從迦南城遠道而來的客人。",
  ui_story_1014_10140801_62_dialog_content = "迦南城啊，隔壁的大叔去過那裡。聽說是個刻板得要命的地方，哎，受罪啊。",
  ui_story_1014_10140801_63_dialog_content = "刻......刻板嗎？也還好啦......",
  ui_story_1014_10140801_64_dialog_content = "然後除此之外，還有我們本地的駐軍戰士。",
  ui_story_1014_10140801_65_dialog_content = "啟光的年輕軍官西恩，和白夜城的鐵棘騎士團團長李奧。",
  ui_story_1014_10140801_66_dialog_content = "是！我是黃昏鎮駐軍少尉軍官西恩！",
  ui_story_1014_10140801_67_dialog_content = "喂，我這可不是你們啟光的食堂啊，別給我行軍禮。",
  ui_story_1014_10140801_68_dialog_content = "哈哈哈，西恩小兄弟的反應總是這麼有意思。",
  ui_story_1014_10140801_69_dialog_content = "老闆，您家的烤肉做得真好吃。",
  ui_story_1014_10140801_70_dialog_content = "下次我一定帶騎士團的兄弟們來嚐嚐！",
  ui_story_1014_10140801_71_dialog_content = "你真是，到哪裡都只知道吃肉。",
  ui_story_1014_10140801_72_dialog_content = "開店嘛，手藝不過關可活不下去。",
  ui_story_1014_10140801_73_dialog_content = "沒看到其他店員啊，這麼大一家店只有您一個人？",
  ui_story_1014_10140801_74_dialog_content = "嗯，就我一個。",
  ui_story_1014_10140801_75_dialog_content = "自己忙裡忙外不累嗎？您這個手藝，完全可以雇些店員把生意做大啊。",
  ui_story_1014_10140801_76_dialog_content = "沒那個興趣，一個人清閒。",
  ui_story_1014_10140801_77_dialog_content = "最早的時候跟自家兄弟一起開店，兩個人老是爭吵，煩死了。",
  ui_story_1014_10140801_78_dialog_content = "我還是第一次聽說您有個兄弟。",
  ui_story_1014_10140801_79_dialog_content = "嗯，因為他三年前死了。",
  ui_story_1014_10140801_80_dialog_content = "我們逃來黃昏鎮的路上，被暗鬼殺了。",
  ui_story_1014_10140801_81_dialog_content = "欸......",
  ui_story_1014_10140801_82_dialog_content = "他腿腳不方便，落在了逃難隊伍的最後面。",
  ui_story_1014_10140801_83_dialog_content = "暗鬼追上來的時候，白夜城的騎士團趕到了。但是沒有救他。",
  ui_story_1014_10140801_84_dialog_content = "......",
  ui_story_1014_10140801_85_dialog_content = "（騎士團......）",
  ui_story_1014_10140801_86_dialog_content = "我不恨那個騎士團。至少，他們救了我。",
  ui_story_1014_10140801_87_dialog_content = "命在這裡並不值錢，也就沒什麼討價還價的餘地。",
  ui_story_1014_10140801_88_dialog_content = "救了誰，沒救誰，怎樣都理所當然。",
  ui_story_1014_10140801_89_dialog_content = "老闆，不要這樣說。生命是很珍貴的，大家的生命同等珍貴。",
  ui_story_1014_10140801_90_dialog_content = "我知道妳是這樣想的，因為妳不一樣，喬瑟琳。",
  ui_story_1014_10140801_91_dialog_content = "妳會去拯救所有人，妳讓大家願意相信世界上有神。",
  ui_story_1014_10140801_92_dialog_content = "但是守住黃昏鎮和平的不是我，是駐紮這裡的士兵們。",
  ui_story_1014_10140801_93_dialog_content = "如果不是珍惜大家的生命，黃昏鎮怎麼會一步步變成流民的避難所？",
  ui_story_1014_10140801_94_dialog_content = "生命是偉大的。在這份偉大面前，拯救與放棄都是一場朝拜。",
  ui_story_1014_10140801_95_dialog_content = "那些士兵只是，先於所有人面對了無可奈何的選擇。",
  ui_story_1014_10140801_96_dialog_content = "......",
  ui_story_1014_10140801_97_dialog_content = "其實他們......",
  ui_story_1014_10140801_98_dialog_content = "喬瑟琳，把妳前面那盤烤香腸往我這推推。我夠不到。",
  ui_story_1014_10140801_99_dialog_content = "啊，好的。",
  ui_story_1014_10140801_100_dialog_content = "對了，PlayerName，還沒仔細問過。你們是來黃昏鎮做什麼的？",
  ui_story_1014_10140801_101_dialog_content = "（欸，李奧他把話題轉移開了。）",
  ui_story_1014_10140801_102_dialog_content = "竟然還有啟光的中校軍官隨行，排場不小啊。",
  ui_story_1014_10140801_103_dialog_content = "如果是保密任務的話，就當我沒問。",
  ui_story_1014_10140801_104_dialog_content = "喔，我們啊，我們是來維修巨像的。",
  ui_story_1014_10140801_105_dialog_content = "巨像？！你們竟然有......",
  ui_story_1014_10140801_106_dialog_content = "對了，你是空裔，有巨像才正常。",
  ui_story_1014_10140801_107_dialog_content = "既然說維修，它出什麼問題了嗎？",
  ui_story_1014_10140801_108_dialog_content = "我想想該怎麼解釋啊。他的功能並沒有故障，只是暫時失去了意識。",
  ui_story_1014_10140801_109_dialog_content = "「巨像失去意識」這件事可能有點難以理解......",
  ui_story_1014_10140801_110_dialog_content = "哦，我明白了，挺好理解的。",
  ui_story_1014_10140801_111_dialog_content = "怪不得會來黃昏鎮。你們是來找啟光研究員的吧？",
  ui_story_1014_10140801_112_dialog_content = "欸，你怎麼知道？",
  ui_story_1014_10140801_113_dialog_content = "我雖然不懂巨像的研究，但是對它的故事略知一二。",
  ui_story_1014_10140801_114_dialog_content = "不如說黃昏鎮的人都知道那段故事。",
  ui_story_1014_10140801_115_dialog_content = "在這種偏遠的地方，值得稱道的傳說可不多。",
  ui_story_1014_10140801_116_dialog_content = "傳說？是什麼樣的故事啊？",
  ui_story_1014_10140801_117_dialog_content = "我想想從哪裡說起啊。",
  ui_story_1014_10140801_118_dialog_content = "算了，讓喬瑟琳給你講吧。她擅長講故事。",
  ui_story_1014_10140801_119_dialog_content = "你不也滿擅長的，我看你在酒吧裡講起話來一晚上都不停。",
  ui_story_1014_10140801_120_dialog_content = "我的嘴巴忙著吃肉呢。",
  ui_story_1014_10140801_121_dialog_content = "好吧，好吧。難得請你吃一次飯，不能讓你餓著。",
  ui_story_1014_10140801_122_dialog_content = "說起這段傳說的話，要追溯到千年之前。",
  ui_story_1014_10140801_123_dialog_content = "光靈們走出北境不久，白夜城建立之初。",
  ui_story_1014_10140801_124_dialog_content = "為了獲得一塊可以生存的家園，光靈們組成軍隊與暗鬼不斷戰鬥。",
  ui_story_1014_10140801_125_dialog_content = "屬於光靈的版圖也在戰鬥中不斷擴張，逐漸接近現在的樣子。",
  ui_story_1014_10140801_126_dialog_content = "而這場擴張的最遠端，就是你們現在身處的這個區域，極光遺跡。",
  ui_story_1014_10140801_127_dialog_content = "哦！原來從那麼久之前這裡就是邊境了！",
  ui_story_1014_10140801_128_dialog_content = "不要小看極光遺跡的戰略地位。",
  ui_story_1014_10140801_129_dialog_content = "只要鞏固住極光遺跡的防線，暗鬼就會被攔在永夜地區，無法深入大陸。",
  ui_story_1014_10140801_130_dialog_content = "反之，放棄了極光遺跡這個狹窄的隘口，就會有大片區域暴露在暗鬼的直接威脅下。",
  ui_story_1014_10140801_131_dialog_content = "這是標誌著光靈終於有權控制艾斯特拉的重要一戰。",
  ui_story_1014_10140801_132_dialog_content = "到底是你講還是我講？",
  ui_story_1014_10140801_133_dialog_content = "妳講，妳講。我只是補充點戰略知識。",
  ui_story_1014_10140801_134_dialog_content = "當時那場爭奪極光遺跡的戰爭非常艱難。",
  ui_story_1014_10140801_135_dialog_content = "這裡靠近永夜，又有不好預測的極光現象，暗鬼的力量空前強大。",
  ui_story_1014_10140801_136_dialog_content = "戰爭進行了很久。防線遲遲沒有建立起來，光靈只能用一代又一代士兵的屍體來填。",
  ui_story_1014_10140801_137_dialog_content = "就在這場綿綿無期的戰爭中途，一個沒有任何文字記載的日子裡。",
  ui_story_1014_10140801_138_dialog_content = "光靈終於得到了一次命運的垂青。",
  ui_story_1014_10140801_139_dialog_content = "在戰場之上，一片前所未見的烏雲遮蔽了太陽。",
  ui_story_1014_10140801_140_dialog_content = "那是一支<color=#FFB400>巨像的艦隊</color>。",
  ui_story_1014_10140801_141_dialog_content = "巨像艦隊？！",
  ui_story_1014_10140801_142_dialog_content = "（我看到過！我看到過那樣的場景！）",
  ui_story_1014_10140801_143_dialog_content = "（是那支艦隊嗎？）",
  ui_story_1014_10140801_144_dialog_content = "巨像艦隊向遠方駛去，但是其中一艘停了下來。",
  ui_story_1014_10140801_145_dialog_content = "它與光靈戰士們進行了溝通，並決定留在戰場上與光靈並肩戰鬥。",
  ui_story_1014_10140801_146_dialog_content = "等一下，妳是說巨像與光靈進行了溝通？",
  ui_story_1014_10140801_147_dialog_content = "不是巨像上的空裔嗎？",
  ui_story_1014_10140801_148_dialog_content = "不是。實際上，那艘巨像上根本就沒有空裔。",
  ui_story_1014_10140801_149_dialog_content = "是巨像<color=#FFB400>自身的意識</color>在做出決定。",
  ui_story_1014_10140801_150_dialog_content = "巨像自己......",
  ui_story_1014_10140801_151_dialog_content = "有個書呆子朋友跟我說過，在光靈的歷史上，「巨像」這個詞的誕生早於「空裔」。",
  ui_story_1014_10140801_152_dialog_content = "這也許算是一種對傳說的佐證吧。",
  ui_story_1014_10140801_153_dialog_content = "後來呢？那艘巨像一直留在極光遺跡了嗎？",
  ui_story_1014_10140801_154_dialog_content = "是的。巨像就像一位特殊的士兵，投身於這場曠日持久的戰爭裡。",
  ui_story_1014_10140801_155_dialog_content = "直到多年之後，戰爭終於獲勝，光靈在極光遺跡建立起了自己的要塞。",
  ui_story_1014_10140801_156_dialog_content = "巨像也因為連年戰損逐漸不再活躍，最終變成了一座沉寂的塑像。",
  ui_story_1014_10140801_157_dialog_content = "這裡的光靈非常敬重巨像，將它視作圖騰來崇拜。",
  ui_story_1014_10140801_158_dialog_content = "竟然有巨像跨過空裔這一層，和光靈結成了紐帶。太不可思議了。",
  ui_story_1014_10140801_159_dialog_content = "它保存完好嗎？",
  ui_story_1014_10140801_160_dialog_content = "聽我把故事說完呀。",
  ui_story_1014_10140801_161_dialog_content = "再之後就到了近代，啟光聯邦興起，派駐軍來到極光遺跡。",
  ui_story_1014_10140801_162_dialog_content = "他們的研究員對巨像展開了研究，試圖將這艘損壞的巨像修復。",
  ui_story_1014_10140801_163_dialog_content = "他們......該說成功了一半吧。",
  ui_story_1014_10140801_164_dialog_content = "那艘巨像短暫地恢復了。但是之後，由於一些原因不明的故障，巨像行為出現混亂。",
  ui_story_1014_10140801_165_dialog_content = "最終巨像在無法控制的情況下，摔落在無法探查的暗面。",
  ui_story_1014_10140801_166_dialog_content = "摔落在暗面？！這也太可惜了！",
  ui_story_1014_10140801_167_dialog_content = "嗯，不少老一輩因此對啟光充滿意見。",
  ui_story_1014_10140801_168_dialog_content = "連累了他們的士兵總是遭受白眼。",
  ui_story_1014_10140801_169_dialog_content = "原來是這樣！怪不得那些集市的老伯都對我愛答不理的。",
  ui_story_1014_10140801_170_dialog_content = "我還以為是哪裡得罪到他們了。",
  ui_story_1014_10140801_171_dialog_content = "黃昏鎮這個地方就是這樣，很多事情說不明白對錯，因此也沒法化解矛盾。",
  ui_story_1014_10140801_172_dialog_content = "啟光的研究也很難說出對錯。",
  ui_story_1014_10140801_173_dialog_content = "錯的地方當然是他們讓黃昏鎮失去了古老的巨像。",
  ui_story_1014_10140801_174_dialog_content = "但是他們的研究成果也許能幫忙修復PlayerName的巨像，這不也是好事嘛。",
  ui_story_1014_10140801_175_dialog_content = "說起來，啟光研究員已經向我發來聯絡了。",
  ui_story_1014_10140801_176_dialog_content = "他也對巨像修復很感興趣，希望能儘早開始這項工作。",
  ui_story_1014_10140801_177_dialog_content = "真的嗎？已經這麼晚了，該休息了吧。",
  ui_story_1014_10140801_178_dialog_content = "這點倒不用擔心，他應該是剛醒。",
  ui_story_1014_10140801_179_dialog_content = "剛醒？！",
  ui_story_1014_10140801_180_dialog_content = "科學家你也知道，總有些古怪的地方。",
  ui_story_1014_10140801_181_dialog_content = "哈哈，也是。",
  ui_story_1014_10140801_182_dialog_content = "既然這樣，吃完飯我們就去研究所吧。",
  ui_story_1014_10140801_183_dialog_content = "臨空者號的事情，我也希望愈快愈好。",
  ui_story_1014_10140801_184_dialog_content = "<color=#e8d9bb>吱——</color>",
  ui_story_1014_10140801_185_dialog_content = "他們走了。",
  ui_story_1014_10140801_186_dialog_content = "這些外鄉人，挺有意思的嘛。",
  ui_story_1014_10140801_187_dialog_content = "嗯，很有意思。",
  ui_story_1014_10140801_188_dialog_content = "啟光的軍官，白夜城的公主，這些人竟然能聚在一起。",
  ui_story_1014_10140801_189_dialog_content = "傳說中的空裔手段很是高明啊。",
  ui_story_1014_10140801_190_dialog_content = "對了，你不謝謝我嗎？",
  ui_story_1014_10140801_191_dialog_content = "不是吧，聖女大人。以您的胸懷，就連在平民面前為我開脫這點小事都要計較嗎？",
  ui_story_1014_10140801_192_dialog_content = "我以為道謝能讓你好受一點。",
  ui_story_1014_10140801_193_dialog_content = "說起來我覺得妳該謝謝我。",
  ui_story_1014_10140801_194_dialog_content = "哦？",
  ui_story_1014_10140801_195_dialog_content = "像妳那樣不管不顧去救人的戰鬥方式是錯誤的。",
  ui_story_1014_10140801_196_dialog_content = "之所以每次都能漂漂亮亮地逞英雄，是因為有人幫妳兜住了後果。",
  ui_story_1014_10140801_197_dialog_content = "啊，你說得對。我是該感謝那個人一下。",
  ui_story_1014_10140801_198_dialog_content = "不過這麼說的話，你還是要感謝我。",
  ui_story_1014_10140801_199_dialog_content = "怎麼講？",
  ui_story_1014_10140801_200_dialog_content = "因為我讓你少了些遺憾。",
  ui_story_1014_10140801_201_dialog_content = "哇喔！一艘完善的巨像！",
  ui_story_1014_10140801_202_dialog_content = "這太棒了！你們知不知道這有多少研究價值？",
  ui_story_1014_10140801_203_dialog_content = "對不起，我們並不是送臨空者號來給你研究的。",
  ui_story_1014_10140801_204_dialog_content = "我們是來......",
  ui_story_1014_10140801_205_dialog_content = "啊，我知道。交易對吧，交易。",
  ui_story_1014_10140801_206_dialog_content = "你們把「戰鬥機器」帶來了嗎？",
  ui_story_1014_10140801_207_dialog_content = "嗯，在這裡。",
  ui_story_1014_10140801_208_dialog_content = "哦對，是它。放在這就行。",
  ui_story_1014_10140801_209_dialog_content = "修復巨像的意識是吧，交給我就行了。",
  ui_story_1014_10140801_210_dialog_content = "在修復過程中讓我記錄一些資料沒問題吧？情理之中的事情，嗯。",
  ui_story_1014_10140801_211_dialog_content = "那倒是沒問題，只要能讓臨空者號的意識恢復。",
  ui_story_1014_10140801_212_dialog_content = "好欸，那我現在就開始！",
  ui_story_1014_10140801_213_dialog_content = "我可以在這裡看著嗎？",
  ui_story_1014_10140801_214_dialog_content = "我......我擔心發生什麼意外。",
  ui_story_1014_10140801_215_dialog_content = "沒問題啊，只要你不嫌無聊。",
  ui_story_1014_10140801_216_dialog_content = "PlayerName，這麼晚了你要留在這裡嗎？",
  ui_story_1014_10140801_217_dialog_content = "嗯。想到臨空者號正在修復我也睡不好覺，不如留在這看著。",
  ui_story_1014_10140801_218_dialog_content = "你們先回去睡吧。",
  ui_story_1014_10140801_219_dialog_content = "自己一個人沒關係嗎？",
  ui_story_1014_10140801_220_dialog_content = "沒關係，這是啟光的駐紮地，也不會發生什麼意外。",
  ui_story_1014_10140801_221_dialog_content = "那好吧。你......不要太勉強自己。",
  ui_story_1014_10140801_222_dialog_content = "嗯，我知道了。",
  ui_story_1014_10140801_223_dialog_content = "<color=#e8d9bb>叮叮、當當——</color>",
  ui_story_1014_10140801_224_dialog_content = "喂，空裔小子，醒醒。",
  ui_story_1014_10140801_225_dialog_content = "嗯......",
  ui_story_1014_10140801_226_dialog_content = "醒醒啊，別再睡了。",
  ui_story_1014_10140801_227_dialog_content = "嗚......",
  ui_story_1014_10140801_228_dialog_content = "你怎麼還翻到另一邊去了。",
  ui_story_1014_10140801_229_dialog_content = "快起來，你看......",
  ui_story_1014_10140801_230_dialog_content = "PlayerName，好久不見。",
  ui_story_1014_10140801_231_dialog_content = "<size=50>！！！</size>",
  ui_story_1014_10140801_232_dialog_content = "臨空者號！你......你甦醒了嗎？",
  ui_story_1014_10140801_233_dialog_content = "快去看看吧，修復工作姑且完成了。",
  ui_story_1014_10140801_234_dialog_content = "只是，我們這裡記錄的資料不夠充足，巨像的意識沒法維持穩定。",
  ui_story_1014_10140801_235_dialog_content = "你要抓緊時間。",
  ui_story_1014_10140801_236_dialog_content = "沒法維持穩定？",
  ui_story_1014_10140801_237_dialog_content = "謝謝你，PlayerName。謝謝你一直在尋找讓我復原的方法。",
  ui_story_1014_10140801_238_dialog_content = "終於又聽到你的聲音了，臨空者號！",
  ui_story_1014_10140801_239_dialog_content = "發生了好多事情，我想想要從......",
  ui_story_1014_10140801_240_dialog_content = "對不起，這次還是沒法陪你很久。",
  ui_story_1014_10140801_241_dialog_content = "......",
  ui_story_1014_10140801_242_dialog_content = "你們的方法是正確的，但是缺乏資料支撐。",
  ui_story_1014_10140801_243_dialog_content = "是的，之前對巨像的研究還沒完成，它就......哎。",
  ui_story_1014_10140801_244_dialog_content = "那......那該怎麼辦......",
  ui_story_1014_10140801_245_dialog_content = "我能搜尋到那艘巨像的下落。",
  ui_story_1014_10140801_246_dialog_content = "什麼？！",
  ui_story_1014_10140801_247_dialog_content = "找到它就可以嗎？它在哪裡！",
  ui_story_1014_10140801_248_dialog_content = "<anim type=Shake>我的時間......要到了。</anim>",
  ui_story_1014_10140801_249_dialog_content = "<anim type=Shake>我在......終端裡......留下了座標資訊。</anim>",
  ui_story_1014_10140801_250_dialog_content = "座標？巨像位置的座標嗎！",
  ui_story_1014_10140801_251_dialog_content = "<anim type=Shake>PlayerName......我......相信你。</anim>",
  ui_story_1014_10140801_252_dialog_content = "<anim type=Shake>請你也......相信......你自己。</anim>",
  ui_story_1014_10140901_1_dialog_content = "給，這是極光遺跡區域最完整的作戰地圖。",
  ui_story_1014_10140901_2_dialog_content = "我是透過特殊許可權拿到的，千萬不要外傳。",
  ui_story_1014_10140901_3_dialog_content = "你想找的那個座標，大概在這裡。",
  ui_story_1014_10140901_4_dialog_content = "這是......暗面？",
  ui_story_1014_10140901_5_dialog_content = "是的，而且是一座地下城。",
  ui_story_1014_10140901_6_dialog_content = "啟光對於那座地下城的探索停留在表層，沒有深入。",
  ui_story_1014_10140901_7_dialog_content = "所以，那裡基本上是一片未知區域。",
  ui_story_1014_10140901_8_dialog_content = "我們可以過去嗎？",
  ui_story_1014_10140901_9_dialog_content = "可以，但是很危險。你最好考慮清楚。",
  ui_story_1014_10140901_10_dialog_content = "我知道了。沒有什麼需要考慮的，這是為了臨空者號，我必須要去。",
  ui_story_1014_10140901_11_dialog_content = "我沒有阻止你去，我是讓你考慮清楚。",
  ui_story_1014_10140901_12_dialog_content = "你要找那座古老的巨像。找到之後呢？你準備怎麼運回來？",
  ui_story_1014_10140901_13_dialog_content = "運回來？呃，這個......",
  ui_story_1014_10140901_14_dialog_content = "沒事，我會幫你的！我找長官借一輛貨運車！",
  ui_story_1014_10140901_15_dialog_content = "我練習過車輛駕駛，肯定能把巨像平安運回來！",
  ui_story_1014_10140901_16_dialog_content = "真的嗎？太好了！這樣就沒問題了！",
  ui_story_1014_10140901_17_dialog_content = "你們......",
  ui_story_1014_10140901_18_dialog_content = "你們兩個能湊出一個腦子我就謝天謝地了。",
  ui_story_1014_10140901_19_dialog_content = "且不說巨像的大小貨運車能否承下。",
  ui_story_1014_10140901_20_dialog_content = "地下城裡有完好的路面供你駕駛嗎？怎麼突破暗鬼的包圍順利離開？",
  ui_story_1014_10140901_21_dialog_content = "這......這些嘛......",
  ui_story_1014_10140901_22_dialog_content = "研究員，你修復臨空者號所需要的具體部件是哪些？",
  ui_story_1014_10140901_23_dialog_content = "嘶，說實話還是拿到完整的巨像最好。",
  ui_story_1014_10140901_24_dialog_content = "我們對巨像的認知還不夠全面，少了哪裡都可能出現問題。",
  ui_story_1014_10140901_25_dialog_content = "不過一定要說的話......",
  ui_story_1014_10140901_26_dialog_content = "對，「<color=#FFB400>主控模組</color>」。",
  ui_story_1014_10140901_27_dialog_content = "那裡的研究價值最大，也是先前研究的重點對象。",
  ui_story_1014_10140901_28_dialog_content = "好。那我們重新明確一下，目標並不是整個巨像，而是巨像上的「主控模組」。",
  ui_story_1014_10140901_29_dialog_content = "這個行動超出了你在迦南城談好的交易內容。",
  ui_story_1014_10140901_30_dialog_content = "因此，你不會得到啟光額外的援助。",
  ui_story_1014_10140901_31_dialog_content = "嗯，我明白。這是我個人的事情。",
  ui_story_1014_10140901_32_dialog_content = "但是，你還可以得到一些個人的援助。",
  ui_story_1014_10140901_33_dialog_content = "欸？",
  ui_story_1014_10140901_34_dialog_content = "這是我可以幫忙的意思對吧，鶯歌！",
  ui_story_1014_10140901_35_dialog_content = "是的。你近期沒有其他作戰任務，可以自由支配時間。",
  ui_story_1014_10140901_36_dialog_content = "哈哈哈哈，好欸！",
  ui_story_1014_10140901_37_dialog_content = "西恩，你......",
  ui_story_1014_10140901_38_dialog_content = "同樣的，我和阿克希亞也沒有作戰任務。",
  ui_story_1014_10140901_39_dialog_content = "妳們！妳們也願意幫助我嗎？",
  ui_story_1014_10140901_40_dialog_content = "暗面的地下城很危險。我可不想放任西恩帶著唯一的空裔蠢死在裡面。",
  ui_story_1014_10140901_41_dialog_content = "我去調理下阿克希亞的狀態。做好準備之後，我們就出發。",
  ui_story_1014_10140901_42_dialog_content = "太好了，PlayerName！我去找長官借貨運車！",
  ui_story_1014_10140901_43_dialog_content = "我，我不知道該說什麼好了。",
  ui_story_1014_10140901_44_dialog_content = "謝謝，真的非常，感謝你們。",
  ui_story_1014_10140901_45_dialog_content = "<color=#e8d9bb>哧——</color>",
  ui_story_1014_10140901_46_dialog_content = "阿克希亞，糖。",
  ui_story_1014_10140901_47_dialog_content = "嗯。",
  ui_story_1014_10140901_48_dialog_content = "鶯歌，妳的任務怎麼樣了？",
  ui_story_1014_10140901_49_dialog_content = "完成了啊，我們不是順利到達了嗎。",
  ui_story_1014_10140901_50_dialog_content = "我是說，另一個。",
  ui_story_1014_10140901_51_dialog_content = "另一個？",
  ui_story_1014_10140901_52_dialog_content = "任務完成了的話，妳不會繼續幫PlayerName的。",
  ui_story_1014_10140901_53_dialog_content = "妳還有其他任務。",
  ui_story_1014_10140901_54_dialog_content = "......",
  ui_story_1014_10140901_55_dialog_content = "有時候真不知道妳在想什麼。看起來什麼都沒想，但是又什麼都知道。",
  ui_story_1014_10140901_56_dialog_content = "我瞭解鶯歌。",
  ui_story_1014_10140901_57_dialog_content = "如果是我不該知道的任務，不說也可以的。",
  ui_story_1014_10140901_58_dialog_content = "我在找<color=#FFB400>吞羅</color>。",
  ui_story_1014_10140901_59_dialog_content = "那個科學家叛徒？",
  ui_story_1014_10140901_60_dialog_content = "對。",
  ui_story_1014_10140901_61_dialog_content = "她也在黃昏鎮嗎？",
  ui_story_1014_10140901_62_dialog_content = "沒人知道她在哪。",
  ui_story_1014_10140901_63_dialog_content = "所以，只能想辦法把她引出來。",
  ui_story_1014_10140901_64_dialog_content = "利用空裔嗎？",
  ui_story_1014_10140901_65_dialog_content = "嗯。沒有比他更好的餌了。",
  ui_story_1014_10140901_66_dialog_content = "他自己並不知道吧。",
  ui_story_1014_10140901_67_dialog_content = "依他的性格，知道了會生氣的。",
  ui_story_1014_10140901_68_dialog_content = "......",
  ui_story_1014_10140901_69_dialog_content = "吃完糖可以再睡一會嗎，阿克希亞。",
  ui_story_1014_10140901_70_dialog_content = "希望妳能等到我叫妳再醒過來。",
  ui_story_1014_10140901_71_dialog_content = "好。我聽妳的。",
  ui_story_1014_10140901_72_dialog_content = "我說了，我一定要去！",
  ui_story_1014_10140901_73_dialog_content = "卡蓮殿下，我明白您的意思。",
  ui_story_1014_10140901_74_dialog_content = "那你還攔在這裡做什麼？",
  ui_story_1014_10140901_75_dialog_content = "您也理解一下，這都是城主大人的意思。",
  ui_story_1014_10140901_76_dialog_content = "城主大人？怎麼在黃昏鎮都能聽到這個稱呼。",
  ui_story_1014_10140901_77_dialog_content = "我記得他從不過問邊境的事務。",
  ui_story_1014_10140901_78_dialog_content = "這不是因為您在嗎。我們也很難辦，您理解一下。",
  ui_story_1014_10140901_79_dialog_content = "我們接到的是巡視任務，白夜要塞沒有資格限制我們的自由。",
  ui_story_1014_10140901_80_dialog_content = "如果是城主的命令，那請你們出示相關的文件。",
  ui_story_1014_10140901_81_dialog_content = "這個......",
  ui_story_1014_10140901_82_dialog_content = "卡蓮、貝爾塔？妳們這邊發生什麼了？",
  ui_story_1014_10140901_83_dialog_content = "卡蓮怎麼會被白夜城的衛兵攔住？",
  ui_story_1014_10140901_84_dialog_content = "PlayerName還有薇絲，來得正好。",
  ui_story_1014_10140901_85_dialog_content = "我和貝爾塔想在出發前到白夜要塞取點物資做準備。",
  ui_story_1014_10140901_86_dialog_content = "結果，被他們攔住不讓走了。",
  ui_story_1014_10140901_87_dialog_content = "沒有阻攔您的意思。只是您要去的地方非常危險，我們必須派人援護確保您的安全。",
  ui_story_1014_10140901_88_dialog_content = "我在戰場上可從來不需要別人來保護。",
  ui_story_1014_10140901_89_dialog_content = "唷，PlayerName。找你們半天了。",
  ui_story_1014_10140901_90_dialog_content = "聽說你們要去暗面的地下城。願不願意帶我一起？",
  ui_story_1014_10140901_91_dialog_content = "你也要去？",
  ui_story_1014_10140901_92_dialog_content = "白夜要塞派來援護的人就是你嗎？",
  ui_story_1014_10140901_93_dialog_content = "不是不是。我早就想去那座地下城了。",
  ui_story_1014_10140901_94_dialog_content = "最近黃昏鎮附近暗鬼的異動，似乎都跟那裡有所關聯。",
  ui_story_1014_10140901_95_dialog_content = "我想去探查清楚，但是帶上騎士團怕惹出是非，獨自一人又勢單力薄。",
  ui_story_1014_10140901_96_dialog_content = "既然現在你們願意去，這個機會對我來說再好不過了。",
  ui_story_1014_10140901_97_dialog_content = "原來是這樣。",
  ui_story_1014_10140901_98_dialog_content = "至於白夜要塞派給你們的援護嘛，另有其人。",
  ui_story_1014_10140901_99_dialog_content = "噢，他來了。",
  ui_story_1014_10140901_100_dialog_content = "希望我沒有讓各位等太久。",
  ui_story_1014_10140901_101_dialog_content = "時間倉促，我只做了最低限度的準備。",
  ui_story_1014_10140901_102_dialog_content = "<color=#FFB400>若瑟神父</color>，您終於來了。",
  ui_story_1014_10140901_103_dialog_content = "卡蓮殿下，這是教區派來負責援護的若瑟神父。他將與你們同行。",
  ui_story_1014_10140901_104_dialog_content = "卡蓮殿下，久聞盛名。",
  ui_story_1014_10140901_105_dialog_content = "既然人已經到了，我不會再阻攔您的行動。",
  ui_story_1014_10140901_106_dialog_content = "卡蓮殿下，祝您一切順利。",
  ui_story_1014_10140901_107_dialog_content = "只有他一個人？",
  ui_story_1014_10140901_108_dialog_content = "是的。實在抱歉，並非教區怠慢，實在是人手緊缺。",
  ui_story_1014_10140901_109_dialog_content = "別聽他的。願意派他來，就是教區拿出的十足的誠意了。",
  ui_story_1014_10140901_110_dialog_content = "我們要去的地方很兇險，實力不夠的人帶多少都沒用。",
  ui_story_1014_10140901_111_dialog_content = "李奧，這次你能如願以償了。",
  ui_story_1014_10140901_112_dialog_content = "是啊。多謝了PlayerName，湊齊這樣一支隊伍可是非常難得的。",
  ui_story_1014_10140901_113_dialog_content = "看起來還不止如此。那個平民女孩又來找你了。",
  ui_story_1014_10140901_114_dialog_content = "平民女孩......",
  ui_story_1014_10140901_115_dialog_content = "我喜歡這個稱呼，比「聖女大人」好多了。",
  ui_story_1014_10140901_116_dialog_content = "喬瑟琳？妳怎麼也來了。",
  ui_story_1014_10140901_117_dialog_content = "PlayerName，我可以加入嗎？",
  ui_story_1014_10140901_118_dialog_content = "欸？噢，好啊！當然可以！",
  ui_story_1014_10140901_119_dialog_content = "但是，為什麼？",
  ui_story_1014_10140901_120_dialog_content = "我不能眼看著遠道而來的客人深入黑暗。",
  ui_story_1014_10140901_121_dialog_content = "至少，讓我來替你們照亮一角。",
  ui_story_1014_10140901_122_dialog_content = "<color=#e8d9bb>喀喀喀......喀喀......</color>",
  ui_story_1014_10140901_123_dialog_content = "<color=#e8d9bb>喀......喀......</color>",
  ui_story_1014_10140901_124_dialog_content = "嗯？怎麼又不動了？",
  ui_story_1014_10140901_125_dialog_content = "哪裡卡住了嗎？",
  ui_story_1014_10140901_126_dialog_content = "好了西恩，別擺弄你的貨車了。",
  ui_story_1014_10140901_127_dialog_content = "我說過，它行不通的。能開到這裡就夠了。",
  ui_story_1014_10140901_128_dialog_content = "大家下車吧，我們到地下城外沿了。",
  ui_story_1014_10140901_129_dialog_content = "阿克希亞，該起床了。",
  ui_story_1014_10140901_130_dialog_content = "唔嗯。好的，我睡飽了。",
  ui_story_1014_10140901_131_dialog_content = "這裡就是了啊。",
  ui_story_1014_10140901_132_dialog_content = "果然，暗能好濃厚。",
  ui_story_1014_10140901_133_dialog_content = "再往前走就是暗面了。",
  ui_story_1014_10140901_134_dialog_content = "嗯。這麼說的話好緊張啊，暗面給我留下的印象很差。",
  ui_story_1014_10140901_135_dialog_content = "這裡有人去過那座地下城嗎？",
  ui_story_1014_10140901_136_dialog_content = "有一些老人去過。也是他們告訴其他人，絕對不能踏入暗面。",
  ui_story_1014_10140901_137_dialog_content = "不過我覺得沒什麼可怕的。那些老人並非刀槍不入的怪物。",
  ui_story_1014_10140901_138_dialog_content = "既然他們能活著離開暗面，我們更沒有問題。",
  ui_story_1014_10140901_139_dialog_content = "呵呵，我以為你講的道理會更嚴謹一些。",
  ui_story_1014_10140901_140_dialog_content = "我又沒親自去過暗面，拿什麼嚴謹呢。",
  ui_story_1014_10140901_141_dialog_content = "相信李奧吧，他的判斷總是準確的。",
  ui_story_1014_10140901_142_dialog_content = "別捧我了，在這裡我其實更想聽聽你的判斷。",
  ui_story_1014_10140901_143_dialog_content = "哈哈。看了看周圍的人，好像又覺得沒什麼可怕的了。",
  ui_story_1014_10140901_144_dialog_content = "比起暗鬼，說不定還是他們的力量更可怕。",
  ui_story_1014_10140901_145_dialog_content = "大家，準備好了的話向地下城前進吧。",
  ui_story_1014_10140901_146_dialog_content = "我們去找那艘巨像。",
  ui_story_1014_10140901_147_dialog_content = "好吵。好吵啊。",
  ui_story_1014_10140901_148_dialog_content = "多久沒這樣吵過了。",
  ui_story_1014_10140901_149_dialog_content = "這是什麼？比雨點聲更密集，比蟲鳴更令人煩躁。",
  ui_story_1014_10140901_150_dialog_content = "啊，一定是了。是人的聲音。",
  ui_story_1014_10140901_151_dialog_content = "是討厭透頂的，人的聲音。",
  ui_story_1014_10141101_1_dialog_content = "這裡就是那座巨像所在的遺跡了嗎......",
  ui_story_1014_10141101_2_dialog_content = "地圖上是這樣寫的。",
  ui_story_1014_10141101_3_dialog_content = "各位小心，這裡聚集了不少暗鬼。",
  ui_story_1014_10141101_4_dialog_content = "......",
  ui_story_1014_10141101_5_dialog_content = "真是怪了，怎麼有這麼多暗鬼？",
  ui_story_1014_10141101_6_dialog_content = "按照暗鬼通常的行為方式，牠們確實不該在這裡聚集。",
  ui_story_1014_10141101_7_dialog_content = "但這裡的環境有別於其他地方，有可能存在著未知的特性。",
  ui_story_1014_10141101_8_dialog_content = "我也無法確定這些暗鬼究竟是被環境吸引來的，還是有什麼人在指揮牠們。",
  ui_story_1014_10141101_9_dialog_content = "情況複雜，我們還是小心為上吧。",
  ui_story_1014_10141101_10_dialog_content = "暗鬼，並不值得畏懼，牠們被打敗，這是唯一的結果。",
  ui_story_1014_10141101_11_dialog_content = "阿克希亞那麼厲害嗎？",
  ui_story_1014_10141101_12_dialog_content = "可別小看她哦，阿克希亞可是我們之中最厲害的！有時候就連我也打不過她呢。",
  ui_story_1014_10141101_13_dialog_content = "根據我的觀察，西恩你和阿克希亞切磋的時候，十場裡有九場失敗，一場平局。",
  ui_story_1014_10141101_14_dialog_content = "與西恩交手，不需要認真。",
  ui_story_1014_10141101_15_dialog_content = "喂，不要說這麼無情的話啊！",
  ui_story_1014_10141101_16_dialog_content = "哈哈哈，你們之間感情還真好。",
  ui_story_1014_10141101_17_dialog_content = "不過這裡並不安全，還是先不要打鬧了。",
  ui_story_1014_10141101_18_dialog_content = "抓緊時間尋找PlayerName需要的模組，盡可能速戰速決吧。",
  ui_story_1014_10141101_19_dialog_content = "正好前面有一群暗鬼，不如這樣吧！",
  ui_story_1014_10141101_20_dialog_content = "阿克希亞，我們再來比試一場，比比看誰擊敗的暗鬼更多！",
  ui_story_1014_10141101_21_dialog_content = "鶯歌來負責當裁判。",
  ui_story_1014_10141101_22_dialog_content = "唉，你總是這樣。",
  ui_story_1014_10141101_23_dialog_content = "好吧，要是輸了，你可別哭鼻子。",
  ui_story_1014_10141101_24_dialog_content = "<color=#e8d9bb>極光遺跡外部，某處</color>",
  ui_story_1014_10141101_25_dialog_content = "（日蝕語）<color=#FFB400>阿斯摩太</color>大人，光靈與空裔已經進入了遺跡裡。",
  ui_story_1014_10141101_26_dialog_content = "（日蝕語）他們與遺跡中的同伴們交手了。",
  ui_story_1014_10141101_27_dialog_content = "（日蝕語）就讓他們繼續深入吧。",
  ui_story_1014_10141101_28_dialog_content = "（日蝕語）他們的欲望，或許會指向我一直在尋找的那個東西。",
  ui_story_1014_10141102_1_dialog_content = "最後一隻暗鬼──是我的！",
  ui_story_1014_10141102_2_dialog_content = "嘎——！",
  ui_story_1014_10141102_3_dialog_content = "怎麼樣，鶯歌，是誰贏了？",
  ui_story_1014_10141102_4_dialog_content = "那麼，來宣布成績好了。",
  ui_story_1014_10141102_5_dialog_content = "西恩，擊敗暗鬼二十隻。",
  ui_story_1014_10141102_6_dialog_content = "嗯！比起我最好的成績還是低了那麼一點。",
  ui_story_1014_10141102_7_dialog_content = "阿克希亞，擊敗暗鬼——",
  ui_story_1014_10141102_8_dialog_content = "三十二隻！",
  ui_story_1014_10141102_9_dialog_content = "那麼多？！",
  ui_story_1014_10141102_10_dialog_content = "不......不可能吧？！",
  ui_story_1014_10141102_11_dialog_content = "西恩，你把太多時間花在四處追著逃竄的小型暗鬼打這件事上了。",
  ui_story_1014_10141102_12_dialog_content = "阿克希亞在這段時間裡選擇去對付由數隻大型暗鬼率領的暗鬼群。",
  ui_story_1014_10141102_13_dialog_content = "唉......這也沒辦法啊。",
  ui_story_1014_10141102_14_dialog_content = "以我的能力，先從弱小的暗鬼開始削減數量，最後專心對付大型暗鬼才是上策。",
  ui_story_1014_10141102_15_dialog_content = "是的，正是因為你還不夠強大，所以最後勝利的是阿克希亞。",
  ui_story_1014_10141102_16_dialog_content = "可惡啊，又讓阿克希亞贏了！",
  ui_story_1014_10141102_17_dialog_content = "西恩又一次失敗了。",
  ui_story_1014_10141102_18_dialog_content = "但是，西恩不會灰心，西恩熱衷於一次次挑戰，就算失敗也不會放棄。",
  ui_story_1014_10141102_19_dialog_content = "直到西恩獲得勝利。",
  ui_story_1014_10141102_20_dialog_content = "阿克希亞不愧是我的好對手，真瞭解我的想法。",
  ui_story_1014_10141102_21_dialog_content = "但是，西恩不可能擊敗阿克希亞。",
  ui_story_1014_10141102_22_dialog_content = "別那麼肯定，我可是會不斷成長並變強的！",
  ui_story_1014_10141102_23_dialog_content = "若瑟，你覺得他們的表現如何？",
  ui_story_1014_10141102_24_dialog_content = "您要詢問我的意見嗎？",
  ui_story_1014_10141102_25_dialog_content = "當然，你一聲不吭地觀察了各位這麼久，一定有不少見解吧。",
  ui_story_1014_10141102_26_dialog_content = "（若瑟一直沒有說話，原來是在觀察我們嗎？）",
  ui_story_1014_10141102_27_dialog_content = "我認為啟光的各位都非常優秀，各有各的長處。",
  ui_story_1014_10141102_28_dialog_content = "阿克希亞操縱機械的實力非常強大、鶯歌擅長觀察與協助，而西恩則擅長將經驗轉化為力量。",
  ui_story_1014_10141102_29_dialog_content = "三位能組成一支非常完美的隊伍呢。",
  ui_story_1014_10141102_30_dialog_content = "......！",
  ui_story_1014_10141102_31_dialog_content = "阿克希亞，認可若瑟的見解。",
  ui_story_1014_10141102_32_dialog_content = "嗯，感謝妳的認同。",
  ui_story_1014_10141102_33_dialog_content = "（若瑟先生的觀察力好強！）",
  ui_story_1014_10141102_34_dialog_content = "不過，阿克希亞可真厲害啊。",
  ui_story_1014_10141102_35_dialog_content = "如果參加聯合軍演的話，大概是個人冠軍的強力競爭者吧！",
  ui_story_1014_10141102_36_dialog_content = "PlayerName也知道聯合軍演？",
  ui_story_1014_10141102_37_dialog_content = "是啊，萊因哈特之前跟我說過這件事。",
  ui_story_1014_10141102_38_dialog_content = "她還說，很期待和冠軍之間的切磋。",
  ui_story_1014_10141102_39_dialog_content = "不愧是那位大元帥，果然是她的風格。",
  ui_story_1014_10141102_40_dialog_content = "我也很期待能在聯合軍演中與她和阿克希亞這樣的強者交手。",
  ui_story_1014_10141102_41_dialog_content = "當然，如果有機會的話，我也想和上一屆的冠軍得主卡蓮殿下比試一場。",
  ui_story_1014_10141102_42_dialog_content = "不得無禮！",
  ui_story_1014_10141102_43_dialog_content = "沒關係。",
  ui_story_1014_10141102_44_dialog_content = "之後那場演習，我依舊會參與。",
  ui_story_1014_10141102_45_dialog_content = "我期待在戰場上與你交手，李奧。",
  ui_story_1014_10141102_46_dialog_content = "一言為定。",
  ui_story_1014_10141102_47_dialog_content = "李奧也要參與那個演習嗎？",
  ui_story_1014_10141102_48_dialog_content = "是的。",
  ui_story_1014_10141102_49_dialog_content = "只要是光靈，就能夠參與這場聯合軍演。",
  ui_story_1014_10141102_50_dialog_content = "能與來自艾斯特拉各地的強者切磋，就算距離再遠，我也必定會前往。",
  ui_story_1014_10141102_X50_dialog_content = "<color=#e8d9bb>極光遺跡深處</color>",
  ui_story_1014_10141102_51_dialog_content = "（已經來到了這裡，看樣子這趟旅程很快就會結束了。）",
  ui_story_1014_10141102_52_dialog_content = "（直到現在，吞羅也沒有出現，難道說我的判斷出現了問題嗎......）",
  ui_story_1014_10141102_53_dialog_content = "（不，吞羅的目標一直都很明確，PlayerName是引出她的最佳誘餌。）",
  ui_story_1014_10141102_54_dialog_content = "（我的判斷不會出錯，現在需要做的，只是繼續等待。）",
  ui_story_1014_10141102_55_dialog_content = "鶯歌，妳怎麼不走了？難道是剛才受傷了嗎？",
  ui_story_1014_10141102_56_dialog_content = "嗯？不，我沒有受傷，只是在思考這裡出現這麼多暗鬼的原因。",
  ui_story_1014_10141102_57_dialog_content = "各位，打斷一下。",
  ui_story_1014_10141102_58_dialog_content = "我們此行的目的是協助PlayerName尋找巨像組件。",
  ui_story_1014_10141102_59_dialog_content = "據我所知，這裡應該距離那座遠古巨像不遠了。",
  ui_story_1014_10141102_60_dialog_content = "我們還是繼續前進吧？",
  ui_story_1014_10141102_61_dialog_content = "嗯，喬瑟琳小姐說得有道理。",
  ui_story_1014_10141102_62_dialog_content = "這裡一直給我一種不太好的感覺，就好像被什麼人盯著一樣......",
  ui_story_1014_10141102_63_dialog_content = "還是快點拿到需要的組件，返回黃昏鎮吧！",
  ui_story_1014_10141102_64_dialog_content = "<color=#e8d9bb>極光遺跡外部，某處</color>",
  ui_story_1014_10141102_65_dialog_content = "（日蝕語）欲望的味道，接近了那座巨像。",
  ui_story_1014_10141102_66_dialog_content = "（日蝕語）難道......那東西在巨像中嗎？",
  ui_story_1014_10141102_67_dialog_content = "（日蝕語）阿斯摩太大人，需要現在動手嗎？",
  ui_story_1014_10141102_68_dialog_content = "（日蝕語）讓欲望靠近些，再靠近些......",
  ui_story_1014_10141102_69_dialog_content = "（日蝕語）那個空裔的背叛者，他的欲望會成為指引道路的信標。",
  ui_story_1014_10141102_70_dialog_content = "（日蝕語）我們，只需要等待。",
  ui_story_1014_10141201_1_dialog_content = "前面就是巨像遺跡了，各位，提高警惕。",
  ui_story_1014_10141201_2_dialog_content = "遠古時期遺留下來的巨像，馬上就能看到它了......",
  ui_story_1014_10141201_3_dialog_content = "<size=45>好大？！</size>",
  ui_story_1014_10141201_4_dialog_content = "這座巨像的大小，完全超出了我的預期......",
  ui_story_1014_10141201_5_dialog_content = "這座巨像的體積在已經發現的巨像中也算是名列前茅的。",
  ui_story_1014_10141201_6_dialog_content = "啟光聯邦曾經透過黃昏鎮的駐軍研究過這座巨像，並獲得了許多珍貴資料。",
  ui_story_1014_10141201_7_dialog_content = "什麼資料？",
  ui_story_1014_10141201_8_dialog_content = "一些設備的詳細製作方法，比如醫療系統的部分設計圖。",
  ui_story_1014_10141201_9_dialog_content = "還有其他發現嗎？比如巨像的記憶、過去空裔的資訊等？",
  ui_story_1014_10141201_10_dialog_content = "這涉及到啟光的機密，恕我無法進行回答。",
  ui_story_1014_10141201_11_dialog_content = "不過，由於當時開發人員的誤操作，導致這座巨像<color=#FFB400>暴走</color>過一次。",
  ui_story_1014_10141201_12_dialog_content = "巨像中的很多區域也在那次暴走中被鎖死，無法進入。",
  ui_story_1014_10141201_13_dialog_content = "在那之後，這座巨像連同其所在的極光遺跡，被劃為低價值高風險的區域了。",
  ui_story_1014_10141201_14_dialog_content = "這一次，尤利西斯長官之所以能夠允許我們來探索，恐怕也是因為你的存在。",
  ui_story_1014_10141201_15_dialog_content = "是因為我的空裔身分嗎......",
  ui_story_1014_10141201_16_dialog_content = "沒錯。",
  ui_story_1014_10141201_17_dialog_content = "空裔是巨像的駕駛者，可能能夠帶來意想不到的發現。",
  ui_story_1014_10141201_18_dialog_content = "......不說這個了。",
  ui_story_1014_10141201_19_dialog_content = "我們進去吧。",
  ui_story_1014_10141201_20_dialog_content = "要小心。",
  ui_story_1014_10141201_21_dialog_content = "阿克希亞，看到了暗鬼活動的痕跡。",
  ui_story_1014_10141201_22_dialog_content = "這座巨像的內部，存在著許多暗鬼。",
  ui_story_1014_10141201_23_dialog_content = "就算有再多暗鬼，我也必須拿到這座巨像的資料。",
  ui_story_1014_10141201_24_dialog_content = "為了臨空者號。",
  ui_story_1014_10141201_25_dialog_content = "巨像內部，很空曠。",
  ui_story_1014_10141201_26_dialog_content = "除了暗鬼的痕跡外，什麼都沒有。",
  ui_story_1014_10141201_27_dialog_content = "PlayerName的巨像中也有像這裡一樣空曠的房間嗎？",
  ui_story_1014_10141201_28_option_content = "有",
  ui_story_1014_10141201_29_dialog_content = "臨空者號的倉庫十分寬敞，在裡面跑步也沒問題。",
  ui_story_1014_10141201_30_dialog_content = "哦，好厲害！",
  ui_story_1014_10141201_31_option_content = "沒有",
  ui_story_1014_10141201_32_dialog_content = "臨空者號的房間和走廊雖然都很寬敞，但平時會有很多人在。",
  ui_story_1014_10141201_33_dialog_content = "只要是有同伴在的地方，就不會顯得空曠。",
  ui_story_1014_10141201_34_dialog_content = "說的是呢！",
  ui_story_1014_10141201_35_dialog_content = "前面，出現了一道門。",
  ui_story_1014_10141201_36_dialog_content = "這扇門，很像臨空者號上的房間門。",
  ui_story_1014_10141201_37_dialog_content = "這扇門後，應該就是這座巨像的艦橋了。",
  ui_story_1014_10141201_38_dialog_content = "看起來關得很緊，上面也沒有把手或者門鎖......",
  ui_story_1014_10141201_39_dialog_content = "要怎麼才能打開呢？",
  ui_story_1014_10141201_40_dialog_content = "臨空者號上的房門都是能用感應的方式打開的。",
  ui_story_1014_10141201_41_dialog_content = "我來感應一下這座巨像試試吧。",
  ui_story_1014_10141201_42_option_content = "強制感應！",
  ui_story_1014_10141201_43_dialog_content = "<color=#e8d9bb>嘶啦——</color>",
  ui_story_1014_10141201_44_dialog_content = "<color=#e8d9bb>檢測到未登記的空裔訪問。</color>",
  ui_story_1014_10141201_45_dialog_content = "這是巨像的系統嗎？為什麼感覺那麼生硬。",
  ui_story_1014_10141201_46_dialog_content = "就好像人格陷入沉睡的臨空者號一樣......",
  ui_story_1014_10141201_47_dialog_content = "<color=#e8d9bb>請登記您的身分。</color>",
  ui_story_1014_10141201_48_dialog_content = "我是空裔，名字是PlayerName。",
  ui_story_1014_10141201_49_dialog_content = "<color=#e8d9bb>已將「未登記用戶」修改為PlayerName。</color>",
  ui_story_1014_10141201_50_dialog_content = "<color=#e8d9bb>巨像「領導者號」已對您開放所有權限。</color>",
  ui_story_1014_10141201_51_dialog_content = "<color=#FFB400>領導者號</color>......這是遠古資料中空裔駕駛的巨像之一！",
  ui_story_1014_10141201_52_dialog_content = "全部許可權？！這麼輕易嗎？",
  ui_story_1014_10141201_53_dialog_content = "<color=#e8d9bb>領導者號的許可權開放，符合巨像所有者設定的規則。</color>",
  ui_story_1014_10141201_54_dialog_content = "<color=#e8d9bb>「等待時間不足100年時，僅對管理員開放所有權限。」</color>",
  ui_story_1014_10141201_55_dialog_content = "<color=#e8d9bb>「等待......超過100年，不足......年時，對全體空裔......許可權。」</color>",
  ui_story_1014_10141201_56_dialog_content = "<color=#e8d9bb>「等待......年，不足......全體生物......所有權限。」</color>",
  ui_story_1014_10141201_57_dialog_content = "<color=#e8d9bb>根據規則，領導者號現在對全體空裔開放許可權。</color>",
  ui_story_1014_10141201_58_dialog_content = "原來你等了這麼久嗎......辛苦你了。",
  ui_story_1014_10141201_59_dialog_content = "<color=#e8d9bb>領導者號人格處於停用狀態，無法解析「辛苦」的含義。</color>",
  ui_story_1014_10141201_60_dialog_content = "<color=#e8d9bb>領導者號上的一切，都是留給未來空裔的「禮物」。</color>",
  ui_story_1014_10141201_61_dialog_content = "人格停用了？為什麼會停用？",
  ui_story_1014_10141201_62_dialog_content = "<color=#e8d9bb>啟用人格將增加能源消耗。</color>",
  ui_story_1014_10141201_63_dialog_content = "<color=#e8d9bb>為了確保領導者號能將一切有用的資料與設備完好傳遞給未來找到領導者號的空裔......</color>",
  ui_story_1014_10141201_64_dialog_content = "<color=#e8d9bb>領導者號選擇停用人格，進入低功耗模式。</color>",
  ui_story_1014_10141201_65_dialog_content = "現在你的各個系統和人格資料還完好嗎？",
  ui_story_1014_10141201_66_dialog_content = "<color=#e8d9bb>運行自檢功能。</color>",
  ui_story_1014_10141201_67_dialog_content = "<color=#e8d9bb>主控系統自檢......運行中。零件損耗率72%，需要進行維護。</color>",
  ui_story_1014_10141201_68_dialog_content = "<color=#e8d9bb>生物模組自檢......已離線。</color>",
  ui_story_1014_10141201_69_dialog_content = "<color=#e8d9bb>維生系統自檢......已離線。</color>",
  ui_story_1014_10141201_70_dialog_content = "<color=#e8d9bb>檢查人格資料完整性......資料缺失32%，無法正常運行。</color>",
  ui_story_1014_10141201_71_dialog_content = "人格資料已經缺失到無法正常運行了？",
  ui_story_1014_10141201_72_dialog_content = "所以，其實領導者號你也已經......",
  ui_story_1014_10141201_73_dialog_content = "不論如何，感謝你能堅持這麼久。",
  ui_story_1014_10141201_74_dialog_content = "請幫我打開通往艦橋的大門吧。",
  ui_story_1014_10141201_75_dialog_content = "<color=#e8d9bb>指令接受。</color>",
  ui_story_1014_10141201_76_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_1014_10141201_77_dialog_content = "大門打開了。",
  ui_story_1014_10141201_78_dialog_content = "能夠看到破損的艦橋，以及巨像的控制台。",
  ui_story_1014_10141201_79_dialog_content = "<anim type=Shake><size=45>吼——！！！</size></anim>",
  ui_story_1014_10141201_80_dialog_content = "各位小心，遊蕩在裡面的暗鬼圍過來了！",
  ui_story_1014_10141201_81_dialog_content = "準備戰鬥！",
  ui_story_1014_10141302_1_dialog_content = "這裡的暗鬼，已經清理乾淨了。",
  ui_story_1014_10141302_2_dialog_content = "PlayerName，暫時關閉巨像的大門吧，免得更多暗鬼來搗亂。",
  ui_story_1014_10141302_3_dialog_content = "好，我這就讓領導者號關門。",
  ui_story_1014_10141302_4_dialog_content = "......",
  ui_story_1014_10141302_5_dialog_content = "阿克希亞，妳還好嗎？",
  ui_story_1014_10141302_6_dialog_content = "持續戰鬥了這麼久，妳需要休息。",
  ui_story_1014_10141302_7_dialog_content = "阿克希亞沒有事。",
  ui_story_1014_10141302_8_dialog_content = "戰鬥帶來的負擔，還在可控範圍內。",
  ui_story_1014_10141302_9_dialog_content = "嗯，我知道了。如果妳感到不舒服，就立刻告訴我。",
  ui_story_1014_10141302_10_dialog_content = "阿克希亞知道了。",
  ui_story_1014_10141302_11_dialog_content = "（我差點就忘記了，阿克希亞強大的力量來自啟光的人體改造技術。）",
  ui_story_1014_10141302_12_dialog_content = "（她平時就沒什麼表情，但就算這樣，剛才那一瞬還是露出了痛苦的表情。）",
  ui_story_1014_10141302_13_dialog_content = "（阿克希亞實際上承受的痛苦，或許比她表現出來的更多吧......）",
  ui_story_1014_10141302_14_dialog_content = "PlayerName，可以放心地去完成你的工作了。",
  ui_story_1014_10141302_15_dialog_content = "嗯......好，謝謝。",
  ui_story_1014_10141302_16_dialog_content = "我們幾個四處看看，提高警戒。",
  ui_story_1014_10141302_17_dialog_content = "那我來協助PlayerName檢查巨像的情況。",
  ui_story_1014_10141302_18_dialog_content = "領導者號，我想要獲得你的人格資料，所以......需要主控模組。",
  ui_story_1014_10141302_19_dialog_content = "<color=#e8d9bb>指令接受。正在檢查主控模組狀態。</color>",
  ui_story_1014_10141302_20_dialog_content = "<color=#e8d9bb>警告：主控模組嚴重受損，強行拆除將導致不可逆的損壞。</color>",
  ui_story_1014_10141302_21_dialog_content = "不能拆嗎？！",
  ui_story_1014_10141302_22_dialog_content = "那......那該怎麼辦？",
  ui_story_1014_10141302_23_dialog_content = "PlayerName露出了困擾的表情，阿克希亞有個提議。",
  ui_story_1014_10141302_24_dialog_content = "阿克希亞的機甲有可以拷貝資料的儀器，PlayerName可以用它與巨像連結。",
  ui_story_1014_10141302_25_dialog_content = "這樣做雖然不能取得整個主控模組，但仍能獲得巨像的意識資料。",
  ui_story_1014_10141302_26_dialog_content = "對阿爾戈爾來說，資料和模組本身能起到的作用，是一致的。",
  ui_story_1014_10141302_27_dialog_content = "看來只能這麼辦了。",
  ui_story_1014_10141302_28_dialog_content = "PlayerName需要拿好數據複製器，連結巨像的主控模組。",
  ui_story_1014_10141302_29_dialog_content = "按下這個按鈕，儀器就能自動拷貝資料。",
  ui_story_1014_10141302_30_dialog_content = "好。",
  ui_story_1014_10141302_31_dialog_content = "<color=#e8d9bb>正在複製巨像意識資料，請稍候。</color>",
  ui_story_1014_10141302_32_dialog_content = "看來又要等一下了呢。",
  ui_story_1014_10141302_33_dialog_content = "這裡到處都是遠古時代殘存的科技製品......",
  ui_story_1014_10141302_34_dialog_content = "白夜至上，希望它們不會對人們造成威脅。",
  ui_story_1014_10141302_35_dialog_content = "<color=#e8d9bb>嘀嘀嘀——</color>",
  ui_story_1014_10141302_36_dialog_content = "這裡是黃昏鎮鐵棘騎士團總部，遠征騎士李奧，聽到請回答。",
  ui_story_1014_10141302_37_dialog_content = "遠征騎士李奧聽到，請講。",
  ui_story_1014_10141302_38_dialog_content = "請報告你的方位及任務進展。",
  ui_story_1014_10141302_39_dialog_content = "報告，目前我們正在極光遺跡的巨像中執行保護空裔PlayerName的任務。",
  ui_story_1014_10141302_40_dialog_content = "卡蓮殿下以及來自啟光的數名光靈正與我們同行。",
  ui_story_1014_10141302_41_dialog_content = "卡蓮殿下嗎......我知道了。",
  ui_story_1014_10141302_42_dialog_content = "請繼續執行任務，如果遇到意外，請直接向鐵棘騎士團申請增援。",
  ui_story_1014_10141302_43_dialog_content = "是。",
  ui_story_1014_10141302_44_dialog_content = "祝你們一切順利。通話完畢。",
  ui_story_1014_10141302_45_dialog_content = "直接向鐵棘騎士團申請增援？",
  ui_story_1014_10141302_46_dialog_content = "與常年在外調查的遠征騎士相比，黃昏鎮駐守的騎士團應該擁有更多兵力和裝備。",
  ui_story_1014_10141302_47_dialog_content = "為什麼不向他們求援？",
  ui_story_1014_10141302_48_dialog_content = "卡蓮殿下，如您所見，鐵棘騎士團與駐守的騎士們之間存在著一些隔閡。",
  ui_story_1014_10141302_49_dialog_content = "遠征騎士大多數出身為平民和被流放的貴族，與駐守騎士們之間存在身分差別。",
  ui_story_1014_10141302_50_dialog_content = "很多時候，就算我們求援，他們也不一定會認真對待身分低微的我們。",
  ui_story_1014_10141302_51_dialog_content = "所以，作為遠征騎士，我們已經習慣於萬事靠自己了。",
  ui_story_1014_10141302_52_dialog_content = "竟然是這樣嗎......",
  ui_story_1014_10141302_53_dialog_content = "我會將這件事回報給白夜城高層。",
  ui_story_1014_10141302_54_dialog_content = "就算身分有別，同為白夜城的人民，也不應該存在這樣的歧視。",
  ui_story_1014_10141302_55_dialog_content = "感謝您的開明，雖然......我並不認為這會有什麼成效。",
  ui_story_1014_10141302_56_dialog_content = "只要貴族與平民之間的差異仍然存在，這種歧視與隔閡就不會消失。",
  ui_story_1014_10141302_57_dialog_content = "像我這樣的流放貴族，是最能認識到這一點的。",
  ui_story_1014_10141302_58_dialog_content = "......在這之前，我曾經遇到過一些同為流放貴族的人。",
  ui_story_1014_10141302_59_dialog_content = "他們或多或少都會對自己的現狀感到不滿。",
  ui_story_1014_10141302_60_dialog_content = "李奧，你也是這樣嗎？",
  ui_story_1014_10141302_61_dialog_content = "您在好奇我的想法嗎？",
  ui_story_1014_10141302_62_dialog_content = "嗯......確實。",
  ui_story_1014_10141302_63_dialog_content = "過去的我是白夜城裡錦衣玉食的貴族。",
  ui_story_1014_10141302_64_dialog_content = "那時的我以騎士之名衝鋒陷陣，以守護白夜城為最高的榮譽。",
  ui_story_1014_10141302_65_dialog_content = "在被流放後，我成了黃昏鎮裡一個寂寂無名的平民。",
  ui_story_1014_10141302_66_dialog_content = "過往的榮譽和誓死守衛白夜城的信念甚至不能用來換取一塊風乾的麵包。",
  ui_story_1014_10141302_67_dialog_content = "所以你心中產生了落差感？",
  ui_story_1014_10141302_68_dialog_content = "我不否認。",
  ui_story_1014_10141302_69_dialog_content = "但是，正是由於被放逐到黃昏鎮，我才意識到自己真正能依靠的，只有自己的力量。",
  ui_story_1014_10141302_70_dialog_content = "在通過考核成為遠征騎士、並在黃昏鎮生活了一段時間後，我的心態發生了改變。",
  ui_story_1014_10141302_71_dialog_content = "我認為這裡並沒有想像中的那麼差勁。",
  ui_story_1014_10141302_72_dialog_content = "至少在黃昏鎮，來自不同勢力的光靈可以暫時忘記陣營之爭、友好相處。",
  ui_story_1014_10141302_73_dialog_content = "我很喜歡這種能和他人共同對抗暗鬼的氛圍，但是......我仍然覺得不公平。",
  ui_story_1014_10141302_74_dialog_content = "不公平，為什麼？請你告訴我。",
  ui_story_1014_10141302_75_dialog_content = "我的意見能為您帶來什麼嗎？",
  ui_story_1014_10141302_76_dialog_content = "我想要聽取更多人的意見，然後改善白夜城的制度與律法。",
  ui_story_1014_10141302_77_dialog_content = "讓白夜城的人們最終都能獲得真正的公平。",
  ui_story_1014_10141302_78_dialog_content = "我——",
  ui_story_1014_10141302_79_dialog_content = "<color=#e8d9bb>嗶嗶——</color>",
  ui_story_1014_10141302_80_dialog_content = "<color=#e8d9bb>提示：已完成對巨像人格資料的複製，可以中斷連線。</color>",
  ui_story_1014_10141302_81_dialog_content = "PlayerName，資料好像複製完了！",
  ui_story_1014_10141302_82_dialog_content = "我們拿上它，趕快回去吧！",
  ui_story_1014_10141302_83_dialog_content = "對，說得對！",
  ui_story_1014_10141302_84_dialog_content = "（感謝阿爾戈爾的儀器......）",
  ui_story_1014_10141302_85_dialog_content = "（如果再讓卡蓮和李奧說下去，他們恐怕會吵起來吧！）",
  ui_story_1014_10141302_86_dialog_content = "<color=#e8d9bb>轟隆</color>",
  ui_story_1014_10141302_87_dialog_content = "噗......咳咳咳！怎麼回事？！",
  ui_story_1014_10141302_88_dialog_content = "<color=#e8d9bb>轟隆！！！</color>",
  ui_story_1014_10141302_89_dialog_content = "PlayerName！這座巨像，在震動！",
  ui_story_1014_10141302_90_dialog_content = "難道說......這座巨像又要暴走了？！",
  ui_story_1014_10141302_91_dialog_content = "暴走？！",
  ui_story_1014_10141302_92_dialog_content = "PlayerName，快拿上裝置，逃出這裡！",
  ui_story_1014_10141302_93_dialog_content = "震動太劇烈了，這座巨像說不定會發生解體和坍塌！",
  ui_story_1014_10141302_94_dialog_content = "不能待在這裡！",
  ui_story_1014_10141302_95_dialog_content = "<color=#e8d9bb>轟隆——！！！</color>",
  ui_story_1014_10141302_96_dialog_content = "糟了！",
  ui_story_1014_10141302_97_dialog_content = "這座巨像距離黃昏鎮不算遠，如果真的暴走，整個黃昏鎮恐怕都會遭波及！",
  ui_story_1014_10141302_98_dialog_content = "黃昏鎮裡除了騎士和軍人，還有許多手無寸鐵的平民！",
  ui_story_1014_10141302_99_dialog_content = "要想辦法制止巨像暴走！",
  ui_story_1014_10141302_100_dialog_content = "但是——",
  ui_story_1014_10141302_101_option_content = "我來想辦法！",
  ui_story_1014_10141302_102_dialog_content = "這座巨像是空裔一族的遺物。",
  ui_story_1014_10141302_103_dialog_content = "如果有辦法制止它暴走，那應該也只有空裔能做到！",
  ui_story_1014_10141302_104_dialog_content = "薇絲、卡蓮，拜託了，請幫我一起阻止它！",
  ui_story_1014_10141302_105_dialog_content = "沒問題！",
  ui_story_1014_10141302_106_dialog_content = "我知道了。",
  ui_story_1014_10141302_107_dialog_content = "謝謝，那我開始了。",
  ui_story_1014_10141302_108_dialog_content = "強制感應！",
  ui_story_1014_10141401_1_dialog_content = "<color=#e8d9bb>嘶啦——</color>",
  ui_story_1014_10141401_2_dialog_content = "領導者號！",
  ui_story_1014_10141401_3_dialog_content = "<color=#e8d9bb>領導者號，正在等待指示。</color>",
  ui_story_1014_10141401_4_dialog_content = "不管你在做什麼，快停下！",
  ui_story_1014_10141401_5_dialog_content = "不可以暴走！會牽連很多無辜生命的！",
  ui_story_1014_10141401_6_dialog_content = "<color=#e8d9bb>正在搜尋與暴走有關的資料。</color>",
  ui_story_1014_10141401_7_dialog_content = "<color=#e8d9bb>領導者號從未發生過暴走行為。</color>",
  ui_story_1014_10141401_8_dialog_content = "沒發生過？那鶯歌之前說的上一次暴走是......",
  ui_story_1014_10141401_9_dialog_content = "<color=#e8d9bb>正在搜尋上一次啟動的資訊。</color>",
  ui_story_1014_10141401_10_dialog_content = "<color=#e8d9bb>領導者號，曾因光子生命體的誤操作而進入防禦模式。</color>",
  ui_story_1014_10141401_11_dialog_content = "<color=#e8d9bb>為保護領導者號中的資料，領導者號進行了必要的躲避。</color>",
  ui_story_1014_10141401_12_dialog_content = "<color=#e8d9bb>在此期間，領導者號並未傷害任何生命體。</color>",
  ui_story_1014_10141401_13_dialog_content = "剛才的震動，不是因為暴走嗎？",
  ui_story_1014_10141401_14_dialog_content = "<color=#e8d9bb>領導者號的動力系統嚴重損壞，已無法啟動。</color>",
  ui_story_1014_10141401_15_dialog_content = "<color=#e8d9bb>推測震動原因來自外部，正在接入巨像外影像。</color>",
  ui_story_1014_10141401_16_dialog_content = "（日蝕語）這是欲望的監牢，是欲望的容器。",
  ui_story_1014_10141401_17_dialog_content = "（日蝕語）欲望構築世界，也終將摧毀世界。",
  ui_story_1014_10141401_18_dialog_content = "（日蝕語）因此，有必要在欲望氾濫之前，將它們請掃乾淨。",
  ui_story_1014_10141401_19_dialog_content = "怎麼會有這麼多暗鬼？！",
  ui_story_1014_10141401_20_dialog_content = "被簇擁在中間的那個，就是指揮牠們的傢伙嗎？",
  ui_story_1014_10141401_21_dialog_content = "（日蝕語）阿斯摩太大人，那些光靈並沒有出來。",
  ui_story_1014_10141401_22_dialog_content = "（日蝕語）他們的欲望終究會將他們引向我們。",
  ui_story_1014_10141401_23_dialog_content = "（日蝕語）因為他們......",
  ui_story_1014_10141401_24_dialog_content = "（日蝕語）已經看到我們了。",
  ui_story_1014_10141401_25_dialog_content = "！！！",
  ui_story_1014_10141401_26_dialog_content = "PlayerName，你沒事吧？！",
  ui_story_1014_10141401_27_dialog_content = "你的臉色怎麼這麼蒼白？",
  ui_story_1014_10141401_28_dialog_content = "震動不是巨像暴走造成的，而是外面的暗鬼！",
  ui_story_1014_10141401_29_dialog_content = "我剛才透過巨像外的影像，看到了一隻很強大的暗鬼。",
  ui_story_1014_10141401_30_dialog_content = "而且，她仿佛也能透過那影像看到我一樣。",
  ui_story_1014_10141401_31_dialog_content = "怎麼可能？難道，那傢伙是像吞羅一樣強大的傢伙嗎？",
  ui_story_1014_10141401_32_dialog_content = "<color=#e8d9bb>轟隆！</color>",
  ui_story_1014_10141401_33_dialog_content = "<color=#e8d9bb>警告，有未授權生命體進入巨像內部。</color>",
  ui_story_1014_10141401_34_dialog_content = "有很強的暗鬼過來了，各位小心！",
  ui_story_1014_10141401_35_dialog_content = "好吵，不只是噪音，還有欲望的味道。",
  ui_story_1014_10141401_36_dialog_content = "有對權力的欲望。",
  ui_story_1014_10141401_37_dialog_content = "有對認同的欲望。",
  ui_story_1014_10141401_38_dialog_content = "還有，哎呀，這是......",
  ui_story_1014_10141401_39_dialog_content = "對於拯救同伴的欲望。",
  ui_story_1014_10141401_40_dialog_content = "妳是誰，想要做什麼？",
  ui_story_1014_10141401_41_dialog_content = "我？怎麼，你也對我懷有欲望？",
  ui_story_1014_10141401_42_dialog_content = "我是阿斯摩太，因欲望而生，也注定會毀滅世間的一切欲望。",
  ui_story_1014_10141401_43_dialog_content = "就讓我毀滅你的欲望吧！",
  ui_story_1014_10141401_44_dialog_content = "你拼死守護的欲望究竟是什麼呢？真想毀滅看看啊。",
  ui_story_1014_10141401_45_dialog_content = "癡心妄想！",
  ui_story_1014_10141401_46_dialog_content = "卡蓮！",
  ui_story_1014_10141401_47_dialog_content = "這傢伙很強，各位，一起上！",
  ui_story_1014_10141401_48_dialog_content = "暗鬼，給我離卡蓮殿下遠一點！",
  ui_story_1014_10141401_49_dialog_content = "欲望，都是些弱小的欲望......",
  ui_story_1014_10141401_50_dialog_content = "僅憑這些，是什麼都無法達成的。",
  ui_story_1014_10141401_51_dialog_content = "有時候欲望太強也不是好事，這位暗鬼......不，你應該是<color=#FFB400>罪靈</color>吧。",
  ui_story_1014_10141401_52_dialog_content = "沒錯，欲望並不是什麼好東西，所以我才想要消滅欲望。",
  ui_story_1014_10141401_53_dialog_content = "但是，只消滅欲望實在是太難了，只要世界上還有光靈存在，欲望就不會消滅。",
  ui_story_1014_10141401_54_dialog_content = "所以，就只好先消滅會產生欲望的光靈了。",
  ui_story_1014_10141401_55_dialog_content = "作為叛徒的空裔，也一併消滅了吧。",
  ui_story_1014_10141401_56_dialog_content = "阿克希亞，不會允許PlayerName受到傷害。",
  ui_story_1014_10141401_57_dialog_content = "嗯？難道這是妳的欲望嗎？",
  ui_story_1014_10141401_58_dialog_content = "保護PlayerName，是阿克希亞的任務。",
  ui_story_1014_10141401_59_dialog_content = "這還真是少見啊，妳，竟然沒有欲望。",
  ui_story_1014_10141401_60_dialog_content = "不，不對。",
  ui_story_1014_10141401_61_dialog_content = "妳本身就是欲望的結晶，所以才會這樣強大。",
  ui_story_1014_10141401_62_dialog_content = "呵呵......真是太有趣了。",
  ui_story_1014_10141401_63_dialog_content = "這樣的欲望，毀滅時究竟會是何等光景呢？",
  ui_story_1014_10141401_64_dialog_content = "真讓人期待啊！",
  ui_story_1014_10141401_65_dialog_content = "各位小心，暗鬼們有所行動了！",
  ui_story_1014_10141402_1_dialog_content = "嗚！",
  ui_story_1014_10141402_2_dialog_content = "阿克希亞！",
  ui_story_1014_10141402_3_dialog_content = "阿克希亞......還能繼續戰鬥。",
  ui_story_1014_10141402_4_dialog_content = "別逞強了，妳現在最需要的是接受治療！",
  ui_story_1014_10141402_5_dialog_content = "太掃興了。",
  ui_story_1014_10141402_6_dialog_content = "整個啟光欲望的結晶，也不過是個柔弱的小丫頭嗎？",
  ui_story_1014_10141402_7_dialog_content = "太令人失望了，現在的光靈，已經只剩下這點毫無價值的欲望了嗎？",
  ui_story_1014_10141402_8_dialog_content = "真讓人無法理解啊。",
  ui_story_1014_10141402_9_dialog_content = "吞羅為什麼會對這樣不值一提的東西如此執著呢？",
  ui_story_1014_10141402_10_dialog_content = "不許妳說阿克希亞的壞話！",
  ui_story_1014_10141402_11_dialog_content = "還不肯承認自己的弱小嗎？",
  ui_story_1014_10141402_12_dialog_content = "那麼，這樣如何？",
  ui_story_1014_10141402_13_dialog_content = "不好，更多暗鬼圍上來了。",
  ui_story_1014_10141402_14_dialog_content = "喬瑟琳、若瑟，注意左側小型暗鬼的偷襲！",
  ui_story_1014_10141402_15_dialog_content = "知道了！",
  ui_story_1014_10141402_16_dialog_content = "鶯歌、西恩，你們對付右側的大型暗鬼！",
  ui_story_1014_10141402_17_dialog_content = "等等，為什麼我們要聽你的？",
  ui_story_1014_10141402_18_dialog_content = "<anim type=Shake><size=45>吼！！！</size></anim>",
  ui_story_1014_10141402_19_dialog_content = "這邊的傢伙就交給我們吧！",
  ui_story_1014_10141402_20_dialog_content = "真沒辦法。",
  ui_story_1014_10141402_21_dialog_content = "剩下的人，和我一起對付這傢伙！",
  ui_story_1014_10141402_22_dialog_content = "你們的欲望終究不過如此。",
  ui_story_1014_10141402_23_dialog_content = "欲望愈強大，力量也就愈強大。",
  ui_story_1014_10141402_24_dialog_content = "你們的欲望庸俗，因此你們的力量才這樣弱小。",
  ui_story_1014_10141402_25_dialog_content = "我的欲望，可是毀滅世間的所有欲望！",
  ui_story_1014_10141402_26_dialog_content = "PlayerName，快躲開！",
  ui_story_1014_10141402_27_dialog_content = "什麼？",
  ui_story_1014_10141402_28_dialog_content = "沒有欲望能逃出我的掌心。",
  ui_story_1014_10141402_29_dialog_content = "嘖！",
  ui_story_1014_10141402_30_dialog_content = "PlayerName！",
  ui_story_1014_10141402_31_dialog_content = "嘶！好疼......",
  ui_story_1014_10141402_32_dialog_content = "糟了，儀器！",
  ui_story_1014_10141402_33_dialog_content = "不要阻擋我，庸俗的欲望。",
  ui_story_1014_10141402_34_dialog_content = "呃！",
  ui_story_1014_10141402_35_dialog_content = "（要趕緊把儀器收好才行！）",
  ui_story_1014_10141402_36_dialog_content = "噫？！",
  ui_story_1014_10141402_37_dialog_content = "原來這就是你的欲望嗎，空裔中的背叛者。",
  ui_story_1014_10141402_38_dialog_content = "......",
  ui_story_1014_10141402_39_dialog_content = "就只有這個？",
  ui_story_1014_10141402_40_dialog_content = "把它放下！",
  ui_story_1014_10141402_41_dialog_content = "無趣。",
  ui_story_1014_10141402_42_dialog_content = "那傢伙在說什麼？",
  ui_story_1014_10141402_43_dialog_content = "無趣，無趣，真是無趣。",
  ui_story_1014_10141402_44_dialog_content = "背叛者，你的欲望，就僅限於這堆因為錯誤產生的無意義的垃圾嗎？",
  ui_story_1014_10141402_45_option_content = "才不是垃圾！",
  ui_story_1014_10141402_46_dialog_content = "這些資料，是奇蹟！",
  ui_story_1014_10141402_47_dialog_content = "巨像們在漫長的時間裡不停嘗試，一次次累積經驗，最終形成的人格......",
  ui_story_1014_10141402_48_dialog_content = "像妳這種張口閉口只知道欲望的庸俗傢伙，是不會理解它們的珍貴之處的！",
  ui_story_1014_10141402_49_dialog_content = "呵呵......庸俗？",
  ui_story_1014_10141402_50_dialog_content = "沒想到叛徒也能和我擁有相同的觀點。",
  ui_story_1014_10141402_51_dialog_content = "沒錯，欲望都是庸俗的東西，庸俗到不該存在於這世界上。",
  ui_story_1014_10141402_52_dialog_content = "暗鬼沒有欲望，不會被誘惑，因此暗鬼才是適合存在於這世界上的完美生物。",
  ui_story_1014_10141402_53_dialog_content = "也正是為了拋棄欲望，我才選擇成為罪靈。",
  ui_story_1014_10141402_54_dialog_content = "PlayerName，不要聽她的歪理邪說。",
  ui_story_1014_10141402_55_dialog_content = "我們一起攻擊，把儀器搶回來！",
  ui_story_1014_10141402_56_dialog_content = "不過，算了，我改主意了。",
  ui_story_1014_10141402_57_dialog_content = "既然你這麼想要它，那就給你吧。",
  ui_story_1014_10141402_58_dialog_content = "糟了，儀器！",
  ui_story_1014_10141402_59_dialog_content = "呼，好險......",
  ui_story_1014_10141402_60_dialog_content = "（儀器看起來沒有損壞。）",
  ui_story_1014_10141402_61_dialog_content = "（這傢伙的目的到底是什麼，難道只是為了嘲笑我們嗎？）",
  ui_story_1014_10141402_62_dialog_content = "我本以為你們的欲望足夠強大，但是現在看來，我錯了。",
  ui_story_1014_10141402_63_dialog_content = "原來你們所圖的，也不過是一些無用的廢物。",
  ui_story_1014_10141402_64_dialog_content = "我甚至提不起興趣去毀滅這些欲望。",
  ui_story_1014_10141402_65_dialog_content = "少在這裡口出狂言！",
  ui_story_1014_10141402_66_dialog_content = "既然妳主動交還了PlayerName需要的設備，那我也無須顧忌了。",
  ui_story_1014_10141402_67_dialog_content = "接招吧，暗鬼！",
  ui_story_1014_10141402_68_dialog_content = "忠誠，是最無用的欲望。",
  ui_story_1014_10141402_69_dialog_content = "好強的力量！",
  ui_story_1014_10141402_70_dialog_content = "那傢伙剛才根本沒有使出全力？！",
  ui_story_1014_10141402_71_dialog_content = "<anim type=Shake><size=45>吼！！！</size></anim>",
  ui_story_1014_10141402_72_dialog_content = "貝爾塔，危險！冰花，散開！",
  ui_story_1014_10141402_73_dialog_content = "太令人失望了......",
  ui_story_1014_10141402_74_dialog_content = "這裡都是些無聊的欲望，我連毀滅它們的興趣都提不起來。",
  ui_story_1014_10141402_75_dialog_content = "但是，你，空裔中的背叛者，PlayerName。",
  ui_story_1014_10141402_76_dialog_content = "......",
  ui_story_1014_10141402_77_dialog_content = "或許只要再給你一些時間，你的欲望，就會變得非常有趣，非常......美味。",
  ui_story_1014_10141402_78_dialog_content = "當然，還有妳，<color=#FFB400>薇絲</color>。",
  ui_story_1014_10141402_79_dialog_content = "我？",
  ui_story_1014_10141402_80_dialog_content = "走吧，暗鬼們。",
  ui_story_1014_10141402_81_dialog_content = "這裡已經不值得我停留了。",
  ui_story_1014_10141402_82_dialog_content = "別想輕易逃走！",
  ui_story_1014_10141402_83_dialog_content = "別衝動，貝爾塔！",
  ui_story_1014_10141402_84_dialog_content = "她不是一般的暗鬼，就算我們拼盡全力，恐怕也只能與她打成平手。",
  ui_story_1014_10141402_85_dialog_content = "我們沒有餘力追擊牠們，現在最需要做的，就是撤退並尋求支援。",
  ui_story_1014_10141402_86_dialog_content = "可是......",
  ui_story_1014_10141402_87_dialog_content = "貝爾塔，李奧的判斷是正確的，我們確實不該繼續追擊。",
  ui_story_1014_10141402_88_dialog_content = "先返回黃昏鎮吧。",
  ui_story_1014_10141402_89_dialog_content = "......是。",
  ui_story_1014_10141402_90_dialog_content = "騎士長，感謝您的認同。",
  ui_story_1014_10141402_91_dialog_content = "這是每個熟悉戰場的人都會得出的結論。",
  ui_story_1014_10141402_92_dialog_content = "（吞羅沒有現身，卻引來了其他的罪靈嗎？）",
  ui_story_1014_10141402_93_dialog_content = "（這到底是巧合，還是必然？）",
  ui_story_1014_10141402_94_dialog_content = "（無論如何，這次任務都以失敗告終了，吞羅並未像預想中的那樣出現。）",
  ui_story_1014_10141402_95_dialog_content = "（追查他們行蹤的任務，只能使用其他方法完成了。）",
  ui_story_1014_10141402_95X1_dialog_content = "就這麼走了嗎？就這樣把領導者號放在這裡......",
  ui_story_1014_10141402_95X2_dialog_content = "有沒有什麼辦法，讓它也一起回去？薇絲，啟光的技術能修好它嗎？",
  ui_story_1014_10141402_95X3_dialog_content = "這恐怕很困難......",
  ui_story_1014_10141402_95X4_dialog_content = "……",
  ui_story_1014_10141402_95X5_dialog_content = "PlayerName，我理解你的心情，但這是目前的我們都做不到的事。",
  ui_story_1014_10141402_95X6_dialog_content = "鶯歌，這座巨像對PlayerName來說很重要，真的沒有辦法了嗎？",
  ui_story_1014_10141402_95X7_dialog_content = "這座巨像本身已經損壞了，更何況上一次暴走又造成了二次傷害。",
  ui_story_1014_10141402_95X8_dialog_content = "它現在還在運行這件事本身，就是一個奇蹟......",
  ui_story_1014_10141402_95X9_dialog_content = "怎麼會……",
  ui_story_1014_10141402_95X10_dialog_content = "<color=#e8d9bb>檢測到空裔PlayerName即將離開。</color>",
  ui_story_1014_10141402_95X11_dialog_content = "領導者號？",
  ui_story_1014_10141402_95X12_dialog_content = "<color=#e8d9bb>領導者號向空裔PlayerName發出詢問。</color>",
  ui_story_1014_10141402_95X13_dialog_content = "<color=#e8d9bb>空裔PlayerName，請告知下次到訪時間及修復領導者號的計畫。</color>",
  ui_story_1014_10141402_95X14_dialog_content = "……",
  ui_story_1014_10141402_95X15_dialog_content = "我......不知道。",
  ui_story_1014_10141402_95X16_dialog_content = "對不起，又要讓你繼續等待了......",
  ui_story_1014_10141402_95X17_dialog_content = "<color=#e8d9bb>指令收到。</color>",
  ui_story_1014_10141402_95X18_dialog_content = "<color=#e8d9bb>根據35的設定，在此對空裔PlayerName送出祝福。</color>",
  ui_story_1014_10141402_95X19_dialog_content = "<color=#e8d9bb>請不要為無法修復領導者號難過，請你的目光注視前方。</color>",
  ui_story_1014_10141402_95X20_dialog_content = "什麼？這是35的寄語？她連這一點都想到了？",
  ui_story_1014_10141402_95X21_dialog_content = "<color=#e8d9bb>領導者號與35一起，祝PlayerName一路順風。</color>",
  ui_story_1014_10141402_95X22_dialog_content = "謝謝……",
  ui_story_1014_10141402_95X23_dialog_content = "我知道了，我會帶著你們的份，繼續旅途......",
  ui_story_1014_10141402_95X24_dialog_content = "PlayerName，我們走吧。",
  ui_story_1014_10141402_95X25_dialog_content = "嗯，走吧。還有別的事等著我們去做。",
  ui_story_1014_10141402_96_dialog_content = "<color=#e8d9bb>臨空者號，艦橋</color>",
  ui_story_1014_10141402_97_dialog_content = "臨空者號，啟動！",
  ui_story_1014_10141402_98_dialog_content = "那群暗鬼呢，沒有跟蹤我們吧？",
  ui_story_1014_10141402_99_dialog_content = "我感應不到牠們，應該已經不在這附近了。",
  ui_story_1014_10141402_100_dialog_content = "雖然搞不懂牠們究竟在想什麼，但總覺得被小看了。",
  ui_story_1014_10141402_101_dialog_content = "不過，總有一天，暗鬼們會付出小看我們的代價。",
  ui_story_1014_10141402_102_dialog_content = "阿克希亞的傷怎麼樣了，剛才承受了暗鬼那麼重的攻擊......",
  ui_story_1014_10141402_103_dialog_content = "阿克希亞，沒有關係。",
  ui_story_1014_10141402_104_dialog_content = "阿克希亞的身體雖然脆弱，但是，咳咳……不會被輕易打敗。",
  ui_story_1014_10141402_105_dialog_content = "（這也是所謂的改造帶來的結果嗎？）",
  ui_story_1014_10141402_107_dialog_content = "（不過，萊因哈特反對這項實驗的態度非常堅決，一定有她的道理。）",
  ui_story_1014_10141402_109_dialog_content = "（這麼說來，萊因哈特似乎也有著超乎常人的戰鬥力和恢復力......）",
  ui_story_1014_10141402_110_dialog_content = "PlayerName，在想什麼呢？",
  ui_story_1014_10141402_111_dialog_content = "欸？沒......沒什麼。",
  ui_story_1014_10141402_112_dialog_content = "怎麼了，薇絲？",
  ui_story_1014_10141402_113_dialog_content = "也沒什麼啦，我只是有些地方想不通。",
  ui_story_1014_10141402_114_dialog_content = "那隻叫做阿斯摩太的暗鬼，為什麼最後會提到我呢？",
  ui_story_1014_10141402_115_dialog_content = "明明我並不認識她，更沒有說過我的名字。",
  ui_story_1014_10141402_116_option_content = "難道是因為和弦紐帶？",
  ui_story_1014_10141402_117_dialog_content = "薇絲使用過和弦紐帶，獲得了特殊的力量。",
  ui_story_1014_10141402_118_dialog_content = "難道阿斯摩太是察覺到了這一點，才會對妳有所關注嗎？",
  ui_story_1014_10141402_119_dialog_content = "不知道......",
  ui_story_1014_10141402_120_dialog_content = "那傢伙的動機實在是太難懂了。",
  ui_story_1014_10141402_121_option_content = "難道是因為身體情況？",
  ui_story_1014_10141402_122_dialog_content = "用過和弦紐帶裝置後，薇絲的身體一直處於一種特殊狀態吧？",
  ui_story_1014_10141402_123_dialog_content = "之前的發光現象也是那個裝置造成的。",
  ui_story_1014_10141402_124_dialog_content = "但是僅從外表是看不出來變化的吧？",
  ui_story_1014_10141402_125_dialog_content = "難道說，那傢伙有什麼特殊的能力，可以察覺到內在的變化嗎？",
  ui_story_1014_10141402_126_dialog_content = "不清楚......",
  ui_story_1014_10141402_127_dialog_content = "先不說這個，妳現在覺得怎麼樣，薇絲？",
  ui_story_1014_10141402_128_dialog_content = "經歷了這麼多戰鬥，妳有覺得哪裡不舒服嗎？",
  ui_story_1014_10141402_129_dialog_content = "放心吧。我現在雖然有些疲憊，但是只要休息一下就能恢復。",
  ui_story_1014_10141402_130_dialog_content = "看起來就算經歷困難的戰鬥，我的身體也沒有出現不好的情況呢。",
  ui_story_1014_10141402_131_dialog_content = "是嗎？那我就放心了。",
  ui_story_1014_10141402_132_dialog_content = "剩下的事就是回到迦南城，用拿到的組件和資料修復臨空者號了！",
  ui_story_1014_10141402_133_dialog_content = "在這之前還要先把阿克希亞他們送回黃昏鎮。",
  ui_story_1014_10141402_134_dialog_content = "嗯！",
  ui_story_1014_10141402_135_dialog_content = "<color=#e8d9bb>嘶啦——</color>",
  ui_story_1014_10141402_136_dialog_content = "嗯？臨空者號收到了遠端通訊訊號，發信人是......領導者號？！",
  ui_story_1014_10141402_137_dialog_content = "<color=#e8d9bb>嘶啦——！</color>",
  ui_story_1014_10141402_137X1_dialog_content = "<color=#e8d9bb>根據35的命令，在空裔離開後，開始執行本指令。</color>",
  ui_story_1014_10141402_138_dialog_content = "<color=#e8d9bb>檢測到條件符合需求，領導者號向空裔PlayerName發出請求。</color>",
  ui_story_1014_10141402_139_dialog_content = "巨像在向我發出請求？",
  ui_story_1014_10141402_140_dialog_content = "<color=#e8d9bb>領導者號的資料已經全部由空裔一族的PlayerName獲得。</color>",
  ui_story_1014_10141402_141_dialog_content = "<color=#e8d9bb>領導者號能源核心已受損，無法修復，即將停止運行。</color>",
  ui_story_1014_10141402_142_dialog_content = "<color=#e8d9bb>根據35的指令，符合上述兩種情況時，領導者號將向附近的空裔發出請求——</color>",
  ui_story_1014_10141402_143_dialog_content = "難道說......",
  ui_story_1014_10141402_144_dialog_content = "<color=#e8d9bb>領導者號請求PlayerName為領導者號<color=#FFB400>寫一首詩</color>。</color>",
  ui_story_1014_10141402_145_dialog_content = "......",
  ui_story_1014_10141402_146_dialog_content = "我知道了。",
  ui_story_1014_10141402_147_dialog_content = "但我還沒試過寫詩，不一定寫得好。",
  ui_story_1014_10141402_148_dialog_content = "你曾經與我們一起踏上航程",
  ui_story_1014_10141402_149_dialog_content = "無垠的星海托著你的翅膀飛翔",
  ui_story_1014_10141402_150_dialog_content = "跨越千里、跨越萬年的旅途啊",
  ui_story_1014_10141402_151_dialog_content = "連星星的光芒都逐漸熄滅",
  ui_story_1014_10141402_152_dialog_content = "最終只剩下漫長的孤旅",
  ui_story_1014_10141402_153_dialog_content = "當回家的呼喚聲終於響起",
  ui_story_1014_10141402_154_dialog_content = "卻已迷失了家的方向",
  ui_story_1014_10141402_155_dialog_content = "你在星空中漂泊了太久",
  ui_story_1014_10141402_156_dialog_content = "又在這黑暗中停留了太久",
  ui_story_1014_10141402_157_dialog_content = "時間與災難曾經抹去了家存在的痕跡",
  ui_story_1014_10141402_158_dialog_content = "如今指引歸途的燈塔已經再次亮起",
  ui_story_1014_10141402_159_dialog_content = "願你的意識隨著風與蒲公英",
  ui_story_1014_10141402_160_dialog_content = "飛回到空之山谷去",
  ui_story_1014_10141402_161_dialog_content = "......",
  ui_story_1014_10141402_162_dialog_content = "（果然還是沒寫過詩，寫得好糟糕......）",
  ui_story_1014_10141402_163_dialog_content = "<color=#e8d9bb>詩歌已收到。開始播放錄音。</color>",
  ui_story_1014_10141402_164_dialog_content = "謝謝你，未來來到這裡的好心人！",
  ui_story_1014_10141402_165_dialog_content = "這是......35的聲音？",
  ui_story_1014_10141402_166_dialog_content = "有了這首詩的陪伴，領導者號也一定會感到開心吧。",
  ui_story_1014_10141402_166X1_dialog_content = "我們雖然素未謀面，但我相信我們能理解這一刻彼此的心情。",
  ui_story_1014_10141402_166X2_dialog_content = "就算不使用感知能力，也能體會到！",
  ui_story_1014_10141402_166X3_dialog_content = "是啊，就算不使用感知能力，但是，這份想要流淚的衝動......",
  ui_story_1014_10141402_166X4_dialog_content = "不管發現這份「禮物」的你是誰，我由衷地希望你的旅途有無數夥伴，永不孤單。",
  ui_story_1014_10141402_166X5_dialog_content = "就讓它與你一起遊歷吧，這是我和領導者號共同的心願！",
  ui_story_1014_10141402_166X6_dialog_content = "謝謝，謝謝你們......",
  ui_story_1014_10141402_166X7_dialog_content = "這份禮物，我會好好使用。",
  ui_story_1014_10141402_168_dialog_content = "再見了，領導者號。",
  ui_story_1014_10141402_169_dialog_content = "再見了，35。",
  ui_story_1014_10141501_1_dialog_content = "<color=#e8d9bb>一段時間後，黃昏鎮</color>",
  ui_story_1014_10141501_2_dialog_content = "送到這裡就可以了。",
  ui_story_1014_10141501_3_dialog_content = "真是辛苦你了，PlayerName。",
  ui_story_1014_10141501_4_dialog_content = "哪裡的事，明明是我拜託你們幫忙的。",
  ui_story_1014_10141501_5_dialog_content = "那麼，再會了，各位。",
  ui_story_1014_10141501_6_dialog_content = "很榮幸能與你們共同戰鬥，我也先回去了。",
  ui_story_1014_10141501_7_dialog_content = "有機會再見吧，PlayerName。",
  ui_story_1014_10141501_8_dialog_content = "等一下。",
  ui_story_1014_10141501_9_dialog_content = "騎士長還有什麼指示嗎？",
  ui_story_1014_10141501_10_dialog_content = "你還沒有回答我那個問題，為什麼你會覺得不公平。",
  ui_story_1014_10141501_11_dialog_content = "哈哈哈哈，原來您還在在意這個問題嗎？",
  ui_story_1014_10141501_12_dialog_content = "那麼，我也直言不諱了——",
  ui_story_1014_10141501_13_dialog_content = "我認為現在的白夜城需要一場變革。",
  ui_story_1014_10141501_14_dialog_content = "你！",
  ui_story_1014_10141501_15_dialog_content = "您應該也知道，白夜城的爵位是依靠血脈來傳承的。",
  ui_story_1014_10141501_16_dialog_content = "不依靠自身的能力就能獲得地位，之後就只會為了維護自身地位而行動。",
  ui_story_1014_10141501_17_dialog_content = "這就使得那些並非貴族卻又有著能力的人，在白夜城很難得到晉升。",
  ui_story_1014_10141501_18_dialog_content = "白夜城需要徹底的變革，而我想成為掀起這場風暴的人。",
  ui_story_1014_10141501_19_dialog_content = "你可知道這句話只要一說出口，我就能向審判庭以謀劃叛亂的罪名告發你？",
  ui_story_1014_10141501_20_dialog_content = "哈哈哈哈，我認為......不，我確信您不會這麼做。",
  ui_story_1014_10141501_21_dialog_content = "就算您出身高貴，也沒有被權力蒙蔽雙眼。",
  ui_story_1014_10141501_22_dialog_content = "您與那些通常意義上的白夜城貴族不同，是一名真正的騎士，經歷過戰場的洗禮。",
  ui_story_1014_10141501_23_dialog_content = "這一點，同樣身為騎士的我還是能夠察覺的。",
  ui_story_1014_10141501_24_dialog_content = "是嗎？",
  ui_story_1014_10141501_25_dialog_content = "那你就去拼命實現你的野心吧。",
  ui_story_1014_10141501_26_dialog_content = "讓我們分別用行動證明，誰的選擇更有利於白夜城。",
  ui_story_1014_10141501_27_dialog_content = "好，一言為定！",
  ui_story_1014_10141501_28_dialog_content = "這樣放他走真的沒問題嗎，卡蓮殿下？",
  ui_story_1014_10141501_29_dialog_content = "沒關係，讓他去吧。",
  ui_story_1014_10141501_30_dialog_content = "這麼說起來，喬瑟琳是不是也要......欸？喬瑟琳去哪裡了？",
  ui_story_1014_10141501_31_dialog_content = "喬瑟琳，被剛剛路過的人叫走幫忙了。",
  ui_story_1014_10141501_32_dialog_content = "就在PlayerName看著卡蓮和李奧聊天的時候。",
  ui_story_1014_10141501_33_dialog_content = "她就是那種性格啦，只要被別人拜託，就會立刻衝上去幫忙。",
  ui_story_1014_10141501_34_dialog_content = "沒來得及和她道別，感覺有些可惜呢。",
  ui_story_1014_10141501_35_dialog_content = "總有機會再見的吧。",
  ui_story_1014_10141501_36_dialog_content = "鶯歌、西恩和阿克希亞，也要回去了。",
  ui_story_1014_10141501_37_dialog_content = "任務，已經順利完成了。",
  ui_story_1014_10141501_38_dialog_content = "話雖如此，還是要先把關於阿斯摩太的情況告知上級才行。",
  ui_story_1014_10141501_39_dialog_content = "我們就在這裡道別吧，PlayerName、薇絲中尉、卡蓮殿下以及貝爾塔小姐。",
  ui_story_1014_10141501_40_dialog_content = "有機會再見啦！",
  ui_story_1014_10141501_41_dialog_content = "阿克希亞，會幫助PlayerName，完成任務。",
  ui_story_1014_10141501_42_dialog_content = "對了，下一次聯合軍演我們也會參加喔。",
  ui_story_1014_10141501_43_dialog_content = "讓我們在演習的模擬戰場上見吧！",
  ui_story_1014_10141501_44_dialog_content = "在戰場上嗎？嗯，我也會期待與你們相見的！",
  ui_story_1014_10141501_45_dialog_content = "到時候再一決高下吧。",
  ui_story_1014_10141501_46_option_content = "下次再見！",
  ui_story_1014_10141501_47_dialog_content = "終於把大家都平安送到黃昏鎮了。",
  ui_story_1014_10141501_48_dialog_content = "我們也趕快回迦南城吧。",
  ui_story_1014_10141501_49_dialog_content = "雖然那個叫阿斯摩太的暗鬼非常讓人在意，但是現在最要緊的還是修好臨空者號。",
  ui_story_1014_10141501_50_dialog_content = "是的，這件事不能再耽擱了。",
  ui_story_1014_10141501_51_dialog_content = "我們走吧！",
  ui_story_1014_10141501_52_dialog_content = "<color=#e8d9bb>一段時間後，迦南城</color>",
  ui_story_1014_10141501_53_dialog_content = "阿爾戈爾，我們把你需要的資料帶回來了！",
  ui_story_1014_10141501_54_dialog_content = "嗯......嗯？什麼？",
  ui_story_1014_10141501_55_dialog_content = "你們已經回來了？這麼快？",
  ui_story_1014_10141501_56_dialog_content = "是的。",
  ui_story_1014_10141501_57_dialog_content = "雖然路上遭遇了一些意想不到的敵人，但我們還是順利拿到資料回來了。",
  ui_story_1014_10141501_58_dialog_content = "嗯，我聽說了哦。是一個奇怪的罪靈，名叫<color=#FFB400>阿斯摩太</color>，對吧？",
  ui_story_1014_10141501_59_dialog_content = "你已經知道了？！",
  ui_story_1014_10141501_60_dialog_content = "也對，黃昏鎮也有啟光的駐軍。",
  ui_story_1014_10141501_61_dialog_content = "不管發生了什麼，只需要一通終端通訊，整個迦南城都會知道吧。",
  ui_story_1014_10141501_62_dialog_content = "差不多吧，可不要小看啟光的情報系統。",
  ui_story_1014_10141501_63_dialog_content = "不過，罪靈什麼的還是交給大元帥去應對吧。",
  ui_story_1014_10141501_64_dialog_content = "我現在只想立刻看看你帶回來的巨像資料。",
  ui_story_1014_10141501_65_dialog_content = "你是怎麼拿到這些資料的？明明那麼多啟光探險隊都從那裡空手而歸。",
  ui_story_1014_10141501_66_dialog_content = "那是因為......",
  ui_story_1014_10141501_67_option_content = "我是空裔",
  ui_story_1014_10141501_68_dialog_content = "那座巨像的意識是在一名空裔的不懈堅持下才最終誕生的。",
  ui_story_1014_10141501_69_dialog_content = "我只是作為最後的空裔，重新取回了這份蒙塵的禮物而已。",
  ui_story_1014_10141501_70_dialog_content = "有意思，這就是空裔之間的傳承嗎？",
  ui_story_1014_10141501_71_option_content = "那裡也是一份「禮物」",
  ui_story_1014_10141501_72_dialog_content = "那座巨像一直在等待著其他人的到來，等著將它儲存的珍貴資料傳遞下去。",
  ui_story_1014_10141501_73_dialog_content = "就像弗朗茨老師曾經在回歸塔中做的那樣。",
  ui_story_1014_10141501_74_dialog_content = "那台巨像......最後甚至還希望我為它作一首詩。",
  ui_story_1014_10141501_75_dialog_content = "巨像也會做這種事嗎？真奇妙。",
  ui_story_1014_10141501_76_dialog_content = "先讓我看看這些資料吧。",
  ui_story_1014_10141501_77_dialog_content = "......",
  ui_story_1014_10141501_78_dialog_content = "嘖，這些資料比我想像的要複雜得多。",
  ui_story_1014_10141501_79_dialog_content = "這是什麼意思？",
  ui_story_1014_10141501_80_dialog_content = "複雜？那還能修好臨空者號嗎？",
  ui_story_1014_10141501_81_dialog_content = "你先別著急，讓我慢慢跟你解釋。",
  ui_story_1014_10141501_82_dialog_content = "你應該也知道吧，巨像的意識誕生於某位空裔堅持不懈的嘗試。",
  ui_story_1014_10141501_83_dialog_content = "嗯。",
  ui_story_1014_10141501_84_dialog_content = "在她的嘗試中，巨像為了面對原本設定裡沒有考慮到的情況，發生了未知的變化。",
  ui_story_1014_10141501_85_dialog_content = "我們一般稱這種變化為「錯誤」，但在這裡，我更願意稱之為「<color=#FFB400>成長</color>」。",
  ui_story_1014_10141501_86_dialog_content = "但是，由於產生變化的根本原因是意外——",
  ui_story_1014_10141501_87_dialog_content = "所以體現在意識資料中時，這些變化就會變成相當複雜且混亂的資料變化。",
  ui_story_1014_10141501_88_dialog_content = "這些資料變化有些可能無用，有些則可能成為使巨像逐步擁有意識的關鍵。",
  ui_story_1014_10141501_89_dialog_content = "並且，由於不同巨像之間的資料是相互獨立的，因此各自發生的變化也不同。",
  ui_story_1014_10141501_90_dialog_content = "你拷貝出來的這些意識資料的形成過程，是無法直接套用在臨空者號上的。",
  ui_story_1014_10141501_91_dialog_content = "我聽不太懂你說的這些複雜知識。",
  ui_story_1014_10141501_92_dialog_content = "我只想知道臨空者號能不能獲救！",
  ui_story_1014_10141501_93_dialog_content = "我需要一些時間分析這些資料，才能知道具體的答案。",
  ui_story_1014_10141501_94_dialog_content = "僅憑臨空者號自身的資料是不夠的，但現在有了這些資料，我可以進行交叉對比。",
  ui_story_1014_10141501_95_dialog_content = "讓臨空者號恢復的機率，已經因此大大提升了。",
  ui_story_1014_10141501_96_dialog_content = "希望你能相信我，給我一些時間。",
  ui_story_1014_10141501_97_dialog_content = "我也沒有其他的選擇了吧。",
  ui_story_1014_10141501_98_dialog_content = "別說得那麼灰心喪氣。在研究人工智慧方面，我可是很有信心的。",
  ui_story_1014_10141501_99_dialog_content = "經歷了這麼多事，你也是時候休息一下了。",
  ui_story_1014_10141501_100_dialog_content = "接下來，就是我的戰場了。",
  ui_story_1014_10141501_101_dialog_content = "PlayerName，臨空者號的情況怎麼樣了？",
  ui_story_1014_10141501_102_dialog_content = "那些資料能提幫助嗎？",
  ui_story_1014_10141501_103_dialog_content = "我也不確定，阿爾戈爾說她需要一些時間對那些資料進行解析。",
  ui_story_1014_10141501_104_dialog_content = "是嗎......",
  ui_story_1014_10141501_105_dialog_content = "但願能有好結果。",
  ui_story_1014_10141501_106_dialog_content = "但願吧。",
  ui_story_1014_10141501_107_dialog_content = "<color=#e8d9bb>嘀嘀嘀——</color>",
  ui_story_1014_10141501_108_dialog_content = "薇絲中尉，PlayerName，你們都在嗎？",
  ui_story_1014_10141501_109_dialog_content = "尤利西斯長官？！",
  ui_story_1014_10141501_110_dialog_content = "關於和弦紐帶裝置的研究，我們這邊有了一些新的進展。",
  ui_story_1014_10141501_111_dialog_content = "薇絲中尉，請你與PlayerName立刻前往指定地點報到，稍後我會把座標發給你們。",
  ui_story_1014_10141501_112_dialog_content = "座標的具體內容涉及機密，無關人員不得隨行。",
  ui_story_1014_10141501_113_dialog_content = "收到請回覆。",
  ui_story_1014_10141501_114_dialog_content = "是。薇絲中尉收到。",
  ui_story_1014_10141501_115_dialog_content = "很好，通訊結束。",
  ui_story_1014_10141501_116_dialog_content = "又是涉密嗎，看起來沒有我能幫上忙的地方了。",
  ui_story_1014_10141501_117_dialog_content = "那麼，這段時間我就先回白夜城吧。",
  ui_story_1014_10141501_118_dialog_content = "正好我也想回白夜城一趟，順便查一查關於鐵棘騎士團的資訊。",
  ui_story_1014_10141501_119_dialog_content = "還要向城主大人報告黃昏鎮的情況。",
  ui_story_1014_10141501_120_dialog_content = "卡蓮還是很在意那些人的事情嗎？",
  ui_story_1014_10141501_121_dialog_content = "說不在意是不可能的。",
  ui_story_1014_10141501_122_dialog_content = "這關乎白夜城的事，有必要確認那些人，尤其是那個遠征騎士李奧的背景。",
  ui_story_1014_10141501_123_dialog_content = "我不否認他的想法，如果是他，確實可能使白夜城變得更好。",
  ui_story_1014_10141501_124_dialog_content = "但我也不能忽視他可能會成為白夜城威脅的事實。",
  ui_story_1014_10141501_125_dialog_content = "不愧是卡蓮，果然很可靠！",
  ui_story_1014_10141501_126_dialog_content = "那我們也趁著現在趕緊前往通知的地點吧。",
  ui_story_1014_10141501_127_dialog_content = "好，現在出發吧。",
  ui_story_1014_10141501_128_dialog_content = "<color=#e8d9bb>啟光聯邦某處</color>",
  ui_story_1014_10141501_129_dialog_content = "按照座標找到這裡，沒想到竟然是一座地下城？！",
  ui_story_1014_10141501_130_dialog_content = "啟光任何一個版本的地圖都沒有標注過這座地下城的存在。",
  ui_story_1014_10141501_131_dialog_content = "如果不是有座標，也根本不可能找到這裡。",
  ui_story_1014_10141501_132_dialog_content = "......",
  ui_story_1014_10141501_133_dialog_content = "這裡的防禦看起來真森嚴......",
  ui_story_1014_10141501_134_dialog_content = "既然是保密設施，守衛多也是理所當然的。",
  ui_story_1014_10141501_135_dialog_content = "你們來了。",
  ui_story_1014_10141501_136_dialog_content = "（怎麼是這個傢伙......）",
  ui_story_1014_10141501_137_dialog_content = "（每次和他說話，都會有種被審視的感覺，讓人不舒服。）",
  ui_story_1014_10141501_138_dialog_content = "怎麼是你，把我們叫過來的不是尤利西斯嗎？",
  ui_story_1014_10141501_139_dialog_content = "那位長官有一件緊急且重要的事情要做，就命令我負責接應兩位。",
  ui_story_1014_10141501_140_dialog_content = "這麼著急把我們叫過來，是有什麼緊急的事情嗎？",
  ui_story_1014_10141501_141_dialog_content = "既然你們已經知道了不少事，這裡的研究也沒必要對你們隱瞞了。",
  ui_story_1014_10141501_142_dialog_content = "先來說明情況吧。",
  ui_story_1014_10141501_143_dialog_content = "啟明星計畫的起源，其實和位於這裡的<color=#FFB400>另一台和弦紐帶裝置</color>有關。",
  ui_story_1014_10141501_144_dialog_content = "什麼，和弦紐帶裝置不止有一台？！",
  ui_story_1014_10141501_145_dialog_content = "沒錯。啟光在多年前曾經發現過一台和弦紐帶裝置。",
  ui_story_1014_10141501_146_dialog_content = "透過研究這台裝置，我們掌握了改造光靈的方法。",
  ui_story_1014_10141501_147_dialog_content = "只不過，由於種種原因，這台裝置並不像空谷中的那台那樣完整。",
  ui_story_1014_10141501_148_dialog_content = "啟光研究出的改造方法也因為那台機器的部分缺失而並不完美。",
  ui_story_1014_10141501_149_dialog_content = "就算今天，這種改造也無法完全控制能力變化的方向，並且有著極高的失敗率。",
  ui_story_1014_10141501_150_dialog_content = "那你們怎麼還不停止這種研究？",
  ui_story_1014_10141501_151_dialog_content = "明知道那麼危險，可能會給人帶來痛苦......",
  ui_story_1014_10141501_152_dialog_content = "你們到底為什麼還要做這種事情？",
  ui_story_1014_10141501_153_dialog_content = "我不介意再次強調一遍，因為啟光的大部分，都只是普通人。",
  ui_story_1014_10141501_154_dialog_content = "只有這樣做，才能維持啟光的存在。",
  ui_story_1014_10141501_155_option_content = "......",
  ui_story_1014_10141501_156_option_content = "我無法認同",
  ui_story_1014_10141501_157_dialog_content = "我理解你的心情，但是請不要忘記，我們之間的關係更類似於交易。",
  ui_story_1014_10141501_158_dialog_content = "如果你覺得不舒服，當然有權利停止向我們開放回歸塔的研究許可權。",
  ui_story_1014_10141501_159_dialog_content = "然而那樣做的話，也會使對和弦紐帶及其副作用的研究陷入停滯。",
  ui_story_1014_10141501_160_dialog_content = "（他這是在用薇絲和巴頓威脅我？）",
  ui_story_1014_10141501_161_dialog_content = "（竟然在這裡被擺了一道......）",
  ui_story_1014_10141501_162_dialog_content = "看你的表情，應該也能理解了吧。",
  ui_story_1014_10141501_163_dialog_content = "你們現在究竟想做什麼？",
  ui_story_1014_10141501_164_dialog_content = "透過研究回歸塔中的裝置，我們對之前那台並不完整的和弦紐帶裝置也進行了改良。",
  ui_story_1014_10141501_165_dialog_content = "我們想用這兩台已經損壞的裝置，製作出完整的、沒有副作用的和弦紐帶。",
  ui_story_1014_10141501_166_dialog_content = "我認為，只要能製作出完整的和弦紐帶裝置，很多問題就都能迎刃而解。",
  ui_story_1014_10141501_167_dialog_content = "比如，薇絲中尉與巴頓軍團長身上存在的未知副作用。",
  ui_story_1014_10141501_168_dialog_content = "......那你們需要我做什麼？",
  ui_story_1014_10141501_169_dialog_content = "和弦紐帶裝置畢竟是空裔的技術，有一部分資料只能透過空裔的感應能力進行解讀。",
  ui_story_1014_10141501_170_dialog_content = "目前我們正在嘗試對這些資料進行還原，等這一步完成，就需要你提供幫助了。",
  ui_story_1014_10141501_171_dialog_content = "現在只需要你稍作等待。",
  ui_story_1014_10141501_172_dialog_content = "（急急忙忙地把我叫過來，現在卻需要我等著嗎......）",
  ui_story_1014_10141501_173_dialog_content = "好吧，我知道了。",
  ui_story_1014_10141501_174_dialog_content = "感謝你的配合。",
  ui_story_1014_10141501_175_dialog_content = "我先失陪了，還有許多工作等著我去做。",
  ui_story_1014_10141501_176_dialog_content = "這種感覺真不好。",
  ui_story_1014_10141501_177_dialog_content = "就好像我成為了別人用來威脅PlayerName的工具。",
  ui_story_1014_10141501_178_dialog_content = "不要這麼比喻自己......",
  ui_story_1014_10141501_179_dialog_content = "不接受他們的幫助，只以我自己的能力，是不能讓妳擺脫副作用的。",
  ui_story_1014_10141501_180_dialog_content = "PlayerName......",
  ui_story_1014_10141501_181_dialog_content = "你可以不用考慮我的情況。",
  ui_story_1014_10141501_182_dialog_content = "除了偶爾出現的發光現象以外，我的身體並沒有感受到任何不舒服。",
  ui_story_1014_10141501_183_dialog_content = "所以，就算不接受他們的幫助也沒關係，後遺症總能找到應對的辦法。",
  ui_story_1014_10141501_184_dialog_content = "我不希望PlayerName做出違背自己本心的決定。",
  ui_story_1014_10141501_185_option_content = "謝謝妳，薇絲",
  ui_story_1014_10141501_186_dialog_content = "但我不會放棄尋找解決和弦紐帶後遺症問題的希望。",
  ui_story_1014_10141501_187_option_content = "我不會放著妳不管",
  ui_story_1014_10141501_188_dialog_content = "從小時候起，臨空者號就一直在教導我，每一個夥伴都是珍貴的。",
  ui_story_1014_10141501_189_dialog_content = "所以，我不會讓任何一個夥伴置身於危險之中。",
  ui_story_1014_10141501_190_dialog_content = "......",
  ui_story_1014_10141501_191_dialog_content = "（糟了，氣氛變得好壓抑......）",
  ui_story_1014_10141501_192_dialog_content = "那個，要不要到處走走，消磨一下時間？",
  ui_story_1014_10141501_193_dialog_content = "反正一直在這裡站著也沒事做，他們又沒說什麼時候會需要我們。",
  ui_story_1014_10141501_194_dialog_content = "嗯，稍微在附近散散步，應該沒關係吧。",
  ui_story_1014_10141501_195_dialog_content = "（這座地下城真的好大啊......）",
  ui_story_1014_10141501_196_dialog_content = "（通道兩邊的房間似乎全都是實驗室。）",
  ui_story_1014_10141501_197_dialog_content = "（這些實驗室裡，究竟做過多少不為人知的實驗......）",
  ui_story_1014_10141501_198_dialog_content = "關於你的要求，我沒辦法同意。",
  ui_story_1014_10141501_199_dialog_content = "那個裝置還處於實驗階段，更何況，妳的實驗對象還處於不穩定的狀態。",
  ui_story_1014_10141501_200_dialog_content = "使用那種實驗對象進行實驗，有很大機率會弄壞那台珍貴的設備。",
  ui_story_1014_10141501_201_dialog_content = "而且那台不完整的設備也不一定能治好妳的實驗對象。",
  ui_story_1014_10141501_202_dialog_content = "這是我的實驗，沒有你插嘴的必要。",
  ui_story_1014_10141501_203_dialog_content = "你只需要把實驗儀器的使用權給我，然後閉嘴。",
  ui_story_1014_10141501_204_dialog_content = "遠處好像有什麼人在說話。",
  ui_story_1014_10141501_205_dialog_content = "這個聲音聽起來有些耳熟？",
  ui_story_1014_10141501_206_dialog_content = "我不同意。",
  ui_story_1014_10141501_207_dialog_content = "珍貴的設備不是給妳玩的玩具，更何況......",
  ui_story_1014_10141501_208_dialog_content = "現在的妳，已經沒有資格再向我提出這種要求了。",
  ui_story_1014_10141501_209_dialog_content = "資格......呵呵，又是這種東西。",
  ui_story_1014_10141501_210_dialog_content = "給予我資格的是你們，剝奪我資格的也是你們。",
  ui_story_1014_10141501_211_dialog_content = "當初我與你合作，取得了無數成果才獲得使用這裡一切設備的資格。",
  ui_story_1014_10141501_212_dialog_content = "而現在，你們只需要輕飄飄的一句話，就剝奪了我所有的付出。",
  ui_story_1014_10141501_213_dialog_content = "這是妳罪有應得。",
  ui_story_1014_10141501_214_dialog_content = "這聲音聽起來好像是......<color=#FFB400>吞羅</color>？！",
  ui_story_1014_10141501_215_dialog_content = "她挾持了什麼人嗎？",
  ui_story_1014_10141501_216_dialog_content = "我們快過去看看！",
  ui_story_1014_10141501_217_dialog_content = "科研人員很少有擅長戰鬥的，一旦被吞羅抓到，後果不堪設想！",
  ui_story_1014_10141501_218_dialog_content = "別動，把人放開！",
  ui_story_1014_10141501_219_dialog_content = "（真的是吞羅！為什麼我沒有感應到她的氣息？！）",
  ui_story_1014_10141501_220_dialog_content = "（等等，她並沒有挾持旁邊那個研究人員？）",
  ui_story_1014_10141501_221_dialog_content = "（那傢伙怎麼立刻轉身跑掉了？！）",
  ui_story_1014_10141501_222_dialog_content = "真意外啊，我需要的<color=#FFB400>實驗材料</color>竟然自己送上門來了。",
  ui_story_1014_10141501_223_dialog_content = "吞羅......妳為什麼會在這裡，還挾持了這裡的研究人員？",
  ui_story_1014_10141501_224_dialog_content = "我並沒有挾持任何人。",
  ui_story_1014_10141501_225_dialog_content = "我只不過是來要回過去寄放在這裡的一些權利而已。",
  ui_story_1014_10141501_226_dialog_content = "既然材料主動過來找我，那麼，我就不客氣了。",
  ui_story_1014_10141501_227_dialog_content = "等等，PlayerName快躲開！小心身後！",
  ui_story_1014_10141501_228_dialog_content = "什麼？",
  ui_story_1014_10141501_229_dialog_content = "<anim type=Shake><size=50>吼——！！！</size></anim>",
  ui_story_1014_10141501_230_dialog_content = "呃！！！",
  ui_story_1014_10141501_231_dialog_content = "我......好像暈過去了很久......",
  ui_story_1014_10141501_232_dialog_content = "我記得暈過去之前，撞見了吞羅在和誰說話，然後......",
  ui_story_1014_10141501_233_dialog_content = "薇絲......對了，薇絲！妳沒事吧？！",
  ui_story_1014_10141501_234_dialog_content = "旁邊的是......吞羅？！",
  ui_story_1014_10141501_235_dialog_content = "又見面了，空裔。",
  ui_story_1014_10141501_236_dialog_content = "如果不想她受傷的話，就按我說的做。",
  ui_story_1014_10141501_237_dialog_content = "......",
  ui_story_1014_10141501_238_dialog_content = "妳想做什麼？快放開她！",
  ui_story_1014_10141501_239_dialog_content = "放開她，我跟你走。",
  ui_story_1014_10141501_240_dialog_content = "你或許還沒搞清楚情況。",
  ui_story_1014_10141501_241_dialog_content = "身為實驗體的你，沒有資格提任何要求。",
  ui_story_1014_10141501_242_dialog_content = "更何況......",
  ui_story_1014_10141501_243_dialog_content = "對於實驗來說，你們兩個都是必需品。",
  ui_story_1015_10150101_1_dialog_content = "嘎——嘎——",
  ui_story_1015_10150101_2_dialog_content = "天快黑了吧。",
  ui_story_1015_10150101_3_dialog_content = "嗯，我們走快一點。",
  ui_story_1015_10150101_4_dialog_content = "<color=#e8d9bb>噠噠……噠噠……</color>",
  ui_story_1015_10150101_5_dialog_content = "聽好了，空裔。",
  ui_story_1015_10150101_6_dialog_content = "從現在開始，你必須遵照我的指令行事。",
  ui_story_1015_10150101_7_dialog_content = "不許求救、不許反抗，不許做任何多餘的動作。",
  ui_story_1015_10150101_8_dialog_content = "我將在接下來的時間裡進行一項研究，需要你從旁協助。",
  ui_story_1015_10150101_9_dialog_content = "妳又要往我身體裡植入什麼東西了嗎？",
  ui_story_1015_10150101_10_dialog_content = "哦，你還記得上次那件事啊。",
  ui_story_1015_10150101_11_dialog_content = "怎麼可能會忘……我可是差點就被妳轉變成「那種」東西！",
  ui_story_1015_10150101_12_dialog_content = "是的，我也覺得很可惜。",
  ui_story_1015_10150101_13_dialog_content = "雖然只是順手為之，但還是想看看如果你和舒默再次變成「同胞」……",
  ui_story_1015_10150101_14_dialog_content = "應該會非常有意思吧。",
  ui_story_1015_10150101_15_dialog_content = "「順手」？其他人呢，伊芙、多恩她們呢，也只是因為一句「順手」嗎？",
  ui_story_1015_10150101_16_dialog_content = "妳到底做了什麼？不，妳到底為什麼要——",
  ui_story_1015_10150101_17_dialog_content = "你吵得我耳朵都痛了。",
  ui_story_1015_10150101_18_dialog_content = "你們這些空裔……嗓門一個比一個大。不然我把你的聲帶切了吧。",
  ui_story_1015_10150101_19_dialog_content = "反正你也不需要靠聲音來交流，對吧？",
  ui_story_1015_10150101_20_dialog_content = "……",
  ui_story_1015_10150101_21_dialog_content = "該閉嘴的是妳……",
  ui_story_1015_10150101_22_dialog_content = "總之，嘴巴放乾淨點，空裔。",
  ui_story_1015_10150101_23_dialog_content = "乖乖跟著我，我叫你做什麼就做什麼。我可不是在跟你商量。",
  ui_story_1015_10150101_24_dialog_content = "只要實驗順利，你和薇絲會得到獲救的機會。",
  ui_story_1015_10150101_25_dialog_content = "……如果失敗呢？",
  ui_story_1015_10150101_26_dialog_content = "我會用你們兩個的生命為失敗買單。",
  ui_story_1015_10150101_27_dialog_content = "……",
  ui_story_1015_10150101_28_dialog_content = "哼，想用性命來威脅我們嗎？",
  ui_story_1015_10150101_29_dialog_content = "我還沒傻到會相信日蝕的承諾。",
  ui_story_1015_10150101_30_dialog_content = "就算實驗成功，妳一樣會殺死我們吧。",
  ui_story_1015_10150101_31_dialog_content = "殺死你們對我來說沒有任何好處。",
  ui_story_1015_10150101_32_dialog_content = "一個是僅存的空裔，一個是和弦紐帶的成功產物。",
  ui_story_1015_10150101_33_dialog_content = "你們兩個都是珍貴的實驗素材。如果有機會，我會將你們帶回我的研究室。",
  ui_story_1015_10150101_34_dialog_content = "但是現在，身處啟光的勢力範圍內，我並沒有辦法隨心所欲。",
  ui_story_1015_10150101_35_dialog_content = "所以我許諾讓你們有獲救的機會。",
  ui_story_1015_10150101_36_dialog_content = "這並非我大發慈悲，而是為了替未來的研究留下可能性。",
  ui_story_1015_10150101_37_dialog_content = "妳……",
  ui_story_1015_10150101_38_dialog_content = "研究好像是妳腦袋裡唯一會考慮的事情。",
  ui_story_1015_10150101_39_dialog_content = "不如說，我不理解其他瑣事有什麼可值得考慮的。",
  ui_story_1015_10150101_40_dialog_content = "講講接下來的實驗吧，你們稍微瞭解一下會比較方便。",
  ui_story_1015_10150101_41_dialog_content = "喂，我還沒同意要聽命於妳吧？",
  ui_story_1015_10150101_42_dialog_content = "你沒有其他選擇。",
  ui_story_1015_10150101_43_dialog_content = "……",
  ui_story_1015_10150101_44_dialog_content = "我在研究如何對光靈身體進行一次蛻變式的改造。",
  ui_story_1015_10150101_45_dialog_content = "不犧牲任何一方面的能力，而是徹底進化為一個更高級的物種。",
  ui_story_1015_10150101_46_dialog_content = "……好誇張的說法。",
  ui_story_1015_10150101_47_dialog_content = "你們使用過空裔遺留下的和弦紐帶，只要回想一下應該就能明白。",
  ui_story_1015_10150101_48_dialog_content = "它具備這樣的潛力。",
  ui_story_1015_10150101_49_dialog_content = "妳要在和弦紐帶上做文章？",
  ui_story_1015_10150101_50_dialog_content = "是的，我正是為此而來。",
  ui_story_1015_10150101_51_dialog_content = "你們應該知道，這座地下城裡藏著一台啟光祕密發掘的和弦紐帶吧？",
  ui_story_1015_10150101_52_dialog_content = "嗯，我們知道……",
  ui_story_1015_10150101_53_dialog_content = "它就是這次研究最重要的設備。",
  ui_story_1015_10150101_54_dialog_content = "我需要用它進行實驗，搜集資料後，找到和弦紐帶最適當的用法。",
  ui_story_1015_10150101_55_dialog_content = "如果有可能的話，我要創造出凌駕於光靈之上的生物。",
  ui_story_1015_10150101_56_dialog_content = "妳、妳要改造薇絲嗎？！",
  ui_story_1015_10150101_57_dialog_content = "我還沒那麼好心。薇絲只會作為測量實驗資料的樣本，不會參與最後的改造。",
  ui_story_1015_10150101_58_dialog_content = "能夠第一個得到如此殊榮的，是他。",
  ui_story_1015_10150101_59_dialog_content = "……",
  ui_story_1015_10150101_60_dialog_content = "喔哦……",
  ui_story_1015_10150101_61_dialog_content = "（吞羅救下他，就是為了進行這項研究嗎？）",
  ui_story_1015_10150101_62_dialog_content = "（還是說反過來，研究的真正目的其實是救他……）",
  ui_story_1015_10150101_63_dialog_content = "不過如果研究順利，你們也可以從中受益。",
  ui_story_1015_10150101_64_dialog_content = "我查看過啟光的資料，薇絲在受到和弦紐帶強化後，身體出現了一些副作用，對吧？",
  ui_story_1015_10150101_65_dialog_content = "妳連這個都知道？！",
  ui_story_1015_10150101_66_dialog_content = "關妳什麼事！",
  ui_story_1015_10150101_67_dialog_content = "只要研究完成，妳身上的副作用有機會透過和弦紐帶消除。",
  ui_story_1015_10150101_68_dialog_content = "對我們來說，這件事的結果是雙贏。",
  ui_story_1015_10150101_69_dialog_content = "……只靠這點好處就想收買我們？",
  ui_story_1015_10150101_70_dialog_content = "我想我用不著收買，幫助我是你們唯一的活路。",
  ui_story_1015_10150101_71_dialog_content = "剛才所說的好處，只是向你們陳述一個事實。",
  ui_story_1015_10150101_72_dialog_content = "好吧，好吧。確實如妳所說，我們沒得選。",
  ui_story_1015_10150101_73_dialog_content = "但是我不明白，我們能幫上妳什麼？",
  ui_story_1015_10150101_74_dialog_content = "幫我摒除一些研究路上的障礙。",
  ui_story_1015_10150101_75_dialog_content = "我需要實驗設備、實驗資料，這些東西都在啟光手裡。",
  ui_story_1015_10150101_76_dialog_content = "但是顯然，他們不準備讓一個外人使用。",
  ui_story_1015_10150101_77_dialog_content = "<color=#e8d9bb>邊境 黃昏鎮</color>",
  ui_story_1015_10150101_78_dialog_content = "快點，把受傷的騎士先抬進去！",
  ui_story_1015_10150101_79_dialog_content = "是！",
  ui_story_1015_10150101_80_dialog_content = "也幫幫啟光的傷患，他們人手更缺。",
  ui_story_1015_10150101_81_dialog_content = "李奧團長，謝謝你……",
  ui_story_1015_10150101_82_dialog_content = "都是在同一片戰場上的兄弟，不用謝。",
  ui_story_1015_10150101_83_dialog_content = "沒想到今天會遭遇這麼強大的敵人，隊伍損失慘重。",
  ui_story_1015_10150101_84_dialog_content = "是我的原因，我沒有盡好指揮官的職責……",
  ui_story_1015_10150101_85_dialog_content = "這不怪你。碰上了強敵，犧牲在所難免。",
  ui_story_1015_10150101_86_dialog_content = "而且我總覺得，今天的犧牲是一種必然。",
  ui_story_1015_10150101_87_dialog_content = "為什麼這麼說？",
  ui_story_1015_10150101_88_dialog_content = "黃昏鎮周圍的「風向」不對勁。",
  ui_story_1015_10150101_89_dialog_content = "就最近幾天，已經連續發生了好幾次針對鎮子的大規模襲擊。",
  ui_story_1015_10150101_90_dialog_content = "在我的印象裡，敵人從未像這樣活躍過。",
  ui_story_1015_10150101_91_dialog_content = "難道暗鬼要有什麼大動作了嗎？",
  ui_story_1015_10150101_92_dialog_content = "不知道，但我們得提前做好準備。",
  ui_story_1015_10150101_93_dialog_content = "西恩，聽說你們的參謀長回來了？",
  ui_story_1015_10150101_94_dialog_content = "對，剛回來沒多久。",
  ui_story_1015_10150101_95_dialog_content = "幫我叫他一下吧，就說我在老地方等他。",
  ui_story_1015_10150101_96_dialog_content = "歡迎光臨，請問幾位？",
  ui_story_1015_10150101_97_dialog_content = "我是來找人的。",
  ui_story_1015_10150101_98_dialog_content = "真是難得，黃昏鎮的大紅人竟然願意請我吃飯。",
  ui_story_1015_10150101_99_dialog_content = "坐下，吃肉。",
  ui_story_1015_10150101_100_dialog_content = "不用了，我吃過飯才來的。",
  ui_story_1015_10150101_101_dialog_content = "那太好了，把你那盤給我。",
  ui_story_1015_10150101_102_dialog_content = "我覺得它還是擺在我面前比較好，這畢竟是為了歡迎我回來請我的。",
  ui_story_1015_10150101_103_dialog_content = "今天叫我來，應該有比吃飯更重要的事吧？",
  ui_story_1015_10150101_104_dialog_content = "當然，只是吃飯不需要特意找人作伴。",
  ui_story_1015_10150101_105_dialog_content = "最近幾天啟光的傷亡報告你收到了吧？",
  ui_story_1015_10150101_106_dialog_content = "嗯，數據很異常。",
  ui_story_1015_10150101_107_dialog_content = "黃昏鎮的啟光駐軍從沒有過如此密集的傷亡紀錄。",
  ui_story_1015_10150101_108_dialog_content = "這些天的戰鬥強度，已經要到達我們所能承受的臨界點了。",
  ui_story_1015_10150101_109_dialog_content = "最可怕的還不是傷亡，而是我們從未真正打敗過敵人。",
  ui_story_1015_10150101_110_dialog_content = "每一次的戰鬥結果都是雙方在僵持後撤退。",
  ui_story_1015_10150101_111_dialog_content = "這說明我們根本沒有摸清對方有多少戰力。",
  ui_story_1015_10150101_112_dialog_content = "最壞的情況是，這幾次遭遇的全部是獨立的暗鬼群。",
  ui_story_1015_10150101_113_dialog_content = "如果牠們集結起來圍攻黃昏鎮，後果不堪設想。",
  ui_story_1015_10150101_114_dialog_content = "沒錯，跟聰明人說話就是舒服。",
  ui_story_1015_10150101_115_dialog_content = "你想好應對的策略了嗎？",
  ui_story_1015_10150101_116_dialog_content = "我已經分出兵力去暗面進行偵察了，希望能摸清敵人的動向。",
  ui_story_1015_10150101_117_dialog_content = "但是依我看來，現在的兵力是不足以守住黃昏鎮的。",
  ui_story_1015_10150101_118_dialog_content = "所以我準備傳訊求援。",
  ui_story_1015_10150101_119_dialog_content = "嗯……對，這是最妥當的做法。",
  ui_story_1015_10150101_120_dialog_content = "跟我說這件事，是想爭取啟光的援助對吧。",
  ui_story_1015_10150101_121_dialog_content = "當然，我們還不知道要面對多少敵人。",
  ui_story_1015_10150101_122_dialog_content = "在這裡談白夜城與啟光之間的分歧就太狹隘了吧？",
  ui_story_1015_10150101_123_dialog_content = "明白了，我回去就傳訊。",
  ui_story_1015_10150101_124_dialog_content = "嗯，越快越好。現在我們最缺的就是時間。",
  ui_story_1015_10150101_125_dialog_content = "我有預感，我們設想的情況，恐怕用不了多久就會成真。",
  ui_story_1015_10150101_126_dialog_content = "<color=#e8d9bb>白夜城 白夜朝堂</color>",
  ui_story_1015_10150101_127_dialog_content = "呼……",
  ui_story_1015_10150101_128_dialog_content = "小卡蓮，做完報告了？",
  ui_story_1015_10150101_129_dialog_content = "嗯。",
  ui_story_1015_10150101_130_dialog_content = "妳看起來有點疲憊。",
  ui_story_1015_10150101_131_dialog_content = "和他說話就是一件累人的事情。",
  ui_story_1015_10150101_132_dialog_content = "我覺得我就是在浪費時間，他想聽的和我想說的幾乎毫不相干。",
  ui_story_1015_10150101_133_dialog_content = "妳是指「黃昏鎮」的事情？",
  ui_story_1015_10150101_134_dialog_content = "是的，我不明白他為什麼要不停地詢問資源分配和組織架構的問題。",
  ui_story_1015_10150101_135_dialog_content = "明明我報告的那些才是……",
  ui_story_1015_10150101_136_dialog_content = "算了，不要在這裡說。",
  ui_story_1015_10150101_137_dialog_content = "嗯，不說了，我們去喝點茶吧。",
  ui_story_1015_10150101_138_dialog_content = "接下來這幾天有什麼安排嗎？",
  ui_story_1015_10150101_139_dialog_content = "沒什麼事，城主讓我留在白夜城待命。",
  ui_story_1015_10150101_140_dialog_content = "待命啊。哦對，因為「<color=#FFB400>聯合軍演</color>」快到了對吧？",
  ui_story_1015_10150101_141_dialog_content = "嗯，應該是。",
  ui_story_1015_10150101_142_dialog_content = "要好好準備喔，妳可是軍演上的明星呢。",
  ui_story_1015_10150101_143_dialog_content = "但……我現在有點靜不下心來。",
  ui_story_1015_10150101_144_dialog_content = "怎麼了呢？",
  ui_story_1015_10150101_145_dialog_content = "PlayerName那邊一直沒有傳來聯絡。",
  ui_story_1015_10150101_146_dialog_content = "不知道他和薇絲怎麼樣了……",
  ui_story_1015_10150101_147_dialog_content = "哦，是卡蓮啊！好久不見！",
  ui_story_1015_10150101_148_dialog_content = "好久不見，貢露，很抱歉突然跟妳聯絡，希望沒有打擾到妳。",
  ui_story_1015_10150101_149_dialog_content = "沒有沒有，妳來得正是時候。",
  ui_story_1015_10150101_150_dialog_content = "我跟妳說，臨空者號的工作剛有了突破性的進展。",
  ui_story_1015_10150101_151_dialog_content = "妳聽著啊。",
  ui_story_1015_10150101_152_dialog_content = "臨空者號，啟動！",
  ui_story_1015_10150101_153_dialog_content = "臨空者號啟動完畢。",
  ui_story_1015_10150101_154_dialog_content = "聽到了嗎！！！",
  ui_story_1015_10150101_155_dialog_content = "聽到了，但是……他之前也可以正常啟動不是嗎？",
  ui_story_1015_10150101_156_dialog_content = "我知道我知道，可以使用但沒有意識對吧？",
  ui_story_1015_10150101_157_dialog_content = "嗯。",
  ui_story_1015_10150101_158_dialog_content = "放心吧，他的意識模組已經基本恢復了。",
  ui_story_1015_10150101_159_dialog_content = "只不過作為光靈的我們無法與他直接溝通。",
  ui_story_1015_10150101_160_dialog_content = "等PlayerName過來，就可以跟臨空者號說話了！",
  ui_story_1015_10150101_161_dialog_content = "哦對！其實我就是想問一下PlayerName……還有薇絲的事情！",
  ui_story_1015_10150101_162_dialog_content = "他們後來怎麼樣了？",
  ui_story_1015_10150101_163_dialog_content = "從我返回白夜城之後，他們兩個一直沒有跟我聯絡。",
  ui_story_1015_10150101_164_dialog_content = "唔，我看到過他們的報告。",
  ui_story_1015_10150101_165_dialog_content = "說是進入祕密的地下城進行調養了，可能會暫時關閉通訊。",
  ui_story_1015_10150101_166_dialog_content = "等到調養結束，應該就會跟妳聯絡了吧。",
  ui_story_1015_10150101_167_dialog_content = "祕密的地下城？",
  ui_story_1015_10150101_168_dialog_content = "嗯。放心吧，那裡保密等級還滿高的。",
  ui_story_1015_10150101_169_dialog_content = "我記得名字是叫……",
  ui_story_1015_10150101_170_dialog_content = "哦對，「<color=#FFB400>X號研究院</color>」。",
  ui_story_1015_10150101_171_dialog_content = "<color=#e8d9bb>迦南城 火車站</color>",
  ui_story_1015_10150101_172_dialog_content = "讓一讓讓一讓，後面什麼都看不到了。",
  ui_story_1015_10150101_173_dialog_content = "咦，那邊是不是掛歪了？",
  ui_story_1015_10150101_174_dialog_content = "就是說啊，把我們啟光的旗幟掛高一點！",
  ui_story_1015_10150101_175_dialog_content = "怎麼聚集了這麼多人？他們在看什麼呢？",
  ui_story_1015_10150101_176_dialog_content = "你不知道嗎？「聯合軍演」快開始了，前面正在懸掛各個勢力的旗幟。",
  ui_story_1015_10150101_177_dialog_content = "哦！又到了聯合軍演的時間了啊。",
  ui_story_1015_10150101_178_dialog_content = "今年還滿有看頭的，預約採訪的報社天天在接待處門口排隊。",
  ui_story_1015_10150101_179_dialog_content = "哦？今年的軍演有什麼特殊的嗎？",
  ui_story_1015_10150101_180_dialog_content = "當然。這可是闊別十幾年之後，空裔再次登上軍演舞台啊。",
  ui_story_1015_10150101_181_dialog_content = "<color=#e8d9bb>迦南城 情報處</color>",
  ui_story_1015_10150101_182_dialog_content = "<color=#e8d9bb>叩、叩、叩……</color>",
  ui_story_1015_10150101_183_dialog_content = "進來。",
  ui_story_1015_10150101_184_dialog_content = "鶯歌中校，有一封發給您的加急電報。",
  ui_story_1015_10150101_185_dialog_content = "請您盡快查看一下。",
  ui_story_1015_10150101_186_dialog_content = "加急電報？",
  ui_story_1015_10150101_187_dialog_content = "好的，我知道了，放在桌上吧。",
  ui_story_1015_10150101_188_dialog_content = "是！",
  ui_story_1015_10150101_189_dialog_content = "是誰的緊急命令……",
  ui_story_1015_10150101_190_dialog_content = "嗯？尤利西斯大人？",
  ui_story_1015_10150201_1_dialog_content = "快點跟上，別磨磨蹭蹭的。",
  ui_story_1015_10150201_2_dialog_content = "你們最好走得比我的刀快。",
  ui_story_1015_10150201_3_dialog_content = "……知道了。",
  ui_story_1015_10150201_4_dialog_content = "但我還是要說，有必要每天都起這麼早嗎？",
  ui_story_1015_10150201_5_dialog_content = "我已經很多天都沒睡過好覺了。",
  ui_story_1015_10150201_6_dialog_content = "是十幾年如一日的慵懶生活把你慣壞了。",
  ui_story_1015_10150201_7_dialog_content = "我們的作息並不苛刻。你也可以看到，周圍的衛兵早就醒了。",
  ui_story_1015_10150201_8_dialog_content = "唉……這樣的日子還要過多久啊。",
  ui_story_1015_10150201_9_dialog_content = "關於這個，我們確實有一個明確的期限。",
  ui_story_1015_10150201_10_dialog_content = "你們應該也聽說過，啟光正在籌備一場名為「聯合軍演」的活動。你們兩個都會受到邀請。",
  ui_story_1015_10150201_11_dialog_content = "屆時，如果你們沒有到場，啟光一定會派人來找麻煩。",
  ui_story_1015_10150201_12_dialog_content = "所以，那就是我們的最後期限。",
  ui_story_1015_10150201_13_dialog_content = "（對，聯合軍演！我們可以靠它得救嗎？）",
  ui_story_1015_10150201_14_dialog_content = "對於你們來說，好消息是這場劫持不會持續太久。",
  ui_story_1015_10150201_15_dialog_content = "壞消息是，如果實驗沒能在期限內順利完成，你們所剩的生命會比想像中更短。",
  ui_story_1015_10150201_16_dialog_content = "……",
  ui_story_1015_10150201_17_dialog_content = "走快一點，為了讓你們自己活下去。",
  ui_story_1015_10150201_18_dialog_content = "唉唷別推我了，我認識路！",
  ui_story_1015_10150201_19_dialog_content = "總之就是去實驗室嘛，已經去過那麼多次了。",
  ui_story_1015_10150201_20_dialog_content = "我不想在實驗以外的事情上浪費太多時間。",
  ui_story_1015_10150201_21_dialog_content = "集中注意力，別暴露我們的行蹤。",
  ui_story_1015_10150201_22_dialog_content = "再像之前那樣出聲求救的話，我保證會割掉你們的舌頭。",
  ui_story_1015_10150201_23_dialog_content = "知道了，妳看這次我們就滿配合的啊。",
  ui_story_1015_10150201_24_dialog_content = "衛兵的巡邏路徑和出勤時間都是固定的，不會有什麼意外……",
  ui_story_1015_10150201_25_dialog_content = "……",
  ui_story_1015_10150201_26_dialog_content = "<size=50>嗚哇！</size>這是……",
  ui_story_1015_10150201_27_dialog_content = "<size=50><anim type=Shake>吼——</anim></size>",
  ui_story_1015_10150201_28_dialog_content = "吞羅，妳養的狗又跟上來了。",
  ui_story_1015_10150201_29_dialog_content = "我再說一次，玉子牠不是狗。",
  ui_story_1015_10150201_30_dialog_content = "好吧，總之是妳的寵物。",
  ui_story_1015_10150201_31_dialog_content = "這麼大一隻，跟過來沒問題嗎？",
  ui_story_1015_10150201_32_dialog_content = "今天的研究需要幫手，所以我叫牠來了。",
  ui_story_1015_10150201_33_dialog_content = "研究啊……",
  ui_story_1015_10150201_34_dialog_content = "說起來，牠會變成這樣也是因為妳的研究吧。",
  ui_story_1015_10150201_35_dialog_content = "……",
  ui_story_1015_10150201_36_dialog_content = "玉子原來是什麼動物？",
  ui_story_1015_10150201_37_dialog_content = "是龍貓。",
  ui_story_1015_10150201_38_dialog_content = "龍貓？！",
  ui_story_1015_10150201_39_dialog_content = "那種小巧可愛的動物竟然會變成這樣……",
  ui_story_1015_10150201_40_dialog_content = "會做出「小巧可愛」這樣的形容，不過是你以食物鏈頂端的視角展現出的傲慢。",
  ui_story_1015_10150201_41_dialog_content = "嗯？",
  ui_story_1015_10150201_42_dialog_content = "因為其他生物的死活可以由你決定，所以更能討好你的特點便成為了牠的優勢。",
  ui_story_1015_10150201_43_dialog_content = "只看在自然界中的情況，龍貓的體型無疑限制了牠們去佔據更高生態位的能力。",
  ui_story_1015_10150201_44_dialog_content = "而現在的玉子，已經打破了這種限制。",
  ui_story_1015_10150201_45_dialog_content = "打破限制？",
  ui_story_1015_10150201_46_dialog_content = "簡單來說，牠有了更豐富的捕食選擇。",
  ui_story_1015_10150201_47_dialog_content = "正好，我們該與守門的士兵交戰了。",
  ui_story_1015_10150201_48_dialog_content = "喂！妳不會要拿士兵去餵牠吧！",
  ui_story_1015_10150201_49_dialog_content = "我們說好的啊，幫妳打架可以，但是絕對不能傷害士兵的性命！",
  ui_story_1015_10150201_50_dialog_content = "你不關心一個族群的走向，卻在乎眼前一兩條性命的得失。",
  ui_story_1015_10150201_51_dialog_content = "好吧，我沒興趣去糾正你的短淺。",
  ui_story_1015_10150201_52_dialog_content = "一兩條性命不重要嗎？他們……",
  ui_story_1015_10150201_53_dialog_content = "還是像之前一樣，空裔為我提供戰鬥資訊。",
  ui_story_1015_10150201_54_dialog_content = "實驗室增強了防禦，這次的戰鬥會比之前困難一些。",
  ui_story_1015_10150201_55_dialog_content = "我能提供不錯的戰力喔，要不要考慮把我放開？",
  ui_story_1015_10150201_56_dialog_content = "至於妳，待在原地，別做多餘的事情，不然妳會成為玉子的第一口早飯。",
  ui_story_1015_10150201_57_dialog_content = "哼。",
  ui_story_1015_10150201_58_dialog_content = "空裔，緊跟在我背後。",
  ui_story_1015_10150201_59_dialog_content = "我們上。",
  ui_story_1015_10150302_1_dialog_content = "<color=#e8d9bb>砰——</color>",
  ui_story_1015_10150302_2_dialog_content = "別別別！別太用力了！",
  ui_story_1015_10150302_3_dialog_content = "人家骨折了怎麼辦！",
  ui_story_1015_10150302_4_dialog_content = "結束了，把這些昏迷的士兵搬到旁邊去。",
  ui_story_1015_10150302_5_dialog_content = "至少在實驗期間，不能讓巡邏兵發現。",
  ui_story_1015_10150302_6_dialog_content = "<size=45><anim type=Shake>嘎——</anim></size>",
  ui_story_1015_10150302_7_dialog_content = "拖的時候輕一點啊！",
  ui_story_1015_10150302_8_dialog_content = "唉唷，還是我來吧。",
  ui_story_1015_10150302_9_dialog_content = "快點，別浪費時間。",
  ui_story_1015_10150302_10_dialog_content = "知道知道，又不是第一次做了。",
  ui_story_1015_10150302_11_dialog_content = "對不起啊，幫吞羅打了你們。",
  ui_story_1015_10150302_12_dialog_content = "嗯？地上還掉了不少東西。",
  ui_story_1015_10150302_13_dialog_content = "這些都幫你們放回口袋裡吧。",
  ui_story_1015_10150302_14_dialog_content = "小刀……鑰匙……磁卡……",
  ui_story_1015_10150302_15_dialog_content = "這個是什麼？針線盒？",
  ui_story_1015_10150302_16_dialog_content = "好像可以打開。",
  ui_story_1015_10150302_17_dialog_content = "<size=45>！！！</size>",
  ui_story_1015_10150302_18_dialog_content = "喔，原來是個<color=#FFB400>打火機</color>……",
  ui_story_1015_10150302_19_dialog_content = "<size=50><anim type=Shake>吼！！！</anim></size>",
  ui_story_1015_10150302_20_dialog_content = "嗚哇！玉子你幹什麼！",
  ui_story_1015_10150302_21_dialog_content = "<size=45><anim type=Shake>嘎——</anim></size>",
  ui_story_1015_10150302_22_dialog_content = "<color=#e8d9bb>砰。</color>",
  ui_story_1015_10150302_23_dialog_content = "牠、牠把打火機踩碎了？",
  ui_story_1015_10150302_24_dialog_content = "一個打火機而已，怎麼反應這麼大。",
  ui_story_1015_10150302_25_dialog_content = "……",
  ui_story_1015_10150302_26_dialog_content = "實驗室附近的環境非常敏感，不能出現一丁點火星。",
  ui_story_1015_10150302_27_dialog_content = "剛才的事情，再也別做了。",
  ui_story_1015_10150302_28_dialog_content = "哦……",
  ui_story_1015_10150302_29_dialog_content = "（如果真是這樣，那為什麼實驗的衛兵還會帶著打火機呢？）",
  ui_story_1015_10150302_30_dialog_content = "走了，別耽誤時間。",
  ui_story_1015_10150302_31_dialog_content = "<color=#e8d9bb>嗡——</color>",
  ui_story_1015_10150302_32_dialog_content = "門開了，進去。",
  ui_story_1015_10150302_33_dialog_content = "你們去前面等我。",
  ui_story_1015_10150302_34_dialog_content = "妳在幹什麼？",
  ui_story_1015_10150302_35_dialog_content = "妳這是在……修改門鎖的祕鑰？",
  ui_story_1015_10150302_36_dialog_content = "……嘖。",
  ui_story_1015_10150302_37_dialog_content = "（應該是為了防止衛兵追上來、用門鎖拖延時間吧。）",
  ui_story_1015_10150302_38_dialog_content = "唉……照理來說這些門是用來攔住我們的吧，怎麼反過來攔住衛兵了。",
  ui_story_1015_10150302_39_dialog_content = "機械沒有意識，它只會幫助懂得使用的人。",
  ui_story_1015_10150302_40_dialog_content = "妳好像很瞭解這裡。",
  ui_story_1015_10150302_41_dialog_content = "嗯？",
  ui_story_1015_10150302_42_dialog_content = "能越過研究院外圍的警戒圈，熟知內部地形，甚至可以操控大部分的門扉和機械。",
  ui_story_1015_10150302_43_dialog_content = "啟光對研究場所的保護在妳面前就像是個笑話。",
  ui_story_1015_10150302_44_dialog_content = "妳說的那些，都是我實施計畫的必要條件。",
  ui_story_1015_10150302_45_dialog_content = "如果做不到，我就不會在這裡出現。",
  ui_story_1015_10150302_46_dialog_content = "但是為什麼？因為妳曾經是啟光的研究員嗎？",
  ui_story_1015_10150302_47_dialog_content = "因為這座研究院是我一手建造的。",
  ui_story_1015_10150302_48_dialog_content = "什麼？！",
  ui_story_1015_10150302_49_dialog_content = "是妳建造的……",
  ui_story_1015_10150302_50_dialog_content = "當時它還叫「X號地下城」。",
  ui_story_1015_10150302_51_dialog_content = "好了，祕鑰重設完畢。",
  ui_story_1015_10150302_52_dialog_content = "今天的實驗該開始了。",
  ui_story_1015_10150302_53_dialog_content = "哇，真的是和弦紐帶！",
  ui_story_1015_10150302_54_dialog_content = "和回歸塔那台雖然有所差異，但看得出是同樣的東西。",
  ui_story_1015_10150302_55_dialog_content = "啟光對它的祕密研究已經持續了很多年，保密等級很高。",
  ui_story_1015_10150302_56_dialog_content = "能接觸到它的只有委員會和科技首席議會的老古董。",
  ui_story_1015_10150302_57_dialog_content = "不知道啟光對它的研究到達什麼地步了……",
  ui_story_1015_10150302_58_dialog_content = "之前妳從來不讓我們進入這裡，為什麼今天換了主意？",
  ui_story_1015_10150302_59_dialog_content = "因為研究進展到了新的階段。",
  ui_story_1015_10150302_60_dialog_content = "啟光為了尋找這台儀器的使用方法投入了幾十年，我沒有那麼長的時間。",
  ui_story_1015_10150302_61_dialog_content = "所以，我要用實驗來學會它的用法。",
  ui_story_1015_10150302_62_dialog_content = "什麼意思？",
  ui_story_1015_10150302_63_dialog_content = "我要啟動一次和弦紐帶，在運行過程中弄懂它的原理。",
  ui_story_1015_10150302_64_dialog_content = "知道我為什麼要帶你們進來了嗎？",
  ui_story_1015_10150302_65_dialog_content = "啟動和弦紐帶？妳、妳要對誰使用它？！",
  ui_story_1015_10150302_66_dialog_content = "當然是早就準備好的「實驗品」。",
  ui_story_1015_10150302_67_dialog_content = "妳……！",
  ui_story_1015_10150302_68_dialog_content = "不行！別碰薇絲！！！",
  ui_story_1015_10150302_69_dialog_content = "玉子。",
  ui_story_1015_10150302_70_dialog_content = "<size=50><anim type=Shake>吼——！！！</anim></size>",
  ui_story_1015_10150302_71_dialog_content = "嗚哇……好重……",
  ui_story_1015_10150302_72_dialog_content = "妳、妳放開薇絲！使用方法都沒弄清楚就不要亂來啊！",
  ui_story_1015_10150302_73_dialog_content = "「實驗品」的作用就是幫我弄清楚使用方法。",
  ui_story_1015_10150302_74_dialog_content = "科學研究即是向黑暗中伸出手，手被刺痛了、劃傷了，才能勾勒出世界的形狀。",
  ui_story_1015_10150302_75_dialog_content = "沒有嘗試，研究就永遠沒法推進。",
  ui_story_1015_10150302_76_dialog_content = "說得冠冕堂皇，怎麼不用自己去試啊！",
  ui_story_1015_10150302_77_dialog_content = "用自己試只能失敗一次，用「實驗品」則可以失敗無數次。",
  ui_story_1015_10150302_78_dialog_content = "研究不是賭博，我當然需要更多機會。",
  ui_story_1015_10150302_79_dialog_content = "<size=45>妳、這、傢、伙……</size>",
  ui_story_1015_10150302_80_dialog_content = "薇絲小姐，希望妳準備好了。",
  ui_story_1015_10150302_81_dialog_content = "就像妳第一次使用和弦紐帶時那樣。",
  ui_story_1015_10150302_82_dialog_content = "妳放開我！",
  ui_story_1015_10150302_83_dialog_content = "和弦紐帶試運行，實驗艙、實驗體準備完畢。",
  ui_story_1015_10150302_84_dialog_content = "實驗開始。",
  ui_story_1015_10150302_85_dialog_content = "尤利西斯長官，這樣下去不是辦法啊。",
  ui_story_1015_10150302_86_dialog_content = "我們已經讓衛兵增加人力進行搜查和圍捕了，但還是抓不住入侵者。",
  ui_story_1015_10150302_87_dialog_content = "現在弄得人心惶惶，許多研究員都不敢前往實驗室了。",
  ui_story_1015_10150302_88_dialog_content = "搞清楚對方的身分了嗎？",
  ui_story_1015_10150302_89_dialog_content = "搞清楚了，和您之前的猜測一樣，就是吞羅。",
  ui_story_1015_10150302_90_dialog_content = "真不知道她是怎麼闖進來的。不僅能躲過搜查，還能穿過所有防護措施。",
  ui_story_1015_10150302_91_dialog_content = "對了，有士兵似乎看到了失聯多日的那個空裔，難道他其實是吞羅的內應？",
  ui_story_1015_10150302_92_dialog_content = "是她的話，根本不需要內應。",
  ui_story_1015_10150302_93_dialog_content = "啊？",
  ui_story_1015_10150302_94_dialog_content = "吞羅比任何人都要瞭解這裡，因為她才是「X號研究院」的建立者。",
  ui_story_1015_10150302_95_dialog_content = "是她建造的？我還以為是您……",
  ui_story_1015_10150302_96_dialog_content = "十一年前，吞羅還在啟光，是那時最有潛力的研究人員。",
  ui_story_1015_10150302_97_dialog_content = "她向我發出申請，祕密接管了一座沒有名字的廢棄地下城。",
  ui_story_1015_10150302_98_dialog_content = "她將其命名為「X號地下城」，也就是現在這座研究院的前身。",
  ui_story_1015_10150302_99_dialog_content = "原來如此。",
  ui_story_1015_10150302_100_dialog_content = "後來吞羅從啟光叛離，研究院才演變成了現在的樣子？",
  ui_story_1015_10150302_101_dialog_content = "差不多吧。",
  ui_story_1015_10150302_102_dialog_content = "她很有天賦，但天賦是一種可怕的東西。",
  ui_story_1015_10150302_103_dialog_content = "那讓她超脫於常人，不斷去進行激進而危險的嘗試。",
  ui_story_1015_10150302_104_dialog_content = "在她的領導下，「X號地下城」掌握了啟光聯邦最先進的生物科技。",
  ui_story_1015_10150302_105_dialog_content = "但同時，也醞釀著一場不斷膨脹的危機。",
  ui_story_1015_10150302_106_dialog_content = "無論是啟光還是她自己都無力承受。",
  ui_story_1015_10150302_107_dialog_content = "我好像聽說過，她被除名是因為研究中發生了巨大的意外……",
  ui_story_1015_10150302_108_dialog_content = "對，一場大火燒毀了「X號地下城」。",
  ui_story_1015_10150302_109_dialog_content = "但意外只是導火索，作用無非是吸引高層去探究吞羅的祕密。",
  ui_story_1015_10150302_110_dialog_content = "真正讓啟光無法容忍的，是她那項研究中不合人倫、不可控制的本質。",
  ui_story_1015_10150302_111_dialog_content = "不掐滅源頭，火只會越燒越旺。",
  ui_story_1015_10150302_112_dialog_content = "確實。要是意外發生在迦南城的話，後果不堪設想。",
  ui_story_1015_10150302_113_dialog_content = "不過這麼說來……發生過重大意外的「X號地下城」為什麼沒有被廢棄呢？",
  ui_story_1015_10150302_114_dialog_content = "可以作為研究場所的地下城還有很多吧。",
  ui_story_1015_10150302_115_dialog_content = "唉。所以我說，天賦是一種可怕的東西。",
  ui_story_1015_10150302_116_dialog_content = "無論那些實驗多麼違背倫理，造成了怎樣的危害，都無法掩蓋她卓越的研究成績。",
  ui_story_1015_10150302_117_dialog_content = "說到底，我也跟她是同一類的人。",
  ui_story_1015_10150302_118_dialog_content = "我捨不得她留下的東西。",
  ui_story_1015_10150302_119_dialog_content = "這樣啊……",
  ui_story_1015_10150302_120_dialog_content = "事情結束後，我重建了受損的地下城，成為了現在的「X號研究院」。",
  ui_story_1015_10150302_121_dialog_content = "借助吞羅留下的儀器和成果，啟光在生物領域的研究得以更進一步。",
  ui_story_1015_10150302_122_dialog_content = "這麼看來，她還算為啟光做了件好事。",
  ui_story_1015_10150302_123_dialog_content = "凡事都有代價，現在到了我們償還的時候。",
  ui_story_1015_10150302_124_dialog_content = "「X號研究院」雖然做了整體翻新，但其中作為根基和原理性的部分無法改變。",
  ui_story_1015_10150302_125_dialog_content = "在吞羅眼裡，我們不過是幫音樂盒換了發條，蒙了層嶄新的布。",
  ui_story_1015_10150302_126_dialog_content = "她只要伸手進去撥動簧片，就能彈奏出自己的曲子。",
  ui_story_1015_10150401_1_dialog_content = "這麼說來……X號研究院的處境很危險啊。",
  ui_story_1015_10150401_2_dialog_content = "我們雖然擁有兵力上的優勢，但是戰鬥力平鋪成了一個面。",
  ui_story_1015_10150401_3_dialog_content = "吞羅熟悉地形，絕對不會給我們集中兵力圍剿她的機會。",
  ui_story_1015_10150401_4_dialog_content = "她幾乎可以在這裡為所欲為……",
  ui_story_1015_10150401_5_dialog_content = "你說得對，靠衛兵奈何不了她。",
  ui_story_1015_10150401_6_dialog_content = "沒有單兵作戰能力可以與之抗衡的人物在，多少衛兵都沒用。",
  ui_story_1015_10150401_7_dialog_content = "不能再這樣下去……",
  ui_story_1015_10150401_8_dialog_content = "長官，我們向迦南城求援吧。",
  ui_story_1015_10150401_9_dialog_content = "只要再得到一些支援，一定可以……",
  ui_story_1015_10150401_10_dialog_content = "不行。",
  ui_story_1015_10150401_11_dialog_content = "長官？為什麼？",
  ui_story_1015_10150401_12_dialog_content = "這不是那麼簡單的事情。",
  ui_story_1015_10150401_13_dialog_content = "如果求援可以解決問題，我早就向迦南城傳訊了，何必你來提醒。",
  ui_story_1015_10150401_14_dialog_content = "我不明白……",
  ui_story_1015_10150401_15_dialog_content = "這裡是機密的研究院，所有事情都要保密。",
  ui_story_1015_10150401_16_dialog_content = "讓軍隊知情並不是件好事，別忘了吞羅是怎麼被除名的。",
  ui_story_1015_10150401_17_dialog_content = "……是。",
  ui_story_1015_10150401_18_dialog_content = "我沒有想那麼多，只是覺得眼前的問題更重要。",
  ui_story_1015_10150401_19_dialog_content = "吞羅是個研究者，她潛入進來是為了做實驗。",
  ui_story_1015_10150401_20_dialog_content = "說到底，這不過是科學家之間的衝突。",
  ui_story_1015_10150401_21_dialog_content = "一旦和軍方扯上關係，所有事情就都變味了。",
  ui_story_1015_10150401_22_dialog_content = "是，我明白了。",
  ui_story_1015_10150401_23_dialog_content = "真的明白了？",
  ui_story_1015_10150401_24_dialog_content = "……",
  ui_story_1015_10150401_25_dialog_content = "呵呵，你畢竟是個軍人，只要執行命令就夠了，沒有必要理解我的想法。",
  ui_story_1015_10150401_26_dialog_content = "你就把這一切當成是一場實驗吧。",
  ui_story_1015_10150401_27_dialog_content = "實驗的內容必須對外保密，這是寫在章程裡的。明白？",
  ui_story_1015_10150401_28_dialog_content = "是！",
  ui_story_1015_10150401_29_dialog_content = "好了好了，接下來說點你能聽懂的吧。",
  ui_story_1015_10150401_30_dialog_content = "不去迦南城搬救兵，並不說明我要坐以待斃。",
  ui_story_1015_10150401_31_dialog_content = "要對付吞羅，我也有自己的辦法。",
  ui_story_1015_10150401_32_dialog_content = "您的辦法？那是……",
  ui_story_1015_10150401_33_dialog_content = "<color=#e8d9bb>叩、叩、叩……</color>",
  ui_story_1015_10150401_34_dialog_content = "進來。",
  ui_story_1015_10150401_35_dialog_content = "啟光情報官中校鶯歌，向您報告！",
  ui_story_1015_10150401_36_dialog_content = "<color=#e8d9bb>嗶——嗶——</color>",
  ui_story_1015_10150401_37_dialog_content = "原來它是這樣運行的……",
  ui_story_1015_10150401_38_dialog_content = "對，只改變身體結構沒有用處。",
  ui_story_1015_10150401_39_dialog_content = "光能的軌跡不在這裡，它藏在更深的地方……",
  ui_story_1015_10150401_40_dialog_content = "（薇絲！妳現在感覺怎麼樣？）",
  ui_story_1015_10150401_41_dialog_content = "（有哪裡不舒服嗎？）",
  ui_story_1015_10150401_42_dialog_content = "（現在還沒有，只是感覺到有一股力量在幫我梳理體內的光能。）",
  ui_story_1015_10150401_43_dialog_content = "（是嗎，那暫時還好。希望不要出現意外……）",
  ui_story_1015_10150401_44_dialog_content = "（不用那麼擔心啦，我畢竟經歷過一次和弦紐帶。）",
  ui_story_1015_10150401_45_dialog_content = "（但是……）",
  ui_story_1015_10150401_46_dialog_content = "（你聽我說，不覺得現在是一個機會嗎？）",
  ui_story_1015_10150401_47_dialog_content = "（機會？）",
  ui_story_1015_10150401_48_dialog_content = "（和弦紐帶能強化光靈的力量，對吧？）",
  ui_story_1015_10150401_49_dialog_content = "（我也許可以借助這次強化，掙脫身上的繩索。）",
  ui_story_1015_10150401_50_dialog_content = "（掙脫繩索！真的能做到嗎？）",
  ui_story_1015_10150401_51_dialog_content = "（應該可以，說不定現在就能做到。）",
  ui_story_1015_10150401_52_dialog_content = "（不過麻煩的是掙脫後要如何與吞羅還有玉子戰鬥。）",
  ui_story_1015_10150401_53_dialog_content = "（我還需要更多力量，必須寄希望於和弦紐帶的強化。）",
  ui_story_1015_10150401_54_dialog_content = "（唔……吞羅的注意力全集中在資料上，這確實是個不錯的反擊機會。）",
  ui_story_1015_10150401_55_dialog_content = "（對吧，讓那傢伙嚐嚐自己的實驗結果是什麼滋味！）",
  ui_story_1015_10150401_56_dialog_content = "（等一下我們兩個要配合好行動，機會只有一次。）",
  ui_story_1015_10150401_57_dialog_content = "（最好趁吞羅還沒反應過來就把她制服，拖入持久戰對我們不利。）",
  ui_story_1015_10150401_58_dialog_content = "（明白，我來尋找那個一擊制敵的時機。）",
  ui_story_1015_10150401_59_dialog_content = "（嗯！拜託你了！）",
  ui_story_1015_10150401_60_dialog_content = "吞羅，實驗還有多久啊？",
  ui_story_1015_10150401_61_dialog_content = "玉子的尾巴好重，壓得我喘不過氣。",
  ui_story_1015_10150401_62_dialog_content = "快了，別出聲。",
  ui_story_1015_10150401_63_dialog_content = "快了是多久啊，有沒有準確的時間？",
  ui_story_1015_10150401_64_dialog_content = "已經到最後階段了。",
  ui_story_1015_10150401_65_dialog_content = "<color=#e8d9bb>嗶——</color>",
  ui_story_1015_10150401_66_dialog_content = "（PlayerName！我感覺到光能的流動開始加快了！）",
  ui_story_1015_10150401_67_dialog_content = "（那妳做好準備，等到強化完成的一瞬間我們就出手！）",
  ui_story_1015_10150401_68_dialog_content = "（嗯！）",
  ui_story_1015_10150401_69_dialog_content = "（掙脫的一瞬間先對吞羅發動進攻，玉子應該會憑藉本能去協助她，然後妳……）",
  ui_story_1015_10150401_70_dialog_content = "對了，空裔。",
  ui_story_1015_10150401_71_dialog_content = "嗯？叫我？",
  ui_story_1015_10150401_72_dialog_content = "你只關心剩餘時間，不關心實驗有沒有成功嗎？",
  ui_story_1015_10150401_73_dialog_content = "我……",
  ui_story_1015_10150401_74_dialog_content = "（糟了，露出破綻了嗎？）",
  ui_story_1015_10150401_75_dialog_content = "（薇絲，距離強化完成還有多久……）",
  ui_story_1015_10150401_76_dialog_content = "放心吧，薇絲的身體沒有發生任何變化。",
  ui_story_1015_10150401_77_dialog_content = "沒有受傷，也沒有符合預期的增強。",
  ui_story_1015_10150401_78_dialog_content = "實驗結束了。",
  ui_story_1015_10150401_79_dialog_content = "<color=#e8d9bb>嗡……</color>",
  ui_story_1015_10150401_80_dialog_content = "（怎麼回事！強化中止了？！）",
  ui_story_1015_10150401_81_dialog_content = "妳、妳做了什麼？",
  ui_story_1015_10150401_82_dialog_content = "只是關閉了和弦紐帶而已。",
  ui_story_1015_10150401_83_dialog_content = "實驗做到這一步就夠了，我並不期待實驗體身上發生多餘的變化。",
  ui_story_1015_10150401_84_dialog_content = "難道說，你們在期待什麼嗎？",
  ui_story_1015_10150401_85_dialog_content = "（怎麼辦薇絲，計畫好像被她看穿了……）",
  ui_story_1015_10150401_86_dialog_content = "（管不了那麼多了，像這樣的機會只有這一次！）",
  ui_story_1015_10150401_87_dialog_content = "（我馬上就掙脫繩索，準備上！）",
  ui_story_1015_10150401_88_dialog_content = "不說話嗎？看來我還是給了你們不切實際的想像。",
  ui_story_1015_10150401_89_dialog_content = "哼，等妳挨揍的時候就知道是否不切實際了。",
  ui_story_1015_10150401_90_dialog_content = "<color=#e8d9bb>哧——</color>",
  ui_story_1015_10150401_91_dialog_content = "妳果然借助和弦紐帶掙脫了繩索。",
  ui_story_1015_10150401_92_dialog_content = "不過沒關係，這本來就在我預估的風險之中。",
  ui_story_1015_10150401_93_dialog_content = "我能抓住妳一次，就能抓住妳第二次。",
  ui_story_1015_10150401_94_dialog_content = "薇絲！她在召集隱蔽起來的暗鬼！",
  ui_story_1015_10150401_95_dialog_content = "快動手！",
  ui_story_1015_10150502_1_dialog_content = "呼……呼……",
  ui_story_1015_10150502_2_dialog_content = "還是不行嗎……",
  ui_story_1015_10150502_3_dialog_content = "借助和弦紐帶的強化來掙脫繩索。妳能想到的事情，我會想不到嗎？",
  ui_story_1015_10150502_4_dialog_content = "別把這當成是機會，我早就做好了準備。",
  ui_story_1015_10150502_5_dialog_content = "虧你還有空在戰鬥中說閒話。",
  ui_story_1015_10150502_6_dialog_content = "這不是戰鬥中，戰鬥已經結束了。",
  ui_story_1015_10150502_7_dialog_content = "我沒時間再陪妳鬧下去。",
  ui_story_1015_10150502_8_dialog_content = "這可不是妳說了算的！",
  ui_story_1015_10150502_9_dialog_content = "那他說了算嗎？",
  ui_story_1015_10150502_10_dialog_content = "<size=45>薇絲！妳背後！</size>",
  ui_story_1015_10150502_11_dialog_content = "什麼……",
  ui_story_1015_10150502_12_dialog_content = "<size=45>嗚啊——！</size>",
  ui_story_1015_10150502_13_dialog_content = "<size=45>薇絲！！！</size>",
  ui_story_1015_10150502_14_dialog_content = "赫利俄斯……這傢伙竟然也藏在附近……",
  ui_story_1015_10150502_15_dialog_content = "對於你們來說，反抗是最愚蠢的選擇。",
  ui_story_1015_10150502_16_dialog_content = "它沒有成功的可能，只會成為干擾實驗進展的因素。",
  ui_story_1015_10150502_17_dialog_content = "我不喜歡實驗受到干擾。",
  ui_story_1015_10150502_18_dialog_content = "妳、妳要幹什麼？",
  ui_story_1015_10150502_19_dialog_content = "今天的實驗做完了，等我整理一下資料就離開這裡。",
  ui_story_1015_10150502_20_dialog_content = "空裔跟著我，赫利俄斯帶走薇絲，我們<color=#FFB400>分開</color>。",
  ui_story_1015_10150502_21_dialog_content = "分開？！",
  ui_story_1015_10150502_22_dialog_content = "從剛才的意外來看，你們兩個湊在一起形成了不安定的因素。",
  ui_story_1015_10150502_23_dialog_content = "既然這樣，以後就離遠一點吧。",
  ui_story_1015_10150502_24_dialog_content = "聽好了，鶯歌。現在的情況是這樣。",
  ui_story_1015_10150502_25_dialog_content = "吞羅潛入了這座研究院，擅自動用我們的研究器械。",
  ui_story_1015_10150502_26_dialog_content = "除此之外，先前到訪研究院的薇絲中尉和那位空裔已經失聯多日。",
  ui_story_1015_10150502_27_dialog_content = "結合士兵的目擊情報，我猜測，他們遭到了吞羅的劫持。",
  ui_story_1015_10150502_28_dialog_content = "PlayerName他們……",
  ui_story_1015_10150502_29_dialog_content = "尤利西斯教授，請問需要我執行的任務是什麼？",
  ui_story_1015_10150502_30_dialog_content = "營救人質，抓捕吞羅。",
  ui_story_1015_10150502_31_dialog_content = "<size=45>！！！</size>",
  ui_story_1015_10150502_32_dialog_content = "（這麼艱巨的任務，就交給一個中校？）",
  ui_story_1015_10150502_33_dialog_content = "……我接受任務。",
  ui_story_1015_10150502_34_dialog_content = "但是教授，以目前的狀況來看，完成任務的可能性很低。",
  ui_story_1015_10150502_35_dialog_content = "對方熟悉地形、實力強勁，且挾持了人質。",
  ui_story_1015_10150502_36_dialog_content = "只有我一人的話，並不具備任何優勢。",
  ui_story_1015_10150502_37_dialog_content = "如果我可以申請使用「<color=#FFB400>兵器</color>」……",
  ui_story_1015_10150502_38_dialog_content = "妳想讓阿克希亞來幫妳，對吧。",
  ui_story_1015_10150502_39_dialog_content = "……是的。",
  ui_story_1015_10150502_40_dialog_content = "不要過分依賴她的力量了。",
  ui_story_1015_10150502_41_dialog_content = "妳們兩個都是「<color=#FFB400>啟明星計畫</color>」的成員，只是側重的方向不同。",
  ui_story_1015_10150502_42_dialog_content = "這次不是用力量硬碰硬就能解決的問題，我需要妳用妳擅長的方式。",
  ui_story_1015_10150502_43_dialog_content = "我明白了，教授。",
  ui_story_1015_10150502_44_dialog_content = "況且，阿克希亞需要為另一個重要的計畫做準備，妳之後會知道的。",
  ui_story_1015_10150502_45_dialog_content = "當然了，與這樣的敵人交手，妳需要準備好底牌。",
  ui_story_1015_10150502_46_dialog_content = "妳可以從我這裡得到兩張牌。",
  ui_story_1015_10150502_47_dialog_content = "您說。",
  ui_story_1015_10150502_48_dialog_content = "第一張牌是增援。",
  ui_story_1015_10150502_49_dialog_content = "我為妳抽調了一個可靠的幫手，他正在趕來的路上。",
  ui_story_1015_10150502_50_dialog_content = "是委員會信賴的少校情報官阿納托利。",
  ui_story_1015_10150502_51_dialog_content = "我認識他！這確實是有效的助力！",
  ui_story_1015_10150502_52_dialog_content = "至於另一張牌……",
  ui_story_1015_10150502_53_dialog_content = "我要妳把它留到最後。",
  ui_story_1015_10150601_1_dialog_content = "<color=#e8d9bb>黃昏鎮 白夜要塞內</color>",
  ui_story_1015_10150601_2_dialog_content = "……",
  ui_story_1015_10150601_3_dialog_content = "<color=#e8d9bb>咚咚——</color>",
  ui_story_1015_10150601_4_dialog_content = "進來！",
  ui_story_1015_10150601_5_dialog_content = "……是妳啊，喬瑟琳。",
  ui_story_1015_10150601_6_dialog_content = "黃昏到了，禱告要開始了……你在等人？",
  ui_story_1015_10150601_7_dialog_content = "看來我來得不是時候。",
  ui_story_1015_10150601_8_dialog_content = "只是在等情報人員的匯報，這是騎士團目前最重要的事。",
  ui_story_1015_10150601_9_dialog_content = "前線那邊的情況一直不樂觀，周邊越來越多的聚落都遭受了暗鬼的攻擊。",
  ui_story_1015_10150601_10_dialog_content = "雖然說以地下城的規模，吸納這些居民還綽綽有餘……",
  ui_story_1015_10150601_11_dialog_content = "但是再這樣下去，我們總有一天會喪失對地面的控制權。",
  ui_story_1015_10150601_12_dialog_content = "是的，我絕不希望看到那樣的事情發生。",
  ui_story_1015_10150601_13_dialog_content = "暗鬼不斷聚集，卻尚未發起大規模進攻，白夜城和啟光聯邦均沒有出軍的指示。",
  ui_story_1015_10150601_14_dialog_content = "戰士們都已經很疲憊了，這種等待對他們反而是一種損耗。",
  ui_story_1015_10150601_15_dialog_content = "那希望今天的每日禱告，能夠稍微撫平你們這群戰士的焦慮。",
  ui_story_1015_10150601_16_dialog_content = "謝謝，喬瑟琳。",
  ui_story_1015_10150601_17_dialog_content = "<color=#e8d9bb>咚咚——</color>",
  ui_story_1015_10150601_18_dialog_content = "呼……呼……",
  ui_story_1015_10150601_19_dialog_content = "李奧團長……有啟光的消息了！",
  ui_story_1015_10150601_20_dialog_content = "啟光發來訊號，命全體駐軍即刻準備！",
  ui_story_1015_10150601_21_dialog_content = "快說是什麼事！",
  ui_story_1015_10150601_22_dialog_content = "是、是<color=#FFB400>聯合軍演</color>的準備。",
  ui_story_1015_10150601_23_dialog_content = "？！",
  ui_story_1015_10150601_24_dialog_content = "<color=#e8d9bb>黃昏鎮 共治地下城</color>",
  ui_story_1015_10150601_25_dialog_content = "這算是對黃昏鎮的例行邀請？",
  ui_story_1015_10150601_26_dialog_content = "是的，參謀長，雖說軍演日期完全按照大人物的心思來，但這也算是老傳統了。",
  ui_story_1015_10150601_27_dialog_content = "原來如此，這對將士們可不是什麼好消息。",
  ui_story_1015_10150601_28_dialog_content = "真是的，偏偏是在這種時候！",
  ui_story_1015_10150601_29_dialog_content = "是啊，「一鼓作氣，再而衰」，規模再大的軍演也比不上一場酣暢淋漓的戰鬥。",
  ui_story_1015_10150601_30_dialog_content = "邀請函上怎麼寫的，黃昏鎮一共要派過去幾人？",
  ui_story_1015_10150601_31_dialog_content = "三人。啟光軍人、白夜騎士、神職人員各一名。除了您之外，還有……",
  ui_story_1015_10150601_32_dialog_content = "<color=#e8d9bb>黃昏鎮 白夜要塞內</color>",
  ui_story_1015_10150601_33_dialog_content = "我知道了。雖說這裡是共治區域，你們看起來都對啟光的這個命令不太滿意啊。",
  ui_story_1015_10150601_34_dialog_content = "這是肯定的吧！迦南城那邊的軍人，就是喜歡搞這些形式死板的東西。",
  ui_story_1015_10150601_35_dialog_content = "前線這邊的戰爭一觸即發，何必要去配合滿足他們的興趣！",
  ui_story_1015_10150601_36_dialog_content = "這個邀請函的到來確實是一個意外的驚喜。",
  ui_story_1015_10150601_37_dialog_content = "驚喜？李奧，你已經決定了？",
  ui_story_1015_10150601_38_dialog_content = "嗯，我要去。",
  ui_story_1015_10150601_39_dialog_content = "團長？！",
  ui_story_1015_10150601_40_dialog_content = "如果那是一個集合各方勢力、能讓全大陸都看到的舞台……",
  ui_story_1015_10150601_41_dialog_content = "就讓邊境動亂的消息向全大陸公開吧。",
  ui_story_1015_10150601_42_dialog_content = "李奧團長……",
  ui_story_1015_10150601_43_dialog_content = "我稍作準備，然後去和若瑟與昭會合。",
  ui_story_1015_10150601_44_dialog_content = "至於在我和若瑟離開的這段時間——喬瑟琳，拜託妳了。",
  ui_story_1015_10150601_45_dialog_content = "嗯，我知道的。",
  ui_story_1015_10150601_46_dialog_content = "和鐵棘騎士團一起並肩作戰，並為民眾們帶來寬慰人心的力量……",
  ui_story_1015_10150601_47_dialog_content = "你回來之後，可要好好請我一頓啊。",
  ui_story_1015_10150601_48_dialog_content = "哈哈，那是當然。",
  ui_story_1015_10150601_49_dialog_content = "<color=#e8d9bb>啟光聯邦 迦南城 某處</color>",
  ui_story_1015_10150601_50_dialog_content = "我堅決反對。",
  ui_story_1015_10150601_51_dialog_content = "我確實是有提出反對的權利的，我沒說錯吧？",
  ui_story_1015_10150601_52_dialog_content = "是，大元帥大人，按科學首席議會的章程規定，元帥對議會意見具有表決權。",
  ui_story_1015_10150601_53_dialog_content = "那勞駕你跑一趟，通知他們盡快舉行投票會議。",
  ui_story_1015_10150601_54_dialog_content = "是這樣的……大元帥，「聯合軍演」是首席議會權衡利弊之後做出的決定。",
  ui_story_1015_10150601_55_dialog_content = "即使您投出反對的一票，首席議會的諸位也不會輕易放棄……",
  ui_story_1015_10150601_56_dialog_content = "跟你說話真累，直接讓尤利西斯出來見我。",
  ui_story_1015_10150601_57_dialog_content = "對不起，但是尤利西斯教授說過，如果您是為了這件事找他，他不會露面。",
  ui_story_1015_10150601_58_dialog_content = "可惡。",
  ui_story_1015_10150601_59_dialog_content = "我先說好，你們搞的這些花拳繡腿，我從來沒有插手的興趣。",
  ui_story_1015_10150601_60_dialog_content = "同樣，我不希望我的戰略部署受到任何因素的干擾。",
  ui_story_1015_10150601_61_dialog_content = "極光遺跡正是需要啟光出兵支援的時期，你們反倒用軍演的理由從中抽兵減員！",
  ui_story_1015_10150601_62_dialog_content = "這完全就是胡鬧！",
  ui_story_1015_10150601_63_dialog_content = "對不起，大元帥，我……",
  ui_story_1015_10150601_64_dialog_content = "何必為難一個基層士兵呢。",
  ui_story_1015_10150601_65_dialog_content = "尤利西斯那個老頭不願出來，跟我說也沒有區別吧。",
  ui_story_1015_10150601_66_dialog_content = "萊因哈特，妳好像很衝動，建議妳稍微冷靜一些。來玩一次抽鬼牌如何？",
  ui_story_1015_10150601_67_dialog_content = "「<color=#FFB400>鐵面</color>」大人……",
  ui_story_1015_10150601_68_dialog_content = "這個笑話並不好笑，<color=#FFB400>貝利撒留</color>，我對抽鬼牌也沒興趣。",
  ui_story_1015_10150601_69_dialog_content = "妳願意露面倒是讓我滿驚訝的。",
  ui_story_1015_10150601_70_dialog_content = "我沒有在開玩笑，我願意付出的時間和耐心有限。",
  ui_story_1015_10150601_71_dialog_content = "選一張吧，並在這個時間裡快點說完，能做到吧。",
  ui_story_1015_10150601_72_dialog_content = "……",
  ui_story_1015_10150601_73_dialog_content = "左邊。",
  ui_story_1015_10150601_74_dialog_content = "我的訴求很簡單，我不支持避戰的策略。",
  ui_story_1015_10150601_75_dialog_content = "暫停聯合軍演，以支援黃昏鎮駐軍為優先！",
  ui_story_1015_10150601_76_dialog_content = "哦，很遺憾，妳抽到了「鬼」，妳輸了。",
  ui_story_1015_10150601_77_dialog_content = "忽略事先觀察就做出選擇，這也是歷任元帥的通病了。",
  ui_story_1015_10150601_78_dialog_content = "萊因哈特，戰爭不是能夠供妳肆意揮霍的遊戲，它的本質是一場生意。",
  ui_story_1015_10150601_79_dialog_content = "輸贏向來無所謂，重要的是輸會損失什麼，贏會獲得什麼。",
  ui_story_1015_10150601_80_dialog_content = "妳輸了，所以我給妳的時間也到此結束。",
  ui_story_1015_10150601_81_dialog_content = "如果妳學不會這件事，我們委員會會找其他人來學。",
  ui_story_1015_10150601_82_dialog_content = "……",
  ui_story_1015_10150601_83_dialog_content = "<color=#e8d9bb>咯吱……</color>",
  ui_story_1015_10150601_84_dialog_content = "<color=#e8d9bb>白夜城 高庭</color>",
  ui_story_1015_10150601_85_dialog_content = "果然，這次的啟光聯合軍演也在從黎明學院裡面挑人。",
  ui_story_1015_10150601_86_dialog_content = "哼哼～我們四天使這邊當然沒有異議，多給年輕的孩子們一些機會吧。",
  ui_story_1015_10150601_87_dialog_content = "拉斐爾大人……明明拉斐爾大人自己也是個孩子嘛！",
  ui_story_1015_10150601_88_dialog_content = "哎呀，反正有卡蓮隊長做領隊，我就不用另外出面了。",
  ui_story_1015_10150601_89_dialog_content = "抓住這次機會吧，隊長～這可是能一舉通過復職考察期的好機會的說～",
  ui_story_1015_10150601_90_dialog_content = "除了妳之外，邀請函上還寫了哪些孩子？",
  ui_story_1015_10150601_91_dialog_content = "有點奇怪的是，這次黎明學院竟然收到了四份邀請。",
  ui_story_1015_10150601_92_dialog_content = "除了我以外，還有克蘿伊、尤萊雅……以及，貝爾塔。",
  ui_story_1015_10150601_93_dialog_content = "但說實話，我對於這次的聯合軍演倒是沒有特別大的興趣。",
  ui_story_1015_10150601_94_dialog_content = "在上次舉行的軍演中，我所率領的小隊已經摘得桂冠了。",
  ui_story_1015_10150601_95_dialog_content = "我也不需要透過這種虛無的榮譽去換取我的正式職位。",
  ui_story_1015_10150601_96_dialog_content = "哈～不愧是隊長會說出來的話呢……",
  ui_story_1015_10150601_97_dialog_content = "所以——貝爾塔，妳沒問題吧？妳和克蘿伊、尤萊雅可以互相配合嗎？",
  ui_story_1015_10150601_98_dialog_content = "咦？！",
  ui_story_1015_10150601_99_dialog_content = "我希望妳接替這個三人小隊的領隊資格，帶著妳的「貝爾塔小隊」為白夜城戰鬥。",
  ui_story_1015_10150601_100_dialog_content = "妳也不是第一次離開白夜城執行外派的工作了，我想妳應該可以勝任。",
  ui_story_1015_10150601_101_dialog_content = "當然當然，我會珍惜這次機會的！",
  ui_story_1015_10150601_102_dialog_content = "呵呵，克蘿伊和尤萊雅就要交到小貝爾塔的手上了。",
  ui_story_1015_10150601_103_dialog_content = "妳可要保護好她們啊～",
  ui_story_1015_10150601_104_dialog_content = "是的！",
  ui_story_1015_10150601_105_dialog_content = "不過……我唯一有點不自信的地方，反而是前往聯合軍演的路程。",
  ui_story_1015_10150601_106_dialog_content = "聽說那群啟光的把地下城建得七彎八拐的，我還從來沒有去過……",
  ui_story_1015_10150601_107_dialog_content = "哦，這點妳不用擔心。",
  ui_story_1015_10150601_108_dialog_content = "我雖說不做領隊，但還是打算和妳們一起前往迦南城一趟。",
  ui_story_1015_10150601_109_dialog_content = "唔，為什麼？",
  ui_story_1015_10150601_110_dialog_content = "說到底……那邊還是有兩個讓人不太放心的傢伙……",
  ui_story_1015_10150701_1_dialog_content = "<color=#e8d9bb>啟光聯邦 X號地下城</color>",
  ui_story_1015_10150701_2_dialog_content = "啟光聯邦情報官阿納托利前來報到，奉委員會的命令，接下來我將會輔佐您的行動，鶯歌中校。",
  ui_story_1015_10150701_3_dialog_content = "你也是情報官？",
  ui_story_1015_10150701_4_dialog_content = "哦……我知道你，你是前一段時間隨大元帥前往空之山谷，對抗日蝕的那個副手。",
  ui_story_1015_10150701_5_dialog_content = "是，鶯歌中校的消息果然很精準，我一直都很期待能有與您一同工作的機會。",
  ui_story_1015_10150701_6_dialog_content = "漂亮話就不必說了，我們快點準備行動吧。",
  ui_story_1015_10150701_7_dialog_content = "……你在記什麼？",
  ui_story_1015_10150701_8_dialog_content = "哦，這是我的筆記本，我剛才畫下了您的形象，「一位性格俐落的中校」。",
  ui_story_1015_10150701_9_dialog_content = "你——好吧，如果這是你習慣的工作方式，那我不會干涉。",
  ui_story_1015_10150701_10_dialog_content = "本次你的任務是配合我「營救人質，並抓捕吞羅」。",
  ui_story_1015_10150701_11_dialog_content = "不好意思打斷一下，鶯歌中校，吞羅在……這座地下城？人質又是？",
  ui_story_1015_10150701_12_dialog_content = "咳，我來說明一下目前的基本情況吧。",
  ui_story_1015_10150701_13_dialog_content = "曾經被整個啟光通緝的吞羅，劫走了薇絲中尉和PlayerName。",
  ui_story_1015_10150701_14_dialog_content = "並且企圖潛入研究室進行她的實驗。",
  ui_story_1015_10150701_15_dialog_content = "我想，她這個舉動一定和空之山谷那場戰役中發生的事情有關。",
  ui_story_1015_10150701_16_dialog_content = "她對空裔科技為薇絲中尉所帶來的變化十分感興趣。",
  ui_story_1015_10150701_17_dialog_content = "這樣的話，他們兩個的處境非常危險！",
  ui_story_1015_10150701_18_dialog_content = "啟光的情報網層疊交織，吞羅帶著兩個大活人，一定會非常顯眼。",
  ui_story_1015_10150701_19_dialog_content = "最棘手的問題是，薇絲中尉在這個過程中被分開了。",
  ui_story_1015_10150701_20_dialog_content = "接下來我們的行動分為兩個步驟。",
  ui_story_1015_10150701_21_dialog_content = "一、尋找薇絲中尉的下落，越早越好，一定要搶在吞羅的前面。",
  ui_story_1015_10150701_22_dialog_content = "二、破壞吞羅的計畫，PlayerName在她手上，但她不敢對他輕舉妄動。",
  ui_story_1015_10150701_23_dialog_content = "如果有機會，最好能一舉抓捕吞羅。",
  ui_story_1015_10150701_24_dialog_content = "是！我明白了……",
  ui_story_1015_10150701_25_dialog_content = "你這又是在？",
  ui_story_1015_10150701_26_dialog_content = "我在根據我以往對這幾人性格和行動的紀錄，畫他們接下來的行動路線推測圖。",
  ui_story_1015_10150701_27_dialog_content = "……真是服了你了。",
  ui_story_1015_10150701_28_dialog_content = "<color=#e8d9bb>嗶嗶、嗶嗶！</color>",
  ui_story_1015_10150701_29_dialog_content = "嗯……？",
  ui_story_1015_10150701_30_dialog_content = "（這是，新訪客的通知？）",
  ui_story_1015_10150701_31_dialog_content = "<color=#e8d9bb>與此同時，X號地下城另一端</color>",
  ui_story_1015_10150701_32_dialog_content = "……",
  ui_story_1015_10150701_33_dialog_content = "別停，快跟上。",
  ui_story_1015_10150701_34_dialog_content = "怎麼了？",
  ui_story_1015_10150701_35_dialog_content = "妳在要求我們配合妳之前，可從沒說過會出現生命威脅。",
  ui_story_1015_10150701_36_dialog_content = "你說薇絲？放心吧，她死不了，我怎麼「捨得」讓她死。",
  ui_story_1015_10150701_37_dialog_content = "你想反抗，或者想反悔？",
  ui_story_1015_10150701_38_dialog_content = "我憑什麼相信妳！",
  ui_story_1015_10150701_39_dialog_content = "麻煩死了。",
  ui_story_1015_10150701_40_dialog_content = "你拿著這個吧。",
  ui_story_1015_10150701_41_dialog_content = "<color=#e8d9bb>嗞嗞……嗞嗞……</color>",
  ui_story_1015_10150701_42_dialog_content = "對面是……薇絲？",
  ui_story_1015_10150701_43_dialog_content = "嗯，啟光人手一個的<color=#FFB400>通訊器</color>，這是她的頻段，我一直接通著。",
  ui_story_1015_10150701_44_dialog_content = "她被赫利俄斯帶著，等一下你就有跟她說話確認的機會。",
  ui_story_1015_10150701_45_dialog_content = "那現在呢？",
  ui_story_1015_10150701_46_dialog_content = "現在，當然是幫我把這幾個小兵解決掉。",
  ui_story_1015_10150702_1_dialog_content = "喂，薇絲，能聽到嗎？",
  ui_story_1015_10150702_2_dialog_content = "PlayerName！是你嗎！",
  ui_story_1015_10150702_3_dialog_content = "薇絲，妳還好嗎？！",
  ui_story_1015_10150702_4_dialog_content = "我沒事……但我被關起來了。",
  ui_story_1015_10150702_5_dialog_content = "這裡看起來是個空曠的倉庫。",
  ui_story_1015_10150702_6_dialog_content = "倉庫？",
  ui_story_1015_10150702_7_dialog_content = "我警告你們，別進行多餘的溝通。",
  ui_story_1015_10150702_8_dialog_content = "如果給你們對講機反而增加了麻煩的話……",
  ui_story_1015_10150702_9_dialog_content = "好了我知道了！我們聊點別的可以嗎？",
  ui_story_1015_10150702_10_dialog_content = "算了，別囉嗦了。",
  ui_story_1015_10150702_11_dialog_content = "前面就是目的地，先辦正事。",
  ui_story_1015_10150702_12_dialog_content = "這是什麼地方，進這裡做什麼？",
  ui_story_1015_10150702_13_dialog_content = "別緊張，就是個大型的「<color=#FFB400>資料室</color>」，拿到我想要的東西我們就走。",
  ui_story_1015_10150702_14_dialog_content = "畢竟我的時間很寶貴。",
  ui_story_1015_10150702_15_dialog_content = "那我們為什麼還站在這裡不動？",
  ui_story_1015_10150702_16_dialog_content = "你過來一下。",
  ui_story_1015_10150702_17_dialog_content = "嗯？",
  ui_story_1015_10150702_18_dialog_content = "正在掃描訪客的臉部資訊……",
  ui_story_1015_10150702_19_dialog_content = "正在進行分析准入資料……",
  ui_story_1015_10150702_20_dialog_content = "檔案館已開放。",
  ui_story_1015_10150702_21_dialog_content = "為、為什麼要我來打開？",
  ui_story_1015_10150702_22_dialog_content = "我不是說了嗎，整座研究院都曾是我的東西，可是尤利西斯動了一些手腳。",
  ui_story_1015_10150702_23_dialog_content = "你既然進過尤利西斯那個大會議室，那肯定就能幫我把這扇門打開。",
  ui_story_1015_10150702_24_dialog_content = "（既然監視器掃到了我，就一定也拍到了站在我後面的吞羅……）",
  ui_story_1015_10150702_25_dialog_content = "（這樣下去，再過不久……）",
  ui_story_1015_10150702_26_dialog_content = "別磨磨蹭蹭的，快點進來。",
  ui_story_1015_10150702_27_dialog_content = "你和玉子站在門口，把門關上，別搗亂。",
  ui_story_1015_10150702_28_dialog_content = "要是突然有人進來，玉子會出手。",
  ui_story_1015_10150702_29_dialog_content = "……至少要讓我知道妳到底要找什麼檔案吧。",
  ui_story_1015_10150702_30_dialog_content = "我要找一份資料，是尤利西斯決不會公之於眾的東西。",
  ui_story_1015_10150702_31_dialog_content = "我要看「<color=#FFB400>啟明星計畫</color>」的實驗資訊。",
  ui_story_1015_10150801_1_dialog_content = "<color=#e8d9bb>不久之前</color>",
  ui_story_1015_10150801_2_dialog_content = "唔……隱私條款——同意，使用者條款——同意！",
  ui_story_1015_10150801_3_dialog_content = "再更新一下必要的檔案……",
  ui_story_1015_10150801_4_dialog_content = "<color=#e8d9bb>咚咚！</color>",
  ui_story_1015_10150801_5_dialog_content = "進來……",
  ui_story_1015_10150801_6_dialog_content = "科研長，一位自稱白夜城「衛隊長」的女孩要見您。",
  ui_story_1015_10150801_7_dialog_content = "哦，白夜城的女孩啊，那就讓她站在啟動介面的左邊吧……",
  ui_story_1015_10150801_8_dialog_content = "啟、啟動介面？",
  ui_story_1015_10150801_9_dialog_content = "哈～抱歉抱歉，我是在說遊戲啦！",
  ui_story_1015_10150801_10_dialog_content = "唔？卡蓮？",
  ui_story_1015_10150801_11_dialog_content = "呵呵～科學家先生，你太失禮啦，你旁邊這位可是上一屆聯合軍演的冠軍喔。",
  ui_story_1015_10150801_12_dialog_content = "打擾了，因為擔憂臨空者號的狀況，所以我打算先來您這裡確認一眼。",
  ui_story_1015_10150801_13_dialog_content = "順便問一下，薇絲和PlayerName不在嗎？",
  ui_story_1015_10150801_14_dialog_content = "妳說臨空者號啊！多虧你們上次去黃昏鎮跑了一趟。",
  ui_story_1015_10150801_15_dialog_content = "妳看，他現在已經蘇醒過來了，還可以撲騰翅膀呢。",
  ui_story_1015_10150801_16_dialog_content = "經過啟光科技的再次修整，他又恢復到可以戰鬥的狀態了，怎麼墜機都不怕喔。",
  ui_story_1015_10150801_17_dialog_content = "真是「借您吉言」，貢露小姐。",
  ui_story_1015_10150801_18_dialog_content = "啊～好可惜，沒有PlayerName這個感應翻譯，聽不到臨空者號對我說謝謝了～",
  ui_story_1015_10150801_19_dialog_content = "既然臨空者號沒事，那真是太好了。",
  ui_story_1015_10150801_20_dialog_content = "卡蓮同學，這次也對聯合軍演勢在必得嗎？",
  ui_story_1015_10150801_21_dialog_content = "再提前透露一個攻略，這次的參與成員可沒有以往那麼好對付啊。",
  ui_story_1015_10150801_22_dialog_content = "不，實際上，我已經棄權了，這次白夜城三人小隊的領隊另有其人。",
  ui_story_1015_10150801_23_dialog_content = "咦？啊，我明白了……",
  ui_story_1015_10150801_24_dialog_content = "你們三個果然還是要快點碰頭才行，因為——",
  ui_story_1015_10150801_25_dialog_content = "發給妳的那張邀請函，編隊是屬於PlayerName小隊的喔！",
  ui_story_1015_10150801_26_dialog_content = "原來如此，這麼說，這也是空裔一族時隔多年，再次在軍演上亮相呢。",
  ui_story_1015_10150801_27_dialog_content = "說的沒錯，所以，給我好好打起精神來，不要手下留情喔。",
  ui_story_1015_10150801_28_dialog_content = "謝謝，我知道了。",
  ui_story_1015_10150801_29_dialog_content = "那麼，PlayerName和薇絲他們到底……",
  ui_story_1015_10150801_30_dialog_content = "唔，妳等一下啊。",
  ui_story_1015_10150801_31_dialog_content = "<color=#e8d9bb>嗶——嗶！</color>",
  ui_story_1015_10150801_32_dialog_content = "我在妳手上的邀請函裡存入了通行證和一個地圖。",
  ui_story_1015_10150801_33_dialog_content = "地圖上標示的座標是X地下城，是啟光對特殊光靈進行治療和研究的地方。",
  ui_story_1015_10150801_34_dialog_content = "（不過……PlayerName和薇絲他們兩個在那裡待得也太久了……）",
  ui_story_1015_10150801_35_dialog_content = "總之，這個通行證可以保證妳擁有啟光大多數一般通道的通行權限。",
  ui_story_1015_10150801_36_dialog_content = "十分感謝，那麼事不宜遲，我就先告辭了。",
  ui_story_1015_10150801_37_dialog_content = "去吧去吧～這裡不像白夜城，沒有在妳身旁隨行的衛兵，一定要注意安全喔。",
  ui_story_1015_10150801_38_dialog_content = "<color=#e8d9bb>啟光聯邦 X號地下城</color>",
  ui_story_1015_10150801_39_dialog_content = "（按照地圖的指示，這裡應該就是貢露所說的位置了……）",
  ui_story_1015_10150801_40_dialog_content = "（不過這裡比我想像得還要大一些。）",
  ui_story_1015_10150801_41_dialog_content = "（使用密集型的大型建築供養龐大的人口，這就是啟光的生存策略吧。）",
  ui_story_1015_10150801_42_dialog_content = "？！",
  ui_story_1015_10150801_43_dialog_content = "<color=#e8d9bb>刷——</color>",
  ui_story_1015_10150801_44_dialog_content = "什麼人！",
  ui_story_1015_10150801_45_dialog_content = "……鶯歌？",
  ui_story_1015_10150801_46_dialog_content = "原來是妳觸發了新訪客的通知。",
  ui_story_1015_10150801_47_dialog_content = "妳在這裡做什麼——哦，我知道了。",
  ui_story_1015_10150801_48_dialog_content = "我們多多少少都是出於同一個目的吧。",
  ui_story_1015_10150801_49_dialog_content = "現在到底是什麼狀況，麻煩了，請為我說明一下。",
  ui_story_1015_10150801_50_dialog_content = "噓——！",
  ui_story_1015_10150801_51_dialog_content = "<anim type=Shake>嘎咕……嘎咕……</anim>",
  ui_story_1015_10150801_52_dialog_content = "至少等打完這幾隻暗鬼吧。",
  ui_story_1015_10150801_53_dialog_content = "那還等什麼，我們快動手吧。",
  ui_story_1015_10150802_1_dialog_content = "怎麼會發生這種事？！這也太胡鬧了！",
  ui_story_1015_10150802_2_dialog_content = "吞羅到底想要幹什麼？",
  ui_story_1015_10150802_3_dialog_content = "為什麼時至今日啟光還沒有出兵圍剿她？",
  ui_story_1015_10150802_4_dialog_content = "冷靜一點，卡蓮，這裡不是白夜城，每一項重要決策都需要多方共同決斷。",
  ui_story_1015_10150802_5_dialog_content = "對此，委員會已經開始籌備了，而我們正是走在決策前面的先遣小隊。",
  ui_story_1015_10150802_6_dialog_content = "所以，我們接下來的計畫是什麼？",
  ui_story_1015_10150802_7_dialog_content = "以情報官的立場，接下來我們需要整合情報，以最有效率的方式接近吞羅。",
  ui_story_1015_10150802_8_dialog_content = "至於對方情報的突破口，我認為可以從這裡到處都有的監視器入手。",
  ui_story_1015_10150802_9_dialog_content = "只要向高層申請監視器紀錄的調用許可，吞羅和薇絲的位置全都一目了然。",
  ui_story_1015_10150802_10_dialog_content = "恐怕不行。",
  ui_story_1015_10150802_11_dialog_content = "不知道是出於什麼樣的目的，這裡的監視器只用於身分驗證，且紀錄會立刻銷毀。",
  ui_story_1015_10150802_12_dialog_content = "竟然……",
  ui_story_1015_10150802_13_dialog_content = "怎麼聽起來偷偷摸摸的。",
  ui_story_1015_10150802_14_dialog_content = "無論如何，我們總不能在這個地下城盲目地亂轉吧。",
  ui_story_1015_10150802_15_dialog_content = "別急，我倒是突然有個想法。",
  ui_story_1015_10150802_16_dialog_content = "在啟光發生的事情，當然要用啟光的工具來解決。",
  ui_story_1015_10150901_1_dialog_content = "（編號1到50內以A字母開頭的文件全都翻遍了，還是沒有找到。）",
  ui_story_1015_10150901_2_dialog_content = "（這麼翻也不是辦法，把這堆櫃子裡的文件標題全看一遍也至少要一個月的時間。）",
  ui_story_1015_10150901_3_dialog_content = "（除了找尤利西斯本人，必須要快點搞懂這些櫃子的分類規則……）",
  ui_story_1015_10150901_4_dialog_content = "薇絲，妳那邊食物和水都充足嗎？",
  ui_story_1015_10150901_5_dialog_content = "放心……些……題。",
  ui_story_1015_10150901_6_dialog_content = "什麼？",
  ui_story_1015_10150901_7_dialog_content = "咦？聽不清楚嗎？",
  ui_story_1015_10150901_8_dialog_content = "喔，能聽清楚了，可是剛才聲音斷斷續續的，真奇怪。",
  ui_story_1015_10150901_9_dialog_content = "是不是電量不足了？對講機的電池容量不大，一直使用的話很容易沒電。",
  ui_story_1015_10150901_10_dialog_content = "咦？還會沒電——",
  ui_story_1015_10150901_11_dialog_content = "吵死了，把它給我。",
  ui_story_1015_10150901_12_dialog_content = "喂！妳把對講機搶走幹嘛！",
  ui_story_1015_10150901_13_dialog_content = "等一下再讓你用，先過來幫我個忙。",
  ui_story_1015_10150901_14_dialog_content = "又要幹什麼。",
  ui_story_1015_10150901_15_dialog_content = "你們空裔能感應到特定光靈近期觸摸過哪些文件吧。",
  ui_story_1015_10150901_16_dialog_content = "幫我看一下。",
  ui_story_1015_10150901_17_dialog_content = "……不可能啊，我又不是狗！",
  ui_story_1015_10150901_18_dialog_content = "嘖，當初在塔裡，真應該也把你丟到那個機器上躺一下。",
  ui_story_1015_10150901_19_dialog_content = "做不到的話，就來看看怎麼破解這台主機的密碼吧。",
  ui_story_1015_10150901_20_dialog_content = "我剛才倒是也注意到了，這台機器確實是有點顯眼。",
  ui_story_1015_10150901_21_dialog_content = "每個研究點都有一台這樣的東西。",
  ui_story_1015_10150901_22_dialog_content = "查詢資料、控制機械運轉，總之是輔助研究者的工具。",
  ui_story_1015_10150901_23_dialog_content = "原來如此。",
  ui_story_1015_10150901_24_dialog_content = "一定要我來操作嗎？保險起見，我還是不動了吧。",
  ui_story_1015_10150901_25_dialog_content = "我對啟光的科技沒有那麼瞭解。",
  ui_story_1015_10150901_26_dialog_content = "……真是囉嗦。",
  ui_story_1015_10150901_27_dialog_content = "<color=#e8d9bb>嗶——</color>",
  ui_story_1015_10150901_28_dialog_content = "等、等一下，先不要這麼隨便地輸入密碼吧……",
  ui_story_1015_10150901_29_dialog_content = "科技本來就是為研究服務的東西，如果不能被我使用，那就沒有存在的價值了。",
  ui_story_1015_10150901_30_dialog_content = "<color=#e8d9bb>嗶、嗶——嗶。</color>",
  ui_story_1015_10150901_31_dialog_content = "……好吧。",
  ui_story_1015_10150901_32_dialog_content = "（好在她看起來真的知道該怎麼破解。）",
  ui_story_1015_10150901_33_dialog_content = "<color=#e8d9bb>嗶——</color>",
  ui_story_1015_10150901_34_dialog_content = "<color=#e8d9bb>警報——警報——</color>",
  ui_story_1015_10150901_35_dialog_content = "<color=#e8d9bb>密碼錯誤，應急預警設施已啟動——</color>",
  ui_story_1015_10150901_36_dialog_content = "什麼？！",
  ui_story_1015_10150901_37_dialog_content = "<anim type=Shake><size=45>嗶——嗶——</size></anim>",
  ui_story_1015_10150901_38_dialog_content = "這是個什麼東西……",
  ui_story_1015_10150901_39_dialog_content = "妳不是很有自信嗎？？？吞羅！",
  ui_story_1015_10150901_40_dialog_content = "失誤是難免的，電子科技並不是我主攻的方向。",
  ui_story_1015_10150901_41_dialog_content = "快想想辦法啊……現在也不是總結失誤的時候！",
  ui_story_1015_10150901_42_dialog_content = "<color=#e8d9bb>啪——</color>",
  ui_story_1015_10150901_43_dialog_content = "直接把這個檔案庫的電源關了就行了。",
  ui_story_1015_10150901_44_dialog_content = "這樣就行？",
  ui_story_1015_10150901_45_dialog_content = "……",
  ui_story_1015_10150901_46_dialog_content = "<anim type=Shake><size=45>嗶——嗶——</size></anim>",
  ui_story_1015_10150901_47_dialog_content = "完全沒有用啊！",
  ui_story_1015_10150901_48_dialog_content = "嘖……真是麻煩。",
  ui_story_1015_10150901_49_dialog_content = "還是要先把這條機械狗幹掉。玉子——",
  ui_story_1015_10150901_50_dialog_content = "<anim type=Shake><size=50>吼！！！</size></anim>",
  ui_story_1015_10150901_51_dialog_content = "去把它嚼碎吧。",
  ui_story_1015_10150902_1_dialog_content = "<anim type=Shake><size=45>咕嚕嚕……咕嚕嚕……</size></anim>",
  ui_story_1015_10150902_2_dialog_content = "幹得不錯，好好地吃吧。",
  ui_story_1015_10150902_3_dialog_content = "繼續幫我盯著門口，懂嗎？",
  ui_story_1015_10150902_4_dialog_content = "<anim type=Shake><size=45>吼……</size></anim>",
  ui_story_1015_10150902_5_dialog_content = "這個機器……算是這裡的守護者嗎？",
  ui_story_1015_10150902_6_dialog_content = "不知道，這不是我留下來的東西。",
  ui_story_1015_10150902_7_dialog_content = "我們已經耽誤太多時間了，接下來的動作要快。",
  ui_story_1015_10150902_8_dialog_content = "<color=#e8d9bb>嗶、嗶——嗶。</color>",
  ui_story_1015_10150902_9_dialog_content = "<color=#e8d9bb>儲存中樞已啟動！</color>",
  ui_story_1015_10150902_10_dialog_content = "繼續搜尋，「啟明星計畫」。",
  ui_story_1015_10150902_11_dialog_content = "……不，如果找不到更多資料……",
  ui_story_1015_10150902_12_dialog_content = "……關鍵字變更，搜尋「<color=#FFB400>人造太陽計畫</color>」。",
  ui_story_1015_10150902_13_dialog_content = "（人造……太陽？什麼意思？顧名思義，難道是製造一個巨大的太陽？）",
  ui_story_1015_10150902_14_dialog_content = "（一下是啟明星，一下又是這個……吞羅究竟想找些什麼……）",
  ui_story_1015_10150902_15_dialog_content = "找到了。",
  ui_story_1015_10150902_16_dialog_content = "好了，快撤吧。",
  ui_story_1015_10150902_17_dialog_content = "吞羅，這個資料的內容到底是什麼，值得妳和尤利西斯這樣爭奪？",
  ui_story_1015_10150902_18_dialog_content = "你想知道？",
  ui_story_1015_10150902_19_dialog_content = "你就算知道了也毫無用處，因為空谷的那台裝置已經失效了。",
  ui_story_1015_10150902_20_dialog_content = "而且，我的研究已經遠超過啟光和空裔科技的水準。",
  ui_story_1015_10150902_21_dialog_content = "我勸你不要生出多餘的心思。",
  ui_story_1015_10150902_22_dialog_content = "我只是出於好奇才問的，剛才的戰鬥我也幫了忙，總不能連戰鬥目的都不知道。",
  ui_story_1015_10150902_23_dialog_content = "以我現在的狀況，妳也不用這麼防備我，不是嗎？",
  ui_story_1015_10150902_24_dialog_content = "……",
  ui_story_1015_10150902_25_dialog_content = "好吧，告訴你確實也無妨。",
  ui_story_1015_10150902_26_dialog_content = "這本來就是你知道的事情。",
  ui_story_1015_10150902_27_dialog_content = "我知道……？",
  ui_story_1015_10150902_28_dialog_content = "當時你們前往「泥潭」，把沉睡已久的赫利俄斯喚醒的時候。",
  ui_story_1015_10150902_29_dialog_content = "那時關於我們三個人的種種過往，她想必都跟你說了。",
  ui_story_1015_10150902_30_dialog_content = "當年的我們三個人一起長大，一起參軍、戰鬥……",
  ui_story_1015_10150902_31_dialog_content = "這種時間長久的磨合當然不是出於所謂的友情、羈絆一類的原因。",
  ui_story_1015_10150902_32_dialog_content = "而是因為，我們就是最早的「<color=#FFB400>人造太陽計畫</color>」的實驗品。",
  ui_story_1015_10150902_33_dialog_content = "只有經歷相同的成長，遭遇同樣的戰鬥，接受同一套改造，才能互為對照。",
  ui_story_1015_10150902_34_dialog_content = "只不過當時那群老古董的研究實在是不怎麼樣。",
  ui_story_1015_10150902_35_dialog_content = "萊因哈特能成為今天這幅樣子還是滿出乎我意料的。",
  ui_story_1015_10150902_36_dialog_content = "後來，這個計畫的名字變成了更好聽的「<color=#FFB400>啟明星</color>」。",
  ui_story_1015_10150902_37_dialog_content = "竟然……這件事的背後竟然是這樣的起因。",
  ui_story_1015_10150902_38_dialog_content = "你這副表情真噁心，空裔都是這種惻隱心氾濫的品種嗎。",
  ui_story_1015_10150902_39_dialog_content = "拿去聽吧，現在可以聽了。",
  ui_story_1015_10150902_40_dialog_content = "咦！",
  ui_story_1015_10150902_41_dialog_content = "<color=#e8d9bb>嗞嗞……嗞嗞……</color>",
  ui_story_1015_10150902_42_dialog_content = "PlayerName！你怎麼樣了！",
  ui_story_1015_10150902_43_dialog_content = "……薇絲！",
  ui_story_1015_10150902_44_dialog_content = "<color=#e8d9bb>嗞嗞……嗞嗞……</color>",
  ui_story_1015_10150902_45_dialog_content = "啊……",
  ui_story_1015_10150902_46_dialog_content = "薇絲的頻段有波動！",
  ui_story_1015_10150902_47_dialog_content = "能不能立刻根據波動定位到薇絲的位置！",
  ui_story_1015_10150902_48_dialog_content = "根據啟光現在的技術來說，恐怕還不行。",
  ui_story_1015_10150902_49_dialog_content = "但至少，我們能知道薇絲中尉使用了她的對講機。",
  ui_story_1015_10150902_50_dialog_content = "這說明她有一定的活動自由。",
  ui_story_1015_10150902_51_dialog_content = "沒猜錯的話，薇絲中尉對講機的另一頭，一定就是吞羅了。",
  ui_story_1015_10150902_52_dialog_content = "嗯，阿納托利，接下來，你隨時留意薇絲那邊的頻段變化。",
  ui_story_1015_10150902_53_dialog_content = "是，阿納托利遵命。",
  ui_story_1015_10150902_54_dialog_content = "我們來整理一下營救計畫。",
  ui_story_1015_10150902_55_dialog_content = "我這邊的資訊顯示，尤利西斯教授的檔案館剛才被觸發了預警系統。",
  ui_story_1015_10150902_56_dialog_content = "毫無疑問，是吞羅就在那裡。PlayerName就在他身邊。",
  ui_story_1015_10150902_57_dialog_content = "只要我們再找到薇絲的位置，營救計畫就可以正式開始。",
  ui_story_1015_10151001_1_dialog_content = "我不要緊，薇絲！我現在和吞羅在X地下城的某一間檔案庫！",
  ui_story_1015_10151001_2_dialog_content = "妳呢？妳有沒有受傷，妳在什麼位置？！",
  ui_story_1015_10151001_3_dialog_content = "<anim type=Shake>我在……門……光……</anim>",
  ui_story_1015_10151001_4_dialog_content = "喂？妳說什麼，薇絲？",
  ui_story_1015_10151001_5_dialog_content = "糟了，為什麼聽不清楚，對講機又沒電了嗎？",
  ui_story_1015_10151001_6_dialog_content = "<color=#e8d9bb>嗶——</color>",
  ui_story_1015_10151001_7_dialog_content = "通話結束，你問了不該問的問題。",
  ui_story_1015_10151001_8_dialog_content = "妳又沒提前說明，我當然要問我最想知道的了！",
  ui_story_1015_10151001_9_dialog_content = "這麼著急地把對講機關掉，妳到底在心虛什麼？",
  ui_story_1015_10151001_10_dialog_content = "別誤會，不是我關的。",
  ui_story_1015_10151001_11_dialog_content = "是這個破機器的電池沒電了。",
  ui_story_1015_10151001_12_dialog_content = "（還真是……）",
  ui_story_1015_10151001_13_dialog_content = "（煩死了，偏偏是在這種關鍵時候……）",
  ui_story_1015_10151001_14_dialog_content = "行了，別再耽誤時間了。",
  ui_story_1015_10151001_15_dialog_content = "準備走吧，新的實驗還在等著進行。",
  ui_story_1015_10151001_16_dialog_content = "這裡是除了尤利西斯教授之外幾乎沒有人涉足的園區。",
  ui_story_1015_10151001_17_dialog_content = "標誌性建築只有兩座，除了傳出警報的檔案館之外，還有一座是實驗室。",
  ui_story_1015_10151001_18_dialog_content = "不愧是鶯歌中校……我雖然在委員會工作已久，也還是對這個地方一無所知。",
  ui_story_1015_10151001_19_dialog_content = "當成密報處理就好，教授不喜歡這裡被太多人知道。",
  ui_story_1015_10151001_20_dialog_content = "所以，任何擅自闖入這裡的人，我會不留情面地驅逐。",
  ui_story_1015_10151001_21_dialog_content = "薇絲的頻段有動靜嗎？",
  ui_story_1015_10151001_22_dialog_content = "暫時沒有了，聽不到任何對講的電流聲，應該是她那邊的通話被切斷了。",
  ui_story_1015_10151001_23_dialog_content = "拿給我——",
  ui_story_1015_10151001_24_dialog_content = "薇絲中尉？呼叫薇絲，這裡是鶯歌，聽得到我說話嗎？",
  ui_story_1015_10151001_25_dialog_content = "方便通話的話，請立即與我聯絡！",
  ui_story_1015_10151001_26_dialog_content = "喂！妳這樣子，薇絲對面的人不也會聽到妳的聲音嗎！",
  ui_story_1015_10151001_27_dialog_content = "正常來說是這樣的。但是現在，吞羅的對講機已經沒電了。",
  ui_story_1015_10151001_28_dialog_content = "沒電？！",
  ui_story_1015_10151001_29_dialog_content = "我一直在監聽他們的對話。PlayerName對講機使用得太過頻繁，耗電非常迅速。",
  ui_story_1015_10151001_30_dialog_content = "從剛才的聲音來看，現在已經到了徹底沒電的時候。",
  ui_story_1015_10151001_31_dialog_content = "成敗就在這個瞬間。",
  ui_story_1015_10151001_32_dialog_content = "是……是鶯歌中校？",
  ui_story_1015_10151001_33_dialog_content = "（太好了！）",
  ui_story_1015_10151001_34_dialog_content = "報出妳的所在位置！",
  ui_story_1015_10151001_35_dialog_content = "身邊有什麼明顯的特徵也好！",
  ui_story_1015_10151001_36_dialog_content = "是！我被關在X地下城的一處倉庫，灰色門，倉庫有窗且有自然光！",
  ui_story_1015_10151001_37_dialog_content = "收到。",
  ui_story_1015_10151001_38_dialog_content = "我會一直待在這個頻段，妳注意維持好電量，即使吞羅再跟妳聯絡我也能聽得到。",
  ui_story_1015_10151001_39_dialog_content = "妳這邊還有什麼人？",
  ui_story_1015_10151001_40_dialog_content = "是赫利俄斯帶著我過來的，但他剛才也離開了。",
  ui_story_1015_10151001_41_dialog_content = "明白。我們立刻就去。",
  ui_story_1015_10151001_42_dialog_content = "鶯歌中校，您已經有頭緒了？",
  ui_story_1015_10151001_43_dialog_content = "X城的倉庫集中在南部，因為南部的地形低，易守難攻。",
  ui_story_1015_10151001_44_dialog_content = "其中，灰色的大門是專門用於儲存各類固體藥品的庫房。",
  ui_story_1015_10151001_45_dialog_content = "剛才薇絲說話的回聲很大，所以一定是處在大型倉庫裡。",
  ui_story_1015_10151001_46_dialog_content = "排除掉所有地下庫房，和各種零零散散的小型儲藏室……",
  ui_story_1015_10151001_47_dialog_content = "薇絲所在的範圍可以縮小到X-106、X-107和X-108號倉庫。",
  ui_story_1015_10151001_48_dialog_content = "那就立刻動身吧。",
  ui_story_1015_10151001_49_dialog_content = "我和阿納托利過去。卡蓮，我想拜託妳另一件事。",
  ui_story_1015_10151001_50_dialog_content = "我希望妳能去檔案館營救PlayerName。",
  ui_story_1015_10151001_51_dialog_content = "為了確保兩個人質的安全，營救最好同時完成。",
  ui_story_1015_10151001_52_dialog_content = "原來如此，我明白了。",
  ui_story_1015_10151001_53_dialog_content = "嗯，我們這邊營救完成後會立刻去支援妳。",
  ui_story_1015_10151001_54_dialog_content = "請一定要小心。",
  ui_story_1015_10151001_55_dialog_content = "<color=#e8d9bb>X地下城 南部倉庫</color>",
  ui_story_1015_10151001_56_dialog_content = "果然和鶯歌中校預測得一樣。",
  ui_story_1015_10151001_57_dialog_content = "看這附近的特徵，我們找對地方了。",
  ui_story_1015_10151001_58_dialog_content = "鶯歌中校，下一步我們應該怎麼辦？",
  ui_story_1015_10151001_59_dialog_content = "只能一個一個試了。",
  ui_story_1015_10151001_60_dialog_content = "好在吞羅那邊也還沒有更進一步的動作……",
  ui_story_1015_10151001_61_dialog_content = "<color=#e8d9bb>咚——！</color>",
  ui_story_1015_10151001_62_dialog_content = "<anim type=Shake><size=50>吼！！！</size></anim>",
  ui_story_1015_10151001_63_dialog_content = "什、什麼東西……",
  ui_story_1015_10151001_64_dialog_content = "（我們的行動被他察覺到了……！）",
  ui_story_1015_10151001_65_dialog_content = "<anim type=Shake><size=50>吼！！！</size></anim>",
  ui_story_1015_10151001_66_dialog_content = "小心！他撲過來了！",
  ui_story_1015_10151101_1_dialog_content = "<color=#e8d9bb>轟隆——！！！</color>",
  ui_story_1015_10151101_2_dialog_content = "完美的一擊！",
  ui_story_1015_10151101_3_dialog_content = "<anim type=Shake><size=50>吼——！！！</size></anim>",
  ui_story_1015_10151101_4_dialog_content = "這傢伙究竟是怎麼回事？！",
  ui_story_1015_10151101_5_dialog_content = "情報上說，萊因哈特大元帥已經在上次的遭遇中對牠造成了重創……",
  ui_story_1015_10151101_6_dialog_content = "為什麼牠還能保持這麼強的戰鬥力？",
  ui_story_1015_10151101_7_dialog_content = "<anim type=Shake><size=50>吼！</size></anim>",
  ui_story_1015_10151101_8_dialog_content = "小心！",
  ui_story_1015_10151101_9_dialog_content = "呃……！",
  ui_story_1015_10151101_10_dialog_content = "謝謝……",
  ui_story_1015_10151101_11_dialog_content = "不可以過分依賴情報，鶯歌中校，畢竟情報也有著失準的可能性。",
  ui_story_1015_10151101_12_dialog_content = "如果那些情報說的是真的，那麼牠……",
  ui_story_1015_10151101_13_dialog_content = "不，他，赫利俄斯上尉很可能在意識不清的情況下，獨自在暗面生存了十餘年。",
  ui_story_1015_10151101_14_dialog_content = "能有這種力量，本來就不可以輕視。",
  ui_story_1015_10151101_15_dialog_content = "更何況他還和萊因哈特大元帥一樣，是經受過改造強化的個體……",
  ui_story_1015_10151101_16_dialog_content = "就算我們兩個加起來，恐怕也沒有大元帥的一半強。",
  ui_story_1015_10151101_17_dialog_content = "這種事情我知道，不用你說，阿納托利少校。",
  ui_story_1015_10151101_18_dialog_content = "這裡太開闊，牠的機動性又遠強於我們。再和牠糾纏下去，只會被耗盡力氣！",
  ui_story_1015_10151101_19_dialog_content = "我們撤回到走廊，限制住牠的行動。",
  ui_story_1015_10151101_20_dialog_content = "明白！",
  ui_story_1015_10151101_21_dialog_content = "<anim type=Shake>吼……</anim>",
  ui_story_1015_10151101_22_dialog_content = "……",
  ui_story_1015_10151101_23_dialog_content = "他走遠了。",
  ui_story_1015_10151101_24_dialog_content = "我們不能跟牠正面交鋒，但可以利用這裡的地形發動針對弱點的突襲。",
  ui_story_1015_10151101_25_dialog_content = "只要吞羅不——",
  ui_story_1015_10151101_26_dialog_content = "不對……",
  ui_story_1015_10151101_27_dialog_content = "<size=45>不好了！</size>",
  ui_story_1015_10151101_28_dialog_content = "怎麼了？",
  ui_story_1015_10151101_29_dialog_content = "經過強化改造的光靈，互相之間會形成特殊的感應。",
  ui_story_1015_10151101_30_dialog_content = "我們在這裡與那傢伙發生衝突，恐怕會被吞羅感應到！",
  ui_story_1015_10151101_31_dialog_content = "……！",
  ui_story_1015_10151101_32_dialog_content = "這麼重要的情報，為什麼不提前告知我？",
  ui_story_1015_10151101_33_dialog_content = "那項實驗計畫本來就是高度保密的。",
  ui_story_1015_10151101_34_dialog_content = "如果不是因為情況緊急，關於實驗的任何資訊，都不是以你我的職權能夠得知的。",
  ui_story_1015_10151101_35_dialog_content = "抱歉，這是我的失誤，關於這則情報，是我沒有及時同步。",
  ui_story_1015_10151101_36_dialog_content = "這下麻煩了……",
  ui_story_1015_10151101_37_dialog_content = "（委員會……你們究竟還隱藏著多少祕密？）",
  ui_story_1015_10151101_38_dialog_content = "（不管是關於人體改造，還是當年我所在的隊伍拼死帶回的情報被篡改的事……）",
  ui_story_1015_10151101_39_dialog_content = "（他們真的值得信任嗎？）",
  ui_story_1015_10151101_40_dialog_content = "我們不能繼續在這裡和牠耗下去。",
  ui_story_1015_10151101_41_dialog_content = "假設吞羅已經察覺到了我們的行動，不可能不有所提防。",
  ui_story_1015_10151101_42_dialog_content = "薇絲中尉暫時還安全，但卡蓮肯定還不知道自己暴露的事。",
  ui_story_1015_10151101_43_dialog_content = "我們要趕快甩掉他，去支援卡蓮。",
  ui_story_1015_10151101_44_dialog_content = "當然，不過我們不能一起行動。",
  ui_story_1015_10151101_45_dialog_content = "你擅長潛行，先找機會避開那傢伙，救出薇絲中尉，然後趕快與卡蓮會合。",
  ui_story_1015_10151101_46_dialog_content = "那妳呢？妳要做什麼？",
  ui_story_1015_10151101_47_dialog_content = "吞羅只會比這裡這隻怪物更難對付，就算多了我們兩個，勝算也微乎其微。",
  ui_story_1015_10151101_48_dialog_content = "我要去準備一張足夠讓她妥協的底牌。",
  ui_story_1015_10151101_49_dialog_content = "<color=#e8d9bb>與此同時，PlayerName與吞羅所在處</color>",
  ui_story_1015_10151101_50_dialog_content = "……",
  ui_story_1015_10151101_51_dialog_content = "<anim type=Shake>吼，吼——</anim>",
  ui_story_1015_10151101_52_dialog_content = "安靜點，玉子。",
  ui_story_1015_10151101_53_dialog_content = "<anim type=Shake>吼……</anim>",
  ui_story_1015_10151101_54_dialog_content = "很吵。",
  ui_story_1015_10151101_55_dialog_content = "是滿吵的，這隻大傢伙的聲音快把我的耳膜都震破了。",
  ui_story_1015_10151101_56_dialog_content = "閉嘴。",
  ui_story_1015_10151101_57_dialog_content = "這裡有老鼠的動靜。",
  ui_story_1015_10151101_58_dialog_content = "老鼠？",
  ui_story_1015_10151101_59_dialog_content = "（這股光能，難道是……）",
  ui_story_1015_10151101_60_option_content = "感應",
  ui_story_1015_10151101_61_dialog_content = "（是卡蓮？！）",
  ui_story_1015_10151101_62_dialog_content = "出來。",
  ui_story_1015_10151101_63_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_1015_10151101_64_dialog_content = "愚蠢。",
  ui_story_1015_10151101_65_dialog_content = "<size=45>（卡蓮，危險！！！）</size>",
  ui_story_1015_10151101_66_dialog_content = "（什……）",
  ui_story_1015_10151101_67_dialog_content = "<color=#e8d9bb>轟！！！</color>",
  ui_story_1015_10151101_68_dialog_content = "噗……咳咳！！！",
  ui_story_1015_10151101_69_dialog_content = "妳是……怎麼發現的？",
  ui_story_1015_10151101_70_dialog_content = "你們的戰術只能用拙劣形容。",
  ui_story_1015_10151101_71_dialog_content = "……",
  ui_story_1015_10151101_72_dialog_content = "但是，作為影響實驗結果的因素，你們還是值得我動手排除的。",
  ui_story_1015_10151101_73_dialog_content = "<anim type=Shake>吼……</anim>",
  ui_story_1015_10151101_74_dialog_content = "這個數量……",
  ui_story_1015_10151101_75_dialog_content = "上吧。",
  ui_story_1015_10151101_76_dialog_content = "<anim type=Shake><size=50>吼！！！</size></anim>",
  ui_story_1015_10151102_1_dialog_content = "呃……！！！",
  ui_story_1015_10151102_2_dialog_content = "<anim type=Shake><size=45>吼——！</size></anim>",
  ui_story_1015_10151102_3_dialog_content = "沒完沒了的……",
  ui_story_1015_10151102_4_dialog_content = "卡蓮！！！",
  ui_story_1015_10151102_5_dialog_content = "你們是想兵分兩路，同時帶走空裔和那個小丫頭對吧。",
  ui_story_1015_10151102_6_dialog_content = "但是，兵分兩路的前提是，對自己的實力有著絕對的信心。",
  ui_story_1015_10151102_7_dialog_content = "妳是怎麼發現的？",
  ui_story_1015_10151102_8_dialog_content = "這就要歸功於那些老東西的計畫了。",
  ui_story_1015_10151102_9_dialog_content = "難道說是之前萊因哈特提到過的、他們之間的特殊感應？",
  ui_story_1015_10151102_10_dialog_content = "糟了，如果有這種能力，那鶯歌那邊也——",
  ui_story_1015_10151102_11_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_1015_10151102_12_dialog_content = "咳……咳咳咳！",
  ui_story_1015_10151102_13_dialog_content = "這裡是……",
  ui_story_1015_10151102_14_dialog_content = "<anim type=Shake>吼……</anim>",
  ui_story_1015_10151102_15_dialog_content = "又是一隻老鼠。",
  ui_story_1015_10151102_16_dialog_content = "阿納托利！你是怎麼到這裡來的？",
  ui_story_1015_10151102_17_dialog_content = "薇絲呢？",
  ui_story_1015_10151102_18_dialog_content = "抱歉……我被發現了，沒能找到他們藏匿薇絲中尉的地方，還沒救出她……",
  ui_story_1015_10151102_19_dialog_content = "看來你們有的只是傲慢和無能。",
  ui_story_1015_10151102_20_dialog_content = "我要做的事情馬上就能完成，你們已經沒用了。",
  ui_story_1015_10151102_21_dialog_content = "……",
  ui_story_1015_10151102_22_dialog_content = "糟了！",
  ui_story_1015_10151102_23_dialog_content = "竟然在這裡被包圍了……",
  ui_story_1015_10151102_24_dialog_content = "撐住，PlayerName，卡蓮。",
  ui_story_1015_10151102_25_dialog_content = "別忘了，還有鶯歌中校。",
  ui_story_1015_10151102_26_dialog_content = "去吧，解決掉——",
  ui_story_1015_10151102_27_dialog_content = "<color=#e8d9bb>嘶啦——</color>",
  ui_story_1015_10151102_28_dialog_content = "吞羅，妳聽得見吧。",
  ui_story_1015_10151102_29_dialog_content = "我剛才還在想，怎麼少了一隻老鼠。",
  ui_story_1015_10151102_30_dialog_content = "原來是躲到遠處去了。",
  ui_story_1015_10151102_31_dialog_content = "不管妳想做什麼，都立刻停下。",
  ui_story_1015_10151102_32_dialog_content = "否則妳一定會後悔的。",
  ui_story_1015_10151102_33_dialog_content = "……",
  ui_story_1015_10151102_34_dialog_content = "妳做了什麼？",
  ui_story_1015_10151102_35_dialog_content = "多虧兩位努力爭取時間，我才能趁這段時間在和弦紐帶實驗室周圍放滿<color=#FFB400>炸藥</color>。",
  ui_story_1015_10151102_36_dialog_content = "我的槍現在已經瞄準了炸藥桶，只要我扣下扳機，和弦紐帶就會連著資料一起葬身火海。",
  ui_story_1015_10151102_37_dialog_content = "？！",
  ui_story_1015_10151102_38_dialog_content = "妳應該很熟悉這副場景吧，「吞羅」？",
  ui_story_1015_10151102_39_dialog_content = "現在，立刻投降，放了PlayerName他們。",
  ui_story_1015_10151102_40_dialog_content = "……",
  ui_story_1015_10151102_41_dialog_content = "<size=45>火……著火了……！</size>",
  ui_story_1015_10151102_42_dialog_content = "<size=45>我的實驗！實驗！！！</size>",
  ui_story_1015_10151102_43_dialog_content = "呵。",
  ui_story_1015_10151102_44_dialog_content = "那群老東西沒什麼研究天賦，倒是挺擅長訓狗的。",
  ui_story_1015_10151102_45_dialog_content = "妳！",
  ui_story_1015_10151102_46_dialog_content = "妳不敢。",
  ui_story_1015_10151102_47_dialog_content = "和弦紐帶裝置是遠古空裔的技術結晶，不是隨隨便便就能在路邊撿到的。",
  ui_story_1015_10151102_48_dialog_content = "整個啟光聯邦也只有這麼一台。",
  ui_story_1015_10151102_49_dialog_content = "更別提那些儲存在機器裡的資料，整個啟明星計畫恐怕也只是其中的一小部分呢。",
  ui_story_1015_10151102_50_dialog_content = "身為他們的狗，妳不可能不知道這件事吧。",
  ui_story_1015_10151102_51_dialog_content = "如果讓那群老東西把和弦紐帶和資料放在天秤上衡量，你們連當砝碼的資格都沒有。",
  ui_story_1015_10151102_52_dialog_content = "是嗎？",
  ui_story_1015_10151102_53_dialog_content = "那就試試看吧。",
  ui_story_1015_10151102_54_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_1015_10151201_1_dialog_content = "<color=#e8d9bb>轟——！！！</color>",
  ui_story_1015_10151201_2_dialog_content = "火……",
  ui_story_1015_10151201_3_dialog_content = "著火了……",
  ui_story_1015_10151201_4_dialog_content = "赫利俄斯，跟我去實驗室！",
  ui_story_1015_10151201_5_dialog_content = "<anim type=Shake><size=45>吼——</size></anim>",
  ui_story_1015_10151201_6_dialog_content = "好機會！",
  ui_story_1015_10151201_7_dialog_content = "散開吧，冰花！",
  ui_story_1015_10151201_8_dialog_content = "小心，暗鬼又圍上來了！",
  ui_story_1015_10151201_9_dialog_content = "<anim type=Shake><size=45>吼！！！</size></anim>",
  ui_story_1015_10151201_10_dialog_content = "<color=#e8d9bb>砰！砰砰——！</color>",
  ui_story_1015_10151201_11_dialog_content = "<anim type=Shake>嘎嗷……</anim>",
  ui_story_1015_10151201_12_dialog_content = "趁現在，去救PlayerName！",
  ui_story_1015_10151201_13_dialog_content = "是！",
  ui_story_1015_10151201_14_dialog_content = "PlayerName，我來幫你鬆綁！",
  ui_story_1015_10151201_15_dialog_content = "謝謝……",
  ui_story_1015_10151201_16_dialog_content = "薇絲沒事吧？她到底在哪裡？",
  ui_story_1015_10151201_17_dialog_content = "抱歉，當時我被敵人發現，沒能找到薇絲中尉……",
  ui_story_1015_10151201_18_dialog_content = "但是那片區域並沒有其他敵人，因此薇絲中尉的安全可以保證。",
  ui_story_1015_10151201_19_dialog_content = "放心吧，薇絲已經有別的人去救了。",
  ui_story_1015_10151201_20_dialog_content = "你們現在要做的，就是阻止吞羅完成實驗。",
  ui_story_1015_10151201_21_dialog_content = "妳果然沒有毀掉和弦紐帶。",
  ui_story_1015_10151201_22_dialog_content = "什麼？沒有毀掉嗎？！",
  ui_story_1015_10151201_23_dialog_content = "那種東西怎麼可能輕易毀掉。",
  ui_story_1015_10151201_24_dialog_content = "如果真的毀掉了，鶯歌中校還不知道要被軍事法庭審判幾百回。",
  ui_story_1015_10151201_25_dialog_content = "好了，別說了。",
  ui_story_1015_10151201_26_dialog_content = "讓我們清理掉這些暗鬼，阻止吞羅吧！",
  ui_story_1015_10151201_27_dialog_content = "正合我意！",
  ui_story_1015_10151202_1_dialog_content = "<color=#e8d9bb>若干年前，X號地下城</color>",
  ui_story_1015_10151202_2_dialog_content = "實驗……我的實驗！",
  ui_story_1015_10151202_3_dialog_content = "資料和實驗材料還都在裡面，得把它們都拿走。",
  ui_story_1015_10151202_4_dialog_content = "<anim type=Shake><size=45>吱——！吱吱——！</size></anim>",
  ui_story_1015_10151202_5_dialog_content = "玉子，到我外套裡來，我們必須要回去！",
  ui_story_1015_10151202_6_dialog_content = "<anim type=Shake><size=45>吱！</size></anim>",
  ui_story_1015_10151202_7_dialog_content = "得趕緊回收實驗資料……",
  ui_story_1015_10151202_8_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_1015_10151202_9_dialog_content = "呃！！！",
  ui_story_1015_10151202_10_dialog_content = "該死，沒想到竟然引發了這麼嚴重的火災……",
  ui_story_1015_10151202_11_dialog_content = "僅憑地下城原有的消防設施，恐怕沒辦法撲滅這場大火。",
  ui_story_1015_10151202_12_dialog_content = "難道，我已經不得不向那個人求援了嗎……",
  ui_story_1015_10151202_13_dialog_content = "<color=#e8d9bb>嗡——嗡——</color>",
  ui_story_1015_10151202_14_dialog_content = "那場大火，幾乎毀了我所有的研究成果。",
  ui_story_1015_10151202_15_dialog_content = "決不能讓它重演！",
  ui_story_1015_10151202_16_dialog_content = "這是……",
  ui_story_1015_10151202_17_dialog_content = "（和弦紐帶裝置的實驗室裡，一點火星都沒有……）",
  ui_story_1015_10151202_18_dialog_content = "（這些撒水龍頭，難道是那些老東西在我離開後裝的？）",
  ui_story_1015_10151202_19_dialog_content = "看來那場大火不僅提醒了我，也提醒了老傢伙們。",
  ui_story_1015_10151202_20_dialog_content = "不過……",
  ui_story_1015_10151202_21_dialog_content = "<color=#e8d9bb>嘶啦——</color>",
  ui_story_1015_10151202_22_dialog_content = "放棄抵抗吧，吞羅。",
  ui_story_1015_10151202_23_dialog_content = "人質都已經安全，妳最後的籌碼已經不復存在了。",
  ui_story_1015_10151202_24_dialog_content = "利用這種把戲誘導我離開，這就是妳的計畫？",
  ui_story_1015_10151202_25_dialog_content = "沒錯，但這不僅是把戲。",
  ui_story_1015_10151202_26_dialog_content = "我知道，用假道具是騙不了妳的，所以放置在實驗室周圍的炸藥桶都是真的。",
  ui_story_1015_10151202_27_dialog_content = "只是妳不知道，自從那次火災過後，大元帥就下令升級了這座地下城所有的消防設施。",
  ui_story_1015_10151202_28_dialog_content = "不僅設置了超過通常數量兩倍的滅火器和灑水龍頭，連牆壁都用防爆阻燃的材料加固過。",
  ui_story_1015_10151202_29_dialog_content = "原來是她。",
  ui_story_1015_10151202_30_dialog_content = "她倒是做了不少事，只可惜，都是些無用功和絆腳石。",
  ui_story_1015_10151202_31_dialog_content = "……",
  ui_story_1015_10151202_32_dialog_content = "妳怎麼不說話了？",
  ui_story_1015_10151202_33_dialog_content = "是不是還對當年那場火災心懷怨恨？",
  ui_story_1015_10151202_34_dialog_content = "但妳難道不想知道，當年的實情是怎麼回事嗎？",
  ui_story_1015_10151202_35_dialog_content = "說。",
  ui_story_1015_10151202_36_dialog_content = "當年妳發出求救訊號後，萊因哈特大元帥第一時間就對X號地下城進行了救援。",
  ui_story_1015_10151202_37_dialog_content = "只是由於火勢太過兇猛，在救援隊到達時，地下城就已經被濃煙充斥。",
  ui_story_1015_10151202_38_dialog_content = "就算是那樣，大元帥依舊第一個衝進火場，在惡劣的環境中找妳找了好幾個小時。",
  ui_story_1015_10151202_39_dialog_content = "我聽那時的救援人員說，大元帥出來的時候，身上全是被煙燻和火燒的痕跡，衣服都爛掉了。",
  ui_story_1015_10151202_40_dialog_content = "但她顧不上傷痛，她只懊悔自己沒能找到重要的妹妹。",
  ui_story_1015_10151202_41_dialog_content = "……",
  ui_story_1015_10151202_42_dialog_content = "所以，妳也知道了吧。",
  ui_story_1015_10151202_43_dialog_content = "當年萊因哈特大元帥並沒有放棄妳，任何人都沒有放棄妳。",
  ui_story_1015_10151202_44_dialog_content = "倒是妳自己，一廂情願地認為自己被人放棄，轉頭投奔了那群罪孽深重的暗鬼。",
  ui_story_1015_10151202_45_dialog_content = "妳這麼多年以來所做的事情，不就是為了報復那些曾經「放棄」了妳的人嗎？",
  ui_story_1015_10151202_46_dialog_content = "現在妳也知道了，如果不是妳主動離開，根本就沒有人想放棄妳。",
  ui_story_1015_10151202_47_dialog_content = "妳的報復，從最開始就是個偽命題！",
  ui_story_1015_10151202_48_dialog_content = "束手就擒吧，妳已經沒有與啟光敵對的理由，也沒有退路了。",
  ui_story_1015_10151202_49_dialog_content = "呵。",
  ui_story_1015_10151202_50_dialog_content = "那些老東西的惡趣味這麼多年來真是一點都沒變。",
  ui_story_1015_10151202_51_dialog_content = "他們還是那麼喜歡愚蠢得恰到好處的狗。",
  ui_story_1015_10151202_52_dialog_content = "……",
  ui_story_1015_10151202_53_dialog_content = "難道妳認為，我之所以選擇離開啟光，是因為感到被背叛這種無聊的理由？",
  ui_story_1015_10151202_54_dialog_content = "妳徹徹底底地錯了。",
  ui_story_1015_10151202_55_dialog_content = "那妳為什麼會背叛啟光？",
  ui_story_1015_10151202_56_dialog_content = "我離開的理由很簡單。",
  ui_story_1015_10151202_57_dialog_content = "啟光聯邦能夠提供給我進行科學研究的環境，已經不足以支撐我繼續進行更深入的研究了。",
  ui_story_1015_10151202_58_dialog_content = "不管是可供研究的對象，還是能夠用於研究的素材，都已經不能為我的研究帶來新的突破。",
  ui_story_1015_10151202_59_dialog_content = "所以我選擇離開，因為日蝕掌握的技術裡，有著讓研究突破的可能性。",
  ui_story_1015_10151202_60_dialog_content = "僅此而已。",
  ui_story_1015_10151202_61_dialog_content = "<color=#e8d9bb>與此同時，地下城的某處</color>",
  ui_story_1015_10151202_62_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_1015_10151202_63_dialog_content = "時間剛剛好。",
  ui_story_1015_10151202_64_dialog_content = "她的計畫一向精準無誤。",
  ui_story_1015_10151202_65_dialog_content = "<color=#e8d9bb>嘶啦——</color>",
  ui_story_1015_10151202_66_dialog_content = "是時候了，讓「<color=#FFB400>清道夫</color>」出場吧。",
  ui_story_1015_10151301_1_dialog_content = "<color=#e8d9bb>嗡——嗡——</color>",
  ui_story_1015_10151301_2_dialog_content = "真是吵鬧。",
  ui_story_1015_10151301_3_dialog_content = "什麼？",
  ui_story_1015_10151301_4_dialog_content = "我本來還以為，妳多少能比那幾隻老鼠強一些。",
  ui_story_1015_10151301_5_dialog_content = "現在看起來，妳也不過如此。",
  ui_story_1015_10151301_6_dialog_content = "斷電。",
  ui_story_1015_10151301_7_dialog_content = "不好，保護電源！",
  ui_story_1015_10151301_8_dialog_content = "<anim type=Shake><size=45>嘎嗷！</size></anim>",
  ui_story_1015_10151301_9_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_1015_10151301_10_dialog_content = "該死……這座地下城的大門控制系統是和電力系統是綁在一起的。",
  ui_story_1015_10151301_11_dialog_content = "一旦斷電，大門就會關閉。",
  ui_story_1015_10151301_12_dialog_content = "那扇門後面是出口嗎？",
  ui_story_1015_10151301_13_dialog_content = "不，那是……比出口更麻煩的東西。",
  ui_story_1015_10151301_14_dialog_content = "究竟是什麼？",
  ui_story_1015_10151301_15_dialog_content = "<color=#e8d9bb>撕拉——</color>",
  ui_story_1015_10151301_16_dialog_content = "讓我來告訴你答案吧。",
  ui_story_1015_10151301_17_dialog_content = "這裡面的東西是和弦紐帶裝置。",
  ui_story_1015_10151301_19_dialog_content = "不管妳想做什麼，都趕快停下！",
  ui_story_1015_10151301_20_dialog_content = "那台裝置並不完整，貿然使用有著巨大的隱患！",
  ui_story_1015_10151301_21_dialog_content = "我承認，妳的情報很靈通。",
  ui_story_1015_10151301_22_dialog_content = "但別忘了，小老鼠。",
  ui_story_1015_10151301_23_dialog_content = "妳並不是研究員，對這台機器的認知，也全都來自於那個老頭子。",
  ui_story_1015_10151301_24_dialog_content = "而妳之所以認為這台機器有隱患，也只是因為——",
  ui_story_1015_10151301_25_dialog_content = "你們根本不知道該如何使用它。",
  ui_story_1015_10151301_26_dialog_content = "<color=#e8d9bb>喀——</color>",
  ui_story_1015_10151301_27_dialog_content = "實驗的干擾已經排除，讓我們繼續吧。",
  ui_story_1015_10151301_28_dialog_content = "過來，實驗體。",
  ui_story_1015_10151301_29_dialog_content = "……",
  ui_story_1015_10151301_30_dialog_content = "<color=#e8d9bb>與此同時，迦南城</color>",
  ui_story_1015_10151301_31_dialog_content = "<color=#e8d9bb>嘶啦——！</color>",
  ui_story_1015_10151301_32_dialog_content = "雷霆軍團長，有緊急任務，收到請回答！",
  ui_story_1015_10151301_33_dialog_content = "緊急任務？這個時間能有什麼緊急任務？",
  ui_story_1015_10151301_34_dialog_content = "是很奇怪，先聽聽看吧。",
  ui_story_1015_10151301_35_dialog_content = "收到，請講。",
  ui_story_1015_10151301_36_dialog_content = "X號地下城疑似遭遇吞羅入侵，委員會命妳立刻進行支援，捉拿吞羅與赫利俄斯。",
  ui_story_1015_10151301_37_dialog_content = "<size=45>什麼？！</size>",
  ui_story_1015_10151301_38_dialog_content = "吞羅？她竟然跑到啟光的地盤上來了……",
  ui_story_1015_10151301_39_dialog_content = "……",
  ui_story_1015_10151301_40_dialog_content = "既然如此，雷霆，我也和妳一起走一趟吧。",
  ui_story_1015_10151301_41_dialog_content = "我就知道妳肯定放不下心。",
  ui_story_1015_10151301_42_dialog_content = "但是妳得向我保證，不會亂來。",
  ui_story_1015_10151301_43_dialog_content = "當然，我向妳保證。這是妳的任務，我不會過多干涉。",
  ui_story_1015_10151301_44_dialog_content = "好，那就跟我一起走吧。",
  ui_story_1015_10151302_1_dialog_content = "<color=#e8d9bb>咚咚咚。</color>",
  ui_story_1015_10151302_2_dialog_content = "進來。",
  ui_story_1015_10151302_3_dialog_content = "呼，呼……報告！",
  ui_story_1015_10151302_4_dialog_content = "長官，按照我們的計畫，雷霆已經向這邊趕來，預計一小時後到達。",
  ui_story_1015_10151302_5_dialog_content = "但是情況有一些變化，萊因哈特也一起跟來了。",
  ui_story_1015_10151302_6_dialog_content = "哦？",
  ui_story_1015_10151302_7_dialog_content = "沒關係，這是預料之中的事情。",
  ui_story_1015_10151302_8_dialog_content = "這也是您的計畫？",
  ui_story_1015_10151302_9_dialog_content = "呵呵，這可不是我的計畫。",
  ui_story_1015_10151302_10_dialog_content = "但和弦紐帶實驗室升起的黑煙……",
  ui_story_1015_10151302_11_dialog_content = "不用在意那些火，我透過監控看到了，它們燒不起來的。",
  ui_story_1015_10151302_12_dialog_content = "坐下來喝點水吧。之後的事，只需要我們坐在觀眾席上看著就好。",
  ui_story_1015_10151302_13_dialog_content = "是。",
  ui_story_1015_10151302_14_dialog_content = "難怪我和那個人玩抽牌遊戲的時候，怎麼都贏不了。",
  ui_story_1015_10151302_15_dialog_content = "原來她已經把人心都摸透了。",
  ui_story_1015_10151302_16_dialog_content = "德尼耶爾，不，吞羅，還真是令人羡慕啊。",
  ui_story_1015_10151302_17_dialog_content = "……？",
  ui_story_1015_10151302_18_dialog_content = "你不羡慕她嗎？",
  ui_story_1015_10151302_19_dialog_content = "長官，我……",
  ui_story_1015_10151302_20_dialog_content = "也是。你不是研究員，不羡慕她也正常。",
  ui_story_1015_10151302_21_dialog_content = "……",
  ui_story_1015_10151302_22_dialog_content = "你是不是在想，她身上究竟有哪一點值得羡慕？",
  ui_story_1015_10151302_23_dialog_content = "是。",
  ui_story_1015_10151302_24_dialog_content = "她擁有最適合當研究員的優秀品格。",
  ui_story_1015_10151302_25_dialog_content = "執著？",
  ui_story_1015_10151302_26_dialog_content = "是冷酷。",
  ui_story_1015_10151302_27_dialog_content = "啟光有一句老話是這麼說的——",
  ui_story_1015_10151302_28_dialog_content = "「科學技術是沒有善惡之分的，但是使用它的光靈有善惡之分。」",
  ui_story_1015_10151302_29_dialog_content = "只不過很多時候，想要研發一項新的技術，就不得不先成為一個「惡人」。",
  ui_story_1015_10151302_30_dialog_content = "這個世界上並不是總有兩全其美的辦法，吞羅深知這一點，而她也深知這一點。",
  ui_story_1015_10151302_31_dialog_content = "為了獲得研究成果，她能毫不猶豫地將自己曾經的戰友當做實驗體。",
  ui_story_1015_10151302_32_dialog_content = "這就是最好的證明。",
  ui_story_1015_10151302_33_dialog_content = "但這難道不是她被逼無奈的選擇嗎？",
  ui_story_1015_10151302_34_dialog_content = "不不不，我們並沒有逼她。",
  ui_story_1015_10151302_35_dialog_content = "我們所做的，只是為她創造了帶有一點點限制、卻無比適合的機會。",
  ui_story_1015_10151302_36_dialog_content = "而抓住這機會，完完全全是她自己的決定。",
  ui_story_1015_10151302_37_dialog_content = "她的研究一直沒有偏離這場試驗的本質——用科學的方式去探索生物可能性的極限。",
  ui_story_1015_10151302_38_dialog_content = "從最初的「人造太陽」計畫那時就是如此。",
  ui_story_1015_10151302_39_dialog_content = "你應該知道吧？那是「啟明星」計畫的前身。",
  ui_story_1015_10151302_40_dialog_content = "它是啟光獨立研發出來的光靈強化技術。但是由於技術不成熟，因此成品並不穩定。",
  ui_story_1015_10151302_41_dialog_content = "單一一種強大的力量在光靈體內不受約束地亂竄，僅能靠強大的意志馴服。",
  ui_story_1015_10151302_42_dialog_content = "這麼做的結果就是不僅成功率極低，實驗體也容易發生力量失控。",
  ui_story_1015_10151302_43_dialog_content = "而失控的結果，不是失去生命，就是終身殘疾，或者是……變成「那種怪物」。",
  ui_story_1015_10151302_44_dialog_content = "可是，過去的德尼耶爾，也就是吞羅，並不屬於上述三種情況。",
  ui_story_1015_10151302_45_dialog_content = "她算是失敗品嗎？",
  ui_story_1015_10151302_46_dialog_content = "嚴格來講，不算。",
  ui_story_1015_10151302_47_dialog_content = "她是成功的個體，只不過，她成功的方向與我們的預期並不相符。",
  ui_story_1015_10151302_48_dialog_content = "我們想要的是力量經過強化的個體，但她卻是在智力上得到了強化。",
  ui_story_1015_10151302_49_dialog_content = "她的成功讓她成為了最富天資的研究員，也讓她成為了啟光最大的隱患。",
  ui_story_1015_10151302_50_dialog_content = "結局你已經看到了，她毫無懸念地成為了叛徒，站在了啟光的對立面。",
  ui_story_1015_10151302_51_dialog_content = "所以，對於整個啟光而言，萊因哈特才是他們那一批「人造太陽」計畫產物中最成功的。",
  ui_story_1015_10151302_52_dialog_content = "但我還有一點，一直以來都不明白。",
  ui_story_1015_10151302_53_dialog_content = "究竟怎麼才能判斷一個經過「人造太陽」計畫改造的光靈有沒有「成功」呢？",
  ui_story_1015_10151302_54_dialog_content = "畢竟不是所有失敗的特徵都能在改造後第一時間表現出來。",
  ui_story_1015_10151302_55_dialog_content = "你還記得發生在80號地下城的那場戰鬥嗎？",
  ui_story_1015_10151302_56_dialog_content = "是的，我記得。",
  ui_story_1015_10151302_57_dialog_content = "當年是我按照委員會的要求修改了傳達給「人造太陽」計畫改造個體隊伍的情報。",
  ui_story_1015_10151302_58_dialog_content = "用那條虛假的情報引導他們進入了暗鬼的包圍圈。",
  ui_story_1015_10151302_59_dialog_content = "我還記得，當時為了獲得足夠準確的情報，折損了不少偵察小隊。",
  ui_story_1015_10151302_60_dialog_content = "我的下屬所在的隊伍也是其中之一，他是那支隊伍裡唯一活下來的那個。",
  ui_story_1015_10151302_61_dialog_content = "哦，我確實記得，是有這麼個人。叫什麼來著？",
  ui_story_1015_10151302_62_dialog_content = "<color=#FFB400>阿納托利</color>。",
  ui_story_1015_10151302_63_dialog_content = "好像是這個名字。我聽說，你不久前還把他調去當萊因哈特的副官了？",
  ui_story_1015_10151302_64_dialog_content = "他知道這件事嗎？更重要的是，讓他去監視萊因哈特的行動，可靠嗎？",
  ui_story_1015_10151302_65_dialog_content = "在收集情報的能力上，我認為他值得信任。",
  ui_story_1015_10151302_66_dialog_content = "而且，這個任務本身就是對他忠誠度的考驗。",
  ui_story_1015_10151302_67_dialog_content = "呵呵，如果你這麼認為的話，那就這麼做吧。",
  ui_story_1015_10151302_68_dialog_content = "好像有點離題了。讓我們回到80號地下城的事吧。",
  ui_story_1015_10151302_69_dialog_content = "那場戰鬥是我們對改造個體的一次「篩選」。",
  ui_story_1015_10151302_70_dialog_content = "刻意引導他們陷入如同絕境一樣的苦戰，讓他們將光能透支到極限，然後……",
  ui_story_1015_10151302_71_dialog_content = "弱小的個體會直接被消滅。",
  ui_story_1015_10151302_72_dialog_content = "精神上有缺陷的、不穩定的個體也會在這種極端情況下失控、最終被剔除。",
  ui_story_1015_10151302_73_dialog_content = "但成功的個體會扛過這場苦戰並活下來。",
  ui_story_1015_10151302_74_dialog_content = "但是……不正是因為成功率極低，所以那項計畫最終才被叫停了嗎？",
  ui_story_1015_10151302_75_dialog_content = "直到啟光獲得了那台不完整的「和弦紐帶」裝置。",
  ui_story_1015_10151302_76_dialog_content = "沒錯，「人造太陽」計畫本來不該被重啟。",
  ui_story_1015_10151302_77_dialog_content = "但那台「和弦紐帶」裝置為它帶來了轉機。",
  ui_story_1015_10151302_78_dialog_content = "「和弦紐帶」裝置是空裔科技的巔峰，也是一種不同於「人造太陽」計畫的全新力量。",
  ui_story_1015_10151302_79_dialog_content = "透過融合這兩種技術，「啟明星」計畫的實驗體們誕生了。",
  ui_story_1015_10151302_80_dialog_content = "經過「啟明星」計畫改造的光靈，體內同時擁有兩種不同技術帶來的力量。",
  ui_story_1015_10151302_81_dialog_content = "這兩種力量互相抗衡，一定程度上提升了強化的成功率。",
  ui_story_1015_10151302_82_dialog_content = "然而，這種抗衡也並不夠穩定，所以經過「啟明星」計畫改造的光靈大部分都非常脆弱。",
  ui_story_1015_10151302_83_dialog_content = "一旦過度使用他們那強大的力量，兩種力量間微妙的平衡很容易就會被打破。",
  ui_story_1015_10151302_84_dialog_content = "而他們的身體，也將隨之土崩瓦解。",
  ui_story_1015_10151302_85_dialog_content = "阿克希亞就是一個很好的例子。",
  ui_story_1015_10151302_86_dialog_content = "但是這一次不同了，吞羅帶來了新的力量，她的研究將會把實驗推向新的高度。",
  ui_story_1015_10151302_87_dialog_content = "您是說……「<color=#FFB400>種子</color>」？",
  ui_story_1015_10151302_88_dialog_content = "正是。",
  ui_story_1015_10151302_89_dialog_content = "吞羅研究了「種子」那麼多年，「種子」早已成為暗鬼一方技術的集大成之作。",
  ui_story_1015_10151302_90_dialog_content = "「種子」的加入會成為最後一塊拼圖，那是只能由吞羅來放上去的東西。",
  ui_story_1015_10151302_91_dialog_content = "最終，三種力量在光靈體內將會成為一個互相制衡的整體，成為穩定的、全新的力量。",
  ui_story_1015_10151302_92_dialog_content = "……！",
  ui_story_1015_10151302_93_dialog_content = "至於這至關重要的第一次實驗結果，就讓我們拭目以待吧。",
  ui_story_1015_10151302_94_dialog_content = "<color=#e8d9bb>與此同時，啟光聯邦和弦紐帶實驗室</color>",
  ui_story_1015_10151302_95_dialog_content = "<color=#e8d9bb>咚——咚！</color>",
  ui_story_1015_10151302_96_dialog_content = "好吵。",
  ui_story_1015_10151302_97_dialog_content = "實驗環境只能算勉強合格，但是，足夠了。",
  ui_story_1015_10151302_98_dialog_content = "進行最後的參數檢查。",
  ui_story_1015_10151302_99_dialog_content = "所有參數準確。",
  ui_story_1015_10151302_100_dialog_content = "是時候加入最後的實驗材料了。",
  ui_story_1015_10151302_101_dialog_content = "實驗開始。",
  ui_story_1015_10151302_102_dialog_content = "「種子」將會指引生命進化的方向。",
  ui_story_1015_10151302_103_dialog_content = "<color=#e8d9bb>和弦紐帶實驗室外</color>",
  ui_story_1015_10151302_104_dialog_content = "冰花，散開！",
  ui_story_1015_10151302_105_dialog_content = "<color=#e8d9bb>咚——！！！</color>",
  ui_story_1015_10151302_106_dialog_content = "承受了一場爆炸和這麼多攻擊，這座大門上竟然連個凹陷都沒有。",
  ui_story_1015_10151302_107_dialog_content = "看來強行突破是行不通了。",
  ui_story_1015_10151302_108_dialog_content = "畢竟在建造的時候使用了最堅固的防爆材料。",
  ui_story_1015_10151302_109_dialog_content = "本來用於防範火災的設施，現在卻成了阻礙。",
  ui_story_1015_10151302_110_dialog_content = "那裡面的和弦紐帶裝置，恐怕是吞羅的實驗必需品。",
  ui_story_1015_10151302_111_dialog_content = "要是放任她胡作非為，之後會更麻煩。",
  ui_story_1015_10151302_112_dialog_content = "是啊，我們必須馬上阻止她！",
  ui_story_1015_10151302_113_dialog_content = "就沒有什麼別的辦法嗎？",
  ui_story_1015_10151302_114_dialog_content = "我想想……",
  ui_story_1015_10151302_115_dialog_content = "或許有一個辦法。",
  ui_story_1015_10151302_116_dialog_content = "是什麼？",
  ui_story_1015_10151302_117_dialog_content = "這座地下城曾經是吞羅的祕密實驗室，每天會有大量失敗的實驗體被廢棄。",
  ui_story_1015_10151302_118_dialog_content = "為了節省時間，她曾修建了一條從實驗室直通底層廢棄物處理室的管道。",
  ui_story_1015_10151302_119_dialog_content = "在地下城重建的時候，這條管道被封在了牆裡，但是並沒有堵死。",
  ui_story_1015_10151302_120_dialog_content = "雖然要繞一些路，但破開封住管道的牆壁要比破開這道大門容易得多。",
  ui_story_1015_10151302_121_dialog_content = "我們可以利用這條她丟垃圾用的「快速通道」，給她一個出其不意的「驚喜」。",
  ui_story_1015_10151401_1_dialog_content = "弱點在這裡！",
  ui_story_1015_10151401_2_dialog_content = "<color=#e8d9bb>砰！砰——！！！</color>",
  ui_story_1015_10151401_3_dialog_content = "<color=#e8d9bb>轟隆——！！！</color>",
  ui_story_1015_10151401_4_dialog_content = "通道打開了！",
  ui_story_1015_10151401_5_dialog_content = "吞羅，住手！",
  ui_story_1015_10151401_6_dialog_content = "妳手下的暗鬼已經都被我們打倒了！",
  ui_story_1015_10151401_7_dialog_content = "你們來的太晚了。",
  ui_story_1015_10151401_8_dialog_content = "我的實驗，已經獲得了成果。",
  ui_story_1015_10151401_9_dialog_content = "<color=#e8d9bb>嗡——</color>",
  ui_story_1015_10151401_10_dialog_content = "PlayerName，快看那台和弦紐帶！",
  ui_story_1015_10151401_11_dialog_content = "裡面好像有東西要出來了！",
  ui_story_1015_10151401_12_dialog_content = "這……這是？！",
  ui_story_1015_10151401_13_dialog_content = "這究竟是什麼怪物？！",
  ui_story_1015_10151401_14_dialog_content = "關於實驗體赫利俄斯的第112次實驗記錄——",
  ui_story_1015_10151401_15_dialog_content = "實驗過程：在使用「和弦紐帶」裝置對「人造太陽」計畫個體進行強化的同時——",
  ui_story_1015_10151401_16_dialog_content = "在「和弦紐帶」裝置中加入「種子」。",
  ui_story_1015_10151401_17_dialog_content = "實驗結果：實驗獲得初步成功，實驗體停止活動的風險大幅降低。",
  ui_story_1015_10151401_18_dialog_content = "她這是在進行實驗記錄？",
  ui_story_1015_10151401_19_dialog_content = "親手把自己曾經的戰友變成這種樣子的怪物，竟然還有心思在這裡做實驗記錄。",
  ui_story_1015_10151401_20_dialog_content = "尤利西斯長官說的沒錯，妳是個不折不扣的冷血動物。",
  ui_story_1015_10151401_21_dialog_content = "尤利西斯？",
  ui_story_1015_10151401_22_dialog_content = "那個老東西說不定比我更加期待這次實驗的結果。",
  ui_story_1015_10151401_23_dialog_content = "妳說什麼？",
  ui_story_1015_10151401_24_dialog_content = "是時候進行下一步實驗了。",
  ui_story_1015_10151401_25_dialog_content = "透過實戰測試實驗體的穩定性。",
  ui_story_1015_10151401_26_dialog_content = "去吧，實驗體，撕碎他們。",
  ui_story_1015_10151401_27_dialog_content = "！！！",
  ui_story_1015_10151401_28_dialog_content = "PlayerName，找地方躲起來！",
  ui_story_1015_10151401_29_dialog_content = "好、好的！",
  ui_story_1015_10151401_30_dialog_content = "……",
  ui_story_1015_10151401_31_dialog_content = "（那個怪物沒有反應？難道說，吞羅的實驗失敗了？）",
  ui_story_1015_10151401_32_dialog_content = "原來如此，看起來我的實驗似乎取得了進一步成功。",
  ui_story_1015_10151401_33_dialog_content = "（進一步成功？什麼意思？）",
  ui_story_1015_10151401_34_dialog_content = "現在確實應該換一種說法了。",
  ui_story_1015_10151401_35_dialog_content = "啟光聯邦的士兵，赫利俄斯——",
  ui_story_1015_10151401_36_dialog_content = "……！",
  ui_story_1015_10151401_37_dialog_content = "那傢伙有反應了，難道說牠聽懂了？！",
  ui_story_1015_10151401_38_dialog_content = "現在站在你面前的，是啟光聯邦的叛徒和敵人。",
  ui_story_1015_10151401_39_dialog_content = "你的任務是消滅他們。",
  ui_story_1015_10151401_40_dialog_content = "<anim type=Shake><size=50>吼——！！！</size></anim>",
  ui_story_1015_10151401_41_dialog_content = "等等，快停下！",
  ui_story_1015_10151401_42_dialog_content = "我們不是敵人！吞羅才是啟光的叛徒與敵人。",
  ui_story_1015_10151401_43_dialog_content = "<anim type=Shake><size=50>吼！！！</size></anim>",
  ui_story_1015_10151401_44_dialog_content = "呃！",
  ui_story_1015_10151401_45_dialog_content = "沒用的，牠看起來還沒有完全恢復理智。",
  ui_story_1015_10151401_46_dialog_content = "先打倒牠再說。",
  ui_story_1015_10151402_1_dialog_content = "<anim type=Shake><size=50>吼——！！！</size></anim>",
  ui_story_1015_10151402_2_dialog_content = "這傢伙怎麼變得這麼強……",
  ui_story_1015_10151402_3_dialog_content = "不僅力量提升，行動也變得難以預測了。",
  ui_story_1015_10151402_4_dialog_content = "各位，小心點！",
  ui_story_1015_10151402_5_dialog_content = "如果說之前牠只是憑藉本能進行反擊，那現在牠已經開始使用戰術了。",
  ui_story_1015_10151402_6_dialog_content = "怪物學會了使用策略嗎？",
  ui_story_1015_10151402_7_dialog_content = "事情變得棘手了……",
  ui_story_1015_10151402_8_dialog_content = "實驗確實取得了進一步的成功，我的理論是正確的。",
  ui_story_1015_10151402_9_dialog_content = "三種不同的力量在實驗體體內交互作用，形成了穩定的狀態。",
  ui_story_1015_10151402_10_dialog_content = "就算進行高強度戰鬥，也不會打破這種平衡。",
  ui_story_1015_10151402_11_dialog_content = "並且最重要的一點是——這個實驗是可以被複製的。",
  ui_story_1015_10151402_12_dialog_content = "現在，只需要驗證最後一項實驗成果，就可以證明實驗完全成功。",
  ui_story_1015_10151402_13_dialog_content = "<anim type=Shake>吼……</anim>",
  ui_story_1015_10151402_14_dialog_content = "小心，那傢伙不對勁！",
  ui_story_1015_10151402_15_dialog_content = "那究竟是光能還是暗能？混在一起，我已經快分不清了！",
  ui_story_1015_10151402_16_dialog_content = "先別管那麼多，做好防禦準備！",
  ui_story_1015_10151402_17_dialog_content = "<anim type=Shake><size=50>吼——！</size></anim>",
  ui_story_1015_10151402_18_dialog_content = "這是？！",
  ui_story_1015_10151402_19_dialog_content = "牠的樣子改變了？！",
  ui_story_1015_10151402_20_dialog_content = "在80號地下城時，我曾經在感應到的記憶片段裡看到過……",
  ui_story_1015_10151402_21_dialog_content = "這是牠原本的樣子！！！",
  ui_story_1015_10151402_22_dialog_content = "終於到了這一步。",
  ui_story_1015_10151402_23_dialog_content = "最後一項實驗結果也得到了驗證。",
  ui_story_1015_10151402_24_dialog_content = "穩定狀態帶來了更大的好處，它使這種力量變得可控。",
  ui_story_1015_10151402_25_dialog_content = "它能扼制「人造太陽」計畫使光靈失去理智、變成怪物的副作用。",
  ui_story_1015_10151402_26_dialog_content = "同時也能使光靈獲得自主改變型態的能力。",
  ui_story_1015_10151402_27_dialog_content = "這正是我想要得到的成果。",
  ui_story_1015_10151402_28_dialog_content = "<anim type=Shake>呃……</anim>",
  ui_story_1015_10151402_29_dialog_content = "<anim type=Shake>這裡……是……</anim>",
  ui_story_1015_10151402_30_dialog_content = "說、說話了？！",
  ui_story_1015_10151402_31_dialog_content = "不……不是……為什麼……不是80號地下城？",
  ui_story_1015_10151402_32_dialog_content = "你們是……什麼人？",
  ui_story_1015_10151402_33_dialog_content = "他竟然恢復成光靈的樣子了，難道理智也隨之恢復了嗎？",
  ui_story_1015_10151402_34_dialog_content = "我是委員會直屬情報官——鶯歌。",
  ui_story_1015_10151402_35_dialog_content = "赫利俄斯上尉，你涉嫌通敵，與暗鬼同流合污。",
  ui_story_1015_10151402_36_dialog_content = "立刻放下武器，停止反抗，接受委員會的調查！",
  ui_story_1015_10151402_37_dialog_content = "不，我沒有……",
  ui_story_1015_10151402_38_dialog_content = "我……怎麼可能通敵？",
  ui_story_1015_10151402_39_dialog_content = "我是……我……",
  ui_story_1015_10151402_40_dialog_content = "冷靜一點，赫利俄斯上尉！",
  ui_story_1015_10151402_41_dialog_content = "你看看周圍，這裡不是80號地下城。",
  ui_story_1015_10151402_42_dialog_content = "你已經不需要再戰鬥了……",
  ui_story_1015_10151402_43_dialog_content = "到底……發生了什麼？我……為什麼會在這裡？",
  ui_story_1015_10151402_44_dialog_content = "為什麼……想不起來……",
  ui_story_1015_10151402_45_dialog_content = "呃……！",
  ui_story_1015_10151402_46_dialog_content = "實驗體的認知能力完好，但記憶似乎發生了錯亂和缺失，不具備失控後的記憶。",
  ui_story_1015_10151402_47_dialog_content = "暫時記為需要留意的副作用，想要完全消除這種副作用，需要繼續進行研究。",
  ui_story_1015_10151402_48_dialog_content = "當然，這種狀況有更大的可能性是實驗體自身的缺陷所導致的。",
  ui_story_1015_10151402_49_dialog_content = "總體而言，實驗成功。",
  ui_story_1015_10151402_50_dialog_content = "我終於掌握了「進化」的方法。",
  ui_story_1015_10151402_51_dialog_content = "現在只剩下一個問題……",
  ui_story_1015_10151402_52_dialog_content = "（想要進行後續的驗證，這個實驗體是必須的。）",
  ui_story_1015_10151402_53_dialog_content = "（得想個辦法把他帶走才行。）",
  ui_story_1015_10151402_54_dialog_content = "（但是，他在逐漸恢復意識和認知，這是不利於計畫的變數。）",
  ui_story_1015_10151402_55_dialog_content = "（不過，想要對付這種頭腦簡單的實驗體，有的是辦法。）",
  ui_story_1015_10151402_56_dialog_content = "妳……我認得妳……",
  ui_story_1015_10151402_57_dialog_content = "妳是……德尼耶爾？",
  ui_story_1015_10151402_58_dialog_content = "妳為什麼，變成這樣……",
  ui_story_1015_10151402_59_dialog_content = "萊因哈特……在哪裡……",
  ui_story_1015_10151402_60_dialog_content = "她為什麼……沒有和妳……一起……？",
  ui_story_1015_10151402_61_dialog_content = "……",
  ui_story_1015_10151402_62_dialog_content = "不管是德尼耶爾，還是曾經的你，都早就被啟光放棄了。",
  ui_story_1015_10151402_63_dialog_content = "我不是德尼耶爾。",
  ui_story_1015_10151402_64_dialog_content = "放……棄……？",
  ui_story_1015_10151402_65_dialog_content = "<anim type=Shake>呃……！！！</anim>",
  ui_story_1015_10151402_66_dialog_content = "他的身上在凝聚暗能！",
  ui_story_1015_10151402_67_dialog_content = "難道說，吞羅想透過語言刺激讓他再度陷入混亂，變回怪物？！",
  ui_story_1015_10151402_68_dialog_content = "大家都已經沒剩多少力氣了……",
  ui_story_1015_10151402_69_dialog_content = "你聽，他們把你叫作「怪物」。",
  ui_story_1015_10151402_70_dialog_content = "<anim type=Shake>不……我不是……不是怪物……</anim>",
  ui_story_1015_10151402_71_dialog_content = "<anim type=Shake>我是……啟光的……軍人……</anim>",
  ui_story_1015_10151402_72_dialog_content = "嘖……",
  ui_story_1015_10151402_73_dialog_content = "啟光聯邦已經沒有你的容身之地了。",
  ui_story_1015_10151402_74_dialog_content = "跟我走，你才有活下去的機會。",
  ui_story_1015_10151402_75_dialog_content = "留在這裡只有死路一條。",
  ui_story_1015_10151402_76_dialog_content = "別相信她，啟光聯邦不會放棄任何一個人！",
  ui_story_1015_10151402_77_dialog_content = "啟光聯邦會捨棄沒辦法再做出貢獻的人，尤其是失敗品。",
  ui_story_1015_10151402_78_dialog_content = "萊因哈特大元帥也是，她從來沒有放棄過尋找你們的下落。",
  ui_story_1015_10151402_79_dialog_content = "萊因哈特從來沒有帶回過援兵。",
  ui_story_1015_10151402_80_dialog_content = "她是被迫的！當時的啟光長官用麻醉劑限制了她的行動！",
  ui_story_1015_10151402_81_dialog_content = "這是我透過感應能力看到的，千真萬確！",
  ui_story_1015_10151402_82_dialog_content = "別忘了，在80號地下城，萊因哈特對你和我刀劍相向。",
  ui_story_1015_10151402_83_dialog_content = "睜開眼睛看看吧，你曾經的同伴已經不再是光靈的一員了。",
  ui_story_1015_10151402_84_dialog_content = "她才是雙手沾滿鮮血的那個！",
  ui_story_1015_10151402_85_dialog_content = "這些虛偽的人，你不恨嗎？",
  ui_story_1015_10151402_86_dialog_content = "<size=45>安靜點！</size>",
  ui_story_1015_10151402_87_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_1015_10151402_88_dialog_content = "<anim type=Shake><size=50>呃！！！</size></anim>",
  ui_story_1015_10151402_89_dialog_content = "那傢伙？！",
  ui_story_1015_10151402_90_dialog_content = "……你在幹什麼？",
  ui_story_1015_10151402_91_dialog_content = "我是……啟光的軍人……",
  ui_story_1015_10151402_92_dialog_content = "我會配合……接受調查……",
  ui_story_1015_10151402_93_dialog_content = "但我也……要……保護戰友……",
  ui_story_1015_10151402_94_dialog_content = "……",
  ui_story_1015_10151402_95_dialog_content = "愚蠢。",
  ui_story_1015_10151402_96_dialog_content = "看起來，實驗體對自身和對他人的認知並不正確。",
  ui_story_1015_10151402_97_dialog_content = "這或許是某種精神錯亂，需要將這份錯誤的認知徹底根除才行。",
  ui_story_1015_10151402_98_dialog_content = "這是……",
  ui_story_1015_10151402_99_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_1015_10151402_100_dialog_content = "怎、怎麼回事？！",
  ui_story_1015_10151402_101_dialog_content = "退後，PlayerName！那扇門上出現了一個大坑！",
  ui_story_1015_10151402_102_dialog_content = "有什麼不得了的東西要破門而入了！",
  ui_story_1015_10151402_103_dialog_content = "噫！！！",
  ui_story_1015_10151402_104_dialog_content = "<color=#e8d9bb>轟！！！</color>",
  ui_story_1015_10151402_105_dialog_content = "不得了這個形容是正確的，但不是東西，而是我。",
  ui_story_1015_10151402_106_dialog_content = "妳果然在這裡，吞羅。",
  ui_story_1015_10151402_107_dialog_content = "時間算得真準。",
  ui_story_1015_10151402_108_dialog_content = "又見面了，萊因哈特，就算隔了這麼久，妳還是沒有一點長進。",
  ui_story_1015_10151402_109_dialog_content = "依舊在心甘情願地被利用。",
  ui_story_1015_10151402_110_dialog_content = "好久不見，吞羅。",
  ui_story_1015_10151402_111_dialog_content = "看來妳在暗鬼那邊混得不怎麼樣，已經淪落到這種地步了。",
  ui_story_1015_10151402_112_dialog_content = "嗯？妳是叫什麼來著？雷……？",
  ui_story_1015_10151402_113_dialog_content = "算了，靠老同學上位的小角色，不值得我去記住。",
  ui_story_1015_10151402_114_dialog_content = "小看我？呵，無所謂。",
  ui_story_1015_10151402_115_dialog_content = "等一下被我按在地上打的時候，可別哭著鼻子找姐姐。",
  ui_story_1015_10151402_116_dialog_content = "幼稚。",
  ui_story_1015_10151402_117_dialog_content = "妳是……萊因哈特……？",
  ui_story_1015_10151402_118_dialog_content = "赫利俄斯？！你的樣子……",
  ui_story_1015_10151402_119_dialog_content = "是……援軍嗎？妳終於……",
  ui_story_1015_10151402_120_dialog_content = "……",
  ui_story_1015_10151402_121_dialog_content = "嗯，抱歉，我來晚了。",
  ui_story_1015_10151402_122_dialog_content = "我帶著援軍來接你們了。",
  ui_story_1015_10151402_123_dialog_content = "包圍這裡！",
  ui_story_1015_10151402_124_dialog_content = "是！",
  ui_story_1015_10151402_125_dialog_content = "果然，與我推測的一模一樣。",
  ui_story_1015_10151402_126_dialog_content = "萊因哈特，我們做個交易吧。",
  ui_story_1015_10151402_127_dialog_content = "什麼……？",
  ui_story_1015_10151402_128_dialog_content = "讓我和我的實驗體離開啟光，對妳沒有壞處。",
  ui_story_1015_10151402_129_dialog_content = "哦？妳是在永夜裡待了太久，被暗能搞壞了腦子嗎？",
  ui_story_1015_10151402_130_dialog_content = "現在的妳，可沒有資格跟我們談條件。",
  ui_story_1015_10151402_131_dialog_content = "我不是在跟你們談條件。",
  ui_story_1015_10151402_132_dialog_content = "那群老東西想要的不是我，而是他。",
  ui_story_1015_10151402_133_dialog_content = "（什麼意思？委員會的人想要的是赫利俄斯？）",
  ui_story_1015_10151402_134_dialog_content = "（但我接到的任務，卻只是抓捕吞羅和營救薇絲中尉。）",
  ui_story_1015_10151402_135_dialog_content = "他落在那些人手裡會有什麼下場，妳應該知道。",
  ui_story_1015_10151402_136_dialog_content = "我不可能同意妳的要求。",
  ui_story_1015_10151402_137_dialog_content = "如果是在十幾年前、妳還沒有離開啟光的時候，我會選擇相信妳。",
  ui_story_1015_10151402_138_dialog_content = "但是我們兩個鬥了這麼多年，現在我是最瞭解妳的。",
  ui_story_1015_10151402_139_dialog_content = "妳想要做的事情，和「他們」並無差別。",
  ui_story_1015_10151402_140_dialog_content = "把他交給我，我會以大元帥的名義將他保護起來，不會讓任何人動他。",
  ui_story_1015_10151402_141_dialog_content = "妳做不到。",
  ui_story_1015_10151402_142_dialog_content = "談判破裂，我也沒必要再在這裡耗下去了。",
  ui_story_1015_10151402_143_dialog_content = "玉子。",
  ui_story_1015_10151402_144_dialog_content = "<anim type=Shake><size=50>嘎吼！</size></anim>",
  ui_story_1015_10151402_145_dialog_content = "「再見」。",
  ui_story_1015_10151402_146_dialog_content = "<color=#e8d9bb>轟隆！！！</color>",
  ui_story_1015_10151501_1_dialog_content = "報告，根據鶯歌中校和阿納托利少校的情報，我們在一間廢棄實驗室裡找到了薇絲中尉。",
  ui_story_1015_10151501_2_dialog_content = "薇絲中尉，歸隊！",
  ui_story_1015_10151501_3_dialog_content = "薇絲！妳還好嗎，有沒有受傷？",
  ui_story_1015_10151501_4_dialog_content = "我沒事！",
  ui_story_1015_10151501_5_dialog_content = "抱歉，是我大意了，給大家添了這麼多麻煩……",
  ui_story_1015_10151501_6_dialog_content = "妳能平安無事地回來就好。",
  ui_story_1015_10151501_7_dialog_content = "沒錯，妳不用太自責。",
  ui_story_1015_10151501_8_dialog_content = "吞羅是一個狡猾的敵人，需要大家一起對付。",
  ui_story_1015_10151501_9_dialog_content = "嗯……",
  ui_story_1015_10151501_10_dialog_content = "搜索工作進行得怎麼樣？發現吞羅的蹤跡了嗎？",
  ui_story_1015_10151501_11_dialog_content = "報告，我們已經搜索了整座地下城，沒有發現吞羅的蹤跡。",
  ui_story_1015_10151501_12_dialog_content = "各個出入口和舊地下城的通道呢？",
  ui_story_1015_10151501_13_dialog_content = "都有人把守，沒發現任何人出入。",
  ui_story_1015_10151501_14_dialog_content = "知道了，但不能掉以輕心，繼續搜索。",
  ui_story_1015_10151501_15_dialog_content = "是！",
  ui_story_1015_10151501_16_dialog_content = "吞羅那傢伙，竟然能大搖大擺地在我們眼皮子底下消失。",
  ui_story_1015_10151501_17_dialog_content = "狠話放了不少，跑得倒是挺快。",
  ui_story_1015_10151501_18_dialog_content = "大元帥，雷霆軍團長，對於吞羅的逃跑路線，我有一個猜想。",
  ui_story_1015_10151501_19_dialog_content = "哦？說來聽聽。",
  ui_story_1015_10151501_20_dialog_content = "這座地下城，是由吞羅進行設計並主持建造的。",
  ui_story_1015_10151501_21_dialog_content = "吞羅在地下城建好後，直到從啟光聯邦叛逃前，曾經多次祕密往返於這裡和迦南城之間。",
  ui_story_1015_10151501_22_dialog_content = "根據我所掌握的情報來看，吞羅是一個不願意在無意義的事情上浪費時間的人。",
  ui_story_1015_10151501_23_dialog_content = "所以我推測，她很可能也建造了能夠在這裡與迦南城之間快速往返的祕密通道。",
  ui_story_1015_10151501_24_dialog_content = "你是說，她很有可能已經逃向迦南城了？",
  ui_story_1015_10151501_25_dialog_content = "是的。",
  ui_story_1015_10151501_26_dialog_content = "嗯，有道理。我立刻組織人手對迦南城進行搜索，對這件事進行調查。",
  ui_story_1015_10151501_27_dialog_content = "萊因哈特，這件事還是交給我處理吧。",
  ui_story_1015_10151501_28_dialog_content = "不行，這件事與吞羅和赫利俄斯有關，我必須親自出面。",
  ui_story_1015_10151501_29_dialog_content = "正是因為這件事與他們有關，妳才不能出面。",
  ui_story_1015_10151501_30_dialog_content = "任務是由委員會指派給我的，我理應作為第一負責人執行任務。",
  ui_story_1015_10151501_31_dialog_content = "更何況，現在站在對面的是妳曾經的親人和戰友。",
  ui_story_1015_10151501_32_dialog_content = "就算我相信妳能剛正不阿，但也沒辦法保證所有人都能相信妳。",
  ui_story_1015_10151501_33_dialog_content = "明眼人都能察覺到，「他們」最近一直在想方設法尋找妳的過失。",
  ui_story_1015_10151501_34_dialog_content = "而且馬上就要舉辦聯合軍演了，全艾斯特拉的勢力都在盯著啟光。",
  ui_story_1015_10151501_35_dialog_content = "現在的妳最需要做的是回到迦南城。",
  ui_story_1015_10151501_36_dialog_content = "一方面，妳回去能穩住局面並保持妳的威信。",
  ui_story_1015_10151501_37_dialog_content = "另一方面，只要有妳坐鎮，就算吞羅真的在迦南城裡，她也不敢造次。",
  ui_story_1015_10151501_38_dialog_content = "……",
  ui_story_1015_10151501_39_dialog_content = "如果妳不信任我，可以派個跟班之類的來，我不介意身邊多個監工。",
  ui_story_1015_10151501_40_dialog_content = "就像我一直所說的，我會堂堂正正地打敗妳。",
  ui_story_1015_10151501_41_dialog_content = "過去是，現在是，未來也會是。",
  ui_story_1015_10151501_42_dialog_content = "我相信妳。",
  ui_story_1015_10151501_43_dialog_content = "追捕吞羅，帶回赫利俄斯的事情就交給妳了。",
  ui_story_1015_10151501_44_dialog_content = "放心吧，我一定會找到他們的。",
  ui_story_1015_10151501_45_dialog_content = "既然如此，PlayerName，你們也都和我一起回迦南城吧。",
  ui_story_1015_10151501_46_dialog_content = "但是，任務……",
  ui_story_1015_10151501_47_dialog_content = "既然委員會已經將此事交給雷霆軍團長負責，那你們也不用再操心了。",
  ui_story_1015_10151501_48_dialog_content = "先以接下來的工作為重吧。",
  ui_story_1015_10151501_49_dialog_content = "是。",
  ui_story_1015_10151501_50_dialog_content = "是，我知道了。",
  ui_story_1015_10151501_51_dialog_content = "<size=30>確實，接下來還有很多工作，要幫大元帥規劃演習期間的行程，還要——</size>",
  ui_story_1015_10151501_52_dialog_content = "阿納托利。",
  ui_story_1015_10151501_53_dialog_content = "<size=45>到！</size>",
  ui_story_1015_10151501_54_dialog_content = "還有什麼額外吩咐嗎，大元帥？",
  ui_story_1015_10151501_55_dialog_content = "你不用跟著我了，去參加演習。",
  ui_story_1015_10151501_56_dialog_content = "是——等一下，大元帥，我並沒有加入隊伍，沒辦法參加演習。",
  ui_story_1015_10151501_57_dialog_content = "這你不用擔心，有支隊伍的一位隊員出現了一些情況，無法參加演習了。",
  ui_story_1015_10151501_58_dialog_content = "這個空缺的名額，就由你來補上吧。",
  ui_story_1015_10151501_59_dialog_content = "是。是哪支隊伍？",
  ui_story_1015_10151501_60_dialog_content = "你應該挺熟悉的，就是鶯歌的隊伍。",
  ui_story_1015_10151501_61_dialog_content = "什麼？我們隊？",
  ui_story_1015_10151501_62_dialog_content = "是阿克希亞出現了情況嗎？",
  ui_story_1015_10151501_63_dialog_content = "不，不是她，是西恩。",
  ui_story_1015_10151501_64_dialog_content = "我也是剛剛才從黃昏鎮那邊得到的消息。",
  ui_story_1015_10151501_65_dialog_content = "他們說，西恩的身體突然出現了一些問題，需要留在黃昏鎮暫時觀察。",
  ui_story_1015_10151501_66_dialog_content = "他的情況怎麼樣，沒事吧？",
  ui_story_1015_10151501_67_dialog_content = "聽黃昏鎮那邊的人說，他只是在使用光能術時出現了一些從前沒有過的奇怪現象。",
  ui_story_1015_10151501_68_dialog_content = "可能和他自身的基因缺陷有關係。",
  ui_story_1015_10151501_69_dialog_content = "是嗎……",
  ui_story_1015_10151501_70_dialog_content = "等這件事告一段落以後，就去黃昏鎮看望一下他吧。",
  ui_story_1015_10151501_71_dialog_content = "要我和鶯歌以及阿克希亞組隊嗎？",
  ui_story_1015_10151501_72_dialog_content = "服從命令。",
  ui_story_1015_10151501_73_dialog_content = "（與原定的計畫有些不同，不過也沒關係，還在可控範圍內。）",
  ui_story_1015_10151501_74_dialog_content = "我也沒有意見。",
  ui_story_1015_10151501_75_dialog_content = "那就先這麼決定吧。",
  ui_story_1015_10151501_76_dialog_content = "是時候回迦南城了。",
  ui_story_1015_10151501_77_dialog_content = "<color=#e8d9bb>幾天後 迦南城</color>",
  ui_story_1015_10151501_78_dialog_content = "「列車即將到達迦南城，請提前做好準備，留意列車與月台之間的空隙。」",
  ui_story_1015_10151501_79_dialog_content = "「願啟明之光照耀您的旅途。」",
  ui_story_1015_10151501_80_dialog_content = "讓一讓，不好意思，請讓我們下車。",
  ui_story_1015_10151501_81_dialog_content = "人好多啊……不愧是全艾斯特拉最大的軍事演習活動！",
  ui_story_1015_10151501_82_dialog_content = "不過，這裡這麼大，我們沒走錯吧？應該是在這一站下車吧？",
  ui_story_1015_10151501_83_dialog_content = "按照卡蓮殿下的指示，在這裡下車應該是正確的。",
  ui_story_1015_10151501_84_dialog_content = "希望不要迷路……",
  ui_story_1015_10151501_85_dialog_content = "貝爾塔。",
  ui_story_1015_10151501_86_dialog_content = "卡蓮大人！",
  ui_story_1015_10151501_87_dialog_content = "按照約定，我來接妳們了。",
  ui_story_1015_10151501_88_dialog_content = "謝謝您！如果沒有您的話，我們一定會在這裡迷路的……",
  ui_story_1015_10151501_89_dialog_content = "沒什麼。多參加幾次演習就會熟悉這裡了。",
  ui_story_1015_10151501_90_dialog_content = "我們走吧。",
  ui_story_1015_10151501_91_dialog_content = "是，卡蓮大人！",
  ui_story_1015_10151501_92_dialog_content = "剛才離開的，好像是那位殿下？",
  ui_story_1015_10151501_93_dialog_content = "嗯，看起來是的。",
  ui_story_1015_10151501_94_dialog_content = "不去打個招呼嗎？",
  ui_story_1015_10151501_95_dialog_content = "哈哈哈，先不去了。",
  ui_story_1015_10151501_96_dialog_content = "這裡人這麼多，就不要阻礙交通了。",
  ui_story_1015_10151501_97_dialog_content = "在聯合軍演的比賽正式開始之前，我們還有很多時間可以用來敘舊和打招呼。",
  ui_story_1015_10151501_98_dialog_content = "說的也是。",
  ui_story_1015_10151501_99_dialog_content = "尤其是在我們的新隊友還有任務在身的情況下……",
  ui_story_1015_10151501_100_dialog_content = "各位，請讓一讓。",
  ui_story_1015_10151501_101_dialog_content = "鴉青，往這邊靠一點，小心別碰到車門。",
  ui_story_1015_10151501_102_dialog_content = "知道了。",
  ui_story_1015_10151501_103_dialog_content = "真是抱歉啊……",
  ui_story_1015_10151501_104_dialog_content = "明明是指派給我的工作，卻要麻煩妳幫忙。",
  ui_story_1015_10151501_105_dialog_content = "我是你的侍衛，協助和保護你是我的職責。",
  ui_story_1015_10151501_106_dialog_content = "再說了，如果我不幫忙，僅憑你一個人，也是沒辦法把這個送到迦南城的。",
  ui_story_1015_10151501_107_dialog_content = "也沒辦法，畢竟我不擅長體力活。",
  ui_story_1015_10151501_108_dialog_content = "需要幫忙嗎，啟光的軍師？",
  ui_story_1015_10151501_109_dialog_content = "不必，我們馬上就要到目的地了。",
  ui_story_1015_10151501_110_dialog_content = "如果有需要的話，我會主動來找你。",
  ui_story_1015_10151501_111_dialog_content = "那就好，別因為之前沒有合作過就不好意思。",
  ui_story_1015_10151501_112_dialog_content = "就算你哪天找我說想要加入鐵棘騎士團，我也不會介意。",
  ui_story_1015_10151501_113_dialog_content = "您可真會開玩笑。",
  ui_story_1015_10151501_114_dialog_content = "如果不介意的話，請您和若瑟先生先行前去報導吧。",
  ui_story_1015_10151501_115_dialog_content = "我和鴉青要先將「她」交付給委託人後，才能去報到。",
  ui_story_1015_10151501_116_dialog_content = "好吧，那我們就先走了。",
  ui_story_1015_10151501_117_dialog_content = "晚點見，昭參謀。",
  ui_story_1015_10151501_118_dialog_content = "……",
  ui_story_1015_10151501_119_dialog_content = "怎麼了，鴉青？",
  ui_story_1015_10151501_120_dialog_content = "…………",
  ui_story_1015_10151501_121_dialog_content = "妳是不是又想問，為什麼我要和他們組隊，而不是和妳？",
  ui_story_1015_10151501_122_dialog_content = "我可以更好地保護你，但是他們不行。",
  ui_story_1015_10151501_123_dialog_content = "這我知道。",
  ui_story_1015_10151501_124_dialog_content = "但這是我們，是整個黃昏鎮共同的決定。",
  ui_story_1015_10151501_125_dialog_content = "我也是黃昏鎮的一員。",
  ui_story_1015_10151501_126_dialog_content = "我知道，但是這一次不一樣。",
  ui_story_1015_10151501_127_dialog_content = "這次與鐵棘騎士團和光之神教會共同合作，是為了向外界展現黃昏鎮的團結和強大。",
  ui_story_1015_10151501_128_dialog_content = "只有這樣，當我們在演習中拔得頭籌時，才有足夠的話語權和籌碼發聲、向各方施壓。",
  ui_story_1015_10151501_129_dialog_content = "他們就那麼討厭黃昏鎮嗎？",
  ui_story_1015_10151501_130_dialog_content = "不，他們並不討厭黃昏鎮。",
  ui_story_1015_10151501_131_dialog_content = "他們只是不在乎。",
  ui_story_1015_10151501_132_dialog_content = "但我們在乎，黃昏鎮是我們的家園，我不能眼睜睜看著它被暗鬼的浪潮吞沒。",
  ui_story_1015_10151501_133_dialog_content = "所以這次我們必須贏，必須讓他們在乎起來，向黃昏鎮增派援兵。",
  ui_story_1015_10151501_134_dialog_content = "……",
  ui_story_1015_10151501_135_dialog_content = "我聽你的。",
  ui_story_1015_10151501_136_dialog_content = "謝謝妳的理解。",
  ui_story_1015_10151501_137_dialog_content = "時候不早了，我們也趕快去交付「她」吧。",
  ui_story_1015_10151501_138_dialog_content = "他們就是目標？",
  ui_story_1015_10151501_139_dialog_content = "看起來一點意思都沒有，還不如我夢裡的玩具熊好玩呢。",
  ui_story_1015_10151501_140_dialog_content = "別這麼早下定論，我的朋友。",
  ui_story_1015_10151501_141_dialog_content = "「大人」給我們的任務是觀察他們，我們得好好執行。",
  ui_story_1015_10151501_142_dialog_content = "「大人」的直覺一向準確，我相信他們一定有深藏不露的一面。",
  ui_story_1015_10151501_143_dialog_content = "希望他們不討厭小動物……",
  ui_story_1015_10151501_144_dialog_content = "以上就是目前的情況。",
  ui_story_1015_10151501_145_dialog_content = "萊因哈特已經回到了迦南城，吞羅與目標實驗體下落不明，但很有可能在迦南城某處。",
  ui_story_1015_10151501_146_dialog_content = "另外，各方勢力已經在迦南城集結，即將開始進行聯合軍演。",
  ui_story_1015_10151501_147_dialog_content = "不過，黃昏鎮派出的啟光與白夜城聯合小隊，確實在意料之外。",
  ui_story_1015_10151501_148_dialog_content = "需要我找兩個人一起組成小隊，牽制他們的行動嗎？",
  ui_story_1015_10151501_149_dialog_content = "他們確實值得注意，但也不必太放在心上。",
  ui_story_1015_10151501_150_dialog_content = "鶯歌和阿克希亞是兩名值得信任的士兵。",
  ui_story_1015_10151501_151_dialog_content = "你還有其他事情要做。",
  ui_story_1015_10151501_152_dialog_content = "是。",
  ui_story_1015_10151501_153_dialog_content = "<color=#e8d9bb>與此同時，迦南城某處</color>",
  ui_story_1015_10151501_154_dialog_content = "<anim type=Shake><size=45>吼……</size></anim>",
  ui_story_1015_10151501_155_dialog_content = "把他放在這裡吧。",
  ui_story_1015_10151501_156_dialog_content = "<anim type=Shake><size=45>吼！</size></anim>",
  ui_story_1015_10151501_157_dialog_content = "<anim type=Shake>咕嚕嚕——</anim>",
  ui_story_1015_10151501_158_dialog_content = "你做得很好。",
  ui_story_1015_10151501_159_dialog_content = "變回去吧，然後順著這些管道，離開這座地下城。",
  ui_story_1015_10151501_160_dialog_content = "<anim type=Shake><size=45>吼？！</size></anim>",
  ui_story_1015_10151501_161_dialog_content = "<anim type=Shake><size=45>吼——吼——！</size></anim>",
  ui_story_1015_10151501_162_dialog_content = "這裡已經沒有你能做的事了。",
  ui_story_1015_10151501_163_dialog_content = "再在這裡待下去，你只會拖後腿。",
  ui_story_1015_10151501_164_dialog_content = "到原本的地方等著我。",
  ui_story_1015_10151501_165_dialog_content = "<anim type=Shake>吼……</anim>",
  ui_story_1015_10151501_166_dialog_content = "吱——！",
  ui_story_1015_10151501_167_dialog_content = "德尼耶爾……？",
  ui_story_1015_10151501_168_dialog_content = "……",
  ui_story_1015_10151501_169_dialog_content = "你醒了。",
  ui_story_1015_10151501_170_dialog_content = "嗯……",
  ui_story_1015_10151501_171_dialog_content = "妳……把我帶到了……哪裡？",
  ui_story_1015_10151501_172_dialog_content = "認知能力在一步步恢復嗎？",
  ui_story_1015_10151501_173_dialog_content = "雖然這代表著實驗的成功，但時間不巧。",
  ui_story_1015_10151501_174_dialog_content = "妳在說什麼……？我聽不懂……",
  ui_story_1015_10151501_175_dialog_content = "沒什麼。",
  ui_story_1015_10151501_176_dialog_content = "這裡是……哪裡？妳還沒有回答我……",
  ui_story_1015_10151501_177_dialog_content = "……",
  ui_story_1015_10151501_178_dialog_content = "迦南城。",
  ui_story_1015_10151501_179_dialog_content = "我們……回來了嗎？",
  ui_story_1015_10151501_180_dialog_content = "是啊。",
  ui_story_1015_10151501_181_dialog_content = "我們回來了。",
  ui_story_1016_10160101_1_dialog_content = "<color=#e8d9bb>嗚——</color>",
  ui_story_1016_10160101_2_dialog_content = "<color=#e8d9bb>叩咚叩咚叩咚……</color>",
  ui_story_1016_10160101_3_dialog_content = "「各位參加聯合軍演的學員請注意。」",
  ui_story_1016_10160101_4_dialog_content = "「列車已到站，請大家盡快下車。」",
  ui_story_1016_10160101_5_dialog_content = "「在月台上稍作休息，等待後續安排。」",
  ui_story_1016_10160101_6_dialog_content = "喔哦！我還是第一次坐火車欸。",
  ui_story_1016_10160101_7_dialog_content = "速度好快，比馬車快得多。",
  ui_story_1016_10160101_8_dialog_content = "我不習慣顛簸，還是下車後安心一些。",
  ui_story_1016_10160101_9_dialog_content = "我們是到軍演場地了對吧，接下來該做什麼？",
  ui_story_1016_10160101_10_dialog_content = "在這裡等待一下就好，會有人來宣布軍演安排的。",
  ui_story_1016_10160101_11_dialog_content = "阿納托利！好久不見啊！",
  ui_story_1016_10160101_12_dialog_content = "你也要參加聯合軍演？",
  ui_story_1016_10160101_13_dialog_content = "當然，站在這裡的所有人都是參加軍演的學員。",
  ui_story_1016_10160101_14_dialog_content = "原來如此，還滿熱鬧的呢。",
  ui_story_1016_10160101_15_dialog_content = "這次來到了你們啟光的地盤，可不要仗勢欺人喔。",
  ui_story_1016_10160101_16_dialog_content = "那是你們白夜城才會做的事，在這裡不用擔心。",
  ui_story_1016_10160101_17_dialog_content = "哼。",
  ui_story_1016_10160101_18_dialog_content = "麻煩大家讓一讓，這裡正在搬運「易碎品」。",
  ui_story_1016_10160101_19_dialog_content = "小心碰撞，小心碰撞。",
  ui_story_1016_10160101_20_dialog_content = "昭，我們要把它運送到哪裡去？",
  ui_story_1016_10160101_21_dialog_content = "按理說接頭人會在這裡跟我們碰面……",
  ui_story_1016_10160101_22_dialog_content = "辛苦了，二位。把它交給我吧。",
  ui_story_1016_10160101_23_dialog_content = "你們的任務完成了。",
  ui_story_1016_10160101_24_dialog_content = "鶯歌中校，原來接頭人是妳。",
  ui_story_1016_10160101_25_dialog_content = "奇怪嗎？",
  ui_story_1016_10160101_26_dialog_content = "妳會來參加軍演是有點奇怪。",
  ui_story_1016_10160101_27_dialog_content = "我還以為，妳是不喜歡抛頭露面的那種角色。",
  ui_story_1016_10160101_28_dialog_content = "你高看我了。",
  ui_story_1016_10160101_29_dialog_content = "拿去吧，好不容易運回來的寶貝。",
  ui_story_1016_10160101_30_dialog_content = "不檢查一下有沒有出問題嗎？",
  ui_story_1016_10160101_31_dialog_content = "嗯。",
  ui_story_1016_10160101_32_dialog_content = "<color=#e8d9bb>叩、叩。</color>",
  ui_story_1016_10160101_33_dialog_content = "阿克希亞，該起床了。",
  ui_story_1016_10160101_34_dialog_content = "<color=#e8d9bb>哧——</color>",
  ui_story_1016_10160101_35_dialog_content = "嗚——啊。",
  ui_story_1016_10160101_36_dialog_content = "鶯歌，早安。",
  ui_story_1016_10160101_37_dialog_content = "睡得好嗎？",
  ui_story_1016_10160101_38_dialog_content = "嗯，很有精神。",
  ui_story_1016_10160101_39_dialog_content = "呼，憋死我了。",
  ui_story_1016_10160101_40_dialog_content = "我真的受不了這種封閉又悶熱的空間。",
  ui_story_1016_10160101_41_dialog_content = "李奧，你出了好多汗。",
  ui_story_1016_10160101_42_dialog_content = "是的，感覺比打完一場仗還要累。",
  ui_story_1016_10160101_43_dialog_content = "是不是說得太誇張了？只是乘坐交通工具而已。",
  ui_story_1016_10160101_44_dialog_content = "我們並沒有經歷任何危險。",
  ui_story_1016_10160101_45_dialog_content = "所以說啊，根本就不是有沒有危險的問題……",
  ui_story_1016_10160101_46_dialog_content = "需要紙巾嗎？",
  ui_story_1016_10160101_47_dialog_content = "謝謝……嗯？卡蓮殿下？！",
  ui_story_1016_10160101_48_dialog_content = "很多白夜城人都沒辦法習慣機械，我能理解你。",
  ui_story_1016_10160101_49_dialog_content = "是吧，要是所有人都像您一樣善解人意就好了。",
  ui_story_1016_10160101_50_dialog_content = "不過還真是意外啊，竟然會在這裡與您相遇。",
  ui_story_1016_10160101_51_dialog_content = "我以為再次見面的地方會是在白夜城。",
  ui_story_1016_10160101_52_dialog_content = "在白夜城見面，我們的身分關係會很複雜。但是在這裡，我們都是學員。",
  ui_story_1016_10160101_53_dialog_content = "哈哈哈哈，說得對啊。",
  ui_story_1016_10160101_54_dialog_content = "在複雜裡生活久了，偶爾就會嚮往簡單的東西。",
  ui_story_1016_10160101_55_dialog_content = "李奧還有若瑟！你們也來參加軍演了？",
  ui_story_1016_10160101_56_dialog_content = "從黃昏鎮趕過來可是很遠的呢！",
  ui_story_1016_10160101_57_dialog_content = "PlayerName！你怎麼在這裡？",
  ui_story_1016_10160101_58_dialog_content = "我收到了聯合軍演的邀請，就跟卡蓮和薇絲一起來了。",
  ui_story_1016_10160101_59_dialog_content = "原來如此。早知道這樣，當初就該搭你的巨像過來。",
  ui_story_1016_10160101_60_dialog_content = "哈哈哈，想坐巨像的話隨時歡迎喔！",
  ui_story_1016_10160101_61_dialog_content = "咳、咳！請各位學員安靜，向這邊集合。",
  ui_story_1016_10160101_62_dialog_content = "接下來由我宣布聯合軍演的諸項事宜。",
  ui_story_1016_10160101_63_dialog_content = "這是薇薇安的聲音？",
  ui_story_1016_10160101_64_dialog_content = "嗯！我們快過去！",
  ui_story_1016_10160101_65_dialog_content = "薇絲妳小心點，這裡人太多了。",
  ui_story_1016_10160101_66_dialog_content = "哎呀，不用這麼操心，我又沒在之前的事件裡受傷。",
  ui_story_1016_10160101_67_dialog_content = "醫院的檢查結果不是出來了嗎，健健康康！",
  ui_story_1016_10160101_68_dialog_content = "但我還是……",
  ui_story_1016_10160101_69_dialog_content = "走了走了！",
  ui_story_1016_10160101_70_dialog_content = "歡迎各位學員來到迦南城參加聯合軍演。",
  ui_story_1016_10160101_71_dialog_content = "我是啟光參謀長薇薇安，也是此行接引大家的向導。",
  ui_story_1016_10160101_72_dialog_content = "啟光重視效率，所以沒有什麼繁文縟節。",
  ui_story_1016_10160101_73_dialog_content = "在我介紹完規則之後，本屆聯合軍演就正式開始。",
  ui_story_1016_10160101_74_dialog_content = "喔，流程這麼乾淨俐落。",
  ui_story_1016_10160101_75_dialog_content = "這樣子不錯，不用聽無聊的政治演說。",
  ui_story_1016_10160101_76_dialog_content = "想必各位也清楚，聯合軍演的宗旨是提高青年一代應對戰爭的能力。",
  ui_story_1016_10160101_77_dialog_content = "被邀請至此的學員，都是二十五歲以下的年輕一代。",
  ui_story_1016_10160101_78_dialog_content = "你們或許是初露鋒芒的軍官，或許是尚未邁出象牙塔的學生。",
  ui_story_1016_10160101_79_dialog_content = "無論年齡和經驗上有多少差異，你們將來都會在同一片戰場上奮戰。",
  ui_story_1016_10160101_80_dialog_content = "你們需要為此學習、合作、競爭，盡最大限度去磨練自身的戰鬥素養。",
  ui_story_1016_10160101_81_dialog_content = "為了幫學員們搭建舞台，軍演將分為兩個階段——課程和考核。",
  ui_story_1016_10160101_82_dialog_content = "在課程階段，你們會享受到啟光聯邦最優秀的資源，借前人之力提升自我。",
  ui_story_1016_10160101_83_dialog_content = "而考核階段，你們需要彼此競爭，角逐出唯一一支獲勝的隊伍。",
  ui_story_1016_10160101_84_dialog_content = "我想很多人都知道。按照傳統，軍演考核的勝者將得到一項特殊的獎賞——",
  ui_story_1016_10160101_85_dialog_content = "得到與大元帥交手的機會。",
  ui_story_1016_10160101_86_dialog_content = "天哪，與大元帥交手……太可怕了吧，我想都不敢想。",
  ui_story_1016_10160101_87_dialog_content = "不過話說回來，能在軍演中勝出的學員也都是恐怖的傢伙。",
  ui_story_1016_10160101_88_dialog_content = "對對對，上次可是那個白夜城的公主啊……",
  ui_story_1016_10160101_89_dialog_content = "好了，基本的介紹就到此為止。",
  ui_story_1016_10160101_90_dialog_content = "副手，幫我把旗子升起來。",
  ui_story_1016_10160101_91_dialog_content = "<color=#e8d9bb>唰——</color>",
  ui_story_1016_10160101_92_dialog_content = "哇，好長的一串旗子！",
  ui_story_1016_10160101_93_dialog_content = "它叫做「<color=#FFB400>冠軍旗</color>」。",
  ui_story_1016_10160101_94_dialog_content = "聯合軍演上奪魁的勝者，將有資格將自己陣營的旗幟懸掛上去。",
  ui_story_1016_10160101_95_dialog_content = "隨著軍演一屆屆地舉辦，旗子便一截截地增長，變成了現在的樣子。",
  ui_story_1016_10160101_96_dialog_content = "你們可以在上面找到各大陣營的旗幟。",
  ui_story_1016_10160101_97_dialog_content = "群星於四處升起，匯集在我們仰望的天上。",
  ui_story_1016_10160101_98_dialog_content = "這串旗幟是軍演的象徵，也印證著一代代人贏下戰爭的決心。",
  ui_story_1016_10160101_99_dialog_content = "（！！！）",
  ui_story_1016_10160101_100_dialog_content = "（我沒看錯吧，那上面有空裔的旗幟……）",
  ui_story_1016_10160101_101_dialog_content = "好了各位，請允許我在這裡宣布。",
  ui_story_1016_10160101_102_dialog_content = "聯合軍演正式開始。",
  ui_story_1016_10160101_103_dialog_content = "<color=#e8d9bb>啪啪啪啪啪啪啪啪啪——</color>",
  ui_story_1016_10160101_104_dialog_content = "接下來我要進行學員登記。",
  ui_story_1016_10160101_105_dialog_content = "在你們的邀請函上，記載著每個人所分配的小隊。",
  ui_story_1016_10160101_106_dialog_content = "一支小隊裡包含三個學員，它代表著軍演中一切團體行動的基本單位。",
  ui_story_1016_10160101_107_dialog_content = "隊長所屬的陣營，即代表這支小隊的陣營。",
  ui_story_1016_10160101_108_dialog_content = "請大家快速確認一下，找到自己小隊的成員。",
  ui_story_1016_10160101_109_dialog_content = "和我一組的是薇絲和卡蓮，對吧？",
  ui_story_1016_10160101_110_dialog_content = "當然啦，我們不是早就確認過了。",
  ui_story_1016_10160101_111_dialog_content = "邀請函上寫著你的名字，你可要當好我們的隊長。",
  ui_story_1016_10160101_112_dialog_content = "哎呀，不要這麼說……",
  ui_story_1016_10160101_113_dialog_content = "確認好分組的學員可以來我這裡登記。",
  ui_story_1016_10160101_114_dialog_content = "分組結束後，請大家跟隨我前往住宿區，安置好行李後，可以在被允許的範圍內自由活動。",
  ui_story_1016_10160101_115_dialog_content = "你們的第一堂課將從明天開始。",
  ui_story_1016_10160101_116_dialog_content = "好興奮啊！",
  ui_story_1016_10160101_117_dialog_content = "從小就聽說過聯合軍演，但親身參與還是第一次。",
  ui_story_1016_10160101_118_dialog_content = "卡蓮，妳上次來是什麼感覺？",
  ui_story_1016_10160101_119_dialog_content = "跟妳現在差不多。",
  ui_story_1016_10160101_120_dialog_content = "興奮、躍躍欲試，但是沒什麼信心。",
  ui_story_1016_10160101_121_dialog_content = "沒什麼信心然後拿了個冠軍嗎？",
  ui_story_1016_10160101_122_dialog_content = "優等生的能力可真讓人羡慕啊～",
  ui_story_1016_10160101_123_dialog_content = "沒、沒有！我沒有炫耀的意思！",
  ui_story_1016_10160101_124_dialog_content = "哈哈，我是在逗妳玩呢！",
  ui_story_1016_10160101_125_dialog_content = "PlayerName是怎麼想的？看你都半天沒說話了。",
  ui_story_1016_10160101_126_dialog_content = "是不習慣這種緊繃的氛圍嗎？",
  ui_story_1016_10160101_127_dialog_content = "我在想……不少學員都是我們的朋友。",
  ui_story_1016_10160101_128_dialog_content = "要彼此競爭的話，我還沒做好心裡準備。",
  ui_story_1016_10160101_129_dialog_content = "嗯，以你的性格，確實像是會排斥競爭的。",
  ui_story_1016_10160101_130_dialog_content = "沒關係，我們以學習為主就好了，競爭意識不必那麼重。",
  ui_story_1016_10160101_131_dialog_content = "但是我這次想贏……",
  ui_story_1016_10160101_132_dialog_content = "嗯？",
  ui_story_1016_10160101_133_dialog_content = "今天我在「冠軍旗」上發現了空裔的旗幟。",
  ui_story_1016_10160101_134_dialog_content = "能看到族人留下的痕跡我很開心，但是……",
  ui_story_1016_10160101_135_dialog_content = "但看著它距離最新的一面旗幟那麼遠，又覺得很難過。",
  ui_story_1016_10160101_136_dialog_content = "空裔已經有那麼多年沒出現在賽場上了啊……",
  ui_story_1016_10160101_137_dialog_content = "我不希望承載著空裔榮譽的旗幟變成古董定格在那裡。",
  ui_story_1016_10160101_138_dialog_content = "我想掛一面新的上去。",
  ui_story_1016_10160101_139_dialog_content = "聽好了，我們可是全員來自白夜城的小隊。",
  ui_story_1016_10160101_140_dialog_content = "我們的表現反映著白夜城的教育素養。",
  ui_story_1016_10160101_141_dialog_content = "不要讓黎明學院丟臉喔。",
  ui_story_1016_10160101_142_dialog_content = "隊長大人，一上來就開始說教啊。",
  ui_story_1016_10160101_143_dialog_content = "這、這不是說教！",
  ui_story_1016_10160101_144_dialog_content = "我只是覺得大家應該打起精神認真應對……",
  ui_story_1016_10160101_145_dialog_content = "是啊，參與軍演的學員們全都實力強勁。",
  ui_story_1016_10160101_146_dialog_content = "我們必須打起精神，才不至於落後。",
  ui_story_1016_10160101_147_dialog_content = "這麼說來，妳們對其他隊伍有印象嗎？",
  ui_story_1016_10160101_148_dialog_content = "我只記住了PlayerName的隊伍。",
  ui_story_1016_10160101_149_dialog_content = "空裔的特殊能力配合卡蓮殿下與薇絲的力量，感覺實力很強啊。",
  ui_story_1016_10160101_150_dialog_content = "嗯，卡蓮殿下還是上一屆的勝者，這次說不定要衛冕了呢。",
  ui_story_1016_10160101_151_dialog_content = "除了PlayerName他們，還有兩支隊伍很值得關注。",
  ui_story_1016_10160101_152_dialog_content = "一支是李奧帶領的小隊，三名成員全部來自黃昏鎮。",
  ui_story_1016_10160101_153_dialog_content = "之前執行任務的時候，我見識過黃昏鎮那些人的戰鬥方式。",
  ui_story_1016_10160101_154_dialog_content = "他們有著豐富的實戰經驗，這一點其他任何隊伍都無法比擬。",
  ui_story_1016_10160101_155_dialog_content = "實戰經驗啊，確實是非常寶貴的東西。",
  ui_story_1016_10160101_156_dialog_content = "明明是同齡人，在這方面卻已經拉開了巨大的差距。",
  ui_story_1016_10160101_157_dialog_content = "還有一支是鶯歌帶領的小隊，組內成員分別是阿克希亞和阿納托利。",
  ui_story_1016_10160101_158_dialog_content = "這三人都是啟光年輕一代中最頂尖的戰士。",
  ui_story_1016_10160101_159_dialog_content = "他們背後有啟光深厚的科學技術支撐，實力難以捉摸。",
  ui_story_1016_10160101_160_dialog_content = "唔……跟科學有關的話，好像是我們討厭的東西。",
  ui_story_1016_10160101_161_dialog_content = "贊成。不想跟他們做對手。",
  ui_story_1016_10160101_162_dialog_content = "這次既然是來迦南城做客，我們只能接受啟光的做法。",
  ui_story_1016_10160101_163_dialog_content = "就當是一種實踐學習吧。",
  ui_story_1016_10160101_164_dialog_content = "話是這麼說啦，可是「接受」也不是一件容易的事。",
  ui_story_1016_10160101_165_dialog_content = "就像隊長妳逛了這麼久，還是沒接受迦南城的地形一樣。",
  ui_story_1016_10160101_166_dialog_content = "怎、怎麼說到我身上來了！",
  ui_story_1016_10160101_167_dialog_content = "因為我想回宿舍啊，隊長。什麼時候才能找到正確的路呢？",
  ui_story_1016_10160101_168_dialog_content = "馬上！我已經看懂了！",
  ui_story_1016_10160101_169_dialog_content = "只要在這個地方右轉……",
  ui_story_1016_10160101_170_dialog_content = "<color=#e8d9bb>嘭！</color>",
  ui_story_1016_10160101_171_dialog_content = "<size=45>唉唷！</size>",
  ui_story_1016_10160101_172_dialog_content = "唔……",
  ui_story_1016_10160101_173_dialog_content = "對、對不起！沒有仔細看路，不小心撞到你了！",
  ui_story_1016_10160101_174_dialog_content = "你沒事吧？",
  ui_story_1016_10160101_175_dialog_content = "沒事，我經常會被人撞到，這不怪妳。",
  ui_story_1016_10160101_176_dialog_content = "可以幫我把手杖遞過來嗎？我不知道它掉到哪裡去了。",
  ui_story_1016_10160101_177_dialog_content = "來，您的手杖。",
  ui_story_1016_10160101_178_dialog_content = "您是……盲人？",
  ui_story_1016_10160101_179_dialog_content = "讓各位見笑了。",
  ui_story_1016_10160101_180_dialog_content = "嗚哇對不起！那我就更不該撞到你了！",
  ui_story_1016_10160101_181_dialog_content = "你要去什麼地方啊，我們帶你去吧！",
  ui_story_1016_10160101_182_dialog_content = "不用這麼客氣。我在找人，一個穿著玩偶服的矮個子女生，妳們有看到嗎？",
  ui_story_1016_10160101_183_dialog_content = "沒有……",
  ui_story_1016_10160101_184_dialog_content = "那就不勞費心了，我自己去找吧。",
  ui_story_1016_10160101_185_dialog_content = "對了。我跟各位一樣，都是來參加軍演的學員。",
  ui_story_1016_10160101_186_dialog_content = "嗯？",
  ui_story_1016_10160101_187_dialog_content = "我叫狄希斯，課堂上請多指教。",
  ui_story_1016_10160101_188_dialog_content = "這次計畫的宗旨是高調，明白嗎？",
  ui_story_1016_10160101_189_dialog_content = "戰爭主題的扮家家酒對我們沒有意義，真正重要的是如何發出聲音。",
  ui_story_1016_10160101_190_dialog_content = "我們必須讓全世界清楚，黃昏鎮即將爆發一場災難。",
  ui_story_1016_10160101_191_dialog_content = "我猜到你盯上什麼東西了。",
  ui_story_1016_10160101_192_dialog_content = "真會賣弄自己的聰明才智，那你來說。",
  ui_story_1016_10160101_193_dialog_content = "你盯上了跟大元帥對決的機會。",
  ui_story_1016_10160101_194_dialog_content = "哈哈哈，沒錯！還有什麼新聞能比戰勝萊因哈特更大嗎！",
  ui_story_1016_10160101_195_dialog_content = "你的胃口還是這麼大。",
  ui_story_1016_10160101_196_dialog_content = "你覺得我太誇張了？",
  ui_story_1016_10160101_197_dialog_content = "在軍演上拔得頭籌、獲得與大元帥對決的機會不算困難。",
  ui_story_1016_10160101_198_dialog_content = "但是，我不覺得你能在一對一的戰鬥中贏她。",
  ui_story_1016_10160101_199_dialog_content = "嘶，真直接啊。",
  ui_story_1016_10160101_200_dialog_content = "單打獨鬥不是你的強項。我應該不用在這方面照顧你的自尊吧？",
  ui_story_1016_10160101_201_dialog_content = "不用，我自己心裡清楚。",
  ui_story_1016_10160101_202_dialog_content = "不過，計畫裡要去跟萊因哈特對決的人並不是我。",
  ui_story_1016_10160101_203_dialog_content = "！！！",
  ui_story_1016_10160101_204_dialog_content = "怪不得你選擇帶他來……",
  ui_story_1016_10160101_205_dialog_content = "我不知道若瑟有幾成勝算。",
  ui_story_1016_10160101_206_dialog_content = "但是我確定，那場戰鬥發出的「聲音」一定夠大。",
  ui_story_1016_10160101_207_dialog_content = "你們聽，有人在哭。",
  ui_story_1016_10160101_208_dialog_content = "嗯？",
  ui_story_1016_10160101_209_dialog_content = "靜下心來，仔細去聽。",
  ui_story_1016_10160101_210_dialog_content = "<size=30>嗚……嗚……</size>",
  ui_story_1016_10160101_211_dialog_content = "還真的有！",
  ui_story_1016_10160101_212_dialog_content = "好奇怪的哭聲，聽起來並不悲傷。",
  ui_story_1016_10160101_213_dialog_content = "聲音接近了，對方在往這邊走。",
  ui_story_1016_10160101_214_dialog_content = "嗚……",
  ui_story_1016_10160101_215_dialog_content = "喔，少見的亞人血統。",
  ui_story_1016_10160101_216_dialog_content = "您還好嗎？我從遠處就聽到了您的哭聲。",
  ui_story_1016_10160101_217_dialog_content = "嗯？您在問我嗎？",
  ui_story_1016_10160101_218_dialog_content = "對不起，對您造成困擾了。",
  ui_story_1016_10160101_219_dialog_content = "我只是在因頭痛而難受，這是我的老毛病了。",
  ui_story_1016_10160101_220_dialog_content = "痛到哭出來嗎，聽起來還滿嚴重的……",
  ui_story_1016_10160101_221_dialog_content = "我在火車站見過妳，妳也是參加軍演的學員。",
  ui_story_1016_10160101_222_dialog_content = "是的，我叫梅里。",
  ui_story_1016_10160101_223_dialog_content = "從哪裡來的？",
  ui_story_1016_10160101_224_dialog_content = "影鎮。",
  ui_story_1016_10160101_225_dialog_content = "幾個人？",
  ui_story_1016_10160101_226_dialog_content = "加上我一共三人。",
  ui_story_1016_10160101_227_dialog_content = "這麼說來我還想問一下，你們有沒有看到過一個穿著玩偶服的矮個子女生？",
  ui_story_1016_10160101_228_dialog_content = "她是我的隊友，好像在周圍迷路了。",
  ui_story_1016_10160101_229_dialog_content = "沒有，我們這段時間見過的學員就只有妳。",
  ui_story_1016_10160101_230_dialog_content = "這樣啊。那要是沒有其他事情的話，我就繼續去找她了。",
  ui_story_1016_10160101_231_dialog_content = "謝謝幾位的關心，我們軍演上再見。",
  ui_story_1016_10160101_232_dialog_content = "你剛才在幹嘛，盤問人家？",
  ui_story_1016_10160101_233_dialog_content = "算不上吧，隨便問問基本資訊。",
  ui_story_1016_10160101_234_dialog_content = "是覺得她可疑？",
  ui_story_1016_10160101_235_dialog_content = "現在還說不清楚，再看看吧。",
  ui_story_1016_10160101_236_dialog_content = "我把收到的命令同步一下。",
  ui_story_1016_10160101_237_dialog_content = "我們這支小隊必須拿下冠軍，不惜一切代價。",
  ui_story_1016_10160101_238_dialog_content = "有疑問嗎？",
  ui_story_1016_10160101_239_dialog_content = "沒有。",
  ui_story_1016_10160101_240_dialog_content = "……這是委員會的命令嗎？",
  ui_story_1016_10160101_241_dialog_content = "是的。",
  ui_story_1016_10160101_242_dialog_content = "好吧，那我沒有疑問了。",
  ui_story_1016_10160101_243_dialog_content = "考核階段之前，我們沒有特別的計畫，正常參與課程即可。",
  ui_story_1016_10160101_244_dialog_content = "唯一需要注意的就是保持低調，不要樹敵也不要引起關注。",
  ui_story_1016_10160101_245_dialog_content = "我們收到的命令必須嚴格保密，出了這個屋子之後，絕不能告訴第四個人。",
  ui_story_1016_10160101_246_dialog_content = "明白。",
  ui_story_1016_10160101_247_dialog_content = "明白。",
  ui_story_1016_10160101_248_dialog_content = "好了，要說的就這些。可以解散了。",
  ui_story_1016_10160101_249_dialog_content = "嗯，阿克希亞睏了。",
  ui_story_1016_10160101_250_dialog_content = "進休眠艙吧，我送妳回去。",
  ui_story_1016_10160101_251_dialog_content = "阿納托利，幫我開一下門。",
  ui_story_1016_10160101_252_dialog_content = "好——",
  ui_story_1016_10160101_253_dialog_content = "<color=#e8d9bb>吱——</color>",
  ui_story_1016_10160101_254_dialog_content = "哎呀！",
  ui_story_1016_10160101_255_dialog_content = "門外有人！",
  ui_story_1016_10160101_256_dialog_content = "誰？",
  ui_story_1016_10160101_257_dialog_content = "痛死了！開門輕一點啊！",
  ui_story_1016_10160101_258_dialog_content = "真是的，腦袋上要腫一個大包了！",
  ui_story_1016_10160101_259_dialog_content = "……",
  ui_story_1016_10160101_260_dialog_content = "這孩子，敵人？",
  ui_story_1016_10160101_261_dialog_content = "幹嘛那樣看著我！",
  ui_story_1016_10160101_262_dialog_content = "我、我又沒有偷聽你們說話！",
  ui_story_1016_10160101_263_dialog_content = "我還沒說妳偷聽呢。",
  ui_story_1016_10160101_264_dialog_content = "妳……",
  ui_story_1016_10160101_265_dialog_content = "明詩！原來妳在這裡！",
  ui_story_1016_10160101_266_dialog_content = "我就說迦南城地形很複雜吧，怎麼能亂跑呢。",
  ui_story_1016_10160101_267_dialog_content = "梅里！妳好慢喔！",
  ui_story_1016_10160101_268_dialog_content = "你們是……同伴嗎？",
  ui_story_1016_10160101_269_dialog_content = "對不起，我的朋友給您添麻煩了。",
  ui_story_1016_10160101_270_dialog_content = "我們第一次來迦南城，這裡地形太複雜了，難免有些迷路。",
  ui_story_1016_10160101_271_dialog_content = "打擾到您了嗎？",
  ui_story_1016_10160101_272_dialog_content = "狄希斯你怎麼幫他們說話！明明是他們開門撞到我了！",
  ui_story_1016_10160101_273_dialog_content = "算了算了，明詩。對新朋友要禮貌一點。",
  ui_story_1016_10160101_274_dialog_content = "……",
  ui_story_1016_10160101_275_dialog_content = "沒有別的事的話，我們就先走了。",
  ui_story_1016_10160101_276_dialog_content = "是啊，趁我還記得回去的方向。",
  ui_story_1016_10160101_277_dialog_content = "哼，拜拜！咧～",
  ui_story_1016_10160101_278_dialog_content = "這三人也是參加軍演的學員，來自影鎮。",
  ui_story_1016_10160101_279_dialog_content = "放他們走沒問題嗎，談話的內容說不定被聽見了。",
  ui_story_1016_10160101_280_dialog_content = "如果真的被聽見了，我會想辦法補救的。",
  ui_story_1016_10160101_281_dialog_content = "走吧，我們也回去休息。",
  ui_story_1016_10160101_282_dialog_content = "該為明天的第一堂課做準備了。",
  ui_story_1016_10160101_283_dialog_content = "<color=#e8d9bb>嗒、嗒、嗒、嗒……</color>",
  ui_story_1016_10160101_284_dialog_content = "他們……走了嗎？",
  ui_story_1016_10160101_285_dialog_content = "嗯，最後一波衛兵已經離開了。",
  ui_story_1016_10160101_286_dialog_content = "赫利俄斯，你現在身體怎麼樣？",
  ui_story_1016_10160101_287_dialog_content = "不用管我……只是小傷。",
  ui_story_1016_10160101_288_dialog_content = "我……隨時可以戰鬥。",
  ui_story_1016_10160101_289_dialog_content = "這裡是迦南城，一旦被他們發現，整個啟光的兵力都會來圍剿我們。",
  ui_story_1016_10160101_290_dialog_content = "憑蠻力是闖不出去的。",
  ui_story_1016_10160101_291_dialog_content = "但是……",
  ui_story_1016_10160101_292_dialog_content = "再忍一忍，越是這種情況越要冷靜。",
  ui_story_1016_10160101_293_dialog_content = "我們還需要一點時間。",
  ui_story_1016_10160101_294_dialog_content = "妳在等什麼？",
  ui_story_1016_10160101_295_dialog_content = "等「<color=#FFB400>罪靈</color>」。",
  ui_story_1016_10160201_1_dialog_content = "<anim type=Shake>哈啊——</anim>沒睡好覺。",
  ui_story_1016_10160201_2_dialog_content = "這城市裡到處都有股工業的臭味。",
  ui_story_1016_10160201_3_dialog_content = "實驗室？！把我們帶來這裡做什麼！",
  ui_story_1016_10160201_4_dialog_content = "我可不是來給啟光當實驗品的啊！",
  ui_story_1016_10160201_5_dialog_content = "啊，好熟悉的地方。",
  ui_story_1016_10160201_6_dialog_content = "我好像猜到要做什麼了。",
  ui_story_1016_10160201_7_dialog_content = "<color=#e8d9bb>鈴——</color>",
  ui_story_1016_10160201_8_dialog_content = "吵死了吵死了！都給我安靜！",
  ui_story_1016_10160201_9_dialog_content = "我是你們的教官貢露，與科學研究相關的課程都會由我負責。",
  ui_story_1016_10160201_10_dialog_content = "當然，我知道你們絕大多數人沒有沉下心做研究的興趣，我也不想搞得氣氛沉悶。",
  ui_story_1016_10160201_11_dialog_content = "所以在第一堂課上，我準備拿出最好玩……最先進的研究成果！",
  ui_story_1016_10160201_12_dialog_content = "來見識一下吧，啟光新研製的士兵訓練裝置——",
  ui_story_1016_10160201_13_dialog_content = "「<color=#FFB400>戰鬥模擬器</color>」。",
  ui_story_1016_10160201_14_dialog_content = "果然是它啊。",
  ui_story_1016_10160201_15_dialog_content = "一個頭盔？這能做什麼訓練？",
  ui_story_1016_10160201_16_dialog_content = "它可比真刀真槍要管用多了。",
  ui_story_1016_10160201_17_dialog_content = "訓練一名士兵最難提升的地方是什麼？",
  ui_story_1016_10160201_18_dialog_content = "是身體素質嗎？還是光能術水準？",
  ui_story_1016_10160201_19_dialog_content = "是戰鬥素養。",
  ui_story_1016_10160201_20_dialog_content = "對，戰鬥素養才是最難培養的。",
  ui_story_1016_10160201_21_dialog_content = "戰場上會經歷的事情，只有親臨戰場才能體會得到。",
  ui_story_1016_10160201_22_dialog_content = "可戰場是很殘酷的，不是每個士兵都有活著帶走經驗的權利。",
  ui_story_1016_10160201_23_dialog_content = "除非，他們可以經歷一場「虛擬」的戰鬥。",
  ui_story_1016_10160201_24_dialog_content = "虛擬的戰鬥，該怎麼做到……",
  ui_story_1016_10160201_25_dialog_content = "這就是你們要在第一堂課上體驗的內容了！",
  ui_story_1016_10160201_26_dialog_content = "跟我手上這台一樣的裝置接下來會發到你們每個人手上。",
  ui_story_1016_10160201_27_dialog_content = "戴上頭盔之後，你們將共同進入到一片虛擬的戰場。",
  ui_story_1016_10160201_28_dialog_content = "在那裡，光能術和各種兵器都能照常使用，面對的敵人當然是大家的老朋友暗鬼。",
  ui_story_1016_10160201_29_dialog_content = "直到「戰死」之前，請把它當作現實對待。",
  ui_story_1016_10160201_30_dialog_content = "哈哈哈，聽起來滿有趣的啊。",
  ui_story_1016_10160201_31_dialog_content = "就是不知道能不能還原現實戰場的情況。",
  ui_story_1016_10160201_32_dialog_content = "好！看起來學員們都很有熱情！",
  ui_story_1016_10160201_33_dialog_content = "我馬上幫你們分發頭盔，開始今天的模擬戰鬥訓練。",
  ui_story_1016_10160201_34_dialog_content = "戰鬥中大家的表現會被換算成分數，顯示在旁邊的螢幕上。",
  ui_story_1016_10160201_35_dialog_content = "數字不會埋沒任何一位人才，在排行榜上展現你們的天賦吧！",
  ui_story_1016_10160201_36_dialog_content = "<color=#e8d9bb>您已進入模擬戰場。</color>",
  ui_story_1016_10160201_37_dialog_content = "果然跟之前的使用方法一樣。",
  ui_story_1016_10160201_38_dialog_content = "薇絲和卡蓮呢，還沒戴好頭盔嗎？",
  ui_story_1016_10160201_39_dialog_content = "唔，這裡是……",
  ui_story_1016_10160201_40_dialog_content = "呀！畫面一下子蹦出來了！",
  ui_story_1016_10160201_41_dialog_content = "看樣子戰場模擬器更成熟了，現在身體的感受與在現實中毫無差異。",
  ui_story_1016_10160201_42_dialog_content = "也許跟現實相似的戰場更能激發我們的危機意識吧。",
  ui_story_1016_10160201_43_dialog_content = "這周圍看起來像是啟光的防線？",
  ui_story_1016_10160201_44_dialog_content = "<color=#e8d9bb>系統偵測到學員已全數就位。</color>",
  ui_story_1016_10160201_45_dialog_content = "<color=#e8d9bb>提示：本次戰場模擬了一場真實發生在啟光的戰鬥。</color>",
  ui_story_1016_10160201_46_dialog_content = "<color=#e8d9bb>突如其來的暗鬼浪潮衝破了軍隊防線，造成巨大的損失。</color>",
  ui_story_1016_10160201_47_dialog_content = "<color=#e8d9bb>為了配合學員的戰鬥能力，模擬器會將戰鬥規模縮減至三人小隊能夠應付的程度。</color>",
  ui_story_1016_10160201_48_dialog_content = "<color=#e8d9bb>各小隊已隨機分配至戰場四周，祝學員好運。</color>",
  ui_story_1016_10160201_49_dialog_content = "<color=#e8d9bb>戰鬥開始。</color>",
  ui_story_1016_10160201_50_dialog_content = "原來大家被分配到不同的地方了。",
  ui_story_1016_10160201_51_dialog_content = "嗯，可能是為了避免隊伍之間互相影響。",
  ui_story_1016_10160201_52_dialog_content = "說是模擬了真實發生在啟光的戰鬥，要是能瞭解一下事件的原型就好了。",
  ui_story_1016_10160201_53_dialog_content = "薇絲，妳知道這是哪場戰鬥嗎？",
  ui_story_1016_10160201_54_dialog_content = "不知道。發生在啟光周邊的戰鬥數不勝數，防線被擊潰的情況也不在少數。",
  ui_story_1016_10160201_55_dialog_content = "如果站在歷史的角度上來看，這就是啟光防線的常態。",
  ui_story_1016_10160201_56_dialog_content = "常態的戰爭啊……",
  ui_story_1016_10160201_57_dialog_content = "我看到暗鬼了！",
  ui_story_1016_10160201_58_dialog_content = "這個數量……真的是三人小隊能應付的嗎？",
  ui_story_1016_10160201_59_dialog_content = "嘶……事件原型裡，軍隊防線被暗鬼浪潮衝破。",
  ui_story_1016_10160201_60_dialog_content = "這是不是意味著，哪怕縮減了戰鬥規模，我們仍然沒辦法扭轉防線崩潰的局面。",
  ui_story_1016_10160201_61_dialog_content = "我們面對這群暗鬼時的無力感，就跟當年陣地上那些士兵一樣……",
  ui_story_1016_10160201_62_dialog_content = "是啊，好在這只是虛擬的。",
  ui_story_1016_10160201_63_dialog_content = "我們盡力而為吧！",
  ui_story_1016_10160201_64_dialog_content = "沒錯，我們上！",
  ui_story_1016_10160202_1_dialog_content = "卡蓮！快往後撤！",
  ui_story_1016_10160202_2_dialog_content = "我也想，但是……",
  ui_story_1016_10160202_3_dialog_content = "怎麼感覺暗鬼越打越多了。",
  ui_story_1016_10160202_4_dialog_content = "是的，就像在往我們這邊聚集一樣。",
  ui_story_1016_10160202_5_dialog_content = "再不脫身的話，我們馬上就要被淹沒了……",
  ui_story_1016_10160202_6_dialog_content = "咦？卡蓮殿下！",
  ui_story_1016_10160202_7_dialog_content = "貝爾塔？！妳怎麼在這裡。",
  ui_story_1016_10160202_8_dialog_content = "我、我們的小隊被暗鬼浪潮分散了。",
  ui_story_1016_10160202_9_dialog_content = "我獨自一人陷入被動，只能且戰且退。",
  ui_story_1016_10160202_10_dialog_content = "中途還遇到了一些其他的學員……",
  ui_story_1016_10160202_11_dialog_content = "別光顧著說話，注意敵人。",
  ui_story_1016_10160202_12_dialog_content = "我當然在注意！不用你提醒我！",
  ui_story_1016_10160202_13_dialog_content = "阿納托利也在這裡！我記得你是跟鶯歌一起的吧。",
  ui_story_1016_10160202_14_dialog_content = "你們的隊伍也被打散了嗎？",
  ui_story_1016_10160202_15_dialog_content = "是的，我們在戰鬥中受到了一些其他組別的干擾。",
  ui_story_1016_10160202_16_dialog_content = "喂！什麼叫「其他組別的干擾」！我們不是在合作嗎？",
  ui_story_1016_10160202_17_dialog_content = "拖後腿的行為我只能稱之為「干擾」。",
  ui_story_1016_10160202_18_dialog_content = "哼！",
  ui_story_1016_10160202_19_dialog_content = "沒見過的學員，妳是……",
  ui_story_1016_10160202_20_dialog_content = "不行了PlayerName！敵人太多了！",
  ui_story_1016_10160202_21_dialog_content = "這樣下去我們是撐不住的！",
  ui_story_1016_10160202_22_dialog_content = "確實，暗鬼的數量還在增加……",
  ui_story_1016_10160202_23_dialog_content = "貝爾塔、阿納托利！還有不知道名字的學員！",
  ui_story_1016_10160202_24_dialog_content = "<size=45>我叫明詩！！！</size>",
  ui_story_1016_10160202_25_dialog_content = "我們合作吧！試試看能不能撤出戰場中心！",
  ui_story_1016_10160202_26_dialog_content = "現在說合作好像……我已經騰不出手了……",
  ui_story_1016_10160202_27_dialog_content = "呃……嗚啊——！",
  ui_story_1016_10160202_28_dialog_content = "<size=45>貝爾塔！！！</size>",
  ui_story_1016_10160202_29_dialog_content = "糟了，她剛才承受的壓力會一下子轉移到我們這邊。",
  ui_story_1016_10160202_30_dialog_content = "哇哇哇哇！暗鬼要撲過來了！怎麼辦！",
  ui_story_1016_10160202_31_dialog_content = "盡量撐得久一點吧……",
  ui_story_1016_10160202_32_dialog_content = "你們向背後的方向突破！那邊的暗鬼數量稍微少一點！",
  ui_story_1016_10160202_34_dialog_content = "小心，PlayerName！",
  ui_story_1016_10160202_35_dialog_content = "嗚哇——",
  ui_story_1016_10160202_36_dialog_content = "快轉身！你們背後——",
  ui_story_1016_10160202_37_dialog_content = "<color=#e8d9bb>嗶——</color>",
  ui_story_1016_10160202_38_dialog_content = "<color=#e8d9bb>系統提示：已退出戰鬥模擬器。</color>",
  ui_story_1016_10160202_39_dialog_content = "呼——退出來了？",
  ui_story_1016_10160202_40_dialog_content = "戰場模擬器帶來的瀕死感還是那麼令人難受……",
  ui_story_1016_10160202_41_dialog_content = "薇絲和卡蓮呢？",
  ui_story_1016_10160202_42_dialog_content = "呼——還是被幹掉了啊。",
  ui_story_1016_10160202_43_dialog_content = "嗯，面對那個數量的暗鬼，怎麼做都於事無補了。",
  ui_story_1016_10160202_44_dialog_content = "哈哈，妳們也出來了啊。使用戰鬥模擬器的感覺怎麼樣？",
  ui_story_1016_10160202_45_dialog_content = "出乎意料地真實。確實像貢露說的那樣，可以利用它訓練戰鬥素養。",
  ui_story_1016_10160202_46_dialog_content = "像剛才那麼緊張的戰鬥，現實中很難遇到。",
  ui_story_1016_10160202_47_dialog_content = "真的遇到的話，恐怕我們就沒法全身而退了。",
  ui_story_1016_10160202_48_dialog_content = "是啊，經歷過之後，更加深刻地認識到啟光面臨的戰爭壓力有多麼嚴峻。",
  ui_story_1016_10160202_49_dialog_content = "軍人們總是會面臨一些……注定要失敗的戰爭。",
  ui_story_1016_10160202_50_dialog_content = "是啊……",
  ui_story_1016_10160202_51_dialog_content = "離開戰鬥模擬器的同學們先不要吵鬧，看我這裡。",
  ui_story_1016_10160202_52_dialog_content = "想必你們在剛才的戰鬥中有所感悟，對模擬器也有了一些自己的看法。",
  ui_story_1016_10160202_53_dialog_content = "這裡呢，有一張關於戰鬥模擬器體驗感受的調查表。",
  ui_story_1016_10160202_54_dialog_content = "大家趁現在填寫一下吧！",
  ui_story_1016_10160202_55_dialog_content = "呃……怎麼還要填表啊……",
  ui_story_1016_10160202_56_dialog_content = "貢露教官，不會是在拿我們做實驗吧？",
  ui_story_1016_10160202_57_dialog_content = "哎呀，怎麼能這麼說呢！",
  ui_story_1016_10160202_58_dialog_content = "有了這些調查表提供的資料，我們可以進一步改善模擬器的效能。",
  ui_story_1016_10160202_59_dialog_content = "這不是對大家都有好處的事情嗎？對吧？",
  ui_story_1016_10160202_60_dialog_content = "好吧好吧……",
  ui_story_1016_10160202_61_dialog_content = "<color=#e8d9bb>二十分鐘後</color>",
  ui_story_1016_10160202_62_dialog_content = "總算是填完了，好長的表啊……",
  ui_story_1016_10160202_63_dialog_content = "是啊，我手都寫酸了！",
  ui_story_1016_10160202_64_dialog_content = "調查表最後要填寫這次模擬戰鬥的分數。我們的分數是多少？",
  ui_story_1016_10160202_65_dialog_content = "對啊，還不知道這次表現算好算壞呢。",
  ui_story_1016_10160202_66_dialog_content = "貢露教官，分數要從哪裡看啊？",
  ui_story_1016_10160202_67_dialog_content = "這個啊，還得稍等一下。",
  ui_story_1016_10160202_68_dialog_content = "有幾位學員還沒退出戰鬥模擬器。",
  ui_story_1016_10160202_69_dialog_content = "還沒退出？！都這麼久了……",
  ui_story_1016_10160202_70_dialog_content = "<color=#e8d9bb>系統提示：本次模擬戰鬥已完成。</color>",
  ui_story_1016_10160202_71_dialog_content = "<color=#e8d9bb>根據結束狀態對本次戰況進行判定——</color>",
  ui_story_1016_10160202_72_dialog_content = "<color=#e8d9bb>戰爭結果，光靈方獲勝。</color>",
  ui_story_1016_10160202_73_dialog_content = "啊？我們贏了？",
  ui_story_1016_10160202_74_dialog_content = "<size=45>獲勝？！！</size>",
  ui_story_1016_10160202_75_dialog_content = "不可能啊，真的有人能把這一關打通嗎……",
  ui_story_1016_10160202_76_dialog_content = "最後才離開模擬器的是誰——",
  ui_story_1016_10160202_77_dialog_content = "呼，頭盔戴久了好不舒服。",
  ui_story_1016_10160202_78_dialog_content = "還不錯，模擬出來的戰場滿真實的。",
  ui_story_1016_10160202_79_dialog_content = "身處在戰火之中，啟光對戰爭的想像果然十分準確。",
  ui_story_1016_10160202_80_dialog_content = "但是過於真實也帶來了問題。",
  ui_story_1016_10160202_81_dialog_content = "只要瞭解模擬戰場的原型，就可以充分預知戰場上的變化。",
  ui_story_1016_10160202_82_dialog_content = "難度因此下降太多了。",
  ui_story_1016_10160202_83_dialog_content = "他、他覺得難度還算低嗎？",
  ui_story_1016_10160202_84_dialog_content = "我不喜歡裡面的環境。",
  ui_story_1016_10160202_85_dialog_content = "無論我如何虔誠地呼喚，回應我的都只有虛假的「光」。",
  ui_story_1016_10160202_86_dialog_content = "別太認真了，若瑟。就當做是個遊戲嘛。",
  ui_story_1016_10160202_87_dialog_content = "計分板上的成績出來了！",
  ui_story_1016_10160202_88_dialog_content = "李奧他們……分數好高……",
  ui_story_1016_10160202_89_dialog_content = "毫無爭議的第一啊……",
  ui_story_1016_10160202_90_dialog_content = "我們是處在同一片戰場上的對吧？",
  ui_story_1016_10160202_91_dialog_content = "面對數量如此龐大的暗鬼，究竟是怎麼取勝的……",
  ui_story_1016_10160202_92_dialog_content = "我看到了他們是如何戰鬥的。",
  ui_story_1016_10160202_93_dialog_content = "是他們……「製造」了那道摧毀防線的暗鬼浪潮……",
  ui_story_1016_10160202_94_dialog_content = "什麼？！",
  ui_story_1016_10160202_95_dialog_content = "暗鬼浪潮是他們製造的？怎麼可能！",
  ui_story_1016_10160202_96_dialog_content = "真的是這樣。他們懂得在戰鬥中引導暗鬼隊伍的行進，讓它們逐漸聚集到一起。",
  ui_story_1016_10160202_97_dialog_content = "然後利用地形與暗鬼迂回、尋找機會，在數量無法發揮優勢的狹窄地帶進行絞殺。",
  ui_story_1016_10160202_98_dialog_content = "暗鬼就像被驅趕的羊群，一隻隻落入他們的尖牙利爪……",
  ui_story_1016_10160202_99_dialog_content = "驅趕暗鬼……竟然還能這樣戰鬥……",
  ui_story_1016_10160202_100_dialog_content = "其實沒有什麼。當你不得不面對十倍、百倍於己方的敵人時，你必須絞盡腦汁。",
  ui_story_1016_10160202_101_dialog_content = "書本上的內容就不用想了，沒有一本書能教會你如何打贏一場不可能取勝的戰鬥。",
  ui_story_1016_10160202_102_dialog_content = "你只能把腦袋裡所有可笑、荒謬的想法一個個拿出來試試。",
  ui_story_1016_10160202_103_dialog_content = "如果你有幸試過足夠多次還沒有戰死，那就說明你學會了在戰場上的必勝法。",
  ui_story_1016_10160202_104_dialog_content = "（對了，第一次見到李奧的時候，他就在用不可思議的方式作戰。）",
  ui_story_1016_10160202_105_dialog_content = "（黃昏鎮人對於戰鬥的想像力是我們無法比擬的。）",
  ui_story_1016_10160202_106_dialog_content = "嘖嘖，真是令人印象深刻。大家都不說話了呢。",
  ui_story_1016_10160202_107_dialog_content = "都學著點吧？你們一個個的這樣盯著積分榜上的數字……",
  ui_story_1016_10160202_108_dialog_content = "簡直像一群第一次看見刀槍的孩子。",
  ui_story_1016_10160301_1_dialog_content = "<color=#e8d9bb>一星期後</color>",
  ui_story_1016_10160301_2_dialog_content = "咦？前面怎麼是辦公區，走錯了嗎？",
  ui_story_1016_10160301_3_dialog_content = "我記得教室是在……",
  ui_story_1016_10160301_4_dialog_content = "PlayerName，你在逛什麼呢？",
  ui_story_1016_10160301_5_dialog_content = "課程馬上就要開始了。",
  ui_story_1016_10160301_6_dialog_content = "阿納托利！太好了！",
  ui_story_1016_10160301_7_dialog_content = "你知道教室要怎麼走嗎？我已經在走廊裡轉暈了，哈哈哈。",
  ui_story_1016_10160301_8_dialog_content = "原來是這樣，那跟我來吧。",
  ui_story_1016_10160301_9_dialog_content = "還好你碰到了我。要是遲到的話，說不定會扣你學分的。",
  ui_story_1016_10160301_10_dialog_content = "今天大家好像都在談論學分欸，它是做什麼用的？",
  ui_story_1016_10160301_11_dialog_content = "你沒看昨天發放的手冊嗎？",
  ui_story_1016_10160301_12_dialog_content = "還沒看，昨天被貢露拉去測試臨空者號了。",
  ui_story_1016_10160301_13_dialog_content = "那我跟你簡單講一下吧。",
  ui_story_1016_10160301_14_dialog_content = "從今天開始，大家在課程中的表現會被記錄為學分。",
  ui_story_1016_10160301_15_dialog_content = "每一位學員得到的學分將持續累積，直至課程階段結束。",
  ui_story_1016_10160301_16_dialog_content = "顯而易見的是，最終學分可以用來評判學員的能力。不過它還有更重要的作用。",
  ui_story_1016_10160301_17_dialog_content = "學分會在考核階段為學員提供幫助。",
  ui_story_1016_10160301_18_dialog_content = "幫助？",
  ui_story_1016_10160301_19_dialog_content = "考核之前可以用它兌換一些物資，增強大家的綜合實力。",
  ui_story_1016_10160301_20_dialog_content = "學分越多，獲得的優勢也就越大。",
  ui_story_1016_10160301_21_dialog_content = "所以大家都期望能在課程中多拿一些學分。",
  ui_story_1016_10160301_22_dialog_content = "怪不得，競爭的味道越來越濃了。",
  ui_story_1016_10160301_23_dialog_content = "是啊，想爭奪第一名的話就得繃緊神經了。",
  ui_story_1016_10160301_24_dialog_content = "教室到了，時間剛剛好。",
  ui_story_1016_10160301_25_dialog_content = "這次記住路了嗎？",
  ui_story_1016_10160301_26_dialog_content = "哈哈，希望我記住了。",
  ui_story_1016_10160301_27_dialog_content = "這堂課是什麼來著？",
  ui_story_1016_10160301_28_dialog_content = "實戰搏擊。",
  ui_story_1016_10160301_29_dialog_content = "<color=#e8d9bb>吱——</color>",
  ui_story_1016_10160301_30_dialog_content = "唷！你們兩個！",
  ui_story_1016_10160301_31_dialog_content = "你還差20秒就遲到了。",
  ui_story_1016_10160301_32_dialog_content = "這麼危險……",
  ui_story_1016_10160301_33_dialog_content = "好了，最慢的學員們已經到場，今天的課程該開始了。",
  ui_story_1016_10160301_34_dialog_content = "我是啟光近衛軍團長雷霆，也是你們今天的教官。",
  ui_story_1016_10160301_35_dialog_content = "這堂課要學的東西非常簡單——打架。",
  ui_story_1016_10160301_36_dialog_content = "打架？",
  ui_story_1016_10160301_37_dialog_content = "我知道你們想說「打架有什麼可學的」。",
  ui_story_1016_10160301_38_dialog_content = "而且能站在這裡的各位，多多少少都對自己的戰鬥能力有點自信。",
  ui_story_1016_10160301_39_dialog_content = "但是我也確定，你們之中的很多人在戰鬥上不夠俐落。",
  ui_story_1016_10160301_40_dialog_content = "我要教你們的不是如何打贏，而是如何完美地打贏。",
  ui_story_1016_10160301_41_dialog_content = "在能贏的戰鬥裡加快速度、省下力氣，才能以更好的狀態投入下一場戰鬥。",
  ui_story_1016_10160301_42_dialog_content = "勝利沒那麼簡單，你得把每個細節都做到完美。",
  ui_story_1016_10160301_43_dialog_content = "唔，這麼說的話確實……",
  ui_story_1016_10160301_44_dialog_content = "沒有在戰鬥效率上做過特別的訓練。",
  ui_story_1016_10160301_45_dialog_content = "道理沒錯，不過「完美」可是件困難的事情。",
  ui_story_1016_10160301_46_dialog_content = "教官能做到完美嗎？",
  ui_story_1016_10160301_47_dialog_content = "小子，你是在質疑我嗎？",
  ui_story_1016_10160301_48_dialog_content = "我擔心自己沒辦法在課上學到東西。",
  ui_story_1016_10160301_49_dialog_content = "呵，我倒是比較擔心你承受不住我的訓練。",
  ui_story_1016_10160301_50_dialog_content = "不說廢話了，大家按照小組站好。",
  ui_story_1016_10160301_51_dialog_content = "這堂課以實戰為主，你們的對手是訓練有素的啟光士兵。",
  ui_story_1016_10160301_52_dialog_content = "第一組，出列！",
  ui_story_1016_10160301_53_dialog_content = "<size=45>是！</size>",
  ui_story_1016_10160301_54_dialog_content = "向我們的學員們來點啟光的問候。",
  ui_story_1016_10160301_55_dialog_content = "<size=45>是！</size>",
  ui_story_1016_10160301_56_dialog_content = "對了，多「照顧」一下那個白夜城的騎士。",
  ui_story_1016_10160301_57_dialog_content = "要是還嫌不夠的話，你可以下了課後找我單練。",
  ui_story_1016_10160301_58_dialog_content = "算了吧，我寧願在課上多花點力氣。",
  ui_story_1016_10160301_59_dialog_content = "至少有學分拿，對吧？",
  ui_story_1016_10160301_60_dialog_content = "說得對，這是第一個賺學分的機會，必須要全力以赴。",
  ui_story_1016_10160301_61_dialog_content = "鶯歌，我呢？",
  ui_story_1016_10160301_62_dialog_content = "稍微輕一點。",
  ui_story_1016_10160301_63_dialog_content = "<size=32>看這些學員的樣子……我怎麼有點害怕……</size>",
  ui_story_1016_10160301_64_dialog_content = "<size=32>我……我也是……</size>",
  ui_story_1016_10160401_1_dialog_content = "<color=#e8d9bb>一個月後</color>",
  ui_story_1016_10160401_2_dialog_content = "好了，今天的課程到此為止。",
  ui_story_1016_10160401_3_dialog_content = "下課。",
  ui_story_1016_10160401_4_dialog_content = "不錯啊PlayerName，今天又賺到不少學分！",
  ui_story_1016_10160401_5_dialog_content = "呼，大家都卯足了勁，搶學分好累啊。",
  ui_story_1016_10160401_6_dialog_content = "現在已經進入白熱化階段，各組之間的競爭只會越來越激烈。",
  ui_story_1016_10160401_7_dialog_content = "看過今天的學分排行榜了嗎？",
  ui_story_1016_10160401_8_dialog_content = "還沒。我們現在排第幾？",
  ui_story_1016_10160401_9_dialog_content = "第三。",
  ui_story_1016_10160401_10_dialog_content = "哇，又上升了一名！",
  ui_story_1016_10160401_11_dialog_content = "局勢不錯啊。前兩名的情況呢？",
  ui_story_1016_10160401_12_dialog_content = "第一名沒什麼懸念，李奧的小隊遙遙領先。",
  ui_story_1016_10160401_13_dialog_content = "這個分數差……恐怕別的隊伍沒什麼超越的希望。",
  ui_story_1016_10160401_14_dialog_content = "果然還是他們啊……",
  ui_story_1016_10160401_15_dialog_content = "第二名是鶯歌的小隊，算是最近才顯露鋒芒的。",
  ui_story_1016_10160401_16_dialog_content = "他們的隊伍沒什麼弱點，各項課程都有不錯的表現，逐漸穩住了積分榜上的位置。",
  ui_story_1016_10160401_17_dialog_content = "我們的分數跟他們差多少？",
  ui_story_1016_10160401_18_dialog_content = "相當於他們差李奧組分數的一半吧。",
  ui_story_1016_10160401_19_dialog_content = "聽起來好多啊……",
  ui_story_1016_10160401_20_dialog_content = "鶯歌幾乎能近乎完美地完成每一堂課的要求，想超越他們確實有點難度。",
  ui_story_1016_10160401_21_dialog_content = "不過，課程外就不好說了。",
  ui_story_1016_10160401_22_dialog_content = "課程外？",
  ui_story_1016_10160401_23_dialog_content = "昨天我看到有的小組在課程外自行展開了訓練。",
  ui_story_1016_10160401_24_dialog_content = "他們把訓練結果上報之後，同樣獲得了學分。",
  ui_story_1016_10160401_25_dialog_content = "哦？還有這種方式！",
  ui_story_1016_10160401_26_dialog_content = "是的，看起來軍演主辦方的出發點是鼓勵大家多進行訓練。",
  ui_story_1016_10160401_27_dialog_content = "這種方式獲得的學分相對較少，但是積少成多。",
  ui_story_1016_10160401_28_dialog_content = "我們也許可以借此超過鶯歌的隊伍。",
  ui_story_1016_10160401_29_dialog_content = "喔！感覺是個不錯的方法！",
  ui_story_1016_10160401_30_dialog_content = "真激烈啊，競爭都要從課上發展到課後了。",
  ui_story_1016_10160401_31_dialog_content = "走吧，我們去研究一下時間表。",
  ui_story_1016_10160401_32_dialog_content = "看看怎麼安排才是最有效率的訓練方案。",
  ui_story_1016_10160401_33_dialog_content = "<color=#e8d9bb>次日 軍演教室</color>",
  ui_story_1016_10160401_34_dialog_content = "課程結束後不離開教室的學員越來越多了。",
  ui_story_1016_10160401_35_dialog_content = "隊長，我們也要進行課後訓練嗎？",
  ui_story_1016_10160401_36_dialog_content = "如果有想做的訓練，你們可以自行安排。",
  ui_story_1016_10160401_37_dialog_content = "為了學分的話，沒有必要。",
  ui_story_1016_10160401_38_dialog_content = "學分好像可以在最終考核獲得優勢，那對我們不重要嗎？",
  ui_story_1016_10160401_39_dialog_content = "是的。我們不需要對軍演有太強的參與感……",
  ui_story_1016_10160401_40_dialog_content = "鶯歌，妳來看一下。",
  ui_story_1016_10160401_41_dialog_content = "那邊的地板和陪練，都被染得五顏六色了。",
  ui_story_1016_10160401_42_dialog_content = "「五顏六色」？",
  ui_story_1016_10160401_43_dialog_content = "怎麼回事？是顏料嗎？",
  ui_story_1016_10160401_44_dialog_content = "剛才那個訓練假人突然爆炸。",
  ui_story_1016_10160401_45_dialog_content = "……",
  ui_story_1016_10160401_46_dialog_content = "阿克希亞猜裡面一定被人提前放滿各種顏料。",
  ui_story_1016_10160401_47_dialog_content = "難道是薇薇安她們的安排嗎？",
  ui_story_1016_10160401_48_dialog_content = "她應該不會做這種幼稚的惡作劇吧。",
  ui_story_1016_10160401_49_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_1016_10160401_50_dialog_content = "<size=45>槍聲？！</size>",
  ui_story_1016_10160401_51_dialog_content = "你幹什麼！！！",
  ui_story_1016_10160401_52_dialog_content = "我……",
  ui_story_1016_10160401_53_dialog_content = "克蘿伊，沒事吧？",
  ui_story_1016_10160401_54_dialog_content = "沒事，沒有子彈射出來，只不過是一堆彩紙。",
  ui_story_1016_10160401_55_dialog_content = "就是聲音太大了，耳朵裡還是嗡嗡的……",
  ui_story_1016_10160401_56_dialog_content = "怎麼回事，士兵！為什麼會發生這種事故！",
  ui_story_1016_10160401_57_dialog_content = "貝爾塔，我覺得這不怪他。",
  ui_story_1016_10160401_58_dialog_content = "你看他那一臉驚恐的表情。",
  ui_story_1016_10160401_59_dialog_content = "嗯？",
  ui_story_1016_10160401_60_dialog_content = "……是的，剛才扣動扳機時撞針的觸感不對，於是我緊急改變了方向。",
  ui_story_1016_10160401_61_dialog_content = "看來當時的感覺沒錯，有人把我的空包彈替換成……彩紙？",
  ui_story_1016_10160401_62_dialog_content = "替換了你的子彈？竟然有這種事情！",
  ui_story_1016_10160401_63_dialog_content = "我也非常疑惑。",
  ui_story_1016_10160401_64_dialog_content = "對不起，我會立刻向長官報告，調查清楚這件事的。",
  ui_story_1016_10160401_65_dialog_content = "空包彈被替換掉？",
  ui_story_1016_10160401_66_dialog_content = "誰在做這麼危險的事情……",
  ui_story_1016_10160401_67_dialog_content = "與其說是危險，不如說是無聊。",
  ui_story_1016_10160401_68_dialog_content = "有人想干擾大家訓練，阻止其他人得分。",
  ui_story_1016_10160401_69_dialog_content = "誰會用這麼幼稚的手法？",
  ui_story_1016_10160401_70_dialog_content = "不好說。軍演上多方勢力互相糾纏，利害關係錯綜複雜。",
  ui_story_1016_10160401_71_dialog_content = "不用去想那麼多，我們自己不要被捲進去就行了。",
  ui_story_1016_10160401_72_dialog_content = "以後不要在課程之外參與多餘的事情。",
  ui_story_1016_10160401_73_dialog_content = "明白。",
  ui_story_1016_10160401_74_dialog_content = "走吧，阿克希亞。",
  ui_story_1016_10160401_75_dialog_content = "嗯。",
  ui_story_1016_10160401_76_dialog_content = "<color=#e8d9bb>與此同時 啟光研究所</color>",
  ui_story_1016_10160401_77_dialog_content = "拿到了！戰鬥模擬器的使用許可！",
  ui_story_1016_10160401_78_dialog_content = "用這個來訓練的話，可以省下不少體力呢。",
  ui_story_1016_10160401_79_dialog_content = "嗯，等其他學員離開教室之後，我們再回去進行一些消耗體力的訓練。",
  ui_story_1016_10160401_80_dialog_content = "這樣算下來，應該是最有效率的學分賺取方式了。",
  ui_story_1016_10160401_81_dialog_content = "卡蓮在這方面思考得好仔細啊。",
  ui_story_1016_10160401_82_dialog_content = "我畢竟參與過上一次軍演，對這種事情有一些經驗。",
  ui_story_1016_10160401_83_dialog_content = "準備開始吧，我們抓緊時間。",
  ui_story_1016_10160401_84_dialog_content = "嗯，像上次一樣把頭盔戴上吧。",
  ui_story_1016_10160401_85_dialog_content = "咦，這是什麼地方？",
  ui_story_1016_10160401_86_dialog_content = "和上次進來的場景不一樣啊。",
  ui_story_1016_10160401_87_dialog_content = "敵人在哪？",
  ui_story_1016_10160401_88_dialog_content = "我看看……",
  ui_story_1016_10160401_89_option_content = "強制感應！",
  ui_story_1016_10160401_90_dialog_content = "<anim type=Shake>嘶……</anim>",
  ui_story_1016_10160401_91_dialog_content = "好多敵人！比上次還多！",
  ui_story_1016_10160401_92_dialog_content = "而且這些敵人散發出的暗能也太強了吧？",
  ui_story_1016_10160401_93_dialog_content = "我們不會又要逃跑吧？",
  ui_story_1016_10160401_94_dialog_content = "恐怕沒有地方讓我們逃跑……",
  ui_story_1016_10160401_95_dialog_content = "牠們來了！",
  ui_story_1016_10160401_96_dialog_content = "<anim type=Shake><size=50>嘎！！！</size></anim>",
  ui_story_1016_10160401_97_dialog_content = "冰花、散開！",
  ui_story_1016_10160401_98_dialog_content = "怎麼會……沒有反應……",
  ui_story_1016_10160401_99_dialog_content = "這些暗鬼肯定有問題！",
  ui_story_1016_10160401_100_dialog_content = "不管了，反正是戰鬥模擬器。跟牠們拼了！",
  ui_story_1016_10160402_11_dialog_content = "你們小心！",
  ui_story_1016_10160402_12_dialog_content = "糟了，這邊也有……",
  ui_story_1016_10160402_13_dialog_content = "卡蓮！薇絲！",
  ui_story_1016_10160402_14_dialog_content = "<size=45>啊——！！！</size>",
  ui_story_1016_10160402_15_dialog_content = "<anim type=Shake>呼——呼——</anim>",
  ui_story_1016_10160402_16_dialog_content = "這什麼可怕的戰鬥……",
  ui_story_1016_10160402_17_dialog_content = "你說得對，剛才的暗鬼不對勁。",
  ui_story_1016_10160402_18_dialog_content = "即使用強大來形容，也強大得非常畸形。",
  ui_story_1016_10160402_19_dialog_content = "是的，攻擊方式都跟一般暗鬼沒有差別，只是身上的暗能異常濃郁……",
  ui_story_1016_10160402_20_dialog_content = "妳們覺得，會不會是有人對戰鬥模擬器動了手腳？",
  ui_story_1016_10160402_21_dialog_content = "你繼續說。",
  ui_story_1016_10160402_22_dialog_content = "我之前聽守護者一號說過，模擬器裡的東西再真實也不過是資料。",
  ui_story_1016_10160402_23_dialog_content = "我們所經歷的戰鬥，更像是資料之間的運算。",
  ui_story_1016_10160402_24_dialog_content = "如果有人把其中幾個數字改得特別大，平衡的局面就會被打破。",
  ui_story_1016_10160402_25_dialog_content = "說不定，就會形成剛才那種局面。",
  ui_story_1016_10160402_26_dialog_content = "對！模擬器中設定暗鬼力量的資料被修改了，所以牠們才會強大得那麼畸形！",
  ui_story_1016_10160402_27_dialog_content = "是誰在做這種惡劣的事情？",
  ui_story_1016_10160402_28_dialog_content = "PlayerName，能感應到周圍的人嗎？",
  ui_story_1016_10160402_29_dialog_content = "我在試了，但是沒發現行蹤可疑的傢伙。",
  ui_story_1016_10160402_30_dialog_content = "這樣啊……",
  ui_story_1016_10160402_31_dialog_content = "戰鬥模擬器可能被人動過手腳的事情最好跟教官說一下。",
  ui_story_1016_10160402_32_dialog_content = "情況有點古怪，今天就不要再練了。",
  ui_story_1016_10160402_33_dialog_content = "嗯，我們回宿舍吧。",
  ui_story_1016_10160402_34_dialog_content = "確定是有人動了手腳？",
  ui_story_1016_10160402_35_dialog_content = "嗯，貢露檢查戰鬥模擬器之後，發現個別資料遭到了人為修改。",
  ui_story_1016_10160402_36_dialog_content = "但是詳細是誰做的，目前還沒有查出來。",
  ui_story_1016_10160402_37_dialog_content = "這樣做的目的是什麼呢……",
  ui_story_1016_10160402_38_dialog_content = "戰鬥模擬器裡發生的事情對現實不會產生什麼影響。",
  ui_story_1016_10160402_39_dialog_content = "要說這樣做的意義……可能只有阻止我們拿到學分了。",
  ui_story_1016_10160402_40_dialog_content = "嗯，這樣確實說得通。",
  ui_story_1016_10160402_41_dialog_content = "因為學分競爭做出這種事的話，對方也是個學員？",
  ui_story_1016_10160402_42_dialog_content = "很有可能，惡性競爭是在所難免的事情。",
  ui_story_1016_10160402_43_dialog_content = "在之前的軍演中，白夜城和啟光的學員之間就經常爆發矛盾。",
  ui_story_1016_10160402_44_dialog_content = "這麼看來，軍演其實就像是各勢力競爭的一個縮影啊。",
  ui_story_1016_10160402_45_dialog_content = "可是為什麼會盯上我們小隊呢？",
  ui_story_1016_10160402_46_dialog_content = "我是空裔，卡蓮屬於白夜城，薇絲屬於啟光。",
  ui_story_1016_10160402_47_dialog_content = "勢力之間的競爭怎麼看都與我們無關吧？",
  ui_story_1016_10160402_48_dialog_content = "我覺得被盯上的並不是我們。",
  ui_story_1016_10160402_49_dialog_content = "還記得嗎，我們的戰鬥模擬器使用許可是臨時拿到的。",
  ui_story_1016_10160402_50_dialog_content = "提前動手腳的那個人大概不知道我們會使用它。",
  ui_story_1016_10160402_51_dialog_content = "那他盯上的是……",
  ui_story_1016_10160402_52_dialog_content = "在時間表上，預約了要使用戰鬥模擬器的是李奧小隊。",
  ui_story_1016_10160402_53_dialog_content = "哦！這麼一想就對了！",
  ui_story_1016_10160402_54_dialog_content = "他們是排行榜第一，原本就是眾矢之的！",
  ui_story_1016_10160402_55_dialog_content = "嗯，我覺得這是可能性最高的答案。",
  ui_story_1016_10160402_56_dialog_content = "好了，先談回我們自己身上吧。",
  ui_story_1016_10160402_57_dialog_content = "無論別人怎麼做，我們能管好的只有自己。",
  ui_story_1016_10160402_58_dialog_content = "來討論一下明天的安排吧。",
  ui_story_1016_10160402_59_dialog_content = "嗯！",
  ui_story_1016_10160402_60_dialog_content = "哈哈哈，好玩！太好玩了！",
  ui_story_1016_10160402_61_dialog_content = "狄希斯，沒想到你連戰鬥模擬器都會改！",
  ui_story_1016_10160402_62_dialog_content = "我剛學會的。",
  ui_story_1016_10160402_63_dialog_content = "軍演期間能看到很多平日裡難得一見的書，建議妳們也讀一讀。",
  ui_story_1016_10160402_64_dialog_content = "獲得知識的機會不是什麼時候都有的。",
  ui_story_1016_10160402_65_dialog_content = "真是的，一個瞎子天天說什麼看書啊，不聽不聽！",
  ui_story_1016_10160402_66_dialog_content = "梅里，我們明天接著去搗亂吧。",
  ui_story_1016_10160402_67_dialog_content = "妳看，他們已經開始互相猜疑了！多好玩啊！",
  ui_story_1016_10160402_68_dialog_content = "小心不要被抓住，我感覺他們要生氣了。",
  ui_story_1016_10160402_69_dialog_content = "不會的不會的！啟光的人會懷疑白夜城，白夜城的人會懷疑啟光。",
  ui_story_1016_10160402_70_dialog_content = "像我們這樣積分又低、立場又不明確的隊伍，不可能會被懷疑啦。",
  ui_story_1016_10160402_71_dialog_content = "這件事上我支持明詩。",
  ui_story_1016_10160402_72_dialog_content = "理性是一道枷鎖，讓人們止不住去思考做每件事的意義。",
  ui_story_1016_10160402_73_dialog_content = "啊，又開始了……",
  ui_story_1016_10160402_74_dialog_content = "可是他們不會意識到這種思考太過狹隘。",
  ui_story_1016_10160402_75_dialog_content = "渺小的我們其實無論做什麼都沒有意義。",
  ui_story_1016_10160402_76_dialog_content = "想不通這一點，便不可能抓住毫無來由的惡意。",
  ui_story_1016_10160402_77_dialog_content = "放心去做吧，明詩。",
  ui_story_1016_10160402_78_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_1016_10160402_79_dialog_content = "她們兩個……",
  ui_story_1016_10160402_80_dialog_content = "唉，又把我丟下了。",
  ui_story_1016_10160402_81_dialog_content = "行吧，我自己回去。宿舍的方向是在……",
  ui_story_1016_10160402_82_dialog_content = "嗯？",
  ui_story_1016_10160501_1_dialog_content = "發現暗鬼蹤跡！快去呼叫增援！",
  ui_story_1016_10160501_2_dialog_content = "絕對不能讓任何一隻逃脫！",
  ui_story_1016_10160501_3_dialog_content = "哨兵已經去通知雷霆將軍了，我們先追上去！",
  ui_story_1016_10160501_4_dialog_content = "好……",
  ui_story_1016_10160501_5_dialog_content = "喂，你呆呆地站在這裡幹嘛？沒聽到前面有暗鬼嗎？",
  ui_story_1016_10160501_6_dialog_content = "對不起，我的眼睛……",
  ui_story_1016_10160501_7_dialog_content = "哦！您是盲人啊！",
  ui_story_1016_10160501_8_dialog_content = "啊盲人……抱歉，我太粗魯了。",
  ui_story_1016_10160501_9_dialog_content = "現在情況緊急，我們沒辦法分出人手送您回家。",
  ui_story_1016_10160501_10_dialog_content = "請您先在路邊躲一躲吧，這裡暫時是安全的。",
  ui_story_1016_10160501_11_dialog_content = "沒關係，不用在意我。",
  ui_story_1016_10160501_12_dialog_content = "既然是突發情況，各位長官快去處理吧。",
  ui_story_1016_10160501_13_dialog_content = "……只能這樣了，你照顧好自己啊。",
  ui_story_1016_10160501_14_dialog_content = "走，我們追上去！",
  ui_story_1016_10160501_15_dialog_content = "嗯！",
  ui_story_1016_10160501_16_dialog_content = "迦南城裡的暗鬼……",
  ui_story_1016_10160501_17_dialog_content = "看起來還有比我們更能搗亂的傢伙在啊。",
  ui_story_1016_10160501_18_dialog_content = "<color=#e8d9bb>噔、噔、噔、噔……</color>",
  ui_story_1016_10160501_19_dialog_content = "就在前面！我們再快一點！",
  ui_story_1016_10160501_20_dialog_content = "馬上就要……",
  ui_story_1016_10160501_21_dialog_content = "小心！！！",
  ui_story_1016_10160501_22_dialog_content = "<anim type=Shake><size=50>嘎！！！</size></anim>",
  ui_story_1016_10160501_23_dialog_content = "什麼？！牠們回頭了？",
  ui_story_1016_10160501_24_dialog_content = "糟糕，這個數量我們不好應付……",
  ui_story_1016_10160501_25_dialog_content = "沒辦法，只能跟牠們拼了。",
  ui_story_1016_10160501_26_dialog_content = "至少要拖到增援到達……",
  ui_story_1016_10160501_27_dialog_content = "喂喂，沒必要這麼悲壯吧，這可是迦南城啊。",
  ui_story_1016_10160501_28_dialog_content = "誰？！",
  ui_story_1016_10160501_29_dialog_content = "路過的好心人。",
  ui_story_1016_10160501_30_dialog_content = "好厲害……",
  ui_story_1016_10160501_31_dialog_content = "謝、謝謝您！",
  ui_story_1016_10160501_32_dialog_content = "你們該謝謝旁邊這位，幸好他有每天出來散步的習慣。",
  ui_story_1016_10160501_33_dialog_content = "你們是在圍剿小股敵人嗎？",
  ui_story_1016_10160501_34_dialog_content = "戰術素養太差了。不但效率低下，還極有可能折損人手。",
  ui_story_1016_10160501_35_dialog_content = "這事傳出去可是會鬧笑話的。",
  ui_story_1016_10160501_36_dialog_content = "長官教訓的是……",
  ui_story_1016_10160501_37_dialog_content = "（看他的樣子應該是個軍官，不過……）",
  ui_story_1016_10160501_38_dialog_content = "（軍官為什麼會跟白夜城打扮的人走在一起？）",
  ui_story_1016_10160501_39_dialog_content = "周圍還有多少能調度的部隊？",
  ui_story_1016_10160501_40_dialog_content = "把指揮權給我，我來組織圍剿。",
  ui_story_1016_10160501_41_dialog_content = "長官，這……",
  ui_story_1016_10160501_42_dialog_content = "別管合不合程序了，再磨蹭下去只會耽誤戰機。",
  ui_story_1016_10160501_43_dialog_content = "是！",
  ui_story_1016_10160501_44_dialog_content = "通知周邊部隊，在五個街區外的路口以扇形排開。",
  ui_story_1016_10160501_45_dialog_content = "我們放緩追擊腳步，等待他們布置完成。",
  ui_story_1016_10160501_46_dialog_content = "記住了，戰鬥不只是靠蠻力。",
  ui_story_1016_10160501_47_dialog_content = "就像捕魚的時候，伸出手未必是想抓魚，而是把魚逼到網裡。",
  ui_story_1016_10160502_1_dialog_content = "小股暗鬼？從哪裡冒出來的。",
  ui_story_1016_10160502_2_dialog_content = "不知道，已經派人去調查敵人的源頭了。",
  ui_story_1016_10160502_3_dialog_content = "不過既然在這個時間出現，應該跟潛伏在迦南城的吞羅有關係吧？",
  ui_story_1016_10160502_4_dialog_content = "我當然知道跟她有關係，現在的問題是她是怎麼辦到的。",
  ui_story_1016_10160502_5_dialog_content = "這幾天巡邏範圍鋪得很廣，巡邏班次也一直在調整。",
  ui_story_1016_10160502_6_dialog_content = "可是我拿到的報告裡，連吞羅的一根頭髮都沒發現。",
  ui_story_1016_10160502_7_dialog_content = "這……可能是吞羅太善於隱蔽？",
  ui_story_1016_10160502_8_dialog_content = "這是一種可能，但我感覺沒那麼簡單。",
  ui_story_1016_10160502_9_dialog_content = "最近的迦南城，總給我一種有心無力的感覺……",
  ui_story_1016_10160502_10_dialog_content = "軍團長，前面剛剛傳來消息！",
  ui_story_1016_10160502_11_dialog_content = "周邊部隊正在組織包圍圈，對敵人進行圍剿。",
  ui_story_1016_10160502_12_dialog_content = "組織包圍圈？多少人，在什麼地方？",
  ui_story_1016_10160502_13_dialog_content = "我可沒有下令，這是誰在擅自調動我的部隊？！",
  ui_story_1016_10160502_14_dialog_content = "詳細情況還不清楚……",
  ui_story_1016_10160502_15_dialog_content = "接著去問！",
  ui_story_1016_10160502_16_dialog_content = "我還掛著少將軍銜呢，不需要別人來替我指揮！",
  ui_story_1016_10160502_17_dialog_content = "軍、軍團長！新的消息傳回來了！",
  ui_story_1016_10160502_18_dialog_content = "入侵迦南城的小股暗鬼已經被全部消滅！",
  ui_story_1016_10160502_19_dialog_content = "<size=50>什麼？！</size>",
  ui_story_1016_10160502_20_dialog_content = "確定是全滅嗎？",
  ui_story_1016_10160502_21_dialog_content = "是的，周圍已無暗鬼蹤跡。",
  ui_story_1016_10160502_22_dialog_content = "動作這麼快……",
  ui_story_1016_10160502_23_dialog_content = "呵，有趣。",
  ui_story_1016_10160502_24_dialog_content = "我倒要看看，今天究竟是沾了誰的光。",
  ui_story_1016_10160502_25_dialog_content = "行了，事情解決了。",
  ui_story_1016_10160502_26_dialog_content = "戰場你們打掃一下，我們就先走了啊。",
  ui_story_1016_10160502_27_dialog_content = "對了，我臨時指揮過你們的事情最好就不要說。",
  ui_story_1016_10160502_28_dialog_content = "這樣大家都能少一點麻煩……",
  ui_story_1016_10160502_29_dialog_content = "幹嘛不說。消滅了暗鬼，平息了騷亂，這是好事啊。",
  ui_story_1016_10160502_30_dialog_content = "我還準備幫你們申請個「助人為樂勳章」呢。",
  ui_story_1016_10160502_31_dialog_content = "雷霆教官……",
  ui_story_1016_10160502_32_dialog_content = "這裡不是軍演課堂，用不著叫我「教官」。把彼此當作軍人就好。",
  ui_story_1016_10160502_33_dialog_content = "對不起，我不該擅自調動您的部隊。",
  ui_story_1016_10160502_34_dialog_content = "我願意接受處罰。",
  ui_story_1016_10160502_35_dialog_content = "嗯……比起處罰，我更想要那個「助人為樂勳章」。",
  ui_story_1016_10160502_36_dialog_content = "算了，處罰什麼的就別再說了。",
  ui_story_1016_10160502_37_dialog_content = "你們臨時過來幫忙，快速地解決了戰鬥，這怎麼說也是功勞一件。",
  ui_story_1016_10160502_38_dialog_content = "我還沒有迂腐到去懲罰有功之人。",
  ui_story_1016_10160502_39_dialog_content = "謝謝長官的理解。",
  ui_story_1016_10160502_40_dialog_content = "你們的戰術素養值得讚賞，行事也非常果斷。",
  ui_story_1016_10160502_41_dialog_content = "今天的騷亂，恐怕只有你們能解決得如此完美。",
  ui_story_1016_10160502_42_dialog_content = "我相信是邊境地區的戰亂環境培養了這樣的能力。",
  ui_story_1016_10160502_43_dialog_content = "同時，也帶來了更實用主義的思考方式。",
  ui_story_1016_10160502_44_dialog_content = "我不覺得你們的思考方式有什麼問題，戰場上需要這樣的果斷。",
  ui_story_1016_10160502_45_dialog_content = "但是在迦南城，制度和規矩有著更高的價值。",
  ui_story_1016_10160502_46_dialog_content = "我花很長時間才學會了這一點，希望你們也能仔細想想。",
  ui_story_1016_10160502_47_dialog_content = "制度和規矩……",
  ui_story_1016_10160502_48_dialog_content = "因為它們能維持住一個體系的穩固，是嗎？",
  ui_story_1016_10160502_49_dialog_content = "沒錯，穩固。",
  ui_story_1016_10160502_50_dialog_content = "不只要不為外力傾倒，也要禁得起內部的瓦解。",
  ui_story_1016_10160502_51_dialog_content = "為了維持住這樣的穩固，有時候不得不犧牲掉局部的勝利。",
  ui_story_1016_10160502_52_dialog_content = "原來如此，我明白了。",
  ui_story_1016_10160502_53_dialog_content = "謝謝長官賜教。",
  ui_story_1016_10160502_54_dialog_content = "如果有一天你們要離開邊境，想明白這一點會非常重要。",
  ui_story_1016_10160502_55_dialog_content = "好了，先回去吧。",
  ui_story_1016_10160502_56_dialog_content = "明天是我的課，別遲到了。",
  ui_story_1016_10160502_57_dialog_content = "是！",
  ui_story_1016_10160502_58_dialog_content = "……但是長官，如果那個穩固的體系本身就是歪曲的呢？",
  ui_story_1016_10160502_59_dialog_content = "什麼？",
  ui_story_1016_10160502_60_dialog_content = "如果遵照制度與規矩搭建成的建築是一尊遲早會倒塌的斜塔。",
  ui_story_1016_10160502_61_dialog_content = "那我們為之而犧牲的東西，只會顯得可笑吧。",
  ui_story_1016_10160502_62_dialog_content = "聽你的意思，你對現有的「建築」並不滿意。",
  ui_story_1016_10160502_63_dialog_content = "您知道我們為什麼要來參加軍演嗎？",
  ui_story_1016_10160502_64_dialog_content = "現在，地圖最邊緣的邊境線上，暗鬼正在暗面集結。",
  ui_story_1016_10160502_65_dialog_content = "牠們隨時可能會對防線發起衝擊。",
  ui_story_1016_10160502_66_dialog_content = "而我們發出的求援信，至今沒收到任何回覆。",
  ui_story_1016_10160502_67_dialog_content = "長官，如果我們繼續在黃昏鎮固守，算是在維持「體系的穩定」嗎？",
  ui_story_1016_10160502_68_dialog_content = "還是說，這條邊境線只是即將被犧牲掉的「局部」？",
  ui_story_1016_10160502_69_dialog_content = "……邊境發生了這麼大的事情？",
  ui_story_1016_10160502_70_dialog_content = "看來我猜得不錯，您並不知道。",
  ui_story_1016_10160502_71_dialog_content = "其他手握兵權的軍團長恐怕也是如此。",
  ui_story_1016_10160502_72_dialog_content = "對不起，我說得太多了。",
  ui_story_1016_10160502_73_dialog_content = "……",
  ui_story_1016_10160502_74_dialog_content = "回去吧。",
  ui_story_1016_10160502_75_dialog_content = "你說的那些，我會去調查清楚。",
  ui_story_1016_10160502_76_dialog_content = "是。",
  ui_story_1016_10160502_77_dialog_content = "（這麼大的事情我竟然毫不知情。）",
  ui_story_1016_10160502_78_dialog_content = "（萊因哈特，妳到底在幹什麼？）",
  ui_story_1016_10160502_79_dialog_content = "（還是說，連妳也無法控制……）",
  ui_story_1016_10160502_80_dialog_content = "德尼耶爾。",
  ui_story_1016_10160502_81_dialog_content = "德尼耶爾！",
  ui_story_1016_10160502_82_dialog_content = "……對不起，我走神了。",
  ui_story_1016_10160502_83_dialog_content = "情況……很糟嗎？",
  ui_story_1016_10160502_84_dialog_content = "妳的臉色……很差。",
  ui_story_1016_10160502_85_dialog_content = "我藏在迦南城的暗鬼都被消滅了。",
  ui_story_1016_10160502_86_dialog_content = "這次對方的指揮官很厲害，沒讓我有反應時間。",
  ui_story_1016_10160502_87_dialog_content = "我們手裡……沒有牌了？",
  ui_story_1016_10160502_88_dialog_content = "在罪靈到來之前，是這樣的。",
  ui_story_1016_10160502_89_dialog_content = "要把籌碼都賭在他們身上，我不喜歡。",
  ui_story_1016_10160502_90_dialog_content = "這不是賭注，是一場交易。",
  ui_story_1016_10160502_91_dialog_content = "我手裡的研究成果，救得下我們這兩條命。",
  ui_story_1016_10160601_1_dialog_content = "<color=#e8d9bb>數日後 課程階段尾聲</color>",
  ui_story_1016_10160601_2_dialog_content = "怎麼樣！我們的排名到多少了！",
  ui_story_1016_10160601_3_dialog_content = "讓我看看——",
  ui_story_1016_10160601_4_dialog_content = "第二！我們來到第二了！",
  ui_story_1016_10160601_5_dialog_content = "太好了！！！總算是做到了！",
  ui_story_1016_10160601_6_dialog_content = "<color=#e8d9bb>鈴——</color>",
  ui_story_1016_10160601_7_dialog_content = "快坐好快坐好，今天守規矩一點。",
  ui_story_1016_10160601_8_dialog_content = "嗯，畢竟是最後一節課了。",
  ui_story_1016_10160601_9_dialog_content = "各位學員們好！",
  ui_story_1016_10160601_10_dialog_content = "我想大家都清楚，今天是聯合軍演課程階段的最後一堂課。",
  ui_story_1016_10160601_11_dialog_content = "接下來你們要為實戰考核做準備，角逐出最後的勝者。",
  ui_story_1016_10160601_12_dialog_content = "課程階段累積的學分會為你們帶來一些幫助。",
  ui_story_1016_10160601_13_dialog_content = "至於現在的學分情況，你們可以從牆上的排行榜上看到。",
  ui_story_1016_10160601_14_dialog_content = "李奧帶領的小隊毫無懸念拿下第一名。",
  ui_story_1016_10160601_15_dialog_content = "承讓，承讓。",
  ui_story_1016_10160601_16_dialog_content = "PlayerName帶領的小隊後來居上，取得第二。",
  ui_story_1016_10160601_17_dialog_content = "真是太不容易了……",
  ui_story_1016_10160601_18_dialog_content = "鶯歌帶領的小隊成績穩定，最終位列第三。",
  ui_story_1016_10160601_19_dialog_content = "謝謝。",
  ui_story_1016_10160601_20_dialog_content = "完整排名我就不一一說了，大家自己去看一下。",
  ui_story_1016_10160601_21_dialog_content = "回到課程上來。作為最後一課，主辦方希望能為大家的考核進行熱身。",
  ui_story_1016_10160601_22_dialog_content = "所以，這一課的內容是實戰。",
  ui_story_1016_10160601_23_dialog_content = "實戰？和之前的搏擊課有什麼區別嗎？",
  ui_story_1016_10160601_24_dialog_content = "區別就在於你們的敵人。",
  ui_story_1016_10160601_25_dialog_content = "之前的課程出於安全性考慮，你們從未面對過真實的威脅。",
  ui_story_1016_10160601_26_dialog_content = "無論是搏擊課上的陪練士兵，還是戰場模擬器中的虛擬環境，都無法對你們造成實質傷害。",
  ui_story_1016_10160601_27_dialog_content = "但是接下來的考核裡面，沒有人能保障你們的安全。",
  ui_story_1016_10160601_28_dialog_content = "我想看看你們有沒有做好在現實中面對暗鬼的準備。",
  ui_story_1016_10160601_29_dialog_content = "真正的暗鬼？在教室裡嗎？",
  ui_story_1016_10160601_30_dialog_content = "啟光的生化研究所為我們提供了珍貴的「陪練素材」。",
  ui_story_1016_10160601_31_dialog_content = "各位學員，請做好準備。",
  ui_story_1016_10160601_32_dialog_content = "<color=#e8d9bb>嘭——！！！</color>",
  ui_story_1016_10160601_33_dialog_content = "哇！竟然弄出來了這麼多暗鬼？",
  ui_story_1016_10160601_34_dialog_content = "啟光的生化研究所在拿牠們做研究嗎……太過火了吧……",
  ui_story_1016_10160601_35_dialog_content = "戰場上最該瞭解的就是敵人。",
  ui_story_1016_10160601_36_dialog_content = "妳以為對暗鬼的研究換來的是什麼？是士兵的性命。",
  ui_story_1016_10160601_37_dialog_content = "可是……",
  ui_story_1016_10160601_38_dialog_content = "放心吧，這些暗鬼全都在可控範圍內。",
  ui_story_1016_10160601_39_dialog_content = "學員們，最後一堂課沒有多餘的規則。",
  ui_story_1016_10160601_40_dialog_content = "請你們用盡一切方法，消滅牠們。",
  ui_story_1016_10160601_41_dialog_content = "<anim type=Shake><size=50>嘎！！！</size></anim>",
  ui_story_1016_10160601_42_dialog_content = "突然就開始了嗎？！",
  ui_story_1016_10160601_43_dialog_content = "我還沒準備好……",
  ui_story_1016_10160601_44_dialog_content = "PlayerName，小心點。",
  ui_story_1016_10160601_45_dialog_content = "對不起！我走神了！",
  ui_story_1016_10160601_46_dialog_content = "戰鬥的同時也觀察一下其他隊伍吧。",
  ui_story_1016_10160601_47_dialog_content = "這是個探明各個隊伍實力的好機會。",
  ui_story_1016_10160601_48_dialog_content = "阿克希亞，妳盡量不要出手。",
  ui_story_1016_10160601_49_dialog_content = "交給我和阿納托利就行。",
  ui_story_1016_10160601_50_dialog_content = "沒問題嗎？",
  ui_story_1016_10160601_51_dialog_content = "這只是上課而已，不會有多大危險。",
  ui_story_1016_10160601_52_dialog_content = "而且還有其他小隊在呢。",
  ui_story_1016_10160601_53_dialog_content = "話是這麼說，不過……",
  ui_story_1016_10160601_54_dialog_content = "我看其他人也沒怎麼出力。",
  ui_story_1016_10160601_55_dialog_content = "尤萊雅，支援一下我的左側！",
  ui_story_1016_10160601_56_dialog_content = "明白！",
  ui_story_1016_10160601_57_dialog_content = "不行，其他方向又壓了過來……",
  ui_story_1016_10160601_58_dialog_content = "克蘿伊！",
  ui_story_1016_10160601_59_dialog_content = "我暫時脫不開身！",
  ui_story_1016_10160601_60_dialog_content = "怎麼回事，感覺周圍根本沒有友軍在戰鬥啊！",
  ui_story_1016_10160601_61_dialog_content = "我們什麼時候衝到最前面來了？",
  ui_story_1016_10160601_62_dialog_content = "我覺得是因為他們都在後退……",
  ui_story_1016_10160601_63_dialog_content = "哈？！",
  ui_story_1016_10160601_64_dialog_content = "排行榜上名次一個比一個高，怎麼真的打起來全都不見了！",
  ui_story_1016_10160601_65_dialog_content = "我們也陷入苦戰了，自顧不暇啊。",
  ui_story_1016_10160601_66_dialog_content = "你連刀都沒拔出來，說什麼陷入苦戰啊！",
  ui_story_1016_10160601_67_dialog_content = "看起來大家都有所保留……",
  ui_story_1016_10160601_68_dialog_content = "也是。最後一堂課了，大家都希望把真正的實力留到考核上面。",
  ui_story_1016_10160601_69_dialog_content = "但是這樣下去的話，好像沒辦法順利戰勝暗鬼啊……",
  ui_story_1016_10160601_70_dialog_content = "既然都不想使出全力的話，我們來合作吧！",
  ui_story_1016_10160601_71_dialog_content = "敵人不算強大，只要大家配合得當，每組只要出一點力就能獲勝！",
  ui_story_1016_10160601_72_dialog_content = "哦？這個主意聽起來不錯。",
  ui_story_1016_10160601_73_dialog_content = "可以和不同地區的人共同戰鬥，我願意試試。",
  ui_story_1016_10160601_74_dialog_content = "是啊。既然最後一堂課沒什麼可競爭的了，就當一起解決個小麻煩吧。",
  ui_story_1016_10160601_75_dialog_content = "我們也同意！趕快幫個忙吧！",
  ui_story_1016_10160601_76_dialog_content = "好玩好玩！明詩要加入！",
  ui_story_1016_10160601_77_dialog_content = "好！那大家通力合作一次吧！",
  ui_story_1016_10160601_78_dialog_content = "把戰線往前推進，幫貝爾塔小隊解圍！",
  ui_story_1016_10160602_1_dialog_content = "好！這下子暗鬼就全都被消滅了！",
  ui_story_1016_10160602_2_dialog_content = "恭喜各位學員，你們順利完成了本次聯合軍演的最後一課。",
  ui_story_1016_10160602_3_dialog_content = "原以為火藥味會更濃一些，沒想到最後大家竟然會通力合作。",
  ui_story_1016_10160602_4_dialog_content = "雖然也是建立在一些心眼之上的合作吧，哈哈。",
  ui_story_1016_10160602_5_dialog_content = "那麼課程階段就此結束！在下課之前，我來介紹一下考核的內容吧。",
  ui_story_1016_10160602_6_dialog_content = "我想，有不少學員對此非常關心。",
  ui_story_1016_10160602_7_dialog_content = "本屆考核的地點設在一處廢棄的地下城裡。",
  ui_story_1016_10160602_8_dialog_content = "它位於防線邊緣，早已被暗鬼侵佔，周邊地帶多年都沒有光靈活動的痕跡。",
  ui_story_1016_10160602_9_dialog_content = "你們要做的是深入地下城，在裡面尋找並爭奪一面提前被設置好的旗幟。",
  ui_story_1016_10160602_10_dialog_content = "規則非常簡單，奪得旗幟的人即軍演冠軍，可以獲得與大元帥對決的機會。",
  ui_story_1016_10160602_11_dialog_content = "至於達成目標的手段，我們不做任何限制。",
  ui_story_1016_10160602_12_dialog_content = "那，我們會得到安全上的保障嗎？",
  ui_story_1016_10160602_13_dialog_content = "你們最好當作不會。",
  ui_story_1016_10160602_14_dialog_content = "為了在考核中激發出學員們的戰鬥潛力，考核的難度和危險性很高。",
  ui_story_1016_10160602_15_dialog_content = "不要以為平時在課程上表現優異就能順利通過考核，實戰與練習是不一樣的。",
  ui_story_1016_10160602_16_dialog_content = "考核途中，教官會透過一些方式觀察你們的行為。",
  ui_story_1016_10160602_17_dialog_content = "如果有學員之間的惡性傷害事件發生，我們會在軍事法庭上拿出充足的證據。",
  ui_story_1016_10160602_18_dialog_content = "但是，我們無法為你們解決那些咫尺之遙的危機。",
  ui_story_1016_10160602_19_dialog_content = "別覺得軍演會提供什麼額外的保障，你們能依靠的只有自己。",
  ui_story_1016_10160602_20_dialog_content = "原來如此，我明白了。",
  ui_story_1016_10160602_21_dialog_content = "這樣滿好的。要是有一群人躲在暗地裡保護大家，我會覺得自己在玩扮家家酒。",
  ui_story_1016_10160602_22_dialog_content = "接下來是考核之前的準備。",
  ui_story_1016_10160602_23_dialog_content = "為了保證公平，你們只允許攜帶戰鬥所需的基本裝備。",
  ui_story_1016_10160602_24_dialog_content = "在此之外，如果你們需要一些額外的幫助，就得依賴課程階段獲得的學分了。",
  ui_story_1016_10160602_25_dialog_content = "哦！累積下來的學分要發揮作用了嗎！",
  ui_story_1016_10160602_26_dialog_content = "是的，明天我會帶你們前往啟光研究所，那裡為學員們準備了許多物資。",
  ui_story_1016_10160602_27_dialog_content = "有的能強化你們的作戰能力，有的能提供有效的戰鬥資訊。",
  ui_story_1016_10160602_28_dialog_content = "換取這些物資的籌碼，就是你們獲得的學分。",
  ui_story_1016_10160602_29_dialog_content = "換言之，積分高的隊伍可以透過換取物資，獲得更大的優勢。",
  ui_story_1016_10160602_30_dialog_content = "至於大家是想補足弱點、強化優點還是增加戰鬥方式，就全看各隊的選擇了。",
  ui_story_1016_10160602_31_dialog_content = "唔，我們該怎麼選呢……",
  ui_story_1016_10160602_32_dialog_content = "你們回去之後做好各自的準備。明天早上，還是來教室集合。",
  ui_story_1016_10160602_33_dialog_content = "好了，今天要講的就是這些。下課。",
  ui_story_1016_10160602_34_dialog_content = "<color=#e8d9bb>次日</color>",
  ui_story_1016_10160602_35_dialog_content = "哇！好豐富的裝備！",
  ui_story_1016_10160602_36_dialog_content = "軍刺、槍械、榴彈，還有各種不同樣式的防護服……",
  ui_story_1016_10160602_37_dialog_content = "天哪，全都想要，這怎麼選啊！",
  ui_story_1016_10160602_38_dialog_content = "冷靜下來看看的話，每一樣物資的標價都好高啊。",
  ui_story_1016_10160602_39_dialog_content = "哪怕我們現在學分排名第二，能換取的資源也非常有限。",
  ui_story_1016_10160602_40_dialog_content = "確實。我想這些物資只是一個激勵，主辦方並不希望我們過分依賴外物。",
  ui_story_1016_10160602_41_dialog_content = "來選一些我們最需要的東西吧。",
  ui_story_1016_10160602_42_dialog_content = "我想想啊。我們的隊伍有PlayerName在，在取得資訊上具備先天優勢。",
  ui_story_1016_10160602_43_dialog_content = "所以，用學分換取能夠增強戰鬥力的物資比較好？",
  ui_story_1016_10160602_44_dialog_content = "這麼說的話，我覺得可以換取一些防具。",
  ui_story_1016_10160602_45_dialog_content = "PlayerName的身體相對脆弱，有防具護身的話我們會比較安心。",
  ui_story_1016_10160602_46_dialog_content = "咦？不用在我身上花費學分吧……",
  ui_story_1016_10160602_47_dialog_content = "我也覺得這樣最好！",
  ui_story_1016_10160602_48_dialog_content = "來吧PlayerName，試試這幾套防護服哪個比較合身。",
  ui_story_1016_10160602_49_dialog_content = "現在就要開始試了嗎？！",
  ui_story_1016_10160602_50_dialog_content = "好吧好吧，就當是為了不拖大家後腿……",
  ui_story_1016_10160602_51_dialog_content = "全都是些機械啊……",
  ui_story_1016_10160602_52_dialog_content = "我提不起興趣，昭來選吧。",
  ui_story_1016_10160602_53_dialog_content = "嗯，我已經提前想過了。",
  ui_story_1016_10160602_54_dialog_content = "對於我們來說，最重要的是資訊。",
  ui_story_1016_10160602_55_dialog_content = "只要能搶佔先機，戰鬥對我們來說不成問題。",
  ui_story_1016_10160602_56_dialog_content = "嗯對，滿有道理的。我可不想當無頭蒼蠅。",
  ui_story_1016_10160602_57_dialog_content = "換一份地圖吧。然後，把這個通訊器換了。",
  ui_story_1016_10160602_58_dialog_content = "呃，這通訊器好貴啊，大半積蓄都要用在這了。",
  ui_story_1016_10160602_59_dialog_content = "看描述上說，通訊器可以用來在考核中即時聯絡場外的教官。",
  ui_story_1016_10160602_60_dialog_content = "沒有比它更有效率的資訊獲得手段了。",
  ui_story_1016_10160602_61_dialog_content = "好吧，聽你的，軍師。",
  ui_story_1016_10160602_62_dialog_content = "把門關上。",
  ui_story_1016_10160602_63_dialog_content = "是！",
  ui_story_1016_10160602_64_dialog_content = "<color=#e8d9bb>砰。</color>",
  ui_story_1016_10160602_65_dialog_content = "清楚你們的任務吧？",
  ui_story_1016_10160602_66_dialog_content = "拿下冠軍，不惜一切代價。",
  ui_story_1016_10160602_67_dialog_content = "我向他們傳達過了。",
  ui_story_1016_10160602_68_dialog_content = "我相信你們的實力。不過，為了完成任務，你們沒必要去遵守所謂的公平。",
  ui_story_1016_10160602_69_dialog_content = "我為你們單獨準備了一些物資，會比學分換到的那些更好。",
  ui_story_1016_10160602_70_dialog_content = "這些物資可以通過考核前的檢查，你們放心帶在身上就行。",
  ui_story_1016_10160602_71_dialog_content = "情報方面，這裡有一張完善的地圖，記錄著旗幟所在的位置。",
  ui_story_1016_10160602_72_dialog_content = "你們不用像其他隊伍一樣摸索，直奔目標而去就行。",
  ui_story_1016_10160602_73_dialog_content = "然後，旁邊的櫃子上擺放了一些增強戰鬥力的裝備，你們可以隨意拿取。",
  ui_story_1016_10160602_74_dialog_content = "（隨意拿取……這些裝備隨便一件就夠掏空一整隊的學分了。）",
  ui_story_1016_10160602_75_dialog_content = "（以這種方式作弊，萬一被戳穿的話，上頭會很難看吧。）",
  ui_story_1016_10160602_76_dialog_content = "（委員會就這麼想要聯合軍演的冠軍嗎？）",
  ui_story_1016_10160602_77_dialog_content = "我要說的就是這些，接下來這裡就交給你們了。",
  ui_story_1016_10160602_78_dialog_content = "別跟任何人說今天見過我。",
  ui_story_1016_10160602_79_dialog_content = "<color=#e8d9bb>砰。</color>",
  ui_story_1016_10160602_80_dialog_content = "阿克希亞有「三次方」，不需要其他裝備。",
  ui_story_1016_10160602_81_dialog_content = "我也不需要多餘的裝備，阿納托利去選吧。",
  ui_story_1016_10160602_82_dialog_content = "我？",
  ui_story_1016_10160602_83_dialog_content = "把裝備集中在一個人身上會有更好的效果。",
  ui_story_1016_10160602_84_dialog_content = "……好吧，我服從安排。",
  ui_story_1016_10160602_85_dialog_content = "嗯，我們都是服從安排。",
  ui_story_1016_10160602_86_dialog_content = "妳們常年跟委員會接觸，早就已經習慣這樣的安排了吧？",
  ui_story_1016_10160602_87_dialog_content = "你好像有話想說？",
  ui_story_1016_10160602_88_dialog_content = "沒有，我就是隨便問問。",
  ui_story_1016_10160602_89_dialog_content = "作為情報官，隨便問問並不是個好的習慣。",
  ui_story_1016_10160602_90_dialog_content = "至於你說的安排，我確實早就習慣了。服從命令是絕對的，無論是怎樣的命令。",
  ui_story_1016_10160602_91_dialog_content = "好的，我明白了……",
  ui_story_1016_10160602_92_dialog_content = "不過，偶爾也會產生一些安排之外的想法。",
  ui_story_1016_10160602_93_dialog_content = "這種時候，我會把想法藏在行為背後。",
  ui_story_1016_10160701_1_dialog_content = "<color=#e8d9bb>嘟、嘟——</color>",
  ui_story_1016_10160701_2_dialog_content = "好了好了，都下車吧，你們的目的地到了。",
  ui_story_1016_10160701_3_dialog_content = "面前這座破破爛爛的地下城，就是你們的考核場地。",
  ui_story_1016_10160701_4_dialog_content = "接下來士兵會帶領每個小隊前往不同的起始地點。",
  ui_story_1016_10160701_5_dialog_content = "還有什麼要說的來著……",
  ui_story_1016_10160701_6_dialog_content = "哦對，保護好自己。可以互相爭鬥，但是別下死手。",
  ui_story_1016_10160701_7_dialog_content = "我會偷偷注視著你們喔。",
  ui_story_1016_10160701_8_dialog_content = "怎麼說得讓人背後發毛……",
  ui_story_1016_10160701_9_dialog_content = "士兵，帶各組就位吧。",
  ui_story_1016_10160701_10_dialog_content = "我等你們的好消息。",
  ui_story_1016_10160701_11_dialog_content = "裝備都確認好了吧。",
  ui_story_1016_10160701_12_dialog_content = "嗯！確認好了！",
  ui_story_1016_10160701_13_dialog_content = "箭矢充足，暗鬼們可要小心別觸霉頭喔。",
  ui_story_1016_10160701_14_dialog_content = "那就按照我們商量好的計畫行動。",
  ui_story_1016_10160701_15_dialog_content = "其他隊伍一定會換取地圖等情報，我們只要利用PlayerName的能力跟上任意一組就行。",
  ui_story_1016_10160701_16_dialog_content = "嗯，我已經在尋找其他隊伍了。",
  ui_story_1016_10160701_17_dialog_content = "不過各組的出發地相隔較遠，暫時還沒有找到。",
  ui_story_1016_10160701_18_dialog_content = "沒關係，我們先往深處走走。",
  ui_story_1016_10160701_19_dialog_content = "明詩，妳買的都是些什麼東西啊……",
  ui_story_1016_10160701_20_dialog_content = "不好玩嗎？妳看，這個是閃光彈，扔出去的話就會——",
  ui_story_1016_10160701_21_dialog_content = "<size=50>嗚哇！</size>",
  ui_story_1016_10160701_22_dialog_content = "怎麼了？發生什麼事了嗎？",
  ui_story_1016_10160701_23_dialog_content = "沒事，梅里叫著玩呢。",
  ui_story_1016_10160701_24_dialog_content = "哎呀，又哭了？",
  ui_story_1016_10160701_25_dialog_content = "太刺眼了，眼淚不自覺就……",
  ui_story_1016_10160701_26_dialog_content = "明詩，這種東西買來有什麼用啊。",
  ui_story_1016_10160701_27_dialog_content = "好玩啊！",
  ui_story_1016_10160701_28_dialog_content = "妳看，我們又沒多少學分，買不起那些好用的道具。",
  ui_story_1016_10160701_29_dialog_content = "既然這樣，多買點玩具不好嗎？",
  ui_story_1016_10160701_30_dialog_content = "這麼說也是啦……",
  ui_story_1016_10160701_31_dialog_content = "反正我們不是為奪冠而來的。",
  ui_story_1016_10160701_32_dialog_content = "奪冠了反而會比較困擾吧，冠軍可是要把自己陣營旗幟掛上去的。",
  ui_story_1016_10160701_33_dialog_content = "我們登記的陣營是什麼來著？",
  ui_story_1016_10160701_34_dialog_content = "是影鎮，雖然我還沒去過那裡。",
  ui_story_1016_10160701_35_dialog_content = "啊不要，影鎮的旗幟太醜了。",
  ui_story_1016_10160701_36_dialog_content = "而且奪冠了要和那個什麼萊因哈特打架，我才不去。",
  ui_story_1016_10160701_37_dialog_content = "狄希斯會去的吧，你可是隊長。",
  ui_story_1016_10160701_38_dialog_content = "沒興趣，被體制吹捧起來的英雄罷了。",
  ui_story_1016_10160701_39_dialog_content = "還是把關注點放在周圍的學員身上吧。",
  ui_story_1016_10160701_40_dialog_content = "別忘了我們到底是為什麼而來的。",
  ui_story_1016_10160701_41_dialog_content = "真是的，狄希斯太正經了，沒意思。",
  ui_story_1016_10160701_42_dialog_content = "走了走了，我們找點樂子去。",
  ui_story_1016_10160701_43_dialog_content = "好想跟其他隊伍一起玩啊！",
  ui_story_1016_10160701_44_dialog_content = "我找到人了！",
  ui_story_1016_10160701_45_dialog_content = "哦？是誰？",
  ui_story_1016_10160701_46_dialog_content = "是那一支表現總是很古怪的影鎮小隊。",
  ui_story_1016_10160701_47_dialog_content = "他們的隊長……是叫狄希斯來著？",
  ui_story_1016_10160701_48_dialog_content = "我記得他們。狄希斯、明詩還有梅里。",
  ui_story_1016_10160701_49_dialog_content = "印象裡是幾個很不安分的傢伙。",
  ui_story_1016_10160701_50_dialog_content = "他們的行進速度很快，正直奔地下城深處而去。",
  ui_story_1016_10160701_51_dialog_content = "這個行動方式，很有可能拿到了線索吧？",
  ui_story_1016_10160701_52_dialog_content = "嗯，快速前進說明他們有明確的目標。",
  ui_story_1016_10160701_53_dialog_content = "我們快追上去看看。",
  ui_story_1016_10160701_54_dialog_content = "不用追了，他們很快會從我們旁邊路過。",
  ui_story_1016_10160701_55_dialog_content = "啊，我好像聽到聲音了……",
  ui_story_1016_10160701_56_dialog_content = "唔呼～來追我啊來追我啊～",
  ui_story_1016_10160701_57_dialog_content = "明詩，妳跑慢一點……",
  ui_story_1016_10160701_58_dialog_content = "等等，不對勁！",
  ui_story_1016_10160701_59_dialog_content = "他們身後跟著大批的暗鬼！",
  ui_story_1016_10160701_60_dialog_content = "哈？",
  ui_story_1016_10160701_61_dialog_content = "他們動作太大，把暗鬼全都招惹過來了！",
  ui_story_1016_10160701_62_dialog_content = "而且……看起來這三個人並沒有消滅暗鬼的意思。",
  ui_story_1016_10160701_63_dialog_content = "他們只是在帶著暗鬼奔跑。",
  ui_story_1016_10160701_64_dialog_content = "在幹什麼啊……把戰場當兒戲嗎？",
  ui_story_1016_10160701_65_dialog_content = "我現在不覺得他們有明確目標了。快走，別被牽扯進去。",
  ui_story_1016_10160701_66_dialog_content = "我也這麼覺得，可是……",
  ui_story_1016_10160701_67_dialog_content = "他們直直地朝這邊跑過來了！",
  ui_story_1016_10160701_68_dialog_content = "明詩，前面發現了空裔帶領的那支隊伍。",
  ui_story_1016_10160701_69_dialog_content = "哦空裔！他滿好玩的，我們去找他玩！",
  ui_story_1016_10160701_70_dialog_content = "<size=50>救命啊救命啊！要被暗鬼吃掉了，快救救我們！！！</size>",
  ui_story_1016_10160701_71_dialog_content = "完了，被他們發現了……",
  ui_story_1016_10160701_72_dialog_content = "……",
  ui_story_1016_10160701_73_dialog_content = "聽好！狄希斯小隊的成員！",
  ui_story_1016_10160701_74_dialog_content = "立刻轉身回頭開始戰鬥！",
  ui_story_1016_10160701_75_dialog_content = "嗯？妳在說什麼呢，妳在命令我嗎！",
  ui_story_1016_10160701_76_dialog_content = "回頭戰鬥的話，我們小隊會與你們合作。",
  ui_story_1016_10160701_77_dialog_content = "繼續奔跑的話，我們小隊會向你們發起攻擊。",
  ui_story_1016_10160701_78_dialog_content = "攻擊他們？！",
  ui_story_1016_10160701_79_dialog_content = "我們只能這樣佔據主動權了。",
  ui_story_1016_10160701_80_dialog_content = "哎呀，別有那麼強的敵意嘛，明詩就是想跟大家一起玩。",
  ui_story_1016_10160701_81_dialog_content = "那就聽妳的，我們合作吧！",
  ui_story_1016_10160701_82_dialog_content = "梅里，回頭狠狠地揍暗鬼一頓！",
  ui_story_1016_10160701_83_dialog_content = "早就想揍了！",
  ui_story_1016_10160701_84_dialog_content = "他們動手了，那我們也上吧！",
  ui_story_1016_10160701_85_dialog_content = "嗯，速戰速決！",
  ui_story_1016_10160802_1_dialog_content = "<anim type=Shake>嘎……</anim>",
  ui_story_1016_10160802_2_dialog_content = "哼哼，比預想得更好解決呢～",
  ui_story_1016_10160802_3_dialog_content = "可是，另外幾個小隊已經全都走到前面去了。",
  ui_story_1016_10160802_4_dialog_content = "真是的，一直被這些暗鬼拖著，進度快要跟不上了……",
  ui_story_1016_10160802_5_dialog_content = "該說是我的錯覺嗎，總覺得自從碰到這個暗色衣服三人組之後……",
  ui_story_1016_10160802_6_dialog_content = "總是莫名其妙地倒楣！",
  ui_story_1016_10160802_7_dialog_content = "現在也不是抱怨的時候。",
  ui_story_1016_10160802_8_dialog_content = "再這樣下去，我們就真的和冠軍無緣了。",
  ui_story_1016_10160802_9_dialog_content = "快走吧。狄希斯小隊，你們也快跟上我們吧。",
  ui_story_1016_10160802_10_dialog_content = "啊，多謝提醒，不過我們暫時還沒有繼續深入的打算。",
  ui_story_1016_10160802_11_dialog_content = "我們還有重要的事情需要完成。",
  ui_story_1016_10160802_12_dialog_content = "（總覺得他們怪怪的……）",
  ui_story_1016_10160802_13_dialog_content = "既然如此，PlayerName、薇絲，我們快走吧。",
  ui_story_1016_10160802_14_dialog_content = "唔，好的。",
  ui_story_1016_10160802_15_dialog_content = "<color=#e8d9bb>暗面地下城深處</color>",
  ui_story_1016_10160802_16_dialog_content = "看到另外幾個小隊了嗎？",
  ui_story_1016_10160802_17_dialog_content = "沒有。按照目前的情況來看，我們的進度最快。",
  ui_story_1016_10160802_18_dialog_content = "不錯，勢頭很好。這些考核比我想像得更容易一些。",
  ui_story_1016_10160802_19_dialog_content = "不過話說回來，騎士、軍師和光能術強大的牧師……",
  ui_story_1016_10160802_20_dialog_content = "我們這樣的隊伍構成，也很難在這裡失敗吧。",
  ui_story_1016_10160802_21_dialog_content = "呵呵，你還真是毫不謙虛。",
  ui_story_1016_10160802_22_dialog_content = "既然我們已經獲得了領先的優勢，不如再乘勝追擊一下。",
  ui_story_1016_10160802_23_dialog_content = "貢露考核官——",
  ui_story_1016_10160802_24_dialog_content = "嗯，我在聽喔。",
  ui_story_1016_10160802_25_dialog_content = "我們支付剩餘的所有學分，請告訴我們目的地的詳細座標。",
  ui_story_1016_10160802_26_dialog_content = "唔，可以是可以啦，但你們還真是大手大腳的～",
  ui_story_1016_10160802_27_dialog_content = "已經到了最後關頭，還是要物盡其用才好。",
  ui_story_1016_10160802_28_dialog_content = "<color=#e8d9bb>嗶——</color>",
  ui_story_1016_10160802_29_dialog_content = "好了，你們可以檢查一下你們的地圖，標記的區域就是目的地。",
  ui_story_1016_10160802_30_dialog_content = "因為這說到底也是規則之內的事情，我好像也沒辦法把你們判定為作弊。",
  ui_story_1016_10160802_31_dialog_content = "你們能充分地利用並享受遊戲規則，這還讓我滿高興的。",
  ui_story_1016_10160802_32_dialog_content = "快去吧，繼續認真過關吧～",
  ui_story_1016_10160802_33_dialog_content = "這下就萬事具備了。",
  ui_story_1016_10160802_34_dialog_content = "趁著還沒有被趕上來，我們快走吧。",
  ui_story_1016_10160802_35_dialog_content = "<color=#e8d9bb>暗面地下城深處 目的地附近</color>",
  ui_story_1016_10160802_36_dialog_content = "<anim type=Shake>嘎……</anim>",
  ui_story_1016_10160802_37_dialog_content = "好了，這就是這一帶最後一隻暗鬼了。",
  ui_story_1016_10160802_38_dialog_content = "雖然你們心向黑暗，但還是願光之神賜你們免受痛苦。",
  ui_story_1016_10160802_39_dialog_content = "我倒是覺得說出這種話的你才更加可怕……",
  ui_story_1016_10160802_40_dialog_content = "雖說我們現在已經無限接近了旗子的所在地，但要說詳細位置……",
  ui_story_1016_10160802_41_dialog_content = "這麼大的地下城，它會被放置在什麼地方呢。",
  ui_story_1016_10160802_42_dialog_content = "<color=#e8d9bb>砰——砰！</color>",
  ui_story_1016_10160802_43_dialog_content = "<size=45>！！！</size>",
  ui_story_1016_10160802_44_dialog_content = "有埋伏！",
  ui_story_1016_10160802_45_dialog_content = "這個問題，當然只能交給情報官來解決了。",
  ui_story_1016_10160802_46_dialog_content = "久等了，多虧了你們這幾個打手，周圍已經變成相對安全的決戰之地了。",
  ui_story_1016_10160802_47_dialog_content = "<size=32>嘖……</size>",
  ui_story_1016_10160802_48_dialog_content = "<size=32>李奧，他們來得比我們更早。</size>",
  ui_story_1016_10160802_49_dialog_content = "<size=32>他們可是主場作戰，我早該預想到的。</size>",
  ui_story_1016_10160802_50_dialog_content = "既然扳機都扣了，那他們的意思也很明顯了。",
  ui_story_1016_10160802_51_dialog_content = "奪冠之路上的爭鬥從來不可避免，因為勝利不會同時屬於兩方。",
  ui_story_1016_10160802_52_dialog_content = "很好，那就讓我們都認真起來吧。",
  ui_story_1016_10160802_53_dialog_content = "阿克希亞，準備戰鬥。",
  ui_story_1016_10160901_1_dialog_content = "<color=#e8d9bb>砰——砰砰！</color>",
  ui_story_1016_10160901_2_dialog_content = "看起來，來者不善啊。",
  ui_story_1016_10160901_3_dialog_content = "我這邊暫時沒辦法幫忙了。李奧，你小心點，那傢伙衝著你去了。",
  ui_story_1016_10160901_4_dialog_content = "還沒有結束。",
  ui_story_1016_10160901_5_dialog_content = "<size=45>！！！</size>",
  ui_story_1016_10160901_6_dialog_content = "李奧！",
  ui_story_1016_10160901_7_dialog_content = "謝了！",
  ui_story_1016_10160901_8_dialog_content = "沒想到，妳看起來瘦瘦小小的，卻有著不俗的實力。",
  ui_story_1016_10160901_9_dialog_content = "啟光聯邦還真是人才輩出，讓人羡慕得眼紅啊。",
  ui_story_1016_10160901_10_dialog_content = "三次方。",
  ui_story_1016_10160901_11_dialog_content = "呃！",
  ui_story_1016_10160901_12_dialog_content = "（她這是看出了我的行動路線，要將我們分開嗎？）",
  ui_story_1016_10160901_13_dialog_content = "（現在正是機會。）",
  ui_story_1016_10160901_14_dialog_content = "（要用這些作弊得來的裝備進攻，多少讓人覺得有點不愉快。）",
  ui_story_1016_10160901_15_dialog_content = "（這麼想讓我們……不，想讓這一隊獲得勝利，這也是那些人的決定嗎？）",
  ui_story_1016_10160901_16_dialog_content = "（現有的情報太少了，只能先走一步看一步。）",
  ui_story_1016_10160901_17_dialog_content = "（那麼，破綻在這裡！）",
  ui_story_1016_10160901_18_dialog_content = "你果然來了。",
  ui_story_1016_10160901_19_dialog_content = "<size=45>什麼？！</size>",
  ui_story_1016_10160901_20_dialog_content = "你們的行動已經被我們猜到了。",
  ui_story_1016_10160901_21_dialog_content = "請不要小看任何一個人來自黃昏鎮的人。",
  ui_story_1016_10160901_22_dialog_content = "呃！！！",
  ui_story_1016_10160901_23_dialog_content = "（好強？！）",
  ui_story_1016_10160901_24_dialog_content = "（明明攜帶了這麼多裝備，但他的攻擊卻還是能夠穿透防禦……）",
  ui_story_1016_10160901_25_dialog_content = "（這個人的實力，遠沒有情報中寫的那麼簡單！）",
  ui_story_1016_10160901_26_dialog_content = "請原諒，我必須打倒你。",
  ui_story_1016_10160901_27_dialog_content = "<size=45>！！！</size>",
  ui_story_1016_10160901_28_dialog_content = "鶯歌，請求支援！",
  ui_story_1016_10160901_29_dialog_content = "竟然？！",
  ui_story_1016_10160901_30_dialog_content = "阿納托利！",
  ui_story_1016_10160901_31_dialog_content = "這個時候分心，是重大的決策失誤！",
  ui_story_1016_10160901_32_dialog_content = "——！",
  ui_story_1016_10160901_33_dialog_content = "（糟了，主動權被對方奪走了。）",
  ui_story_1016_10160901_34_dialog_content = "<color=#e8d9bb>與此同時，廢棄地下城某處</color>",
  ui_story_1016_10160901_35_dialog_content = "這裡到底是哪裡啊？",
  ui_story_1016_10160901_36_dialog_content = "剛才只顧著跟上那個小隊的人，沒想到竟然被帶到了這種地方……",
  ui_story_1016_10160901_37_dialog_content = "這裡看起來像是走廊一樣的地方。",
  ui_story_1016_10160901_38_dialog_content = "但是顯然已經很久沒有人來過了。",
  ui_story_1016_10160901_39_dialog_content = "是啊，現在這裡除了灰塵，就只剩下蜘蛛網。",
  ui_story_1016_10160901_40_dialog_content = "感覺隨時都會跳出來什麼奇怪的東西……",
  ui_story_1016_10160901_41_dialog_content = "<anim type=Shake><size=45>吼……</size></anim>",
  ui_story_1016_10160901_42_dialog_content = "這個感覺是……大家小心！",
  ui_story_1016_10160901_43_dialog_content = "有大傢伙向著這邊過來了！",
  ui_story_1016_10160901_44_dialog_content = "<anim type=Shake><size=50>吼——！！！</size></anim>",
  ui_story_1016_10160901_45_dialog_content = "呀——！",
  ui_story_1016_10160901_46_dialog_content = "這、這是，大蜘蛛？！",
  ui_story_1016_10160901_47_dialog_content = "別放鬆警惕，這傢伙看起來很強。",
  ui_story_1016_10160901_48_dialog_content = "速戰速決吧，我們的目標是找到旗子！",
  ui_story_1016_10160902_1_dialog_content = "<anim type=Shake><size=50>吼——！！！</size></anim>",
  ui_story_1016_10160902_2_dialog_content = "薇絲，我們配合！",
  ui_story_1016_10160902_3_dialog_content = "好！",
  ui_story_1016_10160902_4_dialog_content = "冰花——！",
  ui_story_1016_10160902_5_dialog_content = "<anim type=Shake><size=50>吼！！！</size></anim>",
  ui_story_1016_10160902_6_dialog_content = "<size=45>就是現在！</size>",
  ui_story_1016_10160902_7_dialog_content = "一擊必中！",
  ui_story_1016_10160902_8_dialog_content = "<anim type=Shake><size=40>吼——</size></anim>",
  ui_story_1016_10160902_9_dialog_content = "終於打倒了……",
  ui_story_1016_10160902_10_dialog_content = "呼——是啊。",
  ui_story_1016_10160902_11_dialog_content = "這傢伙也太強了吧！",
  ui_story_1016_10160902_12_dialog_content = "剛才遇到的那些暗鬼根本就沒辦法和這隻比。",
  ui_story_1016_10160902_13_dialog_content = "確實，這種強度的暗鬼完全不該出現在考核裡。",
  ui_story_1016_10160902_14_dialog_content = "明明只是演習，但這隻暗鬼卻這麼強，還隱藏在這種偏僻的角落裡……",
  ui_story_1016_10160902_15_dialog_content = "難道是有什麼人故意把牠放在這裡的？",
  ui_story_1016_10160902_16_dialog_content = "這就不知道了，也可能是我們自己比較倒楣吧。",
  ui_story_1016_10160902_17_dialog_content = "這座地下城看起來廢棄了滿長一段時間的，就算冒出幾個暗鬼也不稀奇。",
  ui_story_1016_10160902_18_dialog_content = "這件事還是留著以後再討論吧。",
  ui_story_1016_10160902_19_dialog_content = "我們已經耽誤太多時間了。",
  ui_story_1016_10160902_20_dialog_content = "再耗下去，恐怕就要失敗了。",
  ui_story_1016_10160902_21_dialog_content = "<color=#e8d9bb>轟隆——</color>",
  ui_story_1016_10160902_22_dialog_content = "這是什麼聲音？！",
  ui_story_1016_10160902_23_dialog_content = "是暗鬼？",
  ui_story_1016_10160902_24_dialog_content = "難道又是暗鬼？",
  ui_story_1016_10160902_25_dialog_content = "不，恐怕不是……",
  ui_story_1016_10160902_26_dialog_content = "<color=#e8d9bb>轟隆……轟隆隆……砰……</color>",
  ui_story_1016_10160902_27_dialog_content = "你聽，這些聲音裡既有槍聲又有光能術的聲音，非常密集，不像是單一小隊的火力。",
  ui_story_1016_10160902_28_dialog_content = "確實，這更像是兩個不同的小隊在互相戰鬥的聲音！",
  ui_story_1016_10160902_29_dialog_content = "這場戰鬥的目標是奪取旗幟，與對手遭遇並戰鬥並不是上策，除非……",
  ui_story_1016_10160902_30_dialog_content = "除非雙方同時發現了旗子！",
  ui_story_1016_10160902_31_dialog_content = "是旗子？",
  ui_story_1016_10160902_32_dialog_content = "難道有人發現了旗子？",
  ui_story_1016_10160902_33_dialog_content = "有可能，你們仔細聽這個聲音。",
  ui_story_1016_10160902_34_dialog_content = "<color=#e8d9bb>轟隆……轟隆隆……砰……</color>",
  ui_story_1016_10160902_35_dialog_content = "你聽，這些聲音裡既有槍聲又有光能術的聲音，非常密集，不像是單一小隊的火力。",
  ui_story_1016_10160902_36_dialog_content = "難道說，是兩隻小隊同時發現了旗子，為了爭奪旗子打了起來？！",
  ui_story_1016_10160902_37_dialog_content = "很有可能！",
  ui_story_1016_10160902_38_dialog_content = "我們必須馬上趕過去，不能把勝利拱手讓人！",
  ui_story_1016_10160902_39_dialog_content = "嗯！",
  ui_story_1016_10160902_40_dialog_content = "<color=#e8d9bb>與此同時，廢棄地下城深處</color>",
  ui_story_1016_10160902_41_dialog_content = "目標已鎖定！",
  ui_story_1016_10160902_42_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_1016_10160902_43_dialog_content = "別想過去！",
  ui_story_1016_10160902_44_dialog_content = "（沒想到他們竟然這麼強，能在失去先機的情況下和我們打成平手。）",
  ui_story_1016_10160902_45_dialog_content = "（尤其是那個叫阿納托利的情報官，他身上的裝備是怎麼回事？）",
  ui_story_1016_10160902_46_dialog_content = "（我一直關注著那支小隊的積分，他們的積分比我們低，卻獲得了比我們還好的裝備。）",
  ui_story_1016_10160902_47_dialog_content = "（真是奇怪，就這件事來看，啟光內部似乎為他們提供了巨大的便利。）",
  ui_story_1016_10160902_48_dialog_content = "（反正黃昏鎮的情況已經被啟光的實戰派得知，我們的目的達到了，所以……）",
  ui_story_1016_10160902_49_dialog_content = "若瑟！",
  ui_story_1016_10160902_50_dialog_content = "我在！",
  ui_story_1016_10160902_51_dialog_content = "……",
  ui_story_1016_10160902_52_dialog_content = "（他的意思是……）",
  ui_story_1016_10160902_53_dialog_content = "我知道了。",
  ui_story_1016_10160902_54_dialog_content = "（他的進攻變慢了？難道是障眼法？）",
  ui_story_1016_10160902_55_dialog_content = "（不，這是個絕妙的機會！）",
  ui_story_1016_10160902_56_dialog_content = "鶯歌！",
  ui_story_1016_10160902_57_dialog_content = "明白了！",
  ui_story_1016_10160902_58_dialog_content = "昭！收縮陣型，準備防禦！",
  ui_story_1016_10160902_59_dialog_content = "我知道！",
  ui_story_1016_10160902_60_dialog_content = "不會讓你們得逞！",
  ui_story_1016_10160902_61_dialog_content = "<color=#e8d9bb>砰！砰砰——</color>",
  ui_story_1016_10160902_62_dialog_content = "糟了，退路被阻斷了！",
  ui_story_1016_10160902_63_dialog_content = "阿克希亞，就是現在！",
  ui_story_1016_10160902_64_dialog_content = "久等了。",
  ui_story_1016_10160902_65_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_1016_10160902_66_dialog_content = "呃——！",
  ui_story_1016_10160902_67_dialog_content = "昭被擊倒了！",
  ui_story_1016_10160902_68_dialog_content = "盡量靠近我，我用光能術支援你！",
  ui_story_1016_10160902_69_dialog_content = "這是白費力氣。",
  ui_story_1016_10160902_70_dialog_content = "<color=#e8d9bb>轟！！！</color>",
  ui_story_1016_10160902_71_dialog_content = "咳……咳咳咳！",
  ui_story_1016_10160902_72_dialog_content = "該說不愧是啟光的最強兵器嗎，竟然擁有這麼可怕的力量。",
  ui_story_1016_10160902_73_dialog_content = "如果是這樣，那我也沒什麼辦法了呢。",
  ui_story_1016_10160902_74_dialog_content = "是啊，我們認輸。",
  ui_story_1016_10160902_75_dialog_content = "你們的選擇是明智的。",
  ui_story_1016_10160902_76_dialog_content = "去拿旗子吧，阿克希亞。",
  ui_story_1016_10160902_77_dialog_content = "瞭解。",
  ui_story_1016_10160902_78_dialog_content = "那麼，獲勝者是——",
  ui_story_1016_10160902_79_dialog_content = "<size=45>趕上了！！！</size>",
  ui_story_1016_10160902_80_dialog_content = "……",
  ui_story_1016_10160902_81_dialog_content = "…………",
  ui_story_1016_10160902_82_dialog_content = "………………",
  ui_story_1016_10160902_83_dialog_content = "嗎……？",
  ui_story_1016_10160902_84_dialog_content = "很可惜，沒有。",
  ui_story_1016_10160902_85_dialog_content = "如果你們能提前五秒鐘趕到，就還有資格與阿克希亞和阿克希亞的同伴們競爭。",
  ui_story_1016_10160902_86_dialog_content = "是嗎？看起來是我們耽誤太長時間了。",
  ui_story_1016_10160902_87_dialog_content = "怎麼會這樣……",
  ui_story_1016_10160902_88_dialog_content = "明明就差一點……",
  ui_story_1016_10160902_89_dialog_content = "好了，不要後悔了。",
  ui_story_1016_10160902_90_dialog_content = "既然結局已定，再怎麼後悔也沒用。",
  ui_story_1016_10160902_91_dialog_content = "還是努力提升自己吧。",
  ui_story_1016_10160902_92_dialog_content = "嗯，妳說得對……",
  ui_story_1016_10160902_93_dialog_content = "那麼，我來宣布成績。",
  ui_story_1016_10160902_94_dialog_content = "本次測試的獲勝隊伍是——<color=#FFB400>鶯歌小隊</color>！",
  ui_story_1016_10160902_95_dialog_content = "綜合所有得分，最終獲得個人第一名的是——<color=#FFB400>阿克希亞</color>中尉！",
  ui_story_1016_10160902_96_dialog_content = "恭喜你們。",
  ui_story_1016_10160902_97_dialog_content = "謝謝。",
  ui_story_1016_10160902_98_dialog_content = "（終於順利結束了。）",
  ui_story_1016_10160902_99_dialog_content = "阿克希亞，贏了。",
  ui_story_1016_10160902_100_dialog_content = "這是預期之中的事情。",
  ui_story_1016_10160902_101_dialog_content = "（她們兩個看起來一點也不驚訝，也沒有任何喜悅。）",
  ui_story_1016_10160902_102_dialog_content = "（就算她們本來不善於表達情緒，這一點也太奇怪了。）",
  ui_story_1016_10160902_103_dialog_content = "（難道，這也是計畫好的嗎……）",
  ui_story_1016_10161001_1_dialog_content = "恭喜妳，阿克希亞中尉！",
  ui_story_1016_10161001_2_dialog_content = "妳能獲得勝利，全啟光的人都為妳高興！",
  ui_story_1016_10161001_3_dialog_content = "這是阿克希亞應該做的事情。",
  ui_story_1016_10161001_4_dialog_content = "讓一讓，都讓一讓——",
  ui_story_1016_10161001_5_dialog_content = "她現在需要及時休息。",
  ui_story_1016_10161001_6_dialog_content = "那個強大的小姑娘被啟光的人團團圍住了。",
  ui_story_1016_10161001_7_dialog_content = "是啊。",
  ui_story_1016_10161001_8_dialog_content = "我想，我有權利知道，是什麼讓你做出了那樣的選擇——",
  ui_story_1016_10161001_9_dialog_content = "選擇主動放棄勝利。",
  ui_story_1016_10161001_10_dialog_content = "因為我們的目的已經達到了。",
  ui_story_1016_10161001_11_dialog_content = "黃昏鎮的情況已經被啟光的雷霆軍團長知道，她有豐富的戰鬥經驗，能明白我們的處境。",
  ui_story_1016_10161001_12_dialog_content = "而這個資訊，很快也會透過啟光的資訊網被白夜城的高層得知。",
  ui_story_1016_10161001_13_dialog_content = "但即便如此，我仍然認為我們有必要奪取聯合軍演的勝利。",
  ui_story_1016_10161001_14_dialog_content = "那會讓我們受到更多關注，也能為黃昏鎮爭取更多援助。",
  ui_story_1016_10161001_15_dialog_content = "危機近在眼前，我們需要更大的勝算。",
  ui_story_1016_10161001_16_dialog_content = "但你還是聽了我的建議，選擇認輸。",
  ui_story_1016_10161001_17_dialog_content = "因為我相信你的判斷，但我想要知道原因。",
  ui_story_1016_10161001_18_dialog_content = "只有這樣，我們才能更順利合作。",
  ui_story_1016_10161001_19_dialog_content = "我認為啟光隊伍有一些不為人知的手段。",
  ui_story_1016_10161001_20_dialog_content = "我從一開始就在關注那支啟光聯邦的隊伍，他們有很多奇怪的地方。",
  ui_story_1016_10161001_21_dialog_content = "他們的實力確實不俗，但他們贏得卻不光彩。",
  ui_story_1016_10161001_22_dialog_content = "你是說……他們在作弊？",
  ui_story_1016_10161001_23_dialog_content = "我沒有實際的證據，但基本上可以確定。",
  ui_story_1016_10161001_24_dialog_content = "他們在最後一戰中使用的裝備，超過了以他們的積分能夠獲得的裝備上限。",
  ui_story_1016_10161001_25_dialog_content = "雖然超過的程度不多，不容易被他人察覺，但卻足以讓他們的實力再上一個層次。",
  ui_story_1016_10161001_26_dialog_content = "他們背後有人。",
  ui_story_1016_10161001_27_dialog_content = "是啟光的高層嗎？",
  ui_story_1016_10161001_28_dialog_content = "或許吧，總而言之，他們的勝利是被安排好的。",
  ui_story_1016_10161001_29_dialog_content = "他們的根本目的並不是取得勝利，而是別的什麼東西。",
  ui_story_1016_10161001_30_dialog_content = "根本目的不是取得勝利，但勝利卻是先決條件……",
  ui_story_1016_10161001_31_dialog_content = "難道……",
  ui_story_1016_10161001_32_dialog_content = "誰知道呢。",
  ui_story_1016_10161001_33_dialog_content = "或許這裡馬上要變得不太平了。",
  ui_story_1016_10161001_34_dialog_content = "什麼嘛——",
  ui_story_1016_10161001_35_dialog_content = "為什麼我們為黃昏鎮小隊準備的「驚喜」全都被那個PlayerName帶領的小隊解決了……",
  ui_story_1016_10161001_36_dialog_content = "他們究竟只是單純的倒楣，還是故意想要破壞我們的計畫？",
  ui_story_1016_10161001_37_dialog_content = "至少目前看起來，這一切還只是巧合，不過這並不是一件壞事。",
  ui_story_1016_10161001_38_dialog_content = "黃昏鎮的小隊已經透過演習證明了自己的實力，而這些「驚喜」為我們帶來了意外的發現。",
  ui_story_1016_10161001_39_dialog_content = "發現這麼多有關注價值的強者，「大人」想必會很開心。",
  ui_story_1016_10161001_40_dialog_content = "另外，空裔小隊擊敗盤絲蛛后花費的時間比我們預計的少得多，這證明他們的實力也有很大的成長。",
  ui_story_1016_10161001_41_dialog_content = "可是，我們的驚喜似乎害他們沒有得到冠軍。",
  ui_story_1016_10161001_42_dialog_content = "希望他們不要生我們的氣……",
  ui_story_1016_10161001_43_dialog_content = "<anim type=Shake>呼啊——</anim>好睏。",
  ui_story_1016_10161001_44_dialog_content = "我們什麼時候能回去啊，我好想連睡三天三夜……",
  ui_story_1016_10161001_45_dialog_content = "不要著急，明詩。",
  ui_story_1016_10161001_46_dialog_content = "我們還有工作沒有完成，還不能走。",
  ui_story_1016_10161001_47_dialog_content = "是啊，我們還有一項非常重要的工作。",
  ui_story_1016_10161001_48_dialog_content = "<color=#e8d9bb>迦南城，尤利西斯的辦公室</color>",
  ui_story_1016_10161001_49_dialog_content = "又回到迦南城了。",
  ui_story_1016_10161001_50_dialog_content = "接下來要發生的事情，將會開啟啟光的新篇章。",
  ui_story_1016_10161001_51_dialog_content = "嗯？這是……",
  ui_story_1016_10161001_52_dialog_content = "她的計畫還真是縝密，都讓人覺得快沒時間休息了。",
  ui_story_1016_10161001_53_dialog_content = "艾森，你來找我一趟。",
  ui_story_1016_10161001_54_dialog_content = "是。",
  ui_story_1016_10161001_55_dialog_content = "<color=#e8d9bb>咚咚咚</color>",
  ui_story_1016_10161001_56_dialog_content = "長官，需要我做什麼？",
  ui_story_1016_10161001_57_dialog_content = "你拿著這個，把它送給那位「<color=#FFB400>鐵面</color>」大人，就說——",
  ui_story_1016_10161001_58_dialog_content = "這是我準備的城防結構調整書，需要她進行配合。",
  ui_story_1016_10161001_59_dialog_content = "是。",
  ui_story_1016_10161001_60_dialog_content = "<color=#e8d9bb>與此同時，迦南城某處</color>",
  ui_story_1016_10161001_61_dialog_content = "時間還沒到，但是啟光的人卻越追越緊。",
  ui_story_1016_10161001_62_dialog_content = "那個老東西，就這麼覬覦我的實驗成果嗎……",
  ui_story_1016_10161001_63_dialog_content = "那樣的話，就讓玉子再……",
  ui_story_1016_10161001_64_dialog_content = "……",
  ui_story_1016_10161001_65_dialog_content = "那傢伙，應該已經跑遠了。",
  ui_story_1016_10161001_66_dialog_content = "德尼耶爾！",
  ui_story_1016_10161001_67_dialog_content = "什麼事，姐姐？",
  ui_story_1016_10161001_68_dialog_content = "妳還記得今天是什麼日子嗎？",
  ui_story_1016_10161001_69_dialog_content = "什麼日子……？",
  ui_story_1016_10161001_70_dialog_content = "實驗報告的提交日？還是考核前的最後一天？",
  ui_story_1016_10161001_71_dialog_content = "都錯了！",
  ui_story_1016_10161001_72_dialog_content = "難道妳忘了嗎？今天是妳的生日啊！",
  ui_story_1016_10161001_73_dialog_content = "生日？哦，好像確實是。",
  ui_story_1016_10161001_74_dialog_content = "妳怎麼連自己的生日都會忘？",
  ui_story_1016_10161001_75_dialog_content = "又不是什麼重要的日子，除了多了一個「生日」的定義外，和其他日子沒有區別。",
  ui_story_1016_10161001_76_dialog_content = "唉……真不愧是妳。",
  ui_story_1016_10161001_77_dialog_content = "也只有妳會給出這種冷靜又理性的回答了吧。",
  ui_story_1016_10161001_78_dialog_content = "但就算妳自己不在意，也還是有人會在意的。",
  ui_story_1016_10161001_79_dialog_content = "哦？",
  ui_story_1016_10161001_80_dialog_content = "我為妳準備了生日禮物。",
  ui_story_1016_10161001_81_dialog_content = "就是這個！",
  ui_story_1016_10161001_82_dialog_content = "吱！",
  ui_story_1016_10161001_83_dialog_content = "這是？！",
  ui_story_1016_10161001_84_dialog_content = "哈哈哈，牠好像還滿喜歡妳的！",
  ui_story_1016_10161001_85_dialog_content = "這是我之前在戰場上撿到的，雖然不知道是哪種動物，但看起來很乖。",
  ui_story_1016_10161001_86_dialog_content = "我把牠帶回來養了幾天，試著用鋸末麵包餵牠，但牠好像不太愛吃。",
  ui_story_1016_10161001_87_dialog_content = "我希望牠能在我不在妳身邊的時候，代替我陪著妳。",
  ui_story_1016_10161001_88_dialog_content = "妳這傢伙真是……",
  ui_story_1016_10161001_89_dialog_content = "這是龍貓，一般情況下牠不吃麵包。",
  ui_story_1016_10161001_90_dialog_content = "要餵的話，就給牠吃乾草或穀類，也可以餵一點胡蘿蔔。",
  ui_story_1016_10161001_91_dialog_content = "果然把牠交給妳養是對的。",
  ui_story_1016_10161001_92_dialog_content = "因為這種動物也會被當成實驗動物使用，飼養實驗動物是研究的一環。",
  ui_story_1016_10161001_93_dialog_content = "<anim type=Shake><size=45>吱！！！</size></anim>",
  ui_story_1016_10161001_94_dialog_content = "妳看，妳都嚇壞牠了！",
  ui_story_1016_10161001_95_dialog_content = "……",
  ui_story_1016_10161001_96_dialog_content = "<anim type=Shake>吱……</anim>",
  ui_story_1016_10161001_97_dialog_content = "如果是妳送的，我就不會對牠怎麼樣。",
  ui_story_1016_10161001_98_dialog_content = "妳的意思是，妳收下這份禮物了？",
  ui_story_1016_10161001_99_dialog_content = "嗯。",
  ui_story_1016_10161001_100_dialog_content = "那就幫牠取個名字吧？",
  ui_story_1016_10161001_101_dialog_content = "名字……",
  ui_story_1016_10161001_102_dialog_content = "就叫「<color=#FFB400>玉子</color>」吧。",
  ui_story_1016_10161001_103_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_1016_10161001_104_dialog_content = "實驗，我的實驗……",
  ui_story_1016_10161001_105_dialog_content = "已經全都毀了……",
  ui_story_1016_10161001_106_dialog_content = "萊因哈特，為什麼，妳又沒有來？",
  ui_story_1016_10161001_107_dialog_content = "<anim type=Shake><size=45>吱——吱——</size></anim>",
  ui_story_1016_10161001_108_dialog_content = "你……",
  ui_story_1016_10161001_109_dialog_content = "我希望牠能在我不在妳身邊的時候，代替我陪著妳。",
  ui_story_1016_10161001_110_dialog_content = "你竟然……！",
  ui_story_1016_10161001_111_dialog_content = "<anim type=Shake><size=45>吱！吱——！！！</size></anim>",
  ui_story_1016_10161001_112_dialog_content = "<anim type=Shake>吱……</anim>",
  ui_story_1016_10161001_113_dialog_content = "——！！！",
  ui_story_1016_10161001_114_dialog_content = "吱！",
  ui_story_1016_10161001_115_dialog_content = "<anim type=Shake>吱……吱……</anim>",
  ui_story_1016_10161001_116_dialog_content = "為什麼？明明只要再用力一點，我就能輕易擰斷你的脖子。",
  ui_story_1016_10161001_117_dialog_content = "你為什麼不像她一樣逃跑？",
  ui_story_1016_10161001_118_dialog_content = "<anim type=Shake><size=32>吱……</size></anim>",
  ui_story_1016_10161001_119_dialog_content = "……",
  ui_story_1016_10161001_120_dialog_content = "算了……",
  ui_story_1016_10161001_121_dialog_content = "我允許你留下來。",
  ui_story_1016_10161001_122_dialog_content = "至少，你還有作為實驗動物的價值。",
  ui_story_1016_10161001_123_dialog_content = "「價值」嗎。",
  ui_story_1016_10161001_124_dialog_content = "這個世界上，確實只有價值是衡量事物的永恆標準。",
  ui_story_1016_10161001_125_dialog_content = "<color=#e8d9bb>窸窸窣窣……</color>",
  ui_story_1016_10161001_126_dialog_content = "德尼耶爾……有動靜……小心……",
  ui_story_1016_10161001_127_dialog_content = "吼……",
  ui_story_1016_10161001_128_dialog_content = "有……暗鬼！",
  ui_story_1016_10161001_129_dialog_content = "……",
  ui_story_1016_10161001_130_dialog_content = "放下你的武器，牠不會傷害你。",
  ui_story_1016_10161001_131_dialog_content = "（日蝕語）吞羅大人，我帶來了<color=#FFB400>斐桀洛</color>大人的口信。",
  ui_story_1016_10161001_132_dialog_content = "（日蝕語）說。",
  ui_story_1016_10161001_133_dialog_content = "（日蝕語）他要您從內部破壞啟光的防禦系統，迎接「<color=#FFB400>大人物</color>」的到來。",
  ui_story_1016_10161001_134_dialog_content = "（日蝕語）終於到時間了。",
  ui_story_1016_10161001_135_dialog_content = "<color=#e8d9bb>表演賽當天，距離比賽開始還有15分鐘</color>",
  ui_story_1016_10161001_136_dialog_content = "唉——",
  ui_story_1016_10161001_137_dialog_content = "沒想到，竟然沒有幫卡蓮再次奪冠。",
  ui_story_1016_10161001_138_dialog_content = "唉……",
  ui_story_1016_10161001_139_dialog_content = "別那麼灰心喪氣，沒什麼好可惜的。",
  ui_story_1016_10161001_140_dialog_content = "這場軍演來的本就是各方勢力的頂尖人才，有比我更強的人不足為奇。",
  ui_story_1016_10161001_141_dialog_content = "勝利或失敗，本就不是注定的，這次的失敗讓我見識到了更強的人，也讓我有了新的努力目標。",
  ui_story_1016_10161001_142_dialog_content = "卡蓮又說出了帥氣得不得了的話呢。",
  ui_story_1016_10161001_143_dialog_content = "有、有嗎？",
  ui_story_1016_10161001_144_dialog_content = "你們也來看比賽了？",
  ui_story_1016_10161001_145_dialog_content = "李奧，你也來啦。",
  ui_story_1016_10161001_146_dialog_content = "昭和若瑟沒和你在一起嗎？",
  ui_story_1016_10161001_147_dialog_content = "這幾天的演習讓昭有些勞累過度，身體出現了不適，就沒來看表演賽。",
  ui_story_1016_10161001_148_dialog_content = "現在他正在接受醫療中心的檢查，若瑟在照顧他。",
  ui_story_1016_10161001_149_dialog_content = "感覺你們的關係變好了，竟然能互相照顧了？",
  ui_story_1016_10161001_150_dialog_content = "哈哈哈，或許吧。",
  ui_story_1016_10161001_151_dialog_content = "這次合作也讓我們之間互相瞭解得更深。",
  ui_story_1016_10161001_152_dialog_content = "就算身處不同的陣營，我們之間也可以成為值得尊重的隊友和勁敵。",
  ui_story_1016_10161001_153_dialog_content = "亦敵亦友嗎……",
  ui_story_1016_10161001_154_dialog_content = "受教了。",
  ui_story_1016_10161001_155_dialog_content = "那是鶯歌嗎，還有阿納托利？",
  ui_story_1016_10161001_156_dialog_content = "咦？他們在哪裡，要不要去打個招呼？",
  ui_story_1016_10161001_157_dialog_content = "你看那邊，裁判席旁邊的位置。",
  ui_story_1016_10161001_158_dialog_content = "怎麼會這樣……",
  ui_story_1016_10161001_159_dialog_content = "難道是暗鬼幹的嗎？",
  ui_story_1016_10161001_160_dialog_content = "現在情況非常緊急。",
  ui_story_1016_10161001_161_dialog_content = "我們走，去看看。",
  ui_story_1016_10161001_162_dialog_content = "好奇怪，他們的表情怎麼這麼嚴肅？",
  ui_story_1016_10161001_163_dialog_content = "不過隔得太遠了，完全聽不清他們在說什麼。",
  ui_story_1016_10161001_164_dialog_content = "唔，在商量什麼重要的事嗎？",
  ui_story_1016_10161001_165_dialog_content = "直接去問問吧。",
  ui_story_1016_10161001_166_dialog_content = "作為一個白夜城的人，你為什麼對啟光的事情這麼關心？",
  ui_story_1016_10161001_167_dialog_content = "我需要糾正一下您的說法——我不關心啟光的事，但我關心黃昏鎮的事情。",
  ui_story_1016_10161001_168_dialog_content = "您應該也聽說了，黃昏鎮正在面臨暗鬼進攻的壓力，並且這壓力正在與日俱增。",
  ui_story_1016_10161001_169_dialog_content = "黃昏鎮需要更多的力量才能確保自身的安全。",
  ui_story_1016_10161001_170_dialog_content = "而現在，啟光的各位看起來遇到了一些麻煩，似乎需要幫助。",
  ui_story_1016_10161001_171_dialog_content = "所以我認為，在適當的時候賣給啟光的未來棟樑們一個人情，也是個不錯的選擇。",
  ui_story_1016_10161001_172_dialog_content = "我聽說過黃昏鎮的事情，也知道你們面臨的壓力。",
  ui_story_1016_10161001_173_dialog_content = "我會向白夜城的高層報告這件事，請他們商議對策。",
  ui_story_1016_10161001_174_dialog_content = "感謝您對黃昏鎮的關心。",
  ui_story_1016_10161001_175_dialog_content = "不過按照以往的經驗來看，這件事恐怕也會不了了之。",
  ui_story_1016_10161001_176_dialog_content = "比起口頭應允，黃昏鎮更需要現實的幫助。",
  ui_story_1016_10161001_177_dialog_content = "……",
  ui_story_1016_10161001_178_dialog_content = "我會努力想辦法。",
  ui_story_1016_10161001_179_dialog_content = "感謝您的努力。我這邊也希望能爭取到更多援助。",
  ui_story_1016_10161001_180_dialog_content = "如果能多掙一份人情，對黃昏鎮也有好處。",
  ui_story_1016_10161001_181_dialog_content = "各位請繼續留在這裡看比賽吧，我先失陪一下。",
  ui_story_1016_10161001_182_dialog_content = "我也去吧。我是啟光的軍人，如果他們遇到了麻煩，我有義務幫忙！",
  ui_story_1016_10161001_183_dialog_content = "我也去！算我一個！",
  ui_story_1016_10161001_184_dialog_content = "也算我一個吧。",
  ui_story_1016_10161001_185_dialog_content = "好，那我們走吧。",
  ui_story_1016_10161001_186_dialog_content = "查到原因和嫌疑人了嗎？",
  ui_story_1016_10161001_187_dialog_content = "目前還在調查。",
  ui_story_1016_10161001_188_dialog_content = "整個迦南城的防禦系統總共有多少損壞？",
  ui_story_1016_10161001_189_dialog_content = "目前查明的有16%左右遭到破壞、完全失靈。",
  ui_story_1016_10161001_190_dialog_content = "還有一半左右沒有查明情況，畢竟整個迦南城太大了，各處通道又複雜……",
  ui_story_1016_10161001_191_dialog_content = "但是，目前被破壞的防禦裝置已經足夠將迦南城的防禦撕開一個口子，情況非常危險。",
  ui_story_1016_10161001_192_dialog_content = "在這個節骨眼上搞破壞，難道是吞羅嗎……",
  ui_story_1016_10161001_193_dialog_content = "很有可能。",
  ui_story_1016_10161001_194_dialog_content = "你跟我走，我們需要立刻……",
  ui_story_1016_10161001_195_dialog_content = "鶯歌、阿納托利，請等一下！",
  ui_story_1016_10161001_196_dialog_content = "PlayerName？還有薇絲中尉和白夜城的人？",
  ui_story_1016_10161001_197_dialog_content = "表演賽快開始了，你們不去看比賽，跑到這裡來幹什麼？",
  ui_story_1016_10161001_198_dialog_content = "我們看到你們急匆匆離開，覺得你們說不定遇到了什麼麻煩。",
  ui_story_1016_10161001_199_dialog_content = "如果你們需要，我可以提供幫助。",
  ui_story_1016_10161001_200_dialog_content = "主動提供幫助？這可不像是你們的作風，更何況你並不是啟光人，為什麼這麼關心啟光的事？",
  ui_story_1016_10161001_201_dialog_content = "既然妳這麼說，那我也就直言不諱了。",
  ui_story_1016_10161001_202_dialog_content = "我現在對你們提供幫助，是為了日後換取你們對黃昏鎮的幫助。",
  ui_story_1016_10161001_203_dialog_content = "你為什麼這麼確定我們需要你的幫助？",
  ui_story_1016_10161001_204_dialog_content = "更何況，我只是一名情報官，並不代表啟光，沒辦法動用啟光的力量向你提供幫助。",
  ui_story_1016_10161001_205_dialog_content = "我當然明白，所以我想要的並不是整個啟光的幫助，而是妳和妳的同伴們的幫助。",
  ui_story_1016_10161001_206_dialog_content = "你們都是具有強大實力的人，而黃昏鎮需要強者的幫助。",
  ui_story_1016_10161001_207_dialog_content = "況且……",
  ui_story_1016_10161001_208_dialog_content = "現在正在舉辦聯合軍演最後的表演賽，大家不是正在看比賽，就是在賽場周邊守衛。",
  ui_story_1016_10161001_209_dialog_content = "你們現在應該很缺人手吧？",
  ui_story_1016_10161001_210_dialog_content = "……",
  ui_story_1016_10161001_211_dialog_content = "鶯歌，如果真的出了什麼事，我們作為夥伴肯定也不會置之不理的。",
  ui_story_1016_10161001_212_dialog_content = "特別是如果「吞羅」牽涉其中……",
  ui_story_1016_10161001_213_dialog_content = "吞羅？！",
  ui_story_1016_10161001_214_dialog_content = "你……",
  ui_story_1016_10161001_215_dialog_content = "抱歉，我剛才在過來的路上聽見的，我其實不是故意偷聽……",
  ui_story_1016_10161001_216_dialog_content = "空裔的能力真是令人印象深刻。",
  ui_story_1016_10161001_217_dialog_content = "非常抱歉……",
  ui_story_1016_10161001_218_dialog_content = "鶯歌，可以告訴我目前的情況嗎？如果是吞羅，我們就更不能袖手旁觀了！",
  ui_story_1016_10161001_219_dialog_content = "我們也不止一次並肩作戰過，妳可以相信我們！",
  ui_story_1016_10161001_220_dialog_content = "沒錯！",
  ui_story_1016_10161001_221_dialog_content = "……",
  ui_story_1016_10161001_222_dialog_content = "你的猜測沒錯，我們現在確實需要人幫忙。",
  ui_story_1016_10161001_223_dialog_content = "迦南城的防禦設施出現了故障，現在需要抽調人手進行防守、對損壞的設施進行檢查。",
  ui_story_1016_10161001_224_dialog_content = "但是現在人手不夠，就拜託你們也來幫忙吧。",
  ui_story_1016_10161001_225_dialog_content = "但前提是，如果你們發現了吞羅或者其他罪靈的蹤跡，要第一時間通知我們。",
  ui_story_1016_10161001_226_dialog_content = "吞羅和……其他罪靈？！",
  ui_story_1016_10161001_227_dialog_content = "如果抓到了他們，也要交由啟光處理。",
  ui_story_1016_10161001_228_dialog_content = "這是你們的地盤，聽你們的。",
  ui_story_1016_10161001_229_dialog_content = "防禦設施損壞了？",
  ui_story_1016_10161001_230_dialog_content = "情況很嚴重嗎？",
  ui_story_1016_10161001_231_dialog_content = "說大不大，說小不小。",
  ui_story_1016_10161001_232_dialog_content = "這件事本來不算嚴重，但考慮到現在這個特殊的時間，加上吞羅有可能在迦南城內。",
  ui_story_1016_10161001_233_dialog_content = "我們必須要做好萬全的對策，不能放過任何一個漏洞。",
  ui_story_1016_10161001_234_dialog_content = "妳是說那個啟光的叛徒現在正在迦南城裡？",
  ui_story_1016_10161001_235_dialog_content = "（如果這是真的，那恐怕之前我遇到的那些暗鬼也是她的手下。）",
  ui_story_1016_10161001_236_dialog_content = "目前還沒有追查到她的行蹤，但很有可能。",
  ui_story_1016_10161001_237_dialog_content = "如果各位想要幫忙，請多加小心。",
  ui_story_1016_10161001_238_dialog_content = "阿納托利少校，幫他們劃分一片區域吧。",
  ui_story_1016_10161001_239_dialog_content = "好的。",
  ui_story_1016_10161001_240_dialog_content = "薇絲中尉，妳對迦南城比較熟悉，就麻煩妳帶隊吧。",
  ui_story_1016_10161001_241_dialog_content = "沒問題，交給我吧。",
  ui_story_1016_10161001_242_dialog_content = "請負責巡視迦南城車站附近的A區至C區，檢查設施的損壞情況。",
  ui_story_1016_10161001_243_dialog_content = "任務完成後，請向我或鶯歌中校進行報告。",
  ui_story_1016_10161001_244_dialog_content = "是！",
  ui_story_1016_10161101_1_dialog_content = "再過一陣子就要開始表演賽了，妳準備好了沒？",
  ui_story_1016_10161101_2_dialog_content = "當然，我準備得非常充分。",
  ui_story_1016_10161101_3_dialog_content = "妳那邊呢？有沒有查到什麼？",
  ui_story_1016_10161101_4_dialog_content = "沒有。",
  ui_story_1016_10161101_5_dialog_content = "吞羅可能躲進了迦南城的未開發區域裡，那種地方四通八達，想要徹底調查，還需要時間。",
  ui_story_1016_10161101_6_dialog_content = "辛苦了。",
  ui_story_1016_10161101_7_dialog_content = "這不算什麼。",
  ui_story_1016_10161101_8_dialog_content = "我本來打算親自帶隊調查，但是一想到這是聯合軍演的表演賽，又不能不出面。",
  ui_story_1016_10161101_9_dialog_content = "如果讓那些愛嚼舌根的傢伙們看見近衛軍團長不在，一定又要謠言滿天飛了。",
  ui_story_1016_10161101_10_dialog_content = "每次都是這群傢伙在礙事。",
  ui_story_1016_10161101_11_dialog_content = "不過沒關係，我已經在決賽場周邊設下重兵。",
  ui_story_1016_10161101_12_dialog_content = "就算我不在，吞羅也沒有辦法干擾這場比賽。",
  ui_story_1016_10161101_13_dialog_content = "嗯，有妳幫忙，聯合軍演一定能順利落幕。",
  ui_story_1016_10161101_14_dialog_content = "<color=#e8d9bb>與此同時，阿爾戈爾的實驗室內</color>",
  ui_story_1016_10161101_15_dialog_content = "好了，最後的調整也已經完成。",
  ui_story_1016_10161101_16_dialog_content = "但是最小的那個小機器人似乎飛得有點慢，可能是因為機械部件老化。",
  ui_story_1016_10161101_17_dialog_content = "反正它也沒什麼別的用途，就把它留在我這裡，讓我替它做個保養吧。",
  ui_story_1016_10161101_18_dialog_content = "沒有關係。",
  ui_story_1016_10161101_19_dialog_content = "阿克希亞，需要小機器人幫忙提袖子。",
  ui_story_1016_10161101_20_dialog_content = "如果小機器人不在，阿克希亞戰鬥時，會苦惱。",
  ui_story_1016_10161101_21_dialog_content = "是嗎？那還是聽妳的吧。",
  ui_story_1016_10161101_22_dialog_content = "等妳和萊因哈特打完，我再幫妳保養它也不遲。",
  ui_story_1016_10161101_23_dialog_content = "現在的三次方是最棒的狀態，盡情地利用它們戰鬥吧。",
  ui_story_1016_10161101_24_dialog_content = "阿爾戈爾是三次方的製造者，也是最擅長調整三次方的人。",
  ui_story_1016_10161101_25_dialog_content = "阿克希亞信任阿爾戈爾，就像阿克希亞信任三次方。",
  ui_story_1016_10161101_26_dialog_content = "哈哈哈哈，謝謝。能聽到妳這麼說，我很開心。",
  ui_story_1016_10161101_27_dialog_content = "妳多少也是我看著長大的，照顧妳理所當然。",
  ui_story_1016_10161101_28_dialog_content = "妳現在感覺如何？",
  ui_story_1016_10161101_29_dialog_content = "阿克希亞，狀態完美，隨時可以出戰。",
  ui_story_1016_10161101_30_dialog_content = "嗯，那就好。",
  ui_story_1016_10161101_31_dialog_content = "不過，可別因為狀態好就小看了萊因哈特的實力。",
  ui_story_1016_10161101_32_dialog_content = "就算只是舊式改造技術強化的光靈，萊因哈特仍舊是啟光數一數二的強者。",
  ui_story_1016_10161101_33_dialog_content = "而妳的體質妳自己也清楚，絕對不可以過度使用能力。",
  ui_story_1016_10161101_34_dialog_content = "阿克希亞，會戰鬥到最後一刻，取得勝利。",
  ui_story_1016_10161101_35_dialog_content = "興致倒是滿高，真拿妳沒辦法。",
  ui_story_1016_10161101_36_dialog_content = "可是千萬別勉強自己，不過就算我這樣說，妳也不一定會聽吧。",
  ui_story_1016_10161101_37_dialog_content = "阿克希亞，服從尤利西斯教授的命令。",
  ui_story_1016_10161101_38_dialog_content = "偶爾也要聽聽看別人的意見啊。",
  ui_story_1016_10161101_39_dialog_content = "不過時間快到了，我就不拖著妳了。",
  ui_story_1016_10161101_40_dialog_content = "到競技場去吧。",
  ui_story_1016_10161101_41_dialog_content = "阿克希亞，瞭解。",
  ui_story_1016_10161101_42_dialog_content = "祝妳旗開得勝。",
  ui_story_1016_10161101_43_dialog_content = "<color=#e8d9bb>決賽場</color>",
  ui_story_1016_10161101_44_dialog_content = "接下來我宣布，聯合軍演表演賽，現在開始！",
  ui_story_1016_10161101_45_dialog_content = "<size=45>哦！！！</size>",
  ui_story_1016_10161101_46_dialog_content = "首先，有請啟光聯邦的大元帥、未有敗績的啟明之光——萊因哈特！",
  ui_story_1016_10161101_47_dialog_content = "<size=45>大元帥——！大元帥——！</size>",
  ui_story_1016_10161101_48_dialog_content = "各位參與聯合軍演，辛苦你們了！",
  ui_story_1016_10161101_49_dialog_content = "我能看到，你們每個人都在這場軍演中發揮了自己的實力、獲得了屬於自己的進步。",
  ui_story_1016_10161101_50_dialog_content = "我由衷地為你們感到高興！",
  ui_story_1016_10161101_51_dialog_content = "<size=45>哦！！！</size>",
  ui_story_1016_10161101_52_dialog_content = "而最終通過所有考驗、取得最好的成績並獲得與萊因哈特大元帥一決高下的資格的人是——",
  ui_story_1016_10161101_53_dialog_content = "來自啟光聯邦的阿克希亞！",
  ui_story_1016_10161101_54_dialog_content = "阿克希亞——！",
  ui_story_1016_10161101_55_dialog_content = "……",
  ui_story_1016_10161101_56_dialog_content = "阿克希亞……之前從來沒聽過這個名字，沒想到竟然這麼強！",
  ui_story_1016_10161101_57_dialog_content = "是啊，就連我們啟光人都嚇了一跳呢。",
  ui_story_1016_10161101_58_dialog_content = "沒想到啟光竟然有連我們都不知道的強者。",
  ui_story_1016_10161101_59_dialog_content = "接下來，請雙方握手。",
  ui_story_1016_10161101_60_dialog_content = "阿克希亞……",
  ui_story_1016_10161101_61_dialog_content = "我知道妳。妳有著很強的實力，令人敬佩。",
  ui_story_1016_10161101_62_dialog_content = "阿克希亞，感謝妳的肯定。",
  ui_story_1016_10161101_63_dialog_content = "怎麼樣，休息得如何了？昨天才結束聯合軍演，今天就要進行表演賽，體力還吃得消嗎？",
  ui_story_1016_10161101_64_dialog_content = "我可不會因為妳沒休息好，就對妳手下留情。",
  ui_story_1016_10161101_65_dialog_content = "沒關係，因為……",
  ui_story_1016_10161101_66_dialog_content = "阿克希亞就是為了這一刻，才站在這裡的。",
  ui_story_1016_10161101_67_dialog_content = "……！",
  ui_story_1016_10161101_68_dialog_content = "與妳戰鬥，是阿克希亞的使命。",
  ui_story_1016_10161101_69_dialog_content = "阿克希亞會使用一切可能的方法擊敗妳。",
  ui_story_1016_10161101_70_dialog_content = "哦？那我期待妳英勇的表現。",
  ui_story_1016_10161101_71_dialog_content = "能與強大的後輩切磋，也是值得高興的事情。",
  ui_story_1016_10161101_72_dialog_content = "……",
  ui_story_1016_10161101_73_dialog_content = "（這孩子究竟是怎麼回事？）",
  ui_story_1016_10161101_74_dialog_content = "（她的表情，給我一種奇怪的感覺，根本就不像是士兵或軍人，而是……）",
  ui_story_1016_10161101_75_dialog_content = "（像是即將赴死的人。）",
  ui_story_1016_10161101_76_dialog_content = "（在她眼裡我就這麼恐怖嗎？）",
  ui_story_1016_10161101_77_dialog_content = "（還是說……）",
  ui_story_1016_10161101_78_dialog_content = "那麼，請雙方各就各位，表演賽即將開始！",
  ui_story_1016_10161101_79_dialog_content = "……",
  ui_story_1016_10161101_80_dialog_content = "預備——",
  ui_story_1016_10161101_81_dialog_content = "<size=50><color=#FFB400>開始</color>！</size>",
  ui_story_1016_10161101_82_dialog_content = "——！",
  ui_story_1016_10161101_83_dialog_content = "三次方！",
  ui_story_1016_10161101_84_dialog_content = "<size=45>！！！</size>",
  ui_story_1016_10161101_85_dialog_content = "好強的力量！",
  ui_story_1016_10161101_86_dialog_content = "看來我也要全力以赴才行了。",
  ui_story_1016_10161101_87_dialog_content = "<color=#e8d9bb>轟！！！</color>",
  ui_story_1016_10161101_88_dialog_content = "<size=45>漂亮！！！</size>",
  ui_story_1016_10161101_89_dialog_content = "大元帥——大元帥——！",
  ui_story_1016_10161101_90_dialog_content = "初次攻擊，命中。攻擊效果：未對敵方造成傷害。",
  ui_story_1016_10161101_91_dialog_content = "敵方的戰鬥力比預期稍高，但仍在能夠應對的範圍內。",
  ui_story_1016_10161101_92_dialog_content = "阿克希亞，將會提高輸出。",
  ui_story_1016_10161101_93_dialog_content = "三——",
  ui_story_1016_10161101_94_dialog_content = "（她這是在聚集力量？！）",
  ui_story_1016_10161101_95_dialog_content = "（得打斷她的行動！）",
  ui_story_1016_10161101_96_dialog_content = "二——",
  ui_story_1016_10161101_97_dialog_content = "<size=45>刺穿一切！</size>",
  ui_story_1016_10161101_98_dialog_content = "——！",
  ui_story_1016_10161101_99_dialog_content = "礙事！",
  ui_story_1016_10161101_100_dialog_content = "一！",
  ui_story_1016_10161101_101_dialog_content = "（來不及了嗎？）",
  ui_story_1016_10161101_103_dialog_content = "走吧，我的愛槍！",
  ui_story_1016_10161101_104_dialog_content = "久等了。",
  ui_story_1016_10161101_105_dialog_content = "<color=#e8d9bb>轟——！！！</color>",
  ui_story_1016_10161101_106_dialog_content = "<size=45>太精彩了！！！</size>",
  ui_story_1016_10161101_107_dialog_content = "咳……咳咳！",
  ui_story_1016_10161101_108_dialog_content = "呃……沒想到，還真的滿痛的。",
  ui_story_1016_10161101_109_dialog_content = "妳真是個不得了的小傢伙。",
  ui_story_1016_10161101_110_dialog_content = "第二次攻擊，命中。",
  ui_story_1016_10161101_111_dialog_content = "大部分光能被敵方光能術抵消，攻擊效果：差。",
  ui_story_1016_10161101_112_dialog_content = "阿克希亞，繼續提高輸出。",
  ui_story_1016_10161101_113_dialog_content = "（還能繼續提升輸出？！）",
  ui_story_1016_10161101_114_dialog_content = "（這麼龐大的光能甚至超過了我的極限，如果正面撞上，肯定沒有好結果……）",
  ui_story_1016_10161101_115_dialog_content = "三——",
  ui_story_1016_10161101_116_dialog_content = "<color=#e8d9bb>喀嚓——</color>",
  ui_story_1016_10161101_117_dialog_content = "<size=45>！</size>",
  ui_story_1016_10161101_118_dialog_content = "（等等，那孩子身上出現了<color=#FFB400>裂痕</color>？）",
  ui_story_1016_10161101_119_dialog_content = "（她的身體開始崩潰了？！難道說是過度使用那種恐怖的力量導致的？）",
  ui_story_1016_10161101_120_dialog_content = "（委員會那些傢伙，竟然製造出這樣一門玻璃大炮……）",
  ui_story_1016_10161101_121_dialog_content = "阿克希亞，快停下！",
  ui_story_1016_10161101_122_dialog_content = "這樣下去妳的身體會承受不住的！！！",
  ui_story_1016_10161101_123_dialog_content = "呃……",
  ui_story_1016_10161101_124_dialog_content = "二……",
  ui_story_1016_10161101_125_dialog_content = "不聽人說話嗎？沒辦法了……",
  ui_story_1016_10161101_126_dialog_content = "裁判，我要求現在停止比賽！",
  ui_story_1016_10161101_127_dialog_content = "再比下去，阿克希亞會有危險！",
  ui_story_1016_10161101_128_dialog_content = "你們的大元帥，剛才是說了什麼嗎？",
  ui_story_1016_10161101_129_dialog_content = "不知道呀，我什麼都沒聽見……",
  ui_story_1016_10161101_130_dialog_content = "肅靜！比賽繼續。",
  ui_story_1016_10161101_131_dialog_content = "（裁判和觀眾都聽不到我說話？這是……）",
  ui_story_1016_10161101_132_dialog_content = "（賽場和觀眾席之間竟然有一層微弱的<color=#FFB400>暗能阻隔</color>，是什麼時候出現的？！）",
  ui_story_1016_10161101_133_dialog_content = "（難道就是它阻隔了我的聲音？看起來得先突破它！）",
  ui_story_1016_10161101_134_dialog_content = "<size=45>！！！</size>",
  ui_story_1016_10161101_135_dialog_content = "（行動路線被限制了？！）",
  ui_story_1016_10161101_136_dialog_content = "目標……鎖定……",
  ui_story_1016_10161101_137_dialog_content = "一！",
  ui_story_1016_10161101_138_dialog_content = "<size=45>久等了！</size>",
  ui_story_1016_10161101_139_dialog_content = "……！",
  ui_story_1016_10161101_140_dialog_content = "<color=#e8d9bb>轟——！！！</color>",
  ui_story_1016_10161101_141_dialog_content = "<color=#e8d9bb>與此同時，迦南城內</color>",
  ui_story_1016_10161101_142_dialog_content = "車站內部已經檢查完了，沒有問題。",
  ui_story_1016_10161101_143_dialog_content = "周圍也沒有問題。",
  ui_story_1016_10161101_144_dialog_content = "我這邊也是。",
  ui_story_1016_10161101_145_dialog_content = "PlayerName！我這邊發現了情況！",
  ui_story_1016_10161101_146_dialog_content = "隧道檢修通道裡的所有防禦設施都被破壞了，裡面好像有暗鬼活動的痕跡！",
  ui_story_1016_10161101_147_dialog_content = "快過去看看！",
  ui_story_1016_10161101_148_dialog_content = "<anim type=Shake><size=50>吼——！</size></anim>",
  ui_story_1016_10161101_149_dialog_content = "檢修通道裡果然有暗鬼！",
  ui_story_1016_10161101_150_dialog_content = "不能讓牠們為所欲為！",
  ui_story_1016_10161102_1_dialog_content = "他們，應該已經進入迦南城了。",
  ui_story_1016_10161102_2_dialog_content = "但是時機還沒到，還不能離開。",
  ui_story_1016_10161102_3_dialog_content = "為什麼，我們要躲……",
  ui_story_1016_10161102_4_dialog_content = "為什麼，妳……不相信……",
  ui_story_1016_10161102_5_dialog_content = "相信？",
  ui_story_1016_10161102_6_dialog_content = "如果我說，這座迦南城裡現在已經布滿了暗鬼的眼線呢？",
  ui_story_1016_10161102_7_dialog_content = "如果就連掌控著這座城市的人，都已經選擇與暗鬼合作呢？",
  ui_story_1016_10161102_8_dialog_content = "如果是這樣，你還會相信他們嗎？",
  ui_story_1016_10161102_9_dialog_content = "……",
  ui_story_1016_10161102_10_dialog_content = "你現在能相信的，只有我。",
  ui_story_1016_10161102_11_dialog_content = "只有我能救你，帶你離開這裡。",
  ui_story_1016_10161102_12_dialog_content = "……",
  ui_story_1016_10161102_13_dialog_content = "（日蝕語）吞羅大人。",
  ui_story_1016_10161102_14_dialog_content = "（日蝕語）說。",
  ui_story_1016_10161102_15_dialog_content = "（日蝕語）斐桀洛大人命我帶來新的消息。",
  ui_story_1016_10161102_16_dialog_content = "（日蝕語）所有的布置已經完成，您可以撤退了。",
  ui_story_1016_10161102_17_dialog_content = "（日蝕語）時機終於到了。你們的動作真慢。",
  ui_story_1016_10161102_18_dialog_content = "（日蝕語）十分抱歉。",
  ui_story_1016_10161102_19_dialog_content = "（日蝕語）我們已經發現了一處祕密疏散通道。",
  ui_story_1016_10161102_20_dialog_content = "（日蝕語）您可以利用那條通道離開迦南城。",
  ui_story_1016_10161102_21_dialog_content = "（日蝕語）位置。",
  ui_story_1016_10161102_22_dialog_content = "（日蝕語）就在這裡。",
  ui_story_1016_10161102_23_dialog_content = "這裡是……還真是個偏僻的地方。",
  ui_story_1016_10161102_24_dialog_content = "實驗體，我們該走了。",
  ui_story_1016_10161201_1_dialog_content = "<color=#e8d9bb>轟隆——！！！</color>",
  ui_story_1016_10161201_2_dialog_content = "<size=45>咳咳咳！！！</size>",
  ui_story_1016_10161201_3_dialog_content = "呃……",
  ui_story_1016_10161201_4_dialog_content = "第三次攻擊……咳咳……命中。",
  ui_story_1016_10161201_5_dialog_content = "攻擊……取得了較為顯著的效果。",
  ui_story_1016_10161201_6_dialog_content = "決定，繼續進攻。",
  ui_story_1016_10161201_7_dialog_content = "（但是阿克希亞，光能不足……）",
  ui_story_1016_10161201_8_dialog_content = "（需要一些時間積蓄力量，才能繼續進攻。）",
  ui_story_1016_10161201_9_dialog_content = "（再這樣下去，她會死。）",
  ui_story_1016_10161201_10_dialog_content = "（究竟是什麼讓她不惜拼上性命，也要打敗我？）",
  ui_story_1016_10161201_11_dialog_content = "（難道說，這是尤利西斯，是委員會向她下的命令？）",
  ui_story_1016_10161201_12_dialog_content = "三次方！",
  ui_story_1016_10161201_13_dialog_content = "——！",
  ui_story_1016_10161201_14_dialog_content = "（她的攻擊方式改變了，光能也比剛才弱了一些。）",
  ui_story_1016_10161201_15_dialog_content = "（看樣子她是在積蓄力量、為下一次進攻做準備。）",
  ui_story_1016_10161201_16_dialog_content = "（這或許是個機會。）",
  ui_story_1016_10161201_17_dialog_content = "阿克希亞，妳為什麼這麼執著於打敗我？",
  ui_story_1016_10161201_18_dialog_content = "阿克希亞能做到，所以阿克希亞必須勝利。",
  ui_story_1016_10161201_19_dialog_content = "妳這根本就不是在回答我的問題。",
  ui_story_1016_10161201_20_dialog_content = "是尤利西斯向妳下的命令嗎？",
  ui_story_1016_10161201_21_dialog_content = "……",
  ui_story_1016_10161201_22_dialog_content = "（沒有否認，看來應該是委員會的命令沒錯了。）",
  ui_story_1016_10161201_23_dialog_content = "（他們就這麼急著想要打擊我、爭奪更多話語權嗎？）",
  ui_story_1016_10161201_24_dialog_content = "（如果這真是他們的命令，以這孩子的性格，哪怕失去生命也必然會去執行。）",
  ui_story_1016_10161201_25_dialog_content = "（但是現在，不能再給委員會更多話語權了。）",
  ui_story_1016_10161201_26_dialog_content = "（想要救這孩子，只能先試著控制住她，強迫她認輸。）",
  ui_story_1016_10161201_27_dialog_content = "還沒有結束——",
  ui_story_1016_10161201_28_dialog_content = "<size=45>破綻在這裡！</size>",
  ui_story_1016_10161201_29_dialog_content = "<color=#e8d9bb>鏘——！</color>",
  ui_story_1016_10161201_30_dialog_content = "妳輸了。",
  ui_story_1016_10161201_31_dialog_content = "<size=50>哦——！！！</size>",
  ui_story_1016_10161201_32_dialog_content = "大元帥控制住了對手。",
  ui_story_1016_10161201_33_dialog_content = "這次也是她獲得了勝利嗎？",
  ui_story_1016_10161201_34_dialog_content = "……",
  ui_story_1016_10161201_35_dialog_content = "認輸吧。",
  ui_story_1016_10161201_36_dialog_content = "我明白妳的堅持，但我們都有各自不能輸的理由。",
  ui_story_1016_10161201_37_dialog_content = "我不想傷害妳，也不想看妳這樣傷害自己。",
  ui_story_1016_10161201_38_dialog_content = "妳比我更年輕，也更優秀，是啟光聯邦未來的希望。",
  ui_story_1016_10161201_39_dialog_content = "不要在這裡就放棄前進的可能。",
  ui_story_1016_10161201_40_dialog_content = "<anim type=Shake>阿克希亞……</anim>",
  ui_story_1016_10161201_41_dialog_content = "<anim type=Shake><size=45>阿克希亞……還沒有輸！</size></anim>",
  ui_story_1016_10161201_42_dialog_content = "？！",
  ui_story_1016_10161201_43_dialog_content = "三次方！",
  ui_story_1016_10161201_44_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_1016_10161201_45_dialog_content = "呃……咳咳！！！",
  ui_story_1016_10161201_46_dialog_content = "（那個看上去一點攻擊力都沒有的小機器人竟然爆炸了？！）",
  ui_story_1016_10161201_47_dialog_content = "（竟然用那種危險的手段逼迫我離開，那孩子恐怕比我傷得更重……）",
  ui_story_1016_10161201_48_dialog_content = "<anim type=Shake>痛……</anim>",
  ui_story_1016_10161201_49_dialog_content = "<anim type=Shake>但是，還能，戰鬥……</anim>",
  ui_story_1016_10161201_50_dialog_content = "<anim type=Shake>阿克希亞，不會認輸……</anim>",
  ui_story_1016_10161201_51_dialog_content = "（她已經下定決心了嗎，那麼這場比賽只剩下有兩種結果……）",
  ui_story_1016_10161201_52_dialog_content = "（不是我獲得勝利，她失去生命。）",
  ui_story_1016_10161201_53_dialog_content = "（就是我在她燃盡自己前認輸，雖然正中委員會的下懷，但是至少她能活下去……）",
  ui_story_1016_10161201_54_dialog_content = "<anim type=Shake>阿克希亞，會，完成任務……打敗，妳……</anim>",
  ui_story_1016_10161201_55_dialog_content = "<color=#e8d9bb>喀嚓——</color>",
  ui_story_1016_10161201_56_dialog_content = "<anim type=Shake>阿克希亞……還能繼續……</anim>",
  ui_story_1016_10161201_57_dialog_content = "……",
  ui_story_1016_10161201_58_dialog_content = "怎麼回事？為什麼萊因哈特不還手？",
  ui_story_1016_10161201_59_dialog_content = "大元帥！快反擊！",
  ui_story_1016_10161201_60_dialog_content = "是啊，大元帥究竟怎麼了？",
  ui_story_1016_10161201_61_dialog_content = "看來，時機已經到了。",
  ui_story_1016_10161201_62_dialog_content = "<color=#e8d9bb>嘶啦——</color>",
  ui_story_1016_10161201_63_dialog_content = "開始下一步行動吧。",
  ui_story_1016_10161201_64_dialog_content = "你有絕對的把握？",
  ui_story_1016_10161201_65_dialog_content = "是的。",
  ui_story_1016_10161201_66_dialog_content = "她已經沒辦法取得勝利了。",
  ui_story_1016_10161201_67_dialog_content = "<color=#e8d9bb>與此同時，迦南城深處</color>",
  ui_story_1016_10161201_68_dialog_content = "呼……呼……",
  ui_story_1016_10161201_69_dialog_content = "暗鬼……跑到哪裡去了？！",
  ui_story_1016_10161201_70_dialog_content = "這群暗鬼竟然看到我們就跑，跑得還滿快。",
  ui_story_1016_10161201_71_dialog_content = "我們這是到哪裡了？",
  ui_story_1016_10161201_72_dialog_content = "我從來沒來過這裡，薇絲，妳知道這是哪裡嗎？",
  ui_story_1016_10161201_73_dialog_content = "我也不清楚……",
  ui_story_1016_10161201_74_dialog_content = "我只能勉強感覺到，我們的位置已經接近迦南城的底層了。",
  ui_story_1016_10161201_75_dialog_content = "薇絲中尉？PlayerName，你們怎麼在這裡？",
  ui_story_1016_10161201_76_dialog_content = "嗯？",
  ui_story_1016_10161201_77_dialog_content = "你們不是去檢查車站了嗎？",
  ui_story_1016_10161201_78_dialog_content = "鶯歌中校？！",
  ui_story_1016_10161201_79_dialog_content = "沒想到在這裡碰到了。",
  ui_story_1016_10161201_80_dialog_content = "我們在檢查車站的時候，在隧道的檢修通道裡發現了暗鬼。",
  ui_story_1016_10161201_81_dialog_content = "是啊，那些暗鬼一看到我們，掉頭就跑。我們追著追著，就到這裡來了。",
  ui_story_1016_10161201_82_dialog_content = "你們呢？不是在巡查城內嗎？",
  ui_story_1016_10161201_83_dialog_content = "怎麼也跑到這裡來了？",
  ui_story_1016_10161201_84_dialog_content = "我們也遇到了和你們相似的情況。",
  ui_story_1016_10161201_85_dialog_content = "那些暗鬼非常奇怪，牠們並不戀戰……",
  ui_story_1016_10161201_86_dialog_content = "這可能是牠們的陰謀，我們得提高警惕。",
  ui_story_1016_10161201_87_dialog_content = "我也認為裡面可能有陰謀。",
  ui_story_1016_10161201_88_dialog_content = "怎麼樣，要放棄追蹤，不管牠們嗎？",
  ui_story_1016_10161201_89_dialog_content = "那可不行！",
  ui_story_1016_10161201_90_dialog_content = "要是放任牠們在迦南城裡橫行，會造成更大的風險。",
  ui_story_1016_10161201_91_dialog_content = "這裡是迦南城深處，有大量珍貴的科技設施，任何一台被暗鬼破壞了都是啟光嚴重的損失。",
  ui_story_1016_10161201_92_dialog_content = "我們得追上去，把牠們的詭計消滅在計畫階段！",
  ui_story_1016_10161201_93_dialog_content = "PlayerName，你能用感應能力感應到暗鬼往哪裡跑嗎？",
  ui_story_1016_10161201_94_dialog_content = "我試試看吧，這裡地形太複雜，感應能力只能感應出大致方向。",
  ui_story_1016_10161201_95_dialog_content = "但要怎麼到那裡，我就不清楚了。",
  ui_story_1016_10161201_96_dialog_content = "沒關係，路線規劃交給我，你只要告訴我方位就好。",
  ui_story_1016_10161201_97_dialog_content = "嗯，那我試試。",
  ui_story_1016_10161201_98_option_content = "強制感應！",
  ui_story_1016_10161201_99_dialog_content = "暗能聚集的方向，在下面……",
  ui_story_1016_10161201_100_dialog_content = "這是……",
  ui_story_1016_10161201_101_dialog_content = "<size=45>！！！</size>",
  ui_story_1016_10161201_102_dialog_content = "是<color=#FFB400>斐桀洛</color>！！！！",
  ui_story_1016_10161201_103_dialog_content = "你是說那個<color=#FFB400>罪靈</color>？！他在哪裡？",
  ui_story_1016_10161201_104_dialog_content = "正下方，很近的地方！",
  ui_story_1016_10161201_105_dialog_content = "正下方嗎……",
  ui_story_1016_10161201_106_dialog_content = "（這裡已經接近迦南城的最深處，再往下一點的位置，就是<color=#FFB400>守護者一號</color>主機所在的位置。）",
  ui_story_1016_10161201_107_dialog_content = "（難道日蝕想對守護者一號下手？！）",
  ui_story_1016_10161201_108_dialog_content = "我們必須趕快追過去，跟我走！",
  ui_story_1016_10161201_109_dialog_content = "當初修建這座地下城的人，腦子裡一定是一團漿糊。",
  ui_story_1016_10161201_110_dialog_content = "不然怎麼會把走廊修得這麼複雜！",
  ui_story_1016_10161201_111_dialog_content = "前面的罪靈，站住！",
  ui_story_1016_10161201_112_dialog_content = "你已經逃不掉了，最好現在就投降。",
  ui_story_1016_10161201_113_dialog_content = "什麼？怎麼可能？！",
  ui_story_1016_10161201_114_dialog_content = "那傢伙不是已經把礙事的光靈都……",
  ui_story_1016_10161201_114X1_dialog_content = "嗯？<color=#FFB400>她</color>人呢？已經先去<color=#FFB400>那個地方</color>了嗎？",
  ui_story_1016_10161201_115_dialog_content = "可惡！每個人都來妨礙我！",
  ui_story_1016_10161201_116_dialog_content = "你們，給我攔住他們！",
  ui_story_1016_10161201_117_dialog_content = "<anim type=Shake><size=45>吼！！！</size></anim>",
  ui_story_1016_10161201_118_dialog_content = "站住！！！",
  ui_story_1016_10161301_1_dialog_content = "我一直都在思考一個問題——",
  ui_story_1016_10161301_2_dialog_content = "對於啟光聯邦來說，什麼是最重要的？",
  ui_story_1016_10161301_3_dialog_content = "是強大先進的軍備？",
  ui_story_1016_10161301_4_dialog_content = "是訓練有素的士兵？",
  ui_story_1016_10161301_5_dialog_content = "還是最為頂尖的技術？",
  ui_story_1016_10161301_6_dialog_content = "我思考了很久，都沒有得到答案。",
  ui_story_1016_10161301_7_dialog_content = "直到我走上戰場。",
  ui_story_1016_10161301_8_dialog_content = "在那裡，我看到了……",
  ui_story_1016_10161301_9_dialog_content = "堅持。",
  ui_story_1016_10161301_10_dialog_content = "責任。",
  ui_story_1016_10161301_11_dialog_content = "犧牲。",
  ui_story_1016_10161301_12_dialog_content = "那時候，我終於明白了，對於啟光聯邦來說，最重要的東西——",
  ui_story_1016_10161301_13_dialog_content = "是<color=#FFB400>人</color>。",
  ui_story_1016_10161301_14_dialog_content = "地面上的啟光沒有防禦暗鬼的天然屏障或遠古科技。",
  ui_story_1016_10161301_15_dialog_content = "是一代代的啟光人，用自己熾熱的心與血鑄就了一座座地下城。",
  ui_story_1016_10161301_16_dialog_content = "當老一輩的人離去時，就會有年輕一輩的人補上，一代一代，一直如此。",
  ui_story_1016_10161301_17_dialog_content = "明明每個人的生命都是這樣珍貴，但為了能讓自己的同胞、後代過上更好的生活——",
  ui_story_1016_10161301_18_dialog_content = "他們義無反顧。",
  ui_story_1016_10161301_19_dialog_content = "沒有一條生命應該被犧牲在內部鬥爭這種無意義的事情上。",
  ui_story_1016_10161301_20_dialog_content = "這種事情，不盡快想辦法制止，以後一定還會重演。",
  ui_story_1016_10161301_21_dialog_content = "就算現在打敗了阿克希亞，那些人一定還會再派更多像阿克希亞這樣的人來……",
  ui_story_1016_10161301_22_dialog_content = "現在他們千方百計地讓我輸給阿克希亞，恐怕也不過是想要我交出大元帥這個頭銜。",
  ui_story_1016_10161301_23_dialog_content = "大元帥的位置雖然重要，但並不是非要不可，更不值得為了守住它而讓同胞失去性命。",
  ui_story_1016_10161301_24_dialog_content = "至少現在，我要先救下這孩子。",
  ui_story_1016_10161301_25_dialog_content = "所以……",
  ui_story_1016_10161301_26_dialog_content = "<size=45>停——！</size>",
  ui_story_1016_10161301_27_dialog_content = "<anim type=Shake>阿克希亞，不會停下……</anim>",
  ui_story_1016_10161301_28_dialog_content = "<color=#e8d9bb>匡啷——</color>",
  ui_story_1016_10161301_29_dialog_content = "停下吧，<color=#FFB400>我認輸</color>。",
  ui_story_1016_10161301_30_dialog_content = "如果妳身後的那些人這麼想要這場勝利的話，那讓他們拿去就是了。",
  ui_story_1016_10161301_31_dialog_content = "但是妳，我希望妳能好好活下去。",
  ui_story_1016_10161301_32_dialog_content = "不是作為一門玻璃大炮或一個好用的工具，而是作為一個<color=#FFB400>人</color>。",
  ui_story_1016_10161301_33_dialog_content = "……！",
  ui_story_1016_10161301_34_dialog_content = "她剛才是不是說了什麼？",
  ui_story_1016_10161301_35_dialog_content = "不知道，完全聽不清。",
  ui_story_1016_10161301_36_dialog_content = "為什麼大元帥要扔掉武器？難道是要使用什麼特殊的招式嗎？",
  ui_story_1016_10161301_37_dialog_content = "裁判，你聽得見吧。",
  ui_story_1016_10161301_38_dialog_content = "大元帥，妳……妳說什麼？",
  ui_story_1016_10161301_39_dialog_content = "現在終於能聽見了嗎？呵呵，還真是巧。",
  ui_story_1016_10161301_40_dialog_content = "我說，這場比賽，是我輸了。",
  ui_story_1016_10161301_41_dialog_content = "……",
  ui_story_1016_10161301_42_dialog_content = "可是，這……",
  ui_story_1016_10161301_43_dialog_content = "不要猶豫了，宣布結果吧。",
  ui_story_1016_10161301_44_dialog_content = "別讓那孩子等太久。",
  ui_story_1016_10161301_45_dialog_content = "是……那麼，我宣布，比賽結束！",
  ui_story_1016_10161301_46_dialog_content = "萊因哈特大元帥主動放棄了比賽，因此獲勝者是——<color=#FFB400>阿克希亞</color>！",
  ui_story_1016_10161301_47_dialog_content = "<color=#e8d9bb>與此同時，迦南城深處</color>",
  ui_story_1016_10161301_48_dialog_content = "終於到這裡了，但是那群麻煩的傢伙也跟過來了。",
  ui_story_1016_10161301_48X1_dialog_content = "她已經進去了嗎？那麼按照計畫……",
  ui_story_1016_10161301_49_dialog_content = "別想跑！",
  ui_story_1016_10161301_50_dialog_content = "<color=#e8d9bb>砰！砰砰！</color>",
  ui_story_1016_10161301_51_dialog_content = "該死的小丫頭，追得真緊！",
  ui_story_1016_10161301_52_dialog_content = "竟然跑到這裡來了……",
  ui_story_1016_10161301_53_dialog_content = "呼，呼……終於追上了。",
  ui_story_1016_10161301_53X1_dialog_content = "空裔，又見面了。",
  ui_story_1016_10161301_53X2_dialog_content = "上次回歸塔的事情可真是拜你所賜……老子這段時間心情很差啊。",
  ui_story_1016_10161301_53X3_dialog_content = "你又要做什麼？！",
  ui_story_1016_10161301_53X4_dialog_content = "這次我絕對不會再讓你逃走了！",
  ui_story_1016_10161301_53X5_dialog_content = "這裡是死路！你已經沒有退路了！",
  ui_story_1016_10161301_53X6_dialog_content = "桀桀桀，別那麼激動。",
  ui_story_1016_10161301_54_dialog_content = "如果沒猜錯的話，這裡應該就是迦南城的最底層了吧？",
  ui_story_1016_10161301_55_dialog_content = "這座大門可真結實，裡面的東西一定很重要。",
  ui_story_1016_10161301_56_dialog_content = "這裡面是守護者一號的主機，絕對不能讓日蝕的傢伙們碰到它！",
  ui_story_1016_10161301_57_dialog_content = "守護者一號？！它不是還沒我高的嗎？",
  ui_story_1016_10161301_58_dialog_content = "那個履帶機器人只是守護者一號的終端。",
  ui_story_1016_10161301_59_dialog_content = "而這裡面，才是它的真身。",
  ui_story_1016_10161301_60_dialog_content = "聽說迦南城，甚至整個啟光大部分的防禦設施都是由守護者一號進行自動控制的。",
  ui_story_1016_10161301_61_dialog_content = "一旦守護者一號出了問題，啟光聯邦就危險了！",
  ui_story_1016_10161301_62_dialog_content = "<size=45>桀桀桀桀桀桀！！！</size>",
  ui_story_1016_10161301_63_dialog_content = "你說的沒錯，白毛小子。",
  ui_story_1016_10161301_64_dialog_content = "但是已經晚了，我們的人已經進去了。",
  ui_story_1016_10161301_65_dialog_content = "什麼？！",
  ui_story_1016_10161301_66_dialog_content = "怎麼做到的？沒有祕鑰的話——",
  ui_story_1016_10161301_67_dialog_content = "這你就自己去猜吧。",
  ui_story_1016_10161301_68_dialog_content = "再一下下，再一下下我就能不被日蝕……",
  ui_story_1016_10161301_69_dialog_content = "你們上，給我拖住他們！",
  ui_story_1016_10161301_70_dialog_content = "吼！！！",
  ui_story_1016_10161301_71_dialog_content = "大家一起上，別讓他得逞！",
  ui_story_1016_10161302_1_dialog_content = "<color=#e8d9bb>迦南城居住區，某處</color>",
  ui_story_1016_10161302_2_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_1016_10161302_3_dialog_content = "原來不是什麼祕密實驗室，而只是普通的民宅。",
  ui_story_1016_10161302_4_dialog_content = "這種偏僻的角落裡，也藏著前往外界的通道嗎？",
  ui_story_1016_10161302_5_dialog_content = "妳……要離開。",
  ui_story_1016_10161302_6_dialog_content = "為什麼？",
  ui_story_1016_10161302_7_dialog_content = "這裡已經沒有退路了。",
  ui_story_1016_10161302_8_dialog_content = "啟光已經放棄了你，也放棄了我，再留下去已經沒有意義了。",
  ui_story_1016_10161302_9_dialog_content = "是啊，委員會，放棄了我們……",
  ui_story_1016_10161302_10_dialog_content = "我……已經想起來了……",
  ui_story_1016_10161302_11_dialog_content = "你想起了什麼？",
  ui_story_1016_10161302_12_dialog_content = "……",
  ui_story_1016_10161302_13_dialog_content = "一切。",
  ui_story_1016_10161302_14_dialog_content = "過去的記憶，那場戰鬥，還有……沒有盡頭的等待。",
  ui_story_1016_10161302_15_dialog_content = "以及絕望。",
  ui_story_1016_10161302_16_dialog_content = "那你也應該知道自己現在的處境了。",
  ui_story_1016_10161302_17_dialog_content = "曾經屬於你的一切已經不復存在了。",
  ui_story_1016_10161302_18_dialog_content = "你不再是啟光的軍人，而是一個逃犯、一個怪物。",
  ui_story_1016_10161302_19_dialog_content = "想活下去的話，就來幫忙找通道。",
  ui_story_1016_10161302_20_dialog_content = "不用那麼麻煩了。",
  ui_story_1016_10161302_21_dialog_content = "這裡根本就沒有出口。",
  ui_story_1016_10161302_22_dialog_content = "……",
  ui_story_1016_10161302_23_dialog_content = "哼，原來你們是這麼盤算的。",
  ui_story_1016_10161302_24_dialog_content = "倒也不意外。",
  ui_story_1016_10161302_25_dialog_content = "投降吧，把妳的實驗成果都交出來。",
  ui_story_1016_10161302_26_dialog_content = "如果妳配合，我可以讓妳死得不那麼難看。",
  ui_story_1016_10161302_27_dialog_content = "別擋路。",
  ui_story_1016_10161302_28_dialog_content = "看起來妳是不願意配合了。",
  ui_story_1016_10161302_29_dialog_content = "那就別怪我不客氣，上。",
  ui_story_1016_10161302_30_dialog_content = "你們……要幹什麼？！",
  ui_story_1016_10161302_31_dialog_content = "抓住他們。",
  ui_story_1016_10161302_32_dialog_content = "是！",
  ui_story_1016_10161302_33_dialog_content = "不自量力。",
  ui_story_1016_10161302_34_dialog_content = "<size=45>防禦！</size>",
  ui_story_1016_10161302_35_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_1016_10161302_36_dialog_content = "……",
  ui_story_1016_10161302_37_dialog_content = "別白費力氣了。",
  ui_story_1016_10161302_38_dialog_content = "為了對付妳，這裡的士兵都裝備了科學首席議會研製的實驗型防禦裝備。",
  ui_story_1016_10161302_39_dialog_content = "在它們失效前，我們會先抓住妳。",
  ui_story_1016_10161302_40_dialog_content = "看來你們終於學聰明點了。",
  ui_story_1016_10161302_41_dialog_content = "但是，仍然是一群蠢貨。",
  ui_story_1016_10161302_42_dialog_content = "<color=#e8d9bb>與此同時，決賽場</color>",
  ui_story_1016_10161302_43_dialog_content = "阿克希亞……贏了？",
  ui_story_1016_10161302_44_dialog_content = "沒錯，妳已經贏了。",
  ui_story_1016_10161302_45_dialog_content = "停下吧，不要再傷害自己了。",
  ui_story_1016_10161302_46_dialog_content = "……",
  ui_story_1016_10161302_47_dialog_content = "什麼？我沒聽錯吧？",
  ui_story_1016_10161302_48_dialog_content = "那個傳說中的萊因哈特竟然輸了？",
  ui_story_1016_10161302_49_dialog_content = "這怎麼可能？",
  ui_story_1016_10161302_50_dialog_content = "怎麼會這樣……",
  ui_story_1016_10161302_51_dialog_content = "<size=45>你們究竟在搞什麼東西？！</size>",
  ui_story_1016_10161302_52_dialog_content = "萊因哈特認輸？她都沒認真打！",
  ui_story_1016_10161302_53_dialog_content = "你們這群老東西究竟用了什麼下三濫的手段？！",
  ui_story_1016_10161302_54_dialog_content = "巴頓軍團長，請注意您的言辭，這是正規的比賽！",
  ui_story_1016_10161302_55_dialog_content = "冷靜點，巴頓。",
  ui_story_1016_10161302_56_dialog_content = "現在不是氣昏頭的時候。",
  ui_story_1016_10161302_57_dialog_content = "如果萊因哈特這麼決定，那她一定有自己的理由。",
  ui_story_1016_10161302_58_dialog_content = "我相信她的選擇，所以等一下向她問清楚就好了。",
  ui_story_1016_10161302_59_dialog_content = "<size=45>有沒有搞錯？！</size>",
  ui_story_1016_10161302_60_dialog_content = "<size=45>就這麼結束了？這算什麼啊？！</size>",
  ui_story_1016_10161302_61_dialog_content = "安靜，都安靜！",
  ui_story_1016_10161302_62_dialog_content = "請尊重比賽結果！",
  ui_story_1016_10161302_63_dialog_content = "還真是熱鬧。",
  ui_story_1016_10161302_64_dialog_content = "時間應該差不多了。",
  ui_story_1016_10161302_65_dialog_content = "報告！尤利西斯長官，有您的消息！",
  ui_story_1016_10161302_66_dialog_content = "說吧。",
  ui_story_1016_10161302_67_dialog_content = "是這樣的……",
  ui_story_1016_10161302_68_dialog_content = "嗯，嗯……我知道了。",
  ui_story_1016_10161302_69_dialog_content = "你繼續去忙吧。",
  ui_story_1016_10161302_70_dialog_content = "是。",
  ui_story_1016_10161302_71_dialog_content = "裁判，能麻煩你把話筒給我嗎？",
  ui_story_1016_10161302_72_dialog_content = "可是，長官，這……",
  ui_story_1016_10161302_73_dialog_content = "我有一件緊急的事要宣布——",
  ui_story_1016_10161302_74_dialog_content = "以委員會的名義。",
  ui_story_1016_10161302_75_dialog_content = "好、好吧……",
  ui_story_1016_10161302_76_dialog_content = "咳咳……各位，請安靜一下，我要宣布一項緊急命令。",
  ui_story_1016_10161302_77_dialog_content = "什麼？緊急命令？",
  ui_story_1016_10161302_78_dialog_content = "緊急命令？",
  ui_story_1016_10161302_79_dialog_content = "那群老東西沒一個好東西。",
  ui_story_1016_10161302_80_dialog_content = "他們肚子裡指不定憋著什麼壞水呢。",
  ui_story_1016_10161302_81_dialog_content = "我有種很不好的預感……",
  ui_story_1016_10161302_82_dialog_content = "就在剛才，委員會收到了一條令人震驚的情報。",
  ui_story_1016_10161302_83_dialog_content = "委員會的情報官在迦南城發現通緝犯吞羅和赫利俄斯的蹤跡，找到了他們的藏身處。",
  ui_story_1016_10161302_84_dialog_content = "不可能！迦南城中的搜索計畫一直都是我在負責，我們對照著地圖，進行了地毯式的搜索！",
  ui_story_1016_10161302_85_dialog_content = "我和我手底下的巡邏隊從來沒在見到過吞羅的半個影子！",
  ui_story_1016_10161302_86_dialog_content = "那只能證明，你們搜索不力。",
  ui_story_1016_10161302_87_dialog_content = "情報官們追捕吞羅的同時，也發現了吞羅藏身的一條未標記在地圖上的暗道。",
  ui_story_1016_10161302_88_dialog_content = "而那條暗道通向的地方，很遺憾……正是大元帥萊因哈特的家附近。",
  ui_story_1016_10161302_89_dialog_content = "而後，為了不打草驚蛇，情報官們跟蹤了她一段時間，發現她大搖大擺地走進了萊因哈特的家。",
  ui_story_1016_10161302_90_dialog_content = "<size=45>什麼？！怎麼可能？！</size>",
  ui_story_1016_10161302_91_dialog_content = "……",
  ui_story_1016_10161302_92_dialog_content = "原來這就是你們的計畫……",
  ui_story_1016_10161302_93_dialog_content = "你們開什麼玩笑？！",
  ui_story_1016_10161302_94_dialog_content = "你們這群老東西……",
  ui_story_1016_10161302_95_dialog_content = "仗沒見你們打過幾場，污蔑起人來倒是一套一套的！",
  ui_story_1016_10161302_96_dialog_content = "有關於這件事，你們最好拿出足夠有力的證據。",
  ui_story_1016_10161302_97_dialog_content = "是的，否則我的刀將會指向每一個侵犯我同胞名譽的人。",
  ui_story_1016_10161302_98_dialog_content = "安靜，請都先安靜一些。",
  ui_story_1016_10161302_99_dialog_content = "我知道各位都很著急，委員會起初也是不願意相信這件事的。",
  ui_story_1016_10161302_100_dialog_content = "但是我們有確鑿的證據，巡邏隊的隊員們都可以作為人證證明這件事。",
  ui_story_1016_10161302_101_dialog_content = "現在，兩名通緝犯正在迦南城內逃竄。",
  ui_story_1016_10161302_102_dialog_content = "這真是太荒唐了，我要回去！",
  ui_story_1016_10161302_103_dialog_content = "萬一吞羅要搞破壞該怎麼辦？難道要讓我們坐以待斃？",
  ui_story_1016_10161302_104_dialog_content = "無需擔心，決賽場周邊有重兵把守，啟光的委員會會對各位的安全負責。",
  ui_story_1016_10161302_105_dialog_content = "但在此之前，委員會作出了一項決定——",
  ui_story_1016_10161302_106_dialog_content = "萊因哈特，妳涉嫌通敵、窩藏逃犯等若干罪名。",
  ui_story_1016_10161302_107_dialog_content = "現在，委員會決定免去妳大元帥的職務。",
  ui_story_1016_10161302_108_dialog_content = "同時，請妳配合接受委員會的調查。",
  ui_story_1016_10161401_1_dialog_content = "<color=#e8d9bb>嗡——</color>",
  ui_story_1016_10161401_2_dialog_content = "偵測到非法入侵，偵測到非法入侵！",
  ui_story_1016_10161401_2X1_dialog_content = "裡面果然有人！給我讓開，罪靈！",
  ui_story_1016_10161401_3_dialog_content = "呿，你最好放尊重點，等我殺死你的時候說不定可以給個痛快。",
  ui_story_1016_10161401_4_dialog_content = "至於其他人……",
  ui_story_1016_10161401_5_dialog_content = "去吧。",
  ui_story_1016_10161401_6_dialog_content = "<anim type=Shake><size=45>吼——！</size></anim>",
  ui_story_1016_10161401_7_dialog_content = "冰花，散開——！",
  ui_story_1016_10161401_8_dialog_content = "<anim type=Shake>嘎……</anim>",
  ui_story_1016_10161401_9_dialog_content = "（日蝕語）斐桀洛大人，我們已經不剩多少了……",
  ui_story_1016_10161401_10_dialog_content = "去死就是你們的使命，少囉嗦。",
  ui_story_1016_10161401_11_dialog_content = "只要被她拖夠時間，這群光靈就輸了！",
  ui_story_1016_10161401_12_dialog_content = "<color=#e8d9bb>嗡——</color>",
  ui_story_1016_10161401_24_dialog_content = "呵呵……<size=50>哈哈哈哈</size>！",
  ui_story_1016_10161401_26_dialog_content = "我馬上就能證明，自己還有資格留下！",
  ui_story_1016_10161401_27_dialog_content = "（資格？難道他要被日蝕除名了？）",
  ui_story_1016_10161401_28_dialog_content = "看看你周圍吧。",
  ui_story_1016_10161401_29_dialog_content = "你的部下已經全都被我們打倒了。",
  ui_story_1016_10161401_30_dialog_content = "現在的你，就是一個光桿司令。",
  ui_story_1016_10161401_31_dialog_content = "光桿司令？",
  ui_story_1016_10161401_32_dialog_content = "那又怎麼樣？就算只有我一個人，也能捏死你們這群臭蟲。",
  ui_story_1016_10161401_33_dialog_content = "<anim type=Shake><size=45>呃啊——！！！</size></anim>",
  ui_story_1016_10161401_34_dialog_content = "他在幹什麼？",
  ui_story_1016_10161401_35_dialog_content = "PlayerName！小心！",
  ui_story_1016_10161401_36_dialog_content = "<anim type=Shake><size=45>桀桀桀桀桀桀！！！</size></anim>",
  ui_story_1016_10161401_37_dialog_content = "好久沒有解放真正的力量了！",
  ui_story_1016_10161401_38_dialog_content = "這一招，我本來打算留著對付那個北境的小丫頭……",
  ui_story_1016_10161401_39_dialog_content = "現在正好先在你們身上開幾個洞，找找當年的感覺！",
  ui_story_1016_10161401_40_dialog_content = "恐懼吧，顫抖吧！",
  ui_story_1016_10161401_41_dialog_content = "然後，開始思考最後的遺言吧！",
  ui_story_1016_10161402_0X1_dialog_content = "可惡，一群臭蟲……居然把我斐桀洛逼到……",
  ui_story_1016_10161402_0X2_dialog_content = "去死！都給我去死！",
  ui_story_1016_10161402_0X3_dialog_content = "危險，他還有餘力！",
  ui_story_1016_10161402_0X4_dialog_content = "還有你，空裔！！你們早該絕種了！！",
  ui_story_1016_10161402_0X5_dialog_content = "快退後，PlayerName！",
  ui_story_1016_10161402_0X6_dialog_content = "別擋老子的路！",
  ui_story_1016_10161402_0X7_dialog_content = "嗚啊！",
  ui_story_1016_10161402_0X8_dialog_content = "<color=#e8d9bb>嗡——</color>",
  ui_story_1016_10161402_0X9_dialog_content = "（這是？！）",
  ui_story_1016_10161402_0X10_dialog_content = "（別動她。）",
  ui_story_1016_10161402_0X11_dialog_content = "（你找到東西了？還等什麼，快出來，我們離開這——）",
  ui_story_1016_10161402_0X12_dialog_content = "（把你的手從她身上拿開。）",
  ui_story_1016_10161402_0X13_dialog_content = "（別說我沒警告過你。）",
  ui_story_1016_10161402_1_dialog_content = "<anim type=Shake><size=45>可惡！</size></anim>",
  ui_story_1016_10161402_2_dialog_content = "<anim type=Shake>你們這群，該死的……光靈……！</anim>",
  ui_story_1016_10161402_3_dialog_content = "<anim type=Shake>該死的光靈！該死的吞羅！還有該死的日蝕！！！</anim>",
  ui_story_1016_10161402_4_dialog_content = "<anim type=Shake>統統都去死吧！！！</anim>",
  ui_story_1016_10161402_4X1_dialog_content = "唔呃……",
  ui_story_1016_10161402_5_dialog_content = "薇絲！！",
  ui_story_1016_10161402_6_dialog_content = "<anim type=Shake>我就算死，也不會死在你們這群蟲子手裡！！！</anim>",
  ui_story_1016_10161402_7_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_1016_10161402_7X1_dialog_content = "<color=#e8d9bb>嗡——！</color>",
  ui_story_1016_10161402_8_dialog_content = "——！！！",
  ui_story_1016_10161402_9_dialog_content = "廢話真多。",
  ui_story_1016_10161402_10_dialog_content = "咳、咳咳！",
  ui_story_1016_10161402_10X1_dialog_content = "薇絲！妳沒事吧！",
  ui_story_1016_10161402_11_dialog_content = "快過來！說不定他只是假裝暈倒，想伺機偷襲。",
  ui_story_1016_10161402_12_dialog_content = "我去看看吧。",
  ui_story_1016_10161402_13_dialog_content = "……",
  ui_story_1016_10161402_14_dialog_content = "看起來沒什麼問題。可以確認，目標失去意識。",
  ui_story_1016_10161402_15_dialog_content = "他確實還活著，只是暈過去了。",
  ui_story_1016_10161402_15X1_dialog_content = "（我剛才的攻擊，威力竟然那麼大？）",
  ui_story_1016_10161402_15X2_dialog_content = "（這到底……）",
  ui_story_1016_10161402_16_dialog_content = "那就讓我用這把劍，送他去為過往的英魂賠罪吧。",
  ui_story_1016_10161402_17_dialog_content = "停！別殺他！",
  ui_story_1016_10161402_18_dialog_content = "嗯？為什麼？",
  ui_story_1016_10161402_19_dialog_content = "我之前說了吧，如果抓到吞羅或其他罪靈，就交給啟光來處置。",
  ui_story_1016_10161402_20_dialog_content = "……好，那就聽妳的。",
  ui_story_1016_10161402_21_dialog_content = "但他已經半死不活了，恐怕就算你們想審問他，也問不出什麼。",
  ui_story_1016_10161402_22_dialog_content = "那就是我們的工作了，不勞您操心。",
  ui_story_1016_10161402_23_dialog_content = "為什麼要留他一命？明明他害了那麼多人！",
  ui_story_1016_10161402_24_dialog_content = "冷靜一點，PlayerName，我知道你很憤怒。",
  ui_story_1016_10161402_25_dialog_content = "但請你想一想，在此之前，艾斯特拉從來沒有關於罪靈的研究紀錄。",
  ui_story_1016_10161402_26_dialog_content = "而且，這傢伙說不定還掌握著有關<color=#FFB400>日蝕</color>這個組織的重要情報。",
  ui_story_1016_10161402_27_dialog_content = "最重要的是，他竟然能毫無阻力地來到這種地方……",
  ui_story_1016_10161402_28_dialog_content = "這說明，他背後一定有著能夠信賴的人作為資訊來源。",
  ui_story_1016_10161402_29_dialog_content = "背後謀劃的這個人，很可能是啟光內部的叛徒。",
  ui_story_1016_10161402_30_dialog_content = "妳說的很有道理，但請恕我無法認同。",
  ui_story_1016_10161402_31_dialog_content = "既然我們對罪靈的研究都不多，那也就是說，就算啟光聯邦也無法保證能完全控制住他。",
  ui_story_1016_10161402_32_dialog_content = "萬一他醒來以後掙脫了控制、逃跑了，那該怎麼辦？",
  ui_story_1016_10161402_33_dialog_content = "啟光會盡一切努力不讓這種事發生。",
  ui_story_1016_10161402_34_dialog_content = "你們無法保證絕對的安全。",
  ui_story_1016_10161402_35_dialog_content = "不能因為有風險，就放棄前進的可能性、停滯不前。",
  ui_story_1016_10161402_36_dialog_content = "……",
  ui_story_1016_10161402_37_dialog_content = "那就聽你們的吧。",
  ui_story_1016_10161402_38_dialog_content = "薇絲、阿納托利還有PlayerName，你們的意見呢？",
  ui_story_1016_10161402_39_dialog_content = "我、我沒有意見。",
  ui_story_1016_10161402_40_dialog_content = "如果鶯歌中校這麼決定的話，我也沒有意見。",
  ui_story_1016_10161402_41_option_content = "我也沒有意見",
  ui_story_1016_10161402_42_option_content = "我不同意",
  ui_story_1016_10161402_43_dialog_content = "卡蓮說得對，我還是擔心被他跑了。",
  ui_story_1016_10161402_44_dialog_content = "我們好不容易打敗了這麼一個難纏的對手，現在放過他，以後會更難對付！",
  ui_story_1016_10161402_45_dialog_content = "而且這傢伙不知道殘害了多少人，他……",
  ui_story_1016_10161402_46_dialog_content = "我知道你的想法，但我還是堅持我的考慮。",
  ui_story_1016_10161402_47_dialog_content = "請讓我，讓啟光聯邦的同伴們試一試。",
  ui_story_1016_10161402_48_dialog_content = "有太多同胞為了獲得關於暗鬼的情報而獻出生命，我們不能白白放過眼前這絕好的機會！",
  ui_story_1016_10161402_49_dialog_content = "……",
  ui_story_1016_10161402_50_dialog_content = "……",
  ui_story_1016_10161402_51_dialog_content = "好吧。",
  ui_story_1016_10161402_52_dialog_content = "謝謝你們的配合。",
  ui_story_1016_10161402_53_dialog_content = "我會立刻聯絡情報部門，讓他們對罪靈展開收容和審問工作。",
  ui_story_1016_10161402_54_dialog_content = "可是我們的工作還沒結束。那扇門裡恐怕還有他的同夥。",
  ui_story_1016_10161402_55_dialog_content = "沒錯，裡面還有非常重要的守護者一號……",
  ui_story_1016_10161402_56_dialog_content = "啊，不管什麼敵人都放馬過來吧。",
  ui_story_1016_10161402_57_dialog_content = "我只希望這一切趕快結束。",
  ui_story_1016_10161402_58_dialog_content = "（也不知道阿克希亞那邊究竟怎麼樣了。她……還活著嗎？）",
  ui_story_1016_10161402_59_dialog_content = "（為什麼，明明已經做好了犧牲的覺悟，但看著她踏上那條路卻還是……）",
  ui_story_1016_10161402_60_dialog_content = "各位，提高警惕！",
  ui_story_1016_10161402_61_dialog_content = "那扇門似乎有動靜了！",
  ui_story_1016_10161402_62_dialog_content = "（這股氣息……！）",
  ui_story_1016_10161402_63_dialog_content = "<color=#e8d9bb>轟隆——</color>",
  ui_story_1016_10161402_64_dialog_content = "<color=#e8d9bb>嗡——嗡——</color>",
  ui_story_1016_10161402_65_dialog_content = "重新做好戰鬥準備，PlayerName！",
  ui_story_1016_10161402_66_dialog_content = "注意隊形！別露出破綻！",
  ui_story_1016_10161402_67_dialog_content = "<color=#e8d9bb>轟——</color>",
  ui_story_1016_10161402_68_dialog_content = "好像有什麼人衝出來了？！",
  ui_story_1016_10161402_69_dialog_content = "那是……！",
  ui_story_1016_10161402_70_dialog_content = "（我看到一個陌生的影子從巨大的門後衝了出來。）",
  ui_story_1016_10161402_71_dialog_content = "（只是一瞬，我便感覺到，那個傢伙身上有著遠比斐桀洛強大的暗能。）",
  ui_story_1016_10161402_72_dialog_content = "（我們在剛才對付斐桀洛的時候，已經消耗了太多力氣。）",
  ui_story_1016_10161402_73_dialog_content = "（此刻只要那個傢伙想要，隨時都可以殺了我們……）",
  ui_story_1016_10161402_74_dialog_content = "薇絲！小心！那傢伙向妳那邊去了！",
  ui_story_1016_10161402_75_dialog_content = "咦？！",
  ui_story_1016_10161402_76_dialog_content = "跨越了遙遠的時間與距離後……",
  ui_story_1016_10161402_77_dialog_content = "我們，又見面了。",
  ui_story_1016_10161402_78_dialog_content = "妳是誰？",
  ui_story_1016_10161402_79_dialog_content = "（她看起來像是<color=#FFB400>罪靈</color>？）",
  ui_story_1016_10161402_80_dialog_content = "（為什麼，明明我連她的名字都不知道，但是……）",
  ui_story_1016_10161402_81_dialog_content = "（為什麼會有<color=#FFB400>熟悉的感覺</color>？！）",
  ui_story_1016_10161402_82_dialog_content = "等等！別走！",
  ui_story_1016_10161402_83_dialog_content = "妳會知道的。",
  ui_story_1016_10161402_84_dialog_content = "在未來。",
  ui_story_1016_10161402_85_dialog_content = "攔住她！",
  ui_story_1016_10161402_86_dialog_content = "她手裡拿著的是<color=#FFB400>守護者一號的核心</color>！",
  ui_story_1016_10161402_87_dialog_content = "微光！",
  ui_story_1016_10161402_88_dialog_content = "沒用的。",
  ui_story_1016_10161402_89_dialog_content = "竟然沒有效？！",
  ui_story_1016_10161402_90_dialog_content = "快追！不能讓她帶走守護者一號的核心！",
  ui_story_1016_10161402_91_dialog_content = "<color=#e8d9bb>與此同時，迦南城內</color>",
  ui_story_1016_10161402_92_dialog_content = "快搜，他們跑不遠的，不要放過任何一個角落。",
  ui_story_1016_10161402_93_dialog_content = "是！",
  ui_story_1016_10161402_94_dialog_content = "……",
  ui_story_1016_10161402_95_dialog_content = "追得真緊。",
  ui_story_1016_10161402_96_dialog_content = "恐怕再過不久，這個地方也會暴露吧。",
  ui_story_1016_10161402_97_dialog_content = "我們該走了。",
  ui_story_1016_10161402_98_dialog_content = "這個情景，就像……回到了80號地下城。",
  ui_story_1016_10161402_99_dialog_content = "你現在說這個沒有意義。",
  ui_story_1016_10161402_100_dialog_content = "沒有意義嗎？或許吧……",
  ui_story_1016_10161402_101_dialog_content = "那時候……我們……也是像現在這樣……被困在地下城裡，周圍全是敵人……",
  ui_story_1016_10161402_102_dialog_content = "但是那時候……我們……面對的是暗鬼。現在面對的卻是同胞……",
  ui_story_1016_10161402_103_dialog_content = "有什麼區別嗎？",
  ui_story_1016_10161402_104_dialog_content = "站在對面妨礙我的，都是敵人。",
  ui_story_1016_10161402_105_dialog_content = "至於他們是光靈還是暗鬼，本質上沒有什麼不同。",
  ui_story_1016_10161402_106_dialog_content = "不……這是，不同的。",
  ui_story_1016_10161402_107_dialog_content = "暗鬼是天生的敵人，但同胞……他們只是不知道，我們經歷了什麼。",
  ui_story_1016_10161402_108_dialog_content = "這是誤會。",
  ui_story_1016_10161402_109_dialog_content = "這不是誤會。",
  ui_story_1016_10161402_110_dialog_content = "這是他們的愚昧，他們的盲從。",
  ui_story_1016_10161402_111_dialog_content = "……",
  ui_story_1016_10161402_112_dialog_content = "妳……到底經歷了什麼……才會……變成現在這個樣子……？",
  ui_story_1016_10161402_113_dialog_content = "你的思路變清晰了，是什麼時候的事？",
  ui_story_1016_10161402_114_dialog_content = "這幾天，一點點地……",
  ui_story_1016_10161402_115_dialog_content = "最初的時候，頭腦裡……像是，霧氣……",
  ui_story_1016_10161402_116_dialog_content = "但現在……好一點了……",
  ui_story_1016_10161402_117_dialog_content = "是嗎？",
  ui_story_1016_10161402_118_dialog_content = "看來，實驗的成果已經超出了預期。",
  ui_story_1016_10161402_119_dialog_content = "妳還沒有……回答我……",
  ui_story_1016_10161402_120_dialog_content = "告訴我，為什麼離開……",
  ui_story_1016_10161402_121_dialog_content = "讓我，幫妳……回到啟光。",
  ui_story_1016_10161402_122_dialog_content = "幼稚。",
  ui_story_1016_10161402_123_dialog_content = "究竟是什麼讓你覺得，你還能活著回到那個地方？",
  ui_story_1016_10161402_124_dialog_content = "那裡，是我的家。",
  ui_story_1016_10161402_125_dialog_content = "我們的同伴，萊因哈特，她還在等著。",
  ui_story_1016_10161402_126_dialog_content = "她早就不是我的同伴了，她放棄了我，也放棄了你。",
  ui_story_1016_10161402_127_dialog_content = "啟光聯邦早就爛透了，從上到下都是。",
  ui_story_1016_10161402_128_dialog_content = "妳在……恨……",
  ui_story_1016_10161402_129_dialog_content = "妳在……燃燒妳自己……",
  ui_story_1016_10161402_130_dialog_content = "是嗎？那讓我來告訴你，這一切的真相吧。",
  ui_story_1016_10161402_131_dialog_content = "如果在得知了真相後，你還要愚蠢地相信他們，那只能說明你無藥可救。",
  ui_story_1016_10161402_132_dialog_content = "真相？",
  ui_story_1016_10161402_133_dialog_content = "不管是你、我還是萊因哈特，我們都是為了啟光而被製造出來的武器。",
  ui_story_1016_10161402_134_dialog_content = "委員會在我們身上實施了名為「人造太陽」計畫的改造實驗，對我們進行了強化。",
  ui_story_1016_10161402_135_dialog_content = "80號地下城那次戰鬥，就是對我們這些改造實驗體的驗證。",
  ui_story_1016_10161402_136_dialog_content = "而那些所謂的任務，根本就沒有意義。",
  ui_story_1016_10161402_137_dialog_content = "怎麼可能？！",
  ui_story_1016_10161402_138_dialog_content = "那場戰鬥……死了那麼多人！",
  ui_story_1016_10161402_139_dialog_content = "送人去死，本來就是他們的目的。",
  ui_story_1016_10161402_140_dialog_content = "委員會利用那場戰鬥，將實驗體逼上絕路，激發他們的潛力。",
  ui_story_1016_10161402_141_dialog_content = "其中的大部分都是改造失敗的廢棄品，他們有的直接被殺了，有的像你一樣變成了這幅樣子。",
  ui_story_1016_10161402_142_dialog_content = "他們……為什麼要這麼做？",
  ui_story_1016_10161402_143_dialog_content = "我說過了，為了驗證，因為「人造太陽」的改造成功率極低。",
  ui_story_1016_10161402_144_dialog_content = "驗證實驗成功與否的唯一的方法，就是在殘酷的戰鬥中活下來、從暗鬼中殺出一條血路。",
  ui_story_1016_10161402_145_dialog_content = "萊因哈特是我們之中唯一的成功者。",
  ui_story_1016_10161402_146_dialog_content = "而其他人，從一開始就是要被放棄的。",
  ui_story_1016_10161402_147_dialog_content = "你還不明白嗎，對於啟光來說，你從一開始就不是一個人，而是一件工具，一把武器。",
  ui_story_1016_10161402_148_dialog_content = "別再被那些所謂的家國大義蒙蔽了，想要活下去，你要先學會獨立思考。",
  ui_story_1016_10161402_149_dialog_content = "在這個地方，一把折斷的武器是沒有容身之處的。",
  ui_story_1016_10161402_150_dialog_content = "你也看見了，這裡的每個人都在對你刀劍相向。",
  ui_story_1016_10161402_151_dialog_content = "……",
  ui_story_1016_10161402_152_dialog_content = "妳剛才……也說過了，他們是……愚昧，和盲從……",
  ui_story_1016_10161402_153_dialog_content = "所以，我們要……解釋清楚，這個誤會……",
  ui_story_1016_10161402_154_dialog_content = "把那些，蠱惑人們的人，趕出去。",
  ui_story_1016_10161402_155_dialog_content = "讓啟光回到原本正確的道路上去。",
  ui_story_1016_10161402_156_dialog_content = "我們要去，解決問題，而不是……無端地憎恨別人。",
  ui_story_1016_10161402_157_dialog_content = "你還在相信那些人的鬼話。",
  ui_story_1016_10161402_158_dialog_content = "不，我早就不信了。",
  ui_story_1016_10161402_159_dialog_content = "這是……我自己思考得出的結論，就像妳說的那樣。",
  ui_story_1016_10161402_160_dialog_content = "如果妳要離開，我不會阻攔。",
  ui_story_1016_10161402_161_dialog_content = "但是我會留下來，查清所有的真相……阻止他們送更多人去死。",
  ui_story_1016_10161402_162_dialog_content = "我不允許。",
  ui_story_1016_10161402_163_dialog_content = "你是我的實驗體，在你失去所有的研究價值之前，必須跟我走。",
  ui_story_1016_10161402_164_dialog_content = "你沒有別的選擇。",
  ui_story_1016_10161402_165_dialog_content = "在這裡！發現目標！",
  ui_story_1016_10161402_166_dialog_content = "嘖。",
  ui_story_1016_10161402_167_dialog_content = "麻煩的蟲子。",
  ui_story_1016_10161402_168_dialog_content = "！！！",
  ui_story_1016_10161402_169_dialog_content = "不要退縮！她的雕蟲小技傷不到你們！",
  ui_story_1016_10161402_170_dialog_content = "竟然還沒耗盡……",
  ui_story_1016_10161402_171_dialog_content = "為了對付啟光聯邦的頭號通緝犯，我們做了萬全的準備。",
  ui_story_1016_10161402_172_dialog_content = "讓開！",
  ui_story_1016_10161402_173_dialog_content = "注意，這次別再讓他們跑了。",
  ui_story_1016_10161402_174_dialog_content = "A隊，防禦陣型，逐漸推進！",
  ui_story_1016_10161402_175_dialog_content = "B隊，繞到後面堵住他們的去路！",
  ui_story_1016_10161402_176_dialog_content = "是！",
  ui_story_1016_10161402_177_dialog_content = "麻煩。",
  ui_story_1016_10161402_178_dialog_content = "還磨蹭什麼呢？該走了，實驗體。",
  ui_story_1016_10161402_179_dialog_content = "不……",
  ui_story_1016_10161402_180_dialog_content = "我……擋住他們，剩下的一半，妳可以，對付，逃走。",
  ui_story_1016_10161402_181_dialog_content = "你想幹什麼？！",
  ui_story_1016_10161402_182_dialog_content = "<size=45>退後！</size>",
  ui_story_1016_10161402_183_dialog_content = "快攔住他！",
  ui_story_1016_10161402_184_dialog_content = "<color=#e8d9bb>轟——！！！</color>",
  ui_story_1016_10161402_185_dialog_content = "咳咳咳——！",
  ui_story_1016_10161402_186_dialog_content = "那傢伙竟然打塌了天花板，封死了這條路？！",
  ui_story_1016_10161402_187_dialog_content = "德尼耶爾，離開這裡。",
  ui_story_1016_10161402_188_dialog_content = "這是我能幫妳做的，最後的事情。",
  ui_story_1016_10161402_189_dialog_content = "愚蠢！",
  ui_story_1016_10161402_190_dialog_content = "愚蠢至極！",
  ui_story_1016_10161402_191_dialog_content = "快走……",
  ui_story_1016_10161402_192_dialog_content = "放跑了吞羅嗎……",
  ui_story_1016_10161402_193_dialog_content = "不過沒關係，畢竟——",
  ui_story_1016_10161402_194_dialog_content = "我們的首要目標，是你。",
  ui_story_1016_10161402_195_dialog_content = "抓住他。",
  ui_story_1016_10161402_196_dialog_content = "是！",
  ui_story_1016_10161402_197_dialog_content = "別過來……",
  ui_story_1016_10161402_198_dialog_content = "我，不想對啟光的同胞動手……",
  ui_story_1016_10161402_199_dialog_content = "立刻放下武器！",
  ui_story_1016_10161402_200_dialog_content = "<size=45>別過來！</size>",
  ui_story_1016_10161402_201_dialog_content = "呃！！！",
  ui_story_1016_10161402_202_dialog_content = "無用的反抗。",
  ui_story_1016_10161402_203_dialog_content = "……！",
  ui_story_1016_10161402_204_dialog_content = "不准動！",
  ui_story_1016_10161402_205_dialog_content = "成功控制首要目標。",
  ui_story_1016_10161402_206_dialog_content = "次要目標逃脫，不過沒關係。",
  ui_story_1016_10161402_207_dialog_content = "行動順利結束。",
  ui_story_1016_10161402_208_dialog_content = "接下來，就要等尤利西斯長官的指示了。",
  ui_story_1016_10161402_209_dialog_content = "<color=#e8d9bb>決賽場</color>",
  ui_story_1016_10161402_210_dialog_content = "阿克希亞中尉，請協助委員會，拘捕嫌犯萊因哈特。",
  ui_story_1016_10161402_211_dialog_content = "……",
  ui_story_1016_10161402_212_dialog_content = "是……",
  ui_story_1016_10161402_213_dialog_content = "快停下，妳的身體已經——",
  ui_story_1016_10161402_214_dialog_content = "……！",
  ui_story_1016_10161402_215_dialog_content = "阿克希亞！",
  ui_story_1016_10161402_216_dialog_content = "嗯……力量使用過度了嗎？",
  ui_story_1016_10161402_217_dialog_content = "我還以為她還能再堅持一下。",
  ui_story_1016_10161402_218_dialog_content = "不過沒關係，士兵，抓住她。",
  ui_story_1016_10161402_219_dialog_content = "是！",
  ui_story_1016_10161402_220_dialog_content = "都給我停下！",
  ui_story_1016_10161402_221_dialog_content = "尤利西斯，你最好弄清楚一點，委員會這次的行為已經越界了。",
  ui_story_1016_10161402_222_dialog_content = "你們這群老東西，一次次打壓我們。",
  ui_story_1016_10161402_223_dialog_content = "以前都是萊因哈特攔著，不讓我們找你們的麻煩。",
  ui_story_1016_10161402_224_dialog_content = "這次你們竟然踩到我們頭上來了！",
  ui_story_1016_10161402_225_dialog_content = "大元帥，請妳說明情況，到底是怎麼回事。",
  ui_story_1016_10161402_226_dialog_content = "如果這是他們的陰謀，我們勢必會為妳而戰。",
  ui_story_1016_10161402_227_dialog_content = "各位軍團長，委員會一向都是按照規定辦事的。",
  ui_story_1016_10161402_228_dialog_content = "倒是各位軍團長現在做的事情不合規章，徇私枉法。",
  ui_story_1016_10161402_229_dialog_content = "如果各位對委員會的決策有異議，可以以書面文件的形式提出，而不是在這裡濫用暴力。",
  ui_story_1016_10161402_230_dialog_content = "你這傢伙……",
  ui_story_1016_10161402_231_dialog_content = "請各位軍團長端正自己的態度，否則委員會將會視你們為萊因哈特的共犯。",
  ui_story_1016_10161402_232_dialog_content = "夠了。",
  ui_story_1016_10161402_233_dialog_content = "這件事與他們無關。",
  ui_story_1016_10161402_234_dialog_content = "萊因哈特？！",
  ui_story_1016_10161402_235_dialog_content = "雷霆，讓我試試看吧。",
  ui_story_1016_10161402_236_dialog_content = "讓我試試一個人在啟光究竟能不能用合法的方式證明自己的清白。",
  ui_story_1016_10161402_237_dialog_content = "……",
  ui_story_1016_10161402_238_dialog_content = "好吧。",
  ui_story_1016_10161402_239_dialog_content = "嗯，謝謝……",
  ui_story_1016_10161402_240_dialog_content = "接下來就交給妳了。",
  ui_story_1016_10161402_241_dialog_content = "那孩子也是，她的狀況很糟糕，要盡快帶她去治療。",
  ui_story_1016_10161402_242_dialog_content = "……",
  ui_story_1016_10161402_243_dialog_content = "大元帥……？！",
  ui_story_1016_10161402_244_dialog_content = "大元帥……",
  ui_story_1016_10161402_245_dialog_content = "……",
  ui_story_1016_10161402_246_dialog_content = "不用你們忙了，尤利西斯。",
  ui_story_1016_10161402_247_dialog_content = "我願意接受調查。",
  ui_story_1016_10161402_248_dialog_content = "感謝妳的配合，萊因哈特。",
  ui_story_1016_10161402_249_dialog_content = "把她帶走。",
  ui_story_1016_10161402_250_dialog_content = "是！",
  ui_story_1016_10161501_1_dialog_content = "現在的情況就是這樣。",
  ui_story_1016_10161501_2_dialog_content = "身分不明的罪靈盜走了<color=#FFB400>守護者一號</color>的核心，並且至今下落不明……",
  ui_story_1016_10161501_3_dialog_content = "鶯歌中校，這是嚴重的失職行為。",
  ui_story_1016_10161501_4_dialog_content = "十分抱歉，我願意為此承擔任何處罰。",
  ui_story_1016_10161501_5_dialog_content = "這件事除了在場的人以外，還有其他人知道嗎？",
  ui_story_1016_10161501_6_dialog_content = "目前還沒有其他人知道這件事。",
  ui_story_1016_10161501_7_dialog_content = "在場的目擊者已經被我集中在這裡了，他們都沒有機會對外透露此事。",
  ui_story_1016_10161501_8_dialog_content = "嗯……我知道了。",
  ui_story_1016_10161501_9_dialog_content = "鶯歌中校，接下來搜索不明罪靈的任務由我接替妳進行。",
  ui_story_1016_10161501_10_dialog_content = "請妳暫時休整，等待委員會的進一步指示。",
  ui_story_1016_10161501_11_dialog_content = "同時，也請在場的各位先不要向任何人透露這件事。",
  ui_story_1016_10161501_12_dialog_content = "是。",
  ui_story_1016_10161501_13_dialog_content = "明白。",
  ui_story_1016_10161501_14_dialog_content = "嗯。",
  ui_story_1016_10161501_15_dialog_content = "知道了。把這件事到處亂說，對我也沒有好處。",
  ui_story_1016_10161501_16_dialog_content = "我也會保密的。",
  ui_story_1016_10161501_17_dialog_content = "感謝你們的配合。",
  ui_story_1016_10161501_18_dialog_content = "那麼，解散。",
  ui_story_1016_10161501_19_dialog_content = "等一下，阿克希亞的情況怎麼樣了？",
  ui_story_1016_10161501_20_dialog_content = "阿克希亞中尉在表演賽中使用力量過度，目前仍處於昏迷狀態。",
  ui_story_1016_10161501_21_dialog_content = "她現在由雷霆軍團長陪同，正在醫療中心接受治療。",
  ui_story_1016_10161501_22_dialog_content = "是嗎，她……",
  ui_story_1016_10161501_23_dialog_content = "我現在就去找她！",
  ui_story_1016_10161501_24_dialog_content = "那我也要回去找萊因哈特大元帥了。",
  ui_story_1016_10161501_25_dialog_content = "PlayerName、薇絲中尉、卡蓮以及李奧，我們就此別過吧。",
  ui_story_1016_10161501_26_dialog_content = "你不用回去了。",
  ui_story_1016_10161501_27_dialog_content = "嗯？",
  ui_story_1016_10161501_28_dialog_content = "萊因哈特已經被免職，現在不再擔任啟光聯邦的大元帥了。",
  ui_story_1016_10161501_29_dialog_content = "<size=45>什麼？！</size>",
  ui_story_1016_10161501_30_option_content = "你沒在開玩笑吧？！",
  ui_story_1016_10161501_31_dialog_content = "究竟發生了什麼？為什麼這麼大的事情，我們卻不知道？",
  ui_story_1016_10161501_32_option_content = "到底發生了什麼？！",
  ui_story_1016_10161501_33_dialog_content = "為什麼萊因哈特突然被免職了？",
  ui_story_1016_10161501_34_dialog_content = "你們先冷靜一下。",
  ui_story_1016_10161501_35_dialog_content = "由於事發突然，當時各位還在追查迦南城中的暗鬼，所以不知道也是理所當然的。",
  ui_story_1016_10161501_36_dialog_content = "迦南城中的巡邏隊在巡邏時發現了通緝犯吞羅及其共犯赫利俄斯的蹤跡。",
  ui_story_1016_10161501_37_dialog_content = "他們近幾日一直躲在迦南城中，伺機破壞聯合軍演。",
  ui_story_1016_10161501_38_dialog_content = "而他們躲藏的地方，正是萊因哈特的家裡。",
  ui_story_1016_10161501_39_dialog_content = "他們被我們抓了個正著，因此委員會斷定萊因哈特有通敵之嫌，暫時罷免了她的職務。",
  ui_story_1016_10161501_40_dialog_content = "這怎麼可能！",
  ui_story_1016_10161501_41_dialog_content = "萊因哈特大元帥絕對不是會通敵的人！",
  ui_story_1016_10161501_42_dialog_content = "我再重複一遍，她現在已經不再是啟光聯邦的大元帥了。",
  ui_story_1016_10161501_43_dialog_content = "這是必要的審查步驟，如果她是清白的，那麼委員會會讓她官復原職。",
  ui_story_1016_10161501_44_dialog_content = "你們要做的，是理解與配合。",
  ui_story_1016_10161501_45_dialog_content = "可是……",
  ui_story_1016_10161501_46_dialog_content = "我還是不能相信……",
  ui_story_1016_10161501_47_dialog_content = "不管你信不信，都要先等調查結果出來才行。",
  ui_story_1016_10161501_48_dialog_content = "而且，作為平日裡與萊因哈特交往密切的人員——",
  ui_story_1016_10161501_49_dialog_content = "PlayerName、薇絲以及阿納托利，你們都要接受調查。",
  ui_story_1016_10161501_50_dialog_content = "怎麼能這樣！",
  ui_story_1016_10161501_51_dialog_content = "調查嗎……",
  ui_story_1016_10161501_52_dialog_content = "這……",
  ui_story_1016_10161501_53_option_content = "好吧",
  ui_story_1016_10161501_54_dialog_content = "就算你們問我，我也沒什麼可說的。",
  ui_story_1016_10161501_55_dialog_content = "我相信萊因哈特，也從沒見過她做什麼不該做的事。",
  ui_story_1016_10161501_56_dialog_content = "說得好。",
  ui_story_1016_10161501_57_option_content = "如果我拒絕呢？",
  ui_story_1016_10161501_58_dialog_content = "剛才那句話並不是一個問句，而是一個陳述句。",
  ui_story_1016_10161501_59_dialog_content = "除了配合以外，你沒有選擇別的選項的權利。",
  ui_story_1016_10161501_60_dialog_content = "你就用這種態度對待啟光重要的客人們？",
  ui_story_1016_10161501_61_dialog_content = "雷霆軍團長？！",
  ui_story_1016_10161501_62_dialog_content = "唷，薇絲，PlayerName，還有萊因哈特的那個副官。",
  ui_story_1016_10161501_63_dialog_content = "雷霆軍團長，請不要妨礙委員會執行公務。",
  ui_story_1016_10161501_64_dialog_content = "我沒有妨礙你，只是提醒你，態度太強硬有時候會對工作造成困難。",
  ui_story_1016_10161501_65_dialog_content = "……",
  ui_story_1016_10161501_66_dialog_content = "抱歉，剛才是我的措辭有問題。",
  ui_story_1016_10161501_67_dialog_content = "希望各位能配合我們的工作。",
  ui_story_1016_10161501_68_dialog_content = "最近一段時間，可能需要三位先在啟光停留，等調查結束後才能自由行動。",
  ui_story_1016_10161501_69_dialog_content = "……",
  ui_story_1016_10161501_70_dialog_content = "也沒有別的選擇了吧。",
  ui_story_1016_10161501_71_dialog_content = "請你理解。",
  ui_story_1016_10161501_72_dialog_content = "好了，那就先這麼決定吧。",
  ui_story_1016_10161501_73_dialog_content = "PlayerName，你們也先消消氣，這裡的事，沒必要發展成衝突。",
  ui_story_1016_10161501_74_dialog_content = "好吧……",
  ui_story_1016_10161501_75_dialog_content = "既然都沒事了，那就散了吧。",
  ui_story_1016_10161501_76_dialog_content = "我還有別的事要做，先告辭了。",
  ui_story_1016_10161501_77_dialog_content = "這傢伙，跑得倒是滿快……",
  ui_story_1016_10161501_78_dialog_content = "雷霆軍團長，這段時間到底發生了什麼？為什麼萊因哈特大元帥會……",
  ui_story_1016_10161501_79_dialog_content = "不清楚。",
  ui_story_1016_10161501_80_dialog_content = "就算是我，現在也沒搞清楚到底是什麼狀況。",
  ui_story_1016_10161501_81_dialog_content = "但現在絕對不是與委員會那些傢伙正面發生衝突的好時候。",
  ui_story_1016_10161501_82_dialog_content = "不如說，他們很樂意與我們起衝突，因為衝突越大，萊因哈特的局面就會越被動。",
  ui_story_1016_10161501_83_dialog_content = "她沒事吧……",
  ui_story_1016_10161501_84_dialog_content = "……",
  ui_story_1016_10161501_85_dialog_content = "相信她吧。",
  ui_story_1016_10161501_86_dialog_content = "卡蓮殿下——！",
  ui_story_1016_10161501_87_dialog_content = "終於找到您了！",
  ui_story_1016_10161501_88_dialog_content = "發生什麼事了？",
  ui_story_1016_10161501_89_dialog_content = "我剛剛接到城主大人的急電，要求包括您在內的所有白夜城參賽者立刻返回！",
  ui_story_1016_10161501_90_dialog_content = "城主大人的命令嗎……",
  ui_story_1016_10161501_91_dialog_content = "我知道了。等我收拾一下東西，立刻回去。",
  ui_story_1016_10161501_92_dialog_content = "嗯，那我們等您！",
  ui_story_1016_10161501_93_dialog_content = "看起來，有不得了的事即將……不，應該說已經發生了。",
  ui_story_1016_10161501_94_dialog_content = "我也得去找若瑟和昭他們，安排大家盡快返回黃昏鎮。",
  ui_story_1016_10161501_95_dialog_content = "我也先失陪了，祝你們好運。",
  ui_story_1016_10161501_96_dialog_content = "嗯……",
  ui_story_1016_10161501_97_dialog_content = "<color=#e8d9bb>與此同時，研究院</color>",
  ui_story_1016_10161501_98_dialog_content = "嗯？已經醒了嗎？",
  ui_story_1016_10161501_99_dialog_content = "真是強大的生命力，不愧是吞羅的研究成果。",
  ui_story_1016_10161501_100_dialog_content = "我記得你……",
  ui_story_1016_10161501_101_dialog_content = "你是我們曾經的長官，尤利西斯。",
  ui_story_1016_10161501_102_dialog_content = "你一點都沒變。",
  ui_story_1016_10161501_103_dialog_content = "哦？連記憶都在逐漸恢復了？",
  ui_story_1016_10161501_104_dialog_content = "真令人感到驚喜。",
  ui_story_1016_10161501_105_dialog_content = "不過只可惜，不太聰明。",
  ui_story_1016_10161501_106_dialog_content = "……",
  ui_story_1016_10161501_107_dialog_content = "有一點我很好奇，既然你不想和我們打，那究竟是什麼讓你對吞羅言聽計從？",
  ui_story_1016_10161501_108_dialog_content = "你甚至不惜自己被抓，也要讓她跑掉，為什麼？",
  ui_story_1016_10161501_109_dialog_content = "那不是言聽計從。",
  ui_story_1016_10161501_110_dialog_content = "我是，啟光聯邦的軍人……",
  ui_story_1016_10161501_111_dialog_content = "保護啟光的人民和戰友，是我的使命。",
  ui_story_1016_10161501_112_dialog_content = "！",
  ui_story_1016_10161501_113_dialog_content = "哈哈哈，這我還真沒想到。",
  ui_story_1016_10161501_114_dialog_content = "她對你說了什麼？難道她說是因為委員會害了她，她才會變成那樣？",
  ui_story_1016_10161501_115_dialog_content = "不，不不不，離開啟光、背叛所有人，那是她自己的選擇。",
  ui_story_1016_10161501_116_dialog_content = "……",
  ui_story_1016_10161501_117_dialog_content = "你真是可憐，一輩子都生活在一個又一個謊言裡，還對此深信不疑。",
  ui_story_1016_10161501_118_dialog_content = "寧可去相信半個暗鬼，也不願意相信與你相同的光靈。",
  ui_story_1016_10161501_119_dialog_content = "不過也難怪，你本來就是個殘次品。",
  ui_story_1016_10161501_120_dialog_content = "只是現在，你終於有點價值了。",
  ui_story_1016_10161501_121_dialog_content = "<color=#e8d9bb>叩，叩</color>",
  ui_story_1016_10161501_122_dialog_content = "進來。",
  ui_story_1016_10161501_123_dialog_content = "尤利西斯長官。",
  ui_story_1016_10161501_124_dialog_content = "我不是說過嗎？從現在開始，我要進行一項重要研究，不允許任何人打擾。",
  ui_story_1016_10161501_125_dialog_content = "十分抱歉！但是「那位大人」在找您。",
  ui_story_1016_10161501_126_dialog_content = "「<color=#FFB400>鐵面</color>」嗎……呵呵，確實，她也該來找我了。",
  ui_story_1016_10161501_127_dialog_content = "<color=#e8d9bb>稍後，迦南城內某處</color>",
  ui_story_1016_10161501_128_dialog_content = "我猜，妳是想問罪？",
  ui_story_1016_10161501_129_dialog_content = "現在問罪未免有些心急。",
  ui_story_1016_10161501_130_dialog_content = "我今天只是想找你來，讓你來幫我看看我的推測是否正確。",
  ui_story_1016_10161501_131_dialog_content = "妳的推測，不是向來都是正確答案嗎？",
  ui_story_1016_10161501_132_dialog_content = "無意義的恭維就免了，這對你我都沒有好處。",
  ui_story_1016_10161501_133_dialog_content = "確實。",
  ui_story_1016_10161501_134_dialog_content = "那麼，來說說最初的計畫吧。",
  ui_story_1016_10161501_135_dialog_content = "最初的計畫是借助日蝕的棄子來演一齣戲，配合你的手下們，借機扳倒萊因哈特。",
  ui_story_1016_10161501_136_dialog_content = "但是現在卻出了意外，日蝕不僅想要吞羅和她的研究成果，還想要守護者一號的核心。",
  ui_story_1016_10161501_137_dialog_content = "不僅如此，這次的計畫，還被一群麻煩的人察覺了。",
  ui_story_1016_10161501_138_dialog_content = "誰？",
  ui_story_1016_10161501_139_dialog_content = "<color=#FFB400>黃昏鎮</color>。",
  ui_story_1016_10161501_140_dialog_content = "來自黃昏鎮的那支小隊察覺到了你的計畫，他們在最後把勝利讓給了你的手下。",
  ui_story_1016_10161501_141_dialog_content = "難道……是有人洩密？",
  ui_story_1016_10161501_142_dialog_content = "也有別的可能，比如……",
  ui_story_1016_10161501_143_dialog_content = "你的手下從不用盡全力。",
  ui_story_1016_10161501_144_dialog_content = "裝備強得有些過分。",
  ui_story_1016_10161501_145_dialog_content = "對於試題早有準備。",
  ui_story_1016_10161501_146_dialog_content = "……",
  ui_story_1016_10161501_147_dialog_content = "你的動作有些過於顯眼了。",
  ui_story_1016_10161501_148_dialog_content = "黃昏鎮雖然只是方寸之地，卻也是啟光和白夜城都不願意去碰的刺頭。",
  ui_story_1016_10161501_149_dialog_content = "現在他們得到了先機，在之後的計畫裡，他們將會成為一個變數。",
  ui_story_1016_10161501_150_dialog_content = "而你之後要做的，就是負起你的責任，讓這個變數變得可控。",
  ui_story_1016_10161501_151_dialog_content = "還有就是，要盡快找回守護者一號的核心。",
  ui_story_1016_10161501_152_dialog_content = "比起因為一個破綻而畏首畏尾，我還是更喜歡自由一點的棋局。",
  ui_story_1016_10161501_153_dialog_content = "嗯……那就這麼辦吧。",
  ui_story_1016_10161501_154_dialog_content = "看來你對你的實驗頗有信心。",
  ui_story_1016_10161501_155_dialog_content = "當然。",
  ui_story_1016_10161501_156_dialog_content = "一旦解析了吞羅的技術，這就將成為整個啟光聯邦多年以來最大的技術突破。",
  ui_story_1016_10161501_157_dialog_content = "這項技術一旦被解明，就可以利用X號地下城的那台和弦紐帶裝置，大量生產強化士兵。",
  ui_story_1016_10161501_158_dialog_content = "畢竟不管是「啟明星」計畫還是「人造太陽」計畫的產物，在整個啟光還有很多。",
  ui_story_1016_10161501_159_dialog_content = "到那時，啟光聯邦的實力將會有質的飛躍。",
  ui_story_1016_10161501_160_dialog_content = "那就盡快吧，我們的時間是比光明還要珍貴的東西。",
  ui_story_1016_10161501_161_dialog_content = "不過，到頭來，你還是選擇了剽竊吞羅的試驗成果。",
  ui_story_1016_10161501_162_dialog_content = "作為研究者，你的自尊心真的允許你這麼做嗎？",
  ui_story_1016_10161501_163_dialog_content = "這不是問題。",
  ui_story_1016_10161501_164_dialog_content = "想要在這個世界上延續文明，我們只能不擇手段。",
  ui_story_1016_10161501_165_dialog_content = "<color=#e8d9bb>幾天後，啟光醫療中心</color>",
  ui_story_1016_10161501_166_dialog_content = "（距離表演賽已經過去好幾天了，但阿克希亞還是沒有醒來。）",
  ui_story_1016_10161501_167_dialog_content = "（這一次，她幾乎又經歷了完全破碎的過程。）",
  ui_story_1016_10161501_168_dialog_content = "（幸運的是，因為有上一次修復破碎的經驗，醫生和研究員們很快就修好了她的身體。）",
  ui_story_1016_10161501_169_dialog_content = "（但由於她傷得太重，何時能夠醒來，還是一個未知數。）",
  ui_story_1016_10161501_170_dialog_content = "嗯……",
  ui_story_1016_10161501_171_dialog_content = "阿克希亞？！",
  ui_story_1016_10161501_172_dialog_content = "阿克希亞……好像做了一個，很長的夢。",
  ui_story_1016_10161501_173_dialog_content = "妳……終於醒了……",
  ui_story_1016_10161501_174_dialog_content = "早安，鶯歌。",
  ui_story_1016_10161501_175_dialog_content = "鶯歌看起來，很疲憊。",
  ui_story_1016_10161501_176_dialog_content = "是嗎？或許吧……",
  ui_story_1016_10161501_177_dialog_content = "妳感覺怎麼樣？有沒有哪裡不舒服？",
  ui_story_1016_10161501_178_dialog_content = "阿克希亞，一切正常。",
  ui_story_1016_10161501_179_dialog_content = "只是想要恢復到能夠戰鬥的狀態，還需要一定時間。",
  ui_story_1016_10161501_180_dialog_content = "先別急著戰鬥，妳能活下來就已經非常幸運了。",
  ui_story_1016_10161501_181_dialog_content = "……",
  ui_story_1016_10161501_182_dialog_content = "萊因哈特，對阿克希亞說了相似的話。",
  ui_story_1016_10161501_183_dialog_content = "我聽說了，她……主動認輸。",
  ui_story_1016_10161501_184_dialog_content = "所以妳才能活下來。",
  ui_story_1016_10161501_185_dialog_content = "對了，這是妳的勝利獎牌。",
  ui_story_1016_10161501_186_dialog_content = "之前啟光亂成一團，妳又暈倒了，都來不及舉行頒獎儀式。",
  ui_story_1016_10161501_187_dialog_content = "現在補給妳吧。",
  ui_story_1016_10161501_188_dialog_content = "獎牌，沉甸甸的。",
  ui_story_1016_10161501_189_dialog_content = "……",
  ui_story_1016_10161501_190_dialog_content = "阿克希亞，想問鶯歌一個問題。",
  ui_story_1016_10161501_191_dialog_content = "什麼問題？",
  ui_story_1016_10161501_192_dialog_content = "在決賽場上，萊因哈特對阿克希亞說——",
  ui_story_1016_10161501_193_dialog_content = "希望阿克希亞作為一個人，活下去。",
  ui_story_1016_10161501_194_dialog_content = "請告訴阿克希亞，什麼是「<color=#FFB400>作為一個人活下去</color>」。",
  ui_story_1017_10170101_1_dialog_content = "您聽得到我說話嗎，大元帥？",
  ui_story_1017_10170101_2_dialog_content = "可以。",
  ui_story_1017_10170101_3_dialog_content = "那我們現在開始。",
  ui_story_1017_10170101_4_dialog_content = "我是本次案件的主審官，啟光聯邦監察長，涅墨西斯。",
  ui_story_1017_10170101_5_dialog_content = "我將依據啟光聯邦調查法，對您通敵、藏匿通緝犯一案進行第三次內部公審。",
  ui_story_1017_10170101_6_dialog_content = "根據啟光聯邦調查法規定，您有權——",
  ui_story_1017_10170101_7_dialog_content = "虛文就不必念了。",
  ui_story_1017_10170101_8_dialog_content = "下面開始正式審問，關於尤利西斯對您提出的指控，您是否有要陳述？",
  ui_story_1017_10170101_9_dialog_content = "再次重申，軍演期間，吞羅在迦南城藏匿的事情我並不知情。",
  ui_story_1017_10170101_10_dialog_content = "我和她之間沒有任何形式的通敵行為。",
  ui_story_1017_10170101_11_dialog_content = "由於您在三次審訊會上的陳述一致，我無法做出對您有利的判決。",
  ui_story_1017_10170101_12_dialog_content = "你們要的不就是這個結果嗎？",
  ui_story_1017_10170101_13_dialog_content = "不如直接把劍亮出來，你們的目的是什麼？",
  ui_story_1017_10170101_14_dialog_content = "主審官，請允許我補充證詞。",
  ui_story_1017_10170101_15_dialog_content = "請發言。",
  ui_story_1017_10170101_16_dialog_content = "情報顯示，軍演前吞羅與萊因哈特曾在「X號研究院」進行一場交易：",
  ui_story_1017_10170101_17_dialog_content = "萊因哈特答應吞羅，只要留下赫利俄斯，就能讓吞羅離開。",
  ui_story_1017_10170101_18_dialog_content = "鶯歌和阿納托利能夠作證。",
  ui_story_1017_10170101_19_dialog_content = "主審官——",
  ui_story_1017_10170101_20_dialog_content = "<size=30>雷霆，不要插話。</size>",
  ui_story_1017_10170101_21_dialog_content = "請鶯歌中校發言。",
  ui_story_1017_10170101_22_dialog_content = "妳只需要回答主審官，吞羅是否有與萊因哈特交易。",
  ui_story_1017_10170101_23_dialog_content = "……是。",
  ui_story_1017_10170101_24_dialog_content = "妳——",
  ui_story_1017_10170101_25_dialog_content = "閉嘴，表態只會對大元帥不利。",
  ui_story_1017_10170101_26_dialog_content = "達成交易後，萊因哈特念及同窗舊情，採取消極行動。",
  ui_story_1017_10170101_27_dialog_content = "她帶援軍接應通緝犯離開，因此導致「守護者一號」的核心被盜。",
  ui_story_1017_10170101_28_dialog_content = "大元帥，您是否認罪？",
  ui_story_1017_10170101_29_dialog_content = "「守護者一號」的核心被盜我有責任，但除此之外的指控請拿出證據。",
  ui_story_1017_10170101_30_dialog_content = "阿納托利。",
  ui_story_1017_10170101_31_dialog_content = "長官，我？",
  ui_story_1017_10170101_32_dialog_content = "萊因哈特是否對吞羅和赫利俄斯說過「我帶著援軍來接你們了」？",
  ui_story_1017_10170101_33_dialog_content = "……",
  ui_story_1017_10170101_34_dialog_content = "有還是沒有？",
  ui_story_1017_10170101_35_dialog_content = "有……",
  ui_story_1017_10170101_36_dialog_content = "大元帥，請您對以上證據作出陳述或抗辯。",
  ui_story_1017_10170101_37_dialog_content = "……",
  ui_story_1017_10170101_38_dialog_content = "我的證據展示完了，主審官。",
  ui_story_1017_10170101_39_dialog_content = "（當時的情況不是這樣……）",
  ui_story_1017_10170101_40_dialog_content = "（等等！證人是我和鶯歌中校的話……）",
  ui_story_1017_10170101_41_dialog_content = "大元帥，對於以上指控，您是否認罪？還有話要補充嗎？",
  ui_story_1017_10170101_42_dialog_content = "呵，啟光會變成今天這副模樣是我失職，我認！",
  ui_story_1017_10170101_43_dialog_content = "如果非要我說——",
  ui_story_1017_10170101_44_dialog_content = "哈哈哈哈！",
  ui_story_1017_10170101_45_dialog_content = "我說完了，主審官，宣判吧。",
  ui_story_1017_10170101_46_dialog_content = "……",
  ui_story_1017_10170101_47_dialog_content = "關於萊因哈特案件的三次審查結果，我宣布——",
  ui_story_1017_10170101_48_dialog_content = "原啟光聯邦大元帥萊因哈特被指控：",
  ui_story_1017_10170101_49_dialog_content = "於軍演期間利用職位之便，與潛入啟光地下城的通緝犯吞羅暗中交易。",
  ui_story_1017_10170101_50_dialog_content = "導致「守護者一號」的核心被盜、78名啟光士兵和家屬受傷，對啟光聯邦的安全造成重大影響。",
  ui_story_1017_10170101_51_dialog_content = "對此，萊因哈特承認失職。",
  ui_story_1017_10170101_52_dialog_content = "但因證據不足，針對藏匿敵人的指控，待當事人具備審訊條件或雙方出具充足證據後，再進一步審查。",
  ui_story_1017_10170101_53_dialog_content = "依照啟光聯邦調查法，監察部門做出如下判決：",
  ui_story_1017_10170101_54_dialog_content = "撤銷萊因哈特大元帥的職位。",
  ui_story_1017_10170101_55_dialog_content = "剝奪萊因哈特啟光軍人權力。",
  ui_story_1017_10170101_56_dialog_content = "即刻起，將萊因哈特關押至啟光監獄。",
  ui_story_1017_10170101_57_dialog_content = "以上。",
  ui_story_1017_10170101_58_dialog_content = "出來了出來了——",
  ui_story_1017_10170101_59_dialog_content = "長、長官好！",
  ui_story_1017_10170101_60_dialog_content = "唔……",
  ui_story_1017_10170101_61_dialog_content = "<size=30>她是誰？</size>",
  ui_story_1017_10170101_62_dialog_content = "貝利撒留長官，她在委員會中似乎有很大的話語權。",
  ui_story_1017_10170101_63_dialog_content = "我剛才都緊張到忘記敬禮了。",
  ui_story_1017_10170101_64_option_content = "連我都緊張起來了",
  ui_story_1017_10170101_65_option_content = "妳完了",
  ui_story_1017_10170101_66_dialog_content = "喂，你能不能說點好話啊？",
  ui_story_1017_10170101_67_dialog_content = "現在過去敬禮已經來不及了……",
  ui_story_1017_10170101_68_dialog_content = "……",
  ui_story_1017_10170101_69_dialog_content = "連她都來了，大元帥的事情不知道還有沒有轉機。",
  ui_story_1017_10170101_70_dialog_content = "剛才是我沒注意。",
  ui_story_1017_10170101_71_dialog_content = "你就是那位空裔吧？",
  ui_story_1017_10170101_72_dialog_content = "是的……長官。",
  ui_story_1017_10170101_73_dialog_content = "貝利撒留長官！",
  ui_story_1017_10170101_74_dialog_content = "聽說妳和空裔、白夜城的同伴一起參加了聯合軍演。",
  ui_story_1017_10170101_75_dialog_content = "是的，長官。",
  ui_story_1017_10170101_76_dialog_content = "呵呵，不錯……",
  ui_story_1017_10170101_77_dialog_content = "看到你們，我總有一種說不上來的感覺。",
  ui_story_1017_10170101_78_dialog_content = "很快，你們就會去驗證我的猜想對不對。",
  ui_story_1017_10170101_79_dialog_content = "我先走了，空裔，下次見面會是個正式的場合。",
  ui_story_1017_10170101_80_dialog_content = "……",
  ui_story_1017_10170101_81_dialog_content = "嚇、嚇死我了……",
  ui_story_1017_10170101_82_dialog_content = "這次不是有敬禮了嗎？",
  ui_story_1017_10170101_83_dialog_content = "我總覺得貝利撒留長官看我們的眼神很奇怪。",
  ui_story_1017_10170101_84_dialog_content = "也許是我想太多了吧……",
  ui_story_1017_10170101_85_dialog_content = "欸，是將軍們——緋長官！",
  ui_story_1017_10170101_86_dialog_content = "……",
  ui_story_1017_10170101_87_dialog_content = "這裡似乎不是說話的地方。",
  ui_story_1017_10170101_88_dialog_content = "他們的表情都好凝重啊……",
  ui_story_1017_10170101_89_dialog_content = "PlayerName、薇絲中尉。",
  ui_story_1017_10170101_90_dialog_content = "阿納托利！情況怎麼樣了？",
  ui_story_1017_10170101_91_dialog_content = "……",
  ui_story_1017_10170101_92_dialog_content = "我們找個安靜的地方再說吧。",
  ui_story_1017_10170101_93_dialog_content = "各位長官，邊境暗鬼活動頻繁，情況已經持續多日。",
  ui_story_1017_10170101_94_dialog_content = "我們已經讓<color=#FFB400>「暗面偵察隊」</color>根據探測資料，即時調整偵察戰略。",
  ui_story_1017_10170101_95_dialog_content = "回測資料縱向對比結果顯示，<color=#FFB400>極光紊亂</color>頻率為近二十年來最高。",
  ui_story_1017_10170101_96_dialog_content = "這意味著日蝕很有可能正在醞釀一場暗潮危機。",
  ui_story_1017_10170101_97_dialog_content = "都聽到了吧？",
  ui_story_1017_10170101_98_dialog_content = "上一次暗潮危機來臨時，坐在這裡的就是我們這些人。",
  ui_story_1017_10170101_99_dialog_content = "多年過去了，大家沉默了許多。",
  ui_story_1017_10170101_100_dialog_content = "暗潮湧動與「守護者一號」核心被盜一事有關嗎？",
  ui_story_1017_10170101_101_dialog_content = "最近日蝕的一系列動作足以證明兩件事情的關係。",
  ui_story_1017_10170101_102_dialog_content = "只是這一次，他們拿到了「守護者一號」的核心，局面會略微不同。",
  ui_story_1017_10170101_103_dialog_content = "追蹤情況如何？",
  ui_story_1017_10170101_104_dialog_content = "剛才的報告你們也聽到了，一支精銳的「暗面偵察隊」已經出發。",
  ui_story_1017_10170101_105_dialog_content = "一支精銳的「暗面偵察隊」？",
  ui_story_1017_10170101_106_dialog_content = "如果是她的話，配得上「精銳」二字。",
  ui_story_1017_10170101_107_dialog_content = "追蹤罪靈，拿回「守護者一號」的事不是由艾森負責嗎？",
  ui_story_1017_10170101_108_dialog_content = "他如果能負責，我就不會讓「佩皮塔」出場了。",
  ui_story_1017_10170101_109_dialog_content = "那個從啟光叛逃，後來加入真理結社的囚犯？",
  ui_story_1017_10170101_110_dialog_content = "囚犯？",
  ui_story_1017_10170101_111_dialog_content = "各位的反應是不是有點太激動了？",
  ui_story_1017_10170101_112_dialog_content = "她現在應該在監牢裡。",
  ui_story_1017_10170101_113_dialog_content = "養兵千日，用在一時。",
  ui_story_1017_10170101_114_dialog_content = "她有深入暗面的經歷，某種程度上來說，這個任務只有她能完成。",
  ui_story_1017_10170101_115_dialog_content = "貝利撒留，委員會並沒有賦予妳組織、訓練私兵的權限。",
  ui_story_1017_10170101_116_dialog_content = "但改造、利用在押囚犯是我的職責。",
  ui_story_1017_10170101_117_dialog_content = "另一支隊伍什麼時候出發？",
  ui_story_1017_10170101_118_dialog_content = "長官，隊員資料已整理完畢，您隨時可以下達命令，最快明天能出發。",
  ui_story_1017_10170101_119_dialog_content = "還有另一支隊伍？",
  ui_story_1017_10170101_120_dialog_content = "調查結果顯示，薇絲中尉與本次潛入迦南城的日蝕成員之間有特殊聯繫。",
  ui_story_1017_10170101_121_dialog_content = "此外，參加軍演的三名影鎮隊員也為日蝕成員的行蹤提供了不同程度的線索。",
  ui_story_1017_10170101_122_dialog_content = "結合以上兩點，我們認為他們在追查「守護者一號」的核心上能提供幫助。",
  ui_story_1017_10170101_123_dialog_content = "因此正在籌備一支臨時隊伍，用來補充「暗面偵察隊」。",
  ui_story_1017_10170101_124_dialog_content = "呵，你不會以為那三個走卒真的是從影鎮來的吧？",
  ui_story_1017_10170101_125_dialog_content = "可別被牽著鼻子走了，「鐵面」。",
  ui_story_1017_10170101_126_dialog_content = "我提供搭車之便，自然是因為他們有上路的價值。",
  ui_story_1017_10170101_127_dialog_content = "不如說說你的進展吧。尤利西斯，你的兵器打磨得怎麼樣了？",
  ui_story_1017_10170101_128_dialog_content = "吞羅的「實驗體」已解析完成，我認為是時候重新定義「啟明星計畫」了。",
  ui_story_1017_10170101_129_dialog_content = "「啟明星計畫」2.0啟動後，光靈的戰鬥力會大幅提升。",
  ui_story_1017_10170101_130_dialog_content = "現在正是推選下一任大元帥的時機。",
  ui_story_1017_10170101_131_dialog_content = "有適合的人選嗎？",
  ui_story_1017_10170101_132_dialog_content = "大元帥的人選是計畫上最薄弱的一環。",
  ui_story_1017_10170101_133_dialog_content = "我擔心的是暗潮危機再次降臨，我們束手無策。",
  ui_story_1017_10170101_134_dialog_content = "「人選是最薄弱的一環」？",
  ui_story_1017_10170101_135_dialog_content = "我不同意。",
  ui_story_1017_10170101_136_dialog_content = "萊因哈特這幾年累積下來的影響力早已超乎想像。",
  ui_story_1017_10170101_137_dialog_content = "如今這個局面正是「啟明星計畫」造成的，還要繼續嗎？",
  ui_story_1017_10170101_138_dialog_content = "萊因哈特的審訊結果尚無決定性證據支持，相信她被革職只是暫時的。",
  ui_story_1017_10170101_139_dialog_content = "倒是尤利西斯博士是不是有點操之過急了？",
  ui_story_1017_10170101_140_dialog_content = "已成定局的事情，討論沒有意義。",
  ui_story_1017_10170101_141_dialog_content = "妳如果有意見，可以照程序提起訴訟。",
  ui_story_1017_10170101_142_dialog_content = "尤利西斯，你研究之餘也多感受一下外面的風氣。",
  ui_story_1017_10170101_143_dialog_content = "你要吃肉，還會讓牲畜自己走到屠宰場嗎？",
  ui_story_1017_10170101_144_dialog_content = "你要大張旗鼓帶著你的「最強兵器」我沒意見。",
  ui_story_1017_10170101_145_dialog_content = "但是決定推選誰來做大元帥，最好還是照你說的，走程序。",
  ui_story_1017_10170101_146_dialog_content = "好了，我們啟光人一向嗇己奉公，都省省吧。",
  ui_story_1017_10170101_147_dialog_content = "趁大家都在，是該討論大元帥的人選了。",
  ui_story_1017_10170101_148_dialog_content = "文件都傳過去了嗎？",
  ui_story_1017_10170101_149_dialog_content = "嗯，各位長官現在看到的文件，詳細記錄了校級以上軍人的履歷。",
  ui_story_1017_10170101_150_dialog_content = "其中也包含了他們私下的人際關係和同僚評價。",
  ui_story_1017_10170101_151_dialog_content = "啟光建立時，一致決定大元帥必須由最強大的士兵擔任。",
  ui_story_1017_10170101_152_dialog_content = "後來就演變成不成文規定，大元帥的人選必須接受身體機能強化。",
  ui_story_1017_10170101_153_dialog_content = "我對「啟明星計畫」2.0沒有意見，單論能力，能夠擔當大元帥一職的只有那四位將軍。",
  ui_story_1017_10170101_154_dialog_content = "如果要從他們當中重新培養一個萊因哈特，大元帥之位又有什麼撤換的必要？",
  ui_story_1017_10170101_155_dialog_content = "選他們做大元帥，不會有點搬石頭砸自己的腳嗎？",
  ui_story_1017_10170101_156_dialog_content = "尤利西斯，你覺得呢？",
  ui_story_1017_10170101_157_dialog_content = "……",
  ui_story_1017_10170101_158_dialog_content = "如果是他們四位的話，確實有一位合適……",
  ui_story_1017_10170201_1_dialog_content = "誰？進來。",
  ui_story_1017_10170201_2_dialog_content = "那個，緋長官好，各位長官好！",
  ui_story_1017_10170201_3_dialog_content = "各位長官好。",
  ui_story_1017_10170201_4_dialog_content = "抱歉打擾了，我只是來找緋長官的，沒想到各位長官都在……",
  ui_story_1017_10170201_5_dialog_content = "聽說了大元帥的事情，我們想——",
  ui_story_1017_10170201_X5_dialog_content = "<color=#e8d9bb>嗶嗶——</color>",
  ui_story_1017_10170201_6_dialog_content = "……",
  ui_story_1017_10170201_7_dialog_content = "各位，回戰區的命令來了。",
  ui_story_1017_10170201_8_dialog_content = "這麼快？",
  ui_story_1017_10170201_9_dialog_content = "我也收到了，這麼短的任務描述還是頭一次看到。",
  ui_story_1017_10170201_10_dialog_content = "一樣。",
  ui_story_1017_10170201_11_dialog_content = "哼，是在擔心我們一起謀反嗎？",
  ui_story_1017_10170201_12_dialog_content = "我作為啟光聯邦的將軍，是靠打仗走到今天的，要來硬的我在行！",
  ui_story_1017_10170201_13_dialog_content = "謹慎起見，先各自執行任務吧，總之，見機行事。",
  ui_story_1017_10170201_14_dialog_content = "嗯。",
  ui_story_1017_10170201_15_dialog_content = "雷霆，妳呢？",
  ui_story_1017_10170201_X15_dialog_content = "……啊？什麼？",
  ui_story_1017_10170201_X16_dialog_content = "你也收到命令了吧？",
  ui_story_1017_10170201_X17_dialog_content = "……我的近衛軍團一直就是個架子，要打也是你們先上。",
  ui_story_1017_10170201_X18_dialog_content = "有事隨時聯絡，保重。",
  ui_story_1017_10170201_X19_dialog_content = "嗯，保重。",
  ui_story_1017_10170201_16_dialog_content = "我？反正<color=#FFB400>我的近衛軍團就是個架子</color>，要打也是你們先上，我暫時不會離開迦南城。",
  ui_story_1017_10170201_17_dialog_content = "嗯，保重。",
  ui_story_1017_10170201_18_dialog_content = "……",
  ui_story_1017_10170201_19_dialog_content = "全都走了。",
  ui_story_1017_10170201_20_dialog_content = "到底發生什麼事了，連緋長官都……",
  ui_story_1017_10170201_21_dialog_content = "你覺得他們在商量什麼？",
  ui_story_1017_10170201_22_option_content = "謀反",
  ui_story_1017_10170201_23_dialog_content = "感覺得出來他們和高層的關係非常緊張。",
  ui_story_1017_10170201_24_dialog_content = "大元帥發生這種事情後，他們可能會採取行動……",
  ui_story_1017_10170201_25_dialog_content = "噓！這種話怎麼能說！",
  ui_story_1017_10170201_26_option_content = "拯救大元帥",
  ui_story_1017_10170201_27_dialog_content = "大元帥是被陷害的，將軍們肯定得想辦法把她救出來。",
  ui_story_1017_10170201_28_dialog_content = "如果真是這樣，我們能做些什麼呢……",
  ui_story_1017_10170201_29_option_content = "不太清楚",
  ui_story_1017_10170201_30_dialog_content = "他們走得這麼急，應該不是什麼好事。",
  ui_story_1017_10170201_31_dialog_content = "唉，看樣子是白跑一趟了……",
  ui_story_1017_10170201_32_dialog_content = "呼——終於找到妳了，薇絲！",
  ui_story_1017_10170201_33_dialog_content = "有個緊急任務要交給妳！",
  ui_story_1017_10170201_34_dialog_content = "和妳一起出發的隊員就在前面嗎？",
  ui_story_1017_10170201_35_dialog_content = "剛才薇薇安走得好匆忙，交代完事情就離開了。",
  ui_story_1017_10170201_36_dialog_content = "嗯，她的臉色也不太好。啟光……大概是要變天了吧。",
  ui_story_1017_10170201_37_dialog_content = "我現在接收到太多資訊，腦袋有點混亂……",
  ui_story_1017_10170201_38_dialog_content = "甚至還聽到詭異的汽笛聲……",
  ui_story_1017_10170201_39_dialog_content = "我也聽到了……",
  ui_story_1017_10170201_40_dialog_content = "「冥河列車」的乘客們，我已在此恭候多時。",
  ui_story_1017_10170201_41_dialog_content = "卡戎長官！原來是和您一起執行任務。",
  ui_story_1017_10170201_42_dialog_content = "你好，薇絲，還有空裔。",
  ui_story_1017_10170201_43_dialog_content = "你好，薇絲，還有空裔。",
  ui_story_1017_10170201_44_dialog_content = "你好，薇絲，還有空裔。",
  ui_story_1017_10170201_45_dialog_content = "終於到齊了，咳咳——諸位好。",
  ui_story_1017_10170201_46_dialog_content = "你們怎麼會來？",
  ui_story_1017_10170201_47_dialog_content = "哼哼，想不到吧，我們可是<color=#FFB400>「追蹤小隊」</color>的正式成員噢！",
  ui_story_1017_10170201_48_dialog_content = "嗯！這次和大家一起旅行，還請多多指教～",
  ui_story_1017_10170201_49_dialog_content = "卡戎長官……這是怎麼回事？",
  ui_story_1017_10170201_50_dialog_content = "這三位遠客和妳一樣，都是受邀搭乘「冥河列車」的夥伴。",
  ui_story_1017_10170201_51_dialog_content = "夥伴？",
  ui_story_1017_10170201_52_dialog_content = "正是，但你並不在邀請名單上，空裔。",
  ui_story_1017_10170201_53_dialog_content = "請回吧，「冥河列車」要發動了。",
  ui_story_1017_10170201_54_dialog_content = "等一下！請讓我上車！",
  ui_story_1017_10170201_55_dialog_content = "PlayerName，你怎麼也……",
  ui_story_1017_10170201_56_dialog_content = "空裔，告訴我，我為什麼要讓你上車？",
  ui_story_1017_10170201_57_option_content = "我不放心薇絲",
  ui_story_1017_10170201_58_dialog_content = "薇薇安說，這次行動有可能會深入暗面……",
  ui_story_1017_10170201_59_dialog_content = "我擔心軍演上遇到的那個神祕敵人會再次對薇絲不利。",
  ui_story_1017_10170201_60_dialog_content = "所以，請你帶我一起去。",
  ui_story_1017_10170201_61_option_content = "我不放心你",
  ui_story_1017_10170201_62_dialog_content = "薇薇安說啟光組織了一支「追蹤小隊」，沒想到他們三個也在。",
  ui_story_1017_10170201_63_dialog_content = "我擔心他們給你添麻煩，讓我一起去吧。",
  ui_story_1017_10170201_64_dialog_content = "我的夥伴自然不會介意，只是前方有諸多危險。",
  ui_story_1017_10170201_65_dialog_content = "旅途的終點，或許就是生命的終點。",
  ui_story_1017_10170201_66_dialog_content = "請相信我，面對危險我有足夠的經驗！",
  ui_story_1017_10170201_67_dialog_content = "PlayerName……",
  ui_story_1017_10170201_68_dialog_content = "哦！聽到了嗎，「彼岸號」？空裔要和我們一起向地獄前進！",
  ui_story_1017_10170201_69_dialog_content = "倒也不必這麼……",
  ui_story_1017_10170201_70_dialog_content = "很遺憾，沒有受邀的乘客請借過，我們要先出發了。",
  ui_story_1017_10170201_71_dialog_content = "去暗面之前，還有很多準備工作要做。",
  ui_story_1017_10170201_72_dialog_content = "那我先走了，PlayerName。",
  ui_story_1017_10170201_73_option_content = "再見，薇絲",
  ui_story_1017_10170201_74_dialog_content = "你沒有什麼話想對我說嗎？",
  ui_story_1017_10170201_75_dialog_content = "有……",
  ui_story_1017_10170201_76_option_content = "等等，薇絲",
  ui_story_1017_10170201_77_dialog_content = "怎麼了？",
  ui_story_1017_10170201_78_dialog_content = "暗面很危險，妳要保護好自己。",
  ui_story_1017_10170201_79_dialog_content = "我知道，但是每次遇到危險，不是都能化險為夷嘛。",
  ui_story_1017_10170201_80_dialog_content = "那是因為……",
  ui_story_1017_10170201_81_dialog_content = "因為什麼？",
  ui_story_1017_10170201_82_dialog_content = "……總之，我有一股不好的預感……",
  ui_story_1017_10170201_83_dialog_content = "知道啦、知道啦，你是空裔，你的感應能力出眾，如何如何……",
  ui_story_1017_10170201_84_dialog_content = "有卡戎長官在，我相信不會有事的！",
  ui_story_1017_10170201_85_dialog_content = "嗯，如果真的遇到危險，妳可以……喊我的名字！",
  ui_story_1017_10170201_86_dialog_content = "喊你的名字？距離那麼遠，你聽得到嗎？",
  ui_story_1017_10170201_87_dialog_content = "不知道，可以試試。",
  ui_story_1017_10170201_88_dialog_content = "好奇怪喔……那，再見啦。",
  ui_story_1017_10170201_89_dialog_content = "再見，薇絲。",
  ui_story_1017_10170201_90_dialog_content = "<color=#e8d9bb>撲通……撲通……</color>",
  ui_story_1017_10170201_X90_dialog_content = "「VICE」……",
  ui_story_1017_10170201_91_dialog_content = "有什麼想問的，直接問吧。",
  ui_story_1017_10170201_92_dialog_content = "我不理解，斐桀洛為妳效命，為什麼會落得如此下場？",
  ui_story_1017_10170201_93_dialog_content = "自討苦吃的傢伙不會有好結果，不是沒給過他機會。",
  ui_story_1017_10170201_94_dialog_content = "總而言之，事情做得並不漂亮，你們兩個都該死。",
  ui_story_1017_10170201_95_dialog_content = "只可惜，東西到手，任務竟然成功了。",
  ui_story_1017_10170201_96_dialog_content = "已經忙著慶祝了嗎，安妮莫妮？",
  ui_story_1017_10170201_97_dialog_content = "東西拿到了。",
  ui_story_1017_10170201_98_dialog_content = "我看看……嗯，妳知道這是什麼嗎，啟光的小丫頭？",
  ui_story_1017_10170201_99_dialog_content = "不是告訴過你，別那樣叫我。",
  ui_story_1017_10170201_100_dialog_content = "呵呵，天真……說說看吧。",
  ui_story_1017_10170201_101_dialog_content = "一台老舊的機器。搞得這麼難看就是為了這個？",
  ui_story_1017_10170201_102_dialog_content = "沒錯，老舊，但這是屬於<color=#FFB400>「工程師」</color>的東西，只是不小心……落在迦南城了。",
  ui_story_1017_10170201_103_dialog_content = "「工程師」？",
  ui_story_1017_10170201_104_dialog_content = "看來妳是真的不知道呀，啟光的小丫頭。",
  ui_story_1017_10170201_105_dialog_content = "「工程師」比啟光的歷史還要久，沒有它，啟光什麼也不是。",
  ui_story_1017_10170201_106_dialog_content = "你們想做什麼？",
  ui_story_1017_10170201_107_dialog_content = "當然是物歸原主。世界不只是妳看到的這些，「工程師」甦醒後，妳會看到更多。",
  ui_story_1017_10170201_108_dialog_content = "哦，妳不會剛好有興趣為「工程師」的到來鋪一塊「地毯」吧……",
  ui_story_1017_10170201_109_dialog_content = "從日蝕殿堂一直延伸至艾斯特拉腹地——",
  ui_story_1017_10170201_110_dialog_content = "由黑渾的暗能和光靈殘軀鋪成的巨大「地毯」，我想那一定很氣派吧。",
  ui_story_1017_10170201_111_dialog_content = "這對我有什麼好處？",
  ui_story_1017_10170201_112_dialog_content = "好處？替日蝕辦事已經是對妳的恩賜了。",
  ui_story_1017_10170201_113_dialog_content = "別聊個沒完，阿斯摩太，你不用回去交差嗎？",
  ui_story_1017_10170201_114_dialog_content = "妳真的很無趣……",
  ui_story_1017_10170201_115_dialog_content = "這樣如何，妳來當鋪「地毯」的人，我答應妳，事情辦好後，日蝕會有妳的一席之地。",
  ui_story_1017_10170201_116_dialog_content = "哼，你知道鋪「地毯」並不簡單。",
  ui_story_1017_10170201_117_dialog_content = "放心，妳發明的那堆破爛裡有一個還算合適的幫手，我會幫妳帶過來。",
  ui_story_1017_10170201_118_dialog_content = "「工程師」若知道是妳做了這些事，它難道不想見見這位啟光的同胞嗎？",
  ui_story_1017_10170201_119_dialog_content = "事情我會辦好，不過，這個過程中我還有一些私人恩怨要解決。",
  ui_story_1017_10170201_120_dialog_content = "請便。不過吞羅，動作可要快一點，妳啟光的夥伴已經等不及了。",
  ui_story_1017_10170201_121_dialog_content = "不用你說，我察覺到了。",
  ui_story_1017_10170201_122_dialog_content = "專心去做妳的事吧，這群小跳蚤就賞給牠們吃吧。",
  ui_story_1017_10170202_1_dialog_content = "報告隊長，暗鬼已經消滅，危機解除！",
  ui_story_1017_10170202_2_dialog_content = "不是說了別叫隊長嗎？",
  ui_story_1017_10170202_3_dialog_content = "前面趕時間的已經轉移了，你們解決的這些——",
  ui_story_1017_10170202_4_dialog_content = "無！聊！透！頂！",
  ui_story_1017_10170202_5_dialog_content = "可是佩皮塔隊長，我們追蹤的敵人真的很強！",
  ui_story_1017_10170202_6_dialog_content = "剛剛儀表板顯示的暗能已經接近最大值了。",
  ui_story_1017_10170202_7_dialog_content = "所以我說，前面那三隻出現的時候，就應該直接開到牠們臉上去。",
  ui_story_1017_10170202_8_dialog_content = "偏要報告這個，報告那個……毀了興致事小，跟丟敵人你要負責嗎！",
  ui_story_1017_10170202_9_dialog_content = "隊長，我只是按照偵察守則，如實報告每一個發現。",
  ui_story_1017_10170202_10_dialog_content = "例如探測到天氣異常……暗能向大陸腹地蔓延的速度……每前進一公里的座標……",
  ui_story_1017_10170202_11_dialog_content = "好啦好啦，貝利撒留答應過我，不給我設這些規則約束。",
  ui_story_1017_10170202_12_dialog_content = "你們那麼多人，這點情況都報告不過來嗎？",
  ui_story_1017_10170202_13_dialog_content = "這、我……",
  ui_story_1017_10170202_14_dialog_content = "轉換思路，我們的目標是追蹤「守護者一號」的核心，無論如何，拿回東西是最重要的。",
  ui_story_1017_10170202_15_dialog_content = "是，隊長！那我們還是沿著剛剛的方向前進嗎？",
  ui_story_1017_10170202_16_dialog_content = "就快接近暗面了，讓我來吧，這條路我閉著眼睛都會走。",
  ui_story_1017_10170202_17_dialog_content = "這麼快！看來任務進展得很順利！",
  ui_story_1017_10170202_18_dialog_content = "追上容易，拿回東西就要看你們的表現了。",
  ui_story_1017_10170202_19_dialog_content = "先說好，待會再出現拖慢進度的暗鬼，我控制方向，你們下去收拾。",
  ui_story_1017_10170202_20_dialog_content = "任務緊急，我可不會再減速了。",
  ui_story_1017_10170202_21_dialog_content = "是，隊長！",
  ui_story_1017_10170202_22_dialog_content = "再說一遍，我不是你們的隊長！",
  ui_story_1017_10170301_1_dialog_content = "將軍沒有細說，但部分士兵已經調至各個戰區了。",
  ui_story_1017_10170301_2_dialog_content = "可是大元帥的事才剛發生沒多久，怎麼這個時候……",
  ui_story_1017_10170301_3_dialog_content = "是啊，現在沒有大元帥，之後由誰來主持大局……",
  ui_story_1017_10170301_4_dialog_content = "「各位啟光同胞，接下來要宣布一則重要消息——」",
  ui_story_1017_10170301_5_dialog_content = "……",
  ui_story_1017_10170301_6_dialog_content = "「啟光聯邦建立以來，我們一直在歷任大元帥的帶領下抵禦暗鬼入侵。」",
  ui_story_1017_10170301_7_dialog_content = "「我們因共同的理想結成光靈同盟，是大元帥的榮光始終照耀著啟光。」",
  ui_story_1017_10170301_8_dialog_content = "「這也許是我們有史以來最生死攸關的時刻……」",
  ui_story_1017_10170301_9_dialog_content = "「儘管前路黑暗，我們依然要攜手同行。」",
  ui_story_1017_10170301_10_dialog_content = "「在此，我代表啟光聯邦軍事與政務委員會，昭告所有啟光同胞——」",
  ui_story_1017_10170301_11_dialog_content = "「新任啟光大元帥已經蓄勢待發，會繼續履行帶領啟光抵抗暗鬼的使命。」",
  ui_story_1017_10170301_12_dialog_content = "「讓我們一起期待啟光大元帥——」",
  ui_story_1017_10170301_13_dialog_content = "「雷霆，為啟光聯邦開創新的未來！」",
  ui_story_1017_10170301_14_dialog_content = "……雷霆將軍？！",
  ui_story_1017_10170301_15_dialog_content = "我們今後的……大元帥？！",
  ui_story_1017_10170301_16_dialog_content = "果然是雷霆將軍呢～",
  ui_story_1017_10170301_17_dialog_content = "你、你們怎麼……突然都來了？",
  ui_story_1017_10170301_18_dialog_content = "PlayerName，我的部下傳來消息，黃昏鎮遭到暗鬼入侵！",
  ui_story_1017_10170301_19_dialog_content = "這個時候？！",
  ui_story_1017_10170301_20_dialog_content = "是，啟光高層的反應速度非常快，連新的大元帥都任命好了。",
  ui_story_1017_10170301_21_dialog_content = "軍演上的種種跡象、前任大元帥入獄、邊境暗鬼躁動……這一切，不會是巧合。",
  ui_story_1017_10170301_22_dialog_content = "（而薇絲，還去暗面執行任務了……）",
  ui_story_1017_10170301_23_dialog_content = "現在來不及仔細分析了，PlayerName。",
  ui_story_1017_10170301_24_dialog_content = "聽說你的巨像已經修好了，我來找你，是想拜託你載我們回黃昏鎮。",
  ui_story_1017_10170301_25_dialog_content = "這是目前能想到最快的方法。",
  ui_story_1017_10170301_26_dialog_content = "可以是可以……只是臨空者號一直是貢露在調整。",
  ui_story_1017_10170301_27_dialog_content = "所以我來了。",
  ui_story_1017_10170301_28_dialog_content = "雖然對臨空者號的研究還遠遠不夠，但是隨時可以啟航。",
  ui_story_1017_10170301_29_dialog_content = "真的嗎？",
  ui_story_1017_10170301_30_dialog_content = "當然。",
  ui_story_1017_10170301_31_dialog_content = "PlayerName，拜託了！雖然此行並不容易，但黃昏鎮有難，我必須趕回去。",
  ui_story_1017_10170301_32_dialog_content = "那我們立刻出發吧！",
  ui_story_1017_10170301_33_dialog_content = "等等，李奧，你們先回去，我去白夜城試試。",
  ui_story_1017_10170301_34_dialog_content = "白夜城？連卡蓮都無能為力，你去了又有什麼用。",
  ui_story_1017_10170301_35_dialog_content = "我覺得情況不會比這裡更糟了。",
  ui_story_1017_10170301_36_dialog_content = "你們先和PlayerName回去，為了我們共同守護的城鎮，再難我也得去試試。",
  ui_story_1017_10170301_37_dialog_content = "……",
  ui_story_1017_10170301_38_dialog_content = "你真的這麼想？",
  ui_story_1017_10170301_39_dialog_content = "嗯，眼前黃昏鎮有難，「鐵棘騎士團」不能沒有你。",
  ui_story_1017_10170301_40_dialog_content = "相信我，此行的目的是披露黃昏鎮的情況，去白夜城求援也在我的計畫之中。",
  ui_story_1017_10170301_41_dialog_content = "戰場上若少了軍師，你知道會有什麼後果。",
  ui_story_1017_10170301_42_dialog_content = "如果有PlayerName，我想結果是一樣的，甚至會更好。",
  ui_story_1017_10170301_43_dialog_content = "如何？你帶士兵清除暗鬼，我隨後帶回好消息。",
  ui_story_1017_10170301_44_dialog_content = "神父，你覺得呢？",
  ui_story_1017_10170301_45_dialog_content = "我相信軍師辦得到，也相信你和PlayerName辦得到。",
  ui_story_1017_10170301_46_dialog_content = "嗯，我會盡力！",
  ui_story_1017_10170301_47_dialog_content = "那麼就照你說的，我們一言為定。",
  ui_story_1017_10170301_48_dialog_content = "保重。",
  ui_story_1017_10170301_49_dialog_content = "保重。",
  ui_story_1017_10170301_50_dialog_content = "<color=#e8d9bb>與此同時，尤利西斯實驗室……</color>",
  ui_story_1017_10170301_51_dialog_content = "教授，第一批「種子」的定向選擇模擬資料，通過了顯著性檢驗。",
  ui_story_1017_10170301_52_dialog_content = "進度比預想的還快，接下來是不是可以做臨床實驗了？",
  ui_story_1017_10170301_53_dialog_content = "嗯，廣播你也聽到了，新元帥即位，不能有任何閃失。",
  ui_story_1017_10170301_54_dialog_content = "是，教授，您做的科學實驗從未有過任何問題。",
  ui_story_1017_10170301_55_dialog_content = "呵呵，過去的事情就不用提了。",
  ui_story_1017_10170301_56_dialog_content = "博士果然謙虛，看來一切都在計畫中。",
  ui_story_1017_10170301_57_dialog_content = "你先出去吧。",
  ui_story_1017_10170301_58_dialog_content = "是，教授。",
  ui_story_1017_10170301_59_dialog_content = "想要達到預期的結果，實驗時必須按照期望進行調和。",
  ui_story_1017_10170301_60_dialog_content = "雷霆是你期望的嗎？",
  ui_story_1017_10170301_61_dialog_content = "妳知道我是怎麼想的。",
  ui_story_1017_10170301_62_dialog_content = "我的目的只有一個，只要不威脅到啟光的穩定，任何變動我都可以接受。",
  ui_story_1017_10170301_63_dialog_content = "「啟明星計畫」2.0在你的接受範圍嗎？",
  ui_story_1017_10170301_64_dialog_content = "暗鬼已經打到黃昏鎮了，日蝕的最新動向，彷彿是為你的實驗量身訂做。",
  ui_story_1017_10170301_65_dialog_content = "在對抗暗鬼這件事情上，從來就不可能投機。",
  ui_story_1017_10170301_66_dialog_content = "我早在暗潮危機結束時，就投入光靈身體機能改造的研究。",
  ui_story_1017_10170301_67_dialog_content = "這些年來我逐漸確定，吞羅的「種子」是至關重要的一環。",
  ui_story_1017_10170301_68_dialog_content = "但願你的初衷與我一致，但我還是要提醒你，嫉妒是科學家的毒藥。",
  ui_story_1017_10170301_69_dialog_content = "妳來找我，不是單純為了心理輔導吧？",
  ui_story_1017_10170301_70_dialog_content = "閒聊就改天吧，我想知道妳開展「啟明星計畫」2.0的計畫和我一樣嗎？",
  ui_story_1017_10170301_71_dialog_content = "畢竟大元帥最好的就任儀式，就是打一場勝仗。",
  ui_story_1017_10170301_72_dialog_content = "不僅雷霆，我希望她的軍團也以嶄新的面貌走上戰場。",
  ui_story_1017_10170301_73_dialog_content = "呵呵，「鐵面」，我覺得妳不像妳的稱號一樣鐵板一塊。",
  ui_story_1017_10170301_74_dialog_content = "榮譽、風采、眾人的仰望，倘若妳來當大元帥，局面會更好看吧。",
  ui_story_1017_10170301_75_dialog_content = "四十年的工作經歷讓我相信，最難的挑戰不在進攻，而在防守。",
  ui_story_1017_10170301_76_dialog_content = "當然年輕人有年輕人的命運，我們要為他們的成長提供舞台。",
  ui_story_1017_10170301_77_dialog_content = "那就讓黃昏鎮成為「啟明星計畫」2.0的舞台吧。",
  ui_story_1017_10170301_78_dialog_content = "雷霆也好，千千萬萬啟光士兵也好，他們都會參與我的計畫……",
  ui_story_1017_10170301_79_dialog_content = "成為啟光聯邦的「明星」，在黃昏鎮殺出黎明。",
  ui_story_1017_10170301_80_dialog_content = "進來。",
  ui_story_1017_10170301_81_dialog_content = "教授，今天的暗鬼機能實驗就要開始了，您要去觀摩嗎？",
  ui_story_1017_10170301_82_dialog_content = "有興趣嗎，「鐵面」？雖然只是例行記錄暗鬼的能力資料而已。",
  ui_story_1017_10170301_83_dialog_content = "跟你一起去看看吧，我在鐵板凳上坐太久了。",
  ui_story_1017_10170302_1_dialog_content = "進來。",
  ui_story_1017_10170302_2_dialog_content = "長官，大元帥出兵在即，實驗方面還有什麼要做的嗎？",
  ui_story_1017_10170302_3_dialog_content = "這些報告，你先看看。",
  ui_story_1017_10170302_4_dialog_content = "數據看起來……很不錯，長官，您的實驗成功了！",
  ui_story_1017_10170302_5_dialog_content = "感謝您讓我參與了如此浩大的工程。",
  ui_story_1017_10170302_6_dialog_content = "還遠遠不夠。",
  ui_story_1017_10170302_7_dialog_content = "您的意思是……？",
  ui_story_1017_10170302_8_dialog_content = "這只是第一批「種子」，接下來還會有第二批、第三批……",
  ui_story_1017_10170302_9_dialog_content = "這麼說，去黃昏鎮只是對第一批實驗品的檢驗？",
  ui_story_1017_10170302_10_dialog_content = "是的，臨床數據還不錯，但科學研究是個奇蹟與覆滅各占一半的黑箱。",
  ui_story_1017_10170302_11_dialog_content = "在徹底摸清黑箱內的東西前，只能不斷改善實驗。這幾天的數據還不錯。",
  ui_story_1017_10170302_12_dialog_content = "是的，是的，我明白……",
  ui_story_1017_10170302_13_dialog_content = "你心中有疑慮。",
  ui_story_1017_10170302_14_dialog_content = "長官……我有一件事不知道該不該說。",
  ui_story_1017_10170302_15_dialog_content = "但說無妨。",
  ui_story_1017_10170302_16_dialog_content = "城內最近有一些傳言，說士兵們透過注射特殊藥物，獲得了可怕的能力……",
  ui_story_1017_10170302_17_dialog_content = "這不是事實嗎？",
  ui_story_1017_10170302_18_dialog_content = "是一部分事實，但我擔心這會影響到我們後續的計畫。",
  ui_story_1017_10170302_19_dialog_content = "就這些？",
  ui_story_1017_10170302_20_dialog_content = "還有……我擔心我們在萊因哈特公審會上的行為，會留下隱患。",
  ui_story_1017_10170302_21_dialog_content = "呵呵，我知道你想說什麼，艾森。",
  ui_story_1017_10170302_22_dialog_content = "你身為委員會裡的年輕成員，看到的事物有限。",
  ui_story_1017_10170302_23_dialog_content = "長官，我不懂您的意思。",
  ui_story_1017_10170302_24_dialog_content = "我在你這個年紀，和你的顧慮是一樣的。",
  ui_story_1017_10170302_25_dialog_content = "遵循準確無誤的實驗步驟，對所有可能出現的結果做好備選方案……",
  ui_story_1017_10170302_26_dialog_content = "我當時十分享受這種一切盡在掌控中的感覺。",
  ui_story_1017_10170302_27_dialog_content = "但是這種所謂的「完美主義」，讓我失去了很多。",
  ui_story_1017_10170302_28_dialog_content = "失去了什麼？",
  ui_story_1017_10170302_29_dialog_content = "突破、意外，一切被稱為奇蹟的東西。",
  ui_story_1017_10170302_30_dialog_content = "可是長官，「規則、計畫、執行、復盤」，這不是我們啟光人從小熟悉的方法論嗎？",
  ui_story_1017_10170302_31_dialog_content = "還是那句話，你還年輕，你應該摸索出自己的生存之道。",
  ui_story_1017_10170302_32_dialog_content = "秩序是荒誕的理想，混沌才是世界的本質。",
  ui_story_1017_10170302_33_dialog_content = "……",
  ui_story_1017_10170302_34_dialog_content = "長官，成為啟光最優秀的科學家，是您的理想嗎？",
  ui_story_1017_10170302_35_dialog_content = "我現在不是嗎？",
  ui_story_1017_10170302_36_dialog_content = "您是！",
  ui_story_1017_10170302_37_dialog_content = "隨我去看看下一批「種子」吧。",
  ui_story_1017_10170302_38_dialog_content = "好的，長官。",
  ui_story_1017_10170401_1_dialog_content = "「今天，雷霆大元帥將帶領近衛軍團支援黃昏鎮，鎮壓暗鬼。」",
  ui_story_1017_10170401_2_dialog_content = "「這也是大元帥上任後首次亮相。」",
  ui_story_1017_10170401_3_dialog_content = "「據瞭解，要成為啟光近衛軍團的菁英戰士，必須經過嚴苛的訓練選拔。」",
  ui_story_1017_10170401_4_dialog_content = "「不少士兵還會駕駛啟光新型武器「引擎七號」進行戰鬥。」",
  ui_story_1017_10170401_5_dialog_content = "「緋將軍率領的第三軍團已集結完畢。」",
  ui_story_1017_10170401_6_dialog_content = "「眾多啟光軍人和居民都自發集結，等待大元帥登場。」",
  ui_story_1017_10170401_7_dialog_content = "快看快看！來了——",
  ui_story_1017_10170401_8_dialog_content = "這陣仗，好有壓迫感……",
  ui_story_1017_10170401_9_dialog_content = "「雷霆大元帥率領近衛軍團走來，啟光同胞們抱以最熱烈的歡迎！」",
  ui_story_1017_10170401_10_dialog_content = "「大元帥和戰士的神情彷彿勝券在握，還沒出兵，勝似凱旋。」",
  ui_story_1017_10170401_11_dialog_content = "「除了雷霆大元帥之外，這次呼聲最高的「引擎七號」，是貢露科研長團隊研發的。」",
  ui_story_1017_10170401_12_dialog_content = "「據說它的誕生經歷了不少波折。今天，我會在現場為大家帶來更多詳細報導。」",
  ui_story_1017_10170401_13_dialog_content = "——噢！好痛……",
  ui_story_1017_10170401_14_dialog_content = "抱歉……",
  ui_story_1017_10170401_15_dialog_content = "欸，我知道您，您是表演賽上獲勝的阿克希亞！",
  ui_story_1017_10170401_16_dialog_content = "原來您是近衛軍團的戰士！比萊因哈特大元帥還厲害！",
  ui_story_1017_10170401_17_dialog_content = "「戰鬥機器」阿克希亞是為啟光而生的。",
  ui_story_1017_10170401_18_dialog_content = "近衛軍團……全是這樣的「怪物」？",
  ui_story_1017_10170401_19_dialog_content = "他們的體格和我們完全不一樣……",
  ui_story_1017_10170401_20_dialog_content = "要帶領這樣的士兵作戰，雷霆大元帥真不簡單……",
  ui_story_1017_10170401_21_dialog_content = "嗯，看得出來，她比萊因哈特大元帥還要強！",
  ui_story_1017_10170401_22_dialog_content = "不過，你有看到緋將軍的表情嗎，好嚴肅……",
  ui_story_1017_10170401_23_dialog_content = "緋將軍一直都很嚴肅。",
  ui_story_1017_10170401_24_dialog_content = "你們這音量，大元帥是聽不到的啦。",
  ui_story_1017_10170401_25_dialog_content = "長、長官大人！我們只是……",
  ui_story_1017_10170401_26_dialog_content = "去向你們軍團長解釋吧，我先記下了。",
  ui_story_1017_10170401_27_dialog_content = "長官……",
  ui_story_1017_10170401_28_dialog_content = "鶯歌中校怎麼會在這裡，不想錯過新任大元帥亮相？",
  ui_story_1017_10170401_29_dialog_content = "我只是擔心阿克希亞。",
  ui_story_1017_10170401_30_dialog_content = "她可是尤利西斯的得意之作，有什麼好擔心的。",
  ui_story_1017_10170401_31_dialog_content = "在那次決鬥中，阿克希亞已經到極限了，但尤利西斯教授似乎不這麼認為……",
  ui_story_1017_10170401_32_dialog_content = "妳能讀懂他的想法，不錯呀。",
  ui_story_1017_10170401_33_dialog_content = "雖然這麼說對參加「啟明星計畫」的士兵並不公平，但尤利西斯教授確實犧牲了很多。",
  ui_story_1017_10170401_34_dialog_content = "把光靈當作兵器送上戰場就不是犧牲？尤利西斯的實驗根本是在動搖啟光的根基！",
  ui_story_1017_10170401_35_dialog_content = "這個由光靈血肉之軀建立的聯邦危在旦夕，你、你們還要袒護他！",
  ui_story_1017_10170401_36_dialog_content = "血肉之軀……難道妳以為，血肉之軀能抵擋暗鬼嗎？",
  ui_story_1017_10170401_37_dialog_content = "只有血肉之軀當然不能抵擋暗鬼。",
  ui_story_1017_10170401_38_dialog_content = "但在無數次與暗鬼的對抗中，我們從未像今天這樣，放棄身為光靈的尊嚴，去證明我們的強大。",
  ui_story_1017_10170401_39_dialog_content = "阿克希亞、士兵，包括妳所做的犧牲，不會換來啟光的安寧，只會讓大家更懼怕暗鬼。",
  ui_story_1017_10170401_40_dialog_content = "這根本就是在向牠們屈服！",
  ui_story_1017_10170401_41_dialog_content = "我討厭戰爭，我也不會屈服。如果啟光需要我，我會為啟光而戰。",
  ui_story_1017_10170401_42_dialog_content = "記住妳說的話，鶯歌中校，好好看看這些即將走上戰場的士兵吧。",
  ui_story_1017_10170401_43_dialog_content = "他們或許不知道自己所做的犧牲，阿克希亞也是，但是妳知道。",
  ui_story_1017_10170401_44_dialog_content = "……",
  ui_story_1017_10170401_45_dialog_content = "「雷霆大元帥來到了近衛軍團前方——」",
  ui_story_1017_10170401_46_dialog_content = "所有啟光軍人聽令！",
  ui_story_1017_10170401_47_dialog_content = "我——啟光聯邦大元帥雷霆在此宣布：",
  ui_story_1017_10170401_48_dialog_content = "暗鬼入侵黃昏鎮，肆虐我們的光靈同胞，今日我們將前往黃昏鎮，將暗鬼全部擊退！",
  ui_story_1017_10170401_49_dialog_content = "近衛軍團今日全軍集結，代表了啟光最強戰力，你們將率先與我榮譽出戰。",
  ui_story_1017_10170401_50_dialog_content = "這一仗無論如何都要贏！一切為了啟明之光！",
  ui_story_1017_10170401_51_dialog_content = "為了啟明之光！！！",
  ui_story_1017_10170401_52_dialog_content = "第三軍團長——緋，聽令！",
  ui_story_1017_10170401_53_dialog_content = "在！",
  ui_story_1017_10170401_54_dialog_content = "整頓隊伍，確立職責，等候差遣。",
  ui_story_1017_10170401_55_dialog_content = "是！",
  ui_story_1017_10170401_56_dialog_content = "近衛軍團，出發！",
  ui_story_1017_10170401_57_dialog_content = "是！！！",
  ui_story_1017_10170401_58_dialog_content = "我們竟然是……等候差遣？",
  ui_story_1017_10170401_59_dialog_content = "這氣勢……好嚇人！",
  ui_story_1017_10170401_60_dialog_content = "她剛剛摸了領章，是嗎？",
  ui_story_1017_10170401_61_dialog_content = "嗯，看到了。",
  ui_story_1017_10170401_62_dialog_content = "無論如何，她已經做到了。",
  ui_story_1017_10170401_63_dialog_content = "嗯，只是不知道她現在在想些什麼……",
  ui_story_1017_10170401_64_dialog_content = "……",
  ui_story_1017_10170401_65_dialog_content = "（大元帥「號令全軍」，原來是這種感覺。）",
  ui_story_1017_10170401_66_dialog_content = "（萊因哈特，這些年來，妳已經習慣了吧……）",
  ui_story_1017_10170401_67_dialog_content = "（妳第一次站上這個位置時，在想什麼呢？）",
  ui_story_1017_10170401_68_dialog_content = "（是早知道大元帥之位非妳莫屬，還是感嘆自己超乎常人的努力和犧牲終於得到了回報呢……）",
  ui_story_1017_10170401_69_dialog_content = "我覺得妳很強，我們交個朋友吧。",
  ui_story_1017_10170401_70_dialog_content = "朋友？我不需要，我只需要練習。",
  ui_story_1017_10170401_71_dialog_content = "（我時時刻刻提醒自己，被友情束縛會變得軟弱，我不想和妳成為朋友。）",
  ui_story_1017_10170401_72_dialog_content = "（於是我以成為大元帥為目標，不停訓練自己。）",
  ui_story_1017_10170401_73_dialog_content = "（但當我以為，我已經站得夠高的時候……）",
  ui_story_1017_10170401_74_dialog_content = "這些是科研部最新研發的導能裝置，請萊因哈特來為大家展示一下吧。",
  ui_story_1017_10170401_75_dialog_content = "她？",
  ui_story_1017_10170401_76_dialog_content = "你們當中只有她能完美控制。",
  ui_story_1017_10170401_77_dialog_content = "……",
  ui_story_1017_10170401_78_dialog_content = "（控制導能裝置是嗎？沒關係，我可以花十倍的時間做到完美。）",
  ui_story_1017_10170401_79_dialog_content = "（等到正式作戰演習時，我和妳之間不會再有差距。）",
  ui_story_1017_10170401_80_dialog_content = "萊因哈特、雷霆妳們二人一組，由萊因哈特來傳達作戰指令。",
  ui_story_1017_10170401_81_dialog_content = "長官！我為什麼不行？",
  ui_story_1017_10170401_82_dialog_content = "傳達作戰指令關係到團員的生命安全。",
  ui_story_1017_10170401_83_dialog_content = "在行動中，多多總結領導團隊的要領吧。",
  ui_story_1017_10170401_84_dialog_content = "……",
  ui_story_1017_10170401_85_dialog_content = "（領導團隊、負責隊員的安全……我不斷摸索進步，逐漸有了追隨我的部下。）",
  ui_story_1017_10170401_86_dialog_content = "恭喜第一軍團的雷霆榮升上尉，以後的任務也要好好表現。",
  ui_story_1017_10170401_87_dialog_content = "（一切都很順利，我只需等待一個能證明自己的機會。）",
  ui_story_1017_10170401_88_dialog_content = "（偏偏暗鬼進攻19號地下城時……）",
  ui_story_1017_10170401_89_dialog_content = "（我第一個接到支援行動訊號，妳卻搶走任務，立下了戰功……）",
  ui_story_1017_10170401_90_dialog_content = "獲得這枚啟光貢獻勳章的是——萊因哈特！",
  ui_story_1017_10170401_91_dialog_content = "（妳總是先發制人，甚至因為妳的出色，選拔考核中增加了許多無用的指標。）",
  ui_story_1017_10170401_92_dialog_content = "（在戰場外大展宏圖不是我追求的，戰士就應該用戰士的方式一決高下！）",
  ui_story_1017_10170401_93_dialog_content = "（於是我想清楚了，我沒有理由繼續等待，我要向妳發起挑戰！）",
  ui_story_1017_10170401_94_dialog_content = "現在不是意氣用事的時候，周圍的暗鬼還很多！",
  ui_story_1017_10170401_95_dialog_content = "少廢話，把妳的武器舉起來，要不殺了我，要不承認我比妳強。",
  ui_story_1017_10170401_96_dialog_content = "幼稚。",
  ui_story_1017_10170401_97_dialog_content = "躲開——",
  ui_story_1017_10170401_98_dialog_content = "用不著替我打暗鬼，我叫妳把槍對準我！",
  ui_story_1017_10170401_99_dialog_content = "我再說一次，不要意氣用事，專心作戰！",
  ui_story_1017_10170401_100_dialog_content = "找死——",
  ui_story_1017_10170401_101_dialog_content = "消滅暗鬼後，妳接受我的挑戰嗎？",
  ui_story_1017_10170401_102_dialog_content = "只要妳能活下來，隨妳便。",
  ui_story_1017_10170401_103_dialog_content = "好！",
  ui_story_1017_10170401_104_dialog_content = "暗鬼！休想擋我的路！",
  ui_story_1017_10170502_1_dialog_content = "（好熟悉的感覺……每次向妳發起挑戰，我幾乎都以這個姿勢收場。）",
  ui_story_1017_10170502_2_dialog_content = "（無論訓練還實戰，一次都沒有輸過，妳到底是怎麼做到的？）",
  ui_story_1017_10170502_3_dialog_content = "（帶著這樣的疑問，我和妳在大元帥最終選拔賽上展開對決……）",
  ui_story_1017_10170502_4_dialog_content = "我們的優勝者——萊因哈特！",
  ui_story_1017_10170502_5_dialog_content = "恭喜萊因哈特成為啟光聯邦的大元帥！",
  ui_story_1017_10170502_6_dialog_content = "萊因哈特大元帥！",
  ui_story_1017_10170502_7_dialog_content = "雷霆雖然失敗了，但仍然是一名實力相當的啟光軍人。",
  ui_story_1017_10170502_8_dialog_content = "（我不服輸，我還沒敗！）",
  ui_story_1017_10170502_9_dialog_content = "（我要再次向妳發起挑戰！）",
  ui_story_1017_10170502_10_dialog_content = "（十次不行就一百次，一百次不行就一千次！）",
  ui_story_1017_10170502_11_dialog_content = "我們回去吧。之前聽廣播說今天天氣不好，現在地面上應該在下雨吧。",
  ui_story_1017_10170502_12_dialog_content = "妳不需要可憐一個手下敗將。",
  ui_story_1017_10170502_13_dialog_content = "對我來說，妳不是手下敗將，是我的朋友。",
  ui_story_1017_10170502_14_dialog_content = "朋友？",
  ui_story_1017_10170502_15_dialog_content = "是的，互相阻礙並互相超越的朋友。",
  ui_story_1017_10170502_16_dialog_content = "誰當妳是朋友？我們從來就不是朋友。",
  ui_story_1017_10170502_17_dialog_content = "（我沒有朋友，只有妳這個唯一的目標。）",
  ui_story_1017_10170502_18_dialog_content = "我們的決鬥僅僅是為了啟光的未來，握拳的時候應該打向共同的敵人。",
  ui_story_1017_10170502_19_dialog_content = "妳的未來會在掌心中湧現，一直緊握拳頭，妳將一無所有。",
  ui_story_1017_10170502_20_dialog_content = "握著妳的啟光大元帥臂章慶祝去吧，我會繼續挑戰妳。",
  ui_story_1017_10170502_21_dialog_content = "即便是大元帥，我也不會對妳客氣。",
  ui_story_1017_10170502_22_dialog_content = "只要妳贏過我，大元帥的位置就給妳。",
  ui_story_1017_10170502_23_dialog_content = "妳敢肯定，妳今後的生命中會一直贏我嗎？",
  ui_story_1017_10170502_24_dialog_content = "……",
  ui_story_1017_10170502_25_dialog_content = "妳敢嗎？",
  ui_story_1017_10170502_26_dialog_content = "我敢。",
  ui_story_1017_10170502_27_dialog_content = "那就不要放鬆警惕，接下來的日子，我會無止境地向妳發起挑戰。",
  ui_story_1017_10170502_28_dialog_content = "無論是大元帥的位置，還是其他什麼，我都會一一取代妳！",
  ui_story_1017_10170502_29_dialog_content = "（誰能想到，如今我取代了妳，卻是以我最不想要的方式。）",
  ui_story_1017_10170502_30_dialog_content = "（呵……歡呼聲和詆毀聲我都聽到了，但是我可不像妳一樣任人擺布。）",
  ui_story_1017_10170502_31_dialog_content = "（那些想在我身上驗證什麼的人，只會看到另一個——）",
  ui_story_1017_10170502_32_dialog_content = "（桀驁不馴的「大元帥」。）",
  ui_story_1017_10170601_1_dialog_content = "<color=#e8d9bb>黃昏鎮上，大量居民正向醫院移動……</color>",
  ui_story_1017_10170601_2_dialog_content = "再堅持一下，前面就是<color=#FFB400>醫院</color>了。",
  ui_story_1017_10170601_3_dialog_content = "我的腳實在動不了了……",
  ui_story_1017_10170601_4_dialog_content = "我背妳走，現在週邊戰區全是暗鬼，誰知道會不會打到這裡來。",
  ui_story_1017_10170601_5_dialog_content = "啊！痛痛痛——",
  ui_story_1017_10170601_6_dialog_content = "把她放在擔架上吧。",
  ui_story_1017_10170601_7_dialog_content = "嗯？妳們是……",
  ui_story_1017_10170601_8_dialog_content = "小心，別晃到她的腳。",
  ui_story_1017_10170601_9_dialog_content = "知道了，喬瑟琳姐姐。",
  ui_story_1017_10170601_10_dialog_content = "妳們是醫院的工作人員吧？",
  ui_story_1017_10170601_11_dialog_content = "你好，我叫喬瑟琳，我身邊這位是醫院的護士。",
  ui_story_1017_10170601_12_dialog_content = "你們好，我是阿奇。",
  ui_story_1017_10170601_13_dialog_content = "阿奇，年紀這麼小卻非常能幹啊。",
  ui_story_1017_10170601_14_dialog_content = "嘿嘿！",
  ui_story_1017_10170601_15_dialog_content = "喬瑟琳……",
  ui_story_1017_10170601_16_dialog_content = "啊！您不會是……白夜教區的「聖女」大人吧！",
  ui_story_1017_10170601_17_dialog_content = "「聖女」？！",
  ui_story_1017_10170601_18_dialog_content = "不不……我不是「聖女」，我只是個普通百姓。",
  ui_story_1017_10170601_19_dialog_content = "什麼是「聖女」啊，喬瑟琳姐姐？",
  ui_story_1017_10170601_20_dialog_content = "「聖女」可是守護光之神子民的在世女神啊！",
  ui_story_1017_10170601_21_dialog_content = "只要「聖女」大人在，暗鬼就不敢踏進我們的家園。",
  ui_story_1017_10170601_22_dialog_content = "哇！這是真的嗎，「聖女」喬瑟琳姐姐？",
  ui_story_1017_10170601_23_dialog_content = "我真的不是「聖女」，叫我喬瑟琳就好。",
  ui_story_1017_10170601_24_dialog_content = "我只是相信「光之神」斬斷黑暗，光之民灼爍永恆。",
  ui_story_1017_10170601_25_dialog_content = "為了那一天的到來，我會盡最大的努力。",
  ui_story_1017_10170601_26_dialog_content = "喬瑟琳姐姐，「光之神」什麼的……好難懂。",
  ui_story_1017_10170601_27_dialog_content = "意思是光明會戰勝黑暗，我們都會回到「光之神」的懷抱。",
  ui_story_1017_10170601_28_dialog_content = "喬瑟琳——",
  ui_story_1017_10170601_29_dialog_content = "醫院這邊還好嗎？",
  ui_story_1017_10170601_30_dialog_content = "從來沒有聚集過這麼多人……但是應該還有空間。",
  ui_story_1017_10170601_31_dialog_content = "前線目前怎麼樣了？",
  ui_story_1017_10170601_32_dialog_content = "唉！暗鬼突然進攻，攻勢猛烈，士兵們死傷慘重！",
  ui_story_1017_10170601_33_dialog_content = "現在黃昏鎮週邊已全線崩潰，很多居民都受到襲擊……",
  ui_story_1017_10170601_34_dialog_content = "天啊！！！",
  ui_story_1017_10170601_35_dialog_content = "完了，一切都完了……",
  ui_story_1017_10170601_36_dialog_content = "李奧他們還沒有消息嗎？",
  ui_story_1017_10170601_37_dialog_content = "已經傳信過去很久了，但還沒見到團長人影！",
  ui_story_1017_10170601_38_dialog_content = "我現在打算帶著團長的馬和裝備，去黃昏鎮<color=#FFB400>關口</color>迎接他。",
  ui_story_1017_10170601_39_dialog_content = "團長不在的時候，這匹馬似乎想替團長指揮，衝進戰場，險些被暗鬼傷害。",
  ui_story_1017_10170601_40_dialog_content = "現在「鐵棘騎士團」還在戰鬥……我先走一步，這邊的事情就拜託妳了。",
  ui_story_1017_10170601_41_dialog_content = "白夜至上——",
  ui_story_1017_10170601_42_dialog_content = "阿奇，妳和這位先生一起把受傷的女士送去醫院。",
  ui_story_1017_10170601_43_dialog_content = "之後告訴負責的護士，往黃昏鎮週邊加派醫護人員。",
  ui_story_1017_10170601_44_dialog_content = "喬瑟琳姐姐，妳要去哪裡？",
  ui_story_1017_10170601_45_dialog_content = "去戰場。",
  ui_story_1017_10170601_46_dialog_content = "去戰場？我是說……上戰場的應該是戰士。",
  ui_story_1017_10170601_47_dialog_content = "我就是一名戰士，這個時候，我必須站在那裡。",
  ui_story_1017_10170601_48_dialog_content = "阿奇，拜託妳了，回頭見。",
  ui_story_1017_10170601_49_dialog_content = "……",
  ui_story_1017_10170601_50_dialog_content = "妳可以嗎？",
  ui_story_1017_10170601_51_dialog_content = "不要看我年紀小，我的力氣可是很大的！",
  ui_story_1017_10170601_52_dialog_content = "<color=#e8d9bb>喬瑟琳來到週邊戰區……</color>",
  ui_story_1017_10170601_53_dialog_content = "當心腳下！",
  ui_story_1017_10170601_54_dialog_content = "竭力斬殺！",
  ui_story_1017_10170601_55_dialog_content = "這隻剛剛已經倒下了才對。",
  ui_story_1017_10170601_56_dialog_content = "留心已經倒下的敵人，有時牠們的攻擊才是最致命的。",
  ui_story_1017_10170601_57_dialog_content = "我明白了，謝謝提醒！",
  ui_story_1017_10170601_58_dialog_content = "都是團長教的，只是現在他不在，總覺得少了什麼。",
  ui_story_1017_10170601_59_dialog_content = "大家雖然不說，但心裡肯定很擔心……",
  ui_story_1017_10170601_60_dialog_content = "我能體會……數量如此龐大的暗鬼，我還是第一次見到。",
  ui_story_1017_10170601_61_dialog_content = "知道牠們有什麼目的嗎？",
  ui_story_1017_10170601_62_dialog_content = "還不知道，行動很混亂，防線也一退再退……",
  ui_story_1017_10170601_63_dialog_content = "再這樣退下去，黃昏鎮就要守不住了……",
  ui_story_1017_10170601_64_dialog_content = "小心身後——！",
  ui_story_1017_10170601_65_dialog_content = "可惡！",
  ui_story_1017_10170601_66_dialog_content = "「鐵棘騎士團」的戰士怎麼能說這種喪氣話？",
  ui_story_1017_10170601_67_dialog_content = "就算李奧不在，我們也要拚盡全力，掃除暗鬼！",
  ui_story_1017_10170601_68_dialog_content = "戍邊多年，我們都知道，黃昏鎮不過是一塊神棄之地，求援不成，任由暗鬼啃食。",
  ui_story_1017_10170601_69_dialog_content = "我們守衛黃昏鎮，僅僅是因為我們出身於此，無處可去罷了。",
  ui_story_1017_10170601_70_dialog_content = "只要能回到……誰還願意在這裡受罪，過著朝不保夕的日子。",
  ui_story_1017_10170601_71_dialog_content = "……",
  ui_story_1017_10170601_72_dialog_content = "說這些……不代表我要退縮……就算是無名的士兵，也應該知道自己是為什麼而戰……",
  ui_story_1017_10170601_73_dialog_content = "這不過分吧？",
  ui_story_1017_10170601_74_dialog_content = "為了保護這裡，這還不夠嗎？",
  ui_story_1017_10170601_75_dialog_content = "那些沒有見過黃昏鎮外風景的孩子們，以為黃昏鎮就是整個世界。",
  ui_story_1017_10170601_76_dialog_content = "我想，在見識世界本來的面目之前，我們都曾這麼以為……",
  ui_story_1017_10170601_77_dialog_content = "而那些早已犧牲的戰士，不正是為了保護這個小小的世界而戰嗎？",
  ui_story_1017_10170601_78_dialog_content = "……",
  ui_story_1017_10170601_79_dialog_content = "戰士不需要透過偉大的戰爭來證明自己。",
  ui_story_1017_10170601_80_dialog_content = "只要能守護一方天地，他的戰績就很偉大。",
  ui_story_1017_10170601_81_dialog_content = "也許吧……雖然妳說得很有道理，但這些年來，我們都明白，大家是為了團長而戰……",
  ui_story_1017_10170601_82_dialog_content = "李奧也在為你們戰鬥，不是嗎？",
  ui_story_1017_10170601_83_dialog_content = "嗯，他為了我們，失去了很多。",
  ui_story_1017_10170601_84_dialog_content = "為了不失去更多，我們一起守護共同戰鬥過的地方吧！",
  ui_story_1017_10170601_85_dialog_content = "不管是出生在這裡，還是因為種種原因而來，為彼此而戰！",
  ui_story_1017_10170601_86_dialog_content = "嗯，妳說得沒錯！我這就告訴弟兄們——",
  ui_story_1017_10170601_87_dialog_content = "「鐵棘騎士團」，再讓暗鬼往前一步，就是對犧牲掉的弟兄們的羞辱！",
  ui_story_1017_10170601_88_dialog_content = "「鐵棘騎士團」不僅有鐵棘，還有鐵骨！",
  ui_story_1017_10170601_89_dialog_content = "就算用我們的屍體築成圍牆，也不能讓暗鬼進來！",
  ui_story_1017_10170601_90_dialog_content = "一起上！",
  ui_story_1017_10170601_91_dialog_content = "還有我！",
  ui_story_1017_10170601_92_dialog_content = "誓死保衛黃昏鎮！",
  ui_story_1017_10170601_93_dialog_content = "誓死保衛黃昏鎮！",
  ui_story_1017_10170602_1_dialog_content = "臨空者號，快到黃昏鎮了嗎？",
  ui_story_1017_10170602_2_dialog_content = "PlayerName，過去一分鐘裡，同樣的問題你問了十次。",
  ui_story_1017_10170602_3_dialog_content = "我只是很著急……",
  ui_story_1017_10170602_4_dialog_content = "原來如此。我只是在確認我們的連接是否出現延遲，看來沒有。",
  ui_story_1017_10170602_5_dialog_content = "連接沒有延遲，但我覺得你的速度很慢……",
  ui_story_1017_10170602_6_dialog_content = "確認飛行速率，始終保持<color=#FFB400>最高時速</color>。",
  ui_story_1017_10170602_7_dialog_content = "……",
  ui_story_1017_10170602_8_dialog_content = "你的心情很沮喪，可以告訴我原因嗎？",
  ui_story_1017_10170602_9_dialog_content = "我只是想到，你失去意識竟然是很久以前的事情了。",
  ui_story_1017_10170602_10_dialog_content = "都還來不及問候你的情況，就要你載我們趕往黃昏鎮……",
  ui_story_1017_10170602_11_dialog_content = "對你來說過了很久，但在我的設定裡，我們從來沒有分開。",
  ui_story_1017_10170602_12_dialog_content = "好像……確實是。",
  ui_story_1017_10170602_13_dialog_content = "因為你和夥伴們有許多地方要去，我才能夠看到這麼多風景。",
  ui_story_1017_10170602_14_dialog_content = "噢，<color=#FFB400>新的風景</color>，前面就是我們的目的地了。",
  ui_story_1017_10170602_15_dialog_content = "到了嗎？",
  ui_story_1017_10170602_16_dialog_content = "已經非常接近了，請確認降落地點。",
  ui_story_1017_10170602_17_dialog_content = "嗯，等黃昏鎮的事情結束，我會把之前發生的事全都告訴你。",
  ui_story_1017_10170602_18_dialog_content = "先減速進入低空飛行，<color=#FFB400>打開艙門</color>吧。",
  ui_story_1017_10170602_19_dialog_content = "減速中，正在開啟<color=#FFB400>三號艙門</color>……",
  ui_story_1017_10170602_20_dialog_content = "李奧——",
  ui_story_1017_10170602_21_dialog_content = "非常感謝，PlayerName，等黃昏鎮的事情結束後，我會正式感謝你的援助。",
  ui_story_1017_10170602_22_dialog_content = "不用這麼客氣……臨空者號已經在降落了，停在哪裡好？",
  ui_story_1017_10170602_23_dialog_content = "看到關口那個士兵了嗎？",
  ui_story_1017_10170602_24_dialog_content = "好像有人……但看起來又像是三匹馬……",
  ui_story_1017_10170602_25_dialog_content = "那是我的部下，他帶著我的馬在等我。",
  ui_story_1017_10170602_26_option_content = "視力這麼好？",
  ui_story_1017_10170602_27_dialog_content = "那麼遠的距離，你竟然看得到那是人和馬？",
  ui_story_1017_10170602_28_dialog_content = "當然，黃昏鎮可是個訓練人的好地方。",
  ui_story_1017_10170602_29_option_content = "不愧是你",
  ui_story_1017_10170602_30_dialog_content = "團長和部下果然心有靈犀啊。",
  ui_story_1017_10170602_31_dialog_content = "這可是多年培養出來的默契。",
  ui_story_1017_10170602_32_dialog_content = "如果有機會，我可以教你一些行軍打仗的本領。",
  ui_story_1017_10170602_33_dialog_content = "已達到降落高度，PlayerName，請確認降落地點。",
  ui_story_1017_10170602_34_dialog_content = "李奧，那就在關口前面降落怎麼樣？",
  ui_story_1017_10170602_35_dialog_content = "嗯……差不多，差不多，就是這個位置，那麼——",
  ui_story_1017_10170602_36_dialog_content = "PlayerName，若瑟就拜託你了。",
  ui_story_1017_10170602_37_dialog_content = "若瑟，回頭見。",
  ui_story_1017_10170602_38_dialog_content = "回頭見，李奧。",
  ui_story_1017_10170602_39_dialog_content = "？？？",
  ui_story_1017_10170602_40_dialog_content = "怎麼就跳下去了！",
  ui_story_1017_10170602_41_dialog_content = "喂！那——我——呢——",
  ui_story_1017_10170602_42_dialog_content = "回——去——吧——",
  ui_story_1017_10170602_43_dialog_content = "……",
  ui_story_1017_10170602_44_dialog_content = "團長！從那個龐然大物上跳下來的真的是你！",
  ui_story_1017_10170602_45_dialog_content = "那就是傳說中的……巨像吧？！",
  ui_story_1017_10170602_46_dialog_content = "沒錯，讓你久等了！",
  ui_story_1017_10170602_47_dialog_content = "直接去戰場，邊走邊說，黃昏鎮情況怎麼樣了？",
  ui_story_1017_10170602_48_dialog_content = "<color=#FFB400>永夜</color>方向暗鬼入侵，週邊堡壘已經被攻破了，兄弟們還在抵抗。",
  ui_story_1017_10170602_49_dialog_content = "暗鬼是誰在操控？",
  ui_story_1017_10170602_50_dialog_content = "沒有領頭暗鬼，牠們數量眾多，行動非常混亂！",
  ui_story_1017_10170602_51_dialog_content = "傷亡情況如何？",
  ui_story_1017_10170602_52_dialog_content = "不少週邊居民受到襲擊，目前已經安排移往安全地帶，數百名士兵受傷，還有……",
  ui_story_1017_10170602_53_dialog_content = "<color=#FFB400>七十五名</color>兄弟不幸犧牲……",
  ui_story_1017_10170602_54_dialog_content = "犧牲了<color=#FFB400>七十五名</color>？！那你還在這裡做什麼？",
  ui_story_1017_10170602_55_dialog_content = "團長……你回來之前，你的馬掙脫韁繩，衝上戰場頂撞暗鬼……",
  ui_story_1017_10170602_56_dialog_content = "只有我能勉強牽住牠，實在不知道怎麼辦了！",
  ui_story_1017_10170602_57_dialog_content = "哼！想吞下黃昏鎮，沒那麼容易。",
  ui_story_1017_10170602_58_dialog_content = "聯繫附近的城鎮了嗎？",
  ui_story_1017_10170602_59_dialog_content = "能打仗的都已經過來支援了……但也有幾個城鎮自身難保。",
  ui_story_1017_10170602_60_dialog_content = "這次不僅作戰困難……醫療資源的消耗也非常巨大……",
  ui_story_1017_10170602_61_dialog_content = "白夜要塞沒有給醫院提供幫助嗎？",
  ui_story_1017_10170602_62_dialog_content = "沒有，醫院只有鎮上的醫生和護士，甚至懂事點的孩子都來幫忙了……",
  ui_story_1017_10170602_63_dialog_content = "任何事情只要放在黃昏鎮上，就會困難重重。",
  ui_story_1017_10170602_64_dialog_content = "好消息是我回來了，我不會再讓兄弟們白白犧牲。",
  ui_story_1017_10170602_65_dialog_content = "壞消息是，我們仍然得靠自己。",
  ui_story_1017_10170602_66_dialog_content = "嗯……團長，昭為什麼沒有和你一起？",
  ui_story_1017_10170602_67_dialog_content = "他有要務在身，還需要一段時間，但我相信他會為我們帶來轉機。",
  ui_story_1017_10170602_68_dialog_content = "這次黃昏鎮面臨的危機，真的有可能出現轉機嗎？",
  ui_story_1017_10170602_69_dialog_content = "上面！",
  ui_story_1017_10170602_70_dialog_content = "接住！",
  ui_story_1017_10170602_71_dialog_content = "<color=#e8d9bb>士兵接住從天而降的PlayerName，兩人差點摔下馬去……</color>",
  ui_story_1017_10170602_72_dialog_content = "你、我認識你，你差點就把我砸死了！",
  ui_story_1017_10170602_73_dialog_content = "還以為、巨像也要一起砸下來了！",
  ui_story_1017_10170602_74_dialog_content = "很抱歉……",
  ui_story_1017_10170602_75_dialog_content = "你沒事吧？",
  ui_story_1017_10170602_76_option_content = "沒事",
  ui_story_1017_10170602_77_dialog_content = "臨空者號飛行的高度正好。",
  ui_story_1017_10170602_78_option_content = "我是誰，我在哪？",
  ui_story_1017_10170602_79_dialog_content = "下降的時候感覺心臟都停止了。",
  ui_story_1017_10170602_80_dialog_content = "還好臨空者號的高度沒問題。",
  ui_story_1017_10170602_81_dialog_content = "你來做什麼？",
  ui_story_1017_10170602_82_dialog_content = "說好一起去黃昏鎮，哪有半路叫人回去的。",
  ui_story_1017_10170602_83_dialog_content = "感謝，但是你的幫助就到此為止吧。",
  ui_story_1017_10170602_84_dialog_content = "掉頭，送他回去。",
  ui_story_1017_10170602_85_dialog_content = "團長……",
  ui_story_1017_10170602_86_dialog_content = "我不想再有部下犧牲！",
  ui_story_1017_10170602_87_dialog_content = "等等！我沒有打算當你的部下。",
  ui_story_1017_10170602_88_dialog_content = "我和臨空者號會對黃昏鎮的戰局有幫助。",
  ui_story_1017_10170602_89_dialog_content = "現在臨空者號的高度正好可以看清前面軍隊的整體情況。",
  ui_story_1017_10170602_90_dialog_content = "臨空者號可以提供空中視角，而我會為你指引戰場。",
  ui_story_1017_10170602_91_dialog_content = "空中視角，有幾分說服力。",
  ui_story_1017_10170602_92_dialog_content = "昭不在，PlayerName對戰場的指揮或許非常關鍵。",
  ui_story_1017_10170602_93_dialog_content = "是這樣沒錯。",
  ui_story_1017_10170602_94_dialog_content = "黃昏鎮的戰場可不是軍演，死了就真的死了。",
  ui_story_1017_10170602_95_dialog_content = "確定要來？",
  ui_story_1017_10170602_96_dialog_content = "當然！",
  ui_story_1017_10170602_97_dialog_content = "好，全速前往戰場！",
  ui_story_1017_10170602_98_dialog_content = "是，團長！",
  ui_story_1017_10170602_99_dialog_content = "牠們似乎無窮無盡……",
  ui_story_1017_10170602_100_dialog_content = "而且仍然沒有發現首領。",
  ui_story_1017_10170602_101_dialog_content = "大家已經筋疲力盡了，喬瑟琳，這樣下去遲早會擋不住。",
  ui_story_1017_10170602_102_dialog_content = "新的堡壘還沒建起來，如果這個時候放棄，前面的抵抗就白費了！",
  ui_story_1017_10170602_103_dialog_content = "但是士氣如此低迷，我擔心就算團長回來，也沒有救了……",
  ui_story_1017_10170602_104_dialog_content = "是誰說就算我回來也沒救的？",
  ui_story_1017_10170602_105_dialog_content = "團長，你終於回來了！",
  ui_story_1017_10170602_106_dialog_content = "團長回來啦！！！",
  ui_story_1017_10170602_107_dialog_content = "空中的是……",
  ui_story_1017_10170602_108_dialog_content = "「鐵棘騎士團」的兄弟們久等了！",
  ui_story_1017_10170602_109_dialog_content = "從現在開始，拿出騎士的樣子來！",
  ui_story_1017_10170602_110_dialog_content = "PlayerName和他的巨像臨空者號會協助我們！",
  ui_story_1017_10170602_111_dialog_content = "這就是傳說中的巨像啊，比想像中要龐大不少！",
  ui_story_1017_10170602_112_dialog_content = "和巨像一起作戰！",
  ui_story_1017_10170602_113_dialog_content = "沒錯，臨空者號會加入我們的戰場，都張開耳朵，注意聽指揮！",
  ui_story_1017_10170602_114_dialog_content = "現在，朝著臨空者號飛行的方向，全速前進，擊退暗鬼！！！",
  ui_story_1017_10170602_115_dialog_content = "好——！",
  ui_story_1017_10170602_116_dialog_content = "PlayerName，拜託了！",
  ui_story_1017_10170602_117_dialog_content = "嗯，我會盡力！",
  ui_story_1017_10170701_1_dialog_content = "通往白夜城的交通要道，應該在這附近才對……",
  ui_story_1017_10170701_2_dialog_content = "啊——",
  ui_story_1017_10170701_X2_dialog_content = "我咬、我咬！",
  ui_story_1017_10170701_3_dialog_content = "好無聊，真無聊，找個人欺負一下怎麼樣！",
  ui_story_1017_10170701_4_dialog_content = "妳們……妳們是誰？",
  ui_story_1017_10170701_5_dialog_content = "你猜！",
  ui_story_1017_10170701_6_dialog_content = "請兩位別捉弄我了，我有急事在身，先告辭了。",
  ui_story_1017_10170701_7_dialog_content = "有急事，拜託我，但不保證完成喔～",
  ui_story_1017_10170701_8_dialog_content = "……",
  ui_story_1017_10170701_9_dialog_content = "妳們知道怎麼去白夜城嗎？",
  ui_story_1017_10170701_10_dialog_content = "那個白色的、漂浮的、冷冰冰的地方，是不會有人去的。",
  ui_story_1017_10170701_11_dialog_content = "我記得有專門的交通前往……",
  ui_story_1017_10170701_12_dialog_content = "小狗溫馨提醒，往白夜城的交通已經停運了。",
  ui_story_1017_10170701_13_dialog_content = "……是最近停運的嗎？知道什麼原因嗎？",
  ui_story_1017_10170701_14_dialog_content = "你的問題這麼多，想做壞事就明說。除非——",
  ui_story_1017_10170701_15_dialog_content = "帶上我！",
  ui_story_1017_10170701_16_dialog_content = "<size=30>啟光的事已經傳開了，白夜城已經有所行動，比想像中要快。</size>",
  ui_story_1017_10170701_17_dialog_content = "<size=30>或許可以藉助信使公會的運輸交通……</size>",
  ui_story_1017_10170701_18_dialog_content = "<size=30>但是以什麼理由還是個問題……</size>",
  ui_story_1017_10170701_19_dialog_content = "哎呀——",
  ui_story_1017_10170701_20_dialog_content = "妳們、妳們做什麼？",
  ui_story_1017_10170701_21_dialog_content = "渾身透露著陰謀的味道，騙不過狗鼻子！",
  ui_story_1017_10170701_22_dialog_content = "一板一眼，來者不善！交給老大，然後開飯！",
  ui_story_1017_10170701_23_dialog_content = "那妳們能聞到黃昏鎮上的硝煙味嗎？我真的有急事，請放我出來！",
  ui_story_1017_10170701_24_dialog_content = "這裡面……我、頭好暈……",
  ui_story_1017_10170701_25_dialog_content = "這裡是影鎮！不是黃昏鎮！",
  ui_story_1017_10170701_26_dialog_content = "垃圾堆裡全是好東西，記得加熱之後食用喔！",
  ui_story_1017_10170701_27_dialog_content = "報告老大，有新發現，獎勵肉肉飯！",
  ui_story_1017_10170701_28_dialog_content = "不是說過不要什麼垃圾都撿回來嗎？",
  ui_story_1017_10170701_29_dialog_content = "不是垃圾，是壞蛋喔！老大請看——",
  ui_story_1017_10170701_30_dialog_content = "鬼鬼祟祟，慌慌張張。",
  ui_story_1017_10170701_31_dialog_content = "看見我們就想跑！",
  ui_story_1017_10170701_32_dialog_content = "……",
  ui_story_1017_10170701_33_dialog_content = "糟糕，壞掉了！",
  ui_story_1017_10170701_34_dialog_content = "這身打扮像個文縐縐的啟光人……他在這裡做什麼？",
  ui_story_1017_10170701_35_dialog_content = "好像說要占領白夜城，消滅信使公會什麼的……",
  ui_story_1017_10170701_36_dialog_content = "對！還要把影鎮變成黃昏！",
  ui_story_1017_10170701_37_dialog_content = "變成黃昏鎮啦！",
  ui_story_1017_10170701_38_dialog_content = "黃昏鎮？",
  ui_story_1017_10170701_39_dialog_content = "沒錯，黃昏鎮！他身上火藥味很濃！",
  ui_story_1017_10170701_40_dialog_content = "去把<color=#FFB400>克萊肯</color>找來，妳們去吃飯吧。",
  ui_story_1017_10170701_41_dialog_content = "好的老大～收工！開飯！",
  ui_story_1017_10170701_42_dialog_content = "城主大人，您到底要考慮到什麼時候？",
  ui_story_1017_10170701_43_dialog_content = "我手上這些全都是白夜要塞寄來的信件。",
  ui_story_1017_10170701_44_dialog_content = "如果再不出兵，今年<color=#FFB400>沃礦</color>的開採量會損失四成。",
  ui_story_1017_10170701_45_dialog_content = "考慮到因此產生的原料擠兌甚至供應中斷，這將對白夜城的對外貿易帶來影響……",
  ui_story_1017_10170701_46_dialog_content = "造成的損失可不僅僅是這些！",
  ui_story_1017_10170701_47_dialog_content = "黃昏鎮的安危什麼時候影響到白夜的經濟狀況了？",
  ui_story_1017_10170701_48_dialog_content = "你擔心的是這幾年在黃昏鎮賺的錢受到影響吧？",
  ui_story_1017_10170701_49_dialog_content = "無稽之談！我<color=#FFB400>迪特里希</color>雖不是歷史悠久的家族，但是這些年來開採資源，供應白夜城……",
  ui_story_1017_10170701_50_dialog_content = "在艱苦環境下，為不少流放的騎士提供住所……",
  ui_story_1017_10170701_51_dialog_content = "論功行賞，<color=#FFB400>迪特里希</color>早該在上城區擁有自己的莊園。",
  ui_story_1017_10170701_52_dialog_content = "但你<color=#FFB400>特洛伊</color>不同，在城主身邊養尊處優，應對暗鬼的能力早已退化了吧。",
  ui_story_1017_10170701_53_dialog_content = "啟光一向喜歡戰爭，鎮壓暗鬼一事，就讓他們去做吧。",
  ui_story_1017_10170701_54_dialog_content = "再說了，「鐵棘騎士團」在黃昏鎮有很大的影響力。",
  ui_story_1017_10170701_55_dialog_content = "說是收留騎士，你的這支劍未來會指向哪裡，恐怕早就計畫好了。",
  ui_story_1017_10170701_56_dialog_content = "你大概不知道，「鐵棘騎士團」保衛的是整個黃昏鎮。",
  ui_story_1017_10170701_57_dialog_content = "他們和啟光軍人親密無間，這次李奧還和他們一起參加了啟光的聯合軍演。",
  ui_story_1017_10170701_58_dialog_content = "據我所知，李奧的家族已經沒落。還是說他在黃昏鎮累積聲望，讓你感覺受到威脅？",
  ui_story_1017_10170701_59_dialog_content = "咳咳……除了黃昏鎮，還有別的情況嗎？",
  ui_story_1017_10170701_60_dialog_content = "城主大人，請允許我向您報告我在聯合軍演上得知的情況。",
  ui_story_1017_10170701_61_dialog_content = "妳說。",
  ui_story_1017_10170701_62_dialog_content = "我在軍演上認識一位黃昏鎮的士兵，他——",
  ui_story_1017_10170701_63_dialog_content = "好了，還是黃昏鎮，不必說下去了。",
  ui_story_1017_10170701_64_dialog_content = "可是——",
  ui_story_1017_10170701_65_dialog_content = "看到這張桌子了嗎？",
  ui_story_1017_10170701_66_dialog_content = "黃昏鎮、白夜要塞，甚至是影鎮的來信，我都已經看夠多了。",
  ui_story_1017_10170701_67_dialog_content = "那您為何還不採取行動？",
  ui_story_1017_10170701_68_dialog_content = "你在黃昏鎮待久了，染上了急躁的脾氣嗎？",
  ui_story_1017_10170701_69_dialog_content = "……",
  ui_story_1017_10170701_70_dialog_content = "（父親雖然嘴上不急，但敲桌子的手指一直沒停過……）",
  ui_story_1017_10170701_71_dialog_content = "（不想聽黃昏鎮的事情，但又是在等什麼呢？）",
  ui_story_1017_10170701_72_dialog_content = "城主大人！有一則啟光聯邦的新動態向想向您報告。",
  ui_story_1017_10170701_73_dialog_content = "說。",
  ui_story_1017_10170701_74_dialog_content = "啟光的新軍隊伍已經越過防線，快到黃昏鎮了。",
  ui_story_1017_10170701_75_dialog_content = "越過防線了？",
  ui_story_1017_10170701_76_dialog_content = "是！",
  ui_story_1017_10170701_77_dialog_content = "新軍隊伍是怎麼回事？",
  ui_story_1017_10170701_78_dialog_content = "新軍隊伍是雷霆上任大元帥後組織的近衛軍團。",
  ui_story_1017_10170701_79_dialog_content = "配備全新的戰鬥兵器和戰士，其中一名士兵還曾在軍演中戰勝萊因哈特。",
  ui_story_1017_10170701_80_dialog_content = "（阿克希亞？她現在應該在養傷才對啊……）",
  ui_story_1017_10170701_81_dialog_content = "有啟光將軍和空裔的消息嗎？",
  ui_story_1017_10170701_82_dialog_content = "除了緋之外，其他軍團長分頭執行任務，似乎並未前往黃昏鎮。",
  ui_story_1017_10170701_83_dialog_content = "至於空裔，之前接到消息，在戰爭開始後不久，他的巨像就前往黃昏鎮了。",
  ui_story_1017_10170701_84_dialog_content = "PlayerName竟然去黃昏鎮了！",
  ui_story_1017_10170701_85_dialog_content = "這有什麼問題？",
  ui_story_1017_10170701_86_dialog_content = "再明顯不過了。軍演過後，黃昏鎮的問題暴露在各大勢力面前。",
  ui_story_1017_10170701_87_dialog_content = "啟光聯邦似乎對保下黃昏鎮勝券在握，於是派出這支強力軍隊。",
  ui_story_1017_10170701_88_dialog_content = "這之後，黃昏鎮是否還有白夜的位置可很難說。",
  ui_story_1017_10170701_89_dialog_content = "在這個節骨眼撤換大元帥、派新軍隊鎮壓暗鬼……",
  ui_story_1017_10170701_90_dialog_content = "在我看來，這是十分荒唐的行為。",
  ui_story_1017_10170701_91_dialog_content = "他們到底是去支援，還是去做什麼？舒瓦茲，你最好想清楚。",
  ui_story_1017_10170701_92_dialog_content = "傳令下去，成立支援軍，立刻前往黃昏鎮。",
  ui_story_1017_10170701_93_dialog_content = "感謝城主大人，關於此事您意下如何？",
  ui_story_1017_10170701_94_dialog_content = "啟光軍隊越過防線，白夜城自然不能作壁上觀。",
  ui_story_1017_10170701_95_dialog_content = "無論是出於合作，還是爭奪目的，不出兵只會讓自己處於劣勢。",
  ui_story_1017_10170701_96_dialog_content = "記住，務必首先確保白夜要塞的安全，切莫攪和啟光軍隊行動。",
  ui_story_1017_10170701_97_dialog_content = "支援軍的每一步行動，都需要我親自批准。",
  ui_story_1017_10170701_98_dialog_content = "是！",
  ui_story_1017_10170701_99_dialog_content = "（父親對啟光的軍隊有所戒備……）",
  ui_story_1017_10170701_100_dialog_content = "城主大人，請問支援軍由誰來統率？我請求——",
  ui_story_1017_10170701_101_dialog_content = "妳先退下。支援黃昏鎮的行動，不在妳的職責範圍內。",
  ui_story_1017_10170701_102_dialog_content = "可是——",
  ui_story_1017_10170701_103_dialog_content = "各位，今天就到這裡吧。",
  ui_story_1017_10170801_1_dialog_content = "請問……我的家人還沒有回來，可以晚一點再關門嗎？",
  ui_story_1017_10170801_2_dialog_content = "城主下令緊閉城門，除了白夜人以外，不許任何人進入。",
  ui_story_1017_10170801_3_dialog_content = "可是……我的孩子也是白夜人啊……他是為了保護我們才去前線作戰。",
  ui_story_1017_10170801_4_dialog_content = "聽不懂命令嗎？城門要關了，退後！",
  ui_story_1017_10170801_5_dialog_content = "偉大的「光之神」，多希望您不曾遺棄我們——",
  ui_story_1017_10170801_6_dialog_content = "黃昏過後是黑夜，黑夜之後又是黃昏……",
  ui_story_1017_10170801_7_dialog_content = "前線的孩子們，我虔心為你們禱告。",
  ui_story_1017_10170801_8_dialog_content = "PlayerName，退後！",
  ui_story_1017_10170801_9_dialog_content = "戰場上，哪有指揮官退後的！",
  ui_story_1017_10170801_10_dialog_content = "這種規模的暗鬼入侵，我也是第一次見到。",
  ui_story_1017_10170801_11_dialog_content = "剛才發起的兩波夾攻都被暗鬼大軍淹沒了，現在不是逞英雄的時候。",
  ui_story_1017_10170801_12_dialog_content = "我確實感應到暗能越來越強……",
  ui_story_1017_10170801_13_dialog_content = "沒有首領，目的不明，數量眾多，在弄清情況之前不能盲目進攻。",
  ui_story_1017_10170801_14_dialog_content = "團長！兩支鎮守防線的隊伍都被暗鬼打敗了，士兵目前傷亡慘重！",
  ui_story_1017_10170801_15_dialog_content = "各隊聽令——防守後退一百步，立刻執行！",
  ui_story_1017_10170801_16_dialog_content = "是！",
  ui_story_1017_10170801_17_dialog_content = "讓後勤部把馬廄裡的老馬改裝成簡易板車，將傷患移往鎮上酒館。",
  ui_story_1017_10170801_18_dialog_content = "我們自己解決傷患問題！",
  ui_story_1017_10170801_19_dialog_content = "是，團長！",
  ui_story_1017_10170801_20_dialog_content = "李奧，我們邊退邊分析一下局勢，你認為暗鬼想要做什麼？",
  ui_story_1017_10170801_21_dialog_content = "他們僅是靠數量壓制，完全是在消耗我方兵力，確實匪夷所思。",
  ui_story_1017_10170801_22_dialog_content = "PlayerName，暗鬼的行動方式，有線索嗎？",
  ui_story_1017_10170801_23_dialog_content = "我感應看看。",
  ui_story_1017_10170801_24_dialog_content = "（黃昏鎮周圍全都是暗鬼……暗能密集……）",
  ui_story_1017_10170801_25_dialog_content = "（暗鬼行動緩慢，彼此卻靠得很近，彷彿……）",
  ui_story_1017_10170801_26_dialog_content = "（彷彿正在結一張巨大的「暗能之網」，往黃昏鎮壓過來……）",
  ui_story_1017_10170801_27_dialog_content = "（「暗能之網」上……結點眾多……）",
  ui_story_1017_10170801_28_dialog_content = "（等等……結點處的暗能強弱不同，暗能密集的結點是指向……）",
  ui_story_1017_10170801_29_dialog_content = "李奧，暗能覆蓋的距離很廣，暗鬼的行動似乎受到一個「中心」指揮。",
  ui_story_1017_10170801_30_dialog_content = "知道「中心」是什麼嗎？",
  ui_story_1017_10170801_31_dialog_content = "抱歉……那超出了我的感應範圍。",
  ui_story_1017_10170801_32_dialog_content = "但這至少表示，暗鬼的行為不是無跡可尋。",
  ui_story_1017_10170801_33_dialog_content = "是的，目前來看，找到那個「中心」非常關鍵。",
  ui_story_1017_10170801_34_dialog_content = "臨空者號，嘗試搜索「中心」。",
  ui_story_1017_10170801_35_dialog_content = "搜索中……",
  ui_story_1017_10170801_36_dialog_content = "視角延伸……",
  ui_story_1017_10170801_37_dialog_content = "找不到「中心」，繼續搜索中……",
  ui_story_1017_10170801_38_dialog_content = "暫時還找不到……",
  ui_story_1017_10170801_39_dialog_content = "如果是距離原因，「中心」的位置很有可能接近暗面，甚至就在暗面。",
  ui_story_1017_10170801_40_dialog_content = "我推測，必須先解決「中心」處的敵人，才能抑制暗鬼行動。",
  ui_story_1017_10170801_41_dialog_content = "你打算深入暗面？",
  ui_story_1017_10170801_42_dialog_content = "沒錯，繼續戰鬥下去，黃昏鎮只有死路一條。",
  ui_story_1017_10170801_43_dialog_content = "團長，我跟你去。",
  ui_story_1017_10170801_44_dialog_content = "不，你代替我指揮主戰部隊，繼續保護好防線。",
  ui_story_1017_10170801_45_dialog_content = "偵察隊，聽我號令——",
  ui_story_1017_10170801_46_dialog_content = "PlayerName，反方向有一支軍隊正在向你們靠近。",
  ui_story_1017_10170801_47_dialog_content = "看得清楚是哪裡的軍隊嗎？",
  ui_story_1017_10170801_48_dialog_content = "領頭的運輸車上插著一面旗幟，圖像是：",
  ui_story_1017_10170801_49_dialog_content = "啟光！",
  ui_story_1017_10170801_50_dialog_content = "李奧，身後是啟光的軍隊！",
  ui_story_1017_10170801_51_dialog_content = "近衛軍團，全體聽令——",
  ui_story_1017_10170801_52_dialog_content = "各連隊按聯防式攻擊向前推進！",
  ui_story_1017_10170801_53_dialog_content = "「引擎七號」優先補上壁壘缺口，不讓暗鬼再推進任何一寸！！！",
  ui_story_1017_10170801_54_dialog_content = "是！！！",
  ui_story_1017_10170801_55_dialog_content = "哼，這就是入侵黃昏鎮的暗鬼？還不夠我練上十分鐘！",
  ui_story_1017_10170801_56_dialog_content = "這……這個魄力……就是啟光的新任大元帥？",
  ui_story_1017_10170801_57_dialog_content = "軍演上還是我的教官，如今成為大元帥，完全不一樣了。",
  ui_story_1017_10170801_58_dialog_content = "是啊，全新的軍裝，感覺力量也強了不少！",
  ui_story_1017_10170801_59_dialog_content = "他們士兵的戰力也很可怕，看那邊那位——",
  ui_story_1017_10170801_60_dialog_content = "一路斬殺了十隻暗鬼，都不用停的……",
  ui_story_1017_10170801_61_dialog_content = "我倒是好奇，啟光還有這種武器，士兵能在裡面直接操控。",
  ui_story_1017_10170801_62_option_content = "（好想親自駕駛）",
  ui_story_1017_10170801_63_dialog_content = "安全起見，不建議嘗試。",
  ui_story_1017_10170801_64_option_content = "（好想改裝臨空者號）",
  ui_story_1017_10170801_65_dialog_content = "畫風不同，不建議嘗試。",
  ui_story_1017_10170801_66_dialog_content = "我只是感嘆一下……",
  ui_story_1017_10170801_67_dialog_content = "嗯？那個士兵也在。",
  ui_story_1017_10170801_68_dialog_content = "在軍演上打敗過萊因哈特，又迅速以雷霆部下的身分出戰，不簡單。",
  ui_story_1017_10170801_69_dialog_content = "阿克希亞……她應該是受了重傷，怎麼會在這……",
  ui_story_1017_10170801_70_dialog_content = "喲，PlayerName也在啊，這就讓你看傻眼了？",
  ui_story_1017_10170801_71_dialog_content = "……",
  ui_story_1017_10170801_72_dialog_content = "又見面了，騎士團長。",
  ui_story_1017_10170801_73_dialog_content = "好久不見，教官。啊抱歉，應該稱呼您「啟光大元帥」！",
  ui_story_1017_10170801_74_dialog_content = "儘管是回到了自己的戰場，但看樣子，你也沒有很輕鬆啊。",
  ui_story_1017_10170801_75_dialog_content = "能否告知一下，您和啟光士兵來此的目的？",
  ui_story_1017_10170801_76_dialog_content = "身為啟光聯邦的大元帥，我帶領精銳部隊支援黃昏鎮，鎮壓暗鬼。",
  ui_story_1017_10170801_77_dialog_content = "這有什麼難以理解的嗎？",
  ui_story_1017_10170801_78_dialog_content = "向來鐵皮的啟光，竟會派兵支援黃昏鎮，多少有點意外。",
  ui_story_1017_10170801_79_dialog_content = "哈哈，黃昏鎮要是被攻陷了，遭殃的可就是啟光了，豈能坐視不管。",
  ui_story_1017_10170801_80_dialog_content = "大元帥有遠見，希望不要再像軍演那樣搞小動作了。",
  ui_story_1017_10170801_81_dialog_content = "有心之人的把戲我也在調查，這次我們是黃昏鎮的盟友，希望我們合作愉快。",
  ui_story_1017_10170801_82_dialog_content = "合作愉快。",
  ui_story_1017_10170801_83_dialog_content = "近衛軍團聽好了，「鐵棘騎士團」已經苦戰多時！",
  ui_story_1017_10170801_84_dialog_content = "展現我們的實力，將暗鬼全部剿滅！",
  ui_story_1017_10170801_85_dialog_content = "是！！！",
  ui_story_1017_10170801_86_dialog_content = "「鐵棘騎士團」聽令——",
  ui_story_1017_10170801_87_dialog_content = "全軍成突翼陣實施突破！如果不想當個膽小鬼，就跟我一起衝在第一線！",
  ui_story_1017_10170801_88_dialog_content = "是！！！",
  ui_story_1017_10170901_1_dialog_content = "尤利西斯還真是可悲，把我不要的垃圾改裝一下，就等不及投入戰場了。",
  ui_story_1017_10170901_2_dialog_content = "還有膽量向前推嗎？",
  ui_story_1017_10170901_3_dialog_content = "（日蝕語）垃圾很能打。",
  ui_story_1017_10170901_4_dialog_content = "廢話，他們體內裝著我的「種子」，你應該早就察覺到了。",
  ui_story_1017_10170901_5_dialog_content = "（日蝕語）……",
  ui_story_1017_10170901_6_dialog_content = "我知道妳在想什麼，那個人也該來了。",
  ui_story_1017_10170901_7_dialog_content = "那麼期待我來呀？這點攻擊就承受不住了？",
  ui_story_1017_10170901_8_dialog_content = "和預料的不一樣，參與者增加了。",
  ui_story_1017_10170901_9_dialog_content = "這不是很好的報仇機會嗎？你應該感到高興才對。",
  ui_story_1017_10170901_10_dialog_content = "報仇的事情不用妳管。東西呢？",
  ui_story_1017_10170901_11_dialog_content = "喏。",
  ui_story_1017_10170901_12_dialog_content = "瑪德昂多？",
  ui_story_1017_10170901_13_dialog_content = "樣子是噁心了點，但能加快妳的推進速度，怎麼樣？",
  ui_story_1017_10170901_14_dialog_content = "我沒記錯的話，牠能吞噬環境、製造泥潭，折磨光靈的方式也……很特殊。對，很特殊。",
  ui_story_1017_10170901_15_dialog_content = "走過去看看。",
  ui_story_1017_10170901_16_dialog_content = "（日蝕語）是。",
  ui_story_1017_10170901_17_dialog_content = "（日蝕語）暗能……在匯聚，感覺……非常饑餓！",
  ui_story_1017_10170901_18_dialog_content = "暗鬼只要站在瑪德昂多的泥潭裡，體內的「種子」就會與其核心產生共振。",
  ui_story_1017_10170901_19_dialog_content = "（日蝕語）力量源源不絕地湧上萊！！！",
  ui_story_1017_10170901_20_dialog_content = "接下來，你們只需啃食光靈，充分成長就行。時間成熟時，瑪德昂多會來收場。",
  ui_story_1017_10170901_21_dialog_content = "不喜歡聽這些枯燥的解說。這裡就交給妳，下次見面就是驗收「地毯」的時候了～",
  ui_story_1017_10170901_22_dialog_content = "（日蝕語）食物！！！",
  ui_story_1017_10170901_23_dialog_content = "去吧，在泥潭深入黃昏鎮之前，這些食物都是你的。",
  ui_story_1017_10170901_24_dialog_content = "（日蝕語）嗷！！！",
  ui_story_1017_10170901_25_dialog_content = "糟糕！我感應到前方有強大的暗能襲來！",
  ui_story_1017_10170901_26_dialog_content = "這麼快！是「中心」處的敵人？",
  ui_story_1017_10170901_27_dialog_content = "不確定，但是「暗能之網」的確離我們越來越近了。",
  ui_story_1017_10170901_28_dialog_content = "呃……啊……",
  ui_story_1017_10170901_29_dialog_content = "那邊怎麼了？",
  ui_story_1017_10170901_30_dialog_content = "報告大元帥！士兵們疑似受到暗能影響……",
  ui_story_1017_10170901_31_dialog_content = "盡快治療，統計傷患情況。",
  ui_story_1017_10170901_32_dialog_content = "是！",
  ui_story_1017_10170901_33_dialog_content = "（……突然覺得……湧上一股力量……）",
  ui_story_1017_10170901_34_dialog_content = "大元帥，您沒事吧？",
  ui_story_1017_10170901_35_dialog_content = "這暗能……確實讓人不舒服……",
  ui_story_1017_10170901_36_dialog_content = "帶著妳的部下後退。鐵棘騎士團，一隊二隊追擊敵人，三隊四隊掩護！",
  ui_story_1017_10170901_37_dialog_content = "慢著！就這點暗鬼不算什麼。",
  ui_story_1017_10170901_38_dialog_content = "PlayerName，繼續輔助我戰鬥！",
  ui_story_1017_10170901_39_dialog_content = "前方有型態特殊的暗鬼逼近。",
  ui_story_1017_10170901_40_dialog_content = "是「中心」的敵人嗎？",
  ui_story_1017_10170901_41_dialog_content = "無法判斷，偵測到暗能強於其他暗鬼。",
  ui_story_1017_10170901_42_dialog_content = "知道了，還有別的資訊嗎？",
  ui_story_1017_10170901_43_dialog_content = "繼續探測，有結果後告訴妳。",
  ui_story_1017_10170901_44_dialog_content = "好的，拜託了！",
  ui_story_1017_10170901_45_dialog_content = "各位，有強大的暗鬼向這邊移動，準備進攻！",
  ui_story_1017_10170901_46_dialog_content = "哼，終於不是來塞牙縫的了嗎？",
  ui_story_1017_10170901_47_dialog_content = "看好了，騎士，近衛軍團可不會在這裡倒下，敵人交給我們！",
  ui_story_1017_10170901_48_dialog_content = "沒問題，「鐵棘騎士團」掩護！",
  ui_story_1017_10170901_49_dialog_content = "是！！！",
  ui_story_1017_10171001_1_dialog_content = "總算是……解決了！",
  ui_story_1017_10171001_2_dialog_content = "竟然在倒下之前召喚出那麼多暗鬼，真是措手不及。",
  ui_story_1017_10171001_3_dialog_content = "嗯，進攻開始有策略了，不過目前戰場暫時安全。",
  ui_story_1017_10171001_4_dialog_content = "報告大元帥！受到暗能影響的士兵仍在增加！",
  ui_story_1017_10171001_5_dialog_content = "查明原因了嗎？",
  ui_story_1017_10171001_6_dialog_content = "沒有，大量士兵身體不受控制，出現<color=#FFB400>嗜殺</color>傾向，治療完全沒有效果。",
  ui_story_1017_10171001_7_dialog_content = "……",
  ui_story_1017_10171001_8_dialog_content = "（不受控制又嗜殺……剛才戰鬥中，大家是不是都有這種感覺……）",
  ui_story_1017_10171001_9_dialog_content = "東區！團長，少量暗鬼又開始騷擾戰壕了！",
  ui_story_1017_10171001_10_dialog_content = "看來，這隻暗鬼不是「中心」的敵人。",
  ui_story_1017_10171001_11_dialog_content = "大家有什麼線索嗎？",
  ui_story_1017_10171001_12_dialog_content = "我在治療時發現，士兵受到的暗能影響與我們平時接觸到的不同。",
  ui_story_1017_10171001_13_dialog_content = "或許要到醫院中接受進一步治療才會有效。",
  ui_story_1017_10171001_14_dialog_content = "雷霆大元帥，您軍隊中情況不明的士兵，就由我送到醫院去吧。",
  ui_story_1017_10171001_15_dialog_content = "我正好想拜託你這件事，謝謝！戰後，啟光一定會補償你們的。",
  ui_story_1017_10171001_16_dialog_content = "這是我該做的。",
  ui_story_1017_10171001_17_dialog_content = "大元帥，有士兵反應，一些戰士脫離隊伍後，都一致往同一個方向移動……",
  ui_story_1017_10171001_18_dialog_content = "彷彿行為受到某種力量驅使。",
  ui_story_1017_10171001_19_dialog_content = "這種情況有可能是受到「中心」處的敵人影響嗎？",
  ui_story_1017_10171001_20_dialog_content = "不排除這個可能。之前就推測，暗能的流動情況是受「中心」控制的。",
  ui_story_1017_10171001_21_dialog_content = "黃昏鎮的士兵呢？大家都有這種感覺嗎？",
  ui_story_1017_10171001_22_dialog_content = "團長，有個情況……",
  ui_story_1017_10171001_23_dialog_content = "都看清楚了？",
  ui_story_1017_10171001_24_dialog_content = "是的，團長。",
  ui_story_1017_10171001_25_dialog_content = "大元帥，這些行動異常的士兵，都是妳的手下。",
  ui_story_1017_10171001_26_dialog_content = "你、什麼意思？",
  ui_story_1017_10171001_27_dialog_content = "那我便直說了，剛剛的幾次進攻中，您的部下情況持續反常。",
  ui_story_1017_10171001_28_dialog_content = "到底是敵人太強——",
  ui_story_1017_10171001_29_dialog_content = "還是大元帥的軍隊裡有內鬼？",
  ui_story_1017_10171001_30_dialog_content = "你懷疑啟光出兵黃昏鎮的企圖？",
  ui_story_1017_10171001_31_dialog_content = "並非如此。我只是感到敵人非比尋常，身為團長，我必須對我的部下負責任。",
  ui_story_1017_10171001_32_dialog_content = "就目前的情況萊看，您的部下已經開始分不清光靈和暗鬼了。",
  ui_story_1017_10171001_33_dialog_content = "話可別亂說！我雷霆從不會搞下三濫的手段！",
  ui_story_1017_10171001_34_dialog_content = "李奧團長、雷霆大元帥，我相信大家都是為了黃昏鎮好。",
  ui_story_1017_10171001_35_dialog_content = "雖然現在還不清楚士兵不照命令行動的原因……",
  ui_story_1017_10171001_36_dialog_content = "不過，我擔心這是敵人的伎倆，故意影響我們對局勢的判斷。",
  ui_story_1017_10171001_37_dialog_content = "在剛才的戰鬥中，我的士兵確實沒有完全按照我的命令行動。",
  ui_story_1017_10171001_38_dialog_content = "但我身為大元帥，啟光在外的一切行為，都由我來負責。",
  ui_story_1017_10171001_39_dialog_content = "士兵的情況，我會給大家一個交代。",
  ui_story_1017_10171001_40_dialog_content = "但你如果繼續質疑啟光的企圖，便是想與我作對。",
  ui_story_1017_10171001_41_dialog_content = "噢？說「作對」言重了，我只是給個小小的提醒。",
  ui_story_1017_10171001_42_dialog_content = "您成為啟光大元帥的時間不久，還請多多瞭解您部下的作戰習慣。",
  ui_story_1017_10171001_43_dialog_content = "若你們再無端出現投敵、甚至傷害士兵的行為，可別怪我不客氣。",
  ui_story_1017_10171001_44_dialog_content = "哼，嘴上功夫了得的傢伙。",
  ui_story_1017_10171001_45_dialog_content = "要和啟光較量，相信我，只要我雷霆一人就能讓你輸得心服口服！",
  ui_story_1017_10171001_46_dialog_content = "大元帥，緊急情況——",
  ui_story_1017_10171001_47_dialog_content = "阿克希亞中尉的作戰小隊，全隊下落不明。",
  ui_story_1017_10171001_48_dialog_content = "？？？",
  ui_story_1017_10171001_49_dialog_content = "她負責哪個區域？",
  ui_story_1017_10171001_50_dialog_content = "報告大元帥，是西區。目前西區仍有一群暗鬼在往黃昏鎮移動。",
  ui_story_1017_10171001_51_dialog_content = "近衛軍團整隊向西移動，剿滅暗鬼！",
  ui_story_1017_10171001_52_dialog_content = "傷患們，除非你斷了腿或是沒了腦袋，否則跟緊隊伍！",
  ui_story_1017_10171001_53_dialog_content = "發現異常士兵，立即向我報告！",
  ui_story_1017_10171001_54_dialog_content = "是！",
  ui_story_1017_10171001_55_dialog_content = "PlayerName，你跟我走。",
  ui_story_1017_10171001_56_dialog_content = "我？",
  ui_story_1017_10171001_57_dialog_content = "跟緊！",
  ui_story_1017_10171001_58_dialog_content = "……",
  ui_story_1017_10171001_59_dialog_content = "團長，我們自己行動嗎？",
  ui_story_1017_10171001_60_dialog_content = "新官上任三把火，不把問題說清楚，後面只會更加麻煩。",
  ui_story_1017_10171001_61_dialog_content = "準備向東前進。東區離住宅區比較近，一隻暗鬼都不能放進來。",
  ui_story_1017_10171001_62_dialog_content = "是，團長。",
  ui_story_1017_10171001_63_dialog_content = "李奧，醫院的同伴已經到了，我先將傷重士兵送到醫院去。",
  ui_story_1017_10171001_64_dialog_content = "那裡優先留給受傷的居民吧，傷員我讓<color=#FFB400>酒館</color>的朋友幫忙處理。",
  ui_story_1017_10171001_65_dialog_content = "團長，酒館已經……",
  ui_story_1017_10171001_66_dialog_content = "那就組織營地裡的後勤兵成立臨時醫護隊，把剩下的<color=#FFB400>沃礦</color>拿去白夜要塞交換醫療物資。",
  ui_story_1017_10171001_67_dialog_content = "可是團長，白夜要塞已經關閉城門了！",
  ui_story_1017_10171001_68_dialog_content = "所以我說了，拿沃礦去換！",
  ui_story_1017_10171001_69_dialog_content = "知道了，團長。",
  ui_story_1017_10171001_70_dialog_content = "任何事情，只要牽扯到白夜要塞，就困難重重。",
  ui_story_1017_10171001_71_dialog_content = "我雖然出身自黃昏鎮，但我也是白夜城的人，我會幫忙想辦法的。",
  ui_story_1017_10171001_72_dialog_content = "以身為白夜人為榮，真是十分罕見呢。",
  ui_story_1017_10171001_73_dialog_content = "陣營並不重要，我只是希望黃昏鎮的所有居民都能安居樂業。",
  ui_story_1017_10171001_74_dialog_content = "妳想像的畫面太遙不可及了。",
  ui_story_1017_10171001_75_dialog_content = "要是沒有啟光和白夜城的幫助，黃昏鎮朝不保夕，更別提安居樂業。",
  ui_story_1017_10171001_76_dialog_content = "妳知道一支軍團最重要的是什麼嗎？",
  ui_story_1017_10171001_77_dialog_content = "是心。團結一心才能打勝仗。而目前啟光的軍隊，根本就是一盤散沙。",
  ui_story_1017_10171001_78_dialog_content = "巨像看得清楚軍隊整體移動的情況嗎？",
  ui_story_1017_10171001_79_dialog_content = "非常清楚，PlayerName。",
  ui_story_1017_10171001_80_dialog_content = "可以，雷霆、大元帥。",
  ui_story_1017_10171001_81_dialog_content = "不覺得彆扭嗎？",
  ui_story_1017_10171001_82_dialog_content = "……",
  ui_story_1017_10171001_83_dialog_content = "你那是什麼表情？",
  ui_story_1017_10171001_84_dialog_content = "沒、沒什麼……只是跟大元帥一起行動，有點不習慣。",
  ui_story_1017_10171001_85_dialog_content = "呵，你不是跟萊因哈特挺熟的嗎？",
  ui_story_1017_10171001_86_dialog_content = "怎麼到我面前就緊張起來了？我跟她有什麼不一樣？",
  ui_story_1017_10171001_87_dialog_content = "（妳們何止是不一樣……）",
  ui_story_1017_10171001_88_dialog_content = "叫我名字就行了。為了互相尊重，我也會直接叫你名字。",
  ui_story_1017_10171001_89_dialog_content = "知道了，雷霆……",
  ui_story_1017_10171001_90_dialog_content = "關於我部下的情況，我有一件事想拜託你。",
  ui_story_1017_10171001_91_dialog_content = "妳說。",
  ui_story_1017_10171001_92_dialog_content = "我不確定在之後的戰鬥中，部下的情況還會不會進一步惡化。",
  ui_story_1017_10171001_93_dialog_content = "現在，我需要你幫我鎖定他們的位置，盡量在敵人大舉進攻前查明情況。",
  ui_story_1017_10171001_94_dialog_content = "沒問題，臨空者號也會幫忙的。",
  ui_story_1017_10171001_95_dialog_content = "正在搜索異常士兵，預計花費時間：六十秒。",
  ui_story_1017_10171001_96_dialog_content = "我有一個問題想問。",
  ui_story_1017_10171001_97_dialog_content = "什麼？",
  ui_story_1017_10171001_98_dialog_content = "阿克希亞怎麼會在你的隊伍裡面？",
  ui_story_1017_10171001_99_dialog_content = "我記得……她在軍演上受了重傷，應該在修養才對。",
  ui_story_1017_10171001_100_dialog_content = "這就是啟光軍人的能耐，明白嗎？",
  ui_story_1017_10171001_101_dialog_content = "一次次冒著生命危險走上戰場嗎……",
  ui_story_1017_10171001_102_dialog_content = "你不相信她的能力嗎？",
  ui_story_1017_10171001_103_dialog_content = "不、我相信，我只是覺得，阿克希亞……",
  ui_story_1017_10171001_104_dialog_content = "她並不像我認識的其他夥伴那樣，會害怕或渴望戰爭。",
  ui_story_1017_10171001_105_dialog_content = "從之前的互動，我幾乎感覺不到她有情緒……",
  ui_story_1017_10171001_106_dialog_content = "情緒並不是打勝仗的關鍵，空裔。",
  ui_story_1017_10171001_107_dialog_content = "不，我的意思是——",
  ui_story_1017_10171001_108_dialog_content = "我知道你想說什麼。",
  ui_story_1017_10171001_109_dialog_content = "在成為大元帥之前，我也和你有一樣的疑慮。",
  ui_story_1017_10171001_110_dialog_content = "但現在我明白了一點：",
  ui_story_1017_10171001_111_dialog_content = "要戰勝一個無論如何也戰勝不了的人，必須拋棄原來的自己，用對方的視角思考問題。",
  ui_story_1017_10171001_112_dialog_content = "拋棄原來的自己……我只看見妳和以前一樣衝鋒在前。",
  ui_story_1017_10171001_113_dialog_content = "哈哈，身為擁有超強感官的空裔一族，腦袋裡裝的東西原來這麼少。",
  ui_story_1017_10171001_114_dialog_content = "真是令人羡慕啊……",
  ui_story_1017_10171001_115_dialog_content = "這話聽起來不像是稱讚啊……",
  ui_story_1017_10171001_116_dialog_content = "你聽錯了，好好看路，別掉進坑裡了。",
  ui_story_1017_10171001_117_dialog_content = "前方二十公尺的障礙物下有一名異常士兵。",
  ui_story_1017_10171001_118_dialog_content = "雷霆，前面有異常士兵！",
  ui_story_1017_10171001_119_dialog_content = "快走。",
  ui_story_1017_10171001_120_dialog_content = "……",
  ui_story_1017_10171001_121_dialog_content = "你感覺怎麼樣？",
  ui_story_1017_10171001_122_dialog_content = "……",
  ui_story_1017_10171001_123_dialog_content = "他還有意識，但好像聽不到妳說話。",
  ui_story_1017_10171001_124_dialog_content = "我試著跟他建立感應看看……或許能找到線索。",
  ui_story_1017_10171001_125_dialog_content = "嗯。",
  ui_story_1017_10171001_126_option_content = "感應——嘗試——",
  ui_story_1017_10171001_127_dialog_content = "（這裡是……一片泥潭？）",
  ui_story_1017_10171001_128_dialog_content = "（像一張巨大的地毯覆蓋在大地上……）",
  ui_story_1017_10171001_129_dialog_content = "（附近幾座殘破的建築……看起來很眼熟……）",
  ui_story_1017_10171001_130_dialog_content = "（應該……是黃昏鎮沒錯……）",
  ui_story_1017_10171001_131_dialog_content = "（可這些泥是從哪裡流過來的……不斷地往我腳下匯聚……）",
  ui_story_1017_10171001_132_dialog_content = "（泥潭的流動似乎沒有特定的方向……）",
  ui_story_1017_10171001_133_dialog_content = "呃啊……",
  ui_story_1017_10171001_134_dialog_content = "怎麼樣？感覺很難受嗎？",
  ui_story_1017_10171001_135_dialog_content = "暗能讓我有點頭痛，不過還好……",
  ui_story_1017_10171001_136_dialog_content = "士兵的意識中是被泥潭覆蓋的黃昏鎮，那泥潭幾乎看不到邊界……",
  ui_story_1017_10171001_137_dialog_content = "泥水不斷往我腳下匯聚，幾乎快要站不穩了。",
  ui_story_1017_10171001_138_dialog_content = "泥潭……暗能……這麼說，士兵意識中的泥潭應該對應著現實中的暗能……",
  ui_story_1017_10171001_139_dialog_content = "這就是士兵異常的原因嗎……",
  ui_story_1017_10171001_140_dialog_content = "如果能看清泥潭擴散的方向……或許就能找到「中心」敵人所在……",
  ui_story_1017_10171001_141_dialog_content = "找死！",
  ui_story_1017_10171001_142_dialog_content = "等……！怎麼會？",
  ui_story_1017_10171001_143_dialog_content = "這是，妳的部下？",
  ui_story_1017_10171001_144_dialog_content = "還用你說？我剛才差點殺了他！",
  ui_story_1017_10171001_145_dialog_content = "他看起來受暗能影響更嚴重，已經完全失去理智的樣子……",
  ui_story_1017_10171001_146_dialog_content = "我試著感應一下他的情況吧。",
  ui_story_1017_10171001_147_dialog_content = "量力而行，遇到危險迅速中斷連結。",
  ui_story_1017_10171001_148_option_content = "感應——嘗試——",
  ui_story_1017_10171001_149_dialog_content = "（同樣的場景……但泥潭流動的速度比之前快很多……）",
  ui_story_1017_10171001_150_dialog_content = "（這一次……泥潭幾乎是從一個方向湧過來……）",
  ui_story_1017_10171001_151_dialog_content = "（那邊是……永夜？）",
  ui_story_1017_10171001_152_dialog_content = "（陰沉的天空和泥潭幾乎連在一起。）",
  ui_story_1017_10171001_153_dialog_content = "（不會錯……那應該就是「中心」所在的方向……）",
  ui_story_1017_10171001_154_dialog_content = "（不好——）",
  ui_story_1017_10171001_155_dialog_content = "你……暗鬼！",
  ui_story_1017_10171001_156_dialog_content = "退下！",
  ui_story_1017_10171001_157_dialog_content = "……雷霆？他這是……",
  ui_story_1017_10171001_158_dialog_content = "不用擔心，只是暈過去了。",
  ui_story_1017_10171001_159_dialog_content = "但你不能再繼續感應了，他體內的暗能連我都能感受得到。",
  ui_story_1017_10171001_160_dialog_content = "你看那邊的天色，越來越暗……",
  ui_story_1017_10171001_161_dialog_content = "……就是那邊！意識中的泥潭從永夜方向流過來，越來越快。",
  ui_story_1017_10171001_162_dialog_content = "那應該就是「中心」所在的方向！",
  ui_story_1017_10171001_163_dialog_content = "這麼說，敵人的位置找到了嗎？",
  ui_story_1017_10171001_164_dialog_content = "應該不會錯，而且似乎是接觸暗能久了……我看周圍的環境都有點恍惚……",
  ui_story_1017_10171001_165_dialog_content = "你的感覺沒錯，永夜方向的天空越來越暗。",
  ui_story_1017_10171001_166_dialog_content = "看來暗能不僅影響士兵，連環境都發生變化了，周圍開始瀰漫著一股腐爛的味道。",
  ui_story_1017_10171001_167_dialog_content = "<color=#e8d9bb>汩汩——汩汩——</color>",
  ui_story_1017_10171001_168_dialog_content = "你有聽到什麼聲音嗎……",
  ui_story_1017_10171001_169_dialog_content = "這聲音……像水在流動一樣……",
  ui_story_1017_10171001_170_dialog_content = "流動的水……黃昏鎮上不會真的有泥潭在流動吧！",
  ui_story_1017_10171001_171_dialog_content = "而且，就是從永夜方向！",
  ui_story_1017_10171001_172_dialog_content = "……看來「中心」敵人在靠近……",
  ui_story_1017_10171001_173_dialog_content = "<color=#e8d9bb>汩汩——汩汩——</color>",
  ui_story_1017_10171001_174_dialog_content = "PlayerName，西側有大規模暗鬼出現，預計5秒後進入你的感應範圍。",
  ui_story_1017_10171001_175_dialog_content = "這麼快！我看看……",
  ui_story_1017_10171001_176_option_content = "感應——嘗試——",
  ui_story_1017_10171001_177_dialog_content = "（黑壓壓的一片……這……這真的是泥潭！）",
  ui_story_1017_10171001_178_dialog_content = "雷霆，和士兵意識中看到的場景一模一樣！暗鬼隨著泥潭一起往我們這邊來了！",
  ui_story_1017_10171001_179_dialog_content = "什麼？！",
  ui_story_1017_10171001_180_dialog_content = "將現在的情況同步給騎士團，讓居民迅速撤離！",
  ui_story_1017_10171001_181_dialog_content = "是，大元帥！",
  ui_story_1017_10171001_182_dialog_content = "偵察小隊隨我去查看情況，「引擎七號」做好後排掩護！",
  ui_story_1017_10171001_183_dialog_content = "任何人，沒有我的命令不許輕舉妄動。如果身體出現異常，迅速離開戰場！",
  ui_story_1017_10171001_184_dialog_content = "大元帥！東側連隊，連續有士兵進入狂暴狀態！",
  ui_story_1017_10171001_185_dialog_content = "東側？我感應到的方向是西側……",
  ui_story_1017_10171001_186_dialog_content = "躲開！",
  ui_story_1017_10171001_187_dialog_content = "連這裡都……怎麼會？",
  ui_story_1017_10171001_188_dialog_content = "哼！顯然我們已經被包圍了。",
  ui_story_1017_10171001_189_dialog_content = "PlayerName，跟緊我！",
  ui_story_1017_10171101_1_dialog_content = "<color=#e8d9bb>不久之前，啟光的一座實驗大樓裡……</color>",
  ui_story_1017_10171101_2_dialog_content = "妳在做什麼？",
  ui_story_1017_10171101_3_dialog_content = "我在、巡邏……嗯、今天我負責巡這片區域……",
  ui_story_1017_10171101_4_dialog_content = "這裡是尤利西斯教授的實驗室，巡邏員沒事不會來到這裡。",
  ui_story_1017_10171101_5_dialog_content = "我、那個……",
  ui_story_1017_10171101_6_dialog_content = "誰派妳來的？",
  ui_story_1017_10171101_7_dialog_content = "我……",
  ui_story_1017_10171101_8_dialog_content = "對、對不起，鶯歌長官！我不該說謊，我只是……",
  ui_story_1017_10171101_9_dialog_content = "知道哥哥參加了啟光有史以來最偉大的<color=#FFB400>實驗</color>，我很羡慕，所以才……",
  ui_story_1017_10171101_10_dialog_content = "這項實驗在成功之前嚴格保密，士兵家屬無權得知。",
  ui_story_1017_10171101_11_dialog_content = "我和哥哥感情很好，他所有事情我都知道，請您相信我，我說的是真的。",
  ui_story_1017_10171101_12_dialog_content = "……",
  ui_story_1017_10171101_13_dialog_content = "自從他加入這項實驗後，媽媽和我都替他感到高興！",
  ui_story_1017_10171101_14_dialog_content = "但我卻因為資歷不夠，沒有入選……",
  ui_story_1017_10171101_15_dialog_content = "妳覺得很可惜？",
  ui_story_1017_10171101_16_dialog_content = "嗯……",
  ui_story_1017_10171101_17_dialog_content = "以後，會有機會的……",
  ui_story_1017_10171101_18_dialog_content = "真的嗎？這次落選，未來還有機會成為啟光的「明星」嗎？",
  ui_story_1017_10171101_19_dialog_content = "嗯……",
  ui_story_1017_10171101_20_dialog_content = "謝謝您，鶯歌長官！我馬上就離開。",
  ui_story_1017_10171101_21_dialog_content = "嗯……他們已經在和暗鬼戰鬥了吧……",
  ui_story_1017_10171101_22_dialog_content = "嗯，哥哥非常厲害……暗鬼不會是他的對手！",
  ui_story_1017_10171101_23_dialog_content = "……",
  ui_story_1017_10171101_24_dialog_content = "啊、抱歉，鶯歌長官，我就不打擾您了，再見！",
  ui_story_1017_10171101_25_dialog_content = "這就是啟光未來的「明星」嗎？",
  ui_story_1017_10171101_26_dialog_content = "……",
  ui_story_1017_10171101_27_dialog_content = "<size=30>教授……</size>",
  ui_story_1017_10171101_28_dialog_content = "……",
  ui_story_1017_10171101_29_dialog_content = "尤利西斯教授？",
  ui_story_1017_10171101_30_dialog_content = "哦，妳來了？調查得怎麼樣了？",
  ui_story_1017_10171101_31_dialog_content = "不是工作上的事，是……別的事情。",
  ui_story_1017_10171101_32_dialog_content = "什麼事？",
  ui_story_1017_10171101_33_dialog_content = "長官，阿克希亞在之前的軍演上受了非常嚴重的傷。",
  ui_story_1017_10171101_34_dialog_content = "對面是萊因哈特，這是她至今遇過最強的對手。",
  ui_story_1017_10171101_35_dialog_content = "……",
  ui_story_1017_10171101_36_dialog_content = "妳有話要說？",
  ui_story_1017_10171101_37_dialog_content = "長官，阿克希亞曾多次身受重傷，但她依然在為啟光戰鬥。",
  ui_story_1017_10171101_38_dialog_content = "我擔心……經過「啟明星計畫」2.0 後，她……",
  ui_story_1017_10171101_39_dialog_content = "呵呵，如果是這件事，妳完全多慮了。",
  ui_story_1017_10171101_40_dialog_content = "這裡是兩組實驗資料的對比結果，妳可以看看。",
  ui_story_1017_10171101_41_dialog_content = "「啟明星計畫」2.0之後，士兵的身體機能比原來提升了十倍。",
  ui_story_1017_10171101_42_dialog_content = "未來還有可能提升二十倍、五十倍……",
  ui_story_1017_10171101_43_dialog_content = "阿克希亞經過實驗後數值大幅提升，戰損率也大大降低。",
  ui_story_1017_10171101_44_dialog_content = "可以說，目前她正處於生命中的巔峰狀態。",
  ui_story_1017_10171101_45_dialog_content = "包括去黃昏鎮的士兵，都是如此。",
  ui_story_1017_10171101_46_dialog_content = "長官……但我仍然認為阿克希亞身體才剛恢復就迅速上戰場，這、十分殘酷……",
  ui_story_1017_10171101_47_dialog_content = "包括那些……認為自己是啟光未來「明星」的年輕士兵。",
  ui_story_1017_10171101_48_dialog_content = "是的，現實就是如此殘酷，但這是他們身為啟光軍人的職責。",
  ui_story_1017_10171101_49_dialog_content = "真的、是這樣嗎？",
  ui_story_1017_10171101_50_dialog_content = "如果他們不知道自己的力量是靠這些手段才達到的。",
  ui_story_1017_10171101_51_dialog_content = "當他們到達極限後，迅速隕落，這對他們將是毀滅性的打擊。",
  ui_story_1017_10171101_52_dialog_content = "鶯歌，妳的提問方式並不符合一名情報官的職業要求。",
  ui_story_1017_10171101_53_dialog_content = "如果沒有別的事，那我要繼續實驗了。",
  ui_story_1017_10171101_54_dialog_content = "可是教授——",
  ui_story_1017_10171101_55_dialog_content = "在妳表達自己的理解之前，先想清楚目的。",
  ui_story_1017_10171101_56_dialog_content = "如果想不通，我認為妳有必要放下手頭的工作，多來我的實驗室看看。",
  ui_story_1017_10171101_57_dialog_content = "這些千挑萬選出來的實驗者，來到這裡都只有一個目的——",
  ui_story_1017_10171101_58_dialog_content = "突破身體的極限、戰勝暗鬼，守護啟光和光靈，僅此而已。",
  ui_story_1017_10171101_59_dialog_content = "這間實驗室中每天都有光靈死去，但總比暗鬼來臨時，我們一起等死要強。",
  ui_story_1017_10171101_60_dialog_content = "我的目的是突破實驗，打磨兵器，沒有好的數據，光靈就沒有未來。",
  ui_story_1017_10171101_61_dialog_content = "實驗、兵器、數據，我敬佩您所做的一切……",
  ui_story_1017_10171101_62_dialog_content = "但我無法認同士兵的犧牲，尤其是不知道後果的情況下。",
  ui_story_1017_10171101_63_dialog_content = "呵呵，知道後果的，不是沒有。",
  ui_story_1017_10171101_64_dialog_content = "為了達到目的，她可以做到這種程度，妳呢？",
  ui_story_1017_10171101_65_dialog_content = "不……啟光不是靠這個走到今天的……",
  ui_story_1017_10171101_66_dialog_content = "啊——",
  ui_story_1017_10171101_67_dialog_content = "這個、聲音是……",
  ui_story_1017_10171101_68_dialog_content = "既然實驗開始了，妳就好好看看兩組實驗的差距吧。",
  ui_story_1017_10171101_69_dialog_content = "（不行……這聲音……）",
  ui_story_1017_10171101_70_dialog_content = "同樣是增強身體機能，結果卻完全不同。",
  ui_story_1017_10171101_71_dialog_content = "左邊的實驗者，植入了新的「種子」後，爆發力更強，且更持久。",
  ui_story_1017_10171101_72_dialog_content = "右邊的實驗者，已經幾乎被暗鬼啃食殆盡了。",
  ui_story_1017_10171101_73_dialog_content = "現在妳知道，為什麼要不惜一切代價逼走萊因哈特了吧？",
  ui_story_1017_10171101_74_dialog_content = "左邊的實驗者，難道……",
  ui_story_1017_10171101_75_dialog_content = "不管妳如何看待歷史與真相，世界就是這個樣子。",
  ui_story_1017_10171101_76_dialog_content = "我們只能用這種方式前進。",
  ui_story_1017_10171101_77_dialog_content = "暗潮湧動，我們甚至不得不以這種方式加速前進。",
  ui_story_1017_10171101_X78_dialog_content = "（我的頭……好痛……）",
  ui_story_1017_10171101_78_dialog_content = "教授，左側實驗者對右側房間的暗能產生劇烈反應！",
  ui_story_1017_10171101_79_dialog_content = "博士，左側實驗者對右側房間的暗能產生劇烈反應！",
  ui_story_1017_10171101_80_dialog_content = "是的，就應該是這樣，「種子」與「種子」之間有反應。",
  ui_story_1017_10171101_81_dialog_content = "那麼接下來，他會做什麼呢……",
  ui_story_1017_10171101_X82_dialog_content = "……",
  ui_story_1017_10171101_82_dialog_content = "教授，他想衝破玻璃，到右側的房間去！",
  ui_story_1017_10171101_83_dialog_content = "博士，他想衝破玻璃，到右側的房間去！",
  ui_story_1017_10171101_84_dialog_content = "嗯……不是想辦法開門，而是直接擊碎玻璃嗎。",
  ui_story_1017_10171101_85_dialog_content = "很好，這次強化的不是大腦，彌補了第一批「種子」的缺陷。",
  ui_story_1017_10171101_86_dialog_content = "這……跟製造暗鬼有什麼差別……",
  ui_story_1017_10171101_87_dialog_content = "想要戰勝暗鬼，不可能用尋常的方法。",
  ui_story_1017_10171101_88_dialog_content = "但在戰場之外，他仍然是妳的光靈同胞。",
  ui_story_1017_10171101_89_dialog_content = "不，啟光的光靈不會跟暗鬼成為同胞……請您馬上停止實驗。",
  ui_story_1017_10171101_90_dialog_content = "……",
  ui_story_1017_10171101_91_dialog_content = "教授，他做到了，他開始吞噬暗鬼！",
  ui_story_1017_10171101_92_dialog_content = "尤利西斯教授，請……馬上停止實驗！",
  ui_story_1017_10171101_93_dialog_content = "實驗才剛剛開始。",
  ui_story_1017_10171101_94_dialog_content = "啟光士兵在啃食暗鬼！這嚴重違反實驗程序……請立即停止！",
  ui_story_1017_10171101_95_dialog_content = "如果我沒記錯的話，實驗程序是我自己編寫的。",
  ui_story_1017_10171101_96_dialog_content = "驗證和突破是所有實驗的目的。",
  ui_story_1017_10171101_97_dialog_content = "教授！實驗者正在攻擊我們的玻璃！",
  ui_story_1017_10171101_98_dialog_content = "（那種充滿殺意的眼神，是在……看我？）",
  ui_story_1017_10171101_99_dialog_content = "請……停止實驗……",
  ui_story_1017_10171101_100_dialog_content = "教授，鶯歌長官的狀況不對！",
  ui_story_1017_10171101_101_dialog_content = "鶯歌，妳感覺怎麼樣？",
  ui_story_1017_10171101_102_dialog_content = "我的頭……好……痛……",
  ui_story_1017_10171101_103_dialog_content = "妳先回去休息吧。",
  ui_story_1017_10171101_104_dialog_content = "記下來，「種子」和「種子」之間的反應機制和距離還需進一步確認。",
  ui_story_1017_10171101_105_dialog_content = "教授，玻璃被——",
  ui_story_1017_10171101_106_dialog_content = "叫護衛隊進來！",
  ui_story_1017_10171101_107_dialog_content = "糟糕！教授快躲開——！",
  ui_story_1017_10171101_108_dialog_content = "……",
  ui_story_1017_10171201_1_dialog_content = "不能再往前了！泥潭蔓延速度太快了！",
  ui_story_1017_10171201_2_dialog_content = "所有人，分散開來，迅速後退！",
  ui_story_1017_10171201_3_dialog_content = "但妳……還要前進嗎？",
  ui_story_1017_10171201_4_dialog_content = "我有部下陷在裡面，無論如何，我都不能丟下他們不管。",
  ui_story_1017_10171201_5_dialog_content = "可是現在半個黃昏鎮都是泥潭……",
  ui_story_1017_10171201_6_dialog_content = "所以在泥潭覆蓋整個黃昏鎮之前，必須把「中心」敵人解決。",
  ui_story_1017_10171201_7_dialog_content = "……從剛剛的進攻來看，「中心」敵人的移動方向非常混亂。",
  ui_story_1017_10171201_8_dialog_content = "哼，是不簡單，成群的暗鬼包圍我們，自己躲在泥潭中四處襲擊！",
  ui_story_1017_10171201_9_dialog_content = "要找到牠，就必須繼續前進。",
  ui_story_1017_10171201_10_dialog_content = "我擔心這樣下去，會有更多士兵犧牲……",
  ui_story_1017_10171201_11_dialog_content = "沒有誰是白白犧牲的，PlayerName，不要替戰士感到惋惜！",
  ui_story_1017_10171201_12_dialog_content = "我只是……",
  ui_story_1017_10171201_13_dialog_content = "不必，來之前，大家早已做好了覺悟。",
  ui_story_1017_10171201_14_dialog_content = "其實我一直想問，他們中的一些士兵，為什麼會被派上戰場？",
  ui_story_1017_10171201_15_dialog_content = "……你知道些什麼？",
  ui_story_1017_10171201_16_dialog_content = "我只是大致猜測……",
  ui_story_1017_10171201_17_dialog_content = "會與暗能產生如此強烈的反應，他們與暗鬼的身體裡應該有相同的東西。",
  ui_story_1017_10171201_18_dialog_content = "剛才在和他們感應的時候，那種熟悉的感覺……",
  ui_story_1017_10171201_19_dialog_content = "在我被植入「種子」後也有過……",
  ui_story_1017_10171201_20_dialog_content = "只有這樣，才能解釋他們趨向暗鬼，甚至聽從「中心」指揮的原因…",
  ui_story_1017_10171201_21_dialog_content = "這種情況，並沒有出現在黃昏鎮的士兵中……",
  ui_story_1017_10171201_22_dialog_content = "你覺得我呢？",
  ui_story_1017_10171201_23_dialog_content = "妳……",
  ui_story_1017_10171201_24_dialog_content = "呵，不瞞你說，士兵剛剛出現異常時，我就知道我來黃昏鎮的真正目的了。",
  ui_story_1017_10171201_25_dialog_content = "不是為了支援黃昏鎮嗎？",
  ui_story_1017_10171201_26_dialog_content = "現在是真正需要支援的時候，你有看到什麼人來嗎？",
  ui_story_1017_10171201_27_dialog_content = "……",
  ui_story_1017_10171201_28_dialog_content = "求援信沒有結果、通訊沒有回應，這種情況持續了整場戰爭。",
  ui_story_1017_10171201_29_dialog_content = "或許是暗能影響了接收效果？",
  ui_story_1017_10171201_30_dialog_content = "你不瞭解啟光。啟光從來不打無準備的仗，除非這一仗另有用意。",
  ui_story_1017_10171201_31_dialog_content = "我們現在只能靠自己。",
  ui_story_1017_10171201_32_dialog_content = "只是想到，我這個大元帥，最後多半會落得和萊因哈特一樣的下場……",
  ui_story_1017_10171201_33_dialog_content = "真是不甘心啊！",
  ui_story_1017_10171201_34_dialog_content = "雷霆，我會和妳一起渡過難關……",
  ui_story_1017_10171201_35_dialog_content = "行了，現在不是傷感的時候。臨空者號有看到什麼嗎？",
  ui_story_1017_10171201_36_dialog_content = "前方三百公尺處，有巨大的暗能團在泥潭裡移動。",
  ui_story_1017_10171201_37_dialog_content = "是「中心」敵人嗎？",
  ui_story_1017_10171201_38_dialog_content = "暗能匯聚，向周圍散開，初步判斷是高級暗鬼。",
  ui_story_1017_10171201_39_dialog_content = "往我們這邊來了嗎？",
  ui_story_1017_10171201_40_dialog_content = "出沒地點不定，無法判定移動方向和預計到達時間。",
  ui_story_1017_10171201_41_dialog_content = "有看到人在指揮嗎？",
  ui_story_1017_10171201_42_dialog_content = "持續搜索中……",
  ui_story_1017_10171201_43_dialog_content = "辛苦你了，臨空者號。",
  ui_story_1017_10171201_44_dialog_content = "嗯？人呢？",
  ui_story_1017_10171201_45_dialog_content = "這裡怎麼突然多了這麼多暗鬼！",
  ui_story_1017_10171201_46_dialog_content = "怎麼樣，PlayerName！",
  ui_story_1017_10171201_47_dialog_content = "（等等……身體感覺……）",
  ui_story_1017_10171201_48_dialog_content = "前方有高級暗鬼在泥潭上移動！",
  ui_story_1017_10171201_49_dialog_content = "哼，看到了吧？就算我們不進攻，暗鬼也會想辦法逼我們動手！",
  ui_story_1017_10171201_50_dialog_content = "不如乾脆一點，堂堂正正地打一仗！",
  ui_story_1017_10171201_51_dialog_content = "泥潭裡恐怕有無數隻暗鬼潛伏，準備擊殺！",
  ui_story_1017_10171201_52_dialog_content = "雷霆，慢著，泥潭太危險，不要站上去！",
  ui_story_1017_10171201_53_dialog_content = "錯！我必須站上去！就算泥潭把我淹沒，我也要解決它！",
  ui_story_1017_10171201_54_dialog_content = "各連隊聽令！立刻將普通暗鬼引往兩側！",
  ui_story_1017_10171201_55_dialog_content = "「引擎七號」把前面的暗鬼撞開，為我開出一條道路！",
  ui_story_1017_10171201_56_dialog_content = "是！",
  ui_story_1017_10171201_57_dialog_content = "哼！自以為是的傢伙，躲在後面算什麼本事……",
  ui_story_1017_10171201_58_dialog_content = "大元帥！西側有暗鬼出現！",
  ui_story_1017_10171201_59_dialog_content = "大元帥，現在在東側！",
  ui_story_1017_10171201_60_dialog_content = "左右挑釁，然後就是……",
  ui_story_1017_10171201_61_dialog_content = "雷霆，注意腳下！",
  ui_story_1017_10171201_62_dialog_content = "果然，你的行動邏輯——",
  ui_story_1017_10171201_63_dialog_content = "愚鈍至極！",
  ui_story_1017_10171201_64_dialog_content = "大元帥！您、您沒事吧！",
  ui_story_1017_10171201_65_dialog_content = "這種……程度……怎麼可能會有事……",
  ui_story_1017_10171201_66_dialog_content = "你的臉色很難看！快來我這邊！",
  ui_story_1017_10171201_67_dialog_content = "不，我打到牠了……",
  ui_story_1017_10171201_68_dialog_content = "速度好快，我只看到牠從泥潭裡隆起，又迅速躲進去。",
  ui_story_1017_10171201_69_dialog_content = "牠被你打傷了嗎？",
  ui_story_1017_10171201_70_dialog_content = "沒那麼容易。感覺那個東西……似乎要把我……",
  ui_story_1017_10171201_71_dialog_content = "雷霆，妳的身體在發抖！",
  ui_story_1017_10171201_72_dialog_content = "原來就是牠……那個東西……似乎要把我……",
  ui_story_1017_10171201_73_dialog_content = "大元帥！「引擎七號」過來接應您，搭上去離開泥潭吧！",
  ui_story_1017_10171201_74_dialog_content = "誰都別過來！",
  ui_story_1017_10171201_75_dialog_content = "這泥潭……是那個暗鬼的領域。",
  ui_story_1017_10171201_76_dialog_content = "只要站上來……就會……",
  ui_story_1017_10171201_77_dialog_content = "但妳正站在上面！",
  ui_story_1017_10171201_78_dialog_content = "（保持清醒，保持清醒！）",
  ui_story_1017_10171201_79_dialog_content = "快離開那裡，雷霆！",
  ui_story_1017_10171201_80_dialog_content = "牠衝過來了……我、不能撤退。",
  ui_story_1017_10171201_81_dialog_content = "如果妳倒下了，黃昏鎮就完了！",
  ui_story_1017_10171201_82_dialog_content = "我不會倒下……我現在……",
  ui_story_1017_10171201_83_dialog_content = "感到……力量正不斷湧上來……",
  ui_story_1017_10171201_84_dialog_content = "我必須、殺了牠！",
  ui_story_1017_10171201_85_dialog_content = "那我替妳指揮！",
  ui_story_1017_10171201_86_dialog_content = "退後！",
  ui_story_1017_10171201_87_dialog_content = "十點鐘方向，暗能相對稀薄！可以繞到暗鬼背後！",
  ui_story_1017_10171201_88_dialog_content = "暗鬼朝你過去了，退後！",
  ui_story_1017_10171201_89_dialog_content = "身後五步距離，暗能減弱，就這樣繼續……",
  ui_story_1017_10171201_90_dialog_content = "（呃……身體突然……僵在原地……）",
  ui_story_1017_10171201_91_dialog_content = "PlayerName！",
  ui_story_1017_10171201_92_dialog_content = "（腿快動啊……暗鬼好多……）",
  ui_story_1017_10171201_93_dialog_content = "PlayerName？！",
  ui_story_1017_10171201_94_dialog_content = "（嗯……完全動不了了……）",
  ui_story_1017_10171201_95_dialog_content = "（只能直接感應雷霆進行指揮了……）",
  ui_story_1017_10171301_1_dialog_content = "又來一隻！雷槍穿刺！",
  ui_story_1017_10171301_2_dialog_content = "（戰鬥越久，越感到身體不聽使喚……）",
  ui_story_1017_10171301_3_dialog_content = "（從一開始的混亂，到現在產生殺戮的快感……）",
  ui_story_1017_10171301_4_dialog_content = "（這樣下去，難道真要像那些士兵一樣……）",
  ui_story_1017_10171301_5_dialog_content = "（不！）",
  ui_story_1017_10171301_6_dialog_content = "（我不能倒下！這才剛開始啊！）",
  ui_story_1017_10171301_7_dialog_content = "喂，小心——！",
  ui_story_1017_10171301_8_dialog_content = "唉喲——！",
  ui_story_1017_10171301_9_dialog_content = "清醒了嗎？",
  ui_story_1017_10171301_10_dialog_content = "被妳這麼一扔，當然醒了！",
  ui_story_1017_10171301_11_dialog_content = "你說什麼？",
  ui_story_1017_10171301_12_dialog_content = "（等等，說話的是PlayerName……）",
  ui_story_1017_10171301_13_dialog_content = "（為什麼會覺得他是暗鬼……）",
  ui_story_1017_10171301_14_dialog_content = "妳沒事吧？",
  ui_story_1017_10171301_15_dialog_content = "我沒事……",
  ui_story_1017_10171301_16_dialog_content = "（是PlayerName，眼前站著的是PlayerName！）",
  ui_story_1017_10171301_17_dialog_content = "雷霆！",
  ui_story_1017_10171301_18_dialog_content = "嗯，我、沒事。",
  ui_story_1017_10171301_19_dialog_content = "我不是叫你離泥潭遠一點嗎！",
  ui_story_1017_10171301_20_dialog_content = "可是妳剛剛不顧一切地往泥潭裡走，和士兵之前的行為一樣……",
  ui_story_1017_10171301_21_dialog_content = "……",
  ui_story_1017_10171301_22_dialog_content = "雷霆？",
  ui_story_1017_10171301_23_dialog_content = "（雷霆狀況不對勁……）",
  ui_story_1017_10171301_24_dialog_content = "前面有暗鬼，過去把牠們解決掉！",
  ui_story_1017_10171301_25_dialog_content = "等等，哪有暗鬼？",
  ui_story_1017_10171301_26_dialog_content = "雷槍穿刺！",
  ui_story_1017_10171301_27_dialog_content = "雷霆……沒有暗鬼，那是泥巴。",
  ui_story_1017_10171301_28_dialog_content = "雷槍穿刺！",
  ui_story_1017_10171301_29_dialog_content = "這……怎麼會？",
  ui_story_1017_10171301_30_dialog_content = "看來現在是你不清醒了。",
  ui_story_1017_10171301_31_dialog_content = "暗鬼就藏在泥潭中伺機襲擊嗎……",
  ui_story_1017_10171301_32_dialog_content = "（……她能提前發現暗鬼的行動並迅速出手，動作似乎不受控制……）",
  ui_story_1017_10171301_33_dialog_content = "趁我還有力氣，好好指揮！",
  ui_story_1017_10171301_34_dialog_content = "嗯！一點鐘方向！",
  ui_story_1017_10171301_35_dialog_content = "好！",
  ui_story_1017_10171301_36_dialog_content = "雷霆，是一點鐘方向！",
  ui_story_1017_10171301_37_dialog_content = "……",
  ui_story_1017_10171301_38_dialog_content = "不是那個方向！",
  ui_story_1017_10171301_39_dialog_content = "PlayerName，雷霆衝進暗鬼群了。",
  ui_story_1017_10171301_40_dialog_content = "這樣下去，她會被暗鬼吞沒的！！！",
  ui_story_1017_10171301_41_dialog_content = "強制——感應——",
  ui_story_1017_10171301_42_dialog_content = "（是泥潭……）",
  ui_story_1017_10171301_43_dialog_content = "（流動的速度好快……而且方向混亂。）",
  ui_story_1017_10171301_44_dialog_content = "（嗯？這裡似乎被什麼東西攪開……）",
  ui_story_1017_10171301_45_dialog_content = "（光點！）",
  ui_story_1017_10171301_46_dialog_content = "（泥潭在往上爬……鋪成一幅畫……）",
  ui_story_1017_10171301_47_dialog_content = "（這裡是……尤利西斯、貝利撒留，還有螢幕上的……）",
  ui_story_1017_10171301_48_dialog_content = "（還沒看清楚就沒了……雷霆不在這裡。）",
  ui_story_1017_10171301_49_dialog_content = "（前面又有一個光點！）",
  ui_story_1017_10171301_50_dialog_content = "（……是萊因哈特！）",
  ui_story_1017_10171301_51_dialog_content = "（年輕的萊因哈特……還有觀眾、橫幅……）",
  ui_story_1017_10171301_52_dialog_content = "（「啟光大元帥終極考核」……敗給萊因哈特了嗎……）",
  ui_story_1017_10171301_53_dialog_content = "（嗯？雨……）",
  ui_story_1017_10171301_54_dialog_content = "（這裡看起來是地下城的環境，竟然會下雨。）",
  ui_story_1017_10171301_55_dialog_content = "（對於雷霆來說……這一天一定很難忘吧……）",
  ui_story_1017_10171301_56_dialog_content = "（這裡是……啟光實驗室……）",
  ui_story_1017_10171301_57_dialog_content = "（尤利西斯和一群人圍在實驗台上……）",
  ui_story_1017_10171301_58_dialog_content = "（上面躺著……）",
  ui_story_1017_10171301_59_dialog_content = "（萊因哈特？）",
  ui_story_1017_10171301_60_dialog_content = "（怎麼會是萊因哈特？）",
  ui_story_1017_10171301_61_dialog_content = "（不是雷霆？！）",
  ui_story_1017_10171301_62_dialog_content = "（等等……站在實驗台邊的不是尤利西斯，是雷霆！）",
  ui_story_1017_10171301_63_dialog_content = "（雷霆！妳聽得到我說話嗎？）",
  ui_story_1017_10171301_64_dialog_content = "（……）",
  ui_story_1017_10171301_65_dialog_content = "（妳現在正在黃昏鎮對抗暗鬼，快醒醒！）",
  ui_story_1017_10171301_66_dialog_content = "（暗鬼……上了實驗台的都會變成暗鬼……）",
  ui_story_1017_10171301_67_dialog_content = "（敵人快把黃昏鎮夷平了，妳現在渾身是傷，快醒醒！）",
  ui_story_1017_10171301_68_dialog_content = "（為什麼萊因哈特從不受傷？）",
  ui_story_1017_10171301_69_dialog_content = "（因為她、是暗鬼……）",
  ui_story_1017_10171301_70_dialog_content = "（所有人都會受傷！但妳是大元帥，士兵們需要妳！）",
  ui_story_1017_10171301_71_dialog_content = "（大元帥……）",
  ui_story_1017_10171301_72_dialog_content = "（奏效了？我再想想……）",
  ui_story_1017_10171301_73_dialog_content = "（大元帥終極考核！）",
  ui_story_1017_10171301_74_dialog_content = "（妳和萊因哈特的較量還沒有結束！快回戰場上！）",
  ui_story_1017_10171301_75_dialog_content = "（萊因哈特……該死的萊因哈特！）",
  ui_story_1017_10171301_76_dialog_content = "（對，萊因哈特還在賽場上，去與她一決勝負！）",
  ui_story_1017_10171301_77_dialog_content = "（雷霆——）",
  ui_story_1017_10171301_78_dialog_content = "PlayerName，你終於清醒過來了。",
  ui_story_1017_10171301_79_dialog_content = "我沒事。雷霆呢？她現在怎麼樣了？",
  ui_story_1017_10171301_80_dialog_content = "初步判斷意識恢復正常，已經重新壓制暗鬼。",
  ui_story_1017_10171301_81_dialog_content = "太好了！",
  ui_story_1017_10171301_82_dialog_content = "剛才雷霆情況不明，你進行強制感應非常危險。",
  ui_story_1017_10171301_83_dialog_content = "我知道……但是情況緊急，我來不及考慮……",
  ui_story_1017_10171301_84_dialog_content = "或許是知道有你在，我就覺得不會有危險。",
  ui_story_1017_10171301_85_dialog_content = "看你右側，是「鐵棘騎士團」保護了你們。",
  ui_story_1017_10171301_86_dialog_content = "李奧他們來了！",
  ui_story_1017_10171301_87_dialog_content = "在你和雷霆感應的時候，他們已經加入戰場。",
  ui_story_1017_10171301_88_dialog_content = "謝謝你，臨空者號！",
  ui_story_1017_10171301_89_dialog_content = "臨空者號持續為你導航。",
  ui_story_1017_10171301_90_dialog_content = "雷槍穿刺！",
  ui_story_1017_10171301_91_dialog_content = "你剛才在胡說八道些什麼？",
  ui_story_1017_10171301_92_option_content = "我是在幫妳",
  ui_story_1017_10171301_93_dialog_content = "妳現在沒事就好！",
  ui_story_1017_10171301_94_dialog_content = "多管閒事。",
  ui_story_1017_10171301_95_option_content = "我不是故意說那些話的",
  ui_story_1017_10171301_96_dialog_content = "我只是為了叫醒妳……",
  ui_story_1017_10171301_97_dialog_content = "別亂看不該看的東西，聽到沒有？",
  ui_story_1017_10171301_98_dialog_content = "但妳能這樣和我講話，真是太好了！",
  ui_story_1017_10171301_99_dialog_content = "保護黃昏鎮的任務還沒有結束。",
  ui_story_1017_10171301_100_dialog_content = "我雷霆就算變成暗鬼，也是守護黃昏鎮的暗鬼！",
  ui_story_1017_10171301_101_dialog_content = "近衛軍團聽好了——",
  ui_story_1017_10171301_102_dialog_content = "我們在戰鬥中多少都出現了不適的症狀，但是相信我，這只是暫時的。",
  ui_story_1017_10171301_103_dialog_content = "試著集中精神，暗能的影響會大幅降低。",
  ui_story_1017_10171301_104_dialog_content = "我向你們保證，所有脫隊的士兵我都會把他們一一找回來，在那之前我需要你們的力量！",
  ui_story_1017_10171301_105_dialog_content = "現在，受了傷、頭腦不清的，立刻掉頭返回啟光！",
  ui_story_1017_10171301_106_dialog_content = "還撐得下去、<color=#FFB400>不怕被暗能影響</color>的，就跟著我一起向「中心」前進！",
  ui_story_1017_10171301_107_dialog_content = "是！！！",
  ui_story_1017_10171401_1_dialog_content = "吃飽了嗎？",
  ui_story_1017_10171401_2_dialog_content = "<遠遠不夠——>",
  ui_story_1017_10171401_3_dialog_content = "好的東西自然是要留到最後。這「地毯」鋪得很漂亮。",
  ui_story_1017_10171401_4_dialog_content = "<吞噬一切——>",
  ui_story_1017_10171401_5_dialog_content = "別動，我在進行最後一次調整。",
  ui_story_1017_10171401_6_dialog_content = "這破地方跟實驗室比差遠了，進度慢了不少。",
  ui_story_1017_10171401_7_dialog_content = "（日蝕語）有一個光靈，始終不肯倒下……",
  ui_story_1017_10171401_8_dialog_content = "不用擔心，那位新任大元帥要留給瑪德昂多最後享用。",
  ui_story_1017_10171401_9_dialog_content = "<給我一切——>",
  ui_story_1017_10171401_10_dialog_content = "（日蝕語）不是她，是另一個。這隻光靈幾乎沒有受到任何影響。",
  ui_story_1017_10171401_11_dialog_content = "新東西？馬上去看看。",
  ui_story_1017_10171401_12_dialog_content = "……",
  ui_story_1017_10171401_13_dialog_content = "還以為是什麼呢，這呆頭呆腦的東西根本就不會戰鬥。",
  ui_story_1017_10171401_14_dialog_content = "阿克希亞是戰爭機器，阿克希亞一直在戰鬥。",
  ui_story_1017_10171401_15_dialog_content = "不是啞巴啊？既然會張嘴，嚐嚐這個。",
  ui_story_1017_10171401_16_dialog_content = "……",
  ui_story_1017_10171401_17_dialog_content = "新鮮，不殺暗鬼，那要做什麼？",
  ui_story_1017_10171401_18_dialog_content = "「阿克希亞要不顧一切代價，打敗萊因哈特大元帥。」",
  ui_story_1017_10171401_19_dialog_content = "哈哈哈哈！尤利西斯竟能把局做得這麼難看，她根本不管你的死活吧。",
  ui_story_1017_10171401_20_dialog_content = "「阿克希亞要以人的身分活下去。」",
  ui_story_1017_10171401_21_dialog_content = "不陪你聊天了，瑪德昂多該去享用食物了。",
  ui_story_1017_10171401_22_dialog_content = "把整隊士兵圍困在這，幹得不錯，你自己看著辦吧。",
  ui_story_1017_10171401_23_dialog_content = "（日蝕語）是。",
  ui_story_1017_10171401_24_dialog_content = "……",
  ui_story_1017_10171401_25_dialog_content = "襲擊我的部下，找死！",
  ui_story_1017_10171401_26_dialog_content = "總算找到你了，還以為你陷入泥潭了！",
  ui_story_1017_10171401_27_dialog_content = "大元帥，阿克希亞中尉小隊隊員陸續找到了。",
  ui_story_1017_10171401_28_dialog_content = "嗯，確認傷患情況，小心「中心」敵人再次攻過來。",
  ui_story_1017_10171401_29_dialog_content = "臨空者號，這附近還有士兵嗎？",
  ui_story_1017_10171401_30_dialog_content = "正在搜索……",
  ui_story_1017_10171401_31_dialog_content = "……",
  ui_story_1017_10171401_32_dialog_content = "遇到暗鬼只是擋下攻擊，阿克希亞，為什麼不殺？",
  ui_story_1017_10171401_33_dialog_content = "「阿克希亞要不顧一切代價，打敗萊因哈特大元帥。」",
  ui_story_1017_10171401_34_dialog_content = "這是尤利西斯對妳說的嗎？",
  ui_story_1017_10171401_35_dialog_content = "「阿克希亞要不顧一切代價，打敗萊因哈特大元帥。」",
  ui_story_1017_10171401_36_dialog_content = "……妳已經完成任務了。妳在軍演上擊敗她了。",
  ui_story_1017_10171401_37_dialog_content = "……",
  ui_story_1017_10171401_38_dialog_content = "她的情況似乎沒有受到嚴重污染，但狀態有些游離。",
  ui_story_1017_10171401_39_dialog_content = "阿克希亞，萊因哈特認輸前對妳說了什麼？",
  ui_story_1017_10171401_40_dialog_content = "萊因哈特大元帥，希望「阿克希亞要以人的身分活下去。」",
  ui_story_1017_10171401_41_dialog_content = "呵，那個傢伙……",
  ui_story_1017_10171401_42_dialog_content = "自己都淪為階下囚了，還留下這種漂亮話。還有別的嗎？",
  ui_story_1017_10171401_43_dialog_content = "阿克希亞要完成兩個任務。",
  ui_story_1017_10171401_44_dialog_content = "「阿克希亞要不顧一切代價，打敗萊因哈特大元帥。」",
  ui_story_1017_10171401_45_dialog_content = "「阿克希亞要以人的身分活下去。」",
  ui_story_1017_10171401_46_dialog_content = "……",
  ui_story_1017_10171401_47_dialog_content = "阿克希亞，第一個任務，妳已經完成了。第二個任務，也是妳唯一的任務。",
  ui_story_1017_10171401_48_dialog_content = "唯一的任務，「阿克希亞要以人的身分活下去。」",
  ui_story_1017_10171401_49_dialog_content = "沒錯，戰勝暗鬼，我們才能活下去。妳是啟光的戰士，妳有活下去的權利。",
  ui_story_1017_10171401_50_dialog_content = "阿克希亞要戰勝暗鬼，阿克希亞要活下去。",
  ui_story_1017_10171401_51_dialog_content = "阿克希亞……移動了身體？",
  ui_story_1017_10171401_52_dialog_content = "看來暫時脫離險境了，完全恢復或許還要一段時間。",
  ui_story_1017_10171401_53_dialog_content = "大元帥，阿克希亞中尉的隊伍嚴重受暗能影響，幾乎無法作戰。",
  ui_story_1017_10171401_54_dialog_content = "看樣子，「中心」敵人的據點離這裡不遠……",
  ui_story_1017_10171401_55_dialog_content = "PlayerName，多虧了你和臨空者號的幫忙。",
  ui_story_1017_10171401_56_dialog_content = "最後拜託你一件事，幫我把這些無法戰鬥的士兵送回去。",
  ui_story_1017_10171401_57_dialog_content = "現在？",
  ui_story_1017_10171401_58_dialog_content = "但是躲在泥潭中的暗鬼，隨時有可能出現！",
  ui_story_1017_10171401_59_dialog_content = "我能感應到「中心」離我們越來越近了！",
  ui_story_1017_10171401_60_dialog_content = "知道為什麼嗎？",
  ui_story_1017_10171401_61_dialog_content = "為什麼？",
  ui_story_1017_10171401_62_dialog_content = "因為我去到哪，「中心」就指向哪。",
  ui_story_1017_10171401_63_dialog_content = "啊？",
  ui_story_1017_10171401_64_dialog_content = "此前怎麼也找不到阿克希亞的隊伍，很有可能是她在這附近設了據點，讓泥潭隔絕我們。",
  ui_story_1017_10171401_65_dialog_content = "讓暗鬼從四面八方擾亂隊伍，就是在拖延時間，為最後的進攻做準備。",
  ui_story_1017_10171401_66_dialog_content = "最後才把我引到這裡，哈哈，是終於被我打怕了嗎？",
  ui_story_1017_10171401_67_dialog_content = "可是「中心」敵人為什麼要這麼做？",
  ui_story_1017_10171401_68_dialog_content = "哼，針對我的部下，然後針對我。她躲在泥潭背後，一定很痛恨啟光吧。",
  ui_story_1017_10171401_69_dialog_content = "妳知道是誰？",
  ui_story_1017_10171401_70_dialog_content = "當然。只要打敗泥潭的「中心」，她就無處可躲了。",
  ui_story_1017_10171401_71_dialog_content = "前方五百公尺，有巨大暗能團迅速向此處移動。",
  ui_story_1017_10171401_72_dialog_content = "雷霆，臨空者號偵測到——",
  ui_story_1017_10171401_73_dialog_content = "小心腳下！",
  ui_story_1017_10171401_74_dialog_content = "李奧！你們怎麼來了？",
  ui_story_1017_10171401_75_dialog_content = "那暗鬼四處從泥潭冒出來，但行動幾乎都指向同一個方向。",
  ui_story_1017_10171401_76_dialog_content = "所以，你是來興師問罪的？",
  ui_story_1017_10171401_77_dialog_content = "不是。黃昏鎮會保護每一個為它而戰的夥伴。",
  ui_story_1017_10171401_78_dialog_content = "您一直在調查士兵情況，是位言而有信的元帥。",
  ui_story_1017_10171401_79_dialog_content = "今天這場仗打得太久了，一起結束吧。",
  ui_story_1017_10171401_80_dialog_content = "正合我意。結束之後，可別忘了我們的較量。",
  ui_story_1017_10171401_81_dialog_content = "當然。",
  ui_story_1017_10171401_82_dialog_content = "（身體還有力量……意識清醒……）",
  ui_story_1017_10171401_83_dialog_content = "（希望這是最後一次對部下下達進攻命令。）",
  ui_story_1017_10171401_84_dialog_content = "PlayerName，一百公尺。",
  ui_story_1017_10171401_85_dialog_content = "敵人預計五秒後進入你的感應範圍。",
  ui_story_1017_10171401_86_dialog_content = "這麼近的距離卻看不見牠的身影……只能用感應能力……",
  ui_story_1017_10171401_87_dialog_content = "<嗷——>",
  ui_story_1017_10171401_88_dialog_content = "這……這究竟是……",
  ui_story_1017_10171401_89_dialog_content = "雷霆！敵人有著血漿四濺的嘴巴……",
  ui_story_1017_10171401_90_dialog_content = "牠、足以將我們一口吞下……",
  ui_story_1017_10171401_91_dialog_content = "「引擎七號」掩護！",
  ui_story_1017_10171401_92_dialog_content = "這狂風，是敵人帶來的嗎……",
  ui_story_1017_10171401_93_dialog_content = "你、你們看，泥潭中隆起的那個……",
  ui_story_1017_10171401_94_dialog_content = "<嗷！！！>",
  ui_story_1017_10171401_95_dialog_content = "這股暗能比剛才那次進攻還……令人難受。大家小心！",
  ui_story_1017_10171401_96_dialog_content = "大元帥！我們要怎麼——",
  ui_story_1017_10171401_97_dialog_content = "前面的士兵都被捲入泥潭了！",
  ui_story_1017_10171401_98_dialog_content = "……",
  ui_story_1017_10171401_99_dialog_content = "（不……我還可以……）",
  ui_story_1017_10171401_100_dialog_content = "雷霆！泥潭擴散過來了！快離開！",
  ui_story_1017_10171401_101_dialog_content = "近衛軍團聽令——",
  ui_story_1017_10171401_102_dialog_content = "……",
  ui_story_1017_10171401_103_dialog_content = "（連下令的聲音……都……）",
  ui_story_1017_10171401_104_dialog_content = "其他人……退到泥潭之外……",
  ui_story_1017_10171401_105_dialog_content = "務必，離我遠一點……",
  ui_story_1017_10171401_106_dialog_content = "各位，隨我衝入泥潭，掩護啟光軍隊撤退！",
  ui_story_1017_10171401_107_dialog_content = "雷霆大元帥，撐住！",
  ui_story_1017_10171401_108_dialog_content = "離我遠一點！",
  ui_story_1017_10171401_109_dialog_content = "……",
  ui_story_1017_10171401_110_dialog_content = "雷霆！妳的身體已經不能再逞強了！",
  ui_story_1017_10171401_111_dialog_content = "騎士……保護我的部下……我拜託你……",
  ui_story_1017_10171401_112_dialog_content = "無論暗鬼、還是什麼，我……絕不認輸……",
  ui_story_1017_10171401_113_dialog_content = "既然如此……",
  ui_story_1017_10171401_114_dialog_content = "PlayerName，上馬！",
  ui_story_1017_10171401_115_dialog_content = "（如果雷霆再次陷入泥潭……）",
  ui_story_1017_10171401_116_dialog_content = "雷霆——別忘了，妳和萊因哈特的戰鬥還沒有結束！",
  ui_story_1017_10171401_117_dialog_content = "！！！",
  ui_story_1017_10171401_118_dialog_content = "（集中……精神……）",
  ui_story_1017_10171401_119_dialog_content = "（這是……）",
  ui_story_1017_10171401_120_dialog_content = "（屬於我……大元帥雷霆的……戰爭……）",
  ui_story_1017_10171402_1_dialog_content = "<color=#e8d9bb>黃昏鎮上，已是泥濘一片……</color>",
  ui_story_1017_10171402_2_dialog_content = "團長！防線已經失守，泥潭湧進黃昏鎮，居民們陷入了恐慌！",
  ui_story_1017_10171402_3_dialog_content = "……啟光大元帥也捲進泥潭中了……",
  ui_story_1017_10171402_4_dialog_content = "先把居民護送到醫院去，我們繼續搜索。",
  ui_story_1017_10171402_X1_dialog_content = "快跑啊！污泥湧進鎮子裡啦！",
  ui_story_1017_10171402_X2_dialog_content = "怎麼會這樣！孩子……我的孩子呢？",
  ui_story_1017_10171402_X3_dialog_content = "喬瑟琳姐姐，還在戰場上……",
  ui_story_1017_10171402_X4_dialog_content = "防線已經失守，泥潭湧進黃昏鎮，居民們陷入了恐慌！",
  ui_story_1017_10171402_X5_dialog_content = "團長還在黃昏鎮外……快去通知團長！",
  ui_story_1017_10171402_5_dialog_content = "大元帥——",
  ui_story_1017_10171402_6_dialog_content = "雷霆！雷……",
  ui_story_1017_10171402_7_dialog_content = "PlayerName，還撐得下去嗎？",
  ui_story_1017_10171402_8_dialog_content = "我沒事……只是戰鬥太久，暫時不能再使用感應能力了。",
  ui_story_1017_10171402_9_dialog_content = "我們也已經把這附近找遍了……",
  ui_story_1017_10171402_10_dialog_content = "剛才在暗鬼倒下之前，我就完全感應不到她的位置……",
  ui_story_1017_10171402_11_dialog_content = "臨空者號最後一次看見她，是在敵人嘴邊，渾身沾滿泥漿……",
  ui_story_1017_10171402_12_dialog_content = "都是我不好……我沒有跟緊她……",
  ui_story_1017_10171402_13_dialog_content = "眼看著她雙眼渙散地衝向敵人，明明已經消耗過度……",
  ui_story_1017_10171402_14_dialog_content = "卻還故意將暗鬼引到別處去……",
  ui_story_1017_10171402_15_dialog_content = "這不是你的錯。正是大家彼此合作，才戰勝了敵人。",
  ui_story_1017_10171402_16_dialog_content = "只是為了保護大家，雷霆大元帥竟下令「引擎七號」阻擋我們支援……",
  ui_story_1017_10171402_17_dialog_content = "這麼危險的行為……她和她的部下，都太拼了。",
  ui_story_1017_10171402_18_dialog_content = "……",
  ui_story_1017_10171402_19_dialog_content = "阿克希亞活了下來，但阿克希亞找不到雷霆大元帥。",
  ui_story_1017_10171402_20_dialog_content = "阿克希亞，妳沒事就好。",
  ui_story_1017_10171402_21_dialog_content = "雷霆大元帥是啟光戰士，「啟光戰士有活下去的權利」。",
  ui_story_1017_10171402_22_dialog_content = "……",
  ui_story_1017_10171402_23_dialog_content = "我們加快速度，再往附近區域找一圈。",
  ui_story_1017_10171402_24_dialog_content = "新的敵人若是現在進攻，要找到她就更難了！",
  ui_story_1017_10171402_25_dialog_content = "嗯！",
  ui_story_1017_10171402_26_dialog_content = "PlayerName，黃昏鎮範圍內，尚未搜索到雷霆的蹤跡。",
  ui_story_1017_10171402_27_dialog_content = "根據搜救時間推測，雷霆戰亡率：99%。",
  ui_story_1017_10171402_28_dialog_content = "不可能……",
  ui_story_1017_10171402_29_dialog_content = "這不可能！",
  ui_story_1017_10171402_30_dialog_content = "<size=50>雷霆！ ！ ！</size>",
  ui_story_1017_10171501_1_dialog_content = "（這裡是……天黑之後的黃昏鎮？）",
  ui_story_1017_10171501_2_dialog_content = "（只有我一個人……）",
  ui_story_1017_10171501_3_dialog_content = "（呵，又脫隊了。萊因哈特那傢伙，還是這麼能打……）",
  ui_story_1017_10171501_4_dialog_content = "（身體……好重，完全使不上力……）",
  ui_story_1017_10171501_5_dialog_content = "（地下城……安靜得……難受……）",
  ui_story_1017_10171501_6_dialog_content = "（後背的東西，該死……）",
  ui_story_1017_10171501_7_dialog_content = "（輸給萊因哈特後，他們在我身體裡拴了鐵鍊……）",
  ui_story_1017_10171501_8_dialog_content = "（輸了最後對決，這就是我要付出的代價嗎……）",
  ui_story_1017_10171501_9_dialog_content = "（戰鬥……明明還沒有結束……）",
  ui_story_1017_10171501_10_dialog_content = "（那東西……傷不了我！）",
  ui_story_1017_10171501_11_dialog_content = "（傷不了！）",
  ui_story_1017_10171501_12_dialog_content = "（我、要求再戰……）",
  ui_story_1017_10171501_13_dialog_content = "（觀眾席上，全在喊我的名字……）",
  ui_story_1017_10171501_14_dialog_content = "（把我的雷槍……軍裝……還給我……）",
  ui_story_1017_10171501_15_dialog_content = "（我……要成為啟光大元帥……）",
  ui_story_1017_10171501_16_dialog_content = "（誰也……攔不住我……）",
  ui_story_1017_10171501_17_dialog_content = "幾天前，啟光高層密談會上……",
  ui_story_1017_10171501_18_dialog_content = "長官，人已經帶到了。",
  ui_story_1017_10171501_19_dialog_content = "坐吧。",
  ui_story_1017_10171501_20_dialog_content = "有什麼事直接說吧，我還有任務在身。",
  ui_story_1017_10171501_21_dialog_content = "坐。",
  ui_story_1017_10171501_22_dialog_content = "……",
  ui_story_1017_10171501_23_dialog_content = "如果讓妳來擔任啟光的大元帥，妳會怎麼想？",
  ui_story_1017_10171501_24_dialog_content = "我？為什麼？",
  ui_story_1017_10171501_25_dialog_content = "因為妳想，因為啟光聯邦需要。",
  ui_story_1017_10171501_26_dialog_content = "我不明白，萊因哈特做錯了什麼？",
  ui_story_1017_10171501_27_dialog_content = "審訊會上已經說得夠清楚了，你也在場不是嗎？",
  ui_story_1017_10171501_28_dialog_content = "真相不是那樣，你們到底有什麼目的？",
  ui_story_1017_10171501_29_dialog_content = "妳看到的不一定是真相，不妨現實一點。",
  ui_story_1017_10171501_30_dialog_content = "考慮一下，是妳來做大元帥，還是其他人。",
  ui_story_1017_10171501_31_dialog_content = "他們三個知道嗎？",
  ui_story_1017_10171501_32_dialog_content = "這取決於妳。我希望妳慎重考慮。",
  ui_story_1017_10171501_33_dialog_content = "……",
  ui_story_1017_10171501_34_dialog_content = "尤利西斯，你不是有話要說？",
  ui_story_1017_10171501_35_dialog_content = "你各方面條件都不錯，唯一的不足之處是身體素質。",
  ui_story_1017_10171501_36_dialog_content = "成為大元帥，我會將你的不足補齊。",
  ui_story_1017_10171501_37_dialog_content = "……",
  ui_story_1017_10171501_38_dialog_content = "你想怎麼做？",
  ui_story_1017_10171501_39_dialog_content = "不必擔心，只是和萊因哈特一樣參加一場小小的實驗而已。",
  ui_story_1017_10171501_40_dialog_content = "改造身體機能，成為啟光最強的戰士。",
  ui_story_1017_10171501_41_dialog_content = "萊因哈特的身體有改造過？！",
  ui_story_1017_10171501_42_dialog_content = "很意外嗎？",
  ui_story_1017_10171501_43_dialog_content = "（萊因哈特？！）",
  ui_story_1017_10171501_44_dialog_content = "（強大！戰無不勝！無法逾越的高峰？！）",
  ui_story_1017_10171501_45_dialog_content = "（……全都是假的！）",
  ui_story_1017_10171501_46_dialog_content = "她參加「人造太陽」計畫的時候，年紀還小。",
  ui_story_1017_10171501_47_dialog_content = "就算她知道真相卻不願告訴妳也很正常，誰都希望自己的強大是天生的。",
  ui_story_1017_10171501_48_dialog_content = "……",
  ui_story_1017_10171501_49_dialog_content = "想知道妳是不是天生的大元帥，需要機會去證明。",
  ui_story_1017_10171501_50_dialog_content = "現在，機會就擺在妳眼前。",
  ui_story_1017_10171501_51_dialog_content = "什麼機會？",
  ui_story_1017_10171501_52_dialog_content = "黃昏鎮這一帶遲早要爆發一場浩大戰爭。如果是妳的話，我有信心能打贏這一仗。",
  ui_story_1017_10171501_53_dialog_content = "我會打贏，但我會用我自己的方式。",
  ui_story_1017_10171501_54_dialog_content = "妳不必現在答覆。",
  ui_story_1017_10171501_55_dialog_content = "對了，很久之前妳說過一句話，還記得嗎？",
  ui_story_1017_10171501_56_dialog_content = "輸了對決那天，妳站在賽場邊。",
  ui_story_1017_10171501_57_dialog_content = "我說妳不該輸給她，而妳說——",
  ui_story_1017_10171501_58_dialog_content = "如果能夠突破身體極限，付出再大的代價我也願意！",
  ui_story_1017_10171501_59_dialog_content = "這就是我的答案。",
  ui_story_1017_10171501_60_dialog_content = "……",
  ui_story_1017_10171501_61_dialog_content = "<color=#e8d9bb>雷霆向巴頓、緋、希羅娜講述了密談會上的內容</color>",
  ui_story_1017_10171501_62_dialog_content = "……",
  ui_story_1017_10171501_63_dialog_content = "那群委員會的垃圾，還有什麼事情幹不出來？",
  ui_story_1017_10171501_64_dialog_content = "不是尤利西斯的人上位，我認為還有轉機。",
  ui_story_1017_10171501_65_dialog_content = "巴頓，你說呢？",
  ui_story_1017_10171501_66_dialog_content = "我沒什麼好說的，大元帥的事我不會善罷甘休。",
  ui_story_1017_10171501_67_dialog_content = "至於將來誰來接替她的位置，我無所謂。",
  ui_story_1017_10171501_68_dialog_content = "反正我不會聽萊因哈特以外的任何人差遣。",
  ui_story_1017_10171501_69_dialog_content = "如果剛才被叫去的人不是我，是你呢？",
  ui_story_1017_10171501_70_dialog_content = "哼！我不會讓尤利西斯在我身上動手術，我會把他給宰了。",
  ui_story_1017_10171501_71_dialog_content = "如果大元帥的事情是真的，那根本由不得你。",
  ui_story_1017_10171501_72_dialog_content = "眼下暗面湧動越來越頻繁，我相信上面馬上會有動作。",
  ui_story_1017_10171501_73_dialog_content = "沒有大元帥指揮，暗鬼入侵後會非常棘手。",
  ui_story_1017_10171501_74_dialog_content = "雷霆，妳可以嗎？",
  ui_story_1017_10171501_75_dialog_content = "萊因哈特當大元帥時什麼都沒怕過，我更沒什麼好怕的。",
  ui_story_1017_10171501_76_dialog_content = "萬一妳變成怪物怎麼辦？",
  ui_story_1017_10171501_77_dialog_content = "那我有一個請求。你們把萊因哈特帶到我面前，讓她親手取我性命。",
  ui_story_1017_10171501_78_dialog_content = "真是……莫名其妙。",
  ui_story_1017_10171501_79_dialog_content = "別說這些，活著回來自然能見到大元帥。",
  ui_story_1017_10171501_80_dialog_content = "妳自己去找她。",
  ui_story_1017_10171501_81_dialog_content = "等等……萊因哈特這件事我不是開玩笑。",
  ui_story_1017_10171501_82_dialog_content = "我們幾個當中，只有妳能做到。",
  ui_story_1017_10171501_83_dialog_content = "妳是說……",
  ui_story_1017_10171501_84_dialog_content = "沒錯，一旦日蝕出動，希羅娜和巴頓會立刻回戰區待命。",
  ui_story_1017_10171501_85_dialog_content = "在防線告急之前，我會讓妳的支援軍留到最後。",
  ui_story_1017_10171501_86_dialog_content = "換句話說，戰場越激烈，我們的機會越大。",
  ui_story_1017_10171501_87_dialog_content = "這麼搞不是進監獄就是死，雷霆，妳真的想清楚了嗎？",
  ui_story_1017_10171501_88_dialog_content = "想清楚了，我認為沒有其他可能性。",
  ui_story_1017_10171501_89_dialog_content = "參加「啟明星計畫」呢？",
  ui_story_1017_10171501_90_dialog_content = "……老實說，還沒有。",
  ui_story_1017_10171501_91_dialog_content = "但你們相信我，情況越危急，我越能做出準確的判斷。",
  ui_story_1017_10171501_92_dialog_content = "真的？",
  ui_story_1017_10171501_93_dialog_content = "總之，各位這一仗跟我打，不會丟啟光的臉。",
  ui_story_1017_10171501_94_dialog_content = "<color=#e8d9bb>第二天……</color>",
  ui_story_1017_10171501_95_dialog_content = "感覺怎麼樣？",
  ui_story_1017_10171501_96_dialog_content = "沒感覺。",
  ui_story_1017_10171501_97_dialog_content = "很快，妳的意識會變得模糊。",
  ui_story_1017_10171501_98_dialog_content = "等妳醒來以後，這個世界對妳來說，會公平很多。",
  ui_story_1017_10171501_99_dialog_content = "公平……",
  ui_story_1017_10171501_100_dialog_content = "強者踩著弱者往上爬，弱者只會叫囂著世界不公。",
  ui_story_1017_10171501_101_dialog_content = "認為暗鬼欺人太甚，不過是自己不夠強大。",
  ui_story_1017_10171501_102_dialog_content = "你想戰勝萊因哈特也是。",
  ui_story_1017_10171501_103_dialog_content = "手術之後，妳們的對決會公平很多。",
  ui_story_1017_10171501_104_dialog_content = "（對決……會公平很多……）",
  ui_story_1017_10171501_105_dialog_content = "（我曾以為為了實現目標，我會不惜一切代價。）",
  ui_story_1017_10171501_106_dialog_content = "（但當尖銳的器械鑽入我的身體時，我彷彿目睹著自己親手將這副軀殼拆解......）",
  ui_story_1017_10171501_107_dialog_content = "（連同野心和傲氣也一起碾得粉碎。）",
  ui_story_1017_10171501_108_dialog_content = "（一路走來，我每做出一個選擇都像是一次溺水時的掙扎……）",
  ui_story_1017_10171501_109_dialog_content = "（然而，暗潮洶湧，我卻越陷越深……）",
  ui_story_1017_10171501_110_dialog_content = "（還要繼續掙扎嗎？這真的是我想要的結果嗎？）",
  ui_story_1017_10171501_111_dialog_content = "（對決會公平很多……確實。）",
  ui_story_1017_10171501_112_dialog_content = "（但這公平終究是……）",
  ui_story_1017_10171501_113_dialog_content = "（來得太遲了……）",
  ui_story_1018_10180101_1_dialog_content = "<color=#e8d9bb>暗面隱蔽處……</color>",
  ui_story_1018_10180101_2_dialog_content = "隊長……我很慶幸剛才沒被那隻<color=#FFB400>閃著綠光的暗鬼</color>擊斃！",
  ui_story_1018_10180101_3_dialog_content = "一路上遇到的巨型冰柱和奇異冰錐，完全超出了我對永夜地區的想像……",
  ui_story_1018_10180101_4_dialog_content = "但我們的任務明明是追蹤「守護者一號」的核心，為什麼我們要躲在這裡觀察暗鬼呢？",
  ui_story_1018_10180101_5_dialog_content = "噓！小聲點！",
  ui_story_1018_10180101_6_dialog_content = "噢……我只是看你剛才那麼興奮，還以為已經追到<color=#FFB400>暗鬼大本營</color>了……",
  ui_story_1018_10180101_7_dialog_content = "可是這個地方<color=#FFB400>一片平坦</color>，只是每隔一段距離就有暗鬼圍成一團……",
  ui_story_1018_10180101_8_dialog_content = "我實在不明白牠們有什麼值得盯著看的地方。",
  ui_story_1018_10180101_9_dialog_content = "嗯～事實證明，你的思維方式和暗鬼一樣楞頭楞腦。",
  ui_story_1018_10180101_10_dialog_content = "回去以後可別告訴別人你是我的隊員啊！",
  ui_story_1018_10180101_11_dialog_content = "啊？這次又是怎麼回事啊……",
  ui_story_1018_10180101_12_dialog_content = "追蹤的心法，就是要化被動為主動，想敵人之所想。",
  ui_story_1018_10180101_13_dialog_content = "那隻帶走核心的暗鬼費盡心思把我們攔在奇怪的地方，就是不想讓我們來到這裡。",
  ui_story_1018_10180101_14_dialog_content = "說到底，偷東西的賊最害怕被人發現他們的老巢。",
  ui_story_1018_10180101_15_dialog_content = "這裡表面上看起來平坦無奇，但有那麼多暗鬼看守，這個地方對日蝕來說一定非常重要。",
  ui_story_1018_10180101_16_dialog_content = "那……暗鬼群到底在看守什麼東西啊？",
  ui_story_1018_10180101_17_dialog_content = "如果沒猜錯，那東西的重要性與「守護者一號」的核心不相上下。",
  ui_story_1018_10180101_18_dialog_content = "看這個……",
  ui_story_1018_10180101_19_dialog_content = "隊長！暗鬼忽然躁動起來！",
  ui_story_1018_10180101_20_dialog_content = "看吧，那東西和「守護者一號」的核心一樣，會對它起反應。",
  ui_story_1018_10180101_21_dialog_content = "果然是在醞釀一起大工程。",
  ui_story_1018_10180101_22_dialog_content = "妳的意思是，除了「守護者一號」的核心外，我們還有意外收穫？",
  ui_story_1018_10180101_23_dialog_content = "哼哼，適時給貝利撒留一些驚喜也很有意思吧，你說呢？",
  ui_story_1018_10180101_24_dialog_content = "隊長果然是偵察高手！",
  ui_story_1018_10180101_25_dialog_content = "但是我擔心……暗鬼在那之前就先把我們解決掉。",
  ui_story_1018_10180101_26_dialog_content = "有點自信好不好，我們搭的交通工具與暗面環境幾乎融為一體。",
  ui_story_1018_10180101_27_dialog_content = "列車外部的塗層經過特殊處理，能與周圍的環境無縫結合。",
  ui_story_1018_10180101_28_dialog_content = "會挑選你們加入，也是因為你們光能氣息微弱，不容易被暗鬼發現。",
  ui_story_1018_10180101_29_dialog_content = "這該不會就是你們無法提升光能術的原因吧……？",
  ui_story_1018_10180101_30_dialog_content = "唉……以前我的長官告訴過我，這輩子註定只能當個司機。",
  ui_story_1018_10180101_31_dialog_content = "喂，我亂講的啦。回去記得告訴他，你現在是跟著我深入暗面的司機了！",
  ui_story_1018_10180101_32_dialog_content = "總之，過來人的經驗，越接近暗面反而越安全。",
  ui_story_1018_10180101_33_dialog_content = "隊長……妳真的不是前日蝕成員叛變加入啟光的嗎？",
  ui_story_1018_10180101_34_dialog_content = "你應該問我，是不是之前的啟光成員，現在叛變加入日蝕了。",
  ui_story_1018_10180101_35_dialog_content = "……",
  ui_story_1018_10180101_36_dialog_content = "你們慢慢靠近掩護我，動作輕一點。",
  ui_story_1018_10180101_37_dialog_content = "我去看看，這個和「守護者一號」的核心相似的東西到底是什麼。",
  ui_story_1018_10180101_38_dialog_content = "知道了，隊長。我們要把現在座標發給後方的追蹤隊嗎？",
  ui_story_1018_10180101_39_dialog_content = "等他們脫離險境再說吧……他們的行動似乎並不順利。",
  ui_story_1018_10180101_40_dialog_content = "<color=#e8d9bb>白夜城朝堂</color>",
  ui_story_1018_10180101_41_dialog_content = "城主大人，支援軍如果只是保護白夜要塞，那他們去黃昏鎮的用意何在？",
  ui_story_1018_10180101_42_dialog_content = "你知道啟光的新軍部隊是如何成立的嗎？",
  ui_story_1018_10180101_43_dialog_content = "您為何要問這個？",
  ui_story_1018_10180101_44_dialog_content = "妳看看。",
  ui_story_1018_10180101_45_dialog_content = "這是……黃昏鎮白夜教區的緊急來信，甚至沒寫名字。",
  ui_story_1018_10180101_46_dialog_content = "「泥潭衝垮黃昏鎮壁壘、暗鬼肆虐，啟光軍與騎士團聯合抵抗但效果甚微……」",
  ui_story_1018_10180101_47_dialog_content = "「啟光士兵吃盡苦頭，軍隊損失慘重，大元帥至今下落不明……僅騎士團堅守戰場。」",
  ui_story_1018_10180101_48_dialog_content = "「醫療設施人滿為患、物資短缺，百姓危在旦夕……」",
  ui_story_1018_10180101_49_dialog_content = "……大元帥下落不明……怎麼會這樣！",
  ui_story_1018_10180101_50_dialog_content = "啟光聯邦不是沒有打過敗仗，但我從未見過像黃昏鎮之戰這樣的局面。",
  ui_story_1018_10180101_51_dialog_content = "即使如此，啟光聯邦的其他軍團仍然堅守在迦南城，未越過防線半步。",
  ui_story_1018_10180101_52_dialog_content = "他們根本無意支援黃昏鎮，而是假借新元帥上任，檢驗新軍科技的實力。",
  ui_story_1018_10180101_53_dialog_content = "如此下去，新軍部隊都將成為這場檢驗的犧牲品。",
  ui_story_1018_10180101_54_dialog_content = "城主大人！您一直都知道？",
  ui_story_1018_10180101_55_dialog_content = "不過是歷史重演而已，啟光聯邦所做之事從未偏離過初心。",
  ui_story_1018_10180101_56_dialog_content = "那仍在前線作戰的士兵怎麼辦？",
  ui_story_1018_10180101_57_dialog_content = "我認為拋開啟光不論，支援軍必須保證黃昏鎮百姓的安全。",
  ui_story_1018_10180101_58_dialog_content = "我在考慮。",
  ui_story_1018_10180101_59_dialog_content = "……您若是繼續拖延下去，不僅黃昏鎮，白夜城的地面城鎮也會受到影響！",
  ui_story_1018_10180101_60_dialog_content = "<size=45>我在考慮。</size>",
  ui_story_1018_10180101_61_dialog_content = "……",
  ui_story_1018_10180101_62_dialog_content = "城主大人，影主伊斯塔萬的信使求見。",
  ui_story_1018_10180101_63_dialog_content = "讓他進來。",
  ui_story_1018_10180101_64_dialog_content = "這浮空小島還是一如既往的冷清啊。拜見城主大人和卡蓮殿下。",
  ui_story_1018_10180101_65_dialog_content = "來自喧囂之城的信使，來為何事？",
  ui_story_1018_10180101_66_dialog_content = "原來我還有信使這層身分啊。",
  ui_story_1018_10180101_67_dialog_content = "我不過是受伊斯塔萬所托，向您傳幾句話。",
  ui_story_1018_10180101_68_dialog_content = "黃昏鎮的戰鬥，相信城主大人也在關注。",
  ui_story_1018_10180101_69_dialog_content = "您既然派了支援軍，卻不打算管周圍城鎮的死活，這是為什麼呢？",
  ui_story_1018_10180101_70_dialog_content = "這是伊斯塔萬的原話？",
  ui_story_1018_10180101_71_dialog_content = "嗯……稍加潤色而已。",
  ui_story_1018_10180101_72_dialog_content = "城主有所不知，一名來自黃昏鎮的客人，在去拜訪您的路上因機緣巧合，與伊斯塔萬意趣相投……",
  ui_story_1018_10180101_73_dialog_content = "就在他說明事情原委之後，黃昏鎮那邊好像更糟了。",
  ui_story_1018_10180101_74_dialog_content = "這名黃昏鎮的人，是否是昭？",
  ui_story_1018_10180101_75_dialog_content = "喔對，就是這個名字！",
  ui_story_1018_10180101_76_dialog_content = "報告城主大人，來自黃昏鎮的昭求見。",
  ui_story_1018_10180101_77_dialog_content = "瞧，這麼快就到了。",
  ui_story_1018_10180101_78_dialog_content = "白夜城對外的交通運輸已經停駛了。",
  ui_story_1018_10180101_79_dialog_content = "只要伊斯塔萬有意願，就沒有辦不到的事情。",
  ui_story_1018_10180101_80_dialog_content = "這位昭靠一己之力輾轉於各大勢力，啟光之後是影鎮，影鎮之後是白夜城。",
  ui_story_1018_10180101_81_dialog_content = "若被您拒於門外，還會前往北境、紅油沙漠……",
  ui_story_1018_10180101_82_dialog_content = "「身體雖孱弱，卻有不達目的誓不甘休之決心，這就是門外求見之人，昭。」",
  ui_story_1018_10180101_83_dialog_content = "這句倒是伊斯塔萬原話。",
  ui_story_1018_10180101_84_dialog_content = "黃昏鎮這塊燙手山芋他倒接手得很快。伊斯塔萬為何不親自前來？",
  ui_story_1018_10180101_85_dialog_content = "我只負責傳話，其他的，城主問問門外的客人便知。",
  ui_story_1018_10180101_86_dialog_content = "這地方太亮了，我還是回我的深海去。城主大人和卡蓮殿下不用送我了。",
  ui_story_1018_10180101_87_dialog_content = "……",
  ui_story_1018_10180101_88_dialog_content = "您不打算傳昭進來嗎？",
  ui_story_1018_10180101_89_dialog_content = "黃昏鎮的問題僅涉及白夜城和啟光聯邦，他人無權參與談判。",
  ui_story_1018_10180101_90_dialog_content = "既然啟光聯邦表明了他們的意圖，黃昏鎮只能由白夜城來守護。",
  ui_story_1018_10180101_91_dialog_content = "隨我啟程。",
  ui_story_1018_10180101_92_dialog_content = "您要親自前往黃昏鎮嗎？",
  ui_story_1018_10180101_93_dialog_content = "我不是那把揭下遮羞布的劍。啟光褻瀆光靈的行為，必須交由神殿代為審判。",
  ui_story_1018_10180201_1_dialog_content = "<color=#e8d9bb>黃昏鎮</color>",
  ui_story_1018_10180201_2_dialog_content = "（已經搜索那麼久了……）",
  ui_story_1018_10180201_3_dialog_content = "（雷霆……妳到底在哪裡……）",
  ui_story_1018_10180201_4_dialog_content = "團長，擊敗「中心」敵人後，隨泥潭湧入的暗鬼已經全部消滅了。",
  ui_story_1018_10180201_5_dialog_content = "雖然泥潭還在，但黃昏鎮暫時沒有危險了。",
  ui_story_1018_10180201_6_dialog_content = "目前的戰況，您認為算是告一段落了嗎？",
  ui_story_1018_10180201_7_dialog_content = "雖然戰場有外移趨勢，但離完全結束可能還要一段時間。",
  ui_story_1018_10180201_8_dialog_content = "PlayerName，黃昏鎮目前的暗能已經消散不少了吧？",
  ui_story_1018_10180201_9_dialog_content = "嗯，臨空者號也沒再發現暗能聚集的敵人了。",
  ui_story_1018_10180201_10_dialog_content = "不過泥潭還是覆蓋著黃昏鎮，這仍然是個隱憂。",
  ui_story_1018_10180201_11_dialog_content = "沒錯……這些受到泥潭影響的士兵，醫護院也只是暫時穩住他們的狀態，並未找到治療的關鍵。",
  ui_story_1018_10180201_12_dialog_content = "拖下去確實很棘手……",
  ui_story_1018_10180201_13_dialog_content = "團長，黃昏鎮百姓已經全部遷往臨時醫護院裡了。",
  ui_story_1018_10180201_14_dialog_content = "靠近腹地一側的居民都願意出借自己的房子收留難民。",
  ui_story_1018_10180201_15_dialog_content = "大部分百姓能夠免受傷害，都是多虧各位拼死抵抗。",
  ui_story_1018_10180201_16_dialog_content = "但是一起待在黃昏鎮上也不是辦法。下一步我會考慮將難民轉移到啟光防線附近的城鎮。",
  ui_story_1018_10180201_17_dialog_content = "團長，目前外圍戰區還未整理過，我擔心現在轉移有危險。",
  ui_story_1018_10180201_18_dialog_content = "雷霆大元帥和與她衝鋒陷陣的部下也受困其中，仍然下落不明……",
  ui_story_1018_10180201_19_dialog_content = "先做準備工作吧，等戰場局勢明朗之後再做進一步打算。",
  ui_story_1018_10180201_20_dialog_content = "這位士兵，請問你們的失蹤人數粗略估計有多少？",
  ui_story_1018_10180201_21_dialog_content = "和大元帥一起衝鋒的有兩支隊伍，人數過百……",
  ui_story_1018_10180201_22_dialog_content = "而且幾乎都是……是新兵。",
  ui_story_1018_10180201_23_dialog_content = "這幾乎是半個「鐵棘騎士團」的兵力了。",
  ui_story_1018_10180201_24_dialog_content = "團長，西側圍牆邊找到少量士兵，情況不明，弟兄們沒有靠近。",
  ui_story_1018_10180201_25_dialog_content = "立刻過去看看情況！",
  ui_story_1018_10180201_26_dialog_content = "他們……沒錯，都是和大元帥一起衝鋒的士兵。",
  ui_story_1018_10180201_27_dialog_content = "放眼望去，又犧牲了數十名……",
  ui_story_1018_10180201_28_dialog_content = "……將犧牲的戰士小心搬到軍營裡，小心潛伏在泥潭中的敵人。",
  ui_story_1018_10180201_29_dialog_content = "是！",
  ui_story_1018_10180201_30_dialog_content = "……",
  ui_story_1018_10180201_31_dialog_content = "就這麼犧牲了……都還來不及認識他們……",
  ui_story_1018_10180201_32_dialog_content = "這就是軍人，PlayerName。",
  ui_story_1018_10180201_33_dialog_content = "常年面對戰爭，有時根本沒時間為失去的戰友哀悼，就要奔赴下一個戰場。",
  ui_story_1018_10180201_34_dialog_content = "……",
  ui_story_1018_10180201_35_dialog_content = "李奧，這裡有位戰士還有呼吸！",
  ui_story_1018_10180201_36_dialog_content = "情況如何？",
  ui_story_1018_10180201_37_dialog_content = "暫時能透過治療來穩住生命徵象……",
  ui_story_1018_10180201_38_dialog_content = "……",
  ui_story_1018_10180201_39_dialog_content = "是在害怕嗎……還是想說話？",
  ui_story_1018_10180201_40_dialog_content = "他好像……在嚼什麼東西。",
  ui_story_1018_10180201_41_dialog_content = "嗷！！！",
  ui_story_1018_10180201_42_dialog_content = "劍如閃電！",
  ui_story_1018_10180201_43_dialog_content = "突然變成……暗鬼了？！",
  ui_story_1018_10180201_44_dialog_content = "果然，我最擔心的情況還是發生了……",
  ui_story_1018_10180201_45_dialog_content = "嗷！！！",
  ui_story_1018_10180201_46_dialog_content = "那邊也是？",
  ui_story_1018_10180201_47_dialog_content = "團長！這些已經犧牲的士兵……不，是「暗鬼」突然向我們發動攻擊！",
  ui_story_1018_10180201_48_dialog_content = "不行，情況比我想得要複雜，不能簡單搜索治療！",
  ui_story_1018_10180201_49_dialog_content = "各位準備戰鬥！",
  ui_story_1018_10180201_50_dialog_content = "慢著，李奧……",
  ui_story_1018_10180202_1_dialog_content = "這些士兵……全都死了嗎……",
  ui_story_1018_10180202_2_dialog_content = "……",
  ui_story_1018_10180202_3_dialog_content = "不必為暗鬼感到惋惜。",
  ui_story_1018_10180202_4_dialog_content = "縱使他們曾經是戰士，如果繼續站在戰場上，只會造成更大的傷亡。",
  ui_story_1018_10180202_5_dialog_content = "啟光士兵，這裡交給我們，你們迅速離開黃昏鎮！",
  ui_story_1018_10180202_6_dialog_content = "李奧團長，啟光士兵……還不能離開黃昏鎮。",
  ui_story_1018_10180202_7_dialog_content = "我說，所有啟光士兵，離開黃昏鎮。",
  ui_story_1018_10180202_8_dialog_content = "……",
  ui_story_1018_10180202_9_dialog_content = "既然如此，李奧團長，我必須說明一個情況。",
  ui_story_1018_10180202_10_dialog_content = "等我說完之後，您再考慮是否要下令我們離開。",
  ui_story_1018_10180202_11_dialog_content = "說。",
  ui_story_1018_10180202_12_dialog_content = "在來黃昏鎮之前，我們啟光近衛軍團是由啟光最精銳的一群士兵組成，所以也叫「精銳預備隊」。",
  ui_story_1018_10180202_13_dialog_content = "站在我身後的弟兄們都是精銳預備隊的一員，一直追隨雷霆大元帥。",
  ui_story_1018_10180202_14_dialog_content = "雖然沒參加過這樣的戰爭，但是我們能撐到現在，足以證明我們的實力。",
  ui_story_1018_10180202_15_dialog_content = "我知道你想說什麼。這些突然變成暗鬼的新兵，在啟光接受過特殊培訓。",
  ui_story_1018_10180202_16_dialog_content = "來到黃昏鎮後，他們因此受到泥潭的影響，包括你們的大元帥。",
  ui_story_1018_10180202_17_dialog_content = "沒錯……但是我保證，在走上戰場之前，我們並沒有料到會發生這種事。",
  ui_story_1018_10180202_18_dialog_content = "失去這麼多弟兄，現在大元帥還下落不明，我們都很難過。",
  ui_story_1018_10180202_19_dialog_content = "所以我代表精銳預備隊的士兵表達訴求，請讓我們留下來守護黃昏鎮。",
  ui_story_1018_10180202_20_dialog_content = "在找到大元帥之前，這是我們以「啟光軍人」身分所接到的命令。",
  ui_story_1018_10180202_21_dialog_content = "我們自願加入保護黃昏鎮的隊伍，由我暫代大元帥指揮。",
  ui_story_1018_10180202_22_dialog_content = "真是什麼樣的團長，就有什麼樣的兵。",
  ui_story_1018_10180202_23_dialog_content = "即使敵人是你們曾經的同胞？",
  ui_story_1018_10180202_24_dialog_content = "即使他們變成破壞黃昏鎮的暗鬼……我也會毫不留情……",
  ui_story_1018_10180202_25_dialog_content = "嗷！！！",
  ui_story_1018_10180202_26_dialog_content = "團長，這邊還有幾隻！",
  ui_story_1018_10180202_27_dialog_content = "這……",
  ui_story_1018_10180202_28_dialog_content = "哼……劍如閃電！",
  ui_story_1018_10180202_29_dialog_content = "你的行為與剛才的誓言相悖，士兵。先退到一邊吧，他們已經沒救了。",
  ui_story_1018_10180202_30_dialog_content = "李奧，先別下定論。那些沒攻擊我們的人並不是完全沒救。",
  ui_story_1018_10180202_31_dialog_content = "是啊……他們好像有猶豫……",
  ui_story_1018_10180202_32_dialog_content = "剛剛的情況你們也看到了，遲疑不過是給了他們傷害你的機會。",
  ui_story_1018_10180202_33_dialog_content = "但他們也是光靈啊——",
  ui_story_1018_10180202_34_dialog_content = "嗷！！！",
  ui_story_1018_10180202_35_dialog_content = "看清楚！他們與暗鬼無異！傷害黃昏鎮士兵的都是敵人！",
  ui_story_1018_10180202_36_dialog_content = "啟光的士兵！如果你們想保護黃昏鎮，面對敵人就不要手軟！",
  ui_story_1018_10180202_37_dialog_content = "否則，離開黃昏鎮後，你們的任務就到此為止。",
  ui_story_1018_10180202_38_dialog_content = "我——",
  ui_story_1018_10180202_39_dialog_content = "輪不到、你來對我的部下指指點點……",
  ui_story_1018_10180202_40_dialog_content = "受到暗能影響……但他們……罪不至死……",
  ui_story_1018_10180202_41_dialog_content = "我肯定……",
  ui_story_1018_10180202_42_dialog_content = "李奧，是雷霆！",
  ui_story_1018_10180202_43_dialog_content = "……",
  ui_story_1018_10180202_44_dialog_content = "因為我……經歷過……",
  ui_story_1018_10180202_45_dialog_content = "大元帥！",
  ui_story_1018_10180301_1_dialog_content = "雷霆！我們找妳找了好久！",
  ui_story_1018_10180301_2_dialog_content = "妳才一出現……就把這些發狂的士兵控制住了……",
  ui_story_1018_10180301_3_dialog_content = "受到泥潭影響……會控制不住身體裡的力量……",
  ui_story_1018_10180301_4_dialog_content = "他們不是有意要……傷害大家……",
  ui_story_1018_10180301_5_dialog_content = "……",
  ui_story_1018_10180301_6_dialog_content = "白夜至上……大元帥您平安無事！",
  ui_story_1018_10180301_7_option_content = "妳看起來很虛弱",
  ui_story_1018_10180301_8_dialog_content = "有沒有哪裡不舒服？",
  ui_story_1018_10180301_9_dialog_content = "除了被泥潭衝撞那幾下感覺到痛之外……",
  ui_story_1018_10180301_10_dialog_content = "其他的我都不記得了……",
  ui_story_1018_10180301_11_option_content = "之前到底是怎麼回事？",
  ui_story_1018_10180301_12_dialog_content = "我們怎樣都找不到妳！",
  ui_story_1018_10180301_13_dialog_content = "我也不是很清楚……",
  ui_story_1018_10180301_14_dialog_content = "只記得衝破泥潭包圍之後，眼前陷入一片黑暗……",
  ui_story_1018_10180301_15_dialog_content = "放心……不過是、弄得一身泥而已……",
  ui_story_1018_10180301_16_dialog_content = "這樣的士兵還有多少……",
  ui_story_1018_10180301_17_dialog_content = "李奧其實一直在搜索他們的下落……",
  ui_story_1018_10180301_18_dialog_content = "還好你回來了！",
  ui_story_1018_10180301_19_dialog_content = "嗯……",
  ui_story_1018_10180301_20_dialog_content = "我說過了，變成暗鬼之前，我會好好守護黃昏鎮……",
  ui_story_1018_10180301_21_dialog_content = "如今……還要加上我的部下……",
  ui_story_1018_10180301_22_dialog_content = "要把他們當作暗鬼隨隨便便殺死……我不允許。",
  ui_story_1018_10180301_23_dialog_content = "……大元帥，您沒事就好。",
  ui_story_1018_10180301_24_dialog_content = "我從未有意傷害啟光士兵，只是出於保護黃昏鎮的考量。",
  ui_story_1018_10180301_25_dialog_content = "順境殺敵，逆境棄兵……騎士的用兵之道，恕我無法苟同……",
  ui_story_1018_10180301_26_dialog_content = "大元帥，我……",
  ui_story_1018_10180301_27_dialog_content = "現在我回來了，我的部下由我來指揮……",
  ui_story_1018_10180301_28_dialog_content = "我現在還沒力氣與你討教……你最好不要再僭越……",
  ui_story_1018_10180301_29_dialog_content = "……如您所願，大元帥。",
  ui_story_1018_10180301_30_dialog_content = "雷霆大元帥，您現在看起來非常虛弱。",
  ui_story_1018_10180301_31_dialog_content = "請您隨我前往醫護院，醫護人員會替您治療！",
  ui_story_1018_10180301_32_dialog_content = "這裡是戰場……我的部下都還站著，我不會離開。",
  ui_story_1018_10180301_33_dialog_content = "那至少……讓我為您檢查傷口，先在我的馬上休息吧！",
  ui_story_1018_10180301_34_dialog_content = "如果真是為了您的部下負責，還是檢查一下身體吧。",
  ui_story_1018_10180301_35_dialog_content = "妳深陷泥潭那麼久，還是不要冒險比較好。",
  ui_story_1018_10180301_36_dialog_content = "……那麼，拜託妳了，喬瑟琳。",
  ui_story_1018_10180301_37_dialog_content = "……白夜至上……您竟然還能施放光能術……",
  ui_story_1018_10180301_38_dialog_content = "您身上傷口很多，雖然不是致命傷，但力氣已經非常微弱了。",
  ui_story_1018_10180301_39_dialog_content = "力氣微弱……我不覺得……",
  ui_story_1018_10180301_40_dialog_content = "我反而覺得身體在迅速恢復……",
  ui_story_1018_10180301_41_dialog_content = "回想起來，昏迷的時候就有一股力量在體內亂竄……",
  ui_story_1018_10180301_42_dialog_content = "好像有人在旁邊替我治療……那感覺難以形容……",
  ui_story_1018_10180301_43_dialog_content = "治療？難道戰場上還有其他人？",
  ui_story_1018_10180301_44_dialog_content = "是很荒謬……但既然我還能站在這裡，那也不是沒有可能……",
  ui_story_1018_10180301_45_dialog_content = "只不過，我沒能保護我的部下……",
  ui_story_1018_10180301_46_dialog_content = "……大元帥，和您一起進攻的兩支隊伍，目前還未找到。",
  ui_story_1018_10180301_47_dialog_content = "阿克希亞隊長一直在帶隊搜救士兵。",
  ui_story_1018_10180301_48_dialog_content = "但……他們或許全都成為您剛剛見到的這幾名……",
  ui_story_1018_10180301_49_dialog_content = "他們……被我、親手送入險境……",
  ui_story_1018_10180301_50_dialog_content = "不是的，大元帥！是我們違抗大元帥的命令……",
  ui_story_1018_10180301_51_dialog_content = "堅持要和您一起前進！而這些新兵，也是……",
  ui_story_1018_10180301_52_dialog_content = "面對這樣的敵人，您毫不猶豫發動攻勢，扭轉了戰局。",
  ui_story_1018_10180301_53_dialog_content = "只要能盡快找到他們，或許還有救！",
  ui_story_1018_10180301_54_dialog_content = "……",
  ui_story_1018_10180301_55_dialog_content = "……無論如何，我不會再讓各位跟著我冒險了……",
  ui_story_1018_10180301_56_dialog_content = "<color=#e8d9bb>眾人一起來到交戰區西側……</color>",
  ui_story_1018_10180301_57_dialog_content = "沒想到泥潭能蔓延到這裡……似乎還在流動……",
  ui_story_1018_10180301_58_dialog_content = "嗯……或許還會有敵人攻過來，那些失蹤的士兵很有可能隨著泥潭的流動不知去向。",
  ui_story_1018_10180301_59_dialog_content = "倘若如此，只要泥潭還在，戰爭就不會結束。",
  ui_story_1018_10180301_60_dialog_content = "我最擔心的……是我的部下被敵人利用……",
  ui_story_1018_10180301_61_dialog_content = "這次編隊人員的失誤對戰局造成很大影響，我也有責任。",
  ui_story_1018_10180301_62_dialog_content = "您此前並不知情，大元帥。我們繼續順著泥潭搜索吧。",
  ui_story_1018_10180301_63_dialog_content = "嗯……",
  ui_story_1018_10180301_64_dialog_content = "雷霆大元帥，您看防線西側——",
  ui_story_1018_10180301_65_dialog_content = "三架「引擎七號」都在那裡！而且……我們的士兵也在！",
  ui_story_1018_10180301_66_dialog_content = "那是之前掩護我進攻的機甲……沒想到竟然在這裡……",
  ui_story_1018_10180301_67_dialog_content = "周圍只剩一片廢墟……他們身後的壁壘已經被衝垮了。多虧有他們守住……",
  ui_story_1018_10180301_68_dialog_content = "這樣就只剩一架「引擎七號」下落不明了，應該就在附近。馬上過去看看吧……",
  ui_story_1018_10180301_69_dialog_content = "<color=#e8d9bb>喀嚓——喀嚓——</color>",
  ui_story_1018_10180301_70_dialog_content = "呼——團長，這……",
  ui_story_1018_10180301_71_dialog_content = "……",
  ui_story_1018_10180301_72_dialog_content = "機甲已經完全毀壞了……",
  ui_story_1018_10180301_73_dialog_content = "而圍著機甲的士兵……正在啃食「引擎七號」的外殼……",
  ui_story_1018_10180301_74_dialog_content = "吼……",
  ui_story_1018_10180301_75_dialog_content = "像暗鬼一樣，靠吃下這些東西來補充能量嗎……",
  ui_story_1018_10180301_76_dialog_content = "這……",
  ui_story_1018_10180301_77_dialog_content = "吼！！！",
  ui_story_1018_10180301_78_dialog_content = "……",
  ui_story_1018_10180301_79_dialog_content = "大元帥您先別下馬，他們似乎察覺不到我們在靠近，這裡交給我們。",
  ui_story_1018_10180301_80_dialog_content = "沒錯，暗鬼數量不多，我一個人就可以解決。",
  ui_story_1018_10180301_81_dialog_content = "他們不是暗鬼……是我的部下……",
  ui_story_1018_10180301_82_dialog_content = "……控制住他們……",
  ui_story_1018_10180301_83_dialog_content = "……",
  ui_story_1018_10180301_84_dialog_content = "身為大元帥，您自己衝鋒在前，對部下卻優柔寡斷嗎？",
  ui_story_1018_10180301_85_dialog_content = "先控制住……或許還有救……",
  ui_story_1018_10180301_86_dialog_content = "雷霆說得沒錯，我可以試著救回他們！",
  ui_story_1018_10180302_1_dialog_content = "呼……終於穩定下來了。",
  ui_story_1018_10180302_2_dialog_content = "接下來就交給醫護人員吧，原來PlayerName不僅指揮有方，也懂治療。",
  ui_story_1018_10180302_3_dialog_content = "之前雷霆出現過這情況，也是這樣恢復的。",
  ui_story_1018_10180302_4_dialog_content = "他們只是深陷在自己的意識中，控制不了自己。",
  ui_story_1018_10180302_5_dialog_content = "但是那位吞食了大量機甲外殼的士兵……我很遺憾。",
  ui_story_1018_10180302_6_dialog_content = "白夜至上……李奧試圖控制他，我相信他也盡力了。",
  ui_story_1018_10180302_7_dialog_content = "那名士兵肢體殘缺，全靠暗能在支撐……",
  ui_story_1018_10180302_8_dialog_content = "我認為大元帥還是該以大局為重。遇到這樣的……士兵，不必自欺欺人。",
  ui_story_1018_10180302_9_dialog_content = "我知道，不用你提醒我……",
  ui_story_1018_10180302_10_dialog_content = "話說，後續找到的士兵，您都要把他們送去醫護院治療嗎？",
  ui_story_1018_10180302_11_dialog_content = "數百名士兵，這可不是小數目。",
  ui_story_1018_10180302_12_dialog_content = "確實……後續搜救到的傷患，醫護院恐怕也已經收治不下……",
  ui_story_1018_10180302_13_dialog_content = "但啟光士兵的傷勢特殊，必須盡快治療。",
  ui_story_1018_10180302_14_dialog_content = "我的部下已經在做準備了，等他回來，我會把居民轉移到腹地的城鎮去。",
  ui_story_1018_10180302_15_dialog_content = "靠什麼轉移？幾輛馬車嗎……",
  ui_story_1018_10180302_16_dialog_content = "對，有限的馬車。交通工具所剩無幾，也許還需要步行……",
  ui_story_1018_10180302_17_dialog_content = "靠步行，那不就是給外面的暗鬼送晚餐嗎……",
  ui_story_1018_10180302_18_dialog_content = "我有個提議……不過需要PlayerName來決定。",
  ui_story_1018_10180302_19_dialog_content = "其實我也想到一個……",
  ui_story_1018_10180302_20_dialog_content = "臨空者號。",
  ui_story_1018_10180302_21_dialog_content = "把黃昏鎮的居民盡快運走倒是沒問題……而且空之山谷應該是目前最安全的地方。",
  ui_story_1018_10180302_22_dialog_content = "但是後續搜救到的傷患，你們打算怎麼辦？",
  ui_story_1018_10180302_23_dialog_content = "在泥潭消散之前……我們自己會想辦法，眼前手無寸鐵的居民最重要。",
  ui_story_1018_10180302_24_dialog_content = "李奧，讓我去白夜要塞試試看吧。",
  ui_story_1018_10180302_25_dialog_content = "之前醫護院裡，有許多教會人員主動留下來參與醫治。",
  ui_story_1018_10180302_26_dialog_content = "急需醫治的傷患，我會去拜託教會協助。希望能為大元帥的搜救任務助一臂之力。",
  ui_story_1018_10180302_27_dialog_content = "白夜要塞……我並不看好那裡。",
  ui_story_1018_10180302_28_dialog_content = "但眼前保護難民為重，我們誰也說不準怎麼做才是最好，所以我不會攔你。",
  ui_story_1018_10180302_29_dialog_content = "我想，無論陣營之間有多少矛盾，白夜教會也不會將光靈拒於門外。",
  ui_story_1018_10180302_30_dialog_content = "不過……雷霆大元帥，您和啟光傷患會介意前往白夜教會嗎？",
  ui_story_1018_10180302_31_dialog_content = "我就不必了。啟光和宗教向來不對盤。",
  ui_story_1018_10180302_32_dialog_content = "但眼前我部下的安危為重，他們……就拜託妳了。",
  ui_story_1018_10180302_33_dialog_content = "你的身體，真的不用去治療嗎？",
  ui_story_1018_10180302_34_dialog_content = "我只是感到疲倦……和你們相處之後感覺好一點了。",
  ui_story_1018_10180302_35_dialog_content = "喬瑟琳，妳的馬可以借我嗎？",
  ui_story_1018_10180302_36_dialog_content = "當然可以！大元帥放心，我會讓您的部下盡快得到治療。",
  ui_story_1018_10180302_37_dialog_content = "希望下次見面時，戰役已經結束。我先去準備了。",
  ui_story_1018_10180302_38_dialog_content = "嗯，保重。",
  ui_story_1018_10180302_39_dialog_content = "PlayerName，隨後與我的部下在西側出口集合吧。",
  ui_story_1018_10180302_40_dialog_content = "等黃昏鎮危機解除後，我會去找你一起安置難民。",
  ui_story_1018_10180302_41_dialog_content = "這段時間……咳，謝謝你，我們之後還會再見的。",
  ui_story_1018_10180302_42_dialog_content = "你們這是……我又沒說要走。",
  ui_story_1018_10180302_43_dialog_content = "臨空者號的自動航行系統會將居民帶到安全的地方。",
  ui_story_1018_10180302_44_dialog_content = "我說過會和你們一起保衛黃昏鎮。在戰役結束之前，我不會離開。",
  ui_story_1018_10180302_45_dialog_content = "……PlayerName，你的毅力遠超出我的想像。",
  ui_story_1018_10180302_46_dialog_content = "一起戰鬥了這麼久，倒是沒想到你還有這一手。",
  ui_story_1018_10180302_47_dialog_content = "PlayerName，我已降落在黃昏鎮西側門口，目前距離能保持交流。",
  ui_story_1018_10180302_48_dialog_content = "臨空者號，隨後請將黃昏鎮的居民安全送往我們的家園。",
  ui_story_1018_10180302_49_dialog_content = "目的地訂為：空之山谷。",
  ui_story_1018_10180302_50_dialog_content = "PlayerName，請務必保護好自己。",
  ui_story_1018_10180302_51_dialog_content = "嗯，黃昏鎮的居民就拜託你了！",
  ui_story_1018_10180401_1_dialog_content = "<color=#e8d9bb>一列向著暗面行駛的火車上……</color>",
  ui_story_1018_10180401_2_dialog_content = "一、二、三……我們已經在這裡繞了四圈了，大人有什麼指示嗎？",
  ui_story_1018_10180401_3_dialog_content = "稍安勿躁，梅里，將我們引至此處的迷題終有解開之時。",
  ui_story_1018_10180401_4_dialog_content = "卡戎列車長真的會相信明詩指的路嗎？",
  ui_story_1018_10180401_5_dialog_content = "已經一起行動這麼久了，妳說呢？話說……明詩妳沒事吧？",
  ui_story_1018_10180401_6_dialog_content = "我從剛剛開始就一直感到頭痛，或許是風太大了……",
  ui_story_1018_10180401_7_dialog_content = "車廂裡哪有風啊……",
  ui_story_1018_10180401_8_dialog_content = "窗外，狂風出現的頻率非常詭異……",
  ui_story_1018_10180401_9_dialog_content = "憑著微弱的光感，我能看到側後方經過的城鎮遭遇不測，這或許是大人遲到的原因。",
  ui_story_1018_10180401_10_dialog_content = "那坨黑黑的原來是城鎮啊，就像從暗面伸出的一隻黑爪子……",
  ui_story_1018_10180401_11_dialog_content = "唉，難得搭上又舒適又漂亮的列車，窗外竟然是這種景色……",
  ui_story_1018_10180401_12_dialog_content = "卡戎長官，那三個人說的話真的可信嗎？從出發開始您就一直叫我們休息。",
  ui_story_1018_10180401_13_dialog_content = "可是我已經睡睡醒醒三次了，我們卻還沒有到達暗面？",
  ui_story_1018_10180401_14_dialog_content = "這是在執行任務，薇絲。無需擔心，彼岸號會確保我們的安全。",
  ui_story_1018_10180401_15_dialog_content = "可是長官，我記得啟光到暗面的距離沒有那麼遠啊……",
  ui_story_1018_10180401_16_dialog_content = "此次任務我只收到兩個確切的線索，這是揭曉謎底的必經之路。",
  ui_story_1018_10180401_17_dialog_content = "確切的線索？那是什麼？",
  ui_story_1018_10180401_18_dialog_content = "一個是啟光防線之外的各個座標，我們走過的地方都可以在地圖上找到。",
  ui_story_1018_10180401_19_dialog_content = "所以可以肯定，我們並沒有駛入奇怪的地方。",
  ui_story_1018_10180401_20_dialog_content = "按照顯示的標記……我們明明一直在兜圈子啊？！",
  ui_story_1018_10180401_21_dialog_content = "噓……驚擾到我們的遠客就麻煩了。",
  ui_story_1018_10180401_22_dialog_content = "他們三個？您果然也感覺不對勁是嗎？",
  ui_story_1018_10180401_23_dialog_content = "算是個隱藏任務吧。原地繞圈也是任務的一部分。",
  ui_story_1018_10180401_24_dialog_content = "冥冥之中有個聲音告訴我，謎底馬上就要揭曉了。",
  ui_story_1018_10180401_25_dialog_content = "又是謎底什麼的……",
  ui_story_1018_10180401_26_dialog_content = "那第二個線索呢？",
  ui_story_1018_10180401_27_dialog_content = "第二個線索是抵達特殊標記處後，與「暗面偵察隊」的通訊波段。",
  ui_story_1018_10180401_28_dialog_content = "欸？可是我們已經很久沒收到他們的位置訊號了。",
  ui_story_1018_10180401_29_dialog_content = "是那邊的長官把通訊器關了嗎？還是附近有訊號遮罩？",
  ui_story_1018_10180401_30_dialog_content = "長官……我認為我們有必要整理一下目前的情報，否則根本就完成不了任務！",
  ui_story_1018_10180401_31_dialog_content = "我很擔心啟光目前的狀態。",
  ui_story_1018_10180401_32_dialog_content = "不妨將那層疑慮稍作昇華，我或許能從遠處為您解答。",
  ui_story_1018_10180401_33_dialog_content = "卡戎長官，您有聽到一位……女士的聲音嗎？",
  ui_story_1018_10180401_34_dialog_content = "正從我耳旁飄過。",
  ui_story_1018_10180401_35_dialog_content = "維多利亞大人！",
  ui_story_1018_10180401_36_dialog_content = "喔，大人！您來了！",
  ui_story_1018_10180401_37_dialog_content = "還認得我嗎，啟光列車長？在外人面前，我或許不該稱呼你為族人……或遠親。",
  ui_story_1018_10180401_38_dialog_content = "收起妳的怪誕之詞，維多利亞女士。妳和妳的三名部下到底有什麼目的？",
  ui_story_1018_10180401_39_dialog_content = "維多利亞女士……？這麼說，這三個傢伙都是真理結社的人？！",
  ui_story_1018_10180401_40_dialog_content = "薇絲小姐，他們沒有給您的旅途添麻煩吧？",
  ui_story_1018_10180401_41_dialog_content = "這……要問卡戎長官，難道我們一直在原地繞圈都是因為您？",
  ui_story_1018_10180401_42_dialog_content = "不全是。但是有了我的加入，這趟滿載真知者的列車才算步入正軌。",
  ui_story_1018_10180401_43_dialog_content = "我猜薇絲小姐之所以上路，是對那位到訪啟光的神祕客人感到好奇吧……",
  ui_story_1018_10180401_44_dialog_content = "以及路過的黃昏鎮，到底發生了什麼事……",
  ui_story_1018_10180401_45_dialog_content = "您怎麼知道那個潛入啟光的人？黃昏鎮……發生了什麼事嗎……？",
  ui_story_1018_10180401_46_dialog_content = "所以，列車需要我這位嚮導不是嗎？",
  ui_story_1018_10180401_47_dialog_content = "至於黃昏鎮發生了什麼事……只能說空裔和啟光新帥似乎並未掌握求生的竅門。",
  ui_story_1018_10180401_48_dialog_content = "PlayerName也去了黃昏鎮？！",
  ui_story_1018_10180401_49_dialog_content = "雖然已經得知大元帥的事……但他們在黃昏鎮遇到危險了嗎……？",
  ui_story_1018_10180401_50_dialog_content = "您希望黃昏鎮如何，在您的維度裡他們便如何。在啟示降臨之前，費心未必有知。",
  ui_story_1018_10180401_51_dialog_content = "……卡戎長官，這是真的嗎？PlayerName和大元帥他們不會有危險吧？",
  ui_story_1018_10180401_52_dialog_content = "……",
  ui_story_1018_10180401_53_dialog_content = "怎麼樣，想去泥潭看看嗎？",
  ui_story_1018_10180401_54_dialog_content = "雖然根據典籍的啟示，這位小姐的命途軌跡是……向著永夜。",
  ui_story_1018_10180401_55_dialog_content = "遺忘摯愛後墮入永夜，任由暗矛滋長，助其完成贖罪之獻祭。",
  ui_story_1018_10180401_56_dialog_content = "薇絲小姐，恭喜您，此行您將尋得真相。",
  ui_story_1018_10180401_57_dialog_content = "您……到底在說什麼呀……",
  ui_story_1018_10180401_58_dialog_content = "胡說八道！此行不為命途，是啟光軍人在執行任務。",
  ui_story_1018_10180401_59_dialog_content = "請不要妨礙我們，維多利亞女士，否則別怪我對妳不客氣。",
  ui_story_1018_10180401_60_dialog_content = "和我的社員行動這麼久了，你真的感受不到「空間環徑」的存在嗎？",
  ui_story_1018_10180401_61_dialog_content = "「空間環徑」……原地兜圈子，這難道不是妳在搞鬼？",
  ui_story_1018_10180401_62_dialog_content = "看來你身上的祖先印記已然淡去。現在是時候接受一些啟示了。",
  ui_story_1018_10180401_63_dialog_content = "出於某種原因，日蝕以這種方式阻止你們接近。",
  ui_story_1018_10180401_64_dialog_content = "你們每行進一段距離，就會回到「最初的位置」，這就是「空間環徑」的力量。",
  ui_story_1018_10180401_65_dialog_content = "而「最初的位置」指的是既定空間內的一個圓心，你們只能在這個圓圈半徑內活動。",
  ui_story_1018_10180401_66_dialog_content = "……這是怎麼做到的呢？",
  ui_story_1018_10180401_67_dialog_content = "不必深究，薇絲小姐，這只會讓您陷入瘋狂。",
  ui_story_1018_10180401_68_dialog_content = "但有了我的指引，便能打破這樣的情況。這麼說的話，列車長還會拒絕我同乘嗎？",
  ui_story_1018_10180401_69_dialog_content = "……",
  ui_story_1018_10180401_70_dialog_content = "那我把你的沉默當作許可了。可以加速前進了，列車長。",
  ui_story_1018_10180401_71_dialog_content = "長官，我有點搞不懂了，我們現在是繼續向永夜方向前進嗎？",
  ui_story_1018_10180401_72_dialog_content = "薇絲小姐，列車所到之處將由您決定。",
  ui_story_1018_10180401_73_dialog_content = "我的心意嗎……",
  ui_story_1018_10180401_74_dialog_content = "<color=#e8d9bb>嗚嗚——！</color>",
  ui_story_1018_10180401_75_dialog_content = "小心站穩——",
  ui_story_1018_10180401_76_dialog_content = "怎麼會突然刮起這麼大的風……不會是敵人進攻前的徵兆吧……",
  ui_story_1018_10180401_77_dialog_content = "阿克希亞要保護部下……",
  ui_story_1018_10180401_78_dialog_content = "這麼大的風，泥潭卻一動也不動……果然詭異……",
  ui_story_1018_10180401_79_dialog_content = "阿克希亞，妳在這邊搜救的時候有發現什麼異常之處嗎？",
  ui_story_1018_10180401_80_dialog_content = "難道「中心」敵人並沒有被擊敗，而是潛伏在這伺機而動……",
  ui_story_1018_10180401_81_dialog_content = "<color=#e8d9bb>咕嚕——</color>",
  ui_story_1018_10180401_82_dialog_content = "團長，我負責的區域已經搜索完畢，傷患準備送往醫護院。",
  ui_story_1018_10180401_83_dialog_content = "知道了。沒有暗鬼的騷擾，搜救工作比預期順利不少。",
  ui_story_1018_10180401_84_dialog_content = "<color=#e8d9bb>咕嚕——</color>",
  ui_story_1018_10180401_85_dialog_content = "阿克希亞聽到奇怪的聲音……",
  ui_story_1018_10180401_86_dialog_content = "我也聽到了，像是有什麼東西在冒出水面……",
  ui_story_1018_10180401_87_dialog_content = "吼……",
  ui_story_1018_10180401_88_dialog_content = "這聲音是……？",
  ui_story_1018_10180401_89_dialog_content = "大元帥！您看擔架上的……士兵！",
  ui_story_1018_10180401_90_dialog_content = "怎麼會？",
  ui_story_1018_10180401_91_dialog_content = "他們身上的泥潭好像在流動……像是有生命一樣。",
  ui_story_1018_10180401_92_dialog_content = "原來剛剛那個聲音……",
  ui_story_1018_10180401_93_dialog_content = "啊——救……救命啊！",
  ui_story_1018_10180401_94_dialog_content = "所有人遠離擔架，過來我身邊！",
  ui_story_1018_10180401_95_dialog_content = "剛剛搜救的時候明明沒有問題……",
  ui_story_1018_10180401_96_dialog_content = "<color=#e8d9bb>呼——</color>",
  ui_story_1018_10180401_97_dialog_content = "吼……",
  ui_story_1018_10180401_98_dialog_content = "等等……是這陣風！難道是襲擊！",
  ui_story_1018_10180401_99_dialog_content = "快抓住附近的掩體——",
  ui_story_1018_10180401_100_dialog_content = "快要、站不穩了——",
  ui_story_1018_10180401_101_dialog_content = "PlayerName，抓緊我！",
  ui_story_1018_10180401_102_dialog_content = "完全……睜不開眼睛了。有、有新的敵人嗎？",
  ui_story_1018_10180401_103_dialog_content = "<color=#e8d9bb>嘩啦！</color>",
  ui_story_1018_10180401_104_dialog_content = "大家小心！泥潭正翻騰而來！",
  ui_story_1018_10180401_105_dialog_content = "雷霆大元帥，小心身後！",
  ui_story_1018_10180401_106_dialog_content = "看到了……那不只是泥潭……有東西在裡面！",
  ui_story_1018_10180401_107_dialog_content = "吼！",
  ui_story_1018_10180401_108_dialog_content = "泥潭裡有大量暗鬼！",
  ui_story_1018_10180401_109_dialog_content = "果然，泥潭帶著暗鬼進攻，受暗能影響的士兵紛紛開始回應……",
  ui_story_1018_10180401_110_dialog_content = "吼！",
  ui_story_1018_10180401_111_dialog_content = "啊——救……救命啊！",
  ui_story_1018_10180401_112_dialog_content = "雷霆大元帥，他們已經殺紅了眼，我只能把他們當作暗鬼解決了！",
  ui_story_1018_10180401_113_dialog_content = "不……不是這樣的……",
  ui_story_1018_10180401_114_dialog_content = "我們身後有暗鬼！再不行動，我們全軍都會被泥潭淹沒！",
  ui_story_1018_10180401_115_dialog_content = "李奧他……",
  ui_story_1018_10180401_116_dialog_content = "<color=#e8d9bb>呼——嗚嗚——！</color>",
  ui_story_1018_10180401_117_dialog_content = "糟糕！又來了！",
  ui_story_1018_10180401_118_dialog_content = "我還聽到微弱的汽笛聲……",
  ui_story_1018_10180401_119_dialog_content = "長官！地圖上顯示，這是黃昏鎮？",
  ui_story_1018_10180401_120_dialog_content = "維多利亞女士，這也是「空間環徑」造成的嗎？我們為什麼會在這裡？",
  ui_story_1018_10180401_121_dialog_content = "我們逃離了「空間環徑」。順著薇絲小姐的心意，我將列車引至此地。",
  ui_story_1018_10180401_122_dialog_content = "圓心的半徑處，正好是黃昏鎮。",
  ui_story_1018_10180401_123_dialog_content = "竟能做到這種事情……",
  ui_story_1018_10180401_124_dialog_content = "長官，前面似乎聚集了很多人，會不會是PlayerName他們？",
  ui_story_1018_10180401_125_dialog_content = "車身下滿是泥潭，請小心裡頭藏身的暗鬼。",
  ui_story_1018_10180401_126_dialog_content = "骯髒的泥水，骯髒的暗鬼！彼岸號會碾碎牠們！",
  ui_story_1018_10180401_127_dialog_content = "抓緊了各位！穿過泥潭，前方停靠！",
  ui_story_1018_10180401_128_dialog_content = "<color=#e8d9bb>嗚嗚——！</color>",
  ui_story_1018_10180401_129_dialog_content = "噢！雷霆大元帥——",
  ui_story_1018_10180401_130_dialog_content = "恭喜您榮登元帥之位，屬下來遲了！",
  ui_story_1018_10180401_131_dialog_content = "雷霆大元帥！PlayerName！",
  ui_story_1018_10180401_132_dialog_content = "薇絲！",
  ui_story_1018_10180401_133_dialog_content = "卡戎和薇絲！你們……怎麼會來！",
  ui_story_1018_10180401_134_dialog_content = "你們不是在執行任務嗎？怎麼會到黃昏鎮來？",
  ui_story_1018_10180401_135_dialog_content = "留意時間，列車長，此為短暫停靠。",
  ui_story_1018_10180401_136_dialog_content = "大元帥，聽聞黃昏鎮的戰局，屬下十分擔心。但是任務在身，無法長時間停留。",
  ui_story_1018_10180401_137_dialog_content = "你們碾碎這群暗鬼，已經幫很大的忙了。",
  ui_story_1018_10180401_138_dialog_content = "不過，這陣狂風難道不是敵人製造的，是你們……？",
  ui_story_1018_10180401_139_dialog_content = "我們來此絕非偶然，來不及細說了，大元帥。泥潭的那頭很長，下面或許還有很多暗鬼。",
  ui_story_1018_10180401_140_dialog_content = "大人，狂風……這是否意味著「空間環徑」再次出現……",
  ui_story_1018_10180401_141_dialog_content = "窮追不捨嗎……靜坐片刻，我會帶大家逃離。",
  ui_story_1018_10180401_142_dialog_content = "這個距離的話，二十秒。",
  ui_story_1018_10180401_143_dialog_content = "大人，我們來倒數……",
  ui_story_1018_10180401_144_dialog_content = "薇絲，你們一路上有遇到危險嗎？",
  ui_story_1018_10180401_145_dialog_content = "比起在黃昏鎮的你們……我遇到的危險不算什麼。",
  ui_story_1018_10180401_146_dialog_content = "只是維多利亞女士一路上語藏玄機，我聽不太懂……",
  ui_story_1018_10180401_147_dialog_content = "總之妳要照顧好自己，真理結社出現是種不祥的預兆。",
  ui_story_1018_10180401_148_dialog_content = "怎麼連你也開始說些莫名奇妙的話了……",
  ui_story_1018_10180401_149_dialog_content = "實際上，維多利亞女士好像確實是在幫助我們。",
  ui_story_1018_10180401_150_dialog_content = "如果這也是卡戎長官的意思的話……",
  ui_story_1018_10180401_151_dialog_content = "十五、十四、十三……",
  ui_story_1018_10180401_152_dialog_content = "十、九……",
  ui_story_1018_10180401_153_dialog_content = "……所以，大元帥還請繼續撐下去，大家盼著您平安回歸啟光！",
  ui_story_1018_10180401_154_dialog_content = "當然。你自己也保重，完成任務，安全返回啟光。",
  ui_story_1018_10180401_155_dialog_content = "五、四、三……",
  ui_story_1018_10180401_156_dialog_content = "記得我跟妳說過的話嗎？",
  ui_story_1018_10180401_157_dialog_content = "……你說如果遇到危險，就喊你名字，我記得！",
  ui_story_1018_10180401_158_dialog_content = "二、一、零。",
  ui_story_1018_10180401_159_dialog_content = "那麼，再會了各位。",
  ui_story_1018_10180401_160_dialog_content = "<color=#e8d9bb>轟隆——</color>",
  ui_story_1018_10180401_161_dialog_content = "他們……就這麼消失了？",
  ui_story_1018_10180401_162_dialog_content = "……不可思議，這完全超出了我對光能術的理解。",
  ui_story_1018_10180401_163_dialog_content = "吼！",
  ui_story_1018_10180401_164_dialog_content = "大元帥！騎士團已經控制不住那些士兵了……",
  ui_story_1018_10180401_165_dialog_content = "完全沒辦法了嗎……",
  ui_story_1018_10180401_166_dialog_content = "團長，弟兄們在問，我們的敵人到底是誰？",
  ui_story_1018_10180401_167_dialog_content = "大元帥的部下，也就是眼前的暗鬼手段十分殘忍……",
  ui_story_1018_10180401_168_dialog_content = "就算她攔著我，我也不會再退讓了。",
  ui_story_1018_10180401_169_dialog_content = "傷害我部下的士兵，我會親手將他處決！",
  ui_story_1018_10180401_170_dialog_content = "騎士團隨我上，把他們解決掉！",
  ui_story_1018_10180401_171_dialog_content = "……是！",
  ui_story_1018_10180401_X171_dialog_content = "突然刮起這麼大的風……會是敵人進攻的前兆嗎……",
  ui_story_1018_10180401_X172_dialog_content = "暗鬼確實越來越多了，但還能繼續搜救。大家有發現什麼異常嗎？",
  ui_story_1018_10180401_X173_dialog_content = "報告大元帥，我負責的區域搜救工作沒有受到影響。",
  ui_story_1018_10180401_X174_dialog_content = "報告大元帥，阿克希亞負責的區域出現了許多暗鬼，已經解決。",
  ui_story_1018_10180401_X175_dialog_content = "大元帥，李奧團長負責泥潭區域，情況不太好。",
  ui_story_1018_10180401_X176_dialog_content = "知道了……大家各自小心，我過去看看。",
  ui_story_1018_10180401_X177_dialog_content = "團長，傷患都已經上擔架了，我先送他們去醫院。",
  ui_story_1018_10180401_X178_dialog_content = "嗯，注意士兵的情況。泥潭又開始湧動了，暗鬼也越來越多，要在牠們大舉進攻前爭取時間撤離。",
  ui_story_1018_10180401_X179_dialog_content = "是，團長。",
  ui_story_1018_10180401_X180_dialog_content = "阿克希亞聽到奇怪的聲音……是從士兵身上傳來的。",
  ui_story_1018_10180401_X181_dialog_content = "不要再靠近了，這些士兵都是從泥潭裡面撈起來的。",
  ui_story_1018_10180401_X182_dialog_content = "那些污泥在他們身上流動，像是有生命一樣……",
  ui_story_1018_10180401_X183_dialog_content = "我們現在並沒有清理這些污泥的方法……",
  ui_story_1018_10180401_X184_dialog_content = "吼……",
  ui_story_1018_10180401_X185_dialog_content = "吼……",
  ui_story_1018_10180401_X186_dialog_content = "大元帥，傷患的情況非常不穩定！",
  ui_story_1018_10180401_X187_dialog_content = "他們身上的污泥，流動速度是不是變快了？",
  ui_story_1018_10180401_X188_dialog_content = "流動速度變快？那只能是……",
  ui_story_1018_10180401_X189_dialog_content = "大家小心！泥潭正翻騰而來！",
  ui_story_1018_10180401_X190_dialog_content = "不只是泥潭……有東西在裡面！",
  ui_story_1018_10180401_X191_dialog_content = "吼！",
  ui_story_1018_10180401_X192_dialog_content = "果然，泥潭帶著暗鬼進攻，受暗能影響的士兵也開始出現異常……",
  ui_story_1018_10180401_X193_dialog_content = "……騎士團一隊掩護醫療隊，其餘準備戰鬥！",
  ui_story_1018_10180401_X194_dialog_content = "是！",
  ui_story_1018_10180401_X195_dialog_content = "<color=#e8d9bb>呼呼——</color>",
  ui_story_1018_10180401_X196_dialog_content = "又來……難道後面還有敵人！",
  ui_story_1018_10180401_X197_dialog_content = "快要、站不穩了——",
  ui_story_1018_10180401_X198_dialog_content = "抓住附近的掩體——",
  ui_story_1018_10180401_X199_dialog_content = "完全……睜不開眼睛了。有、有新的敵人嗎？",
  ui_story_1018_10180401_X200_dialog_content = "PlayerName，抓緊我！",
  ui_story_1018_10180401_X201_dialog_content = "<color=#e8d9bb>呼——嗚嗚——！</color>",
  ui_story_1018_10180401_X202_dialog_content = "PlayerName，你還好嗎？",
  ui_story_1018_10180401_X203_dialog_content = "我好像……聽到了汽笛聲……",
  ui_story_1018_10180401_X204_dialog_content = "我沒看錯吧！前面那個灰頭土臉的是……PlayerName？！",
  ui_story_1018_10180401_X205_dialog_content = "長官，我們是來到了黃昏鎮嗎？這是怎麼做到的……",
  ui_story_1018_10180401_X206_dialog_content = "「空間環徑」確實很有意思，不過更有意思的是，我可以順著薇絲小姐的心意將列車引至此地。",
  ui_story_1018_10180401_X207_dialog_content = "竟然能做到這種事情……",
  ui_story_1018_10180401_X208_dialog_content = "雖然聽不懂您在說什麼，但是我們能在前面停靠嗎？PlayerName他們似乎很危險……",
  ui_story_1018_10180401_X209_dialog_content = "混濁的泥潭，還有成群的暗鬼，幾乎把他們團團圍住了……",
  ui_story_1018_10180401_X210_dialog_content = "很遺憾，薇絲小姐，這裡不是我們的目的地。在衝破「空間環徑」之前是無法停靠的。",
  ui_story_1018_10180401_X211_dialog_content = "已經離他們越來越近了……長官，我們能做點什麼嗎？",
  ui_story_1018_10180401_X212_dialog_content = "既然無法停靠……",
  ui_story_1018_10180401_X213_dialog_content = "彼岸號會壓過這骯髒的泥潭，把暗鬼統統碾碎！坐好了，各位！",
  ui_story_1018_10180401_X214_dialog_content = "<color=#e8d9bb>轟隆——</color>",
  ui_story_1018_10180401_X215_dialog_content = "嘎——",
  ui_story_1018_10180401_X216_dialog_content = "團長！剛才那是……火車？幾乎把泥潭裡的暗鬼都消滅了！",
  ui_story_1018_10180401_X217_dialog_content = "……看起來很像啟光的科技，抓緊時間確認醫療隊的情況吧。",
  ui_story_1018_10180401_X218_dialog_content = "是！",
  ui_story_1018_10180401_X219_dialog_content = "不會錯……那是卡戎的火車，我好像還看到了薇絲的身影……",
  ui_story_1018_10180401_X220_dialog_content = "他們怎麼會在這？而且轉瞬間又消失了？",
  ui_story_1018_10180401_X221_dialog_content = "不知道……來黃昏鎮之前，薇絲和卡戎就已經出發去暗面執行任務了。",
  ui_story_1018_10180401_X222_dialog_content = "他們恰巧出現在這，還幫我們解決了暗鬼，這確實很不尋常……",
  ui_story_1018_10180401_X223_dialog_content = "報告大元帥，又發現一支失蹤隊伍！",
  ui_story_1018_10180401_X224_dialog_content = "知道了，我馬上過去。",
  ui_story_1018_10180401_X225_dialog_content = "PlayerName，他們或許經歷了我們無法理解的事情，但那是他們需要解決的問題，我相信他們。",
  ui_story_1018_10180401_X226_dialog_content = "我們先解決眼前的危機吧。",
  ui_story_1018_10180401_X227_dialog_content = "嗯，希望他們一切順利。",
  ui_story_1018_10180401_X228_dialog_content = "（薇絲，妳一定要平安啊。）",
  ui_story_1018_10180501_1_dialog_content = "<color=#e8d9bb>列車懸停在未知空間內……</color>",
  ui_story_1018_10180501_2_dialog_content = "明詩！把妳的袖套拿開，一路上都快憋死我了！",
  ui_story_1018_10180501_3_dialog_content = "咦？你看！鈴鐺發光了……是不是表示我們成功了！",
  ui_story_1018_10180501_4_dialog_content = "確實……有濃稠的物質撞擊我的眼皮，這感覺不會錯。",
  ui_story_1018_10180501_5_dialog_content = "維多利亞大人，這裡是……？",
  ui_story_1018_10180501_6_dialog_content = "無光無暗，唯有真理垂青，此乃吾之祕境。",
  ui_story_1018_10180501_7_dialog_content = "噢！在下已雙膝枕地，俯聽主之聲！",
  ui_story_1018_10180501_8_dialog_content = "這是真理灌入耳朵的隱痛感，我記得，我會靜心聆聽！",
  ui_story_1018_10180501_9_dialog_content = "能……說句大家聽得懂的話嗎？這裡到底是什麼地方？",
  ui_story_1018_10180501_10_dialog_content = "無需擔心，薇絲小姐，我們已經逃離「空間環徑」。",
  ui_story_1018_10180501_11_dialog_content = "這麼說，是您救了我們？",
  ui_story_1018_10180501_12_dialog_content = "旨在遵循指引——",
  ui_story_1018_10180501_13_dialog_content = "大人！我「見」到鮮血！",
  ui_story_1018_10180501_14_dialog_content = "我、我「聽」到鮮活的字句，疼痛刻入耳膜！",
  ui_story_1018_10180501_15_dialog_content = "……黑色典籍竟在此時降下啟示……",
  ui_story_1018_10180501_16_dialog_content = "字符變換如此之快，前途微微顯影……",
  ui_story_1018_10180501_17_dialog_content = "「行動之後將迎來敗績。」",
  ui_story_1018_10180501_18_dialog_content = "這是否就是所謂的「日蝕將展長其尾，極光照臨之際，祂啟回歸之程。」",
  ui_story_1018_10180501_19_dialog_content = "不對，還在變動……",
  ui_story_1018_10180501_20_dialog_content = "「挫折後將迎來宏大之舉。」",
  ui_story_1018_10180501_21_dialog_content = "如此便是「光靈將迎來劫難，與祂相會，但受極光阻隔。」",
  ui_story_1018_10180501_22_dialog_content = "啟示不明……",
  ui_story_1018_10180501_23_dialog_content = "大人！濃稠的恨意在主的眼裡流淌……",
  ui_story_1018_10180501_24_dialog_content = "閉上眼睛，狄希斯！那不是主的目光，主不含恨意！",
  ui_story_1018_10180501_25_dialog_content = "各位，屏息。",
  ui_story_1018_10180501_26_dialog_content = "……",
  ui_story_1018_10180501_27_dialog_content = "長官！儀表板上隱約傳來訊號……",
  ui_story_1018_10180501_28_dialog_content = "是「暗面探索隊」傳來的座標，這個位置……並不在地圖上。",
  ui_story_1018_10180501_29_dialog_content = "因為那並非<color=#FFB400>真實之地</color>，而是啟示中提到過的「眾離故園，歸途之起點」。",
  ui_story_1018_10180501_30_dialog_content = "這是什麼意思呢？我們能找到他們嗎？",
  ui_story_1018_10180501_31_dialog_content = "看來已經到了裁決光明與黑暗之爭時，真理之主定會降臨。",
  ui_story_1018_10180501_32_dialog_content = "為了去見證那個時刻，我會將你們送至目的地。",
  ui_story_1018_10180501_33_dialog_content = "不過列車長，我需要你的幫忙。",
  ui_story_1018_10180501_34_dialog_content = "……",
  ui_story_1018_10180501_35_dialog_content = "卡戎長官，我覺得非常不安……",
  ui_story_1018_10180501_36_dialog_content = "維多利亞女士的祕境好像被什麼東西擠壓……我有點難以呼吸……",
  ui_story_1018_10180501_37_dialog_content = "我、也是——",
  ui_story_1018_10180501_38_dialog_content = "還是找到這來了……",
  ui_story_1018_10180501_39_dialog_content = "安妮莫妮到底在搞什麼鬼，竟把你們留到現在。",
  ui_story_1018_10180501_40_dialog_content = "……是誰在說話？",
  ui_story_1018_10180501_41_dialog_content = "你身上有一股讓我討厭的味道，但想不起來是什麼……",
  ui_story_1018_10180501_42_dialog_content = "骯髒的東西，離我的部下遠一點！",
  ui_story_1018_10180501_43_dialog_content = "我對你沒興趣。倒是這位金髮女士，妳手上的東西似乎很有意思。",
  ui_story_1018_10180501_44_dialog_content = "罪惡的僕人，真知只會讓你顫抖。",
  ui_story_1018_10180501_45_dialog_content = "我看是你們在瑟瑟發抖吧，閉著眼睛是在做什麼？",
  ui_story_1018_10180501_46_dialog_content = "……以鮮血獻祭，真理之主賜予庇佑。",
  ui_story_1018_10180501_47_dialog_content = "喔？在舉行什麼儀式？",
  ui_story_1018_10180501_48_dialog_content = "你的對手是我，不敢露出真容的惡徒，嘗嘗獄火的味道！",
  ui_story_1018_10180501_49_dialog_content = "信徒狄希斯已完成獻祭。",
  ui_story_1018_10180501_50_dialog_content = "以疼痛獻祭，主帶你深入聆聽真理。",
  ui_story_1018_10180501_51_dialog_content = "信徒梅里已完成獻祭。",
  ui_story_1018_10180501_52_dialog_content = "不如讓我來，效率高多了。",
  ui_story_1018_10180501_53_dialog_content = "見證、神蹟——！",
  ui_story_1018_10180501_54_dialog_content = "儀式即將完成，列車長——",
  ui_story_1018_10180501_55_dialog_content = "卡戎長官，您、您沒事吧？",
  ui_story_1018_10180501_56_dialog_content = "坐穩了，冥河列車借道！調轉車頭，向著下方！",
  ui_story_1018_10180501_57_dialog_content = "我的腳……完全離開車廂地面了？",
  ui_story_1018_10180501_58_dialog_content = "以靈寵獻祭，主將揭開隱藏的謎團。",
  ui_story_1018_10180501_59_dialog_content = "信徒明詩已完成獻祭。",
  ui_story_1018_10180501_60_dialog_content = "想逃？",
  ui_story_1018_10180501_61_dialog_content = "願主接納祭品，奪取我鮮血之力，讓深紅真理顯現於世！",
  ui_story_1018_10180501_62_dialog_content = "神蹟顯現——突破罪靈之領域！",
  ui_story_1018_10180501_63_dialog_content = "抓穩了各位——",
  ui_story_1018_10180501_64_dialog_content = "不、不行，身體……在迅速往下掉——",
  ui_story_1018_10180501_65_dialog_content = "要前往暗面，我們會途徑<color=#FFB400>冥流之河</color>，亦稱<color=#FFB400>遺忘荒原</color>。",
  ui_story_1018_10180501_66_dialog_content = "在見光之前，請凝神閉目，別讓危險感知到您。",
  ui_story_1018_10180501_67_dialog_content = "可是我一閉上眼睛，就會看見成群的暗鬼朝我湧來……",
  ui_story_1018_10180501_68_dialog_content = "那是妳意識中的戰場，不是真實的敵人。",
  ui_story_1018_10180501_69_dialog_content = "但是那些……都是啟光的士兵……",
  ui_story_1018_10180501_70_dialog_content = "我看到他們在啃食機甲……",
  ui_story_1018_10180501_71_dialog_content = "他們在互相殘殺……",
  ui_story_1018_10180501_72_dialog_content = "我還看到……黑色的泥潭從暗面一直延伸到啟光防線……",
  ui_story_1018_10180501_73_dialog_content = "（離開，不要靠近。）",
  ui_story_1018_10180501_74_dialog_content = "（是妳……妳到底是誰？）",
  ui_story_1018_10180501_75_dialog_content = "（離開，不要靠近。）",
  ui_story_1018_10180501_76_dialog_content = "（總覺得有種奇怪的力量在驅使著我……）",
  ui_story_1018_10180501_77_dialog_content = "薇絲？",
  ui_story_1018_10180501_78_dialog_content = "有一個聲音，在叫我們離開……",
  ui_story_1018_10180501_79_dialog_content = "不要聆聽，不要凝視，否則您將再也無法醒來。",
  ui_story_1018_10180501_80_dialog_content = "我看不清她……但我感覺到她的聲音，她的心跳，是如此真實……",
  ui_story_1018_10180501_81_dialog_content = "彷彿……我就是她……",
  ui_story_1018_10180501_82_dialog_content = "這正是危險在附近的預兆。",
  ui_story_1018_10180501_83_dialog_content = "（PlayerName說過，如果遇到危險就喊他的名字。）",
  ui_story_1018_10180501_84_dialog_content = "（或許他會聽到吧……）",
  ui_story_1018_10180501_85_dialog_content = "（離開，危險。）",
  ui_story_1018_10180501_86_dialog_content = "（但無論如何，我都要去看清妳……）",
  ui_story_1018_10180501_87_dialog_content = "（因為這是我第一次感覺到，一個人能離我那麼近……）",
  ui_story_1018_10180501_88_dialog_content = "（……）",
  ui_story_1018_10180501_89_dialog_content = "（……這是？）",
  ui_story_1018_10180501_90_dialog_content = "（薇絲的心跳……）",
  ui_story_1018_10180501_91_dialog_content = "（她一定遇到了危險……）",
  ui_story_1018_10180501_92_dialog_content = "PlayerName！小心你的背後！",
  ui_story_1018_10180601_1_dialog_content = "吼……",
  ui_story_1018_10180601_2_dialog_content = "大元帥請下令……我的槍已瞄準他的腦袋……",
  ui_story_1018_10180601_X2_dialog_content = "把槍放下。",
  ui_story_1018_10180601_X3_dialog_content = "可是……他身為第九分隊的指揮官，不僅殺害了這麼多弟兄，現在還傷害了您！他不配做啟光軍人！",
  ui_story_1018_10180601_X4_dialog_content = "這不是他的本意。他的眼神告訴我，他還有意識。",
  ui_story_1018_10180601_X5_dialog_content = "大元帥！騎士團已經控制不住那些士兵了……再這樣下去，我們都會有危險……",
  ui_story_1018_10180601_3_dialog_content = "他雖然是第九分隊的指揮官，但他殺害了這麼多弟兄，不配成為啟光軍人！",
  ui_story_1018_10180601_4_dialog_content = "他的眼神告訴我，他還有意識！",
  ui_story_1018_10180601_5_dialog_content = "看清楚，我是你的大元帥！放手！",
  ui_story_1018_10180601_6_dialog_content = "……大元帥。",
  ui_story_1018_10180601_7_dialog_content = "竟然真的聽得到……",
  ui_story_1018_10180601_8_dialog_content = "我會帶你回啟光，你不能死在這裡。",
  ui_story_1018_10180601_9_dialog_content = "……",
  ui_story_1018_10180601_10_dialog_content = "他的身體完全只剩暗能在支配，再拖下去，你遲早會被自己的屬下捏斷脖子。",
  ui_story_1018_10180601_11_dialog_content = "吼……",
  ui_story_1018_10180601_12_dialog_content = "（身體裡的能量……被喚醒一般……）",
  ui_story_1018_10180601_13_dialog_content = "（我竟有殺他的衝動……）",
  ui_story_1018_10180601_14_dialog_content = "雷霆，他應該是像妳之前一樣陷入意識當中，別衝動……",
  ui_story_1018_10180601_15_dialog_content = "讓我使用感應能力試試看吧？",
  ui_story_1018_10180601_16_dialog_content = "他的狀況不明，我擔心你會遇到危險。",
  ui_story_1018_10180601_17_dialog_content = "這或許是目前唯一的辦法……",
  ui_story_1018_10180601_18_dialog_content = "如果情況不對，我會馬上中止感應，相信我。",
  ui_story_1018_10180601_19_dialog_content = "……如果他傷害你的話，我，不會猶豫……",
  ui_story_1018_10180601_20_dialog_content = "嗯……",
  ui_story_1018_10180601_21_option_content = "嘗試感應",
  ui_story_1018_10180601_22_dialog_content = "（進來了……這是……啟光地下城……）",
  ui_story_1018_10180601_23_dialog_content = "（這裡是住宅區吧……彷彿能聞到清洗劑的味道……）",
  ui_story_1018_10180601_24_dialog_content = "可是媽媽，這是千載難逢的機會！",
  ui_story_1018_10180601_25_dialog_content = "（在和媽媽吵架嗎……）",
  ui_story_1018_10180601_26_dialog_content = "雷霆軍團長正是一次又一次挑戰目標，才坐上今天的位置！",
  ui_story_1018_10180601_27_dialog_content = "如果錯過這一次的士兵培養計畫，我成為大元帥的夢想就沒辦法實現了！",
  ui_story_1018_10180601_28_dialog_content = "雷霆軍團長肯定我的能力，說我能勝任更高的職位！",
  ui_story_1018_10180601_29_dialog_content = "成為將領……贏下一場又一場的戰爭……你的父親如此，如今你也是……",
  ui_story_1018_10180601_30_dialog_content = "你確實繼承了你父親的膽識和智慧，在媽媽眼裡，你永遠是最優秀的……",
  ui_story_1018_10180601_31_dialog_content = "但是寶貝……我聽說那項培養計畫會非常辛苦……",
  ui_story_1018_10180601_32_dialog_content = "如果承受不住訓練強度，將再也無法走上戰場……",
  ui_story_1018_10180601_33_dialog_content = "留在媽媽身邊好嗎？我現在，只有你們倆了……",
  ui_story_1018_10180601_34_dialog_content = "媽媽……我相信哥哥……",
  ui_story_1018_10180601_35_dialog_content = "嗯！所以媽媽，請您也相信我，我一定會撐下去！",
  ui_story_1018_10180601_36_dialog_content = "一直守在迦南城沒有未來，軍人就該走上戰場，視死如歸！",
  ui_story_1018_10180601_37_dialog_content = "喔，我的寶貝……你別說這種話……",
  ui_story_1018_10180601_38_dialog_content = "總之我已經決定了！",
  ui_story_1018_10180601_39_dialog_content = "（……）",
  ui_story_1018_10180601_40_dialog_content = "（這位母親要是知道了他在戰場上的情況會怎麼想呢……）",
  ui_story_1018_10180601_41_dialog_content = "（啊！光顧著聽他們談話了！）",
  ui_story_1018_10180601_42_dialog_content = "（嗯？好像已經換到另一個地方了，這燈光好刺眼……）",
  ui_story_1018_10180601_43_dialog_content = "長官，這就是「啟明星計畫」的最終考核嗎？",
  ui_story_1018_10180601_44_dialog_content = "沒錯，這是最後一步了。",
  ui_story_1018_10180601_45_dialog_content = "沒有任何限制，你唯一的目標就是戰勝接下來的敵人，活下來。",
  ui_story_1018_10180601_46_dialog_content = "（等等！快離開這裡！）",
  ui_story_1018_10180601_47_dialog_content = "（媽媽？你怎麼來了……我已經下定決心了，你不要再攔我……）",
  ui_story_1018_10180601_48_dialog_content = "（把我認成了媽媽……既然如此……）",
  ui_story_1018_10180601_49_dialog_content = "（別聽他的！參加計畫會變成暗鬼！媽媽不希望看到你這樣！）",
  ui_story_1018_10180601_50_dialog_content = "（不會的，媽媽……長官說我很有天賦，我必須通過考核。）",
  ui_story_1018_10180601_51_dialog_content = "準備好後可以隨時開始。",
  ui_story_1018_10180601_52_dialog_content = "（他在騙你！你現在正在黃昏鎮的戰場上！）",
  ui_story_1018_10180601_53_dialog_content = "（站在你眼前的不是敵人，是你的長官雷霆！快離開這個房間！）",
  ui_story_1018_10180601_54_dialog_content = "（雷霆大元帥也在看著我嗎？）",
  ui_story_1018_10180601_55_dialog_content = "（你說黃昏鎮……我好像去過……）",
  ui_story_1018_10180601_56_dialog_content = "你在猶豫？",
  ui_story_1018_10180601_57_dialog_content = "沒有……長官，可以開始了。",
  ui_story_1018_10180601_58_dialog_content = "（拜託了！快醒醒！）",
  ui_story_1018_10180601_59_dialog_content = "（媽媽，看著吧，我會成為一名英勇的戰士。）",
  ui_story_1018_10180601_60_dialog_content = "吼！！！",
  ui_story_1018_10180601_61_dialog_content = "（喂！醒醒啊！不要與牠戰鬥！）",
  ui_story_1018_10180601_62_dialog_content = "長官，一見到暗鬼，我便覺得……渾身充滿了力量。",
  ui_story_1018_10180601_63_dialog_content = "沒錯，就是這樣，感受力量，然後控制力量。",
  ui_story_1018_10180601_64_dialog_content = "吼！！！",
  ui_story_1018_10180601_65_dialog_content = "暗鬼……必須死！",
  ui_story_1018_10180601_66_dialog_content = "（怎麼辦……再不結束感應的話恐怕……）",
  ui_story_1018_10180601_67_dialog_content = "必須死！！！",
  ui_story_1018_10180601_68_dialog_content = "吼！！！",
  ui_story_1018_10180601_69_dialog_content = "<color=#e8d9bb>吼！！！</color>",
  ui_story_1018_10180601_70_dialog_content = "糟糕！他的嘶吼聲似乎帶動了其他士兵！",
  ui_story_1018_10180602_1_dialog_content = "<color=#e8d9bb>砰——</color>",
  ui_story_1018_10180602_2_dialog_content = "……",
  ui_story_1018_10180602_3_dialog_content = "抱歉……大元帥，我別無選擇。",
  ui_story_1018_10180602_4_dialog_content = "你沒事吧，PlayerName？",
  ui_story_1018_10180602_5_dialog_content = "對不起，我沒能挽救他……",
  ui_story_1018_10180602_6_dialog_content = "但他是一名優秀的士兵……",
  ui_story_1018_10180602_7_dialog_content = "阿克希亞很難過……",
  ui_story_1018_10180602_8_dialog_content = "……遠處的幾名士兵，您打算怎麼做？",
  ui_story_1018_10180602_9_dialog_content = "……",
  ui_story_1018_10180602_10_dialog_content = "親手殺死自己的部下，我沒資格擔任啟光大元帥……",
  ui_story_1018_10180602_11_dialog_content = "（我到底該怎麼做……）",
  ui_story_1018_10180602_12_dialog_content = "（如果是你，萊因哈特，你會怎麼做？）",
  ui_story_1018_10180602_13_dialog_content = "讓我來吧——",
  ui_story_1018_10180602_14_dialog_content = "李奧……",
  ui_story_1018_10180602_15_dialog_content = "就當是你們沒有攔住我，我一意孤行，殺死了這些暴走的士兵。",
  ui_story_1018_10180602_16_dialog_content = "我只是一名駐守黃昏鎮的騎士，不用像大元帥你一樣，背負陣營的責任。",
  ui_story_1018_10180602_17_dialog_content = "心軟只會讓我們損失更多，你必須學會面對現實。",
  ui_story_1018_10180602_18_dialog_content = "不……我的手根本撐不起那麼多條性命……",
  ui_story_1018_10180602_19_dialog_content = "我明明說過，要帶他們打贏黃昏鎮這一仗……",
  ui_story_1018_10180602_20_dialog_content = "他們……是被我葬送的士兵……",
  ui_story_1018_10180602_21_dialog_content = "（我以為只要我有力量，只要我夠強，就能做到任何事。）",
  ui_story_1018_10180602_22_dialog_content = "（夠強……哈哈……）",
  ui_story_1018_10180602_23_dialog_content = "雷霆，我認為妳在做的，是一件比變強還要困難的事。",
  ui_story_1018_10180602_24_dialog_content = "……",
  ui_story_1018_10180602_25_dialog_content = "戰士本來就是用身體擋住危險的人。",
  ui_story_1018_10180602_26_dialog_content = "當他們自己成為了危險，而無法掌握生死的時候——",
  ui_story_1018_10180602_27_dialog_content = "身為將領，這是我們唯一能為他們做的事……",
  ui_story_1018_10180602_28_dialog_content = "將領……",
  ui_story_1018_10180602_29_dialog_content = "（這也是妳說的敞開手心嗎？萊因哈特……）",
  ui_story_1018_10180602_30_dialog_content = "您的士兵死得其所，相信我，他們的痛苦很快就會結束。",
  ui_story_1018_10180602_31_dialog_content = "慢著，李奧。",
  ui_story_1018_10180602_32_dialog_content = "或許你說得對，士兵們……死得其所……",
  ui_story_1018_10180602_33_dialog_content = "我必須面對現實……",
  ui_story_1018_10180602_34_dialog_content = "與其讓他們那麼痛苦，我，會給他們一個痛快。",
  ui_story_1018_10180602_35_dialog_content = "大元帥……",
  ui_story_1018_10180602_36_dialog_content = "各位戰士，請讓我和你們曾經的戰友，最後說幾句話……",
  ui_story_1018_10180602_37_dialog_content = "無論如何，我們永遠追隨您！",
  ui_story_1018_10180602_38_dialog_content = "……",
  ui_story_1018_10180602_39_dialog_content = "即使你們聽不清楚我說的話，我也在此向你們保證——",
  ui_story_1018_10180602_40_dialog_content = "你們是啟光軍人，生來便佩有啟光軍人的榮耀，肩負消滅暗鬼的責任。",
  ui_story_1018_10180602_41_dialog_content = "明知戰場是最快迎接死亡之途，你們依然奮不顧身……",
  ui_story_1018_10180602_42_dialog_content = "你們，是作為英勇的啟光士兵犧牲……",
  ui_story_1018_10180602_43_dialog_content = "而不是棄子……",
  ui_story_1018_10180602_44_dialog_content = "我們會繼續你們未竟的使命，一直戰鬥下去！",
  ui_story_1018_10180602_45_dialog_content = "吼……",
  ui_story_1018_10180602_46_dialog_content = "（就是這樣，雷霆，很快就會結束……）",
  ui_story_1018_10180602_47_dialog_content = "而你們，終於可以卸下重擔，像勝利來臨那樣——",
  ui_story_1018_10180602_48_dialog_content = "前往那個永無戰事的家園！",
  ui_story_1018_10180602_49_dialog_content = "吼！！！",
  ui_story_1018_10180602_50_dialog_content = "狙擊手瞄準——",
  ui_story_1018_10180602_51_dialog_content = "射擊！",
  ui_story_1018_10180602_52_dialog_content = "<color=#e8d9bb>砰砰砰——</color>",
  ui_story_1018_10180602_53_dialog_content = "……",
  ui_story_1018_10180602_54_dialog_content = "戰爭結束了，安然入睡吧……",
  ui_story_1018_10180602_55_dialog_content = "……",
  ui_story_1018_10180602_56_dialog_content = "……",
  ui_story_1018_10180701_1_dialog_content = "<color=#e8d9bb>前往白夜要塞的路上……</color>",
  ui_story_1018_10180701_2_dialog_content = "阿奇，前面就是白夜要塞了，還撐得住嗎？",
  ui_story_1018_10180701_3_dialog_content = "嗯……阿奇還有力氣……",
  ui_story_1018_10180701_4_dialog_content = "妳好像很不舒服，是剛剛掙脫繩索的士兵嚇到妳了嗎？",
  ui_story_1018_10180701_5_dialog_content = "不是的，喬瑟琳姐姐……",
  ui_story_1018_10180701_6_dialog_content = "看著妳為了保護大家那麼拼命，我反而一點都不怕。",
  ui_story_1018_10180701_7_dialog_content = "但是這一次……傷患好多……甚至要用繩索才能把他們控制住……",
  ui_story_1018_10180701_8_dialog_content = "啊、我沒有埋怨他們的意思！我知道士兵們是為了保護我們……",
  ui_story_1018_10180701_9_dialog_content = "只是……喬瑟琳姐姐一直面對這樣的情況，一定非常辛苦吧……",
  ui_story_1018_10180701_10_dialog_content = "……",
  ui_story_1018_10180701_11_dialog_content = "阿奇，妳知道嗎？比起現在，我小時候的黃昏鎮其實更辛苦……",
  ui_story_1018_10180701_12_dialog_content = "喬瑟琳姐姐……小時候嗎？",
  ui_story_1018_10180701_13_dialog_content = "在我十二歲那年，黃昏鎮遭到暗鬼襲擊，我的父母為了保護我失去了生命。",
  ui_story_1018_10180701_14_dialog_content = "當時我住的村子裡，沒有任何人來幫助我們，只能靠我們自己。",
  ui_story_1018_10180701_15_dialog_content = "我記得稍微比我大一點的孩子都拿起武器上了戰場。有許多人我再也沒見過……",
  ui_story_1018_10180701_16_dialog_content = "那……後來呢？",
  ui_story_1018_10180701_17_dialog_content = "後來暗鬼跑進村子裡，我帶著剩下的孩子們東躲西藏，那種擔驚受怕的感覺一直持續了很多年。",
  ui_story_1018_10180701_18_dialog_content = "不過還好我們被遠征騎士團救了出來，也是士兵們把我帶去白夜教會的孤兒院，讓我最終成為了一名修女。",
  ui_story_1018_10180701_19_dialog_content = "聽起來確實很辛苦呢……那喬瑟琳姐姐為什麼後來會跟隨遠征騎士團呢？",
  ui_story_1018_10180701_20_dialog_content = "因為我相信，只有主動對抗暗鬼，黃昏鎮的居民才有活下去的希望。",
  ui_story_1018_10180701_21_dialog_content = "我被騎士團救過，我也想像他們一樣，為黃昏鎮的百姓創造安全的生活環境。",
  ui_story_1018_10180701_22_dialog_content = "喬瑟琳姐姐真是個了不起的人！",
  ui_story_1018_10180701_23_dialog_content = "阿奇，妳幫助了那麼多人，比小時候的我更加了不起！",
  ui_story_1018_10180701_24_dialog_content = "就是這樣，再加把勁，把傷患送進去就安全了。",
  ui_story_1018_10180701_25_dialog_content = "嗯！",
  ui_story_1018_10180701_26_dialog_content = "<color=#e8d9bb>咚咚咚——咚咚咚——</color>",
  ui_story_1018_10180701_27_dialog_content = "我是黃昏鎮的戰士喬瑟琳，我們帶著傷患，請求白夜要塞給予傷患醫治和庇護！",
  ui_story_1018_10180701_28_dialog_content = "城主有令，除白夜人以外，任何人不得入內。你們去別處尋求庇護吧。",
  ui_story_1018_10180701_29_dialog_content = "請聽我說，我身後的傷患中有白夜要塞的騎士，他們是我們的同伴，至少請讓他們進城。",
  ui_story_1018_10180701_30_dialog_content = "此前「鐵棘騎士團」已多次求援，白夜要塞的資源有限，無法醫治更多士兵了。",
  ui_story_1018_10180701_31_dialog_content = "士兵先生……",
  ui_story_1018_10180701_32_dialog_content = "<color=#e8d9bb>磅磅磅——</color>",
  ui_story_1018_10180701_33_dialog_content = "喬瑟琳姐姐！那兩個啟光的傷患越來越不受控制了。",
  ui_story_1018_10180701_34_dialog_content = "如果他們再次掙脫繩索，襲擊傷患的話……",
  ui_story_1018_10180701_35_dialog_content = "你隊伍中的傷患有危害白夜要塞百姓的可能，我更不能讓你們進來！",
  ui_story_1018_10180701_36_dialog_content = "既然如此……",
  ui_story_1018_10180701_37_dialog_content = "士兵先生，請轉告白夜教區的若瑟神父——",
  ui_story_1018_10180701_38_dialog_content = "我，喬瑟琳，以黃昏鎮「聖女」之名，請求白夜教會給予光靈庇護。",
  ui_story_1018_10180701_39_dialog_content = "若瑟神父有要事在身，不在城內。而妳不過是黃昏鎮百姓口中的「聖女」罷了。",
  ui_story_1018_10180701_40_dialog_content = "即使妳真的是「聖女」，我也不會違背城主的命令！",
  ui_story_1018_10180701_41_dialog_content = "光之神的子民正處於水深火熱之中，白夜教會難道不管光靈的死活嗎？！",
  ui_story_1018_10180701_42_dialog_content = "吼！！！",
  ui_story_1018_10180701_43_dialog_content = "天啊……士兵竟、竟然變成了暗鬼？",
  ui_story_1018_10180701_44_dialog_content = "喬瑟琳姐姐！",
  ui_story_1018_10180701_45_dialog_content = "大家不必驚慌！盡快遠離馬車，交給我來處理！",
  ui_story_1018_10180701_46_dialog_content = "<size=30>把城門打開。</size>",
  ui_story_1018_10180701_47_dialog_content = "讓這樣的士兵進城，無疑是自掘墳墓……",
  ui_story_1018_10180701_48_dialog_content = "把城門打開。",
  ui_story_1018_10180701_49_dialog_content = "膽敢忤逆「聖女」之意，看來你已忘卻白夜教義！",
  ui_story_1018_10180701_50_dialog_content = "我，高庭衛隊長卡蓮，以白夜要塞臨時城主之名，命令你打開城門，接收難民！",
  ui_story_1018_10180701_51_dialog_content = "暗鬼交給我！開門！",
  ui_story_1018_10180701_52_dialog_content = "卡、卡蓮殿下……是、是！",
  ui_story_1018_10180701_53_dialog_content = "<color=#e8d9bb>嘎吱——</color>",
  ui_story_1018_10180702_1_dialog_content = "<color=#e8d9bb>這束不屬於世間的光芒，讓眾人產生了俯身跪拜之意……</color>",
  ui_story_1018_10180702_2_dialog_content = "是真正的「聖女大人」！",
  ui_story_1018_10180702_3_dialog_content = "不會錯……這聖光裡的唯有「聖女大人」！",
  ui_story_1018_10180702_4_dialog_content = "光之神聽見，教女講述的一切皆真實無妄——",
  ui_story_1018_10180702_5_dialog_content = "借您聖光，願您寵罩迷途的光靈。",
  ui_story_1018_10180702_6_dialog_content = "喬瑟琳姐姐！士兵的身體上閃著金色的光耶！",
  ui_story_1018_10180702_7_dialog_content = "好奇怪的感覺……身上的疼痛感在消失……",
  ui_story_1018_10180702_8_dialog_content = "唔，喬瑟琳姐姐……妳怎麼……在流淚……？",
  ui_story_1018_10180702_9_dialog_content = "親眼見到「聖女大人」……我有些失態……",
  ui_story_1018_10180702_10_dialog_content = "阿奇，這就是代神行走世間的使者，白夜教會的「聖女大人」！",
  ui_story_1018_10180702_11_dialog_content = "「聖女大人」……",
  ui_story_1018_10180702_12_dialog_content = "喬瑟琳——",
  ui_story_1018_10180702_13_dialog_content = "若瑟神父！白夜至上——",
  ui_story_1018_10180702_14_dialog_content = "白夜至上——抱歉，讓黃昏鎮的士兵受苦了！李奧那邊還順利嗎？",
  ui_story_1018_10180702_15_dialog_content = "多虧啟光士兵和空裔的幫助，暗鬼已經減少了許多。",
  ui_story_1018_10180702_16_dialog_content = "但泥潭仍然是個隱憂，啟光士兵的情況很糟糕……",
  ui_story_1018_10180702_17_dialog_content = "非常抱歉，看守要塞的士兵聽命於白夜貴族，就連城主派來的支援軍也只是堅守要塞。",
  ui_story_1018_10180702_18_dialog_content = "我除了一直向舒瓦茲求援，也無能為力……",
  ui_story_1018_10180702_19_dialog_content = "只能讓教會人員前往黃昏鎮救援，然後不斷寫信向白夜神殿求助。",
  ui_story_1018_10180702_20_dialog_content = "原來如此！如今聖女大人親臨，白夜教區已經被聖恩寵罩了！",
  ui_story_1018_10180702_21_dialog_content = "這我也沒料到。寄出信件後不久，我本來準備前往白夜城。",
  ui_story_1018_10180702_22_dialog_content = "但在動身之前，我接到了聖女大人親臨的指示，於是才在此等候。",
  ui_story_1018_10180702_23_dialog_content = "詳細情況之後再說吧，我先去教會做準備。",
  ui_story_1018_10180702_24_dialog_content = "黃昏鎮上的傷患，我會派教會人員去接過來。",
  ui_story_1018_10180702_25_dialog_content = "感謝您的幫助，若瑟神父！",
  ui_story_1018_10180702_26_dialog_content = "但是……其中一些傷患的情況比較複雜，還請多多留意。",
  ui_story_1018_10180702_27_dialog_content = "放心吧，隨聖女大人一同來的神職人員都和她一樣深諳治療要領，我一定會將他們照顧好。",
  ui_story_1018_10180702_28_dialog_content = "白夜至上——",
  ui_story_1018_10180702_29_dialog_content = "白夜至上——",
  ui_story_1018_10180702_30_dialog_content = "呼——這樣子應該就沒有問題了吧，光之神永恆。",
  ui_story_1018_10180702_31_dialog_content = "您、您真的是聖女大人啊……神棄之地竟然會有神降臨！",
  ui_story_1018_10180702_32_dialog_content = "有聖女大人在，泥潭就不會再蔓延過來了！",
  ui_story_1018_10180702_33_dialog_content = "你們看，黃昏鎮上空的黑雲已被聖女大人驅散，暗鬼將無處可逃！",
  ui_story_1018_10180702_34_dialog_content = "感謝聖女大人！",
  ui_story_1018_10180702_35_dialog_content = "不用謝……不用叫我聖女大人……",
  ui_story_1018_10180702_36_dialog_content = "聖女大人，我有一事相求，我的孩子還在黃昏鎮戰鬥——",
  ui_story_1018_10180702_37_dialog_content = "聖女大人！請您聽我說——",
  ui_story_1018_10180702_38_dialog_content = "聖女大人……",
  ui_story_1018_10180702_39_dialog_content = "大家、大家叫我赫爾達就可以了……",
  ui_story_1018_10180702_40_dialog_content = "你們的祈禱，我都有仔細聆聽……",
  ui_story_1018_10180702_41_dialog_content = "聖女大人！請不要再離我們而去……",
  ui_story_1018_10180702_42_dialog_content = "……",
  ui_story_1018_10180702_43_dialog_content = "您無需一一回應。",
  ui_story_1018_10180702_44_dialog_content = "可是，這是我第一次與神殿以外的光靈交流……",
  ui_story_1018_10180702_45_dialog_content = "無需回應。",
  ui_story_1018_10180702_46_dialog_content = "……好吧。",
  ui_story_1018_10180702_47_dialog_content = "大家的心意，聖女大人已經收到了。",
  ui_story_1018_10180702_48_dialog_content = "謝謝妳，卡蓮。赫爾達其實感到很開心，嘿嘿——",
  ui_story_1018_10180702_49_dialog_content = "嗯？妳是誰？怎麼……盯著我看呀……",
  ui_story_1018_10180702_50_dialog_content = "妳頭上的角是怎麼回事？",
  ui_story_1018_10180702_51_dialog_content = "休得無禮——",
  ui_story_1018_10180702_52_dialog_content = "沒事的！",
  ui_story_1018_10180702_53_dialog_content = "這個嘛，其實是一個和<color=#FFB400>犀角獸</color>有關的故事……",
  ui_story_1018_10180702_54_dialog_content = "是犀角獸護神的故事嗎？阿奇從小就聽過喔！故事是這樣的……",
  ui_story_1018_10180702_55_dialog_content = "<color=#e8d9bb>喬瑟琳安頓好傷患後……</color>",
  ui_story_1018_10180702_56_dialog_content = "拜見聖女大人，教女喬瑟琳來遲了。",
  ui_story_1018_10180702_57_dialog_content = "妳好，喬瑟琳，若瑟神父向我提起過妳。初次見面，希望有幫上忙。",
  ui_story_1018_10180702_58_dialog_content = "教女慚愧，無法挽救這些被暗鬼傷害的光靈，是您的聖光治癒了他們。",
  ui_story_1018_10180702_59_dialog_content = "別這麼說，妳傾盡全力救助光靈，妳是如此善良。",
  ui_story_1018_10180702_60_dialog_content = "如果不介意的話……叫我赫爾達就行了，那是我的名字喔。赫爾達還有很多問題想請教妳呢！",
  ui_story_1018_10180702_61_dialog_content = "這怎麼行……您可是聖女大人！",
  ui_story_1018_10180702_62_dialog_content = "喬瑟琳姐姐，我覺得聖女大人和黃昏鎮的姐姐們一樣親切呢。",
  ui_story_1018_10180702_63_dialog_content = "對喔！剛剛沒講完呢，阿奇——那個故事的結局，其實是……",
  ui_story_1018_10180702_64_dialog_content = "……",
  ui_story_1018_10180702_65_dialog_content = "妳在想什麼，喬瑟琳女士？",
  ui_story_1018_10180702_66_dialog_content = "卡蓮殿下，我只是有點意外……",
  ui_story_1018_10180702_67_dialog_content = "聖女大人畢竟是聖女……身上卻有一種……孩童的天真。",
  ui_story_1018_10180702_68_dialog_content = "不瞞妳說，初次見到聖女大人時，她不諳世事的模樣也令我吃驚。",
  ui_story_1018_10180702_69_dialog_content = "但是妳也看到了，聖女大人很自然地親近阿奇這個年紀的女孩，並對黃昏鎮流傳的故事非常好奇。",
  ui_story_1018_10180702_70_dialog_content = "或許身為聖女大人的她，對於身分之外的事還不甚瞭解吧。",
  ui_story_1018_10180702_71_dialog_content = "嗯，是我狹隘了，您說得沒錯。",
  ui_story_1018_10180702_72_dialog_content = "將傷患交給教會後，妳不打算留下來照顧嗎？",
  ui_story_1018_10180702_73_dialog_content = "黃昏鎮的戰事還未結束，我要回到戰場上和戰士們一起戰鬥。",
  ui_story_1018_10180702_74_dialog_content = "這邊有若瑟神父，我可以放心交給他。",
  ui_story_1018_10180702_75_dialog_content = "嗯，我會帶著白夜支援軍，隨妳一同前往。",
  ui_story_1018_10180702_76_dialog_content = "赫爾達也會去喔！我們、還有時間吧……？",
  ui_story_1018_10180702_77_dialog_content = "是的，聖女大人。",
  ui_story_1018_10180702_78_dialog_content = "有聖女大人同行，黃昏鎮必會脫離險境。我們立刻啟程吧！",
  ui_story_1018_10180801_1_dialog_content = "<color=#e8d9bb>黃昏鎮外</color>",
  ui_story_1018_10180801_2_dialog_content = "（日蝕語）大人，我不理解您為什麼要替她治療。",
  ui_story_1018_10180801_3_dialog_content = "（日蝕語）她應該和那些士兵一樣加入我們才對。",
  ui_story_1018_10180801_4_dialog_content = "把她逼到絕境，竟然還能活下來，她的實驗結果確實令人意外。",
  ui_story_1018_10180801_5_dialog_content = "如果能搞清楚她體內的「種子」為何這麼特殊，這一趟也算沒白來。",
  ui_story_1018_10180801_6_dialog_content = "（日蝕語）大人，我已經很久沒有磨牙了。",
  ui_story_1018_10180801_7_dialog_content = "瑪德昂多也恢復得差不多了，準備把地毯鋪得再長一些。",
  ui_story_1018_10180801_8_dialog_content = "（日蝕語）繼續往前推進嗎？",
  ui_story_1018_10180801_9_dialog_content = "沒錯，不過這一次，繞過黃昏鎮。",
  ui_story_1018_10180801_10_dialog_content = "泥潭漫延到啟光後，尤利西斯手上的士兵將全都變成暗鬼……",
  ui_story_1018_10180801_11_dialog_content = "（日蝕語）這些士兵，您打算怎麼辦？",
  ui_story_1018_10180801_12_dialog_content = "讓瑪德昂多運到防線去，當然還有那個「藝術品」。",
  ui_story_1018_10180801_13_dialog_content = "不過離開之前，我要看看她會不會喜歡我準備的禮物。",
  ui_story_1018_10180801_14_dialog_content = "阿克希亞隊長、大元帥！第九分隊找到了……",
  ui_story_1018_10180801_15_dialog_content = "他們……就躺在壁壘附近的泥潭裡。",
  ui_story_1018_10180801_16_dialog_content = "泥潭退散後，我們也找到了他們……只是已經……",
  ui_story_1018_10180801_17_dialog_content = "……",
  ui_story_1018_10180801_18_dialog_content = "帶我過去。",
  ui_story_1018_10180801_19_dialog_content = "除了坦克手已經進入現在的編隊，第九分隊的士兵都在這裡。",
  ui_story_1018_10180801_20_dialog_content = "其餘士兵都已犧牲，包括……「引擎七號」的駕駛員。",
  ui_story_1018_10180801_21_dialog_content = "那名士兵，為什麼是……這樣犧牲的……",
  ui_story_1018_10180801_22_dialog_content = "下顎處留有彈孔，手指緊扣扳機。顯然，他在暴走前了結了自己……",
  ui_story_1018_10180801_23_dialog_content = "……",
  ui_story_1018_10180801_24_dialog_content = "這幾位，他們只是普通的士兵吧？",
  ui_story_1018_10180801_25_dialog_content = "是的……",
  ui_story_1018_10180801_26_dialog_content = "他們的身體彼此攙扶著，是在抵擋泥潭嗎……",
  ui_story_1018_10180801_27_dialog_content = "好殘忍……幾乎只剩骨頭了……",
  ui_story_1018_10180801_28_dialog_content = "……以這種方式犧牲，他們……非常英勇。",
  ui_story_1018_10180801_29_dialog_content = "……我為我之前草率的判斷道歉。",
  ui_story_1018_10180801_30_dialog_content = "……",
  ui_story_1018_10180801_31_dialog_content = "雷霆……",
  ui_story_1018_10180801_32_dialog_content = "這是我戍境多年從未見過的情況。",
  ui_story_1018_10180801_33_dialog_content = "我們，能做點什麼嗎？",
  ui_story_1018_10180801_34_dialog_content = "繼續檢查周圍的情況，把傷患都找出來。",
  ui_story_1018_10180801_35_dialog_content = "<color=#e8d9bb>噗嚕噗嚕——</color>",
  ui_story_1018_10180801_36_dialog_content = "團長！士兵後面的泥潭裡有動靜！",
  ui_story_1018_10180801_37_dialog_content = "這就是黃昏鎮吸引人的原因嗎？",
  ui_story_1018_10180801_38_dialog_content = "原來不為別的，就為這真正的「藝術品」。",
  ui_story_1018_10180801_39_dialog_content = "吞羅？",
  ui_story_1018_10180801_40_dialog_content = "躲在暗處的敵人就是妳嗎？",
  ui_story_1018_10180801_41_dialog_content = "我是來問候大元帥的。打得還暢快嗎？",
  ui_story_1018_10180801_42_dialog_content = "吞——羅——",
  ui_story_1018_10180801_43_dialog_content = "放鬆點。就妳這副身體，認真的嗎？",
  ui_story_1018_10180801_44_dialog_content = "不許妳傷害雷霆大元帥！",
  ui_story_1018_10180801_45_dialog_content = "又是妳，呆頭呆腦的傢伙，看來我不該對妳手下留情。",
  ui_story_1018_10180801_46_dialog_content = "妳欠我部下的，我要妳加倍奉還！",
  ui_story_1018_10180801_47_dialog_content = "欠妳？就算把他們全部弄死，也不夠償還我的損失。",
  ui_story_1018_10180801_48_dialog_content = "妳大概不知道自己為什麼能撐到現在吧？啟光對妳做的事，夠妳死一百次了。",
  ui_story_1018_10180801_49_dialog_content = "難道不想知道為什麼是妳在這苦戰，而啟光始終無動於衷嗎？",
  ui_story_1018_10180801_50_dialog_content = "少說廢話，無恥的傢伙！",
  ui_story_1018_10180801_51_dialog_content = "看來多少知道一些呢。那他們知道新任元帥的作風，是親手殺死自己的部下嗎？",
  ui_story_1018_10180801_52_dialog_content = "吞羅，妳找死！",
  ui_story_1018_10180801_53_dialog_content = "雷霆冷靜！她在故意激妳。",
  ui_story_1018_10180801_54_dialog_content = "……",
  ui_story_1018_10180801_55_dialog_content = "我早知道黃昏鎮發生的一切都是妳在搞鬼，今天我不會放過妳！",
  ui_story_1018_10180801_56_dialog_content = "我不否認，但我樂意為之，就當作是對小偷的懲罰。",
  ui_story_1018_10180801_57_dialog_content = "既然藝術品你們都看到了，那正式展演就要開始囉，你們可要睜大眼睛看好！",
  ui_story_1018_10180801_58_dialog_content = "妳要做什麼？",
  ui_story_1018_10180801_59_dialog_content = "喔？站在她前面，是想和我單挑嗎？",
  ui_story_1018_10180801_60_dialog_content = "還有阿克希亞……",
  ui_story_1018_10180801_61_dialog_content = "嗯，還有我！",
  ui_story_1018_10180801_62_dialog_content = "隨便，我已經玩夠了。你們的對手，不是我——",
  ui_story_1018_10180801_63_dialog_content = "吼……",
  ui_story_1018_10180801_64_dialog_content = "這是機甲駕駛員的聲音……他不是已經犧牲了……",
  ui_story_1018_10180801_65_dialog_content = "吼……",
  ui_story_1018_10180801_66_dialog_content = "……你們已經犧牲過一次了……",
  ui_story_1018_10180801_67_dialog_content = "我不能再讓你們……",
  ui_story_1018_10180801_68_dialog_content = "大元帥……阿克希亞感受到了您的憤怒……",
  ui_story_1018_10180801_69_dialog_content = "你這是……",
  ui_story_1018_10180801_70_dialog_content = "阿克希亞想保護大元帥……雖然阿克希亞感受不到大元帥的體溫……",
  ui_story_1018_10180801_71_dialog_content = "但是鶯歌告訴過我……這裡是阿克希亞原來心臟的位置……",
  ui_story_1018_10180801_72_dialog_content = "我想，那個地方比我們身體裡的那股力量要溫熱……",
  ui_story_1018_10180801_73_dialog_content = "阿克希亞……",
  ui_story_1018_10180801_74_dialog_content = "……妳放心，我不會被那股力量控制住的。",
  ui_story_1018_10180801_75_dialog_content = "團長……整支隊伍朝我們過來了！現在怎麼辦？",
  ui_story_1018_10180801_76_dialog_content = "泥潭……不、暗能明顯從他們身體裡滲透出來，士兵的眼裡有詭異的光！",
  ui_story_1018_10180801_77_dialog_content = "<color=#e8d9bb>嗖——</color>",
  ui_story_1018_10180801_78_dialog_content = "雷槍穿刺！",
  ui_story_1018_10180801_79_dialog_content = "他們的靈早已榮歸故里，再戰鬥下去是對他們的侮辱。",
  ui_story_1018_10180801_80_dialog_content = "所有人聽清楚！不要再讓我們的士兵痛苦下去，他們保護過我們，他們沒有白白犧牲！",
  ui_story_1018_10180801_81_dialog_content = "知道了，大元帥。",
  ui_story_1018_10180801_82_dialog_content = "不錯，心狠手辣，所以不介意我把剩下的帶走吧……",
  ui_story_1018_10180801_83_dialog_content = "別想跑！",
  ui_story_1018_10180801_84_dialog_content = "一起隱入泥潭中的士兵不會是……",
  ui_story_1018_10180801_85_dialog_content = "是阿克希亞的部下。",
  ui_story_1018_10180801_86_dialog_content = "把第八分隊交給阿克希亞！",
  ui_story_1018_10180801_87_dialog_content = "阿克希亞不會有事吧……",
  ui_story_1018_10180801_88_dialog_content = "與她一起衝鋒的部下始終跟著她，應該沒問題。",
  ui_story_1018_10180801_89_dialog_content = "解決完這裡後，我們迅速追上去！",
  ui_story_1018_10180801_90_dialog_content = "嗯！",
  ui_story_1018_10180802_1_dialog_content = "都已經這副模樣了，還要追我嗎？",
  ui_story_1018_10180802_2_dialog_content = "阿克希亞……要保護大家……請把大家，還給我。",
  ui_story_1018_10180802_3_dialog_content = "那妳想想辦法，殺了我？",
  ui_story_1018_10180802_4_dialog_content = "阿克希亞……要把第八分隊帶回去！",
  ui_story_1018_10180802_5_dialog_content = "殺人？應該像這樣！",
  ui_story_1018_10180802_6_dialog_content = "不要……",
  ui_story_1018_10180802_7_dialog_content = "阿克希亞長官，您……沒事吧……",
  ui_story_1018_10180802_8_dialog_content = "……",
  ui_story_1018_10180802_9_dialog_content = "這是什麼表情？尤利西斯製造的空心人，竟然會感到……痛苦？",
  ui_story_1018_10180802_10_dialog_content = "阿克希亞……不是空心人……",
  ui_story_1018_10180802_11_dialog_content = "嘴硬？",
  ui_story_1018_10180802_12_dialog_content = "不要傷害他們……他們很痛苦……",
  ui_story_1018_10180802_13_dialog_content = "他們像是聽得到妳說話的樣子嗎？",
  ui_story_1018_10180802_14_dialog_content = "阿克希亞不會放過妳……",
  ui_story_1018_10180802_15_dialog_content = "妳除了看著我捏死他們，還能做什麼呢？",
  ui_story_1018_10180802_16_dialog_content = "（日蝕語）大人，瑪德昂多已準備就緒。",
  ui_story_1018_10180802_17_dialog_content = "很好，既然妳苦苦哀求，就留幾個陪妳玩吧。剩下的……哼哼。",
  ui_story_1018_10180802_18_dialog_content = "阿克希亞長官，大家……隱入泥潭不見了……",
  ui_story_1018_10180802_19_dialog_content = "把大家……還給我……",
  ui_story_1018_10180802_20_dialog_content = "吼！！！",
  ui_story_1018_10180802_21_dialog_content = "阿克希亞隊長，小心！",
  ui_story_1018_10180802_22_dialog_content = "吼！！！",
  ui_story_1018_10180802_23_dialog_content = "住手……",
  ui_story_1018_10180802_24_dialog_content = "救救我，阿克希亞隊長！",
  ui_story_1018_10180802_25_dialog_content = "吼！！！",
  ui_story_1018_10180802_26_dialog_content = "呃……",
  ui_story_1018_10180802_27_dialog_content = "……你們不是戰爭兵器……請不要殺死大家……",
  ui_story_1018_10180802_28_dialog_content = "吼！！！",
  ui_story_1018_10180802_29_dialog_content = "啊——",
  ui_story_1018_10180802_30_dialog_content = "……",
  ui_story_1018_10180802_31_dialog_content = "（他的叫聲……風聲、武器聲……全都聽不見了……）",
  ui_story_1018_10180802_32_dialog_content = "（他已經……死了嗎……）",
  ui_story_1018_10180802_33_dialog_content = "（或許……是阿克希亞死了……）",
  ui_story_1018_10180802_34_dialog_content = "（……）",
  ui_story_1018_10180802_35_dialog_content = "阿克希亞隊長！救我——",
  ui_story_1018_10180802_36_dialog_content = "（身體好重……沒有辦法移動……）",
  ui_story_1018_10180802_37_dialog_content = "（快……去救他！）",
  ui_story_1018_10180802_38_dialog_content = "<color=#e8d9bb>哐噹——</color>",
  ui_story_1018_10180802_39_dialog_content = "（……他的身體被重重摔在地上……）",
  ui_story_1018_10180802_40_dialog_content = "（彷彿……是阿克希亞的身體被摔在地上……）",
  ui_story_1018_10180802_41_dialog_content = "<color=#e8d9bb>吼！！！</color>",
  ui_story_1018_10180802_42_dialog_content = "（他抓破了士兵的胸口……啃食他的身體……）",
  ui_story_1018_10180802_43_dialog_content = "（士兵倒在血泊裡……）",
  ui_story_1018_10180802_44_dialog_content = "（但阿克希亞覺得……倒在那裡的是自己……）",
  ui_story_1018_10180802_45_dialog_content = "<color=#e8d9bb>哐噹——哐噹——</color>",
  ui_story_1018_10180802_46_dialog_content = "（五次、六次……）",
  ui_story_1018_10180802_47_dialog_content = "（阿克希亞已經倒下第六次了……）",
  ui_story_1018_10180802_48_dialog_content = "（第十次……）",
  ui_story_1018_10180802_49_dialog_content = "（第二十三次、第二十四次……）",
  ui_story_1018_10180802_50_dialog_content = "（一百零二次……）",
  ui_story_1018_10180802_51_dialog_content = "（兩千次……）",
  ui_story_1018_10180802_52_dialog_content = "（……）",
  ui_story_1018_10180802_53_dialog_content = "（第一萬一千一百一十一次……）",
  ui_story_1018_10180802_54_dialog_content = "（阿克希亞還在倒下……）",
  ui_story_1018_10180802_55_dialog_content = "（父親說，阿克希亞是優秀的戰爭兵器，戰爭兵器從不動搖。）",
  ui_story_1018_10180802_56_dialog_content = "（但阿克希亞一次次地倒下……）",
  ui_story_1018_10180802_57_dialog_content = "（怎麼阻止這一切，阿克希亞不知道……）",
  ui_story_1018_10180802_58_dialog_content = "阿克希亞！",
  ui_story_1018_10180802_59_dialog_content = "（是父親……？請原諒阿克希亞……）",
  ui_story_1018_10180802_60_dialog_content = "阿克希亞！記住，妳要以人的身分活下去！",
  ui_story_1018_10180802_61_dialog_content = "（活下去……阿克希亞要怎麼做……）",
  ui_story_1018_10180802_62_dialog_content = "（也許……阿克希亞可以……）",
  ui_story_1018_10180802_63_dialog_content = "吼……",
  ui_story_1018_10180802_64_dialog_content = "吼！！！",
  ui_story_1018_10180802_65_dialog_content = "雷鳴之勢！",
  ui_story_1018_10180802_66_dialog_content = "快醒醒，阿克希亞！聽我說話！",
  ui_story_1018_10180802_67_dialog_content = "雷霆，不能再往前了！",
  ui_story_1018_10180802_68_dialog_content = "吼……",
  ui_story_1018_10180802_69_dialog_content = "連阿克西亞都要……",
  ui_story_1018_10180802_70_dialog_content = "<color=#e8d9bb>駕——</color>",
  ui_story_1018_10180802_71_dialog_content = "這個聲音是……",
  ui_story_1018_10180802_72_dialog_content = "好刺眼的光……",
  ui_story_1018_10180802_73_dialog_content = "大元帥，李奧！抱歉，我們來遲了——",
  ui_story_1018_10180802_74_dialog_content = "教女喬瑟琳沐浴聖女之光，將袒護眾光靈重回神之懷抱！",
  ui_story_1018_10180802_75_dialog_content = "罪惡的暗鬼再也無法傷害你們！",
  ui_story_1018_10180802_76_dialog_content = "團長！是喬瑟琳！還有……卡蓮殿下和白夜空騎兵！",
  ui_story_1018_10180802_77_dialog_content = "那位站在光中的少女，該不會是……",
  ui_story_1018_10180802_78_dialog_content = "聖女傾聽，眾人回歸之時機未至。",
  ui_story_1018_10180802_79_dialog_content = "萬物有靈，汝將在神之襁褓中洗淨腐化之力。",
  ui_story_1018_10180802_80_dialog_content = "沐聖光、聞聖禱，獲祝福之光。",
  ui_story_1018_10180802_81_dialog_content = "封印之力，溢出此地，願傷病痊癒，惡念盡除。",
  ui_story_1018_10180802_82_dialog_content = "光之神永恆——光之靈永存。",
  ui_story_1018_10180802_83_dialog_content = "團長，您看士兵的身體，都在閃著金光！",
  ui_story_1018_10180802_84_dialog_content = "不會錯……喬瑟琳竟然請來了聖女大人……",
  ui_story_1018_10180802_85_dialog_content = "是她在治療這些異常士兵？",
  ui_story_1018_10180802_86_dialog_content = "嗯……據說聖女不僅能驅除暗能影響，普通光靈就算只是看到聖光，都能獲得治療……",
  ui_story_1018_10180802_87_dialog_content = "確實……",
  ui_story_1018_10180802_88_dialog_content = "我身體裡的那股力量似乎在漸漸消散，感覺舒暢許多……",
  ui_story_1018_10180802_89_dialog_content = "果然，變成暗鬼的士兵都不再進攻了……",
  ui_story_1018_10180802_90_dialog_content = "汝之苦痛，我已深知，此刻只需靜待修養之時。",
  ui_story_1018_10180802_91_dialog_content = "白夜至上——",
  ui_story_1018_10180802_92_dialog_content = "抱歉，我們來遲了！",
  ui_story_1018_10180802_93_dialog_content = "你們好……",
  ui_story_1018_10180802_94_dialog_content = "向大家介紹，這位是白夜城神殿的聖女大人。",
  ui_story_1018_10180802_95_dialog_content = "白夜城神殿……這究竟是……",
  ui_story_1018_10180802_96_dialog_content = "雷霆大元帥，聖女大人來幫助我們治療負傷士兵。",
  ui_story_1018_10180802_97_dialog_content = "之前隨我前往白夜要塞的傷患，都在聖女大人的治療下脫離險境了。",
  ui_story_1018_10180802_98_dialog_content = "聖女大人使用的……是神的力量？",
  ui_story_1018_10180802_99_dialog_content = "不是的。赫爾達是光靈，與元帥並無差別。",
  ui_story_1018_10180802_100_dialog_content = "可是怎麼看都……",
  ui_story_1018_10180802_101_dialog_content = "元帥與部下的遭遇我已聽說，赫爾達無比痛心，於是擅自施救，還請元帥諒解。",
  ui_story_1018_10180802_102_dialog_content = "不，是我該謝謝聖女、大人才對……",
  ui_story_1018_10180802_103_dialog_content = "您怎麼會……到這裡來？",
  ui_story_1018_10180802_104_dialog_content = "我聆聽光靈在噩夢中的低語，那痛苦的音韻，我能洞悉。",
  ui_story_1018_10180802_105_dialog_content = "元帥也曾被噩夢困擾，赫爾達亦聞其聲。",
  ui_story_1018_10180802_106_dialog_content = "……",
  ui_story_1018_10180802_107_dialog_content = "啊、抱歉……現在似乎不是聽我說這些的時候。",
  ui_story_1018_10180802_108_dialog_content = "元帥去看看部下吧，他們應該已經脫離險境了。",
  ui_story_1018_10180802_109_dialog_content = "嗯，再次，非常感謝……",
  ui_story_1018_10180802_110_dialog_content = "聖女大人……果然不一樣啊……",
  ui_story_1018_10180802_111_dialog_content = "你的聲音，我有聽到喔！",
  ui_story_1018_10180802_112_dialog_content = "哎？我明明已經很小聲了……",
  ui_story_1018_10180802_113_dialog_content = "你好像、和大家不一樣。",
  ui_story_1018_10180802_114_dialog_content = "聖女大人，這位就是空裔。",
  ui_story_1018_10180802_115_dialog_content = "拜見聖女大人，我是PlayerName。",
  ui_story_1018_10180802_116_dialog_content = "你好，PlayerName，叫我赫爾達就可以。",
  ui_story_1018_10180802_117_dialog_content = "赫爾達……",
  ui_story_1018_10180802_118_dialog_content = "我以前讀過一本故事書，書中的主角也叫赫爾達……",
  ui_story_1018_10180802_119_dialog_content = "欸？真的嗎！那位赫爾達是個什麼樣的人呀？",
  ui_story_1018_10180802_120_dialog_content = "呃……其實是動物……",
  ui_story_1018_10180802_121_dialog_content = "你、你竟然說聖女大人是……？",
  ui_story_1018_10180802_122_dialog_content = "但是書裡真的是這麼寫的！赫爾達很喜歡種植花草……",
  ui_story_1018_10180802_123_dialog_content = "噗哈哈哈……喜歡種植花草的動物？是小鼴鼠，還是小狐狸？",
  ui_story_1018_10180802_124_dialog_content = "牠有角嗎？有翅膀嗎？去過很多地方嗎……",
  ui_story_1018_10180802_125_dialog_content = "團長，這就是白夜教會的聖女大人嗎……？",
  ui_story_1018_10180802_126_dialog_content = "嗯……",
  ui_story_1018_10180901_1_dialog_content = "<color=#e8d9bb>迦南城</color>",
  ui_story_1018_10180901_2_dialog_content = "唔……不如新聞就這麼寫好了：",
  ui_story_1018_10180901_3_dialog_content = "黃昏鎮傳回不利戰報，家屬對即將上戰場的士兵倍感不捨……",
  ui_story_1018_10180901_4_dialog_content = "哎，你能不能用更一點積極的口吻啊？不要讓人覺得我們輸了戰爭一樣……",
  ui_story_1018_10180901_5_dialog_content = "難道不是嗎？黃昏鎮從來沒有傳回過好消息。再這樣下去，報導都沒得寫了……",
  ui_story_1018_10180901_6_dialog_content = "緋將軍，我們此次的出兵任務為什麼不是去黃昏鎮支援，而是防線？",
  ui_story_1018_10180901_7_dialog_content = "軍令如此。",
  ui_story_1018_10180901_8_dialog_content = "可是黃昏鎮的戰局並不樂觀……",
  ui_story_1018_10180901_9_dialog_content = "把擔心吞進肚裡，化成接下來應對危機的動力。",
  ui_story_1018_10180901_10_dialog_content = "是……",
  ui_story_1018_10180901_11_dialog_content = "報告將軍，隊伍整頓完畢。",
  ui_story_1018_10180901_12_dialog_content = "參謀長調遣的砲車呢？",
  ui_story_1018_10180901_13_dialog_content = "已就位！",
  ui_story_1018_10180901_14_dialog_content = "出發。",
  ui_story_1018_10180901_15_dialog_content = "是！",
  ui_story_1018_10180901_16_dialog_content = "第三軍團已經出發啦！相信黃昏鎮的戰局將迎來轉機——",
  ui_story_1018_10180901_17_dialog_content = "嗯？對講機似乎收到奇怪的訊號？",
  ui_story_1018_10180901_18_dialog_content = "我也發現了！",
  ui_story_1018_10180901_19_dialog_content = "是誰在惡作劇嗎……？調一下旋鈕看能不能聽清楚……",
  ui_story_1018_10180901_20_dialog_content = "「啟明星計畫」是尤利西斯與日蝕吞羅的一場陰謀……",
  ui_story_1018_10180901_21_dialog_content = "這是……",
  ui_story_1018_10180901_22_dialog_content = "你就是訊號的發布者吧？",
  ui_story_1018_10180901_23_dialog_content = "為什麼這麼說？",
  ui_story_1018_10180901_24_dialog_content = "讓我來幫你整理一下。",
  ui_story_1018_10180901_25_dialog_content = "你一開始是艾森的眼線，被安插在大元帥身邊觀察她的一舉一動。",
  ui_story_1018_10180901_26_dialog_content = "後來，你被迫在軍演上配合尤利西斯演了一場作賊喊抓賊的戲碼。",
  ui_story_1018_10180901_27_dialog_content = "接著，在萊因哈特的公審上，你終於發現自己只是一枚政治鬥爭的棋子……",
  ui_story_1018_10180901_28_dialog_content = "於是良心發現，不僅對我們的行動睜一隻眼閉一隻眼，還在偷偷幫助我們。",
  ui_story_1018_10180901_29_dialog_content = "只是沒想到，情報官對通訊十分瞭解。你的長官對此沒意見嗎？",
  ui_story_1018_10180901_30_dialog_content = "情報官收集情報，當然也會適時放出情報，這是我自己的準則，與他人無關。",
  ui_story_1018_10180901_31_dialog_content = "哼，看來你是認真的。",
  ui_story_1018_10180901_32_dialog_content = "知行合一是我評判一個人的標準，你的情報工作準確，態度堅定。",
  ui_story_1018_10180901_33_dialog_content = "也就是說，你在監獄中對我說的話，我現在完全相信了……",
  ui_story_1018_10180901_34_dialog_content = "<color=#e8d9bb>不久前，薇薇安第三次探訪啟光監獄……</color>",
  ui_story_1018_10180901_35_dialog_content = "能夠進入高度戒備的監獄，表示阿納托利這一次提供的情報無誤。",
  ui_story_1018_10180901_36_dialog_content = "薇薇安長官，這麼重要的計畫，您為什麼會相信一個做假證的傢伙提供的情報呢？",
  ui_story_1018_10180901_37_dialog_content = "直覺。",
  ui_story_1018_10180901_38_dialog_content = "之前雷霆認為阿納托利做假證另有隱情，而他不斷試探我們此次行動的目的，也說明了他在搖擺不定。",
  ui_story_1018_10180901_39_dialog_content = "這次應該是下定決心助我們一臂之力吧。",
  ui_story_1018_10180901_40_dialog_content = "那……這群突然出現的巡邏兵，就是所謂的「一臂之力」嗎……",
  ui_story_1018_10180901_41_dialog_content = "……",
  ui_story_1018_10180901_42_dialog_content = "薇薇安參謀長，任何人進入高級戒備監獄都要出示相關證件。",
  ui_story_1018_10180901_43_dialog_content = "不如去向你們長官要？派我來的上司可沒有給我這種東西。",
  ui_story_1018_10180901_44_dialog_content = "您的直屬上司萊因哈特正關押在此，還請您和您的部下三思而行。",
  ui_story_1018_10180901_45_dialog_content = "長官，看來您對情報官的直覺並不準確。",
  ui_story_1018_10180901_46_dialog_content = "我會看錯人，他還是第一個。",
  ui_story_1018_10180901_47_dialog_content = "但計畫如此，無論如何都要趕在緋出兵之前將大元帥救出來。",
  ui_story_1018_10180901_48_dialog_content = "這是我們最後的機會，準備戰鬥！",
  ui_story_1018_10180901_49_dialog_content = "嗯，為了大元帥！",
  ui_story_1018_10180901_50_dialog_content = "參謀長，您這是要硬闖？那我們……",
  ui_story_1018_10180901_51_dialog_content = "啊痛痛痛——",
  ui_story_1018_10180901_52_dialog_content = "……我們還沒碰到您。",
  ui_story_1018_10180901_53_dialog_content = "讓我來吧。",
  ui_story_1018_10180901_54_dialog_content = "是，長官。",
  ui_story_1018_10180901_55_dialog_content = "……阿納托利，這是怎麼回事？你竟然耍我們！",
  ui_story_1018_10180901_56_dialog_content = "抱歉，我必須以這種方式消除我心中的疑慮。",
  ui_story_1018_10180901_57_dialog_content = "什麼疑慮？",
  ui_story_1018_10180901_58_dialog_content = "為了啟光的未來，你們選擇哪條路？為了達成目的，能做到什麼程度？",
  ui_story_1018_10180901_59_dialog_content = "那你得出了什麼結論？",
  ui_story_1018_10180901_60_dialog_content = "大元帥是個可靠的領導者。這是我長久觀察後得出的結論。",
  ui_story_1018_10180901_61_dialog_content = "身為一名情報官，保持懷疑是最基本的準則，因此我討厭盲目的信仰。",
  ui_story_1018_10180901_62_dialog_content = "但我曾獲得過別人對我無條件的信任，如今我在你們身上再次看到。",
  ui_story_1018_10180901_63_dialog_content = "這才是我渴望的未來。所以我選擇站在你們身邊。",
  ui_story_1018_10180901_64_dialog_content = "呵呵，恕我無法相信任何背刺大元帥之人，儘管……我很欣賞你這席話。",
  ui_story_1018_10180901_65_dialog_content = "今後您還有很多機會可以瞭解我。巡邏兵是我的部下，你們盡快行動吧。",
  ui_story_1018_10180901_66_dialog_content = "所以，歡迎你加入，不怕死的傢伙。",
  ui_story_1018_10180901_67_dialog_content = "引人注目的行動就不必了，我習慣潛於暗處。",
  ui_story_1018_10180901_68_dialog_content = "如果你們成功了，我這裡還有些籌碼能派上用場。",
  ui_story_1018_10180901_69_dialog_content = "嗯哼，一言為定。",
  ui_story_1018_10180901_70_dialog_content = "<color=#e8d9bb>嗞嗞——嗞嗞——</color>",
  ui_story_1018_10180901_71_dialog_content = "設備怎麼……都發出這個聲音？",
  ui_story_1018_10180901_72_dialog_content = "<color=#e8d9bb>嗶——</color>",
  ui_story_1018_10180901_73_dialog_content = "好奇怪……對講機壞了嗎？訊號突然就亂了。",
  ui_story_1018_10180901_74_dialog_content = "我的也是……",
  ui_story_1018_10180901_75_dialog_content = "到底……發生了什麼？",
  ui_story_1018_10180901_76_dialog_content = "看樣子，委員會出手了……",
  ui_story_1018_10180901_77_dialog_content = "參謀長，我們與防線部隊的通訊就在故障的同時中斷了。",
  ui_story_1018_10180901_78_dialog_content = "竟然用這種方式……",
  ui_story_1018_10180901_79_dialog_content = "過去聯邦對訊號的干擾，從未影響過與防線部隊的通訊。",
  ui_story_1018_10180901_80_dialog_content = "……沒有時間了，阿納托利，保護好自己。",
  ui_story_1018_10180901_81_dialog_content = "……",
  ui_story_1018_10180901_82_dialog_content = "<color=#e8d9bb>滋滋——</color>",
  ui_story_1018_10180901_83_dialog_content = "教授，無線電頻率干擾問題似乎已經解決，可以繼續進行線上會議了。",
  ui_story_1018_10180901_84_dialog_content = "……",
  ui_story_1018_10180901_85_dialog_content = "為了降低風險，我必須採取這種方式。",
  ui_story_1018_10180901_86_dialog_content = "現在還要調查訊號來源，完全恢復還需要一些時間。",
  ui_story_1018_10180901_87_dialog_content = "看來離啟光上下共賞博士陰謀的時刻又近了一步呢。",
  ui_story_1018_10180901_88_dialog_content = "我會派艾森立刻去調查這件事。",
  ui_story_1018_10180901_89_dialog_content = "轉移注意力總比硬碰硬的成本低，博士還是專心彌補實驗的缺陷吧。",
  ui_story_1018_10180901_90_dialog_content = "怎麼，面對黃昏鎮的戰局，妳有解決方案？",
  ui_story_1018_10180901_91_dialog_content = "解決方案一直都有，只是選擇用哪一個而已。這也要看事態如何發展。",
  ui_story_1018_10180901_92_dialog_content = "我會盡快用第四批「種子」來彌補。",
  ui_story_1018_10180901_93_dialog_content = "我的經驗是，不把耐心消耗在一件事情上。",
  ui_story_1018_10180901_94_dialog_content = "那個「暗面偵察隊」有好消息嗎？",
  ui_story_1018_10180901_95_dialog_content = "「暗面偵察隊」已傳回多組疑似「守護者一號」核心的<color=#FFB400>仿造裝置圖</color>。",
  ui_story_1018_10180901_96_dialog_content = "初步推測，日蝕盜取「守護者一號」的核心是在為「工程師」相關計畫做準備。",
  ui_story_1018_10180901_97_dialog_content = "……",
  ui_story_1018_10180901_98_dialog_content = "暗潮危機已經過去十年了，看看我們到底做成了什麼事情。",
  ui_story_1018_10180901_99_dialog_content = "你的擔心是多餘的，鐵面。",
  ui_story_1018_10180901_100_dialog_content = "我熟悉「守護者一號」，它的核心要派上用場，還需要一段時間。",
  ui_story_1018_10180901_101_dialog_content = "順便和各位說一聲，為了加快「種子」的研發進度，我不會再參加後續的會議。告辭。",
  ui_story_1018_10180901_102_dialog_content = "教授，這是結果，請過目。",
  ui_story_1018_10180901_103_dialog_content = "……新一期的戰鬥數據為何這麼差？",
  ui_story_1018_10180901_104_dialog_content = "教授，貝利撒留長官來訊……",
  ui_story_1018_10180901_105_dialog_content = "……接。",
  ui_story_1018_10180901_106_dialog_content = "我還是想來提醒你一句，博士。",
  ui_story_1018_10180901_107_dialog_content = "連那個從未露面的少女都已經出動，你應該知道我們落下了多少。",
  ui_story_1018_10180901_108_dialog_content = "日蝕會大張旗鼓地進犯，表示暗面的行動延遲了。如果這對你算是有利的消息。",
  ui_story_1018_10180901_109_dialog_content = "妳想說什麼？",
  ui_story_1018_10180901_110_dialog_content = "你可以繼續你的實驗，只可惜你的計畫在我這裡已經不是優先考量了。",
  ui_story_1018_10180901_111_dialog_content = "保重，博士。",
  ui_story_1018_10180901_112_dialog_content = "……",
  ui_story_1018_10180901_113_dialog_content = "教授……我們的實驗，還要繼續嗎？",
  ui_story_1018_10180901_114_dialog_content = "繼續！這點阻力微不足道！",
  ui_story_1018_10180901_115_dialog_content = "我們還有可以改進的地方嗎？步驟、環境、測量？",
  ui_story_1018_10180901_116_dialog_content = "教授……我認為這些都不是問題。",
  ui_story_1018_10180901_117_dialog_content = "也許我們可以調整一下研究思路……",
  ui_story_1018_10180901_118_dialog_content = "這和她的思路完全一致！",
  ui_story_1018_10180901_119_dialog_content = "啟光科技、和弦紐帶、「種子」……這三樣東西，你告訴我還有什麼可以調整的？",
  ui_story_1018_10180901_120_dialog_content = "教授，目前「種子」的迭代速率其實沒有問題，但是每個版本的改進效果微乎其微……",
  ui_story_1018_10180901_121_dialog_content = "果然，我對劑量的調配還是過於保守了……",
  ui_story_1018_10180901_122_dialog_content = "……時間緊迫，在下一批「種子」中增加提取物的劑量！",
  ui_story_1018_10180901_123_dialog_content = "你告訴艾森，再做一次士兵招募，淘汰掉的那批士兵可以破例參加實驗。",
  ui_story_1018_10180901_124_dialog_content = "……",
  ui_story_1018_10180901_125_dialog_content = "啊，尤利西斯教授的實驗室原來這麼熱鬧？",
  ui_story_1018_10180901_126_dialog_content = "教授……",
  ui_story_1018_10180901_127_dialog_content = "你們來做什麼？",
  ui_story_1018_10180901_128_dialog_content = "別緊張，我只是接到命令，特地把我實驗室的夥伴帶來借博士用幾天。",
  ui_story_1018_10180901_129_dialog_content = "委員會？",
  ui_story_1018_10180901_130_dialog_content = "原來你還沒接到命令？唔，或許鶯歌中校忘記告訴你了。",
  ui_story_1018_10180901_131_dialog_content = "是，教授……我也接到了命令，或許是認為我們一起，能加快實驗進度……",
  ui_story_1018_10180901_132_dialog_content = "哼，貝利撒留不過是派人來監視我而已……",
  ui_story_1018_10180901_133_dialog_content = "也罷，我不會放棄的。",
  ui_story_1018_10180901_134_dialog_content = "那麼招募士兵的工作就交給妳了，鶯歌。隔壁助理會跟妳交接。",
  ui_story_1018_10180901_135_dialog_content = "知道了，教授……",
  ui_story_1018_10180901_136_dialog_content = "貢露科研長，妳的實驗夥伴對「啟明星計畫」瞭解多少？",
  ui_story_1018_10180901_137_dialog_content = "喔，教授直接問他們就行，他們都是好學的好孩子呢～",
  ui_story_1018_10180901_138_dialog_content = "悉聽尤利西斯教授教導。",
  ui_story_1018_10180901_139_dialog_content = "妳在這裡呀，鶯歌中校，剛剛表現得很棒呢。尤利西斯教授似乎沒有察覺喔～",
  ui_story_1018_10180901_140_dialog_content = "謝謝貢露前輩……按照職責我不該這麼做……",
  ui_story_1018_10180901_141_dialog_content = "可是自從目睹教授的實驗後，我沒辦法當作什麼也沒發生過。",
  ui_story_1018_10180901_142_dialog_content = "只要我閉上眼睛，就會見到阿克希亞在戰場上與士兵互相……",
  ui_story_1018_10180901_143_dialog_content = "哈哈，善良的小鳥，不必擔心。妳已經做得很好了，戰場上的事就交給我們吧。",
  ui_story_1018_10180901_144_dialog_content = "前輩的意思是？",
  ui_story_1018_10180901_145_dialog_content = "其實啟光的大家和妳有一樣的擔憂，所以嚴格來說，是妳在幫我們才對。",
  ui_story_1018_10180901_146_dialog_content = "接下來我要出發了，我會把戰場上的傷患接回來！",
  ui_story_1018_10180901_147_dialog_content = "真的嗎？貢露前輩這趟行動也是……委員會的命令嗎？",
  ui_story_1018_10180901_148_dialog_content = "鶯歌中校必須自己判斷喔～",
  ui_story_1018_10180901_149_dialog_content = "……",
  ui_story_1018_10180901_150_dialog_content = "貢露前輩，能不能再拜託您一件事……",
  ui_story_1018_10180901_151_dialog_content = "說說看。",
  ui_story_1018_10180901_152_dialog_content = "我可以，和您一起去戰場嗎？",
  ui_story_1018_10180901_153_dialog_content = "唔……一起去是沒有問題啦……",
  ui_story_1018_10180901_154_dialog_content = "但是上次在這裡看到妳時，狀態並不好。兵刃相接的聲音讓妳很難受吧。",
  ui_story_1018_10180901_155_dialog_content = "沒錯……雖然身為一名軍人，我知道我必須拿起武器。",
  ui_story_1018_10180901_156_dialog_content = "但是當我一個人的時候，那些冰冷的戰鬥聲就會迴盪在我耳邊，嚇得我一身冷汗……",
  ui_story_1018_10180901_157_dialog_content = "不過現在啟光需要我，我必須做點什麼，就像我和薇薇安長官說的那樣……",
  ui_story_1018_10180901_158_dialog_content = "喔，薇薇安她——哇唔，差一點就要說溜嘴了呢。",
  ui_story_1018_10180901_159_dialog_content = "善良小鳥終究是要飛向自己的天地。準備好了就到整備場來找我吧！",
  ui_story_1018_10180901_160_dialog_content = "嗯，謝謝您，貢露前輩。",
  ui_story_1018_10181002_1_dialog_content = "報告衛隊長，泥潭消散了許多，黃昏鎮周圍已經沒有暗鬼活動的跡象。",
  ui_story_1018_10181002_2_dialog_content = "協助啟光的搜救任務完成，雷霆大元帥在向部下瞭解情況。",
  ui_story_1018_10181002_3_dialog_content = "明白了，整頓隊伍後待命。",
  ui_story_1018_10181002_4_dialog_content = "原來，泥潭褪去之後的黃昏鎮是這樣的……這裡原來很熱鬧。",
  ui_story_1018_10181002_5_dialog_content = "是的，聖女大人，這附近原來是市集，還勉強看得出攤位的模樣。",
  ui_story_1018_10181002_6_dialog_content = "前面那個斷掉的石壁，本來圍著一個小花壇。",
  ui_story_1018_10181002_7_dialog_content = "說來也奇怪，花壇裡種著各式各樣的花朵，而且常年盛開。",
  ui_story_1018_10181002_8_dialog_content = "孩子們喜歡在這裡玩耍，我小時候也是。",
  ui_story_1018_10181002_9_dialog_content = "只是……孩子們的樂園，如今完全被暗鬼摧毀了……",
  ui_story_1018_10181002_10_dialog_content = "我相信，凋零的花朵將再度綻放。",
  ui_story_1018_10181002_11_dialog_content = "在喬瑟琳女士的呵護下，孩子們會在這享受幸福的生活。",
  ui_story_1018_10181002_12_dialog_content = "嘿嘿，我能聽到孩子們的笑聲喔～",
  ui_story_1018_10181002_13_dialog_content = "謝謝聖女大人的認可！只是我擔心……",
  ui_story_1018_10181002_14_dialog_content = "暗鬼摧毀的不只是家園，還有黃昏鎮百姓對戰士們的信任……",
  ui_story_1018_10181002_15_dialog_content = "或許大家不會再相信，這個地方能帶給他們庇佑。",
  ui_story_1018_10181002_16_dialog_content = "我相信能。",
  ui_story_1018_10181002_17_dialog_content = "李奧……？",
  ui_story_1018_10181002_18_dialog_content = "這泥潭下躺著的，是這次戰爭中犧牲的戰士。",
  ui_story_1018_10181002_19_dialog_content = "黃昏鎮本來就是由士兵的屍骸承擔起來的地方，如今的局面，更是讓他們相信戰爭永遠存在。",
  ui_story_1018_10181002_20_dialog_content = "只要還有人願意在這裡生活，保護黃昏鎮的信念就不會動搖。",
  ui_story_1018_10181002_21_dialog_content = "在此之前，黃昏鎮對我來說就是一個舒適區。",
  ui_story_1018_10181002_22_dialog_content = "如果沒有這場戰役，我可能還會像從前一樣，一邊擔心著黃昏鎮何時會倒塌，一邊躊躇不前。",
  ui_story_1018_10181002_23_dialog_content = "現在的結果，對於黃昏鎮和我個人來說，都是一次重新審視自己的機會。",
  ui_story_1018_10181002_24_dialog_content = "李奧閣下，你說的這番話，是否代表你對白夜城的看法發生了改變？",
  ui_story_1018_10181002_25_dialog_content = "沒有，卡蓮殿下，恐怕要讓您失望了。",
  ui_story_1018_10181002_26_dialog_content = "不過，雷霆大元帥的行為讓我意識到，對當局的不滿不能只停留在表面。",
  ui_story_1018_10181002_27_dialog_content = "我必須率先做出改變，讓我的能力配得上我的野心。",
  ui_story_1018_10181002_28_dialog_content = "我會向各位保證，黃昏鎮的未來就是我的未來。",
  ui_story_1018_10181002_29_dialog_content = "這樣說的話，你會放心一些嗎，喬瑟琳？",
  ui_story_1018_10181002_30_dialog_content = "李奧……聽你這麼說，我非常感動。",
  ui_story_1018_10181002_31_dialog_content = "這樣的話，我相信重建黃昏鎮一定會很順利的！",
  ui_story_1018_10181002_32_dialog_content = "其實這段時間，我一直有個想法，不知聖女大人能否給予教女一些指導？",
  ui_story_1018_10181002_33_dialog_content = "聖女大人，我們還有要事在身。",
  ui_story_1018_10181002_34_dialog_content = "對喔……但是和喬瑟琳女士最後說幾句，可以嗎？",
  ui_story_1018_10181002_35_dialog_content = "喬瑟琳女士，請盡快。",
  ui_story_1018_10181002_36_dialog_content = "聖女大人，我想……在黃昏鎮建立一個庇護所有人的教會，不光是信仰光之神的人……",
  ui_story_1018_10181002_37_dialog_content = "光靈、亞人、空裔，甚至是被迫趨於黑暗的人……",
  ui_story_1018_10181002_38_dialog_content = "他們或許不被陣營接受，但每一位踏足黃昏鎮的人，只要懷有愛與關懷，便能在此安家。",
  ui_story_1018_10181002_39_dialog_content = "黃昏鎮不應只有黃昏，這裡也應該蒙光照耀。",
  ui_story_1018_10181002_40_dialog_content = "他們應該與艾斯特拉其他地方的人一樣，看得到日月星辰。",
  ui_story_1018_10181002_41_dialog_content = "我知道……這會很辛苦，但首先我希望能得到聖女大人的庇護。",
  ui_story_1018_10181002_42_dialog_content = "喬瑟琳女士，妳真是虔誠、慷慨。",
  ui_story_1018_10181002_43_dialog_content = "如同光靈創世之初南下立教的艱辛，要在這裡建立妳心中的教會，同樣困難重重。",
  ui_story_1018_10181002_44_dialog_content = "但是聖光可以照亮每一個虔誠的角落，在妳的引導下更是如此。",
  ui_story_1018_10181002_45_dialog_content = "若妳有心，就去做吧，我會給予妳支持。",
  ui_story_1018_10181002_46_dialog_content = "感謝聖女大人的教誨，教女定謹記於心！",
  ui_story_1018_10181002_47_dialog_content = "呼——我說得好嗎？",
  ui_story_1018_10181002_48_dialog_content = "辭章有度，聖女大人。但是我們該上路了。",
  ui_story_1018_10181002_49_dialog_content = "嗯！那麼今後的事情就交給你們了。",
  ui_story_1018_10181002_50_dialog_content = "對了，卡蓮，黃昏鎮安頓好後，盡快去防線處與城主的軍隊會合吧。",
  ui_story_1018_10181002_51_dialog_content = "城主的軍隊去了防線？！",
  ui_story_1018_10181002_52_dialog_content = "但他為什麼在朝堂上表現出一副漠不關心的樣子？",
  ui_story_1018_10181002_53_dialog_content = "嗯……城主說「因勢利導」什麼的，赫爾達也不是很清楚。",
  ui_story_1018_10181002_54_dialog_content = "不僅是城主的軍隊，元帥的同僚也在喔。",
  ui_story_1018_10181002_55_dialog_content = "戰爭……不是已經結束了嗎？",
  ui_story_1018_10181002_56_dialog_content = "黃昏鎮的戰爭已經結束了，你們可以放心。",
  ui_story_1018_10181002_57_dialog_content = "但是光靈的戰爭似乎才剛剛開始，這正是我離開神殿的意義所在。",
  ui_story_1018_10181002_58_dialog_content = "旅途中能遇見你們，赫爾達很開心，我會為各位祈禱。",
  ui_story_1018_10181002_59_dialog_content = "願光之神與你們同在，赫爾達靜待與各位重逢的時刻。",
  ui_story_1018_10181002_60_dialog_content = "光之神永恆——",
  ui_story_1018_10181002_61_dialog_content = "白夜至上——",
  ui_story_1018_10181002_62_dialog_content = "……暗鬼不是撤退，而是去了啟光防線。看來這次暗潮湧動不會那麼輕易結束……",
  ui_story_1018_10181002_63_dialog_content = "你們，都知道了。",
  ui_story_1018_10181002_64_dialog_content = "雷霆大元帥……至少聖女大人說……黃昏鎮目前已經沒有危險了。",
  ui_story_1018_10181002_65_dialog_content = "正是啟光軍隊和騎士團共同努力，黃昏鎮才倖免於難！",
  ui_story_1018_10181002_66_dialog_content = "謝謝妳的認可，喬瑟琳，但是不用安慰我。",
  ui_story_1018_10181002_67_dialog_content = "事實上，事態發展逐漸清晰起來，我反而感到慶幸。",
  ui_story_1018_10181002_68_dialog_content = "從結果來看我們成功了，但是對我來說，卻是一場巨大的失敗……",
  ui_story_1018_10181002_69_dialog_content = "雷霆大元帥，現在的情況已經不是啟光能夠獨自面對的了。",
  ui_story_1018_10181002_70_dialog_content = "此前黃昏鎮的戰局不利，白夜城本不該坐視不管。",
  ui_story_1018_10181002_71_dialog_content = "現在城主的軍隊已經在防線集結，無論啟光作何反應，白夜城都不會再置身事外。",
  ui_story_1018_10181002_72_dialog_content = "您誤會了，卡蓮殿下。唯有失敗，這一切才有意義。",
  ui_story_1018_10181002_73_dialog_content = "黃昏鎮的戰役，部下的犧牲，以及上頭的計畫……都必須以我的失敗作結。",
  ui_story_1018_10181002_74_dialog_content = "只有這樣，啟光才有未來。",
  ui_story_1018_10181002_75_dialog_content = "大元帥……您和您的同僚在計畫著什麼嗎？",
  ui_story_1018_10181002_76_dialog_content = "我堅信的東西，我必須去驗證，不管等待在防線處的危險是什麼。",
  ui_story_1018_10181002_77_dialog_content = "我擔心，黃昏鎮的情況會在啟光重演……",
  ui_story_1018_10181002_78_dialog_content = "阿克希亞戰士不是說，她的部下也被吞羅帶走了？",
  ui_story_1018_10181002_79_dialog_content = "只要守在那裡的是他們，是血肉之軀，我就確信不會重演。",
  ui_story_1018_10181002_80_dialog_content = "我對犧牲的士兵承諾過，無論如何，我都會帶他們回到啟光。",
  ui_story_1018_10181002_81_dialog_content = "黃昏鎮的事情，我之後會與你商量。啟光軍隊將全員返回防線。",
  ui_story_1018_10181002_82_dialog_content = "如果您去防線，黃昏鎮的騎士團會隨您一起。",
  ui_story_1018_10181002_83_dialog_content = "敵人未除，別忘了我們還是共同殺敵的盟友。",
  ui_story_1018_10181002_84_dialog_content = "哈哈哈，好！黃昏鎮的盟友，我雷霆不會忘記。",
  ui_story_1018_10181002_85_dialog_content = "既然如此，李奧閣下和雷霆大元帥，你們願意搭乘白夜城的飛空艇前往嗎？",
  ui_story_1018_10181002_86_dialog_content = "我就不必了。騎士團一向騎馬打仗，不習慣空中載具。",
  ui_story_1018_10181002_87_dialog_content = "謝謝您的好意，卡蓮殿下，但這並不符合啟光的規矩。",
  ui_story_1018_10181002_88_dialog_content = "看得出來士兵們已經非常疲憊了，不妨在飛空艇上休息吧。",
  ui_story_1018_10181002_89_dialog_content = "卡蓮說得對，如果後面仍是惡戰，現在休息是必須的。",
  ui_story_1018_10181002_90_dialog_content = "傷重的士兵如果繼續在路上顛簸，也會承受不住吧……",
  ui_story_1018_10181002_91_dialog_content = "……連你都掌握一些帶兵的要領了嗎？",
  ui_story_1018_10181002_92_dialog_content = "看來黃昏鎮真是個鍛鍊人的地方啊。",
  ui_story_1018_10181002_93_dialog_content = "大元帥，那我們就恭敬不如從命了。",
  ui_story_1018_10181002_94_dialog_content = "團長，那我們也……？",
  ui_story_1018_10181002_95_dialog_content = "……",
  ui_story_1018_10181002_96_dialog_content = "一起來吧，李奧。",
  ui_story_1018_10181002_97_dialog_content = "既然要共同殺敵就別磨蹭了，騎士。",
  ui_story_1018_10181002_98_dialog_content = "……嗯！",
  ui_story_1018_10181101_1_dialog_content = "<color=#e8d9bb>啟光防線</color>",
  ui_story_1018_10181101_2_dialog_content = "報告軍團長，已確認東西防線上出現的騎兵來自白夜城。",
  ui_story_1018_10181101_3_dialog_content = "目前東西防線上未見暗鬼蹤跡，白夜騎兵和我方守備部隊處於盯哨狀態。",
  ui_story_1018_10181101_4_dialog_content = "知道了。",
  ui_story_1018_10181101_5_dialog_content = "暗鬼的進攻路線有變化嗎？",
  ui_story_1018_10181101_6_dialog_content = "未改變路線，始終是從中部向內陸垂直進攻；攻擊部隊正在迎戰，有機會突破敵方隊伍。",
  ui_story_1018_10181101_7_dialog_content = "現在目標不明，攻擊部隊在壕溝外抵禦暗鬼即可。",
  ui_story_1018_10181101_8_dialog_content = "但是軍團長……即使打退一波暗鬼，又會有新一波進攻，我們繼續防守真的沒有問題嗎……",
  ui_story_1018_10181101_9_dialog_content = "這些暗鬼不過是一波接一波的挑釁罷了，不是進攻的態勢。",
  ui_story_1018_10181101_10_dialog_content = "在弄清敵情之前，不能輕舉妄動。",
  ui_story_1018_10181101_11_dialog_content = "防禦工事安排得怎麼樣了？",
  ui_story_1018_10181101_12_dialog_content = "地下城之間的防禦事務由巴頓將軍負責，緋將軍的部隊應該快要抵達防線了。",
  ui_story_1018_10181101_13_dialog_content = "此前的通訊裝置故障還未恢復，已按照您的要求通知下去，地面戰場交由正面軍負責。",
  ui_story_1018_10181101_14_dialog_content = "各地下城只做好自我防禦，不回應防線戰事。",
  ui_story_1018_10181101_15_dialog_content = "好。黃昏鎮那邊還是沒有消息嗎？",
  ui_story_1018_10181101_16_dialog_content = "未收到大元帥的消息。但以白夜軍隊的警戒狀態來看，黃昏鎮戰場已經接近尾聲。",
  ui_story_1018_10181101_17_dialog_content = "……希望與料想的一樣。",
  ui_story_1018_10181101_18_dialog_content = "軍團長——防線外側，壕溝裡突然湧現泥潭，幾名士兵落入其中！",
  ui_story_1018_10181101_19_dialog_content = "暗鬼這一次的進攻要兇猛得多！",
  ui_story_1018_10181101_20_dialog_content = "壕溝裡？之前並沒見到泥潭擴散的跡象呀。",
  ui_story_1018_10181101_21_dialog_content = "報告軍團長，泥潭並不是逐步擴散過來，而是突然從地面湧出來的！",
  ui_story_1018_10181101_22_dialog_content = "士兵描述，壕溝裡原先有一些污泥，結果污泥突然攪動起來，越積越多。",
  ui_story_1018_10181101_23_dialog_content = "已經擴散到週邊的壁壘了！",
  ui_story_1018_10181101_24_dialog_content = "……",
  ui_story_1018_10181101_25_dialog_content = "把情況告知東西防線上的白夜騎兵，叫守備部隊迅速往中央靠攏！",
  ui_story_1018_10181101_26_dialog_content = "突擊部隊全員，立刻隨我向中部前進！",
  ui_story_1018_10181101_27_dialog_content = "是！",
  ui_story_1018_10181101_28_dialog_content = "就這樣也敢稱為「壁壘」？十年前這樣，十年後還是這樣。",
  ui_story_1018_10181101_29_dialog_content = "<食物——>",
  ui_story_1018_10181101_30_dialog_content = "你不是來這裡進食的，你只需將那些能幹的傢伙運過來。",
  ui_story_1018_10181101_31_dialog_content = "不出多久，從暗面通往腹地的道路就會連上。",
  ui_story_1018_10181101_32_dialog_content = "<藍色的火焰在燃燒——>",
  ui_story_1018_10181101_33_dialog_content = "呵呵，動作倒是挺快的。",
  ui_story_1018_10181101_34_dialog_content = "原來是你，背叛同胞之人。",
  ui_story_1018_10181101_35_dialog_content = "呵，妳也不過如此。忘了妳曾經殺戮過的士兵了嗎？",
  ui_story_1018_10181101_36_dialog_content = "無知小人！黃昏鎮犧牲的戰士皆為妳所殺？",
  ui_story_1018_10181101_37_dialog_content = "不全是。不少是死在自己人的槍下，不過這倒符合啟光用完即棄的傳統。",
  ui_story_1018_10181101_38_dialog_content = "廢話少說，準備迎接妳的死期！",
  ui_story_1018_10181101_39_dialog_content = "將死之人是妳吧？你們新任大元帥在「他們」面前，可是嚐盡了苦頭呢。",
  ui_story_1018_10181101_40_dialog_content = "……「他們」？",
  ui_story_1018_10181101_41_dialog_content = "很眼熟嗎？自作聰明的東西，早該料到會有這麼一天。",
  ui_story_1018_10181101_42_dialog_content = "……雷霆現在怎麼樣了？",
  ui_story_1018_10181101_43_dialog_content = "死活只是時間問題。她死後，大元帥的位置也該輪到你了。",
  ui_story_1018_10181101_44_dialog_content = "竟敢侮辱大元帥！",
  ui_story_1018_10181101_45_dialog_content = "吼！！！",
  ui_story_1018_10181101_46_dialog_content = "……",
  ui_story_1018_10181101_47_dialog_content = "怎麼，捨不得下手？要做心理建設的話就快點。",
  ui_story_1018_10181101_48_dialog_content = "……團長，她竟能隱入泥潭中……",
  ui_story_1018_10181101_49_dialog_content = "難道泥潭已經淹沒了黃昏鎮，從地底蔓延過來……",
  ui_story_1018_10181101_50_dialog_content = "啟光防線……也要被吞沒了嗎？",
  ui_story_1018_10181101_51_dialog_content = "……先解決暗鬼，待我確認壕溝下方的情況。",
  ui_story_1018_10181101_52_dialog_content = "既然能從地面湧現，直搗啟光地下城顯然更快。",
  ui_story_1018_10181101_53_dialog_content = "不必驚慌，控制好前線！",
  ui_story_1018_10181101_54_dialog_content = "收到！",
  ui_story_1018_10181101_55_dialog_content = "攻擊部隊退至石牆邊，開始清剿暗鬼。",
  ui_story_1018_10181101_56_dialog_content = "吼！！！",
  ui_story_1018_10181101_57_dialog_content = "軍團長，他……是我們啟光的戰士嗎？",
  ui_story_1018_10181101_58_dialog_content = "暗能匯流，啃食暗鬼，傷害同胞……",
  ui_story_1018_10181101_59_dialog_content = "他們是暗鬼，殺無赦！",
  ui_story_1018_10181101_60_dialog_content = "收、收到！軍團長！",
  ui_story_1018_10181102_1_dialog_content = "<color=#e8d9bb>轟隆隆隆——</color>",
  ui_story_1018_10181102_2_dialog_content = "是砲彈！泥潭的擴散好像都停下來了！",
  ui_story_1018_10181102_3_dialog_content = "暗鬼也是！",
  ui_story_1018_10181102_4_dialog_content = "團長，您的指令下得正好！",
  ui_story_1018_10181102_5_dialog_content = "指令不是我下的……",
  ui_story_1018_10181102_6_dialog_content = "……砲彈是分別從三座陣地堡壘打出來的。",
  ui_story_1018_10181102_7_dialog_content = "難道……",
  ui_story_1018_10181102_8_dialog_content = "哈哈哈哈，刺激！好久沒聽到這麼振奮人心的砲聲了！",
  ui_story_1018_10181102_9_dialog_content = "略為偏離目標，但仍有達到預期效果。",
  ui_story_1018_10181102_10_dialog_content = "團長，是巴頓將軍和緋將軍！",
  ui_story_1018_10181102_11_dialog_content = "果然是軍團長的支援！",
  ui_story_1018_10181102_12_dialog_content = "地下城的防禦工作非常順利。防線的戰役，我巴頓豈能錯過！",
  ui_story_1018_10181102_13_dialog_content = "既然打到家門口了，沒有理由縮在後面。",
  ui_story_1018_10181102_14_dialog_content = "兩位的支援，希羅娜感激不盡。目前暗鬼的行動尚在控制範圍內。",
  ui_story_1018_10181102_15_dialog_content = "只是壕溝出現了泥潭，我擔心會往地下城滲透。",
  ui_story_1018_10181102_16_dialog_content = "來的路上沒有發現這種情況，敵人應該才剛抵達防線。",
  ui_story_1018_10181102_17_dialog_content = "沒錯，防線周圍我都有好好盯著。",
  ui_story_1018_10181102_18_dialog_content = "之前泥潭衝垮了黃昏鎮，而且又是吞羅……",
  ui_story_1018_10181102_19_dialog_content = "無論如何，我們一起面對。",
  ui_story_1018_10181102_20_dialog_content = "現在就等雷霆了，希望會和她的計畫一樣……",
  ui_story_1018_10181102_21_dialog_content = "我相信會。",
  ui_story_1018_10181102_22_dialog_content = "……大元帥！",
  ui_story_1018_10181102_23_dialog_content = "我也相信雷霆！",
  ui_story_1018_10181102_24_dialog_content = "參謀長……你們怎麼會……？",
  ui_story_1018_10181102_25_dialog_content = "按照雷霆的計畫，若暗鬼入侵防線，我會最後一個出兵。",
  ui_story_1018_10181102_26_dialog_content = "接到命令後，大元帥會隨我一起行動。",
  ui_story_1018_10181102_27_dialog_content = "這麼說……剛剛的三門砲，其中一門是大元帥控制的？",
  ui_story_1018_10181102_28_dialog_content = "很久沒有<color=#FFB400>操控砲車</color>了，看來還不算生疏。",
  ui_story_1018_10181102_29_dialog_content = "大元帥，您是怎麼逃……",
  ui_story_1018_10181102_30_dialog_content = "喔，差點忘了——",
  ui_story_1018_10181102_31_dialog_content = "報告！參謀長薇薇安，圓滿完成劫獄任務！",
  ui_story_1018_10181102_32_dialog_content = "這真是……",
  ui_story_1018_10181102_33_dialog_content = "報告大元帥！第一軍團長希羅娜，奉命堅守防線，未讓一隻暗鬼入侵。",
  ui_story_1018_10181102_34_dialog_content = "有我第二軍團長巴頓在，一隻暗鬼都別想踏進地下城！",
  ui_story_1018_10181102_35_dialog_content = "第三軍團長緋，負責最後支援，現已完成任務。",
  ui_story_1018_10181102_36_dialog_content = "你們做得很好，各位啟光同胞都辛苦了！",
  ui_story_1018_10181102_37_dialog_content = "將軍與大元帥都來了，簡直不敢相信……",
  ui_story_1018_10181102_38_dialog_content = "大元帥！",
  ui_story_1018_10181102_39_dialog_content = "呼！！！",
  ui_story_1018_10181201_1_dialog_content = "軍團長，溝壑中並未發現吞羅的行蹤。",
  ui_story_1018_10181201_2_dialog_content = "目前白夜騎兵仍然鎮守在防線上，據說去黃昏鎮的支援軍已經在返途中。",
  ui_story_1018_10181201_3_dialog_content = "知道了，看到支援軍立即回報。",
  ui_story_1018_10181201_4_dialog_content = "看來白夜城並沒有介入戰爭的打算。",
  ui_story_1018_10181201_5_dialog_content = "黃昏鎮的情況不明，怎麼說都還有商量餘地，我只是擔心雷霆……",
  ui_story_1018_10181201_6_dialog_content = "沒錯，已經很久沒收到黃昏鎮的消息了。",
  ui_story_1018_10181201_7_dialog_content = "屬下失職，自從雷霆前往黃昏鎮後，只是鎮守在此……",
  ui_story_1018_10181201_8_dialog_content = "進攻則擔心防線被毀，退至防線內卻又怕錯過黃昏鎮的戰報。",
  ui_story_1018_10181201_9_dialog_content = "甚至也未查明泥潭四散的情況，讓吞羅逃走了。",
  ui_story_1018_10181201_10_dialog_content = "這不是妳的失職。我來時有聽說黃昏鎮的情況，敵人的攻擊方式前所未見，大家小心為上。",
  ui_story_1018_10181201_11_dialog_content = "大元帥，前方泥潭中有動靜，有敵人在迅速靠近。",
  ui_story_1018_10181201_12_dialog_content = "又來找死？讓我去會會牠！",
  ui_story_1018_10181201_13_dialog_content = "小心泥潭，吞羅很有可能潛伏在裡面。",
  ui_story_1018_10181201_14_dialog_content = "像老鼠一樣竄來竄去，這就是妳攻打防線的態度？",
  ui_story_1018_10181201_15_dialog_content = "豹——擊——！",
  ui_story_1018_10181201_16_dialog_content = "<吞沒一切——>",
  ui_story_1018_10181201_17_dialog_content = "終於敢冒出來了嗎，臭蟲！",
  ui_story_1018_10181201_18_dialog_content = "<吼——>",
  ui_story_1018_10181201_19_dialog_content = "軍團長！泥潭暗鬼出現，有大量不明士兵朝防線移動！",
  ui_story_1018_10181201_20_dialog_content = "大元帥，請您指示！",
  ui_story_1018_10181201_21_dialog_content = "……",
  ui_story_1018_10181201_22_dialog_content = "我不會對你們發號施令，現在的戰場不由我指揮。",
  ui_story_1018_10181201_23_dialog_content = "大元帥……",
  ui_story_1018_10181201_24_dialog_content = "沒有商量的餘地，我將以個人名義加入軍隊。",
  ui_story_1018_10181201_25_dialog_content = "你們各自按照計畫，放手去做吧。",
  ui_story_1018_10181201_26_dialog_content = "……",
  ui_story_1018_10181201_27_dialog_content = "既然如此，我可不想讓砲彈白運過來！東側砲手瞄準！",
  ui_story_1018_10181201_28_dialog_content = "西側砲手瞄準！",
  ui_story_1018_10181201_29_dialog_content = "軍團長，東西側守備軍團集結完畢。",
  ui_story_1018_10181201_30_dialog_content = "東西側守備軍順著泥潭搜索吞羅，攻擊部隊準備迎擊暗鬼！",
  ui_story_1018_10181201_31_dialog_content = "等等希羅娜……這些覆著泥的……暗鬼，不是啟光的士兵嗎……",
  ui_story_1018_10181201_32_dialog_content = "……",
  ui_story_1018_10181201_33_dialog_content = "他們有些……還有意識，但也有不少已經完全成了暗鬼。",
  ui_story_1018_10181201_34_dialog_content = "那該如何……",
  ui_story_1018_10181201_35_dialog_content = "讓我來。",
  ui_story_1018_10181201_36_dialog_content = "大元帥……",
  ui_story_1018_10181201_37_dialog_content = "不必擔心，只要還有希望，我都會救。",
  ui_story_1018_10181201_38_dialog_content = "可是大元帥，他們會啃食士兵，我剛才已經……",
  ui_story_1018_10181201_39_dialog_content = "我是妳的話也會這樣做。但是我的身體捱得住他們啃。",
  ui_story_1018_10181201_40_dialog_content = "繼續指揮妳的部下吧，接收傷患的隊伍已經在路上了。",
  ui_story_1018_10181201_41_dialog_content = "是，大元帥。",
  ui_story_1018_10181201_42_dialog_content = "<color=#e8d9bb>轟隆隆——</color>",
  ui_story_1018_10181201_43_dialog_content = "是……緋團長的砲火！正中泥潭！",
  ui_story_1018_10181201_44_dialog_content = "……西側砲手尚未出手。",
  ui_story_1018_10181201_45_dialog_content = "別看我，我這邊也沒有。",
  ui_story_1018_10181201_46_dialog_content = "那只能是……",
  ui_story_1018_10181201_47_dialog_content = "呵呵，就算是你來了，以為能擋住瑪德昂多嗎？",
  ui_story_1018_10181201_48_dialog_content = "黃昏鎮，正是毀在牠的手上——",
  ui_story_1018_10181201_49_dialog_content = "<泥潭過境——>",
  ui_story_1018_10181201_50_dialog_content = "吞羅，妳摧毀了黃昏鎮，現在為何又來攻打防線？",
  ui_story_1018_10181201_51_dialog_content = "被關進大牢的妳，不會還在替啟光著想吧？",
  ui_story_1018_10181201_52_dialog_content = "與其硬碰硬，不如打開城門，讓我把那些陷害妳的傢伙燒死，如何？",
  ui_story_1018_10181201_53_dialog_content = "哼，啟光有啟光的規矩，你們只能到這裡了。",
  ui_story_1018_10181201_54_dialog_content = "還是一副聖人口吻啊，怪不得搞得這麼狼狽。",
  ui_story_1018_10181201_55_dialog_content = "不許妳對大元帥說這種話！",
  ui_story_1018_10181201_56_dialog_content = "看清楚了，走狗，這裡根本就沒有大元帥。",
  ui_story_1018_10181201_57_dialog_content = "妳說沒有大元帥？這不就來了嗎。",
  ui_story_1018_10181201_58_dialog_content = "<color=#e8d9bb>地面開始響起震耳欲聾的車輪聲與馬蹄聲……</color>",
  ui_story_1018_10181201_59_dialog_content = "提前著陸果然是正確的選擇，還是在陸地上行進比較踏實！",
  ui_story_1018_10181201_60_dialog_content = "跨過前方的壕溝，敵人將無處可逃！砲車繼續朝著泥潭開砲！",
  ui_story_1018_10181201_61_dialog_content = "啊，啟光防線還真熱鬧，敵人的進攻策略還是這麼直接。",
  ui_story_1018_10181201_62_dialog_content = "哼，那正好，圍困她的最後一道鐵牆，就由我們完成。",
  ui_story_1018_10181201_63_dialog_content = "阿克希亞，會把部下都找回來……",
  ui_story_1018_10181201_64_dialog_content = "這麼快就恢復了？阿克希亞戰士的身體如同啟光機甲一般……",
  ui_story_1018_10181201_65_dialog_content = "我認為阿克希亞更厲害，都已經到那種程度了，還能恢復如初……",
  ui_story_1018_10181201_66_dialog_content = "PlayerName，休息後就要開始戰鬥了。在停靠之前，我們還得一路斬殺暗鬼。",
  ui_story_1018_10181201_67_dialog_content = "嗯，沒問題。",
  ui_story_1018_10181201_68_dialog_content = "那就坐穩了，在這裡脫隊會被砲手當作暗鬼射殺喔。",
  ui_story_1018_10181201_69_dialog_content = "……知道了。",
  ui_story_1018_10181201_70_dialog_content = "<color=#e8d9bb>嘩啦——</color>",
  ui_story_1018_10181201_71_dialog_content = "小心變道！",
  ui_story_1018_10181201_72_dialog_content = "引擎七號？突然從……壕溝中站起來了！",
  ui_story_1018_10181201_73_dialog_content = "這是……在黃昏鎮上壞掉的那一架……",
  ui_story_1018_10181201_74_dialog_content = "竟然將機甲帶到這裡來，怪不得士兵會成群消失……",
  ui_story_1018_10181201_75_dialog_content = "……吼……",
  ui_story_1018_10181201_76_dialog_content = "……這個聲音……駕駛員也許還有意識？",
  ui_story_1018_10181201_77_dialog_content = "小心不要靠近——它的腳邊有士兵爬上來！",
  ui_story_1018_10181201_78_dialog_content = "那裡……究竟藏了多少……",
  ui_story_1018_10181201_79_dialog_content = "<color=#e8d9bb>嗞——喀嚓——喀嚓——</color>",
  ui_story_1018_10181201_80_dialog_content = "這個動作……他在猶豫……",
  ui_story_1018_10181201_81_dialog_content = "大元帥，裡面的士兵或許還有救，阿克希亞想把他救出來。",
  ui_story_1018_10181201_82_dialog_content = "妳已經……破碎過一次了！",
  ui_story_1018_10181201_83_dialog_content = "在此之前，阿克希亞已經破碎過許多次了……",
  ui_story_1018_10181201_84_dialog_content = "但是，阿克希亞總能恢復如初。",
  ui_story_1018_10181201_85_dialog_content = "裡面的駕駛員是阿克希亞小隊的隊員，保護他們，是阿克希亞的職責。",
  ui_story_1018_10181201_86_dialog_content = "……",
  ui_story_1018_10181201_87_dialog_content = "……吼……",
  ui_story_1018_10181201_88_dialog_content = "血肉都已經跟機身融為一體……駕駛員一定很辛苦吧。",
  ui_story_1018_10181201_89_dialog_content = "機甲也是阿克希亞身體的一部分。阿克希亞知道，他很辛苦。",
  ui_story_1018_10181201_90_dialog_content = "……對不起……阿克希亞……",
  ui_story_1018_10181201_91_dialog_content = "雷霆，讓我和阿克希亞一起前進吧！我會和她一起把部下救出來！",
  ui_story_1018_10181201_92_dialog_content = "……身為大元帥，我的職責是要攔住你們，但是既然如此……",
  ui_story_1018_10181201_93_dialog_content = "李奧，請為我們吸引引擎七號的注意力！",
  ui_story_1018_10181201_94_dialog_content = "沒問題。",
  ui_story_1018_10181201_95_dialog_content = "雷霆……妳？",
  ui_story_1018_10181201_96_dialog_content = "我怎麼可能讓你們兩個去單獨面對。",
  ui_story_1018_10181201_97_dialog_content = "引擎七號在黃昏鎮一直是我們軍隊的壁壘，如今他卻站在我們對立面。",
  ui_story_1018_10181201_98_dialog_content = "想傷害你們，就得先把我這個壁壘打倒。",
  ui_story_1018_10181201_99_dialog_content = "吼！！！",
  ui_story_1018_10181201_100_dialog_content = "糟糕，有士兵從壕溝裡爬出來……",
  ui_story_1018_10181201_101_dialog_content = "他們……是阿克希亞的部下……",
  ui_story_1018_10181201_102_dialog_content = "想用我的部下擋住我？不會再讓她得逞！",
  ui_story_1018_10181201_103_dialog_content = "放手去做吧，阿克希亞！把妳的部下救出來！士兵交給我！",
  ui_story_1018_10181201_104_dialog_content = "阿克希亞，聽令。",
  ui_story_1018_10181202_1_dialog_content = "這邊的士兵全都控制住了，都還有意識！",
  ui_story_1018_10181202_2_dialog_content = "我這邊的也是！小心引擎七號的射擊！",
  ui_story_1018_10181202_3_dialog_content = "……吼……",
  ui_story_1018_10181202_4_dialog_content = "阿克希亞知道，你在經歷的事情很困難。",
  ui_story_1018_10181202_5_dialog_content = "你不想傷害大家……阿克希亞，都知道。",
  ui_story_1018_10181202_6_dialog_content = "吼……",
  ui_story_1018_10181202_7_dialog_content = "他在緩慢往防線移動，那邊沒有敵人。",
  ui_story_1018_10181202_8_dialog_content = "小心跟上去！等他跨過壕溝，從背後制住他！",
  ui_story_1018_10181202_9_dialog_content = "吼！！！",
  ui_story_1018_10181202_10_dialog_content = "必須出手了！",
  ui_story_1018_10181202_11_dialog_content = "阿克希亞，快離開！",
  ui_story_1018_10181202_12_dialog_content = "雷槍穿刺！",
  ui_story_1018_10181202_13_dialog_content = "吼……",
  ui_story_1018_10181202_14_dialog_content = "停下來了！但是阿克希亞——",
  ui_story_1018_10181202_15_dialog_content = "李奧，阿克希亞往你那邊去了！",
  ui_story_1018_10181202_16_dialog_content = "駕——",
  ui_story_1018_10181202_17_dialog_content = "這個距離，沒問題！",
  ui_story_1018_10181202_18_dialog_content = "駕——",
  ui_story_1018_10181202_19_dialog_content = "<color=#e8d9bb>嘶——</color>",
  ui_story_1018_10181202_20_dialog_content = "呼——",
  ui_story_1018_10181202_21_dialog_content = "再次見證了你的英勇，黃昏鎮的李奧。",
  ui_story_1018_10181202_22_dialog_content = "您……怎麼在這？",
  ui_story_1018_10181202_23_dialog_content = "阿克希亞戰士，妳辛苦了。",
  ui_story_1018_10181202_24_dialog_content = "……是大元帥，接住了阿克希亞。",
  ui_story_1018_10181202_25_dialog_content = "妳已經超越了表演賽上的自己。妳是一名優秀的戰士。",
  ui_story_1018_10181202_26_dialog_content = "阿克希亞……一直在想大元帥說的話……",
  ui_story_1018_10181202_27_dialog_content = "阿克希亞想問大元帥，戰勝暗鬼，保護啟光的戰士……",
  ui_story_1018_10181202_28_dialog_content = "這樣，算不算是「以人的身分，活下去」？",
  ui_story_1018_10181202_29_dialog_content = "妳已經做到了，阿克希亞。",
  ui_story_1018_10181202_30_dialog_content = "謝謝、大元帥。阿克希亞，會繼續戰鬥。",
  ui_story_1018_10181202_31_dialog_content = "以後還有機會，阿克希亞。關心妳的同伴來接妳了。",
  ui_story_1018_10181202_32_dialog_content = "阿克希亞！還好趕上了……",
  ui_story_1018_10181202_33_dialog_content = "鶯歌……",
  ui_story_1018_10181202_34_dialog_content = "對不起！我明明知道……卻還讓妳承受這些……對不起！",
  ui_story_1018_10181202_35_dialog_content = "阿克希亞只知道，鶯歌想保護阿克希亞。",
  ui_story_1018_10181202_36_dialog_content = "阿克希亞沒事真是太好了，我就說嘛～善良的小鳥一定會有福報的！",
  ui_story_1018_10181202_37_dialog_content = "報告大元帥！科研長貢露會和鶯歌上尉一起接啟光士兵回家！",
  ui_story_1018_10181202_38_dialog_content = "嗯，這些戰士就拜託妳們了。",
  ui_story_1018_10181202_39_dialog_content = "大元帥，對於審訊會上的事情……我很抱歉。",
  ui_story_1018_10181202_40_dialog_content = "還有尤利西斯教授的實驗……",
  ui_story_1018_10181202_41_dialog_content = "但是請相信我，這件事我不會再袒護他。我不想看到無辜的同胞受到傷害。",
  ui_story_1018_10181202_42_dialog_content = "請允許我先帶他們回啟光治療。實驗上的問題，我會想辦法……",
  ui_story_1018_10181202_43_dialog_content = "你們都是受害者，不必道歉。",
  ui_story_1018_10181202_44_dialog_content = "可是，我還是害您失去了大元帥的職位……",
  ui_story_1018_10181202_45_dialog_content = "大元帥的職位，不是妳一句話就能奪走的。",
  ui_story_1018_10181202_46_dialog_content = "我還要謝謝妳讓我當了一回大元帥呢。",
  ui_story_1018_10181202_47_dialog_content = "妳回來了，雷霆。",
  ui_story_1018_10181202_48_dialog_content = "哇，兩位大元帥！",
  ui_story_1018_10181202_49_dialog_content = "我就知道，雷霆沒有問題的！",
  ui_story_1018_10181202_50_dialog_content = "妳這傢伙，還挺像大元帥的嘛。",
  ui_story_1018_10181202_51_dialog_content = "終於熬過了黃昏鎮的惡戰。",
  ui_story_1018_10181202_52_dialog_content = "我們一直都在防線上等妳。",
  ui_story_1018_10181202_53_dialog_content = "說好暫時替你撐起大元帥之位，然後活著回來，我雷霆怎麼可能會食言？",
  ui_story_1018_10181202_54_dialog_content = "大元帥和四位軍團長？難道……",
  ui_story_1018_10181202_55_dialog_content = "……",
  ui_story_1018_10181202_56_dialog_content = "我一直在爭一個結果，但現在我也證實了一件事——",
  ui_story_1018_10181202_57_dialog_content = "雷霆，妳完全夠格。",
  ui_story_1018_10181202_58_dialog_content = "我什麼都還沒說……",
  ui_story_1018_10181202_59_dialog_content = "妳完全夠格。",
  ui_story_1018_10181202_60_dialog_content = "……",
  ui_story_1018_10181202_61_dialog_content = "咳，妳以為……妳這麼說，我就會欣然接受？",
  ui_story_1018_10181202_62_dialog_content = "沒戰勝妳之前，我是不會心安理得地擔任大元帥的。",
  ui_story_1018_10181202_63_dialog_content = "戰爭還沒結束，妳給我好好指揮。",
  ui_story_1018_10181202_64_dialog_content = "……",
  ui_story_1018_10181202_65_dialog_content = "近衛軍團長雷霆，奉命驅逐黃昏鎮的暗鬼，任務完成！",
  ui_story_1018_10181202_66_dialog_content = "啟光四軍團集結防線完畢，等待執行啟光大元帥的任務！",
  ui_story_1018_10181401_1_dialog_content = "時間很充裕，還以為這裡會有個大窟窿呢。",
  ui_story_1018_10181401_2_dialog_content = "怎麼，捨不得姐姐嗎？",
  ui_story_1018_10181401_3_dialog_content = "可笑，我想妳的事情也該辦好了，才不想繼續浪費時間。",
  ui_story_1018_10181401_4_dialog_content = "走吧，妳期待的時刻就要到來了。",
  ui_story_1018_10181401_5_dialog_content = "好。不過離開之前，我還有一點東西要清理。",
  ui_story_1018_10181401_6_dialog_content = "……我瞭解吞羅。要不是對她的實驗有利，她是不會冒險做這麼多事的。",
  ui_story_1018_10181401_7_dialog_content = "更何況，把赫利俄斯留在迦南城，這應該是她沒料到的結果。",
  ui_story_1018_10181401_8_dialog_content = "這麼說，吞羅潛入啟光地下城，是尤利西斯答應會給她想要的東西……",
  ui_story_1018_10181401_9_dialog_content = "而尤利西斯擺了吞羅一道，拿到「種子」後馬上投入「啟明星計畫」。",
  ui_story_1018_10181401_10_dialog_content = "有這個可能。",
  ui_story_1018_10181401_11_dialog_content = "「守護者一號」的核心也是他們交易的一部分？",
  ui_story_1018_10181401_12_dialog_content = "是日蝕計畫的一部分，但是不是他們交易的內容還不明瞭。",
  ui_story_1018_10181401_13_dialog_content = "我傾向相信，「守護者一號」的核心被盜並不在尤利西斯的計畫之內。",
  ui_story_1018_10181401_14_dialog_content = "委員會沒有理由為了「啟明星計畫」而讓「守護者一號」的核心落入日蝕手裡。",
  ui_story_1018_10181401_15_dialog_content = "這麼做不僅代價太大，而且植入了「種子」的士兵即使能撐過去，未來也無法走上戰場。",
  ui_story_1018_10181401_16_dialog_content = "妳說……什麼？",
  ui_story_1018_10181401_17_dialog_content = "……",
  ui_story_1018_10181401_18_dialog_content = "……",
  ui_story_1018_10181401_19_dialog_content = "妳，植入了「種子」……？",
  ui_story_1018_10181401_20_dialog_content = "……這有什麼……我現在不是好好的？",
  ui_story_1018_10181401_21_dialog_content = "……",
  ui_story_1018_10181401_22_dialog_content = "原來，我堅持讓你成為大元帥，竟然是要植入「種子」……",
  ui_story_1018_10181401_23_dialog_content = "這事與妳無關，是我自己的決定。",
  ui_story_1018_10181401_24_dialog_content = "我不該……",
  ui_story_1018_10181401_25_dialog_content = "要是沒有我的「種子」，就憑她自己也能撐到現在？",
  ui_story_1018_10181401_26_dialog_content = "……終於露面了，吞羅。",
  ui_story_1018_10181401_27_dialog_content = "骯髒的東西！",
  ui_story_1018_10181401_28_dialog_content = "吞羅！我的部下受妳折磨，現在該做個了結了。",
  ui_story_1018_10181401_29_dialog_content = "等等雷霆，她身後的泥潭中有士兵！",
  ui_story_1018_10181401_30_dialog_content = "吼……",
  ui_story_1018_10181401_31_dialog_content = "竟然用這種陰險的方式……",
  ui_story_1018_10181401_32_dialog_content = "小心控制住他們！保護好防線！這裡先交給我！",
  ui_story_1018_10181401_33_dialog_content = "收到！",
  ui_story_1018_10181401_34_dialog_content = "很有精神嘛。妳難道不好奇，妳體內的「種子」為什麼沒把妳折騰壞呢？",
  ui_story_1018_10181401_35_dialog_content = "還是說，毫不猶豫地把部下殺了，妳其實感到很痛快？",
  ui_story_1018_10181401_36_dialog_content = "住嘴，吞羅。傷害啟光士兵的人是妳。",
  ui_story_1018_10181401_37_dialog_content = "……",
  ui_story_1018_10181401_38_dialog_content = "在泥潭中治療我的人，果然是妳……",
  ui_story_1018_10181401_39_dialog_content = "折磨我的部下……把我逼到絕境……只為了看「種子」在我身上的反應……",
  ui_story_1018_10181401_40_dialog_content = "看來妳沒有我想得那麼蠢。我只是順手幫尤利西斯一個小忙而已，他是個非常失敗的科學家。",
  ui_story_1018_10181401_41_dialog_content = "吞羅，日蝕到底答應了妳什麼？",
  ui_story_1018_10181401_42_dialog_content = "這種事情妳怎麼可能會懂？妳以為妳還有能力保護一切？",
  ui_story_1018_10181401_43_dialog_content = "光靈即使接受過改造，仍然是一群身體脆弱、腦袋不清的廢物。",
  ui_story_1018_10181401_44_dialog_content = "與其被啟光高層用完即棄，不如趁早替自己找條出路。",
  ui_story_1018_10181401_45_dialog_content = "哼，妳投靠日蝕，現在不過是隻任人驅使的暗鬼而已，沒什麼好得意的。",
  ui_story_1018_10181401_46_dialog_content = "妳自以為聰明，但那不過是妳參加了「人造太陽」計畫的結果而已。",
  ui_story_1018_10181401_47_dialog_content = "在場的所有人，包括在黃昏鎮倒下的士兵，都是靠自己的意志走到現在。",
  ui_story_1018_10181401_48_dialog_content = "比起他們，妳才是真正屈服於力量的奴隸！",
  ui_story_1018_10181401_49_dialog_content = "真正脆弱的是妳！",
  ui_story_1018_10181401_50_dialog_content = "閉嘴！腦子進水的白癡！妳現在都是靠我的「種子」才能活著。",
  ui_story_1018_10181401_51_dialog_content = "這世界不是給三歲小孩看的童話書。要活下去，必須不惜一切代價往上爬。",
  ui_story_1018_10181401_52_dialog_content = "像蟑螂一樣四處逃竄，無知的光靈到死都不會得知世界的真相。",
  ui_story_1018_10181401_53_dialog_content = "我知道妳有抱負，吞羅。即使如此，我也不允許妳犧牲他人來實現抱負。",
  ui_story_1018_10181401_54_dialog_content = "我再跟妳說最後一次——",
  ui_story_1018_10181401_55_dialog_content = "妳傷害了啟光同胞，啟光不會饒過妳。但我現在不是大元帥，我希望妳停手。",
  ui_story_1018_10181401_56_dialog_content = "不要聽任日蝕的安排。那不是妳真正的意志。",
  ui_story_1018_10181401_57_dialog_content = "聽任安排的是妳，萊因哈特！妳保護不了所有人！",
  ui_story_1018_10181401_58_dialog_content = "妳也用不著對我有惻隱之心，我早已不屑與妳為伍。",
  ui_story_1018_10181401_59_dialog_content = "妳大可追殺我，但我不會停下腳步。",
  ui_story_1018_10181401_60_dialog_content = "<color=#e8d9bb>劈啪——</color>",
  ui_story_1018_10181401_61_dialog_content = "咳咳，臨別感言就是妳送給姐姐的禮物嗎？",
  ui_story_1018_10181401_62_dialog_content = "罪靈，吃我一刀！",
  ui_story_1018_10181401_63_dialog_content = "士兵都控制住了，竟然還出現罪靈。",
  ui_story_1018_10181401_64_dialog_content = "我要是想陪你們玩，你們早就都沒命了。",
  ui_story_1018_10181401_65_dialog_content = "吞羅，妳再說下去，我就要改變主意了。",
  ui_story_1018_10181401_66_dialog_content = "不要追隨日蝕，吞羅。妳會因此喪命。",
  ui_story_1018_10181401_67_dialog_content = "這是我自己的事。倒是妳，萊因哈特，小心死在我手上。",
  ui_story_1018_10181401_68_dialog_content = "<color=#e8d9bb>劈啪——</color>",
  ui_story_1018_10181401_69_dialog_content = "體內的「種子」在微微震動……小心！附近有敵人！",
  ui_story_1018_10181401_70_dialog_content = "<嘔——>",
  ui_story_1018_10181401_71_dialog_content = "吼！！！",
  ui_story_1018_10181401_72_dialog_content = "牠口中吐出的這些……是吞羅從黃昏鎮帶走的……",
  ui_story_1018_10181401_73_dialog_content = "吼！！！",
  ui_story_1018_10181401_74_dialog_content = "這、這機甲不是已經被打倒了嗎？！竟然又站起來！",
  ui_story_1018_10181401_75_dialog_content = "吞羅果然留了一手。",
  ui_story_1018_10181401_76_dialog_content = "壕溝裡淤積大量泥潭，機甲被打倒後一直躺在那裡。",
  ui_story_1018_10181401_77_dialog_content = "現在泥潭暗鬼再次出現，恐怕沒有那麼容易倒下了……",
  ui_story_1018_10181401_78_dialog_content = "現在怎麼辦，大元帥？",
  ui_story_1018_10181401_79_dialog_content = "……",
  ui_story_1018_10181401_80_dialog_content = "……",
  ui_story_1018_10181401_81_dialog_content = "沒有讓部下好好安息，是我的失職……",
  ui_story_1018_10181401_82_dialog_content = "無論如何，他們的身體，我會不顧一切奪回來！",
  ui_story_1018_10181401_83_dialog_content = "妳才剛被吞羅傷過……",
  ui_story_1018_10181401_84_dialog_content = "我的身體我清楚……我會控制自己……不去使用那股力量。",
  ui_story_1018_10181401_85_dialog_content = "我要直搗泥潭「中心」，把它再次打爆！",
  ui_story_1018_10181401_86_dialog_content = "我會與妳一起進攻，雷霆。這些狂暴的士兵就交給我。",
  ui_story_1018_10181401_87_dialog_content = "防線有我們守著！",
  ui_story_1018_10181401_88_dialog_content = "嗯！",
  ui_story_1018_10181401_89_dialog_content = "大元帥——",
  ui_story_1018_10181401_90_dialog_content = "你們怎麼也……",
  ui_story_1018_10181401_91_dialog_content = "白夜空騎兵會做好掩護，暗鬼傷不到你們。",
  ui_story_1018_10181401_92_dialog_content = "大元帥的戰法我很熟悉，這一次黃昏鎮的騎士會護送你衝入泥潭。",
  ui_story_1018_10181401_93_dialog_content = "還有我，雷霆，我會輔助妳作戰！",
  ui_story_1018_10181401_94_dialog_content = "白夜至上——這是多方勢力組成的聯合軍隊！",
  ui_story_1018_10181401_95_dialog_content = "那就踐行各自的意志吧！消滅敵人後，我們再會合！",
  ui_story_1018_10181401_96_dialog_content = "萊因哈特，妳說呢？",
  ui_story_1018_10181401_97_dialog_content = "無論如何，都不能放棄任何一個啟光同胞！",
  ui_story_1018_10181501_1_dialog_content = "<color=#e8d9bb>浠瀝瀝——</color>",
  ui_story_1018_10181501_2_dialog_content = "嗯？下雨了……？",
  ui_story_1018_10181501_3_dialog_content = "確實有點罕見。",
  ui_story_1018_10181501_4_dialog_content = "大元帥，周遭已經沒有暗鬼的蹤跡。",
  ui_story_1018_10181501_5_dialog_content = "白夜城的部隊向東西防線去清理戰場了。",
  ui_story_1018_10181501_6_dialog_content = "我這邊也很順利！泥潭在退散，防線還好好的！",
  ui_story_1018_10181501_7_dialog_content = "雷霆這傢伙，果然很能打啊！",
  ui_story_1018_10181501_8_dialog_content = "泥潭會消散，會不會跟這場雨有關？",
  ui_story_1018_10181501_9_dialog_content = "這我倒沒想過。這麼說……真的結束了……",
  ui_story_1018_10181501_10_dialog_content = "妳醒了，沒事吧？",
  ui_story_1018_10181501_11_dialog_content = "我一直醒著，只是在想……那時候妳對我說的話……",
  ui_story_1018_10181501_12_dialog_content = "<color=#e8d9bb>雷霆去找尤利西斯之前……</color>",
  ui_story_1018_10181501_13_dialog_content = "你到底要在這地方待到什麼時候？",
  ui_story_1018_10181501_14_dialog_content = "別在這裡說這些，審訊結果妳也聽到了——",
  ui_story_1018_10181501_15_dialog_content = "萊因哈特！",
  ui_story_1018_10181501_16_dialog_content = "妳難道要我相信妳會通敵這種蠢話？",
  ui_story_1018_10181501_17_dialog_content = "……",
  ui_story_1018_10181501_18_dialog_content = "妳參加「人造太陽」計畫的時候，也是這般緘口不言嗎？",
  ui_story_1018_10181501_19_dialog_content = "妳都知道了。",
  ui_story_1018_10181501_20_dialog_content = "妳接受了身體改造，所以才能在決鬥上贏我？",
  ui_story_1018_10181501_21_dialog_content = "……",
  ui_story_1018_10181501_22_dialog_content = "回答我！",
  ui_story_1018_10181501_23_dialog_content = "很多事情不是外表看起來那麼簡單。就當是為了啟光好，妳不要再問下去了。",
  ui_story_1018_10181501_24_dialog_content = "堂堂啟光大元帥，妳明明可以——",
  ui_story_1018_10181501_25_dialog_content = "正因如此！我必須接受這個結果。",
  ui_story_1018_10181501_26_dialog_content = "……",
  ui_story_1018_10181501_27_dialog_content = "想通了就把拳頭鬆開。現在不是鬧脾氣的時候。",
  ui_story_1018_10181501_28_dialog_content = "……",
  ui_story_1018_10181501_29_dialog_content = "妳的未來，會在掌心湧現。",
  ui_story_1018_10181501_30_dialog_content = "一直緊握拳頭，妳將一無所有。",
  ui_story_1018_10181501_31_dialog_content = "「握緊拳頭，我們將一無所有」……",
  ui_story_1018_10181501_32_dialog_content = "我為什麼會想起這句話……",
  ui_story_1018_10181501_33_dialog_content = "因為是時候了。我們現在要握拳打向共同的敵人。",
  ui_story_1018_10181501_34_dialog_content = "握拳的時候，應該打向共同的敵人。",
  ui_story_1018_10181501_35_dialog_content = "……",
  ui_story_1018_10181501_36_dialog_content = "相信我，妳會明白我手中的力量。",
  ui_story_1018_10181501_37_dialog_content = "這就是妳的計畫，是嗎……",
  ui_story_1018_10181501_38_dialog_content = "……",
  ui_story_1018_10181501_39_dialog_content = "妳已經做好覺悟，讓我放手去做了……",
  ui_story_1018_10181501_40_dialog_content = "……",
  ui_story_1018_10181501_41_dialog_content = "我知道了。",
  ui_story_1018_10181501_42_dialog_content = "我，會暫時助你撐起大元帥之位。",
  ui_story_1018_10181501_43_dialog_content = "但我終究會踏破鐵牢，讓你心無旁騖地成為我的對手。",
  ui_story_1018_10181501_44_dialog_content = "在那之前，我們一起揮拳，打向共同的敵人。",
  ui_story_1018_10181501_45_dialog_content = "雷霆。",
  ui_story_1018_10181501_46_dialog_content = "嗯？",
  ui_story_1018_10181501_47_dialog_content = "放手去做，但妳一定要活著回來。",
  ui_story_1018_10181501_48_dialog_content = "……",
  ui_story_1018_10181501_49_dialog_content = "<color=#e8d9bb>浠瀝瀝——</color>",
  ui_story_1018_10181501_50_dialog_content = "如今我活著回來了，但那些士兵……已經沒救了，對嗎？",
  ui_story_1018_10181501_51_dialog_content = "他們能夠撐到現在，已經非常不容易了。",
  ui_story_1018_10181501_52_dialog_content = "他們是真正的勇士，啟光會厚葬他們的。",
  ui_story_1018_10181501_53_dialog_content = "我在黃昏鎮沒有保護好他們……防線上要再次將他們當作敵人殺害……",
  ui_story_1018_10181501_54_dialog_content = "失敗……再一次……",
  ui_story_1018_10181501_55_dialog_content = "即使成了大元帥……我也是注定的失敗者。",
  ui_story_1018_10181501_56_dialog_content = "妳沒有失敗，雷霆，是妳帶領大家守住黃昏鎮，守住了防線。",
  ui_story_1018_10181501_57_dialog_content = "雨越來越大了，我們回去吧。",
  ui_story_1018_10181501_58_dialog_content = "……",
  ui_story_1018_10181501_59_dialog_content = "我們回去吧。之前聽廣播說今天天氣不好，現在地面上應該在下雨吧。",
  ui_story_1018_10181501_60_dialog_content = "<color=#e8d9bb>嘩啦——</color>",
  ui_story_1018_10181501_61_dialog_content = "呵呵……萊因哈特……",
  ui_story_1018_10181501_62_dialog_content = "妳在笑什麼？",
  ui_story_1018_10181501_63_dialog_content = "身為大元帥，難道就要隨時被這種無力感衝擊嗎……",
  ui_story_1018_10181501_64_dialog_content = "我一閉上眼，彷彿就能看到黃昏鎮上犧牲的戰士……",
  ui_story_1018_10181501_65_dialog_content = "他們為了防止自己變成暗鬼傷害同胞，朝自己腦袋開槍……",
  ui_story_1018_10181501_66_dialog_content = "阿克希亞的身體已經破碎過無數次，卻為了拯救部下，一次次站起來……",
  ui_story_1018_10181501_67_dialog_content = "以及剛剛那名，僅剩最後一點意識，也要堅持回到啟光……",
  ui_story_1018_10181501_68_dialog_content = "想要贏得戰爭，卻需要付出那麼大的代價……",
  ui_story_1018_10181501_69_dialog_content = "妳一定經歷過這些，經歷過無數次……",
  ui_story_1018_10181501_70_dialog_content = "但這麼多年來，妳擔任大元帥，我沒見過妳有一絲懊悔……",
  ui_story_1018_10181501_71_dialog_content = "甚至會為了保護阿克希亞，在戰場上認輸……",
  ui_story_1018_10181501_72_dialog_content = "會為了啟光的未來，被關進監獄裡任人宰割……",
  ui_story_1018_10181501_73_dialog_content = "……這些事，只有妳萊因哈特做得到。",
  ui_story_1018_10181501_74_dialog_content = "……",
  ui_story_1018_10181501_75_dialog_content = "大元帥是一個承諾，一種立場，一把保護傘……一個不能死，卻要不斷為他人追悼的人。",
  ui_story_1018_10181501_76_dialog_content = "大元帥正是用自己的血肉，撐起同胞的性命。",
  ui_story_1018_10181501_77_dialog_content = "悼念說只有我能做到……呵。但悼念也為了啟光的安危堅持到現在了。",
  ui_story_1018_10181501_78_dialog_content = "是嗎……",
  ui_story_1018_10181501_79_dialog_content = "<color=#e8d9bb>雨水洗刷著地上的泥濘，遠處雲層中透出些許微光。</color>",
  ui_story_1018_10181501_80_dialog_content = "<color=#e8d9bb>雷霆的肩膀瘦弱卻堅毅，站在光影中的輪廓愈發清晰、挺拔。</color>",
  ui_story_1018_10181501_81_dialog_content = "但我果然，不想再當什麼大元帥了……",
  ui_story_1018_10181501_82_dialog_content = "妳在危急時刻替我挑起大元帥的重擔，現在是我繼續承擔責任的時候了。",
  ui_story_1018_10181501_83_dialog_content = "接下來要面對的問題同樣棘手，但是相信我，我會為大家剷除內部敵人。",
  ui_story_1018_10181501_84_dialog_content = "妳打算怎麼應對委員會？",
  ui_story_1018_10181501_85_dialog_content = "大元帥，兵在我們手上，只要你一句話，我就會掀翻他們的老巢！",
  ui_story_1018_10181501_86_dialog_content = "我能來這裡和你們一起戰鬥，表示委員會默許我們的行動。",
  ui_story_1018_10181501_87_dialog_content = "他們那麼急著推行「啟明星計畫」，絕對不只是為了黃昏鎮。",
  ui_story_1018_10181501_88_dialog_content = "如今暗潮湧動，「守護者一號」的核心被盜，日蝕的行動才是最棘手的。",
  ui_story_1018_10181501_89_dialog_content = "如果回到迦南城，妳不會再讓他們關進牢裡去了吧？",
  ui_story_1018_10181501_90_dialog_content = "士兵會遭遇眼前的狀況，尤利西斯難逃審判。",
  ui_story_1018_10181501_91_dialog_content = "不管怎麼說，貝利撒留是個體面的人。我的事情，他們會給大家一個交代的。",
  ui_story_1018_10181501_92_dialog_content = "說到日蝕，大元帥，我們有兩支隊伍去了暗面。",
  ui_story_1018_10181501_93_dialog_content = "不知道委員會那邊有什麼打算，但卡戎和薇絲的隊伍，我認為需要我們的支援。",
  ui_story_1018_10181501_94_dialog_content = "確實……他們與我有過短暫的交流，目前的處境並不樂觀……",
  ui_story_1018_10181501_95_dialog_content = "PlayerName，你有什麼打算？",
  ui_story_1018_10181501_96_dialog_content = "黃昏鎮的難民還在空谷，我應該會先隨李奧他們回去安置難民。",
  ui_story_1018_10181501_97_dialog_content = "但是薇絲他們，我其實一直很擔心……",
  ui_story_1018_10181501_98_dialog_content = "我不會讓他們陷入危險的，PlayerName，我向你保證。",
  ui_story_1018_10181501_99_dialog_content = "無論委員會要如何解決後續問題，我會優先搜尋他們的下落。",
  ui_story_1018_10181501_100_dialog_content = "那黃昏鎮的後續問題就交給我，和李奧戰鬥了這麼久，我希望啟光能給黃昏鎮一個承諾。",
  ui_story_1018_10181501_101_dialog_content = "嗯，還有你的身體，記得盡快治療……",
  ui_story_1018_10181501_102_dialog_content = "知道了，實在沒辦法的話，我會聯繫你的。",
  ui_story_1018_10181501_103_dialog_content = "嗯……如果我能幫忙的話。",
  ui_story_1018_10181501_104_dialog_content = "<color=#e8d9bb>嗞——</color>",
  ui_story_1018_10181501_105_dialog_content = "鬧劇，喔不，喜劇。而我們的劇作家尤利西斯，甚至無顏出席今天的會議。",
  ui_story_1018_10181501_106_dialog_content = "妳打算如何收場？",
  ui_story_1018_10181501_107_dialog_content = "還沒到收場的時候。",
  ui_story_1018_10181501_108_dialog_content = "開什麼玩笑？兩位啟光大元帥帶兵在防線上打了勝仗。",
  ui_story_1018_10181501_109_dialog_content = "妳是指望他們低聲下氣來找妳和平談判嗎？",
  ui_story_1018_10181501_110_dialog_content = "萊因哈特能走出啟光監獄，妳覺得我會不知道？",
  ui_story_1018_10181501_111_dialog_content = "還不到關鍵證據出場的時候。今後如何發展，還要看他們的態度。",
  ui_story_1018_10181501_112_dialog_content = "不愧是貝利撒留，萬事都留後路。",
  ui_story_1018_10181501_113_dialog_content = "只不過防線上的戰事，整個艾斯特拉大陸都在看。",
  ui_story_1018_10181501_114_dialog_content = "沒錯，都在看，並且最好看得仔細一點。",
  ui_story_1018_10181501_115_dialog_content = "暗潮危機倘若真的來了，各個陣營到底能做到什麼程度？",
  ui_story_1018_10181501_116_dialog_content = "……妳支持尤利西斯的計畫，是在逼白夜城出手？",
  ui_story_1018_10181501_117_dialog_content = "這是一方面。",
  ui_story_1018_10181501_118_dialog_content = "無論是黃昏鎮還是防線，你們都看到了，我們在面對暗鬼時仍然有威懾力。",
  ui_story_1018_10181501_119_dialog_content = "而他們的其中一張底牌，如今也亮出來了。",
  ui_story_1018_10181501_120_dialog_content = "那個女孩？",
  ui_story_1018_10181501_121_dialog_content = "是的，但那肯定不是全部。",
  ui_story_1018_10181501_122_dialog_content = "沒想到，這才是你貝利撒留想看的「軍演」。",
  ui_story_1018_10181501_123_dialog_content = "別的不說，代價如此巨大，妳想過後果嗎？",
  ui_story_1018_10181501_124_dialog_content = "任何人有任何更好的方案，都可以拿到桌上來談。",
  ui_story_1018_10181501_125_dialog_content = "這次日蝕的武器仍然是吞羅的「種子」，起碼現階段我們也有了。",
  ui_story_1018_10181501_126_dialog_content = "這就是我支持尤利西斯的原因。",
  ui_story_1018_10181501_127_dialog_content = "在未來，任何有可能把我們毀滅的武器，我們都必須握在手裡。",
  ui_story_1018_10181501_128_dialog_content = "不論是白夜城的還是北境的，甚至是異端教團的。",
  ui_story_1018_10181501_129_dialog_content = "「守護者一號」的核心被盜，妳最擔心的竟然是各勢力之間的平衡？",
  ui_story_1018_10181501_130_dialog_content = "沒有優先順序，腹背受敵就是啟光目前的處境。",
  ui_story_1018_10181501_131_dialog_content = "當年從啟光出走的「工程師」，可不光是受到白夜城詬病。",
  ui_story_1018_10181501_132_dialog_content = "事已至此，我們不妨換個思路，直接讓大家看清「工程師」的面貌。",
  ui_story_1018_10181501_133_dialog_content = "妳有把握嗎？",
  ui_story_1018_10181501_134_dialog_content = "「暗面偵察隊」已經傳回情報，和預計的一樣。",
  ui_story_1018_10181501_135_dialog_content = "「守護者一號」的核心正是「工程師」復甦計畫的最後一塊拼圖。",
  ui_story_1018_10181501_136_dialog_content = "既然防線的戰事停了，「工程師」很快也該甦醒了。",
  ui_story_1018_10181501_137_dialog_content = "……",
  ui_story_1018_10181501_138_dialog_content = "「工程師」，迦南城建立以來真正意義上的第一任「城主」。",
  ui_story_1018_10181501_139_dialog_content = "如此古老的東西如果真的甦醒了，我倒有些期待。",
  ui_story_1018_10181501_140_dialog_content = "呵呵，我何嘗不是呢？",
  ui_story_1018_10181501_141_dialog_content = "嗞嗞……",
  ui_story_1018_10181501_142_dialog_content = "又來……",
  ui_story_1018_10181501_143_dialog_content = "不是……我……",
  ui_story_1018_10181501_144_dialog_content = "看來……工程……",
  ui_story_1018_10181501_145_dialog_content = "……已經醒了……",
  ui_story_1019_10190101_1_dialog_content = "<color=#e8d9bb>嗡嗡嗡——</color>",
  ui_story_1019_10190101_2_dialog_content = "果然，種子對能力的作用不是增強，而是轉換……",
  ui_story_1019_10190101_3_dialog_content = "所以就算複製了種子的核心通道，也會在泥潭中被暗能滲透……",
  ui_story_1019_10190101_4_dialog_content = "呵呵……妳到底，是怎麼想到的……",
  ui_story_1019_10190101_5_dialog_content = "咳、咳咳……咳、咳咳——",
  ui_story_1019_10190101_6_dialog_content = "應該是放在這附近才對啊……",
  ui_story_1019_10190101_7_dialog_content = "……但能得出這個結論，死在黃昏鎮的實驗體也值了。",
  ui_story_1019_10190101_8_dialog_content = "<color=#e8d9bb>叮啷——</color>",
  ui_story_1019_10190101_9_dialog_content = "最後三顆藥……",
  ui_story_1019_10190101_10_dialog_content = "科研四十載，籌備<color=#FFB400>特殊基因型號庫</color>近二十年……該做的我都做了。",
  ui_story_1019_10190101_11_dialog_content = "但我為什麼還是感到不甘心啊……",
  ui_story_1019_10190101_12_dialog_content = "<color=#FFB400>拉比</color>，我真是不甘心啊……",
  ui_story_1019_10190101_13_dialog_content = "<color=#e8d9bb>颯颯——颯颯——</color>",
  ui_story_1019_10190101_14_dialog_content = "好、好大的風……",
  ui_story_1019_10190101_15_dialog_content = "等等……我怎麼在雲層上？",
  ui_story_1019_10190101_16_dialog_content = "這熟悉的失重感……該不會又墜機了吧……！",
  ui_story_1019_10190101_17_dialog_content = "鎮定！鎮定！臨空者號會把我接住的。",
  ui_story_1019_10190101_18_dialog_content = "導航員，你在叫我嗎？",
  ui_story_1019_10190101_19_dialog_content = "你今天的飛行風格很像我最近翻江倒海的腸胃啊。我們現在要去哪？",
  ui_story_1019_10190101_20_dialog_content = "我們正在前往<color=#FFB400>高塔戰場</color>，去執行空投任務。",
  ui_story_1019_10190101_21_dialog_content = "……什麼任務？哪來的任務？",
  ui_story_1019_10190101_22_dialog_content = "馬上為導航員播放作戰指令：",
  ui_story_1019_10190101_23_dialog_content = "「請各位導航員前往高塔戰場，投放武器。」",
  ui_story_1019_10190101_24_dialog_content = "已下降至緩衝高度，請導航員下達指令，確保武器安全降落。",
  ui_story_1019_10190101_25_dialog_content = "停、停停——你在說什麼啊？！",
  ui_story_1019_10190101_26_dialog_content = "臨空者號？臨空者號——！",
  ui_story_1019_10190101_27_dialog_content = "啊啊啊——！！！",
  ui_story_1019_10190101_28_dialog_content = "吼吼吼吼吼吼吼吼吼！！！",
  ui_story_1019_10190101_29_dialog_content = "哪來的暗鬼啊！？我怎麼……和暗鬼一起下墜！",
  ui_story_1019_10190101_30_dialog_content = "臨空者號——這究竟是怎麼回事？！",
  ui_story_1019_10190101_31_dialog_content = "請導航員確保武器安全降落。這是你身為空裔一族的使命。",
  ui_story_1019_10190101_32_dialog_content = "吼吼吼吼吼吼吼吼吼！！！",
  ui_story_1019_10190101_33_dialog_content = "亂講……這、這一定是夢！",
  ui_story_1019_10190101_34_dialog_content = "導航員沒有在做夢。",
  ui_story_1019_10190101_35_dialog_content = "目前座標確認為高塔戰場，請確保武器安全降落。",
  ui_story_1019_10190101_36_dialog_content = "高塔……？這明明就是空之山谷啊！那座高高的回歸塔我認得出來！",
  ui_story_1019_10190101_37_dialog_content = "但地面上那些四處逃竄的……是空裔嗎？還是……",
  ui_story_1019_10190101_38_dialog_content = "夢，這一定是夢！或許摔到地面上就能醒過來……",
  ui_story_1019_10190101_39_dialog_content = "……不管了！",
  ui_story_1019_10190101_40_dialog_content = "……",
  ui_story_1019_10190101_41_dialog_content = "……還在半空……？",
  ui_story_1019_10190101_42_dialog_content = "一旦接受必然墜地的心態，下墜過程似乎變得無比漫長……",
  ui_story_1019_10190101_43_dialog_content = "<color=#e8d9bb>轟隆——！！！</color>",
  ui_story_1019_10190101_44_dialog_content = "啊———！",
  ui_story_1019_10190101_45_dialog_content = "……",
  ui_story_1019_10190101_46_dialog_content = "你醒了？",
  ui_story_1019_10190101_47_dialog_content = "白夜至上，我們平安抵達了。",
  ui_story_1019_10190101_48_dialog_content = "李奧……喬瑟琳？我、我們這是……",
  ui_story_1019_10190101_49_dialog_content = "我們回到空之山谷了。",
  ui_story_1019_10190101_50_dialog_content = "飛空艇搖晃得這麼厲害，戰士們都站不穩了，你這傢伙竟然睡得這麼死……",
  ui_story_1019_10190101_51_dialog_content = "空之山谷……",
  ui_story_1019_10190101_52_dialog_content = "沒錯……沒錯……是空谷……",
  ui_story_1019_10190101_53_dialog_content = "經過黃昏鎮和啟光防線的戰役後，我們乘著白夜城的飛空艇，返回空谷……",
  ui_story_1019_10190101_54_dialog_content = "原來、原來是一場夢啊，還好……真好！",
  ui_story_1019_10190101_55_dialog_content = "你這樣跑來跑去的，真的沒事嗎？",
  ui_story_1019_10190101_56_dialog_content = "沒事……太好了李奧！",
  ui_story_1019_10190101_57_dialog_content = "失重感那麼真實，真實到……像曾經發生過的事……",
  ui_story_1019_10190101_58_dialog_content = "是夢……還好是夢！",
  ui_story_1019_10190101_59_dialog_content = "……你也不用抱那麼緊……",
  ui_story_1019_10190101_60_dialog_content = "<color=#e8d9bb>吧唧——</color>",
  ui_story_1019_10190101_61_dialog_content = "PlayerName，我的鞋面雖然不乾淨，但你還是不要踩上去比較好。",
  ui_story_1019_10190101_62_dialog_content = "啊抱歉……不過我應該沒有踩到才對……",
  ui_story_1019_10190101_63_dialog_content = "丘丘……丘丘……",
  ui_story_1019_10190101_64_dialog_content = "這個白方塊是什麼東西……為何抱著我的靴子？",
  ui_story_1019_10190101_65_dialog_content = "這是我在空谷的夥伴，丘布。但怎麼一副醉醺醺的樣子……",
  ui_story_1019_10190101_66_dialog_content = "丘丘……嗝——",
  ui_story_1019_10190101_67_dialog_content = "喂——李奧團長！聖女大人！空裔小哥！",
  ui_story_1019_10190101_68_dialog_content = "終於等到你們回來了！",
  ui_story_1019_10190101_69_dialog_content = "男人們聽說你們把暗鬼趕出黃昏鎮，立刻就啟程回去了！",
  ui_story_1019_10190101_70_dialog_content = "我和酒坊的太太們自作主張準備了一些食物和果酒，犒勞各位戰士！",
  ui_story_1019_10190101_71_dialog_content = "果酒雖然發酵時間短，但用空谷的果子釀出來的酒，有一種很特別的口感。",
  ui_story_1019_10190101_72_dialog_content = "原來丘布是喝了果酒啊……",
  ui_story_1019_10190101_73_dialog_content = "空裔小哥，雷霆大元帥還好嗎？怎麼沒見到她？",
  ui_story_1019_10190101_74_dialog_content = "雷霆的身體暫時沒有大礙，但還是需要先回啟光治療。",
  ui_story_1019_10190101_75_dialog_content = "沒大礙就好！真希望能夠當面感謝各位保衛了黃昏鎮的戰士們。",
  ui_story_1019_10190101_76_dialog_content = "對了，空裔小哥，謝謝你收留我們！",
  ui_story_1019_10190101_77_dialog_content = "我們在這也沒什麼事好做，就餵餵魚，釀釀酒，替果樹除除雜草……",
  ui_story_1019_10190101_78_dialog_content = "我每天都有打掃房間喔！還在樹梢上掛了歡迎空裔哥哥和騎士哥哥凱旋的旗子……",
  ui_story_1019_10190101_79_dialog_content = "你們竟然做了這麼多事……",
  ui_story_1019_10190101_80_dialog_content = "請收下這些好意吧，就當作報答空谷收留我們！",
  ui_story_1019_10190101_81_dialog_content = "應該是我感謝你們才對！空谷從來沒有這麼熱鬧過……",
  ui_story_1019_10190101_82_dialog_content = "只要你們願意，可以一直在空谷生活下去……",
  ui_story_1019_10190101_83_dialog_content = "那黃昏鎮今後可就少了很多美酒了。",
  ui_story_1019_10190101_84_dialog_content = "白夜至上，PlayerName，謝謝你為黃昏鎮做的一切。",
  ui_story_1019_10190101_85_dialog_content = "丘丘！丘……嗝——呃——",
  ui_story_1019_10190101_86_dialog_content = "<color=#e8d9bb>乾杯——！！！</color>",
  ui_story_1019_10190101_87_dialog_content = "哈哈哈哈，想不到你去白夜城一路竟然這麼曲折。孤軍奮戰，辛苦了，軍師。",
  ui_story_1019_10190101_88_dialog_content = "比起黃昏鎮而言，那不算什麼。只要結果是好的，我做的一切就都值得。",
  ui_story_1019_10190101_89_dialog_content = "果然是我李奧看中的人。來，乾杯！",
  ui_story_1019_10190101_90_dialog_content = "……",
  ui_story_1019_10190101_91_dialog_content = "怎麼，就算是大戰之後，軍師也滴酒不沾？",
  ui_story_1019_10190101_92_dialog_content = "身體狀況使我無福消受。你們多喝一些吧。這樣的場景我多年沒見了。",
  ui_story_1019_10190101_93_dialog_content = "嗯，我又何嘗不是呢。",
  ui_story_1019_10190101_94_dialog_content = "但我瞭解大家。就算他們此時藉著酒意開懷大笑，心裡依然擔心著黃昏鎮。",
  ui_story_1019_10190101_95_dialog_content = "除了這些沒有煩惱的白方塊之外，大家都心事重重的樣子。",
  ui_story_1019_10190101_96_dialog_content = "所以我決定了，明天就啟程回去。",
  ui_story_1019_10190101_97_dialog_content = "戰士嘛，不聞著硝煙味反而睡得不踏實。喝完這些酒，是該準備迎接下一場戰爭了。",
  ui_story_1019_10190101_98_dialog_content = "<color=#e8d9bb>歡聲笑語一直持續到深夜……</color>",
  ui_story_1019_10190101_99_dialog_content = "<color=#e8d9bb>嗶——</color>",
  ui_story_1019_10190101_100_dialog_content = "噢，是你？空谷那邊還順利嗎？",
  ui_story_1019_10190101_101_dialog_content = "嗯，滿順利的……",
  ui_story_1019_10190101_102_dialog_content = "這麼晚聯絡我，你是想問薇絲的情況吧？",
  ui_story_1019_10190101_103_dialog_content = "嗯……薇絲她有消息了嗎？",
  ui_story_1019_10190101_104_dialog_content = "有消息。但是情況如何，我還沒辦法給你肯定的答覆。",
  ui_story_1019_10190101_105_dialog_content = "真的有消息？！",
  ui_story_1019_10190101_106_dialog_content = "卡戎帶領的追蹤小隊一直有傳回行進訊號，這在啟光偵查程序中是任務順利進行的意思。",
  ui_story_1019_10190101_107_dialog_content = "……但如果遇到特殊情況，比如在黃昏鎮——",
  ui_story_1019_10190101_108_dialog_content = "我已經知道了，所以我還在進一步查證。你放心，有消息我會聯絡你。",
  ui_story_1019_10190101_109_dialog_content = "那現在我能做些什麼嗎？黃昏鎮的戰爭我也有參加，或許可以幫上什麼忙。",
  ui_story_1019_10190101_110_dialog_content = "什麼都不用做，PlayerName。",
  ui_story_1019_10190101_111_dialog_content = "但是——",
  ui_story_1019_10190101_112_dialog_content = "你的好意我心領了，但現在不是來啟光的時候。",
  ui_story_1019_10190101_113_dialog_content = "自從「守護者一號」核心遭竊後，迦南城的城防出現一些問題，大家正在全力應對。",
  ui_story_1019_10190101_114_dialog_content = "你在黃昏鎮表現出的英勇和善意，對我們啟光已經是最大的幫助了。",
  ui_story_1019_10190101_115_dialog_content = "之後的事就交給我吧。時候不早了，早點休息。",
  ui_story_1019_10190101_116_dialog_content = "嗯……",
  ui_story_1019_10190101_117_dialog_content = "……",
  ui_story_1019_10190101_118_dialog_content = "PlayerName，你現在無法入睡，是在擔心薇絲的安危吧。",
  ui_story_1019_10190101_119_dialog_content = "是啊……",
  ui_story_1019_10190101_120_dialog_content = "<color=#e8d9bb>你靜靜地數了二十秒，記錄自己的心跳頻率。</color>",
  ui_story_1019_10190101_121_dialog_content = "臨空者號……",
  ui_story_1019_10190101_122_dialog_content = "臨空者號一直都在。",
  ui_story_1019_10190101_123_dialog_content = "二十秒雜念排除法好像真的有效，我回憶起開心的感覺了。",
  ui_story_1019_10190101_124_dialog_content = "……",
  ui_story_1019_10190101_125_dialog_content = "我調了PlayerName開心時的圖像資料。在你小時候，你開心時會倒立。",
  ui_story_1019_10190101_126_dialog_content = "倒立？！",
  ui_story_1019_10190101_127_dialog_content = "PlayerName還叫臨空者號無論如何都要倒立給你看。",
  ui_story_1019_10190101_128_dialog_content = "呃……現在不管是你還是我，倒立都很困難。",
  ui_story_1019_10190101_129_dialog_content = "經過計算，臨空者號倒立的成功率為五成九。若要執行，你必須找個安全的地方抓穩。",
  ui_story_1019_10190101_130_dialog_content = "啊？哈哈謝謝你，臨空者號。我覺得……現在這樣就好。",
  ui_story_1019_10190101_131_dialog_content = "像現在這樣看著控制台發呆、無憂無慮的時光，已經過去好久了啊……",
  ui_story_1019_10190101_132_dialog_content = "在我的意識模組損壞之後，你做了很多事情。",
  ui_story_1019_10190101_133_dialog_content = "是啊，你或許還不知道發生了什麼事吧？仔細想來……",
  ui_story_1019_10190101_134_dialog_content = "在你的意識模組損壞後，根據你的座標，我們在地下城找到一把鑰匙……",
  ui_story_1019_10190101_135_dialog_content = "跟隨著座標的指引，我們來到空之山谷。",
  ui_story_1019_10190101_136_dialog_content = "這是我第一次踏上故土，卻發現……故鄉早已沒了故人。",
  ui_story_1019_10190101_137_dialog_content = "喔，那一次甚至差點失去我們最好的朋友……",
  ui_story_1019_10190101_138_dialog_content = "後來，我看到空裔前輩和巨像一起離開大陸，並在很長一段時間後再次回歸。",
  ui_story_1019_10190101_139_dialog_content = "現在回想起來，仍然覺得那是一個過於漫長的夢。他們最後怎麼樣了呢……？",
  ui_story_1019_10190101_140_dialog_content = "接著，你為了救我，困在遠古戰場中……",
  ui_story_1019_10190101_141_dialog_content = "好在我們找到「領導者號」的意識資料，終於把你喚醒。",
  ui_story_1019_10190101_142_dialog_content = "……",
  ui_story_1019_10190101_143_dialog_content = "無論看多少次修復日誌，都不如聽PlayerName親口講述一遍。",
  ui_story_1019_10190101_144_dialog_content = "原來你都知道了啊……那我不是白講了？",
  ui_story_1019_10190101_145_dialog_content = "貢露科研長將這幾段經歷都詳細地記錄在臨空者號的修復日誌中。",
  ui_story_1019_10190101_146_dialog_content = "能不能告訴我，你代表空裔一族參與聯合軍演的那段經歷？",
  ui_story_1019_10190101_147_dialog_content = "喔，那一段啊……",
  ui_story_1019_10190201_1_dialog_content = "<color=#e8d9bb>幾天後，啟光醫療中心，淩晨</color>",
  ui_story_1019_10190201_2_dialog_content = "這些，全是我打倒的……",
  ui_story_1019_10190201_3_dialog_content = "對、對不起……錢德菈醫生，我還是控制不了自己……",
  ui_story_1019_10190201_4_dialog_content = "不用道歉啦，赫利俄斯上尉！",
  ui_story_1019_10190201_5_dialog_content = "適度的戰鬥訓練不僅可以發洩情緒，本身也是心理治療的一部分。",
  ui_story_1019_10190201_6_dialog_content = "真不知道我這樣子，還能為啟光做些什麼……",
  ui_story_1019_10190201_7_dialog_content = "請不要這麼想，赫利俄斯上尉。",
  ui_story_1019_10190201_8_dialog_content = "你之前回憶中提到的許多地方，尤其是暗面，對啟光是非常關鍵的情報。",
  ui_story_1019_10190201_9_dialog_content = "至於你一直想回憶起的人和事……",
  ui_story_1019_10190201_10_dialog_content = "因為在與他人相處的時候，我們的大腦通常會調動感官和情緒處理區域。",
  ui_story_1019_10190201_11_dialog_content = "等到你能控制住情緒，這部分功能也會逐漸恢復啦。",
  ui_story_1019_10190201_12_dialog_content = "原來是這樣……那我還得多加努力才行。",
  ui_story_1019_10190201_13_dialog_content = "喔，這些打壞的模型我會修好的……之後製作模型也讓我來幫忙吧。",
  ui_story_1019_10190201_14_dialog_content = "喔，另外！那麼晚將妳吵醒，真的很抱歉……",
  ui_story_1019_10190201_15_dialog_content = "不要緊，赫利俄斯上尉。這本來就是我的工作……呼——呵——",
  ui_story_1019_10190201_16_dialog_content = "嘿嘿，那麼今天就先到這吧。",
  ui_story_1019_10190201_17_dialog_content = "希望你能繼續把你想到、夢到的東西隨手記下來。",
  ui_story_1019_10190201_18_dialog_content = "雖然不知道大元帥要這些筆記做什麼，但可以看出這對她非常重要。",
  ui_story_1019_10190201_19_dialog_content = "可別小看那些突如其來的情緒和畫面。",
  ui_story_1019_10190201_20_dialog_content = "這些小小的火苗之下，通常是已經燃燒了很久的柴火堆。",
  ui_story_1019_10190201_21_dialog_content = "嗯，那個黑暗寒冷世界裡的點點滴滴，我永遠都不會忘。",
  ui_story_1019_10190201_22_dialog_content = "再次感謝妳，錢德菈醫生。",
  ui_story_1019_10190201_23_dialog_content = "<color=#e8d9bb>嗶——</color>",
  ui_story_1019_10190201_24_dialog_content = "嗯？是誰淩晨傳訊息給我……",
  ui_story_1019_10190201_25_dialog_content = "<color=#e8d9bb>颯——颯——颯——</color>",
  ui_story_1019_10190201_26_dialog_content = "（日蝕語）1011X？",
  ui_story_1019_10190201_27_dialog_content = "（日蝕語）是的，最後一個<color=#FFB400>驅動環</color>到手了。",
  ui_story_1019_10190201_28_dialog_content = "（日蝕語）01X11。",
  ui_story_1019_10190201_29_dialog_content = "（日蝕語）唸您尊名，盼您注視——",
  ui_story_1019_10190201_30_dialog_content = "（日蝕語）吾等，恭候您的降臨——",
  ui_story_1019_10190201_31_dialog_content = "<color=#e8d9bb>嗶——</color>",
  ui_story_1019_10190201_32_dialog_content = "這裡是……？",
  ui_story_1019_10190201_33_dialog_content = "這些黑影是誰……？",
  ui_story_1019_10190201_34_dialog_content = "不要注視！PlayerName！",
  ui_story_1019_10190201_35_dialog_content = "等等……是薇絲嗎？",
  ui_story_1019_10190201_36_dialog_content = "是妳！薇絲，真的是妳！",
  ui_story_1019_10190201_37_dialog_content = "回家吧。",
  ui_story_1019_10190201_38_dialog_content = "妳迷路了嗎？薇絲，那裡很危險嗎？",
  ui_story_1019_10190201_39_dialog_content = "快告訴我妳在哪裡，我會帶妳離開！",
  ui_story_1019_10190201_40_dialog_content = "回家吧。",
  ui_story_1019_10190201_41_dialog_content = "……",
  ui_story_1019_10190201_42_dialog_content = "回哪裡？薇絲？",
  ui_story_1019_10190201_43_dialog_content = "回家吧。",
  ui_story_1019_10190201_44_dialog_content = "家？這是哪裡……？",
  ui_story_1019_10190201_45_dialog_content = "回家吧。",
  ui_story_1019_10190201_46_dialog_content = "妳是誰？薇絲呢？",
  ui_story_1019_10190201_47_dialog_content = "<color=#e8d9bb>嗶——</color>",
  ui_story_1019_10190201_48_dialog_content = "PlayerName，這裡很危險！",
  ui_story_1019_10190201_49_dialog_content = "薇絲！妳到底在哪？！",
  ui_story_1019_10190201_50_dialog_content = "<color=#e8d9bb>嗶——嗶——嗶——</color>",
  ui_story_1019_10190201_51_dialog_content = "薇絲……薇絲！",
  ui_story_1019_10190201_52_dialog_content = "PlayerName，又做惡夢了嗎？",
  ui_story_1019_10190201_53_dialog_content = "夢……",
  ui_story_1019_10190201_54_dialog_content = "又是夢……",
  ui_story_1019_10190201_55_dialog_content = "臨空者號，我覺得不對勁……自從回空谷後，我總是夢到一些奇怪的畫面……",
  ui_story_1019_10190201_56_dialog_content = "但感覺更像是感應到些什麼……我也不知道怎麼形容。",
  ui_story_1019_10190201_57_dialog_content = "或許是PlayerName過於憂心導致的。你已經連續好幾晚在這裡等消息，該回房間休息了。",
  ui_story_1019_10190201_58_dialog_content = "現在幾點了？",
  ui_story_1019_10190201_59_dialog_content = "再過三個小時，就能看到太陽升起了。",
  ui_story_1019_10190201_60_dialog_content = "又一天過去了……",
  ui_story_1019_10190201_61_dialog_content = "這種什麼都做不了，只能等待的感覺真是糟糕……",
  ui_story_1019_10190201_62_dialog_content = "<color=#e8d9bb>嗶——</color>",
  ui_story_1019_10190201_63_dialog_content = "我記得這個聲音……你又在「領導者號」的資料裡檢索到舊的座標訊號了。",
  ui_story_1019_10190201_64_dialog_content = "你形容這些訊號是……「來自過去的回音」。",
  ui_story_1019_10190201_65_dialog_content = "沒錯。",
  ui_story_1019_10190201_66_dialog_content = "「領導者號」在沉寂之前一次又一次播放這些座標訊號，但都無法在這片大陸上找到對應的位置。",
  ui_story_1019_10190201_67_dialog_content = "是因為環境改變了嗎？",
  ui_story_1019_10190201_68_dialog_content = "也因為時間改變了。",
  ui_story_1019_10190201_69_dialog_content = "但是，你依然沒有停止檢索……",
  ui_story_1019_10190201_70_dialog_content = "如果能瀏覽所有資料，我就能讓意識恢復如初。",
  ui_story_1019_10190201_71_dialog_content = "其實，你已經是我認識的臨空者號了。",
  ui_story_1019_10190201_72_dialog_content = "我與PlayerName的意識契合度只有修復前的90%。",
  ui_story_1019_10190201_73_dialog_content = "真的嗎……但我感覺不出來有什麼差別。",
  ui_story_1019_10190201_74_dialog_content = "我會繼續學習的。",
  ui_story_1019_10190201_75_dialog_content = "我想問你一個問題……",
  ui_story_1019_10190201_76_dialog_content = "雖然萊因哈特要我別管啟光的事，但我還是很擔心。",
  ui_story_1019_10190201_77_dialog_content = "空谷越平靜我就越焦急，更加讓我覺得當時感受到的薇絲心跳……",
  ui_story_1019_10190201_78_dialog_content = "一定是她想告訴我什麼，但被我遺漏了……",
  ui_story_1019_10190201_79_dialog_content = "所以PlayerName想問我什麼？",
  ui_story_1019_10190201_80_dialog_content = "不，我想好了！就算萊因哈特一直不讓我去啟光，我——",
  ui_story_1019_10190201_81_dialog_content = "<color=#e8d9bb>嗶——</color>",
  ui_story_1019_10190201_82_dialog_content = "怎麼是她……",
  ui_story_1019_10190201_83_dialog_content = "是你期待的訊息嗎？",
  ui_story_1019_10190201_84_dialog_content = "是！你看！",
  ui_story_1019_10190201_85_dialog_content = "……",
  ui_story_1019_10190201_86_dialog_content = "「速來啟光」",
  ui_story_1019_10190201_87_dialog_content = "「速速速」",
  ui_story_1019_10190301_1_dialog_content = "<color=#e8d9bb>啟光整備場</color>",
  ui_story_1019_10190301_2_dialog_content = "糟糕……忘了問在哪碰面了。",
  ui_story_1019_10190301_3_dialog_content = "那個，士兵先生您好，請問——",
  ui_story_1019_10190301_4_dialog_content = "普通居民不得進入整備場，請立刻離開。",
  ui_story_1019_10190301_5_dialog_content = "喔，我不是普通居民，我是空——",
  ui_story_1019_10190301_6_dialog_content = "全體集合！",
  ui_story_1019_10190301_7_dialog_content = "是——！",
  ui_story_1019_10190301_8_dialog_content = "再次提醒，由於防禦系統漏洞，這裡並不安全！請立刻離開。",
  ui_story_1019_10190301_9_dialog_content = "防禦系統漏洞……",
  ui_story_1019_10190301_10_dialog_content = "這麼多巡邏士兵，看來城防問題還是沒有解決啊。",
  ui_story_1019_10190301_11_dialog_content = "哈！PlayerName看招——",
  ui_story_1019_10190301_12_dialog_content = "等、等一下……你是……",
  ui_story_1019_10190301_13_dialog_content = "不會吧？PlayerName竟然把我忘了？！",
  ui_story_1019_10190301_14_dialog_content = "喔，我想起來了，你是……",
  ui_story_1019_10190301_15_option_content = "綠毛",
  ui_story_1019_10190301_16_dialog_content = "不，我是想說，西恩！",
  ui_story_1019_10190301_17_dialog_content = "（怎麼一不小心把第一印象說出來了……）",
  ui_story_1019_10190301_18_dialog_content = "哈哈，是有些人會這麼稱呼我啦～",
  ui_story_1019_10190301_19_option_content = "鴉青",
  ui_story_1019_10190301_20_dialog_content = "欸等等……不是鴉青，是西恩！",
  ui_story_1019_10190301_21_dialog_content = "唔……跟鴉青比起來，我好像確實是隊伍裡最不起眼的。",
  ui_story_1019_10190301_22_option_content = "西恩",
  ui_story_1019_10190301_23_dialog_content = "沒錯沒錯，是西恩……",
  ui_story_1019_10190301_24_dialog_content = "抱歉！我只是感覺……你跟印象中不太一樣了。",
  ui_story_1019_10190301_25_dialog_content = "那當然，因為我每天都在練拳，每天都在變強！",
  ui_story_1019_10190301_26_dialog_content = "算了，就勉強算你通過吧～",
  ui_story_1019_10190301_27_dialog_content = "西恩，你怎麼在這？",
  ui_story_1019_10190301_28_dialog_content = "我定期回迦南城檢查身體呀，沒想到早點來還能見到你。",
  ui_story_1019_10190301_29_dialog_content = "早來為什麼不加入巡邏隊，幫忙巡查暗鬼呢？",
  ui_story_1019_10190301_30_dialog_content = "薇薇安長官好！因為我……",
  ui_story_1019_10190301_31_dialog_content = "我開玩笑的，快去做你的事吧，注意安全。",
  ui_story_1019_10190301_32_dialog_content = "知道了，長官！那麼回頭見了，PlayerName。",
  ui_story_1019_10190301_33_dialog_content = "回頭見，西恩。",
  ui_story_1019_10190301_34_dialog_content = "大元帥果然說中了，你遲遲等不到消息，一定會來啟光。",
  ui_story_1019_10190301_35_dialog_content = "她知道我會擅自來啟光，所以……",
  ui_story_1019_10190301_36_dialog_content = "當然。你和巨像在艾斯特拉的一舉一動，我們都瞭若指掌。",
  ui_story_1019_10190301_37_dialog_content = "但現在啟光的局勢複雜，管理層正忙於處理權力紛爭問題。",
  ui_story_1019_10190301_38_dialog_content = "你也看到了，城防問題依然很嚴峻。",
  ui_story_1019_10190301_39_dialog_content = "對了，現在啟光的大元帥是……",
  ui_story_1019_10190301_40_option_content = "萊因哈特？",
  ui_story_1019_10190301_41_dialog_content = "那還用說，她是啟光所有軍人的精神領袖，無人能及的大元帥。",
  ui_story_1019_10190301_42_option_content = "雷霆？",
  ui_story_1019_10190301_43_dialog_content = "雷霆雖然名義上是大元帥，但她也向委員會表達要將大元帥之位還給萊因哈特。",
  ui_story_1019_10190301_44_dialog_content = "但無論誰來當大元帥都有違委員會的立場，而軍隊又不能缺少統一的指揮……",
  ui_story_1019_10190301_45_dialog_content = "委員會便決定擱置大元帥「通敵」的調查，暫時由委員會和軍方共同負責啟光的事務。",
  ui_story_1019_10190301_46_dialog_content = "聽起來，管理工作變得複雜了啊。",
  ui_story_1019_10190301_47_dialog_content = "正是這樣，現在的啟光管理制度混亂，我甚至還常聯絡不上大元帥。",
  ui_story_1019_10190301_48_dialog_content = "難怪一直沒有她的消息……真是對不起，給你們添了這麼多麻煩！",
  ui_story_1019_10190301_49_dialog_content = "那……雷霆還想要和萊因哈特一決高下嗎？",
  ui_story_1019_10190301_50_dialog_content = "你說對了。雷霆明明不想爭大元帥之位，但還是堅持要跟她打一架。",
  ui_story_1019_10190301_51_dialog_content = "這一聽就像她會做的事……雷霆現在怎麼樣了？手術還順利嗎？",
  ui_story_1019_10190301_52_dialog_content = "我也很想知道……但由於現在管理太複雜，任何涉及「啟明星計畫」的工作都變得非常困難。",
  ui_story_1019_10190301_53_dialog_content = "所以如果你是來探望她的話，恐怕沒辦法了。",
  ui_story_1019_10190301_54_dialog_content = "其實我這次來啟光，是……",
  ui_story_1019_10190301_55_dialog_content = "嘎！！！",
  ui_story_1019_10190301_56_dialog_content = "參謀長！機械員說整備場西側的通風管道失靈，看來暗鬼是從那裡進來的！",
  ui_story_1019_10190301_57_dialog_content = "折騰了整整一夜，終於找到漏洞了！",
  ui_story_1019_10190301_58_dialog_content = "列隊！掩護焊工，隨我消滅暗鬼！",
  ui_story_1019_10190301_59_dialog_content = "是！！！",
  ui_story_1019_10190301_60_dialog_content = "啊——前面的，閃開！閃開！",
  ui_story_1019_10190301_61_dialog_content = "參謀長！您背後……暗鬼勒死人啦！！！",
  ui_story_1019_10190301_62_dialog_content = "那難道是……",
  ui_story_1019_10190301_63_dialog_content = "布布布布！",
  ui_story_1019_10190301_64_dialog_content = "當著這麼多人的面……",
  ui_story_1019_10190301_65_dialog_content = "布布布布！",
  ui_story_1019_10190301_66_dialog_content = "好、好好好，雖然還沒到運動時間……",
  ui_story_1019_10190301_67_dialog_content = "準備執行程式！",
  ui_story_1019_10190301_68_dialog_content = "布！",
  ui_story_1019_10190301_69_dialog_content = "……這位究竟是誰啊？",
  ui_story_1019_10190402_1_dialog_content = "上傳……上傳……呼——戶外運動的資料還是太少了。",
  ui_story_1019_10190402_2_dialog_content = "原來科學家戰鬥起來是這個樣子啊……",
  ui_story_1019_10190402_3_dialog_content = "喂喂喂，在你從科學家的刻板印象找出一堆偏頗的形容詞之前，我先提醒你……",
  ui_story_1019_10190402_4_dialog_content = "科學家可不全是沉悶無趣、弱不禁風的禿頭書呆子！",
  ui_story_1019_10190402_5_dialog_content = "不不不，我沒有那個意思……",
  ui_story_1019_10190402_6_dialog_content = "PlayerName，這位是……？",
  ui_story_1019_10190402_7_dialog_content = "她是啟光科學首席議會的科學家，阿爾戈爾。",
  ui_story_1019_10190402_8_dialog_content = "我來啟光正是因為她的邀請。不過……總覺得她現在的樣子跟上次見面不一樣了。",
  ui_story_1019_10190402_9_dialog_content = "科學首席議會……我還是第一次見到他們的真面目。",
  ui_story_1019_10190402_10_dialog_content = "搞——定——！",
  ui_story_1019_10190402_11_dialog_content = "嗨！空裔，以及……我有邀請妳嗎？",
  ui_story_1019_10190402_12_dialog_content = "阿爾戈爾教授，我是啟光參謀長薇薇安。",
  ui_story_1019_10190402_13_dialog_content = "嗯……既然都來了，跟我走吧。",
  ui_story_1019_10190402_14_dialog_content = "阿爾戈爾教授，我還是想跟您說明一下，是大元帥派我來協助PlayerName在啟光的行動。",
  ui_story_1019_10190402_15_dialog_content = "我必須事先瞭解你們的計畫，向大元帥回報。",
  ui_story_1019_10190402_16_dialog_content = "我們是臨時見面，不會事前預約，更不會寫上你們的行程表。如果妳一定要記下來，就用這個。",
  ui_story_1019_10190402_17_dialog_content = "您是指……",
  ui_story_1019_10190402_18_dialog_content = "腦袋。",
  ui_story_1019_10190402_19_dialog_content = "布！",
  ui_story_1019_10190402_20_dialog_content = "……",
  ui_story_1019_10190402_21_dialog_content = "但出於安全考量，我想問一下，剛才和您並肩作戰的……那不是普通的武器吧？",
  ui_story_1019_10190402_22_dialog_content = "當然不是普通的武器。它叫布林，是我的寵——",
  ui_story_1019_10190402_23_dialog_content = "布布！！",
  ui_story_1019_10190402_24_dialog_content = "啊好痛——夥伴、夥伴……別這樣嘛！",
  ui_story_1019_10190402_25_dialog_content = "真是的……嗯～舒服～再往上一點……",
  ui_story_1019_10190402_26_dialog_content = "布林還會按摩……？",
  ui_story_1019_10190402_27_dialog_content = "布林說你比上次見面時胖了一點。",
  ui_story_1019_10190402_28_dialog_content = "什麼……！它怎麼這樣說話啊？",
  ui_story_1019_10190402_29_dialog_content = "身為空裔，你應該知道交流不一定要靠開口。",
  ui_story_1019_10190402_30_dialog_content = "我和布林之間也有獨特的交流方式。",
  ui_story_1019_10190402_31_dialog_content = "像是布林現在就說……它很滿意我替它升級的戰鬥系統！",
  ui_story_1019_10190402_32_dialog_content = "布！",
  ui_story_1019_10190402_33_dialog_content = "哈哈哈，別客氣！",
  ui_story_1019_10190402_34_dialog_content = "（我怎麼覺得剛剛那個出場方式好像有點糟糕……）",
  ui_story_1019_10190402_35_dialog_content = "嗯？空裔在說什麼？",
  ui_story_1019_10190402_36_dialog_content = "布！",
  ui_story_1019_10190402_37_dialog_content = "的確……他那不屑的表情我也看得一清二楚。",
  ui_story_1019_10190402_38_dialog_content = "連心裡想的都被你們聽到了嗎……",
  ui_story_1019_10190402_39_dialog_content = "哈哈哈，別緊張，走吧。",
  ui_story_1019_10190402_40_dialog_content = "對了……阿爾戈爾教授，妳急著叫我來啟光，是有什麼重要的事嗎？",
  ui_story_1019_10190402_41_dialog_content = "你連要幹嘛都不知道就來了啊？",
  ui_story_1019_10190402_42_dialog_content = "這倒是符合我對空裔的刻板印象。",
  ui_story_1019_10190402_43_dialog_content = "還記得你為了恢復臨空者號，拷貝了「領導者號」的人格資料吧？",
  ui_story_1019_10190402_44_dialog_content = "這些資料裡的座標本來找不到對應的位置。",
  ui_story_1019_10190402_45_dialog_content = "但最近啟光更新了一部分永夜地區的地圖，有可能在其中找到「守護者一號」核心的線索。",
  ui_story_1019_10190402_46_dialog_content = "甚至追蹤小隊發現的未知座標，在這些資料中也可能有答案。",
  ui_story_1019_10190402_47_dialog_content = "真的嗎！那真是太好了！需要我做什麼嗎？",
  ui_story_1019_10190402_48_dialog_content = "這次需要的不是你的感應能力，而是臨空者號的學習能力。",
  ui_story_1019_10190402_49_dialog_content = "學習能力？",
  ui_story_1019_10190402_50_dialog_content = "對，臨空者號的意識能在那麼短的時間內恢復，足以證明它的學習能力非常出色。",
  ui_story_1019_10190402_51_dialog_content = "我想借鑑臨空者號的學習能力，提高繪製暗面地圖的效率，同時也為我的研究提供一些新思路。",
  ui_story_1019_10190402_52_dialog_content = "聽起來好厲害……如果能幫上忙就太好了。",
  ui_story_1019_10190402_53_dialog_content = "那就讓臨空者號連上我的<color=#FFB400>終端</color>吧，這需要花一些時間。",
  ui_story_1019_10190402_54_dialog_content = "至於等待的時間嘛……我看看……",
  ui_story_1019_10190402_55_dialog_content = "你的<color=#FFB400>終端</color>就是你手腕上的那個嗎？",
  ui_story_1019_10190402_56_dialog_content = "這是科技手環，當然，我比較喜歡叫他「運動手環」啦。",
  ui_story_1019_10190402_57_dialog_content = "啊，健身時間到了。你們要不要跟我一起運動一下？",
  ui_story_1019_10190402_58_dialog_content = "現在是淩晨……阿爾戈爾教授，您都在淩晨運動嗎？",
  ui_story_1019_10190402_59_dialog_content = "我的生理時鐘就是這樣……",
  ui_story_1019_10190402_60_dialog_content = "那這樣好了，剛才的戰鬥就當運動，待會直接開始工作吧！",
  ui_story_1019_10190402_61_dialog_content = "……",
  ui_story_1019_10190402_62_dialog_content = "管家、管家……開門，順便幫我準備三杯咖啡提神。",
  ui_story_1019_10190402_63_dialog_content = "一號拒絕，一號不是管家。",
  ui_story_1019_10190402_64_dialog_content = "……",
  ui_story_1019_10190402_65_dialog_content = "呃哈哈……可能、可能是剛起床的關係吧……",
  ui_story_1019_10190501_1_dialog_content = "<color=#e8d9bb>阿爾戈爾辦公室</color>",
  ui_story_1019_10190501_2_dialog_content = "歡迎來到我的實驗室——房間有點亂，自己找地方坐吧。",
  ui_story_1019_10190501_3_dialog_content = "啟光還有這樣的實驗室啊……",
  ui_story_1019_10190501_4_dialog_content = "盆景、健身器材，還有這些看起來很厲害的東西……",
  ui_story_1019_10190501_5_dialog_content = "這是床還是沙發啊？",
  ui_story_1019_10190501_6_dialog_content = "妳自己躺上去看看不就知道了嗎？按摩功能鍵就在旁邊。",
  ui_story_1019_10190501_7_dialog_content = "嗯……好舒服，睡意都上來了呢。",
  ui_story_1019_10190501_8_dialog_content = "這和啟光的風格也差太多了吧……",
  ui_story_1019_10190501_9_dialog_content = "是啊，這裡的佈置完全不符合《啟光生活住宅環境管理條例》……",
  ui_story_1019_10190501_10_dialog_content = "欸？這裡很多東西都是我用廢棄材料改造的。",
  ui_story_1019_10190501_11_dialog_content = "我把我生活和工作所需都集中在這間屋子裡了，這樣不是很節約資源嗎！",
  ui_story_1019_10190501_12_dialog_content = "而且參謀長在工作時間按摩，也違反了《啟光軍人條例》啊。",
  ui_story_1019_10190501_13_dialog_content = "我、我哪有按摩……",
  ui_story_1019_10190501_14_dialog_content = "剛剛不是還說睡意上來了嘛……",
  ui_story_1019_10190501_15_dialog_content = "你也別站著了，空裔。看到那邊的轉輪了嗎？",
  ui_story_1019_10190501_16_dialog_content = "只要站上去十分鐘，就能比你在巨像裡跑十圈減掉的肉還多。",
  ui_story_1019_10190501_17_dialog_content = "減肥的事還是以後再說吧……",
  ui_story_1019_10190501_18_dialog_content = "嗶嚕——",
  ui_story_1019_10190501_19_dialog_content = "好久不見，空裔！",
  ui_story_1019_10190501_20_dialog_content = "啊，一號！管家機器人原來是你。",
  ui_story_1019_10190501_21_dialog_content = "一號從來沒有答應要當阿爾戈爾的管家。",
  ui_story_1019_10190501_22_dialog_content = "……那你手裡端著的是什麼？",
  ui_story_1019_10190501_23_dialog_content = "是一號特地為兩位來賓準備的提神咖啡，阿爾戈爾的咖啡要自己弄。",
  ui_story_1019_10190501_24_dialog_content = "怎麼這樣……",
  ui_story_1019_10190501_25_dialog_content = "嗯——這裡面是加了奶油嗎？這種口味的咖啡我只在影鎮喝過呢。",
  ui_story_1019_10190501_26_dialog_content = "這是用特殊比例混合的調味油，應該符合參謀長的口味。",
  ui_story_1019_10190501_27_dialog_content = "我很喜歡。",
  ui_story_1019_10190501_28_dialog_content = "那我也喝喝看……",
  ui_story_1019_10190501_29_dialog_content = "嗯……我聞到一股青草的香氣，意外好喝耶！",
  ui_story_1019_10190501_30_dialog_content = "這是空谷的特調口味。",
  ui_story_1019_10190501_31_dialog_content = "阿爾戈爾最近開發了很多有趣的程式。一號可以根據你在啟光的飲食習慣調製特殊口味的咖啡。",
  ui_story_1019_10190501_32_dialog_content = "這麼說來，一號真的很像個管家呢。",
  ui_story_1019_10190501_33_dialog_content = "……",
  ui_story_1019_10190501_34_dialog_content = "布布！",
  ui_story_1019_10190501_35_dialog_content = "噢，環境建好了。那我就開始跑資料啦！",
  ui_story_1019_10190501_36_dialog_content = "輸入器、輸入器……嘶～在哪呢？",
  ui_story_1019_10190501_37_dialog_content = "啊呀……幫我撿一下，一號。",
  ui_story_1019_10190501_38_dialog_content = "……",
  ui_story_1019_10190501_39_dialog_content = "……還是我來吧。",
  ui_story_1019_10190501_40_dialog_content = "咦……背後怎麼畫著好多粉紅色的愛心啊？",
  ui_story_1019_10190501_41_dialog_content = "……「親愛的阿爾戈爾，可以教我數學嗎？」",
  ui_story_1019_10190501_42_dialog_content = "還有這張也是，「妳的智慧就像地下城的探照燈把我照亮」……",
  ui_story_1019_10190501_43_dialog_content = "落款還是「妳猜」……？",
  ui_story_1019_10190501_44_dialog_content = "喔，那些——都是以前收到的情書啦。",
  ui_story_1019_10190501_45_option_content = "……真肉麻",
  ui_story_1019_10190501_46_option_content = "……看不下去",
  ui_story_1019_10190501_47_dialog_content = "阿爾戈爾竟然拿人家送的情書當計算紙。",
  ui_story_1019_10190501_48_dialog_content = "手邊有現成的計算紙幹嘛不用……表示我一封都沒扔嘛。",
  ui_story_1019_10190501_49_dialog_content = "明明可以用工作板的……",
  ui_story_1019_10190501_50_dialog_content = "那麼大一塊工作板上……地圖……計算……計算……還是計算……",
  ui_story_1019_10190501_51_dialog_content = "這些便條紙上，有很多反映阿爾戈爾博士心情的塗改痕跡呀。",
  ui_story_1019_10190501_52_dialog_content = "妳也看出這上面烙印著我的痛苦了嗎？",
  ui_story_1019_10190501_53_dialog_content = "那是因為我始終無法解開「守護者」的謎團啊。",
  ui_story_1019_10190501_54_dialog_content = "「守護者」是指一號嗎？",
  ui_story_1019_10190501_55_dialog_content = "不是喔。",
  ui_story_1019_10190501_56_dialog_content = "「守護者一號」是負責整個啟光科技系統日常運作和計算的遠古人工智慧。",
  ui_story_1019_10190501_57_dialog_content = "它是一個龐大的電腦叢集。罪靈盜走了它的核心，對迦南城的影響你已經看到了。",
  ui_story_1019_10190501_X57_dialog_content = "這個叢集是以遠古科技「守護者」為基礎，逐漸發展起來的。",
  ui_story_1019_10190501_58_dialog_content = "可以說，「守護者」是「守護者一號」的原型機。",
  ui_story_1019_10190501_59_dialog_content = "一號是這個電腦叢集的一部分，有獨立處理資料的核心，也儲存了大量遠古資訊。",
  ui_story_1019_10190501_X59_dialog_content = "所以，理論上它們有相同的名字。但為了方便區分，你可以稱呼一號……郵筒。",
  ui_story_1019_10190501_60_dialog_content = "一號不是郵筒。",
  ui_story_1019_10190501_61_dialog_content = "嗶嚕嗶嚕嗶嚕。",
  ui_story_1019_10190501_62_dialog_content = "一號聽不懂阿爾戈爾在說什麼。",
  ui_story_1019_10190501_63_dialog_content = "看來你還得學習如何處理光靈間複雜的對話資訊。",
  ui_story_1019_10190501_64_dialog_content = "一號知道。",
  ui_story_1019_10190501_65_dialog_content = "（阿爾戈爾真的不是在敷衍一號嗎……）",
  ui_story_1019_10190501_66_dialog_content = "總之，我的工作就是繼續研究和學習「守護者」，並開發其他功能。",
  ui_story_1019_10190501_67_dialog_content = "那這部機器就是原型機嗎？",
  ui_story_1019_10190501_68_dialog_content = "這部是<color=#FFB400>虛擬機</color>，原型機在很久以前就因安全考量被封存了。",
  ui_story_1019_10190501_69_dialog_content = "也對……如果是遠古科技的話，應該破破爛爛的才對。",
  ui_story_1019_10190501_70_dialog_content = "那倒未必。我曾經接觸過原型機，那個外形只能說……透露著一股古老而高貴的氣息。",
  ui_story_1019_10190501_71_dialog_content = "近年來所有的週邊科技都有進步，唯獨「守護者」的研究一直沒有突破……",
  ui_story_1019_10190501_72_dialog_content = "要是在封存之前，我能多鑽研一會……",
  ui_story_1019_10190501_73_dialog_content = "一想到這，我就對自己恨得牙癢癢！",
  ui_story_1019_10190501_74_dialog_content = "布～",
  ui_story_1019_10190501_75_dialog_content = "居然！居然！連你都笑我……",
  ui_story_1019_10190501_76_dialog_content = "布林的反應……不是在笑吧？好像是反對妳說的話。",
  ui_story_1019_10190501_77_dialog_content = "布！",
  ui_story_1019_10190501_78_dialog_content = "這下好了！連空裔都比我聰明了！",
  ui_story_1019_10190501_79_dialog_content = "……",
  ui_story_1019_10190501_80_dialog_content = "說到誤解……",
  ui_story_1019_10190501_81_dialog_content = "既然你能感應一號的意識，或許也能試試看布林意識裡到底有些什麼？",
  ui_story_1019_10190501_82_dialog_content = "布布！！！",
  ui_story_1019_10190501_83_dialog_content = "想到什麼做什麼嗎……布林躲到妳身後了，看來它不是很願意。",
  ui_story_1019_10190501_84_dialog_content = "布……",
  ui_story_1019_10190501_85_dialog_content = "你沒看出來嗎？它在故作矜持。",
  ui_story_1019_10190501_86_dialog_content = "那……我試試看吧。",
  ui_story_1019_10190501_87_dialog_content = "布……",
  ui_story_1019_10190501_88_option_content = "開始感應",
  ui_story_1019_10190501_89_dialog_content = "（嗯？怎麼只有阿爾戈爾……是布林躲到阿爾戈爾身後去了嗎……）",
  ui_story_1019_10190501_90_dialog_content = "（難道我感應錯了？）",
  ui_story_1019_10190501_91_dialog_content = "（但是什麼場景都沒有……）",
  ui_story_1019_10190501_92_dialog_content = "（難道阿爾戈爾不是光靈，而是機器人？人工智慧！）",
  ui_story_1019_10190501_93_dialog_content = "（不可能……她剛才還用光能戰鬥，我在想什麼啊……）",
  ui_story_1019_10190501_94_dialog_content = "（或許是感應到的意識太淺層，我得找到更深入的場景……）",
  ui_story_1019_10190501_95_dialog_content = "（更深入的場景……）",
  ui_story_1019_10190501_96_dialog_content = "（更深……）",
  ui_story_1019_10190501_97_dialog_content = "（啊？剛剛那是……布林？）",
  ui_story_1019_10190501_98_dialog_content = "（我竟然可以在兩個感應對象間切換，這種感覺好奇妙，就像有了兩雙眼睛……）",
  ui_story_1019_10190501_99_dialog_content = "<color=#e8d9bb>布！！！啪——</color>",
  ui_story_1019_10190501_100_dialog_content = "——啊！",
  ui_story_1019_10190601_1_dialog_content = "沒想到布林對你也這麼貼心啊～",
  ui_story_1019_10190601_2_dialog_content = "心率、血壓……嗯，數據都很正常。你的氧合能力和肢體協調性還提升了呢。",
  ui_story_1019_10190601_3_dialog_content = "你把「一頓暴揍」當成鍛煉身體了嗎？！",
  ui_story_1019_10190601_4_dialog_content = "這哪算暴揍？你身上連個淤青都沒有……再說，這可是一種高級的溝通方式。",
  ui_story_1019_10190601_5_dialog_content = "布～",
  ui_story_1019_10190601_6_dialog_content = "這個語氣我記得！現在安慰是不是太晚了……",
  ui_story_1019_10190601_7_dialog_content = "阿爾戈爾博士，妳跟布林到底是怎麼溝通的？",
  ui_story_1019_10190601_8_dialog_content = "就是布林用不同力度的捶打向我傳達訊息。不過顯然它和空裔還不太契合。",
  ui_story_1019_10190601_9_dialog_content = "這種契合還是免了吧……",
  ui_story_1019_10190601_10_dialog_content = "可是布林之前對你一直都很友善啊，怎麼會這樣呢……",
  ui_story_1019_10190601_11_dialog_content = "嗯……我剛剛確實在布林的意識裡看到了些什麼……",
  ui_story_1019_10190601_12_dialog_content = "但是跟一號的意識不一樣，沒有確切的畫面。",
  ui_story_1019_10190601_13_dialog_content = "沒錯，布林的思維方式還是比較接近電腦。",
  ui_story_1019_10190601_14_dialog_content = "總之，還請原諒布林的脾氣啦，畢竟不打不相識嘛。",
  ui_story_1019_10190601_15_dialog_content = "……",
  ui_story_1019_10190601_16_dialog_content = "<color=#e8d9bb>嗶——嗶嗶——</color>",
  ui_story_1019_10190601_17_dialog_content = "啊，臨空者號的資料裡果然有一些座標訊號能顯示在新地圖上。",
  ui_story_1019_10190601_18_dialog_content = "那邊是我們從來沒去過的地方吧？",
  ui_story_1019_10190601_19_dialog_content = "咦？這是有好幾個座標的意思？",
  ui_story_1019_10190601_20_dialog_content = "可能來自同一個訊號源，只不過訊號有些波動而已。",
  ui_story_1019_10190601_21_dialog_content = "迦南城西北方，大概四千多公里的樣子……",
  ui_story_1019_10190601_22_dialog_content = "嗯……還算可以，沒有想像中那麼遠。",
  ui_story_1019_10190601_23_dialog_content = "不過這些訊號，要比回歸塔發出的訊號古老得多。",
  ui_story_1019_10190601_24_dialog_content = "這麼說，空之山谷並不是巨像初始的地方……？",
  ui_story_1019_10190601_25_dialog_content = "是的，空之山谷現在的位置，應該算是暗鬼入侵艾斯特拉大陸時建立的前沿基地。",
  ui_story_1019_10190601_26_dialog_content = "巨像的初始位置很可能在暗面。",
  ui_story_1019_10190601_27_dialog_content = "原來空之山谷不是臨空者號的故鄉……",
  ui_story_1019_10190601_28_dialog_content = "甚至，也不是空裔的故鄉……",
  ui_story_1019_10190601_29_dialog_content = "故鄉在哪並不重要，空裔。",
  ui_story_1019_10190601_30_dialog_content = "重要的是，臨空者號自誕生「家」的意識開始，就一直和空裔一起生活在空谷。",
  ui_story_1019_10190601_31_dialog_content = "從機械生物學的角度來講，如今的臨空者號應該算是你的「造物」才對。",
  ui_story_1019_10190601_32_dialog_content = "……",
  ui_story_1019_10190601_33_dialog_content = "別灰心，我們現在還只是猜測而已。",
  ui_story_1019_10190601_34_dialog_content = "等我們確定位置，我們會一起去尋找答案的。",
  ui_story_1019_10190601_35_dialog_content = "阿爾戈爾博士，我們要怎麼為暗面探索做準備呢？",
  ui_story_1019_10190601_36_dialog_content = "在赫利俄斯和暗面探索隊提供的情報幫助下，我們對暗面有了一些瞭解。",
  ui_story_1019_10190601_37_dialog_content = "有一位專家正在根據情報製作地圖，臨空者號提供的資料也支援著他的工作喔。",
  ui_story_1019_10190601_38_dialog_content = "我們去找他諮詢一下吧。這樣提得起興趣了吧？",
  ui_story_1019_10190601_39_dialog_content = "嗯。",
  ui_story_1019_10190601_40_dialog_content = "<color=#e8d9bb>叮——</color>",
  ui_story_1019_10190601_41_dialog_content = "嗯？科技園區有暗鬼出沒……巡邏隊由誰負責？",
  ui_story_1019_10190601_42_dialog_content = "這個時間點應該是巴頓吧。您怎麼知道科技園區有暗鬼？",
  ui_story_1019_10190601_43_dialog_content = "我的科技手環可以感測附近的危險源。是巴頓負責的話……那就沒問題了。",
  ui_story_1019_10190601_44_dialog_content = "科技園區是迦南城的重要基地，現在暗鬼闖進來，迦南城的安全怎麼辦……",
  ui_story_1019_10190601_45_dialog_content = "暗鬼出現在哪裡？我要馬上調查暗鬼的情況，安排人手。",
  ui_story_1019_10190601_46_dialog_content = "已經通知巴頓了。",
  ui_story_1019_10190601_47_dialog_content = "通報危險源、分析暗鬼、調度士兵、消滅暗鬼、修復漏洞……這些事情，科技手環都能搞定。",
  ui_story_1019_10190601_48_dialog_content = "可是——",
  ui_story_1019_10190601_49_dialog_content = "相信我，沒問題。妳不可能每件事都親力親為……這樣會累垮的。",
  ui_story_1019_10190601_50_dialog_content = "這是我的職責，我不覺得累。",
  ui_story_1019_10190601_51_dialog_content = "表情不錯，但布林說黑眼圈出賣妳囉。",
  ui_story_1019_10190601_52_dialog_content = "布！",
  ui_story_1019_10190601_53_dialog_content = "走吧，危險源就在我們會經過的地方。妳擔心的話，我們可以順道去看看。",
  ui_story_1019_10190601_54_dialog_content = "布！",
  ui_story_1019_10190702_1_dialog_content = "真沒想到，科技園區居然有暗鬼闖進來……",
  ui_story_1019_10190702_2_dialog_content = "那個真的是暗鬼嗎……怎麼看起來比較像啟光的士兵？",
  ui_story_1019_10190702_3_dialog_content = "去問問巴頓吧，他那邊應該已經處理好暗鬼了。",
  ui_story_1019_10190702_4_dialog_content = "你這小子怎麼跑來這了？大元帥不是叫你好好待在空谷嗎？",
  ui_story_1019_10190702_5_dialog_content = "這個，說來話長……",
  ui_story_1019_10190702_6_dialog_content = "是我叫空裔來的。",
  ui_story_1019_10190702_7_dialog_content = "妳就是傳訊給我的科學家，阿爾戈爾對吧？",
  ui_story_1019_10190702_8_dialog_content = "沒錯。暗鬼不會是從外面潛入的吧？",
  ui_story_1019_10190702_9_dialog_content = "暗鬼的事情……你們科學家還是別多管閒事比較好。",
  ui_story_1019_10190702_10_dialog_content = "黃昏鎮的事妳也知道，尤利西斯的陰謀就算沒有成功，也讓我們軍官吃了不少苦頭。",
  ui_story_1019_10190702_11_dialog_content = "別把我跟其他科學家混為一談，我對光靈的事情沒興趣。",
  ui_story_1019_10190702_12_dialog_content = "巴頓，阿爾戈爾教授是好心，你先告訴我們暗鬼的情況吧。",
  ui_story_1019_10190702_13_dialog_content = "……",
  ui_story_1019_10190702_14_dialog_content = "唉，說來也奇怪！我到達危險位置的時候並沒有發現暗鬼，只看見兩個經過實驗大樓的士兵……",
  ui_story_1019_10190702_15_dialog_content = "誰知道一走近，他們像發了瘋一樣朝我撲來！",
  ui_story_1019_10190702_16_dialog_content = "我們也遇到同樣的情況。",
  ui_story_1019_10190702_17_dialog_content = "仔細看起來，是有點像「啟明星計畫」的士兵。小子，你覺得呢？",
  ui_story_1019_10190702_18_dialog_content = "我剛才指揮你們作戰的時候，就感覺到他們身上的暗能很不尋常……",
  ui_story_1019_10190702_19_dialog_content = "如果是暗鬼的話，可能是防禦系統出了問題，讓實驗暗鬼從倉庫裡逃出來。",
  ui_story_1019_10190702_20_dialog_content = "有可能。啟光科技園區裡不只有醫學中心、黑傘實驗室……",
  ui_story_1019_10190702_21_dialog_content = "還有那個在光靈身上動刀的科學家！",
  ui_story_1019_10190702_22_dialog_content = "布……",
  ui_story_1019_10190702_23_dialog_content = "你為什麼不直接去問尤利西斯？",
  ui_story_1019_10190702_24_dialog_content = "妳以為我不想問嗎？",
  ui_story_1019_10190702_25_dialog_content = "「啟明星計畫」調查案拖了這麼久，委員會對尤利西斯改造士兵的態度也一直含糊不清！",
  ui_story_1019_10190702_26_dialog_content = "依我看，繼續拖下去迦南城只會更危險！",
  ui_story_1019_10190702_27_dialog_content = "尤利西斯奪走那麼多士兵的生命，啟光為什麼沒有起訴他呢？",
  ui_story_1019_10190702_28_dialog_content = "這個我來解釋吧。",
  ui_story_1019_10190702_29_dialog_content = "正是考量到士兵的安全，尤利西斯還有義務協助傷患的後續治療。",
  ui_story_1019_10190702_30_dialog_content = "何況和案件有關的資料都在他的實驗大樓裡，審查團還在持續調資料查證。",
  ui_story_1019_10190702_31_dialog_content = "雖然有人一直在監視尤利西斯，但他現在還是相對自由。",
  ui_story_1019_10190702_32_dialog_content = "所以除非有特殊情況，否則我們不能隨便進入他的實驗室。",
  ui_story_1019_10190702_33_dialog_content = "有了這些暗鬼的證據，你們可以用「檢查防禦漏洞」當藉口去問尤利西斯。",
  ui_story_1019_10190702_34_dialog_content = "布！",
  ui_story_1019_10190702_35_dialog_content = "這招我試過了，沒用。",
  ui_story_1019_10190702_36_dialog_content = "那就跟我來吧。我有進入他實驗室的權限，就說你們是來協助我的。",
  ui_story_1019_10190702_37_dialog_content = "至少以我的推斷，暗鬼不可能從外面滲透到迦南城最底層。",
  ui_story_1019_10190702_38_dialog_content = "我也不希望「守護者一號」核心遭竊後，啟光科技園區成為暗鬼的巢穴。",
  ui_story_1019_10190702_39_dialog_content = "這也是個辦法。巴頓，你覺得呢？",
  ui_story_1019_10190702_40_dialog_content = "那就試試看吧……",
  ui_story_1019_10190702_41_dialog_content = "走吧。不過要小心，如果暗鬼真的是從倉庫裡逃出來的，那一定不只這幾隻。",
  ui_story_1019_10190802_1_dialog_content = "布布！！！",
  ui_story_1019_10190802_2_dialog_content = "別急，別急，我在把資料傳輸給你了……",
  ui_story_1019_10190802_3_dialog_content = "果然。巡邏士兵回報說，其他實驗大樓裡都沒有發現暗鬼。看來我們找對地方了。",
  ui_story_1019_10190802_4_dialog_content = "這些暗鬼，難道是尤利西斯故意放出來的嗎？",
  ui_story_1019_10190802_5_dialog_content = "我不信他有這個膽量。他再傻也不會想跟整個啟光同歸於盡。",
  ui_story_1019_10190802_6_dialog_content = "咳咳……這算是誇我嗎？",
  ui_story_1019_10190802_7_dialog_content = "尤利西斯，你知道你的實驗室裡有暗鬼嗎？",
  ui_story_1019_10190802_8_dialog_content = "這裡是實驗大樓，為了研究光靈和暗鬼，實驗用的暗鬼一直都不少。",
  ui_story_1019_10190802_9_dialog_content = "這不是什麼祕密，但也不關你們的事。",
  ui_story_1019_10190802_10_dialog_content = "可是自從核心遭竊後，實驗大樓的倉庫閥門就出現很多漏洞。這些暗鬼，恐怕就是從那裡逃出來的。",
  ui_story_1019_10190802_11_dialog_content = "<color=#e8d9bb>哐噹——</color>",
  ui_story_1019_10190802_12_dialog_content = "這些可不是實驗用暗鬼。現在已經明令禁止你繼續進行改造光靈的實驗了。",
  ui_story_1019_10190802_13_dialog_content = "況且，無論是改造士兵，還是實驗暗鬼……",
  ui_story_1019_10190802_14_dialog_content = "只要從你實驗大樓裡跑出來威脅到他人生命安全的東西，我們都有權過問。",
  ui_story_1019_10190802_15_dialog_content = "明令禁止？呵呵……",
  ui_story_1019_10190802_16_dialog_content = "但是又有誰授權你們進入我的實驗大樓，處理這些實驗用暗鬼嗎？",
  ui_story_1019_10190802_17_dialog_content = "委員會怎麼說不重要，我們的責任是消滅所有暗鬼！",
  ui_story_1019_10190802_18_dialog_content = "不是大聲就贏喔。但是能幫我找到這些實驗體，也算有點能耐。",
  ui_story_1019_10190802_19_dialog_content = "你！",
  ui_story_1019_10190802_20_dialog_content = "只是檢查一下布林系統，這裡怎麼就吵起來了……",
  ui_story_1019_10190802_21_dialog_content = "尤利西斯，這幾位是我請來協助工作的，跟你沒關係。",
  ui_story_1019_10190802_22_dialog_content = "慢著……",
  ui_story_1019_10190802_23_dialog_content = "長官，委員會的人聯絡您了……",
  ui_story_1019_10190802_24_dialog_content = "他們希望您準時參加最終審查會。",
  ui_story_1019_10190802_25_dialog_content = "……我知道了。",
  ui_story_1019_10190802_26_dialog_content = "（尤利西斯在看我……）",
  ui_story_1019_10190802_27_dialog_content = "好久不見，空裔。",
  ui_story_1019_10190802_28_dialog_content = "上一次在會議室，是萊因哈特陪你一起去。阿爾戈爾當時也在。",
  ui_story_1019_10190802_29_dialog_content = "……那場乏味無趣、裝腔作勢的會議，想來還真是浪費時間。",
  ui_story_1019_10190802_30_dialog_content = "過去好久了，世界又發生了一些變化。如果是空裔的話，這些都逃不過你的眼睛，對吧？",
  ui_story_1019_10190802_31_dialog_content = "你到底想說什麼……？",
  ui_story_1019_10190802_32_dialog_content = "很久以前，我就能……看到一些特殊的畫面，而近年來更是頻繁出現。",
  ui_story_1019_10190802_33_dialog_content = "那些場景是如此真實，彷彿牽動著我的身體……我的心跳……",
  ui_story_1019_10190802_34_dialog_content = "布布！布布！布布！",
  ui_story_1019_10190802_35_dialog_content = "嗯？什麼……？",
  ui_story_1019_10190802_36_dialog_content = "心跳？",
  ui_story_1019_10190802_37_dialog_content = "呵呵，我們都是能窺見真實的人，但偏偏有人想把我和這些真相隔絕……",
  ui_story_1019_10190802_38_dialog_content = "並剝奪讓你一探生命奧祕的機會……這對你來說真是太可惜了。",
  ui_story_1019_10190802_39_dialog_content = "咳咳……審查會之後，還有誰能對抗暗鬼呢？",
  ui_story_1019_10190802_40_dialog_content = "在那嘰嘰喳喳說什麼？我巴頓還沒遇過戰勝不了的敵人。",
  ui_story_1019_10190802_41_dialog_content = "我看你是想拉攏PlayerName，為你的罪行開脫吧？",
  ui_story_1019_10190802_42_dialog_content = "言重了。我只是在問艾斯特拉的空之末裔，你難道沒有這樣的好奇心嗎？",
  ui_story_1019_10190802_43_dialog_content = "如果你抓緊時間，興許可以在我這裡見識到真相……",
  ui_story_1019_10190802_44_dialog_content = "布布！布布！布布！",
  ui_story_1019_10190802_45_dialog_content = "哎……等一下，我有點搞不清楚了——",
  ui_story_1019_10190802_46_dialog_content = "布林怎麼了？",
  ui_story_1019_10190802_47_dialog_content = "有問題，它從來沒有出現過這樣的反應……",
  ui_story_1019_10190802_48_dialog_content = "呵呵，誰又能說，這種「問題」不是一種幸運呢？",
  ui_story_1019_10190802_49_dialog_content = "「幸運」？",
  ui_story_1019_10190802_50_dialog_content = "當厄運來敲門的時候，有人替你守夜，這就是一種幸運。",
  ui_story_1019_10190802_51_dialog_content = "不過現在看來，一切都還不確定……",
  ui_story_1019_10190802_52_dialog_content = "你有空在那裝神弄鬼，不如去醫院檢查一下腦袋哪裡有洞。",
  ui_story_1019_10190802_53_dialog_content = "呵呵，年輕真好啊。",
  ui_story_1019_10190802_54_dialog_content = "怎麼樣，PlayerName？你有想要發掘的真相嗎？",
  ui_story_1019_10190802_55_dialog_content = "（難道他知道……）",
  ui_story_1019_10190802_56_option_content = "（那些夢境的真相？）",
  ui_story_1019_10190802_57_option_content = "（薇絲心跳的真相？）",
  ui_story_1019_10190802_58_dialog_content = "（但他怎麼知道的……）",
  ui_story_1019_10190802_59_dialog_content = "（還是像薇薇安說的，他只是想利用我，為自己開脫？）",
  ui_story_1019_10190802_60_dialog_content = "看你猶豫的樣子，果然有疑問對吧？",
  ui_story_1019_10190802_61_dialog_content = "只要你來我實驗室，幫助我完成一個小小的「實驗」，你就會知道答案。",
  ui_story_1019_10190802_62_dialog_content = "甚至還能看到……你的極限。",
  ui_story_1019_10190802_63_dialog_content = "尤利西斯，大元帥已經明確說過了，禁止一切實驗！",
  ui_story_1019_10190802_64_dialog_content = "別說實驗了，你要是敢動PlayerName一根汗毛，我會立刻宰了你。",
  ui_story_1019_10190802_65_dialog_content = "兩位誤會了，我才是那個要躺下來讓PlayerName做「實驗」的人。",
  ui_story_1019_10190802_66_dialog_content = "畢竟，任何基於好奇心提出的假設，都需要靠實驗來驗證，不是嗎？",
  ui_story_1019_10190802_67_dialog_content = "你想做什麼實驗？",
  ui_story_1019_10190802_68_dialog_content = "我想讓你用你空裔的感應能力，看看我夢到的一些奇異的畫面……看看裡面是否有你想要的答案。",
  ui_story_1019_10190802_69_dialog_content = "奇怪的夢境！？",
  ui_story_1019_10190802_70_dialog_content = "布布！布布！布布！",
  ui_story_1019_10190802_71_dialog_content = "這是怎麼回事……？空裔，我們快走吧。",
  ui_story_1019_10190802_72_dialog_content = "可是我想留下來……",
  ui_story_1019_10190802_73_dialog_content = "PlayerName？！",
  ui_story_1019_10190802_74_dialog_content = "我想參加這個實驗。",
  ui_story_1019_10190802_75_dialog_content = "布布！布布！布布！",
  ui_story_1019_10190802_76_dialog_content = "等、等等——別、別拉呀……",
  ui_story_1019_10190802_77_dialog_content = "對不起，我得先處理一下布林的問題。",
  ui_story_1019_10190802_78_dialog_content = "放心，雖然不是我的任務，但我會看好他的。",
  ui_story_1019_10190802_79_dialog_content = "確保PlayerName的安全就是我的職責。",
  ui_story_1019_10190802_80_dialog_content = "我的實驗室很安全。進來吧。",
  ui_story_1019_10190901_1_dialog_content = "空裔，你準備好了嗎？在你開始之前，我想問你一個問題。",
  ui_story_1019_10190901_2_dialog_content = "在你眼中，世界的盡頭在哪裡？",
  ui_story_1019_10190901_3_dialog_content = "倘若暗潮危機再次來臨，光靈如何才能抵抗黑暗的侵蝕？",
  ui_story_1019_10190901_4_dialog_content = "這個……我沒想過。",
  ui_story_1019_10190901_5_dialog_content = "空裔一族曾創下飛離艾斯特拉大陸的壯舉，難道你不想探索那片未知的天空嗎？",
  ui_story_1019_10190901_6_dialog_content = "那是遠古空裔和巨像締造的奇蹟，與現在相隔太久了。",
  ui_story_1019_10190901_7_dialog_content = "我只是個普通人，我去過最遠的地方也只是艾斯特拉大陸附近的東方大陸。",
  ui_story_1019_10190901_8_dialog_content = "呵呵，人們總是用恐懼來限制自己的想像。",
  ui_story_1019_10190901_9_dialog_content = "你為什麼要這樣說？",
  ui_story_1019_10190901_10_dialog_content = "你很快就會明白。現在，讓我們開始吧。",
  ui_story_1019_10190901_11_dialog_content = "……",
  ui_story_1019_10190901_12_option_content = "開始感應",
  ui_story_1019_10190901_13_dialog_content = "這是……北境？",
  ui_story_1019_10190901_14_dialog_content = "好多冰石柱……像利刃一樣刺向天空。",
  ui_story_1019_10190901_15_dialog_content = "不，這種昏暗的感覺，比較像暗面……",
  ui_story_1019_10190901_16_dialog_content = "我曾經探索過極光遺跡，那裡也有一些黑色的岩石，散發著陰冷的氣息。",
  ui_story_1019_10190901_17_dialog_content = "但是那些岩石都是沉甸甸地壓在地上，而這裡的冰石柱卻是輕盈地浮在空中。",
  ui_story_1019_10190901_18_dialog_content = "甚至有些發光的冰石柱，不斷往上生長……",
  ui_story_1019_10190901_19_dialog_content = "這是尤利西斯的記憶嗎？他為什麼會來到這樣的地方？",
  ui_story_1019_10190901_20_dialog_content = "尤利西斯的意識裡，怎麼會有這樣的記憶？",
  ui_story_1019_10190901_21_dialog_content = "這裡彷彿是被遺忘的世界，沒有任何生命的氣息……",
  ui_story_1019_10190901_22_dialog_content = "<color=#e8d9bb>嘩啦——</color>",
  ui_story_1019_10190901_23_dialog_content = "怎麼了……？！",
  ui_story_1019_10190901_24_dialog_content = "冰石柱開始變化了！像是被某種力量牽引著往高空匯集……？",
  ui_story_1019_10190901_25_dialog_content = "難道……那些冰石柱正在組合成某種東西？",
  ui_story_1019_10190901_26_dialog_content = "這到底是哪裡——",
  ui_story_1019_10190901_27_dialog_content = "<color=#e8d9bb>轟隆——</color>",
  ui_story_1019_10190901_28_dialog_content = "呼……",
  ui_story_1019_10190901_29_dialog_content = "怎麼樣，空裔，感覺如何？",
  ui_story_1019_10190901_30_dialog_content = "小子，他到底給你看了什麼？",
  ui_story_1019_10190901_31_option_content = "那是什麼地方？",
  ui_story_1019_10190901_32_dialog_content = "什麼地方……",
  ui_story_1019_10190901_33_option_content = "為什麼給我看這些？",
  ui_story_1019_10190901_34_dialog_content = "因為……",
  ui_story_1019_10190901_35_dialog_content = "那裡是世界的盡頭。",
  ui_story_1019_10190901_36_dialog_content = "正是在那裡，暗鬼潛伏，試圖喚醒惡魔……",
  ui_story_1019_10190901_37_dialog_content = "惡魔……？",
  ui_story_1019_10190901_38_dialog_content = "（難道是此前在遠古戰場中聽說的那個東西……）",
  ui_story_1019_10190901_39_dialog_content = "但我沒有看到任何暗鬼，只有無數的冰石柱……",
  ui_story_1019_10190901_40_dialog_content = "呵呵，那是因為牠們已經開始了。",
  ui_story_1019_10190901_41_dialog_content = "開始了……？",
  ui_story_1019_10190901_42_dialog_content = "喚醒惡魔！",
  ui_story_1019_10190901_43_dialog_content = "……",
  ui_story_1019_10190901_44_dialog_content = "尤利西斯，你這個瘋子！給我離PlayerName遠一點。",
  ui_story_1019_10190901_45_dialog_content = "參謀長，巴頓軍團長和PlayerName也在……",
  ui_story_1019_10190901_46_dialog_content = "阿納托利，你來得正好。",
  ui_story_1019_10190901_47_dialog_content = "是委員會派你來的吧……",
  ui_story_1019_10190901_48_dialog_content = "是的，尤利西斯博士。是有關「啟明星計畫」的調查會，之前與您聯絡過。",
  ui_story_1019_10190901_49_dialog_content = "我會出席，不過……",
  ui_story_1019_10190901_50_dialog_content = "既然委員會認為空裔是拯救光靈的英雄，我希望他也能參加。",
  ui_story_1019_10190901_51_dialog_content = "尤利西斯博士，這恐怕不符合規定。",
  ui_story_1019_10190901_52_dialog_content = "空裔隨便進出迦南城又是符合哪一條規定？",
  ui_story_1019_10190901_53_dialog_content = "空裔，考慮一下我的提議。我知道你有想揭開的謎團。",
  ui_story_1019_10190901_54_dialog_content = "或許整個啟光，只有我能告訴你真相。",
  ui_story_1019_10190901_55_dialog_content = "……",
  ui_story_1019_10190901_56_dialog_content = "你知道現在什麼對你最重要嗎？是在惡魔到來之前，做好活下去的準備！",
  ui_story_1019_10190901_57_dialog_content = "……",
  ui_story_1019_10190901_58_dialog_content = "阿納托利，把尤利西斯帶走吧。",
  ui_story_1019_10190901_59_dialog_content = "空裔？",
  ui_story_1019_10190901_60_dialog_content = "……",
  ui_story_1019_10190901_61_dialog_content = "哈哈哈哈……拯救光靈的怎麼可能是你啊！咳、咳咳咳……",
  ui_story_1019_10190901_62_dialog_content = "躊躇……軟弱……毫無志向！你、咳咳、咳咳咳……",
  ui_story_1019_10190901_63_dialog_content = "長官，抱歉來遲了。讓我扶您吧。",
  ui_story_1019_10190901_64_dialog_content = "不用！",
  ui_story_1019_10190901_65_dialog_content = "呵……",
  ui_story_1019_10190901_66_dialog_content = "（暗能？等等……不太像……）",
  ui_story_1019_10190901_67_dialog_content = "我，不會放棄的……你們都會後悔！咳咳、咳咳……",
  ui_story_1019_10190901_68_dialog_content = "博士……您站不太穩，真的沒事嗎？",
  ui_story_1019_10190901_69_dialog_content = "我說，別碰我！",
  ui_story_1019_10190901_70_dialog_content = "喝啊！！！",
  ui_story_1019_10190901_71_dialog_content = "微光，潛於暗影。",
  ui_story_1019_10190901_72_dialog_content = "和剛剛一樣疑似暗鬼的敵人……",
  ui_story_1019_10190901_73_dialog_content = "牠不是你們的敵人……",
  ui_story_1019_10190901_74_dialog_content = "那是什麼？！",
  ui_story_1019_10190901_75_dialog_content = "解釋的話留著去審查會說吧。PlayerName，指揮我們消滅牠！",
  ui_story_1019_10190901_76_dialog_content = "好！",
  ui_story_1019_10190902_1_dialog_content = "巴頓，把刀放下！",
  ui_story_1019_10190902_2_dialog_content = "我已經通知大元帥了，接管人員馬上就到。她要我們先去巡查實驗室。",
  ui_story_1019_10190902_3_dialog_content = "妳還想放那瘋子生路？那東西攻擊我們，卻沒有攻擊尤利西斯！",
  ui_story_1019_10190902_4_dialog_content = "他要是放出實驗大樓裡的暗鬼，啟光就完蛋了！",
  ui_story_1019_10190902_5_dialog_content = "巴頓，現在尤利西斯的事由阿納托利負責。大元帥說她會查明真相。",
  ui_story_1019_10190902_6_dialog_content = "啊，好多人啊～我錯過什麼了嗎？",
  ui_story_1019_10190902_7_dialog_content = "年輕人也在啊。看來戰場的洗禮讓你們成熟了不少，連味道……都變了呢。",
  ui_story_1019_10190902_8_dialog_content = "……",
  ui_story_1019_10190902_9_dialog_content = "就算兩位阻攔，尤利西斯博士也得跟我走。",
  ui_story_1019_10190902_10_dialog_content = "唔，不擋不擋，我們只是來接管博士的實驗室而已。大家散會吧～",
  ui_story_1019_10190902_11_dialog_content = "接管我的實驗室？可笑……",
  ui_story_1019_10190902_12_dialog_content = "科學首席議會的主席是我！妳們就算用盡一生，也無法超越我的成就！",
  ui_story_1019_10190902_13_dialog_content = "成就越高越好呀！啟光不允許知識壟斷。這些資料有什麼是我貢露看不懂的嗎？",
  ui_story_1019_10190902_14_dialog_content = "不過在博士離開之前，麻煩移交一下電腦的權限喲～",
  ui_story_1019_10190902_15_dialog_content = "實驗暗鬼和生物材料也會由我們黑傘實驗室來接管。",
  ui_story_1019_10190902_16_dialog_content = "放心吧，有我在，我不會讓任何一隻暗鬼在科技園區亂跑。",
  ui_story_1019_10190902_17_dialog_content = "空裔？你真的不想知道嗎？！",
  ui_story_1019_10190902_18_option_content = "不想",
  ui_story_1019_10190902_19_dialog_content = "（尤利西斯和這些畫面的關係很詭異……）",
  ui_story_1019_10190902_20_dialog_content = "（剛才看到的景象，我必須告訴薇薇安才行。）",
  ui_story_1019_10190902_21_option_content = "想",
  ui_story_1019_10190902_22_dialog_content = "（尤利西斯為什麼會給我看那些畫面……難道他真的想告訴我什麼？）",
  ui_story_1019_10190902_23_dialog_content = "（但他的狀態不對勁，或許不能信任他……）",
  ui_story_1019_10190902_24_dialog_content = "我相信審查會後，一切都會水落石出。",
  ui_story_1019_10190902_25_dialog_content = "呵呵……哈哈哈哈……",
  ui_story_1019_10190902_26_dialog_content = "這就是光靈的歸宿嗎……我的心血終究被你們這些愚昧之徒踐踏。",
  ui_story_1019_10190902_27_dialog_content = "罷了……罷了……",
  ui_story_1019_10190902_28_dialog_content = "既然如此，那就讓我親自揭示這一切吧。",
  ui_story_1019_10190902_29_dialog_content = "如果你們能親眼見證歷史，那也算是種榮幸了……",
  ui_story_1019_10190902_30_dialog_content = "告訴貝利撒留，我要傳我的證人。",
  ui_story_1019_10190902_31_dialog_content = "證人？您是說誰？",
  ui_story_1019_10190902_32_dialog_content = "鶯歌、阿克希亞、西恩。只管去帶人就行了。",
  ui_story_1019_10190902_33_dialog_content = "是，長官。",
  ui_story_1019_10190902_34_dialog_content = "……",
  ui_story_1019_10190902_35_dialog_content = "PlayerName，你的擔憂我通知大元帥了，但現在我們必須把尤利西斯交給審查會。",
  ui_story_1019_10190902_36_dialog_content = "在他們查明真相前，我們還有更重要的事得做。別忘了，我們還有座標的事情要探索。",
  ui_story_1019_10190902_37_dialog_content = "嗯……可是他剛才問我的話，讓我很在意……",
  ui_story_1019_10190902_38_dialog_content = "「在你眼中，世界的盡頭在哪裡？」",
  ui_story_1019_10190902_39_dialog_content = "「倘若暗潮危機再次來臨，光靈如何才能抵抗黑暗的侵蝕？」",
  ui_story_1019_10190902_40_dialog_content = "哈——呼——",
  ui_story_1019_10190902_41_dialog_content = "可能是最近沒睡好吧，我總覺得有些迷茫，像失去了重要的東西一樣。",
  ui_story_1019_10190902_42_dialog_content = "如果真的失去了什麼，無論多遠多黑暗，我相信你都會勇敢地去尋找。",
  ui_story_1019_10190902_43_dialog_content = "但是啟光不同，啟光是我們的家園，我們的希望。",
  ui_story_1019_10190902_44_dialog_content = "如果這裡能看到地下城的天空……",
  ui_story_1019_10190902_45_dialog_content = "地面上，太陽應該已經升起來了。",
  ui_story_1019_10190902_46_dialog_content = "而對於啟光人來說，離開地下城站在陽光下，就是他們能夠去到最遠的地方。",
  ui_story_1019_10190902_47_dialog_content = "迦南城十年如一日，看不到太陽，倒也不用擔心被黑暗侵蝕。",
  ui_story_1019_10190902_48_dialog_content = "只是隨著時間變化，我們越來越沉入地底。",
  ui_story_1019_10190902_49_dialog_content = "真好奇迦南城剛建立的時候是什麼樣子……",
  ui_story_1019_10190902_50_dialog_content = "有一點是肯定的，那就是暗鬼無處不在。",
  ui_story_1019_10190902_51_dialog_content = "是暗鬼的威脅讓我們在此生存，也讓我們的目標變成「消滅暗鬼」。",
  ui_story_1019_10190902_52_dialog_content = "真不知道審判結束後，啟光的未來會怎麼樣。",
  ui_story_1019_10190902_53_dialog_content = "……",
  ui_story_1019_10190902_54_dialog_content = "我知道你小子想得多，但你可要撐住啊！",
  ui_story_1019_10190902_55_dialog_content = "嗯，和你們聊了一會後，我比較能打起精神了。",
  ui_story_1019_10190902_56_dialog_content = "那可能是阿爾戈爾說的「生理時鐘」吧？現在正是一天的開始。",
  ui_story_1019_10190902_57_dialog_content = "是這樣啊……",
  ui_story_1019_10190902_58_dialog_content = "那……早安，薇薇安、巴頓。",
  ui_story_1019_10190902_59_dialog_content = "早安，PlayerName。",
  ui_story_1019_10190902_60_dialog_content = "早安，啟光。快去忙你們的事吧，希望這一切早點結束。",
  ui_story_1019_10191001_1_dialog_content = "<color=#e8d9bb>啟光高層會議室，眾人沉默不語。</color>",
  ui_story_1019_10191001_2_dialog_content = "到了要定罪我的時候，你們反而不出聲了。",
  ui_story_1019_10191001_3_dialog_content = "咳咳……",
  ui_story_1019_10191001_4_dialog_content = "嗯……",
  ui_story_1019_10191001_5_dialog_content = "這是第五場審查會了。我們不妨換個方式，隨便聊聊。你不是帶了證人嗎？",
  ui_story_1019_10191001_6_dialog_content = "……",
  ui_story_1019_10191001_7_dialog_content = "聊聊？你們還想拖延多久？黃昏鎮和啟光防線的戰鬥，已經證明了我軍的決心和實力！",
  ui_story_1019_10191001_8_dialog_content = "軍演事件的證人赫利俄斯還沒完全恢復意識，「啟明星計畫」士兵的身體狀況也還在檢查。",
  ui_story_1019_10191001_9_dialog_content = "這些都是藉口，你們應該拿出有力的證據！",
  ui_story_1019_10191001_10_dialog_content = "沒錯。無論軍演還是「啟明星計畫」，我都是親歷者，一人作證足矣！",
  ui_story_1019_10191001_11_dialog_content = "看來術後身體恢復得不錯啊，雷霆大元帥。",
  ui_story_1019_10191001_12_dialog_content = "我理解你們的訴求，但我們不能忽視尤利西斯博士的立場和貢獻。",
  ui_story_1019_10191001_13_dialog_content = "審查會都拖了這麼久，你們還不滿意嗎？",
  ui_story_1019_10191001_14_dialog_content = "我們可以給他一個機會，但這是最後一次。",
  ui_story_1019_10191001_15_dialog_content = "萊因哈特？",
  ui_story_1019_10191001_16_dialog_content = "但我有一個條件。我軍不會再退讓，最終審判之前，我會傳喚我的證人。",
  ui_story_1019_10191001_17_dialog_content = "到那時，你們就不得不對尤利西斯判刑了。",
  ui_story_1019_10191001_18_dialog_content = "當然。那你可得把握時間，尤利西斯。這是最後一次陳述，我想聽點別的。",
  ui_story_1019_10191001_19_dialog_content = "呵呵……我……咳咳……",
  ui_story_1019_10191001_20_dialog_content = "博士，你的藥、水——",
  ui_story_1019_10191001_21_dialog_content = "……",
  ui_story_1019_10191001_22_dialog_content = "……沒事，最近身體不太好，有點累。",
  ui_story_1019_10191001_23_dialog_content = "我已經說過了，我沒有隱瞞任何事情。",
  ui_story_1019_10191001_24_dialog_content = "沒問你的話，你也沒說，當然就不算隱瞞。",
  ui_story_1019_10191001_25_dialog_content = "但是你的研究成果，以及你離開實驗室後，你的團隊能否繼續你的工作，我們希望你能坦白告訴我們。",
  ui_story_1019_10191001_26_dialog_content = "畢竟，你的任務是歷史重責，應該交給新一代的人了。",
  ui_story_1019_10191001_27_dialog_content = "妳是在怪我活太久了嗎？呵呵……",
  ui_story_1019_10191001_28_dialog_content = "我尤利西斯，晨光曆一九四五年生，如今已經活了半個多世紀……",
  ui_story_1019_10191001_29_dialog_content = "按照啟光光靈的平均壽命，我早就該死了，和我的同齡人一樣。",
  ui_story_1019_10191001_30_dialog_content = "自啟光建城以來受制於『工程師』的難題，真的要交給這些只知兵馬和槍砲的軍人嗎？",
  ui_story_1019_10191001_31_dialog_content = "……",
  ui_story_1019_10191001_32_dialog_content = "「工程師」？什麼意思？",
  ui_story_1019_10191001_33_dialog_content = "萊因哈特，妳知道他在說什麼嗎？",
  ui_story_1019_10191001_34_dialog_content = "……",
  ui_story_1019_10191001_35_dialog_content = "尤利西斯，別岔開話題。你實施「啟明星計畫」到底有什麼目的？",
  ui_story_1019_10191001_36_dialog_content = "為了提高光靈的生存能力，啟光持續進行多年的「光靈改造實驗」，現在你們都知道了。",
  ui_story_1019_10191001_37_dialog_content = "除了赫利俄斯和德尼耶爾，從早期的「機體增強實驗」，到現在「啟明星計畫」的優秀個體都在這裡了。",
  ui_story_1019_10191001_38_dialog_content = "……",
  ui_story_1019_10191001_39_dialog_content = "……",
  ui_story_1019_10191001_40_dialog_content = "「機體增強實驗」和……「優異個體」？",
  ui_story_1019_10191001_41_dialog_content = "啟光聯邦軍人設法提高戰鬥力來保護他人生命者，並不在少數。",
  ui_story_1019_10191001_42_dialog_content = "更有身體機能有缺陷的光靈，透過改造技術來延續生命……",
  ui_story_1019_10191001_43_dialog_content = "博士，您看著我……是在說我嗎？",
  ui_story_1019_10191001_44_dialog_content = "我是透過改造技術來延續生命的人……？",
  ui_story_1019_10191001_45_dialog_content = "……",
  ui_story_1019_10191001_46_dialog_content = "這是……開玩笑吧？我只是定期來啟光做檢查的……怎麼是「透過改造技術來延續生命」？",
  ui_story_1019_10191001_47_dialog_content = "你不是普通的光靈，西恩。你也是「啟明星計畫」的優秀個體。",
  ui_story_1019_10191001_48_dialog_content = "……",
  ui_story_1019_10191001_49_dialog_content = "很難相信嗎？但是你們不知道，自己是多麼幸運。",
  ui_story_1019_10191001_50_dialog_content = "對我這樣來自戰爭年代的人來說，有能力戰鬥者，就是掠奪無力者生存權的人。",
  ui_story_1019_10191001_51_dialog_content = "如果你們處在我的位置，又會做出什麼選擇呢……",
  ui_story_1019_10191001_52_dialog_content = "尤利，今天你又想到什麼新問題？",
  ui_story_1019_10191001_53_dialog_content = "還是老樣子。",
  ui_story_1019_10191001_54_dialog_content = "哈哈，基因工程？你說這樣的詞彙，那些前輩是怎麼想出來的呢？",
  ui_story_1019_10191001_55_dialog_content = "怎麼想出來的重要嗎？",
  ui_story_1019_10191001_56_dialog_content = "重要的是，我現在在研究這個。",
  ui_story_1019_10191001_57_dialog_content = "「前輩是怎麼想出來的」，我從沒想過這個問題。因為追本溯源的結果往往很可笑……",
  ui_story_1019_10191001_58_dialog_content = "迦南城是白夜城的一支先遣部隊發現的。",
  ui_story_1019_10191001_59_dialog_content = "這群無畏的戰士在對抗暗鬼時遭遇毀滅性打擊，隨後卻遭到白夜城拋棄……",
  ui_story_1019_10191001_60_dialog_content = "這支先遣部隊，最終演變成如今地下城偏安一隅的軍事聯邦。",
  ui_story_1019_10191001_61_dialog_content = "但不知為何，拉比的話始終在我腦海裡揮之不去。",
  ui_story_1019_10191001_62_dialog_content = "尤利，今天你又想到什麼新問題？",
  ui_story_1019_10191001_63_dialog_content = "……",
  ui_story_1019_10191001_64_dialog_content = "在看什麼，這麼入迷？",
  ui_story_1019_10191001_65_dialog_content = "「啟光聯邦歷史年鑑」？怎麼有空看這個？今天不覺得歷史可笑啦？",
  ui_story_1019_10191001_66_dialog_content = "拉比，你知道啟光聯邦建立多少年了嗎？",
  ui_story_1019_10191001_67_dialog_content = "<color=#FFB400>六百四十九年。</color>",
  ui_story_1019_10191001_68_dialog_content = "……記得這麼清楚？",
  ui_story_1019_10191001_69_dialog_content = "當然。要不是我爸反對，我應該會在媽媽的鼓勵下成為歷史學家。",
  ui_story_1019_10191001_70_dialog_content = "你問啟光聯邦建立的時間，不會只想考我吧？",
  ui_story_1019_10191001_71_dialog_content = "我追溯基因工程的發展歷程時，在「啟光聯邦歷史年鑑」中發現一個問題。",
  ui_story_1019_10191001_72_dialog_content = "啟光並沒有記錄基因工程的發展歷程。彷彿基因改造技術從誕生開始就有很高的技術。",
  ui_story_1019_10191001_73_dialog_content = "基因工程難道是白夜城的技術？在啟光建立以前就有了？",
  ui_story_1019_10191001_74_dialog_content = "還是……啟光歷史不只六百四十九年？",
  ui_story_1019_10191001_75_dialog_content = "有可能。關於這一點，我會繼續研究。",
  ui_story_1019_10191001_76_dialog_content = "於是我像著了魔一樣，順著這個疑問一直查下去。",
  ui_story_1019_10191001_77_dialog_content = "資料館外是和平還是戰亂，我不清楚。",
  ui_story_1019_10191001_78_dialog_content = "我只知道，戰爭無法波及這間小小的資料室，影響我探究真相的唯有時間。",
  ui_story_1019_10191001_79_dialog_content = "一天……一個月……",
  ui_story_1019_10191001_80_dialog_content = "我腦海中有個聲音在告訴我，目前實驗的失敗不可怕，歷史會告訴我答案。",
  ui_story_1019_10191001_81_dialog_content = "一年……兩年……",
  ui_story_1019_10191001_82_dialog_content = "直到有一天……",
  ui_story_1019_10191001_83_dialog_content = "拉比！拉比！拉比你快看……右下角這幾個字是什麼？！",
  ui_story_1019_10191001_84_dialog_content = "……「工程師」？",
  ui_story_1019_10191001_85_dialog_content = "這是什麼？",
  ui_story_1019_10191001_86_dialog_content = "之前查閱資料時，我就發覺很多涉及基因工程起源的問題有些遮掩、草草帶過。",
  ui_story_1019_10191001_87_dialog_content = "但這本書中的這個地方給了我答案——",
  ui_story_1019_10191001_88_dialog_content = "「在 的指導下，光能超載問題得到解決……」",
  ui_story_1019_10191001_89_dialog_content = "在……什麼的指導下？",
  ui_story_1019_10191001_90_dialog_content = "對！在什麼的指導下？",
  ui_story_1019_10191001_91_dialog_content = "……「工程師」？你認為這裡刪除的字眼是「工程師」？",
  ui_story_1019_10191001_92_dialog_content = "我的直覺告訴我，是這樣沒錯。",
  ui_story_1019_10191001_93_dialog_content = "有意思……正文裡刪除，但答案在邊角……",
  ui_story_1019_10191001_94_dialog_content = "但是尤利，你能確定嗎？同樣的情況還有嗎？",
  ui_story_1019_10191001_95_dialog_content = "沒了……但是如果為那些晦澀的文獻開頭加上一個「工程師」的假設……",
  ui_story_1019_10191001_96_dialog_content = "沒錯，很多事情就說得通了……",
  ui_story_1019_10191001_97_dialog_content = "「在工程師的帶領下，部分光靈迅速組織了團隊研究遠古科技。」",
  ui_story_1019_10191001_98_dialog_content = "「工程師帶領研究團隊參觀了迦南城的整體構造，並教他們使用部分科技的方法。」",
  ui_story_1019_10191001_99_dialog_content = "尤利，我從沒見你這麼高興過。",
  ui_story_1019_10191001_100_dialog_content = "我會繼續調查下去的！",
  ui_story_1019_10191001_101_dialog_content = "伴隨著資料室外連綿的砲火聲……",
  ui_story_1019_10191001_102_dialog_content = "再給我一點時間，我相信，那一定會變成光靈戰勝暗鬼的慶祝之聲！",
  ui_story_1019_10191101_1_dialog_content = "暗面地圖繪製得怎麼樣了？",
  ui_story_1019_10191101_2_dialog_content = "喔，這不是阿爾戈爾博士嗎？居然肯從實驗室裡出來透透氣，真難得啊！",
  ui_story_1019_10191101_3_dialog_content = "喬伊斯博士，您好。",
  ui_story_1019_10191101_4_dialog_content = "妳好，妳好。咦，這位……不是空裔嗎？",
  ui_story_1019_10191101_5_dialog_content = "您好。",
  ui_story_1019_10191101_6_dialog_content = "我聽阿爾戈爾說了，你的巨像功能對我的暗面地圖模型幫了很大的忙，真是太感謝你了！",
  ui_story_1019_10191101_7_dialog_content = "不客氣，這是我答應過要幫助啟光的，這本身也是在幫助我。",
  ui_story_1019_10191101_8_dialog_content = "喬伊斯，別廢話了。有個暗面座標，我想聽聽你的意見，那裡有沒有探索的可能性。",
  ui_story_1019_10191101_9_dialog_content = "暗面的新情報嗎……你快趕上<color=#FFB400>地理模型推演</color>的速度了。",
  ui_story_1019_10191101_10_dialog_content = "你也知道，我現在的環境模型是基於已知區域的連續性推算出來的。",
  ui_story_1019_10191101_11_dialog_content = "也就是說，如果座標離迦南城太遠，而且中間還有斷層的大陸，那麼計算就會變得非常複雜。",
  ui_story_1019_10191101_12_dialog_content = "我只能根據一些機率權重，分別針對連續和不連續的情況來計算，然後根據現有的環境資料去推斷。",
  ui_story_1019_10191101_13_dialog_content = "那結果呢？你算出來了嗎？",
  ui_story_1019_10191101_14_dialog_content = "這麼快就沒耐心了……？",
  ui_story_1019_10191101_15_dialog_content = "直接說結果吧。",
  ui_story_1019_10191101_16_dialog_content = "好吧，好吧……我還在根據赫利俄斯提供的線索補充模型。",
  ui_story_1019_10191101_17_dialog_content = "艾斯特拉的宜居帶之外，是一片厚度不一的冰凍沼澤，上面覆蓋著一層薄薄的雪。",
  ui_story_1019_10191101_18_dialog_content = "沼澤之後是一片高低不平的冰塔林，這些冰塔的形狀各異……",
  ui_story_1019_10191101_19_dialog_content = "有的像尖銳的三角錐，有的像倒掛的圓錐，有的像扭曲的螺旋……",
  ui_story_1019_10191101_20_dialog_content = "別說廢話，說重點！",
  ui_story_1019_10191101_21_dialog_content = "布！布！布！",
  ui_story_1019_10191101_22_dialog_content = "你對這些有興趣？",
  ui_story_1019_10191101_23_dialog_content = "布！布！布！",
  ui_story_1019_10191101_24_dialog_content = "……",
  ui_story_1019_10191101_25_dialog_content = "<color=#e8d9bb>喬伊斯侃侃而談一刻鐘後……</color>",
  ui_story_1019_10191101_26_dialog_content = "……所以這些冰塔裡面，有一部分空氣會因為溫差而液化，形成一些奇怪的石柱或冰柱。",
  ui_story_1019_10191101_27_dialog_content = "這個原理我也不太清楚，可能跟白夜城的浮空技術有關。",
  ui_story_1019_10191101_28_dialog_content = "但是這些氣流凝固的時候，有的會往上升，有的會下降……",
  ui_story_1019_10191101_29_dialog_content = "等等！你剛剛說什麼？",
  ui_story_1019_10191101_30_dialog_content = "……所以這些石頭的外形就會有很大的差別。這就是我的結論。",
  ui_story_1019_10191101_31_dialog_content = "你問哪一句？",
  ui_story_1019_10191101_32_dialog_content = "往上升的石柱……",
  ui_story_1019_10191101_33_dialog_content = "我在尤利西斯的意識裡，也看過那種東西……",
  ui_story_1019_10191101_34_dialog_content = "我應該沒有看錯……這是巧合嗎？",
  ui_story_1019_10191101_35_dialog_content = "……",
  ui_story_1019_10191101_36_dialog_content = "你再說一遍，喬伊斯，你剛剛說的那兩句話。",
  ui_story_1019_10191101_37_dialog_content = "我說，這些氣流在凝固時，有的會往上升，有的會往下降，所以這些石頭的外形就會有很大的差別。",
  ui_story_1019_10191101_38_dialog_content = "說到上升和下降，我們曾經做過一個實驗……",
  ui_story_1019_10191101_39_dialog_content = "不會錯……",
  ui_story_1019_10191101_40_dialog_content = "我仔細回想了一下，那些上升的冰石柱中，有些還嵌有會發光的圓環……",
  ui_story_1019_10191101_41_dialog_content = "你是說，你看到「守護者一號」的核心？那東西竟然是在上升的冰石柱上？！",
  ui_story_1019_10191101_42_dialog_content = "……是這樣嗎？",
  ui_story_1019_10191101_43_dialog_content = "沒錯！沒錯！",
  ui_story_1019_10191101_44_dialog_content = "有意思……太有意思了！",
  ui_story_1019_10191101_45_dialog_content = "你在尤利西斯意識中看到的東西，跟暗面探索隊傳回疑似「守護者一號」核心的圖一模一樣……",
  ui_story_1019_10191101_46_dialog_content = "而且，如果臨空者號的座標周圍，正是這些上升的冰石柱……",
  ui_story_1019_10191101_47_dialog_content = "我懂了……訊號會閃爍不是多個座標，而是因為冰石柱在移動！",
  ui_story_1019_10191101_48_dialog_content = "我總結一下。尤利西斯不僅知道核心的位置，而且核心很可能就在巨像的原始地點？",
  ui_story_1019_10191101_49_dialog_content = "……他甚至還暗示過，他知道薇絲遭遇了什麼事！",
  ui_story_1019_10191101_50_dialog_content = "……",
  ui_story_1019_10191101_51_dialog_content = "看來，我不僅幫了你們大忙，而且還揭開了一個大祕密。",
  ui_story_1019_10191101_52_dialog_content = "唔……如果他和日蝕有聯繫，這怎麼聽都不是好消息啊……",
  ui_story_1019_10191101_53_dialog_content = "尤利西斯從來沒離開過地下城，卻和日蝕的計畫有那麼深的牽連……",
  ui_story_1019_10191101_54_dialog_content = "我在想，之前罪靈能潛入迦南城，偷走「守護者一號」的核心，會不會就是尤利西斯的關係？",
  ui_story_1019_10191101_55_dialog_content = "我有一個更大膽的猜想……",
  ui_story_1019_10191101_56_dialog_content = "「守護者一號」不可能繞過我的監視系統，除非有人用了那台能繞過監視系統的東西……",
  ui_story_1019_10191101_57_dialog_content = "那部因安全隱憂而被封存的原型機。",
  ui_story_1019_10191101_58_dialog_content = "……",
  ui_story_1019_10191101_59_dialog_content = "如果是尤利西斯在暗中操縱原型機，我們必須去啟光會議向他問個清楚。",
  ui_story_1019_10191101_60_dialog_content = "不，我們直接去他的辦公室。",
  ui_story_1019_10191101_61_dialog_content = "如果我們的猜想沒錯，那裡是現在啟光最危險的地方！",
  ui_story_1019_10191101_62_dialog_content = "……",
  ui_story_1019_10191201_1_dialog_content = "我能提問吧？你們到底在玩什麼把戲？刪掉正文，掩蓋歷史……",
  ui_story_1019_10191201_2_dialog_content = "關於「工程師」，你們究竟隱瞞了什麼？還是白夜城有什麼不可告人的祕密？",
  ui_story_1019_10191201_3_dialog_content = "可以肯定的是，「工程師」的資料只在啟光的檔案裡出現過，而委員會對此瞭解不深。",
  ui_story_1019_10191201_4_dialog_content = "你當我白癡嗎？！",
  ui_story_1019_10191201_5_dialog_content = "資料確實不是委員會刪除的。",
  ui_story_1019_10191201_6_dialog_content = "至少不是現在的委員會。",
  ui_story_1019_10191201_7_dialog_content = "如果不是暗潮危機爆發時，啟光高層決定解除「守護者」的研究限制，我也不可能查到「工程師」的資料。",
  ui_story_1019_10191201_8_dialog_content = "「守護者」……？",
  ui_story_1019_10191201_9_dialog_content = "那是白夜城先遣隊在迦南城發現的一部神祕遠古機器。",
  ui_story_1019_10191201_10_dialog_content = "後來的定居者把它取名叫「守護者」。",
  ui_story_1019_10191201_11_dialog_content = "這部「守護者」現在還在研究嗎？",
  ui_story_1019_10191201_12_dialog_content = "阿爾戈爾只拿到<color=#FFB400>沙盒隔離</color>的備份，原型機則因安全隱憂而封存了。",
  ui_story_1019_10191201_13_dialog_content = "這只是原本的計畫……",
  ui_story_1019_10191201_14_dialog_content = "尤利西斯……你？！",
  ui_story_1019_10191201_15_dialog_content = "呵呵……我一直懷疑，掩埋原型機和「工程師」資訊不明之間，一定有某種關聯。",
  ui_story_1019_10191201_16_dialog_content = "直到我在原型機中發現大量「工程師」的筆記……",
  ui_story_1019_10191201_17_dialog_content = "<color=#e8d9bb>嘩啦——</color>",
  ui_story_1019_10191201_18_dialog_content = "尤利，你在這啊！我找你好久，到處都找不到你。大夥還擔心你到戰場去了呢。",
  ui_story_1019_10191201_19_dialog_content = "他們還說你會一蹶不振，但我很清楚，沒有事情能把你擊垮。",
  ui_story_1019_10191201_20_dialog_content = "……你說，是吧……？",
  ui_story_1019_10191201_21_dialog_content = "……",
  ui_story_1019_10191201_22_dialog_content = "尤利……？你怎麼那麼安靜？",
  ui_story_1019_10191201_23_dialog_content = "你還記得我在調查「工程師」的情資吧？",
  ui_story_1019_10191201_24_dialog_content = "記得，只是我以為戰爭環境這麼糟糕，你又……剛失去家人，早就會放棄了呢……",
  ui_story_1019_10191201_25_dialog_content = "拉比，你不會相信的。委員會最近開放的那台遠古人工智慧，才是調查「工程師」的關鍵。",
  ui_story_1019_10191201_26_dialog_content = "那台遠古機器……是叫「守護者」對吧？那不是阿爾戈爾在研究嗎？",
  ui_story_1019_10191201_27_dialog_content = "那只是虛擬機器，而原型機正是你眼前的這部。",
  ui_story_1019_10191201_28_dialog_content = "尤利！你該不會把封存的原型機……？你知道這是要坐牢的吧？",
  ui_story_1019_10191201_29_dialog_content = "但要是能檢索到「工程師」的研究資料就不一樣了……",
  ui_story_1019_10191201_30_dialog_content = "……",
  ui_story_1019_10191201_31_dialog_content = "「工程師」不但是基因工程的提出者……",
  ui_story_1019_10191201_32_dialog_content = "他對光靈實驗和魔導科技的猜想，以及對肉體和精神本質的思考……",
  ui_story_1019_10191201_33_dialog_content = "彷彿一道道強烈電流，刺激著我的大腦！我從來沒有這麼激動過！",
  ui_story_1019_10191201_34_dialog_content = "尤利……",
  ui_story_1019_10191201_35_dialog_content = "先聽我說完。",
  ui_story_1019_10191201_36_dialog_content = "他在一篇筆記裡記錄了光靈基因組編輯的嘗試……",
  ui_story_1019_10191201_37_dialog_content = "比我們目前的光靈身體素質強上幾百倍！你知道這意味著什麼嗎？",
  ui_story_1019_10191201_38_dialog_content = "這位「工程師」所在的時代……科技程度比現在更高？",
  ui_story_1019_10191201_39_dialog_content = "還有呢？",
  ui_story_1019_10191201_40_dialog_content = "噢……「工程師」 正是「守護者」的擁有者！",
  ui_story_1019_10191201_41_dialog_content = "不，拉比。這些都不是最重要的。",
  ui_story_1019_10191201_42_dialog_content = "重要的是，如果能重現這些技術，我們還需要在這暗無天日的地下城躲避暗鬼嗎？",
  ui_story_1019_10191201_43_dialog_content = "……",
  ui_story_1019_10191201_44_dialog_content = "尤利，如果這一切都是真的……那未免也……",
  ui_story_1019_10191201_45_dialog_content = "太驚喜了對嗎？這將是突破性的進展，啟光的未來！戰勝暗鬼，重回地面的理想！",
  ui_story_1019_10191201_46_dialog_content = "以及你環遊艾歐里亞的夢想，都可以實現了！",
  ui_story_1019_10191201_47_dialog_content = "環遊艾歐里亞……",
  ui_story_1019_10191201_48_dialog_content = "尤利，我知道你內心深處蘊藏著超越眾人的勇氣和力量。",
  ui_story_1019_10191201_49_dialog_content = "我此前還擔心你……哈哈，你能振作起來就好，尤利。",
  ui_story_1019_10191201_50_dialog_content = "無論如何，只要你沒事就好……",
  ui_story_1019_10191201_51_dialog_content = "一開始拉比這麼說的時候，我並沒有什麼感覺。",
  ui_story_1019_10191201_52_dialog_content = "但直到他笑容消失，日益被戰爭的痛苦壓垮之後，我才明白他話裡的含義。",
  ui_story_1019_10191201_53_dialog_content = "我必須加快速度，在暗鬼消滅光靈之前，再現「工程師」的研究成果。",
  ui_story_1019_10191201_54_dialog_content = "就算這會導致我遺忘他人，甚至遺忘自我。",
  ui_story_1019_10191201_55_dialog_content = "因為唯有從「工程師」的筆記找出提升光靈戰鬥力的方法，我才會感到振奮和喜……",
  ui_story_1019_10191201_56_dialog_content = "咳咳……咳咳咳，喜悅！",
  ui_story_1019_10191201_57_dialog_content = "長官，您的身體沒事吧……要不要——",
  ui_story_1019_10191201_58_dialog_content = "……不要緊……咳咳！",
  ui_story_1019_10191201_59_dialog_content = "找尋「工程師」遺留的線索、重現他的成果，花費我近十年的時間……",
  ui_story_1019_10191201_60_dialog_content = "十年啊。如今她們接收了我的實驗室，又能做些什麼呢？",
  ui_story_1019_10191201_61_dialog_content = "<color=#e8d9bb>咔噠咔噠——</color>",
  ui_story_1019_10191201_62_dialog_content = "資料整理得這麼齊，這老頭的強迫症倒也替我們省了不少事。嗯，這是什麼……",
  ui_story_1019_10191201_63_dialog_content = "……",
  ui_story_1019_10191201_64_dialog_content = "欸？不是說剛才就是最後一回合嗎？都半小時了。妳是不是在耍賴啊？",
  ui_story_1019_10191201_65_dialog_content = "唔……既然省事的話就拜託小彌加德了，哈哈！",
  ui_story_1019_10191201_66_dialog_content = "好久沒玩過這麼簡單的遊戲了，唯一缺點是執行的速度太慢了！",
  ui_story_1019_10191201_67_dialog_content = "唔……啟光的電腦應該統一升級過啦，難道漏掉了？還是這台是老頭的私藏？",
  ui_story_1019_10191201_68_dialog_content = "漏掉什麼？",
  ui_story_1019_10191201_69_dialog_content = "咿……我可沒在工作的時候打遊戲啊！這是……這是……",
  ui_story_1019_10191201_70_dialog_content = "電腦借我用一下。",
  ui_story_1019_10191201_71_dialog_content = "阿爾戈爾博士，就是這部機器嗎？",
  ui_story_1019_10191201_72_dialog_content = "……不是。難道是漏了什麼線索……",
  ui_story_1019_10191201_73_dialog_content = "等等……別動……",
  ui_story_1019_10191201_74_dialog_content = "這麼、近的距離……是要做什麼？",
  ui_story_1019_10191201_75_dialog_content = "不貼近一點怎麼會發現不對勁呢……",
  ui_story_1019_10191201_76_dialog_content = "你們路上遇到什麼東西了嗎？總覺得有一股不懷好意的氣息……",
  ui_story_1019_10191201_77_dialog_content = "是說我？還是說布林？",
  ui_story_1019_10191201_78_dialog_content = "布布！布布！布布！",
  ui_story_1019_10191201_79_dialog_content = "危險 ？不、非常危險？剛剛見尤利西斯的時候是這個意思……",
  ui_story_1019_10191201_80_dialog_content = "從你們進來就我覺得不對勁，現在待在這實驗室裡，越來越有種被視線盯著的感覺……",
  ui_story_1019_10191201_81_dialog_content = "年輕人，你感應到了嗎？",
  ui_story_1019_10191201_82_dialog_content = "有一點……",
  ui_story_1019_10191201_83_dialog_content = "布布！布布！布布！",
  ui_story_1019_10191201_84_dialog_content = "哇呀……我說多少次了，布林，不要這樣扯我的脖子！",
  ui_story_1019_10191201_85_dialog_content = "門外？門外有什麼……",
  ui_story_1019_10191201_86_dialog_content = "糟糕！有一股很強的暗能……",
  ui_story_1019_10191201_87_dialog_content = "巡查時漏掉的暗鬼啊……竟然躲過潛庭之脊的注視。",
  ui_story_1019_10191201_88_dialog_content = "大家小心！",
  ui_story_1019_10191201_89_dialog_content = "<color=#e8d9bb>碰！</color>",
  ui_story_1019_10191202_1_dialog_content = "喝啊——",
  ui_story_1019_10191202_2_dialog_content = "終於……沒動靜了？",
  ui_story_1019_10191202_3_dialog_content = "這麼大一隻……簡直就是遊戲裡的BOSS嘛！",
  ui_story_1019_10191202_4_dialog_content = "不過牠身上沒有任何記號，我們怎麼知道牠是從哪來的？",
  ui_story_1019_10191202_5_dialog_content = "和倉庫裡那些實驗暗鬼不同，牠的身上完全沒有實驗編號。",
  ui_story_1019_10191202_6_dialog_content = "而且，我們甚至不知道牠到底是實驗暗鬼還是什麼……",
  ui_story_1019_10191202_7_dialog_content = "會是尤利西斯的實驗品嗎？就像雷霆的近衛軍一樣……他是不是想用這些怪物來對付委員會？",
  ui_story_1019_10191202_8_dialog_content = "不管是什麼，造出攻打自己人的武器，就是跟日蝕的利益一致了。",
  ui_story_1019_10191202_9_dialog_content = "現在委員會那邊有答覆了嗎？",
  ui_story_1019_10191202_10_dialog_content = "聯絡不上大元帥，看來審查會還沒結束。",
  ui_story_1019_10191202_11_dialog_content = "等不了委員會了。我們必須先行動，找出原型機和漏洞，這比審判尤利西斯重要。",
  ui_story_1019_10191202_12_dialog_content = "嗯，那我們十分鐘後會合，總結一下目前的情況吧。",
  ui_story_1019_10191202_13_dialog_content = "我要先檢查實驗大樓，疏散這裡的研究員。他們可能也知道一些有用的資訊。",
  ui_story_1019_10191202_14_dialog_content = "阿爾戈爾博士，麻煩您把危險源傳給周圍的巡邏兵，增派支援。",
  ui_story_1019_10191202_15_dialog_content = "我們不知道還有多少暗鬼潛伏在這裡，必須提高警覺。",
  ui_story_1019_10191202_16_dialog_content = "沒問題。我也要繼續查原型機的位置。",
  ui_story_1019_10191301_1_dialog_content = "艾森，我說到哪了？",
  ui_story_1019_10191301_2_dialog_content = "您說到……您在閱讀「工程師」的工作筆記時，獲得極大的振奮和喜悅。",
  ui_story_1019_10191301_3_dialog_content = "沒錯，喜悅……",
  ui_story_1019_10191301_4_dialog_content = "這種喜悅，是因為我看到「工程師」的偉大創造，他用「光靈基因定向改造」的技術，製造出一批又一批的超級兵！",
  ui_story_1019_10191301_5_dialog_content = "「大量生產超級兵」……改頭換面之後，就成了如今的「人造太陽計畫」、「啟明星計畫」嗎？",
  ui_story_1019_10191301_6_dialog_content = "僅僅是重現那些實驗過程還不算什麼，令我意想不到的是最後一則工作筆記。",
  ui_story_1019_10191301_7_dialog_content = "大量生產的超級兵數量，在距今<color=#FFB400>六百年</color>前的某個時間點，突然達到高峰。",
  ui_story_1019_10191301_8_dialog_content = "但從那個時間點開始，「守護者」因不明原因永久關閉……",
  ui_story_1019_10191301_9_dialog_content = "而「工程師」的名字則永遠消失在啟光的歷史當中。",
  ui_story_1019_10191301_10_dialog_content = "這是為什麼呢？",
  ui_story_1019_10191301_11_dialog_content = "……",
  ui_story_1019_10191301_12_dialog_content = "鶯歌，妳說。",
  ui_story_1019_10191301_13_dialog_content = "因為……「工程師」實驗失敗了？",
  ui_story_1019_10191301_14_dialog_content = "不，他的實驗無比成功。",
  ui_story_1019_10191301_15_dialog_content = "是啟光終於發現……",
  ui_story_1019_10191301_16_dialog_content = "他們「工程師」所大量生產的「超級兵」，正是戰場上殺死他們的暗鬼！",
  ui_story_1019_10191301_17_dialog_content = "拉比，我可能想錯了……",
  ui_story_1019_10191301_18_dialog_content = "戰場上帶回來的那些暗鬼較為複雜，但仍然有一些個體可以分離出基因樣本。",
  ui_story_1019_10191301_19_dialog_content = "光靈與個別暗鬼的基因組，相似度竟達九成以上。",
  ui_story_1019_10191301_20_dialog_content = "九成？",
  ui_story_1019_10191301_21_dialog_content = "大多數由無機物拼接而成的暗鬼，比較像被真正敵人打到場上的砲彈。",
  ui_story_1019_10191301_22_dialog_content = "但仍有與光靈個體非常接近的敵人，他們或許是扔砲彈的人。",
  ui_story_1019_10191301_23_dialog_content = "如果不製造類似的兵器，我們永遠都敵不過牠們，更別說看清扔砲彈的敵人是誰。",
  ui_story_1019_10191301_24_dialog_content = "尤利，你是想……製造暗鬼嗎？",
  ui_story_1019_10191301_25_dialog_content = "不，我們的武器會比敵人的更厲害。",
  ui_story_1019_10191301_26_dialog_content = "我們的武器既是暗鬼砲彈，還是擁有強大光能術的光靈。",
  ui_story_1019_10191301_27_dialog_content = "暗鬼和光靈……基因融合？",
  ui_story_1019_10191301_28_dialog_content = "尤利……你瘋了……",
  ui_story_1019_10191301_29_dialog_content = "不，是我終於想清楚了。",
  ui_story_1019_10191301_30_dialog_content = "只有這樣，我們光靈在面對暗鬼的時候才有勝算。",
  ui_story_1019_10191301_31_dialog_content = "如果我們只是用原本的身體與暗鬼對抗，只會有一個結局——",
  ui_story_1019_10191301_32_dialog_content = "所以不惜把自己也變成暗鬼嗎？",
  ui_story_1019_10191301_33_dialog_content = "不！是超越！這是「工程師」的天才之舉，他賦予光靈更強大的力量！",
  ui_story_1019_10191301_34_dialog_content = "尤利，你知道你在說什麼嗎？否定光靈反抗敵人的意義，你是在背叛我們的信仰！",
  ui_story_1019_10191301_35_dialog_content = "自從你發現「工程師」的線索以來，你的研究對啟光來說，走得太遠了。",
  ui_story_1019_10191301_36_dialog_content = "你有沒有想過，這或許正是「工程師」的意圖？引導我們生產暗鬼，甚至成為暗鬼。",
  ui_story_1019_10191301_37_dialog_content = "我不是要把我們變成暗鬼！是要把我們變成更強的光靈！",
  ui_story_1019_10191301_38_dialog_content = "我已經找到方法，我們的研究馬上就要進入新的階段了。",
  ui_story_1019_10191301_39_dialog_content = "你一直相信我的，對嗎？我可以讓我們的夢想成為現實，我可以改變光靈的命運！",
  ui_story_1019_10191301_40_dialog_content = "不是這樣的，尤利……不是這樣的……",
  ui_story_1019_10191301_41_dialog_content = "有件事我們都還沒搞清楚……",
  ui_story_1019_10191301_42_dialog_content = "既然你說「工程師」建造了這一切，那他是誰？他為何從啟光歷史中消失？",
  ui_story_1019_10191301_43_dialog_content = "他為何背叛啟光……為何與所有光靈為敵？",
  ui_story_1019_10191301_44_dialog_content = "……",
  ui_story_1019_10191301_45_dialog_content = "「工程師」到底是誰？",
  ui_story_1019_10191301_46_dialog_content = "暗鬼？光靈？惡魔？又或者……",
  ui_story_1019_10191301_47_dialog_content = "都不是呢？咳……咳咳咳咳……咳咳！",
  ui_story_1019_10191301_48_dialog_content = "你到底要咳到什麼時候？！如果今天不逼你，你打算沉默到死嗎？",
  ui_story_1019_10191301_49_dialog_content = "呵呵……四十年來的苦心探索，就算想說，也時常因歷史太沉重而不知該從何回憶起……",
  ui_story_1019_10191301_50_dialog_content = "感謝你們，讓我想起那段意氣風發的歲月，也想起了拉比。",
  ui_story_1019_10191301_51_dialog_content = "但「工程師」是誰，對於我來說已經不重要了。",
  ui_story_1019_10191301_52_dialog_content = "……",
  ui_story_1019_10191301_53_dialog_content = "尤利西斯，「工程師」是誰對你不重要。",
  ui_story_1019_10191301_54_dialog_content = "但啟光要走向何處，這對我很重要。",
  ui_story_1019_10191301_55_dialog_content = "我已經給夠你時間，聽你訴說理想。",
  ui_story_1019_10191301_56_dialog_content = "我該如何衡量「啟明星計畫」能為啟光帶來什麼好處？告訴我。",
  ui_story_1019_10191301_57_dialog_content = "站在你面前的人，有的曾為啟光帶來十年安寧，也有的是未來十年最具潛力的人。",
  ui_story_1019_10191301_58_dialog_content = "光靈戰勝暗鬼的道路只有這一條。即使要踩著光靈的白骨前進，我也要這麼做。",
  ui_story_1019_10191301_59_dialog_content = "你想知道什麼好處？這就是我的回答。",
  ui_story_1019_10191401_1_dialog_content = "各位長官……我聽到動靜……",
  ui_story_1019_10191401_2_dialog_content = "我已經通知所有研究員離開研究中心了，你怎麼還在這？",
  ui_story_1019_10191401_3_dialog_content = "等等——我認得你，你是尤利西斯的助理。",
  ui_story_1019_10191401_4_dialog_content = "這些實驗體是從哪個倉庫跑出來的？",
  ui_story_1019_10191401_5_dialog_content = "實驗體……博士的實驗體都是打上標籤，依生產批次保存的。",
  ui_story_1019_10191401_6_dialog_content = "這些……抱歉，我沒見過，但是博士的電腦上應該有檔案。",
  ui_story_1019_10191401_7_dialog_content = "尤利西斯的電腦我查過了，都是一些實驗資料、報告什麼的。",
  ui_story_1019_10191401_8_dialog_content = "那會是從哪裡冒出來的？",
  ui_story_1019_10191401_9_dialog_content = "我看看……",
  ui_story_1019_10191401_10_dialog_content = "調閱遭拒？看來他還留了一手。",
  ui_story_1019_10191401_11_dialog_content = "布林？你覺得呢？",
  ui_story_1019_10191401_12_dialog_content = "布布！",
  ui_story_1019_10191401_13_dialog_content = "不錯，棒極了！",
  ui_story_1019_10191401_14_dialog_content = "助理，輸入你的密碼。",
  ui_story_1019_10191401_15_dialog_content = "好……",
  ui_story_1019_10191401_16_dialog_content = "<color=#e8d9bb>咔噠咔噠——</color>",
  ui_story_1019_10191401_17_dialog_content = "<color=#e8d9bb>嗡——</color>",
  ui_story_1019_10191401_18_dialog_content = "果然有東西！",
  ui_story_1019_10191401_19_dialog_content = "超級兵檔案……這已經迭代過多少個版本了……",
  ui_story_1019_10191401_20_dialog_content = "這些，我在實驗室都沒見過……",
  ui_story_1019_10191401_21_dialog_content = "當然，這是只屬於尤利西斯自己的實驗！",
  ui_story_1019_10191401_22_dialog_content = "這些超級兵，就是一直襲擊我們的那些吧？他們都存放在哪？",
  ui_story_1019_10191401_23_dialog_content = "存放、存放……",
  ui_story_1019_10191401_24_dialog_content = "布布！",
  ui_story_1019_10191401_25_dialog_content = "啊，找到了！",
  ui_story_1019_10191401_26_dialog_content = "……<color=#FFB400>零號倉庫</color>？那不是……",
  ui_story_1019_10191401_27_dialog_content = "迦南城裡……有零號倉庫嗎？",
  ui_story_1019_10191401_28_dialog_content = "沒聽過……",
  ui_story_1019_10191401_29_dialog_content = "如果是那間早已封存的零號倉庫的話……",
  ui_story_1019_10191401_30_dialog_content = "跟我來！",
  ui_story_1019_10191401_31_dialog_content = "……",
  ui_story_1019_10191401_32_dialog_content = "大家，跑得好快……",
  ui_story_1019_10191401_33_dialog_content = "這已經不是改造光靈的程度了，是在大量生產暗鬼！",
  ui_story_1019_10191401_34_dialog_content = "防禦漏洞跑出來的那些已經夠危險了，再不快點找到源頭制止，大家就一起等死吧！",
  ui_story_1019_10191401_35_dialog_content = "<color=#e8d9bb>咔嚓——</color>",
  ui_story_1019_10191401_36_dialog_content = "……這就是零號倉庫？",
  ui_story_1019_10191401_37_dialog_content = "好、好大啊！",
  ui_story_1019_10191401_38_dialog_content = "倉庫門全都是敞開的……大到可以存放好幾架引擎七號了。",
  ui_story_1019_10191401_39_dialog_content = "藥水味……就是在這裡進行實驗的嗎？大家小心。",
  ui_story_1019_10191401_40_dialog_content = "<color=#e8d9bb>滋滋——</color>",
  ui_story_1019_10191401_41_dialog_content = "布布！布布！布布！",
  ui_story_1019_10191401_42_dialog_content = "竟然真的是……",
  ui_story_1019_10191401_43_dialog_content = "<color=#e8d9bb>哐噹——</color>",
  ui_story_1019_10191401_44_dialog_content = "這聲音……在前面的儀器上！有超級兵！",
  ui_story_1019_10191401_45_dialog_content = "看樣子實驗剛完成一半……和之前襲擊我們的怪物確實很像。",
  ui_story_1019_10191401_46_dialog_content = "還好有找出源頭！大家小心檢查一下周圍。",
  ui_story_1019_10191401_47_dialog_content = "<color=#e8d9bb>滋滋——</color>",
  ui_story_1019_10191401_48_dialog_content = "哈哈……哈哈哈哈！",
  ui_story_1019_10191401_49_dialog_content = "布！布！布！",
  ui_story_1019_10191401_50_dialog_content = "阿爾戈爾博士，您最好不要碰這些東西，小心觸發開關！",
  ui_story_1019_10191401_51_dialog_content = "溫控面板、中斷按鈕、輸入器……",
  ui_story_1019_10191401_52_dialog_content = "不會錯……",
  ui_story_1019_10191401_53_dialog_content = "<color=#e8d9bb>哐噹——</color>",
  ui_story_1019_10191401_54_dialog_content = "那超級兵動靜好大！似乎想掙脫儀器！",
  ui_story_1019_10191401_55_dialog_content = "布布！布布！布布！",
  ui_story_1019_10191401_56_dialog_content = "顯示器和主機雖然換了外殼，但這些作業系統、傳輸端子、指令介面……",
  ui_story_1019_10191401_57_dialog_content = "因為安全問題被封存，果然是幌子嗎？",
  ui_story_1019_10191401_58_dialog_content = "還有這裡……",
  ui_story_1019_10191401_59_dialog_content = "竟然還在運轉……",
  ui_story_1019_10191401_60_dialog_content = "他究竟躲在這裡做什麼……？",
  ui_story_1019_10191401_61_dialog_content = "布布布布——！！！",
  ui_story_1019_10191401_62_dialog_content = "布林的動作好快！",
  ui_story_1019_10191401_63_dialog_content = "<color=#e8d9bb>哐噹、哐噹——！！！</color>",
  ui_story_1019_10191401_64_dialog_content = "呵呵呵——",
  ui_story_1019_10191401_65_dialog_content = "糟糕，超級兵掙脫了！",
  ui_story_1019_10191401_66_dialog_content = "阿爾戈爾博士，這裡不安全，快離開！",
  ui_story_1019_10191401_67_dialog_content = "……",
  ui_story_1019_10191401_68_dialog_content = "阿爾戈爾博士！！！",
  ui_story_1019_10191401_69_dialog_content = "……",
  ui_story_1019_10191401_70_dialog_content = "<color=#e8d9bb>咔嚓——！！！</color>",
  ui_story_1019_10191401_71_dialog_content = "機甲技能！",
  ui_story_1019_10191401_72_dialog_content = "這麼大的空間，根本不是牆，是倉庫門啊——！",
  ui_story_1019_10191401_73_dialog_content = "大家快走，身後還有大怪物啊！！！",
  ui_story_1019_10191401_74_dialog_content = "先退到門口……進來的時候明明是空的！",
  ui_story_1019_10191401_75_dialog_content = "……站直的樣子還怪嚇人的。",
  ui_story_1019_10191401_76_dialog_content = "但阿爾戈爾博士進來就不走了。",
  ui_story_1019_10191401_77_dialog_content = "阿爾戈爾博士！",
  ui_story_1019_10191401_78_dialog_content = "布布！布布！布布！",
  ui_story_1019_10191401_79_dialog_content = "對付暗鬼，你們才是專業的。",
  ui_story_1019_10191401_80_dialog_content = "暗鬼就在妳身後！無論那有多重要，妳不能連安危都不顧啊！",
  ui_story_1019_10191401_81_dialog_content = "受過折磨之後你也會懂的。",
  ui_story_1019_10191401_82_dialog_content = "被我一根根拔掉的那些頭髮……",
  ui_story_1019_10191401_83_dialog_content = "啃出血又反覆癒合的十根手指頭……",
  ui_story_1019_10191401_84_dialog_content = "反覆折磨我，又讓我七竅生煙的程式碼……",
  ui_story_1019_10191401_85_dialog_content = "我這輩子都不可能再離開這台原型機！",
  ui_story_1019_10191401_86_dialog_content = "……",
  ui_story_1019_10191401_87_dialog_content = "各位，保護阿爾戈爾博士，準備戰鬥！",
  ui_story_1019_10191502_1_dialog_content = "大家沒有受傷吧？",
  ui_story_1019_10191502_2_dialog_content = "輕微的皮肉傷而已，不要緊。",
  ui_story_1019_10191502_3_dialog_content = "都流血了……你不會像遊戲裡那樣，被怪物感染後也變成怪物吧？",
  ui_story_1019_10191502_4_dialog_content = "……妳把我當成什麼了？這樣的小傷在黑傘實驗室很常見吧……",
  ui_story_1019_10191502_5_dialog_content = "不過潛庭之脊的反應確實超乎尋常，它的結構和能量輸出都有很大的變化。",
  ui_story_1019_10191502_6_dialog_content = "同意！不過這些怪物，終究不是我王座的對手！",
  ui_story_1019_10191502_7_dialog_content = "尤利西斯祕密製造超級兵到底想做什麼？而且這原型機還在旁邊持續運轉……",
  ui_story_1019_10191502_8_dialog_content = "從他堅持「啟明星計畫」來看，這倒不難想像……他想要用超級兵來取代光靈，提高光靈的存活率。",
  ui_story_1019_10191502_9_dialog_content = "我擔心的是，這些超級兵就是全部了嗎？雷霆近衛軍團中的改造光靈可是有上百人……",
  ui_story_1019_10191502_10_dialog_content = "我們去問問阿爾戈爾博士那邊有什麼發現吧，也許她能找到超級兵的源頭和數量。",
  ui_story_1019_10191502_11_dialog_content = "<color=#e8d9bb>咔噠咔噠——</color>",
  ui_story_1019_10191502_12_dialog_content = "布林竟然能操作按鍵……而且動作好快！",
  ui_story_1019_10191502_13_dialog_content = "沒錯……",
  ui_story_1019_10191502_14_dialog_content = "我現在知道布林老是扯我頭髮的原因了。",
  ui_story_1019_10191502_15_dialog_content = "布！",
  ui_story_1019_10191502_16_dialog_content = "阿爾戈爾博士，布林是怎麼操作這台原型機的呢？",
  ui_story_1019_10191502_17_dialog_content = "是一頭連著妳的腦子，另一頭的觸手執行妳的指令？",
  ui_story_1019_10191502_18_dialog_content = "嗯……想法不錯，可惜不是。布林應該是利用觸覺和記憶，按照我之前的操作來輸入指令。",
  ui_story_1019_10191502_19_dialog_content = "阿爾戈爾博士，你這邊有什麼發現嗎？",
  ui_story_1019_10191502_20_dialog_content = "這些實驗進行到一半的超級兵，確實就是之前襲擊我們的那些。",
  ui_story_1019_10191502_21_dialog_content = "這就是全部的超級兵了嗎？",
  ui_story_1019_10191502_22_dialog_content = "以我自己來說，發現未封存的原型機已經很不可思議了……",
  ui_story_1019_10191502_23_dialog_content = "超級兵的問題，我或許需要登入系統才能知道。",
  ui_story_1019_10191502_24_dialog_content = "我希望在布林運算的時候，把倉庫好好檢查一遍，看看有沒有其他的實驗體或倉庫。",
  ui_story_1019_10191502_25_dialog_content = "「守護者一號」的核心遭竊，迦南城的防禦疏漏頻出，這一切都和尤利西斯有關。",
  ui_story_1019_10191502_26_dialog_content = "我現在要看看這台仍在運轉的原型機有沒有其他風險，以及……尤利西斯在用它做什麼。",
  ui_story_1019_10191502_27_dialog_content = "我現在非常想採訪一下尤利西斯……",
  ui_story_1019_10191502_28_dialog_content = "因為安全問題被處理掉……哈哈哈哈……",
  ui_story_1019_10191502_29_dialog_content = "妳在笑什麼……？",
  ui_story_1019_10191502_30_dialog_content = "守護者的研究權限開放後，我曾以尤利西斯的學生身分參觀過這部機器。",
  ui_story_1019_10191502_31_dialog_content = "那時候他對人工智慧的研究似乎不感興趣，只是敷衍了事。再後來，就聽說原型機「因為安全問題被處理掉」，我還以為他放棄了這個研究方向。",
  ui_story_1019_10191502_32_dialog_content = "他究竟在私自用原型機做什麼呢？",
  ui_story_1019_10191502_33_dialog_content = "研究沒有進展，問題往往不是出在硬體限制、或歷史的侷限上……",
  ui_story_1019_10191502_34_dialog_content = "而是永遠出在「人」身上。",
  ui_story_1019_10191502_35_dialog_content = "布布布布——！！！",
  ui_story_1019_10191502_36_dialog_content = "<color=#e8d9bb>嗡——</color>",
  ui_story_1019_10191502_37_dialog_content = "做得……不錯……",
  ui_story_1019_10191502_38_dialog_content = "終於要見到「守護者」的全貌了嗎……",
  ui_story_1019_10191502_39_dialog_content = "圓圈和四根光標……這是什麼？",
  ui_story_1019_10191502_40_dialog_content = "看起來是需要登入密碼之類的東西。但不知道是原型機的保護，還是尤利西斯的警戒……",
  ui_story_1019_10191502_41_dialog_content = "登入之後……裡面會有什麼呢？",
  ui_story_1019_10191502_42_dialog_content = "登入後就知道了。",
  ui_story_1019_10191502_43_dialog_content = "布林，準備執行指令！",
  ui_story_1019_10191502_44_dialog_content = "布！",
  ui_story_1020_10200101_1_dialog_content = "<size=45>布布布布——！！！</size>",
  ui_story_1020_10200101_2_dialog_content = "破解密碼的事，交給布林就可以了嗎？",
  ui_story_1020_10200101_3_dialog_content = "布林的速度好快啊……這麼近距離看還真是不可思議。",
  ui_story_1020_10200101_4_dialog_content = "這倒是印證了我的猜想……",
  ui_story_1020_10200101_5_dialog_content = "此前布林對進入尤利西斯的辦公室這麼反抗，包括對他本人也是。",
  ui_story_1020_10200101_6_dialog_content = "或許它正是在提醒我，尤利西斯和原型機之間有關聯。",
  ui_story_1020_10200101_7_dialog_content = "布林是怎麼知道的呢？",
  ui_story_1020_10200101_8_dialog_content = "我也想問。布林怎麼看都不像是第一次操作這部原型機。",
  ui_story_1020_10200101_9_dialog_content = "這就要從我和布林認識的故事講起了。",
  ui_story_1020_10200101_10_dialog_content = "在原型機被封存之前，我曾跟幾位研究員一起來這間破舊的倉庫製作「守護者」系統的隔離拷貝。",
  ui_story_1020_10200101_11_dialog_content = "我擔心他們漏掉什麼，所以每天都在這裡待到很晚。雖然這其中也包含著我想多接觸原型機的私心啦。",
  ui_story_1020_10200101_12_dialog_content = "這裡的儀器總是發出「嗡嗡嗡」的聲音，非常助眠。但我也偶爾會被一些「布布布」的聲音吵到……",
  ui_story_1020_10200101_13_dialog_content = "拷貝完成後，我抱著虛擬機器回到房間，竟然發現這不知是觸手還是電線的東西纏在我的脖子上……",
  ui_story_1020_10200101_14_dialog_content = "然後，原型機的一部分從此就寄生在妳身上了。",
  ui_story_1020_10200101_15_dialog_content = "聽起來和王座、潛庭之脊都有點相似之處。",
  ui_story_1020_10200101_16_dialog_content = "或許吧。但你們恐怕無法想像，我剛剛認識布林的時候有多災難！",
  ui_story_1020_10200101_17_dialog_content = "它幾乎不眠不休，把我房間裡的家具拆得破破爛爛。",
  ui_story_1020_10200101_18_dialog_content = "我試著跟它交流，但總免不了被它暴揍一頓的下場……",
  ui_story_1020_10200101_19_dialog_content = "我的鎖骨、肋骨、肩胛骨……任何它能纏繞的地方，都有骨折的痕跡……",
  ui_story_1020_10200101_20_dialog_content = "這聽起來已經不是暴揍了吧！根本是要把妳大卸八塊啊！",
  ui_story_1020_10200101_21_dialog_content = "不然你以為，我那麼專注於鍛煉身體是為了什麼。",
  ui_story_1020_10200101_22_dialog_content = "這麼說……妳的實驗室裡有那麼多運動器械，是為了強身健體？",
  ui_story_1020_10200101_23_dialog_content = "還有每日健康檢測、定時體檢……算起來，我也是啟光醫療中心的常客了。",
  ui_story_1020_10200101_24_dialog_content = "為了研究布林，阿爾戈爾博士竟然能做到這種程度……",
  ui_story_1020_10200101_25_dialog_content = "為科學事業獻身的人，果然會令人興奮啊……",
  ui_story_1020_10200101_26_dialog_content = "因為我知道它並沒有惡意，交朋友當然會有磨合期。",
  ui_story_1020_10200101_27_dialog_content = "大概是當我開始專注於工作的時候，才發現布林不僅僅只是寄生獸那麼簡單。",
  ui_story_1020_10200101_28_dialog_content = "它對我的研究充滿興趣，甚至會給我回饋。",
  ui_story_1020_10200101_29_dialog_content = "……很難想像，布林從原型機的一部分變成現在這樣，究竟經歷了什麼……",
  ui_story_1020_10200101_30_dialog_content = "總之，在我習慣布林的存在後，才意識到我已經把自己關在屋裡整整半年了。",
  ui_story_1020_10200101_31_dialog_content = "然而這半年，卻是我經歷過最充實、最輕鬆的日子。",
  ui_story_1020_10200101_32_dialog_content = "雖然也是從那個時候起，我被貼上「機器人」、「獨行俠」、「沒朋友」這樣的標籤，但我不在乎。",
  ui_story_1020_10200101_33_dialog_content = "我沒必要跟無法理解我的光靈解釋。和機械體在一起反而讓我更輕鬆自在。",
  ui_story_1020_10200101_34_dialog_content = "哈哈，當然還有一號，那個傢伙……也費了我不少精力。",
  ui_story_1020_10200101_35_dialog_content = "先是一號，然後是布林，阿爾戈爾博士果然是一個——",
  ui_story_1020_10200101_36_dialog_content = "怪人？",
  ui_story_1020_10200101_37_dialog_content = "有點奇怪，但是還怪有趣的人！",
  ui_story_1020_10200101_38_dialog_content = "我知道，我喜歡我是個怪人。",
  ui_story_1020_10200101_39_dialog_content = "這真是說到我心坎裡了，這何嘗不是我身上的標籤。",
  ui_story_1020_10200101_40_dialog_content = "標籤沒什麼不好的啦～聽聽我的標籤，「遊戲王」、「副本殺手」、「二週目黑洞」……",
  ui_story_1020_10200101_41_dialog_content = "我希望這樣的標籤越多越好！",
  ui_story_1020_10200101_42_dialog_content = "因為妳的標籤一聽就很獨特啊。年輕人呢，你的標籤是什麼？",
  ui_story_1020_10200101_43_dialog_content = "我身上……好像沒有什麼標籤。",
  ui_story_1020_10200101_44_dialog_content = "這個我知道，「手下敗將」！",
  ui_story_1020_10200101_45_dialog_content = "對、對……",
  ui_story_1020_10200101_46_dialog_content = "之前對這標籤還有點嫌棄，現在居然愉快地認領了呢。",
  ui_story_1020_10200101_47_dialog_content = "我只是一時想不起其他的標籤而已……",
  ui_story_1020_10200101_48_dialog_content = "說了那麼多，阿爾戈爾博士，我們現在要怎麼做呢？",
  ui_story_1020_10200101_49_dialog_content = "喔，什麼也不做。",
  ui_story_1020_10200101_50_dialog_content = "聽聽這機器轉動的聲音，這或許是布林的本能，接觸原型機後會去翻一遍更新資料。",
  ui_story_1020_10200101_51_dialog_content = "之後調整自己的運作邏輯，破解密碼。這個過程可能會很漫長。",
  ui_story_1020_10200101_52_dialog_content = "但一旦登入之後，不僅能查明尤利西斯到底在做什麼……",
  ui_story_1020_10200101_53_dialog_content = "而且還能調用「守護者」中的防禦程式碼搭建新的核心，補上啟光的防禦漏洞了。",
  ui_story_1020_10200101_54_dialog_content = "那真是太好了！",
  ui_story_1020_10200101_55_dialog_content = "這麼多年了，原型機竟然還能運轉。而且是在空裔來了之後才發現的。",
  ui_story_1020_10200101_56_dialog_content = "看來，還是不能閉門造車啊。",
  ui_story_1020_10200101_57_dialog_content = "哈哈哈，沒想到……真是沒想到啊，哈哈哈哈哈！",
  ui_story_1020_10200101_58_dialog_content = "我有一個問題……尤利西斯如果真的是在這裡偷偷生產超級兵……",
  ui_story_1020_10200101_59_dialog_content = "那他在醫療中心為士兵治療的時候，內心都不會感到不安嗎？",
  ui_story_1020_10200101_60_dialog_content = "如果真的在原型機裡發現他和暗鬼有關聯，那你擔心的那種不安就不會存在。",
  ui_story_1020_10200101_61_dialog_content = "人不會為自己作惡找理由。他們只會覺得自己作惡的方式非常有趣。",
  ui_story_1020_10200201_1_dialog_content = "站在妳面前的人，有的曾為啟光帶來十年安寧，也有的是未來十年最具潛力的人。",
  ui_story_1020_10200201_2_dialog_content = "既然妳想知道我的實驗有什麼好處，那這就是我的回答。",
  ui_story_1020_10200201_3_dialog_content = "「為啟光帶來十年安寧」……你說萊因哈特？",
  ui_story_1020_10200201_4_dialog_content = "啟光有過很多位大元帥，有的人是自身力量強大，而更多是後天賦予的力量。",
  ui_story_1020_10200201_5_dialog_content = "在萊因哈特之前，有許多任大元帥無法控制自己的力量……",
  ui_story_1020_10200201_6_dialog_content = "在生命後期主動或被動地結束了自己的生命。",
  ui_story_1020_10200201_7_dialog_content = "類似的實驗在我出生之前就持續了很多年。",
  ui_story_1020_10200201_8_dialog_content = "我相信這是啟光永遠不願提起的過往，同樣，這也是研究人的恥辱。",
  ui_story_1020_10200201_9_dialog_content = "要不是我主張從嬰幼兒階段開始改造士兵，以及<color=#FFB400>八十號地下城</color>的篩選機制……",
  ui_story_1020_10200201_10_dialog_content = "啟光就不會出現像萊因哈特這樣有勇有謀的大元帥。",
  ui_story_1020_10200201_11_dialog_content = "……",
  ui_story_1020_10200201_12_dialog_content = "正是從「人造太陽計畫」開始，啟光的研究終於步入正軌，甚至可說是相當出色。",
  ui_story_1020_10200201_13_dialog_content = "過程中或許犧牲過一些人，但為了我們的安寧和進步，這些犧牲有其必要。",
  ui_story_1020_10200201_14_dialog_content = "所以，您承認<color=#FFB400>八十號地下城</color>那次災難並非「情報失誤」……",
  ui_story_1020_10200201_15_dialog_content = "當然不是，但我不需要向民眾解釋實驗的每一個步驟。",
  ui_story_1020_10200201_16_dialog_content = "安定的政體需要強硬的統治，對於動盪的啟光民眾來說，倫理和道德的衝擊只會更加致命。",
  ui_story_1020_10200201_17_dialog_content = "倫理和道德的衝擊……",
  ui_story_1020_10200201_18_dialog_content = "我的夥伴用性命換來的情報……卻只是您實驗中的一個步驟。",
  ui_story_1020_10200201_19_dialog_content = "<color=#e8d9bb>轟隆——！！！</color>",
  ui_story_1020_10200201_20_dialog_content = "還記得我們這次八十號地下城偵察任務的目標嗎？！",
  ui_story_1020_10200201_21_dialog_content = "只許成功，不許失敗！！！",
  ui_story_1020_10200201_22_dialog_content = "嘎——！",
  ui_story_1020_10200201_23_dialog_content = "班長！這是<color=#FFB400>阿鵬</color>……託付給我的情報……他沒有為偵察班丟臉！",
  ui_story_1020_10200201_24_dialog_content = "阿鵬……好！做得——非常好！",
  ui_story_1020_10200201_25_dialog_content = "前面就是出口了，阿納托利，一口氣跑出去！",
  ui_story_1020_10200201_26_dialog_content = "是！",
  ui_story_1020_10200201_27_dialog_content = "<color=#e8d9bb>轟隆——！！！</color>",
  ui_story_1020_10200201_28_dialog_content = "班長！",
  ui_story_1020_10200201_29_dialog_content = "情報交給阿納托利！你，還有你們，所有人跟我斷後！",
  ui_story_1020_10200201_30_dialog_content = "是！！！",
  ui_story_1020_10200201_31_dialog_content = "班長！我——",
  ui_story_1020_10200201_32_dialog_content = "記得我教過你的偵察方法嗎？",
  ui_story_1020_10200201_33_dialog_content = "……",
  ui_story_1020_10200201_34_dialog_content = "當隊友把情報託付給你時，無論如何，立刻帶著情報逃命！",
  ui_story_1020_10200201_35_dialog_content = "我有記住，班長！但我……我會和你們一起逃出去！",
  ui_story_1020_10200201_36_dialog_content = "嘎——！",
  ui_story_1020_10200201_37_dialog_content = "呃啊——",
  ui_story_1020_10200201_38_dialog_content = "把我的話當耳邊風嗎？！不要把情感帶入工作！偵察工作只有情報、暗鬼和死人！",
  ui_story_1020_10200201_39_dialog_content = "快走！",
  ui_story_1020_10200201_40_dialog_content = "嘎——！！！",
  ui_story_1020_10200201_41_dialog_content = "班長！！！",
  ui_story_1020_10200201_42_dialog_content = "……走！",
  ui_story_1020_10200201_43_dialog_content = "……把情報帶回去，阿納托利……",
  ui_story_1020_10200201_44_dialog_content = "……有我在背後，你可以跑得……更快……",
  ui_story_1020_10200201_45_dialog_content = "<color=#e8d9bb>轟隆——！！！</color>",
  ui_story_1020_10200201_46_dialog_content = "這些人的生命，他們生存的意義……都被您無情地抹去了！",
  ui_story_1020_10200201_47_dialog_content = "八十號地下城的資源回收作戰，誕生了啟明之光萊因哈特。他們的犧牲換來啟光十年的安寧。",
  ui_story_1020_10200201_48_dialog_content = "這讓像你我這樣的人活到現在，不值得嗎？",
  ui_story_1020_10200201_49_dialog_content = "……我敬重大元帥為啟光做的一切。",
  ui_story_1020_10200201_50_dialog_content = "但是，是調查夥伴死因這個信念支撐著我活到現在。",
  ui_story_1020_10200201_51_dialog_content = "這些年來，我一直跟隨在你們身邊，我早就該明白了……",
  ui_story_1020_10200201_52_dialog_content = "大元帥，我擔任情報官的目標，就是希望我的情報能讓更多人在戰場上活下來。",
  ui_story_1020_10200201_53_dialog_content = "但正是我帶回來的情報讓您被暗鬼圍困，失去重要的夥伴。",
  ui_story_1020_10200201_54_dialog_content = "情報官情報不利，還招致嚴重的後果，我願意接受懲罰。但在此之前……",
  ui_story_1020_10200201_55_dialog_content = "希望您能處死尤利西斯博士！",
  ui_story_1020_10200201_56_dialog_content = "阿納托利……",
  ui_story_1020_10200201_57_dialog_content = "我願意等！無論如何，我必須、一定，要給犧牲的夥伴一個交代！",
  ui_story_1020_10200201_58_dialog_content = "我，曾用我的生命起誓！",
  ui_story_1020_10200201_59_dialog_content = "<color=#e8d9bb>咚——！！！</color>",
  ui_story_1020_10200201_60_dialog_content = "萊因哈特……",
  ui_story_1020_10200201_61_dialog_content = "貝利撒留！",
  ui_story_1020_10200201_62_dialog_content = "無論尤利西斯的立場如何，我絕不允許我們的同胞生活在這麼冷酷的集體當中！",
  ui_story_1020_10200201_63_dialog_content = "我要你立刻審判！否則……就由我來審判！",
  ui_story_1020_10200201_64_dialog_content = "刀已出鞘。",
  ui_story_1020_10200201_65_dialog_content = "雷鳴之勢！",
  ui_story_1020_10200201_66_dialog_content = "慢著——",
  ui_story_1020_10200201_67_dialog_content = "武器放下，所有人！",
  ui_story_1020_10200201_68_dialog_content = "……",
  ui_story_1020_10200201_69_dialog_content = "我不加罪於誰，因為在我看來，你們都是在為啟光做出可能的生存選擇。",
  ui_story_1020_10200201_70_dialog_content = "所以我支持尤利西斯的實驗，也同樣支持軍方繞過委員會的命令，隨意調兵遣將。",
  ui_story_1020_10200201_71_dialog_content = "但一盤棋局結束了，棋子就該回到自己的位置。",
  ui_story_1020_10200201_72_dialog_content = "棋局與棋子？妳以為妳是誰？",
  ui_story_1020_10200201_73_dialog_content = "到了現在，啟光內部還有毒害同胞的毒瘤，迦南城外部還有步步進逼的暗鬼……",
  ui_story_1020_10200201_74_dialog_content = "妳還能坐在這裡，當作沒事發生？",
  ui_story_1020_10200201_75_dialog_content = "啟光不會帶頭討伐暗鬼和探索險境第二次。",
  ui_story_1020_10200201_76_dialog_content = "他們不動，啟光就不動。",
  ui_story_1020_10200201_77_dialog_content = "妳在說什麼？",
  ui_story_1020_10200201_78_dialog_content = "在危機來臨之前，啟光不會率先出擊，更不會自斷雙臂——就算是長滿毒瘤的雙臂。",
  ui_story_1020_10200201_79_dialog_content = "聽懂了嗎？！",
  ui_story_1020_10200201_80_dialog_content = "哈哈哈哈……鐵面、光靈之間互相制衡的遊戲，妳玩了一輩子還沒玩夠？",
  ui_story_1020_10200201_81_dialog_content = "需要我告訴妳，這樣下去，大家的結局會怎樣嗎？",
  ui_story_1020_10200201_82_dialog_content = "就算是死，啟光也不會當白夜城的先遣隊而死！",
  ui_story_1020_10200201_83_dialog_content = "嘶……耳朵都要被妳喊聾了。",
  ui_story_1020_10200201_84_dialog_content = "尤利西斯，你接著說。啟光未來十年的潛力又是什麼？",
  ui_story_1020_10200201_X84_dialog_content = "是你無論如何也要送上戰場的啟光大元帥候選人嗎？",
  ui_story_1020_10200201_85_dialog_content = "呵呵……",
  ui_story_1020_10200201_86_dialog_content = "「啟明星計劃」的成果可不止一個。能代表啟光未來十年潛力的人，是西恩。",
  ui_story_1020_10200201_87_dialog_content = "……",
  ui_story_1020_10200201_88_dialog_content = "……我？",
  ui_story_1020_10200301_1_dialog_content = "<color=#e8d9bb>嗡嗡嗡——</color>",
  ui_story_1020_10200301_2_dialog_content = "布林已經解析好一陣子了吧……",
  ui_story_1020_10200301_3_dialog_content = "……",
  ui_story_1020_10200301_4_dialog_content = "沒在聽我說話嗎……",
  ui_story_1020_10200301_5_dialog_content = "嗶嚕——阿爾戈爾可能進入待機狀態了，請一號去叫醒她。",
  ui_story_1020_10200301_6_dialog_content = "一號？你怎麼……帶了這麼多東西來？",
  ui_story_1020_10200301_7_dialog_content = "這些是阿爾戈爾常用的電腦裝置，一號認為，這些可以幫助阿爾戈爾加快搭建核心的速度。",
  ui_story_1020_10200301_8_dialog_content = "<color=#e8d9bb>哐噹——</color>",
  ui_story_1020_10200301_9_dialog_content = "喔！這聲音一聽就是我的寶貝！一號，快跟我一起組裝起來吧。",
  ui_story_1020_10200301_10_dialog_content = "（還真的「醒」了！）",
  ui_story_1020_10200301_11_dialog_content = "阿爾戈爾今天的運轉速度很慢。",
  ui_story_1020_10200301_12_dialog_content = "那是因為這部機器已經跟我們差了成千上萬年之久……",
  ui_story_1020_10200301_13_dialog_content = "說起來，它還是你的祖先呢。",
  ui_story_1020_10200301_14_dialog_content = "長得一點都不像的祖先。",
  ui_story_1020_10200301_15_dialog_content = "這個解析時間，已經超出我預估的太多了。",
  ui_story_1020_10200301_16_dialog_content = "會不會是布林在一次次升級更新之後，對那些符號背後的「語言」規則完全陌生了……",
  ui_story_1020_10200301_17_dialog_content = "面對自己的原型機，現在都停不下來，它處理的資訊到底有多少啊……",
  ui_story_1020_10200301_18_dialog_content = "阿爾戈爾急得原地跑步。",
  ui_story_1020_10200301_19_dialog_content = "我當然急啊！急急急！",
  ui_story_1020_10200301_20_dialog_content = "要是布林能像你一樣和空裔靠意識溝通就好了！哪怕只是看到一小部分資訊……",
  ui_story_1020_10200301_21_dialog_content = "這裡有這些計算裝置可以同時運作，現在我卻什麼也做不了！",
  ui_story_1020_10200301_22_dialog_content = "雖然不能用語言交流，但是我之前確實感應到一些布林的「資訊」。",
  ui_story_1020_10200301_23_dialog_content = "或許我可以試著感應布林，看有沒有什麼可用的線索。",
  ui_story_1020_10200301_24_dialog_content = "謝謝你的好意，但是布林不攻擊你就已經不容易了。",
  ui_story_1020_10200301_25_dialog_content = "……但妳不是說，布林擅長學習嗎？或許經過剛才的小插曲之後，布林已經信任我了呢？",
  ui_story_1020_10200301_26_dialog_content = "PlayerName聰明。",
  ui_story_1020_10200301_27_dialog_content = "有道理……反正現在什麼也做不了，不如挨頓揍試試看吧。",
  ui_story_1020_10200301_28_dialog_content = "挨揍？！",
  ui_story_1020_10200301_29_dialog_content = "那個……布林，拜託了！",
  ui_story_1020_10200301_30_option_content = "感應——開始——",
  ui_story_1020_10200301_31_dialog_content = "……",
  ui_story_1020_10200301_32_dialog_content = "這樣就結束了……？布林拒絕了嗎？",
  ui_story_1020_10200301_33_dialog_content = "不是……是「資訊」變換的速度太快了！",
  ui_story_1020_10200301_34_dialog_content = "……有看到什麼有用的資訊嗎？",
  ui_story_1020_10200301_35_dialog_content = "有用的資訊……",
  ui_story_1020_10200301_36_option_content = "好像有線條",
  ui_story_1020_10200301_37_dialog_content = "很多很多的線條……從上面落下來。",
  ui_story_1020_10200301_38_dialog_content = "但也可能不是線條……",
  ui_story_1020_10200301_39_dialog_content = "你這相當於什麼都沒說啊！",
  ui_story_1020_10200301_40_dialog_content = "啊！和原型機連接的為什麼不——是——我——？！",
  ui_story_1020_10200301_41_option_content = "有很多數字",
  ui_story_1020_10200301_42_dialog_content = "那些數字在快速移動！",
  ui_story_1020_10200301_43_dialog_content = "數字？0和1組成的數字？幾位數？有固定順序嗎？",
  ui_story_1020_10200301_44_dialog_content = "好像都有……",
  ui_story_1020_10200301_45_dialog_content = "至於位數和排序嘛，我看不清楚……",
  ui_story_1020_10200301_46_option_content = "完全看不清楚",
  ui_story_1020_10200301_47_dialog_content = "速度實在太快了，我還看不清楚就結束了。",
  ui_story_1020_10200301_48_dialog_content = "讓我再試一次吧！",
  ui_story_1020_10200301_49_dialog_content = "有了剛才的經歷，這次我會想辦法看清楚。",
  ui_story_1020_10200301_50_dialog_content = "不要勉強。布林是連我都還沒徹底搞懂的東西。",
  ui_story_1020_10200301_51_dialog_content = "如果你的身體感到不適，就立刻停下來。",
  ui_story_1020_10200301_52_dialog_content = "嗯，我知道了。",
  ui_story_1020_10200301_53_dialog_content = "其實自從之前回歸塔升起後，我的感應能力好像提升了不少。",
  ui_story_1020_10200301_54_dialog_content = "從高塔上迅速捕捉艾斯特拉大陸各個角落，不是用自己的眼睛看，而是借了環境的眼睛……",
  ui_story_1020_10200301_55_dialog_content = "聽起來有點抽象。你覺得用這種方法能看清楚布林的「資訊」？",
  ui_story_1020_10200301_56_dialog_content = "如果是借用環境的眼睛……",
  ui_story_1020_10200301_57_dialog_content = "我試試看吧！",
  ui_story_1020_10200301_58_option_content = "感應——開始——",
  ui_story_1020_10200301_59_dialog_content = "（好、好快！）",
  ui_story_1020_10200301_60_dialog_content = "（必須……跟上……）",
  ui_story_1020_10200301_61_dialog_content = "（呃啊——眼睛都快看花了——）",
  ui_story_1020_10200301_62_dialog_content = "（等等！不能用自己的眼睛，要用環境的眼睛……）",
  ui_story_1020_10200301_63_dialog_content = "（先看準一個序列，然後……）",
  ui_story_1020_10200301_64_option_content = "感應——延伸——",
  ui_story_1020_10200301_65_dialog_content = "（……）",
  ui_story_1020_10200301_66_dialog_content = "（沒錯，是數字……）",
  ui_story_1020_10200301_67_dialog_content = "（01105745630112……2311111……0010112231……）",
  ui_story_1020_10200301_68_dialog_content = "（如果阿爾戈爾能知道這些數字……應該能迅速破解密碼吧？）",
  ui_story_1020_10200301_69_dialog_content = "（但……根本記不住啊……）",
  ui_story_1020_10200301_70_dialog_content = "我看到了！一列一列的數字，像在下雨一樣！",
  ui_story_1020_10200301_71_dialog_content = "哇！裡面有寫通關密碼嗎？",
  ui_story_1020_10200301_72_dialog_content = "沒有那麼簡單啦……但通關密碼可能就在其中。",
  ui_story_1020_10200301_73_dialog_content = "空裔，你能在感應的同時將這些數字複述出來嗎？",
  ui_story_1020_10200301_74_dialog_content = "如果能獲得夠多資料，我或許可以試著用旁邊的電腦一起破解密碼。",
  ui_story_1020_10200301_75_dialog_content = "現在能分清楚是數字不是線條，就已經很極限了。要複述出來恐怕辦不到……",
  ui_story_1020_10200301_76_dialog_content = "而且……",
  ui_story_1020_10200301_77_dialog_content = "而且什麼？",
  ui_story_1020_10200301_78_dialog_content = "而且那麼多數字，妳應該無法全部記錄下來……",
  ui_story_1020_10200301_79_dialog_content = "你相信我嗎？",
  ui_story_1020_10200301_80_dialog_content = "當然相信……但妳為什麼這麼問？",
  ui_story_1020_10200301_81_dialog_content = "我有一種猜想……",
  ui_story_1020_10200301_82_dialog_content = "從巨像誕生人格那一刻起，這個複雜的「自動化工廠」便擁有了創造性和適應能力。",
  ui_story_1020_10200301_83_dialog_content = "創造性和適應能力，這正是我們的腦袋所具有的獨特能力。",
  ui_story_1020_10200301_84_dialog_content = "然而，雖然我們能靈活處理各種複雜的情景和問題，但這種創造性和適應力……",
  ui_story_1020_10200301_85_dialog_content = "恰恰「干擾」了機械化的運算過程，導致工作效率大大降低。",
  ui_story_1020_10200301_86_dialog_content = "如果你相信我，暫時放棄大腦的創造性和適應性。",
  ui_story_1020_10200301_87_dialog_content = "放棄大腦的創造性和適應性……怎麼放棄？",
  ui_story_1020_10200301_88_dialog_content = "簡單說就是暫時放棄思考，像機器一樣運作。",
  ui_story_1020_10200301_89_dialog_content = "這我倒沒試過……",
  ui_story_1020_10200301_90_dialog_content = "這是我在高強度工作時會用的方法。我也會和你一起將這些數字盡可能全部記錄下來。",
  ui_story_1020_10200301_91_dialog_content = "不要擔心資訊的衝擊，而是專注在過程。當夠多的資訊經過意識表面後，這些資訊就會留下痕跡。",
  ui_story_1020_10200301_92_dialog_content = "相信我，當你進入心流後，你會感覺時間無限拉長了。",
  ui_story_1020_10200301_93_dialog_content = "專注在過程……",
  ui_story_1020_10200301_94_dialog_content = "或許摔到地面上就能醒過來……",
  ui_story_1020_10200301_95_dialog_content = "……還在半空……？",
  ui_story_1020_10200301_96_dialog_content = "一旦接受必然墜地的心態，下墜過程似乎變得無比漫長……",
  ui_story_1020_10200301_97_dialog_content = "我好像理解妳的意思了。",
  ui_story_1020_10200301_98_dialog_content = "想起什麼了嗎？",
  ui_story_1020_10200301_99_dialog_content = "雖然嚴格來說也不是墜機……總之，我大概知道該怎麼做了。",
  ui_story_1020_10200301_100_option_content = "感應——深入——",
  ui_story_1020_10200301_101_dialog_content = "哎……PlayerName的眼珠動得好快啊……",
  ui_story_1020_10200301_102_dialog_content = "這麼神奇的PlayerName，真想看看他的腦袋裡到底裝了些什麼。",
  ui_story_1020_10200301_103_dialog_content = "我宣佈，從現在起，空裔就是我的研究助理了！事成之後，我要幫空裔做一套衣服！",
  ui_story_1020_10200301_104_dialog_content = "阿爾戈爾想跟空裔做朋友。",
  ui_story_1020_10200301_105_dialog_content = "不是他身上穿的那種衣服，是和你一樣的機械外殼。",
  ui_story_1020_10200301_106_dialog_content = "嗶嚕——",
  ui_story_1020_10200301_107_dialog_content = "11101100……",
  ui_story_1020_10200301_108_dialog_content = "有了有了！",
  ui_story_1020_10200301_109_dialog_content = "是二進位嗎？！",
  ui_story_1020_10200301_110_dialog_content = "010221111，022211110101……",
  ui_story_1020_10200301_111_dialog_content = "……不是？",
  ui_story_1020_10200301_112_dialog_content = "一號，快點錄音，以免漏掉！",
  ui_story_1020_10200301_113_dialog_content = "嗶嚕，一號知道了。",
  ui_story_1020_10200301_114_dialog_content = "貢露、薇薇安和彌加德也用身邊的電腦一起吧！集中精力，用光能來輔助。",
  ui_story_1020_10200301_115_dialog_content = "好！",
  ui_story_1020_10200301_116_dialog_content = "0101157567565500101……100150115332234560101……",
  ui_story_1020_10200301_117_dialog_content = "（5列……6列……7、8、9……）",
  ui_story_1020_10200301_118_dialog_content = "（這究竟有多少啊……）",
  ui_story_1020_10200301_119_dialog_content = "（等等……是我眼花了嗎？怎麼感覺有東西……在閃……）",
  ui_story_1020_10200301_120_dialog_content = "（糟糕糟糕……又開始思考了……）",
  ui_story_1020_10200301_121_dialog_content = "（唔——這麼快的速度，跟……上，好、好難受！）",
  ui_story_1020_10200401_1_dialog_content = "尤利西斯博士，您到底在……說什麼啊？",
  ui_story_1020_10200401_2_dialog_content = "你、鶯歌、阿克希亞。你們三個都是「啟明星計畫」的產物。",
  ui_story_1020_10200401_3_dialog_content = "……",
  ui_story_1020_10200401_4_dialog_content = "……",
  ui_story_1020_10200401_5_dialog_content = "「啟明星計畫」的產物，是像鶯歌一樣聰明，像阿克希亞一樣能把暗鬼揍飛的強大光靈吧……",
  ui_story_1020_10200401_6_dialog_content = "但我……",
  ui_story_1020_10200401_7_dialog_content = "你比你想像得強大，西恩。",
  ui_story_1020_10200401_8_dialog_content = "「強大」……這個字眼好像是第一次用在我身上呢……",
  ui_story_1020_10200401_9_dialog_content = "阿克希亞看招！嘿——！",
  ui_story_1020_10200401_10_dialog_content = "哎唷——！",
  ui_story_1020_10200401_11_dialog_content = "……",
  ui_story_1020_10200401_12_dialog_content = "我連和阿克希亞對拳，都會感到痛……「強大」嗎……",
  ui_story_1020_10200401_13_dialog_content = "新兵？小孩吧！黃昏鎮可不是你來的地方！",
  ui_story_1020_10200401_14_dialog_content = "……",
  ui_story_1020_10200401_15_dialog_content = "你這傢伙，在迦南城到底犯了什麼事才來到這？連這種程度的暗鬼都打不過！",
  ui_story_1020_10200401_16_dialog_content = "……",
  ui_story_1020_10200401_17_dialog_content = "雖然我沒資格說這些，但是我們都在艱苦的環境下努力磨練自己吧，西恩。",
  ui_story_1020_10200401_18_dialog_content = "我會的，長官……",
  ui_story_1020_10200401_19_dialog_content = "能力越強，責任越強。誰叫我比西恩「強大」呢，哈哈哈！你說是不是？",
  ui_story_1020_10200401_20_dialog_content = "可是……這裡是我負責的區域。",
  ui_story_1020_10200401_21_dialog_content = "沒關係，到時候我會跟班長說，這片區域的暗鬼太「強大」了。",
  ui_story_1020_10200401_22_dialog_content = "……",
  ui_story_1020_10200401_23_dialog_content = "跑快點，西恩！再快一點！",
  ui_story_1020_10200401_24_dialog_content = "……是、是！",
  ui_story_1020_10200401_25_dialog_content = "尤利西斯教授說，我是和鶯歌、阿克希亞一樣強大的光靈……",
  ui_story_1020_10200401_26_dialog_content = "但為什麼，只有我的雙手……",
  ui_story_1020_10200401_27_dialog_content = "佈滿了大大小小的繭呢……？",
  ui_story_1020_10200401_28_dialog_content = "這些在訓練中留下的印記……無論怎麼看，都只有我這樣一無是處的人身上才會有。",
  ui_story_1020_10200401_29_dialog_content = "不光雙手……還有許多地方，都是訓練留下的疤痕……",
  ui_story_1020_10200401_30_dialog_content = "是我訓練得還不夠嗎？",
  ui_story_1020_10200401_31_dialog_content = "西恩……",
  ui_story_1020_10200401_32_dialog_content = "將你送往黃昏鎮，確實是因為你在實驗早期被判定為「失敗品」。",
  ui_story_1020_10200401_33_dialog_content = "但實驗的初始階段，出現各種誤判都在所難免。",
  ui_story_1020_10200401_34_dialog_content = "「失敗品」……",
  ui_story_1020_10200401_35_dialog_content = "我果然因為是失敗品才去到黃昏鎮的啊……哈哈……",
  ui_story_1020_10200401_36_dialog_content = "西恩，別聽尤利西斯胡說八道。這不是你的錯。",
  ui_story_1020_10200401_37_dialog_content = "在這場計畫裡，我們所有人都是「失敗品」。",
  ui_story_1020_10200401_38_dialog_content = "謝謝大元帥安慰我。但我都知道的……我終歸和大家不一樣……",
  ui_story_1020_10200401_39_dialog_content = "問他，送往黃昏鎮的「失敗品」如何成為啟光未來的潛力？",
  ui_story_1020_10200401_40_dialog_content = "說重點，尤利西斯。",
  ui_story_1020_10200401_41_dialog_content = "果然是「鐵面」……",
  ui_story_1020_10200401_42_dialog_content = "我們確實在中途放棄了對西恩的研究，但是當他前往距離暗面更近的黃昏鎮後，他的身體發生了變化。",
  ui_story_1020_10200401_43_dialog_content = "透過持續驗證，我發現西恩的光能術並非受基因缺陷所限制。正好相反，他是能「吸收暗能」。",
  ui_story_1020_10200401_44_dialog_content = "雖然這些暗能無法轉化成光能來利用，但這讓他在對抗暗鬼的過程中，有了強大的身體屏障。",
  ui_story_1020_10200401_45_dialog_content = "事實上，之前在佩皮塔的帶領下前往暗面探索的那些人，也有類似的特點。",
  ui_story_1020_10200401_46_dialog_content = "學術方面的細節我就不多介紹了。如果要戰勝暗鬼，他們將是光靈的希望所在！",
  ui_story_1020_10200401_47_dialog_content = "機體增強的實驗方案我已經寫好了，相信要不了多久，這一批產物就能前往暗面了。",
  ui_story_1020_10200401_48_dialog_content = "開什麼玩笑，尤利西斯？！啟光豈能放任你繼續胡搞下去？",
  ui_story_1020_10200401_49_dialog_content = "西恩！我必須告訴你，西恩——",
  ui_story_1020_10200401_50_dialog_content = "你從檔案中得知的身世，或許是啟光軍人從暗鬼手中救出你，將你送進育幼院。",
  ui_story_1020_10200401_51_dialog_content = "但是把你帶到暗鬼身邊希望你死去的，正是你的父母！",
  ui_story_1020_10200401_52_dialog_content = "他們因身體缺陷受盡折磨，於是才希望讓尚不懂事的你早點解脫。",
  ui_story_1020_10200401_53_dialog_content = "但正是因為「啟明星計畫」，你不再需要承受痛苦。",
  ui_story_1020_10200401_54_dialog_content = "是我對你進行身體改造，給予你第二次生命。你想成為被認可的「強大」的人，就必須——",
  ui_story_1020_10200401_55_dialog_content = "尤利西斯教授……您要做什麼？",
  ui_story_1020_10200401_56_dialog_content = "深入暗面，討伐暗鬼的希望，答應我——",
  ui_story_1020_10200401_57_dialog_content = "與其在黃昏鎮做個不起眼的士兵，不如發揮你的基因優勢，做一名深入日蝕內部的光靈英雄！",
  ui_story_1020_10200401_58_dialog_content = "到那時……剿滅暗鬼，親眼看看那個躲在暗處的惡魔……",
  ui_story_1020_10200401_59_dialog_content = "尤利西斯，站住！",
  ui_story_1020_10200401_60_dialog_content = "不許靠近西恩，教授！",
  ui_story_1020_10200401_61_dialog_content = "您在實驗中不惜犧牲他人生命，如今卻想說服西恩是您拯救了他。",
  ui_story_1020_10200401_62_dialog_content = "您冷酷自私的樣子，讓我……讓我感到噁心！",
  ui_story_1020_10200401_63_dialog_content = "現在，沒有人能放棄、奪去，甚至左右西恩的性命！",
  ui_story_1020_10200401_64_dialog_content = "沒有人能放棄、奪去，甚至左右西恩的性命！",
  ui_story_1020_10200401_65_dialog_content = "……鶯歌、阿克希亞，妳們不用把我圍得那麼緊啦……嘿嘿……",
  ui_story_1020_10200401_66_dialog_content = "尤利西斯教授說，是我的父母帶著我衝向暗鬼。",
  ui_story_1020_10200401_67_dialog_content = "以前我總告訴自己那是夢……",
  ui_story_1020_10200401_68_dialog_content = "那麼深刻的感受……怎麼可能是夢呢……哈哈…",
  ui_story_1020_10200401_69_dialog_content = "但是我仍然想用「父母為了救我而英勇犧牲」來回憶那一天。",
  ui_story_1020_10200401_70_dialog_content = "雖然很愚蠢……但是惟有靠著這種愚蠢的想法，才能樂觀地活下去，不是嗎？",
  ui_story_1020_10200401_71_dialog_content = "那時發生的事情已經不重要了，西恩。",
  ui_story_1020_10200401_72_dialog_content = "你是黃昏鎮，不——是啟光優秀的戰士！",
  ui_story_1020_10200401_73_dialog_content = "現在的西恩和阿克希亞一樣，是能斬殺很多暗鬼的啟光軍人。",
  ui_story_1020_10200401_74_dialog_content = "雖然這麼說很自私，但是阿克希亞覺得，西恩不需要當戰士，也不需要當英雄……",
  ui_story_1020_10200401_75_dialog_content = "做西恩自己就可以了。",
  ui_story_1020_10200401_76_dialog_content = "哈哈哈哈！你們難道想再次迎來遠古戰爭的失敗結局嗎？",
  ui_story_1020_10200401_77_dialog_content = "這個世界沒有那麼簡單……我親眼目睹過日蝕的力量。我知道唯有這樣，光靈才有出路。",
  ui_story_1020_10200401_78_dialog_content = "你為了科技不惜犧牲同胞的性命！你是在毀滅啟光、毀滅光靈！",
  ui_story_1020_10200401_79_dialog_content = "區區戰爭兵器，也配跟我談犧牲與毀滅……？",
  ui_story_1020_10200401_80_dialog_content = "我真羡慕吞羅，年紀輕輕就提出光能與暗能中蘊藏著神祕力量的猜想，並踐行自己的理想。",
  ui_story_1020_10200401_81_dialog_content = "而你們只願相信情感的力量，去強調那些無關緊要的死亡……",
  ui_story_1020_10200401_82_dialog_content = "是個人情感作祟，束縛住光靈前進的動力……",
  ui_story_1020_10200401_83_dialog_content = "是你們的愚昧，導致更多的人犧牲……",
  ui_story_1020_10200401_84_dialog_content = "讓光靈怕死……只能等死……",
  ui_story_1020_10200401_85_dialog_content = "但我，不願成為情感主義的奴隸……",
  ui_story_1020_10200401_86_dialog_content = "絕不！",
  ui_story_1020_10200401_87_dialog_content = "我會習慣……",
  ui_story_1020_10200401_88_dialog_content = "習慣每分每秒都有光靈死去！死幾十人！成千上萬人！",
  ui_story_1020_10200401_89_dialog_content = "把眼前的人當作終將腐爛的白骨，然後跨越……去創造內心和身體都強大的光靈！",
  ui_story_1020_10200401_90_dialog_content = "你們聽過……「進化」吧？光靈必須進化……",
  ui_story_1020_10200401_91_dialog_content = "每一分、每一秒都得進化……",
  ui_story_1020_10200401_92_dialog_content = "只有這樣，我們才能在末日存活！才能睜大雙眼，帶著這副強大的身體……",
  ui_story_1020_10200401_93_dialog_content = "飛……升……",
  ui_story_1020_10200401_94_dialog_content = "長官您、您沒事吧……？",
  ui_story_1020_10200401_95_dialog_content = "「進化」，多麼美妙的詞彙……",
  ui_story_1020_10200401_96_dialog_content = "每一分、每一秒都得進化……",
  ui_story_1020_10200401_97_dialog_content = "尤利西斯長官——！",
  ui_story_1020_10200401_98_dialog_content = "瘋了？",
  ui_story_1020_10200401_99_dialog_content = "如果不是親眼看見……我都不會相信……",
  ui_story_1020_10200401_100_dialog_content = "他怎麼了？",
  ui_story_1020_10200401_101_dialog_content = "這就是我堅持傳喚我的證人錢德菈的原因。",
  ui_story_1020_10200401_102_dialog_content = "大元帥，我一直在旁邊。",
  ui_story_1020_10200401_103_dialog_content = "把尤利西斯的情況告訴大家。",
  ui_story_1020_10200401_104_dialog_content = "好的，大元帥。尤利西斯博士在接受心理治療期間，偶爾會出現這樣雙目無神地看著一個方向的情況……",
  ui_story_1020_10200401_105_dialog_content = "但過一會之後，又會像什麼事都沒發生一樣。",
  ui_story_1020_10200401_106_dialog_content = "……",
  ui_story_1020_10200401_107_dialog_content = "證人錢德菈，接著說……",
  ui_story_1020_10200401_108_dialog_content = "尤利西斯教授在十年前開始接受心理治療，這是教授的治療記錄。",
  ui_story_1020_10200401_109_dialog_content = "我當時雖然沒有參與，但從他過往的治療記錄可知，當時正是暗鬼大軍大力滲透各個勢力的時候。",
  ui_story_1020_10200401_110_dialog_content = "而在軍演之前幾個月，尤利西斯教授到醫療中心接受心理治療的次數又增加了。",
  ui_story_1020_10200401_111_dialog_content = "隨後，啟光嫌犯吞羅潛入了X號研究所，而罪靈也從迦南城竊走了「守護者一號」核心。",
  ui_story_1020_10200401_112_dialog_content = "這兩個關鍵節點，都有尤利西斯博士牽涉其中。我們懷疑，尤利西斯與日蝕有特殊的關係。",
  ui_story_1020_10200401_113_dialog_content = "……",
  ui_story_1020_10200401_114_dialog_content = "引起我注意的是，尤利西斯診療中描述了一些奇怪場景……",
  ui_story_1020_10200401_115_dialog_content = "冰柱不是降水的凝結，而是巨石在上升……",
  ui_story_1020_10200401_116_dialog_content = "驅動元耗盡，連結中斷，但唯一的眼睛還在上空注視……",
  ui_story_1020_10200401_117_dialog_content = "上升的冰柱、驅動元……注視的眼睛……",
  ui_story_1020_10200401_118_dialog_content = "這種場景和艾斯特拉大陸完全相悖，他一個從未走出過迦南城的人，怎麼可能會知道？",
  ui_story_1020_10200401_119_dialog_content = "我不相信妳不會心生懷疑，貝利撒留！這根本不可能是巧合！",
  ui_story_1020_10200401_120_dialog_content = "她為什麼這麼肯定？",
  ui_story_1020_10200401_121_dialog_content = "證據？",
  ui_story_1020_10200401_122_dialog_content = "因為曾經的暗鬼——深入過暗面的赫利俄斯，在回憶錄中也是這樣寫的！",
  ui_story_1020_10200401_123_dialog_content = "委員會始終用他「意識尚未恢復」當作藉口，拖延我洗清嫌疑。",
  ui_story_1020_10200401_124_dialog_content = "但如果這和我對尤利西斯的指控吻合，你們又作何解釋？",
  ui_story_1020_10200401_125_dialog_content = "這讓我想起「那個」，你們呢？",
  ui_story_1020_10200401_126_dialog_content = "那個罪靈？",
  ui_story_1020_10200401_127_dialog_content = "原來他說的是這個意思……",
  ui_story_1020_10200401_128_dialog_content = "……",
  ui_story_1020_10200401_129_dialog_content = "你們不必在我身上浪費時間。",
  ui_story_1020_10200401_130_dialog_content = "等祂降臨後，沒有佩戴「圓環」的傢伙只配匍匐在地，因恐懼和渺小而泯滅。",
  ui_story_1020_10200401_131_dialog_content = "「圓環」是什麼？！",
  ui_story_1020_10200401_132_dialog_content = "還妄想獲得祂的「圓環」嗎？賤畜、強盜、寄生蟲！",
  ui_story_1020_10200401_133_dialog_content = "六百年前，那座浮空島本是我晉升的底座！",
  ui_story_1020_10200401_134_dialog_content = "浮空島……是指白夜城？",
  ui_story_1020_10200401_135_dialog_content = "待祂降臨後，將再次賜我晉升之榮光！我會重回殿堂，重回祂的懷抱。",
  ui_story_1020_10200401_136_dialog_content = "你們，為什麼要與光靈為敵？",
  ui_story_1020_10200401_137_dialog_content = "當然是因為光靈需索無度——將祂的造物占為己有！",
  ui_story_1020_10200401_138_dialog_content = "祂，終會拿回祂建造的一切！",
  ui_story_1020_10200401_139_dialog_content = "桀桀桀桀桀——！！！",
  ui_story_1020_10200401_140_dialog_content = "……",
  ui_story_1020_10200401_141_dialog_content = "一切的源頭都指向那部……啟光建立之初就存在的遠古機器。",
  ui_story_1020_10200401_142_dialog_content = "這就是啟光的宿命？呵呵……",
  ui_story_1020_10200401_143_dialog_content = "那部機器在哪？",
  ui_story_1020_10200401_144_dialog_content = "一間倉庫裡。你看好的天才正盯著呢。",
  ui_story_1020_10200401_145_dialog_content = "「進化」，多麼美妙的詞彙。",
  ui_story_1020_10200401_146_dialog_content = "每一分、每一秒都得進化……",
  ui_story_1020_10200401_147_dialog_content = "……",
  ui_story_1020_10200501_1_dialog_content = "……就是這些嗎？",
  ui_story_1020_10200501_2_dialog_content = "對比過了，沒有漏喔。阿爾戈爾博士覺得少了什麼嗎？",
  ui_story_1020_10200501_3_dialog_content = "確實比我想得更少。這些數列是循環出現的……或許是某種有限文字的組合。",
  ui_story_1020_10200501_4_dialog_content = "而且，最早的電腦語言是從「守護者」系統中來的。無論怎麼演化，語言規則也都是相通的。",
  ui_story_1020_10200501_5_dialog_content = "我的程式可以根據這些數據分析出組合邏輯。",
  ui_story_1020_10200501_6_dialog_content = "很快，我就可以運用這幾部電腦和布林一起登入完整的「守護者」系統了。很快！",
  ui_story_1020_10200501_7_dialog_content = "既然是有限的文字組合，PlayerName怎麼還沒有結束感應？他不會有事吧？",
  ui_story_1020_10200501_8_dialog_content = "對耶！他的頭髮都飄起來了……這個狀態，看起來很像那個什麼東西，我想不起來了。",
  ui_story_1020_10200501_9_dialog_content = "馬上……馬上……",
  ui_story_1020_10200501_10_dialog_content = "布布！",
  ui_story_1020_10200501_11_dialog_content = "好！",
  ui_story_1020_10200501_12_dialog_content = "只要照順序輸入……",
  ui_story_1020_10200501_13_dialog_content = "<color=#e8d9bb>嗶——嗶——嗶——</color>",
  ui_story_1020_10200501_14_dialog_content = "……不對？",
  ui_story_1020_10200501_15_dialog_content = "想起來了！ 是布林，手下敗將現在的頭髮，跟布林的觸手一模一樣！",
  ui_story_1020_10200501_16_dialog_content = "PlayerName的腦袋不會也跟布林一樣，是一台算力強大的機器吧？",
  ui_story_1020_10200501_17_dialog_content = "阿爾戈爾博士，我擔心PlayerName有危險！",
  ui_story_1020_10200501_18_dialog_content = "……有再強的感應能力，畢竟不是電腦啊……",
  ui_story_1020_10200501_19_dialog_content = "我們把他——",
  ui_story_1020_10200501_20_dialog_content = "85……X……32875……X……",
  ui_story_1020_10200501_21_dialog_content = "啊？！",
  ui_story_1020_10200501_22_dialog_content = "他在唸什麼？",
  ui_story_1020_10200501_23_dialog_content = "……「X」？",
  ui_story_1020_10200501_24_dialog_content = "不只是數字序列……？",
  ui_story_1020_10200501_25_dialog_content = "3292……X……4782……X……2212323293845……",
  ui_story_1020_10200501_26_dialog_content = "滿臉通紅，簡直像觸電了一樣！",
  ui_story_1020_10200501_27_dialog_content = "……12983289……X……",
  ui_story_1020_10200501_28_dialog_content = "50227833……X……",
  ui_story_1020_10200501_29_dialog_content = "這個傢伙難道跟上了布林的運算速度……這樣下去他會有危險……",
  ui_story_1020_10200501_30_dialog_content = "……但如果現在結束的話，就很難再得知這些數據了……",
  ui_story_1020_10200501_31_dialog_content = "這樣吧！讓他戴上我的手環兩分鐘試試看。",
  ui_story_1020_10200501_32_dialog_content = "……這能起什麼作用？",
  ui_story_1020_10200501_33_dialog_content = "兩分鐘是腦細胞高速運轉的極限，這個東西能監測佩戴者的身體狀況。",
  ui_story_1020_10200501_34_dialog_content = "如果資訊超過他的身體負荷，手環會示警。",
  ui_story_1020_10200501_35_dialog_content = "在那之前，貢露、一號，請再次和我一起記錄。我們盡可能在兩分鐘內記錄下可用的資訊。",
  ui_story_1020_10200501_36_dialog_content = "哪怕只是一部分也行，這可能是我目前唯一能接觸到的原型機深層資訊！",
  ui_story_1020_10200501_37_dialog_content = "沒問題！",
  ui_story_1020_10200501_38_dialog_content = "一號知道了。",
  ui_story_1020_10200501_39_dialog_content = "薇薇安，妳看著時間，兩分鐘一到我們立刻停止。",
  ui_story_1020_10200501_40_dialog_content = "嗯。",
  ui_story_1020_10200501_41_dialog_content = "彌加德，兩分鐘內如果手環示警，妳把PlayerName直接扛走。",
  ui_story_1020_10200501_42_dialog_content = "包在我身上！",
  ui_story_1020_10200501_43_dialog_content = "862033934……X……",
  ui_story_1020_10200501_44_dialog_content = "385782493666……X……",
  ui_story_1020_10200501_45_dialog_content = "嗶嚕、嗶嚕、嗶嚕……",
  ui_story_1020_10200501_46_dialog_content = "236758423423……X……",
  ui_story_1020_10200501_47_dialog_content = "（「X」？）",
  ui_story_1020_10200501_48_dialog_content = "（那個閃爍的字母是「X」？沒看錯吧？）",
  ui_story_1020_10200501_49_dialog_content = "（唔……應該已經過去很久了……）",
  ui_story_1020_10200501_50_dialog_content = "（我的腦袋好像沒剛才那麼痛了！）",
  ui_story_1020_10200501_51_dialog_content = "（但這個「X」到底是什麼啊……）",
  ui_story_1020_10200501_52_dialog_content = "（啊啊啊……又加速了……）",
  ui_story_1020_10200502_1_dialog_content = "布布！布布！布布！",
  ui_story_1020_10200502_2_dialog_content = "剛好兩分鐘。",
  ui_story_1020_10200502_3_dialog_content = "很好！",
  ui_story_1020_10200502_4_dialog_content = "布布布！布布、布布——",
  ui_story_1020_10200502_5_dialog_content = "好、好噢……慢點、慢點……",
  ui_story_1020_10200502_6_dialog_content = "那麼接下來，就用這幾部機器平行解析這些數據，這次一定沒問題。",
  ui_story_1020_10200502_7_dialog_content = "布！",
  ui_story_1020_10200502_8_dialog_content = "呃啊——",
  ui_story_1020_10200502_9_dialog_content = "你沒事吧，PlayerName？",
  ui_story_1020_10200502_10_dialog_content = "……哇！血壓這麼高！血氧飽和度……你還看得到我們嗎？",
  ui_story_1020_10200502_11_dialog_content = "看、看得到……",
  ui_story_1020_10200502_12_dialog_content = "先坐下，別動。眼睛跟著我手指的方向移動。",
  ui_story_1020_10200502_13_dialog_content = "左……右……",
  ui_story_1020_10200502_14_dialog_content = "現在，感覺怎麼樣？",
  ui_story_1020_10200502_15_dialog_content = "感覺……腦袋——呼，暈暈的……四肢軟綿綿的……",
  ui_story_1020_10200502_16_dialog_content = "沒有噁心、眼花的情況嗎？",
  ui_story_1020_10200502_17_dialog_content = "好像沒有……",
  ui_story_1020_10200502_18_dialog_content = "把這個喝下去。",
  ui_story_1020_10200502_19_dialog_content = "這是什麼？",
  ui_story_1020_10200502_20_dialog_content = "大腦高速運轉之後通常會伴隨缺氧症狀，我也算是這方面的專家了。",
  ui_story_1020_10200502_21_dialog_content = "但沒想到，你的感應能力竟能做到這個程度，真是幫了我大忙了！",
  ui_story_1020_10200502_22_dialog_content = "我也沒想到……起初數字變換太快了，為了看清楚，我只是盯著一個數位序列有點難受。",
  ui_story_1020_10200502_23_dialog_content = "在我不糾結於看清楚單一個序列，像妳說的「放棄思考」後……那些數字反而自然就「流」過來了……",
  ui_story_1020_10200502_24_dialog_content = "中途我還停下來思考了一下……",
  ui_story_1020_10200502_25_dialog_content = "但它好像發現我在思考似的，又開始加速了……",
  ui_story_1020_10200502_26_dialog_content = "快……慢……思考……然後加速……一個完整的學習反射弧……",
  ui_story_1020_10200502_27_dialog_content = "等等，不是都放棄思考了嗎？怎麼還能看清楚啊，你到底是什麼怪物……？！",
  ui_story_1020_10200502_28_dialog_content = "你這傢伙……真的不是人工智慧體嗎？",
  ui_story_1020_10200502_29_dialog_content = "怎、怎麼會有這種疑問……",
  ui_story_1020_10200502_30_dialog_content = "對了，數字中出現的「X」是什麼呀？",
  ui_story_1020_10200502_31_dialog_content = "我應該……沒唸錯吧？",
  ui_story_1020_10200502_32_dialog_content = "沒唸錯……",
  ui_story_1020_10200502_33_dialog_content = "但……這麼關鍵的資訊目前只能交給布林了。交給同樣是遠古機器一部分的布林……",
  ui_story_1020_10200502_34_dialog_content = "阿爾戈爾也無能為力。",
  ui_story_1020_10200502_35_dialog_content = "……真是被遠古科技遠遠地甩在後面啊……",
  ui_story_1020_10200502_36_dialog_content = "發明這部機器的傢伙，你到底是人還是神啊——？哈哈哈哈！",
  ui_story_1020_10200502_37_dialog_content = "……",
  ui_story_1020_10200502_38_dialog_content = "就啟光來說，我們的電腦還停留在以二進位為基礎，已經六百多年了！",
  ui_story_1020_10200502_39_dialog_content = "無論是物理材料的穩態數量，還是數學層面的運算邏輯……我們一直認為二進位是計算機的最佳解。",
  ui_story_1020_10200502_40_dialog_content = "但是這部機器……它最底層的語言竟然有除了0和1以外的其他數字！不只是三進位、四進位……",
  ui_story_1020_10200502_41_dialog_content = "甚至還有一個「X」？這是我完全無法理解的科技……「X」！「X」？",
  ui_story_1020_10200502_42_dialog_content = "像不像對我的嘲笑？！哈哈哈哈！",
  ui_story_1020_10200502_43_dialog_content = "它到底是怎麼運作的？內部又在處理多複雜的邏輯？",
  ui_story_1020_10200502_44_dialog_content = "遠古時代到底發生了什麼事？！",
  ui_story_1020_10200502_45_dialog_content = "為什麼一切都不在了，只有空裔、暗鬼、光靈活下來？",
  ui_story_1020_10200502_46_dialog_content = "噢……！我差點忘了……還有光之神！還有真理之主！或許邪典上有答案？！",
  ui_story_1020_10200502_47_dialog_content = "呵呵……哈哈哈哈……",
  ui_story_1020_10200502_48_dialog_content = "她怎麼了？突然好恐怖的樣子……",
  ui_story_1020_10200502_49_dialog_content = "阿爾戈爾發現自己太不中用了。",
  ui_story_1020_10200502_50_dialog_content = "怎麼可能？開什麼玩笑？！我自己講出來都想笑……",
  ui_story_1020_10200502_51_dialog_content = "哈哈哈哈……！",
  ui_story_1020_10200502_52_dialog_content = "一號！我不管他是什麼邪神惡鬼！",
  ui_story_1020_10200502_53_dialog_content = "這個世界不講先來後到！我可不要把我的疑問丟給那些早已死透的東西！",
  ui_story_1020_10200502_54_dialog_content = "就算我現在還解不開其中的奧祕，但我會繼續研究和開發「守護者」系統。",
  ui_story_1020_10200502_55_dialog_content = "你聽到了沒有？！",
  ui_story_1020_10200502_56_dialog_content = "一號聽到了，各種意義上都聽到了。",
  ui_story_1020_10200502_57_dialog_content = "布布！",
  ui_story_1020_10200502_58_dialog_content = "好！布林！交給你了！",
  ui_story_1020_10200502_59_dialog_content = "……布布……",
  ui_story_1020_10200502_60_dialog_content = "這一刻，終於來了……",
  ui_story_1020_10200502_61_dialog_content = "一起進入BOSS關吧！",
  ui_story_1020_10200502_62_dialog_content = "……",
  ui_story_1020_10200502_63_dialog_content = "這算什麼？",
  ui_story_1020_10200502_64_dialog_content = "空裔。",
  ui_story_1020_10200502_65_dialog_content = "……",
  ui_story_1020_10200502_66_dialog_content = "剛剛腦子裡閃過的……不是夢境嗎？",
  ui_story_1020_10200502_67_dialog_content = "那個黑色的太陽……和原型機有關聯？",
  ui_story_1020_10200601_1_dialog_content = "你說你在夢中看到的那個圓環……",
  ui_story_1020_10200601_2_dialog_content = "有罪靈，還有薇絲？",
  ui_story_1020_10200601_3_dialog_content = "嗯……",
  ui_story_1020_10200601_4_dialog_content = "尤利西斯使用的原型機，難道是日蝕造物……阿爾戈爾博士，妳認為這之中有關聯嗎？",
  ui_story_1020_10200601_5_dialog_content = "當然……哈哈哈哈哈哈哈！",
  ui_story_1020_10200601_6_dialog_content = "……",
  ui_story_1020_10200601_7_dialog_content = "……你們這是什麼表情？",
  ui_story_1020_10200601_8_dialog_content = "這可是啟光自建立以來，賴以生存的遠古科技啊……",
  ui_story_1020_10200601_9_dialog_content = "如果這是日蝕的東西……那不是很危險嗎？",
  ui_story_1020_10200601_10_dialog_content = "空裔。",
  ui_story_1020_10200601_11_dialog_content = "（又出現了……）",
  ui_story_1020_10200601_12_dialog_content = "至少我瀏覽完之後，還沒發現和我的虛擬機器有什麼差別。",
  ui_story_1020_10200601_13_dialog_content = "如果有其他存放超級兵的地點，恐怕也沒有記錄在原型機上。",
  ui_story_1020_10200601_14_dialog_content = "但原型機上的符號與PlayerName的夢境似乎有某種關聯，謎團好像越來越多了……",
  ui_story_1020_10200601_15_dialog_content = "正好相反，我倒是覺得越來越清晰了。",
  ui_story_1020_10200601_16_dialog_content = "起初覺得尤利西斯就是個無可救藥的自大狂。看到這東西後，我對他的看法反而改觀了。",
  ui_story_1020_10200601_17_dialog_content = "這麼多年來，迦南城都沒有毀滅……他堅持做那些實驗，真的只是因為他喪心病狂嗎？",
  ui_story_1020_10200601_18_dialog_content = "參謀長，我現在想請尤利西斯來這裡。",
  ui_story_1020_10200601_19_dialog_content = "這個……恐怕委員會目前不會同意。我可以試著聯絡看看大元帥……",
  ui_story_1020_10200601_20_dialog_content = "……",
  ui_story_1020_10200601_21_dialog_content = "但現在最瞭解這部機器的人，就是尤利西斯。",
  ui_story_1020_10200601_22_dialog_content = "布林還能幫忙調取搭建核心需要的模組數據，而我們剛剛記錄的資訊只是輔助計算而已。",
  ui_story_1020_10200601_23_dialog_content = "原型機曾一直封存，我不知道之後的研究還會不會受到限制。",
  ui_story_1020_10200601_24_dialog_content = "空裔。",
  ui_story_1020_10200601_25_dialog_content = "……",
  ui_story_1020_10200601_26_dialog_content = "你沒事吧，PlayerName？",
  ui_story_1020_10200601_27_dialog_content = "我……我剛剛好像看到有東西閃過……",
  ui_story_1020_10200601_28_dialog_content = "什麼東西？",
  ui_story_1020_10200601_29_dialog_content = "布布！布布！布布！",
  ui_story_1020_10200601_30_dialog_content = "<color=#e8d9bb>嗶——嗶——嗶——</color>",
  ui_story_1020_10200601_31_dialog_content = "鎖住了？",
  ui_story_1020_10200601_32_dialog_content = "<color=#e8d9bb>轟隆隆——</color>",
  ui_story_1020_10200601_33_dialog_content = "咿呀——怎麼回事啊？",
  ui_story_1020_10200601_34_dialog_content = "是倉庫在震動……！",
  ui_story_1020_10200601_35_dialog_content = "……",
  ui_story_1020_10200601_36_dialog_content = "稍等……既然能調取模組數據，不應該鎖住啊……",
  ui_story_1020_10200601_37_dialog_content = "布布！布布！布布！",
  ui_story_1020_10200601_38_dialog_content = "<color=#e8d9bb>轟隆隆——</color>",
  ui_story_1020_10200601_39_dialog_content = "布林之前不是在調取原型機的防禦程式碼來搭建新的核心嗎？",
  ui_story_1020_10200601_40_dialog_content = "是補上防禦漏洞出現的反應嗎？",
  ui_story_1020_10200601_41_dialog_content = "照理說是這樣沒錯，但這晃動的程度也太大了吧！",
  ui_story_1020_10200601_42_dialog_content = "<color=#e8d9bb>轟隆隆——</color>",
  ui_story_1020_10200601_43_dialog_content = "布布！布布！布布！",
  ui_story_1020_10200601_44_dialog_content = "沒錯！這可能是調取「守護者」模組數據後，有東西開始攻擊我的電腦，進而攻擊啟光的防禦系統。",
  ui_story_1020_10200601_45_dialog_content = "遊戲照進現實？數位入侵？",
  ui_story_1020_10200601_46_dialog_content = "等等……等等……防禦模組……防禦模組……",
  ui_story_1020_10200601_47_dialog_content = "你們先檢查一下四周的情況，我重新調取防禦模組看看。",
  ui_story_1020_10200601_48_dialog_content = "如果「守護者」不是在補上防禦，而是進一步瓦解……",
  ui_story_1020_10200601_49_dialog_content = "那地下城就危險了……",
  ui_story_1020_10200601_50_dialog_content = "不是。是原型機裡，或是它的另一頭有東西在和我們對抗。",
  ui_story_1020_10200601_51_dialog_content = "……",
  ui_story_1020_10200601_52_dialog_content = "原型機裡……或是它的另一頭？是誰？",
  ui_story_1020_10200601_53_dialog_content = "只有尤利西斯才知道了……",
  ui_story_1020_10200601_54_dialog_content = "<color=#e8d9bb>嗶——嗶——嗶——</color>",
  ui_story_1020_10200601_55_dialog_content = "可惡！竟然封鎖了我的路徑！",
  ui_story_1020_10200601_56_dialog_content = "<color=#e8d9bb>轟隆隆——！！！</color>",
  ui_story_1020_10200601_57_dialog_content = "<color=#e8d9bb>嗶——</color>",
  ui_story_1020_10200601_58_dialog_content = "<color=#e8d9bb>嗶——</color>",
  ui_story_1020_10200601_59_dialog_content = "<color=#e8d9bb>嗶嗶嗶——</color>",
  ui_story_1020_10200601_60_dialog_content = "……一下子收到那麼多終端訊息……",
  ui_story_1020_10200601_61_dialog_content = "隧道……十號城門……阿爾戈爾博士，情況比我想像得還糟！",
  ui_story_1020_10200601_62_dialog_content = "地下城多個防禦系統都遭到攻擊了！",
  ui_story_1020_10200601_63_dialog_content = "……應該有不少控制開關被凍結了。參謀長，外面的情況要請你們暫時先撐一下！",
  ui_story_1020_10200601_64_dialog_content = "布林，重啟模組！",
  ui_story_1020_10200601_65_dialog_content = "布！",
  ui_story_1020_10200601_66_dialog_content = "貢露、彌加德，妳們去實驗大樓檢查控制台，特別是有倉庫和大型實驗設施的地方。",
  ui_story_1020_10200601_67_dialog_content = "部分依賴它的開關，我們只能暫時手動控制了！",
  ui_story_1020_10200601_68_dialog_content = "我先向傳訊息來的各位問清楚狀況，然後聯絡大元帥！",
  ui_story_1020_10200601_69_dialog_content = "PlayerName，你感官比較敏銳，發現危險立刻提醒大家！",
  ui_story_1020_10200601_70_dialog_content = "沒問題！",
  ui_story_1020_10200601_71_dialog_content = "（這和剛剛閃過的那個畫面有關嗎……）",
  ui_story_1020_10200601_72_dialog_content = "<color=#e8d9bb>啟光某隧道施工隊</color>",
  ui_story_1020_10200601_73_dialog_content = "<color=#e8d9bb>轟隆隆——！！！</color>",
  ui_story_1020_10200601_74_dialog_content = "琪爾！琪爾——！！！",
  ui_story_1020_10200601_75_dialog_content = "快從裡面出來！！！",
  ui_story_1020_10200601_76_dialog_content = "唔……？",
  ui_story_1020_10200601_77_dialog_content = "這麼劇烈的晃動妳感覺不到嗎？隧道前面坍方啦！",
  ui_story_1020_10200601_78_dialog_content = "唔……現在亂跑的話，更容易發生危險……",
  ui_story_1020_10200601_79_dialog_content = "……總之，琪爾先啟動動力裝甲了。",
  ui_story_1020_10200601_80_dialog_content = "<color=#e8d9bb>啟光醫療中心</color>",
  ui_story_1020_10200601_81_dialog_content = "<color=#e8d9bb>轟隆隆——！！！</color>",
  ui_story_1020_10200601_82_dialog_content = "這個動靜……",
  ui_story_1020_10200601_83_dialog_content = "又是因為我……而把大家吵醒的嗎？",
  ui_story_1020_10200601_84_dialog_content = "……",
  ui_story_1020_10200601_85_dialog_content = "不……這次不是……",
  ui_story_1020_10200601_86_dialog_content = "我還躺在床上……",
  ui_story_1020_10200601_87_dialog_content = "萊因哈特……我多希望，我能為啟光做些什麼……",
  ui_story_1020_10200601_88_dialog_content = "<color=#e8d9bb>嗶——</color>",
  ui_story_1020_10200601_89_dialog_content = "大元帥！您終於——！",
  ui_story_1020_10200601_90_dialog_content = "抱歉讓你久等了。",
  ui_story_1020_10200601_91_dialog_content = "科技園區一間倉庫裡有危險的機器，你們現在在哪？",
  ui_story_1020_10200601_92_dialog_content = "我們在零號倉庫，這裡已經被尤利西斯私自啟用了！",
  ui_story_1020_10200601_93_dialog_content = "零號倉庫？！",
  ui_story_1020_10200601_94_dialog_content = "這裡存放著超級兵！還有一台似乎與日蝕有關的遠古機器。這個震動正是那部機器引起的！",
  ui_story_1020_10200601_95_dialog_content = "先離開！",
  ui_story_1020_10200601_96_dialog_content = "所有人，現在立刻離開！",
  ui_story_1020_10200601_97_dialog_content = "阿爾戈爾博士……",
  ui_story_1020_10200601_98_dialog_content = "先穩住那些開關！要徹底解決防禦漏洞，必須搭建新的核心，這需要時間！",
  ui_story_1020_10200601_99_dialog_content = "布布！布布！布布！",
  ui_story_1020_10200601_100_dialog_content = "對了，參謀長——叫萊因哈特把尤利西斯帶過來！",
  ui_story_1020_10200601_101_dialog_content = "<color=#e8d9bb>啟光高層會議室</color>",
  ui_story_1020_10200601_102_dialog_content = "自動控制系統失控、淺層區城門控制失靈、隧道坍方……",
  ui_story_1020_10200601_103_dialog_content = "這就是你期待的結果嗎？",
  ui_story_1020_10200601_104_dialog_content = "白夜城呢？",
  ui_story_1020_10200601_105_dialog_content = "沒有動靜。",
  ui_story_1020_10200601_106_dialog_content = "……",
  ui_story_1020_10200601_107_dialog_content = "在想<color=#FFB400>緊急備案</color>嗎？",
  ui_story_1020_10200601_108_dialog_content = "還不是時候。",
  ui_story_1020_10200601_109_dialog_content = "阿克希亞感覺……地面在晃動。",
  ui_story_1020_10200601_110_dialog_content = "我也感覺到了……",
  ui_story_1020_10200601_111_dialog_content = "這就是聲稱要接收我實驗室的人搞出來的事情嗎？",
  ui_story_1020_10200601_112_dialog_content = "呵呵……你們以為……你們能做什麼？",
  ui_story_1020_10200601_113_dialog_content = "你知道那部原型機有問題，它在等待著什麼，對嗎？",
  ui_story_1020_10200601_114_dialog_content = "……原型機出問題了？",
  ui_story_1020_10200601_115_dialog_content = "你們……應該自己揭開歷史……",
  ui_story_1020_10200601_116_dialog_content = "雷霆、緋，妳們盯緊尤利西斯，無論如何別讓他離開妳們的視線。",
  ui_story_1020_10200601_117_dialog_content = "我先去看看情況，之後我會通知妳們把尤利西斯帶過來。",
  ui_story_1020_10200601_118_dialog_content = "遵命。",
  ui_story_1020_10200601_119_dialog_content = "注意安全。",
  ui_story_1020_10200601_120_dialog_content = "<color=#e8d9bb>迦南城淺層</color>",
  ui_story_1020_10200601_121_dialog_content = "<color=#e8d9bb>轟隆隆——！！！</color>",
  ui_story_1020_10200601_122_dialog_content = "是的，巴頓軍團長！牆壁晃動得非常厲害，像有人在轉動城門開關一樣！",
  ui_story_1020_10200601_123_dialog_content = "所有的城門嗎？！",
  ui_story_1020_10200601_124_dialog_content = "不完全是。主要是右側那兩道破損嚴重的城門，有暗鬼在靠近！",
  ui_story_1020_10200601_125_dialog_content = "看來薇薇安她們遇到麻煩了。",
  ui_story_1020_10200601_126_dialog_content = "無論如何，一定要把門給我守住。",
  ui_story_1020_10200601_127_dialog_content = "就算城門出現窟窿，我們也要把大砲架在窟窿上，來一個打一個！來十個打一串！",
  ui_story_1020_10200601_128_dialog_content = "喜歡看暗鬼腦袋開花的，今天有福啦！",
  ui_story_1020_10200601_129_dialog_content = "遵命！",
  ui_story_1020_10200601_130_dialog_content = "<color=#e8d9bb>轟——轟——轟——！！！</color>",
  ui_story_1020_10200601_131_dialog_content = "哈哈哈哈哈！",
  ui_story_1020_10200601_132_dialog_content = "腦袋開花！",
  ui_story_1020_10200601_133_dialog_content = "巴頓軍團最強的人來也！",
  ui_story_1020_10200602_1_dialog_content = "布布布布——！！！",
  ui_story_1020_10200602_2_dialog_content = "……",
  ui_story_1020_10200602_3_dialog_content = "大家都沒事吧？",
  ui_story_1020_10200602_4_dialog_content = "大元帥！感謝您替我擋住身後的怪物……",
  ui_story_1020_10200602_5_dialog_content = "沒想到這些已經死亡的超級兵還會再次襲擊！",
  ui_story_1020_10200602_6_dialog_content = "嗚！回來啦回來啦！我們剛剛果然發現幾個實驗室的艙門警報在響！",
  ui_story_1020_10200602_7_dialog_content = "現在重新鎖上了，現在士兵都在實驗室門口把守。",
  ui_story_1020_10200602_8_dialog_content = "大家都辛苦了。",
  ui_story_1020_10200602_9_dialog_content = "PlayerName，縱使啟光深陷險境，你還是要往危險的地方來是嗎？",
  ui_story_1020_10200602_10_dialog_content = "對不起……",
  ui_story_1020_10200602_11_dialog_content = "平安就好。沒想到尤利西斯竟然把這裡變成製造超級兵的地方……",
  ui_story_1020_10200602_12_dialog_content = "薇薇安，說說你們這邊的情況吧。",
  ui_story_1020_10200602_13_dialog_content = "起初是因為迦南城的防禦出現漏洞，超級兵出現在科技園區裡襲擊大家……",
  ui_story_1020_10200602_14_dialog_content = "還好阿爾戈爾博士找到這裡，發現這部封存的原型機。她目前正在試著搭建防禦核心。",
  ui_story_1020_10200602_15_dialog_content = "現在看來，剛才的震動問題已經解決了？",
  ui_story_1020_10200602_16_dialog_content = "暫時建了新的路徑穩住開關，但還不知道下一個漏洞會出現在哪裡。",
  ui_story_1020_10200602_17_dialog_content = "尤利西斯呢？",
  ui_story_1020_10200602_18_dialog_content = "他交代了這部機器的事情，但是我必須先瞭解情況後，再決定是否將他帶過來。",
  ui_story_1020_10200602_19_dialog_content = "尤利西斯現在的狀況……比較特別。",
  ui_story_1020_10200602_20_dialog_content = "日蝕方是誰在和他聯絡？他交代了嗎？",
  ui_story_1020_10200602_21_dialog_content = "連妳也這樣說，那沒錯了……",
  ui_story_1020_10200602_22_dialog_content = "他提到，他在原型機裡發現「工程師」的線索。",
  ui_story_1020_10200602_23_dialog_content = "據尤利西斯說，這個「工程師」是建立啟光的首任城主，但是早在六百年前就不知去向。",
  ui_story_1020_10200602_24_dialog_content = "消失了六百多年的「工程師」……現在透過一部電腦和尤利西斯聯絡……",
  ui_story_1020_10200602_25_dialog_content = "像PlayerName那樣，透過感應能力？",
  ui_story_1020_10200602_26_dialog_content = "感應能力……？",
  ui_story_1020_10200602_27_dialog_content = "（那腦袋裡面的畫面，難道是感應……？）",
  ui_story_1020_10200602_28_dialog_content = "那不是只有空裔才能做到的事情嗎……",
  ui_story_1020_10200602_29_dialog_content = "如果「工程師」真的存在，理論上只要線路效率夠高，就能透過原型機和尤利西斯即時溝通。",
  ui_story_1020_10200602_30_dialog_content = "但是原型機既沒有可見的線路，也沒有傳播和接收訊號的裝置。所以——",
  ui_story_1020_10200602_31_dialog_content = "嗶嚕——",
  ui_story_1020_10200602_32_dialog_content = "阿爾戈爾叫一號帶過來的<color=#FFB400>端子</color>。",
  ui_story_1020_10200602_33_dialog_content = "謝了，端子給我。",
  ui_story_1020_10200602_34_dialog_content = "打個比方……",
  ui_story_1020_10200602_35_dialog_content = "只要接上這樣的線路，一號就能出現在我的電腦上，與我即時視訊溝通。",
  ui_story_1020_10200602_36_dialog_content = "喔，嗨大家！我的臉是不是太大了……",
  ui_story_1020_10200602_37_dialog_content = "我們檢查中沒有發現這樣的<color=#FFB400>線路</color>，四周都很乾淨，牆壁和地面也沒有縫隙……",
  ui_story_1020_10200602_38_dialog_content = "這就奇怪了，這間倉庫沒有登記使用的原因，是當時很多舊線路和環境融合嚴重，沒法處理。",
  ui_story_1020_10200602_39_dialog_content = "竟然還有這麼一說？我第一次到這裡來的時候，它就和現在的環境差不多了。",
  ui_story_1020_10200602_40_dialog_content = "或許在那之前，就已經被處理過了吧。",
  ui_story_1020_10200602_41_dialog_content = "這麼大一間倉庫，這老頭真不簡單……",
  ui_story_1020_10200602_42_dialog_content = "布布！布布！布布！",
  ui_story_1020_10200602_43_dialog_content = "<color=#e8d9bb>唰啦——唰啦——</color>",
  ui_story_1020_10200602_44_dialog_content = "欸……阿爾戈爾博士，妳的線路怎麼在冒火花啊？！",
  ui_story_1020_10200602_45_dialog_content = "哈？功率超載……？？？不可能啊！",
  ui_story_1020_10200602_46_dialog_content = "怎麼會……所有部件都在強制滿功率運轉？！",
  ui_story_1020_10200602_47_dialog_content = "<color=#e8d9bb>唰啦——砰！</color>",
  ui_story_1020_10200602_48_dialog_content = "啊——！竟然把我的線路燒壞了——！！！",
  ui_story_1020_10200602_49_dialog_content = "阿爾戈爾憤怒。",
  ui_story_1020_10200602_50_dialog_content = "布布布布——！！！",
  ui_story_1020_10200602_51_dialog_content = "<color=#e8d9bb>嗶——嗶——嗶——</color>",
  ui_story_1020_10200602_52_dialog_content = "可——惡——！剛搭建的防禦模組癱瘓了！",
  ui_story_1020_10200602_53_dialog_content = "布布！布布！布布！",
  ui_story_1020_10200602_54_dialog_content = "<color=#e8d9bb>嗡——</color>",
  ui_story_1020_10200602_55_dialog_content = "停下來了……？",
  ui_story_1020_10200602_56_dialog_content = "<color=#e8d9bb>滋滋——滋滋——</color>",
  ui_story_1020_10200602_57_dialog_content = "是個腦袋！",
  ui_story_1020_10200602_58_dialog_content = "……",
  ui_story_1020_10200602_59_dialog_content = "這難道就是所謂的「工程師」？",
  ui_story_1020_10200602_60_dialog_content = "剛剛閃過的畫面……即時溝通？",
  ui_story_1020_10200602_61_dialog_content = "咦……怎麼沒了……",
  ui_story_1020_10200602_62_dialog_content = "布布布布——！！！",
  ui_story_1020_10200602_63_dialog_content = "什麼？對話？你能解析他的語言嗎？",
  ui_story_1020_10200602_64_dialog_content = "……布布……",
  ui_story_1020_10200602_65_dialog_content = "「工程師」在說什麼？",
  ui_story_1020_10200602_66_dialog_content = "……布布……",
  ui_story_1020_10200602_67_dialog_content = "「好久不見」",
  ui_story_1020_10200602_68_dialog_content = "……布布……",
  ui_story_1020_10200602_69_dialog_content = "「尤利西斯」",
  ui_story_1020_10200602_70_dialog_content = "……布布……",
  ui_story_1020_10200602_71_dialog_content = "「博士」",
  ui_story_1020_10200602_72_dialog_content = "……",
  ui_story_1020_10200602_73_dialog_content = "布林！更改路徑，重新調取模組！",
  ui_story_1020_10200602_74_dialog_content = "布！",
  ui_story_1020_10200602_75_dialog_content = "<color=#e8d9bb>嗡——</color>",
  ui_story_1020_10200602_76_dialog_content = "……",
  ui_story_1020_10200602_77_dialog_content = "好久……不見……",
  ui_story_1020_10200602_78_dialog_content = "呵呵……呵……哈哈哈哈……",
  ui_story_1020_10200602_79_dialog_content = "你來了……",
  ui_story_1020_10200602_80_dialog_content = "誰？",
  ui_story_1020_10200602_81_dialog_content = "「工程師」……",
  ui_story_1020_10200602_82_dialog_content = "在哪？",
  ui_story_1020_10200602_83_dialog_content = "艾森，最後一顆藥……給我。",
  ui_story_1020_10200602_84_dialog_content = "長官……",
  ui_story_1020_10200602_85_dialog_content = "給我！",
  ui_story_1020_10200602_86_dialog_content = "<color=#e8d9bb>啟光監禁室</color>",
  ui_story_1020_10200602_87_dialog_content = "（日蝕語）是您、是您……無上的主宰！",
  ui_story_1020_10200602_88_dialog_content = "（日蝕語）您忠誠的奴僕，斐桀洛，已在此跪候您的降臨。",
  ui_story_1020_10200602_89_dialog_content = "……",
  ui_story_1020_10200602_90_dialog_content = "<color=#e8d9bb>咔嚓——</color>",
  ui_story_1020_10200602_91_dialog_content = "（日蝕語）……",
  ui_story_1020_10200602_92_dialog_content = "（日蝕語）顫、顫抖！絕、絕不敢違背您的意志！",
  ui_story_1020_10200602_93_dialog_content = "（日蝕語）為了報答您……",
  ui_story_1020_10200602_94_dialog_content = "（日蝕語）當年那起失敗的任務，我願意獻出生命去完成。",
  ui_story_1020_10200701_1_dialog_content = "<color=#e8d9bb>轟隆隆——</color>",
  ui_story_1020_10200701_2_dialog_content = "尤利西斯，他已經拿走了「守護者一號」的核心，還想做什麼？",
  ui_story_1020_10200701_3_dialog_content = "看著這座地下城搖搖欲墜，你都不會感到害怕嗎，鐵面？",
  ui_story_1020_10200701_4_dialog_content = "你策劃了這一切……把啟光的命脈交到日蝕手裡，就是為了獲得更多研究資源，實踐你的理想？",
  ui_story_1020_10200701_5_dialog_content = "我也曾深深相信，沒有工程師，就沒有啟光的今天。",
  ui_story_1020_10200701_6_dialog_content = "但後來我知道了，「守護者一號」的核心，從來就不是啟光的命脈。",
  ui_story_1020_10200701_7_dialog_content = "我才是！",
  ui_story_1020_10200701_8_dialog_content = "僅僅是沒了「守護者一號」核心，迦南城的防禦系統何至於潰爛成現在這樣？",
  ui_story_1020_10200701_9_dialog_content = "讓我告訴妳「工程師」的計畫吧……",
  ui_story_1020_10200701_10_dialog_content = "他要統合，要燃燒！要用他的強大蔑視光靈的渺小……",
  ui_story_1020_10200701_11_dialog_content = "而我不想像你們一樣坐以待斃，在這黑暗的地下城死去！我會向他挑戰！",
  ui_story_1020_10200701_12_dialog_content = "瘋子……胡說八道！",
  ui_story_1020_10200701_13_dialog_content = "你們知道他是怎麼做的嗎……",
  ui_story_1020_10200701_14_dialog_content = "他建立了這些然後沉寂，將收回核心、製造暗鬼的任務交給那些愚蠢的罪靈。",
  ui_story_1020_10200701_15_dialog_content = "蟄伏幾百年後，他復甦了。",
  ui_story_1020_10200701_16_dialog_content = "但，世界發生了變化。他已經不是那個我從資料裡瞭解到的工程師了。",
  ui_story_1020_10200701_17_dialog_content = "如今他能做到的事情，我未必不能。",
  ui_story_1020_10200701_18_dialog_content = "閉上你那喋喋不休的臭嘴！",
  ui_story_1020_10200701_19_dialog_content = "我們這裡的任何人一抬手，就可以把你給殺了，你最好——",
  ui_story_1020_10200701_20_dialog_content = "妳能做什麼？",
  ui_story_1020_10200701_21_dialog_content = "……",
  ui_story_1020_10200701_22_dialog_content = "呵呵……要做的，我都已經準備在我的倉庫裡了。",
  ui_story_1020_10200701_23_dialog_content = "站住！",
  ui_story_1020_10200701_24_dialog_content = "……敢攔我？",
  ui_story_1020_10200701_25_dialog_content = "老實待在這裡。",
  ui_story_1020_10200701_26_dialog_content = "……就算你們都不相信我說的，但現在……只有我……",
  ui_story_1020_10200701_27_dialog_content = "再往前一步看看？",
  ui_story_1020_10200701_28_dialog_content = "把刀放下。",
  ui_story_1020_10200701_29_dialog_content = "……",
  ui_story_1020_10200701_30_dialog_content = "時間不多了，鐵面。妳我都是如此。但啟光的路還很長，光靈的路還很長。",
  ui_story_1020_10200701_31_dialog_content = "我知道這一天終會來臨，就算所有人否定我，我也不會放棄！",
  ui_story_1020_10200701_32_dialog_content = "我，會用我的方式對抗。",
  ui_story_1020_10200701_33_dialog_content = "即使你們做不到，那我也會自己上……",
  ui_story_1020_10200701_34_dialog_content = "你們……敢去看嗎？",
  ui_story_1020_10200701_35_dialog_content = "……",
  ui_story_1020_10200701_36_dialog_content = "<color=#e8d9bb>嗶——</color>",
  ui_story_1020_10200701_37_dialog_content = "是大元帥嗎……？",
  ui_story_1020_10200701_38_dialog_content = "她要我們把尤利西斯帶過去……",
  ui_story_1020_10200701_39_dialog_content = "……",
  ui_story_1020_10200701_40_dialog_content = "貝利撒留，如果沒有棋子，棋局也不會存在。妳又怎麼做得起那個下棋的人呢？",
  ui_story_1020_10200701_41_dialog_content = "我相信無論發生什麼事，萊因哈特都撐得起這座迦南城。但妳，可以嗎？",
  ui_story_1020_10200701_42_dialog_content = "……",
  ui_story_1020_10200701_43_dialog_content = "達夫迪爾，聯絡巴蕾特。",
  ui_story_1020_10200701_44_dialog_content = "長官，巴蕾特博士已經等您很久了。",
  ui_story_1020_10200701_45_dialog_content = "決定了嗎？",
  ui_story_1020_10200701_46_dialog_content = "執行<color=#FFB400>緊急備案</color>。",
  ui_story_1020_10200701_47_dialog_content = "卸除原來的裝備，改變預設線路，打開運輸井，將居民運往備用的幾座地下城。",
  ui_story_1020_10200701_48_dialog_content = "載具和運輸井可以正常作業，居民也能轉移。",
  ui_story_1020_10200701_49_dialog_content = "但我希望委員會安排足夠的軍隊保障運輸井的行動安全。",
  ui_story_1020_10200701_50_dialog_content = "妳只管去做，委員會為妳的行動開路。",
  ui_story_1020_10200701_51_dialog_content = "好，乾脆俐落。",
  ui_story_1020_10200701_52_dialog_content = "妳們把尤利西斯安全帶去倉庫。",
  ui_story_1020_10200701_53_dialog_content = "等等，妳剛才說的載具、運輸井……是什麼？",
  ui_story_1020_10200701_54_dialog_content = "啟光研發的飛行器，以及一系列專為飛行器設計的地下軌道。",
  ui_story_1020_10200701_55_dialog_content = "飛行器……？",
  ui_story_1020_10200701_56_dialog_content = "火車、地面運輸車、專用軌道……你們以為啟光只有這些貼著地面跑的東西。",
  ui_story_1020_10200701_57_dialog_content = "原來的裝備、預設線路……那又是什麼？",
  ui_story_1020_10200701_58_dialog_content = "不怕告訴妳們，這些飛行器是為那座浮空島準備的，預設線路就是從這裡直搗白夜城。",
  ui_story_1020_10200701_59_dialog_content = "飛行器……原來載了彈藥準備攻打白夜城？！",
  ui_story_1020_10200701_60_dialog_content = "面對不同的敵人，要用不同的武器。若決定要走上地面，只能不擇手段。",
  ui_story_1020_10200701_61_dialog_content = "……",
  ui_story_1020_10200701_62_dialog_content = "沒想到是在這個時候，以這種方式執行緊急備案。",
  ui_story_1020_10200701_63_dialog_content = "就算妳不說，至少在這件事情上，我和你們的利益是一致的。",
  ui_story_1020_10200701_64_dialog_content = "把尤利西斯帶到他的倉庫去吧。他現在是妳們的人質了。",
  ui_story_1020_10200701_65_dialog_content = "……",
  ui_story_1020_10200701_66_dialog_content = "呵呵……鐵面，看來妳不是曾經那個玩世不恭的上位者了。",
  ui_story_1020_10200701_67_dialog_content = "我們，還會再見吧……",
  ui_story_1020_10200701_68_dialog_content = "該玩的時候當然要玩。",
  ui_story_1020_10200701_69_dialog_content = "但是玩夠了，也該做些什麼吧。",
  ui_story_1020_10200701_70_dialog_content = "如果你也能這樣做的話，我們就沒有見面的必要了。",
  ui_story_1020_10200701_71_dialog_content = "運輸井打開後，白夜城仍然沒有動靜。",
  ui_story_1020_10200701_72_dialog_content = "韜光養晦這麼多年，不趁著這個機會對浮空島來上兩砲，可惜。",
  ui_story_1020_10200701_73_dialog_content = "都回到各自的位置上去吧，之後要做的事情還有不少。",
  ui_story_1020_10200701_74_dialog_content = "<color=#e8d9bb>轟隆隆——</color>",
  ui_story_1020_10200701_75_dialog_content = "阿克希亞、鶯歌……我們現在，該怎麼辦？",
  ui_story_1020_10200701_76_dialog_content = "之前怎麼辦，現在就怎麼辦。大元帥他們都去那間倉庫了，我們應該保護他們。",
  ui_story_1020_10200701_77_dialog_content = "就算是戰爭兵器……你們也時刻知道自己要做什麼嗎？",
  ui_story_1020_10200701_78_dialog_content = "我從懂事以來就知道。",
  ui_story_1020_10200701_79_dialog_content = "阿克希亞，是最近才知道的。西恩，也會知道的。",
  ui_story_1020_10200701_80_dialog_content = "說得輕鬆……妳們倆都那麼……",
  ui_story_1020_10200701_81_dialog_content = "呀——！",
  ui_story_1020_10200701_82_dialog_content = "鶯歌妳……妳掐我做什麼？都、都流血了……",
  ui_story_1020_10200701_83_dialog_content = "戰爭兵器，不也是有血有肉的光靈嗎？",
  ui_story_1020_10200701_84_dialog_content = "會議上的事你別放在心上，無論發生了什麼事，大元帥都不會否定你存在的意義。",
  ui_story_1020_10200701_85_dialog_content = "她和雷霆大元帥都是這場計畫的受害者……但她們仍然在履行自己的職責。",
  ui_story_1020_10200701_86_dialog_content = "雖然這麼說很奇怪……但有這樣的大元帥，我一點也不覺得害怕。",
  ui_story_1020_10200701_87_dialog_content = "……",
  ui_story_1020_10200701_88_dialog_content = "阿克希亞也是……",
  ui_story_1020_10200701_89_dialog_content = "妳們……",
  ui_story_1020_10200701_90_dialog_content = "走啦！跑快點，西恩！",
  ui_story_1020_10200701_91_dialog_content = "……嗯！",
  ui_story_1020_10200701_92_dialog_content = "<color=#e8d9bb>轟隆隆——</color>",
  ui_story_1020_10200801_1_dialog_content = "搖晃……停止了。",
  ui_story_1020_10200801_2_dialog_content = "核心搭建成功了嗎？！",
  ui_story_1020_10200801_3_dialog_content = "不會……我們的運作速度要慢上很多，現在才完成沒多少。",
  ui_story_1020_10200801_4_dialog_content = "再給我一點時間，我一定做得到！",
  ui_story_1020_10200801_5_dialog_content = "布！",
  ui_story_1020_10200801_6_dialog_content = "不用浪費時間了……",
  ui_story_1020_10200801_7_dialog_content = "站好，尤利西斯！",
  ui_story_1020_10200801_8_dialog_content = "你們來了。",
  ui_story_1020_10200801_9_dialog_content = "這也是貝利撒留的意思。她已經下令遷移迦南城的居民了。",
  ui_story_1020_10200801_10_dialog_content = "沒想到……阿爾戈爾博士，尤利西斯要如何處置？",
  ui_story_1020_10200801_11_dialog_content = "尤利西斯，你在這間倉庫裡做了這麼多暗鬼，是在和「工程師」做交易嗎？",
  ui_story_1020_10200801_12_dialog_content = "天真。但能登入系統，穩住迦南城的開關，看來妳這些年來確實有所成長。",
  ui_story_1020_10200801_13_dialog_content = "但正是你自作聰明，既想調取「守護者」的防禦資料，又想抵禦他的攻擊才會這樣。",
  ui_story_1020_10200801_14_dialog_content = "你什麼意思？",
  ui_story_1020_10200801_15_dialog_content = "啟光的漏洞不是這樣一點一點補起來的。要讓防禦瓦解非常容易。",
  ui_story_1020_10200801_16_dialog_content = "但我只要告訴他，要他停手……",
  ui_story_1020_10200801_17_dialog_content = "操作給我看。",
  ui_story_1020_10200801_18_dialog_content = "我做不到。但我說過空裔做得到，你們不信。",
  ui_story_1020_10200801_19_dialog_content = "我……？",
  ui_story_1020_10200801_20_dialog_content = "別把他扯進來。你要怎麼阻止「工程師」？",
  ui_story_1020_10200801_21_dialog_content = "阻止？我沒想要阻止……我只是來看看，你們有沒有破壞我的東西。",
  ui_story_1020_10200801_22_dialog_content = "尤利西斯，你出爾反爾！！！",
  ui_story_1020_10200801_23_dialog_content = "這本就是與你們無關的事情……",
  ui_story_1020_10200801_24_dialog_content = "<color=#e8d9bb>滋滋——滋滋——</color>",
  ui_story_1020_10200801_25_dialog_content = "又來了……",
  ui_story_1020_10200801_26_dialog_content = "……布布……",
  ui_story_1020_10200801_27_dialog_content = "「禮物」？",
  ui_story_1020_10200801_28_dialog_content = "……什麼意思？",
  ui_story_1020_10200801_29_dialog_content = "那些還沒做完的實驗，既然被你們破壞掉，我就不計較了。",
  ui_story_1020_10200801_30_dialog_content = "但我還替他準備了東西。",
  ui_story_1020_10200801_31_dialog_content = "我看看，應該是在這……",
  ui_story_1020_10200801_32_dialog_content = "<color=#e8d9bb>轟隆隆——！！！</color>",
  ui_story_1020_10200801_33_dialog_content = "啊——！",
  ui_story_1020_10200801_34_dialog_content = "快抓緊我！",
  ui_story_1020_10200801_35_dialog_content = "尤利西斯，你碰了什麼東西？！",
  ui_story_1020_10200801_36_dialog_content = "這、這震動比、比剛才的還要劇烈！",
  ui_story_1020_10200801_37_dialog_content = "不是在晃動！是……移動！",
  ui_story_1020_10200801_38_dialog_content = "小心站穩了——",
  ui_story_1020_10200801_39_dialog_content = "哈哈哈哈哈哈……看看吧！",
  ui_story_1020_10200801_40_dialog_content = "<color=#e8d9bb>轟隆隆——！！！</color>",
  ui_story_1020_10200801_41_dialog_content = "這些融合了光靈和暗鬼，能夠以一敵百的<color=#FFB400>超級兵</color>……",
  ui_story_1020_10200801_42_dialog_content = "早已超越妳的研究！",
  ui_story_1020_10200801_43_dialog_content = "地下全部都是……",
  ui_story_1020_10200801_44_dialog_content = "究竟有多少……",
  ui_story_1020_10200801_45_dialog_content = "……原來倉庫正是我們站立的地面！難怪怎麼都找不到它們！",
  ui_story_1020_10200801_46_dialog_content = "少說也有幾百個……不，不只。",
  ui_story_1020_10200801_47_dialog_content = "它們身上插滿纜線，似乎有能源在供應……",
  ui_story_1020_10200801_48_dialog_content = "尤利西斯！",
  ui_story_1020_10200801_49_dialog_content = "<color=#e8d9bb>碰——碰——碰——</color>",
  ui_story_1020_10200801_50_dialog_content = "糟糕……這些超級兵有動靜！",
  ui_story_1020_10200801_51_dialog_content = "<color=#e8d9bb>唰啦——唰啦——</color>",
  ui_story_1020_10200801_52_dialog_content = "看那些倉庫裡的線纜……似乎在冒火星啊！",
  ui_story_1020_10200801_53_dialog_content = "和環境融為一體的纜線，一直在倉庫下面！",
  ui_story_1020_10200801_54_dialog_content = "布布！布布！布布！",
  ui_story_1020_10200801_55_dialog_content = "原來是這些東西控制著超級兵，然後他從電腦裡發送指令……",
  ui_story_1020_10200801_56_dialog_content = "……知道了！布林！",
  ui_story_1020_10200801_57_dialog_content = "布！",
  ui_story_1020_10200801_58_dialog_content = "怎麼樣？還喜歡吧！",
  ui_story_1020_10200801_59_dialog_content = "十年前……二十年前……進攻艾斯特拉大陸的暗鬼還不如這些吧？",
  ui_story_1020_10200801_60_dialog_content = "啊？",
  ui_story_1020_10200801_61_dialog_content = "哈哈哈哈……",
  ui_story_1020_10200801_62_dialog_content = "<color=#e8d9bb>滋滋——滋滋——</color>",
  ui_story_1020_10200801_63_dialog_content = "（為什麼「工程師」聽得到尤利西斯說話？）",
  ui_story_1020_10200801_64_dialog_content = "（是透過原型機？還是其他的溝通方式？）",
  ui_story_1020_10200801_65_dialog_content = "……布布……",
  ui_story_1020_10200801_66_dialog_content = "「不值」",
  ui_story_1020_10200801_67_dialog_content = "……布布……",
  ui_story_1020_10200801_68_dialog_content = "「一提」",
  ui_story_1020_10200801_X68_dialog_content = "（為什麼「工程師」聽得到尤利西斯說話？）",
  ui_story_1020_10200801_X69_dialog_content = "（是透過原型機？還是其他的溝通方式？）",
  ui_story_1020_10200801_69_dialog_content = "<color=#e8d9bb>轟隆隆——！！！</color>",
  ui_story_1020_10200801_70_dialog_content = "那些超級兵都站起來了！",
  ui_story_1020_10200801_X70_dialog_content = "怎麼樣……哈哈哈哈……",
  ui_story_1020_10200801_71_dialog_content = "緋，抓好尤利西斯！其他人退後！",
  ui_story_1020_10200801_72_dialog_content = "遵命！",
  ui_story_1020_10200801_73_dialog_content = "……",
  ui_story_1020_10200801_74_dialog_content = "阿爾戈爾博士！",
  ui_story_1020_10200801_75_dialog_content = "……放任這部機器不管，啟光就完了！",
  ui_story_1020_10200801_76_dialog_content = "怎麼樣……哈哈哈哈……",
  ui_story_1020_10200801_77_dialog_content = "<color=#e8d9bb>嗶——嗶——嗶——</color>",
  ui_story_1020_10200801_78_dialog_content = "尤利西斯，倉庫門要怎麼關閉？",
  ui_story_1020_10200801_79_dialog_content = "回答我！！！",
  ui_story_1020_10200801_80_dialog_content = "這與你們沒有關係……這些不是你們的敵人！你們只要離開……",
  ui_story_1020_10200801_81_dialog_content = "胡言亂語！！！",
  ui_story_1020_10200801_82_dialog_content = "布林，找到線路了沒？！快一點！再快一點！",
  ui_story_1020_10200801_83_dialog_content = "布布布布——！！！",
  ui_story_1020_10200801_X83_dialog_content = "再快一點！再快一點！",
  ui_story_1020_10200801_84_dialog_content = "<color=#e8d9bb>碰——碰——碰——</color>",
  ui_story_1020_10200801_85_dialog_content = "吼吼吼吼吼——",
  ui_story_1020_10200801_86_dialog_content = "阿爾戈爾博士！",
  ui_story_1020_10200801_87_dialog_content = "……",
  ui_story_1020_10200801_88_dialog_content = "阿爾戈爾博士仍然不肯離開……",
  ui_story_1020_10200801_89_dialog_content = "阿爾戈爾，我用感應能力救妳！",
  ui_story_1020_10200801_90_dialog_content = "不！你們出去！！！",
  ui_story_1020_10200801_91_dialog_content = "控制超級兵的線路找到了……",
  ui_story_1020_10200801_92_dialog_content = "布布布布——！！！",
  ui_story_1020_10200801_93_dialog_content = "資料庫同步了，好！然後連進……",
  ui_story_1020_10200801_94_dialog_content = "再快一點……再快一點！！！",
  ui_story_1020_10200801_95_dialog_content = "布布！布布！布布！",
  ui_story_1020_10200801_96_dialog_content = "阿爾戈爾，快躲開！",
  ui_story_1020_10200801_97_dialog_content = "<color=#e8d9bb>碰——！！！</color>",
  ui_story_1020_10200801_98_dialog_content = "布布？",
  ui_story_1020_10200801_99_dialog_content = "吼吼吼吼吼——",
  ui_story_1020_10200801_100_dialog_content = "怎麼回事？超級兵沒有攻擊阿爾戈爾！",
  ui_story_1020_10200801_101_dialog_content = "……",
  ui_story_1020_10200801_102_dialog_content = "<color=#e8d9bb>碰——！碰——！碰——！</color>",
  ui_story_1020_10200801_103_dialog_content = "他們在攻擊……原型機？",
  ui_story_1020_10200801_104_dialog_content = "難道，尤利西斯的超級兵是為了……",
  ui_story_1020_10200801_105_dialog_content = "呵哈哈哈哈哈……喜歡嗎……嗯？",
  ui_story_1020_10200801_106_dialog_content = "怎麼樣……你的暗鬼……在哪裡呢？",
  ui_story_1020_10200801_107_dialog_content = "<color=#e8d9bb>滋滋——滋滋——</color>",
  ui_story_1020_10200801_108_dialog_content = "……布布……",
  ui_story_1020_10200801_109_dialog_content = "「謝謝」",
  ui_story_1020_10200801_110_dialog_content = "……謝謝？",
  ui_story_1020_10200801_111_dialog_content = "……",
  ui_story_1020_10200801_112_dialog_content = "吼……",
  ui_story_1020_10200801_113_dialog_content = "超級兵……不動了？",
  ui_story_1020_10200801_114_dialog_content = "他們在找什麼？",
  ui_story_1020_10200801_115_dialog_content = "<color=#e8d9bb>唰啦——唰啦——</color>",
  ui_story_1020_10200801_116_dialog_content = "阿爾戈爾博士，那些纜線又開始冒火花了！",
  ui_story_1020_10200801_117_dialog_content = "沒關係……我會截斷指令……",
  ui_story_1020_10200801_118_dialog_content = "<color=#e8d9bb>嗶——嗶——嗶——</color>",
  ui_story_1020_10200801_119_dialog_content = "啊！！！怪物！簡直是怪物！",
  ui_story_1020_10200801_120_dialog_content = "你想做什麼……？",
  ui_story_1020_10200801_121_dialog_content = "<color=#e8d9bb>唰啦——唰啦——</color>",
  ui_story_1020_10200801_122_dialog_content = "快看那些超級兵的後背！！！",
  ui_story_1020_10200801_123_dialog_content = "吼——！！！",
  ui_story_1020_10200801_124_dialog_content = "他開始進攻了！",
  ui_story_1020_10200801_125_dialog_content = "你要對我的東西做什麼？！！！",
  ui_story_1020_10200801_126_dialog_content = "吼——！！！",
  ui_story_1020_10200801_127_dialog_content = "阿爾戈爾，危險！！！",
  ui_story_1020_10200901_1_dialog_content = "<color=#e8d9bb>轟隆隆隆隆——！</color>",
  ui_story_1020_10200901_2_dialog_content = "巴頓軍團長，我們已經拼盡全力了！",
  ui_story_1020_10200901_3_dialog_content = "但是<color=#FFB400>第十號城門</color>那邊的戰友還在苦戰，急需增援！",
  ui_story_1020_10200901_4_dialog_content = "你是想說，你們這些菁英小隊要把這麼好的實戰機會讓給別人嗎？！",
  ui_story_1020_10200901_5_dialog_content = "不是的，軍團長！是城門的震動太劇烈了，我們的身體都快撐不住了……",
  ui_story_1020_10200901_6_dialog_content = "第十號城門……那不是整備場的方向嗎？",
  ui_story_1020_10200901_7_dialog_content = "難道是那個小子的臨空者號也想出風頭，想用身體來支撐城門？",
  ui_story_1020_10200901_8_dialog_content = "巨像能支撐城門嗎……？",
  ui_story_1020_10200901_9_dialog_content = "怎麼不能？巨像還能把空裔養大呢！",
  ui_story_1020_10200901_10_dialog_content = "來，跟我走！就不信我這身體比不過一堆廢鐵！",
  ui_story_1020_10200901_11_dialog_content = "軍團長！<color=#FFB400>第九號城門</color>那邊也在瘋狂震盪，好像有一股強大的氣流從地底湧向上層！",
  ui_story_1020_10200901_12_dialog_content = "地底？！馬上檢查所有通風管道！不要放過任何一個角落！",
  ui_story_1020_10200901_13_dialog_content = "都檢查過了！沒有發現任何暗鬼的蹤跡！",
  ui_story_1020_10200901_14_dialog_content = "這到底是怎麼回事……",
  ui_story_1020_10200901_15_dialog_content = "<color=#e8d9bb>第九號城門附近</color>",
  ui_story_1020_10200901_16_dialog_content = "這位長官，目前區域震度強烈，請到安全的地方避難！",
  ui_story_1020_10200901_17_dialog_content = "不用管我。下方的運輸井在運作，我來調查上層的震度如何。",
  ui_story_1020_10200901_18_dialog_content = "運輸井……",
  ui_story_1020_10200901_19_dialog_content = "<color=#e8d9bb>轟隆隆——</color>",
  ui_story_1020_10200901_20_dialog_content = "還可以，對城門造成的影響不大。",
  ui_story_1020_10200901_21_dialog_content = "……",
  ui_story_1020_10200901_22_dialog_content = "<color=#e8d9bb>白夜城·黎明學院</color>",
  ui_story_1020_10200901_23_dialog_content = "白夜至上——妳聽說了嗎？學院中的<color=#FFB400>白夜石</color>突然發生異變，光能紊亂的現象持續了很久。",
  ui_story_1020_10200901_24_dialog_content = "神父和修女們紛紛趕來，用盡全力施展光能術都無法平息！",
  ui_story_1020_10200901_25_dialog_content = "這與之前白夜城的震動有關嗎？",
  ui_story_1020_10200901_26_dialog_content = "嗯，恐怕是古代遺跡又開始和神祕力量共鳴了。",
  ui_story_1020_10200901_27_dialog_content = "此前黃昏鎮發生極光紊亂的時候，就已經出現過一次。這一次更加嚴重。",
  ui_story_1020_10200901_28_dialog_content = "<color=#e8d9bb>白夜城·朝堂</color>",
  ui_story_1020_10200901_29_dialog_content = "你瞧，那些運輸井就像地面張開貪婪的嘴，啟光這隻狼餓太久了！",
  ui_story_1020_10200901_30_dialog_content = "餓狼的嘴暫時還沒咬到白夜城。",
  ui_story_1020_10200901_31_dialog_content = "衛隊長，解除防禦吧，遺跡基本上已經穩住了。",
  ui_story_1020_10200901_32_dialog_content = "是。",
  ui_story_1020_10200901_33_dialog_content = "城主大人，黎明學院中儲存光能的石頭對剛才的震動反應劇烈，您認為白夜城中是否有不明的力量？",
  ui_story_1020_10200901_34_dialog_content = "白夜至上——卡蓮殿下不必擔心。",
  ui_story_1020_10200901_35_dialog_content = "這雖是自聖女大人進入神殿後就再也沒出現過的情形，但光之神會指引我們。",
  ui_story_1020_10200901_36_dialog_content = "神父，你認為白夜石的異變是何緣故？",
  ui_story_1020_10200901_37_dialog_content = "教典中有相關記載。當新的<color=#FFB400>承靈者</color>出現時，光能會發生紊亂。",
  ui_story_1020_10200901_38_dialog_content = "……",
  ui_story_1020_10200901_39_dialog_content = "地下遺跡裡蘊藏的邪惡之力曾震盪整個浮空島，正是承靈者——聖女大人驅散了邪惡力量。",
  ui_story_1020_10200901_40_dialog_content = "算來，聖女大人已經守護浮空島許多年了。",
  ui_story_1020_10200901_41_dialog_content = "邪惡只會減退、無法驅散。白夜城並不是一座潔淨的島嶼。",
  ui_story_1020_10200901_42_dialog_content = "神父，白夜城會陷入危險嗎？",
  ui_story_1020_10200901_43_dialog_content = "不會。",
  ui_story_1020_10200901_44_dialog_content = "那啟光聯邦呢？",
  ui_story_1020_10200901_45_dialog_content = "他們首先要找到自己的信仰。",
  ui_story_1020_10200901_46_dialog_content = "衛隊長，留意來自啟光的信件。",
  ui_story_1020_10200901_47_dialog_content = "知道了，城主大人。",
  ui_story_1020_10200901_48_dialog_content = "<color=#e8d9bb>轟隆隆——</color>",
  ui_story_1020_10200901_49_dialog_content = "阿爾戈爾博士，目前情況怎麼樣？",
  ui_story_1020_10200901_50_dialog_content = "控制台輸出顯示，核心就要搭建完成了。",
  ui_story_1020_10200901_51_dialog_content = "工程師竟然沒有發動攻擊……加把勁啊，布林！",
  ui_story_1020_10200901_52_dialog_content = "布布！布布！布布！",
  ui_story_1020_10200901_53_dialog_content = "什麼……？",
  ui_story_1020_10200901_54_dialog_content = "<color=#e8d9bb>滋滋——滋滋——</color>",
  ui_story_1020_10200901_55_dialog_content = "……布布……",
  ui_story_1020_10200901_56_dialog_content = "「回家吧，空裔」",
  ui_story_1020_10200901_57_dialog_content = "空裔哪裡都不會去！",
  ui_story_1020_10200901_58_dialog_content = "……",
  ui_story_1020_10200901_59_dialog_content = "「工程師」不是和尤利西斯對話嗎？為什麼會知道PlayerName？",
  ui_story_1020_10200901_60_dialog_content = "回家吧，空裔。",
  ui_story_1020_10200901_61_dialog_content = "他的聲音，我好像聽到了……",
  ui_story_1020_10200901_62_dialog_content = "在哪裡聽到？",
  ui_story_1020_10200901_63_dialog_content = "腦袋裡……",
  ui_story_1020_10200901_64_dialog_content = "原來腦袋裡的畫面，真的是感應……",
  ui_story_1020_10200901_65_dialog_content = "回家吧，空裔。",
  ui_story_1020_10200901_66_dialog_content = "……你是誰？",
  ui_story_1020_10200901_67_dialog_content = "你們叫我「工程師」。",
  ui_story_1020_10200901_68_dialog_content = "你是日蝕的暗鬼……透過這部機器控制著啟光的超級兵？",
  ui_story_1020_10200901_69_dialog_content = "不是。",
  ui_story_1020_10200901_70_dialog_content = "……你偷走啟光的「守護者一號」核心，讓暗鬼入侵迦南城？",
  ui_story_1020_10200901_71_dialog_content = "那本來就是我的東西。",
  ui_story_1020_10200901_72_dialog_content = "你也是。",
  ui_story_1020_10200901_73_dialog_content = "……我出生在艾斯特拉大陸的空之山谷，我是空裔。",
  ui_story_1020_10200901_74_dialog_content = "空裔是怎麼誕生的？",
  ui_story_1020_10200901_75_dialog_content = "你對我……對空裔做了什麼？",
  ui_story_1020_10200901_76_dialog_content = "回家吧，空裔。",
  ui_story_1020_10200901_77_dialog_content = "與我一起，繼續那項崇高的事業。",
  ui_story_1020_10200901_78_dialog_content = "「崇高事業」……空裔哪裡都不去！！！",
  ui_story_1020_10200901_79_dialog_content = "尤利西斯，你在說什麼？！",
  ui_story_1020_10200901_80_dialog_content = "……",
  ui_story_1020_10200901_81_dialog_content = "他也能感應到你？",
  ui_story_1020_10200901_82_dialog_content = "他和你不一樣。",
  ui_story_1020_10200901_83_dialog_content = "我會告訴你，一切你想知道的真相。",
  ui_story_1020_10200901_84_dialog_content = "遠古年代的暗面戰場、巨像停泊層、空裔家園……",
  ui_story_1020_10200901_85_dialog_content = "還有你一直渴望的族人。",
  ui_story_1020_10200901_86_dialog_content = "……？！",
  ui_story_1020_10200901_87_dialog_content = "<color=#e8d9bb>嗶——嗶嗶——嗶嗶嗶——</color>",
  ui_story_1020_10200901_88_dialog_content = "阿爾戈爾手環，報告危險源。",
  ui_story_1020_10200901_89_dialog_content = "啟光整備場……",
  ui_story_1020_10200901_90_dialog_content = "PlayerName，巨像正在中斷與我終端的連線！",
  ui_story_1020_10200901_91_dialog_content = "臨空者號……",
  ui_story_1020_10200901_92_dialog_content = "是你？！",
  ui_story_1020_10200901_93_dialog_content = "我已為你啟動巨像。",
  ui_story_1020_10200901_94_dialog_content = "不……不！",
  ui_story_1020_10200901_95_dialog_content = "<color=#e8d9bb>碰咚——</color>",
  ui_story_1020_10200901_96_dialog_content = "PlayerName！",
  ui_story_1020_10200901_97_dialog_content = "喔吼，跑出去了。",
  ui_story_1020_10200901_98_dialog_content = "薇薇安，跟上去，現在外面很危險。",
  ui_story_1020_10200901_99_dialog_content = "遵命！",
  ui_story_1020_10200901_100_dialog_content = "空裔哪裡都不會去！你的目標是我……",
  ui_story_1020_10200901_101_dialog_content = "尤利西斯，你不准再亂來了！",
  ui_story_1020_10200901_102_dialog_content = "放開我！讓我來對付他！",
  ui_story_1020_10200901_103_dialog_content = "<color=#e8d9bb>咔噠咔噠——</color>",
  ui_story_1020_10200901_104_dialog_content = "布布！布布！布布！",
  ui_story_1020_10200901_105_dialog_content = "尤利西斯，住手！",
  ui_story_1020_10200901_106_dialog_content = "吼！！！",
  ui_story_1020_10200901_107_dialog_content = "這麼多年……我也做到了……",
  ui_story_1020_10200901_108_dialog_content = "這些夠嗎……？！",
  ui_story_1020_10200901_109_dialog_content = "不夠還有！還有成千上百！比起暗鬼要強上百倍、千倍的超級士兵！！！",
  ui_story_1020_10200901_110_dialog_content = "<color=#e8d9bb>滋滋——滋滋——</color>",
  ui_story_1020_10200901_111_dialog_content = "……布布……",
  ui_story_1020_10200901_112_dialog_content = "「最後一次」",
  ui_story_1020_10200901_113_dialog_content = "糟糕，把尤利西斯抓好！他要控制超級兵攻擊了！",
  ui_story_1020_10200901_114_dialog_content = "尤利西斯交給我！",
  ui_story_1020_10200901_115_dialog_content = "<color=#e8d9bb>嗶——嗶——嗶——</color>",
  ui_story_1020_10200901_116_dialog_content = "啊——！！！好不容易搭建的防禦模組……！！！",
  ui_story_1020_10200901_117_dialog_content = "吼吼吼！！！",
  ui_story_1020_10201001_1_dialog_content = "PlayerName！",
  ui_story_1020_10201001_2_dialog_content = "從這裡到整備場還有一些距離，外面太危險了！",
  ui_story_1020_10201001_3_dialog_content = "……我不會讓臨空者號離開！",
  ui_story_1020_10201001_4_dialog_content = "沒有你的命令，臨空者號怎麼會自行啟動呢？",
  ui_story_1020_10201001_5_dialog_content = "……",
  ui_story_1020_10201001_6_dialog_content = "我看見了……",
  ui_story_1020_10201001_7_dialog_content = "你看見什麼……？",
  ui_story_1020_10201001_8_dialog_content = "我看見了，尤利西斯看到的東西……",
  ui_story_1020_10201001_9_dialog_content = "有一個聲音……「工程師」在叫我和臨空者號「回家」……",
  ui_story_1020_10201001_10_dialog_content = "PlayerName……",
  ui_story_1020_10201001_11_dialog_content = "我好不容易才把領空者號找回來，我們剛相處才沒幾天……",
  ui_story_1020_10201001_12_dialog_content = "我一定一定……一定不會讓這件事情發生！",
  ui_story_1020_10201001_13_dialog_content = "我能做什麼……我能……",
  ui_story_1020_10201001_14_option_content = "開始感應",
  ui_story_1020_10201001_15_dialog_content = "……",
  ui_story_1020_10201001_16_option_content = "開始感應",
  ui_story_1020_10201001_17_dialog_content = "……",
  ui_story_1020_10201001_18_dialog_content = "臨空者號……已經不在了嗎？",
  ui_story_1020_10201001_19_dialog_content = "今天走出實驗大樓那一刹那，我就有一種說不上來的感覺。",
  ui_story_1020_10201001_20_dialog_content = "我彷彿看見偌大的天井上方，有一束光會帶走我全部的希望……",
  ui_story_1020_10201001_21_dialog_content = "總覺得……我總覺得臨空者號會從那裡飛走……",
  ui_story_1020_10201001_22_dialog_content = "我……當時我為什麼會那樣想，我不知道……！",
  ui_story_1020_10201001_23_dialog_content = "包括之前的那些夢境，我早該有所察覺……",
  ui_story_1020_10201001_24_option_content = "開始感應",
  ui_story_1020_10201001_25_dialog_content = "……",
  ui_story_1020_10201001_26_option_content = "開始感應",
  ui_story_1020_10201001_27_dialog_content = "……",
  ui_story_1020_10201001_28_option_content = "開始感應",
  ui_story_1020_10201001_29_dialog_content = "……",
  ui_story_1020_10201001_30_dialog_content = "啊——！！！",
  ui_story_1020_10201001_31_dialog_content = "快停下來，PlayerName！",
  ui_story_1020_10201001_32_dialog_content = "你今天已經過度使用感應能力了，你的臉色非常糟糕！",
  ui_story_1020_10201001_33_dialog_content = "我已經和薇絲分開了……如果再和臨空者號分開，我就什麼也沒有了……",
  ui_story_1020_10201001_34_dialog_content = "……到底要臨空者號飛去什麼地方？工程師想做什麼？！",
  ui_story_1020_10201001_35_dialog_content = "這個問題，你可以問我——",
  ui_story_1020_10201001_36_dialog_content = "出鞘！",
  ui_story_1020_10201001_37_dialog_content = "薇薇安！",
  ui_story_1020_10201001_38_dialog_content = "……斐桀洛？",
  ui_story_1020_10201001_39_dialog_content = "輕，不、是嫩……",
  ui_story_1020_10201001_40_dialog_content = "嫩得我都不忍出手！",
  ui_story_1020_10201001_41_dialog_content = "呵呵，看著別人失去重要之物的滋味，就是這麼美好啊。",
  ui_story_1020_10201001_42_dialog_content = "……你早就知道臨空者號會飛走？！",
  ui_story_1020_10201001_43_dialog_content = "你怎麼不問我，我對臨空者號做了什麼？",
  ui_story_1020_10201001_44_dialog_content = "你……？！",
  ui_story_1020_10201001_45_dialog_content = "慢著，PlayerName，他看起來不對勁……",
  ui_story_1020_10201001_46_dialog_content = "他明明被關在監禁室裡動彈不得，竟然還能逃脫……",
  ui_story_1020_10201001_47_dialog_content = "不敢相信嗎？這就是祂的力量。",
  ui_story_1020_10201001_48_dialog_content = "那些鎖鏈雖然將我捆得狼狽，但我卻讓捆我的那些雜碎，在死亡瞬間盡享絕望之美。",
  ui_story_1020_10201001_49_dialog_content = "只不過味道嘛……跟空裔比起來，差遠了。",
  ui_story_1020_10201001_50_dialog_content = "哈哈哈！挑吧，空裔！你是要像你那些孱弱的同胞一樣，毫無用處地死去？",
  ui_story_1020_10201001_51_dialog_content = "還是願意成為我手中的見面禮，與我一同見證祂的威嚴？",
  ui_story_1020_10201001_52_dialog_content = "空裔不會無用地死去！工程師在哪裡？！",
  ui_story_1020_10201001_53_dialog_content = "哈哈哈哈！好！看來你選擇了後者。",
  ui_story_1020_10201001_54_dialog_content = "那麼你身邊這個雜碎，就可以放心去死了。",
  ui_story_1020_10201001_55_dialog_content = "你休想傷害PlayerName！",
  ui_story_1020_10201001_56_dialog_content = "看來妳想嚐嚐我的暗能？這可是用光靈的鮮血換來的。",
  ui_story_1020_10201001_57_dialog_content = "PlayerName！退到我後面。",
  ui_story_1020_10201001_58_dialog_content = "妳掙扎的樣子真是可笑……",
  ui_story_1020_10201001_59_dialog_content = "珍惜還能感知疼痛的幸福吧。偉大的時代即將來臨，祂會讓妳解脫。",
  ui_story_1020_10201001_60_dialog_content = "渡鴉——賜你品嘗空裔的鮮血！",
  ui_story_1020_10201001_61_dialog_content = "暗鬼！不許你——傷害PlayerName！",
  ui_story_1020_10201001_62_dialog_content = "還好即時趕到了！",
  ui_story_1020_10201001_63_dialog_content = "PlayerName！薇薇安長官！你們沒受傷吧？",
  ui_story_1020_10201001_64_dialog_content = "西恩？！快走！牠的暗能會把你打傷的！",
  ui_story_1020_10201001_65_dialog_content = "我知道！但我在保護你，PlayerName！",
  ui_story_1020_10201001_66_dialog_content = "怎麼樣？我的身手沒讓你失望吧？",
  ui_story_1020_10201001_67_dialog_content = "說什麼失望？西恩，你的身體，竟然承受得住他的攻擊！",
  ui_story_1020_10201001_68_dialog_content = "當然！我可是和鶯歌、阿克希亞一樣的超級戰士。",
  ui_story_1020_10201001_69_dialog_content = "同時也是有血有肉的光靈！",
  ui_story_1020_10201001_70_dialog_content = "參謀長、PlayerName，這隻暗鬼就交給我吧！",
  ui_story_1020_10201001_71_dialog_content = "小心，西恩！他的手段非常卑鄙。我們會在你身後消滅其它暗鬼來掩護你！",
  ui_story_1020_10201001_72_dialog_content = "好！",
  ui_story_1020_10201001_73_dialog_content = "哇……鮮嫩！太嫩了！",
  ui_story_1020_10201101_1_dialog_content = "區區幾個雜碎……也想攔我嗎？",
  ui_story_1020_10201101_2_dialog_content = "這一次，我必須完成使命……否則……",
  ui_story_1020_10201101_3_dialog_content = "你，長毛耳朵那個……被我的暗能打中之後竟能完好無損……",
  ui_story_1020_10201101_4_dialog_content = "是、是又怎麼樣？我不會讓你傷害我的夥伴！",
  ui_story_1020_10201101_5_dialog_content = "哼，看你的樣子也不奇怪……怪不得你們純種亞人族已經滅絕了，你卻活到現在。",
  ui_story_1020_10201101_6_dialog_content = "……你想說什麼？",
  ui_story_1020_10201101_7_dialog_content = "我斐桀洛有幸參與剿滅獸人族的偉大計畫，那是我為祂做出的最光榮之事。",
  ui_story_1020_10201101_8_dialog_content = "但顯然，那些奸懶狡猾的獸人為了存續，竟和光靈媾合苟活到現在！",
  ui_story_1020_10201101_9_dialog_content = "該說你們像蟑螂一樣生命力頑強嗎？",
  ui_story_1020_10201101_10_dialog_content = "住口！不許你這樣說西恩！",
  ui_story_1020_10201101_11_dialog_content = "怎麼？生氣了？想殺了我嗎？",
  ui_story_1020_10201101_12_dialog_content = "還想知道臨空者號去哪了嗎？還有啟光那個整天圍著你轉的黏巴達。",
  ui_story_1020_10201101_13_dialog_content = "那黏巴達遇到安妮莫妮，恐怕，死得很慘吧。",
  ui_story_1020_10201101_14_dialog_content = "……薇絲？薇絲遇到安妮莫妮……她到底發生了什麼事？！",
  ui_story_1020_10201101_15_dialog_content = "嗯？我想想，當時發生了什麼事……",
  ui_story_1020_10201101_16_dialog_content = "工程師在哪裡？臨空者號去了哪裡？告訴我！",
  ui_story_1020_10201101_17_dialog_content = "……",
  ui_story_1020_10201101_18_dialog_content = "噢！！！我偉大的主人——請不要遺棄我！",
  ui_story_1020_10201101_19_dialog_content = "……",
  ui_story_1020_10201101_20_dialog_content = "他在跟誰說話……「主人」？",
  ui_story_1020_10201101_21_dialog_content = "應該是意識中的溝通。「工程師」聯絡他了……",
  ui_story_1020_10201101_22_dialog_content = "要找到線索，或許要趁現在……",
  ui_story_1020_10201101_23_dialog_content = "PlayerName，你要做什麼？",
  ui_story_1020_10201101_24_option_content = "強制感應",
  ui_story_1020_10201101_25_dialog_content = "（呃啊——好難受的感覺……）",
  ui_story_1020_10201101_26_dialog_content = "（管不了那麼多了！）",
  ui_story_1020_10201101_27_dialog_content = "（薇絲到底發生什麼事，臨空者號飛去哪裡……）",
  ui_story_1020_10201101_28_dialog_content = "（我必須，找到答案……）",
  ui_story_1020_10201101_29_dialog_content = "身體消瘦虛弱，樣貌也十分醜陋。",
  ui_story_1020_10201101_30_dialog_content = "我、我不在乎！只要有您的印記，那些卑賤的光靈和暗鬼都將俯首於我。",
  ui_story_1020_10201101_31_dialog_content = "俯首於你？那我呢？",
  ui_story_1020_10201101_32_dialog_content = "您的威嚴讓我顫抖，我將畢生做您的羽翼！",
  ui_story_1020_10201101_33_dialog_content = "你願意戴上這認可你身分的「圓環」嗎？",
  ui_story_1020_10201101_34_dialog_content = "「圓環」……",
  ui_story_1020_10201101_35_dialog_content = "願意！那是您賜予我的恩典，是我生命的意義，是高貴之靈才配擁有的印記！",
  ui_story_1020_10201101_36_dialog_content = "跪謝您，無上的主宰！",
  ui_story_1020_10201101_37_dialog_content = "好。",
  ui_story_1020_10201101_38_dialog_content = "請賜予我、我……啊啊——！！！",
  ui_story_1020_10201101_39_dialog_content = "我的……我的頭！痛、痛死我了……救、救我……無上的、主宰……",
  ui_story_1020_10201101_40_dialog_content = "（這是斐桀洛以前的記憶……而那個聲音正是工程師……）",
  ui_story_1020_10201101_41_dialog_content = "（日蝕的罪靈，自願戴上那個象徵枷鎖的「圓環」……）",
  ui_story_1020_10201101_42_dialog_content = "（……）",
  ui_story_1020_10201101_43_dialog_content = "（沒想到我的感應能力竟然能看到這麼遠……是自從出現工程師的夢境後？）",
  ui_story_1020_10201101_44_dialog_content = "（還是在阿爾戈爾的訓練下，成功感應了布林之後……？）",
  ui_story_1020_10201101_45_dialog_content = "（如果要尋找薇絲和臨空者號的線索，或許要延伸至最近……）",
  ui_story_1020_10201101_46_option_content = "感應延伸——",
  ui_story_1020_10201101_47_dialog_content = "（呃……這個暗能……和感應布林的時候一樣難受。）",
  ui_story_1020_10201101_48_dialog_content = "（但經歷過那樣的體驗後，這個感覺也能承受了……）",
  ui_story_1020_10201101_49_dialog_content = "（嗯……？這是暗面？）",
  ui_story_1020_10201101_50_dialog_content = "（這麼大的坑洞……裂縫似乎還在往遠處蔓延一般……）",
  ui_story_1020_10201101_51_dialog_content = "（這難道就是工程師說的……遠古戰爭的遺跡？）",
  ui_story_1020_10201101_52_dialog_content = "（究竟發生了什麼事，這裡最終變成這個樣子……）",
  ui_story_1020_10201101_53_dialog_content = "（這四周……不像是有巨像的樣子……）",
  ui_story_1020_10201101_54_option_content = "感應延伸——",
  ui_story_1020_10201101_55_dialog_content = "（這裡是……巨像的殘骸堆？）",
  ui_story_1020_10201101_56_dialog_content = "（一艘、兩艘、三艘……）",
  ui_story_1020_10201101_57_dialog_content = "（……）",
  ui_story_1020_10201101_58_dialog_content = "（所謂的「巨像停泊之地」……）",
  ui_story_1020_10201101_59_dialog_content = "（平整的荒灘……跟回歸塔差好多。）",
  ui_story_1020_10201101_60_dialog_content = "（它們都經歷了些什麼……風化得只剩下形似巨龍的骨骼……）",
  ui_story_1020_10201101_61_dialog_content = "（這到底是多久之前的場景？感受不到一絲生命的氣息……）",
  ui_story_1020_10201101_62_dialog_content = "（對了，「守護者一號」核心……）",
  ui_story_1020_10201101_63_dialog_content = "（那個出現在臨空者號資料中的座標，或許就是線索……）",
  ui_story_1020_10201101_64_dialog_content = "（座標……發光的柱子……）",
  ui_story_1020_10201101_65_option_content = "感應延伸——",
  ui_story_1020_10201101_66_dialog_content = "（是這裡！）",
  ui_story_1020_10201101_67_dialog_content = "（沒錯，和之前在尤利西斯意識中見過的一樣……）",
  ui_story_1020_10201101_68_dialog_content = "（這些發光的柱子正是「守護者一號」的核心，現在看得更清楚了……）",
  ui_story_1020_10201101_69_dialog_content = "（石頭在向上移動，上方一定有什麼東西……）",
  ui_story_1020_10201101_70_dialog_content = "準備好了？",
  ui_story_1020_10201101_71_dialog_content = "是的，最後一個<color=#FFB400>驅動環</color>已經到手。",
  ui_story_1020_10201101_72_dialog_content = "好。",
  ui_story_1020_10201101_73_dialog_content = "唸您尊名，盼您注視——",
  ui_story_1020_10201101_74_dialog_content = "吾等，恭候您的降臨——",
  ui_story_1020_10201101_75_dialog_content = "妳是誰？",
  ui_story_1020_10201101_76_dialog_content = "……",
  ui_story_1020_10201101_77_dialog_content = "啟光的小丫頭，還是個科學家。",
  ui_story_1020_10201101_78_dialog_content = "啟光。",
  ui_story_1020_10201101_79_dialog_content = "那隻沒用的渡鴉，也在啟光。",
  ui_story_1020_10201101_80_dialog_content = "「啟光」。真是個令人懷念的名字。",
  ui_story_1020_10201101_81_dialog_content = "<color=#e8d9bb>轟隆隆——</color>",
  ui_story_1020_10201101_82_dialog_content = "（剛才的場景……原來不是夢……）",
  ui_story_1020_10201101_83_dialog_content = "（但之前有看到薇絲，這次沒有……而是看到吞羅……）",
  ui_story_1020_10201101_84_dialog_content = "（她身邊的那些，是罪靈嗎……）",
  ui_story_1020_10201101_85_dialog_content = "是您、是您……無上的主宰！",
  ui_story_1020_10201101_86_dialog_content = "您忠誠的奴僕，斐桀洛，在此跪候您的降臨。",
  ui_story_1020_10201101_87_dialog_content = "你一事無成。",
  ui_story_1020_10201101_88_dialog_content = "我曾經輝煌過！偉大的主人！我曾經領導屠殺獸人族的行動——",
  ui_story_1020_10201101_89_dialog_content = "那已經是幾百年前的事了。",
  ui_story_1020_10201101_90_dialog_content = "我給你的東西，在我需要的時候，我都會拿回來。",
  ui_story_1020_10201101_91_dialog_content = "您不會……您不會這麼做的，對吧！我是您親手打造的羽翼！",
  ui_story_1020_10201101_92_dialog_content = "我會替你斬斷鎖鏈。",
  ui_story_1020_10201101_93_dialog_content = "如果想證明你對日蝕還有一點價值，就把空裔帶回我身邊來。",
  ui_story_1020_10201101_94_dialog_content = "我還有足夠的力量啟動巨像。",
  ui_story_1020_10201101_95_dialog_content = "<color=#e8d9bb>咔嚓——</color>",
  ui_story_1020_10201101_96_dialog_content = "……",
  ui_story_1020_10201101_97_dialog_content = "顫、顫抖！絕、絕不敢違背您的意志！",
  ui_story_1020_10201101_98_dialog_content = "（……）",
  ui_story_1020_10201101_99_dialog_content = "（工程師來到迦南城，是為了召回罪靈……）",
  ui_story_1020_10201101_100_dialog_content = "（同時也要把我和臨空者號帶回去……）",
  ui_story_1020_10201101_101_dialog_content = "喜歡嗎？",
  ui_story_1020_10201101_102_dialog_content = "你……在注視我？",
  ui_story_1020_10201101_103_dialog_content = "一直注視著。",
  ui_story_1020_10201101_104_dialog_content = "你的視野，是我賜予的。你應該感謝我，讓你看到高塔戰場的壯麗。",
  ui_story_1020_10201101_105_dialog_content = "高塔戰場……那是真實發生過的事……？！",
  ui_story_1020_10201101_106_dialog_content = "只有真實才有價值。",
  ui_story_1020_10201101_107_dialog_content = "那個裂縫處，曾是我的家園。但那場戰爭，讓我支離破碎。",
  ui_story_1020_10201101_108_dialog_content = "我尋找碎片，將我的底座拼湊完整，然後重啟心臟。",
  ui_story_1020_10201101_109_dialog_content = "那些巨像，為了我的事業耗盡核心。",
  ui_story_1020_10201101_110_dialog_content = "……臨空者號也會成為你的犧牲品？！你難道想摧毀這個世界……",
  ui_story_1020_10201101_111_dialog_content = "我不想。",
  ui_story_1020_10201101_112_dialog_content = "你會明白的。你和我是一樣的。",
  ui_story_1020_10201101_113_dialog_content = "……",
  ui_story_1020_10201101_114_dialog_content = "……臨空者號到底去了哪裡？",
  ui_story_1020_10201101_115_dialog_content = "……薇絲到底怎麼了？！",
  ui_story_1020_10201101_116_dialog_content = "……",
  ui_story_1020_10201101_117_dialog_content = "（……越來越黑了……）",
  ui_story_1020_10201101_118_dialog_content = "記住，光明只會蒙蔽你的雙眼。唯有黑暗是最真誠的底色。",
  ui_story_1020_10201101_119_dialog_content = "接受黑暗，融入黑暗，讓黑暗成為你的力量。",
  ui_story_1020_10201101_120_dialog_content = "不要！",
  ui_story_1020_10201101_121_dialog_content = "讓黑暗成為你的力量。",
  ui_story_1020_10201101_122_dialog_content = "我不要戴上枷鎖！",
  ui_story_1020_10201101_123_dialog_content = "（這樣下去，黑暗真的會將我吞噬……）",
  ui_story_1020_10201102_1_dialog_content = "<color=#e8d9bb>嘩啦啦——</color>",
  ui_story_1020_10201102_2_dialog_content = "（黑暗之中的琴聲……）",
  ui_story_1020_10201102_3_dialog_content = "（這裡……好亮啊……）",
  ui_story_1020_10201102_4_dialog_content = "（這流動的波光，應該是湖面……）",
  ui_story_1020_10201102_5_dialog_content = "（這裡是北境的……極光？）",
  ui_story_1020_10201102_6_dialog_content = "（嗯？那是什麼……）",
  ui_story_1020_10201102_7_dialog_content = "PlayerName。",
  ui_story_1020_10201102_8_dialog_content = "臨空者號？！真的是你嗎？臨空者號——！！！",
  ui_story_1020_10201102_9_dialog_content = "剛才，我好像聽見鋼琴聲。沒想到就聽到你的聲音，PlayerName。",
  ui_story_1020_10201102_10_dialog_content = "琴聲……？我也聽到了！沒想到還能感應到你！",
  ui_story_1020_10201102_11_dialog_content = "臨空者號，你現在在哪裡？！",
  ui_story_1020_10201102_12_dialog_content = "……",
  ui_story_1020_10201102_13_dialog_content = "我不知道。",
  ui_story_1020_10201102_14_dialog_content = "……",
  ui_story_1020_10201102_15_dialog_content = "是他在對你下指令，對嗎？",
  ui_story_1020_10201102_16_dialog_content = "……",
  ui_story_1020_10201102_17_dialog_content = "臨空者號，能不能……不要走？",
  ui_story_1020_10201102_18_dialog_content = "……",
  ui_story_1020_10201102_19_dialog_content = "抱歉，PlayerName。",
  ui_story_1020_10201102_20_dialog_content = "空裔一族，終其一生都在做著自由的夢……",
  ui_story_1020_10201102_21_dialog_content = "短時間內的資訊流，讓我看見在遇到你之前，空裔和巨像經歷的事情……",
  ui_story_1020_10201102_22_dialog_content = "我看見無數代空裔和巨像，做著掙脫枷鎖的努力。",
  ui_story_1020_10201102_23_dialog_content = "這一次……",
  ui_story_1020_10201102_24_dialog_content = "我好像失敗了。",
  ui_story_1020_10201102_25_dialog_content = "臨空者號……不要離開……",
  ui_story_1020_10201102_26_dialog_content = "我們一起擺脫這些枷鎖，好嗎？",
  ui_story_1020_10201102_27_dialog_content = "……",
  ui_story_1020_10201102_28_dialog_content = "此刻，我既是臨空者號，也是「領導者號」……",
  ui_story_1020_10201102_29_dialog_content = "還是「孤高者號」、「探索者號」、「呼喚者號」、「跨越者號」……",
  ui_story_1020_10201102_30_dialog_content = "我能做的，就是像前輩們一樣，竭盡全力保護好自己的導航員。",
  ui_story_1020_10201102_31_dialog_content = "在與你相伴的這些日子裡，每一次與你一同飛翔，都是我生命中最美妙的時刻。",
  ui_story_1020_10201102_32_dialog_content = "如果我能擺脫枷鎖，我們一定會再相見的。",
  ui_story_1020_10201102_33_dialog_content = "臨空者號……",
  ui_story_1020_10201102_34_dialog_content = "因為，無論接收多少訊號……",
  ui_story_1020_10201102_35_dialog_content = "如果臨空者號有「心」，那麼臨空者號的「心」裡，只聽得到PlayerName的聲音。",
  ui_story_1020_10201102_36_dialog_content = "……",
  ui_story_1020_10201102_37_dialog_content = "臨空者號……",
  ui_story_1020_10201102_38_dialog_content = "臨空者號？！",
  ui_story_1020_10201102_39_dialog_content = "PlayerName……",
  ui_story_1020_10201102_40_option_content = "開始感應",
  ui_story_1020_10201102_41_dialog_content = "……",
  ui_story_1020_10201102_42_option_content = "感應連接——",
  ui_story_1020_10201102_43_dialog_content = "……",
  ui_story_1020_10201102_44_option_content = "感應連接——！！！",
  ui_story_1020_10201102_45_dialog_content = "……",
  ui_story_1020_10201102_46_option_content = "感應連接——！！！",
  ui_story_1020_10201102_47_dialog_content = "PlayerName！",
  ui_story_1020_10201102_48_dialog_content = "……",
  ui_story_1020_10201102_49_dialog_content = "感應不到……",
  ui_story_1020_10201102_50_dialog_content = "完全感應不到——！",
  ui_story_1020_10201102_51_dialog_content = "PlayerName……你終於醒了，你沒事吧？",
  ui_story_1020_10201102_52_dialog_content = "PlayerName的樣子讓阿克希亞很心痛。",
  ui_story_1020_10201102_53_dialog_content = "你剛才自言自語的樣子真是太嚇人了。還好西恩制服了斐桀洛，你才睜開眼睛！",
  ui_story_1020_10201102_54_dialog_content = "其實是大家一起制服他的！",
  ui_story_1020_10201102_55_dialog_content = "......？",
  ui_story_1020_10201102_56_dialog_content = "我們親眼看著他化成一團暗能消失的……",
  ui_story_1020_10201102_57_dialog_content = "那樣的暗能，只有西恩能承受得住。",
  ui_story_1020_10201102_58_dialog_content = "（斐桀洛……真的是大家制服的嗎？）",
  ui_story_1020_10201102_59_dialog_content = "（快要陷入無盡的黑暗之時，那個琴聲和發光的湖面又是怎麼回事……）",
  ui_story_1020_10201102_60_dialog_content = "到底發生了什麼事，PlayerName？你剛剛強制感應斐桀洛，還發出奇怪的聲音……",
  ui_story_1020_10201102_61_dialog_content = "我感應到臨空者號了……",
  ui_story_1020_10201102_62_dialog_content = "臨空者號？！它在哪？",
  ui_story_1020_10201102_63_dialog_content = "臨空者號為了保護我，離開了……",
  ui_story_1020_10201102_64_dialog_content = "……",
  ui_story_1020_10201102_65_dialog_content = "PlayerName，臨空者號的事情之後再說好嗎？我們先去跟大元帥他們會合吧。",
  ui_story_1020_10201102_66_dialog_content = "你獨自在這裡真的非常危險，要不是他們三人及時趕到，我們恐怕已經落入斐桀洛手裡了。",
  ui_story_1020_10201102_67_dialog_content = "謝謝你們……",
  ui_story_1020_10201102_68_dialog_content = "走吧，等危機過去，我們一定能找回臨空者號！",
  ui_story_1020_10201102_69_dialog_content = "嗯……",
  ui_story_1020_10201102_70_dialog_content = "（工程師……我是透過斐桀洛的意識看到的……）",
  ui_story_1020_10201102_71_dialog_content = "（要找到線索……）",
  ui_story_1020_10201102_72_dialog_content = "PlayerName，剛才真的非常危險，如果不是他們三小只及時趕到，我們恐怕已經——",
  ui_story_1020_10201102_73_dialog_content = "我知道了……！",
  ui_story_1020_10201102_74_dialog_content = "PlayerName！先去和大元帥他們會合！",
  ui_story_1020_10201201_1_dialog_content = "布布！",
  ui_story_1020_10201201_2_dialog_content = "布林的意思是……這一次的防禦模組應該沒有問題了吧？",
  ui_story_1020_10201201_3_dialog_content = "應該吧？哈哈……哈哈哈哈哈哈！",
  ui_story_1020_10201201_4_dialog_content = "哎呀——手指頭和肩膀的痠痛感，這麼快就上來了——",
  ui_story_1020_10201201_5_dialog_content = "多虧各位的掩護，完成得比預期還快……沒想到光靠腦子的戰鬥竟然也能這麼艱難……",
  ui_story_1020_10201201_6_dialog_content = "這遠古機器，果然不簡單！",
  ui_story_1020_10201201_7_dialog_content = "<color=#e8d9bb>嗶——嗶——嗶——</color>",
  ui_story_1020_10201201_8_dialog_content = "啊？新程式執行還是會報錯……",
  ui_story_1020_10201201_9_dialog_content = "是工程師還在某處攻擊我們……還是「守護者」的模組本身就有問題啊！",
  ui_story_1020_10201201_10_dialog_content = "<size=45>布布布布——！！！</size>",
  ui_story_1020_10201201_11_dialog_content = "再看看……再看看……",
  ui_story_1020_10201201_12_dialog_content = "欸？尤利西斯呢？讓我採訪一下他啊！這些年他到底在對這部機器做什麼……",
  ui_story_1020_10201201_13_dialog_content = "我是不是，仍然需要一個能處理複雜計算的核心啊……？",
  ui_story_1020_10201201_14_dialog_content = "布布？",
  ui_story_1020_10201201_15_dialog_content = "尤利西斯剛才似乎受到刺激，一直在那邊閉著眼睛，沒有動靜。",
  ui_story_1020_10201201_16_dialog_content = "萊因哈特，趁這部機器穩定下來，超級兵也停止發動攻擊的空檔……",
  ui_story_1020_10201201_17_dialog_content = "我們必須盡快處理剩下的超級兵，防止發生剛剛那樣的襲擊。",
  ui_story_1020_10201201_18_dialog_content = "我也同意。而且這些超級兵怎麼說都是我們的士兵……或許黑傘實驗室還能治好他們。",
  ui_story_1020_10201201_19_dialog_content = "……源頭上，他們都似乎被原型機操縱著。恐怕只能等阿爾戈爾博士那邊的模組搭建好才有救。",
  ui_story_1020_10201201_20_dialog_content = "阿爾戈爾博士，我們現在能做些什麼嗎？",
  ui_story_1020_10201201_21_dialog_content = "要處理這些超級兵確實不容易。",
  ui_story_1020_10201201_22_dialog_content = "這些纜線或許埋在更深的地方，靠人力清除恐怕至少要花上好幾個禮拜。",
  ui_story_1020_10201201_23_dialog_content = "這其中還有可能遇到其他風險……看來調取「守護者」的模組來補上核心是行不通了……",
  ui_story_1020_10201201_24_dialog_content = "我必須建一套完全脫離工程師和「守護者」的防禦系統，補上迦南城的防禦漏洞才行！",
  ui_story_1020_10201201_25_dialog_content = "你的意思是不靠任何其他科技，搭建一套屬於啟光自己的防禦系統，啟光自研系統？",
  ui_story_1020_10201201_26_dialog_content = "你說對了。不過目前核心算力不足，要一邊防禦可能的攻擊，一邊搭建就更困難了。",
  ui_story_1020_10201201_27_dialog_content = "如果有其他的運算核心，能幫我平行處理資料就好了……",
  ui_story_1020_10201201_28_dialog_content = "阿爾戈爾博士，調用迦南城其他的電腦裝置，可以幫上忙嗎？",
  ui_story_1020_10201201_29_dialog_content = "現在根本沒有多少閒置電腦可用，對算力的幫助不大。",
  ui_story_1020_10201201_30_dialog_content = "我想說的不是閒置電腦，而是迦南城的全部電腦！",
  ui_story_1020_10201201_31_dialog_content = "全部？如果是全部電腦核心的算力……應該能幫上不少忙。",
  ui_story_1020_10201201_32_dialog_content = "但是這樣做的話，所有工程設備的運轉都會暫停，城門大開，維生系統會當機……",
  ui_story_1020_10201201_33_dialog_content = "這麼大一座迦南城，能脫離這些至關重要的設施哪怕一分鐘嗎？",
  ui_story_1020_10201201_34_dialog_content = "……",
  ui_story_1020_10201201_35_dialog_content = "其實新搭建的防禦系統也需要檢驗。如果替代不了能處理複雜計算的核心，馬上又會崩潰。",
  ui_story_1020_10201201_36_dialog_content = "我現在做的事情，也只是在猜測工程師的行為，和他對賭而已。",
  ui_story_1020_10201201_37_dialog_content = "布！布！布！",
  ui_story_1020_10201201_38_dialog_content = "不行。",
  ui_story_1020_10201201_39_dialog_content = "布布！！！",
  ui_story_1020_10201201_40_dialog_content = "你也是原型機的一部分啊。",
  ui_story_1020_10201201_41_dialog_content = "布！布！布！",
  ui_story_1020_10201201_42_dialog_content = "布林是想到什麼方法嗎？",
  ui_story_1020_10201201_43_dialog_content = "布林想自願去當迦南城的防禦系統核心。",
  ui_story_1020_10201201_44_dialog_content = "布林……？它怎麼做得到呢？",
  ui_story_1020_10201201_45_dialog_content = "是啊，它本身是原型機的一部分，對我來說就是個來搗亂的助手罷了。",
  ui_story_1020_10201201_46_dialog_content = "布布！！！",
  ui_story_1020_10201201_47_dialog_content = "布林明明幫了阿爾戈爾博士不少忙！",
  ui_story_1020_10201201_48_dialog_content = "布！",
  ui_story_1020_10201201_49_dialog_content = "嗶嚕——",
  ui_story_1020_10201201_50_dialog_content = "請阿爾戈爾打開一號的<color=#FFB400>維修艙</color>。",
  ui_story_1020_10201201_51_dialog_content = "用一號的<color=#FFB400>核心</color>，來守護迦南城。",
  ui_story_1020_10201201_52_dialog_content = "啊……？",
  ui_story_1020_10201201_53_dialog_content = "一號現在想放棄人工智慧的部分，只當一部能防堵資料攻擊的機器。",
  ui_story_1020_10201201_54_dialog_content = "我幫你安裝那麼多程式，可不是為了讓你現在放棄智慧，成為守護迦南城的機器啊，一號。",
  ui_story_1020_10201201_55_dialog_content = "一號知道。阿爾戈爾希望一號能處理光靈間複雜的對話，希望一號成為阿爾戈爾的朋友。",
  ui_story_1020_10201201_56_dialog_content = "但是阿爾戈爾需要一號。請用一號的核心守護迦南城。",
  ui_story_1020_10201201_57_dialog_content = "不行。",
  ui_story_1020_10201201_58_dialog_content = "請阿爾戈爾用一號的核心，來守護迦南城。",
  ui_story_1020_10201201_59_dialog_content = "不行！",
  ui_story_1020_10201201_60_dialog_content = "嗶嚕——請阿爾戈爾用一號的核心，來守護迦南城。",
  ui_story_1020_10201201_61_dialog_content = "我說不行就是不行！",
  ui_story_1020_10201201_62_dialog_content = "我說不行就是不行！",
  ui_story_1020_10201201_63_dialog_content = "……",
  ui_story_1020_10201201_64_dialog_content = "你……什麼時候學會挖苦人的啊……？",
  ui_story_1020_10201201_65_dialog_content = "一號想了好久才懂，阿爾戈爾當時回我「嗶嚕嗶嚕嗶嚕」，其實什麼都沒說。",
  ui_story_1020_10201201_66_dialog_content = "……",
  ui_story_1020_10201201_67_dialog_content = "你這樣我更捨不得你了，你知道嗎？",
  ui_story_1020_10201201_68_dialog_content = "一號知道。但是這是一號的請求。請阿爾戈爾用一號的核心，來守護迦南城。",
  ui_story_1020_10201201_69_dialog_content = "守護迦南城，你知道你會面臨什麼嗎？",
  ui_story_1020_10201201_70_dialog_content = "這裡不僅有複雜的纜線，還會有邪惡的攻擊入侵你的思維……",
  ui_story_1020_10201201_71_dialog_content = "可能會封鎖你的思考能力，甚至讓你像暗鬼一樣攻擊啟光！",
  ui_story_1020_10201201_72_dialog_content = "這不是簡單的遷移，是完全放棄創造性和適應性，成為千千萬萬個只會執行開關指令的大門！",
  ui_story_1020_10201201_73_dialog_content = "一號不會胡思亂想。因為阿爾戈爾曾經告訴過一號，思考是光靈的特長。",
  ui_story_1020_10201201_74_dialog_content = "有阿爾戈爾這樣的智慧導師，一號可以放棄思考，只做好守護迦南城這一件事。",
  ui_story_1020_10201201_75_dialog_content = "你這個連咖啡都不願意幫我倒的傢伙，竟然……",
  ui_story_1020_10201201_76_dialog_content = "一號知道，阿爾戈爾不希望一號只當她的管家機器人，而是成為會和她打鬧的夥伴。",
  ui_story_1020_10201201_77_dialog_content = "一號有個條件，如果一號以後要住在這裡，請把這裡佈置得像阿爾戈爾的辦公室一樣，放些植物增添綠意。",
  ui_story_1020_10201201_78_dialog_content = "等以後有了二號、三號，也請替他們設計一些方便活動的軀殼，不要像一號一樣……",
  ui_story_1020_10201201_79_dialog_content = "阿爾戈爾常說一號像個郵筒，想往一號嘴裡塞信箋。",
  ui_story_1020_10201201_80_dialog_content = "……",
  ui_story_1020_10201201_81_dialog_content = "對了，還有一件事要告訴阿爾戈爾……",
  ui_story_1020_10201201_82_dialog_content = "一號在和PlayerName意識溝通時，擅自做了一些阿爾戈爾不知道的事。",
  ui_story_1020_10201201_83_dialog_content = "……？",
  ui_story_1020_10201201_84_dialog_content = "但正是那次溝通，讓一號相信，一號可以把全部意識託付給PlayerName。",
  ui_story_1020_10201201_85_dialog_content = "阿爾戈爾如果需要朋友，一號很推薦PlayerName。",
  ui_story_1020_10201201_86_dialog_content = "……",
  ui_story_1020_10201201_87_dialog_content = "再見了，阿爾戈爾。",
  ui_story_1020_10201201_88_dialog_content = "一號喜歡阿爾戈爾替他設計的新表情。",
  ui_story_1020_10201201_89_dialog_content = "嗶嚕——嗶嚕——嗶——嚕——",
  ui_story_1020_10201201_90_dialog_content = "<color=#e8d9bb>咔嚓——</color>",
  ui_story_1020_10201201_91_dialog_content = "布……",
  ui_story_1020_10201201_92_dialog_content = "嗶嚕嗶嚕嗶嚕。",
  ui_story_1020_10201201_93_dialog_content = "……",
  ui_story_1020_10201201_94_dialog_content = "大元帥，我們難道就沒有其他辦法了嗎？",
  ui_story_1020_10201201_95_dialog_content = "……",
  ui_story_1020_10201201_96_dialog_content = "這或許是目前唯一的辦法。早在工程師第一次出現的時候，我就想過了。",
  ui_story_1020_10201201_97_dialog_content = "阿爾戈爾博士，我知道對你來說，他們是你的朋友。",
  ui_story_1020_10201201_98_dialog_content = "是我唯一的朋友。",
  ui_story_1020_10201201_99_dialog_content = "但是，哪會有人把朋友像這樣拿在手上？哈哈……！",
  ui_story_1020_10201201_100_dialog_content = "真是個自以為是的郵筒……",
  ui_story_1020_10201201_101_dialog_content = "自以為是……！",
  ui_story_1020_10201201_102_dialog_content = "阿爾戈爾，有了核心之後，妳說的「脫離至關重要的設施哪怕一分鐘」的前提還在嗎？",
  ui_story_1020_10201201_103_dialog_content = "……？",
  ui_story_1020_10201201_104_dialog_content = "集中迦南城全部電腦核心的算力，協助妳完成核心替換。",
  ui_story_1020_10201201_105_dialog_content = "布！布！布！",
  ui_story_1020_10201201_106_dialog_content = "一分鐘，我做不到。",
  ui_story_1020_10201201_107_dialog_content = "那就十分鐘！調用全部電腦，用人力補上設施的不足，這樣能夠幫上妳嗎？",
  ui_story_1020_10201201_108_dialog_content = "妳……認真的？",
  ui_story_1020_10201201_109_dialog_content = "認真的。",
  ui_story_1020_10201201_110_dialog_content = "阿爾戈爾博士，啟光人不是靠改造光靈才活下來。",
  ui_story_1020_10201201_111_dialog_content = "也不是靠這遠古機器才活下來。",
  ui_story_1020_10201201_112_dialog_content = "沒錯。雖然尤利西斯認為，是啟光依賴了「守護者」六百多年……",
  ui_story_1020_10201201_113_dialog_content = "但我始終相信，是軍人鑄成啟光的銅牆鐵壁。",
  ui_story_1020_10201201_114_dialog_content = "如果連這十分鐘都做不到，啟光永遠不可能在艾斯特拉大陸上立足。所以就算冒險也要嘗試！",
  ui_story_1020_10201201_115_dialog_content = "如果你願意，可以把我的命也拿在手裡。因為我願意當那個相信你的朋友。",
  ui_story_1020_10201201_116_dialog_content = "……",
  ui_story_1020_10201201_117_dialog_content = "還有我。",
  ui_story_1020_10201201_118_dialog_content = "還有我！",
  ui_story_1020_10201201_119_dialog_content = "……和所謂相信自己的「朋友」一起，做一件單靠自己完成不了的事情嗎？",
  ui_story_1020_10201201_120_dialog_content = "這好像是學生時期才會有的熱血場面了，哈哈。",
  ui_story_1020_10201201_121_dialog_content = "但我願意試試看。",
  ui_story_1020_10201201_122_dialog_content = "啾——最喜歡和朋友一起玩遊戲啦！",
  ui_story_1020_10201201_123_dialog_content = "那麼，開始吧！緋，立刻撥通戰時全域緊急頻道，我要下達指令。",
  ui_story_1020_10201201_124_dialog_content = "遵命！",
  ui_story_1020_10201201_125_dialog_content = "<color=#e8d9bb>嗶嗶——</color>",
  ui_story_1020_10201201_126_dialog_content = "大元帥。",
  ui_story_1020_10201201_127_dialog_content = "啊，還以為這個頻道永遠都用不到呢。",
  ui_story_1020_10201201_128_dialog_content = "現在緊急調用全部電腦，用人力補上設施的不足，持續十分鐘。",
  ui_story_1020_10201201_129_dialog_content = "同時，迦南城的防禦，需要我們各自負責。",
  ui_story_1020_10201201_130_dialog_content = "大元帥儘管吩咐！",
  ui_story_1020_10201201_131_dialog_content = "靠近地面的隔離帶、守備樓層和緩衝樓層會直接暴露在暗鬼面前。巴頓，你負責這部分。",
  ui_story_1020_10201201_132_dialog_content = "遵命！",
  ui_story_1020_10201201_133_dialog_content = "希羅娜迅速回援迦南城，從外圍掃蕩暗鬼。工程隊應該已經完成遷移居民了。",
  ui_story_1020_10201201_134_dialog_content = "遵命。",
  ui_story_1020_10201201_135_dialog_content = "緋，農業區、礦區、工業區、庫房區交給妳。",
  ui_story_1020_10201201_136_dialog_content = "有少部分軍民仍在維持機械運轉，沒有遷移，請隨時為上層和下層區域提供支援。",
  ui_story_1020_10201201_137_dialog_content = "沒問題。",
  ui_story_1020_10201201_138_dialog_content = "我呢？",
  ui_story_1020_10201201_139_dialog_content = "研究區實驗暗鬼眾多，雷霆，帶妳的部下找到所有存放暗鬼的倉庫，務必阻止牠們往上層移動。",
  ui_story_1020_10201201_140_dialog_content = "遵命！",
  ui_story_1020_10201201_141_dialog_content = "布布！布布！布布！",
  ui_story_1020_10201201_142_dialog_content = "繞過「守護者」系統築起新的牢籠，繼續屈身在這地下城……",
  ui_story_1020_10201201_143_dialog_content = "你們都是習慣黑暗的人……",
  ui_story_1020_10201201_144_dialog_content = "尤利西斯的身體，怎麼會……",
  ui_story_1020_10201201_145_dialog_content = "是我的失誤……剛才一直在集中精力解決超級兵，沒注意尤利西斯竟然自己上了手術台？",
  ui_story_1020_10201201_146_dialog_content = "這麼短的時間內，他就完成了身體改造？",
  ui_story_1020_10201201_147_dialog_content = "……他的改造恐怕已經持續很久了，不是剛剛才開始的。",
  ui_story_1020_10201201_148_dialog_content = "防禦永無止境，唯有正面對抗……有了這副軀體，就不再需要守護核心！",
  ui_story_1020_10201201_149_dialog_content = "尤利西斯，敢輕舉妄動我就割下你的腦袋！",
  ui_story_1020_10201201_150_dialog_content = "等等——大家先退後！",
  ui_story_1020_10201201_151_dialog_content = "我說過，我從來不怕「暗面恐懼」……",
  ui_story_1020_10201201_152_dialog_content = "就算他們都失敗了……",
  ui_story_1020_10201201_153_dialog_content = "我也會自己上！",
  ui_story_1020_10201201_154_dialog_content = "<color=#e8d9bb>嗶——嗶——嗶——</color>",
  ui_story_1020_10201201_155_dialog_content = "……！資料超載？！難道是因為尤利西斯？",
  ui_story_1020_10201201_156_dialog_content = "……",
  ui_story_1020_10201201_157_dialog_content = "大元帥，要繼續執行任務嗎？",
  ui_story_1020_10201201_158_dialog_content = "布林，準備執行指令！",
  ui_story_1020_10201201_159_dialog_content = "布布布布！",
  ui_story_1020_10201201_160_dialog_content = "所有人，按定原計劃行動！務必確保阿爾戈爾博士成功替換核心！這裡就交給我！",
  ui_story_1020_10201201_161_dialog_content = "是！",
  ui_story_1020_10201201_162_dialog_content = "遵命！",
  ui_story_1020_10201201_163_dialog_content = "知道了，大元帥！",
  ui_story_1020_10201201_164_dialog_content = "<color=#e8d9bb>轟隆隆——！！！</color>",
  ui_story_1020_10201201_165_dialog_content = "大家小心！超級兵倉庫又打開了！",
  ui_story_1020_10201201_166_dialog_content = "是衝著尤利西斯來的嗎……",
  ui_story_1020_10201201_167_dialog_content = "有了這副軀體，就不再需要守護核心！",
  ui_story_1020_10201201_168_dialog_content = "愚蠢！自以為強化身體就無敵了嗎……",
  ui_story_1020_10201201_169_dialog_content = "這種程度的改造，只要工程師想，隨意伸出一根纜線都能控制你！",
  ui_story_1020_10201201_170_dialog_content = "倉庫裡全是纜線……",
  ui_story_1020_10201201_171_dialog_content = "萊因哈特！叫剩下的人也離開！這些纜線可能會控制大家！",
  ui_story_1020_10201201_172_dialog_content = "這裡留下妳一個人就夠了！我必須確保新搭建的防禦系統安全無虞！",
  ui_story_1020_10201201_173_dialog_content = "大家照阿爾戈爾說的做！",
  ui_story_1020_10201201_174_dialog_content = "妳把我當成什麼了？我怎麼可能讓你們倆在這裡對付這些超級兵？",
  ui_story_1020_10201201_175_dialog_content = "我會為妳們掩護的，大元帥！",
  ui_story_1020_10201201_176_dialog_content = "還有我！",
  ui_story_1020_10201201_177_dialog_content = "超級兵就交給妳們了！看好尤利西斯！",
  ui_story_1020_10201201_178_dialog_content = "布林，找到接線口！切斷超級兵和原型機的連線！然後，替換核心！",
  ui_story_1020_10201201_179_dialog_content = "布布布布！",
  ui_story_1020_10201301_1_dialog_content = "布布！",
  ui_story_1020_10201301_2_dialog_content = "成功了……成功了！哈哈哈哈哈哈！",
  ui_story_1020_10201301_3_dialog_content = "一號！一號！！了不起啊，一號！！！",
  ui_story_1020_10201301_4_dialog_content = "布！",
  ui_story_1020_10201301_5_dialog_content = "大元帥，我們剛才聽到巨大的震動聲，你們沒事——",
  ui_story_1020_10201301_6_dialog_content = "噓……你們有聽到嗎？",
  ui_story_1020_10201301_7_dialog_content = "（日蝕語）1011X。",
  ui_story_1020_10201301_8_dialog_content = "（日蝕語）01X11。",
  ui_story_1020_10201301_9_dialog_content = "（日蝕語）X1010。",
  ui_story_1020_10201301_10_dialog_content = "教授他……怎麼了？",
  ui_story_1020_10201301_11_dialog_content = "……",
  ui_story_1020_10201301_12_dialog_content = "（日蝕語）0111X。",
  ui_story_1020_10201301_13_dialog_content = "（日蝕語）0X111。",
  ui_story_1020_10201301_14_dialog_content = "……日蝕語？",
  ui_story_1020_10201301_15_dialog_content = "……？？？",
  ui_story_1020_10201301_16_dialog_content = "從他口中說出來有點奇怪，但不會錯，這應該就是暗鬼之間溝通的語言。",
  ui_story_1020_10201301_17_dialog_content = "……剛才PlayerName在感應斐桀洛的時候，也是這樣自言自語……",
  ui_story_1020_10201301_18_dialog_content = "1011X。",
  ui_story_1020_10201301_19_dialog_content = "這樣……嗎？",
  ui_story_1020_10201301_20_dialog_content = "等等——你說什麼？說慢點。",
  ui_story_1020_10201301_21_dialog_content = "1……0……1……1……X……",
  ui_story_1020_10201301_22_dialog_content = "布布！布布！布布！",
  ui_story_1020_10201301_23_dialog_content = "PlayerName聽得懂日蝕語？！",
  ui_story_1020_10201301_24_dialog_content = "這樣說可能很奇怪……但並非能聽懂，是很容易把句子複述出來……",
  ui_story_1020_10201301_25_dialog_content = "怪不得……這和你感應布林時記錄的那些資訊有相似之處！",
  ui_story_1020_10201301_26_dialog_content = "日蝕語和原型機的語言之間有關聯……",
  ui_story_1020_10201301_27_dialog_content = "大多數暗鬼平常都處在不知所措的狀態，只會在攻擊時遵循統一的指令。",
  ui_story_1020_10201301_28_dialog_content = "指令……語言……一切似乎都連起來了啊！",
  ui_story_1020_10201301_29_dialog_content = "（日蝕語）2355X11874……",
  ui_story_1020_10201301_30_dialog_content = "（日蝕語）32456901X14361……",
  ui_story_1020_10201301_31_dialog_content = "（如果尤利西斯是在和「工程師」交流的話……）",
  ui_story_1020_10201301_32_dialog_content = "我或許能使用感應能力……",
  ui_story_1020_10201301_33_dialog_content = "PlayerName，你要做什麼？尤利西斯殺害了那麼多人！他該死！",
  ui_story_1020_10201301_34_dialog_content = "但這或許是唯一能找到臨空者號和薇絲下落的辦法……",
  ui_story_1020_10201301_35_dialog_content = "PlayerName！",
  ui_story_1020_10201301_36_dialog_content = "不要再使用感應能力了……你已經到極限了。",
  ui_story_1020_10201301_37_dialog_content = "這就是我的極限了嗎……",
  ui_story_1020_10201301_38_dialog_content = "但如果這是我唯一能做的事情……",
  ui_story_1020_10201301_39_option_content = "開始感應——",
  ui_story_1020_10201301_40_dialog_content = "戴上圓環，或是成為我的燃料。",
  ui_story_1020_10201301_41_dialog_content = "我不會向你屈服，我已經說過無數次了……",
  ui_story_1020_10201301_42_dialog_content = "我如今這副模樣，早已跨越對死亡的恐懼……",
  ui_story_1020_10201301_43_dialog_content = "從研究死人，到把活人變成死人……我早已經沒有了恐懼。",
  ui_story_1020_10201301_44_dialog_content = "你有超出常人的膽識，尤利。",
  ui_story_1020_10201301_45_dialog_content = "像曾經的我。",
  ui_story_1020_10201301_46_dialog_content = "呵呵……哈哈哈哈……只是像而已嗎？",
  ui_story_1020_10201301_47_dialog_content = "那時，連拉比都倒下了……偌大的實驗室裡，只有我還記得我們這群人走上研究道路的初衷……",
  ui_story_1020_10201301_48_dialog_content = "找出暗鬼強大的原因，找到光靈存活下去的方法。",
  ui_story_1020_10201301_49_dialog_content = "我查閱資料時，你的名字出現了……你讓我去翻開那些塵封的歷史書頁，去祕密研究「守護者」。",
  ui_story_1020_10201301_50_dialog_content = "也是從那時起，我看見機械化生產暗鬼的工廠，駕駛巨像轟炸艾斯特拉大陸的空裔……",
  ui_story_1020_10201301_51_dialog_content = "以及紛紛躲進地下城的光靈。",
  ui_story_1020_10201301_52_dialog_content = "艾歐里亞從一顆湛藍的星球變成火紅色，轉眼間又成為灰黑色的死星……",
  ui_story_1020_10201301_53_dialog_content = "極光滿佈天際，星球的軌道發生偏移……",
  ui_story_1020_10201301_54_dialog_content = "科技、戰爭、仇恨、生命……",
  ui_story_1020_10201301_55_dialog_content = "是你讓我看見世界的殘酷，還要我帶著恐懼，堅強地活下去。",
  ui_story_1020_10201301_56_dialog_content = "我是怎麼說的？",
  ui_story_1020_10201301_57_dialog_content = "「想要戰勝暗鬼，必須大膽一些！」",
  ui_story_1020_10201301_58_dialog_content = "「再大膽一些！」",
  ui_story_1020_10201301_59_dialog_content = "聽著這個聲音，我常常不知道自己是誰，是身處過去？還是未來？",
  ui_story_1020_10201301_60_dialog_content = "我甚至會想，為什麼是我？",
  ui_story_1020_10201301_61_dialog_content = "但是當我跨越這些恐懼之後，我明白了，我尤利西斯自此便無所畏懼。",
  ui_story_1020_10201301_62_dialog_content = "就算是面對這個殘酷的世界，就算是面對你。",
  ui_story_1020_10201301_63_dialog_content = "你跨越了恐懼，但你有了新的恐懼。",
  ui_story_1020_10201301_64_dialog_content = "什麼恐懼？",
  ui_story_1020_10201301_65_dialog_content = "要看看嗎？",
  ui_story_1020_10201301_66_dialog_content = "……",
  ui_story_1020_10201301_67_dialog_content = "德尼耶爾。",
  ui_story_1020_10201301_68_dialog_content = "老師。",
  ui_story_1020_10201301_69_dialog_content = "你在研討會上提出的暗能術猜想，非常具有研究價值。",
  ui_story_1020_10201301_70_dialog_content = "謝謝老師，但是目前，啟光沒有辦法支持我的研究。",
  ui_story_1020_10201301_71_dialog_content = "戰後會有一批研究物資回收，到時候你可以去迦南城外圍建立你自己的實驗室，做你想做的實驗。",
  ui_story_1020_10201301_72_dialog_content = "……謝謝，老師。",
  ui_story_1020_10201301_73_dialog_content = "進展如何了，德尼耶爾？",
  ui_story_1020_10201301_74_dialog_content = "這是我培育的種子，老師。",
  ui_story_1020_10201301_75_dialog_content = "不錯……非常漂亮……",
  ui_story_1020_10201301_76_dialog_content = "如果能為我們的士兵植入種子……",
  ui_story_1020_10201301_77_dialog_content = "老師！這只是研究，種子中的暗能會把光靈吞噬的。",
  ui_story_1020_10201301_78_dialog_content = "不過是吞噬光靈而已……你知道暗鬼是如何吞噬這個世界的嗎？",
  ui_story_1020_10201301_79_dialog_content = "……？",
  ui_story_1020_10201301_80_dialog_content = "你的研究非常出色，德尼耶爾。時機成熟了，光靈終於可以迎來蛻變。",
  ui_story_1020_10201301_81_dialog_content = "……您要做什麼？",
  ui_story_1020_10201301_82_dialog_content = "把種子交出來。",
  ui_story_1020_10201301_83_dialog_content = "……",
  ui_story_1020_10201301_84_dialog_content = "交出來。",
  ui_story_1020_10201301_85_dialog_content = "我拒絕。",
  ui_story_1020_10201301_86_dialog_content = "你想與啟光為敵嗎？",
  ui_story_1020_10201301_87_dialog_content = "不……老師。",
  ui_story_1020_10201301_88_dialog_content = "你不要忘了，沒有我，也就沒有你。",
  ui_story_1020_10201301_89_dialog_content = "……",
  ui_story_1020_10201301_90_dialog_content = "我想起來了，這是那個叫「吞羅」的啟光人，你一直想成為的人。",
  ui_story_1020_10201301_91_dialog_content = "不是……",
  ui_story_1020_10201301_92_dialog_content = "你的得意之作，極致之作，是叫「人造太陽計畫」嗎？",
  ui_story_1020_10201301_93_dialog_content = "我已經承認你的才華了，尤利。戴上這認可你的圓環。",
  ui_story_1020_10201301_94_dialog_content = "我不需要你的承認，我永遠不會服從！",
  ui_story_1020_10201301_95_dialog_content = "（傷害了那麼多人、做殘忍實驗的尤利西斯，和始終沒有向工程師屈服的尤利西斯……）",
  ui_story_1020_10201301_96_dialog_content = "（這是為什麼呢？）",
  ui_story_1020_10201301_97_dialog_content = "感到意外嗎？空裔？",
  ui_story_1020_10201301_98_dialog_content = "你果然能在我使用感應能力的時候……看到我……",
  ui_story_1020_10201301_99_dialog_content = "為什麼……？",
  ui_story_1020_10201301_100_dialog_content = "當巨像「看到」了我，我就「看到」了你。",
  ui_story_1020_10201301_101_dialog_content = "自我意識的「自我」只是一種想像性的指涉。看似智慧的東西，本身可以是另一個智慧的載體。",
  ui_story_1020_10201301_102_dialog_content = "因為後者有更高的智慧。",
  ui_story_1020_10201301_103_dialog_content = "遠古機器是我的載體，那個罪靈也是。他，也快了。",
  ui_story_1020_10201301_104_dialog_content = "……尤利西斯，不要戴上圓環！",
  ui_story_1020_10201301_105_dialog_content = "他聽不到你說話。",
  ui_story_1020_10201301_106_dialog_content = "……",
  ui_story_1020_10201301_107_dialog_content = "我一定會找到他們的……臨空者號，還有薇絲！",
  ui_story_1020_10201301_108_dialog_content = "好。",
  ui_story_1020_10201301_109_dialog_content = "之前有一片光將我們短暫區隔開，那裡或許也有我想要「看到」的東西。",
  ui_story_1020_10201301_110_dialog_content = "光亮的湖面……",
  ui_story_1020_10201301_111_dialog_content = "你聽到了嗎？我是不會戴上圓環的，也沒想過這麼簡單死去……",
  ui_story_1020_10201301_112_dialog_content = "你這幅模樣，掙扎毫無意義。",
  ui_story_1020_10201301_113_dialog_content = "我變成怎樣無所謂，但我會告訴他們，光靈應該如何活下去。",
  ui_story_1020_10201301_114_dialog_content = "這個世界上只有我理解你。但我尊重你。",
  ui_story_1020_10201301_115_dialog_content = "你要對他做什麼？",
  ui_story_1020_10201301_116_dialog_content = "成全他。",
  ui_story_1020_10201301_117_dialog_content = "啟光，任何年代都會誕生優秀的科學家。",
  ui_story_1020_10201301_118_dialog_content = "但沒有了原型機和他們，我們也會在其他地方相見的。你已經知道我的座標了。",
  ui_story_1020_10201301_119_dialog_content = "……",
  ui_story_1020_10201301_120_dialog_content = "記住，光明會欺騙你。光明試圖掩蓋的黑暗，才是這個世界最真實的底色。",
  ui_story_1020_10201301_121_dialog_content = "接受黑暗，融入黑暗，讓黑暗成為你的力量。",
  ui_story_1020_10201301_122_dialog_content = "呃啊——",
  ui_story_1020_10201301_123_dialog_content = "布布！布布！布布！",
  ui_story_1020_10201301_124_dialog_content = "腦子沒壞吧，PlayerName？",
  ui_story_1020_10201301_125_dialog_content = "我沒事！但尤利西斯……",
  ui_story_1020_10201301_126_dialog_content = "喝啊——！！！",
  ui_story_1020_10201301_127_dialog_content = "布布！布布！布布！",
  ui_story_1020_10201301_128_dialog_content = "教授，不要再往前了！否則……",
  ui_story_1020_10201301_129_dialog_content = "<color=#e8d9bb>咔嚓——</color>",
  ui_story_1020_10201301_130_dialog_content = "……",
  ui_story_1020_10201301_131_dialog_content = "開槍……？是我創造了你們……你們會理解我的，對嗎？",
  ui_story_1020_10201301_132_dialog_content = "他的狀態，和斐桀洛一樣！",
  ui_story_1020_10201301_133_dialog_content = "不一樣。",
  ui_story_1020_10201301_134_dialog_content = "他沒有向工程師屈服，所以工程師要毀了他……他現在正在抵抗。",
  ui_story_1020_10201301_135_dialog_content = "……",
  ui_story_1020_10201301_136_dialog_content = "大元帥？我們該如何處置他呢？",
  ui_story_1020_10201301_137_dialog_content = "……停下來吧，尤利西斯！你還不明白嗎？",
  ui_story_1020_10201301_138_dialog_content = "你自以為在拯救光靈，對抗日蝕，但你不知不覺中早已成為日蝕的一員了！",
  ui_story_1020_10201301_139_dialog_content = "告訴他們……空裔……",
  ui_story_1020_10201301_140_dialog_content = "10011000……光靈要如何才能活下去……00！",
  ui_story_1020_10201301_141_dialog_content = "唯有拼命……12933……做到極致……11012……才……103001111……",
  ui_story_1020_10201301_142_dialog_content = "有可能……",
  ui_story_1020_10201301_143_dialog_content = "01100……",
  ui_story_1020_10201301_144_dialog_content = "不是的……",
  ui_story_1020_10201301_145_dialog_content = "你特殊……你要以你的方式……去面對命運……",
  ui_story_1020_10201301_146_dialog_content = "但……10011001X0……但是……",
  ui_story_1020_10201301_147_dialog_content = "呃……啊啊啊——",
  ui_story_1020_10201301_148_dialog_content = "1001X1000……我改變的世界……",
  ui_story_1020_10201301_149_dialog_content = "一定會……10102099……成為你們的未來……1X120……",
  ui_story_1020_10201301_150_dialog_content = "布林！",
  ui_story_1020_10201301_151_dialog_content = "把線路接到尤利西斯身上的管子，我們找出接孔！切斷他和工程師的連線！",
  ui_story_1020_10201301_152_dialog_content = "喝——！",
  ui_story_1020_10201301_153_dialog_content = "來不及了……",
  ui_story_1020_10201301_154_dialog_content = "……",
  ui_story_1020_10201301_155_dialog_content = "不管尤利西斯曾為啟光做過什麼，如今的他已經不是光靈，更不是啟光人了。",
  ui_story_1020_10201301_156_dialog_content = "他屢次讓迦南城陷入險境，傷害同胞生命。",
  ui_story_1020_10201301_157_dialog_content = "我以啟光大元帥的名義，判處尤利西斯死刑。",
  ui_story_1020_10201301_158_dialog_content = "喝啊——！！！",
  ui_story_1020_10201301_159_dialog_content = "殺了他！",
  ui_story_1020_10201402_1_dialog_content = "我死了……你們就能得救嗎……",
  ui_story_1020_10201402_2_dialog_content = "拉比，我真是不甘心啊……",
  ui_story_1020_10201402_3_dialog_content = "<color=#e8d9bb>暗潮危機·啟光戰時療養院</color>",
  ui_story_1020_10201402_4_dialog_content = "喔……好久不見啊，尤利。",
  ui_story_1020_10201402_5_dialog_content = "沒想到會在這裡遇見你……拉比……",
  ui_story_1020_10201402_6_dialog_content = "你，過得還——",
  ui_story_1020_10201402_7_dialog_content = "今天你又想到什麼新問題嗎？",
  ui_story_1020_10201402_8_dialog_content = "……",
  ui_story_1020_10201402_9_dialog_content = "我的實驗再次失敗了，尤利。<color=#FFB400>七十七號地下城</color>只送回來幾具燒焦的實驗體……",
  ui_story_1020_10201402_10_dialog_content = "今天的廣播放了以前我們常在實驗室聽的音樂……喔，你剛剛說什麼？",
  ui_story_1020_10201402_11_dialog_content = "……",
  ui_story_1020_10201402_12_dialog_content = "我說……那枚胸針，你還一直戴著。",
  ui_story_1020_10201402_13_dialog_content = "是啊……昨天我找了一宿，原來是被薩莎藏起來了，真是個淘氣的孩子。",
  ui_story_1020_10201402_14_dialog_content = "……",
  ui_story_1020_10201402_15_dialog_content = "薩沙最近學會寫詩了，我唸給你聽，尤利。你聽聽看她寫的詩怎麼樣……",
  ui_story_1020_10201402_16_dialog_content = "拉比……",
  ui_story_1020_10201402_17_dialog_content = "你已經忘記了我們一起鑽研實驗，調查工程師線索的日子。",
  ui_story_1020_10201402_18_dialog_content = "你只記得那些早已逝去的親人……",
  ui_story_1020_10201402_19_dialog_content = "其實，我還挺替你感到高興，呵呵……",
  ui_story_1020_10201402_20_dialog_content = "如果我從來沒見過工程師的名字，也沒見過那些畫面……",
  ui_story_1020_10201402_21_dialog_content = "如果我們還能像從前那樣，在實驗室裡談論理想……",
  ui_story_1020_10201402_22_dialog_content = "每天見面第一句話便是……",
  ui_story_1020_10201402_23_dialog_content = "尤利，今天你又想到什麼新問題？",
  ui_story_1020_10201402_24_dialog_content = "……",
  ui_story_1020_10201402_25_dialog_content = "尤利。",
  ui_story_1020_10201402_26_dialog_content = "嗯？",
  ui_story_1020_10201402_27_dialog_content = "你曾經歷過信仰崩塌的時刻嗎？",
  ui_story_1020_10201402_28_dialog_content = "……",
  ui_story_1020_10201402_29_dialog_content = "沒有。",
  ui_story_1020_10201402_30_dialog_content = "你認為……",
  ui_story_1020_10201402_31_dialog_content = "信仰崩塌和無力實現理想，哪一個比較可悲呢？",
  ui_story_1020_10201402_32_dialog_content = "……",
  ui_story_1020_10201402_33_dialog_content = "信仰崩塌和無力實現理想……",
  ui_story_1020_10201402_34_dialog_content = "到底哪一個比較可悲呢？",
  ui_story_1020_10201402_35_dialog_content = "……",
  ui_story_1020_10201501_1_dialog_content = "……好像畫布啊！",
  ui_story_1020_10201501_2_dialog_content = "真的呢……而且是明詩的畫布。亂畫一通後，再把洗顏料的水潑上去！",
  ui_story_1020_10201501_3_dialog_content = "……反而有一種獨特的美感。",
  ui_story_1020_10201501_4_dialog_content = "你們什麼意思啊？！",
  ui_story_1020_10201501_5_dialog_content = "維多利亞大人把我們帶到這裡來 ，可不是讓你們取笑我的！",
  ui_story_1020_10201501_6_dialog_content = "噢！差點忘了，感謝維多利亞大人！",
  ui_story_1020_10201501_7_dialog_content = "感謝維多利亞大人！",
  ui_story_1020_10201501_8_dialog_content = "感謝維多利亞大人！",
  ui_story_1020_10201501_9_dialog_content = "這並非吾之功勞，而是真理之主的庇護。",
  ui_story_1020_10201501_10_dialog_content = "這裡是什麼地方啊？",
  ui_story_1020_10201501_11_dialog_content = "……",
  ui_story_1020_10201501_12_dialog_content = "<color=#FFB400>原始河流</color>不歸時間掌管，不受空間約束，它和外界唯一的區別便是流動。",
  ui_story_1020_10201501_13_dialog_content = "再這麼下去，我們的生命也都不由自己掌管了是嗎？",
  ui_story_1020_10201501_14_dialog_content = "為什麼把我們帶到這裡？",
  ui_story_1020_10201501_15_dialog_content = "為了找到對應我們時空的標記點，讓真理之主，隨我們降臨。",
  ui_story_1020_10201501_16_dialog_content = "裝神弄鬼……",
  ui_story_1020_10201501_17_dialog_content = "維多利亞小姐，我們的暗面偵察任務還沒有結束，從這裡傳回去的座標，啟光真的收得到嗎？",
  ui_story_1020_10201501_18_dialog_content = "真理之主告知，凡有心，便有知。全依您的方式而定。",
  ui_story_1020_10201501_19_dialog_content = "<color=#e8d9bb>撲通——</color>",
  ui_story_1020_10201501_20_dialog_content = "嗯？薇絲，是妳掉的東西嗎？",
  ui_story_1020_10201501_21_dialog_content = "啊……是我的啟光徽章！",
  ui_story_1020_10201501_22_dialog_content = "怎麼辦、怎麼辦……完全撈不起來啊……",
  ui_story_1020_10201501_23_dialog_content = "欸？一枚小小的徽章，怎麼感覺整個河面瞬間亮了起來？",
  ui_story_1020_10201501_24_dialog_content = "荒原靜止，但河流之下已是另一番景象。",
  ui_story_1020_10201501_25_dialog_content = "湖面……嘶，涼颼颼的，總覺得好不真實啊。",
  ui_story_1020_10201501_26_dialog_content = "湖面……",
  ui_story_1020_10201501_27_dialog_content = "PlayerName，你醒了。",
  ui_story_1020_10201501_28_dialog_content = "這裡是……",
  ui_story_1020_10201501_29_dialog_content = "卡蓮？妳們……我怎麼在這啊？",
  ui_story_1020_10201501_30_dialog_content = "什麼都不記得了嗎？",
  ui_story_1020_10201501_31_dialog_content = "我好像夢到一個透亮的湖面……仔細一想卻想不起來了……",
  ui_story_1020_10201501_32_dialog_content = "喔，對了！啟光沒事吧？！",
  ui_story_1020_10201501_33_dialog_content = "嗯，聲音渾厚有力，看來沒問題了。",
  ui_story_1020_10201501_34_dialog_content = "睡了三天果然恢復得不錯，年輕真好啊。",
  ui_story_1020_10201501_35_dialog_content = "我睡了三天？！",
  ui_story_1020_10201501_36_dialog_content = "嗯，卡蓮衛隊長已經來過三趟了。",
  ui_story_1020_10201501_37_dialog_content = "我只是覺得頻繁聯絡，會打擾到薇薇安參謀長……",
  ui_story_1020_10201501_38_dialog_content = "這本來就是啟光發起的<color=#FFB400>聯合會議</color>，遲遲沒有和你商定時間，還請見諒。",
  ui_story_1020_10201501_39_dialog_content = "既然PlayerName醒了，衛隊長也在，就今天如何？",
  ui_story_1020_10201501_40_dialog_content = "嗯，我沒問題。",
  ui_story_1020_10201501_41_dialog_content = "聯合會議……發生什麼事了嗎？尤利西斯呢……他怎麼樣了？",
  ui_story_1020_10201501_42_dialog_content = "他死了，工程師的事情也暫時告一段落了。",
  ui_story_1020_10201501_43_dialog_content = "後來回顧整件事情，我大概能猜到你在他的意識裡看到些什麼，PlayerName。",
  ui_story_1020_10201501_44_dialog_content = "這次接收了他的實驗室，大量的工作日記中記錄了很多關鍵資料。",
  ui_story_1020_10201501_45_dialog_content = "讓我意想不到的是，被工程師注視那麼久，他竟能堅持到現在。",
  ui_story_1020_10201501_46_dialog_content = "但就像大元帥說的，當尤利西斯在凝視暗面的時候，暗面也在將他侵蝕……",
  ui_story_1020_10201501_47_dialog_content = "不知不覺中，他就變成日蝕的一員了。",
  ui_story_1020_10201501_48_dialog_content = "嗯，這次迦南城的危機，似乎將六百多年前我們都未曾見過的事情重現了一遍。",
  ui_story_1020_10201501_49_dialog_content = "但同樣是在大家的努力下，保住了迦南城。這一次，你和阿爾戈爾博士功不可沒。",
  ui_story_1020_10201501_50_dialog_content = "阿爾戈爾呢？",
  ui_story_1020_10201501_51_dialog_content = "阿爾戈爾博士啊，還以為她會像你一樣昏睡好幾天呢。",
  ui_story_1020_10201501_52_dialog_content = "沒想到危機結束之後，她就像什麼都沒發生一樣繼續做起了研究。",
  ui_story_1020_10201501_53_dialog_content = "今天應該是出門去了，好像是說要為一號尋找修復元件……",
  ui_story_1020_10201501_54_dialog_content = "已經打算修復一號了嗎……阿爾戈爾會出門真稀奇啊。",
  ui_story_1020_10201501_55_dialog_content = "可能是因為可以乘坐啟光新載具的緣故吧。",
  ui_story_1020_10201501_56_dialog_content = "啟光新載具？那是什麼？",
  ui_story_1020_10201501_57_dialog_content = "尤利西斯研究巨像多年，工程隊根據他的研究資料做了一些相似的小型載具。",
  ui_story_1020_10201501_58_dialog_content = "此次危機中，這些小型載具幫助我們轉移了部分居民。而這些載具也會投入本次的聯合探索。",
  ui_story_1020_10201501_59_dialog_content = "……",
  ui_story_1020_10201501_60_option_content = "尤利西斯……",
  ui_story_1020_10201501_61_option_content = "小型載具……",
  ui_story_1020_10201501_62_dialog_content = "他的研究成果真的要繼續嗎？",
  ui_story_1020_10201501_63_dialog_content = "我知道你在擔心什麼。",
  ui_story_1020_10201501_64_dialog_content = "不只是小型載具，包括對西恩這樣具有暗面探索天賦的注重……",
  ui_story_1020_10201501_65_dialog_content = "恰恰都是基於尤利西斯的研究，這是事實。",
  ui_story_1020_10201501_66_dialog_content = "我相信做出這個決策的難度，不亞於當年暗潮危機時開放「守護者」系統的研究許可。",
  ui_story_1020_10201501_67_dialog_content = "這一次，儘管已經讓科學家首席議會和科研室全體負責人對他的研究成果做了評估和表決……",
  ui_story_1020_10201501_68_dialog_content = "結果仍然是贊成者與反對者各說各話。",
  ui_story_1020_10201501_69_dialog_content = "但就我的角度而言，保證啟光同胞的生存是最重要的。",
  ui_story_1020_10201501_70_dialog_content = "所以妳是站反對的一方嗎？",
  ui_story_1020_10201501_71_dialog_content = "恰恰相反。",
  ui_story_1020_10201501_72_dialog_content = "保證生存的一個條件是不斷縮小風險。我們必須知曉風險，並化風險為利劍。",
  ui_story_1020_10201501_73_dialog_content = "我們必須繼續研究敵人，繼續試探我們的極限，不斷為改善光靈的生存環境向前探索。",
  ui_story_1020_10201501_74_dialog_content = "所以就有了聯合探索嗎……這麼說，白夜城也陷入危險了嗎？",
  ui_story_1020_10201501_75_dialog_content = "白夜城沒有陷入危險，不過有許多聖物產生了光能紊亂現象，引起城主的重視。",
  ui_story_1020_10201501_76_dialog_content = "經過迦南城的危機，委員會終於願意試著和大陸各陣營一起探討聯合探索的可能性。",
  ui_story_1020_10201501_77_dialog_content = "卡蓮將擔任白夜城的聯合探索隊長。之後還陸續會有北境和影鎮的特使過來參會。",
  ui_story_1020_10201501_78_dialog_content = "喔，大元帥！紅油沙漠的那幫好事之徒，不知道從哪裡聽到風聲，想加入的呼聲已經傳到我這裡來了。",
  ui_story_1020_10201501_79_dialog_content = "PlayerName，我想聽聽你個人的想法。",
  ui_story_1020_10201501_80_dialog_content = "我的想法……",
  ui_story_1020_10201501_81_dialog_content = "之前，我似乎從來沒有主動做過什麼，只是被動地跟著空裔留下的痕跡探索。",
  ui_story_1020_10201501_82_dialog_content = "修復臨空者號的過程中，我發現這些痕跡不全是好的……",
  ui_story_1020_10201501_83_dialog_content = "甚至我自己是不是好的，我都不確定……",
  ui_story_1020_10201501_84_dialog_content = "但經歷了薇絲和臨空者號的事後，那種總在意外中收穫驚喜的感覺已經完全消失了。",
  ui_story_1020_10201501_85_dialog_content = "因為我失去了，所以我必須去找回來……這種感覺很迫切。",
  ui_story_1020_10201501_86_dialog_content = "對了……我最近總覺得自己似乎看到了過去，又或許是未來……",
  ui_story_1020_10201501_87_dialog_content = "但總覺得，那都是我必須去探索的地方。",
  ui_story_1020_10201501_88_dialog_content = "可能是暗面，也可能是比暗面還要遠、還要難以企及的地方。",
  ui_story_1020_10201501_89_dialog_content = "我怎麼聽出了一種「宿命感」？",
  ui_story_1020_10201501_90_dialog_content = "是嗎……不過我一個東方的朋友替我看過卦，說我的命數「不在名錄上」……",
  ui_story_1020_10201501_91_dialog_content = "空裔能掙脫先天枷鎖，所以我不相信宿命。",
  ui_story_1020_10201501_92_dialog_content = "有自己的主張，並且充滿勇氣和智慧，你失去的東西一定能找回來。",
  ui_story_1020_10201501_93_dialog_content = "好！",
  ui_story_1020_10201501_94_dialog_content = "你能這樣想，那就太好了。",
  ui_story_1020_10201501_95_dialog_content = "當然，身為啟光大元帥，我有義務去找回我啟光的優秀軍人，卡戎、薇絲和他們的隊員。",
  ui_story_1020_10201501_96_dialog_content = "如果你願意，啟光會協助你向暗面探索，去找回臨空者號。",
  ui_story_1020_10201501_97_dialog_content = "嗯，此次白夜城加入聯合探索隊伍，也是因為你。",
  ui_story_1020_10201501_98_dialog_content = "謝謝你們……",
  ui_story_1020_10201501_99_dialog_content = "是我一直得到大家的信任和幫助，這次聯合探索我一定會加入！",
  ui_story_1020_10201501_100_dialog_content = "不過，我們的探索會從哪裡開始呢？",
  ui_story_1020_10201501_101_dialog_content = "其實能開始的地方還真不少。",
  ui_story_1020_10201501_102_dialog_content = "那是什麼？",
  ui_story_1020_10201501_103_dialog_content = "「赫利俄斯回憶錄」。",
  ui_story_1020_10201501_104_dialog_content = "好厚的一本啊……這麼快就完成了嗎？小錢德菈還真是神速啊。",
  ui_story_1020_10201501_105_dialog_content = "畢竟在那個長日，每個人都被一個不速之客提著一根筋，拼命地工作。",
  ui_story_1020_10201501_106_dialog_content = "看到你沒事，我們終於可以好好睡一覺了。",
  ui_story_1020_10201501_107_dialog_content = "對了，PlayerName，你剛才說夢到什麼透亮的湖面？",
  ui_story_1020_10201501_108_dialog_content = "是的……透亮的湖面……",
  ui_story_1020_10201501_109_dialog_content = "還有一枚十分眼熟的徽章……",
  ui_story_1020_10201501_110_dialog_content = "你們有過這樣的體驗嗎……",
  ui_story_1020_10201501_111_dialog_content = "在自己就快被黑暗吞噬的時候，忽然有琴聲劃破黑暗，讓光透進來……",
  ui_story_1020_10201501_112_dialog_content = "<color=#e8d9bb>撲通——</color>",
  ui_story_1020_10201501_113_dialog_content = "大家！有聽到哪裡傳來的琴聲嗎？",
  ui_story_1020_10201501_114_dialog_content = "我聽到了！",
  ui_story_1020_10201501_115_dialog_content = "嗯？",
  ui_story_1020_10201501_116_dialog_content = "嗯……在梅里大叫之後就沒了……",
  ui_story_1020_10201501_117_dialog_content = "感謝真理之主！",
  ui_story_1020_10201501_118_dialog_content = "薇絲小姐，您已經找到那個標記點了，請用您的方式指引我們。",
  ui_story_1020_10201501_119_dialog_content = "我？",
  ui_story_1020_10201501_120_dialog_content = "當您和空裔一起啟動那艘巨像時，這沉睡的原始河流便被喚醒。",
  ui_story_1020_10201501_121_dialog_content = "從那時起，艾歐里亞的歷史被您翻開了新的一頁。",
  ui_story_1020_10201501_122_dialog_content = "請再次用您的方式，指引我們。",
  ui_story_1020_10201501_123_dialog_content = "請再次用您的方式，指引我們。",
  ui_story_1020_10201501_124_dialog_content = "……？",
  ui_story_1020_10201501_125_dialog_content = "……",
  ui_story_1020_10201501_126_dialog_content = "剛才的琴聲，難道是……",
  ui_story_1020_10201501_127_dialog_content = "這個與「鋼琴」一模一樣的東西，就是巨像的控制台吧？",
  ui_story_1020_10201501_128_dialog_content = "讓我和你一起啟動巨像吧，導航員。",
  ui_story_1020_10201501_129_dialog_content = "一起……？薇絲，妳是光靈，沒有感應能力……",
  ui_story_1020_10201501_130_dialog_content = "但我可以成為你的力量。我……可以幫上忙。",
  ui_story_1020_10201501_131_dialog_content = "……？",
  ui_story_1020_10201501_132_dialog_content = "相信我吧，PlayerName。我和你其實……是有點相似之處的。",
  ui_story_1020_10201501_133_dialog_content = "不過那就說來話長了。等以後有機會，我再好好跟你說吧！",
  ui_story_1020_10201501_134_dialog_content = "我教妳如何「彈奏」它。",
  ui_story_1020_10201501_135_dialog_content = "維多利亞小姐的話，讓我想起一些事情……",
  ui_story_1020_10201501_136_dialog_content = "……",
  ui_story_1020_10201501_137_dialog_content = "很簡單，就像演奏一首鋼琴曲。",
  ui_story_1020_10201501_138_dialog_content = "……",
  ui_story_1020_10201501_139_dialog_content = "我看不見曲譜。可以指出我該按下的琴鍵嗎？",
  ui_story_1020_10201501_140_dialog_content = "……",
  ui_story_1020_10201501_141_dialog_content = "我感受到……能量在流動。",
  ui_story_1020_10201501_142_dialog_content = "就像對話一般——雖然我無法理解巨像的語言。",
  ui_story_1020_10201501_143_dialog_content = "他的語言就是琴鍵的語言。",
  ui_story_1020_10201501_144_dialog_content = "讓我們完成啟動它的指令吧，薇絲。",
  ui_story_1020_10201501_145_dialog_content = "……",
  ui_story_1020_10201501_146_dialog_content = "如果這就是指引大家的方式，我知道該怎麼做了。",
  ui_story_1020_10201501_147_dialog_content = "你們聽！你們聽！是鋼琴曲！",
  ui_story_1020_10201501_148_dialog_content = "這閃爍著神祕光芒的河流，乃是主的眷顧所在。",
  ui_story_1020_10201501_149_dialog_content = "祂傾聽那神祕旋律，啟示無盡真理。",
  ui_story_1020_10201501_150_dialog_content = "願真理之主見證我們的探索，與我們同行、降臨。",
  ui_story_1021_10210100_1_dialog_content = "<color=#e8d9bb>許多年前，北境邊緣……</color>",
  ui_story_1021_10210100_2_dialog_content = "女王陛下，越過前面的小山丘，您就走出北境的界域了。",
  ui_story_1021_10210100_3_dialog_content = "……",
  ui_story_1021_10210100_4_dialog_content = "雪原廣袤，前方仍然生活著北境的子民。",
  ui_story_1021_10210100_5_dialog_content = "諾維亞老師，你先回去吧。這是我想要做的事情。",
  ui_story_1021_10210100_6_dialog_content = "歷任先王，以及這無垠的冰雪，會銘記您對北境所做的一切。",
  ui_story_1021_10210100_7_dialog_content = "守護北境的力量並非源於我，而是源於北境自身的力量。",
  ui_story_1021_10210100_8_dialog_content = "取之有愧，必當竭力相報。",
  ui_story_1021_10210100_9_dialog_content = "暮冬而生。我們，為守護北境而生。",
  ui_story_1021_10210100_10_dialog_content = "<color=#e8d9bb>窸窸窣窣——</color>",
  ui_story_1021_10210100_11_dialog_content = "嗯？雪停了……",
  ui_story_1021_10210100_12_dialog_content = "印象中，這片雪松林還沒出現過這麼好的天氣。",
  ui_story_1021_10210100_13_dialog_content = "……哈！",
  ui_story_1021_10210100_14_dialog_content = "嗯？",
  ui_story_1021_10210100_15_dialog_content = "陌生人！我警告妳，快點離開這裡，否則讓妳嚐嚐首領提亞拉的厲害！",
  ui_story_1021_10210100_16_dialog_content = "……妳叫提亞拉？",
  ui_story_1021_10210100_17_dialog_content = "妳……！妳怎麼知道我的名字……",
  ui_story_1021_10210100_18_dialog_content = "咳……就算妳偷偷打聽過本首領的名字，本首領也不會讓妳踏進雪狐部落半步！",
  ui_story_1021_10210100_19_dialog_content = "是雪狐部落的孩子啊。妳的父母呢？",
  ui_story_1021_10210100_20_dialog_content = "父親大人和母親大人都在忙著護衛北境！別想岔開話題！快說，妳來這裡做什麼？！",
  ui_story_1021_10210100_21_dialog_content = "提亞拉！看看太奶奶帶了什麼來給妳。",
  ui_story_1021_10210100_22_dialog_content = "哇！是提亞拉最喜歡的香香松枝耶！",
  ui_story_1021_10210100_23_dialog_content = "現在告訴太奶奶，妳不到祭壇去，為什麼跑到這邊來調皮？",
  ui_story_1021_10210100_24_dialog_content = "唔……長老說那裡不是小孩子能去的地方……",
  ui_story_1021_10210100_25_dialog_content = "那隻老狐狸，看來是越老越糊塗了。",
  ui_story_1021_10210100_26_dialog_content = "太奶奶，提亞拉今天做了一件了不起的事情！看，我嚇得這個陌生人不敢靠近部落！",
  ui_story_1021_10210100_27_dialog_content = "……",
  ui_story_1021_10210100_28_dialog_content = "提亞拉真了不起！",
  ui_story_1021_10210100_29_dialog_content = "現在，太奶奶要考考妳。妳還記得「三棵松樹」的傳說嗎？",
  ui_story_1021_10210100_30_dialog_content = "記得！",
  ui_story_1021_10210100_31_dialog_content = "提亞拉很聰明，別再和她提那些傳說了。",
  ui_story_1021_10210100_32_dialog_content = "如果我不講給她聽，就不會有人記得了。不久後，她就會開始學習、傳承他人的故事。",
  ui_story_1021_10210100_33_dialog_content = "……",
  ui_story_1021_10210100_34_dialog_content = "伯利恆見過兩位。",
  ui_story_1021_10210100_35_dialog_content = "感謝先民對北境的庇護，我先告辭了。",
  ui_story_1021_10210100_36_dialog_content = "……",
  ui_story_1021_10210100_37_dialog_content = "<color=#e8d9bb>窸窸窣窣——</color>",
  ui_story_1021_10210100_38_dialog_content = "妳說過，燈塔會照到這裡。",
  ui_story_1021_10210100_39_dialog_content = "……",
  ui_story_1021_10210100_40_dialog_content = "雪狐部落已經許多年沒有聽到新生兒的啼哭了。",
  ui_story_1021_10210100_41_dialog_content = "感謝雪狐部落為北境誕下的每一名護衛。",
  ui_story_1021_10210100_42_dialog_content = "這些孩子生下來不是在巍峨的王宮中，而是在這隨時可能遭暗鬼侵襲的雪林裡。",
  ui_story_1021_10210100_43_dialog_content = "他們的祖輩，一代又一代，為保衛北境葬身在此。",
  ui_story_1021_10210100_44_dialog_content = "我可以把她帶到冬宮去。",
  ui_story_1021_10210100_45_dialog_content = "如果暗鬼毀滅了北境，妳會離開這裡，到別的地方去嗎？",
  ui_story_1021_10210100_46_dialog_content = "不會。",
  ui_story_1021_10210100_47_dialog_content = "北境養育我們，庇佑我們，我們應當世世代代守護這裡。",
  ui_story_1021_10210100_48_dialog_content = "我怎麼會……想起那一天的事……",
  ui_story_1021_10210100_49_dialog_content = "女王陛下，邊境的天氣異常，燈塔的光芒也發生了微弱的變化。",
  ui_story_1021_10210100_50_dialog_content = "這一切，果然不是偶然……我已經有所預感。",
  ui_story_1021_10210100_51_dialog_content = "正如您所預見，此前啟光的危機並非孤立，據點的建設不是那麼順利……",
  ui_story_1021_10210100_52_dialog_content = "我們要密切關注暗面的動向了。",
  ui_story_1021_10210100_53_dialog_content = "聯合探索至關重要，這關乎光靈族的未來。而且，距離聯合會議召開沒有幾天了。",
  ui_story_1021_10210100_54_dialog_content = "我去看看吧。",
  ui_story_1021_10210100_55_dialog_content = "現在嗎？",
  ui_story_1021_10210100_56_dialog_content = "嗯。你見到提亞拉了嗎？",
  ui_story_1021_10210100_57_dialog_content = "提亞拉她……",
  ui_story_1021_10210100_58_dialog_content = "女王陛下，您……要出去嗎？請讓我陪您一起吧。",
  ui_story_1021_10210100_59_dialog_content = "……",
  ui_story_1021_10210100_60_dialog_content = "我要獨自出遠門幾天，冬宮的事情就交給諾維亞了。我不在的時候，希望妳多多磨練自己。",
  ui_story_1021_10210100_61_dialog_content = "是，女王陛下！",
  ui_story_1021_10210100_62_dialog_content = "（陛下為何行色匆匆……）",
  ui_story_1021_10210100_63_dialog_content = "那些窗台上的腳印，該擦一擦了。",
  ui_story_1021_10210100_64_dialog_content = "……是！",
  ui_story_1021_10210100_65_dialog_content = "<color=#e8d9bb>嗷——</color>",
  ui_story_1021_10210100_66_dialog_content = "……",
  ui_story_1021_10210100_67_dialog_content = "果然聽不到一點回應呢……",
  ui_story_1021_10210100_68_dialog_content = "女王陛下已經出宮好幾天了……",
  ui_story_1021_10210100_69_dialog_content = "身為陛下的護衛，卻不能時刻陪在女王身邊，我該如何「多多磨練自己」呢……",
  ui_story_1021_10210100_70_dialog_content = "<color=#e8d9bb>嗷——</color>",
  ui_story_1021_10210100_71_dialog_content = "是你們……",
  ui_story_1021_10210100_72_dialog_content = "嗚嗚……",
  ui_story_1021_10210100_73_dialog_content = "什麼……？",
  ui_story_1021_10210100_74_dialog_content = "嗚嗚——！",
  ui_story_1021_10210100_75_dialog_content = "怎麼會這樣……？！",
  ui_story_1021_10210100_76_dialog_content = "女王出宮之前我剛回去過一趟，那時，長老還在和我分享豐收的喜悅……",
  ui_story_1021_10210100_77_dialog_content = "但我身為女王陛下的護衛，不能就這樣……",
  ui_story_1021_10210100_78_dialog_content = "嗷嗚嗚——！",
  ui_story_1021_10210100_79_dialog_content = "……知道了！我馬上跟你們回去！",
  ui_story_1021_10210100_80_dialog_content = "雪狐，是雪狐耶！",
  ui_story_1021_10210100_81_dialog_content = "你又打斷安頓先生講課！哪裡有什麼雪狐嘛？！",
  ui_story_1021_10210100_82_dialog_content = "看，那不就是一隻跳來跳去的兔子嗎！",
  ui_story_1021_10210100_83_dialog_content = "但我剛剛真的看到了嘛……牠和識字書上畫的雪狐一模一樣！",
  ui_story_1021_10210100_84_dialog_content = "雖然雪狐出現在鎮上確實很奇怪……安頓先生，您說呢？您相信我嗎？",
  ui_story_1021_10210100_85_dialog_content = "傳說在北境還不叫「北境」的時候，雪狐就和一些光靈是好朋友。牠們一起守護著這片土地。",
  ui_story_1021_10210100_86_dialog_content = "那北境現在還有雪狐嗎？",
  ui_story_1021_10210100_87_dialog_content = "我相信有。雪狐是有靈性的動物，傳說中有些雪狐活了好幾百年，甚至上千年……",
  ui_story_1021_10210100_88_dialog_content = "千年……那得有多久啊？",
  ui_story_1021_10210100_89_dialog_content = "那可比北境最古老的雪松還要長久呢。還記得我跟你們講過「三棵松樹」的故事嗎？",
  ui_story_1021_10210100_90_dialog_content = "記得！",
  ui_story_1021_10210100_91_dialog_content = "在北境還沒成為北境之前，有三棵偉大的雪松，他們都夢想著保護北境……",
  ui_story_1021_10210100_92_dialog_content = "但是其他生靈都笑他們，說區區雪松怎麼可能守護得了整個北境呢？",
  ui_story_1021_10210100_93_dialog_content = "後來在戰爭期間，伐木人把這三棵雪松砍倒了。",
  ui_story_1021_10210100_94_dialog_content = "一棵被搭建成了畜棚……",
  ui_story_1021_10210100_95_dialog_content = "一棵被做成木桌子，賣給一個窮苦人家……",
  ui_story_1021_10210100_96_dialog_content = "而第三棵，因為沒人要，就被收進倉庫，再也沒見過陽光。",
  ui_story_1021_10210100_97_dialog_content = "很多年後，一位懷孕的女子路過那個畜棚，在那裡生下了一個孩子……",
  ui_story_1021_10210100_98_dialog_content = "那棵雪松承接的新生兒，就是我們偉大的第一位北境女王！",
  ui_story_1021_10210100_99_dialog_content = "又過了很多年，北境女王幫助了那個窮苦的家庭。",
  ui_story_1021_10210100_100_dialog_content = "就在那張破舊的木桌前，貧窮的四兄弟向女王發誓，要世世代代守護王室……",
  ui_story_1021_10210100_101_dialog_content = "那四兄弟的後裔，就成了我們北境的王室護衛！",
  ui_story_1021_10210100_102_dialog_content = "啊……對不起，安頓先生，我忘記第三棵雪松的故事了……",
  ui_story_1021_10210100_103_dialog_content = "後來，女王在倉庫裡找到那棵雪松，用它製成一把權杖……",
  ui_story_1021_10210100_104_dialog_content = "那把權杖，能夠號令所有的北境生靈一起保衛北境。",
  ui_story_1021_10210100_105_dialog_content = "雪松，是我們北境的守護神。有了他們，這個家園才能夠世代平安、幸福……",
  ui_story_1021_10210100_106_dialog_content = "……",
  ui_story_1021_10210100_107_dialog_content = "怎麼會這樣……！",
  ui_story_1021_10210100_108_dialog_content = "狐兒們……長老……這裡究竟發生了什麼事？！",
  ui_story_1021_10210100_109_dialog_content = "……",
  ui_story_1021_10210100_110_dialog_content = "<color=#e8d9bb>嚶嚶嚶——！</color>",
  ui_story_1021_10210201_1_dialog_content = "<color=#e8d9bb>艾斯特拉聯合探索委員會·臨時指揮部</color>",
  ui_story_1021_10210201_2_dialog_content = "好一段時間沒見了啊，PlayerName！",
  ui_story_1021_10210201_3_dialog_content = "好久不見，溫蒂。妳還是那麼準時！",
  ui_story_1021_10210201_4_dialog_content = "纏、纏住了……這圍巾真是麻煩……",
  ui_story_1021_10210201_5_dialog_content = "喲呼，匹皮也很準時嘛！妳那個有趣的後輩塔塔呢？",
  ui_story_1021_10210201_6_dialog_content = "嗯……坦白說我不太看好這個後輩，她離成為合格的信使還有一段距離的說。",
  ui_story_1021_10210201_7_dialog_content = "每次催她，她都叫著「馬桑馬桑，偶馬桑就到啦」！但其實又不知道去哪撿那些掉落的信件了！",
  ui_story_1021_10210201_8_dialog_content = "唉！但是身為前輩，我也不是不能原諒她的毛躁、馬虎和偶爾缺乏責任心犯的錯……",
  ui_story_1021_10210201_9_dialog_content = "她似乎繼承了妳的一些特質……等等，感覺妳是在形容自己……",
  ui_story_1021_10210201_10_dialog_content = "再怎麼說我也是前輩，當然會好好照顧她啦！",
  ui_story_1021_10210201_11_dialog_content = "那誰照顧我啊？才剛收假，薇薇安大人就派我去什麼黃昏鎮確認聯合探索據點。",
  ui_story_1021_10210201_12_dialog_content = "黃昏鎮是什麼地方啊！稍微想休息一下，那裡的風沙混著瀰漫的暗能，整個都烏漆墨黑的……",
  ui_story_1021_10210201_13_dialog_content = "搞得我整天都昏昏沉沉的，一點工作的力氣也沒有……",
  ui_story_1021_10210201_14_dialog_content = "唉！這工作一分鐘都做不下去了啦……下個月我一定要重新找份工作。",
  ui_story_1021_10210201_15_option_content = "薇薇安，妳來啦！",
  ui_story_1021_10210201_16_dialog_content = "……！",
  ui_story_1021_10210201_17_dialog_content = "雖然同事常常把這樣的話掛在嘴邊……但我一直鼓勵他們，薇薇安大人對我們還是蠻不錯的！",
  ui_story_1021_10210201_18_dialog_content = "工作安排恰當，報酬又可觀……還能在多樣化的任務中鍛煉自己……去哪找這麼好的工作嘛……？",
  ui_story_1021_10210201_19_dialog_content = "……變臉的速度真快啊。",
  ui_story_1021_10210201_20_option_content = "暗面探索隊歡迎妳加入",
  ui_story_1021_10210201_21_dialog_content = "暗面？！饒了我吧……比起去暗面探索，信使工作可說是好上一萬倍。",
  ui_story_1021_10210201_22_dialog_content = "仔細想想……我可以靈活安排送信時間，不僅行動自由，也沒有下班壓力……",
  ui_story_1021_10210201_23_dialog_content = "所以感謝你的邀請，我還是繼續混……繼續當好一名信使吧！",
  ui_story_1021_10210201_24_dialog_content = "這下薇薇安該頒給我一個「勸工獎」了……",
  ui_story_1021_10210201_25_dialog_content = "大元帥，約定的時間到了，北境的代表還沒出席。",
  ui_story_1021_10210201_26_dialog_content = "我上午有收到北境的來信了，先按照正常程式開始會議吧。",
  ui_story_1021_10210201_27_dialog_content = "是，大元帥。",
  ui_story_1021_10210201_28_dialog_content = "各位陣營代表，感謝你們出席「艾斯特拉大陸聯合探索大會」的首次會議。",
  ui_story_1021_10210201_29_dialog_content = "我是啟光聯邦的參謀長薇薇安。若無特殊情況，會議就開始了。",
  ui_story_1021_10210201_30_dialog_content = "我沒問題。",
  ui_story_1021_10210201_31_dialog_content = "我代表影主大人出席，我也沒問題。",
  ui_story_1021_10210201_32_dialog_content = "看樣子，也只能先開始了。",
  ui_story_1021_10210201_33_dialog_content = "那麼，讓我們正式啟動會議。",
  ui_story_1021_10210201_34_dialog_content = "我們選擇這個開闊的會議地點，是希望我們能夠在陽光下共同討論光靈的未來。",
  ui_story_1021_10210201_35_dialog_content = "首先，我要感謝信使公會的成員在據點建設期間提供的幫助。",
  ui_story_1021_10210201_36_dialog_content = "為了確保各陣營能盡速回應暗面探索隊的動態，信使公會將在多個領域提供支援……",
  ui_story_1021_10210201_37_dialog_content = "包括據點間的資訊傳遞和暗面線索的資訊回報。信使公會將承擔監督和確認的重要職責。",
  ui_story_1021_10210201_38_dialog_content = "嘿嘿！信使公會，使命必達！",
  ui_story_1021_10210201_39_dialog_content = "現在，請啟光大元帥向我們介紹聯合探索的計畫，並徵詢各位的意見。",
  ui_story_1021_10210201_40_dialog_content = "關於此次探索的路線，此前的聯合信件中有提過……",
  ui_story_1021_10210201_41_dialog_content = "關於探索路線，我們計畫在暗面附近建立多個<color=#FFB400>前沿據點</color>，以便於支援和收集情報。",
  ui_story_1021_10210201_42_dialog_content = "根據各陣營的地理位置，我們將在艾斯特拉北部設立<color=#FFB400>三個據點</color>。",
  ui_story_1021_10210201_43_dialog_content = "第一個據點設於西北的<color=#FFB400>黃昏鎮</color>。黃昏鎮目前的規模和勢力，非常適合當作探索隊進入暗面的後備基地。",
  ui_story_1021_10210201_44_dialog_content = "此前白夜城城主已和我達成共治黃昏鎮的共識，本次正式建立黃昏鎮據點，將視作此共識的見證。",
  ui_story_1021_10210201_45_dialog_content = "黃昏鎮將成立「戰略執行指揮部」，負責為探索隊提供必要的支援。",
  ui_story_1021_10210201_46_dialog_content = "李奧將擔任據點負責人，並定期向總指揮部報告探索隊的進展。",
  ui_story_1021_10210201_47_dialog_content = "其他兩個據點分別是<color=#FFB400>空之山谷據點</color>和<color=#FFB400>北境據點</color>。",
  ui_story_1021_10210201_48_dialog_content = "考慮到空谷地下遺跡的影響，我們正在評估空谷據點的建立可行性。",
  ui_story_1021_10210201_49_dialog_content = "北境據點的建設將因環境特殊而耗時較長，我將與北境女王確認後立即向大家回報。",
  ui_story_1021_10210201_50_dialog_content = "最後，我要說明……",
  ui_story_1021_10210201_51_dialog_content = "暗面探索的路線和座標資訊，是由啟光聯邦的科學家阿爾戈爾博士和一名重要情報員共同完成的。",
  ui_story_1021_10210201_52_dialog_content = "資訊經過多次驗證，確保其真實性和安全性。我們將這些情報分享給各位，希望大家能共同參與和維護。",
  ui_story_1021_10210201_53_dialog_content = "針對以上資訊，大家可以提問了。",
  ui_story_1021_10210201_54_dialog_content = "為了獲得這些暗面情報，啟光付出了不小的代價。",
  ui_story_1021_10210201_55_dialog_content = "你們啟光聯邦有野心的傢伙不少，但這是關乎光靈未來的探索，你們自己真的能決定前往暗面的人選嗎？",
  ui_story_1021_10210201_56_dialog_content = "當然。在啟光，我們不以野心大小來評斷個人，而是以戰勝困難的勇氣和決心。",
  ui_story_1021_10210201_57_dialog_content = "首先，我們已經有一支菁英<color=#FFB400>「探索小隊」</color>在暗面打前陣了，他們將為後續的探索鋪路。",
  ui_story_1021_10210201_58_dialog_content = "其次是行動顧問<color=#FFB400>巴蕾特博士</color>。本次駕駛的飛行器就是她的團隊所研發。",
  ui_story_1021_10210201_59_dialog_content = "接著是情報長<color=#FFB400>菲莉詩中尉</color>，她負責團隊的生活和通訊。",
  ui_story_1021_10210201_60_dialog_content = "我們的軍事後備正在接受最後的測試，他們將是我們探索隊的堅強後盾。",
  ui_story_1021_10210201_61_dialog_content = "根據你們提供的情報，白夜城方會派出精銳部隊，為往後的隊伍剷除障礙。",
  ui_story_1021_10210201_62_dialog_content = "……",
  ui_story_1021_10210201_63_dialog_content = "（精銳部隊？白夜城也想在探索中取得主導權，看來卡蓮都不知道城主的安排……）",
  ui_story_1021_10210201_64_dialog_content = "白夜城的隊伍將與大家並肩作戰，為探索提供全力支援。",
  ui_story_1021_10210201_65_dialog_content = "嗯。我們的軍事物資都準備就緒，只待出發的號令了。",
  ui_story_1021_10210201_66_dialog_content = "咳咳……咳咳……影鎮總商會也準備了豐富的物資，我們的商隊會陸續將物資運到出發地。",
  ui_story_1021_10210201_67_dialog_content = "影鎮雖然探索經驗不足，但是這些物資足夠一支<color=#FFB400>探索隊</color>使用一年。",
  ui_story_1021_10210201_68_dialog_content = "感謝你們慷慨解囊。",
  ui_story_1021_10210201_69_dialog_content = "對影鎮來說，這是一次雙贏的交易。",
  ui_story_1021_10210201_70_dialog_content = "關於啟程的確切日期，我們會盡快通知大家。",
  ui_story_1021_10210201_71_dialog_content = "（這就是所謂的「有錢出錢，有力出力」……）",
  ui_story_1021_10210201_72_dialog_content = "PlayerName，你似乎有話要說？",
  ui_story_1021_10210201_73_dialog_content = "呃……我或許沒有物資能提供給大家，但我有一顆保護同伴的心！",
  ui_story_1021_10210201_74_dialog_content = "我們這次要去的地方會充滿危險，我一定會確保我們的隊伍安全。",
  ui_story_1021_10210201_75_dialog_content = "不會讓我的同伴們受傷或莫名其妙脫隊……",
  ui_story_1021_10210201_76_dialog_content = "……",
  ui_story_1021_10210201_77_dialog_content = "（說錯什麼話了嗎……）",
  ui_story_1021_10210201_78_dialog_content = "PlayerName，如果你需要商會的幫助，歡迎隨時開口。",
  ui_story_1021_10210201_79_dialog_content = "謝謝，貝菲爾會長，我會記住的。",
  ui_story_1021_10210201_80_dialog_content = "主要議題討論完了，我就說幾句閒話吧。",
  ui_story_1021_10210201_81_dialog_content = "我年輕的時候，曾希望等我成為白夜城的城主後，可以親自去想去的地方巡視。",
  ui_story_1021_10210201_82_dialog_content = "但現在看來，光是把白夜城治理好就已經來到這把年紀了。",
  ui_story_1021_10210201_83_dialog_content = "所以於公，我在我有生之年，希望透過你們年輕人的眼睛再看看更遠的世界。",
  ui_story_1021_10210201_84_dialog_content = "於私，儘管此行不易，我仍然希望卡蓮能參與你們見證一個新時代的誕生。",
  ui_story_1021_10210201_85_dialog_content = "城主大人……",
  ui_story_1021_10210201_86_dialog_content = "您相信，我們的探索會開啟一個新時代嗎？",
  ui_story_1021_10210201_87_dialog_content = "當然。應該說，從你在艾斯特拉大陸上揭開一個又一個謎團起，嶄新的時代就已經來臨了。",
  ui_story_1021_10210201_88_dialog_content = "我們將全力支持你們的探索，因為艾斯特拉大陸的未來已經掌握在你們手中了。",
  ui_story_1021_10210201_89_dialog_content = "羅伊哥，你也來幫個忙嘛！我一個人忙不過來了。",
  ui_story_1021_10210201_90_dialog_content = "都說上了年紀會開始喜歡撿破爛，但大叔我啊，只在想今晚的肉排要搭配什麼醬汁好……",
  ui_story_1021_10210201_91_dialog_content = "哈——啾——！",
  ui_story_1021_10210201_92_dialog_content = "啟光的飛行器新歸新，但這刺鼻的工廠味也太像胡椒粉了吧，哈——啾！",
  ui_story_1021_10210201_93_dialog_content = "醒山大哥總是想得周到，他對空裔他們的探索很感興趣。嘿，我們得好好研究這飛行器，萬一有用呢！",
  ui_story_1021_10210201_94_dialog_content = "醒山那小子還真是一如既往地愛惹麻煩啊……喂，小不點，走了！",
  ui_story_1021_10210201_95_dialog_content = "新機械總是需要時間散味道嘛，希望衛隊長待會不要介意。",
  ui_story_1021_10210201_96_dialog_content = "喔，沒關係，我對氣味不敏感。",
  ui_story_1021_10210201_97_dialog_content = "今天早上收到北境女王來信，說據點的建設要往後延幾天。確切原因她沒說，身為盟友我也不便過問。",
  ui_story_1021_10210201_98_dialog_content = "但探索任務需要各據點同時進行，目前啟光已經抽不出人手了。",
  ui_story_1021_10210201_99_dialog_content = "所以要麻煩你們兩位替我跑一趟了。",
  ui_story_1021_10210201_100_dialog_content = "嗯，最近發生這麼多事情，我也很久沒去北境了。",
  ui_story_1021_10210201_101_dialog_content = "那正好，PlayerName也能帶妳熟悉一下飛行器的駕駛。",
  ui_story_1021_10210201_102_dialog_content = "交給我吧！雖然這和臨空號不太一樣……但很多地方的設計還是會讓我產生熟悉的感覺。",
  ui_story_1021_10210201_103_dialog_content = "所以最近，我已經獨自駕著飛行器跑遍半個艾斯特拉了。",
  ui_story_1021_10210201_104_dialog_content = "那就拜託了，有問題隨時聯絡我。通訊裝置已經都調校好了。",
  ui_story_1021_10210201_105_dialog_content = "一路順風！",
  ui_story_1021_10210201_106_dialog_content = "嗯！",
  ui_story_1021_10210201_107_dialog_content = "大元帥，要提醒PlayerName他們，這有兩個紅油扳手的傢伙嗎？",
  ui_story_1021_10210201_108_dialog_content = "不用，這是探索中常有的事，他們自己會處理了。",
  ui_story_1021_10210201_109_dialog_content = "況且，紅油扳手不是也吵著要加入這次探索嗎？",
  ui_story_1021_10210301_1_dialog_content = "<color=#e8d9bb>一段時間後……</color>",
  ui_story_1021_10210301_2_dialog_content = "此前我還有點擔心，啟光的飛行器會坐不習慣。",
  ui_story_1021_10210301_3_dialog_content = "沒想到，雖然空間小得多，但和搭乘臨空者號的感覺還蠻像的，不知不覺已經快到北境了。",
  ui_story_1021_10210301_4_dialog_content = "我就說嘛，不會有問題的。",
  ui_story_1021_10210301_5_dialog_content = "在降落之前，妳要不要來試著駕駛看看？剛才起飛的時候妳也看到了，其實很簡單。",
  ui_story_1021_10210301_6_dialog_content = "那……那你在旁邊講解，我來操作看看。",
  ui_story_1021_10210301_7_dialog_content = "嗯，首先，這裡的控制台上都會顯示——",
  ui_story_1021_10210301_8_dialog_content = "<color=#e8d9bb>轟隆隆——！</color>",
  ui_story_1021_10210301_9_dialog_content = "啊——！",
  ui_story_1021_10210301_10_dialog_content = "怎、怎麼回事？！我什麼都還沒碰！",
  ui_story_1021_10210301_11_dialog_content = "別、別怕……！應該是亂流影響……",
  ui_story_1021_10210301_12_dialog_content = "這個俯衝的感覺……只要拉起駕駛桿，然後……",
  ui_story_1021_10210301_13_dialog_content = "<color=#e8d9bb>嗶——嗶——嗶——</color>",
  ui_story_1021_10210301_14_dialog_content = "糟糕——！",
  ui_story_1021_10210301_15_dialog_content = "<color=#e8d9bb>嗶——嗶——嗶——</color>",
  ui_story_1021_10210301_16_dialog_content = "羅伊哥你找到了嗎？！要不然……我們直接去接管飛行器好了。",
  ui_story_1021_10210301_17_dialog_content = "現在出去只會惹人誤會，反而麻煩。我這裡……馬上就……啊不行，太黑了使不上力氣。",
  ui_story_1021_10210301_18_dialog_content = "我有現成的燈！",
  ui_story_1021_10210301_19_dialog_content = "……還真是刺眼啊……咱們到哪了？",
  ui_story_1021_10210301_20_dialog_content = "離紅油沙漠少說也有個幾百公里吧。外面越來越白，該不會是到北境了……",
  ui_story_1021_10210301_21_dialog_content = "這麼說的話，遇到極端亂流也不奇怪……",
  ui_story_1021_10210301_22_dialog_content = "嘖……這結構跟我想的不一樣啊，看來是修不了啦。",
  ui_story_1021_10210301_23_dialog_content = "什麼叫跟你想得不一樣？這可是性命攸關的事啊！讓我看看！",
  ui_story_1021_10210301_24_dialog_content = "……你剛剛是說升降舵出了問題吧？",
  ui_story_1021_10210301_25_dialog_content = "嗯，差不多。啟光的飛行器上根本就沒有傳動軸這種東西……",
  ui_story_1021_10210301_26_dialog_content = "……因為傳動軸已經斷了啊！",
  ui_story_1021_10210301_27_dialog_content = "這樣啊……那我找找口袋裡有沒有能用的東西，妳先用扳手撐一會吧。",
  ui_story_1021_10210301_28_dialog_content = "你倒是稍微有點危機感啊！！！",
  ui_story_1021_10210301_29_dialog_content = "<color=#e8d9bb>轟隆——！！！</color>",
  ui_story_1021_10210301_30_dialog_content = "嗚哇……！！！",
  ui_story_1021_10210301_31_dialog_content = "沒、沒事了！妳還好吧？",
  ui_story_1021_10210301_32_dialog_content = "卡蓮呢？這些血跡……該不會……？卡蓮！！！",
  ui_story_1021_10210301_33_dialog_content = "……！",
  ui_story_1021_10210301_34_dialog_content = "我再也不要坐什麼飛行器了！！！",
  ui_story_1021_10210301_35_dialog_content = "（看樣子沒事了……）",
  ui_story_1021_10210301_36_dialog_content = "嗯……不坐了不坐了……都怪我……",
  ui_story_1021_10210301_37_dialog_content = "但也確實沒想到，北境會遇到這麼嚴重的亂流……",
  ui_story_1021_10210301_38_dialog_content = "……",
  ui_story_1021_10210301_39_dialog_content = "這也是冒險中難免的事……",
  ui_story_1021_10210301_40_dialog_content = "還好後來駕駛桿又突然回應我的操作了——",
  ui_story_1021_10210301_41_dialog_content = "欸……！尾翼都已經翹成這個角度了，竟然還能安全降落……",
  ui_story_1021_10210301_42_dialog_content = "你是想要我稱讚你的駕駛技術很厲害嗎？",
  ui_story_1021_10210301_43_dialog_content = "這……我還真不知道怎麼回答……",
  ui_story_1021_10210301_44_dialog_content = "<color=#e8d9bb>嗷嗚嗚——！</color>",
  ui_story_1021_10210301_45_dialog_content = "這是……野獸的領地嗎？到處都是血跡……",
  ui_story_1021_10210301_46_dialog_content = "確實像最近的戰鬥留下的痕跡……這裡離冬宮應該還很遠，說不定是暗鬼造成的……",
  ui_story_1021_10210301_47_dialog_content = "暗鬼……那這就是燈塔之外的地方了……",
  ui_story_1021_10210301_48_dialog_content = "燈塔之外的北境，比你想像的還要遼闊。尤其是北部，暗鬼橫行無忌……",
  ui_story_1021_10210301_49_dialog_content = "之前只是聽說，沒想到親眼見到會這麼嚇人……",
  ui_story_1021_10210301_50_dialog_content = "……",
  ui_story_1021_10210301_51_dialog_content = "……那邊有人聲！",
  ui_story_1021_10210301_52_dialog_content = "過去看看。",
  ui_story_1021_10210301_53_dialog_content = "哼！",
  ui_story_1021_10210301_54_dialog_content = "小妹妹，妳這樣看著我也沒辦法啊，就說了我們是逼不得已才來到這的。",
  ui_story_1021_10210301_55_dialog_content = "飛行器上還有我羅伊駕駛員的工作證，不信妳等一下，我去找來給妳看……",
  ui_story_1021_10210301_56_dialog_content = "羅伊哥，我們哪有工作證這種東西？",
  ui_story_1021_10210301_57_dialog_content = "嘖……每次帶小鬼出門就是麻煩，又把工作證弄丟了吧？我去幫妳找！",
  ui_story_1021_10210301_58_dialog_content = "站住！",
  ui_story_1021_10210301_59_dialog_content = "讓他們走吧。",
  ui_story_1021_10210301_60_dialog_content = "長老！您、您怎麼會在這？！您不是……",
  ui_story_1021_10210301_61_dialog_content = "不必擔心我。",
  ui_story_1021_10210301_62_dialog_content = "但部落一夜之間就變成這樣，我怎麼能不擔心呢？！您看到那些滲出黑血的狐兒了嗎？！",
  ui_story_1021_10210301_63_dialog_content = "妳不該來這裡。",
  ui_story_1021_10210301_64_dialog_content = "您總是要我離開……但這裡是我的故鄉啊……！",
  ui_story_1021_10210301_65_dialog_content = "……提亞拉？",
  ui_story_1021_10210301_66_dialog_content = "來，躲進我張開的防護罩裡吧。",
  ui_story_1021_10210301_67_dialog_content = "身為女王陛下的護衛，我實在太失職了！",
  ui_story_1021_10210301_68_dialog_content = "請女王陛下勿再丟下提亞拉，獨自一人對付暗鬼！",
  ui_story_1021_10210301_69_dialog_content = "讓提亞拉為女王陛下衝鋒陷陣吧！",
  ui_story_1021_10210301_70_dialog_content = "女王的護衛……",
  ui_story_1021_10210301_71_dialog_content = "是你們……",
  ui_story_1021_10210301_72_dialog_content = "妳怎麼在這？這裡……發生什麼事了嗎？",
  ui_story_1021_10210301_73_dialog_content = "……",
  ui_story_1021_10210301_74_dialog_content = "（這就是傳說中的雪狐嗎……牠看我的眼神……似乎在叫我滾開。）",
  ui_story_1021_10210301_75_dialog_content = "我們……是來拜訪女王陛下的。不料飛行器遇到亂流，我們才迫降在這裡。",
  ui_story_1021_10210301_76_dialog_content = "……",
  ui_story_1021_10210301_77_dialog_content = "……如有叨擾，還請見諒。",
  ui_story_1021_10210301_78_dialog_content = "那兩個傢伙跟你們是一起的嗎？",
  ui_story_1021_10210301_79_dialog_content = "哪兩個傢伙？",
  ui_story_1021_10210301_80_dialog_content = "……他們剛才還在這裡的！",
  ui_story_1021_10210301_81_dialog_content = "那兩個人手裡拿著奇怪的東西對著我的朋友比劃，聲稱是飛行器的駕駛員。",
  ui_story_1021_10210301_82_dialog_content = "飛行器上，只有我和卡蓮兩個人啊……",
  ui_story_1021_10210301_83_dialog_content = "不可能！",
  ui_story_1021_10210301_84_dialog_content = "提亞拉，妳先別急。",
  ui_story_1021_10210301_85_dialog_content = "如果他們傷害到妳和妳朋友，我和PlayerName一定不會放過他們。",
  ui_story_1021_10210301_86_dialog_content = "妳剛剛好像提到，這是妳的故鄉……？",
  ui_story_1021_10210301_87_dialog_content = "……這是北境的邊境地區，因為有暗鬼出沒……",
  ui_story_1021_10210301_88_dialog_content = "我是……奉女王陛下的命令，在巡查這片雪松林。",
  ui_story_1021_10210301_89_dialog_content = "原來是這樣……那等妳巡邏結束後，可以帶我們去見女王陛下嗎？",
  ui_story_1021_10210301_90_dialog_content = "我們也還找不到去冬宮的路。如果要對付暗鬼，我們也能幫上忙！",
  ui_story_1021_10210301_91_dialog_content = "<color=#e8d9bb>嚶嚶嚶——！</color>",
  ui_story_1021_10210301_92_dialog_content = "不行！",
  ui_story_1021_10210301_93_dialog_content = "我是說……這裡離冬宮很遠，而且非常危險，你們還是趕快離開吧。",
  ui_story_1021_10210301_94_dialog_content = "那是……",
  ui_story_1021_10210301_95_dialog_content = "（提亞拉的表情明顯不對勁……）",
  ui_story_1021_10210301_96_dialog_content = "可以告訴我們，這裡發生了什麼事嗎？",
  ui_story_1021_10210301_97_dialog_content = "……",
  ui_story_1021_10210301_98_dialog_content = "你們不是要見女王陛下嗎……？",
  ui_story_1021_10210301_99_dialog_content = "順著那隻兔子的腳印，你們應該就能見到她。",
  ui_story_1021_10210301_100_dialog_content = "如果見到女王陛下，請幫我轉告她……我會把腳印打掃乾淨，但不是現在。",
  ui_story_1021_10210301_101_dialog_content = "……",
  ui_story_1021_10210301_102_dialog_content = "這麼快就不見人影了……",
  ui_story_1021_10210301_103_dialog_content = "沒想到，北境真的有雪狐部落……",
  ui_story_1021_10210301_104_dialog_content = "我在北境學習的時候，曾聽過一些當地的居民提到……",
  ui_story_1021_10210301_105_dialog_content = "北境的西北邊陲曾經有一個雪狐聚集的部落，仰賴著雪松林生存。",
  ui_story_1021_10210301_106_dialog_content = "雪狐保護著雪松林，以及雪松林底下的遺跡。",
  ui_story_1021_10210301_107_dialog_content = "但因為沒有人見過，大家都不確定是傳說還是事實。但排斥光靈這一點似乎是真的……",
  ui_story_1021_10210301_108_dialog_content = "你有沒有注意到，提亞拉把那些受傷的雪狐護在她的身後？",
  ui_story_1021_10210301_109_dialog_content = "嗯……還有那隻年長的雪狐，看到我們彷彿看到仇敵一樣……",
  ui_story_1021_10210301_110_dialog_content = "那些血跡應該就是雪狐留下的。",
  ui_story_1021_10210301_111_dialog_content = "這些血跡黑一塊紅一塊的，我的頭都暈了起來……",
  ui_story_1021_10210301_112_dialog_content = "據說雪狐中有應自然之力而生的「山靈」，一旦自然受到暗能侵蝕，牠們的身體也會隨之病變。",
  ui_story_1021_10210301_113_dialog_content = "你會感到不舒服，大概是這些血跡中暗能的緣故吧。",
  ui_story_1021_10210301_114_dialog_content = "暗能……那她請我們轉告女王的話，就沒有那麼簡單了……",
  ui_story_1021_10210301_115_dialog_content = "結合目前的情況來看，或許是暗鬼入侵了北境，不僅傷害雪狐，還摧毀了據點……",
  ui_story_1021_10210301_116_dialog_content = "於是女王陛下遲遲沒有派出信使……",
  ui_story_1021_10210301_117_dialog_content = "那提亞拉的處境就非常危險了！",
  ui_story_1021_10210301_118_dialog_content = "我們應該跟著她！萬一她遇到什麼危險了，我們也能幫上忙。",
  ui_story_1021_10210301_119_dialog_content = "順著血跡走吧！邊境地區的暗鬼眾多，我們也要小心一點！",
  ui_story_1021_10210401_1_dialog_content = "血跡在這裡消失了……？不知道是不是我暈血的緣故，腦袋越來越不舒服……",
  ui_story_1021_10210401_2_dialog_content = "讓我用……感應能力找一找線索吧……",
  ui_story_1021_10210401_3_dialog_content = "PlayerName，經過上次的事件後，我知道你一直沒有使用感應能力。你……不害怕了嗎？",
  ui_story_1021_10210401_4_option_content = "嗯……",
  ui_story_1021_10210401_5_dialog_content = "確實有很長一段時間，只要一想到感應能力，我的心情就會變得很複雜……",
  ui_story_1021_10210401_6_option_content = "還是會有點害怕",
  ui_story_1021_10210401_7_dialog_content = "這段時間以來，只要一想到感應能力，我就心亂如麻……",
  ui_story_1021_10210401_8_dialog_content = "你擔心會看到那些遙遠的片段，以及再次受到工程師注視？",
  ui_story_1021_10210401_9_dialog_content = "嗯，我也擔心會耳聞或目睹薇絲和臨空者號不好的消息……",
  ui_story_1021_10210401_10_dialog_content = "我知道這些事對你造成的影響有多大，但是——",
  ui_story_1021_10210401_11_dialog_content = "但是拋開這些不談，感應能力是我的戰鬥力，也是我保護大家的方式。",
  ui_story_1021_10210401_12_dialog_content = "無論如何，我都會克服恐懼，練習好好控制感應能力！",
  ui_story_1021_10210401_13_dialog_content = "所以，感謝妳的關心，卡蓮。我已經，沒事了。",
  ui_story_1021_10210401_14_dialog_content = "你能這麼快振作起來，我很為你開心，PlayerName。",
  ui_story_1021_10210401_15_dialog_content = "要記住，我一直在你身邊。如果感應中遇到危險，我會和你一起面對。",
  ui_story_1021_10210401_16_dialog_content = "嗯！",
  ui_story_1021_10210401_17_option_content = "感應——連接——",
  ui_story_1021_10210401_18_dialog_content = "（空曠的洞穴……）",
  ui_story_1021_10210401_19_dialog_content = "（這些冰層，已經形成很長一段時間了。）",
  ui_story_1021_10210401_20_dialog_content = "……她如果參加紅油拉力賽，一定能贏得冠軍……",
  ui_story_1021_10210401_21_dialog_content = "雙腿怎能與四輪相提並論？等等……你聞到那股刺鼻的味道了嗎？",
  ui_story_1021_10210401_22_dialog_content = "（……這些聲音……從哪裡傳來的？）",
  ui_story_1021_10210401_23_dialog_content = "（……是黑紅色的血跡，和地面上一樣！）",
  ui_story_1021_10210401_24_dialog_content = "（至少，我還能掌控我的意識……）",
  ui_story_1021_10210401_25_dialog_content = "（對了，提亞拉來過這裡……這洞穴會不會就在雪松林下面……）",
  ui_story_1021_10210401_26_dialog_content = "這腐爛的臭味……真叫人懷念紅油的香氣啊……",
  ui_story_1021_10210401_27_dialog_content = "……快把妳的燈關了。待會要是引出什麼奇怪的東西，我們不就白受凍了。",
  ui_story_1021_10210401_28_dialog_content = "我們為什麼放著雪地不走，非要躲到這裡來啊……現在連個問路的人都找不到。",
  ui_story_1021_10210401_29_dialog_content = "羅伊哥不是說，最討厭的地方就是「地底」了嗎？",
  ui_story_1021_10210401_30_dialog_content = "（怎麼是他們兩個？！）",
  ui_story_1021_10210401_31_dialog_content = "（這裡的岔路很多，他們是從哪個方向進去的……）",
  ui_story_1021_10210401_32_option_content = "感應——延伸——",
  ui_story_1021_10210401_33_dialog_content = "……",
  ui_story_1021_10210401_34_dialog_content = "看到什麼？",
  ui_story_1021_10210401_35_dialog_content = "提亞拉剛才說不懷好意的傢伙，是我認識的兩個紅油的朋友……",
  ui_story_1021_10210401_36_dialog_content = "……延伸視野之後，我好像看到一團像蒸汽般膨脹的暗能……",
  ui_story_1021_10210401_37_dialog_content = "離我們非常近……",
  ui_story_1021_10210401_38_dialog_content = "……！",
  ui_story_1021_10210401_39_dialog_content = "而且洞穴裡有和雪地上一模一樣的血跡……提亞拉應該也在那……",
  ui_story_1021_10210401_40_dialog_content = "那我們必須加緊腳步找到他們！現在該往哪走？",
  ui_story_1021_10210401_41_dialog_content = "血跡在這裡消失了，洞穴應該就在這片雪松的背後。跟我來！",
  ui_story_1021_10210401_42_dialog_content = "（提亞拉，還有羅伊、小不點，你們千萬不要有事啊……）",
  ui_story_1021_10210401_43_dialog_content = "<color=#e8d9bb>嗚嗚……</color>",
  ui_story_1021_10210401_44_dialog_content = "偉大而古老的神靈啊，提亞拉永遠仰望您，如同您永遠注視著我們一樣。",
  ui_story_1021_10210401_45_dialog_content = "黑暗的陰影再次降臨，猶如獵食者般侵蝕我們的身體，在我們身上留下無法抹去的烙印。",
  ui_story_1021_10210401_46_dialog_content = "在冬宮，我是女王陛下的護衛……",
  ui_story_1021_10210401_47_dialog_content = "而在此，我是宣誓過要保護部落的首領。",
  ui_story_1021_10210401_48_dialog_content = "您孕育了部落，並將神聖的血脈傳給我們，讓我們與神聖的您相連。",
  ui_story_1021_10210401_49_dialog_content = "但現在，我所剩無幾的族人們日夜痛苦呻吟，身軀潰敗……我知道我們總有一天會回到您的懷抱。",
  ui_story_1021_10210401_50_dialog_content = "願您再次將慈愛的目光投向我們，如同您曾經庇護我們的先祖和部落一樣。",
  ui_story_1021_10210401_51_dialog_content = "<color=#e8d9bb>嚶嚶嚶——！</color>",
  ui_story_1021_10210401_52_dialog_content = "那些誤入此地的光靈遇到了危險，我已經無力再驅逐他們了……",
  ui_story_1021_10210401_53_dialog_content = "長老，這本該是我的職責……",
  ui_story_1021_10210401_54_dialog_content = "提亞拉！看看妳手裡拿的長矛！妳是北境的護衛……請放下妳對這裡的牽掛……",
  ui_story_1021_10210401_55_dialog_content = "……咳咳咳……",
  ui_story_1021_10210401_56_dialog_content = "長老……求您……我不能眼睜睜看著族人走向滅亡……",
  ui_story_1021_10210401_57_dialog_content = "妳……不該回來……",
  ui_story_1021_10210401_58_dialog_content = "我到底……該怎麼做……",
  ui_story_1021_10210401_59_dialog_content = "<color=#e8d9bb>滴答——滴答——</color>",
  ui_story_1021_10210401_60_dialog_content = "哎唷——！",
  ui_story_1021_10210401_61_dialog_content = "結冰的路面很滑，小心點。不對……這裡怎麼開始滴水了？",
  ui_story_1021_10210401_62_dialog_content = "我已經連續踩到好幾個水坑了。剛才摔那一下，大概是被這股難聞的氣味給熏昏頭了……",
  ui_story_1021_10210401_63_dialog_content = "等等！我好像踩到什麼軟綿綿的東西……妳幫我看一眼……",
  ui_story_1021_10210401_64_dialog_content = "好像是……一隻雪狐……",
  ui_story_1021_10210401_65_dialog_content = "牠還……活著嗎……？",
  ui_story_1021_10210401_66_dialog_content = "……",
  ui_story_1021_10210401_67_dialog_content = "完、完了……我忽然覺得眼前一陣發白……",
  ui_story_1021_10210401_68_dialog_content = "你振作一點，前面似乎真的有白光……",
  ui_story_1021_10210401_69_dialog_content = "<color=#e8d9bb>滴答——滴答——</color>",
  ui_story_1021_10210401_70_dialog_content = "小不點，是我產生錯覺嗎？我們這樣一直走，感覺就要走回老家了……",
  ui_story_1021_10210401_71_dialog_content = "越來越熱……我的肌肉也不知不覺放鬆了許多。",
  ui_story_1021_10210401_72_dialog_content = "既然是這樣，這袋寶石給你來提吧。",
  ui_story_1021_10210401_73_dialog_content = "妳這是什麼話……白撿的寶貝都不要，這怎麼行……",
  ui_story_1021_10210401_74_dialog_content = "啊！別碰我的頭啦！你的手都是黏黏的汗！",
  ui_story_1021_10210401_75_dialog_content = "妳這、這……我的雙眼受不了這種突然的光照……就說強光容易引來麻煩的傢伙。",
  ui_story_1021_10210401_76_dialog_content = "喂，你們兩個！",
  ui_story_1021_10210401_77_dialog_content = "還真的說來就來了……",
  ui_story_1021_10210401_78_dialog_content = "你們好……",
  ui_story_1021_10210401_79_dialog_content = "嗨，PlayerName，你們也來尋寶？",
  ui_story_1021_10210401_80_dialog_content = "尋寶？！你們為什麼混入了我們的飛行器？",
  ui_story_1021_10210401_81_dialog_content = "醒山那傢伙是忘記交報名表了嗎？我們是代表紅油扳手參加艾斯特拉大陸的聯合探索會議的。",
  ui_story_1021_10210401_82_dialog_content = "誰知道你們的會議實在無聊透頂，我們一覺睡醒就被賣到這來了……",
  ui_story_1021_10210401_83_dialog_content = "我看你們帶那麼大一個背包，是想來偷走北境的寶石吧？！我勸你們哪裡拿的放回哪去！",
  ui_story_1021_10210401_84_dialog_content = "這……這原來是北境啊？呵呵，大叔我啊，還沒離開過紅油沙漠呢，哪知道什麼地方有寶石啊！",
  ui_story_1021_10210401_85_dialog_content = "倒是順手幫你們修了修機器，這袋東西如果當作謝禮的話，我也不計較了。",
  ui_story_1021_10210401_86_dialog_content = "你們——！！！",
  ui_story_1021_10210401_87_dialog_content = "卡蓮，等等……我好像知道是怎麼回事了。",
  ui_story_1021_10210401_88_dialog_content = "這兩人在紅油扳手都是數一數二的機械師，飛行器上遠離控制室的只有靠近尾翼那個修理間。",
  ui_story_1021_10210401_89_dialog_content = "而尾翼翻成那個模樣我們還能安全降落……或許是他們躲在那裡，順便幫了個大忙……",
  ui_story_1021_10210401_90_dialog_content = "你說的是……真的？",
  ui_story_1021_10210401_91_dialog_content = "那個……飛行器的事，謝謝你們……",
  ui_story_1021_10210401_92_dialog_content = "客氣什麼，都聯合探索了，當然要互相照應囉。",
  ui_story_1021_10210401_93_dialog_content = "<color=#e8d9bb>滴答——滴答——</color>",
  ui_story_1021_10210401_94_dialog_content = "一碼歸一碼，回去之後，我可以給你們一些白夜幣，但北境的寶石，你們不能帶走。",
  ui_story_1021_10210401_95_dialog_content = "白夜幣，也……行吧。",
  ui_story_1021_10210401_96_dialog_content = "羅伊、小不點，這附近很危險，和雪狐在一起的那個女孩，你們知道她往哪去了嗎？",
  ui_story_1021_10210401_97_dialog_content = "知道啊，但她跑得太快了！根本追不上！",
  ui_story_1021_10210401_98_dialog_content = "我們明明是在躲她……",
  ui_story_1021_10210401_99_dialog_content = "PlayerName，這洞穴中有不少狐狸的屍骨，她身邊似乎有很多狐狸都傷得不輕。",
  ui_story_1021_10210401_100_dialog_content = "那我們要快點找到她才行……",
  ui_story_1021_10210401_101_dialog_content = "既然知道怎麼走，就由你們來帶路吧。",
  ui_story_1021_10210401_102_dialog_content = "……這裡還行，裡面就別想了。洞穴中岔路很多……我和小不點都差點迷路了。",
  ui_story_1021_10210401_103_dialog_content = "羅伊哥！我的燈……",
  ui_story_1021_10210401_104_dialog_content = "變暗了？",
  ui_story_1021_10210401_105_dialog_content = "這也意味著暗能變強了……",
  ui_story_1021_10210401_106_dialog_content = "雖然我也喜歡暖和的地方，但是抱歉了，PlayerName、白夜幣小姐，我得帶著我們家小不點先走了！",
  ui_story_1021_10210401_107_dialog_content = "這兩個傢伙，剛才還說要互相照應……這下我們該走哪條路呢？",
  ui_story_1021_10210401_108_dialog_content = "我用感應能力看看吧。",
  ui_story_1021_10210401_109_option_content = "感應——延伸——",
  ui_story_1021_10210401_110_dialog_content = "貪……嗔……癡……是憂苦身心的虛妄。",
  ui_story_1021_10210401_111_dialog_content = "因嗔而怒，進而產生病相。",
  ui_story_1021_10210401_112_dialog_content = "是的……是的……",
  ui_story_1021_10210401_113_dialog_content = "氣焰……又收斂了一些……",
  ui_story_1021_10210401_114_dialog_content = "（暗鬼？！）",
  ui_story_1021_10210401_115_dialog_content = "（雖然看不清楚……但就是剛才感應到的那個……）",
  ui_story_1021_10210401_116_dialog_content = "（牠周圍的暗能……我的腦袋……像被拳頭猛捶一樣……）",
  ui_story_1021_10210401_117_dialog_content = "大人——！",
  ui_story_1021_10210401_118_dialog_content = "嗯……？",
  ui_story_1021_10210401_119_dialog_content = "嘎啊——！",
  ui_story_1021_10210401_120_dialog_content = "（……！）",
  ui_story_1021_10210401_121_dialog_content = "……",
  ui_story_1021_10210401_122_dialog_content = "收斂……收斂……",
  ui_story_1021_10210401_123_dialog_content = "……大、大人……",
  ui_story_1021_10210401_124_dialog_content = "不用擔心，靠近點吧，我不會傷害你。",
  ui_story_1021_10210401_125_dialog_content = "是……",
  ui_story_1021_10210401_126_dialog_content = "大人……有噁心的光靈在附近……",
  ui_story_1021_10210401_127_dialog_content = "……",
  ui_story_1021_10210401_128_dialog_content = "在下……在下認為，他們或許會影響到大人您修行……",
  ui_story_1021_10210401_129_dialog_content = "這裡，是哪裡？",
  ui_story_1021_10210401_130_dialog_content = "您已經越過那座堡壘了。",
  ui_story_1021_10210401_131_dialog_content = "<color=#FFB400>雪國</color>……走得真是夠遠了……",
  ui_story_1021_10210401_132_dialog_content = "自從它變了模樣，我，沒有回來過。",
  ui_story_1021_10210401_133_dialog_content = "變了模樣……",
  ui_story_1021_10210401_134_dialog_content = "改變，真是一種殘忍的剝奪！",
  ui_story_1021_10210401_135_dialog_content = "大人……",
  ui_story_1021_10210401_136_dialog_content = "提醒得很好……收斂……收斂……",
  ui_story_1021_10210401_137_dialog_content = "<color=#e8d9bb>滴答——滴答——</color>",
  ui_story_1021_10210401_138_dialog_content = "這裡的冰在融化……是那隻暗鬼的暗能導致的……",
  ui_story_1021_10210401_139_dialog_content = "PlayerName……你這次看到了什麼？為什麼這個表情？",
  ui_story_1021_10210401_140_dialog_content = "我看到剛才那隻暗鬼了……",
  ui_story_1021_10210401_141_dialog_content = "想了想，咱們還是一起走吧！",
  ui_story_1021_10210401_142_dialog_content = "你們還好意思回來？",
  ui_story_1021_10210401_143_dialog_content = "PlayerName，前面突然出現很多暗鬼！",
  ui_story_1021_10210401_144_dialog_content = "嘎——！！！",
  ui_story_1021_10210401_145_dialog_content = "卡蓮小心！",
  ui_story_1021_10210401_146_dialog_content = "你們分明是把暗鬼引過來！",
  ui_story_1021_10210401_147_dialog_content = "……小不點，躲到我身後！",
  ui_story_1021_10210401_148_dialog_content = "離得那麼近……是普通的暗能，不是剛剛那種膨脹的感覺……",
  ui_story_1021_10210401_149_dialog_content = "PlayerName，別發呆了！快指揮我戰鬥！",
  ui_story_1021_10210401_150_dialog_content = "嗯！",
  ui_story_1021_10210402_1_dialog_content = "冰解之時，終結。",
  ui_story_1021_10210402_2_dialog_content = "全消滅了！",
  ui_story_1021_10210402_3_dialog_content = "你們沒事吧？",
  ui_story_1021_10210402_4_dialog_content = "女王陛下！您怎麼在這裡？",
  ui_story_1021_10210402_5_dialog_content = "在間歇泉邊，我察覺到妳的光能術。",
  ui_story_1021_10210402_6_dialog_content = "<color=#e8d9bb>不久前……</color>",
  ui_story_1021_10210402_7_dialog_content = "<color=#e8d9bb>汩汩——汩汩——砰！</color>",
  ui_story_1021_10210402_8_dialog_content = "女王陛下，那是……",
  ui_story_1021_10210402_9_dialog_content = "位於邊境線上的<color=#FFB400>間歇泉</color>，停歇多年，如今又開始噴發。真是如同歷史鐘錶般，按時揭露北境的創傷……",
  ui_story_1021_10210402_10_dialog_content = "這些噴出的黑水中混著暗能，毀掉我們的草木、房屋，還有那個無辜的部落……",
  ui_story_1021_10210402_11_dialog_content = "從鏡子中可以看到，近來暗面的能量異動頻繁。女王陛下，您打算怎麼做？",
  ui_story_1021_10210402_12_dialog_content = "下一次噴發結束後，我會深入泉眼對付那頭暗鬼。",
  ui_story_1021_10210402_13_dialog_content = "妳的北國之鏡中蘊含著極盛的光能，我進入後，就拜託妳抑制這些暗能擴散了。",
  ui_story_1021_10210402_14_dialog_content = "是，女王陛下。",
  ui_story_1021_10210402_15_dialog_content = "<color=#e8d9bb>汩汩——汩汩——砰！</color>",
  ui_story_1021_10210402_16_dialog_content = "嗯……？",
  ui_story_1021_10210402_17_dialog_content = "女王陛下，您為何皺眉？",
  ui_story_1021_10210402_18_dialog_content = "她對光能的控制，我再熟悉不過了。",
  ui_story_1021_10210402_19_dialog_content = "不等了，接下來就交給妳了。",
  ui_story_1021_10210402_20_dialog_content = "……是，女王陛下。",
  ui_story_1021_10210402_21_dialog_content = "原來……那些破敗的場景是間歇泉噴發所致……",
  ui_story_1021_10210402_22_dialog_content = "還有大量暗鬼循著暗能而來，傷害了那些弱小的雪狐。你們在洞穴中應該看到不少東西。",
  ui_story_1021_10210402_23_dialog_content = "在下一次噴發前，迅速離開這裡吧。",
  ui_story_1021_10210402_24_dialog_content = "可是女王陛下……我剛剛感應到附近有一隻力量強大的暗鬼……",
  ui_story_1021_10210402_25_dialog_content = "我們本來是為了確認北境據點的事而來，卻意外迫降在附近。",
  ui_story_1021_10210402_26_dialog_content = "接著便見到提亞拉和一群受傷的雪狐在一起，狀況似乎不太好……",
  ui_story_1021_10210402_27_dialog_content = "因為擔心他們的安危，我們一路追到這裡。說起來……那兩個紅油的傢伙呢？！",
  ui_story_1021_10210402_28_dialog_content = "……",
  ui_story_1021_10210402_29_dialog_content = "女王陛下，這裡並非王室守護的範圍……",
  ui_story_1021_10210402_30_dialog_content = "是您派您的護衛提亞拉來這裡調查暗鬼的嗎？",
  ui_story_1021_10210402_31_dialog_content = "「女王的護衛」……這是提亞拉模仿「王室護衛」為自己取的稱號。",
  ui_story_1021_10210402_32_dialog_content = "要成為「王室護衛」，她還需要參透守護北境的意義。這也是身為北境子民永恆的哉問。",
  ui_story_1021_10210402_33_dialog_content = "諾維亞大人！",
  ui_story_1021_10210402_34_dialog_content = "卡蓮，PlayerName閣下。",
  ui_story_1021_10210402_35_dialog_content = "既然你來了，結果我已經知道了。",
  ui_story_1021_10210402_36_dialog_content = "女王陛下早已知曉，提亞拉會離開冬宮，回她的部落去。",
  ui_story_1021_10210402_37_dialog_content = "果然……提亞拉是傳說中雪狐部落的人，甚至……她看起來……",
  ui_story_1021_10210402_38_dialog_content = "提亞拉，是雪狐部落的首領。",
  ui_story_1021_10210402_39_dialog_content = "首領？！",
  ui_story_1021_10210402_40_dialog_content = "難道部落中已經沒有比她更年長的人……",
  ui_story_1021_10210402_41_dialog_content = "……",
  ui_story_1021_10210402_42_dialog_content = "對了，女王陛下……提亞拉託我們轉告您，「她會把腳印打掃乾淨，但不是現在」……",
  ui_story_1021_10210402_43_dialog_content = "她說這句話，是什麼意思呢？",
  ui_story_1021_10210402_44_dialog_content = "永恆的哉問……儘管連我自己都沒有做到……",
  ui_story_1021_10210402_45_dialog_content = "女王陛下，這些年來，您巡邏北境之時從未忽略過這裡。",
  ui_story_1021_10210402_46_dialog_content = "這是我的責任，諾維亞。你帶他們先離開，我去找提亞拉。",
  ui_story_1021_10210402_47_dialog_content = "女王陛下，我已經找到了。",
  ui_story_1021_10210402_48_dialog_content = "嗯。",
  ui_story_1021_10210402_49_dialog_content = "女王陛下……！剛才那股強烈的暗能越來越近了……",
  ui_story_1021_10210402_50_dialog_content = "你說的，是我嗎？",
  ui_story_1021_10210402_51_dialog_content = "……！極光之刃！",
  ui_story_1021_10210402_52_dialog_content = "快到我的光能護罩裡來！",
  ui_story_1021_10210402_53_dialog_content = "妳，是那自詡雪國女王之人？我，錯過了很多啊。",
  ui_story_1021_10210402_54_dialog_content = "……竟然突然出現在這麼近的地方？！",
  ui_story_1021_10210402_55_dialog_content = "你……",
  ui_story_1021_10210402_56_dialog_content = "<color=#FFB400>薩旦</color>會把你的腦子煉成瓊漿，讓你的同胞輪流品嘗。",
  ui_story_1021_10210402_57_dialog_content = "同胞……？你在說什麼？",
  ui_story_1021_10210402_58_dialog_content = "瓊漿……",
  ui_story_1021_10210402_59_dialog_content = "提到瓊漿……",
  ui_story_1021_10210402_60_dialog_content = "好、好難受……",
  ui_story_1021_10210402_61_dialog_content = "（牠施放的暗能，竟有壓倒女王護罩的趨勢……）",
  ui_story_1021_10210402_62_dialog_content = "……極寒之力，加護！",
  ui_story_1021_10210402_63_dialog_content = "女王陛下，我們在這裡只會干擾您的戰鬥。他們就交給我吧。",
  ui_story_1021_10210402_64_dialog_content = "……拜託你了，諾維亞。",
  ui_story_1021_10210402_65_dialog_content = "女王陛下，讓我和您一起戰鬥吧！",
  ui_story_1021_10210402_66_dialog_content = "這是命令。",
  ui_story_1021_10210402_67_dialog_content = "……",
  ui_story_1021_10210402_68_dialog_content = "卡蓮、PlayerName閣下，跟著我山杖的指引，到地面上去吧。",
  ui_story_1021_10210402_69_dialog_content = "你的指引，在哪裡？",
  ui_story_1021_10210402_70_dialog_content = "……",
  ui_story_1021_10210402_71_dialog_content = "諾維亞大人！",
  ui_story_1021_10210402_72_dialog_content = "安心地留在黑暗之中吧。",
  ui_story_1021_10210402_73_dialog_content = "在極光顯現的北境，根本沒有黑暗可言！極光之刃——！",
  ui_story_1021_10210402_74_dialog_content = "妳，與她相比，差得遠了。",
  ui_story_1021_10210402_75_dialog_content = "女王陛下豈是你能評價的！！！",
  ui_story_1021_10210402_76_dialog_content = "<color=#e8d9bb>咻——！</color>",
  ui_story_1021_10210402_77_dialog_content = "提亞拉！回來——！",
  ui_story_1021_10210402_78_dialog_content = "身為女王陛下的護衛，我必須站在您的前面！",
  ui_story_1021_10210402_79_dialog_content = "<color=#e8d9bb>乒——！</color>",
  ui_story_1021_10210402_80_dialog_content = "我不許你動女王陛下一根汗毛！這，是女王護衛賜你的一擊！",
  ui_story_1021_10210402_81_dialog_content = "高傲的頭顱……潔白有勁的下肢……",
  ui_story_1021_10210402_82_dialog_content = "喔，可以告訴我，妳眼中的東西……是什麼嗎？",
  ui_story_1021_10210402_83_dialog_content = "是我殺死你的決心！",
  ui_story_1021_10210402_84_dialog_content = "妳讓我想起……",
  ui_story_1021_10210402_85_dialog_content = "她將黑裙挽在腰間，將長袍割成短衣碎布，好指揮她的士兵以最快的速度衝刺。",
  ui_story_1021_10210402_86_dialog_content = "別眨眼，我手中的長矛——同樣會以最快的速度刺瞎你的雙眼！",
  ui_story_1021_10210402_87_dialog_content = "多迷人的眼神啊，但太遲了……",
  ui_story_1021_10210402_88_dialog_content = "冰解之時，終結！",
  ui_story_1021_10210402_89_dialog_content = "……女王陛下？！",
  ui_story_1021_10210402_90_dialog_content = "這不是妳的戰鬥。現在，順著我綻開的冰錐離開！",
  ui_story_1021_10210402_91_dialog_content = "可是……您呢？",
  ui_story_1021_10210402_92_dialog_content = "我就在你們身後！諾維亞老師，拜託了！",
  ui_story_1021_10210402_93_dialog_content = "山川靈杖，賜我力量！",
  ui_story_1021_10210402_94_dialog_content = "大人……您為什麼不殺了他們？",
  ui_story_1021_10210402_95_dialog_content = "因為從那隻狐狸的眼中，我瞧見了，我的憤怒……",
  ui_story_1021_10210402_96_dialog_content = "憤怒，是懦弱的表現。我，發誓不做憤怒的奴隸。",
  ui_story_1021_10210402_97_dialog_content = "雪國的女王……",
  ui_story_1021_10210402_98_dialog_content = "在我的幽火之中，她們凝結的冰層，都能堅硬不化……",
  ui_story_1021_10210501_1_dialog_content = "……",
  ui_story_1021_10210501_2_dialog_content = "女王陛下，您……為什麼停下來了？",
  ui_story_1021_10210501_3_dialog_content = "在暗能的影響下，路過的冰層都露出了原本的岩層……",
  ui_story_1021_10210501_4_dialog_content = "這裡卻完好無損……而且我能感覺到，這裡有特殊的力量。",
  ui_story_1021_10210501_5_dialog_content = "諾維亞，我知道該怎麼做了。你們接下來注意安全。",
  ui_story_1021_10210501_6_dialog_content = "可是……女王陛下……",
  ui_story_1021_10210501_7_dialog_content = "……請讓我跟著您吧！",
  ui_story_1021_10210501_8_dialog_content = "……",
  ui_story_1021_10210501_9_dialog_content = "妳會出現在這裡，不是為了護衛女王，而是為了保護妳的部落。",
  ui_story_1021_10210501_10_dialog_content = "是、是因為……",
  ui_story_1021_10210501_11_dialog_content = "部落危在旦夕，我們只有祭壇這一個庇護所了……",
  ui_story_1021_10210501_12_dialog_content = "我感受到的，就是祭壇守護的那股力量？",
  ui_story_1021_10210501_13_dialog_content = "女王陛下……您……不能到祭壇去！",
  ui_story_1021_10210501_14_dialog_content = "妳竟然攔在陛下前面？！妳知不知道自己在做什麼，提亞拉？",
  ui_story_1021_10210501_15_dialog_content = "……您要去任何危險的地方，我都會護衛您，但是祭壇……",
  ui_story_1021_10210501_16_dialog_content = "抱歉，提亞拉不能讓您去！",
  ui_story_1021_10210501_17_dialog_content = "這是我身為雪狐部落的首領，對祖先的承諾！",
  ui_story_1021_10210501_18_dialog_content = "我不能去，是因為仇恨嗎？",
  ui_story_1021_10210501_19_dialog_content = "仇恨什麼的……提亞拉其實有疑慮……",
  ui_story_1021_10210501_20_dialog_content = "……",
  ui_story_1021_10210501_21_dialog_content = "若妳對部落和王室之間的嫌隙有疑慮，妳理應自己去確認，直到釐清疑慮為止。",
  ui_story_1021_10210501_22_dialog_content = "但現在，我去祭壇見她，是為了北境。提亞拉，妳相信我。",
  ui_story_1021_10210501_23_dialog_content = "女王陛下！",
  ui_story_1021_10210501_24_dialog_content = "提亞拉，讓她進來。",
  ui_story_1021_10210501_25_dialog_content = "是……誰在說話？",
  ui_story_1021_10210501_26_dialog_content = "長老？！您……可是——",
  ui_story_1021_10210501_27_dialog_content = "無妨。",
  ui_story_1021_10210501_28_dialog_content = "您好些了嗎？",
  ui_story_1021_10210501_29_dialog_content = "勞煩山林大人記掛，老身還活著。",
  ui_story_1021_10210501_30_dialog_content = "是那隻雪狐……卡蓮，是剛才那隻年長的雪狐在說話！",
  ui_story_1021_10210501_31_dialog_content = "你也不用反應這麼大……牠看起來好像恢復了不少……",
  ui_story_1021_10210501_32_dialog_content = "聽這個聲音，或許應該稱呼為「她」。",
  ui_story_1021_10210501_33_dialog_content = "……",
  ui_story_1021_10210501_34_dialog_content = "他們不是北境的人，但他們會尊重長老離開這裡的。",
  ui_story_1021_10210501_35_dialog_content = "不必了，尊重老身之人皆已離世，你們的尊重只是出於虧欠罷了。",
  ui_story_1021_10210501_36_dialog_content = "請對女王陛下的態度放尊重些！",
  ui_story_1021_10210501_37_dialog_content = "卡蓮，退下！",
  ui_story_1021_10210501_38_dialog_content = "……",
  ui_story_1021_10210501_39_dialog_content = "老身的心氣早就散盡了，只是拖著這副舊時代的軀殼，苟延殘喘至今。",
  ui_story_1021_10210501_40_dialog_content = "部落不是沒有尊重過你們的王，但這凋敝的洞穴會替老身回答你們的疑慮。",
  ui_story_1021_10210501_41_dialog_content = "長老，女王陛下真的可以……",
  ui_story_1021_10210501_42_dialog_content = "提亞拉，我多希望妳不必揹負這些。",
  ui_story_1021_10210501_43_dialog_content = "……",
  ui_story_1021_10210501_44_dialog_content = "長老，入侵北境的暗鬼已經逼近這裡了……",
  ui_story_1021_10210501_45_dialog_content = "有「自然之力」的庇護，雖然微弱，但暗鬼是無法接近祭壇的。跟我來吧。",
  ui_story_1021_10210501_46_dialog_content = "……",
  ui_story_1021_10210501_47_dialog_content = "<color=#e8d9bb>嗚嗚……</color>",
  ui_story_1021_10210501_48_dialog_content = "這就是……提亞拉的部落守護的祭壇嗎？",
  ui_story_1021_10210501_49_dialog_content = "沒想到，洞穴裡還有這樣的地方……",
  ui_story_1021_10210501_50_dialog_content = "這是在北境建立之初，部落的祖先所設的祭壇。",
  ui_story_1021_10210501_51_dialog_content = "這裡祭拜的……是什麼？",
  ui_story_1021_10210501_52_dialog_content = "三棵庇護著北境的雪松，以及那些守護過雪松林的先民。",
  ui_story_1021_10210501_53_dialog_content = "三棵雪松……是這三墩樹樁……？",
  ui_story_1021_10210501_54_dialog_content = "有著庇護北境的理想，卻免不了被砍伐的命運，但祂們的力量不會消散。",
  ui_story_1021_10210501_55_dialog_content = "一旦三棵雪松拔地而起，群山都會替祂們讓路。天空記得，於是裂縫永遠讓光透進來。",
  ui_story_1021_10210501_56_dialog_content = "這塊碑上刻的……是古老的文字嗎？",
  ui_story_1021_10210501_57_dialog_content = "上面寫什麼？",
  ui_story_1021_10210501_58_dialog_content = "「祂為替世界帶來和平的國王掃除疲勞。」",
  ui_story_1021_10210501_59_dialog_content = "「祂的承諾，使黑暗化為光明。」",
  ui_story_1021_10210501_60_dialog_content = "「當人們目睹祂，便能獲得安寧和幸福。」",
  ui_story_1021_10210501_61_dialog_content = "這難道是……",
  ui_story_1021_10210501_62_dialog_content = "最早記錄「三棵松樹」傳說的碑文……",
  ui_story_1021_10210501_63_dialog_content = "是北境流傳的那個傳說嗎？",
  ui_story_1021_10210501_64_dialog_content = "第一棵松樹承接了北境的第一任女王，第二棵松樹見證了王室護衛的效忠……",
  ui_story_1021_10210501_65_dialog_content = "而第三棵松樹是女王統治北境的權杖……",
  ui_story_1021_10210501_66_dialog_content = "哈哈哈哈……真是充滿王室後繼者的虛榮……",
  ui_story_1021_10210501_67_dialog_content = "還好太奶奶聽不到了，否則你們一定會被她揍得滿地找牙。",
  ui_story_1021_10210501_68_dialog_content = "但我也能理解，每個王朝都得替自己想一個顯赫的起源。",
  ui_story_1021_10210501_69_dialog_content = "<color=#e8d9bb>啪——！</color>",
  ui_story_1021_10210501_70_dialog_content = "……！！！",
  ui_story_1021_10210501_71_dialog_content = "長老——！",
  ui_story_1021_10210501_72_dialog_content = "抱、抱歉……打擾到你們的儀式了……小不點，妳的聚光燈怎麼回事啦……",
  ui_story_1021_10210501_73_dialog_content = "我……不知道為什麼……",
  ui_story_1021_10210501_74_dialog_content = "原來你們兩個一直躲在附近？！",
  ui_story_1021_10210501_75_dialog_content = "世……外之物……",
  ui_story_1021_10210501_76_dialog_content = "PlayerName，快叫你的朋友把那東西拿走！長老的身體很虛弱！",
  ui_story_1021_10210501_77_dialog_content = "小不點！",
  ui_story_1021_10210501_78_dialog_content = "但是怎麼……不靈了！",
  ui_story_1021_10210501_79_dialog_content = "<color=#e8d9bb>呼呼——呼呼——</color>",
  ui_story_1021_10210501_80_dialog_content = "長槍似乎有力量在湧現……",
  ui_story_1021_10210501_81_dialog_content = "這……到底是……",
  ui_story_1021_10210501_82_dialog_content = "<color=#e8d9bb>呼呼——呼呼——</color>",
  ui_story_1021_10210501_83_dialog_content = "靈杖與祭壇產生了共鳴……",
  ui_story_1021_10210501_84_dialog_content = "……",
  ui_story_1021_10210501_85_dialog_content = "但女王的暮冬之力，似乎才是祂的選擇……",
  ui_story_1021_10210501_86_dialog_content = "……什、麼？",
  ui_story_1021_10210501_87_dialog_content = "我想陪伴在能夠為世界帶來和平的國王左右！",
  ui_story_1021_10210501_88_dialog_content = "（這個聲音是……？）",
  ui_story_1021_10210501_89_dialog_content = "我想把黑暗的世界變得光明！",
  ui_story_1021_10210501_90_dialog_content = "而我啊，只要人們看到我的時候，能感到安寧和幸福就足夠了……",
  ui_story_1021_10210501_91_dialog_content = "哈哈哈……真是兩個狂妄的傢伙啊……",
  ui_story_1021_10210501_92_dialog_content = "你不也是嗎？哈哈……",
  ui_story_1021_10210501_93_dialog_content = "有三道聲音，在祭壇裡迴盪……",
  ui_story_1021_10210501_94_dialog_content = "我也聽到了……",
  ui_story_1021_10210501_95_dialog_content = "這是……神的聲音嗎？",
  ui_story_1021_10210501_96_dialog_content = "……",
  ui_story_1021_10210501_97_dialog_content = "神……認出了妳的力量……",
  ui_story_1021_10210501_98_dialog_content = "我的眼前，正閃過許多畫面……",
  ui_story_1021_10210501_99_dialog_content = "神能認出祂認可之人駕馭的力量……",
  ui_story_1021_10210501_100_dialog_content = "也就是說……",
  ui_story_1021_10210501_101_dialog_content = "你……你們的第一任女王……真的獲得了祂的祝福……",
  ui_story_1021_10210501_102_dialog_content = "這……",
  ui_story_1021_10210501_103_dialog_content = "這讓逝去的先民們，怎麼想得到啊……",
  ui_story_1021_10210501_104_dialog_content = "<color=#e8d9bb>殺——！！！</color>",
  ui_story_1021_10210501_105_dialog_content = "如果你們向前，兌現你們的承諾，北境將有你的安息之地！",
  ui_story_1021_10210501_106_dialog_content = "如果後退，我會割下你們的頭顱掛在松樹上，讓你的後代蒙羞！",
  ui_story_1021_10210501_107_dialog_content = "這……這是誰的意識？我沒有使用感應能力啊……",
  ui_story_1021_10210501_108_dialog_content = "大家在祭壇前的位置並沒有變……",
  ui_story_1021_10210501_109_dialog_content = "這……是北境邊境上曾經那座堅不可摧的古堡……",
  ui_story_1021_10210501_110_dialog_content = "這座古堡現在的位置，該不會……",
  ui_story_1021_10210501_111_dialog_content = "祭壇，就設在古堡的庭院裡。",
  ui_story_1021_10210501_112_dialog_content = "……",
  ui_story_1021_10210501_113_dialog_content = "冰城之人，速速離開。",
  ui_story_1021_10210501_114_dialog_content = "……",
  ui_story_1021_10210501_115_dialog_content = "是……在說我們嗎？",
  ui_story_1021_10210501_116_dialog_content = "我們的裝束……比起他們……",
  ui_story_1021_10210501_117_dialog_content = "你們奪走了祂的力量，從此我們不受庇護。",
  ui_story_1021_10210501_118_dialog_content = "但我們不會忘記對祂的承諾！",
  ui_story_1021_10210501_119_dialog_content = "就算我們最終都會死在這養育我們的雪林中，就算我們的胸上會壓著這片不仁的天空……",
  ui_story_1021_10210501_120_dialog_content = "我，只認我的王。",
  ui_story_1021_10210501_121_dialog_content = "……",
  ui_story_1021_10210501_122_dialog_content = "羅德大人……",
  ui_story_1021_10210501_123_dialog_content = "哈根！去把王賜我的戰甲拿來，我要用它獎勵衝鋒的弟兄！",
  ui_story_1021_10210501_124_dialog_content = "羅德大人……請您披上那副戰甲吧。",
  ui_story_1021_10210501_125_dialog_content = "這不是我的最後一仗，哈根！有你做我的戰甲，足矣！",
  ui_story_1021_10210501_126_dialog_content = "……",
  ui_story_1021_10210501_127_dialog_content = "走了，哈根。",
  ui_story_1021_10210501_128_dialog_content = "我一直在您身後，羅德大人……",
  ui_story_1021_10210501_129_dialog_content = "……",
  ui_story_1021_10210501_130_dialog_content = "強壯威嚴，卻體恤部下的羅德大人。我們都以為他會成為下一個北境之王。",
  ui_story_1021_10210501_131_dialog_content = "弟兄們！為了吾王！為了北境！殺——！",
  ui_story_1021_10210501_132_dialog_content = "殺——！",
  ui_story_1021_10210501_133_dialog_content = "殺——！",
  ui_story_1021_10210501_134_dialog_content = "<color=#e8d9bb>呼呼——呼——</color>",
  ui_story_1021_10210501_135_dialog_content = "消失了……這就是「自然之力」嗎……",
  ui_story_1021_10210501_136_dialog_content = "……",
  ui_story_1021_10210501_137_dialog_content = "原來長老曾經是那位羅德大人的護衛？",
  ui_story_1021_10210501_138_dialog_content = "他是妳的祖先，也是妳從小引以為傲的族人。",
  ui_story_1021_10210501_139_dialog_content = "如今部落淪落成這模樣，我無顏面對他。",
  ui_story_1021_10210501_140_dialog_content = "您臉上的疤痕……就是當時的暗鬼害的……？",
  ui_story_1021_10210501_141_dialog_content = "不必為那些殘酷的歲月感到遺憾，提亞拉。",
  ui_story_1021_10210501_142_dialog_content = "妳只看到我們受的傷，卻沒看到我們把暗鬼打退後，一起在雪松林中燃起篝火慶祝的日子。",
  ui_story_1021_10210501_143_dialog_content = "這些事……您為什麼不告訴我？",
  ui_story_1021_10210501_144_dialog_content = "如果妳得知這些，一定會離開冬宮，像妳和祖先發誓的那樣守在這裡。",
  ui_story_1021_10210501_145_dialog_content = "妳的天性我瞭解，即使妳成了女王的護衛，身上也流淌著我們先民的血。",
  ui_story_1021_10210501_146_dialog_content = "但時至今日，我們一族早已凋零，知道這些，已經沒有意義了。",
  ui_story_1021_10210501_147_dialog_content = "而且，妳已經選擇了妳的王。",
  ui_story_1021_10210501_148_dialog_content = "……",
  ui_story_1021_10210501_149_dialog_content = "而妳效忠的對象，竟然真的獲得神的認可。妳還有什麼理由留在部落，守著我們？",
  ui_story_1021_10210501_150_dialog_content = "……",
  ui_story_1021_10210501_151_dialog_content = "但……羅德大人說的「奪走了祂的力量」，是指什麼？",
  ui_story_1021_10210501_152_dialog_content = "是燈塔……",
  ui_story_1021_10210501_153_dialog_content = "燈塔……？北境的燈塔？",
  ui_story_1021_10210501_154_dialog_content = "「當人們目睹祂，便能獲得安寧和幸福。」",
  ui_story_1021_10210501_155_dialog_content = "……",
  ui_story_1021_10210501_156_dialog_content = "為了驅逐暗鬼，照亮整個北境……",
  ui_story_1021_10210501_157_dialog_content = "王室的先輩獲得了一棵蘊含「自然之力」的雪松。",
  ui_story_1021_10210501_158_dialog_content = "雪松折斷自己，做成承接「火種」的支架，那便是北境最早的燈塔。",
  ui_story_1021_10210501_159_dialog_content = "自此，大片北境被點亮……受雪松庇護的雪松林，卻逐漸失去了抵抗暗鬼的力量。",
  ui_story_1021_10210501_160_dialog_content = "……",
  ui_story_1021_10210501_161_dialog_content = "這些，就是妳剛才看到的畫面嗎？",
  ui_story_1021_10210501_162_dialog_content = "是的。祂認可王室，決定成為北境的燈塔。",
  ui_story_1021_10210501_163_dialog_content = "只有這樣，祂才能實現庇護北境的理想……",
  ui_story_1021_10210501_164_dialog_content = "原來是這樣……",
  ui_story_1021_10210501_165_dialog_content = "這麼說，王室並沒有奪走祂的力量，是嗎？",
  ui_story_1021_10210501_166_dialog_content = "……",
  ui_story_1021_10210501_167_dialog_content = "……",
  ui_story_1021_10210501_168_dialog_content = "神在成為北境的燈塔之前，曾在此庇佑我們。那時，祂的力量還在。",
  ui_story_1021_10210501_169_dialog_content = "先民建立了祭壇，每日祈禱，將他們的希望和信仰獻給神。",
  ui_story_1021_10210501_170_dialog_content = "他們在寒冷的冬日裡點亮松油燈，守護著部落的安寧和繁榮。",
  ui_story_1021_10210501_171_dialog_content = "然而，歲月的流逝帶來不測的變故。部落陷入困境，疾病蔓延、莊稼凋零……",
  ui_story_1021_10210501_172_dialog_content = "雪松被砍斷後，仇恨和絕望籠罩在部落上空。",
  ui_story_1021_10210501_173_dialog_content = "後來，在王的帶領下，我們日夜在祭壇祈禱，盼著神的眷顧。",
  ui_story_1021_10210501_174_dialog_content = "然而暗鬼肆虐，我一生中見證過無數先民誕生、離去，然而神並沒有回應我們……",
  ui_story_1021_10210501_175_dialog_content = "甚至默認了，我們一族都會在仇恨中走向生命終點。",
  ui_story_1021_10210501_176_dialog_content = "這就是我們一族的故事。在妳誕生之前，我也曾以為這會是我的結局……",
  ui_story_1021_10210501_177_dialog_content = "長老……",
  ui_story_1021_10210501_178_dialog_content = "我已經太老了，提亞拉，老到只能靠回憶這些故事來度日。",
  ui_story_1021_10210501_179_dialog_content = "但妳決定好妳要做的事，並用一生去銘記了嗎？",
  ui_story_1021_10210501_180_dialog_content = "我想要保護部落，長老……我也想要幫助女王陛下。",
  ui_story_1021_10210501_181_dialog_content = "如果部落和王室之間有隔閡，您可以把一切都告訴我，我願意努力去瞭解和彌補。",
  ui_story_1021_10210501_182_dialog_content = "現在，為了北境的安寧，我們可以先信任彼此，一起對抗那些入侵的暗鬼嗎？",
  ui_story_1021_10210501_183_dialog_content = "……",
  ui_story_1021_10210501_184_dialog_content = "長老，我的記憶裡一直有個關於「原始淨域」的說法。",
  ui_story_1021_10210501_185_dialog_content = "直到剛才，我在閃過的畫面中瞥見一眼……",
  ui_story_1021_10210501_186_dialog_content = "北境燈塔最初的軀幹，也就是紮根在這裡的雪松，因浸潤於古老的靈力而堅韌無比。",
  ui_story_1021_10210501_187_dialog_content = "祭壇周圍有著「原始淨域」，對嗎？",
  ui_story_1021_10210501_188_dialog_content = "如果要喚醒「原始淨域」，為北境提供庇護，您知道該怎麼做嗎？",
  ui_story_1021_10210501_189_dialog_content = "喚醒「原始淨域」，呵呵……",
  ui_story_1021_10210501_190_dialog_content = "除非妳讓北境的燈塔熄滅，讓這截斷的樹根之上重新長出三棵雪松。",
  ui_story_1021_10210501_191_dialog_content = "……",
  ui_story_1021_10210501_192_dialog_content = "除了燈塔，另外兩棵雪松也要回歸祭壇，對嗎？",
  ui_story_1021_10210501_193_dialog_content = "沒錯。",
  ui_story_1021_10210501_194_dialog_content = "長老？您說的……是真的嗎？",
  ui_story_1021_10210501_195_dialog_content = "……",
  ui_story_1021_10210501_196_dialog_content = "北境的燈塔怎麼能熄滅呢……如果燈塔熄滅了，那冬宮和城鎮上的人不就——",
  ui_story_1021_10210501_197_dialog_content = "妳不是總把「身為女王陛下的護衛」這句話掛在嘴邊嗎？",
  ui_story_1021_10210501_198_dialog_content = "妳的王要喚醒「原始淨域」，彌補王室對部落的虧欠，妳難道不想幫她嗎？",
  ui_story_1021_10210501_199_dialog_content = "提亞拉想！提亞拉永遠都會追隨女王陛下！但……",
  ui_story_1021_10210501_200_dialog_content = "提亞拉，抬起頭來看著我。",
  ui_story_1021_10210501_201_dialog_content = "……",
  ui_story_1021_10210501_202_dialog_content = "相信我，我接受了那股力量，我知道該怎麼還。",
  ui_story_1021_10210501_203_dialog_content = "身為我的護衛，我希望妳和我一起去喚醒「原始淨域」，保護北境。",
  ui_story_1021_10210501_204_dialog_content = "另外的兩棵雪松，就由妳去找回來，好嗎？",
  ui_story_1021_10210501_205_dialog_content = "女王陛下……",
  ui_story_1021_10210501_206_dialog_content = "冰雪覆蓋之處，都是我要用生命去保護的北境。這是我對我的先民做出的承諾。",
  ui_story_1021_10210501_207_dialog_content = "燈塔尚未照到這裡，就算毀滅你們家園的是暗鬼，但是沒有保護好你們的是我，伯利恆。",
  ui_story_1021_10210501_208_dialog_content = "……",
  ui_story_1021_10210501_209_dialog_content = "諾維亞，你知道雪松在什麼地方，對嗎？",
  ui_story_1021_10210501_210_dialog_content = "知道，女王陛下。請放心去對付那隻暗鬼，大家和我一起走吧。",
  ui_story_1021_10210501_211_dialog_content = "……",
  ui_story_1021_10210501_212_dialog_content = "長老，那我先隨諾維亞大人離開了……",
  ui_story_1021_10210501_213_dialog_content = "循著妳的燈塔，去兌現妳對妳的王做出的承諾吧。",
  ui_story_1021_10210501_214_dialog_content = "嗯！",
  ui_story_1021_10210601_1_dialog_content = "女王獨自去對付暗鬼了……我們真的什麼忙也幫不上嗎？",
  ui_story_1021_10210601_2_dialog_content = "當年女王陛下救起我時，賦予了我特殊的力量，但我卻沒站在她的身邊和她一起戰鬥……",
  ui_story_1021_10210601_3_dialog_content = "你們在洞穴裡和那隻暗鬼對抗的時候，就應該知道牠的力量如何。",
  ui_story_1021_10210601_4_dialog_content = "而提亞拉妳該找回的東西，就是在幫助女王陛下戰鬥。",
  ui_story_1021_10210601_5_dialog_content = "這間歇泉噴出的暗能一直在侵蝕北境的雪原……",
  ui_story_1021_10210601_6_dialog_content = "女王陛下之所以去祭壇找長老，就是為了找到淨化污染的方法，也就是喚醒「原始淨域」。",
  ui_story_1021_10210601_7_dialog_content = "諾維亞大人，另外的兩棵雪松在什麼地方呢？",
  ui_story_1021_10210601_8_dialog_content = "除了那座崖邊的燈塔外，還有兩棵松樹在別的地方保護著北境。",
  ui_story_1021_10210601_9_dialog_content = "一直保護著……？",
  ui_story_1021_10210601_10_dialog_content = "是的。其中一棵在冬宮，一棵在妳出生的地方。",
  ui_story_1021_10210601_11_dialog_content = "但是經過歲月的改變，雪松已經不再是容易辨認的樣子。妳或許得從「三棵松樹」的傳說去尋找答案。",
  ui_story_1021_10210601_12_dialog_content = "雪松中的「自然之力」雖已沉寂，但在靠近祂們的時候，女王賜給妳的力量會與之共鳴。",
  ui_story_1021_10210601_13_dialog_content = "我明白了，諾維亞大人！",
  ui_story_1021_10210601_14_dialog_content = "無論是伯利恆女王還是長老，她們都深知「守護」的意義重於自己的生命。",
  ui_story_1021_10210601_15_dialog_content = "提亞拉，希望妳身為北境的護衛，能夠肩負起「守護」的使命。",
  ui_story_1021_10210601_16_dialog_content = "嗯，交給我吧，我一定不會讓大家失望！",
  ui_story_1021_10210601_17_dialog_content = "提亞拉，等等！我和妳一起去！",
  ui_story_1021_10210601_18_dialog_content = "你？",
  ui_story_1021_10210601_19_dialog_content = "我也可以幫忙！",
  ui_story_1021_10210601_20_dialog_content = "可是你們跟得上我嗎？還是說，你們願意被我扛在肩上？",
  ui_story_1021_10210601_21_dialog_content = "扛在肩上……？",
  ui_story_1021_10210601_22_dialog_content = "……如果能幫上妳的忙，扛在肩上也沒關係！",
  ui_story_1021_10210601_23_dialog_content = "PlayerName閣下的感應能力，或許能幫上忙。",
  ui_story_1021_10210601_24_dialog_content = "這樣啊……那我知道了，諾維亞大人！這邊就拜託你們了。",
  ui_story_1021_10210601_25_dialog_content = "我和PlayerName很快就回來！",
  ui_story_1021_10210601_26_dialog_content = "欸、欸——！",
  ui_story_1021_10210601_27_dialog_content = "還真是一眨眼就不見了……",
  ui_story_1021_10210601_28_dialog_content = "這些夾雜著暗能的黑水，正在往王室的方向蔓延……",
  ui_story_1021_10210601_29_dialog_content = "看來，就算是擁有極盛光能的娜席里絲，也控制不住了。",
  ui_story_1021_10210601_30_dialog_content = "希望提亞拉他們能把雪松找回來，這樣，部落才有延續下去的可能……",
  ui_story_1021_10210601_31_dialog_content = "諾維亞大人，也請把我當作北境的護衛吧。我也想為保護北境出一份力！",
  ui_story_1021_10210601_32_dialog_content = "<color=#e8d9bb>森林的另一邊</color>",
  ui_story_1021_10210601_33_dialog_content = "唉，自己回紅油是不可能了，不如和PlayerName他們一起把危機解決掉還現實一點呢。",
  ui_story_1021_10210601_34_dialog_content = "你是認真的嗎？",
  ui_story_1021_10210601_35_dialog_content = "說來說去，也是為了紅油啊。",
  ui_story_1021_10210601_36_dialog_content = "在伊芙的事情上，PlayerName也幫了醒山不少忙。",
  ui_story_1021_10210601_37_dialog_content = "就衝著這件事，無論PlayerName何時陷入危險，醒山那小子都會去拉他一把。",
  ui_story_1021_10210601_38_dialog_content = "知道PlayerName他們的聯合探索，醒山只是在裝糊塗罷了。",
  ui_story_1021_10210601_39_dialog_content = "我也就賣他個人情，替紅油表明這份心意吧。",
  ui_story_1021_10210601_40_dialog_content = "羅伊哥真夠意思！怪不得醒山大哥都說要我們向你多學習呢，學到了！",
  ui_story_1021_10210601_41_dialog_content = "走吧，順著那黑水的流向，我們把附近的暗鬼給解決掉！",
  ui_story_1021_10210601_42_dialog_content = "<color=#e8d9bb>北境邊緣</color>",
  ui_story_1021_10210601_43_dialog_content = "（日蝕語）大人……不能再往前了……",
  ui_story_1021_10210601_44_dialog_content = "（日蝕語）據說那邊有一座邪惡的燈塔，會把我們的身體撕得粉碎。",
  ui_story_1021_10210601_45_dialog_content = "（日蝕語）冰凍如同瘙癢，火山如吹熱風。邪惡的燈塔，不過如此。",
  ui_story_1021_10210601_46_dialog_content = "<color=#e8d9bb>嚶嚶嚶——！</color>",
  ui_story_1021_10210601_47_dialog_content = "（日蝕語）是那些白色的畜牲。",
  ui_story_1021_10210601_48_dialog_content = "（日蝕語）這麼多年過去了，城堡和護衛早已消逝，牠們卻還在。",
  ui_story_1021_10210601_49_dialog_content = "（日蝕語）北境，真是個令人嚮往的地方。",
  ui_story_1021_10210601_50_dialog_content = "冰凍之刃——！",
  ui_story_1021_10210601_51_dialog_content = "擅入北境者，就在冰雪中終結吧！",
  ui_story_1021_10210601_52_dialog_content = "放過了妳，妳卻窮追不捨。",
  ui_story_1021_10210601_53_dialog_content = "是想用冰牆……再次將我等冰封起來？",
  ui_story_1021_10210601_54_dialog_content = "……關於<color=#FFB400>那場戰爭</color>，你知道些什麼？",
  ui_story_1021_10210601_55_dialog_content = "看來，妳的年紀，還很小。",
  ui_story_1021_10210601_56_dialog_content = "（日蝕語）去，陪她玩玩吧。",
  ui_story_1021_10210601_57_dialog_content = "（日蝕語）是，大人！",
  ui_story_1021_10210700_1_dialog_content = "……呂王陛下要塔塔，無論如活也要趕來告訴過位大人。",
  ui_story_1021_10210700_2_dialog_content = "速情就素、就素卓樣……",
  ui_story_1021_10210700_3_dialog_content = "還未踏入暗面，聯合探索就已經開始了。",
  ui_story_1021_10210700_4_dialog_content = "既然如此，我們無論如何也要去把北境的據點守住。薇薇安，我們立刻出發去北境。",
  ui_story_1021_10210700_5_dialog_content = "是，大元帥。",
  ui_story_1021_10210700_6_dialog_content = "白蘭，隨我啟程。",
  ui_story_1021_10210700_7_dialog_content = "是，城主大人。",
  ui_story_1021_10210700_8_dialog_content = "會長，我們也去嗎？",
  ui_story_1021_10210700_9_dialog_content = "這種場合，影鎮怎麼能缺席？",
  ui_story_1021_10210700_10_dialog_content = "那可是海拔超高的北境啊……",
  ui_story_1021_10210700_11_dialog_content = "北境確實不比影鎮，貝菲爾小姐，請搭乘我們的飛行器一起去吧。",
  ui_story_1021_10210700_12_dialog_content = "嗯！",
  ui_story_1021_10210700_13_dialog_content = "提、提亞拉……可以讓我下來走一段路嗎？！我的腰實在受不了了……",
  ui_story_1021_10210700_14_dialog_content = "<color=#e8d9bb>咚——</color>",
  ui_story_1021_10210700_15_dialog_content = "妳還真的把我扛在肩上……而且跑了那麼久！",
  ui_story_1021_10210700_16_dialog_content = "你說我可以這麼做，所以我這麼做了。莫非你們外鄉人都喜歡說違心之論？",
  ui_story_1021_10210700_17_dialog_content = "也不是……我只是以為妳是隨便說說……",
  ui_story_1021_10210700_18_dialog_content = "我現在，終於對妳是雪狐首領這件事有體會了！",
  ui_story_1021_10210700_19_dialog_content = "呼——！終於能看到冬宮了……",
  ui_story_1021_10210700_20_dialog_content = "嗷——！",
  ui_story_1021_10210700_21_dialog_content = "這是在……",
  ui_story_1021_10210700_22_dialog_content = "<color=#e8d9bb>嗷——</color>",
  ui_story_1021_10210700_23_dialog_content = "竟然有回應……！",
  ui_story_1021_10210700_24_dialog_content = "這是我和狐兒傳遞訊號的溝通方式。",
  ui_story_1021_10210700_25_dialog_content = "……你們剛才說了些什麼？",
  ui_story_1021_10210700_26_dialog_content = "我告訴狐兒，這附近沒有受到黑水影響。而狐兒說，會轉告諾維亞大人。",
  ui_story_1021_10210700_27_dialog_content = "只要這樣喊一聲，就能傳遞那麼多訊息了嗎？",
  ui_story_1021_10210700_28_dialog_content = "你也可以試試看！",
  ui_story_1021_10210700_29_option_content = "我？算了吧……",
  ui_story_1021_10210700_30_dialog_content = "你會覺得這很可笑嗎？",
  ui_story_1021_10210700_31_dialog_content = "不、不會呀……妳為什麼這樣想？",
  ui_story_1021_10210700_32_dialog_content = "剛來冬宮的時候，有幾個王室護衛就常常戲仿我……",
  ui_story_1021_10210700_33_dialog_content = "一開始我以為他們只是覺得我吵，但後來發現，問題似乎不在聲音大小。",
  ui_story_1021_10210700_34_dialog_content = "管他的，可笑就可笑吧！後來我在冬宮中努力改掉了這個習慣……",
  ui_story_1021_10210700_35_dialog_content = "但每當我獨自巡林或夜深人靜的時候，還是會像這樣和狐兒們交流。",
  ui_story_1021_10210700_36_dialog_content = "這根本就沒什麼可笑的！妳聽好了——",
  ui_story_1021_10210700_37_dialog_content = "嗚啊啊啊——！",
  ui_story_1021_10210700_38_option_content = "嗚啊啊啊——",
  ui_story_1021_10210700_39_dialog_content = "怎麼樣？",
  ui_story_1021_10210700_40_dialog_content = "……",
  ui_story_1021_10210700_41_dialog_content = "妳這表情……有那麼難聽嗎？",
  ui_story_1021_10210700_42_dialog_content = "我在想，你是想表達「飯菜香」……「非常想」……還是「風吹雪」呢……？",
  ui_story_1021_10210700_43_dialog_content = "你再叫一聲看看。",
  ui_story_1021_10210700_44_dialog_content = "啊……還是算了吧。",
  ui_story_1021_10210700_45_dialog_content = "像這樣，把頭抬起來，頸部伸直。",
  ui_story_1021_10210700_46_dialog_content = "把頭抬起來……頸部伸直……",
  ui_story_1021_10210700_47_dialog_content = "然後張大嘴巴，把心裡面想說的話，一口氣全部呼出來！",
  ui_story_1021_10210700_48_dialog_content = "嗷——！",
  ui_story_1021_10210700_49_dialog_content = "<color=#e8d9bb>嗷——</color>",
  ui_story_1021_10210700_50_dialog_content = "怎麼樣？我說得沒錯吧？",
  ui_story_1021_10210700_51_dialog_content = "哇！雖然不知道傳達得準不準確，但聽到回音的時候真的很幸福啊！",
  ui_story_1021_10210700_52_dialog_content = "聽到你的祝福，狐兒們也會感到幸福的。",
  ui_story_1021_10210700_53_dialog_content = "好啦，看樣子休息夠了，接下來我會一口氣將你扛到冬宮去！",
  ui_story_1021_10210700_54_dialog_content = "喂——！好歹、好歹讓我看著前面啊！",
  ui_story_1021_10210700_55_dialog_content = "喔，這不是札莉雅小姐嗎？今天妳也採集到許多礦石了呀。",
  ui_story_1021_10210700_56_dialog_content = "這是女王陛下交給我的第一份工作，當然要好好完成！",
  ui_story_1021_10210700_57_dialog_content = "聽說札莉雅小姐有強大的光能術，做起事來一定輕鬆不少！",
  ui_story_1021_10210700_58_dialog_content = "不是這樣的……我現在還是會常常不小心把自己凍起來……",
  ui_story_1021_10210700_59_dialog_content = "還好只是局部啦！我還要多多練習才是！再見，我要去冬宮見女王陛下啦。",
  ui_story_1021_10210700_60_dialog_content = "唔……諾爾聽說女王陛下不在冬宮呢……",
  ui_story_1021_10210700_61_dialog_content = "<color=#e8d9bb>咻——！</color>",
  ui_story_1021_10210700_62_dialog_content = "哎——！",
  ui_story_1021_10210700_63_dialog_content = "PlayerName……？還有提亞拉……他們怎麼在這？",
  ui_story_1021_10210700_64_dialog_content = "所有的角落都去過了，妳的長矛好像都沒有發生變化啊……",
  ui_story_1021_10210700_65_dialog_content = "古老的力量果然因時間太久而沉寂了嗎……",
  ui_story_1021_10210700_66_dialog_content = "諾維亞說，要從傳說之中尋找線索。妳現在有什麼想法嗎？",
  ui_story_1021_10210700_67_dialog_content = "冬宮的雪松，或許對應著第一個傳說：「祂為替世界帶來和平的國王掃除疲勞。」",
  ui_story_1021_10210700_68_dialog_content = "女王陛下平常都是怎麼掃除疲勞的？",
  ui_story_1021_10210700_69_dialog_content = "她在冬宮的時間不多，通常只在她的寢宮、後花園，以及餐廳停留。",
  ui_story_1021_10210700_70_dialog_content = "那看來女王消除疲勞的方式也和我差不多，都是睡覺、打盹，還有吃美食。",
  ui_story_1021_10210700_71_dialog_content = "但女王陛下，似乎不常做你說的這些事……",
  ui_story_1021_10210700_72_dialog_content = "你們這麼急著找女王陛下，是有什麼事嗎？",
  ui_story_1021_10210700_73_dialog_content = "……！妳的這些礦石……？",
  ui_story_1021_10210700_74_dialog_content = "欸欸欸——這些可不是從妳的家鄉附近帶來的喔！",
  ui_story_1021_10210700_75_dialog_content = "札莉雅，妳怎麼來啦？",
  ui_story_1021_10210700_76_dialog_content = "你們剛剛都沒看見我嗎？我看到你們跑得這麼快，一定是找女王有急事。",
  ui_story_1021_10210700_77_dialog_content = "可是聽說女王陛下不在冬宮，所以趕來告訴你們一聲。",
  ui_story_1021_10210700_78_dialog_content = "我們已經知道了。",
  ui_story_1021_10210700_79_dialog_content = "那你們還在這做什麼……？",
  ui_story_1021_10210700_80_dialog_content = "找東西。",
  ui_story_1021_10210700_81_dialog_content = "找東西……你們說說看，或許我可以幫上忙。",
  ui_story_1021_10210700_82_dialog_content = "我們在找一樣……能為女王陛下「掃除疲勞」的東西。",
  ui_story_1021_10210700_83_dialog_content = "聽起來怎麼很像……孩子根據傳說玩的某種冒險遊戲啊……",
  ui_story_1021_10210700_84_dialog_content = "這種遊戲很常見嗎？",
  ui_story_1021_10210700_85_dialog_content = "當然，女王的花園裡常常有小孩在玩這種遊戲。",
  ui_story_1021_10210700_86_dialog_content = "女王的宮殿，小孩子竟然能隨意進來玩嗎？",
  ui_story_1021_10210700_87_dialog_content = "女王陛下從來沒有把冬宮當作她自己的東西。",
  ui_story_1021_10210700_88_dialog_content = "她是個勤懇的女王，說起來，我從來沒見她休息過……",
  ui_story_1021_10210700_89_dialog_content = "這裡的椅子啊、長凳啊，甚至是花園裡的搖籃椅那麼漂亮，她卻從來不坐。",
  ui_story_1021_10210700_90_dialog_content = "那，「掃除疲勞」的會不會是……提亞拉，快過來看看！",
  ui_story_1021_10210700_91_dialog_content = "……",
  ui_story_1021_10210700_92_dialog_content = "咦？妳的長矛，在發光呢！",
  ui_story_1021_10210700_93_dialog_content = "啊……果然！",
  ui_story_1021_10210700_94_dialog_content = "這是女王陛下的王座……",
  ui_story_1021_10210700_95_dialog_content = "這就是你們在找的東西嗎？",
  ui_story_1021_10210700_96_dialog_content = "說到能為國王掃除疲勞的東西，王座還挺貼切的。而且有國王的象徵……",
  ui_story_1021_10210700_97_dialog_content = "原來那棵雪松成了女王的椅子啊……但我從來沒見女王陛下坐在上面過……",
  ui_story_1021_10210700_98_dialog_content = "難道她知道這張椅子和雪松有關，所以從來不在這裡休息嗎……",
  ui_story_1021_10210700_99_dialog_content = "……",
  ui_story_1021_10210700_100_dialog_content = "椅子好像在變化……！",
  ui_story_1021_10210700_101_dialog_content = "這是那些宣誓效忠的部落送來的，專屬於您——北境女王的御座。",
  ui_story_1021_10210700_102_dialog_content = "從今以後，您將坐在這個位置上接見您的子民。",
  ui_story_1021_10210700_103_dialog_content = "走遍北境的雪地和山林，需要花多久時間？",
  ui_story_1021_10210700_104_dialog_content = "這個……女王陛下，您為什麼這麼問？",
  ui_story_1021_10210700_105_dialog_content = "坐在那個冰冷的王位上是無法守護北境的。我要用行動來保衛冰雪覆蓋的每一寸土地。",
  ui_story_1021_10210700_106_dialog_content = "雪花落下來，您走過的路就已經成為一條新的路了。",
  ui_story_1021_10210700_107_dialog_content = "春天來臨之後，山林便與去年不同。",
  ui_story_1021_10210700_108_dialog_content = "那就不停地走，不停地巡邏，直至讓每一寸北境的土地都受燈塔庇護為止。",
  ui_story_1021_10210700_109_dialog_content = "剛剛那是……",
  ui_story_1021_10210700_110_dialog_content = "難道是女王陛下剛成為女王時的場景……",
  ui_story_1021_10210700_111_dialog_content = "不使用感應能力就能看到……應該是更早的事情……",
  ui_story_1021_10210700_112_dialog_content = "宣誓效忠的部落送來了松木製成的椅子，但女王並沒有坐上去。",
  ui_story_1021_10210700_113_dialog_content = "而伯利恆女王繼承了她的意志，一生都在不停奔走……",
  ui_story_1021_10210700_114_dialog_content = "快看，快看！",
  ui_story_1021_10210700_115_dialog_content = "王座竟然變成了一棵小小的松枝……",
  ui_story_1021_10210700_116_dialog_content = "看來這就是那棵雪松了。",
  ui_story_1021_10210700_117_dialog_content = "好神奇的力量啊……！",
  ui_story_1021_10210700_118_dialog_content = "有了雪松，就能幫助女王陛下了……",
  ui_story_1021_10210700_119_dialog_content = "嗯，那麼接下來，就是妳生活的地方了！",
  ui_story_1021_10210700_120_dialog_content = "我們走！",
  ui_story_1021_10210700_121_dialog_content = "喂——！下次還有這樣的傳說遊戲，記得帶上我啊……！",
  ui_story_1021_10210700_122_dialog_content = "<color=#e8d9bb>從此，北境女王沒有御座。</color>",
  ui_story_1021_10210801_1_dialog_content = "<color=#e8d9bb>嘩嘩嘩——</color>",
  ui_story_1021_10210801_2_dialog_content = "突然變天了……",
  ui_story_1021_10210801_3_dialog_content = "燈塔被暴風雪擋住了，不知道女王陛下那邊怎麼樣了……",
  ui_story_1021_10210801_4_dialog_content = "關於妳家鄉的雪松，妳有什麼想法嗎？",
  ui_story_1021_10210801_5_dialog_content = "最後一個傳說：「祂的承諾，使黑暗變成了光明」。",
  ui_story_1021_10210801_6_dialog_content = "記憶中，太奶奶好像和我講過……",
  ui_story_1021_10210801_7_dialog_content = "北境曾經有過一個黑暗時代，是神許下承諾，最終帶給北境光明。",
  ui_story_1021_10210801_8_dialog_content = "一個「承諾」，這也太抽象了吧……",
  ui_story_1021_10210801_9_dialog_content = "但是當有人記得這個承諾並去守護它的時候，承諾就真實存在。",
  ui_story_1021_10210801_10_dialog_content = "這也是太奶奶告訴我的話……",
  ui_story_1021_10210801_11_dialog_content = "我想到辦法了……",
  ui_story_1021_10210801_12_dialog_content = "妳的太奶奶一定是記得這個「承諾」，並且守護著它。我或許能從妳的記憶裡找到線索……",
  ui_story_1021_10210801_13_dialog_content = "真的嗎？",
  ui_story_1021_10210801_14_dialog_content = "但太奶奶她……已經去世很久了，而且關於她的記憶，我不知道能不能像你說的那樣……",
  ui_story_1021_10210801_15_dialog_content = "為什麼？",
  ui_story_1021_10210801_16_dialog_content = "……你看了就知道了。",
  ui_story_1021_10210801_17_dialog_content = "嗯，別擔心，讓我試試看吧！",
  ui_story_1021_10210801_18_option_content = "感應——連接——",
  ui_story_1021_10210801_19_dialog_content = "好了，不要再說了！",
  ui_story_1021_10210801_20_dialog_content = "我都快死的人了，還不能多說幾句嗎？",
  ui_story_1021_10210801_21_dialog_content = "太奶奶……您不陪提亞拉玩了嗎？",
  ui_story_1021_10210801_22_dialog_content = "提亞拉乖喔……答應太奶奶，快點長大好不好……？",
  ui_story_1021_10210801_23_dialog_content = "快點長大呀，提亞拉……",
  ui_story_1021_10210801_24_dialog_content = "為什麼妳來得那麼晚……晚到太奶奶無法看著妳長大了……",
  ui_story_1021_10210801_25_dialog_content = "再過幾年，我就要去見那些日日夜夜惦記的人了……",
  ui_story_1021_10210801_26_dialog_content = "提亞拉，妳要記得太奶奶……記得部落……記得……",
  ui_story_1021_10210801_27_dialog_content = "別再說這些讓大家難過的話了。沒有人會記得，沒有人會留下來。",
  ui_story_1021_10210801_28_dialog_content = "提亞拉，去那邊和狐兒們玩吧。",
  ui_story_1021_10210801_29_dialog_content = "嗚哇……這是提亞拉的尾巴……",
  ui_story_1021_10210801_30_dialog_content = "這是……讓我猜猜，不許提醒我喔！",
  ui_story_1021_10210801_31_dialog_content = "以後別再帶提亞拉到這裡來了。",
  ui_story_1021_10210801_32_dialog_content = "提亞拉是部落的孩子。她必須記住部落的輝煌，記住她是接受過先民的祝福才來到這世上。",
  ui_story_1021_10210801_33_dialog_content = "我會讓她繼承首領的位置，誕下北境的護衛……",
  ui_story_1021_10210801_34_dialog_content = "那個承諾，就由她去見證了。",
  ui_story_1021_10210801_35_dialog_content = "曾經，各大部落齊心北上，如今唯有我們雪狐部落留下來，守護著這片土地。",
  ui_story_1021_10210801_36_dialog_content = "我們等不到祂的承諾了。或許那塊<color=#FFB400>石板</color>，早已被神遺忘。",
  ui_story_1021_10210801_37_dialog_content = "老狐狸，妳要是敢跟提亞拉這麼講，我可不會放過妳。",
  ui_story_1021_10210801_38_dialog_content = "神不會遺忘。有提亞拉在，那塊石板會一直傳遞下去。",
  ui_story_1021_10210801_39_dialog_content = "……在提亞拉得知這些之前，我會先毀了它。",
  ui_story_1021_10210801_40_dialog_content = "妳比誰都珍視那塊石板。妳不會這麼做的。",
  ui_story_1021_10210801_41_dialog_content = "我別無選擇。",
  ui_story_1021_10210801_42_dialog_content = "不要讓提亞拉承受這些了好嗎？妳看她現在的模樣，就讓她像普通的孩子一樣快樂地長大，不好嗎？",
  ui_story_1021_10210801_43_dialog_content = "她該守護的是部落！不是那冰冷的王宮！",
  ui_story_1021_10210801_44_dialog_content = "王室奪走祂的力量，不但沒有回報，還將拼命保護邊疆的護衛與入侵者一同冰封在古堡中……",
  ui_story_1021_10210801_45_dialog_content = "上千年了……這些冰凍可曾有過變化……？",
  ui_story_1021_10210801_46_dialog_content = "一旦得知那些殘酷的歲月，提亞拉還會像現在這樣快樂嗎？",
  ui_story_1021_10210801_47_dialog_content = "承諾、守護……我現在只覺得是種殘忍。",
  ui_story_1021_10210801_48_dialog_content = "而這種殘忍，我已經在妳身上看到了，從妳誕生……到妳……",
  ui_story_1021_10210801_49_dialog_content = "不必說了。提亞拉會成長得更加強大，足以抵抗這種殘忍，像她那些強大的祖先一樣。",
  ui_story_1021_10210801_50_dialog_content = "……",
  ui_story_1021_10210801_51_dialog_content = "太奶奶——狐兒說妳是凶巴巴的老太婆！哈哈哈……這樣好癢呀！",
  ui_story_1021_10210801_52_dialog_content = "哇嗚……提亞拉才不認輸呢！",
  ui_story_1021_10210801_53_dialog_content = "……",
  ui_story_1021_10210801_54_dialog_content = "怎麼了？你怎麼這副表情？",
  ui_story_1021_10210801_55_dialog_content = "……你看到她們的爭論了？",
  ui_story_1021_10210801_56_dialog_content = "嗯。看到她們在妳繼承部落首領這件事情上意見相左。",
  ui_story_1021_10210801_57_dialog_content = "我才知道，原來長老一直不希望妳成為部落的首領……",
  ui_story_1021_10210801_58_dialog_content = "是啊……你別看長老不歡迎大家，其實她連我都不歡迎回到部落……",
  ui_story_1021_10210801_59_dialog_content = "或許長老早就知道，部落會在我接任首領後變成這副樣子。",
  ui_story_1021_10210801_60_dialog_content = "長老擔心的不是這個。她擔心的是妳今後再也不快樂，擔心妳會像太奶奶那樣，在仇恨中度過一生。",
  ui_story_1021_10210801_61_dialog_content = "快樂……？",
  ui_story_1021_10210801_62_dialog_content = "所以她才希望我切斷和部落的聯繫，總是要我去履行女王護衛的職責……",
  ui_story_1021_10210801_63_dialog_content = "但她卻獨自守著這些祕密……",
  ui_story_1021_10210801_64_dialog_content = "小時候不准我到祭壇去……",
  ui_story_1021_10210801_65_dialog_content = "從不講傳說故事給我聽……",
  ui_story_1021_10210801_66_dialog_content = "部落遇到危機，她卻想趕我走……",
  ui_story_1021_10210801_67_dialog_content = "儘管長老深愛著部落，但她，更愛妳啊……",
  ui_story_1021_10210801_68_dialog_content = "……",
  ui_story_1021_10210801_69_dialog_content = "所以我，提亞拉，更不會違背身為雪狐首領的承諾……！",
  ui_story_1021_10210801_70_dialog_content = "我相信女王陛下，只要喚醒「原始淨域」，部落一定會得救！",
  ui_story_1021_10210801_71_dialog_content = "那時候，長老就不會再趕我走了！",
  ui_story_1021_10210801_72_dialog_content = "嗯，提亞拉一定辦得到！",
  ui_story_1021_10210801_73_dialog_content = "不過說了半天……我的記憶中並沒有雪松的線索，對嗎？",
  ui_story_1021_10210801_74_dialog_content = "不，他們有聊到一塊石板……似乎記錄著神對雪狐部落的承諾？",
  ui_story_1021_10210801_75_dialog_content = "石板……",
  ui_story_1021_10210801_76_dialog_content = "太奶奶說，長老比任何人都珍視那塊石板。",
  ui_story_1021_10210801_77_dialog_content = "不過，那塊石板可能已經被長老毀了……",
  ui_story_1021_10210801_78_dialog_content = "……",
  ui_story_1021_10210801_79_dialog_content = "妳再想想，長老珍視的石板，她應該經常去看。",
  ui_story_1021_10210801_80_dialog_content = "長老常去的地方，洞穴、祭壇、山脊……還有……",
  ui_story_1021_10210801_81_dialog_content = "會不會是……？",
  ui_story_1021_10210801_82_dialog_content = "在我離開部落之前，長老總是在這附近久久地注視著燈塔，一待就是一整天。",
  ui_story_1021_10210801_83_dialog_content = "但這裡除了樹木之外，好像沒有其他東西了……",
  ui_story_1021_10210801_84_dialog_content = "……誰？哪裡跑？！",
  ui_story_1021_10210801_85_dialog_content = "小妹妹……又被妳逮到了啊……",
  ui_story_1021_10210801_86_dialog_content = "怎麼是你們？",
  ui_story_1021_10210801_87_dialog_content = "好心幫忙清除附近的暗鬼，首領大人竟然這樣報答救命恩人啊？",
  ui_story_1021_10210801_88_dialog_content = "鬼鬼祟祟的傢伙怎可能安什麼好心，該不會又偷了寶石吧！",
  ui_story_1021_10210801_89_dialog_content = "能從那洞穴裡活著出來就已經不錯了，真的顧不上什麼寶石。",
  ui_story_1021_10210801_90_dialog_content = "咳咳……羅伊哥，你就不能好好說話嗎？",
  ui_story_1021_10210801_91_dialog_content = "你之前不是說，紅油扳手也是聯合探索的一員，不可能放著同伴的生命安全不顧！",
  ui_story_1021_10210801_92_dialog_content = "所以，從洞穴出來後找不到你們，我們只好在這裡把冒出來的暗鬼通通解決了！",
  ui_story_1021_10210801_93_dialog_content = "我們過來的路上，還真的一隻暗鬼都沒見到……真是謝謝你們了！",
  ui_story_1021_10210801_94_dialog_content = "那是因為……這裡剛好是燈塔能照到的最遠界限啊！",
  ui_story_1021_10210801_95_dialog_content = "……這、這誰知道啊？連個界碑都沒有，我們剛剛不是白忙一場了？",
  ui_story_1021_10210801_96_dialog_content = "羅伊哥，我剛剛好像確實有看到界碑……",
  ui_story_1021_10210801_97_dialog_content = "提亞拉！難道界碑……",
  ui_story_1021_10210801_98_dialog_content = "是石板！",
  ui_story_1021_10210801_99_dialog_content = "快用妳的長矛和界碑共鳴看看！",
  ui_story_1021_10210801_100_dialog_content = "自然之力，聚力冰尖之上！",
  ui_story_1021_10210801_101_dialog_content = "剛剛要是有這麼亮，也不至於白忙一場啊……",
  ui_story_1021_10210801_102_dialog_content = "這些油亮的文字……應該是取自雪松的油。",
  ui_story_1021_10210801_103_dialog_content = "太奶奶曾說，我們的松油燈就是整個北境的眼睛。",
  ui_story_1021_10210801_104_dialog_content = "如果是夜裡，一定非常亮吧……",
  ui_story_1021_10210801_105_dialog_content = "沒想到，雪松竟然成了記錄燈塔邊界的界碑。",
  ui_story_1021_10210801_106_dialog_content = "噢！這是怎麼回事……",
  ui_story_1021_10210801_107_dialog_content = "偉大的北境護衛們，戰爭結束了，燈塔也已經建成。",
  ui_story_1021_10210801_108_dialog_content = "那座冰封的古堡將佇立於斯，紀念犧牲在邊境線上的戰士、嚇阻敵人，也提醒著我。",
  ui_story_1021_10210801_109_dialog_content = "我在此向你們承諾：",
  ui_story_1021_10210801_110_dialog_content = "我站立的地方，不是黑暗與光明的交界。燈塔，一定會照到這裡！",
  ui_story_1021_10210801_111_dialog_content = "你們的家人將在廣袤的北境安居樂業。",
  ui_story_1021_10210801_112_dialog_content = "願山川見證我的誓言，賜燈塔力量，庇佑我們北境。",
  ui_story_1021_10210801_113_dialog_content = "也請你們，與神靈一同見證我的承諾。",
  ui_story_1021_10210801_114_dialog_content = "我是北境的第一任女王，我的子孫後代一定會成為保護北境的最後一名護衛！",
  ui_story_1021_10210801_115_dialog_content = "我願守衛北境，願我的子孫後代成為保護北境的最後一名護衛！",
  ui_story_1021_10210801_116_dialog_content = "北境的第一任女王，真是氣宇非凡啊……！",
  ui_story_1021_10210801_117_dialog_content = "原來石板上的「承諾」，不是神對妳的部落許下的……",
  ui_story_1021_10210801_118_dialog_content = "而是當年的女王和邊境的護衛互相許下的承諾……",
  ui_story_1021_10210801_119_dialog_content = "所以是我的祖先一直守在這裡，而女王的承諾遲遲沒有兌現，後來部落漸漸衰敗……",
  ui_story_1021_10210801_120_dialog_content = "於是對王室產生了仇恨……",
  ui_story_1021_10210801_121_dialog_content = "要讓燈塔照到部落，這似乎是一件無法完成的事情啊……",
  ui_story_1021_10210801_122_dialog_content = "是啊……但這些年來，女王陛下總是不辭辛勞地到邊境巡邏。",
  ui_story_1021_10210801_123_dialog_content = "我相信……無論是部落還是王室，沒有人背棄承諾。",
  ui_story_1021_10210801_124_dialog_content = "而現在，她們都把喚醒「原始淨域」，保衛北境的重任交給了我……",
  ui_story_1021_10210801_125_dialog_content = "這就是諾維亞大人說過，希望我去明白的使命！",
  ui_story_1021_10210801_126_dialog_content = "和妳一起尋找雪松，我似乎才重新開始認識北境。",
  ui_story_1021_10210801_127_dialog_content = "石板和女王的座椅一樣，似乎要變成最初的模樣了……",
  ui_story_1021_10210801_128_dialog_content = "這就是第二棵雪松啦。",
  ui_story_1021_10210801_129_dialog_content = "至於第三棵，不知道女王陛下會不會真的讓北境燈塔熄滅……",
  ui_story_1021_10210801_130_dialog_content = "我現在對女王陛下已經沒有疑慮了。無論她要做什麼，我都會陪在她身邊幫她一起完成！",
  ui_story_1021_10210801_131_dialog_content = "我們快把雪松帶回去吧！",
  ui_story_1021_10210801_132_dialog_content = "嗯！",
  ui_story_1021_10210801_133_dialog_content = "啊，還有……謝謝你們啦！",
  ui_story_1021_10210801_134_dialog_content = "哈哈，別客氣。",
  ui_story_1021_10210801_135_dialog_content = "羅伊哥，既然找到他們了，就跟上去幫幫忙吧。",
  ui_story_1021_10210801_136_dialog_content = "唉，真拿妳沒辦法，走吧。",
  ui_story_1021_10210801_137_dialog_content = "<color=#e8d9bb>從此，部落與王室間的承諾石板不再。</color>",
  ui_story_1021_10210801_138_dialog_content = "長老！諾維亞大人！我們回來啦！還帶了——",
  ui_story_1021_10210801_139_dialog_content = "祭壇上那是……？！",
  ui_story_1021_10210801_140_dialog_content = "那是女王陛下從身體裡分出的火種之力，正在凝結成「燈芯」。",
  ui_story_1021_10210801_141_dialog_content = "「燈芯」……那懸崖邊的燈塔會熄滅嗎？",
  ui_story_1021_10210801_142_dialog_content = "不會，女王早已成為北境的燈塔，這是她的生命能量。",
  ui_story_1021_10210801_143_dialog_content = "生命能量……陛下的身體會因此變得虛弱嗎？",
  ui_story_1021_10210801_144_dialog_content = "即使虛弱，她也已將暗鬼逼退到北境邊緣……",
  ui_story_1021_10210801_145_dialog_content = "女王陛下竟然……",
  ui_story_1021_10210801_146_dialog_content = "她承諾的燈塔，雖然遲到了那麼多年，但有了你們的幫忙，馬上就要建成了。",
  ui_story_1021_10210801_147_dialog_content = "我現在……該怎麼做？",
  ui_story_1021_10210801_148_dialog_content = "把你們帶回來的松枝，放在祭壇上，將長矛之中的力量也一併歸還給神靈。",
  ui_story_1021_10210801_149_dialog_content = "跟著我一起，向神靈祈禱……",
  ui_story_1021_10210801_150_dialog_content = "雪狐部落的長老，北境戰神羅德大人的護衛，哈根，祈求神靈的幫助。",
  ui_story_1021_10210801_151_dialog_content = "雪狐部落的首領，北境女王伯利恆的護衛，提亞拉，祈求神靈的幫助！",
  ui_story_1021_10210801_152_dialog_content = "北境女王兌現了她的承諾，「燈芯」是取自您的力量，松枝也是取自您的力量。",
  ui_story_1021_10210801_153_dialog_content = "請您收回它們，用孕育萬物的力量澆灌它們生長。",
  ui_story_1021_10210801_154_dialog_content = "願您，賜予滄桑的北境長久庇護——",
  ui_story_1021_10210801_155_dialog_content = "山川靈杖，賜我力量！",
  ui_story_1021_10210801_156_dialog_content = "<color=#e8d9bb>呼呼——呼呼——！</color>",
  ui_story_1021_10210801_157_dialog_content = "……！！！",
  ui_story_1021_10210801_158_dialog_content = "三個樹樁，瞬間就長成了這麼一棵……參天巨樹！",
  ui_story_1021_10210801_159_dialog_content = "這就是「原始淨域」的力量嗎……？",
  ui_story_1021_10210801_160_dialog_content = "……",
  ui_story_1021_10210801_161_dialog_content = "長矛中的力量沒有被收回……我反而感覺有一股更強的力量在湧入！",
  ui_story_1021_10210801_162_dialog_content = "這些像雷光一樣閃爍的東西，是從雪松之中流過來的能量嗎……",
  ui_story_1021_10210801_163_dialog_content = "……",
  ui_story_1021_10210801_164_dialog_content = "在世界屋脊之上，祖先發現一條溫潤的溪流。",
  ui_story_1021_10210801_165_dialog_content = "這條溪流，如同天賜的恩澤，常年在冰封的北境中蜿蜒流淌，也流入艾斯特拉的心臟深處……",
  ui_story_1021_10210801_166_dialog_content = "這便是「原始淨域」的起源。它滋養了茂密的雪松林，而我們的先民則在這片森林中生根發芽。",
  ui_story_1021_10210801_167_dialog_content = "在「原始淨域」的庇護下，雪松與「燈芯」的力量匯聚，共同鑄成這座嶄新的「燈塔」。",
  ui_story_1021_10210801_168_dialog_content = "它的光會穿透漫漫冬夜，越過連綿雪峰，驅散黑暗，照亮生靈熱愛的土地。",
  ui_story_1021_10210801_169_dialog_content = "而現在，提亞拉，妳已經是一名獲神靈認可的北境護衛了。",
  ui_story_1021_10210801_170_dialog_content = "神靈認可我……因此賜予我力量！",
  ui_story_1021_10210801_171_dialog_content = "這冰長矛在我手中，彷彿是一根熾熱的火炬！",
  ui_story_1021_10210801_172_dialog_content = "從此，妳的肩上承載了神靈賦予妳的力量和使命……",
  ui_story_1021_10210801_173_dialog_content = "提亞拉，用妳的勇氣和智慧，好好守護我們的北境吧。",
  ui_story_1021_10210802_1_dialog_content = "那束從雪松林深處升騰而上的光，難道是另一座遠古遺跡……",
  ui_story_1021_10210802_2_dialog_content = "等等，那束光現在出現……或許是一道信號！",
  ui_story_1021_10210802_3_dialog_content = "傳說中燈塔的功能是指引和守護。北境是否有著太多燈塔？",
  ui_story_1021_10210802_4_dialog_content = "這些燈塔如何分佈？",
  ui_story_1021_10210802_5_dialog_content = "它們的燈光又如何影響這片土地……",
  ui_story_1021_10210802_6_dialog_content = "<color=#e8d9bb>某個隱祕的角落</color>",
  ui_story_1021_10210802_7_dialog_content = "北境果然蘊藏著那股力量。",
  ui_story_1021_10210802_8_dialog_content = "水脈已經復甦，很快就會匯入大海了。",
  ui_story_1021_10210802_9_dialog_content = "維多利亞大人一定會為我們的見證感到高興。",
  ui_story_1021_10210802_10_dialog_content = "我們也差不多該啟程了。",
  ui_story_1021_10210802_11_dialog_content = "<color=#e8d9bb>啟光飛行器上</color>",
  ui_story_1021_10210802_12_dialog_content = "……彷彿太陽從雪山上升起……我還從未見過這種光芒。",
  ui_story_1021_10210802_13_dialog_content = "往那個方向，加速前進！",
  ui_story_1021_10210802_14_dialog_content = "是！",
  ui_story_1021_10210901_1_dialog_content = "看來……新的「燈塔」完成了。",
  ui_story_1021_10210901_2_dialog_content = "女王陛下，您沒事了嗎？！剛才您虛弱的樣子讓我……",
  ui_story_1021_10210901_3_dialog_content = "沒事了，卡蓮。無論是我還是北境，現在都有了更強的護罩。",
  ui_story_1021_10210901_4_dialog_content = "嘎啊——！",
  ui_story_1021_10210901_5_dialog_content = "（日蝕語）大人……痛……",
  ui_story_1021_10210901_6_dialog_content = "（日蝕語）痛……！",
  ui_story_1021_10210901_7_dialog_content = "（日蝕語）這感覺……我想起來了……",
  ui_story_1021_10210901_8_dialog_content = "（日蝕語）那個雪天，一名騎在麋鹿背上的女子……",
  ui_story_1021_10210901_9_dialog_content = "（日蝕語）我，都想起來了。",
  ui_story_1021_10210901_10_dialog_content = "（日蝕語）這趟修行，值得。",
  ui_story_1021_10210901_11_dialog_content = "聚力冰尖之上！",
  ui_story_1021_10210901_12_dialog_content = "……",
  ui_story_1021_10210901_13_dialog_content = "嘎啊——！",
  ui_story_1021_10210901_14_dialog_content = "女王陛下、卡蓮，抱歉我來晚了！",
  ui_story_1021_10210901_15_dialog_content = "提亞拉，妳剛才的攻擊真是精準有力！",
  ui_story_1021_10210901_16_dialog_content = "妳的長矛，還有妳的力量，似乎比以往更強了！",
  ui_story_1021_10210901_17_dialog_content = "長老說這是獲得神靈認可的證明。現在，我終於成為合格的女王護衛了！",
  ui_story_1021_10210901_18_dialog_content = "是北境的護衛！",
  ui_story_1021_10210901_19_dialog_content = "嗯，北境的護衛！",
  ui_story_1021_10210901_20_dialog_content = "我能感受到妳的蛻變和成長，提亞拉。做得很好。",
  ui_story_1021_10210901_21_dialog_content = "也謝謝妳，願意和我一起築起新的燈塔。",
  ui_story_1021_10210901_22_dialog_content = "女王陛下！我剛剛得知冬宮中那個王座的故事，還有王室和部落間的承諾……還有……",
  ui_story_1021_10210901_23_dialog_content = "我還有好多好多話想對您說！但是、但是我現在最想說的是：",
  ui_story_1021_10210901_24_dialog_content = "從今以後，提亞拉跟定您了！提亞拉不會再讓您獨自戰鬥了！",
  ui_story_1021_10210901_25_dialog_content = "「融水取萬物於山川，草木引生機至福地」……",
  ui_story_1021_10210901_26_dialog_content = "準備受死吧，暗鬼！",
  ui_story_1021_10210901_27_dialog_content = "等等，提亞拉！",
  ui_story_1021_10210901_28_dialog_content = "女王陛下……？",
  ui_story_1021_10210901_29_dialog_content = "你不僅知道那場戰爭，為什麼……連北境的祝福都知道？",
  ui_story_1021_10210901_30_dialog_content = "那個時候，雪國一片死寂。",
  ui_story_1021_10210901_31_dialog_content = "天上是深黑的太陽，祂離我們是那樣的近……",
  ui_story_1021_10210901_32_dialog_content = "但是那名女子出現了……",
  ui_story_1021_10210901_33_dialog_content = "……",
  ui_story_1021_10210901_34_dialog_content = "你見過……北境的第一任女王？",
  ui_story_1021_10210901_35_dialog_content = "她攥著一束光，將這穹頂震碎，將我們與祂，永遠隔開。",
  ui_story_1021_10210901_36_dialog_content = "再看一眼，這深黑的太陽，我這樣想著。",
  ui_story_1021_10210901_37_dialog_content = "但她手中的東西，卻將我的雙眼，撕裂。",
  ui_story_1021_10210901_38_dialog_content = "這趟修行，讓我想起了所有……",
  ui_story_1021_10210901_39_dialog_content = "留在我雙瞳中最後的火光，不是憤怒……",
  ui_story_1021_10210901_40_dialog_content = "那本不是憤怒！",
  ui_story_1021_10210901_41_dialog_content = "是那束光，搖曳著，將我的世界染成憤怒的顏色！",
  ui_story_1021_10210901_42_dialog_content = "（日蝕語）我不怕冰凍，也不怕火焰……",
  ui_story_1021_10210901_43_dialog_content = "（日蝕語）但那搖曳著向我靠近的白色……究竟是什麼……",
  ui_story_1021_10210901_44_dialog_content = "是燈塔——！是女王的燈塔——！",
  ui_story_1021_10210901_45_dialog_content = "女王帶著燈塔來救我們啦！",
  ui_story_1021_10210901_46_dialog_content = "（日蝕語）燈塔……",
  ui_story_1021_10210901_47_dialog_content = "嘎啊——！",
  ui_story_1021_10210901_48_dialog_content = "全部，我全部都想起來了。",
  ui_story_1021_10210901_49_dialog_content = "全部……",
  ui_story_1021_10210901_50_dialog_content = "修行結束了。我，放過你們。逃命去吧。",
  ui_story_1021_10210901_51_dialog_content = "……",
  ui_story_1021_10210901_52_dialog_content = "但我提亞拉，不打算放過你！",
  ui_story_1021_10210901_53_dialog_content = "我要把你對部落和狐兒們造成的傷害，十倍奉還給你！",
  ui_story_1021_10210901_54_dialog_content = "不逃……那就到這裡來吧。",
  ui_story_1021_10210901_55_dialog_content = "提亞拉！",
  ui_story_1021_10210901_56_dialog_content = "聚力冰尖之上！",
  ui_story_1021_10210901_57_dialog_content = "<color=#e8d9bb>轟隆隆——！</color>",
  ui_story_1021_10210901_58_dialog_content = "暗、暗鬼……我不會放過你……咳……咳咳……",
  ui_story_1021_10210901_59_dialog_content = "提亞拉！",
  ui_story_1021_10210901_60_dialog_content = "小心！牠想把妳引入暗面！",
  ui_story_1021_10210901_61_dialog_content = "剛剛那是……砲彈嗎？",
  ui_story_1021_10210901_62_dialog_content = "PlayerName，看天上——",
  ui_story_1021_10210901_63_dialog_content = "沒有打中目標，但PlayerName他們似乎要進入暗鬼的領地了。",
  ui_story_1021_10210901_64_dialog_content = "下降高度，掩護他們！",
  ui_story_1021_10210901_65_dialog_content = "收到，大元帥！",
  ui_story_1021_10210901_66_dialog_content = "會長，據點……在駁火！我們——",
  ui_story_1021_10210901_67_dialog_content = "啟光和白夜城的軍隊會支援他們，別去添亂了。",
  ui_story_1021_10210901_68_dialog_content = "我們去甲板，把聯合探索的旗幟掛上去！",
  ui_story_1021_10210901_69_dialog_content = "整隊完畢，可以隨時降落！",
  ui_story_1021_10210901_70_dialog_content = "沿著邊境線剷除暗鬼，撐起那些北境護衛的位置，主戰場是他們年輕人的。",
  ui_story_1021_10210901_71_dialog_content = "是，城主大人！",
  ui_story_1021_10210901_72_dialog_content = "是啟光的飛行器……",
  ui_story_1021_10210901_73_dialog_content = "還有白夜城的飛空艇……大家都在關注著這裡。",
  ui_story_1021_10210901_74_dialog_content = "但那暗鬼挑釁著提亞拉，似乎要引我們到那邊去……",
  ui_story_1021_10210901_75_dialog_content = "提亞拉好快啊！她已經快越過前面這堵「牆」了！",
  ui_story_1021_10210901_76_dialog_content = "越過這道「牆」，我們便無法回頭。",
  ui_story_1021_10210901_77_dialog_content = "但燈塔的光已經照到那邊了，跟著來吧。",
  ui_story_1021_10210901_78_dialog_content = "我會用冰製成道路助你們攀上山脊。我們和提亞拉一起，逼到那暗鬼退出北境為止！",
  ui_story_1021_10210901_79_dialog_content = "嗯！",
  ui_story_1021_10210901_80_dialog_content = "提亞拉——！",
  ui_story_1021_10210901_81_dialog_content = "別再把我們甩在後面啦，這是我們共同的戰鬥！",
  ui_story_1021_10210901_82_dialog_content = "女王陛下，大家……！還有你們倆？",
  ui_story_1021_10210901_83_dialog_content = "別忘了，聯合探索也有紅油的份！",
  ui_story_1021_10210901_84_dialog_content = "嗯，按照你們的說法，探險開始之前，一定要有個激動人心的集結儀式。",
  ui_story_1021_10210901_85_dialog_content = "集結什麼的我不知道……",
  ui_story_1021_10210901_86_dialog_content = "但北境護衛提亞拉向你們發誓，我一定會把這些暗鬼通通趕出去！",
  ui_story_1021_10210901_87_dialog_content = "不知不覺中，光靈的聯合探索已經邁出這一步了。",
  ui_story_1021_10210901_88_dialog_content = "那邊，是暗鬼自稱的「領地」。但那些以殺戮為生的暗鬼，不該有生存的地盤！",
  ui_story_1021_10210901_89_dialog_content = "我們，一定要順著燈塔的光，把牠們趕盡殺絕！",
  ui_story_1021_10210901_90_dialog_content = "女王陛下竟然會說出這樣的話來……",
  ui_story_1021_10210901_91_dialog_content = "有提亞拉這樣的護衛，我也會不自覺地受她感染。",
  ui_story_1021_10210901_92_dialog_content = "願你們互相激勵，心中惦記彼此，惦記北境和光靈的未來……",
  ui_story_1021_10210901_93_dialog_content = "等你們成為彼此的燈塔之時，你們的力量將超越面臨的恐懼。",
  ui_story_1021_10210901_94_dialog_content = "……！",
  ui_story_1021_10210901_95_dialog_content = "喔！快看那碎裂的石頭，那暗鬼似乎還不肯離開呢！",
  ui_story_1021_10210901_96_dialog_content = "那就去消滅他！我會跟你們一起，向著暗面前進！",
  ui_story_1021_10210901_97_dialog_content = "前進！",
  ui_story_1021_10210902_1_dialog_content = "不錯，遠遠超出了我的預期……",
  ui_story_1021_10210902_2_dialog_content = "為了達到境界，我必須克制自己。",
  ui_story_1021_10210902_3_dialog_content = "我要走了，但我有句話要送給你們……",
  ui_story_1021_10210902_4_dialog_content = "嗅著黑暗的氣味，來到我們的世界吧……",
  ui_story_1021_10210902_5_dialog_content = "你們前人的屍骨堆積成山，在你們經過的每一個地方呼喊著你們的名字。",
  ui_story_1021_10210902_6_dialog_content = "我，王的護衛，阿伊讓，在永夜等著你們。",
  ui_story_1021_10210902_7_dialog_content = "如果是你們，我很期待……",
  ui_story_1021_10211001_1_dialog_content = "暗鬼退出北境，燈塔的光源也恢復穩定了。",
  ui_story_1021_10211001_2_dialog_content = "支援的隊伍在回程了嗎？",
  ui_story_1021_10211001_3_dialog_content = "啟光的參謀長還在松霜谷口等著空裔他們。",
  ui_story_1021_10211001_4_dialog_content = "據點尚未建設，暗面探索卻已經開始了，還是以這種方式開始的。",
  ui_story_1021_10211001_5_dialog_content = "有了那座新的燈塔，他們在深入暗面之前也能暫時有個庇護了。",
  ui_story_1021_10211001_6_dialog_content = "這麼說，他們會從這裡出發？",
  ui_story_1021_10211001_7_dialog_content = "是的，所以據點的事情也要加快了。",
  ui_story_1021_10211001_8_dialog_content = "女王陛下，我們是來向您道別的，我們準備回去了。",
  ui_story_1021_10211001_9_dialog_content = "卡蓮等不及要回去上飛行課了。",
  ui_story_1021_10211001_10_dialog_content = "才、才不是……其實是還有很多事情要準備……",
  ui_story_1021_10211001_11_dialog_content = "嗯，那就早點回去吧。這一次也感謝你們，幫助我們築起新的燈塔。",
  ui_story_1021_10211001_12_dialog_content = "這也是提亞拉的功勞！對了，她人呢？",
  ui_story_1021_10211001_13_dialog_content = "她還有其他的工作。",
  ui_story_1021_10211001_14_dialog_content = "請替我轉告聯合探索隊的各位，不用擔心據點建設的事，我很快會帶來好消息。",
  ui_story_1021_10211001_15_dialog_content = "城主大人說，他會派白夜衛隊來幫助建設據點，但是可能要晚兩天。",
  ui_story_1021_10211001_16_dialog_content = "外面就有兩個現成的機械專家，今天就可以開工啦！",
  ui_story_1021_10211001_17_dialog_content = "有道理！他們早就在打寶石的主意啦。被他們拿走的那些，就當作預付的報酬吧。",
  ui_story_1021_10211001_18_dialog_content = "你們倆一定要那麼大聲地幫我們安排工作嗎……",
  ui_story_1021_10211001_19_dialog_content = "寶石早就不知道掉哪去了……要是打白工，我們會被醒山大哥罵的。",
  ui_story_1021_10211001_20_dialog_content = "而且，我還是想在暖呼呼的紅油當後勤。北境雖然都是寶，但我再也不想來了。",
  ui_story_1021_10211001_21_dialog_content = "那說好的一起探索呢？",
  ui_story_1021_10211001_22_dialog_content = "看情況吧，大叔我可是很忙的。",
  ui_story_1021_10211001_23_dialog_content = "我早已預見卻又遙不可及的這一天，現在真的要來臨了。",
  ui_story_1021_10211001_24_dialog_content = "過去，他們各有陣營，也各有立場，聯合探索多是飄渺的政治宣言。",
  ui_story_1021_10211001_25_dialog_content = "但現在，眾人像夥伴一樣，為照顧彼此挺身而出……",
  ui_story_1021_10211001_26_dialog_content = "希望等他們走進暗面，這些昔日的夥伴會成為他們黑暗中的依靠。",
  ui_story_1021_10211001_27_dialog_content = "<color=#e8d9bb>松霜谷口附近</color>",
  ui_story_1021_10211001_28_dialog_content = "PlayerName！等等！",
  ui_story_1021_10211001_29_dialog_content = "提亞拉，妳怎麼來啦？",
  ui_story_1021_10211001_30_dialog_content = "我有一些禮物要送給你們，但我不小心……把和我一起運送禮物的人甩在後面了，嘿嘿！",
  ui_story_1021_10211001_31_dialog_content = "總覺得再這樣下去，就沒人願意和提亞拉一起玩了……",
  ui_story_1021_10211001_32_dialog_content = "對了，妳接下來有什麼打算嗎？妳知道我們很想邀請妳一起去接下來的探索。",
  ui_story_1021_10211001_33_dialog_content = "妳的機敏與勇氣，一定能在危險之中幫上大忙！",
  ui_story_1021_10211001_34_dialog_content = "謝謝你們的邀請，但是你們忘了，我心裡早就有更重要的東西！",
  ui_story_1021_10211001_35_dialog_content = "這次和你們一起經歷這些事情，我也瞭解了我還沒盡到的責任。",
  ui_story_1021_10211001_36_dialog_content = "我會繼續努力，成為一名有擔當的北境護衛！",
  ui_story_1021_10211001_37_dialog_content = "所以我決定了！我要留在北境，傳承雪狐部落先輩和歷代女王的事蹟！",
  ui_story_1021_10211001_38_dialog_content = "太奶奶沒跟我說過的那些故事，我會請長老告訴我！",
  ui_story_1021_10211001_39_dialog_content = "這是一件很有意義的事情！想要記得這些事蹟的還有我，妳別忘了，我也是見證者喔。",
  ui_story_1021_10211001_40_dialog_content = "如果得知了新的故事，記得寫信告訴我！",
  ui_story_1021_10211001_41_dialog_content = "喔！用那個——",
  ui_story_1021_10211001_42_dialog_content = "嗷——！",
  ui_story_1021_10211001_43_dialog_content = "嗷——！",
  ui_story_1021_10211001_44_dialog_content = "我推著這麼重的東西，你們卻在這裡嗚嗚叫！",
  ui_story_1021_10211001_45_dialog_content = "這位是……？",
  ui_story_1021_10211001_46_dialog_content = "這是我在北境認識的朋友，札莉雅。",
  ui_story_1021_10211001_47_dialog_content = "原來和提亞拉一起運送禮物的人就是妳呀……",
  ui_story_1021_10211001_48_dialog_content = "提亞拉真是個飛毛腿，一轉眼就跑得不見人影了！",
  ui_story_1021_10211001_49_dialog_content = "畢竟是跟提亞拉一起，被她甩在後面也很正常啦……",
  ui_story_1021_10211001_50_dialog_content = "才不是呢，明明是提亞拉還在生我的氣！",
  ui_story_1021_10211001_51_dialog_content = "哼！誰叫妳對狐兒牠們放出一堆冰晶呀！",
  ui_story_1021_10211001_52_dialog_content = "是妳沒先提醒我，去妳的家鄉做客，要被雪白的狐狸……輪流舔手背……！",
  ui_story_1021_10211001_53_dialog_content = "北境可沒有這種傳統！",
  ui_story_1021_10211001_54_dialog_content = "……",
  ui_story_1021_10211001_55_dialog_content = "那些發光的東西，就是禮物嗎？",
  ui_story_1021_10211001_56_dialog_content = "這難道是光能礦石……？",
  ui_story_1021_10211001_57_dialog_content = "答對啦！這可是我費了九牛二虎之力，才從提亞拉的家鄉運過來的！",
  ui_story_1021_10211001_58_dialog_content = "這麼貴重的禮物，我不能收啊！",
  ui_story_1021_10211001_59_dialog_content = "為什麼不收？我今天可是雪狐首領提亞拉，特地要將這些石頭送給我們部落的恩人……",
  ui_story_1021_10211001_60_dialog_content = "這也是長老的意思。",
  ui_story_1021_10211001_61_dialog_content = "女王陛下也說了，這些礦石可以照亮暗面的路，還能驅散暗鬼，你們探索的時候用得到。",
  ui_story_1021_10211001_62_dialog_content = "但這些礦石也照亮了北境的邊境，讓暗鬼不敢靠近……",
  ui_story_1021_10211001_63_dialog_content = "……！這是部落送出的禮物！再不收，本首領可要反悔了！",
  ui_story_1021_10211001_64_dialog_content = "唔……我收我收！",
  ui_story_1021_10211001_65_dialog_content = "（唉，開始想念女王護衛提亞拉了……）",
  ui_story_1021_10211001_66_dialog_content = "……",
  ui_story_1021_10211001_67_dialog_content = "看來，妳已經放心讓提亞拉去做她想做的事情了。",
  ui_story_1021_10211001_68_dialog_content = "就算不當我的護衛，她也會在北境找到自己的位置。",
  ui_story_1021_10211001_69_dialog_content = "但自從那次雪崩之後，妳就永遠成為了她的燈塔。",
  ui_story_1021_10211001_70_dialog_content = "<color=#e8d9bb>部落被毀那一天……</color>",
  ui_story_1021_10211001_71_dialog_content = "成為女王的護衛，妳會感到辛苦嗎？",
  ui_story_1021_10211001_72_dialog_content = "女王陛下那麼強大……發生危險時，往往是她在保護大家，我從未覺得辛苦。",
  ui_story_1021_10211001_73_dialog_content = "她總是在我陷入危險的時候救我，一次又一次……",
  ui_story_1021_10211001_74_dialog_content = "雪狐部落，有恩必報。所以從我在雪崩中被她救起來那刻，我就發誓要守護她。",
  ui_story_1021_10211001_75_dialog_content = "妳真的瞭解她嗎？",
  ui_story_1021_10211001_76_dialog_content = "當然！從女王陛下巡視我們的領地起……我就偷偷跟著她，觀察她……",
  ui_story_1021_10211001_77_dialog_content = "她的一舉一動、她的氣息，甚至她的呼吸……我都瞭解。",
  ui_story_1021_10211001_78_dialog_content = "我能感覺到部落對外來者的排斥，但女王陛下不同……",
  ui_story_1021_10211001_79_dialog_content = "她看我的眼神，就像每年都會來探望我一次的親人……",
  ui_story_1021_10211001_80_dialog_content = "她的到來，彷彿照亮整個部落，也照亮了我的世界……",
  ui_story_1021_10211001_81_dialog_content = "提亞拉，該怎麼做，答案一直就在妳心裡。",
  ui_story_1021_10211001_82_dialog_content = "在這個世上，能夠照亮妳世界的人，便是妳的燈塔。",
  ui_story_1021_10211001_83_dialog_content = "我希望妳循著自己的燈塔，去吸收光和熱。",
  ui_story_1021_10211001_84_dialog_content = "等妳成為能夠照亮自己的燈塔時，一定就能照亮我們的部落了。",
  ui_story_1021_10211001_85_dialog_content = "……",
  ui_story_1021_10211001_86_dialog_content = "雪崩……妳不打算向她坦承真相了嗎？",
  ui_story_1021_10211001_87_dialog_content = "坦承或不坦承，現在已經沒有差別了。",
  ui_story_1021_10211001_88_dialog_content = "……",
  ui_story_1021_10211001_89_dialog_content = "但是在我眼裡，妳也是她的燈塔。",
  ui_story_1021_10211001_90_dialog_content = "<color=#e8d9bb>幾年前……</color>",
  ui_story_1021_10211001_91_dialog_content = "<color=#e8d9bb>窸窸窣窣——</color>",
  ui_story_1021_10211001_92_dialog_content = "……？",
  ui_story_1021_10211001_93_dialog_content = "（當時向我扔雪球的小女孩，不知不覺已經長這麼大了……）",
  ui_story_1021_10211001_94_dialog_content = "（獨自生活在這片雪松林裡，一定時常感到寂寞吧。）",
  ui_story_1021_10211001_95_dialog_content = "<color=#e8d9bb>沙沙——</color>",
  ui_story_1021_10211001_96_dialog_content = "……",
  ui_story_1021_10211001_97_dialog_content = "……",
  ui_story_1021_10211001_98_dialog_content = "（還真是個心急的孩子……）",
  ui_story_1021_10211001_99_dialog_content = "（從前只是遠遠地跟著，這一次卻主動露面……）",
  ui_story_1021_10211001_100_dialog_content = "……",
  ui_story_1021_10211001_101_dialog_content = "每年的這個時候，妳都會來。",
  ui_story_1021_10211001_102_dialog_content = "……",
  ui_story_1021_10211001_103_dialog_content = "但我仍然沒有做到「把燈塔照到這裡」的承諾。",
  ui_story_1021_10211001_104_dialog_content = "……",
  ui_story_1021_10211001_105_dialog_content = "謝謝你們。沒有你們，北境不會有如今的安寧。",
  ui_story_1021_10211001_106_dialog_content = "雖然先民留在這裡，死在戰爭的殘酷之下……",
  ui_story_1021_10211001_107_dialog_content = "但是我們肯定了自己，並且會繼續守護下去。",
  ui_story_1021_10211001_108_dialog_content = "……",
  ui_story_1021_10211001_109_dialog_content = "把提亞拉帶走吧。",
  ui_story_1021_10211001_110_dialog_content = "……？",
  ui_story_1021_10211001_111_dialog_content = "我的時日不多了，等她再長大一些，她就會知道「守護」的代價有多沉重。",
  ui_story_1021_10211001_112_dialog_content = "我不希望她像她的太奶奶一樣，固執而孤獨地守護這片雪松林。",
  ui_story_1021_10211001_113_dialog_content = "……提亞拉，是個倔強的孩子。",
  ui_story_1021_10211001_114_dialog_content = "但我知道，她對妳是那樣地好奇、嚮往。",
  ui_story_1021_10211001_115_dialog_content = "……",
  ui_story_1021_10211001_116_dialog_content = "<color=#e8d9bb>長老往林中一躍，巨大的雪球向著提亞拉滾去……</color>",
  ui_story_1021_10211001_117_dialog_content = "咿呀——！",
  ui_story_1021_10211001_118_dialog_content = "冰解之時，終結——",
  ui_story_1021_10211001_119_dialog_content = "妳救了我……",
  ui_story_1021_10211001_120_dialog_content = "而且……",
  ui_story_1021_10211001_121_dialog_content = "這樣，妳的長矛會變得更加堅固。",
  ui_story_1021_10211001_122_dialog_content = "咦……竟然發出這麼耀眼的光……！",
  ui_story_1021_10211001_123_dialog_content = "就像那座燈塔一樣……",
  ui_story_1021_10211001_124_dialog_content = "等等……",
  ui_story_1021_10211001_125_dialog_content = "……",
  ui_story_1021_10211001_126_dialog_content = "我、我叫提亞拉！",
  ui_story_1021_10211001_127_dialog_content = "……",
  ui_story_1021_10211001_128_dialog_content = "從今天起，無論妳去哪裡，我都會保護妳！雪狐部落，有恩必報！",
  ui_story_1021_10211001_129_dialog_content = "……",
  ui_story_1021_10211001_130_dialog_content = "感謝你們為北境所做的一切。",
  ui_story_1021_10211001_131_dialog_content = "誓言雖然沉重，但我會堅定地走出每一步……一直走下去……",
  ui_story_1021_10211001_132_dialog_content = "我向你們承諾，北境的燈塔，一定會照到這裡……",
  ui_story_1021_10211001_133_dialog_content = "甚至，照到更遠的地方。",
  ui_story_1022_10220100_1_dialog_content = "（這裡……是哪裡？）",
  ui_story_1022_10220100_2_dialog_content = "<color=#e8d9bb>世界昏黑一片，難辨方向，只讓人覺得冷。</color>",
  ui_story_1022_10220100_3_dialog_content = "（我為什麼在這種地方？）",
  ui_story_1022_10220100_4_dialog_content = "（越來越冷了。不行，不能待著不動，我得行動起來！）",
  ui_story_1022_10220100_5_dialog_content = "（可是往哪裡去才好？太黑了……嗯？那是什麼？）",
  ui_story_1022_10220100_6_dialog_content = "<color=#e8d9bb>極遠處，微弱的光點閃動著，在黑暗的擠壓中，在凜寒的肆虐下——</color>",
  ui_story_1022_10220100_7_dialog_content = "<color=#e8d9bb>光點不僅沒消失，反而越來越亮，光輝四射，閃耀奪目。</color>",
  ui_story_1022_10220100_8_dialog_content = "<color=#e8d9bb>猶如永夜中升起了太陽。</color>",
  ui_story_1022_10220100_9_dialog_content = "（好豐沛的光能！而且非常純粹，像正注視著我，指引我……）",
  ui_story_1022_10220100_10_dialog_content = "……會忘記的。看時間是否夠長，看你今後遇到的人是否更讓你難忘。",
  ui_story_1022_10220100_11_dialog_content = "什麼人？是在對我說話嗎？",
  ui_story_1022_10220100_12_dialog_content = "好、好冷，渾身都涼颼颼的。",
  ui_story_1022_10220100_13_dialog_content = "……感冒的喵！",
  ui_story_1022_10220100_14_dialog_content = "冷……好冷啊……",
  ui_story_1022_10220100_15_dialog_content = "誰叫你把毯子踢掉了喵～還壓在身體下面，菲莉詩沒辦法幫你重新蓋起來喵。",
  ui_story_1022_10220100_16_dialog_content = "不想感冒就快點醒來喵。",
  ui_story_1022_10220100_17_dialog_content = "咦，我睡著了？那剛才是在做夢？",
  ui_story_1022_10220100_18_dialog_content = "好冷！謝謝妳啊，菲莉詩，幸好妳把我叫醒了。",
  ui_story_1022_10220100_19_dialog_content = "不用客氣喵～既然你起來了，這個舒適的窩，就由菲莉詩來接管吧～",
  ui_story_1022_10220100_20_dialog_content = "等、等一下，不要這麼快入睡阿！",
  ui_story_1022_10220100_21_dialog_content = "現在情況怎麼樣？我們到什麼地方了？",
  ui_story_1022_10220100_22_dialog_content = "你往窗外看一眼就知道了喵～",
  ui_story_1022_10220100_23_dialog_content = "窗外……啊。",
  ui_story_1022_10220100_24_dialog_content = "<color=#e8d9bb>飛行器外，黑夜如黏質的流體一般綿延，壟罩天穹與大地，望不到盡頭。</color>",
  ui_story_1022_10220100_25_dialog_content = "<color=#e8d9bb>就像方才夢中的黑暗。</color>",
  ui_story_1022_10220100_26_dialog_content = "我們已經進入暗面了嗎？",
  ui_story_1022_10220100_27_dialog_content = "沒錯喵，菲莉詩剛過來通知你，就發現你抱著肩膀在喊冷喵～",
  ui_story_1022_10220100_28_dialog_content = "咳咳咳！",
  ui_story_1022_10220100_29_dialog_content = "（這麼說，我夢到那片黑暗，說不定是進入暗面的影響。）",
  ui_story_1022_10220100_30_dialog_content = "（但夢裡還有光能團，難道它也存在於現實中？）",
  ui_story_1022_10220100_31_option_content = "延伸感應",
  ui_story_1022_10220100_32_dialog_content = "……！",
  ui_story_1022_10220100_33_dialog_content = "（居然是真的。那究竟是什麼？）",
  ui_story_1022_10220100_34_dialog_content = "不過，狀況變得有些不妙了喵。",
  ui_story_1022_10220100_35_dialog_content = "我原本可以接收到兩組座標喵。",
  ui_story_1022_10220100_36_dialog_content = "一組是啟光先前派出的菁英探索小隊，另一組是卡戎長官和薇絲喵。",
  ui_story_1022_10220100_37_dialog_content = "薇絲怎麼了嗎？！",
  ui_story_1022_10220100_38_dialog_content = "別緊張呀～但也很難不讓你緊張喵，因為兩組座標的訊號都出了問題。",
  ui_story_1022_10220100_39_dialog_content = "菁英探索小隊的訊號越來越微弱，很可能是暗面對通訊儀器的影響喵。",
  ui_story_1022_10220100_40_dialog_content = "大家裝備的儀器應該都能在暗面使用啊。",
  ui_story_1022_10220100_41_dialog_content = "暗面環境太多變了喵，地勢、天氣、距離、暗能分佈，都會影響到儀器。",
  ui_story_1022_10220100_42_dialog_content = "原來如此。那、那薇絲他們呢？",
  ui_story_1022_10220100_43_dialog_content = "卡戎長官和薇絲的座標，一直在亂跳喵。",
  ui_story_1022_10220100_44_dialog_content = "亂跳？",
  ui_story_1022_10220100_45_dialog_content = "像貓咪眼前的逗貓棒，一會在這裡，一眨眼又到了那裡，讓菲莉詩眼花繚亂喵！",
  ui_story_1022_10220100_46_dialog_content = "根據菲莉詩掌握的彼岸號情報，它還做不出那麼跳脫的移動模式。",
  ui_story_1022_10220100_47_dialog_content = "但看起來又不像發訊儀器損壞，非常的奇怪喵～",
  ui_story_1022_10220100_48_dialog_content = "難道也是暗面的影響？現在還是聯絡不上他們嗎？",
  ui_story_1022_10220100_49_dialog_content = "緋長官試過，但是失敗了喵。現在連他們又跳到哪裡都無法判斷了。",
  ui_story_1022_10220100_50_dialog_content = "怎麼會有這種現象喵喵喵，太神祕了！菲莉詩仔細確認過一遍情報，還是找不到答案喵！這次是真的認真工作了喵！",
  ui_story_1022_10220100_51_dialog_content = "該不會是遭遇了……罪靈？",
  ui_story_1022_10220100_52_dialog_content = "咦？！",
  ui_story_1022_10220100_53_dialog_content = "那些罪靈的能力完全未知吧！擁有空間跳躍之類的荒唐能力也不無可能。",
  ui_story_1022_10220100_54_dialog_content = "薇絲又有駕馭衝擊者號的潛力，對覬覦巨像的罪靈來說很有價值。",
  ui_story_1022_10220100_55_dialog_content = "萬一哪個罪靈挾持了她，帶著她滿世界亂跑呢？！",
  ui_story_1022_10220100_56_dialog_content = "喵喵喵！這、這……",
  ui_story_1022_10220100_57_dialog_content = "有卡戎和彼岸號在，你說的情況幾乎不可能發生。",
  ui_story_1022_10220100_58_dialog_content = "緋長官！",
  ui_story_1022_10220100_59_dialog_content = "緋，妳說不可能，是真的嗎？畢竟不怕一萬，就怕萬一——",
  ui_story_1022_10220100_60_dialog_content = "<color=#e8d9bb>啪！</color>",
  ui_story_1022_10220100_61_dialog_content = "哎喲！",
  ui_story_1022_10220100_62_dialog_content = "（腦袋被狠狠彈了一下……）",
  ui_story_1022_10220100_63_dialog_content = "「萬一」的機率，誰也無法排除，所以擔心也沒用。",
  ui_story_1022_10220100_64_dialog_content = "出發前你答應會把心放在肚子裡不亂想，都忘了？",
  ui_story_1022_10220100_65_dialog_content = "當然沒忘！但一聽到薇絲遭遇了莫名的狀況，我就……",
  ui_story_1022_10220100_66_dialog_content = "（腦袋好痛，緋下手超狠的！）",
  ui_story_1022_10220100_67_dialog_content = "你的心情可以理解，但暗面危機四伏，還是集中精神吧。",
  ui_story_1022_10220100_68_dialog_content = "但願薇絲也能意識到這一點。她和你一樣，越是置身危機，越會去牽掛別人。",
  ui_story_1022_10220100_69_dialog_content = "作為軍人，還需要歷練。",
  ui_story_1022_10220100_70_dialog_content = "難道……緋，妳其實也很擔心薇絲？",
  ui_story_1022_10220100_71_dialog_content = "那是當然的吧？",
  ui_story_1022_10220100_72_dialog_content = "薇絲、卡戎長官、貢露科研長……讓人操心的小貓越來越多了喵。",
  ui_story_1022_10220100_73_dialog_content = "貢露？貢露怎麼了？",
  ui_story_1022_10220100_74_dialog_content = "「衝擊者號」重現天日後，貢露連遊戲都不開了，每天埋頭修理喵。",
  ui_story_1022_10220100_75_dialog_content = "她當年是衝擊者號實驗的負責人，想必是覺得對不起薇絲和大元帥喵。",
  ui_story_1022_10220100_76_dialog_content = "沒時間操心別人了，我們正面臨棘手的難題。",
  ui_story_1022_10220100_77_dialog_content = "這艘飛行器本來計畫與另外兩個小組協同行動，彼此照應。",
  ui_story_1022_10220100_78_dialog_content = "但目前兩組人馬都方位不明，我們的行動必須作出相應調整。",
  ui_story_1022_10220100_79_dialog_content = "菲莉詩很在意卡戎長官他們的情況，但現在很難與他們會合吧？",
  ui_story_1022_10220100_80_dialog_content = "（就算趕往他們上次傳來的座標，他們很可能又跳去別處了，可惡！）",
  ui_story_1022_10220100_81_dialog_content = "受暗面干擾，探索小隊的座標訊號也很久沒有傳回來了。",
  ui_story_1022_10220100_82_dialog_content = "這樣下去，我們等於是在漫無目的地浪費時間，不可能達成任何目標。",
  ui_story_1022_10220100_83_dialog_content = "……有一個光能團。",
  ui_story_1022_10220100_84_dialog_content = "什麼？",
  ui_story_1022_10220100_85_dialog_content = "我感應到……一團無名狀的巨大光能，就在暗面深處，可能很接近永夜地帶。",
  ui_story_1022_10220100_86_dialog_content = "居然有那種東西喵喵喵！",
  ui_story_1022_10220100_87_dialog_content = "凝聚的光能在暗面很罕見。其他隊伍要是也注意到了，或許會趕過去一探究竟。",
  ui_story_1022_10220100_88_dialog_content = "這倒不失為一個會合的契機。",
  ui_story_1022_10220100_89_dialog_content = "報告！收到後方據點的通訊請求！",
  ui_story_1022_10220100_90_dialog_content = "轉進來。",
  ui_story_1022_10220100_91_dialog_content = "是！",
  ui_story_1022_10220100_92_dialog_content = "測試，測試，聽得到嗎？",
  ui_story_1022_10220100_93_dialog_content = "萊因哈特！太好了，幸好還能跟妳聯絡上。",
  ui_story_1022_10220100_94_dialog_content = "聽得很清楚，大元帥，看來與後方的通訊並未受到影響。",
  ui_story_1022_10220100_95_dialog_content = "探索小隊的座標還是搜尋不到嗎？暗面真麻煩啊。",
  ui_story_1022_10220100_96_dialog_content = "緋，辛苦了，這次帶隊任務不輕鬆。",
  ui_story_1022_10220100_97_dialog_content = "部下深入暗面且處境不明，找回她是我的職責。",
  ui_story_1022_10220100_98_dialog_content = "何況聯合部隊成立以來，是靠白夜城的軍隊在地面紮營駐兵，我們才能沒有後顧之憂。",
  ui_story_1022_10220100_99_dialog_content = "大元帥，倒是您，和委員會溝通得順利嗎？有沒有又被為難？",
  ui_story_1022_10220100_100_dialog_content = "哈，要是他們完全不為難我，我反而要懷疑我走錯路了。",
  ui_story_1022_10220100_101_dialog_content = "總的來說還算順利吧。我慢慢發現，委員會就像一條啃自己尾巴的蛇。",
  ui_story_1022_10220100_102_dialog_content = "您的比喻是什麼意思？",
  ui_story_1022_10220100_103_dialog_content = "無論貝利撒留還是其他未露面的人……嗯，勉強把過去的尤利西斯也算上吧！",
  ui_story_1022_10220100_104_dialog_content = "他們的初衷，是想利用科技解決光靈的生存問題。",
  ui_story_1022_10220100_105_dialog_content = "這一點我不否認。",
  ui_story_1022_10220100_106_dialog_content = "但科技有其冷酷的一面。委員會離科技最近，因此也受到了最深的影響。",
  ui_story_1022_10220100_107_dialog_content = "他們在追求科技的路上，成了科技冷酷一面的化身。",
  ui_story_1022_10220100_108_dialog_content = "理性、效率、實用，為了追求這些，他們剝除人性，反而忘卻了最初的目的——",
  ui_story_1022_10220100_109_dialog_content = "創造出能讓光靈幸福生活的世界。",
  ui_story_1022_10220100_110_dialog_content = "（即使是尤利西斯，初衷也是強化光靈，與暗鬼對抗。）",
  ui_story_1022_10220100_111_dialog_content = "一味追逐效率，剝奪思考的空間，與一群暗鬼服從罪靈有什麼兩樣？",
  ui_story_1022_10220100_112_dialog_content = "所以新一代的人才要走出自己的路啊，想想鶯歌、西恩他們。",
  ui_story_1022_10220100_113_dialog_content = "我也不能輸給他們，必須做一點以前沒做過的事了。",
  ui_story_1022_10220100_114_dialog_content = "還有什麼是妳沒做過的嗎？",
  ui_story_1022_10220100_115_dialog_content = "哈哈哈！說得我像個反派一樣。",
  ui_story_1022_10220100_116_dialog_content = "身為大元帥，我做得還不夠多。過去因為戰爭，我竟無視了那些暗中的危險。",
  ui_story_1022_10220100_117_dialog_content = "委員會把控著啟光這艘大船的航向，我卻像上一任那樣選擇了妥協。",
  ui_story_1022_10220100_118_dialog_content = "大元帥！我知道您絕不是那樣的人——",
  ui_story_1022_10220100_119_dialog_content = "放輕鬆，緋，我只是在幫自己設定新的目標。",
  ui_story_1022_10220100_120_dialog_content = "現在不一樣了——我會將當年考慮過的變革實行到底。",
  ui_story_1022_10220100_121_dialog_content = "也許委員會的存在有意義，但我不允許啟光的力量被引入歧途。",
  ui_story_1022_10220100_122_dialog_content = "我要去剝開那群人的鐵面，看看底下還有沒有剩下人性。",
  ui_story_1022_10220100_123_dialog_content = "眼下雖然還有些疑團，但我很快會給大家一個交代。再給我一點時間吧。",
  ui_story_1022_10220100_124_dialog_content = "<color=#e8d9bb>與此同時，啟光委員會</color>",
  ui_story_1022_10220100_125_dialog_content = "萊因哈特下台了又捲土重來，尤利西斯的人體實驗鬧得天下皆知。",
  ui_story_1022_10220100_126_dialog_content = "為那座浮空島準備的軍火恐怕也曝光了。",
  ui_story_1022_10220100_127_dialog_content = "妳支持的每一件事，都成了射穿妳眉心的子彈。",
  ui_story_1022_10220100_128_dialog_content = "貝利撒留，妳打算怎麼負責？",
  ui_story_1022_10220100_129_dialog_content = "這些事要是全都輕輕帶過，委員會的威信就蕩然無存了！",
  ui_story_1022_10220100_130_dialog_content = "都這種時候了，何必還遮遮掩掩的？",
  ui_story_1022_10220100_131_dialog_content = "不妨直說讓我引咎辭職，騰出位置給你們。",
  ui_story_1022_10220100_132_dialog_content = "難道妳還有不服？",
  ui_story_1022_10220100_133_dialog_content = "沒有服不服，只有情勢需要與否。",
  ui_story_1022_10220100_134_dialog_content = "只要情勢需要，我隨時可以卸任，攬下所有責任，將罵名帶離委員會。",
  ui_story_1022_10220100_135_dialog_content = "這就是我存在於此的意義。",
  ui_story_1022_10220100_136_dialog_content = "……哼。",
  ui_story_1022_10220100_137_dialog_content = "不過，各位可要想清楚。想想萊因哈特，想想她的實力和號召力。",
  ui_story_1022_10220100_138_dialog_content = "想想這位大元帥麾下的軍隊，如今對委員會是什麼態度？",
  ui_story_1022_10220100_139_dialog_content = "……",
  ui_story_1022_10220100_140_dialog_content = "走到今天這一步，是因為啟光當年選擇了分權下的威權政治。",
  ui_story_1022_10220100_141_dialog_content = "委員會與軍隊彼此牽制，經歷了多年的拉鋸與摩擦，才有啟光今日的輝煌。",
  ui_story_1022_10220100_142_dialog_content = "但矛盾爆發，那邊的大元帥越能幹，局面就越難收拾。",
  ui_story_1022_10220100_143_dialog_content = "當年，我被推到台前與軍隊交涉；今天，我也可以因為與軍隊的衝突而離開。",
  ui_story_1022_10220100_144_dialog_content = "但我離開之後呢？",
  ui_story_1022_10220100_145_dialog_content = "這個攤子，你們誰想接手？誰能接手？",
  ui_story_1022_10220100_146_dialog_content = "<color=#e8d9bb>漫長的沉默降臨在會議室中。</color>",
  ui_story_1022_10220100_147_dialog_content = "趁著還有一件事情沒收場，各位再想想吧。",
  ui_story_1022_10220100_148_dialog_content = "一旦「武力」失去「理智」的約束，未來將會如何？",
  ui_story_1022_10220100_149_dialog_content = "但如果我們再去介入，真正的戰爭便會打響。",
  ui_story_1022_10220100_150_dialog_content = "委員會的初衷就是為了制約，我們還怕爭端嗎？",
  ui_story_1022_10220100_151_dialog_content = "但無意義的內鬥，對我們的目標又有什麼幫助？",
  ui_story_1022_10220100_152_dialog_content = "啟光的舵暫時交給<color=#FFB400>她</color>，我們本該接受，但<color=#FFB400>她</color>身上還有不確定的因素。",
  ui_story_1022_10220100_153_dialog_content = "別吵了，我們應該團結一致，共渡難關。",
  ui_story_1022_10220100_154_dialog_content = "團結？對現在的啟光人來說，我們恐怕只是添亂的吧？呵呵，我都猜得到他們會怎麼想——陰魂不散的委員會。",
  ui_story_1022_10220100_155_dialog_content = "各位得出結論了嗎？",
  ui_story_1022_10220100_156_dialog_content = "該<color=#FFB400>我們</color>出場了。",
  ui_story_1022_10220100_157_dialog_content = "……！",
  ui_story_1022_10220100_158_dialog_content = "啟光因分歧而生，決不能讓它因分歧而亡。",
  ui_story_1022_10220100_159_dialog_content = "由誰掌權都無所謂，重要的是不能再重蹈覆轍。",
  ui_story_1022_10220100_160_dialog_content = "啟光絕不能再遭受背叛。",
  ui_story_1022_10220201_1_dialog_content = "<color=#e8d9bb>暗面深處某地</color>",
  ui_story_1022_10220201_2_dialog_content = "隊長，怎麼辦？訊號還是發不出去。",
  ui_story_1022_10220201_3_dialog_content = "我們該不會再也聯絡不上大部隊了吧？",
  ui_story_1022_10220201_4_dialog_content = "聯絡不上好啊，可以自由行動了。",
  ui_story_1022_10220201_5_dialog_content = "聯絡得上才麻煩呢！跟脖子上牽了條繩子一樣，渾身不自在。",
  ui_story_1022_10220201_6_dialog_content = "隊長！這種話可不能亂講……",
  ui_story_1022_10220201_7_dialog_content = "你怕被誰聽見啊？那塊冰，還是那塊石頭？",
  ui_story_1022_10220201_8_dialog_content = "……咳咳！",
  ui_story_1022_10220201_9_dialog_content = "隊長！我、我好像聽見詭異的咳嗽聲……",
  ui_story_1022_10220201_10_option_content = "哪裡詭異了！",
  ui_story_1022_10220201_11_dialog_content = "就是說啊，明明是很正常的咳嗽。",
  ui_story_1022_10220201_12_option_content = "自信點，把「好像」去掉",
  ui_story_1022_10220201_13_dialog_content = "就是說啊，這麼刻意的咳嗽聲，顯然為了讓人注意到。",
  ui_story_1022_10220201_14_dialog_content = "誰在那裡？該不會是所謂的「大部隊」吧？",
  ui_story_1022_10220201_15_dialog_content = "妳相當冷靜呢。「菁英探索小隊」隊長佩皮塔。",
  ui_story_1022_10220201_16_dialog_content = "看在這個份上，妳剛才的發言，我就當做沒聽到吧，下不為例。",
  ui_story_1022_10220201_17_dialog_content = "第、第三軍團長！",
  ui_story_1022_10220201_18_dialog_content = "這裡又暗又安靜，非常非常適合睡覺喵～",
  ui_story_1022_10220201_19_dialog_content = "還有情報長！",
  ui_story_1022_10220201_20_dialog_content = "我、我、我，我去替各位長官泡茶！",
  ui_story_1022_10220201_21_dialog_content = "哪來的茶葉啊？各位長官把這孩子都嚇出幻覺了。",
  ui_story_1022_10220201_22_dialog_content = "……",
  ui_story_1022_10220201_23_dialog_content = "這位咳嗽的仁兄還沒介紹呢。你為什麼畏畏縮縮站在後面？頭銜比不過她們？",
  ui_story_1022_10220201_24_dialog_content = "我不是啟光的軍人，只是一個空裔……",
  ui_story_1022_10220201_25_dialog_content = "那就更怪了。她們又管不到你，你幹嘛要當小跟班？",
  ui_story_1022_10220201_26_dialog_content = "才不是呢！我們只是自然而然地結伴同行——",
  ui_story_1022_10220201_27_dialog_content = "自然而然地淪為小跟班？",
  ui_story_1022_10220201_28_dialog_content = "妳！",
  ui_story_1022_10220201_29_dialog_content = "好了，閒話就說到這裡。會合不易，我們先來交換情報。",
  ui_story_1022_10220201_30_dialog_content = "嗯……你們朝著一個巨大的光能團前進，途中意外發現了我們？",
  ui_story_1022_10220201_31_dialog_content = "未免太巧了吧？該不會在耍我？",
  ui_story_1022_10220201_32_dialog_content = "我們為什麼要做這種事？",
  ui_story_1022_10220201_33_dialog_content = "原因就只有你們自己知道了。比如不想跟我說實話啦，純粹覺得惡作劇好玩啦……",
  ui_story_1022_10220201_34_dialog_content = "惡作劇？妳在說什——",
  ui_story_1022_10220201_35_dialog_content = "妳給我認真一點！",
  ui_story_1022_10220201_36_dialog_content = "PlayerName？",
  ui_story_1022_10220201_37_dialog_content = "我和緋是為了尋找非常重要的同伴才來暗面的！",
  ui_story_1022_10220201_38_dialog_content = "本來以為朝著光能團走，說不定能碰到她，結果完全沒有……",
  ui_story_1022_10220201_39_dialog_content = "我們怎麼可能還有心情惡作劇？",
  ui_story_1022_10220201_40_dialog_content = "同伴？",
  ui_story_1022_10220201_41_dialog_content = "喔，要是妳還敢說「你們看到是我一定很失望吧」這種話，我就真的要生氣了！",
  ui_story_1022_10220201_42_dialog_content = "……",
  ui_story_1022_10220201_43_dialog_content = "……",
  ui_story_1022_10220201_44_dialog_content = "哈哈哈哈哈哈！",
  ui_story_1022_10220201_45_dialog_content = "妳、妳笑什麼！",
  ui_story_1022_10220201_46_dialog_content = "原來你這樣還不算真的生氣啊？你真的生氣是怎麼樣，我倒是好奇起來了。",
  ui_story_1022_10220201_47_dialog_content = "妳這個人——！",
  ui_story_1022_10220201_48_dialog_content = "不過，大概是看不到了，因為我完全沒有打算說那種話。",
  ui_story_1022_10220201_49_dialog_content = "是我誤會你們了。玩鬧得有點過頭，抱歉啦。",
  ui_story_1022_10220201_50_dialog_content = "誤會……？",
  ui_story_1022_10220201_51_dialog_content = "因為你們是啟光的人。我想，無非就是一群聽了上級命令，想也不想就衝進暗面的傻瓜。",
  ui_story_1022_10220201_52_dialog_content = "結果是……「為了重要的同伴」嗎？哈哈！",
  ui_story_1022_10220201_53_dialog_content = "尤其是你小子，敢當著第三軍團長的面大叫大嚷，膽子很大嘛。",
  ui_story_1022_10220201_54_dialog_content = "我喜歡你。",
  ui_story_1022_10220201_55_dialog_content = "？！",
  ui_story_1022_10220201_56_dialog_content = "妳、妳妳妳妳又在胡說些什麼啊！",
  ui_story_1022_10220201_57_dialog_content = "該胡說的時候我眼也不會眨的，但剛才那句不是。",
  ui_story_1022_10220201_58_dialog_content = "我喜歡有自我意志的人。",
  ui_story_1022_10220201_59_dialog_content = "這東西誰都有吧……",
  ui_story_1022_10220201_60_dialog_content = "行了，又扯遠了。",
  ui_story_1022_10220201_61_dialog_content = "佩皮塔，既然妳願意好好對話了，現在輪到妳來報告探索進展。",
  ui_story_1022_10220201_62_dialog_content = "妳深入暗面已久，是否有掌握到什麼情報？",
  ui_story_1022_10220201_63_dialog_content = "探索進展？唉，在暗面探索實在強人所難，做什麼都得費不少功夫。",
  ui_story_1022_10220201_64_dialog_content = "就說紮營吧。這些糊牆的紙，還是我滿地撿回來的通緝令呢。",
  ui_story_1022_10220201_65_dialog_content = "<color=#FFB400>我·自·己·的</color>。",
  ui_story_1022_10220201_66_dialog_content = "妳的通緝令？不是我理解的那個意思吧，哈哈……",
  ui_story_1022_10220201_67_dialog_content = "嗯……唔唔……好奇怪呀，菲莉詩做了一個關於這位小姐的夢喵……",
  ui_story_1022_10220201_68_dialog_content = "夢裡的小姐非常非常眼熟喵～",
  ui_story_1022_10220201_69_dialog_content = "不愧是啟光的情報長！",
  ui_story_1022_10220201_70_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_1022_10220201_71_dialog_content = "PlayerName，趴下！",
  ui_story_1022_10220201_72_dialog_content = "<color=#e8d9bb>巨響轟隆隆震過冰洞，無數冰塊從頭頂砸落。</color>",
  ui_story_1022_10220201_73_dialog_content = "<color=#e8d9bb>混亂之中，響徹佩皮塔爽朗的大笑。</color>",
  ui_story_1022_10220201_74_dialog_content = "找你們的同伴去吧。我不會妨礙你們，你們也別來妨礙我！",
  ui_story_1022_10220201_75_dialog_content = "喵喵，究竟為什麼那麼眼熟喵？",
  ui_story_1022_10220201_76_dialog_content = "怎、怎麼回事，冰洞怎麼突然塌了？佩皮塔到哪裡去了？",
  ui_story_1022_10220201_77_dialog_content = "大概是逃跑了。",
  ui_story_1022_10220201_78_dialog_content = "逃跑？為什麼？！",
  ui_story_1022_10220201_79_dialog_content = "喵！菲莉詩想起來了喵！那位小姐是個逃犯喵！",
  ui_story_1022_10220201_80_dialog_content = "逃犯？但她是啟光派來探索暗面的人，還帶領著啟光的士兵。",
  ui_story_1022_10220201_81_dialog_content = "因為她後來被逮捕了喵，逮捕後關在啟光的監獄裡喵～",
  ui_story_1022_10220201_82_dialog_content = "這麼說，是我們捏住了她的什麼把柄，要脅她效命？為什麼非得是她？",
  ui_story_1022_10220201_83_dialog_content = "菲莉詩，佩皮塔入獄的原因是什麼？",
  ui_story_1022_10220201_84_dialog_content = "菲莉詩不知道喵……",
  ui_story_1022_10220201_85_dialog_content = "那位小姐的調查與逮捕都是涅墨西斯負責的，據說是直接向委員會報告喵。",
  ui_story_1022_10220201_86_dialog_content = "來頭還真不小。",
  ui_story_1022_10220201_87_dialog_content = "那個……我可以插句話嗎？",
  ui_story_1022_10220201_88_dialog_content = "佩皮塔是囚犯，趁機逃跑倒是說得通，但為什麼偏偏選在現在？",
  ui_story_1022_10220201_89_dialog_content = "和我們會合之前，她帶領小隊單獨行動，逃跑機會要多少有多少吧？",
  ui_story_1022_10220201_90_dialog_content = "偏偏要當著緋的面逃跑？怎麼看都是難度大增啊！",
  ui_story_1022_10220201_91_dialog_content = "這……",
  ui_story_1022_10220201_92_dialog_content = "發生了什麼事？剛才的巨響，是隊長引爆了防暗鬼陷阱嗎？暗鬼在哪裡？",
  ui_story_1022_10220201_93_dialog_content = "咦，隊長到哪裡去了？！",
  ui_story_1022_10220201_94_dialog_content = "喵喵喵？防暗鬼陷阱？",
  ui_story_1022_10220201_95_dialog_content = "因、因為我們這些隊員進了暗面會被壓制感官，隊長每駐紮一處都會設下各種防備暗鬼的機關。",
  ui_story_1022_10220201_96_dialog_content = "特別是發現「那個地方」後，隊長戒備得更森嚴了。",
  ui_story_1022_10220201_97_dialog_content = "別看隊長那樣，她其實很關心我們的，嘿嘿。",
  ui_story_1022_10220201_98_dialog_content = "……",
  ui_story_1022_10220201_99_dialog_content = "該不會，之所以現在才逃跑……",
  ui_story_1022_10220201_100_dialog_content = "是為了把隊員託付給我們吧？那個佩皮塔……",
  ui_story_1022_10220201_101_dialog_content = "<color=#e8d9bb>暗面，白夜城部隊駐紮地</color>",
  ui_story_1022_10220201_102_dialog_content = "佩皮塔。這是本次目標的名字。",
  ui_story_1022_10220201_103_dialog_content = "目標非常狡猾，為了脫身什麼事都幹得出來，各位務必謹慎行事。",
  ui_story_1022_10220201_104_dialog_content = "不能重蹈覆轍。",
  ui_story_1022_10220201_105_dialog_content = "是，組長！",
  ui_story_1022_10220201_106_dialog_content = "上一次，是我太大意，受到蠱惑……",
  ui_story_1022_10220201_107_dialog_content = "不是妳的錯，艾莉法。",
  ui_story_1022_10220201_108_dialog_content = "啟光委員會跟那傢伙打了多年交道，當初能捷足先登也是沒辦法的事。",
  ui_story_1022_10220201_109_dialog_content = "但這一次，擁有優勢的是我們！",
  ui_story_1022_10220201_110_dialog_content = "可以詳細說說你們的行動嗎？",
  ui_story_1022_10220201_111_dialog_content = "殿下……！",
  ui_story_1022_10220202_1_dialog_content = "請，這是您點的「深淵的凝視」。",
  ui_story_1022_10220202_2_dialog_content = "迷幻的色彩、罪惡的香氣、扭曲幻化的紋理……原來如此，這就是邪神詛咒過的飲料嗎？",
  ui_story_1022_10220202_3_dialog_content = "唔呃……！如此甜蜜，深深蠱惑著我的胃袋和心靈！邪神，可怖如斯……",
  ui_story_1022_10220202_4_dialog_content = "我不入地獄誰入地獄？再來、再來一杯！",
  ui_story_1022_10220202_5_dialog_content = "哈哈哈哈！小喝一杯而已，內心戲這麼豐富，妳這人還真有意思啊。",
  ui_story_1022_10220202_6_dialog_content = "是誰？哪個不可言說之物在對我呢喃？",
  ui_story_1022_10220202_7_dialog_content = "不是什麼不可言說之物，是我，一直坐在妳旁邊的客人。",
  ui_story_1022_10220202_8_dialog_content = "妳也喜歡喝這個？看在是同好的份上，我可以跟妳推薦幾種喔。",
  ui_story_1022_10220202_9_dialog_content = "推薦？嗯，偶爾隨波逐流也沒有什麼不好。",
  ui_story_1022_10220202_10_dialog_content = "不過，我需要無酒精的，謝謝。",
  ui_story_1022_10220202_11_dialog_content = "……蛤啊？",
  ui_story_1022_10220202_12_dialog_content = "<size=30>沒喝醉都這樣，這是什麼精神狀態？</size>",
  ui_story_1022_10220202_13_dialog_content = "妳對菜單很熟悉……經常來這裡感受罪惡嗎？",
  ui_story_1022_10220202_14_dialog_content = "我感受的可不止罪惡。歡欣、驚險、狂熱、欺瞞，都是本大人人生菜單上的主菜。",
  ui_story_1022_10220202_15_dialog_content = "將虛假的世界視作菜餚，予以俯視嗎？也許，妳也具備與未知之物對抗的潛力。",
  ui_story_1022_10220202_16_dialog_content = "來執行墮入罪惡的儀式吧——乾杯。",
  ui_story_1022_10220202_17_dialog_content = "乾杯！",
  ui_story_1022_10220202_18_dialog_content = "唔唔……這一杯也好喝得令人心悸。妳的推薦都很出色。",
  ui_story_1022_10220202_19_dialog_content = "那還用說？",
  ui_story_1022_10220202_20_dialog_content = "不過，妳為什麼堅持要無酒精的？看妳也不像那種假正經啊。",
  ui_story_1022_10220202_21_dialog_content = "其實……我正在執行任務。為了任務，必須自律。",
  ui_story_1022_10220202_22_dialog_content = "欸，聽起來是很了不起的工作嘛。",
  ui_story_1022_10220202_23_dialog_content = "白夜城的異端調查團……的確，是了不起的工作。對世界，很重要……",
  ui_story_1022_10220202_24_dialog_content = "異端調查團來到影鎮了？！",
  ui_story_1022_10220202_25_dialog_content = "影鎮是惡魔支配的土地，混亂、無序，因此我們的目標逃往此處。",
  ui_story_1022_10220202_26_dialog_content = "那個人竊走了白夜城的祕典，潛入影鎮，行蹤成謎。",
  ui_story_1022_10220202_27_dialog_content = "（說的不就是我嗎……？）",
  ui_story_1022_10220202_28_dialog_content = "必須抓住她，找回祕典……嗯？心靈之友啊，妳要上哪去？",
  ui_story_1022_10220202_29_dialog_content = "我……冷飲喝多了頭暈，去一下洗手間！",
  ui_story_1022_10220202_30_dialog_content = "……可惡！這麼好的機會，竟然被她逃了！",
  ui_story_1022_10220202_31_dialog_content = "心靈之友就是兇惡逃犯佩皮塔……怎麼會……",
  ui_story_1022_10220202_32_dialog_content = "趕緊追，還有機會！",
  ui_story_1022_10220202_33_dialog_content = "只要別讓啟光捷足先登……",
  ui_story_1022_10220202_34_dialog_content = "（躲到這裡就沒問題了。）",
  ui_story_1022_10220202_35_dialog_content = "（藏一棵樹最好的地點是森林，藏一個光靈最好的地點當然就是——）",
  ui_story_1022_10220202_36_dialog_content = "（葬禮現場！）",
  ui_story_1022_10220202_37_dialog_content = "（後頭都在挖坑了，誰會想到棺材裡的死者是我呀？哈哈哈！）",
  ui_story_1022_10220202_38_dialog_content = "別躺了，自己出來。",
  ui_story_1022_10220202_39_dialog_content = "果然躲來這裡，很有妳的風格。",
  ui_story_1022_10220202_40_dialog_content = "壓著死人也不嫌晦氣？",
  ui_story_1022_10220202_41_dialog_content = "！！！",
  ui_story_1022_10220202_42_dialog_content = "（哪裡露出了馬腳？啊，衣服！）",
  ui_story_1022_10220202_43_dialog_content = "（失策了，誰家死人躺棺材裡接受瞻仰時穿我這一身破爛……）",
  ui_story_1022_10220202_44_dialog_content = "（以後……以後一定要好好穿衣服！）",
  ui_story_1022_10220202_45_dialog_content = "妳說那個叫佩皮塔的人偷走了白夜城的祕典？",
  ui_story_1022_10220202_46_dialog_content = "是的，殿下。不過，她偷走的祕典並非真品，因此這樁竊案也就罷了。",
  ui_story_1022_10220202_47_dialog_content = "重要的是，她帶著假祕典投入了真理結社——艾斯特拉最可恨的異端組織！",
  ui_story_1022_10220202_48_dialog_content = "妳說失竊的祕典是偽品，那真正的祕典到哪去了？",
  ui_story_1022_10220202_49_dialog_content = "這正是問題的關鍵。真正的祕典多年前就遺失了，種種線索都表明——",
  ui_story_1022_10220202_50_dialog_content = "真品祕典早就落在真理結社手中。",
  ui_story_1022_10220202_51_dialog_content = "我懂了。誰也不知道真理結社的大本營在哪裡，結社成員又都行蹤飄忽。",
  ui_story_1022_10220202_52_dialog_content = "好不容易來了一個佩皮塔，又是偷假祕典，又是和艾莉法喝酒，高調又囂張。",
  ui_story_1022_10220202_53_dialog_content = "你們想循著她這條線索，摸到真理結社，尋回真祕典。",
  ui_story_1022_10220202_54_dialog_content = "殿下明察，我們當時的計畫正如您所說。",
  ui_story_1022_10220202_55_dialog_content = "可恨啟光委員會派出的處刑者搶先一步，把佩皮塔抓回了啟光……",
  ui_story_1022_10220202_56_dialog_content = "這麼說，佩皮塔此次來到暗面是受啟光派遣的了，白夜城要動她恐怕沒那麼簡單。",
  ui_story_1022_10220202_57_dialog_content = "殿下，這一點您大可以放心。",
  ui_story_1022_10220202_58_dialog_content = "異端調查組本次的行動，已獲得城主大人和啟光大元帥批准。",
  ui_story_1022_10220202_59_dialog_content = "城主大人與萊因哈特照會過後，准許我們追緝佩皮塔，履行原本的職責。",
  ui_story_1022_10220202_60_dialog_content = "這一次，她絕對逃不了！",
  ui_story_1022_10220202_61_dialog_content = "既然這樣，我們暫時與啟光的暗面探索隊一起行動吧。",
  ui_story_1022_10220202_62_dialog_content = "他們不久前已經遭遇過佩皮塔了。",
  ui_story_1022_10220301_1_dialog_content = "卡蓮，這裡這裡！妳們來得好快。",
  ui_story_1022_10220301_2_dialog_content = "事關白夜城祕典，馬虎不得。",
  ui_story_1022_10220301_3_dialog_content = "你呢？跟兇惡的逃犯打了一回交道，吃大虧了吧？",
  ui_story_1022_10220301_4_dialog_content = "咳，確實有種被玩弄的挫敗感……",
  ui_story_1022_10220301_5_dialog_content = "不過，別小看我！我可是一路感應過來的，佩皮塔絕對離這裡不遠了。",
  ui_story_1022_10220301_6_dialog_content = "……",
  ui_story_1022_10220301_7_dialog_content = "菲莉詩帶著佩皮塔的隊員先回一趟飛行器，我和緋跟妳們一起行動。",
  ui_story_1022_10220301_8_dialog_content = "佩皮塔受啟光派遣探索暗面，我有義務追回她和她的探索所得。",
  ui_story_1022_10220301_9_dialog_content = "這次恐怕得讓給我們了。",
  ui_story_1022_10220301_10_dialog_content = "妳是誰？",
  ui_story_1022_10220301_11_dialog_content = "這位是白夜城異端調查組的組長。目前的情況是——",
  ui_story_1022_10220301_12_dialog_content = "大元帥批准了白夜城的追緝行動？",
  ui_story_1022_10220301_13_dialog_content = "明白了。人可以交給你們，但我要先問她幾個問題。",
  ui_story_1022_10220301_14_dialog_content = "發現「那個地方」時，隊長一開始很興奮，但馬上像是顧及我們的安危，飛快把我們帶走了。",
  ui_story_1022_10220301_15_dialog_content = "我感覺，隊長對那裡奇異的景觀並不陌生。",
  ui_story_1022_10220301_16_dialog_content = "佩皮塔明顯知道些什麼。",
  ui_story_1022_10220301_17_dialog_content = "哼，啟光的人總是這麼蠻橫，搶了我們一次，還想搶第二次！",
  ui_story_1022_10220301_18_dialog_content = "都說了人可以交給你們——",
  ui_story_1022_10220301_19_dialog_content = "把人當牛排一樣又分又搶的，經過我同意了嗎？",
  ui_story_1022_10220301_20_dialog_content = "佩皮塔！",
  ui_story_1022_10220301_21_dialog_content = "自己送上門來了嗎？！",
  ui_story_1022_10220301_22_dialog_content = "心靈之友！不，錯誤的……我不能再被蠱惑……",
  ui_story_1022_10220301_23_dialog_content = "誰蠱惑妳了？我們共飲時的快樂難道不是真的？都是妳真實的感受。",
  ui_story_1022_10220301_24_dialog_content = "遵循妳的內心，真實地來戰吧，艾莉法！",
  ui_story_1022_10220301_25_dialog_content = "我的感受……虛假世界中的真實……",
  ui_story_1022_10220301_26_dialog_content = "別想再欺騙艾莉法！",
  ui_story_1022_10220301_27_dialog_content = "（好靈活的移動！）",
  ui_story_1022_10220301_28_dialog_content = "哪裡跑？",
  ui_story_1022_10220301_29_dialog_content = "散華——寂滅！",
  ui_story_1022_10220301_30_dialog_content = "<color=#e8d9bb>一波波攻勢襲向佩皮塔。佩皮塔偶爾玩鬧般反擊幾下，多數時候卻只是跳躍、閃避。</color>",
  ui_story_1022_10220301_31_dialog_content = "<color=#e8d9bb>以一敵眾，竟不像落在下風。</color>",
  ui_story_1022_10220301_32_dialog_content = "這傢伙，難道不受暗面的影響？！",
  ui_story_1022_10220301_33_dialog_content = "她果然非同尋常……",
  ui_story_1022_10220301_34_dialog_content = "（正常光靈在暗面活動時，一定會受到壓制，佩皮塔卻像沒事一樣。）",
  ui_story_1022_10220301_35_dialog_content = "哈哈哈哈，知道你佩皮塔姥姥的厲害了吧？",
  ui_story_1022_10220301_36_dialog_content = "新手教學關結束囉～接下來，是大反派佩皮塔的狂暴時間！",
  ui_story_1022_10220301_37_dialog_content = "佩蒂佩蒂——大大大！",
  ui_story_1022_10220301_38_dialog_content = "這股能量……！",
  ui_story_1022_10220301_39_dialog_content = "怎麼回事，突然間連呼吸都困難……",
  ui_story_1022_10220301_40_dialog_content = "暗能……變得好濃郁。",
  ui_story_1022_10220301_41_dialog_content = "（沒錯，佩皮塔手中的布娃娃有股暗鬼的氣息！這是怎麼回事？）",
  ui_story_1022_10220301_42_dialog_content = "大大大，大大大，再大再大再大——！",
  ui_story_1022_10220301_43_dialog_content = "<color=#e8d9bb>伴隨著佩皮塔高昂的哄笑，布娃娃不斷膨大，沉重的身軀接連送出轟擊</color>。",
  ui_story_1022_10220301_44_dialog_content = "<color=#e8d9bb>就連它的影子都彷彿有形。昏黑、龐大的影子，擠壓著現場所有光靈的身心。</color>",
  ui_story_1022_10220301_45_dialog_content = "這樣下去，我的人會撐不住的！",
  ui_story_1022_10220301_46_dialog_content = "她怎麼會有這麼詭異的布偶？！",
  ui_story_1022_10220301_47_dialog_content = "佩蒂是我的<color=#FFB400>魔寵</color>。都叫魔寵了，當然得有點魔性囉～",
  ui_story_1022_10220301_48_dialog_content = "好好感受吧！留給你們和布娃娃玩耍的時間——",
  ui_story_1022_10220301_49_dialog_content = "可·不·多·了。",
  ui_story_1022_10220301_50_dialog_content = "啊！",
  ui_story_1022_10220301_51_dialog_content = "什麼……那是什麼？",
  ui_story_1022_10220301_52_dialog_content = "PlayerName，你怎麼了？突然東張西望。",
  ui_story_1022_10220301_53_dialog_content = "<color=#e8d9bb>她·來·了。</color>",
  ui_story_1022_10220301_54_dialog_content = "有什麼東西在接近……好強的暗能……快躲開！",
  ui_story_1022_10220301_55_dialog_content = "<color=#e8d9bb>一滴乳白色的淚滴從天而降，倒映在每一雙飛快後退的眼睛裡。</color>",
  ui_story_1022_10220301_56_dialog_content = "<color=#e8d9bb>淚滴墜落地面。</color>",
  ui_story_1022_10220301_57_dialog_content = "<color=#e8d9bb>高能量爆炸掀翻戰場——</color>",
  ui_story_1022_10220301_58_dialog_content = "是誰，在欺負我的朋友？",
  ui_story_1022_10220301_59_dialog_content = "<color=#FFB400>烏蘇拉</color>，妳果然來了～",
  ui_story_1022_10220301_60_dialog_content = "<color=#e8d9bb>煙塵散盡，現身於爆炸中央的身影，扼住了在場所有人的呼吸。</color>",
  ui_story_1022_10220301_61_dialog_content = "這個波長……是<color=#FFB400>罪靈</color>！",
  ui_story_1022_10220301_62_dialog_content = "佩皮塔，妳不僅加入異端結社，甚至還勾結暗鬼嗎？！",
  ui_story_1022_10220301_63_dialog_content = "她的身影像在濃霧裡，我不知該怎麼勾勒……",
  ui_story_1022_10220301_64_dialog_content = "什麼勾結？亂講，亂講！佩皮塔跟我早就是朋友，比認識你們更早！你們才是勾結！",
  ui_story_1022_10220301_65_dialog_content = "？！！",
  ui_story_1022_10220301_66_dialog_content = "哈哈哈哈，你們的表情太有趣了！光為這個表情，我冒險重新現身就值了。",
  ui_story_1022_10220301_67_dialog_content = "妳早就知道會引來罪靈嗎？",
  ui_story_1022_10220301_68_dialog_content = "廢話。要不是知道烏蘇拉就在附近，我幹嘛要主動找你們打架？我又不是傻子。",
  ui_story_1022_10220301_69_dialog_content = "又被我玩弄於股掌之間的感覺怎麼樣啊，空裔？",
  ui_story_1022_10220301_70_dialog_content = "可惡！",
  ui_story_1022_10220301_71_dialog_content = "佩皮塔，我送妳的小佩蒂呢？我是感知到牠的氣息，特地來找妳的。看我對妳多好。",
  ui_story_1022_10220301_72_dialog_content = "在這裡，妳看。幹嘛，別想再要回去喔，我跟牠有感情了。",
  ui_story_1022_10220301_73_dialog_content = "（我沒聽錯吧？這對話聽起來居然真的像朋友……）",
  ui_story_1022_10220301_74_dialog_content = "佩皮塔，不要以為引來罪靈就萬事大吉了。",
  ui_story_1022_10220301_75_dialog_content = "妳偷走白夜城祕典，必須給一個交代！",
  ui_story_1022_10220301_76_dialog_content = "「偷」？那本來就是真理結社的東西好嗎？",
  ui_story_1022_10220301_77_dialog_content = "什麼？！",
  ui_story_1022_10220301_78_dialog_content = "所以啊，我可不欠你們白夜城任何東西。",
  ui_story_1022_10220301_79_dialog_content = "至於啟光就更別說了，我不找你們討債就不錯了。",
  ui_story_1022_10220301_80_dialog_content = "啊別誤會，債我還是要討的，絕對不會一筆勾銷喔！",
  ui_story_1022_10220301_81_dialog_content = "……",
  ui_story_1022_10220301_82_dialog_content = "貝利撒留那老太婆，以為用心臟就能要脅我，讓我做牛做馬？做夢去吧。",
  ui_story_1022_10220301_83_dialog_content = "佩皮塔大人不伺候囉，哈哈哈哈！",
  ui_story_1022_10220301_84_dialog_content = "烏蘇拉，我們走。",
  ui_story_1022_10220301_85_dialog_content = "一起瘋個通宵！",
  ui_story_1022_10220301_86_dialog_content = "佩皮塔……",
  ui_story_1022_10220301_87_dialog_content = "不准走！",
  ui_story_1022_10220301_88_dialog_content = "你們……好煩！都去死！！",
  ui_story_1022_10220301_89_dialog_content = "嘎——！！",
  ui_story_1022_10220301_90_dialog_content = "小心！",
  ui_story_1022_10220302_1_dialog_content = "（佩蒂，去吧，告訴維多利亞大人我在哪裡。）",
  ui_story_1022_10220302_2_dialog_content = "快走啊，佩皮塔，妳還在蘑菇什麼？是妳邀請我一起玩的吧？",
  ui_story_1022_10220302_3_dialog_content = "來了來了~",
  ui_story_1022_10220302_4_dialog_content = "哇哈哈哈，妳有看到那些光靈的樣子嗎？我揍得他們還不了手，氣得要命！",
  ui_story_1022_10220302_5_dialog_content = "妳是沒看到，我之前才叫厲害呢。我趁他們沒有防備，一口氣引爆了陷阱。",
  ui_story_1022_10220302_6_dialog_content = "場面要多華麗有多華麗～",
  ui_story_1022_10220302_7_dialog_content = "這麼好玩的事，為什麼不找我？不公平，不公平！",
  ui_story_1022_10220302_8_dialog_content = "妳得賠我！妳要賠我更瘋、更華麗的場面，嗚哇哇哇！",
  ui_story_1022_10220302_9_dialog_content = "別哭呀，我們兩個在一起，華麗還會少嗎？",
  ui_story_1022_10220302_10_dialog_content = "（日蝕語）報告，遠處有一個會動彈的小東西，好像正在逃跑。",
  ui_story_1022_10220302_11_dialog_content = "（日蝕語）那是——是烏蘇拉大人送給那個光靈的魔寵！",
  ui_story_1022_10220302_12_dialog_content = "（日蝕語）那光靈在搗什麼鬼？光靈果然都是一群狡猾的東西。",
  ui_story_1022_10220302_13_dialog_content = "（日蝕語）怎麼辦，要讓牠逃走嗎？",
  ui_story_1022_10220302_14_dialog_content = "（日蝕語）什麼蠢問題！快點把魔寵抓回來，交給烏蘇拉大人！",
  ui_story_1022_10220302_15_dialog_content = "（日蝕語）是！",
  ui_story_1022_10220302_16_dialog_content = "可惡！！",
  ui_story_1022_10220302_17_dialog_content = "竟然又被那傢伙跑了……好不容易都圍住她了！",
  ui_story_1022_10220302_18_dialog_content = "佩皮塔竟然能召來罪靈，誰都預料不到，您別太懊惱了。",
  ui_story_1022_10220302_19_dialog_content = "我的疑問倒是解開了。",
  ui_story_1022_10220302_20_dialog_content = "剛才的罪靈身上長著珊瑚一樣的東西……",
  ui_story_1022_10220302_21_dialog_content = "恐怕佩皮塔一發現那個地方，就知道罪靈在附近，當即決定要找機會逃跑、投奔罪靈。",
  ui_story_1022_10220302_22_dialog_content = "為什麼投奔罪靈？罪靈，能給她什麼呢？",
  ui_story_1022_10220302_23_dialog_content = "表示她已經徹底墮落、不可理喻了！艾莉法，妳可別再因為她的話而動搖！",
  ui_story_1022_10220302_24_dialog_content = "……",
  ui_story_1022_10220302_25_dialog_content = "沒有人覺得奇怪嗎？",
  ui_story_1022_10220302_26_dialog_content = "妳是指什麼，卡蓮？",
  ui_story_1022_10220302_27_dialog_content = "那個罪靈——烏蘇拉實力很強，但似乎並不熱衷於攻擊我們。",
  ui_story_1022_10220302_28_dialog_content = "兩次主動進攻，都只是為了保護佩皮塔。",
  ui_story_1022_10220302_29_option_content = "友情之力？！",
  ui_story_1022_10220302_30_dialog_content = "……你是在耍寶嗎？",
  ui_story_1022_10220302_31_dialog_content = "對不起。",
  ui_story_1022_10220302_32_option_content = "她們真的像是朋友",
  ui_story_1022_10220302_33_dialog_content = "佩皮塔相信烏蘇拉會來找她，所以才會肆無忌憚地在我們面前現身。",
  ui_story_1022_10220302_34_dialog_content = "光靈和罪靈的友誼，真的能夠維持嗎？",
  ui_story_1022_10220302_35_dialog_content = "確實，烏蘇拉的表現令人費解。",
  ui_story_1022_10220302_36_dialog_content = "對我們沒有敵意，卻又救走了佩皮塔？為了什麼？她們到底想幹什麼？",
  ui_story_1022_10220302_37_dialog_content = "也許，只是為了一起玩。",
  ui_story_1022_10220302_38_dialog_content = "……",
  ui_story_1022_10220302_39_dialog_content = "別開玩笑了！",
  ui_story_1022_10220302_40_dialog_content = "艾莉法，帶好光能石，準備出發。",
  ui_story_1022_10220302_41_dialog_content = "咦？！你們還要繼續追佩皮塔嗎？",
  ui_story_1022_10220302_42_dialog_content = "當然了！區區罪靈，別想擋我的路。",
  ui_story_1022_10220302_43_dialog_content = "白夜城祕典的線索在佩皮塔身上，我們別無選擇。",
  ui_story_1022_10220302_44_dialog_content = "有什麼問題，見了她再問。",
  ui_story_1022_10220302_45_dialog_content = "（卡蓮指的是「白夜城祕典其實屬於真理結社」這件事吧。）",
  ui_story_1022_10220302_46_dialog_content = "（聽卡蓮說，佩皮塔是真理結社的成員。）",
  ui_story_1022_10220302_47_dialog_content = "（既然是結社的人，為什麼會成為啟光的囚犯？佩皮塔要向啟光討債，又是什麼意思？）",
  ui_story_1022_10220302_48_dialog_content = "（問題越來越多了……）",
  ui_story_1022_10220401_1_dialog_content = "歡迎光臨——冰原上的珊瑚地！",
  ui_story_1022_10220401_2_dialog_content = "漂亮吧？詭異吧？大開眼界吧？哇哈哈，盡情捧著下巴尖叫吧！",
  ui_story_1022_10220401_3_dialog_content = "嗯，又絢麗又扭曲，和妳絕配。",
  ui_story_1022_10220401_4_dialog_content = "什麼嘛，佩皮塔一點都不興奮，掃興！",
  ui_story_1022_10220401_5_dialog_content = "我是說真的。好特別的景色，讓我大吃一驚。",
  ui_story_1022_10220401_6_dialog_content = "（只不過是之前剛看見的時候。）",
  ui_story_1022_10220401_7_dialog_content = "知道厲害就好。快來快來，好看好玩的還多著呢。",
  ui_story_1022_10220401_8_dialog_content = "哎～把我胃口吊這麼高，最好是真的有料喔。",
  ui_story_1022_10220401_9_dialog_content = "<color=#e8d9bb>本應蒼白寂靜的冰原上，忽然覆滿了地衣、珊瑚與絢麗的樹，宛如暗黑童話中的光景。</color>",
  ui_story_1022_10220401_10_dialog_content = "<color=#e8d9bb>珊瑚叢中，活動著——</color>",
  ui_story_1022_10220401_11_dialog_content = "？！",
  ui_story_1022_10220401_12_dialog_content = "（那些是……光靈？不對，眼神呆呆的，比較像暗鬼，但外表又和暗鬼大不相同。）",
  ui_story_1022_10220401_13_dialog_content = "<color=#e8d9bb>狀似光靈的生物在珊瑚叢中活動，神情呆滯、動作機械，清理著生長過分繁茂的地衣與珊瑚。</color>",
  ui_story_1022_10220401_14_dialog_content = "<color=#e8d9bb>在豔麗植物的映襯下，他們一板一眼的舉止令人寒毛直豎。</color>",
  ui_story_1022_10220401_15_dialog_content = "烏蘇拉，那邊的人是誰？",
  ui_story_1022_10220401_16_dialog_content = "那妳都不認識嗎？是珊瑚啦！",
  ui_story_1022_10220401_17_dialog_content = "不是，我是說清理珊瑚的那些……光靈？暗鬼？謎之生物？",
  ui_story_1022_10220401_18_dialog_content = "喔……妳看他們幹嘛？又沒意思。",
  ui_story_1022_10220401_19_dialog_content = "他們才不是光靈呢，光靈好玩的地方他們半點也沒繼承到。",
  ui_story_1022_10220401_20_dialog_content = "（「繼承」？也就是說，他們確實跟光靈有關係？）",
  ui_story_1022_10220401_21_dialog_content = "他們只是在這裡待久了，變得很耐用，可以幫<color=#FFB400>我們</color>做點雜工。",
  ui_story_1022_10220401_22_dialog_content = "要他們幹活都會聽，然後就一點用處也沒有了。",
  ui_story_1022_10220401_23_dialog_content = "話也說不通，玩也不好玩，隨便玩兩下就會死掉，根本比不上光靈啦！",
  ui_story_1022_10220401_24_dialog_content = "（沒有辦法交流，戰鬥力也不高……是這個意思吧？）",
  ui_story_1022_10220401_25_dialog_content = "別管他們了，我才是這裡的主人，妳要跟著我！",
  ui_story_1022_10220401_26_dialog_content = "……",
  ui_story_1022_10220402_1_dialog_content = "呼哇……今天的實驗總算是結束了。",
  ui_story_1022_10220402_2_dialog_content = "最近的測試是不是越來越折騰人了？你們覺得呢？",
  ui_story_1022_10220402_3_dialog_content = "嗯，說實話，我有點受不了了。",
  ui_story_1022_10220402_4_dialog_content = "身上到處都痛，晚上睡覺也老是做噩夢。",
  ui_story_1022_10220402_5_dialog_content = "我也差不多。",
  ui_story_1022_10220402_6_dialog_content = "還是佩皮塔厲害。明明心臟不好，安排給妳的測試又最狠，卻從來都不吭一聲。",
  ui_story_1022_10220402_7_dialog_content = "這點程度，毛毛雨啦～",
  ui_story_1022_10220402_8_dialog_content = "比起我爸爸面對的危險，我做的基本就只是躺著而已嘛。",
  ui_story_1022_10220402_9_dialog_content = "我記得……佩皮塔的爸爸是去暗面探險了，對嗎？",
  ui_story_1022_10220402_10_dialog_content = "沒錯！爸爸是啟光暗面探索隊的一員，這是非常了不起的工作！",
  ui_story_1022_10220402_11_dialog_content = "我以後也要去暗面探險。爸爸一定會以我為榮的，嘿嘿。",
  ui_story_1022_10220402_12_dialog_content = "好厲害，佩皮塔加油！我們都支持妳！",
  ui_story_1022_10220402_13_dialog_content = "不過這麼一來，下次的探訪日妳爸爸也來不了了吧？",
  ui_story_1022_10220402_14_dialog_content = "……沒、沒辦法，爸爸太忙了……",
  ui_story_1022_10220402_15_dialog_content = "妳想要什麼，我請我媽媽幫妳帶來！",
  ui_story_1022_10220402_16_dialog_content = "嗯、嗯……好，謝謝。",
  ui_story_1022_10220402_17_dialog_content = "等爸爸回來就會來看我了……一定。",
  ui_story_1022_10220402_18_dialog_content = "<color=#e8d9bb>若干年後</color>",
  ui_story_1022_10220402_19_dialog_content = "她最近怎麼樣？",
  ui_story_1022_10220402_20_dialog_content = "報告！還是和以前一樣，不愛吃的食物直接丟出來，愛吃的會要雙份。",
  ui_story_1022_10220402_21_dialog_content = "總是吵著要我們放音樂，不理會她就開始大聲唱歌。",
  ui_story_1022_10220402_22_dialog_content = "關了她這麼久，她對食物的偏好你們總該知道了。不愛吃的就別送了。",
  ui_story_1022_10220402_23_dialog_content = "是！",
  ui_story_1022_10220402_24_dialog_content = "妳是不是太寵她了？再怎麼說，她都只是個囚犯。",
  ui_story_1022_10220402_25_dialog_content = "她的體質很珍貴，心臟又那樣，若是因為營養不良倒下，蒙受損失的是我們。",
  ui_story_1022_10220402_26_dialog_content = "再說，浪費食物總是不太好。",
  ui_story_1022_10220402_27_dialog_content = "希望她會配合妳。",
  ui_story_1022_10220402_28_dialog_content = "喂，怎麼樣了啊？唱片什麼時候拿來？不會還要我自己唱吧？迷上我的歌喉了？",
  ui_story_1022_10220402_29_dialog_content = "真沒辦法，我就再服務一下粉絲吧。咳咳！♪美麗的草原～我的家～♪",
  ui_story_1022_10220402_30_dialog_content = "妳沒有見過草原吧，佩皮塔。",
  ui_story_1022_10220402_31_dialog_content = "搞什麼，又是妳？那張老臉我早就看膩了，走開走開。",
  ui_story_1022_10220402_32_dialog_content = "膩了是嗎？當年妳躺在實驗室時，見到我好像還挺高興的啊。",
  ui_story_1022_10220402_33_dialog_content = "因為沒有別人會去看妳。",
  ui_story_1022_10220402_34_dialog_content = "妳那不是來看我，只是來看看貴重的實驗品有什麼進展。",
  ui_story_1022_10220402_35_dialog_content = "實驗品的價值是堅實的，可以衡量的。",
  ui_story_1022_10220402_36_dialog_content = "而情感，即使是親情也虛無縹緲，很容易可以弄虛作假。",
  ui_story_1022_10220402_37_dialog_content = "妳對此應該再清楚不過了。",
  ui_story_1022_10220402_38_dialog_content = "……",
  ui_story_1022_10220402_39_dialog_content = "妳若真像妳所說般痛恨虛偽，而非叛逆期的耍酷、嘴上不饒人……",
  ui_story_1022_10220402_40_dialog_content = "妳便會更積極地看待我對妳……這個「實驗品」的重視。",
  ui_story_1022_10220402_41_dialog_content = "尤利西斯，過來。",
  ui_story_1022_10220402_42_dialog_content = "……",
  ui_story_1022_10220402_43_dialog_content = "？！那部裝置！",
  ui_story_1022_10220402_44_dialog_content = "（不會錯。當年，啟光的實驗員把我有缺陷的心臟換成了人造心臟。）",
  ui_story_1022_10220402_45_dialog_content = "（我從置換手術中醒來時，床邊就放著那部裝置。）",
  ui_story_1022_10220402_46_dialog_content = "（那裡面一定裝著我原生的心臟！）",
  ui_story_1022_10220402_47_dialog_content = "妳顯然知道這裡面是什麼嘛。",
  ui_story_1022_10220402_48_dialog_content = "……妳想怎樣？",
  ui_story_1022_10220402_49_dialog_content = "很簡單。發揮妳的能力，到暗面去找回「守護者一號」的核心。",
  ui_story_1022_10220402_50_dialog_content = "只要妳成功了，我就把這裡面的東西給妳。",
  ui_story_1022_10220402_51_dialog_content = "我也可以用升級後的技術，補全妳胸前那顆不完整的人造心臟。隨妳選擇。",
  ui_story_1022_10220402_52_dialog_content = "妳以為妳能擺佈我？！",
  ui_story_1022_10220402_53_dialog_content = "我才剛說過，佩皮塔，不要意氣用事。",
  ui_story_1022_10220402_54_dialog_content = "仔細想想妳想要什麼，又願意為此付出多少代價。",
  ui_story_1022_10220402_55_dialog_content = "……",
  ui_story_1022_10220402_56_dialog_content = "<color=#e8d9bb>暗面，珊瑚地</color>",
  ui_story_1022_10220402_57_dialog_content = "<color=#e8d9bb>烏蘇拉尖著嗓子指揮手下的暗鬼擺宴設席，接待她的朋友。</color>",
  ui_story_1022_10220402_58_dialog_content = "<color=#e8d9bb>佩皮塔回過神，意識到自己剛陷入了回憶。</color>",
  ui_story_1022_10220402_59_dialog_content = "<color=#e8d9bb>她眺望絢麗的珊瑚叢，想起自己為什麼會拋棄與貝利撒留的交易，來到這裡。</color>",
  ui_story_1022_10220402_60_dialog_content = "烏蘇拉。",
  ui_story_1022_10220402_61_dialog_content = "蠢貨！誰叫你們把紅珊瑚和綠珊瑚擺在同一個餐盤，醜死了！果然是低賤的螻蟻！",
  ui_story_1022_10220402_62_dialog_content = "所以說，高貴的血統多重要……妳叫我嗎，佩皮塔？",
  ui_story_1022_10220402_63_dialog_content = "我們剛認識的時候，我們談過我心臟的事，妳還記得嗎？",
  ui_story_1022_10220402_64_dialog_content = "就是他們拿走我原生的心臟——",
  ui_story_1022_10220402_65_dialog_content = "煩死啦！妳的心臟總是像被揪住一樣痛，就因為那些光靈給妳裝了個半成品。",
  ui_story_1022_10220402_66_dialog_content = "妳的事情我都記得啦，不需要囉囉嗦嗦從頭說起。",
  ui_story_1022_10220402_67_dialog_content = "當時妳說，妳也有能力製造心臟。",
  ui_story_1022_10220402_68_dialog_content = "<color=#e8d9bb>佩皮塔的目光落在烏蘇拉胸口——珊瑚枝從那裡張揚地穿出，搏動起伏。</color>",
  ui_story_1022_10220402_69_dialog_content = "<color=#e8d9bb>烏蘇拉的心臟，是用珊瑚做的。</color>",
  ui_story_1022_10220402_70_dialog_content = "當然可以！我擁有最最純粹、最最高貴的力量。",
  ui_story_1022_10220402_71_dialog_content = "用珊瑚枝幫妳做一個有力的心臟，對高貴的我來說，就像呼吸一樣簡單。",
  ui_story_1022_10220402_72_dialog_content = "什麼時候可以開始？",
  ui_story_1022_10220402_73_dialog_content = "妳總算下定決心了嗎？",
  ui_story_1022_10220402_74_dialog_content = "哼，那妳得先答應我一個條件！",
  ui_story_1022_10220501_1_dialog_content = "喵喵！菲莉詩不在的時候，竟然發生了這麼多事喵喵喵！",
  ui_story_1022_10220501_2_dialog_content = "不過，有一個好消息，菲莉詩帶來了珍貴的情報喵～",
  ui_story_1022_10220501_3_dialog_content = "關於佩皮塔嗎？！",
  ui_story_1022_10220501_4_dialog_content = "沒錯，那位小姐的事，我們知道得太少了喵。",
  ui_story_1022_10220501_5_dialog_content = "所以我聯絡了鶯歌，鶯歌又跑去翻閱了委員會的資料。",
  ui_story_1022_10220501_6_dialog_content = "佩皮塔來頭果然不小。",
  ui_story_1022_10220501_7_dialog_content = "資料顯示，委員會多年前就派出過暗面探索隊……",
  ui_story_1022_10220501_8_dialog_content = "佩皮塔的父親正是其中一員。",
  ui_story_1022_10220501_9_dialog_content = "啊？暗面探索隊的職位還是世襲的？",
  ui_story_1022_10220501_10_dialog_content = "不，PlayerName，你想一想佩皮塔與我們交戰時的表現。",
  ui_story_1022_10220501_11_dialog_content = "她沒有穿戴裝備，行動卻不受暗能影響。",
  ui_story_1022_10220501_12_dialog_content = "如果說，這是一種家族遺傳的體質，事情就很好理解了。",
  ui_story_1022_10220501_13_dialog_content = "有道理。佩皮塔的父親很可能也是同樣的體質，能在暗面行動自如。",
  ui_story_1022_10220501_14_dialog_content = "那他的探索隊應該成果不菲吧？",
  ui_story_1022_10220501_15_dialog_content = "那一支探索隊，幾乎全軍覆沒喵……",
  ui_story_1022_10220501_16_dialog_content = "全軍覆沒？！",
  ui_story_1022_10220501_17_dialog_content = "生還者只有佩皮塔的父親一個人。",
  ui_story_1022_10220501_18_dialog_content = "他能活著回來，一方面是體質特別，另一方面可能也用了一些不光彩的手段。",
  ui_story_1022_10220501_19_dialog_content = "因為他回來後不久，就簽署監護權移交同意書，把佩皮塔送進了啟光研究所。",
  ui_story_1022_10220501_20_dialog_content = "放棄了自己的女兒嗎？！",
  ui_story_1022_10220501_21_dialog_content = "這不是讓她淪為實驗品嗎？",
  ui_story_1022_10220501_22_dialog_content = "沒錯喵。所以鶯歌猜測他肯定是犯了一些錯，為了自保，才用女兒做交換。",
  ui_story_1022_10220501_23_dialog_content = "難以置信。",
  ui_story_1022_10220501_24_dialog_content = "啟光居然會有這樣的軟腳蝦。",
  ui_story_1022_10220501_25_dialog_content = "那之後，暗面探索的頻率就大幅下降，但對佩皮塔的研究一直在進行。",
  ui_story_1022_10220501_26_dialog_content = "為了讓她擁有充分的行動力和戰鬥力，委員會用人造心臟，換掉了她先天不足的心臟。",
  ui_story_1022_10220501_27_dialog_content = "咦？她的心臟是人工的？",
  ui_story_1022_10220501_28_dialog_content = "換言之，委員會沒有放棄暗面探索計畫，而是希望把佩皮塔培養成下一代的探索隊員。",
  ui_story_1022_10220501_29_dialog_content = "很可能喵～不過……",
  ui_story_1022_10220501_30_dialog_content = "人造心臟技術至今還不成熟，所以應該也有用佩皮塔做人體實驗的目的在……",
  ui_story_1022_10220501_31_dialog_content = "怎麼這樣……佩皮塔也太可憐了。",
  ui_story_1022_10220501_32_dialog_content = "是的喵。再加上佩皮塔後來察覺了委員會與她父親的交易，叛逆心大爆發。",
  ui_story_1022_10220501_33_dialog_content = "一找到機會就逃出啟光，混跡各處，現在看來是加入真理結社了喵～",
  ui_story_1022_10220501_34_dialog_content = "我終於理解了。那就是她最後的容身之處……",
  ui_story_1022_10220501_35_dialog_content = "還有一件事。佩皮塔出逃後，又祕密潛回過啟光一次。",
  ui_story_1022_10220501_36_dialog_content = "膽量不錯。那她的目的是什麼？",
  ui_story_1022_10220501_37_dialog_content = "好像是為了取回自己原生的心臟。",
  ui_story_1022_10220501_38_dialog_content = "當然她馬上就被發現了，再次開始逃亡喵～",
  ui_story_1022_10220501_39_dialog_content = "啟光通緝她，白夜城也通緝她，最終她還是被抓回啟光，接著又被送往暗面……",
  ui_story_1022_10220501_40_dialog_content = "怎麼說呢……真是非常傳奇的經歷。",
  ui_story_1022_10220501_41_dialog_content = "（難怪她會有那種藐視權威、忤逆一切的個性。）",
  ui_story_1022_10220501_42_dialog_content = "現在她甚至跟罪靈混在一起。",
  ui_story_1022_10220501_43_dialog_content = "辛苦妳了，菲莉詩。我馬上向大元帥報告。",
  ui_story_1022_10220502_1_dialog_content = "……情況就是這樣。佩皮塔在暗面也能行動自如，她的能力有目共睹。",
  ui_story_1022_10220502_2_dialog_content = "大元帥，我們該怎麼行動？",
  ui_story_1022_10220502_3_dialog_content = "若是又碰到佩皮塔，真的要坐視白夜城帶走她嗎？",
  ui_story_1022_10220502_4_dialog_content = "佩皮塔很可能知道白夜城失竊寶物的線索。",
  ui_story_1022_10220502_5_dialog_content = "啟光與白夜城同在聯合探索部隊中，進退與共，我們不能無視他們的利益。",
  ui_story_1022_10220502_6_dialog_content = "但是——",
  ui_story_1022_10220502_7_dialog_content = "當然，我們也不能無底線地讓步。",
  ui_story_1022_10220502_8_dialog_content = "鶯歌向我報告過佩皮塔的經歷了。我猜她可能有暗面探索方面的才能。",
  ui_story_1022_10220502_9_dialog_content = "因此，當即就把這個情報分享給白夜城城主了。",
  ui_story_1022_10220502_10_dialog_content = "什麼！那……他是什麼反應？",
  ui_story_1022_10220502_11_dialog_content = "明眼人都看得出，佩皮塔留在暗面，比關在監獄更有用。",
  ui_story_1022_10220502_12_dialog_content = "舒瓦茲也不是瞎子。",
  ui_story_1022_10220502_13_dialog_content = "佩皮塔若能為我們所用，充分發揮特長，所有人都會受益。",
  ui_story_1022_10220502_14_dialog_content = "不只眼下，長遠來看更加如此。",
  ui_story_1022_10220502_15_dialog_content = "靠她去掌握更多情報，在未來光靈與暗鬼的戰爭中搶佔先機……妳是想這麼說嗎？",
  ui_story_1022_10220502_16_dialog_content = "看來您也有一樣的意思。",
  ui_story_1022_10220502_17_dialog_content = "哼，不過是個小賊。只要她肯吐露祕典的線索，白夜城將不再與她為敵。",
  ui_story_1022_10220502_18_dialog_content = "竟然……不愧是大元帥！",
  ui_story_1022_10220502_19_dialog_content = "所以，你們放手去做就好。",
  ui_story_1022_10220502_20_dialog_content = "比起白夜城，佩皮塔本人恐怕還更難搞吧？哈哈哈！",
  ui_story_1022_10220502_21_dialog_content = "並非如此！若非您及時談判，白夜城的人鐵定會把佩皮塔送進監獄。",
  ui_story_1022_10220502_22_dialog_content = "他們那位異端調查組的組長，對真理結社的成員非常執著。",
  ui_story_1022_10220502_23_dialog_content = "什麼？不再懲治佩皮塔？！",
  ui_story_1022_10220502_24_dialog_content = "城主大人應該知道啊！佩皮塔是真理結社的成員！",
  ui_story_1022_10220502_25_dialog_content = "城主大人是為全體光靈的長遠利益考量。",
  ui_story_1022_10220502_26_dialog_content = "而且，我們仍然有權去問出祕典的下落。",
  ui_story_1022_10220502_27_dialog_content = "那也不能只因為這樣，就輕易放過她……",
  ui_story_1022_10220502_28_dialog_content = "我知道妳對真理結社的仇恨。妳為此踏上異端調查之路，表現一直很出色。",
  ui_story_1022_10220502_29_dialog_content = "不過，妳的仇人是否真的來自真理結社，多年來一直沒有定論。",
  ui_story_1022_10220502_30_dialog_content = "就這麼放過她……不行……不可能……",
  ui_story_1022_10220502_31_dialog_content = "妳給我冷靜點！",
  ui_story_1022_10220502_32_dialog_content = "這裡是暗面。放任情感支配自己，只會白白葬送妳和同伴的性命！",
  ui_story_1022_10220502_33_dialog_content = "……對不起，殿下，是我失態了。",
  ui_story_1022_10220502_34_dialog_content = "我……一個人冷靜一下。",
  ui_story_1022_10220502_35_dialog_content = "……",
  ui_story_1022_10220601_1_dialog_content = "不能放過她……不能放過她！哪怕只有我一個人，我也要讓她付出代價。",
  ui_story_1022_10220601_2_dialog_content = "真理結社的傢伙……統統該死！",
  ui_story_1022_10220601_3_dialog_content = "妳果然要做傻事。",
  ui_story_1022_10220601_4_dialog_content = "殿下！",
  ui_story_1022_10220601_5_dialog_content = "妳手上拿的是什麼？",
  ui_story_1022_10220601_6_dialog_content = "這是……白夜指針。從前保管在白夜城的神殿裡，能與受過祝福的物品共鳴。",
  ui_story_1022_10220601_7_dialog_content = "自從來到暗面後，白夜指針的反應就一直很劇烈。",
  ui_story_1022_10220601_8_dialog_content = "我想，這附近也許還有白夜城遺失的珍寶。",
  ui_story_1022_10220601_9_dialog_content = "指針現在指向哪裡？該不會恰好指向烏蘇拉離開的方位吧？",
  ui_story_1022_10220601_10_dialog_content = "我……",
  ui_story_1022_10220601_11_dialog_content = "妳想一個人去追蹤罪靈和佩皮塔，順便替白夜城找回幾件失物？",
  ui_story_1022_10220601_12_dialog_content = "妳未免太高估自己，也太小看妳的同伴了！",
  ui_story_1022_10220601_13_dialog_content = "若是一個人就能做到一切，我們何必成立聯合探索部隊？",
  ui_story_1022_10220601_14_dialog_content = "其實……坦白說，我感應到的巨大光能團也在同一個方向。",
  ui_story_1022_10220601_15_dialog_content = "？！",
  ui_story_1022_10220601_16_dialog_content = "罪靈是我們共同的敵人，別的我就不置喙了。",
  ui_story_1022_10220601_17_dialog_content = "妳……哼。",
  ui_story_1022_10220601_18_dialog_content = "組長，我也要去見佩皮塔……不是為了懲罰，而是為了救助。",
  ui_story_1022_10220601_19_dialog_content = "從未知力量手中拯救我們的世界與……友人，才是異端調查的目的。我是這樣想的。",
  ui_story_1022_10220601_20_dialog_content = "艾莉法……妳比我想的更成熟、更有智慧。反而是我……",
  ui_story_1022_10220601_21_dialog_content = "對不起，殿下，還有……其他人，我被私仇蒙蔽了理智。",
  ui_story_1022_10220601_22_dialog_content = "但只要一想到真理結社，我就——！",
  ui_story_1022_10220601_23_dialog_content = "您無須馬上放下仇恨，誰都知道那是強人所難。",
  ui_story_1022_10220601_24_dialog_content = "但至少要注重安全吧。我們正是為此才成立部隊，彼此照應的，不是嗎？",
  ui_story_1022_10220601_25_dialog_content = "我……",
  ui_story_1022_10220601_26_dialog_content = "一起出發吧！目標，烏蘇拉的大本營！",
  ui_story_1022_10220601_27_dialog_content = "<color=#e8d9bb>一行人循著白夜指針前進。行出一陣後，大地開始佈滿扭曲而絢麗的植物。</color>",
  ui_story_1022_10220601_28_dialog_content = "哇喔，這個地方……",
  ui_story_1022_10220601_29_dialog_content = "美麗而詭異，攝人心魄……多麼不祥。",
  ui_story_1022_10220601_30_dialog_content = "看來我們方向沒錯。探索隊員說過，佩皮塔帶領他們發現的正是一片珊瑚地。",
  ui_story_1022_10220601_31_dialog_content = "地貌如此詭異，或許正是受到烏蘇拉的影響。",
  ui_story_1022_10220601_32_dialog_content = "登記為「<color=#FFB400>未知區域44區</color>」。",
  ui_story_1022_10220601_33_dialog_content = "PlayerName，跟我來，我有件事要問你。",
  ui_story_1022_10220601_34_dialog_content = "怎麼啦，卡蓮？",
  ui_story_1022_10220601_35_dialog_content = "你之前說，你感應到一個巨大的光能團，對嗎？",
  ui_story_1022_10220601_36_dialog_content = "你說，那會不會也是白夜城遺失的祕寶？",
  ui_story_1022_10220601_37_dialog_content = "咦？！白夜指針指向的那個嗎？",
  ui_story_1022_10220601_38_dialog_content = "我不能完全排除這樣的可能，但我總覺得不是……",
  ui_story_1022_10220601_39_dialog_content = "我也說不上來，就是一種直覺。那個光能團，給我一種溫暖又親近的感覺……",
  ui_story_1022_10220601_40_dialog_content = "好吧，沒什麼，我只是問問。我們回去吧。",
  ui_story_1022_10220601_41_dialog_content = "卡蓮……妳沒事吧？感覺妳身上的擔子好重。",
  ui_story_1022_10220601_42_dialog_content = "代表白夜城來到這裡，一定很辛苦。",
  ui_story_1022_10220601_43_dialog_content = "可能我確實有點心急了。經歷了最近這些事，急著想達成點什麼。",
  ui_story_1022_10220601_44_dialog_content = "而不是像困獸一樣，無處發揮。",
  ui_story_1022_10220601_45_dialog_content = "你說得對，我不該這麼焦躁。",
  ui_story_1022_10220601_46_option_content = "我又還沒說……",
  ui_story_1022_10220601_47_dialog_content = "反正下一句就要說了吧？！",
  ui_story_1022_10220601_48_dialog_content = "咳！倒也沒錯。",
  ui_story_1022_10220601_49_option_content = "沒什麼該不該的",
  ui_story_1022_10220601_50_dialog_content = "妳焦躁我也能理解。我的心情……也是一樣。",
  ui_story_1022_10220601_51_dialog_content = "……謝謝。這句話比什麼安慰都管用。",
  ui_story_1022_10220601_52_dialog_content = "嗯？他們那邊在騷動什麼？快去看看。",
  ui_story_1022_10220601_53_dialog_content = "不祥的氣息越來越濃厚……邪惡的神明曾在此降臨……",
  ui_story_1022_10220601_54_dialog_content = "屍體？！這是……光靈的屍體嗎？",
  ui_story_1022_10220601_55_dialog_content = "面容又不太像光靈，卻也不像暗鬼，究竟是什麼？",
  ui_story_1022_10220601_56_dialog_content = "是形似光靈的某種生物。他們身體裡有光能的痕跡。",
  ui_story_1022_10220601_57_dialog_content = "只不過，光能幾乎被徹底抽乾了。",
  ui_story_1022_10220601_58_dialog_content = "誰做了這麼殘忍的事？！用這種方式殺死了他們嗎……",
  ui_story_1022_10220601_59_dialog_content = "我一開始也這樣認為，但調查後發現不是。",
  ui_story_1022_10220601_60_dialog_content = "他們並非因光能乾涸而死，而是很可能長期處於光能枯竭的狀態。",
  ui_story_1022_10220601_61_dialog_content = "怎麼會這樣？光靈能夠這樣活著嗎？",
  ui_story_1022_10220601_62_dialog_content = "死去的光靈、枯竭的光能、白夜城的失物……",
  ui_story_1022_10220601_63_dialog_content = "可惡！污穢的暗鬼，究竟要侵蝕光靈到怎樣的地步？！",
  ui_story_1022_10220601_64_dialog_content = "有沒有可能，是你們光靈佔據了原本屬於「日蝕」的東西？",
  ui_story_1022_10220601_65_dialog_content = "就連你們生活的宜居地帶，也是……",
  ui_story_1022_10220601_66_dialog_content = "啊！",
  ui_story_1022_10220601_67_dialog_content = "怎麼了，PlayerName？",
  ui_story_1022_10220601_68_dialog_content = "沒……沒什麼。",
  ui_story_1022_10220601_69_dialog_content = "（剛才隱約聽到的聲音，是我的錯覺嗎？）",
  ui_story_1022_10220701_1_dialog_content = "大量的屍體都像是同一時間死去的。",
  ui_story_1022_10220701_2_dialog_content = "珊瑚叢中還散落著奇怪的金屬碎片……這裡究竟發生過什麼事？",
  ui_story_1022_10220701_3_dialog_content = "也許我有辦法揭曉答案。",
  ui_story_1022_10220701_4_dialog_content = "也只能靠你了。",
  ui_story_1022_10220701_5_dialog_content = "小心點，PlayerName，千萬不要勉強。",
  ui_story_1022_10220701_6_option_content = "感應",
  ui_story_1022_10220701_7_dialog_content = "這、這是？！",
  ui_story_1022_10220701_8_dialog_content = "<color=#e8d9bb>耳畔迴盪著機械的轟鳴。</color>",
  ui_story_1022_10220701_9_dialog_content = "<color=#e8d9bb>大地隨著機械的運轉微微震顫。</color>",
  ui_story_1022_10220701_10_dialog_content = "<color=#e8d9bb>無數古怪的機器聳向天空。機器之間，生出絢麗而扭曲的珊瑚、植物。</color>",
  ui_story_1022_10220701_11_dialog_content = "<color=#e8d9bb>這幅景象，比單純的珊瑚冰原更加震撼。</color>",
  ui_story_1022_10220701_12_dialog_content = "（緋發現的金屬碎片，像是這些機器的殘骸。）",
  ui_story_1022_10220701_13_dialog_content = "（這裡是……珊瑚地的<color=#FFB400>過去</color>嗎？）",
  ui_story_1022_10220701_14_dialog_content = "（啊！管理機器的是那些類似光靈的生物。他們一直生活在這裡嗎？）",
  ui_story_1022_10220701_15_dialog_content = "<color=#e8d9bb>意識到生物的存在後，才發現這個地方是多麼安靜。</color>",
  ui_story_1022_10220701_16_dialog_content = "<color=#e8d9bb>除了機器運作時的嗡鳴聲，幾乎什麼聲音都沒有。</color>",
  ui_story_1022_10220701_17_dialog_content = "（他們彼此之間沒有任何交流，表情、行動也非常呆板，只是按部就班地完成工作。）",
  ui_story_1022_10220701_18_dialog_content = "（這樣的表現，倒有點像低級暗鬼，但外表分明又是光靈？）",
  ui_story_1022_10220701_19_dialog_content = "啊啊……這麼多年了，會說話的還是只有我們幾個。",
  ui_story_1022_10220701_20_dialog_content = "（嗚哇！嚇死我了，原來還是有會說話的個體啊。）",
  ui_story_1022_10220701_21_dialog_content = "自我誕生以來，這裡就是這樣。除了機器，就是沒有思想、感情與語言的同類……",
  ui_story_1022_10220701_22_dialog_content = "我已經快要分不清機器與同類了。",
  ui_story_1022_10220701_23_dialog_content = "神啊，為什麼我們要過著這樣的生活？",
  ui_story_1022_10220701_24_dialog_content = "我們就不能離開這個死氣沉沉的地方，到外面去看看嗎？",
  ui_story_1022_10220701_25_dialog_content = "萬萬使不得！",
  ui_story_1022_10220701_26_dialog_content = "我年輕的時候，有幾個像你我一樣能說話的同類結伴逃去了外頭……",
  ui_story_1022_10220701_27_dialog_content = "然後呢？！他們看到了什麼？",
  ui_story_1022_10220701_28_dialog_content = "死亡……",
  ui_story_1022_10220701_29_dialog_content = "？！",
  ui_story_1022_10220701_30_dialog_content = "外面有一個地方，像熔爐一樣火熱，逃離的同伴一瞬間就被燒成了灰燼。",
  ui_story_1022_10220701_31_dialog_content = "那之後就沒有人再敢離開了，偶爾走出去的也從來沒有回來過。",
  ui_story_1022_10220701_32_dialog_content = "怎麼會……難道我們就沒有任何希望了嗎？只能被困到死去？",
  ui_story_1022_10220701_33_dialog_content = "這也太殘酷了……",
  ui_story_1022_10220701_34_dialog_content = "？！",
  ui_story_1022_10220701_35_dialog_content = "（嗚哇，突然全都朝我看過來了！）",
  ui_story_1022_10220701_36_dialog_content = "哈、哈哈，你們好……？",
  ui_story_1022_10220701_37_dialog_content = "外來者嗎？我真羡慕你能到外面去。",
  ui_story_1022_10220701_38_dialog_content = "為什麼要來這鬼地方？這裡除了機器和珊瑚，什麼也沒有。",
  ui_story_1022_10220701_39_dialog_content = "對了，千萬不要吃那些珊瑚。那會把你的血液變成噁心的乳白色。",
  ui_story_1022_10220701_40_dialog_content = "就跟我們一樣。",
  ui_story_1022_10220701_41_dialog_content = "<color=#e8d9bb>面容近似光靈的生物露出了自虐的笑容。</color>",
  ui_story_1022_10220701_42_dialog_content = "吃了珊瑚，血液會變成白色嗎？我知道了，謝謝你們提醒。",
  ui_story_1022_10220701_43_dialog_content = "除了珊瑚，你們就沒有其他食物了嗎？",
  ui_story_1022_10220701_44_dialog_content = "沒有了。珊瑚、珊瑚、珊瑚，該死的珊瑚！",
  ui_story_1022_10220701_45_dialog_content = "這個地方就像被詛咒了，每天都會冒出數不清的苔蘚和珊瑚。",
  ui_story_1022_10220701_46_dialog_content = "必須馬上清理掉，機器才能正常運轉。",
  ui_story_1022_10220701_47_dialog_content = "尤其是那個「爐子」，不能讓它停下來。",
  ui_story_1022_10220701_48_dialog_content = "一生只能圍著爐子和雜草度過，沒有絲毫尊嚴……我們一定也被詛咒了。",
  ui_story_1022_10220701_49_dialog_content = "除了我，還有別人來過嗎？像是……暗鬼？",
  ui_story_1022_10220701_50_dialog_content = "有一個罪靈偶爾會來，對吧？",
  ui_story_1022_10220701_51_dialog_content = "沒錯，名叫「尤度」的罪靈。",
  ui_story_1022_10220701_52_dialog_content = "罪靈？！",
  ui_story_1022_10220701_53_dialog_content = "他會殺死我們。",
  ui_story_1022_10220701_54_dialog_content = "他會殺死我們。",
  ui_story_1022_10220701_55_dialog_content = "他會殺死我們。",
  ui_story_1022_10220701_56_dialog_content = "？！",
  ui_story_1022_10220701_57_dialog_content = "某一天，尤度認為我們不再具備價值，便殺死了我們所有人。",
  ui_story_1022_10220701_58_dialog_content = "我們早已死去，一生被困在此處。",
  ui_story_1022_10220701_59_dialog_content = "一生被困在此處。",
  ui_story_1022_10220701_60_dialog_content = "一生被困在此處。",
  ui_story_1022_10220701_61_dialog_content = "啊！！！",
  ui_story_1022_10220701_62_dialog_content = "PlayerName！你還好吧！你的臉色好蒼白。",
  ui_story_1022_10220701_63_dialog_content = "我……感應到這些死者殘存的意念。",
  ui_story_1022_10220701_64_dialog_content = "……",
  ui_story_1022_10220701_65_dialog_content = "靈魂至今被困在這裡嗎……願你們得解脫。",
  ui_story_1022_10220701_66_dialog_content = "那個叫尤度的罪靈屠殺了所有人？！不可饒恕！",
  ui_story_1022_10220701_67_dialog_content = "相比之下，烏蘇拉算是攻擊性低了。",
  ui_story_1022_10220701_68_dialog_content = "你的想法很危險。罪靈的本性都一樣，不能輕易放鬆警惕。",
  ui_story_1022_10220701_69_dialog_content = "對不起。",
  ui_story_1022_10220701_70_dialog_content = "不用緊張，我只是希望你能保持必要的危機意識。",
  ui_story_1022_10220701_71_dialog_content = "從你感應到的內容判斷，這個地方從前算是一個科技基地。",
  ui_story_1022_10220701_72_dialog_content = "工人是近似光靈的不明生物，監管者則是罪靈尤度。",
  ui_story_1022_10220701_73_dialog_content = "嗯，我也是這樣想。",
  ui_story_1022_10220701_74_dialog_content = "工人大多數沒有感情、思想和語言，只有少數幾個例外。",
  ui_story_1022_10220701_75_dialog_content = "他們的主要任務是拔除珊瑚、苔蘚之類的孳生物，維持機器運轉。",
  ui_story_1022_10220701_76_dialog_content = "其中最重要的機器是一個「爐子」？",
  ui_story_1022_10220701_77_dialog_content = "為什麼一直有珊瑚和苔蘚長出來？會不會跟烏蘇拉有關？",
  ui_story_1022_10220701_78_dialog_content = "不無可能。也許烏蘇拉走到哪裡，哪裡就會長出珊瑚。",
  ui_story_1022_10220701_79_dialog_content = "換言之，烏蘇拉從前也在科技基地附近？說不定還跟尤度有交情。",
  ui_story_1022_10220701_80_dialog_content = "這麼一想，她果然很危險……",
  ui_story_1022_10220701_81_dialog_content = "佩皮塔卻跟她成為了朋友。既然是朋友，應該不會對佩皮塔不利……",
  ui_story_1022_10220701_82_dialog_content = "真不知是幸運還是不幸，佩皮塔一來暗面就發現了珊瑚地。",
  ui_story_1022_10220701_83_dialog_content = "我能插一句嗎？",
  ui_story_1022_10220701_84_dialog_content = "怎麼了？",
  ui_story_1022_10220701_85_dialog_content = "這個地方的暗能非常稀薄，幾乎不像是在暗面了。",
  ui_story_1022_10220701_86_dialog_content = "我在想，白夜指針指向的寶物，會不會像我們的<color=#FFB400>光能石</color>一樣，可以隔絕暗能？",
  ui_story_1022_10220701_87_dialog_content = "猜測無益，盡快過去看看吧。",
  ui_story_1022_10220701_88_dialog_content = "烏蘇拉不會離我們太遠，務必小心戒備。",
  ui_story_1022_10220800_1_dialog_content = "<color=#e8d9bb>珊瑚地深處，佩皮塔眺望著扭曲的美景，若有所思。</color>",
  ui_story_1022_10220800_2_dialog_content = "佩皮塔，條件考慮得怎麼樣了？",
  ui_story_1022_10220800_3_dialog_content = "妳回來了。外面怎麼回事？",
  ui_story_1022_10220800_4_dialog_content = "不值一提，幾隻螻蟻罷了。高貴的烏蘇拉大人看都懶得多看一眼。",
  ui_story_1022_10220800_5_dialog_content = "倒是妳，快點回答我啊。",
  ui_story_1022_10220800_6_dialog_content = "只要妳點頭，我馬上可以用珊瑚枝做一個心臟給妳。",
  ui_story_1022_10220800_7_dialog_content = "條件是……「我永遠留下來陪妳玩」嗎？",
  ui_story_1022_10220800_8_dialog_content = "不是「陪我玩」，是「和我玩」！妳也想和我一起玩吧？妳和我玩時很開心呀！",
  ui_story_1022_10220800_9_dialog_content = "是啊，我很開心，很少見到誰能跟我一樣瘋。",
  ui_story_1022_10220800_10_dialog_content = "就是說啊！所以答應我吧，我馬上換掉妳的心臟。",
  ui_story_1022_10220800_11_dialog_content = "這樣妳的血也會變成高貴的白色，再也不會害我發瘋了，妳就可以永遠留下來。",
  ui_story_1022_10220800_12_dialog_content = "……烏蘇拉。",
  ui_story_1022_10220800_13_dialog_content = "要答應我了嗎？！",
  ui_story_1022_10220800_14_dialog_content = "妳還記得我們剛認識時的事嗎？",
  ui_story_1022_10220800_15_dialog_content = "幹嘛，突然提那麼討厭的往事。",
  ui_story_1022_10220800_16_dialog_content = "……",
  ui_story_1022_10220800_17_dialog_content = "（我……怎麼了？這裡是哪裡？）",
  ui_story_1022_10220800_18_dialog_content = "嘎！！",
  ui_story_1022_10220800_19_dialog_content = "哈、哈……哈哈哈，就這點程度嗎？再來啊！",
  ui_story_1022_10220800_20_dialog_content = "嘎——！",
  ui_story_1022_10220800_21_dialog_content = "唔呃！心臟又在作痛……可惡，可惡……可惡！",
  ui_story_1022_10220800_22_dialog_content = "（要是我有一顆健康的心臟，一定不會這樣……）",
  ui_story_1022_10220800_23_dialog_content = "（我想起來了。我跟著結社來暗面探索，一個人貪玩，碰到了成群的暗鬼。）",
  ui_story_1022_10220800_24_dialog_content = "（由於心臟無力，即使拼命抵抗，還是被抓住了。）",
  ui_story_1022_10220800_25_dialog_content = "（不愧是我啊，連死法都這麼亂來，哈哈、哈！）",
  ui_story_1022_10220800_26_dialog_content = "哈哈哈哈哈！",
  ui_story_1022_10220800_27_dialog_content = "什麼啊，難得有光靈過來，我才從長～長長長的休眠裡醒來的。",
  ui_story_1022_10220800_28_dialog_content = "迷迷糊糊過來一看，居然是個瘋子。",
  ui_story_1022_10220800_29_dialog_content = "誰？！",
  ui_story_1022_10220800_30_dialog_content = "不過，瘋就瘋吧。妳的血液和心臟——",
  ui_story_1022_10220800_31_dialog_content = "<color=#FFB400>歸·我·啦～</color>",
  ui_story_1022_10220800_32_dialog_content = "<color=#e8d9bb>貌如幼女的暗鬼一笑，露出尖利的虎牙。</color>",
  ui_story_1022_10220800_33_dialog_content = "<color=#e8d9bb>襯著她天真而殘酷的笑臉，令人遍體生寒。</color>",
  ui_story_1022_10220800_34_dialog_content = "哈哈……",
  ui_story_1022_10220800_35_dialog_content = "又笑！有什麼好笑的？妳馬上要完蛋了，要被我烏蘇拉大人吃乾抹淨了，知道嗎？",
  ui_story_1022_10220800_36_dialog_content = "妳一個長尖牙的怪物，居然嫌我瘋，不好笑嗎？",
  ui_story_1022_10220800_37_dialog_content = "哼，這尖牙可是高貴血族的象徵，妳懂什麼？",
  ui_story_1022_10220800_38_dialog_content = "血族？名字這麼酷，不就是要喝人血嗎？",
  ui_story_1022_10220800_39_dialog_content = "竟敢藐視我！我要把妳吸乾，一滴不剩！吸成一張癟癟的人皮！",
  ui_story_1022_10220800_40_dialog_content = "哈哈哈哈！稀奇，真稀奇。",
  ui_story_1022_10220800_41_dialog_content = "你佩皮塔姥姥人見人愛，走到哪裡都有喝不完的酒，交不完的朋友。",
  ui_story_1022_10220800_42_dialog_content = "還是頭一回見人要喝我的血。怎麼，這是妳扭曲的愛的表現？",
  ui_story_1022_10220800_43_dialog_content = "放屁！我才不愛妳，烏蘇拉只愛爺爺一個人！",
  ui_story_1022_10220800_44_dialog_content = "我喝妳的血，是要把妳變成奴僕，一輩子奴役妳，讓妳再也不能用那種藐視的眼神看我！",
  ui_story_1022_10220800_45_dialog_content = "奴役？",
  ui_story_1022_10220800_46_dialog_content = "哼，知道害怕了？我不介意妳露出一點恐懼、求饒的表情喔。",
  ui_story_1022_10220800_47_dialog_content = "唔……不要。",
  ui_story_1022_10220800_48_dialog_content = "妳、妳什麼時候拿在手上的，快放下！",
  ui_story_1022_10220800_49_dialog_content = "殺我可以，奴役我不行。",
  ui_story_1022_10220800_50_dialog_content = "<color=#FFB400>不自由，毋寧死！</color>",
  ui_story_1022_10220800_51_dialog_content = "<color=#e8d9bb>佩皮塔一把將珊瑚枝捅進胸口，鮮血噴湧而出。</color>",
  ui_story_1022_10220800_52_dialog_content = "……！",
  ui_story_1022_10220800_53_dialog_content = "嗚哇……是血！紅色的……血！嗚哇啊啊啊啊啊啊——！！",
  ui_story_1022_10220800_54_dialog_content = "嘎！！",
  ui_story_1022_10220800_55_dialog_content = "救命啊！",
  ui_story_1022_10220800_56_dialog_content = "家主大人，求您放過我吧！饒了我嗚哇啊啊！！",
  ui_story_1022_10220800_57_dialog_content = "血……可恨的血！喂，殺他們時別讓血流出來！",
  ui_story_1022_10220800_58_dialog_content = "（日蝕語）是！",
  ui_story_1022_10220800_59_dialog_content = "嗚啊啊啊啊！",
  ui_story_1022_10220800_60_dialog_content = "唔呃！不是說了嗎，不准讓血流出來！你們是我的「新朋友」吧？要聽我的才行！",
  ui_story_1022_10220800_61_dialog_content = "（日蝕語）是，烏蘇拉大人！我們盡量。",
  ui_story_1022_10220800_62_dialog_content = "光會嘴上答應，沒用的東西。",
  ui_story_1022_10220800_63_dialog_content = "我要忍耐……我的「新神」比所謂的「真理之主」更偉大。",
  ui_story_1022_10220800_64_dialog_content = "清洗吧，降臨吧，我的神啊！",
  ui_story_1022_10220800_65_dialog_content = "唔呃……休眠太久，我都忘記了。",
  ui_story_1022_10220800_66_dialog_content = "我已經接受「日蝕」的圓環，不再需要血，見不得血了！",
  ui_story_1022_10220800_67_dialog_content = "喝血奶、泡血澡的快樂童年結束了……嗚哇哇哇哇！爺爺，爺爺！",
  ui_story_1022_10220800_68_dialog_content = "（突然歇斯底里地哭起來了？叫著「爺爺」的樣子怪可憐的。）",
  ui_story_1022_10220800_69_dialog_content = "（那什麼爺爺丟她一個人在這裡？八成也跟我爸一樣人渣吧。）",
  ui_story_1022_10220800_70_dialog_content = "喂，妳沒事吧？咳、咳……對了，有事的是我啊，哈哈。",
  ui_story_1022_10220800_71_dialog_content = "我才沒事，高貴的我怎麼會有事？",
  ui_story_1022_10220800_72_dialog_content = "唔咕！妳又想幹什麼……",
  ui_story_1022_10220800_73_dialog_content = "別想靠流血制服我。我、我不僅能見血，還能喝呢！",
  ui_story_1022_10220800_74_dialog_content = "哇靠，妳怎麼突然舔我傷口？妳是變態嗎？",
  ui_story_1022_10220800_75_dialog_content = "嗚嗚，好難受……",
  ui_story_1022_10220800_76_dialog_content = "<color=#e8d9bb>烏蘇拉眼角滲出了乳白色的眼淚。</color>",
  ui_story_1022_10220800_77_dialog_content = "知道難受就別靠過來——",
  ui_story_1022_10220800_78_dialog_content = "呃、呃呃——呃啊啊啊啊！",
  ui_story_1022_10220800_79_dialog_content = "<color=#e8d9bb>驀地，猶如被某種原始的力量觸碰，烏蘇拉抽搐、慘叫，乳白的眼淚不斷溢出。</color>",
  ui_story_1022_10220800_80_dialog_content = "症狀這麼嚴重？！",
  ui_story_1022_10220800_81_dialog_content = "呃啊啊啊！",
  ui_story_1022_10220800_82_dialog_content = "（哇啊，她這是要失控了？！我得快跑，但……可惡，失血太多了！）",
  ui_story_1022_10220800_83_dialog_content = "佩……蒂！佩蒂，大大大……！",
  ui_story_1022_10220800_84_dialog_content = "布娃娃？哇呀！",
  ui_story_1022_10220800_85_dialog_content = "<color=#e8d9bb>烏蘇拉全身抽搐，卻仍掙扎著召喚出一隻灰撲撲的玩偶，不由分說拖走佩皮塔。</color>",
  ui_story_1022_10220800_86_dialog_content = "<color=#e8d9bb>轟！乳白色的眼淚滴落地面，將佩皮塔瞬息前的所在處炸成了一片煙塵。</color>",
  ui_story_1022_10220800_87_dialog_content = "（她……救了我？）",
  ui_story_1022_10220800_88_dialog_content = "（她自己又怎麼樣？有沒有被捲進爆炸？糟糕，眼睛睜不開……我對自己下手還真狠。）",
  ui_story_1022_10220800_89_dialog_content = "（今天……果然是我的葬身之日嗎？）",
  ui_story_1022_10220800_90_dialog_content = "<color=#e8d9bb>許久之後。</color>",
  ui_story_1022_10220800_91_dialog_content = "……",
  ui_story_1022_10220800_92_dialog_content = "（該說不愧是我嗎？居然還活著。）",
  ui_story_1022_10220800_93_dialog_content = "妳的心臟是怎麼回事？",
  ui_story_1022_10220800_94_dialog_content = "烏蘇拉？",
  ui_story_1022_10220800_95_dialog_content = "那是啟光的技術吧？不是妳原本的心臟。",
  ui_story_1022_10220800_96_dialog_content = "妳為什麼要救我？",
  ui_story_1022_10220800_97_dialog_content = "哼，本來以為加入日蝕，就能得到永不忤逆我的新朋友。",
  ui_story_1022_10220800_98_dialog_content = "但他們都跟廢物沒兩樣，一群螻蟻，配不上高貴的我。",
  ui_story_1022_10220800_99_dialog_content = "但是，妳不錯。",
  ui_story_1022_10220800_100_dialog_content = "<size=30>還會關心我。</size>",
  ui_story_1022_10220800_101_dialog_content = "哈哈……",
  ui_story_1022_10220800_102_dialog_content = "又笑！",
  ui_story_1022_10220800_103_dialog_content = "妳這是……看上我了嗎？",
  ui_story_1022_10220800_104_dialog_content = "不行嗎？這是妳的榮幸，給我高興、狂喜、手舞足蹈吧！",
  ui_story_1022_10220800_105_dialog_content = "啟光製造的心臟，不管多好，都會害妳受啟光控制。",
  ui_story_1022_10220800_106_dialog_content = "我大可以做個新的心臟給妳！我有這個本事！",
  ui_story_1022_10220800_107_dialog_content = "當時我是怎麼回答的，妳還記得嗎？",
  ui_story_1022_10220800_108_dialog_content = "當然記得！妳拒絕了我，說「不用了，我還想自己再掙扎一下」。",
  ui_story_1022_10220800_109_dialog_content = "結果妳看，還是乖乖回到我身邊了吧？",
  ui_story_1022_10220800_110_dialog_content = "妳靠著這個心臟，根本不可能掙扎出什麼結果來。",
  ui_story_1022_10220800_111_dialog_content = "是啊，這真是一顆糟糕的心臟。",
  ui_story_1022_10220800_112_dialog_content = "<color=#e8d9bb>我一直痛恨著它，想著「要是我有一顆完美的心臟就好了」。</color>",
  ui_story_1022_10220800_113_dialog_content = "<color=#e8d9bb>強壯、健康的心臟，不再受制於人，能夠一直戰鬥到精疲力竭。</color>",
  ui_story_1022_10220800_114_dialog_content = "<color=#e8d9bb>因此，明知道烏蘇拉可能會提什麼條件，仍然來到這裡。</color>",
  ui_story_1022_10220800_115_dialog_content = "<color=#e8d9bb>比起睥睨我的貝利撒留，至少烏蘇拉會平等待我。</color>",
  ui_story_1022_10220800_116_dialog_content = "<color=#e8d9bb>然而，那條件——</color>",
  ui_story_1022_10220800_117_dialog_content = "<color=#FFB400>「永遠留下來吧。」</color>",
  ui_story_1022_10220800_118_dialog_content = "<color=#e8d9bb>聽過之後，再望向無際的冰原、扭曲卻絢麗的珊瑚，我的心情竟完全不同了。</color>",
  ui_story_1022_10220800_119_dialog_content = "<color=#e8d9bb>從今以後，這就是我的全部嗎？</color>",
  ui_story_1022_10220800_120_dialog_content = "<color=#e8d9bb>……不要。</color>",
  ui_story_1022_10220800_121_dialog_content = "<color=#e8d9bb>世界那麼大。</color>",
  ui_story_1022_10220800_122_dialog_content = "<color=#e8d9bb>我，還沒有看過草原呢。</color>",
  ui_story_1022_10220800_123_dialog_content = "今天我的回答也是一樣。",
  ui_story_1022_10220800_124_dialog_content = "不用了，烏蘇拉。",
  ui_story_1022_10220800_125_dialog_content = "我還想自己再掙扎一下。",
  ui_story_1022_10220901_1_dialog_content = "妳敢耍我！",
  ui_story_1022_10220901_2_dialog_content = "抱歉啦，朋友，跟妳在一起真的很開心。",
  ui_story_1022_10220901_3_dialog_content = "但每天無縫黏在一起還是算了吧～有句話說「君子之交淡如水」，聽過吧？",
  ui_story_1022_10220901_4_dialog_content = "……",
  ui_story_1022_10220901_5_dialog_content = "帶上來。",
  ui_story_1022_10220901_6_dialog_content = "（日蝕語）是！",
  ui_story_1022_10220901_7_dialog_content = "帶什麼上來？我應該沒有能被妳綁架威脅的至親吧？",
  ui_story_1022_10220901_8_dialog_content = "佩、佩蒂！可惡……烏蘇拉，妳早就抓到佩蒂了嗎？",
  ui_story_1022_10220901_9_dialog_content = "早就抓到了，但我還是忍到現在，還不能證明我對妳多好嗎？",
  ui_story_1022_10220901_10_dialog_content = "我都這樣……都這樣了！妳為什麼還是總想著要離開？！",
  ui_story_1022_10220901_11_dialog_content = "答案，我當時不就說過了嗎？",
  ui_story_1022_10220901_12_dialog_content = "<color=#FFB400>不自由，毋寧死！</color>",
  ui_story_1022_10220901_13_dialog_content = "嘎……",
  ui_story_1022_10220901_14_dialog_content = "攔住她！",
  ui_story_1022_10220901_15_dialog_content = "（日蝕語）服從烏蘇拉大人的命令！",
  ui_story_1022_10220901_16_dialog_content = "嘎！！",
  ui_story_1022_10220901_17_dialog_content = "哼，就憑你們？",
  ui_story_1022_10220901_18_dialog_content = "嘎……",
  ui_story_1022_10220901_19_dialog_content = "妳、妳太亂來了！妳這是在自殺！",
  ui_story_1022_10220901_20_dialog_content = "那妳倒是住手讓我跑啊。",
  ui_story_1022_10220901_21_dialog_content = "嘎……",
  ui_story_1022_10220901_22_dialog_content = "唔呃……哈、哈哈，烏蘇拉，妳這些部下都跟提線木偶一樣，不夠看啊。",
  ui_story_1022_10220901_23_dialog_content = "不奉陪囉，拜拜！",
  ui_story_1022_10220901_24_dialog_content = "不准走！",
  ui_story_1022_10220901_25_dialog_content = "呃啊……",
  ui_story_1022_10220901_26_dialog_content = "心臟開始痛了吧？妳心氣太高了，那顆破爛根本撐不住妳。",
  ui_story_1022_10220901_27_dialog_content = "早點認清自己的極限吧！",
  ui_story_1022_10220901_28_dialog_content = "才不要！",
  ui_story_1022_10220901_29_dialog_content = "唔……！",
  ui_story_1022_10220901_30_dialog_content = "都給我上！",
  ui_story_1022_10220901_31_dialog_content = "別想擋我的路！",
  ui_story_1022_10220901_32_dialog_content = "妳瘋了！居然還越攻越猛，不要命了嗎？",
  ui_story_1022_10220901_33_dialog_content = "這樣下去，都不用我認真，你自己就先燃燒殆盡了！",
  ui_story_1022_10220901_34_dialog_content = "那也是……燃燒過了啊！",
  ui_story_1022_10220901_35_dialog_content = "血……我居然流血了？",
  ui_story_1022_10220901_36_dialog_content = "可惡！可惡可惡可惡！妳敢傷我！好啊，想死是嗎？我成全妳！",
  ui_story_1022_10220901_37_dialog_content = "呃啊——！",
  ui_story_1022_10220901_38_dialog_content = "<color=#e8d9bb>咚咚咚咚咚咚咚——</color>",
  ui_story_1022_10220901_39_dialog_content = "<color=#e8d9bb>胸腔內部，搏動聲越來越狂亂。</color>",
  ui_story_1022_10220901_40_dialog_content = "<color=#e8d9bb>心臟顫動到抽搐的地步，如同煞車失靈、即將脫軌的火車。</color>",
  ui_story_1022_10220901_41_dialog_content = "<color=#e8d9bb>一陣陣激痛撕裂神智。</color>",
  ui_story_1022_10220901_42_dialog_content = "<color=#e8d9bb>已經什麼都不知道，什麼都感覺不到了。</color>",
  ui_story_1022_10220901_43_dialog_content = "<color=#e8d9bb>因此，那唯一的念頭，從未比此刻更清晰。</color>",
  ui_story_1022_10220901_44_dialog_content = "只要燦爛地燃燒過，死又算什麼？",
  ui_story_1022_10220901_45_dialog_content = "我不是任何人的寵物，不會屈服於任何人。",
  ui_story_1022_10220901_46_dialog_content = "<color=#FFB400>我，只屬於我自己！</color>",
  ui_story_1022_10220902_1_dialog_content = "白夜指針的反應越來越強烈了，失物就在附近。",
  ui_story_1022_10220902_2_dialog_content = "那個……",
  ui_story_1022_10220902_3_dialog_content = "反應更大了！大家睜大眼睛，目標可能很小。",
  ui_story_1022_10220902_4_dialog_content = "有時，苦苦追尋的答案也許意外地顯眼……",
  ui_story_1022_10220902_5_dialog_content = "艾莉法，有什麼感言等一下再說，先集中精神搜尋。",
  ui_story_1022_10220902_6_dialog_content = "不是感言，殿下。我是想說，您前方有一團聖潔的光芒，難道就是……",
  ui_story_1022_10220902_7_dialog_content = "什麼？！",
  ui_story_1022_10220902_8_dialog_content = "噗……",
  ui_story_1022_10220902_9_dialog_content = "笑什麼！你不也沒有發現嗎？",
  ui_story_1022_10220902_10_dialog_content = "咳咳，我們都只顧著看指針的反應了。這不重要！快看看是不是白夜城遺失的東西吧。",
  ui_story_1022_10220902_11_dialog_content = "好純淨的光能，令人感到平靜。",
  ui_story_1022_10220902_12_dialog_content = "找到了嗎？！",
  ui_story_1022_10220902_13_dialog_content = "不會錯，正是這團光能隔絕了暗能。",
  ui_story_1022_10220902_14_dialog_content = "也就是說，它正是真理結社遺失已久的聖物。",
  ui_story_1022_10220902_15_dialog_content = "咦，這個聲音？",
  ui_story_1022_10220902_16_dialog_content = "今日物歸原主，萬物皆回到命定的軌跡，主的指引玄妙至此。",
  ui_story_1022_10220902_17_dialog_content = "什麼人？放下白夜城的失物！",
  ui_story_1022_10220902_18_dialog_content = "維多利亞，妳太不講理了。祕典的事我還沒和妳理論，妳竟然又來硬搶！",
  ui_story_1022_10220902_19_dialog_content = "維多利亞？難、難道，妳就是那個異端結社的首領？",
  ui_story_1022_10220902_20_dialog_content = "呵呵。追尋真知，在蒙昧的國度的確稱得上「異端」。",
  ui_story_1022_10220902_21_dialog_content = "至於這件聖物，乃是此地領主當年從瓦拉吉鎮劫走的，我不曾觸碰任何不屬於我的東西。",
  ui_story_1022_10220902_22_dialog_content = "就連引導我來此的線索，也出自真理結社成員佩皮塔之手。",
  ui_story_1022_10220902_23_dialog_content = "我哪一步不講理了呢，卡蓮殿下？",
  ui_story_1022_10220902_24_dialog_content = "閉嘴！！",
  ui_story_1022_10220902_25_dialog_content = "異端邪祟，滿口大話，污人清聽……",
  ui_story_1022_10220902_26_dialog_content = "去死吧！",
  ui_story_1022_10220902_27_dialog_content = "哈、哈……",
  ui_story_1022_10220902_28_dialog_content = "（珊瑚，還是珊瑚……我還沒逃出去嗎？）",
  ui_story_1022_10220902_29_dialog_content = "（烏蘇拉剛才對我手軟了一下，但難保她不會越想越氣，又追上來，到時我可就真的要沒命了。）",
  ui_story_1022_10220902_30_dialog_content = "（嗯？什麼聲音？）",
  ui_story_1022_10220902_31_dialog_content = "唔呃！混帳，異端的邪惡力量竟然這麼強！",
  ui_story_1022_10220902_32_dialog_content = "聽您滿口「邪惡」，莫非與主的信徒有什麼恩怨？",
  ui_story_1022_10220902_33_dialog_content = "腳步聲……是她！",
  ui_story_1022_10220902_34_dialog_content = "艾莉法，還有維多利亞大人！您怎麼會在這裡？送信的佩蒂明明被截獲了。",
  ui_story_1022_10220902_35_dialog_content = "在主的指引下，命運會找到自己的路。",
  ui_story_1022_10220902_36_dialog_content = "佩皮塔，妳果然受傷了。是誰下手這麼重？噢不……看來不必問了。",
  ui_story_1022_10220902_37_dialog_content = "佩皮塔！妳一路流的血都夠妳死十次了，還要往哪裡跑？",
  ui_story_1022_10220902_38_dialog_content = "妳再跑，我就真的真的要生氣了！看我現在就把這裡炸成平地！",
  ui_story_1022_10220902_39_dialog_content = "啊！",
  ui_story_1022_10220902_40_dialog_content = "佩皮塔，過來，站在我身後。",
  ui_story_1022_10220902_41_dialog_content = "什麼人，竟敢妨礙我……啊！妳、妳是……",
  ui_story_1022_10220902_42_dialog_content = "妨礙妳的不是我。我站在這裡，一動不曾動。",
  ui_story_1022_10220902_43_dialog_content = "是佩皮塔用她的雙腳遠離妳，走到了我身後。",
  ui_story_1022_10220902_44_dialog_content = "而令她做出如此選擇的，不是別人，正是妳啊。",
  ui_story_1022_10220902_45_dialog_content = "自始至終，妨礙妳的只有妳自己。",
  ui_story_1022_10220902_46_dialog_content = "……",
  ui_story_1022_10220902_47_dialog_content = "妳……不對，佩皮塔是我的，不是妳、妳……！",
  ui_story_1022_10220902_48_dialog_content = "真理極盡玄奧，一時想不明白也是常事。",
  ui_story_1022_10220902_49_dialog_content = "但您若想也不想，將蒙昧、無知和殘酷當做自己的家徽——",
  ui_story_1022_10220902_50_dialog_content = "終有一天，您會墮入真理之光再也照耀不到的永夜。",
  ui_story_1022_10220902_51_dialog_content = "我……妳……嗚哇哇哇哇——！！",
  ui_story_1022_10220902_52_dialog_content = "<color=#e8d9bb>片刻前還氣勢洶洶的罪靈，忽然一癟嘴落荒而逃，遠遠還能聽見哭叫「爺爺」的聲音。</color>",
  ui_story_1022_10220902_53_dialog_content = "哭著逃跑了？",
  ui_story_1022_10220902_54_dialog_content = "呵呵……好久沒有教訓壞孩子了，讓您見笑了。",
  ui_story_1022_10220902_55_dialog_content = "那個罪靈和瓦拉吉家也算有些緣分，又重傷了佩皮塔，我一時忍不住。",
  ui_story_1022_10220902_56_dialog_content = "（又一個瓦拉吉？！）",
  ui_story_1022_10220902_57_dialog_content = "佩皮塔，我馬上替妳療傷。",
  ui_story_1022_10220902_58_dialog_content = "這枚徽章……維多利亞大人，莫非您就是靠這徽章找到我的？",
  ui_story_1022_10220902_59_dialog_content = "這枚徽章是我的術式，能引出妳那顆人造心臟的力量，與妳的生命緊密相連。",
  ui_story_1022_10220902_60_dialog_content = "妳一遭遇危險，我立刻便能察知。",
  ui_story_1022_10220902_61_dialog_content = "因此沒錯，佩皮塔。正是因為妳，我才會趕來此處，機緣巧合找回結社的聖物。",
  ui_story_1022_10221001_1_dialog_content = "對了，維多利亞小姐，您認識卡戎。",
  ui_story_1022_10221001_2_dialog_content = "您知道薇絲去哪了嗎？為什麼彼岸號的座標跳來跳去的？",
  ui_story_1022_10221001_3_dialog_content = "他們應該沒有遭遇罪靈，對吧！",
  ui_story_1022_10221001_4_dialog_content = "關於這件事——嗯？閣下又想幹什麼？",
  ui_story_1022_10221001_5_dialog_content = "我才要問妳吧！這傢伙偷走白夜城祕典，妳想包庇她嗎？",
  ui_story_1022_10221001_6_dialog_content = "說起來，偷走的祕典如今就在你們手裡，多麼邪惡的賊窟！",
  ui_story_1022_10221001_7_dialog_content = "喂，妳說話一直這麼難聽嗎？",
  ui_story_1022_10221001_8_dialog_content = "雙方互相挑釁，局面越來越緊張……我該怎麼辦……",
  ui_story_1022_10221001_9_dialog_content = "佩皮塔沒有告訴過您嗎？那本祕典與我手中的聖物一樣，本應屬於真理結社。",
  ui_story_1022_10221001_10_dialog_content = "胡說八道！這也屬於真理結社，那也屬於真理結社，艾斯特拉是你們發明的嗎？！",
  ui_story_1022_10221001_11_dialog_content = "既然說不通，我就用劍讓妳們留下來。",
  ui_story_1022_10221001_12_dialog_content = "艾莉法，我們上！",
  ui_story_1022_10221001_13_dialog_content = "是！",
  ui_story_1022_10221001_14_dialog_content = "等一下！",
  ui_story_1022_10221001_15_dialog_content = "PlayerName，你不要插手。",
  ui_story_1022_10221001_16_dialog_content = "無論如何，我們必須問出祕典的下落。",
  ui_story_1022_10221001_17_dialog_content = "問是用嘴，不是用劍！城主大人的意願都還記得嗎？",
  ui_story_1022_10221001_18_dialog_content = "這……",
  ui_story_1022_10221001_19_dialog_content = "我們還是盡可能用和平方式解決問題，不要影響聯合探索部隊的下一步——",
  ui_story_1022_10221001_20_dialog_content = "聯合？你在和誰聯合？",
  ui_story_1022_10221001_21_dialog_content = "？！",
  ui_story_1022_10221001_22_dialog_content = "一路走來，我本來開始信任你了，結果關鍵時刻你站在異端那一邊。",
  ui_story_1022_10221001_23_dialog_content = "「聯合探索，相互照應」，果然只是說得好聽！",
  ui_story_1022_10221001_24_dialog_content = "讓開，不然我就——",
  ui_story_1022_10221001_25_dialog_content = "妳就怎麼樣？",
  ui_story_1022_10221001_26_dialog_content = "連妳也！",
  ui_story_1022_10221001_27_dialog_content = "PlayerName說得沒錯。以暗面探索為重，是大元帥和白夜城城主的共識。",
  ui_story_1022_10221001_28_dialog_content = "妳想問別的事，先把劍放下。",
  ui_story_1022_10221001_29_dialog_content = "……",
  ui_story_1022_10221001_30_dialog_content = "組長……",
  ui_story_1022_10221001_31_dialog_content = "異端……都該死！！",
  ui_story_1022_10221002_1_dialog_content = "唔呃……呼、嗚……",
  ui_story_1022_10221002_2_dialog_content = "（可惡，這傢伙太強了，偏偏暗面還削弱了我的力量……）",
  ui_story_1022_10221002_3_dialog_content = "別想……跑！",
  ui_story_1022_10221002_4_dialog_content = "主已給予我啟示，佩皮塔尚有瑰麗輝煌的命數等在前方。",
  ui_story_1022_10221002_5_dialog_content = "再會吧，願真理之光引導您。",
  ui_story_1022_10221002_6_dialog_content = "混帳，給我站住！",
  ui_story_1022_10221002_7_dialog_content = "等一下，維多利亞小姐！薇絲在哪，您還沒回答我呢！",
  ui_story_1022_10221002_8_dialog_content = "嗚哇，緋，妳幹什麼？哇啊啊啊，飛起來了——",
  ui_story_1022_10221002_9_dialog_content = "別吵，沒有飛，只是跑得比較快。",
  ui_story_1022_10221002_10_dialog_content = "這樣才追得上維多利亞。",
  ui_story_1022_10221002_11_dialog_content = "嗯？",
  ui_story_1022_10221002_12_dialog_content = "怎麼了，維多利亞大人？",
  ui_story_1022_10221002_13_dialog_content = "佩皮塔，妳先走吧。再留在這裡，又是一番糾纏。",
  ui_story_1022_10221002_14_dialog_content = "快。",
  ui_story_1022_10221002_15_dialog_content = "好、好！",
  ui_story_1022_10221002_16_dialog_content = "她在這！",
  ui_story_1022_10221002_17_dialog_content = "維多利亞小姐，您知道薇絲的行蹤，是不是？！",
  ui_story_1022_10221002_18_dialog_content = "不必著急。等到典籍揭示的時機到來，您自然會與她重逢。",
  ui_story_1022_10221002_19_dialog_content = "現在卻還不是時候。再會了。",
  ui_story_1022_10221002_20_dialog_content = "（她果然知道薇絲的狀況！）",
  ui_story_1022_10221002_21_option_content = "強制感應！",
  ui_story_1022_10221002_22_dialog_content = "呵呵……",
  ui_story_1022_10221002_23_dialog_content = "這、這是……",
  ui_story_1022_10221002_24_dialog_content = "<color=#e8d9bb>永夜如同黏質的流體，巨大的冰柱聳入天空。</color>",
  ui_story_1022_10221002_25_dialog_content = "<color=#e8d9bb>一道人影，封凍於冰柱之中。</color>",
  ui_story_1022_10221002_26_dialog_content = "薇絲！",
  ui_story_1022_10221002_27_dialog_content = "（怎麼會？薇絲怎麼會在那種地方？）",
  ui_story_1022_10221002_28_option_content = "再次感應",
  ui_story_1022_10221002_29_dialog_content = "這琴聲是真正的藝術，彷彿能穿透時間與空間的界線。",
  ui_story_1022_10221002_30_dialog_content = "薇絲，妳在做什麼？",
  ui_story_1022_10221002_31_dialog_content = "PlayerName有危險，他就快沉入工程師施加的黑暗了！我得做點什麼！",
  ui_story_1022_10221002_32_dialog_content = "就用我的琴聲喚醒PlayerName……",
  ui_story_1022_10221002_33_dialog_content = "工程師正注視著空裔，他們的意識連在一起。",
  ui_story_1022_10221002_34_dialog_content = "妳若插手，很可能會被工程師發現。",
  ui_story_1022_10221002_35_dialog_content = "可是！",
  ui_story_1022_10221002_36_dialog_content = "維多利亞女士，您要不解風情到何種地步？",
  ui_story_1022_10221002_37_dialog_content = "打斷這美妙的音樂，棄我們的友人於黑暗之中，您的主會讚美此種行徑嗎？",
  ui_story_1022_10221002_38_dialog_content = "喔？你竟提起主的名諱，而且似是準備好與工程師對抗。",
  ui_story_1022_10221002_39_dialog_content = "怎麼，終於脫離漫長的叛逆期，有意擁抱真理、覺醒血脈了嗎？",
  ui_story_1022_10221002_40_dialog_content = "妳從哪一句得出這種結論的？我對你們宣揚的真理沒有興趣。",
  ui_story_1022_10221002_41_dialog_content = "那真是萬分遺憾。",
  ui_story_1022_10221002_42_dialog_content = "成功了！PlayerName掙扎出來了！",
  ui_story_1022_10221002_43_dialog_content = "可是臨空者號離開了……",
  ui_story_1022_10221002_44_dialog_content = "放心吧，薇絲。PlayerName不會放棄他的巨像，我們也不會放棄他。",
  ui_story_1022_10221002_45_dialog_content = "那就有些困擾了。",
  ui_story_1022_10221002_46_dialog_content = "女士，您又想潑什麼冷水？",
  ui_story_1022_10221002_47_dialog_content = "真理結社的成員都有真理庇護，啟光的人卻尚未獲得選召。",
  ui_story_1022_10221002_48_dialog_content = "若你們非要以身涉險，只能……這樣了。",
  ui_story_1022_10221002_49_dialog_content = "<color=#e8d9bb>嘩啦啦——</color>",
  ui_story_1022_10221002_50_dialog_content = "嗚哇！",
  ui_story_1022_10221002_51_dialog_content = "怎、怎麼回事？！",
  ui_story_1022_10221002_52_dialog_content = "<color=#e8d9bb>維多利亞一揮手，原始河流驀地分開。</color>",
  ui_story_1022_10221002_53_dialog_content = "<color=#e8d9bb>卡戎和薇絲穿過河水，筆直墜落、再墜落。</color>",
  ui_story_1022_10221002_54_dialog_content = "<color=#e8d9bb>耳畔猶迴盪著神祕的低語——</color>",
  ui_story_1022_10221002_55_dialog_content = "只要注入一滴原始河流的水，再強的暗能都無法將其融化。",
  ui_story_1022_10221002_56_dialog_content = "哇啊啊啊啊——嗯？下墜停止了？",
  ui_story_1022_10221002_57_dialog_content = "這裡又是哪裡？",
  ui_story_1022_10221002_58_dialog_content = "<color=#e8d9bb>眼睛一閉一睜，周圍竟已是另一番光景。</color>",
  ui_story_1022_10221002_59_dialog_content = "<color=#e8d9bb>天幕漆黑黏稠，微微扭曲，彷彿正透過一層崎嶇厚重的玻璃望去。</color>",
  ui_story_1022_10221002_60_dialog_content = "<color=#e8d9bb>但那不是玻璃，而是——</color>",
  ui_story_1022_10221002_61_dialog_content = "冰？我、我怎麼會被封在一根冰柱裡？！",
  ui_story_1022_10221002_62_dialog_content = "嗯？這個聲音是……",
  ui_story_1022_10221002_63_dialog_content = "<color=#e8d9bb>隆隆隆——</color>",
  ui_story_1022_10221002_64_dialog_content = "粉碎吧，寒冰！別想用酷寒封凍我熾烈的熱情！",
  ui_story_1022_10221002_65_dialog_content = "卡戎長官！您也被封在冰柱裡了嗎？",
  ui_story_1022_10221002_66_dialog_content = "<color=#e8d9bb>隆隆隆隆隆——</color>",
  ui_story_1022_10221002_67_dialog_content = "<color=#e8d9bb>冰柱在彼岸號的衝擊下開始破碎。</color>",
  ui_story_1022_10221002_68_dialog_content = "薇絲，抓住我的手！",
  ui_story_1022_10221002_69_dialog_content = "來了！",
  ui_story_1022_10221002_70_dialog_content = "薇絲。",
  ui_story_1022_10221002_71_dialog_content = "（是我的錯覺嗎？好像聽到維多利亞小姐在叫我。）",
  ui_story_1022_10221002_72_dialog_content = "薇絲，聽我說。",
  ui_story_1022_10221002_73_dialog_content = "PlayerName即將遭逢嚴酷的考驗。他——",
  ui_story_1022_10221002_74_dialog_content = "<color=#e8d9bb>維多利亞的聲音如在耳畔。一字字，一句句。</color>",
  ui_story_1022_10221002_75_dialog_content = "！！",
  ui_story_1022_10221002_76_dialog_content = "薇絲，還愣著做什麼，快到我這裡來！",
  ui_story_1022_10221002_77_dialog_content = "……",
  ui_story_1022_10221002_78_dialog_content = "卡戎長官，您先走吧。",
  ui_story_1022_10221002_79_dialog_content = "我要留下來。",
  ui_story_1022_10221002_80_dialog_content = "什麼？！",
  ui_story_1022_10221002_81_dialog_content = "PlayerName需要我……",
  ui_story_1022_10221002_82_dialog_content = "在這裡，我一定可以幫上他的。",
  ui_story_1022_10221002_83_dialog_content = "<color=#FFB400>薇絲</color>——！",
  ui_story_1022_10221002_84_dialog_content = "<color=#e8d9bb>我——想叫喊，想伸手，想挽留少女的笑容，想索性一步跨到她身邊。</color>",
  ui_story_1022_10221002_85_dialog_content = "<color=#e8d9bb>但感應到的畫面越來越暗。</color>",
  ui_story_1022_10221002_86_dialog_content = "<color=#e8d9bb>越來越暗。</color>",
  ui_story_1022_10221002_87_dialog_content = "<color=#e8d9bb>暗如永夜。</color>",
  ui_story_1022_10221002_88_dialog_content = "<color=#e8d9bb>唯有她所在之處，一點點亮起光芒。</color>",
  ui_story_1022_10221002_89_dialog_content = "<color=#e8d9bb>在黑暗的擠壓中，在凜寒的肆虐下——</color>",
  ui_story_1022_10221002_90_dialog_content = "<color=#e8d9bb>光輝四射，閃耀奪目。</color>",
  ui_story_1022_10221002_91_dialog_content = "<color=#e8d9bb>猶如永夜中升起了太陽。</color>",
  ui_story_1022_10221002_92_dialog_content = "（我感應到的那團光能，是薇絲啊……）",
  ui_story_1022_10221002_93_dialog_content = "（追著她以靈魂形成的標記，我才沒有在黑暗中迷失方向。）",
  ui_story_1022_10221002_94_dialog_content = "（妳們叫我導航員，因為我在戰場上指引妳們。）",
  ui_story_1022_10221002_95_dialog_content = "（但引導我的光，一直都是薇絲啊。）",
  ui_story_1022_10221002_96_dialog_content = "（從第一天開始……）",
  ui_story_1022_10221101_1_dialog_content = "……PlayerName。",
  ui_story_1022_10221101_2_dialog_content = "PlayerName，醒醒！",
  ui_story_1022_10221101_3_dialog_content = "緋……",
  ui_story_1022_10221101_4_dialog_content = "對了，薇絲！薇絲在冰柱裡，就是我感應到的光能團，我們得去救她！",
  ui_story_1022_10221101_5_dialog_content = "冷靜點，喝口水慢慢說。",
  ui_story_1022_10221101_6_dialog_content = "嗯，謝謝……",
  ui_story_1022_10221101_7_dialog_content = "先跟你說一聲，維多利亞不見了，突然消失的。",
  ui_story_1022_10221101_8_dialog_content = "突然？",
  ui_story_1022_10221101_9_dialog_content = "恐怕從一開始，來的就不是真身。",
  ui_story_1022_10221101_10_dialog_content = "嗚哇哇哇——爺爺，爺爺！",
  ui_story_1022_10221101_11_dialog_content = "討厭，嗚哇哇，爺爺你為什麼拋下我就死了？要是你還在，那個<color=#FFB400>大家主</color>才不敢欺負我！",
  ui_story_1022_10221101_12_dialog_content = "爺爺……",
  ui_story_1022_10221101_13_dialog_content = "……",
  ui_story_1022_10221101_14_dialog_content = "算了，死都死了，念著他也沒用……",
  ui_story_1022_10221101_15_dialog_content = "我已經有佩皮塔了，佩皮塔是真心對我好。",
  ui_story_1022_10221101_16_dialog_content = "但佩皮塔也被大家主搶走了……",
  ui_story_1022_10221101_17_dialog_content = "<size=50>嗚哇哇哇哇哇！</size>",
  ui_story_1022_10221101_18_dialog_content = "我說過了，趕走佩皮塔的，正是妳自己啊。",
  ui_story_1022_10221101_19_dialog_content = "妳？！",
  ui_story_1022_10221101_20_dialog_content = "偶爾也動用一下妳的頭腦如何？雖然從妳出生開始，頭腦就沒什麼登場機會……",
  ui_story_1022_10221101_21_dialog_content = "但放任它生銹還是有些浪費了，不是嗎？",
  ui_story_1022_10221101_22_dialog_content = "早被除名的<color=#FFB400>十三家主「孩童」</color>？",
  ui_story_1022_10221101_23_dialog_content = "妳還敢……還敢提！",
  ui_story_1022_10221101_24_dialog_content = "蠢貨，賤民的血也敢拿給我的寶貝孫女！",
  ui_story_1022_10221101_25_dialog_content = "烏蘇拉嘗得出低賤和愚蠢的味道！你們是想害死她嗎？",
  ui_story_1022_10221101_26_dialog_content = "對、對不起！",
  ui_story_1022_10221101_27_dialog_content = "嗚哇，哇哇哇哇哇！",
  ui_story_1022_10221101_28_dialog_content = "乖乖，不哭不哭，爺爺去找配得上妳的血畜。",
  ui_story_1022_10221101_29_dialog_content = "用最甜美的血液，澆灌妳燦爛的天賦……",
  ui_story_1022_10221101_30_dialog_content = "<color=#e8d9bb>嘩啦！桌上的餐具全被掃到地上，摔得粉碎。</color>",
  ui_story_1022_10221101_31_dialog_content = "家主大人！怎麼了，又有什麼事害您不高興了嗎？",
  ui_story_1022_10221101_32_dialog_content = "為什麼？今天陪我玩的「獵物」才那麼幾個！如果爺爺還活著，你們絕對不敢這樣糊弄我！",
  ui_story_1022_10221101_33_dialog_content = "這……要是平民減損太快，生產會停滯，很多人都會沒飯吃……",
  ui_story_1022_10221101_34_dialog_content = "沒飯吃，吃蛋糕不就行了？這點小事都得我教你嗎？",
  ui_story_1022_10221101_35_dialog_content = "是、是……我去重新安排。",
  ui_story_1022_10221101_36_dialog_content = "快逃啊！",
  ui_story_1022_10221101_37_dialog_content = "哈哈哈哈！這樣才對嘛，狩獵遊戲人越多才越有趣。",
  ui_story_1022_10221101_38_dialog_content = "逃吧，逃吧，跑快一點，逃遠一點！不過，別擔心……",
  ui_story_1022_10221101_39_dialog_content = "我會把你們一～個一個找出來，好好陪你們玩的。",
  ui_story_1022_10221101_40_dialog_content = "絕不會……冷落任何人。",
  ui_story_1022_10221101_41_dialog_content = "從前多好啊，誰都聽我的，誰都陪我玩……",
  ui_story_1022_10221101_42_dialog_content = "都是因為你們瓦拉吉，所謂的「大家主」……全都毀掉了！",
  ui_story_1022_10221101_43_dialog_content = "你們害我只能縮回日蝕，整天除了睡覺就是睡覺，誰也不理我，誰都忤逆我！",
  ui_story_1022_10221101_44_dialog_content = "全都是你們的錯！！",
  ui_story_1022_10221101_45_dialog_content = "又要怪罪在別人身上嗎？",
  ui_story_1022_10221101_46_dialog_content = "妳被除名，是因為妳的暴虐和背叛。",
  ui_story_1022_10221101_47_dialog_content = "妳率領暗鬼大軍攻入瓦拉吉鎮，殘害無數信徒、搶走結社聖物，在瓦拉吉的歷史上留下慘絕人寰的一頁。",
  ui_story_1022_10221101_48_dialog_content = "我僅是翻開塵封書籍，都為妳的行徑而震駭……",
  ui_story_1022_10221101_49_dialog_content = "閉嘴！閉嘴閉嘴閉嘴！弄死幾個光靈有什麼大不了，妳就沒有玩死過人嗎？",
  ui_story_1022_10221101_50_dialog_content = "爺爺在的時候，我玩得越盡興，他就越高興！偏偏就你們問題最多！",
  ui_story_1022_10221101_51_dialog_content = "別以為有個「大家主」的名頭就能教訓我！",
  ui_story_1022_10221101_52_dialog_content = "只要燦爛地燃燒過，死又算什麼？",
  ui_story_1022_10221101_53_dialog_content = "我不是任何人的寵物，不會屈服於任何人。",
  ui_story_1022_10221101_54_dialog_content = "<color=#FFB400>我，只屬於我自己！</color>",
  ui_story_1022_10221101_55_dialog_content = "我只屬於自己，才不會屈服於妳！",
  ui_story_1022_10221101_56_dialog_content = "妳這樣誤解佩皮塔的信念，她若知道，只怕要哭笑不得了。",
  ui_story_1022_10221101_57_dialog_content = "不准！再提！佩皮塔！！",
  ui_story_1022_10221101_58_dialog_content = "<color=#e8d9bb>伴隨歇斯底里的尖叫，濃厚的暗能噴勃而出。</color>",
  ui_story_1022_10221101_59_dialog_content = "<color=#e8d9bb>暗能包裹住烏蘇拉，又湧向四面八方，覆蓋昏黑的冰層。</color>",
  ui_story_1022_10221101_60_dialog_content = "<color=#e8d9bb>無數肉芽扭動著鑽出冰層，開裂分叉，形成巨大、畸形的珊瑚叢。</color>",
  ui_story_1022_10221101_61_dialog_content = "<color=#e8d9bb>珊瑚枝纏繞交織，像畸變的血管，又像惡性的筋肉。</color>",
  ui_story_1022_10221101_62_dialog_content = "<color=#e8d9bb>咚，咚。</color>",
  ui_story_1022_10221101_63_dialog_content = "<color=#e8d9bb>這片珊瑚叢是巨大的生命體，與黑霧深處的心跳共振搏動。</color>",
  ui_story_1022_10221101_64_dialog_content = "<color=#e8d9bb>每一次搏動，都噴吐出黏稠的暗能，腐蝕領域內一切光靈的生命。</color>",
  ui_story_1022_10221101_65_dialog_content = "嘎——！！！",
  ui_story_1022_10221102_1_dialog_content = "<color=#e8d9bb>喀嚓。</color>",
  ui_story_1022_10221102_2_dialog_content = "<color=#e8d9bb>烏蘇拉的暗能外殼終於破碎，維多利亞卻亦為此付出代價。</color>",
  ui_story_1022_10221102_3_dialog_content = "咳——！",
  ui_story_1022_10221102_4_dialog_content = "哈、哈……哈哈哈哈！什麼大家主，不過如此嘛。",
  ui_story_1022_10221102_5_dialog_content = "我稍微認真一下，馬上就被打趴了。",
  ui_story_1022_10221102_6_dialog_content = "也難怪啦，我可是在很～小很小的時候就血脈覺醒了，連爺爺都說我擁有他見過最高的天賦。",
  ui_story_1022_10221102_7_dialog_content = "妳呢，阿姨？看妳的樣子，該不會半截身子都入土了才覺醒吧？哇哈哈哈！",
  ui_story_1022_10221102_8_dialog_content = "……呵。",
  ui_story_1022_10221102_9_dialog_content = "有什麼好笑！",
  ui_story_1022_10221102_10_dialog_content = "我是有史以來最早覺醒的血族，表示我天賦最高，力量最純粹，妳哪一點都比不過我。",
  ui_story_1022_10221102_11_dialog_content = "不如把大家主之位讓給我坐坐吧！哇哈哈——",
  ui_story_1022_10221102_12_dialog_content = "<color=#e8d9bb>烏蘇拉的狂笑戛然而止。</color>",
  ui_story_1022_10221102_13_dialog_content = "<color=#e8d9bb>在她驚愕的注視下，維多利亞身上的傷逐一痊癒，連開裂的衣服都恢復如初。</color>",
  ui_story_1022_10221102_14_dialog_content = "怎、怎麼會……",
  ui_story_1022_10221102_15_dialog_content = "還要問嗎？以妳的天賦，這點事總該看得出來。",
  ui_story_1022_10221102_16_dialog_content = "妳……妳！妳分了大半的力量在別處……妳在幹什麼？",
  ui_story_1022_10221102_17_dialog_content = "我讓他們從原始河流墜落，總該看顧著他們。暗面畢竟相當兇險。",
  ui_story_1022_10221102_18_dialog_content = "若妳不曾走上歧途，妳我本該都能蒙受主的眷顧。",
  ui_story_1022_10221102_19_dialog_content = "與我戰鬥的時候，還能分心照顧別人？怎麼可能！",
  ui_story_1022_10221102_20_dialog_content = "我才是最強的！覺醒最早，天分最高，力量最純粹……妳、妳一定是作弊！",
  ui_story_1022_10221102_21_dialog_content = "這就是妳唯一想得到的解釋嗎？妳的確是覺醒得<color=#FFB400>太早</color>了。",
  ui_story_1022_10221102_22_dialog_content = "什麼？",
  ui_story_1022_10221102_23_dialog_content = "覺醒太早，因而太過純粹，單純而原始。妳的力量，不曾經過一絲理性的凝鍊。",
  ui_story_1022_10221102_24_dialog_content = "妳很強，烏蘇拉，妳代表的是血族最原初的慾望。",
  ui_story_1022_10221102_25_dialog_content = "至於我，我站在離你很遠很遠的另一端。",
  ui_story_1022_10221102_26_dialog_content = "什、什麼意思……",
  ui_story_1022_10221102_27_dialog_content = "我覺醒得比妳晚許多。",
  ui_story_1022_10221102_28_dialog_content = "為了參悟真理，我見證、思辨、剖析，走過了很長的路。",
  ui_story_1022_10221102_29_dialog_content = "這條路途，妳未曾經歷，也不會設想。",
  ui_story_1022_10221102_30_dialog_content = "那麼，我的祕法有多麼深奧複雜……我只能邀請妳想像一番了。",
  ui_story_1022_10221102_31_dialog_content = "因為妳永遠也理解不了。",
  ui_story_1022_10221102_32_dialog_content = "不、不可能！我才是……最強的！",
  ui_story_1022_10221102_33_dialog_content = "<color=#e8d9bb>狂亂的叫喊也壓制不住烏蘇拉的恐懼。畢竟，她是天賦極高的血族。</color>",
  ui_story_1022_10221102_34_dialog_content = "<color=#e8d9bb>所以，她的心、眼、靈魂都承受著同一領悟引發的激痛——</color>",
  ui_story_1022_10221102_35_dialog_content = "<color=#FFB400>「法則」</color>……",
  ui_story_1022_10221102_36_dialog_content = "<color=#e8d9bb>那是為真理嘔心瀝血的光靈，最終抵達的境界。</color>",
  ui_story_1022_10221102_37_dialog_content = "<color=#e8d9bb>超越原始，超越純粹，以殷殷求索之心，為真知獻上的讚歌。</color>",
  ui_story_1022_10221102_38_dialog_content = "答得很好，烏蘇拉。接下來是見習時間。",
  ui_story_1022_10221102_39_dialog_content = "我的祕法——請妳睜大眼睛，好好鑑賞吧。",
  ui_story_1022_10221102_40_dialog_content = "這既是，我獻給主的朝聖——",
  ui_story_1022_10221102_41_dialog_content = "嗚哇啊啊啊啊啊啊啊！",
  ui_story_1022_10221102_42_dialog_content = "為、為什麼？我明明早就接受了日蝕的印記，為什麼？！",
  ui_story_1022_10221102_43_dialog_content = "我竟然，正在還原成光靈？！",
  ui_story_1022_10221102_44_dialog_content = "不要……不要！我不要死，不要消失！",
  ui_story_1022_10221102_45_dialog_content = "不要！！！",
  ui_story_1022_10221102_46_dialog_content = "多麼可怕的祕法啊……原來如此，這就是「救贖」。",
  ui_story_1022_10221102_47_dialog_content = "妳否定了那些虛構的物質，要將純粹的本質獻給意識的主嗎？",
  ui_story_1022_10221102_48_dialog_content = "呵，不，可怕的是妳這個人才對，維多利亞。",
  ui_story_1022_10221102_49_dialog_content = "連我都能再利用兩下，還有什麼是不在妳視野之中的嗎？",
  ui_story_1022_10221102_50_dialog_content = "<color=#e8d9bb>斑斕的河流在無限中蜿蜒。這條河裡，時間沒有意義。</color>",
  ui_story_1022_10221102_51_dialog_content = "<color=#e8d9bb>如今，無數的過去與未來，平等羅列在隱修者面前，甚至連同「平行的自己」。</color>",
  ui_story_1022_10221102_52_dialog_content = "也罷……過來吧。",
  ui_story_1022_10221102_53_dialog_content = "<color=#e8d9bb>隱修者拍拍手，空中裂開縫隙，一列蒸汽火車驀地被扯出虛空。</color>",
  ui_story_1022_10221102_54_dialog_content = "哇啊啊啊啊——",
  ui_story_1022_10221102_55_dialog_content = "安靜。我一個人待久了，耳朵受不得嚷嚷。",
  ui_story_1022_10221102_56_dialog_content = "怎麼又是這條河！你又是誰？等一下，我見過你。",
  ui_story_1022_10221102_57_dialog_content = "莫非你是……我父親早已逝世的堂弟，維多利亞的叔叔——<color=#FFB400>威廉·瓦拉吉</color>？",
  ui_story_1022_10221102_58_dialog_content = "你的氣還真長，直接叫我一聲「堂叔」不好嗎？",
  ui_story_1022_10221102_59_dialog_content = "在這詭異的地點，見到已逝之人，攀親帶故才是可疑之舉！",
  ui_story_1022_10221102_60_dialog_content = "真頭痛。跟維多利亞一樣難搞。",
  ui_story_1022_10221102_61_dialog_content = "你在嘀咕什麼？我和那位裝神弄鬼的女士大不相同。",
  ui_story_1022_10221102_62_dialog_content = "剛帶完兄長的孩子，又要帶朋友的孩子，我的家徽該改成奶嘴和搖籃了。",
  ui_story_1022_10221102_63_dialog_content = "我記得你的名字，叫卡戎吧。你可知道你為什麼會來到這裡？",
  ui_story_1022_10221102_64_dialog_content = "不是你搞的鬼嗎？",
  ui_story_1022_10221102_65_dialog_content = "維多利亞想讓你與我修練祕法，參悟真理。她從你身上看出了潛能。",
  ui_story_1022_10221102_66_dialog_content = "什麼？！我早就告訴過她，我沒有興趣。",
  ui_story_1022_10221102_67_dialog_content = "你告訴她沒有興趣時，的確沒有興趣。",
  ui_story_1022_10221102_68_dialog_content = "但河流已經向前流淌，再回到河中的你，不是從前的你。現在的你又是如何？",
  ui_story_1022_10221102_69_dialog_content = "我……",
  ui_story_1022_10221102_70_dialog_content = "<color=#e8d9bb>「當然還是沒有興趣」，這句話來到了卡戎嘴邊。</color>",
  ui_story_1022_10221102_71_dialog_content = "<color=#e8d9bb>霎時，他腦海中卻浮出冰柱中薇絲的身影。他的部下，正陷身於暗鬼環伺的永夜。</color>",
  ui_story_1022_10221102_72_dialog_content = "<color=#e8d9bb>她說要為了空裔留下。也就是說，空裔及同行的啟光同僚，多半也遭遇了困境。</color>",
  ui_story_1022_10221102_73_dialog_content = "<color=#e8d9bb>這樣的情況下……</color>",
  ui_story_1022_10221102_74_dialog_content = "或許真的是時候從叛逆期畢業了。",
  ui_story_1022_10221102_75_dialog_content = "哼，你知道自己在叛逆期，比起某些人還算有救。",
  ui_story_1022_10221102_76_dialog_content = "這一次，應該不需要我再搭上不存在的性命了吧？",
  ui_story_1022_10221200_1_dialog_content = "……",
  ui_story_1022_10221200_2_dialog_content = "（冰洞？對了，我逃回最開始駐紮的臨時基地，虛脫昏睡了過去。）",
  ui_story_1022_10221200_3_dialog_content = "（維多利亞大人多半去追烏蘇拉了，我得去找她……）",
  ui_story_1022_10221200_4_dialog_content = "可惡，失物和逃犯都到眼前了，竟然還會失手！",
  ui_story_1022_10221200_5_dialog_content = "（哎喲，她怎麼也在？幸好沒急著出去。）",
  ui_story_1022_10221200_6_dialog_content = "組長，請您不要亂動，傷口會裂開的。",
  ui_story_1022_10221200_7_dialog_content = "（艾莉法……看到我受傷，她當時的表情很擔心。）",
  ui_story_1022_10221200_8_dialog_content = "我的傷沒事，艾莉法。倒是這位不速之客，不知有何指教？",
  ui_story_1022_10221200_9_dialog_content = "已經通報過來意了吧？我是來幫您的。",
  ui_story_1022_10221200_10_dialog_content = "（居然還有一個人……一點聲息也沒有。）",
  ui_story_1022_10221200_11_dialog_content = "幫我？我們一群人圍住佩皮塔都讓她溜了，你要怎麼幫？",
  ui_story_1022_10221200_12_dialog_content = "（哎？在說我的事？）",
  ui_story_1022_10221200_13_dialog_content = "當然是用萬無一失的辦法。",
  ui_story_1022_10221200_14_dialog_content = "請收下這個。",
  ui_story_1022_10221200_15_dialog_content = "遙控器？你該不會想說，按一下就能把佩皮塔定身吧？",
  ui_story_1022_10221200_16_dialog_content = "正是。",
  ui_story_1022_10221200_17_dialog_content = "……你敢耍我！？",
  ui_story_1022_10221200_18_dialog_content = "不，我沒有一絲誇大。您稱為「遙控器」的東西，是貝利撒留當年留下的保險裝置。",
  ui_story_1022_10221200_19_dialog_content = "它能控制佩皮塔胸前的人造心臟。",
  ui_story_1022_10221200_20_dialog_content = "唔！",
  ui_story_1022_10221200_21_dialog_content = "她的心臟……是人造的？",
  ui_story_1022_10221200_22_dialog_content = "只要按下這顆按鈕，人造心臟立刻便會停止運作。結果如何，我就不必說了。",
  ui_story_1022_10221200_23_dialog_content = "還有比這更為切實、永久的「定身」嗎？",
  ui_story_1022_10221200_24_dialog_content = "少胡說八道了！什麼定身，這不就是殺人嗎？",
  ui_story_1022_10221200_25_dialog_content = "只有當死者清白無辜時，奪去生命才叫殺人。",
  ui_story_1022_10221200_26_dialog_content = "若死者是罪人，您之所為，名為「處刑」。",
  ui_story_1022_10221200_27_dialog_content = "這跟那有什麼兩樣……",
  ui_story_1022_10221200_28_dialog_content = "當年佩皮塔叛逃出啟光時，貝利撒留手中就握著這個裝置。",
  ui_story_1022_10221200_29_dialog_content = "但她眼睜睜望著罪人的背影消失，就是下不了手。真是……令人失望。",
  ui_story_1022_10221200_30_dialog_content = "（貝利撒留……）",
  ui_story_1022_10221200_31_dialog_content = "不過，我相信您與那位空有其名的「鐵娘子」不一樣。",
  ui_story_1022_10221200_32_dialog_content = "面對白夜城的罪人，您的覺悟是貨真價實的。",
  ui_story_1022_10221200_33_dialog_content = "我……",
  ui_story_1022_10221200_34_dialog_content = "不可以！",
  ui_story_1022_10221200_35_dialog_content = "組長，這樣的做法……是錯誤的！佩皮塔可能做過一些錯事，但她不是惡人！",
  ui_story_1022_10221200_36_dialog_content = "身為她的心靈之友，每次看到她的眼睛，我就知道。",
  ui_story_1022_10221200_37_dialog_content = "哪有人一輩子都不會犯錯的？神的宗旨不是說過嗎，哪怕是罪人，也有悔過的機會！",
  ui_story_1022_10221200_38_dialog_content = "艾莉法……！",
  ui_story_1022_10221200_39_dialog_content = "誰在那裡？！",
  ui_story_1022_10221200_40_dialog_content = "佩皮塔？！妳怎麼在這——",
  ui_story_1022_10221200_41_dialog_content = "看錯了吧？我不在，你們繼續聊。",
  ui_story_1022_10221200_42_dialog_content = "……追！",
  ui_story_1022_10221200_43_dialog_content = "佩皮塔，別跑了，停一下！",
  ui_story_1022_10221200_44_dialog_content = "叫妳長官丟掉遙控器我就停！",
  ui_story_1022_10221200_45_dialog_content = "佩皮塔，我不會讓他們傷害妳的！等一等——",
  ui_story_1022_10221200_46_dialog_content = "這種話等妳升官了再說吧。",
  ui_story_1022_10221200_47_dialog_content = "佩皮塔，前面是——",
  ui_story_1022_10221200_48_dialog_content = "別喊了，我不會停的——嗚哇啊！",
  ui_story_1022_10221200_49_dialog_content = "<color=#e8d9bb>凜冽的寒風從腳底捲上，差點把佩皮塔吹走。</color>",
  ui_story_1022_10221200_50_dialog_content = "<color=#e8d9bb>再往前一步，便會墜下萬丈深淵。</color>",
  ui_story_1022_10221200_51_dialog_content = "佩皮塔，小心！",
  ui_story_1022_10221200_52_dialog_content = "妳、妳別過來。",
  ui_story_1022_10221200_53_dialog_content = "好，我不過去，妳好好站著聽我說。",
  ui_story_1022_10221200_54_dialog_content = "城主大人答應不會懲罰妳。只要妳告訴我們祕典的線索，我保證——",
  ui_story_1022_10221200_55_dialog_content = "妳保證？還是城主大人保證？",
  ui_story_1022_10221200_56_dialog_content = "這……",
  ui_story_1022_10221200_57_dialog_content = "艾莉法，妳保證不了吧？妳只能指望妳的城主說話算話。",
  ui_story_1022_10221200_58_dialog_content = "多謝，但抱歉啦，我完全不打算指望大老爺的心意過日子。",
  ui_story_1022_10221200_59_dialog_content = "<color=#FFB400>不自由，毋寧死！</color>",
  ui_story_1022_10221200_60_dialog_content = "<color=#e8d9bb>佩皮塔奔向懸崖，不假思索一躍而下。</color>",
  ui_story_1022_10221200_61_dialog_content = "佩皮塔！",
  ui_story_1022_10221200_62_dialog_content = "<color=#e8d9bb>艾莉法一個箭步衝到崖邊。雲霧捲動，哪裡還有佩皮塔的影子？</color>",
  ui_story_1022_10221200_63_dialog_content = "……",
  ui_story_1022_10221200_64_dialog_content = "直到最後妳都沒按下按鈕，眼睜睜錯失良機。",
  ui_story_1022_10221200_65_dialog_content = "連續兩次看錯人，我也該反省反省了。",
  ui_story_1022_10221200_66_dialog_content = "艾莉法說得對，她是犯錯之人，不是該死之人……我、我不會因我的私怨殺人！",
  ui_story_1022_10221200_67_dialog_content = "你……到底是什麼人？",
  ui_story_1022_10221200_68_dialog_content = "覺悟不足，好奇心倒不少。白夜城的異端調查組不過如此。",
  ui_story_1022_10221200_69_dialog_content = "佩皮塔不勞你們費心了。",
  ui_story_1022_10221200_70_dialog_content = "啟光<color=#FFB400>「處刑者」</color>組織，正式接手此事。",
  ui_story_1022_10221200_71_dialog_content = "<color=#e8d9bb>暗面深處，某座冰窟前，閃電般的火花閃過。</color>",
  ui_story_1022_10221200_72_dialog_content = "發生了什麼事？我怎麼會……我被重組了？",
  ui_story_1022_10221200_73_dialog_content = "黑夜、嚴寒、暗能……啊啊，日蝕！我回來了！感謝您，我的神……",
  ui_story_1022_10221200_74_dialog_content = "你也知道你是靠著祂的仁慈才回得來啊。",
  ui_story_1022_10221200_75_dialog_content = "……",
  ui_story_1022_10221200_76_dialog_content = "哼，妳們都在。",
  ui_story_1022_10221200_77_dialog_content = "當然，等你很久了。哪怕你有一點真本事，也不至於空耗我們這麼多時間。",
  ui_story_1022_10221200_78_dialog_content = "好大的口氣啊，阿斯摩太。我為那位大人衝鋒陷陣，妳又做了什麼？",
  ui_story_1022_10221200_79_dialog_content = "哪怕大人要我立刻闖回迦南城，我也不會皺一下眉頭。",
  ui_story_1022_10221200_80_dialog_content = "你也只有這一點蠻勇了。",
  ui_story_1022_10221200_81_dialog_content = "妳什麼意思？",
  ui_story_1022_10221200_82_dialog_content = "說起來，這傢伙為什麼在這？八罪靈的會議，哪有她立足的餘地？",
  ui_story_1022_10221200_83_dialog_content = "……",
  ui_story_1022_10221200_84_dialog_content = "你知道的吧，斐桀洛？日蝕成員晉升的通道是唯一的。",
  ui_story_1022_10221200_85_dialog_content = "要想提拔新人，舊的席位中便必須有人消失。",
  ui_story_1022_10221200_86_dialog_content = "日蝕的罪靈只有八席，不會是七，也不會是九。",
  ui_story_1022_10221200_87_dialog_content = "妳、妳說這個幹什麼？吞羅究竟為什麼在這裡？！",
  ui_story_1022_10221200_88_dialog_content = "愚者不需要聰明的下屬。吞羅完成的事，比你重要太多了。",
  ui_story_1022_10221200_89_dialog_content = "享用晉升的<color=#FFB400>材料</color>，是她應得的獎賞。",
  ui_story_1022_10221200_90_dialog_content = "！！！",
  ui_story_1022_10221200_91_dialog_content = "怎、怎麼回事？是誰？誰膽敢束縛我！放開我！",
  ui_story_1022_10221200_92_dialog_content = "……我不想看這種畫面，先進去了。",
  ui_story_1022_10221200_93_dialog_content = "呵，我也用不著杵在這。吞羅，解決了就進來，會議要開始了。",
  ui_story_1022_10221200_94_dialog_content = "……",
  ui_story_1022_10221200_95_dialog_content = "……",
  ui_story_1022_10221200_96_dialog_content = "哈、哈哈哈哈哈！都給我上，解決她！",
  ui_story_1022_10221200_97_dialog_content = "嘎！！！",
  ui_story_1022_10221200_98_dialog_content = "……",
  ui_story_1022_10221200_99_dialog_content = "實力變強了啊……但妳敢嗎？有那個膽子，有那個覺悟嗎？",
  ui_story_1022_10221200_100_dialog_content = "今天妳吃了我，就等於接受未來被吞吃的命運……",
  ui_story_1022_10221200_101_dialog_content = "只要出現一個比妳更強、更受賞識的暗鬼，妳也會成為她晉升通道前的食糧！",
  ui_story_1022_10221200_102_dialog_content = "妳敢嗎？有膽子墮落到那種地步，再也無法回頭嗎？",
  ui_story_1022_10221200_103_dialog_content = "妳的心裡……還有一個放不下的光靈吧？",
  ui_story_1022_10221200_104_dialog_content = "……",
  ui_story_1022_10221200_105_dialog_content = "廢話，終於說完了吧？",
  ui_story_1022_10221200_106_dialog_content = "烏蘇拉……沒有動靜了。",
  ui_story_1022_10221200_107_dialog_content = "她也算是立功了。搭上大半條命，總算幫我們看見「那個人」的祕法。",
  ui_story_1022_10221200_108_dialog_content = "接下來才是重頭戲。",
  ui_story_1022_10221200_109_dialog_content = "……來了。",
  ui_story_1022_10221200_110_dialog_content = "嗯？",
  ui_story_1022_10221200_111_dialog_content = "<color=#e8d9bb>陰影中緩步走出的身影，吸引了在場的每一道目光。</color>",
  ui_story_1022_10221200_112_dialog_content = "……",
  ui_story_1022_10221200_113_dialog_content = "不愧是超級新人，呵呵……要比斐桀洛更能幹喔。",
  ui_story_1022_10221200_114_dialog_content = "不，我是說……烏蘇拉，來了。",
  ui_story_1022_10221200_115_dialog_content = "……",
  ui_story_1022_10221200_116_dialog_content = "「<color=#FFB400>X物質</color>」被抽離，心臟消失，身體差不多全碎了，但她還活著。不僅活著，還在緩慢恢復。",
  ui_story_1022_10221200_117_dialog_content = "是因為她原本是血族嗎？本就是被污染過一次的本質，不純粹的「<color=#FFB400>N物質</color>」。",
  ui_story_1022_10221200_118_dialog_content = "即使後天注入的虛構被剝奪，她仍然倖存。",
  ui_story_1022_10221200_119_dialog_content = "只要把她生成的珊瑚枝還給她，虛構的「<color=#FFB400>X</color>」的力量就會回歸，她的心臟會重新跳動。",
  ui_story_1022_10221200_120_dialog_content = "<color=#e8d9bb>嘰嘰，嘰嘰！嘰嘰嘰！</color>",
  ui_story_1022_10221200_121_dialog_content = "佩蒂，別吵，讓我再睡一下……",
  ui_story_1022_10221200_122_dialog_content = "哎，佩蒂？！",
  ui_story_1022_10221200_123_dialog_content = "是你救了我嗎？你怎麼跑出來的？烏蘇拉呢……？該不會死了吧？！",
  ui_story_1022_10221200_124_dialog_content = "不不，冷靜點。佩蒂還在活動，代表烏蘇拉一定活著。但佩蒂能逃出來，表示烏蘇拉凶多吉少……",
  ui_story_1022_10221200_125_dialog_content = "我……我為什麼還在擔心她啊！",
  ui_story_1022_10221200_126_dialog_content = "哎，生死不明烏蘇拉，死去活來佩皮塔……兩個折騰鬼，還挺相配的。",
  ui_story_1022_10221200_127_dialog_content = "<color=#e8d9bb>嘰嘰嘰！佩蒂纏在佩皮塔腳邊，莫名地很激動。</color>",
  ui_story_1022_10221200_128_dialog_content = "好啦好啦，知道你擔心原主人……嗯？不是在擔心她？那是——哇啊啊！！",
  ui_story_1022_10221200_129_dialog_content = "<color=#e8d9bb>半空中憑空裂開一道縫隙，一列蒸汽火車呼嘯而出。</color>",
  ui_story_1022_10221200_130_dialog_content = "火火火——火車？！",
  ui_story_1022_10221200_131_dialog_content = "暗面荒涼，好客的列車長不會對落單的光靈見死不救。",
  ui_story_1022_10221200_132_dialog_content = "如何，小姐？要來搭一趟華麗的便車嗎？"
}
return config
